real function cbrt (x)
implicit none
real, intent(in) :: x
real :: r
!-----------------------------------------------------------------------
!                   Cube root of a real number
!-----------------------------------------------------------------------
if (x) 30, 10, 20
10 cbrt = 0.0
return
20 r = alog(x)/3.0
cbrt = exp(r)
return
30 r = alog(-x)/3.0
cbrt = -exp(r)
return
end function cbrt

double precision function dcbrt (x)
implicit none
!-----------------------------------------------------------------------
!                   Cube root of a real number
!-----------------------------------------------------------------------
double precision, intent(in) :: x
double precision :: r
!
if (x) 30, 10, 20
10 dcbrt = 0.d0
return
20 r = dlog(x)/3.d0
dcbrt = dexp(r)
return
30 r = dlog(-x)/3.d0
dcbrt = -dexp(r)
return
end function dcbrt

function artnq(y,x)
implicit none
real, intent(in) :: x, y
real :: artnq
if (x) 1,2,5
1 artnq=atan(y/x)+3.1415926535898
return
2 if (y) 3,8,4
3 artnq=4.7123889803847
return
4 artnq=1.5707963267949
return
5 if (y) 6,8,7
6 artnq=atan(y/x)+6.2831853071795
return
7 artnq=atan(y/x)
return
8 artnq=0.
return
end function artnq

double precision function dartnq(y,x)
implicit none
double precision, intent(in) :: x, y
if (x) 1,2,5
1 dartnq=datan(y/x)+3.14159265358979323846264338328d0
return
2 if (y) 3,8,4
3 dartnq=4.71238898038468985769396507492d0
return
4 dartnq=1.57079632679489661923132169164d0
return
5 if (y) 6,8,7
6 dartnq=datan(y/x)+6.28318530717958647692528676656d0
return
7 dartnq=datan(y/x)
return
8 dartnq=0.d0
return
end function dartnq

real function cpabs(x, y)
implicit none
real, intent(in) :: x, y
real :: a
!     --------------------------------------
!     Evaluation of sqrt(x*x + y*y)
!     --------------------------------------
if (abs(x) .le. abs(y)) go to 10
   a = y/x
   cpabs = abs(x)*sqrt(1.0 + a*a)
   return
10 if (y .eq. 0.0) go to 20
   a = x/y
   cpabs = abs(y)*sqrt(1.0 + a*a)
   return
20 cpabs = 0.0
return
end function cpabs

double precision function dcpabs(x, y)
implicit none
double precision, intent(in) :: x, y
!     --------------------------------------
!     Evaluation of sqrt(x*x + y*y)
!     --------------------------------------
double precision :: a
!
if (dabs(x) .le. dabs(y)) go to 10
   a = y/x
   dcpabs = dabs(x)*dsqrt(1.d0 + a*a)
   return
10 if (y .eq. 0.d0) go to 20
   a = x/y
   dcpabs = dabs(y)*dsqrt(1.d0 + a*a)
   return
20 dcpabs = 0.d0
return
end function dcpabs

subroutine crec (x, y, u, v)
implicit none
real, intent(inout) :: u, v
real, intent(in) :: x, y
real :: d, t
!-----------------------------------------------------------------------
!             COMPLEX RECIPROCAL u + I*v = 1/(x + I*y)
!-----------------------------------------------------------------------
if (abs(x) .gt. abs(y)) go to 10
   t = x/y
   d = y + t*x
   u = t/d
   v = -1.0/d
   return
10 t = y/x
d = x + t*y
u = 1.0/d
v = -t/d
return
end subroutine crec

subroutine dcrec (x, y, u, v)
implicit none
!-----------------------------------------------------------------------
!             COMPLEX RECIPROCAL u + I*v = 1/(x + I*y)
!-----------------------------------------------------------------------
double precision, intent(in) :: x, y
double precision, intent(inout) :: u, v
double precision :: d, t
!
if (dabs(x) .gt. dabs(y)) go to 10
   t = x/y
   d = y + t*x
   u = t/d
   v = -1.d0/d
   return
10 t = y/x
d = x + t*y
u = 1.d0/d
v = -t/d
return
end subroutine dcrec

complex function cdiv (a, b)
implicit none
real :: ai, ar, bi, br, d, t, u, v
!-----------------------------------------------------------------------
!              COMPLEX DIVISION a/b WHERE b IS NONZERO
!-----------------------------------------------------------------------
complex, intent(in) :: a, b
!
ar = real(a)
ai = aimag(a)
br = real(b)
bi = aimag(b)
!
if (abs(br) .lt. abs(bi)) go to 10
