&b(13) / .24986849985481658331800044137276d-04/, &
&b(14) /-.67319286764160294344603050339520d-05/, &
&b(15) / .17078578785573543710504524047844d-05/, &
&b(16) /-.40917551226475381271896592490038d-06/, &
