subroutine dginv (a, x, p, q, ierr)
implicit none
integer, intent(inout) :: ierr
integer :: ier, ind
!-----------------------------------------------------------------------
!
!                        Double precision
!             inverse incomplete gamma ratio function
!
!     GIVEN POSITIVE A, AND NONEGATIVE p AND q WHERE p + q = 1.
!     THEN x IS COMPUTED WHERE p(a,x) = p AND q(a,x) = q. SCHRODER
!     iteration is employed.
!
!                        ------------
!
!     x IS A VARIABLE. IF p = 0 THEN x IS ASSIGNED THE VALUE 0,
!     AND IF q = 0 THEN x IS SET TO THE LARGEST FLOATING POINT
!     number available. Otherwise, dginv attempts to obtain
!     A SOLUTION FOR p(a,x) = p AND q(a,x) = q. IF THE ROUTINE
!     is successful then the solution is stored in x.
!
!     ierr is a variable that reports the status of the results.
!     When the routine terminates, ierr has one of the following
!     values ...
!
!       ierr =  0    THE SOLUTION WAS OBTAINED. ITERATION WAS
!                    not used.
!       ierr.GT.0    THE SOLUTION WAS OBTAINED. ierr ITERATIONS
!                    were performed.
!       ierr = -2    (INPUT ERROR) a .LE. 0
!       ierr = -3    NO SOLUTION WAS OBTAINED. THE RATIO q/a
!                    is too large.
!       ierr = -4    (INPUT ERROR) p OR q IS NEGATIVE, OR
!                    p + q .NE. 1.
!       ierr = -6    10 ITERATIONS WERE PERFORMED. THE MOST
!                    recent value obtained for x is given.
!                    (This setting should never occur.)
!       ierr = -7    ITERATION FAILED. NO VALUE IS GIVEN FOR x.
!                    This may occur when x is approximately 0.
!       ierr = -8    A VALUE FOR x HAS BEEN OBTAINED, BUT THE
!                    routine is not certain of its accuracy.
!                    Iteration cannot be performed in this
!                    case. This setting can occur only when
!                    p or q is approximately 0.
!
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris, Jr.
!        Naval Surface Warfare Center
!        Dahlgren, Virginia
!     written ... January 1992
!------------------------
double precision, intent(in) :: a
double precision, intent(out) :: x
double precision, intent(in) :: p, q
real :: p0, q0, x0
double precision :: am1, apn, ap1, ap2, ap3, b, c, c1, c2, c3, c4, &
&c5, d, e, eps, g, h, ln10, pn, qg, qn, r, rta, s, sum, s2, t, tol, &
&u, w, xmin, xn, y, z, amin
double precision :: dpmpar, dlnrel, dgamma, dgamln, dgmln1, drcomp
!------------------------
!     ln10 = ln(10)
!     c = EULER CONSTANT
!------------------------
data ln10 /2.302585d0/
data c  /.577215664901533d0/
!------------------------
data tol /1.d-10/
!------------------------
!
!     ****** E AND XMIN ARE MACHINE DEPENDENT CONSTANTS. E IS THE
!            SMALLEST NUMBER FOR WHICH 1.0 + E .GT. 1.0, AND XMIN
!            is the smallest positive number.
!
             e = dpmpar(1)
             xmin = dpmpar(2)
!
!------------------------
x = 0.d0
if (a .le. 0.d0) go to 500
if (p .lt. 0.d0 .or. q .lt. 0.d0) go to 520
t = ((p + q) - 0.5d0) - 0.5d0
if (dabs(t) .gt. 5.d0*dmax1(e,1.d-30)) go to 520
!
ierr = 0
xmin = xmin/e
if ((p/e) .le. xmin) go to 400
if ((q/e) .le. xmin) go to 560
if (a .eq. 1.d0) go to 410
!
e = dmax1(e,1.d-30)
eps = 1.d3*e
amin = 5.d3
if (e .lt. 1.d-17) amin = 2.d6
if (a .ge. amin) go to 50
!
!        Get an initial approximation using the single
!         precision arithmetic (if this is possible)
!
p0 = p
q0 = q
if (p0 .eq. 0.0 .or.q0 .eq. 0.0) go to 10
call gaminv (sngl(a), x0, 0.0, p0, q0, ier)
if (ier .lt. 0.0 .and. ier .ne. -8) go to 10
ierr = max0(ier,0)
if (x0 .gt. 1.e34) go to 10
   xn = x0
   go to 100
!
10 if (a .gt. 1.d0) go to 50
xn = 0.d0
!
!        Selection of the initial approximation XN of x
!                       WHEN a .LT. 1
!
g = dgamma(a + 1.d0)
qg = q*g
if (qg .eq. 0.d0) go to 560
b = qg/a
if (qg .gt. 0.6d0*a) go to 30
if (a .ge. 0.30d0 .or. b .lt. 0.35d0) go to 20
   t = dexp(-(b + c))
   u = t*dexp(t)
   xn = t*dexp(u)
   go to 100
!
20 if (b .ge. 0.45d0) go to 30
if (b .eq. 0.d0) go to 560
y = -dlog(b)
s = 0.5d0 + (0.5d0 - a)
z = dlog(y)
t = y - s*z
if (b .lt. 0.15d0) go to 21
   xn = y - s*dlog(t) - dlog(1.d0 + s/(t + 1.d0))
   go to 200
21 if (b .le. 1.d-2) go to 22
   u = ((t + 2.d0*(3.d0 - a))*t + (2.d0 - a)*(3.d0 - a))/ &
&((t + (5.d0 - a))*t + 2.d0)
   xn = y - s*dlog(t) - dlog(u)
   go to 200
22 c1 = -s*z
c2 = -s*(1.d0 + c1)
c3 =  s*((0.5d0*c1 + (2.d0 - a))*c1 + (2.5d0 - 1.5d0*a))
c4 = -s*(((c1/3.d0 + (2.5d0 - 1.5d0*a))*c1 + ((a - 6.d0)*a &
&+ 7.d0))*c1 + ((11.d0*a - 46.d0)*a + 47.d0)/6.d0)
c5 = -s*((((-c1/4.d0 + (11.d0*a - 17.d0)/6.d0)*c1 &
&+ ((-3.d0*a + 13.d0)*a - 13.d0))*c1 &
&+ 0.5d0*(((2.d0*a - 25.d0)*a + 72.d0)*a - 61.d0))*c1 &
&+ (((25.d0*a - 195.d0)*a + 477.d0)*a - 379.d0)/12.d0)
xn = ((((c5/y + c4)/y + c3)/y + c2)/y + c1) + y
go to 200
!
30 if (b*q .gt. 1.d-8) go to 31
   xn = dexp(-(q/a + c))
   go to 40
31 if (p .le. 0.9d0) go to 32
   xn = dexp((dlnrel(-q) + dgmln1(a))/a)
   go to 40
32 xn = dexp(dlog(p*g)/a)
!
40 if (xn .eq. 0.d0) go to 510
t = 0.5d0 + (0.5d0 - xn/(a + 1.d0))
xn = xn/t
go to 100
!
!        Selection of the initial approximation XN of x
!                       WHEN a .GT. 1
!
50 t = p - 0.5d0
if (q .lt. 0.5d0) t = 0.5d0 - q
call dpni (p, q, t, s, ier)
!
rta = dsqrt(a)
s2 = s*s
xn = (((12.d0*s2 - 243.d0)*s2 - 923.d0)*s2 + 1472.d0)/204120.d0 &
&- s*(((3753.d0*s2 + 4353.d0)*s2 - 289517.d0)*s2 - 289717.d0) &
&/(146966400.d0*rta)
xn = (xn/a + s*((9.d0*s2 + 256.d0)*s2 - 433.d0)/(38880.d0*rta)) &
&- ((3.d0*s2 + 7.d0)*s2 - 16.d0)/810.d0
xn = a + s*rta + (s2 - 1.d0)/3.d0 + s*(s2 - 7.d0)/(36.d0*rta) &
&+ xn/a
xn = dmax1(xn, 0.d0)
!
if (a .lt. amin) go to 60
   x = xn
   d = 0.5d0 + (0.5d0 - x/a)
   if (dabs(d) .gt. 1.d-1) go to 60
   if (dabs(d) .gt. 1.d-3) go to 100
   return
!
60 if (p .le. 0.5d0) go to 70
if (xn .lt. 3.d0*a) go to 200
w = dlog(q)
y = -(w + dgamln(a))
d = dmax1(2.d0, a*(a - 1.d0))
if (y .lt. ln10*d) go to 61
   s = 1.d0 - a
   z = dlog(y)
   go to 22
61 t = a - 1.d0
xn = y + t*dlog(xn) - dlnrel(-t/(xn + 1.d0))
xn = y + t*dlog(xn) - dlnrel(-t/(xn + 1.d0))
go to 200
!
70 ap1 = a + 1.d0
if (xn .gt. 0.7d0*ap1) go to 101
w = dlog(p) + dgamln(ap1)
if (xn .gt. 0.15d0*ap1) go to 80
   ap2 = a + 2.d0
   ap3 = a + 3.d0
   x = dexp((w + x)/a)
   x = dexp((w + x - dlog(1.0 + (x/ap1)*(1.d0 + x/ap2)))/a)
   x = dexp((w + x - dlog(1.0 + (x/ap1)*(1.d0 + x/ap2)))/a)
   x = dexp((w + x - dlog(1.0 + (x/ap1)*(1.d0 + (x/ap2)*(1.d0 &
&+ x/ap3))))/a)
   xn = x
   if (xn .le. 1.d-2*ap1) go to 101
!
80 apn = ap1
t = xn/apn
sum = 1.d0 + t
81 apn = apn + 1.d0
   t = t*(xn/apn)
   sum = sum + t
   if (t .gt. 1.d-4) go to 81
t = w - dlog(sum)
xn = dexp((xn + t)/a)
xn = xn*(1.d0 - (a*dlog(xn) - xn - t)/(a - xn))
go to 101
!
!                 Schroder iteration using p
!
100 if (p .gt. 0.5d0) go to 200
101 if (p .le. xmin) go to 550
am1 = (a - 0.5d0) - 0.5d0
!
110 if (ierr .ge. 10) go to 530
ierr = ierr + 1
call dgrat (a, xn, pn, qn, ind)
if (pn .eq. 0.d0 .or. qn .eq. 0.d0) go to 550
r = drcomp(a,xn)
if (r .lt. xmin) go to 550
t = (pn - p)/r
w = 0.5d0*(am1 - xn)
if (dabs(t) .le. 0.1d0 .and. dabs(w*t) .le. 0.1d0) go to 120
   x = xn*(1.d0 - t)
   if (x .le. 0.d0) go to 540
   d = dabs(t)
   go to 121
!
120 h = t*(1.d0 + w*t)
x = xn*(1.d0 - h)
if (x .le. 0.d0) go to 540
if (dabs(w) .ge. 1.d0 .and. dabs(w)*t*t .le. eps) return
d = dabs(h)
121 xn = x
if (d .gt. tol) go to 110
if (d .le. eps) return
if (dabs(p - pn) .le. tol*p) return
go to 110
!
!                 Schroder iteration using q
!
200 if (q .le. xmin) go to 550
am1 = (a - 0.5d0) - 0.5d0
!
210 if (ierr .ge. 10) go to 530
ierr = ierr + 1
call dgrat (a, xn, pn, qn, ind)
if (pn .eq. 0.d0 .or. qn .eq. 0.d0) go to 550
r = drcomp(a,xn)
if (r .lt. xmin) go to 550
t = (q - qn)/r
w = 0.5d0*(am1 - xn)
if (dabs(t) .le. 0.1d0 .and. dabs(w*t) .le. 0.1d0) go to 220
   x = xn*(1.d0 - t)
   if (x .le. 0.d0) go to 540
   d = dabs(t)
   go to 221
!
220 h = t*(1.d0 + w*t)
x = xn*(1.d0 - h)
if (x .le. 0.d0) go to 540
if (dabs(w) .ge. 1.d0 .and. dabs(w)*t*t .le. eps) return
d = dabs(h)
221 xn = x
if (d .gt. tol) go to 210
if (d .le. eps) return
if (dabs(q - qn) .le. tol*q) return
go to 210
!
!                       Special cases
!
400 ierr = -8
return
!
410 if (q .lt. 0.9d0) go to 411
   x = -dlnrel(-p)
   return
411 x = -dlog(q)
return
!
!                       Error return
!
500 ierr = -2
return
!
510 ierr = -3
return
!
520 ierr = -4
return
!
530 ierr = -6
return
!
540 ierr = -7
return
!
550 x = xn
ierr = -8
return
!
560 x = dpmpar(3)
ierr = -8
return
end subroutine dginv

subroutine bratio (a, b, x, y, w, w1, ierr)
implicit none
real :: apser, basym, bfrac, bpser, bup, fpser, spmpar
integer, intent(inout) :: ierr
real, intent(in) :: a, b
real, intent(out) :: w, w1
real, intent(in) :: x, y
integer :: ierr1, ind, n
real :: a0, b0, eps, t, x0, y0, z
!-----------------------------------------------------------------------
!
!            Evaluation of the incomplete beta function ix(a,b)
!
!                     --------------------
!
!     IT IS ASSUMED THAT A AND b ARE NONNEGATIVE, AND THAT x .LE. 1
!     AND y = 1 - x.  bratio ASSIGNS w AND w1 THE VALUES
!
!                      w  = ix(a,b)
!                      w1 = 1 - ix(a,b)
!
!     ierr is a variable that reports the status of the results.
!     If no input errors are detected then ierr is set to 0 and
!     w and w1 are computed. Otherwise, if an error is detected,
!     then w and w1 are assigned the value 0 and ierr is set to
!     one of the following values ...
!
!        ierr = 1  IF A OR b IS NEGATIVE
!        ierr = 2  IF a = b = 0
!        ierr = 3  IF x .LT. 0 OR x .GT. 1
!        ierr = 4  IF y .LT. 0 OR y .GT. 1
!        ierr = 5  IF x + y .NE. 1
!        ierr = 6  IF x = a = 0
!        ierr = 7  IF y = b = 0
!
!--------------------
!     Written by Alfred H. Morris, Jr.
!        Naval Surface Warfare Center
!        Dahlgren, Virginia
!     revised ... nov 1991
!-----------------------------------------------------------------------
real :: lambda
!-----------------------------------------------------------------------
!
!     ****** eps IS A MACHINE DEPENDENT CONSTANT. EPS IS THE SMALLEST
!            FLOATING POINT NUMBER FOR WHICH 1.0 + eps .GT. 1.0
!
                 eps = spmpar(1)
!
!-----------------------------------------------------------------------
w = 0.0
w1 = 0.0
if (a .lt. 0.0 .or. b .lt. 0.0) go to 300
if (a .eq. 0.0 .and. b .eq. 0.0) go to 310
if (x .lt. 0.0 .or. x .gt. 1.0) go to 320
if (y .lt. 0.0 .or. y .gt. 1.0) go to 330
z = ((x + y) - 0.5) - 0.5
if (abs(z) .gt. 3.0*eps) go to 340
!
ierr = 0
if (x .eq. 0.0) go to 200
if (y .eq. 0.0) go to 210
if (a .eq. 0.0) go to 211
if (b .eq. 0.0) go to 201
!
eps = amax1(eps, 1.e-15)
if (amax1(a,b) .lt. 1.e-3*eps) go to 230
!
ind = 0
a0 = a
b0 = b
x0 = x
y0 = y
if (amin1(a0, b0) .gt. 1.0) go to 30
!
!             PROCEDURE FOR a0 .LE. 1 OR b0 .LE. 1
!
if (x .le. 0.5) go to 10
ind = 1
a0 = b
b0 = a
x0 = y
y0 = x
!
10 if (b0 .lt. amin1(eps,eps*a0)) go to 80
if (a0 .lt. amin1(eps,eps*b0) .and. b0*x0 .le. 1.0) go to 90
if (amax1(a0, b0) .gt. 1.0) go to 20
if (a0 .ge. amin1(0.2, b0)) go to 100
if (x0**a0 .le. 0.9) go to 100
if (x0 .ge. 0.3) go to 110
n = 20
go to 130
!
20 if (b0 .le. 1.0) go to 100
if (x0 .ge. 0.3) go to 110
if (x0 .ge. 0.1) go to 21
if ((x0*b0)**a0 .le. 0.7) go to 100
21 if (b0 .gt. 15.0) go to 131
n = 20
go to 130
!
!             PROCEDURE FOR a0 .GT. 1 AND b0 .GT. 1
!
30 if (a .gt. b) go to 31
   lambda = a - (a + b)*x
   go to 32
31 lambda = (a + b)*y - b
32 if (lambda .ge. 0.0) go to 40
ind = 1
a0 = b
b0 = a
x0 = y
y0 = x
lambda = abs(lambda)
!
40 if (b0 .lt. 40.0 .and. b0*x0 .le. 0.7) go to 100
if (b0 .lt. 40.0) go to 140
if (a0 .gt. b0) go to 50
   if (a0 .le. 100.0) go to 120
   if (lambda .gt. 0.03*a0) go to 120
   go to 180
50 if (b0 .le. 100.0) go to 120
if (lambda .gt. 0.03*b0) go to 120
go to 180
!
!            Evaluation of the appropriate algorithm
!
80 w = fpser(a0, b0, x0, eps)
w1 = 0.5 + (0.5 - w)
go to 220
!
90 w1 = apser(a0, b0, x0, eps)
w = 0.5 + (0.5 - w1)
go to 220
!
100 w = bpser(a0, b0, x0, eps)
w1 = 0.5 + (0.5 - w)
go to 220
!
110 w1 = bpser(b0, a0, y0, eps)
w = 0.5 + (0.5 - w1)
go to 220
!
120 w = bfrac(a0, b0, x0, y0, lambda, 15.0*eps)
w1 = 0.5 + (0.5 - w)
go to 220
!
130 w1 = bup(b0, a0, y0, x0, n, eps)
b0 = b0 + n
131 call bgrat(b0, a0, y0, x0, w1, 15.0*eps, ierr1)
w = 0.5 + (0.5 - w1)
go to 220
!
140 n = b0
b0 = b0 - n
if (b0 .ne. 0.0) go to 141
   n = n - 1
   b0 = 1.0
141 w = bup(b0, a0, y0, x0, n, eps)
if (x0 .gt. 0.7) go to 150
w = w + bpser(a0, b0, x0, eps)
w1 = 0.5 + (0.5 - w)
go to 220
!
150 if (a0 .gt. 15.0) go to 151
   n = 20
   w = w + bup(a0, b0, x0, y0, n, eps)
   a0 = a0 + n
151 call bgrat(a0, b0, x0, y0, w, 15.0*eps, ierr1)
w1 = 0.5 + (0.5 - w)
go to 220
!
180 w = basym(a0, b0, lambda, 100.0*eps)
w1 = 0.5 + (0.5 - w)
go to 220
!
!               Termination of the procedure
!
200 if (a .eq. 0.0) go to 350
201 w = 0.0
w1 = 1.0
return
!
210 if (b .eq. 0.0) go to 360
211 w = 1.0
w1 = 0.0
return
!
220 if (ind .eq. 0) return
t = w
w = w1
w1 = t
return
!
!           PROCEDURE FOR A AND b .LT. 1.E-3*eps
!
230 w = b/(a + b)
w1 = a/(a + b)
return
!
!                       Error return
!
300 ierr = 1
return
310 ierr = 2
return
320 ierr = 3
return
330 ierr = 4
return
340 ierr = 5
return
350 ierr = 6
return
360 ierr = 7
return
end subroutine bratio

real function fpser (a, b, x, eps)
implicit none
real, intent(in) :: a, b, eps, x
real :: an, c, s, t, tol
real :: exparg
!-----------------------------------------------------------------------
!
!                 Evaluation of I (a,b)
!                                x
!
!          FOR b .LT. min(eps,eps*a) AND x .LE. 0.5.
!
!-----------------------------------------------------------------------
!
!                  SET  fpser = x**a
!
fpser = 1.0
if (a .le. 1.e-3*eps) go to 10
fpser = 0.0
t = a*alog(x)
if (t .lt. exparg(1)) return
fpser = exp(t)
!
!                NOTE THAT 1/b(a,b) = b
!
10 fpser = (b/a)*fpser
tol = eps/a
an = a + 1.0
t = x
s = t/an
20 an = an + 1.0
   t = x*t
   c = t/an
   s = s + c
   if (abs(c) .gt. tol) go to 20
!
fpser = fpser*(1.0 + a*s)
return
end function fpser

real function apser (a, b, x, eps)
implicit none
real, intent(in) :: a, b, eps, x
real :: aj, bx, c, g, s, t, tol
real :: psi
!-----------------------------------------------------------------------
!     apser yields the incomplete beta ratio I(SUB(1-x))(b,A) for
!     a .LE. min(eps,eps*b), b*x .LE. 1, AND x .LE. 0.5. USED WHEN
!     A is very small. Use only if above inequalities are satisfied.
!-----------------------------------------------------------------------
real :: j
!--------------------
data g/.577215664901533/
!--------------------
bx = b*x
t = x - bx
if (b*eps .gt. 2.e-2) go to 10
   c = alog(x) + psi(b) + g + t
   go to 20
10 c = alog(bx) + g + t
!
20 tol = 5.0*eps*abs(c)
j = 1.0
s = 0.0
30 j = j + 1.0
   t = t*(x - bx/j)
   aj = t/j
   s = s + aj
   if (abs(aj) .gt. tol) go to 30
!
apser = -a*(c + s)
return
end function apser

real function bpser(a, b, x, eps)
implicit none
real, intent(in) :: a, b, eps, x
integer :: i, m
real :: a0, apb, b0, c, sum, t, tol, u, w, z
real :: algdiv, betaln, gam1, gamln1
!-----------------------------------------------------------------------
!     POWER SERIES EXPANSION FOR EVALUATING IX(a,b) WHEN b .LE. 1
!     OR b*x .LE. 0.7.  EPS IS THE TOLERANCE USED.
!-----------------------------------------------------------------------
real :: n
!
bpser = 0.0
if (x .eq. 0.0) return
!-----------------------------------------------------------------------
!            COMPUTE THE FACTOR x**a/(a*BETA(a,b))
!-----------------------------------------------------------------------
a0 = amin1(a,b)
if (a0 .lt. 1.0) go to 10
   z = a*alog(x) - betaln(a,b)
   bpser = exp(z)/a
   go to 70
10 b0 = amax1(a,b)
if (b0 .ge. 8.0) go to 60
if (b0 .gt. 1.0) go to 40
!
!            PROCEDURE FOR a0 .LT. 1 AND b0 .LE. 1
!
bpser = x**a
if (bpser .eq. 0.0) return
!
apb = a + b
if (apb .gt. 1.0) go to 20
   z = 1.0 + gam1(apb)
   go to 30
20 u = dble(a) + dble(b) - 1.d0
z = (1.0 + gam1(u))/apb
!
30 c = (1.0 + gam1(a))*(1.0 + gam1(b))/z
bpser = bpser*c*(b/apb)
go to 70
!
!         PROCEDURE FOR a0 .LT. 1 AND 1 .LT. b0 .LT. 8
!
40 u = gamln1(a0)
m = b0 - 1.0
if (m .lt. 1) go to 50
c = 1.0
do 41 i = 1,m
   b0 = b0 - 1.0
41 c = c*(b0/(a0 + b0))
u = alog(c) + u
!
50 z = a*alog(x) - u
b0 = b0 - 1.0
apb = a0 + b0
if (apb .gt. 1.0) go to 51
   t = 1.0 + gam1(apb)
   go to 52
51 u = dble(a0) + dble(b0) - 1.d0
t = (1.0 + gam1(u))/apb
52 bpser = exp(z)*(a0/a)*(1.0 + gam1(b0))/t
go to 70
!
!            PROCEDURE FOR a0 .LT. 1 AND b0 .GE. 8
!
60 u = gamln1(a0) + algdiv(a0,b0)
z = a*alog(x) - u
bpser = (a0/a)*exp(z)
70 if (bpser .eq. 0.0 .or. a .le. 0.1*eps) return
!-----------------------------------------------------------------------
!                     Compute the series
!-----------------------------------------------------------------------
sum = 0.0
n = 0.0
c = 1.0
tol = eps/a
100 n = n + 1.0
   c = c*(0.5 + (0.5 - b/n))*x
   w = c/(a + n)
   sum = sum + w
   if (abs(w) .gt. tol) go to 100
bpser = bpser*(1.0 + a*sum)
return
end function bpser

real function bup(a, b, x, y, n, eps)
implicit none
integer, intent(in) :: n
real, intent(in) :: a, b, eps, x, y
integer :: i, k, kp1, mu, nm1
real :: ap1, apb, d, r, t, w
real :: brcmp1, exparg
!-----------------------------------------------------------------------
!     Evaluation of IX(a,b) - IX(a+n,b) where n is a positive integer.
!     Eps is the tolerance used.
!-----------------------------------------------------------------------
real :: l
!
!          Obtain the scaling factor exp(-mu) and
!             exp(mu)*(x**a*y**b/BETA(a,b))/a
!
apb = a + b
ap1 = a + 1.0
mu = 0
d = 1.0
if (n .eq. 1 .or. a .lt. 1.0) go to 10
if (apb .lt. 1.1*ap1) go to 10
   mu = abs(exparg(1))
   k = exparg(0)
   if (k .lt. mu) mu = k
   t = mu
   d = exp(-t)
!
10 bup = brcmp1(mu,a,b,x,y)/a
if (n .eq. 1 .or. bup .eq. 0.0) return
nm1 = n - 1
w = d
!
!          Let k be the index of the maximum term
!
k = 0
if (b .le. 1.0) go to 40
if (y .gt. 1.e-4) go to 20
   k = nm1
   go to 30
20 r = (b - 1.0)*x/y - a
if (r .lt. 1.0) go to 40
k = nm1
t = nm1
if (r .lt. t) k = r
!
!          Add the increasing terms of the series
!
30 do i = 1,k
   l = i - 1
   d = ((apb + l)/(ap1 + l))*x*d
   w = w + d
end do
if (k .eq. nm1) go to 50
!
!          Add the remaining terms of the series
!
40 kp1 = k + 1
do i = kp1,nm1
   l = i - 1
   d = ((apb + l)/(ap1 + l))*x*d
   w = w + d
   if (d .le. eps*w) go to 50
end do
!
!               Terminate the procedure
!
50 bup = bup*w
return
end function bup

real function bfrac(a, b, x, y, lambda, eps)
implicit none
real, intent(in) :: a, b, eps, x, y
real :: alpha, an, anp1, beta, bn, bnp1, c, c0, c1, e, p, r, r0, &
&s, t, w, yp1
real :: brcomp
!-----------------------------------------------------------------------
!     CONTINUED FRACTION EXPANSION FOR IX(a,b) WHEN A,b .GT. 1.
!     IT IS ASSUMED THAT  lambda = (a + b)*y - b.
!-----------------------------------------------------------------------
real, intent(in) :: lambda
real :: n
!--------------------
bfrac = brcomp(a,b,x,y)
if (bfrac .eq. 0.0) return
!
c = 1.0 + lambda
c0 = b/a
c1 = 1.0 + 1.0/a
yp1 = y + 1.0
!
n = 0.0
p = 1.0
s = a + 1.0
an = 0.0
bn = 1.0
anp1 = 1.0
bnp1 = c/c1
r = c1/c
!
!        Continued fraction calculation
!
10 n = n + 1.0
   t = n/a
   w = n*(b - n)*x
   e = a/s
   alpha = (p*(p + c0)*e*e)*(w*x)
   e = (1.0 + t)/(c1 + t + t)
   beta = n + w/s + e*(c + n*yp1)
   p = 1.0 + t
   s = s + 2.0
!
!        Update an, bn, anp1, and bnp1
!
   t = alpha*an + beta*anp1
   an = anp1
   anp1 = t
   t = alpha*bn + beta*bnp1
   bn = bnp1
   bnp1 = t
!
   r0 = r
   r = anp1/bnp1
   if (abs(r - r0) .le. eps*r) go to 20
!
!        Rescale an, bn, anp1, and bnp1
!
   an = an/bnp1
   bn = bn/bnp1
   anp1 = r
   bnp1 = 1.0
   go to 10
!
!                 Termination
!
20 bfrac = bfrac*r
return
end function bfrac

real function brcomp (a, b, x, y)
implicit none
real, intent(in) :: a, b, x, y
integer :: i, n
real :: a0, apb, b0, c, const, e, h, t, u, v, x0, y0, z
real :: algdiv, alnrel, bcorr, betaln, gam1, gamln1, rlog1
!-----------------------------------------------------------------------
!               EVALUATION OF x**a*y**b/BETA(a,b)
!-----------------------------------------------------------------------
real :: lambda, lnx, lny
!-----------------
!     const = 1/sqrt(2*pi)
!-----------------
data const/.398942280401433/
!
brcomp = 0.0
if (x .eq. 0.0 .or. y .eq. 0.0) return
a0 = amin1(a,b)
if (a0 .ge. 8.0) go to 100
!
if (x .gt. 0.375) go to 10
   lnx = alog(x)
   lny = alnrel(-x)
   go to 20
10 if (y .gt. 0.375) go to 11
   lnx = alnrel(-y)
   lny = alog(y)
   go to 20
11 lnx = alog(x)
lny = alog(y)
!
20 z = a*lnx + b*lny
if (a0 .lt. 1.0) go to 30
z = z - betaln(a,b)
brcomp = exp(z)
return
!-----------------------------------------------------------------------
!              PROCEDURE FOR a .LT. 1 OR b .LT. 1
!-----------------------------------------------------------------------
30 b0 = amax1(a,b)
if (b0 .ge. 8.0) go to 80
if (b0 .gt. 1.0) go to 60
!
!                   ALGORITHM FOR b0 .LE. 1
!
brcomp = exp(z)
if (brcomp .eq. 0.0) return
!
apb = a + b
if (apb .gt. 1.0) go to 40
   z = 1.0 + gam1(apb)
   go to 50
40 u = dble(a) + dble(b) - 1.d0
z = (1.0 + gam1(u))/apb
!
50 c = (1.0 + gam1(a))*(1.0 + gam1(b))/z
brcomp = brcomp*(a0*c)/(1.0 + a0/b0)
return
!
!                ALGORITHM FOR 1 .LT. b0 .LT. 8
!
60 u = gamln1(a0)
n = b0 - 1.0
if (n .lt. 1) go to 70
c = 1.0
do i = 1,n
   b0 = b0 - 1.0
   c = c*(b0/(a0 + b0))
end do
u = alog(c) + u
!
70 z = z - u
b0 = b0 - 1.0
apb = a0 + b0
if (apb .gt. 1.0) go to 71
   t = 1.0 + gam1(apb)
   go to 72
71 u = dble(a0) + dble(b0) - 1.d0
t = (1.0 + gam1(u))/apb
72 brcomp = a0*exp(z)*(1.0 + gam1(b0))/t
return
!
!                   ALGORITHM FOR b0 .GE. 8
!
80 u = gamln1(a0) + algdiv(a0,b0)
brcomp = a0*exp(z - u)
return
!-----------------------------------------------------------------------
!              PROCEDURE FOR a .GE. 8 AND b .GE. 8
!-----------------------------------------------------------------------
100 if (a .gt. b) go to 101
   h = a/b
   x0 = h/(1.0 + h)
   y0 = 1.0/(1.0 + h)
   lambda = a - (a + b)*x
   go to 110
101 h = b/a
x0 = 1.0/(1.0 + h)
y0 = h/(1.0 + h)
lambda = (a + b)*y - b
!
110 e = -lambda/a
if (abs(e) .gt. 0.6) go to 111
   u = rlog1(e)
   go to 120
111 u = e - alog(x/x0)
!
120 e = lambda/b
if (abs(e) .gt. 0.6) go to 121
   v = rlog1(e)
   go to 130
121 v = e - alog(y/y0)
!
130 z = exp(-(a*u + b*v))
brcomp = const*sqrt(b*x0)*z*exp(-bcorr(a,b))
return
end function brcomp

real function brcmp1 (mu, a, b, x, y)
implicit none
integer, intent(in) :: mu
real, intent(in) :: a, b, x, y
integer :: i, n
real :: a0, apb, b0, c, const, e, h, t, u, v, x0, y0, z
real :: algdiv, alnrel, bcorr, betaln, esum, gam1, gamln1, rlog1
!-----------------------------------------------------------------------
!          EVALUATION OF  exp(mu) * (x**a*y**b/BETA(a,b))
!-----------------------------------------------------------------------
real :: lambda, lnx, lny
!-----------------
!     const = 1/sqrt(2*pi)
!-----------------
data const/.398942280401433/
!
a0 = amin1(a,b)
if (a0 .ge. 8.0) go to 100
!
if (x .gt. 0.375) go to 10
   lnx = alog(x)
   lny = alnrel(-x)
   go to 20
10 if (y .gt. 0.375) go to 11
   lnx = alnrel(-y)
   lny = alog(y)
   go to 20
11 lnx = alog(x)
lny = alog(y)
!
20 z = a*lnx + b*lny
if (a0 .lt. 1.0) go to 30
z = z - betaln(a,b)
brcmp1 = esum(mu,z)
return
!-----------------------------------------------------------------------
!              PROCEDURE FOR a .LT. 1 OR b .LT. 1
!-----------------------------------------------------------------------
30 b0 = amax1(a,b)
if (b0 .ge. 8.0) go to 80
if (b0 .gt. 1.0) go to 60
!
!                   ALGORITHM FOR b0 .LE. 1
!
brcmp1 = esum(mu,z)
if (brcmp1 .eq. 0.0) return
!
apb = a + b
if (apb .gt. 1.0) go to 40
   z = 1.0 + gam1(apb)
   go to 50
40 u = dble(a) + dble(b) - 1.d0
z = (1.0 + gam1(u))/apb
!
50 c = (1.0 + gam1(a))*(1.0 + gam1(b))/z
brcmp1 = brcmp1*(a0*c)/(1.0 + a0/b0)
return
!
!                ALGORITHM FOR 1 .LT. b0 .LT. 8
!
60 u = gamln1(a0)
n = b0 - 1.0
if (n .lt. 1) go to 70
c = 1.0
do i = 1,n
   b0 = b0 - 1.0
   c = c*(b0/(a0 + b0))
end do
u = alog(c) + u
!
70 z = z - u
b0 = b0 - 1.0
apb = a0 + b0
if (apb .gt. 1.0) go to 71
   t = 1.0 + gam1(apb)
   go to 72
71 u = dble(a0) + dble(b0) - 1.d0
t = (1.0 + gam1(u))/apb
72 brcmp1 = a0*esum(mu,z)*(1.0 + gam1(b0))/t
return
!
!                   ALGORITHM FOR b0 .GE. 8
!
80 u = gamln1(a0) + algdiv(a0,b0)
brcmp1 = a0*esum(mu,z - u)
return
!-----------------------------------------------------------------------
!              PROCEDURE FOR a .GE. 8 AND b .GE. 8
!-----------------------------------------------------------------------
100 if (a .gt. b) go to 101
   h = a/b
   x0 = h/(1.0 + h)
   y0 = 1.0/(1.0 + h)
   lambda = a - (a + b)*x
   go to 110
101 h = b/a
x0 = 1.0/(1.0 + h)
y0 = h/(1.0 + h)
lambda = (a + b)*y - b
!
110 e = -lambda/a
if (abs(e) .gt. 0.6) go to 111
   u = rlog1(e)
   go to 120
111 u = e - alog(x/x0)
!
120 e = lambda/b
if (abs(e) .gt. 0.6) go to 121
   v = rlog1(e)
   go to 130
121 v = e - alog(y/y0)
!
130 z = esum(mu,-(a*u + b*v))
brcmp1 = const*sqrt(b*x0)*z*exp(-bcorr(a,b))
return
end function brcmp1

subroutine bgrat(a, b, x, y, w, eps, ierr)
implicit none
integer, intent(inout) :: ierr
real, intent(in) :: a, b, eps
real, intent(inout) :: w
real, intent(in) :: x, y
integer :: i, n, nm1
real :: bm1, bp2n, cn, coef, dj, p, q, r, s, sum, t, t2, u, v, z
real :: algdiv, alnrel, gam1
!-----------------------------------------------------------------------
!     Asymptotic expansion for IX(a,b) when A is larger than b.
!     The result of the expansion is added to w. it is assumed
!     THAT a .GE. 15 AND b .LE. 1.  EPS IS THE TOLERANCE USED.
!     ierr is a variable that reports the status of the results.
!-----------------------------------------------------------------------
real :: j, l, lnx, nu, n2
real :: c(30), d(30)
!
bm1 = (b - 0.5) - 0.5
nu = a + 0.5*bm1
if (y .gt. 0.375) go to 10
   lnx = alnrel(-y)
   go to 11
10 lnx = alog(x)
11 z = -nu*lnx
if (b*z .eq. 0.0) go to 100
!
!                 Computation of the expansion
!                 SET r = exp(-z)*z**b/gamma(b)
!
r = b*(1.0 + gam1(b))*exp(b*alog(z))
r = r*exp(a*lnx)*exp(0.5*bm1*lnx)
u = algdiv(b,a) + b*alog(nu)
u = r*exp(-u)
if (u .eq. 0.0) go to 100
call grat1(b,z,r,p,q,eps)
!
v = 0.25*(1.0/nu)**2
t2 = 0.25*lnx*lnx
l = w/u
j = q/r
sum = j
t = 1.0
cn = 1.0
n2 = 0.0
do n = 1,30
   bp2n = b + n2
   j = (bp2n*(bp2n + 1.0)*j + (z + bp2n + 1.0)*t)*v
   n2 = n2 + 2.0
   t = t*t2
   cn = cn/(n2*(n2 + 1.0))
   c(n) = cn
   s = 0.0
   if (n .eq. 1) go to 21
      nm1 = n - 1
      coef = b - n
      do 20 i = 1,nm1
         s = s + coef*c(i)*d(n-i)
20 coef = coef + b
21 d(n) = bm1*cn + s/n
   dj = d(n)*j
   sum = sum + dj
   if (sum .le. 0.0) go to 100
   if (abs(dj) .le. eps*(sum + l)) go to 30
end do
!
!                    Add the results to w
!
30 ierr = 0
w = w + u*sum
return
!
!               The expansion cannot be computed
!
100 ierr = 1
return
end subroutine bgrat

subroutine grat1 (a,x,r,p,q,eps)
implicit none
real, intent(in) :: a, eps
real, intent(inout) :: p, q
real, intent(in) :: r, x
real :: a2n, a2nm1, am0, an, an0, b2n, b2nm1, c, cma, g, h, sum, &
&t, tol, w, z
real :: erfc1, gam1, rexp
real :: j, l
!-----------------------------------------------------------------------
!        Evaluation of the incomplete gamma ratio functions
!                      p(a,x) AND q(a,x)
!
!     IT IS ASSUMED THAT a .LE. 1.  EPS IS THE TOLERANCE TO BE USED.
!     THE INPUT ARGUMENT r HAS THE VALUE E**(-x)*x**a/gamma(a).
!-----------------------------------------------------------------------
if (a*x .eq. 0.0) go to 130
if (a .eq. 0.5) go to 120
if (x .lt. 1.1) go to 10
go to 50
!
!             TAYLOR SERIES FOR p(a,x)/x**a
!
10 an = 3.0
c = x
sum = x/(a + 3.0)
tol = 0.1*eps/(a + 1.0)
11 an = an + 1.0
   c = -c*(x/an)
   t = c/(a + an)
   sum = sum + t
   if (abs(t) .gt. tol) go to 11
j = a*x*((sum/6.0 - 0.5/(a + 2.0))*x + 1.0/(a + 1.0))
!
z = a*alog(x)
h = gam1(a)
g = 1.0 + h
if (x .lt. 0.25) go to 20
   if (a .lt. x/2.59) go to 40
   go to 30
20 if (z .gt. -.13394) go to 40
!
30 w = exp(z)
p = w*g*(0.5 + (0.5 - j))
q = 0.5 + (0.5 - p)
return
!
40 l = rexp(z)
w = 0.5 + (0.5 + l)
q = (w*j - l)*g - h
if (q .lt. 0.0) go to 110
p = 0.5 + (0.5 - q)
return
!
!              Continued fraction expansion
!
50 a2nm1 = 1.0
a2n = 1.0
b2nm1 = x
b2n = x + (1.0 - a)
c = 1.0
51 a2nm1 = x*a2n + c*a2nm1
   b2nm1 = x*b2n + c*b2nm1
   am0 = a2nm1/b2nm1
   c = c + 1.0
   cma = c - a
   a2n = a2nm1 + cma*a2n
   b2n = b2nm1 + cma*b2n
   an0 = a2n/b2n
   if (abs(an0 - am0) .ge. eps*an0) go to 51
q = r*an0
p = 0.5 + (0.5 - q)
return
!
!                Special cases
!
100 p = 0.0
q = 1.0
return
!
110 p = 1.0
q = 0.0
return
!
120 if (x .ge. 0.25) go to 121
p = erf(sqrt(x))
q = 0.5 + (0.5 - p)
return
121 q = erfc1(0,sqrt(x))
p = 0.5 + (0.5 - q)
return
!
130 if (x .le. a) go to 100
go to 110
end subroutine grat1

real function basym(a, b, lambda, eps)
implicit none
real, intent(in) :: a, b, eps
integer :: i, im1, imj, j, m, mm1, mmj, n, np1, num
real :: bsum, dsum, e0, e1, f, h, h2, hn, r, r0, r1, s, sum, t, &
&t0, t1, u, w, w0, z, z0, z2, zn, znm1
real :: bcorr, erfc1, rlog1
!-----------------------------------------------------------------------
!     Asymptotic expansion for IX(a,b) for large A and b.
!     lambda = (a + b)*Y - b  AND EPS IS THE TOLERANCE USED.
!     It is assumed that lambda is nonnegative and that
!     A and b are greater than or equal to 15.
!-----------------------------------------------------------------------
real :: j0, j1
real, intent(in) :: lambda
real :: a0(21), b0(21), c(21), d(21)
!------------------------
!     ****** num IS THE MAXIMUM VALUE THAT n CAN TAKE IN THE DO LOOP
!            ending at statement 50. It is required that num be even.
!            The arrays a0, b0, c, d have dimension num + 1.
!
                data num/20/
!------------------------
!     e0 = 2/sqrt(pi)
!     e1 = 2**(-3/2)
!------------------------
data e0/1.12837916709551/, e1/.353553390593274/
!------------------------
basym = 0.0
if (a .ge. b) go to 10
   h = a/b
   r0 = 1.0/(1.0 + h)
   r1 = (b - a)/b
   w0 = 1.0/sqrt(a*(1.0 + h))
   go to 20
10 h = b/a
r0 = 1.0/(1.0 + h)
r1 = (b - a)/a
w0 = 1.0/sqrt(b*(1.0 + h))
!
20 f = a*rlog1(-lambda/a) + b*rlog1(lambda/b)
t = exp(-f)
if (t .eq. 0.0) return
z0 = sqrt(f)
z = 0.5*(z0/e1)
z2 = f + f
!
a0(1) = (2.0/3.0)*r1
c(1) = - 0.5*a0(1)
d(1) = - c(1)
j0 = (0.5/e0)*erfc1(1,z0)
j1 = e1
sum = j0 + d(1)*w0*j1
!
s = 1.0
h2 = h*h
hn = 1.0
w = w0
znm1 = z
zn = z2
do n = 2, num, 2
   hn = h2*hn
   a0(n) = 2.0*r0*(1.0 + h*hn)/(n + 2.0)
   np1 = n + 1
   s = s + hn
   a0(np1) = 2.0*r1*s/(n + 3.0)
!
   do 41 i = n, np1
   r = -0.5*(i + 1.0)
   b0(1) = r*a0(1)
   do 31 m = 2, i
      bsum = 0.0
      mm1 = m - 1
      do 30 j = 1, mm1
         mmj = m - j
30 bsum = bsum + (j*r - mmj)*a0(j)*b0(mmj)
31 b0(m) = r*a0(m) + bsum/m
   c(i) = b0(i)/(i + 1.0)
!
   dsum = 0.0
   im1 = i - 1
   do 40 j = 1, im1
      imj = i - j
40 dsum = dsum + d(imj)*c(j)
41 d(i) = -(dsum + c(i))
!
   j0 = e1*znm1 + (n - 1.0)*j0
   j1 = e1*zn + n*j1
   znm1 = z2*znm1
   zn = z2*zn
   w = w0*w
   t0 = d(n)*w*j0
   w = w0*w
   t1 = d(np1)*w*j1
   sum = sum + (t0 + t1)
   if ((abs(t0) + abs(t1)) .le. eps*sum) go to 60
   end do
!
60 u = exp(-bcorr(a,b))
basym = e0*t*u*sum
return
end function basym

subroutine isubx (a0, b0, x0, p, ierr, eps)
implicit none
integer, intent(out) :: ierr
real, intent(in) :: a0, b0, eps
real, intent(out) :: p
real, intent(in) :: x0
integer :: ind, l, max
real :: a, afrac, am1, an, b, bfrac, c, gamrat, p0, pihalf, rpinv, &
&rty, sum, t, temp, tol, x, y
real :: algdiv
integer :: ipmpar
real :: blnd
real :: alnrel
real :: i, j, k, lambda, m, n, w(10), z(10)
!     -------------------
data w(1) /6.6671344308688e-2/,  w(2) /1.4945134915058e-1/, &
&w(3) /2.1908636251598e-1/,  w(4) /2.6926671931000e-1/, &
&w(5) /2.9552422471475e-1/,  w(6) /2.9552422471475e-1/, &
&w(7) /2.6926671931000e-1/,  w(8) /2.1908636251598e-1/, &
&w(9) /1.4945134915058e-1/,  w(10)/6.6671344308688e-2/
data z(1) /1.3046735791414e-2/,  z(2) /6.7468316655507e-2/, &
&z(3) /1.6029521585049e-1/,  z(4) /2.8330230293538e-1/, &
&z(5) /4.2556283050918e-1/,  z(6) /5.7443716949081e-1/, &
&z(7) /7.1669769706462e-1/,  z(8) /8.3970478414951e-1/, &
&z(9) /9.3253168334449e-1/,  z(10)/9.8695326420859e-1/
!     -------------------
!     rpinv = 1/sqrt(pi)
!     -------------------
data pihalf /1.5707963267949/
data rpinv  /.56418958354776/
!     -------------------
!     ****** max IS A MACHINE DEPENDENT CONSTANT. MAX IS THE
!            largest positive integer that may be used.
!
               max = ipmpar(3)
!
!     -------------------
a = a0
b = b0
x = x0
y = 0.5 + (0.5 - x)
!
!                        Check the arguments
!
p = 0.0
ierr = 1
if (a .lt. 0.5 .or. b .lt. 0.5) go to 410
if (x .eq. 0.0 .or. x .eq. 1.0) go to 300
if (x .lt. 0.0) go to 400
m = max
if (a .ge. m .or. b .gt. 70.0 .or. y .lt. 0.0) go to 411
k = int(a)
j = int(b)
afrac = a - k
bfrac = b - j
if ((afrac .ne. 0.0 .and. afrac .ne. 0.5) .or. &
&(bfrac .ne. 0.0 .and. bfrac .ne. 0.5)) go to 420
if (a .ge. 5000.0 .and. x .lt. 0.96) return
!
!                      Check if b is an integer
!
ind = 0
tol = 0.5*amax1(eps, 1.e-11)
if (bfrac .ne. 0.0) go to 100
if (afrac .ne. 0.0) go to 20
if (a .ge. b) go to 20
!
!                        Interchange A and b
!
10 ind = 1
t = b
b = a
a = t
t = y
y = x
x = t
t = j
j = k
k = t
!
!                        Compute expansion 14
!
20 am1 = a - 1.0
n = 1.0
if (am1 .lt. 0.5) go to 30
n = j
if (y .ge. 2.0*j*x) go to 30
t = am1*y/x + 1.0
if (t .lt. j) n = int(t)
!
30 i = n - 1.0
c = (a*alog(x) + i*alnrel(-x)) - blnd(a,i)
if (c .le. -30) go to 60
tol = tol/j
an = exp(c)
if (an .le. tol) go to 60
if (an .ge. 1.0 - tol) go to 330
!
c = an
sum = 0.0
40 i = i + 1.0
if (i .ge. j) go to 50
c = ((am1 + i)/i)*y*c
sum = sum + c
if (c .gt. tol) go to 40
!
50 i = n
c = an
51 i = i - 1.0
if (i .eq. 0.0) go to 52
c = i*c/((i + am1)*y)
sum = sum + c
if (c .gt. tol) go to 51
52 p = an + sum
!
60 if (p .ge. 1.0) p = 1.0
if (ind .eq. 0) return
p = 0.5 + (0.5 - p)
if (p .lt. 0.0) p = 0.0
return
!
!                Selection of the appropriate algorithm
!
100 am1 = a - 1.0
if (a .gt. 70.0) go to 150
if (afrac .eq. 0.0) go to 10
!
!                COMPUTE p0 = IX(a,1/2) OR p0 = IX(1/2,b)
!                           using formula 22
!
temp = sqrt(x)
rty  = sqrt(y)
c = atan(temp/rty)/pihalf
if (k .eq. 0.0) go to 130
ind = j
m = k + k
temp = -temp
!
110 i = 0.0
t = 1.0
sum = 0.0
111 i = i + 2.0
if (i .eq. m) go to 120
t = x*(i/(i + 1.0))*t
sum = t + sum
go to 111
!
120 p0 = (sum + 1.0)*temp*rty/pihalf + c
if (ind .ne. 0) go to 200
p = p0
return
!
130 if (j .eq. 0.0) go to 310
m = j + j
x = y
go to 110
!
!                  COMPUTE p0 = IX(a,1/2) FOR a .GT. 70
!                       using expansion 52 or 53
!
150 p0 = 0.0
if (x .lt. 0.7) go to 200
t = tol**(1.0/am1)
if (x .le. t) go to 200
!
t = 0.5 + (0.5 - t)
lambda = sqrt(t)
rty = sqrt(y)
gamrat = rpinv*exp(-algdiv(0.5,a))
if (t .ge. 4.0*y) go to 170
!
c = lambda - rty
temp = 2.0*rty
sum = 0.0
do 160 l = 1,10
   t = c*z(l)
160 sum = sum + w(l)*(x - t*(t + temp))**am1
p0 = c*gamrat*sum + 0.5*tol
go to 200
!
170 sum = 0.0
do 171 l = 1,10
   t = 1.0 - y*z(l)*z(l)
171 sum = sum + w(l)*t**am1
p0 = 1.0 - rty*gamrat*sum
!
!                     Compute p using expansion 21
!
200 if (j .eq. 0.0) go to 251
n = j
if (y .ge. 2.0*j*x) go to 210
t = am1*y/x + 0.5
if (t .ge. 2.0) go to 201
   n = 1.0
   go to 210
201 if (t .lt. j) n = int(t)
!
210 t = n - 0.5
c = (a*alog(x) + t*alnrel(-x)) - blnd(a,t)
if (c .le. -30.0) go to 251
c = exp(c)
if (c .le. tol/j) go to 251
if (p0 + c .ge. 1.0 - tol) go to 320
!
tol = tol/j
lambda = c
sum = 0.0
220 t = t + 1.0
if (t .gt. j) go to 240
lambda = (am1 + t)*y*lambda/t
sum = sum + lambda
if (lambda .gt. tol) go to 220
!
240 lambda = c
t = a - 0.5
i = n
241 i = i - 1.0
if (i .le. 0.0) go to 250
lambda = ((i + 0.5)/(i + t))*lambda/y
sum = lambda + sum
if (lambda .gt. tol) go to 241
!
250 p = c + sum
251 p = p + p0
if (p .ge. 1.0) p = 1.0
return
!
!                           Special cases
!
300 p = x
return
!
310 p = c
return
!
320 p = 1.0
return
!
330 p = 1 - ind
return
!
!                           Error return
!
400 ierr = 2
return
!
410 if (a .le. 0.0 .or. b .le. 0.0) go to 400
411 ierr = 3
return
!
420 ierr = 4
return
end subroutine isubx

real function blnd(a,b)
implicit none
real, intent(in) :: a, b
real :: algdiv
real :: logam
!
if (a .gt. 20.0) go to 10
   blnd = (logam(a) - logam(a + b)) + logam(b + 1.0)
   return
10 blnd = algdiv(b,a) + logam(b + 1.0)
return
end function blnd

real function logam (x)
implicit none
real, intent(in) :: x
integer :: n
real :: d, t, z
real :: w(200)
!     ------------------------------------------------------------------
!     COMPUTATION OF LN(gamma(x)) FOR x = n/2  WHERE n IS AN INTEGER
!     ------------------------------------------------------------------
!     d = 0.5*(ln(2*pi) - 1)
!     ---------------------
data d/.41893853320467/
!     ---------------------
data w(1)  /.57236494292470e+00/, w(2)  /0.0/, &
&w(3) /-.12078223763525e+00/, w(4)  /0.0/, &
&w(5)  /.28468287047292e+00/, w(6)  /.69314718055995e+00/, &
&w(7)  /.12009736023471e+01/, w(8)  /.17917594692281e+01/, &
&w(9)  /.24537365708424e+01/, w(10) /.31780538303479e+01/, &
