tm(1)=+an*ts(1)/pm
tm(2)=+an*ts(2)/pm
if(abs(sm(3))+abs(tm(1)).ne.abs(sm(3)))go to 017
if(abs(sm(4))+abs(tm(2)).eq.abs(sm(4)))go to 020
017 sm(3)=sm(3)+tm(1)
sm(4)=sm(4)+tm(2)
if(pm.lt.35.0)go to 015
go to 020
018 sm(1)=1.0
sm(2)=0.0
sm(3)=1.0
sm(4)=0.0
m=15.0*qn+2.0
n=15.0*qn+15.0
do 019 i = m,n
ts(1)=+qz(2)-cd(i)
ts(2)=-qz(1)
