tm(1)=+ce(i)*ts(1)/ss
tm(2)=-ce(i)*ts(2)/ss
sm(1)=sm(1)+tm(1)
sm(2)=sm(2)+tm(2)
ts(1)=-qz(2)-cd(i)
ts(2)=+qz(1)
ss=ts(1)*ts(1)+ts(2)*ts(2)
tm(1)=+ce(i)*ts(1)/ss
tm(2)=-ce(i)*ts(2)/ss
sm(3)=sm(3)+tm(1)
sm(4)=sm(4)+tm(2)
019 continue
ts(1)=+0.5*(sm(2)-sm(4))
ts(2)=-0.5*(sm(1)-sm(3))
sm(1)=+0.5*(sm(1)+sm(3))
sm(2)=+0.5*(sm(2)+sm(4))
sm(3)=ts(1)
sm(4)=ts(2)
020 aq(1)=qz(1)-1.57079632679490*(qn+0.5)
aq(2)=qz(2)
ts(1)=+cos(aq(1))*0.5*(exp(+aq(2))+exp(-aq(2)))
ts(2)=-sin(aq(1))*0.5*(exp(+aq(2))-exp(-aq(2)))
tm(1)=sm(1)*ts(1)-sm(2)*ts(2)
tm(2)=sm(1)*ts(2)+sm(2)*ts(1)
ts(1)=+sin(aq(1))*0.5*(exp(+aq(2))+exp(-aq(2)))
ts(2)=+cos(aq(1))*0.5*(exp(+aq(2))-exp(-aq(2)))
rm(1)=tm(1)-sm(3)*ts(1)+sm(4)*ts(2)
rm(2)=tm(2)-sm(3)*ts(2)-sm(4)*ts(1)
if(qn.eq.pn)go to 030
rm(3)=rm(1)
rm(4)=rm(2)
qn=qn+1.0
if(zm.le.17.5)go to 025
021 an=qn*qn-0.25
sm(1)=0.0
sm(2)=0.0
sm(3)=0.0
sm(4)=0.0
tm(1)=1.0
tm(2)=0.0
pm=0.0
go to 023
022 an=an-2.0*pm
pm=pm+1.0
ts(1)=tm(1)*rz(1)-tm(2)*rz(2)
ts(2)=tm(1)*rz(2)+tm(2)*rz(1)
tm(1)=-an*ts(1)/pm
tm(2)=-an*ts(2)/pm
023 sm(1)=sm(1)+tm(1)
sm(2)=sm(2)+tm(2)
an=an-2.0*pm
pm=pm+1.0
ts(1)=tm(1)*rz(1)-tm(2)*rz(2)
ts(2)=tm(1)*rz(2)+tm(2)*rz(1)
tm(1)=+an*ts(1)/pm
tm(2)=+an*ts(2)/pm
if(abs(sm(3))+abs(tm(1)).ne.abs(sm(3)))go to 024
if(abs(sm(4))+abs(tm(2)).eq.abs(sm(4)))go to 027
024 sm(3)=sm(3)+tm(1)
sm(4)=sm(4)+tm(2)
if(pm.lt.35.0)go to 022
go to 027
025 sm(1)=1.0
sm(2)=0.0
sm(3)=1.0
sm(4)=0.0
m=15.0*qn+2.0
n=15.0*qn+15.0
do 026 i = m,n
ts(1)=+qz(2)-cd(i)
ts(2)=-qz(1)
ss=ts(1)*ts(1)+ts(2)*ts(2)
tm(1)=+ce(i)*ts(1)/ss
tm(2)=-ce(i)*ts(2)/ss
sm(1)=sm(1)+tm(1)
sm(2)=sm(2)+tm(2)
ts(1)=-qz(2)-cd(i)
ts(2)=+qz(1)
ss=ts(1)*ts(1)+ts(2)*ts(2)
tm(1)=+ce(i)*ts(1)/ss
tm(2)=-ce(i)*ts(2)/ss
sm(3)=sm(3)+tm(1)
sm(4)=sm(4)+tm(2)
026 continue
ts(1)=+0.5*(sm(2)-sm(4))
ts(2)=-0.5*(sm(1)-sm(3))
sm(1)=+0.5*(sm(1)+sm(3))
sm(2)=+0.5*(sm(2)+sm(4))
sm(3)=ts(1)
sm(4)=ts(2)
027 aq(1)=qz(1)-1.57079632679490*(qn+0.5)
aq(2)=qz(2)
ts(1)=+cos(aq(1))*0.5*(exp(+aq(2))+exp(-aq(2)))
ts(2)=-sin(aq(1))*0.5*(exp(+aq(2))-exp(-aq(2)))
tm(1)=sm(1)*ts(1)-sm(2)*ts(2)
tm(2)=sm(1)*ts(2)+sm(2)*ts(1)
ts(1)=+sin(aq(1))*0.5*(exp(+aq(2))+exp(-aq(2)))
ts(2)=+cos(aq(1))*0.5*(exp(+aq(2))-exp(-aq(2)))
rm(1)=tm(1)-sm(3)*ts(1)+sm(4)*ts(2)
rm(2)=tm(2)-sm(3)*ts(2)-sm(4)*ts(1)
go to 029
028 tm(1)=+2.0*qn*qz(1)/zs
tm(2)=-2.0*qn*qz(2)/zs
ts(1)=tm(1)*rm(1)-tm(2)*rm(2)-rm(3)
ts(2)=tm(1)*rm(2)+tm(2)*rm(1)-rm(4)
rm(3)=rm(1)
rm(4)=rm(2)
rm(1)=ts(1)
rm(2)=ts(2)
qn=qn+1.0
029 if(qn.lt.pn)go to 028
030 fj(1)=qf(1)*rm(1)-qf(2)*rm(2)
fj(2)=qf(1)*rm(2)+qf(2)*rm(1)
w=cmplx(fj(1),fj(2))
return
031 sz(1)=+0.25*(qz(1)*qz(1)-qz(2)*qz(2))
sz(2)=+0.5*qz(1)*qz(2)
an=qn
sm(1)=0.0
sm(2)=0.0
sm(3)=0.0
sm(4)=0.0
tm(1)=1.0
tm(2)=0.0
pm=0.0
032 an=an+1.0
ts(1)=+tm(1)/an
ts(2)=+tm(2)/an
sm(3)=sm(3)+ts(1)
sm(4)=sm(4)+ts(2)
tm(1)=-ts(1)*sz(1)+ts(2)*sz(2)
tm(2)=-ts(1)*sz(2)-ts(2)*sz(1)
pm=pm+1.0
tm(1)=tm(1)/pm
tm(2)=tm(2)/pm
if(abs(sm(1))+abs(tm(1)).ne.abs(sm(1)))go to 033
if(abs(sm(2))+abs(tm(2)).eq.abs(sm(2)))go to 034
033 sm(1)=sm(1)+tm(1)
sm(2)=sm(2)+tm(2)
go to 032
034 sm(1)=sm(1)+1.0
an=qn+1.0
sm(3)=an*sm(3)
sm(4)=an*sm(4)
go to 036
035 an=qn*(qn+1.0)
tm(1)=sz(1)/an
tm(2)=sz(2)/an
ts(1)=-tm(1)*sm(3)+tm(2)*sm(4)
ts(2)=-tm(1)*sm(4)-tm(2)*sm(3)
sm(3)=sm(1)
sm(4)=sm(2)
sm(1)=sm(1)+ts(1)
sm(2)=sm(2)+ts(2)
qn=qn-1.0
036 if(qn.gt.pn)go to 035
qf(1)=sn
qf(2)=0.0
qn=0.0
go to 038
037 qn=qn+1.0
tm(1)=qf(1)*qz(1)-qf(2)*qz(2)
tm(2)=qf(1)*qz(2)+qf(2)*qz(1)
qf(1)=0.5*tm(1)/qn
qf(2)=0.5*tm(2)/qn
038 if(qn.lt.pn)go to 037
fj(1)=qf(1)*sm(1)-qf(2)*sm(2)
fj(2)=qf(1)*sm(2)+qf(2)*sm(1)
w=cmplx(fj(1),fj(2))
return
end subroutine bsslj

subroutine besj(x, alpha, n, y, nz)
implicit none
!
!     Written by D.E. Amos, S.L. Daniel and M.K. Weston, January, 1975.
!
!     References
!         sand-75-0147
!
!         CDC 6600 subroutines ibess and JBESS for Bessel functions
!         i(NU,X) AND J(NU,X), X.GE.0, NU.GE.0  BY D.E. AMOS, S.L.
!         Daniel, M.K. Weston. ACM trans math software,3,PP 76-92
!         (1977)
!
!         Tables of Bessel functions of moderate or large orders,
!         npl mathematical tables, vol. 6, by F.W.J. Olver, her
!         majesty-S stationery office, london, 1962.
!
!     Abstract
!         besj computes an n member sequence of J Bessel functions
!         J/SUB(alpha+k-1)/(X), k=1,...,n FOR NON-NEGATIVE alpha AND X.
!         A combination of the power series, the asymptotic expansion
!         for X to infinity and the uniform asymptotic expansion for
!         nu to infinity are applied over subdivisions of the (NU,X)
!         plane. For values of (NU,X) not covered by one of these
!         formulae, the order is incremented or decremented by integer
!         values into a region where one of the formulae apply. Backward
!         recursion is applied to reduce orders by integer values except
!         where the entire sequence lies in the oscillatory region. In
!         this case forward recursion is stable and values from the
!         asymptotic expansion for X to infinity start the recursion
!         when it is efficient to do so. Leading terms of the series and
!         uniform expansion are tested for underflow. If a sequence is
!         requested and the last member would underflow, the result is
!         set to zero and the next lower order tried, etc., until A
!         member comes on scale or all members are set to zero. Overflow
!         cannot occur.
!
!         besj calls asjy, jairy, gamln, spmpar, and ipmpar
!
!     Description of arguments
!
!         Input
!           X      - X.GE.0.0E0
!           alpha  - order of first member of the sequence,
!                    alpha.GE.0.0E0
!           n      - NUMBER OF MEMBERS IN THE SEQUENCE, n.GE.1
!
!         Output
!           y      - A VECTOR WHOSE FIRST n COMPONENTS CONTAIN
!                    VALUES FOR J/SUB(alpha+k-1)/(X), k=1,...,n
!           nz     - ERROR INDICATOR
!                    nz=0      NORMAL RETURN - COMPUTATION COMPLETED
!                    nz=-1     X IS LESS THAN 0.0
!                    nz=-2     alpha IS LESS THAN 0.0
!                    nz=-3     n IS LESS THAN 1
!                    nz.GT.0   LAST nz COMPONENTS OF y SET TO 0.0
!                              because of underflow
!
!     Error conditions
!         improper input arguments - a fatal error
!         UNDERFLOW  - A NON-FATAL ERROR (nz.GT.0)
!
external jairy
integer :: i, ialp, idalp, iflw, in, inlim, is, i1, i2, k, kk, km, &
&kt
integer, intent(in) :: n
integer :: nn, ns
integer, intent(inout) :: nz
integer :: ipmpar
real :: ak, akm
real, intent(in) :: alpha
real :: ans, ap, arg, coef, dalpha, dfn, dtm, earg, elim, etx, &
&fidal, flgjy, fn, fnf, fni, fnp1, fnu, fnulim(2), gln, pdf, pidt, &
&pp(4), rden, relb, rttp, rtwo, rtx, rzden, s, sa, sb, sxo2, s1, &
&s2, t, ta, tau, tb, temp(3), tfn, tm, tol, tolln, trx, tx, t1, t2, &
&wk(7), x, xo2, xo2l
real, intent(inout) :: y(n)
real :: gamln, spmpar
data rtwo,pdf,rttp,pidt                    / 1.34839972492648e+00, &
&7.85398163397448e-01, 7.97884560802865e-01, 1.57079632679490e+00/
data  pp(1),  pp(2),  pp(3),  pp(4)        / 8.72909153935547e+00, &
&2.65693932265030e-01, 1.24578576865586e-01, 7.70133747430388e-04/
data inlim           /      150            /
data fnulim(1), fnulim(2) /      100.0e0,     60.0e0     /
!     -------------------
!     ipmpar(8) replaces ipmpar(5) in a double precision code
!     ipmpar(9) replaces ipmpar(6) in a double precision code
!
!     Definition of the tolerances TOL and elim
!
tb = ipmpar(4)
ta = spmpar(1)/tb
if (tb.eq.2.0e0) go to 1
if (tb.eq.8.0e0) go to 2
if (tb.eq.16.0e0) go to 3
tb = alog(tb)
go to 5
1 tb = .69315e0
go to 5
2 tb = 2.07944e0
go to 5
3 tb = 2.77259e0
!
5 tol = amax1(ta,1.e-15)
i1 = ipmpar(5)
i2 = ipmpar(6)
!     ln(10**3) = 6.90776
elim = float(-i2)*tb - 6.90776e0
!     tolln = -ln(tol)
tolln = float(i1)*tb
tolln = amin1(tolln,34.5388e0)
!
!
!
nz = 0
kt = 1
if (n-1) 720, 10, 20
10 kt = 2
20 nn = n
if (x) 730, 30, 80
30 if (alpha) 710, 40, 50
40 y(1) = 1.0e0
if (n.eq.1) return
i1 = 2
go to 60
50 i1 = 1
60 do i=i1,n
  y(i) = 0.0e0
end do
return
80 continue
if (alpha.lt.0.0e0) go to 710
!
ialp = int(alpha)
fni = float(ialp+n-1)
fnf = alpha - float(ialp)
dfn = fni + fnf
fnu = dfn
xo2 = x*0.5e0
sxo2 = xo2*xo2
!
!     Decision tree for region where series, asymptotic expansion for X
!     to infinity and asymptotic expansion for nu to infinity are
!     applied.
!
if (sxo2.le.(fnu+1.0e0)) go to 90
ta = amax1(20.0e0,fnu)
if (x.gt.ta) go to 120
if (x.gt.12.0e0) go to 110
xo2l = alog(xo2)
ns = int(sxo2-fnu) + 1
go to 100
90 fn = fnu
fnp1 = fn + 1.0e0
xo2l = alog(xo2)
is = kt
if (x.le.0.50e0) go to 330
ns = 0
100 fni = fni + float(ns)
dfn = fni + fnf
fn = dfn
fnp1 = fn + 1.0e0
is = kt
if (n-1+ns.gt.0) is = 3
go to 330
110 ans = amax1(36.0e0-fnu,0.0e0)
ns = int(ans)
fni = fni + float(ns)
dfn = fni + fnf
fn = dfn
is = kt
if (n-1+ns.gt.0) is = 3
go to 130
120 continue
rtx = sqrt(x)
tau = rtwo*rtx
ta = tau + fnulim(kt)
if (fnu.le.ta) go to 480
fn = fnu
is = kt
!
!     Uniform asymptotic expansion for nu to infinity
!
130 continue
i1 = iabs(3-is)
i1 = max0(i1,1)
flgjy = 1.0e0
call asjy(jairy,x,fn,flgjy,i1,tol,elim,temp(is),wk,iflw)
if(iflw.ne.0) go to 380
go to (320, 450, 620), is
310 temp(1) = temp(3)
kt = 1
320 is = 2
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
if(i1.eq.2) go to 450
go to 130
!
!     SERIES FOR (X/2)**2.LE.NU+1
!
330 continue
gln = gamln(fnp1)
arg = fn*xo2l - gln
if (arg.lt.(-elim)) go to 400
earg = exp(arg)
340 continue
s = 1.0e0
if (x.lt.tol) go to 360
ak = 3.0e0
t2 = 1.0e0
t = 1.0e0
s1 = fn
do k=1,17
  s2 = t2 + s1
  t = -t*sxo2/s2
  s = s + t
  if (abs(t).lt.tol) go to 360
  t2 = t2 + ak
  ak = ak + 2.0e0
  s1 = s1 + fn
end do
360 continue
temp(is) = s*earg
go to (370, 450, 610), is
370 earg = earg*fn/xo2
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
is = 2
go to 340
!
!     Set underflow value and update parameters
!
380 y(nn) = 0.0e0
nn = nn - 1
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
if (nn-1) 440, 390, 130
390 kt = 2
is = 2
go to 130
400 y(nn) = 0.0e0
nn = nn - 1
fnp1 = fn
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
if (nn-1) 440, 410, 420
410 kt = 2
is = 2
420 if (sxo2.le.fnp1) go to 430
go to 130
430 arg = arg - xo2l + alog(fnp1)
if (arg.lt.(-elim)) go to 400
go to 330
440 nz = n - nn
return
!
!     Backward recursion section
!
450 continue
nz = n - nn
if (kt.eq.2) go to 470
!     Backward recur from index alpha+nn-1 to alpha
y(nn) = temp(1)
y(nn-1) = temp(2)
if (nn.eq.2) return
trx = 2.0e0/x
dtm = fni
tm = (dtm+fnf)*trx
k = nn + 1
do i=3,nn
  k = k - 1
  y(k-2) = tm*y(k-1) - y(k)
  dtm = dtm - 1.0e0
  tm = (dtm+fnf)*trx
end do
return
470 y(1) = temp(2)
return
!
!     Asymptotic expansion for X to infinity with forward recursion in
!     OSCILLATORY REGION X.GT.max(20, NU), PROVIDED THE LAST MEMBER
!     of the sequence is also in the region.
!
480 continue
in = int(alpha-tau+2.0e0)
if (in.le.0) go to 490
idalp = ialp - in - 1
kt = 1
go to 500
490 continue
idalp = ialp
in = 0
500 is = kt
fidal = float(idalp)
dalpha = fidal + fnf
arg = x - pidt*dalpha - pdf
sa = sin(arg)
sb = cos(arg)
coef = rttp/rtx
etx = 8.0e0*x
510 continue
dtm = fidal + fidal
dtm = dtm*dtm
tm = 0.0e0
if (fidal.eq.0.0e0 .and. abs(fnf).lt.tol) go to 520
tm = 4.0e0*fnf*(fidal+fidal+fnf)
520 continue
trx = dtm - 1.0e0
t2 = (trx+tm)/etx
s2 = t2
relb = tol*abs(t2)
t1 = etx
s1 = 1.0e0
fn = 1.0e0
ak = 8.0e0
do k=1,13
  t1 = t1 + etx
  fn = fn + ak
  trx = dtm - fn
  ap = trx + tm
  t2 = -t2*ap/t1
  s1 = s1 + t2
  t1 = t1 + etx
  ak = ak + 8.0e0
  fn = fn + ak
  trx = dtm - fn
  ap = trx + tm
  t2 = t2*ap/t1
  s2 = s2 + t2
  if (abs(t2).le.relb) go to 540
  ak = ak + 8.0e0
end do
540 temp(is) = coef*(s1*sb-s2*sa)
if(is.eq.2) go to 560
550 fidal = fidal + 1.0e0
dalpha = fidal + fnf
is = 2
tb = sa
sa = -sb
sb = tb
go to 510
!
!     Forward recursion section
!
560 if (kt.eq.2) go to 470
s1 = temp(1)
s2 = temp(2)
tx = 2.0e0/x
tm = dalpha*tx
if (in.eq.0) go to 580
!
!     Forward recur to index alpha
!
do i=1,in
  s = s2
  s2 = tm*s2 - s1
  tm = tm + tx
  s1 = s
end do
if (nn.eq.1) go to 600
s = s2
s2 = tm*s2 - s1
tm = tm + tx
s1 = s
580 continue
!
!     Forward recur from index alpha to alpha+n-1
!
y(1) = s1
y(2) = s2
if (nn.eq.2) return
do i=3,nn
  y(i) = tm*y(i-1) - y(i-2)
  tm = tm + tx
end do
return
600 y(1) = s2
return
!
!     Backward recursion with normalization by
!     asymptotic expansion for nu to infinity or power series.
!
610 continue
!     Computation of last order for series normalization
akm = amax1(3.0e0-fn,0.0e0)
km = int(akm)
tfn = fn + float(km)
ta = (gln+tfn-0.9189385332e0-0.0833333333e0/tfn)/(tfn+0.5e0)
ta = xo2l - ta
tb = -(1.0e0-1.5e0/tfn)/tfn
akm = tolln/(-ta+sqrt(ta*ta-tolln*tb)) + 1.5e0
in = km + int(akm)
go to 660
620 continue
!     Computation of last order for asymptotic expansion normalization
gln = wk(3) + wk(2)
if (wk(6).gt.30.0e0) go to 640
rden = (pp(4)*wk(6)+pp(3))*wk(6) + 1.0e0
rzden = pp(1) + pp(2)*wk(6)
ta = rzden/rden
if (wk(1).lt.0.10e0) go to 630
tb = gln/wk(5)
go to 650
630 tb=(1.259921049e0+(0.1679894730e0+0.0887944358e0*wk(1))*wk(1)) &
&/wk(7)
go to 650
640 continue
ta = 0.5e0*tolln/wk(4)
ta=((0.0493827160e0*ta-0.1111111111e0)*ta+0.6666666667e0)*ta*wk(6)
if (wk(1).lt.0.10e0) go to 630
tb = gln/wk(5)
650 in = int(ta/tb+1.5e0)
if (in.gt.inlim) go to 310
660 continue
dtm = fni + float(in)
trx = 2.0e0/x
tm = (dtm+fnf)*trx
ta = 0.0e0
tb = tol
kk = 1
670 continue
!
!     Backward recur unindexed
!
do i=1,in
  s = tb
  tb = tm*tb - ta
  ta = s
  dtm = dtm - 1.0e0
  tm = (dtm+fnf)*trx
end do
!     Normalization
if (kk.ne.1) go to 690
ta = (ta/tb)*temp(3)
tb = temp(3)
kk = 2
in = ns
if (ns.ne.0) go to 670
690 y(nn) = tb
nz = n - nn
if (nn.eq.1) return
k = nn - 1
y(k) = tm*tb - ta
if (nn.eq.2) return
dtm = dtm - 1.0e0
tm = (dtm+fnf)*trx
km = k - 1
!
!     Backward recur indexed
!
do i=1,km
  y(k-1) = tm*y(k) - y(k+1)
  dtm = dtm - 1.0e0
  tm = (dtm+fnf)*trx
  k = k - 1
end do
return
!
!
!
710 continue
nz = -2
return
720 continue
nz = -3
return
730 continue
nz = -1
return
end subroutine besj

subroutine asjy(funjy,x,fnu,flgjy,in,tol,elim,y,wk,iflw)
implicit none
!
!               asjy computes Bessel functions j and Y
!               FOR ARGUMENTS X.GT.0.0 AND ORDERS FNU.GE.35.0
!               ON FLGJY = 1 AND FLGJY = -1 RESPECTIVELY
!
!                                  Input
!
!      FUNJY - external function jairy or YAIRY
!          X - ARGUMENT, X.GT.0.0E0
!        FNU - order of the first Bessel function
!      FLGJY - selection flag
!              FLGJY =  1.0E0 GIVES THE j FUNCTION
!              FLGJY = -1.0E0 GIVES THE Y FUNCTION
!         in - NUMBER OF FUNCTIONS DESIRED, in = 1 OR 2
!        TOL - tolerance specified by besj or BESY
!       ELIM - tolerance specified by besj or BESY
!
!                                  Output
!
!         Y  - a vector whose first in components contain the sequence
!       iflw - a flag indicating underflow or overflow
!                    RETURN VARIABLES FOR besj ONLY
!      wk(1) = 1 - (x/fnu)**2 = w**2
!      wk(2) = sqrt(abs(wk(1)))
!      wk(3) = abs(wk(2) - atan(wk(2)))  or
!              abs(LN((1 + WK(2))/(X/FNU)) - WK(2))
!            = abs((2/3)*ZETA**(3/2))
!      wk(4) = fnu*wk(3)
!      wk(5) = (1.5*wk(3)*fnu)**(1/3) = sqrt(zeta)*fnu**(1/3)
!      wk(6) = sign(1.,w**2)*wk(5)**2 = sign(1.,w**2)*zeta*fnu**(2/3)
!      wk(7) = fnu**(1/3)
!
!                                  Written by
!                                  D. E. Amos
!
!     Abstract
!         ASJK implements the uniform asymptotic expansion of
!         THE j AND Y BESSEL FUNCTIONS FOR FNU.GE.35 AND REAL
!         X.GT.0.0E0. THE FORMS ARE IDENTICAL EXCEPT FOR A CHANGE
!         in sign of some of the terms. This change in sign is
!         ACCOMPLISHED BY MEANS OF THE FLAG flgjy = 1 OR -1. ON
!         FLGJY = 1 THE AIRY FUNCTIONS ai(X) AND DAI(X) ARE
!         supplied by the external function jairy, and on
!         FLGJY = -1 THE AIRY FUNCTIONS bi(X) AND DBI(X) ARE
!         supplied by the external funtion YAIRY.
!
integer :: i, iflw, in, j, jn, jr, ju, k, kb, klast, kmax(5), kp1, &
&ks, ksp1, kstemp, l, lr, lrp1
real :: abw2, akm, alfa(26,4), alfa1(26,2), alfa2(26,2), ap, &
&ar(8), asum, az, beta(26,5), beta1(26,2), beta2(26,2), &
&beta3(26,1), br(10), bsum, c(65), con1, con2, con3, con548, &
&cr(10), crz32, dfi, elim, dr(10), fi, flgjy, fn, fnu, fn2, &
&gama(26), phi, rcz, rden, relb, rfn2, rtz, rzden, sa, sb, suma, &
&sumb, s1, ta, tau, tb, tfn, tol, tols, t2, upol(10), wk(*), x, xx, &
&y(*), z, z32
external funjy
equivalence (alfa(1,1),alfa1(1,1))
equivalence (alfa(1,3),alfa2(1,1))
equivalence (beta(1,1),beta1(1,1))
equivalence (beta(1,3),beta2(1,1))
equivalence (beta(1,5),beta3(1,1))
data tols            /-6.90775527898214e+00/
data con1,con2,con3,con548/ &
&6.66666666666667e-01, 3.33333333333333e-01, 1.41421356237310e+00, &
&1.04166666666667e-01/
data  ar(1),  ar(2),  ar(3),  ar(4),  ar(5),  ar(6),  ar(7), &
&ar(8)          / 8.35503472222222e-02, 1.28226574556327e-01, &
&2.91849026464140e-01, 8.81627267443758e-01, 3.32140828186277e+00, &
&1.49957629868626e+01, 7.89230130115865e+01, 4.74451538868264e+02/
data  br(1), br(2), br(3), br(4), br(5), br(6), br(7), br(8), &
&br(9), br(10)  /-1.45833333333333e-01,-9.87413194444444e-02, &
&-1.43312053915895e-01,-3.17227202678414e-01,-9.42429147957120e-01, &
&-3.51120304082635e+00,-1.57272636203680e+01,-8.22814390971859e+01, &
&-4.92355370523671e+02,-3.31621856854797e+03/
data c(1), c(2), c(3), c(4), c(5), c(6), c(7), c(8), c(9), c(10), &
&c(11), c(12), c(13), c(14), c(15), c(16), c(17), c(18), &
&c(19), c(20), c(21), c(22), c(23), c(24)/ &
&-2.08333333333333e-01,        1.25000000000000e-01, &
&3.34201388888889e-01,       -4.01041666666667e-01, &
&7.03125000000000e-02,       -1.02581259645062e+00, &
