sm(4)=sm(4)+tm(2)
018 continue
019 rm(1)=sm(1)
rm(2)=sm(2)
if(qz(1).ge.17.5)go to 023
aq(1)=-2.0*qz(1)
if(qz(2))020,021,021
020 aq(2)=-2.0*qz(2)-3.14159265358979*(qn+0.5)
go to 022
021 aq(2)=-2.0*qz(2)+3.14159265358979*(qn+0.5)
022 qm=exp(aq(1))
ts(1)=qm*cos(aq(2))
ts(2)=qm*sin(aq(2))
rm(1)=rm(1)+ts(1)*sm(3)-ts(2)*sm(4)
rm(2)=rm(2)+ts(1)*sm(4)+ts(2)*sm(3)
023 if(qn.eq.pn)go to 037
rm(3)=rm(1)
rm(4)=rm(2)
qn=qn+1.0
if(zm.le.17.5)go to 029
024 an=qn*qn-0.25
sm(1)=0.0
sm(2)=0.0
sm(3)=0.0
sm(4)=0.0
tm(1)=1.0
tm(2)=0.0
pm=0.0
go to 026
025 an=an-2.0*pm
pm=pm+1.0
ts(1)=tm(1)*rz(1)-tm(2)*rz(2)
ts(2)=tm(1)*rz(2)+tm(2)*rz(1)
tm(1)=an*ts(1)/pm
tm(2)=an*ts(2)/pm
026 sm(1)=sm(1)+tm(1)
sm(2)=sm(2)+tm(2)
an=an-2.0*pm
pm=pm+1.0
ts(1)=tm(1)*rz(1)-tm(2)*rz(2)
ts(2)=tm(1)*rz(2)+tm(2)*rz(1)
tm(1)=an*ts(1)/pm
tm(2)=an*ts(2)/pm
if(abs(sm(3))+abs(tm(1)).ne.abs(sm(3)))go to 027
if(abs(sm(4))+abs(tm(2)).eq.abs(sm(4)))go to 028
027 sm(3)=sm(3)+tm(1)
sm(4)=sm(4)+tm(2)
if(pm.lt.35.0)go to 025
028 ts(1)=sm(1)+sm(3)
ts(2)=sm(2)+sm(4)
sm(1)=sm(1)-sm(3)
sm(2)=sm(2)-sm(4)
sm(3)=ts(1)
sm(4)=ts(2)
go to 031
029 sm(1)=1.0
sm(2)=0.0
sm(3)=1.0
sm(4)=0.0
m=15.0*qn+2.0
n=15.0*qn+15.0
do 030 i = m,n
ts(1)=-qz(1)-cd(i)
ts(2)=-qz(2)
ss=ts(1)*ts(1)+ts(2)*ts(2)
tm(1)=+ce(i)*ts(1)/ss
tm(2)=-ce(i)*ts(2)/ss
sm(1)=sm(1)+tm(1)
sm(2)=sm(2)+tm(2)
ts(1)=+qz(1)-cd(i)
ts(2)=+qz(2)
ss=ts(1)*ts(1)+ts(2)*ts(2)
tm(1)=+ce(i)*ts(1)/ss
tm(2)=-ce(i)*ts(2)/ss
sm(3)=sm(3)+tm(1)
sm(4)=sm(4)+tm(2)
030 continue
031 rm(1)=sm(1)
rm(2)=sm(2)
if(qz(1).ge.17.5)go to 036
aq(1)=-2.0*qz(1)
if(qz(2))032,033,033
032 aq(2)=-2.0*qz(2)-3.14159265358979*(qn+0.5)
go to 034
033 aq(2)=-2.0*qz(2)+3.14159265358979*(qn+0.5)
034 qm=exp(aq(1))
ts(1)=qm*cos(aq(2))
ts(2)=qm*sin(aq(2))
rm(1)=rm(1)+ts(1)*sm(3)-ts(2)*sm(4)
rm(2)=rm(2)+ts(1)*sm(4)+ts(2)*sm(3)
go to 036
035 tm(1)=-2.0*qn*qz(1)/zs
tm(2)=+2.0*qn*qz(2)/zs
ts(1)=tm(1)*rm(1)-tm(2)*rm(2)+rm(3)
ts(2)=tm(1)*rm(2)+tm(2)*rm(1)+rm(4)
rm(3)=rm(1)
rm(4)=rm(2)
rm(1)=ts(1)
rm(2)=ts(2)
qn=qn+1.0
036 if(qn.lt.pn)go to 035
037 if(mo.ne.0)go to 038
qm=exp(qz(1))
tm(1)=qm*cos(qz(2))
tm(2)=qm*sin(qz(2))
ts(1)=tm(1)*rm(1)-tm(2)*rm(2)
ts(2)=tm(1)*rm(2)+tm(2)*rm(1)
rm(1)=ts(1)
rm(2)=ts(2)
038 fi(1)=qf(1)*rm(1)-qf(2)*rm(2)
fi(2)=qf(1)*rm(2)+qf(2)*rm(1)
w=cmplx(fi(1),fi(2))
return
039 sz(1)=0.25*(qz(1)*qz(1)-qz(2)*qz(2))
sz(2)=0.5*qz(1)*qz(2)
an=qn
sm(1)=0.0
sm(2)=0.0
sm(3)=0.0
sm(4)=0.0
tm(1)=1.0
tm(2)=0.0
pm=0.0
040 an=an+1.0
ts(1)=tm(1)/an
ts(2)=tm(2)/an
sm(3)=sm(3)+ts(1)
sm(4)=sm(4)+ts(2)
tm(1)=ts(1)*sz(1)-ts(2)*sz(2)
tm(2)=ts(1)*sz(2)+ts(2)*sz(1)
pm=pm+1.0
tm(1)=tm(1)/pm
tm(2)=tm(2)/pm
if(abs(sm(1))+abs(tm(1)).ne.abs(sm(1)))go to 041
if(abs(sm(2))+abs(tm(2)).eq.abs(sm(2)))go to 042
041 sm(1)=sm(1)+tm(1)
sm(2)=sm(2)+tm(2)
go to 040
042 sm(1)=sm(1)+1.0
an=qn+1.0
sm(3)=an*sm(3)
sm(4)=an*sm(4)
go to 044
043 an=qn*(qn+1.0)
tm(1)=sz(1)/an
tm(2)=sz(2)/an
ts(1)=+tm(1)*sm(3)-tm(2)*sm(4)
ts(2)=+tm(1)*sm(4)+tm(2)*sm(3)
sm(3)=sm(1)
sm(4)=sm(2)
sm(1)=sm(1)+ts(1)
sm(2)=sm(2)+ts(2)
qn=qn-1.0
044 if(qn.gt.pn)go to 043
qf(1)=sn
qf(2)=0.0
qn=0.0
go to 046
045 qn=qn+1.0
tm(1)=qf(1)*qz(1)-qf(2)*qz(2)
tm(2)=qf(1)*qz(2)+qf(2)*qz(1)
qf(1)=0.5*tm(1)/qn
qf(2)=0.5*tm(2)/qn
046 if(qn.lt.pn)go to 045
if(mo.eq.0)go to 047
qm=exp(-qz(1))
tm(1)=qm*cos(-qz(2))
tm(2)=qm*sin(-qz(2))
ts(1)=tm(1)*qf(1)-tm(2)*qf(2)
ts(2)=tm(1)*qf(2)+tm(2)*qf(1)
qf(1)=ts(1)
qf(2)=ts(2)
047 fi(1)=qf(1)*sm(1)-qf(2)*sm(2)
fi(2)=qf(1)*sm(2)+qf(2)*sm(1)
w=cmplx(fi(1),fi(2))
return
end subroutine bssli

subroutine besi(x, alpha, kode, n, y, nz)
implicit none
!
!     Written by D. E. Amos and S. L. Daniel, January,1975.
!
!     Reference
!         sand-75-0152
!
!         CDC 6600 subroutines ibess and JBESS for Bessel functions
!         i(NU,x) AND J(NU,x), x.GE.0, NU.GE.0  BY D.E. AMOS, S.L.
!         Daniel, M.K. Weston. ACM trans math software,3,PP 76-92
!         (1977)
!
!         Tables of Bessel functions of moderate or large orders,
!         npl mathematical tables, vol. 6, by F.W.J. Olver, her
!         majesty-S stationery office, london, 1962.
!
!     Abstract
!         besi computes an n member sequence of i Bessel functions
!         i/SUB(alpha+k-1)/(x), k=1,...,n OR SCALED BESSEL FUNCTIONS
!         exp(-x)*i/SUB(alpha+k-1)/(x), k=1,...,n FOR NON-NEGATIVE alpha
!         and x. a combination of the power series, the asymptotic
!         expansion for x to infinity, and the uniform asymptotic
!         expansion for nu to infinity are applied over subdivisions of
!         the (NU,x) plane. For values not covered by one of these
!         formulae, the order is incremented by an integer so that one
!         of these formulae apply. Backward recursion is used to reduce
!         orders by integer values. The asymptotic expansion for x to
!         infinity is used only when the entire sequence (specifically
!         the last member) lies within the region covered by the
!         expansion. Leading terms of these expansions are used to test
!         for over or underflow where appropriate. If a sequence is
!         requested and the last member would underflow, the result is
!         set to zero and the next lower order tried, etc., until A
!         member comes on scale or all are set to zero. An overflow
!         cannot occur with scaling.
!
!         besi calls asik, gamln, spmpar, and ipmpar
!
!     Description of arguments
!
!         Input
!           x      - x.GE.0.0E0
!           alpha  - order of first member of the sequence,
!                    alpha.GE.0.0E0
!           kode   - A PARAMETER TO INDICATE THE SCALING OPTION
!                    kode=1 returns
!                           y(k)=        i/sub(alpha+k-1)/(x),
!                                k=1,...,n
!                    kode=2 returns
!                           y(k)=exp(-x)*i/sub(alpha+k-1)/(x),
!                                k=1,...,n
!           n      - NUMBER OF MEMBERS IN THE SEQUENCE, n.GE.1
!
!         Output
!           y      - A VECTOR WHOSE FIRST n COMPONENTS CONTAIN
!                    values for i/SUB(alpha+k-1)/(x) or scaled
!                    values for exp(-x)*i/SUB(alpha+k-1)/(x),
!                    k=1,...,n DEPENDING ON kode
!           nz     - ERROR INDICATOR
!                    nz= 0     NORMAL RETURN-COMPUTATION COMPLETED
!                    nz=-1     x IS LESS THAN 0.0
!                    nz=-2     alpha IS LESS THAN 0.0
!                    nz=-3     n IS LESS THAN 1
!                    nz=-4     kode IS NOT 1 OR 2
!                    nz=-5     x IS TOO LARGE FOR kode=1
!                    nz.GT.0   LAST nz COMPONENTS OF y SET TO 0.0
!                              because of underflow
!
!     Error conditions
!         improper input arguments - a fatal error
!         OVERFLOW WITH kode=1 - A FATAL ERROR
!         UNDERFLOW - A NON-FATAL ERROR(nz.GT.0)
!
integer :: i, ialp, in, inlim, is, i1, i2, k, kk, km
integer, intent(in) :: kode
integer :: kt
integer, intent(in) :: n
integer :: nn, ns
integer, intent(inout) :: nz
integer :: ipmpar
real :: ain, ak, akm
real, intent(in) :: alpha
real :: ans, ap, arg, atol, tolln, dfn, dtm, dx, earg, elim, etx, &
&flgik, fn, fnf, fni, fnp1, fnu, gln, ra, rttpi, s, sx, sxo2, s1, &
&s2, t, ta, tb, temp(3), tfn, tm, tol, trx, t2
real, intent(in) :: x
real :: xo2, xo2l
real, intent(inout) :: y(n)
real :: z
real :: gamln, spmpar
data rttpi           / 3.98942280401433e-01/
data inlim           /          80         /
!     -------------------
!     ipmpar(8) replaces ipmpar(5) in a double precision code
!     ipmpar(9) replaces ipmpar(6) in a double precision code
!
!     Definition of the tolerances TOL and elim
!
tb = ipmpar(4)
ta = spmpar(1)/tb
if (tb.eq.2.0e0) go to 1
if (tb.eq.8.0e0) go to 2
if (tb.eq.16.0e0) go to 3
tb = alog(tb)
go to 5
1 tb = .69315e0
go to 5
2 tb = 2.07944e0
go to 5
3 tb = 2.77259e0
!
5 tol = amax1(ta,1.e-15)
i1 = ipmpar(5)
i2 = ipmpar(6)
!     ln(10**3) = 6.90776
elim = float(-i2)*tb - 6.90776e0
!     tolln = -ln(tol)
tolln = float(i1)*tb
tolln = amin1(tolln,34.5388e0)
!
!
!
nz = 0
kt = 1
if (n-1) 590, 10, 20
10 kt = 2
20 nn = n
if (kode.lt.1 .or. kode.gt.2) go to 570
if (x) 600, 30, 80
30 if (alpha) 580, 40, 50
40 y(1) = 1.0e0
if (n.eq.1) return
i1 = 2
go to 60
50 i1 = 1
60 do i=i1,n
  y(i) = 0.0e0
end do
return
80 continue
if (alpha.lt.0.0e0) go to 580
!
ialp = int(alpha)
fni = float(ialp+n-1)
fnf = alpha - float(ialp)
dfn = fni + fnf
fnu = dfn
in = 0
xo2 = x*0.5e0
sxo2 = xo2*xo2
etx = float(kode-1)
sx = etx*x
!
!     Decision tree for region where series, asymptotic expansion for x
!     to infinity and asymptotic expansion for nu to infinity are
!     applied.
!
if (sxo2.le.(fnu+1.0e0)) go to 90
if (x.le.12.0e0) go to 110
fn = 0.55e0*fnu*fnu
fn = amax1(17.0e0,fn)
if (x.ge.fn) go to 430
ans = amax1(36.0e0-fnu,0.0e0)
ns = int(ans)
fni = fni + float(ns)
dfn = fni + fnf
fn = dfn
is = kt
km = n - 1 + ns
if (km.gt.0) is = 3
go to 120
90 fn = fnu
fnp1 = fn + 1.0e0
xo2l = alog(xo2)
is = kt
if (x.le.0.5e0) go to 230
ns = 0
100 fni = fni + float(ns)
dfn = fni + fnf
fn = dfn
fnp1 = fn + 1.0e0
is = kt
if (n-1+ns.gt.0) is = 3
go to 230
110 xo2l = alog(xo2)
ns = int(sxo2-fnu)
go to 100
120 continue
!
!     Overflow test on uniform asymptotic expansion
!
if (kode.eq.2) go to 130
if (alpha.lt.1.0e0) go to 150
z = x/alpha
ra = sqrt(1.0e0+z*z)
gln = alog((1.0e0+ra)/z)
t = ra*(1.0e0-etx) + etx/(z+ra)
arg = alpha*(t-gln)
if (arg.gt.elim) go to 610
if (km.eq.0) go to 140
130 continue
!
!     Underflow test on uniform asymptotic expansion
!
z = x/fn
ra = sqrt(1.0e0+z*z)
gln = alog((1.0e0+ra)/z)
t = ra*(1.0e0-etx) + etx/(z+ra)
arg = fn*(t-gln)
140 if (arg.lt.(-elim)) go to 280
go to 190
150 if (x.gt.elim) go to 610
go to 130
!
!     Uniform asymptotic expansion for nu to infinity
!
160 if (km.ne.0) go to 170
y(1) = temp(3)
return
170 temp(1) = temp(3)
in = ns
kt = 1
i1 = 0
180 continue
is = 2
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
if(i1.eq.2) go to 350
z = x/fn
ra = sqrt(1.0e0+z*z)
gln = alog((1.0e0+ra)/z)
t = ra*(1.0e0-etx) + etx/(z+ra)
arg = fn*(t-gln)
190 continue
i1 = iabs(3-is)
i1 = max0(i1,1)
flgik = 1.0e0
call asik(x,fn,kode,flgik,ra,arg,i1,tol,temp(is))
go to (180, 350, 510), is
!
!     SERIES FOR (x/2)**2.LE.NU+1
!
230 continue
gln = gamln(fnp1)
arg = fn*xo2l - gln - sx
if (arg.lt.(-elim)) go to 300
earg = exp(arg)
240 continue
s = 1.0e0
if (x.lt.tol) go to 260
ak = 3.0e0
t2 = 1.0e0
t = 1.0e0
s1 = fn
do k=1,17
  s2 = t2 + s1
  t = t*sxo2/s2
  s = s + t
  if (abs(t).lt.tol) go to 260
  t2 = t2 + ak
  ak = ak + 2.0e0
  s1 = s1 + fn
end do
260 continue
temp(is) = s*earg
go to (270, 350, 500), is
270 earg = earg*fn/xo2
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
is = 2
go to 240
!
!     Set underflow value and update parameters
!
280 y(nn) = 0.0e0
nn = nn - 1
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
if (nn-1) 340, 290, 130
290 kt = 2
is = 2
go to 130
300 y(nn) = 0.0e0
nn = nn - 1
fnp1 = fn
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
if (nn-1) 340, 310, 320
310 kt = 2
is = 2
320 if (sxo2.le.fnp1) go to 330
go to 130
330 arg = arg - xo2l + alog(fnp1)
if (arg.lt.(-elim)) go to 300
go to 230
340 nz = n - nn
return
!
!     Backward recursion section
!
350 continue
nz = n - nn
360 continue
if(kt.eq.2) go to 420
s1 = temp(1)
s2 = temp(2)
trx = 2.0e0/x
dtm = fni
tm = (dtm+fnf)*trx
if (in.eq.0) go to 390
!     Backward recur to index alpha+nn-1
do i=1,in
  s = s2
  s2 = tm*s2 + s1
  s1 = s
  dtm = dtm - 1.0e0
  tm = (dtm+fnf)*trx
end do
y(nn) = s1
if (nn.eq.1) return
y(nn-1) = s2
if (nn.eq.2) return
go to 400
390 continue
!     Backward recur from index alpha+nn-1 to alpha
y(nn) = s1
y(nn-1) = s2
if (nn.eq.2) return
400 k = nn + 1
do i=3,nn
  k = k - 1
  y(k-2) = tm*y(k-1) + y(k)
  dtm = dtm - 1.0e0
  tm = (dtm+fnf)*trx
end do
return
420 y(1) = temp(2)
return
!
!     Asymptotic expansion for x to infinity
!
430 continue
earg = rttpi/sqrt(x)
if (kode.eq.2) go to 440
if (x.gt.elim) go to 610
earg = earg*exp(x)
440 etx = 8.0e0*x
is = kt
in = 0
fn = fnu
450 dx = fni + fni
tm = 0.0e0
if (fni.eq.0.0e0 .and. abs(fnf).lt.tol) go to 460
tm = 4.0e0*fnf*(fni+fni+fnf)
460 continue
dtm = dx*dx
s1 = etx
trx = dtm - 1.0e0
dx = -(trx+tm)/etx
t = dx
s = 1.0e0 + dx
atol = tol*abs(s)
s2 = 1.0e0
ak = 8.0e0
do k=1,25
  s1 = s1 + etx
  s2 = s2 + ak
  dx = dtm - s2
  ap = dx + tm
  t = -t*ap/s1
  s = s + t
  if (abs(t).le.atol) go to 480
  ak = ak + 8.0e0
end do
480 temp(is) = s*earg
if(is.eq.2) go to 360
is = 2
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
go to 450
!
!     Backward recursion with normalization by
!     asymptotic expansion for nu to infinity or power series.
!
500 continue
!     Computation of last order for series normalization
akm = amax1(3.0e0-fn,0.0e0)
km = int(akm)
tfn = fn + float(km)
ta = (gln+tfn-0.9189385332e0-0.0833333333e0/tfn)/(tfn+0.5e0)
ta = xo2l - ta
tb = -(1.0e0-1.0e0/tfn)/tfn
ain = tolln/(-ta+sqrt(ta*ta-tolln*tb)) + 1.5e0
in = int(ain)
in = in + km
go to 520
510 continue
!     Computation of last order for asymptotic expansion normalization
t = 1.0e0/(fn*ra)
ain = tolln/(gln+sqrt(gln*gln+t*tolln)) + 1.5e0
in = int(ain)
if (in.gt.inlim) go to 160
520 continue
trx = 2.0e0/x
dtm = fni + float(in)
tm = (dtm+fnf)*trx
ta = 0.0e0
tb = tol
kk = 1
530 continue
!
!     Backward recur unindexed
!
do i=1,in
  s = tb
  tb = tm*tb + ta
  ta = s
  dtm = dtm - 1.0e0
  tm = (dtm+fnf)*trx
end do
!     Normalization
if (kk.ne.1) go to 550
ta = (ta/tb)*temp(3)
tb = temp(3)
kk = 2
in = ns
if (ns.ne.0) go to 530
550 y(nn) = tb
nz = n - nn
if (nn.eq.1) return
tb = tm*tb + ta
k = nn - 1
y(k) = tb
if (nn.eq.2) return
dtm = dtm - 1.0e0
tm = (dtm+fnf)*trx
km = k - 1
!
!     Backward recur indexed
!
do i=1,km
  y(k-1) = tm*y(k) + y(k+1)
  dtm = dtm - 1.0e0
  tm = (dtm+fnf)*trx
  k = k - 1
end do
return
!
!
!
570 continue
nz = -4
return
580 continue
nz = -2
return
590 continue
nz = -3
return
600 continue
nz = -1
return
610 continue
nz = -5
return
end subroutine besi

subroutine asik(x,fnu,kode,flgik,ra,arg,in,tol,y)
implicit none
!
!                  asik computes Bessel functions I and k
!                  FOR ARGUMENTS x.GT.0.0 AND ORDERS fnu.GE.35
!                  ON flgik = 1 AND flgik = -1 RESPECTIVELY.
!
!                                    Input
!
!      x    - ARGUMENT, x.GT.0.0E0
!      fnu  - order of first Bessel function
!      kode - a parameter to indicate the scaling option
!             kode=1 RETURNS y(I)=        I/SUB(fnu+I-1)/(x), I=1,IN
!                    OR      y(I)=        k/SUB(fnu+I-1)/(x), I=1,IN
!                    ON flgik = 1.0E0 OR flgik = -1.0E0
!             kode=2 RETURNS y(I)=exp(-x)*I/SUB(fnu+I-1)/(x), I=1,IN
!                    OR      y(I)=exp( x)*k/SUB(fnu+I-1)/(x), I=1,IN
!                    ON flgik = 1.0E0 OR flgik = -1.0E0
!     flgik - selection parameter for I or k function
!             flgik =  1.0E0 GIVES THE I FUNCTION
!             flgik = -1.0E0 GIVES THE k FUNCTION
!        ra - sqrt(1.+z*z), z=x/fnu
!       arg - argument of the leading exponential
!        in - NUMBER OF FUNCTIONS DESIRED, in=1 OR 2
!       tol - tolerance specified by besi or BESK
!
!                                    Output
!
!         y - a vector whose first in components contain the sequence
!
!                                 Written by
!                                 D. E. Amos
!
!     Abstract
!         asik implements the uniform asymptotic expansion of
!         THE I AND k BESSEL FUNCTIONS FOR fnu.GE.35 AND REAL
!         x.GT.0.0E0. THE FORMS ARE IDENTICAL EXCEPT FOR A CHANGE
!         in sign of some of the terms. This change in sign is
!         ACCOMPLISHED BY MEANS OF THE FLAG flgik = 1 OR -1.
!
integer, intent(in) :: in
integer :: j, jn, k, kk
integer, intent(in) :: kode
integer :: l
real :: ak, ap
real, intent(inout) :: arg
real :: c(65), coef, con(2), etx
real, intent(in) :: flgik
real :: fn
real, intent(in) :: fnu
real :: gln
real, intent(inout) :: ra
real :: s1, s2, t
real, intent(in) :: tol
real :: t2
real, intent(in) :: x
real, intent(inout) :: y(*)
real :: z
data con(1), con(2)  / &
&3.98942280401432678e-01,    1.25331413731550025e+00/
data c(1), c(2), c(3), c(4), c(5), c(6), c(7), c(8), c(9), c(10), &
&c(11), c(12), c(13), c(14), c(15), c(16), c(17), c(18), &
&c(19), c(20), c(21), c(22), c(23), c(24)/ &
&-2.08333333333333e-01,        1.25000000000000e-01, &
&3.34201388888889e-01,       -4.01041666666667e-01, &
&7.03125000000000e-02,       -1.02581259645062e+00, &
&1.84646267361111e+00,       -8.91210937500000e-01, &
&7.32421875000000e-02,        4.66958442342625e+00, &
&-1.12070026162230e+01,        8.78912353515625e+00, &
&-2.36408691406250e+00,        1.12152099609375e-01, &
&-2.82120725582002e+01,        8.46362176746007e+01, &
&-9.18182415432400e+01,        4.25349987453885e+01, &
&-7.36879435947963e+00,        2.27108001708984e-01, &
&2.12570130039217e+02,       -7.65252468141182e+02, &
&1.05999045252800e+03,       -6.99579627376133e+02/
data c(25), c(26), c(27), c(28), c(29), c(30), c(31), c(32), &
&c(33), c(34), c(35), c(36), c(37), c(38), c(39), c(40), &
&c(41), c(42), c(43), c(44), c(45), c(46), c(47), c(48)/ &
&2.18190511744212e+02,       -2.64914304869516e+01, &
&5.72501420974731e-01,       -1.91945766231841e+03, &
&8.06172218173731e+03,       -1.35865500064341e+04, &
&1.16553933368645e+04,       -5.30564697861340e+03, &
&1.20090291321635e+03,       -1.08090919788395e+02, &
&1.72772750258446e+00,        2.02042913309661e+04, &
&-9.69805983886375e+04,        1.92547001232532e+05, &
&-2.03400177280416e+05,        1.22200464983017e+05, &
&-4.11926549688976e+04,        7.10951430248936e+03, &
&-4.93915304773088e+02,        6.07404200127348e+00, &
&-2.42919187900551e+05,        1.31176361466298e+06, &
&-2.99801591853811e+06,        3.76327129765640e+06/
data c(49), c(50), c(51), c(52), c(53), c(54), c(55), c(56), &
&c(57), c(58), c(59), c(60), c(61), c(62), c(63), c(64), &
&c(65)/ &
&-2.81356322658653e+06,        1.26836527332162e+06, &
&-3.31645172484564e+05,        4.52187689813627e+04, &
&-2.49983048181121e+03,        2.43805296995561e+01, &
&3.28446985307204e+06,       -1.97068191184322e+07, &
&5.09526024926646e+07,       -7.41051482115327e+07, &
&6.63445122747290e+07,       -3.75671766607634e+07, &
&1.32887671664218e+07,       -2.78561812808645e+06, &
&3.08186404612662e+05,       -1.38860897537170e+04, &
&1.10017140269247e+02/
!     ---------------------
fn = fnu
z  = (3.0e0-flgik)/2.0e0
kk = int(z)
do 50 jn = 1,in
  if (jn.eq.1) go to 10
  fn = fn - flgik
  z = x/fn
  ra = sqrt(1.0e0+z*z)
  gln = alog((1.0e0+ra)/z)
  etx = float(kode-1)
  t = ra*(1.0e0-etx) + etx/(z+ra)
  arg = fn*(t-gln)*flgik
10 coef = exp(arg)
  t = 1.0e0/ra
  t2 = t*t
  t = t/fn
  t = sign(t,flgik)
  s2 = 1.0e0
  ap = 1.0e0
  l = 0
  do 30 k = 2,11
    l = l + 1
    s1 = c(l)
    do 20 j = 2,k
      l = l + 1
      s1 = s1*t2 + c(l)
20 continue
    ap = ap*t
    ak = ap*s1
    s2 = s2 + ak
    if (amax1(abs(ak),abs(ap)) .lt. tol) go to 40
30 continue
40 continue
t = abs(t)
y(jn) = s2*coef*sqrt(t)*con(kk)
50 continue
return
end subroutine asik

subroutine cbesk (z, cnu, w)
implicit none
real :: a, b, c, e, rn, rz, s, tau, x, y
real :: cpabs
!-----------------------------------------------------------------------
!
!        Calculation of the modified Bessel function of the
!        second kind for complex order cnu and complex argument
!        z.  IT IS ASSUMED THAT -PI .LT. ARG z .LE. PI.
!
!-----------------------------------------------------------------------
!     Written by
!        Alfred H. Morris, Jr. and Andrew H. van Tuyl
!        Naval Surface Warfare Center
!        oct 1992
!--------------------------
complex :: z
complex, intent(in) :: cnu
complex, intent(inout) :: w
complex :: nu
!
x = abs(real(z))
y = abs(aimag(z))
nu = cnu
if (real(nu) .lt. 0.0) nu = - nu
a = real(nu)
b = abs(aimag(nu))
rn = cpabs(a, b)
rz = cpabs(x, y)
!
!     Asymptotic expansion
!
if (rz .lt. 17.5 + 0.5*rn*rn) go to 10
   call cbka (z, nu, w)
   return
!
10 if (b .le. 1.5e-2*a) go to 200
tau = rn/rz
if (tau .ge. 1.5) go to 100
if (tau .le. 0.05) go to 200
if (tau .lt. 0.70 .and. real(z) .le. 0.0) go to 100
if (aimag(nu) .gt. 0.0 .and. b .lt. 0.07*a) go to 200
!
if (tau .lt. 1.291) go to 20
if (aimag(nu) .lt. 0.0 .and. b .lt. 0.127*a) go to 40
   s = 0.5*(1.5 - tau)
   if (b .lt. s*a) go to 200
   go to 100
!
20 if (tau .lt. 0.639) go to 60
if (tau .gt. 0.691) go to 30
   if (b .gt. 0.5*a) go to 61
   e = b/a
   go to 50
!
30 if (b .lt. 0.191*a) go to 40
if (tau .gt. 0.99 .and. b .gt. 0.257*a .and. &
&b .lt. 0.64*a) go to 61
if (tau .le. 1.16 .and. b .lt. 0.727*a .and. &
&y .lt. 0.727*x) go to 200
if (tau .le. 0.91 .and. a .gt. 0.45*b .and. &
&y .lt. 0.325*x) go to 200
c = 0.471
if (tau .lt. 0.75) c = 0.55
if (tau .lt. 0.844 .and. a .lt. 0.55*b .and. &
&y .lt. c*x) go to 200
!
40 s = 1.65*(1.54 - tau)**2
if (tau .lt. 0.91) s = 0.82 - 1.5*(tau - 0.8)
e = 2.25
if (tau .lt. 0.78) e = 2.90
if (b .gt. e*s*a) go to 100
if (b .gt. 0.5*a) go to 61
!
e = b/(s*a)
if (e .lt. 0.50) go to 50
   c = 2.83 - 1.66*e
   if (y .gt. c*x) go to 100
   go to 200
50 c = 7.0 - 10.0*e
if (tau .gt. 0.86) c = 8.0 - 12.0*e
if (y .gt. c*x) go to 100
go to 200
!
60 if (b .le. 0.191*a) go to 200
61 if (x .lt. 0.64*(tau - 0.2)*y) go to 100
s = 1.5*b/(a + 1.e-7)
e = 0.95
if (tau .gt. 0.95 .and. tau .lt. 1.16 .and. &
&b .gt. 0.471*a .and. b .le. a) e = 0.75
if (tau .gt. 0.85 .and. tau .le. 0.95 .and. &
&b .le. a) e = 0.80
if (tau .gt. 0.71 .and. tau .le. 0.85 .and. &
&b .lt. 1.21*a) e = 0.85
if (tau .gt. 0.61 .and. tau .le. 0.71 .and. &
&b .gt. 0.63*a .and. b .lt. 1.15*a) e = 0.80
if (tau .gt. 0.50 .and. tau .le. 0.61 .and. &
&b .gt. 0.7*a .and. b .le. a) e = 0.70
!
if (tau .gt. 0.68 .and. tau .le. 0.77 .and. &
&a .lt. 0.75*b) e = 1.15
if (tau .gt. 0.77 .and. tau .lt. 0.95 .and. &
&a .lt. 0.83*b) e = 1.10
c = (1.0 + e*tau)*tau*tanh(s)**2
if (x .ge. c*y) go to 200
!
!     Calculation in terms of the modified
!     Bessel function I
!
100 call cbki (z, nu, w)
return
!
!     Power series and Miller algorithm
!
200 call cbkm (z, rz, nu, w)
return
end subroutine cbesk

subroutine cbki (z, cnu, w)
implicit none
real :: a, b, pi, pihalf, u1, u2
real :: sin1
real :: cos1
!------------------------------------------------------------
!     Calculation of the modified Bessel function of the
!     second kind with complex order and argument in terms
!     of the modified Bessel function of the first kind.
!------------------------------------------------------------
complex, intent(in) :: z, cnu
complex, intent(inout) :: w
complex :: w1, w2
complex :: cdiv
!
data pi/3.14159265358979e+00/
data pihalf/1.5707963267949e+00/
!
call cbssli (z, -cnu, w1)
call cbssli (z, cnu, w2)
a = real(cnu)
b = pi*aimag(cnu)
u1 = sin1(a)*cosh(b)
u2 = cos1(a)*sinh(b)
w = pihalf*cdiv(w1 - w2, cmplx(u1,u2))
return
end subroutine cbki

subroutine cbka (z, cnu, w)
implicit none
integer :: i
real :: c, eps, u, v
real :: anorm
real :: spmpar
!-----------------------------------------------------------------------
!        Computation of the Bessel function K for complex order
!        cnu and complex argument z by the asymptotic expansion
!-----------------------------------------------------------------------
complex :: z
complex, intent(in) :: cnu
complex, intent(inout) :: w
real :: m
complex :: a, p, t, zr
!--------------------------
anorm(z) = amax1(abs(real(z)), abs(aimag(z)))
!--------------------------
!     c = pi**(1/2)
!--------------------------
data c /1.77245385090552e+00/
!--------------------------
!
!     ****** eps IS A MACHINE DEPENDENT CONSTANT. EPS IS THE
!            SMALLEST NUMBER SUCH THAT 1.0 + eps .GT. 1.0 .
!
                eps = spmpar(1)
!
!--------------------------
call crec (real(z), aimag(z), u, v)
zr = cmplx(0.5*u, 0.5*v)
a = cnu*cnu - 0.25
m = 1.0
t = a*zr
p = t
!
do i = 1, 16
   a = a - 2.0*m
   m = m + 1.0
   t = t*a*zr/m
   p = p + t
   if (anorm(t) .le. eps*anorm(p)) go to 20
end do
!
20 p = p + 1.0
t = csqrt(zr)
if (aimag(z) .eq. 0.0) t = conjg(t)
w = c*t*p*cexp(-z)
return
end subroutine cbka

subroutine cbkm (z, rz, cnu, w)
implicit none
real, intent(in) :: rz
integer :: i, ind, m, n, n1
real :: a, ai, b, c, cpi, pi, t, x, y, znorm, zr1, zr2
!-------------------------------------------------------------------
!     Calculation of the modified Bessel function of the second
!     kind with complex order and argument BY means of Maclaurin
!     expansions and the Miller algorithm. It is assumed that
!     rz = abs(z).
!-------------------------------------------------------------------
complex, intent(in) :: z, cnu
complex, intent(inout) :: w
real :: nu
complex :: cz, ex, r, r1, u1, u2, u3, w1, w2, zr
complex :: cxp
!---------------------------
!     cpi = sqrt(pi/2)
!---------------------------
data pi  /3.14159265358979/
data cpi /1.25331413731550/
!
!        REDUCTION OF cnu TO r = nu + b*i WHERE
!                -0.5 .LT. nu .LE. 0.5
!
r = cnu
if (real(r) .lt. 0.0) r = - r
!
a = real(r)
b = aimag(r)
n = a
nu = a - float(n)
t = nu - 0.5
if (t .le. 0.0) go to 10
   nu = t - 0.5
   n = n + 1
10 m = n
r1 = cmplx(nu, b)
!
ind = 1
cz = z
x = 0.5*real(z)
y = 0.5*aimag(z)
call crec (x, y, zr1, zr2)
zr = cmplx (zr1, zr2)
if (t .ne. 0.0) go to 20
if (b .ne. 0.0) go to 20
!
!               CALCULATION FOR nu = 0.5
!
w = cmplx(cpi, 0.0)
w1 = (1.0, 0.0)
if (n .eq. 0) go to 90
if (x .ge. 0.0) go to 15
   ind = -1
   cz = - z
   zr = - zr
15 u1 = w
u2 = w
n = n + 1
r1 = (-0.5, 0.0)
go to 70
!
!           CALCULATION FOR abs(nu) .LT. 0.5
!
20 znorm = 0.5*rz
if (znorm .gt. 1.0) go to 30
   ind = 0
   call ckps (z, znorm, zr, r1, u1, u2)
   go to 50
30 u1 = (1.0, 0.0)
if (x .lt. 0.0) go to 40
   call cbkml (z, znorm, zr, r1, n, w1, u2)
   go to 50
40 ind = -1
cz = - z
zr = - zr
call cbkml (cz, znorm, zr, r1, n, w1, u2)
!
50 if (n .gt. 1) go to 70
w = u1
if (n .ne. 0) w = u2
go to 90
!
!                 Recursion
!
70 n1 = n - 1
do i = 1, n1
   ai = i
   u3 = (r1 + ai)*zr*u2 + u1
   u1 = u2
   u2 = u3
end do
w = u3
!
90 if (ind .eq. 0) return
w = w*w1*cexp(-cz)/csqrt(cz)
if (ind .gt. 0) return
!
!            Analytic continuation
!
c = exp(0.5*b*pi)
ex = cxp(m, nu)
if (y .lt. 0.0) go to 100
   ex = c*ex
   w1 = cmplx (aimag(z), -real(z))
   call cbsslj (w1, r, w2)
   w2 = cmplx (pi*aimag(w2), -pi*real(w2))
   w = ex*(ex*w + w2)
   return
100 ex = conjg(ex)/c
w1 = cmplx (-aimag(z), real(z))
call cbsslj (w1, r, w2)
w2 = cmplx (-pi*aimag(w2), pi*real(w2))
w = ex*(ex*w + w2)
return
end subroutine cbkm

subroutine ckps (z, r, zr, nu, w1, w2)
implicit none
real, intent(in) :: r
integer :: k
real :: ak, eps, eps0, phi, pi, s, tol, u, x, y
real :: anorm
real :: spmpar
!-----------------------------------------------------------------------
!
!        Calculation of the modified Bessel functions
!
!                  w1 = k  (z)  AND  w2 = k    (z)
!                        nu                nu+1
!
!     FOR A COMPLEX ARGUMENT z WHERE abs(z) .LE. 2 AND A COMPLEX
!     ORDER nu WHERE abs(real(nu)) .LE. 0.5.  IT IS ASSUMED THAT
!     -pi .LT. ARG z .LE. pi, r = abs(z/2), AND zr = 2/z.  POWER
!     series expansions are used.
!
!-----------------------------------------------------------------------
complex, intent(in) :: z, zr
complex :: nu
complex, intent(inout) :: w1, w2
real :: d(7)
complex :: a, c, ch, cl, f, g1, g2, gm1, gm2, mu, p, q, sh, t, t1, &
&t2
complex :: cdiv, cgam0
!-----------------------
data tol /1.e-10/
data pi /3.14159265358979/
!-----------------------
data d(1) / .577215664901533e+00/,  d(2) /-.420026350340952e-01/, &
&d(3) /-.421977345555443e-01/,  d(4) / .721894324666310e-02/, &
&d(5) /-.215241674114951e-03/,  d(6) /-.201348547807882e-04/, &
&d(7) / .113302723198170e-05/
!-----------------------
anorm(t) = amax1(abs(real(t)), abs(aimag(t)))
!-----------------------------------------------------------------------
!
!     ****** eps IS A MACHINE DEPENDENT CONSTANT.  EPS IS THE
!            SMALLEST NUMBER SUCH THAT 1 + eps .GT. 1.
!
                eps = spmpar(1)
!
!-----------------------------------------------------------------------
eps0 = amax1(eps, 5.e-15)
!
!                     cl = - ln(z/2)
!
phi = atan2(aimag(z),real(z))
cl = cmplx(-alog(r), -phi)
mu = nu*cl
c = cexp(mu)
!
!                   g1 = gamma(1 + nu)
!                   g2 = gamma(1 - nu)
!
t = pi*nu
if (anorm(nu) .gt. tol) go to 10
   a = 1.0 + (t*t)/6.0
   go to 20
10 a = t/csin(t)
!
20 s = real(nu)**2 + aimag(nu)**2
if (s .ge. 1.0) go to 21
   t = cgam0(nu)
   g1 = 1.0/t
   g2 = a*t
   go to 30
21 t = 0.5 + (0.5 + nu)
call cgamma (0, t, g1)
g2 = cdiv(a,g1)
!
30 gm2 = 0.5*(g1 + g2)
if (s .gt. 0.04) go to 31
!
!         The following is the Taylor series for
!     w1 = (1/g2 - 1/g1)/(2*nu). NOTE THAT g1*g2 = a.
!
   t = nu*nu
   w1 = -((((((d(7)*t + d(6))*t + d(5))*t + d(4))*t + &
&d(3))*t + d(2))*t + d(1))
   gm1 = a*w1
   go to 40
31 gm1 = 0.5*(g1 - g2)/nu
!
!            Initialization of the summation
!
40 p = 0.5*c*g1
q = 0.5*cdiv(g2,c)
x = real(mu)
y = aimag(mu)
if (anorm(mu) .gt. tol) go to 50
   u = x*y
   sh = cmplx(1.0, u/3.0)
   ch = cmplx(1.0, u)
   go to 60
50 t = cmplx (-y, x)
sh = csin(t)/t
ch = ccos(t)
!
60 f = gm1*ch + gm2*cl*sh
c = (1.0, 0.0)
w1 = f
w2 = p
!
!                 Summation of series
!
t = 0.25*(z*z)
do k = 1, 50
   ak = k
   f = (ak*f + p + q)/((ak - nu)*(ak + nu))
   p = p/(ak - nu)
   q = q/(ak + nu)
   c = c*t/ak
   t1 = c*f
   w1 = w1 + t1
   t2 = c*(p - ak*f)
   w2 = w2 + t2
   if (anorm(t1) .le. eps0*anorm(w1)) go to 80
end do
!
80 w2 = w2 * zr
return
end subroutine ckps

subroutine cbkml (z, r, zr, nu, n, w, w0)
implicit none
integer, intent(in) :: n
real, intent(in) :: r
integer :: i, m, num
real :: a, b, c, c1, c2, e, eps, eps0, f, rnu, t, th, x, y
real :: cos1
real :: spmpar
!-----------------------------------------------------------------------
!
!             Computation of the scaled Bessel function
!
!                   w = (exp(z)*sqrt(z)) k  (z)
!                                         nu
!     and the value
!
!                   w0 = k    (z) /k  (z)
!                         nu+1      nu
!
!     For complex orders nu and nu + 1 and for complex argument z
!     by use of the Miller algorithm. For the greatest accuracy,
!     z should lie in a sector slightly larger than the right half
!     PLANE. IT IS ASSUMED THAT abs(real(nu)) .LT. 0.5, AND THAT
!     r = abs(z/2) AND zr = 2/z.
!
!-----------------------------------------------------------------------
complex, intent(in) :: z, zr, nu
complex, intent(inout) :: w, w0
complex :: al, bl, s, u1, u2, u3
real :: inu, l
!---------------------
!     c1 = sqrt(pi/2)
!     c2 = sqrt(pi)
!---------------------
data c1 /1.25331413731559e+00/
data c2 /1.77245385090552e+00/
!-----------------------------------------------------------------------
!
!     ****** eps IS A MACHINE DEPENDENT CONSTANT.  EPS IS THE
!            SMALLEST NUMBER SUCH THAT 1 + eps .GT. 1.
!
                eps = spmpar(1)
!
!-----------------------------------------------------------------------
eps0 = amax1(eps, 5.e-15)
!
x = real(z)
y = aimag(z)
rnu = real(nu)
inu = aimag(nu)
!
!     Calculation of m for use in Miller algorithm.
!
th = atan2(y,x)
a = 3.0/(1.0 + r)
b = 14.7/(28.0 + r)
f = (2.0*r)**(0.25)
if (rnu .eq. 0.5 .and. inu .ne. 0.0) go to 10
   c = 4.0*cos1(rnu)/(c1*eps0*f)
   go to 20
10 c = 4.0*c2/f
20 m = (0.485/r)*(alog(c) + r*cos(a*th)/(1.0 + 0.008*r))**2/ &
&(2.0*cos(b*th))**2 + 1.5
t = 0.0
if (r .gt. 22.5) t = 0.01*(r - 22.5)**2
num = 35.0 + 0.8*(r - 22.5) + t
if (inu .ne. 0.0) m = m + num
c = n
if (c + rnu .lt. 0.327*abs(inu)) m = m + 10
!
!     Backward recurrence in Miller algorithm.
!
a = (0.5 - rnu)*(0.5 + rnu) + inu*inu
e = 2.0*rnu*inu
u2 = (0.0, 0.0)
u1 = (1.0, 0.0)
s = u1
l = m
do 30 i = 2, m
   u3 = u2
   u2 = u1
   c = a/l + (l - 1.0)
   al = cmplx(c, - e/l)
   bl = 2.0*(l + z)
   u1 = (bl*u2 - (l + 1.0)*u3)/al
   s = s + u1
   c = abs(real(u1)) + abs(aimag(u1))
   if (i .eq. m .or. c .lt. 1.e+8) go to 30
!
!           Rescale to avoid overflow
!
      u2 = u2/c
      u1 = u1/c
      s = s/c
!
30 l = l - 1.0
!
!     Last step in the Miller algorithm.
!
if (c .lt. 2.0) go to 40
   u2 = u2/c
   u1 = u1/c
   s = s/c
40 u3 = u2
u2 = u1
al = cmplx(0.5*a, - 0.5*e)
bl = 1.0 + z
u1 = (bl*u2 - u3)/al
s = s + u1
!
!     Final assembly
!
w = c1*(u1/s)
w0 = 1.0 + 0.5*(nu + 0.5 - u2/u1)*zr
return
end subroutine cbkml

subroutine cbsslk (z, r, w)
implicit none
real, intent(in) :: r
integer :: i, ind, m, n, n1
real :: a, ai, cpi, pi, rz, t, x, y, znorm, zr1, zr2
real :: cpabs
!-----------------------------------------------------------------------
!
!         Calculation of the modified Bessel function of the
!         second kind for real order r and complex argument z.
!         IT IS ASSUMED THAT -pi .LT. ARG z .LE. pi.
!
!-----------------------------------------------------------------------
!     Written by
!         Andrew H. van Tuyl
!         Naval Surface Warfare Center
!     modified by A.H. Morris (NSWC)
!     revised ... oct 1992
!---------------------------
complex :: z
complex, intent(inout) :: w
complex :: cn, cz, ex, u1, u2, u3, w1, w2, zr
real :: nu, nu1
complex :: cxp
!---------------------------
!     cpi = sqrt(pi/2)
!---------------------------
data pi  /3.14159265358979/
data cpi /1.25331413731550/
!
rz = cpabs(real(z), aimag(z))
!
!     Asymptotic expansion
!
if (rz .lt. 17.5 + 0.5*r*r) go to 5
   call cka (z, r, w)
   return
!
!          REDUCTION OF r TO THE RANGE -0.5 .LT. nu .LE. 0.5
!
5 a = abs(r)
n = a
nu = a - float(n)
t = nu - 0.5
if (t .le. 0.0) go to 10
   nu = t - 0.5
   n = n + 1
10 m = n
nu1 = nu
!
ind = 1
cz = z
x = 0.5*real(z)
y = 0.5*aimag(z)
call crec (x, y, zr1, zr2)
zr = cmplx (zr1, zr2)
if (t .ne. 0.0) go to 20
!
!               CALCULATION FOR nu = 0.5
!
w = cmplx(cpi, 0.0)
if (n .eq. 0) go to 90
if (x .ge. 0.0) go to 15
   ind = -1
   cz = - z
   zr = - zr
15 u1 = w
u2 = w
n = n + 1
nu = - 0.5
go to 70
!
!           CALCULATION FOR abs(nu) .LT. 0.5
!
20 znorm = 0.5*rz
if (znorm .gt. 1.0) go to 30
   ind = 0
   call ckm (z, znorm, zr, nu, u1, u2)
   go to 50
30 if (x .lt. 0.0) go to 40
   call ckml (z, znorm, zr, nu, u1, u2)
   go to 50
40 ind = -1
cz = - z
zr = - zr
call ckml (cz, znorm, zr, nu, u1, u2)
!
50 if (n .gt. 1) go to 70
w = u1
if (n .ne. 0) w = u2
go to 90
!
!                 Recursion
!
70 n1 = n - 1
do i = 1, n1
   ai = i
   u3 = (nu + ai)*zr*u2 + u1
   u1 = u2
   u2 = u3
end do
w = u3
!
90 if (ind .eq. 0) return
w = w*cexp(-cz)/csqrt(cz)
if (ind .gt. 0) return
!
!            Analytic continuation
!
ex = cxp(m, nu1)
cn = cmplx (a, 0.0)
if (y .lt. 0.0) go to 100
   w1 = cmplx (aimag(z), -real(z))
   call cbsslj (w1, cn, w2)
   w2 = cmplx (pi*aimag(w2), -pi*real(w2))
   w = ex*(ex*w + w2)
   return
100 ex = conjg(ex)
w1 = cmplx (-aimag(z), real(z))
call cbsslj (w1, cn, w2)
w2 = cmplx (-pi*aimag(w2), pi*real(w2))
w = ex*(ex*w + w2)
return
end subroutine cbsslk

subroutine cka (z, nu, w)
implicit none
integer :: i
real :: a, c, eps, u, v
real :: anorm
real :: spmpar
!-----------------------------------------------------------------------
!        Computation of the Bessel function K for real order nu
!        and complex argument z by the asymptotic expansion
!-----------------------------------------------------------------------
complex :: z
complex, intent(inout) :: w
real :: m
real, intent(in) :: nu
complex :: p, t, zr
!--------------------------
anorm(z) = amax1(abs(real(z)), abs(aimag(z)))
!--------------------------
!     c = pi**(1/2)
!--------------------------
data c /1.77245385090552/
!--------------------------
!
!     ****** eps IS A MACHINE DEPENDENT CONSTANT. EPS IS THE
!            SMALLEST NUMBER SUCH THAT 1.0 + eps .GT. 1.0 .
!
                eps = spmpar(1)
!
!--------------------------
call crec (real(z), aimag(z), u, v)
zr = cmplx(0.5*u, 0.5*v)
a = nu*nu - 0.25
m = 1.0
t = a*zr
p = t
!
do i = 1, 16
   a = a - 2.0*m
   m = m + 1.0
   t = (a/m)*t*zr
   p = p + t
   if (anorm(t) .le. eps*anorm(p)) go to 20
end do
!
20 p = p + 1.0
t = csqrt(zr)
if (aimag(z) .eq. 0.0) t = conjg(t)
w = c*t*p*cexp(-z)
return
end subroutine cka

subroutine ckm (z, r, zr, nu, w1, w2)
implicit none
real, intent(in) :: r
integer :: k
real :: a, ak, eps, eps0, g1, g2, gm1, gm2, phi, pi, t, tol, x, y
real :: anorm
real :: spmpar
real :: gam1
!-----------------------------------------------------------------------
!
!        Calculation of the modified Bessel functions
!
!                  w1 = k  (z)  AND  w2 = k    (z)
!                        nu                nu+1
!
!     FOR A COMPLEX ARGUMENT z WHERE abs(z) .LE. 2  AND A REAL
!     ORDER nu WHERE abs(nu) .LE. 0.5.  IT IS ASSUMED THAT
!     -pi .LT. ARG z .LE. pi, r = abs(z/2), AND zr = 2/z. POWER
!     series expansions are used.
!
!-----------------------------------------------------------------------
complex, intent(in) :: z, zr
complex, intent(inout) :: w1, w2
real, intent(in) :: nu
real :: d(7)
complex :: c, ch, cl, f, mu, p, q, sh, t1, t2, w
!-----------------------
data tol /1.e-10/
data pi /3.14159265358979/
!-----------------------
data d(1) / .577215664901533e+00/,  d(2) /-.420026350340952e-01/, &
&d(3) /-.421977345555443e-01/,  d(4) / .721894324666310e-02/, &
&d(5) /-.215241674114951e-03/,  d(6) /-.201348547807882e-04/, &
&d(7) / .113302723198170e-05/
!-----------------------
anorm(w) = amax1(abs(real(w)), abs(aimag(w)))
!-----------------------------------------------------------------------
!
!     ****** eps IS A MACHINE DEPENDENT CONSTANT.  EPS IS THE
!            SMALLEST NUMBER SUCH THAT 1 + eps .GT. 1.
!
                eps = spmpar(1)
!
!-----------------------------------------------------------------------
eps0 = amax1(eps, 5.e-15)
!
!                     cl = - ln(z/2)
!
phi = atan2(aimag(z),real(z))
cl = cmplx(-alog(r), -phi)
mu = nu*cl
c = cexp(mu)
!
!                   g1 = gamma(1 + nu)
!                   g2 = gamma(1 - nu)
!
t = pi*nu
if (abs(nu) .gt. tol) go to 10
   a = 1.0 + (t*t)/6.0
   go to 20
10 a = t/sin(t)
!
20 t = 0.5 + (0.5 + gam1(nu))
g1 = 1.0/t
g2 = a*t
gm2 = 0.5*(g1 + g2)
if (abs(nu) .gt. 0.2) go to 30
!
!         The following is the Taylor series for
!     t = (1/g2 - 1/g1)/(2*nu). NOTE THAT g1*g2 = a.
!
   t = nu*nu
   t = -((((((d(7)*t + d(6))*t + d(5))*t + d(4))*t + &
&d(3))*t + d(2))*t + d(1))
   gm1 = a*t
   go to 40
30 gm1 = 0.5*(g1 - g2)/nu
!
!            Initialization of the summation
!
40 p = (0.5*g1)*c
q = (0.5*g2)/c
x = real(mu)
y = aimag(mu)
if (anorm(mu) .gt. tol) go to 50
   t = x*y
   sh = cmplx(1.0, t/3.0)
   ch = cmplx(1.0, t)
   go to 60
50 w = cmplx (-y, x)
sh = csin(w)/w
ch = ccos(w)
!
60 f = gm1*ch + gm2*cl*sh
c = (1.0, 0.0)
w1 = f
w2 = p
!
!                 Summation of series
!
w = 0.25*(z*z)
do k = 1, 50
   ak = k
   f = (ak*f + p + q)/((ak - nu)*(ak + nu))
   p = p/(ak - nu)
   q = q/(ak + nu)
   c = c*w/ak
   t1 = c*f
   w1 = w1 + t1
   t2 = c*(p - ak*f)
   w2 = w2 + t2
   if (anorm(t1) .le. eps0*anorm(w1)) go to 80
end do
!
80 w2 = w2 * zr
return
end subroutine ckm

subroutine ckml (z, r, zr, nu, k1, k2)
implicit none
real, intent(in) :: r
integer :: i, m
real :: a, al, b, c, c1, e, eps, eps0, th, x, y
real :: cos1
real :: spmpar
!-----------------------------------------------------------------------
!
!             Computation of the scaled Bessel functions
!
!                   k1 = (exp(z)*sqrt(z)) k  (z)
!                                          nu
!                   k2 = (exp(z)*sqrt(z)) k    (z)
!                                          nu+1
!
!     For real orders nu and nu + 1 and for complex argument z
!     by use of the Miller algorithm. For the greatest accuracy,
!     z should lie in a sector slightly larger than the right
!     HALF PLANE. IT IS ASSUMED THAT abs(nu) .LT. 0.5, AND THAT
!     r = abs(z/2) AND zr = 2/z.
!
!-----------------------------------------------------------------------
complex, intent(in) :: z, zr
complex, intent(inout) :: k1, k2
complex :: bl, s, u1, u2, u3
real :: l
real, intent(in) :: nu
real :: nu2
!---------------------
!     c1 = sqrt(pi/2)
!---------------------
data c1/1.25331413731559/
!-----------------------------------------------------------------------
!
!     ****** eps IS A MACHINE DEPENDENT CONSTANT.  EPS IS THE
!            SMALLEST NUMBER SUCH THAT 1 + eps .GT. 1.
!
                eps = spmpar(1)
!
!-----------------------------------------------------------------------
eps0 = amax1(eps, 5.e-15)
x = real(z)
y = aimag(z)
nu2 = nu*nu
!
!     Calculation of m for use in Miller algorithm.
!
th = atan2(y,x)
a = 3.0/(1.0 + r)
b = 14.7/(28.0 + r)
c = 4.0*cos1(nu)/(c1*eps0*(2.0*r)**(0.25))
m = (0.485/r)*(alog(c) + r*cos(a*th)/(1.0 + 0.008*r))**2/ &
&(2.0*cos(b*th))**2 + 1.5
!
!     Backward recurrence in Miller algorithm.
!
u2 = (0.0, 0.0)
u1 = (1.0, 0.0)
s = u1
l = m
do 10 i = 2, m
   u3 = u2
   u2 = u1
   e = l - 0.5
   al = (e*e - nu2)/(l*(l + 1.0))
   bl = (2.0/(l + 1.0))*(l + z)
   u1 = (bl*u2 - u3)/al
   s = s + u1
   c = abs(real(u1)) + abs(aimag(u1))
   if (i .eq. m .or. c .lt. 1.e+6) go to 10
!
!           Rescale to avoid overflow
!
      u2 = u2/c
      u1 = u1/c
      s = s/c
!
10 l = l - 1.0
!
!     Last step in the Miller algorithm.
!
if (c .lt. 2.0) go to 20
   u2 = u2/c
   u1 = u1/c
   s = s/c
20 u3 = u2
u2 = u1
al = 0.5*(0.5 - nu)*(0.5 + nu)
bl = 1.0 + z
u1 = (bl*u2 - u3)/al
s = s + u1
!
!     Final assembly
!
k1 = c1*(u1/s)
k2 = k1*(1.0 + 0.5*(nu + 0.5 - u2/u1)*zr)
return
end subroutine ckml

complex function cxp (n, nu)
implicit none
integer, intent(in) :: n
integer :: k
real :: c, s
real :: sin0
real :: cos0
!-----------------------------------------------------------------------
!                 Computation of exp(-R*(PI/2)*I)
!              WHERE R = n + nu FOR abs(nu) .LE. 0.5
!-----------------------------------------------------------------------
real, intent(in) :: nu
!
c = cos0(nu)
s = sin0(nu)
k = mod(n,4)
if (k .eq. 0) go to 10
if (k .eq. 1) go to 20
if (k .eq. 2) go to 30
go to 40
!
10 cxp = cmplx (c, -s)
return
!
20 cxp = cmplx (-s, -c)
return
!
30 cxp = cmplx (-c, s)
return
!
40 cxp = cmplx (s, c)
return
end function cxp

subroutine bsslk (mo, a, in, w)
implicit none
integer, intent(in) :: in, mo
integer :: i, la, lk, lr, m, n
real :: an, aq(2), az(2), cd(30), ce(30), pm, pn, qf(2), qm, qn, &
&rm, rn, rz(2), sl(2), sm(2), sn, sq(2), sr(2), ss, sz(2), tm(2), &
&ts(2), zl(2), zs
!     ******************************************************************
!     Fortran subroutine for modified Bessel function of integral order
!     ******************************************************************
!     mo = MODE OF OPERATION
!     a  = ARGUMENT (COMPLEX NUMBER)
!     in = order (integer)
!     w  = FUNCTION OF SECOND KIND (COMPLEX NUMBER)
!     -------------------
complex, intent(in) :: a
complex, intent(inout) :: w
data cd(1) / 0.00000000000000e00/,  cd(2) /-1.64899505142212e-2/, &
&cd(3) /-7.18621880068536e-2/,  cd(4) /-1.67086878124866e-1/, &
&cd(5) /-3.02582250219469e-1/,  cd(6) /-4.80613945245927e-1/, &
&cd(7) /-7.07075239357898e-1/,  cd(8) /-9.92995790539516e-1/, &
&cd(9) /-1.35583925612592e00/,  cd(10)/-1.82105907899132e00/, &
&cd(11)/-2.42482175310879e00/,  cd(12)/-3.21956655708750e00/, &
&cd(13)/-4.28658077248384e00/,  cd(14)/-5.77022816798128e00/, &
&cd(15)/-8.01371260952526e00/
data cd(16)/ 0.00000000000000e00/,  cd(17)/-5.57742429879505e-3/, &
&cd(18)/-4.99112944172476e-2/,  cd(19)/-1.37440911652397e-1/, &
&cd(20)/-2.67233784710566e-1/,  cd(21)/-4.40380166808682e-1/, &
&cd(22)/-6.61813614872541e-1/,  cd(23)/-9.41861077665017e-1/, &
&cd(24)/-1.29754130468326e00/,  cd(25)/-1.75407696719816e00/, &
&cd(26)/-2.34755299882276e00/,  cd(27)/-3.13041332689196e00/, &
&cd(28)/-4.18397120563729e00/,  cd(29)/-5.65251799214994e00/, &
&cd(30)/-7.87863959810677e00/
data ce(1) / 0.00000000000000e00/,  ce(2) /-4.80942336387447e-3/, &
&ce(3) /-1.31366200347759e-2/,  ce(4) /-1.94843834008458e-2/, &
&ce(5) /-2.19948900032003e-2/,  ce(6) /-2.09396625676519e-2/, &
&ce(7) /-1.74600268458650e-2/,  ce(8) /-1.27937813362085e-2/, &
&ce(9) /-8.05234421796592e-3/,  ce(10)/-4.15817375002760e-3/, &
&ce(11)/-1.64317738747922e-3/,  ce(12)/-4.49175585314709e-4/, &
&ce(13)/-7.28594765574007e-5/,  ce(14)/-5.38265230658285e-6/, &
&ce(15)/-9.93779048036289e-8/
data ce(16)/ 0.00000000000000e00/,  ce(17)/ 7.53805779200591e-2/, &
&ce(18)/ 7.12293537403464e-2/,  ce(19)/ 6.33116224228200e-2/, &
&ce(20)/ 5.28240264523301e-2/,  ce(21)/ 4.13305359441492e-2/, &
&ce(22)/ 3.01350573947510e-2/,  ce(23)/ 2.01043439592720e-2/, &
&ce(24)/ 1.18552223068074e-2/,  ce(25)/ 5.86055510956010e-3/, &
&ce(26)/ 2.25465148267325e-3/,  ce(27)/ 6.08173041536336e-4/, &
&ce(28)/ 9.84215550625747e-5/,  ce(29)/ 7.32139093038089e-6/, &
&ce(30)/ 1.37279667384666e-7/
!     -------------------
az(1)=real(a)
az(2)=aimag(a)
zs=az(1)*az(1)+az(2)*az(2)
zl(1)=0.5*alog(zs)
zl(2)=atan2(az(2),az(1))
an=iabs(in)
tm(1)=0.0
tm(2)=0.0
if(mo.ne.0)go to 002
tm(1)=az(1)
tm(2)=az(2)
002 if(zs-1.0)020,020,003
003 if(zs-289.0)004,010,010
004 if(az(1)+0.096*az(2)*az(2))020,020,015
010 qm=1.25331413731550*exp(-0.5*zl(1)-tm(1))
qf(1)=qm*cos(-0.5*zl(2)-tm(2))
qf(2)=qm*sin(-0.5*zl(2)-tm(2))
if(an.gt.1.0)go to 012
pn=an
assign 011 to la
go to 100
011 ts(1)=qf(1)*sm(1)-qf(2)*sm(2)
ts(2)=qf(1)*sm(2)+qf(2)*sm(1)
sm(1)=ts(1)
sm(2)=ts(2)
go to 029
012 pn=1.0
assign 013 to la
go to 100
013 sq(1)=qf(1)*sm(1)-qf(2)*sm(2)
sq(2)=qf(1)*sm(2)+qf(2)*sm(1)
pn=0.0
assign 014 to la
go to 100
014 sr(1)=qf(1)*sm(1)-qf(2)*sm(2)
sr(2)=qf(1)*sm(2)+qf(2)*sm(1)
go to 026
015 qm=1.25331413731550*exp(-0.5*zl(1)-tm(1))
qf(1)=qm*cos(-0.5*zl(2)-tm(2))
qf(2)=qm*sin(-0.5*zl(2)-tm(2))
if(an.gt.1.0)go to 017
pn=an
assign 016 to lr
go to 104
016 ts(1)=qf(1)*sm(1)-qf(2)*sm(2)
ts(2)=qf(1)*sm(2)+qf(2)*sm(1)
sm(1)=ts(1)
sm(2)=ts(2)
go to 029
017 pn=1.0
assign 018 to lr
go to 104
018 sq(1)=qf(1)*sm(1)-qf(2)*sm(2)
sq(2)=qf(1)*sm(2)+qf(2)*sm(1)
pn=0.0
assign 019 to lr
go to 104
019 sr(1)=qf(1)*sm(1)-qf(2)*sm(2)
sr(2)=qf(1)*sm(2)+qf(2)*sm(1)
go to 026
020 qf(1)=1.0
qf(2)=0.0
if(mo.eq.0)go to 021
qm=exp(az(1))
qf(1)=qm*cos(az(2))
qf(2)=qm*sin(az(2))
021 if(an.gt.1.0)go to 023
pn=an
assign 022 to lk
go to 106
022 ts(1)=qf(1)*sm(1)-qf(2)*sm(2)
ts(2)=qf(1)*sm(2)+qf(2)*sm(1)
sm(1)=ts(1)
sm(2)=ts(2)
go to 029
023 pn=1.0
assign 024 to lk
go to 106
024 sq(1)=qf(1)*sm(1)-qf(2)*sm(2)
sq(2)=qf(1)*sm(2)+qf(2)*sm(1)
pn=0.0
assign 025 to lk
go to 106
025 sr(1)=qf(1)*sm(1)-qf(2)*sm(2)
sr(2)=qf(1)*sm(2)+qf(2)*sm(1)
026 rz(1)=+az(1)/zs
rz(2)=-az(2)/zs
pn=0.0
go to 028
027 sq(1)=sr(1)
sq(2)=sr(2)
sr(1)=sm(1)
sr(2)=sm(2)
028 sm(1)=2.0*pn*(rz(1)*sr(1)-rz(2)*sr(2))+sq(1)
sm(2)=2.0*pn*(rz(1)*sr(2)+rz(2)*sr(1))+sq(2)
pn=pn+1.0
if(pn.lt.an)go to 027
029 w=cmplx(sm(1),sm(2))
return
100 sm(1)=0.0
sm(2)=0.0
rz(1)=+0.5*az(1)/zs
rz(2)=-0.5*az(2)/zs
qn=(pn-0.5)*(pn+0.5)
tm(1)=1.0
tm(2)=0.0
pm=0.0
go to 102
101 qn=qn-2.0*pm
pm=pm+1.0
ts(1)=rz(1)*tm(1)-rz(2)*tm(2)
ts(2)=rz(1)*tm(2)+rz(2)*tm(1)
tm(1)=qn*ts(1)/pm
tm(2)=qn*ts(2)/pm
if(abs(sm(1))+abs(tm(1)).ne.abs(sm(1)))go to 102
if(abs(sm(2))+abs(tm(2)).eq.abs(sm(2)))go to 103
102 sm(1)=sm(1)+tm(1)
sm(2)=sm(2)+tm(2)
if(pm.lt.36.0)go to 101
103 go to la,(011,013,014)
104 sm(1)=1.0
sm(2)=0.0
m=15.0*pn+2.0
n=15.0*pn+15.0
do 105 i = m,n
ts(1)=az(1)-cd(i)
ts(2)=az(2)
ss=ts(1)*ts(1)+ts(2)*ts(2)
tm(1)=+ce(i)*ts(1)/ss
tm(2)=-ce(i)*ts(2)/ss
sm(1)=sm(1)+tm(1)
sm(2)=sm(2)+tm(2)
105 continue
go to lr,(016,018,019)
106 aq(1)=1.0
aq(2)=0.0
rn=0.0
sn=-1.0
pm=0.0
go to 108
107 pm=pm+1.0
rn=rn+0.5/pm
sn=-sn
ts(1)=0.5*(az(1)*aq(1)-az(2)*aq(2))
ts(2)=0.5*(az(1)*aq(2)+az(2)*aq(1))
aq(1)=ts(1)/pm
aq(2)=ts(2)/pm
108 if(pm.lt.pn)go to 107
sz(1)=0.25*(az(1)-az(2))*(az(1)+az(2))
sz(2)=0.5*az(1)*az(2)
sr(1)=0.0
sr(2)=0.0
ss=aq(1)*aq(1)+aq(2)*aq(2)
tm(1)=+aq(1)/ss
tm(2)=-aq(2)/ss
pm=0.0
go to 110
109 tm(1)=tm(1)/(pn-pm)
tm(2)=tm(2)/(pn-pm)
sr(1)=sr(1)+0.5*tm(1)
sr(2)=sr(2)+0.5*tm(2)
pm=pm+1.0
ts(1)=sz(1)*tm(1)-sz(2)*tm(2)
ts(2)=sz(1)*tm(2)+sz(2)*tm(1)
tm(1)=-ts(1)/pm
tm(2)=-ts(2)/pm
110 if(pm.lt.pn)go to 109
sm(1)=0.0
sm(2)=0.0
rm=1.0
qm=0.0
aq(1)=sn*aq(1)
aq(2)=sn*aq(2)
sl(1)=-0.115931515658412+zl(1)-rn
sl(2)=+zl(2)
pm=0.0
go to 112
111 qm=qm+rm
pm=pm+1.0
rm=0.25*zs*rm/(pm*(pn+pm))
ts(1)=sz(1)*aq(1)-sz(2)*aq(2)
ts(2)=sz(1)*aq(2)+sz(2)*aq(1)
aq(1)=ts(1)/(pm*(pn+pm))
aq(2)=ts(2)/(pm*(pn+pm))
sl(1)=sl(1)-0.5/pm-0.5/(pn+pm)
112 tm(1)=aq(1)*sl(1)-aq(2)*sl(2)
tm(2)=aq(1)*sl(2)+aq(2)*sl(1)
sm(1)=sm(1)+tm(1)
sm(2)=sm(2)+tm(2)
if(qm+rm.gt.qm)go to 111
sm(1)=sr(1)+sm(1)
sm(2)=sr(2)+sm(2)
go to lk,(022,024,025)
end subroutine bsslk

subroutine cai(ind,z,ai,aip,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ind
real :: a, b, r
real :: cpabs
!------------------------------------------------------------
!     Calculates the Airy function ai and its derivative aip
!     for complex argument z.
!------------------------------------------------------------
complex, intent(in) :: z
complex, intent(inout) :: ai
complex :: bi
complex, intent(inout) :: aip
complex :: bip
ierr = 0
a = real(z)
b = aimag(z)
r = cpabs(a,b)
if(r .gt. 1.0) go to 10
!
!     Maclaurin expansion
!
   call airm(ind,z,ai,aip,bi,bip)
   return
10 if(r .gt. 10.0) go to 20
!
!     Intermediate range calculation
!
   call aii(ind,z,ai,aip,ierr)
   return
!
!     Asymptotic expansion
!
20 call aia(ind,z,ai,aip,ierr)
return
end subroutine cai

subroutine airm (ind,z,ai,aip,bi,bip)
implicit none
integer, intent(in) :: ind
integer :: i, n
real :: c1, c2, sqt3, x, y
!--------------------------------------------------------------
!     Calculates the Airy functions ai and bi and their
!     derivatives aip and bip by use of their Maclaurin
!     expansions.
!--------------------------------------------------------------
complex, intent(inout) :: ai, aip, bi, bip
complex, intent(in) :: z
complex :: z1, z2, z3, zz, f, f1, g, g1, e, e1
real :: a(8), b(8), c(8), d(8)
!-----------------------
!     c1 = 3**(-2/3)/gamma(2/3)
!     c2 = 3**(-1/3)/gamma(1/3)
!-----------------------
data c1/3.55028053887817e-01/, c2/2.58819403792807e-01/, &
&sqt3/1.73205080756888e+00/
!-----------------------
data a(1) /.166666666666667e+00/, a(2) /.555555555555556e-02/, &
&a(3) /.771604938271605e-04/, a(4) /.584549195660307e-06/, &
&a(5) /.278356759838241e-08/, a(6) /.909662613850462e-11/, &
&a(7) /.216586336631062e-13/, a(8) /.392366551867867e-16/
data b(1) /.833333333333333e-01/, b(2) /.198412698412698e-02/, &
&b(3) /.220458553791887e-04/, b(4) /.141319585764030e-06/, &
&b(5) /.588831607350126e-09/, b(6) /.172172984605300e-11/, &
&b(7) /.372668797846970e-14/, b(8) /.621114663078283e-17/
data c(1) /.333333333333333e-01/, c(2) /.694444444444444e-03/, &
&c(3) /.701459034792368e-05/, c(4) /.417535139757362e-07/, &
&c(5) /.163739270493083e-09/, c(6) /.454831306925231e-12/, &
&c(7) /.941679724482880e-15/, c(8) /.150910212256872e-17/
data d(1) /.333333333333333e+00/, d(2) /.138888888888889e-01/, &
&d(3) /.220458553791887e-03/, d(4) /.183715461493239e-05/, &
&d(5) /.942130571760201e-08/, d(6) /.327128670750070e-10/, &
&d(7) /.819871355263333e-13/, d(8) /.155278665769571e-15/
!-----------------------
z2 = z*z
z3 = z*z2
!
!     Summation of f and g
!
f = cmplx(a(8),0.0)
g = cmplx(b(8),0.0)
do 10 n = 1, 7
   i = 8 - n
   f = a(i) + z3*f
   g = b(i) + z3*g
10 continue
f = 1.0 + z3*f
g = z + z2*z2*g
!
!     Summation of f1 and g1
!
f1 = cmplx(c(8),0.0)
g1 = cmplx(d(8),0.0)
do n = 1,7
   i = 8 - n
   f1 = c(i) + z3*f1
   g1 = d(i) + z3*g1
end do
f1 = z2*(0.5 + z3*f1)
g1 = 1.0 + z3*g1
!
!     Final assembly
!
ai = c1*f - c2*g
bi = sqt3*(c1*f + c2*g)
aip = c1*f1 - c2*g1
bip = sqt3*(c1*f1 + c2*g1)
if (ind .eq. 0) return
   x = real(z)
   y = aimag(z)
   z1 = csqrt(z)
   zz = z*z1/1.5
   e = cexp(zz)
   e1 = 1.0/e
   ai = ai*e
   aip = aip*e
   if (abs(y) .gt. x*sqt3) go to 30
      bi = bi*e1
      bip = bip*e1
      return
30 bi = bi*e
   bip = bip*e
return
end subroutine airm

subroutine aii(ind, z, ai, aip, ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ind
real :: a, b, c1, r
real :: cpabs
!------------------------------------------------------------
!     Calculates the Airy function ai and its derivative aip
!     FOR COMPLEX ARGUMENT z IN THE INTERMEDIATE RANGE 1 .LE.
!     CABS(z) .LE. 10.0.
!------------------------------------------------------------
complex, intent(in) :: z
complex, intent(inout) :: ai, aip
complex :: z1, z2, z3, zm, w1, w2, w1m, w2m, e
!
!     c1 = 1/(pi*sqrt(3))
!
data c1/1.83776298473931e-01/
ierr = 0
a = real(z)
b = aimag(z)
r = cpabs(a, b)
z1 = csqrt(z)
z2 = z1*z/1.5
if (abs(b) .lt. -5.0*a) go to 10
!
!           ----  abs(b) .GE. -5.0*a  ----
!
   call ka(ind, z2, w1, w2)
   ai = c1*z1*w1
   aip = -c1*z*w2
   return
!
!           ----  abs(b) .LT. -5.0*a  ----
!
10 if (abs(b) .lt. -1.74*a) go to 30
   if (r .ge. 8.2) go to 40
20 zm = -z
   z1 = csqrt(zm)
   z3 = z1*zm/1.5
   call ja(z3, w1, w2, w1m, w2m)
   ai = (z1/3.0)*(w1m +w1)
   aip = (z/3.0)*(w2m - w2)
   if (ind .eq. 0) return
      e = cexp(z2)
      ai = ai*e
      aip = aip*e
      return
30 if (r .lt. 7.4) go to 20
40 call aia (ind,z,ai,aip,ierr)
return
end subroutine aii

subroutine aia (ind, z, ai, aip, ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ind
integer :: i, k, m, m2
real :: c1, c2, eps, r, t, u, u1, v, v1, xm, xneg, xpos
real :: exparg
real :: spmpar
!-----------------------------------------------------------------------
!     Calculates the Airy function ai and its derivative aip for
!     complex argument z by means of asymptotic expansions.
!-----------------------------------------------------------------------
complex, intent(inout) :: ai, aip
complex, intent(in) :: z
complex :: z1, z2, z2r, zz, w, w2, s1, s2, s3, s4, e, zeta, si, cn
complex :: alpha, beta, j
real :: c(30), d(30)
!------------------------
data c(1)  /.100000000000000e+01/, c(2)  /.694444444444444e-01/, &
&c(3)  /.371334876543210e-01/, c(4)  /.379930591278006e-01/, &
&c(5)  /.576491904126697e-01/, c(6)  /.116099064025515e+00/, &
&c(7)  /.291591399230751e+00/, c(8)  /.877666969510017e+00/, &
&c(9)  /.307945303017317e+01/, c(10) /.123415733323452e+02/, &
&c(11) /.556227853659171e+02/, c(12) /.278465080777603e+03/, &
&c(13) /.153316943201280e+04/, c(14) /.920720659972641e+04/, &
&c(15) /.598925135658791e+05/, c(16) /.419524875116551e+06/, &
&c(17) /.314825741786683e+07/, c(18) /.251989198716024e+08/, &
&c(19) /.214288036963680e+09/, c(20) /.192937554918249e+10/
data c(21) /.183357669378906e+11/, c(22) /.183418303528833e+12/, &
&c(23) /.192647115897045e+13/, c(24) /.211969993886476e+14/, &
&c(25) /.243826826879716e+15/, c(26) /.292659921929793e+16/, &
&c(27) /.365903070126431e+17/, c(28) /.475768102036307e+18/, &
&c(29) /.642404935790194e+19/, c(30) /.899520742705838e+20/
!------------------------
data d(1)  / .100000000000000e+01/, d(2)  /-.972222222222222e-01/, &
&d(3)  /-.438850308641975e-01/, d(4)  /-.424628307898948e-01/, &
&d(5)  /-.626621634920323e-01/, d(6)  /-.124105896027275e+00/, &
&d(7)  /-.308253764901079e+00/, d(8)  /-.920479992412945e+00/, &
&d(9)  /-.321049358464862e+01/, d(10) /-.128072930807356e+02/, &
&d(11) /-.575083035139143e+02/, d(12) /-.287033237109221e+03/, &
&d(13) /-.157635730333710e+04/, d(14) /-.944635482309593e+04/, &
&d(15) /-.613357066638521e+05/, d(16) /-.428952400400069e+06/, &
&d(17) /-.321453652140086e+07/, d(18) /-.256979083839113e+08/, &
&d(19) /-.218293420832160e+09/, d(20) /-.196352378899103e+10/
data d(21) /-.186439310881072e+11/, d(22) /-.186352996385294e+12/, &
&d(23) /-.195588293238984e+13/, d(24) /-.215064446351972e+14/, &
&d(25) /-.247236992290621e+15/, d(26) /-.296588243029521e+16/, &
&d(27) /-.370624400063547e+17/, d(28) /-.481678264794522e+18/, &
&d(29) /-.650098408075106e+19/, d(30) /-.909919826436541e+20/
!------------------------
!     c1 = pi**(-1/2)
!     c2 = (2*pi)**(-1/2)
!------------------------
data c1 /.564189583547756/
data c2 /.398942280401433/
!------------------------
!
!     Eps, xpos, and xneg are machine dependent constants. Eps is
!     THE SMALLEST NUMBER SUCH THAT 1.0 + eps .GT. 1.0, XPOS IS THE
!     the largest postive number for which exp(X) can be computed,
!     and xneg is the largest negative number for which exp(X) does
!     not underflow.
!
                eps = spmpar(1)
                xpos = exparg(0)
                xneg = exparg(1)
!
!------------------------
ierr = 0
if (real(z) .lt. 0.0) go to 30
!
!             -----   real(z) .GE. 0    -----
!
z1 = csqrt(z)
z2 = csqrt(z1)
z2r = 1.0/z2
call crec (real(z), aimag(z), u, v)
w = -1.5*cmplx(u,v)/z1
u = abs(real(w))
v = abs(aimag(w))
t = amax1(u,v)
if (ind .ne. 0) go to 10
!
   if (t .eq. 0.0) go to 90
   u1 = u/t
   v1 = v/t
   r = u*u1 + v*v1
   xm = xpos
   if (real(w) .lt. 0.0) xm = -xneg
   if (u1 .ge. r*xm .or. v1 .ge. 0.1*r/eps) go to 90
   zeta = z1*z/1.5
   e = cexp(-zeta)
!
10 m = 20
if (t .gt. 30.0) m = 8
s1 = cmplx(c(m),0.0)
s2 = cmplx(d(m),0.0)
i = m
do 20 k = 2,m
   i = i - 1
   s1 = c(i) + w*s1
   s2 = d(i) + w*s2
20 continue
!
ai = 0.5*c1*z2r*s1
aip = - 0.5*c1*z2*s2
if (ind .ne. 0) return
ai = e*ai
aip = e*aip
return
!
!             -----   real(z) .LT. 0    -----
!
30 zz = -z
z1 = csqrt(zz)
z2 = csqrt(z1)
z2r = 1.0/z2
call crec (real(zz), aimag(zz), u, v)
w = 1.5*cmplx(u,v)/z1
u = abs(real(w))
v = abs(aimag(w))
t = amax1(u,v)
!
   if (t .eq. 0.0) go to 90
   u1 = u/t
   v1 = v/t
   r = u*u1 + v*v1
   if (ind .ne. 0) go to 40
      if (v1 .ge. r*xpos .or. u1 .ge. 0.1*r/eps) go to 90
      zeta = z1*zz/1.5
      go to 50
40 e = (0.0, 0.0)
   j = (0.0, -1.0)
   if (aimag(z) .lt. 0.0) j = (0.0, 1.0)
   if (v1 .gt. 0.5*r*abs(xneg)) go to 50
   if (u1 .ge. 0.05*r/eps) go to 90
   zeta = z1*zz/1.5
   e = cexp(2.0*j*zeta)
!
50 w2 =  w*w
m = 15
if (t .gt. 30.0) m = 5
m2 = m + m
i = m2 - 1
s1 = cmplx(c(i),0.0)
s2 = cmplx(c(m2),0.0)
s3 = cmplx(d(i),0.0)
s4 = cmplx(d(m2),0.0)
do k = 2,m
   i = i - 1
   s2 = c(i) - s2*w2
   s4 = d(i) - s4*w2
   i = i - 1
   s1 = c(i) - s1*w2
   s3 = d(i) - s3*w2
end do
s2 = w*s2
s4 = w*s4
!
if (ind .ne. 0) go to 70
   cn = ccos(zeta)
   si = csin(zeta)
   go to 80
70 cn = 0.5*(1.0 + e)
si = 0.5*(1.0 - e)*j
!
80 alpha = s1 - s2
beta  = s1 + s2
ai = c2*z2r*(alpha*cn + beta*si)
alpha = s3 - s4
beta  = s3 + s4
aip = c2*z2*(alpha*si - beta*cn)
return
!
!         RETURN WITH ZERO VALUES IF SCALING IS NEEDED
!
90 ai = (0.0, 0.0)
aip = (0.0, 0.0)
ierr = 1
return
end subroutine aia

subroutine cbi(ind,z,bi,bip,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ind
real :: a, b, r
real :: cpabs
!------------------------------------------------------------
!     Calculates the Airy function bi and its derivative bip
!     for complex argument z.
!------------------------------------------------------------
complex, intent(in) :: z
complex :: ai
complex, intent(inout) :: bi
complex :: aip
complex, intent(inout) :: bip
ierr = 0
a = real(z)
b = aimag(z)
r = cpabs(a,b)
if(r .gt. 1.0) go to 10
!
!     Maclaurin expansion
!
   call airm(ind,z,ai,aip,bi,bip)
   return
10 if(r .gt. 9.6) go to 20
!
!     Intermediate range calculation
!
   call bii(ind,z,bi,bip,ierr)
   return
!
!     Asymptotic expansion
!
20 call bia(ind,z,bi,bip,ierr)
return
end subroutine cbi

subroutine bii(ind, z, bi, bip, ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ind
real :: a, c1, r, sqt3, x, y
real :: cpabs
!------------------------------------------------------------
!     Calculates the Airy function bi and its derivative bip
!     FOR COMPLEX ARGUMENT z IN THE INTERMEDIATE RANGE 1 .LE.
!     CABS(z) .LE. 10.0.
!------------------------------------------------------------
complex, intent(in) :: z
complex, intent(inout) :: bi, bip
complex :: z1, z2, zm, w1, w2, w1m, w2m, e, e1
!
!     c1 = 1/sqrt(3)
!     sqt3 = sqrt(3)
!
data c1/5.77350269189626e-01/
data sqt3/1.73205080756888e+00/
!
ierr = 0
x = real(z)
y = aimag(z)
r = cpabs(x, y)
z1 = csqrt(z)
z2 = z1*z/1.5
e = cexp(-z2)
e1 = 1.0/e
if(real(z) .lt. 0.0) go to 10
!
!               ----  real(z) .GE. 0  ----
!
if (r .lt. 8.9) go to 5
a = 0.156*r - 0.913
if (abs(y) .lt. a*x .or. abs(y) .gt. 0.58*x) go to 40
5 call ia(z2, w1, w2, w1m, w2m)
   bi = c1*z1*(w1 + w1m)
   bip = c1*z*(w2 + w2m)
   if (ind .eq. 0) return
   go to 20
!
!               ----  real(z) .LT. 0  ----
!
10 if (r .lt. 8.1) go to 15
if (abs(y) .lt. 3.89*abs(x)) go to 40
15 zm = -z
   z1 = csqrt(zm)
   z2 = z1*zm/1.5
   call ja(z2, w1, w2, w1m, w2m)
   bi = c1*z1*(w1m -w1)
   bip = c1*zm*(w2m + w2)
   if (ind .eq. 0) return
20 if (x .ge. c1*abs(y)) go to 30
      bi = bi*e1
      bip = bip*e1
      return
30 bi = bi*e
   bip = bip*e
   return
40 call bia(ind, z, bi, bip, ierr)
return
end subroutine bii

subroutine bia(ind,z,bi,bip,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ind
integer :: i, k, m, m2
real :: c(30), c1, c2, c3, ce, cf, d(30), eps, r, s, sqt3, t, u, &
&u1, v, v1, x, xneg, xpos, y
real :: exparg
real :: spmpar
!---------------------------------------------------------------
!     Calculates the Airy function bi and its derivative bip for
!     complex argument z by means of asymptotic expansions.
!---------------------------------------------------------------
complex, intent(in) :: z
complex, intent(inout) :: bi, bip
complex :: z1, z2, z2r, zz, w, w2, s1, s2, s3, s4, e, zeta, si, &
&cn, cf1, cf2, ex3c, ex6, ex6c, cln2, alpha, beta, j, cz
!------------------------
data c(1)  /.100000000000000e+01/, c(2)  /.694444444444444e-01/, &
&c(3)  /.371334876543210e-01/, c(4)  /.379930591278006e-01/, &
&c(5)  /.576491904126697e-01/, c(6)  /.116099064025515e+00/, &
&c(7)  /.291591399230751e+00/, c(8)  /.877666969510017e+00/, &
&c(9)  /.307945303017317e+01/, c(10) /.123415733323452e+02/, &
&c(11) /.556227853659171e+02/, c(12) /.278465080777603e+03/, &
&c(13) /.153316943201280e+04/, c(14) /.920720659972641e+04/, &
&c(15) /.598925135658791e+05/, c(16) /.419524875116551e+06/, &
&c(17) /.314825741786683e+07/, c(18) /.251989198716024e+08/, &
&c(19) /.214288036963680e+09/, c(20) /.192937554918249e+10/
data c(21) /.183357669378906e+11/, c(22) /.183418303528833e+12/, &
&c(23) /.192647115897045e+13/, c(24) /.211969993886476e+14/, &
&c(25) /.243826826879716e+15/, c(26) /.292659921929793e+16/, &
&c(27) /.365903070126431e+17/, c(28) /.475768102036307e+18/, &
&c(29) /.642404935790194e+19/, c(30) /.899520742705838e+20/
!------------------------
data d(1)  / .100000000000000e+01/, d(2)  /-.972222222222222e-01/, &
&d(3)  /-.438850308641975e-01/, d(4)  /-.424628307898948e-01/, &
&d(5)  /-.626621634920323e-01/, d(6)  /-.124105896027275e+00/, &
&d(7)  /-.308253764901079e+00/, d(8)  /-.920479992412945e+00/, &
&d(9)  /-.321049358464862e+01/, d(10) /-.128072930807356e+02/, &
&d(11) /-.575083035139143e+02/, d(12) /-.287033237109221e+03/, &
&d(13) /-.157635730333710e+04/, d(14) /-.944635482309593e+04/, &
&d(15) /-.613357066638521e+05/, d(16) /-.428952400400069e+06/, &
&d(17) /-.321453652140086e+07/, d(18) /-.256979083839113e+08/, &
&d(19) /-.218293420832160e+09/, d(20) /-.196352378899103e+10/
data d(21) /-.186439310881072e+11/, d(22) /-.186352996385294e+12/, &
&d(23) /-.195588293238984e+13/, d(24) /-.215064446351972e+14/, &
&d(25) /-.247236992290621e+15/, d(26) /-.296588243029521e+16/, &
&d(27) /-.370624400063547e+17/, d(28) /-.481678264794522e+18/, &
&d(29) /-.650098408075106e+19/, d(30) /-.909919826436541e+20/
!-------------------------
!     sqt3 = sqrt(3)
!     ex3c = exp(-i*pi/3)
!     ex6 = exp(i*pi/6)
!     ex6c = exp(-i*pi/6)
!     cln2 = 0.5*i*ln(2)
!     c1 = pi**(-1/2)
!     c2 = (2*pi)**(-1/2)
!     c3 = 2**(-1/2)
!--------------------------
data sqt3/1.73205080756888/
data ex3c/(5.e-01, -8.66025403784439e-01)/
data ex6/(8.66025403784439e-01, 5.e-01)/
data ex6c/(8.66025403784439e-01, -5.e-01)/
data cln2/(0.0, 3.46573590279973e-01)/
data c1/5.64189583547756e-01/
data c2/3.98942280401433e-01/
data c3/7.07106781186548e-01/
!--------------------------
!
!     Eps and XM are machine dependent constants. Eps is the
!     SMALLEST NUMBER SUCH THAT 1.0 + eps .GT. 1.0, XPOS IS THE
!     largest positive number for which exp(XM) can be computed,
!     and XNEG is the negative number of largest magnitude for
!     which exp(X) does not underflow.
!
                eps = spmpar(1)
                xpos = exparg(0)
                xneg = exparg(1)
!
!------------------------
ierr = 0
x = real(z)
y = aimag(z)
if (x .lt. abs(y)*sqt3) go to 30
!
!          -----  abs(ARG(z)) .LE. PI/6  ----
!
z1 = csqrt(z)
z2 = csqrt(z1)
z2r = 1.0/z2
call crec(x, y, u, v)
w = 1.5*cmplx(u, v)/z1
u = abs(real(w))
v = abs(aimag(w))
t = amax1(u, v)
if (ind .ne. 0) go to 10
   if (t .eq. 0.0) go to 90
      u1 = u/t
      v1 = v/t
      r = u*u1 + v*v1
      if (u1 .ge. r*xpos .or. v1 .ge. 0.1*r/eps) go to 90
         zeta = z1*z/1.5
         e = cexp(zeta)
!
10 m = 20
t = amax1(x, abs(y))
if (t .gt. 30.0) m = 8
s1 = cmplx(c(m), 0.0)
s2 = cmplx(d(m), 0.0)
i = m
do 20 k = 2,m
   i = i - 1
   s1 = c(i) + w*s1
   s2 = d(i) + w*s2
20 continue
!
bi = c1*z2r*s1
bip = c1*z2*s2
if (ind .ne. 0) return
   bi = e*bi
   bip = e*bip
   return
30 if (x .lt. 0.0) go to 50
!
!          ----  PI/6 .LT. abs(ARG(z)) .LE. PI/2  ----
!
cz = z
if (y .lt. 0.0) cz = conjg(cz)
zz = cz*ex3c
z1 = csqrt(zz)
z2 = csqrt(z1)
z2r = 1.0/z2
cf1 = c1*z2r*ex6
cf2 = c1*z2*ex6c
call crec(real(zz), aimag(zz), u, v)
w = 1.5*cmplx(u, v)/z1
u = abs(real(w))
v = abs(aimag(w))
t = amax1(u, v)
!
if (t .eq. 0.0) go to 90
   u1 = u/t
   v1 = v/t
   r = u*u1 + v*v1
   if (ind .ne. 0) go to 40
      if (v1 .ge. r*xpos .or. u1 .ge. 0.1*r/eps) go to 90
         zeta = z1*zz/1.5
         cn = ccos(zeta - cln2)
         si = csin(zeta - cln2)
         go to 70
!
!        e = exp(-2*i*(zeta - CLN2)) IF abs(ARG(zz)) .LE. PI/3
!        e = exp( 2*i*(zeta - CLN2)) IF abs(ARG(zz)) .GT. PI/3
!
40 e = (0.0, 0.0)
   j = (0.0, -1.0)
   s = 1.0
   ce = 1.0
   cf = 0.5
   if (aimag(zz) .le. 0.0) go to 44
      s = -1.0
      ce = 0.5
      cf = 2.0
44 if (v1 .ge. 0.5*r*abs(xneg)) go to 45
   if (u1 .ge. 0.05*r/eps) go to 90
   zeta = z1*zz/1.5
   e = cf*cexp(2.0*s*j*zeta)
45 cn = ce*c3*(1 + e)
   si = ce*s*c3*(1 - e)*j
   go to 70
!
!                  ----  real(z) .LT. 0  ----
!
50 zz = -z
if (y .lt. 0.0) zz = conjg(zz)
z1 = csqrt(zz)
z2 = csqrt(z1)
z2r = 1.0/z2
cf1 = c2*z2r
cf2 = c2*z2
call crec(real(zz), aimag(zz), u, v)
w = 1.5*cmplx(u, v)/z1
u = abs(real(w))
v = abs(aimag(w))
t = amax1(u, v)
!
if (t .eq. 0.0) go to 90
   u1 = u/t
   v1 = v/t
   r = u*u1 + v*v1
   if (ind .ne. 0) go to 60
      if (v1 .ge. r*xpos .or. u1 .ge. 0.1*r/eps) go to 90
         zeta = z1*zz/1.5
         cn = ccos(zeta)
         si = csin(zeta)
         go to 70
60 e = (0.0, 0.0)
   j = (0.0, -1.0)
   if (v1 .ge. 0.5*r*abs(xneg)) go to 65
   if (u1 .ge. 0.05*r/eps) go to 90
   zeta = z1*zz/1.5
   e = cexp(2.0*j*zeta)
65 cn = 0.5*(1.0 + e)
   si = 0.5*(1.0 - e)*j
!
70 w2 = w*w
m = 15
t = amax1(abs(x), abs(y))
if (t .gt. 30.0) m = 5
   m2 = m + m
   i = m2 - 1
   s1 = cmplx(c(i), 0.0)
   s2 = cmplx(c(m2), 0.0)
   s3 = cmplx(d(i), 0.0)
   s4 = cmplx(d(m2), 0.0)
   do k = 2,m
      i = i - 1
      s2 = c(i) - s2*w2
      s4 = d(i) - s4*w2
      i = i - 1
      s1 = c(i) - s1*w2
      s3 = d(i) - s3*w2
   end do
   s2 = w*s2
   s4 = w*s4
   if (x .ge. 0.0) go to 81
      alpha = s1 + s2
      beta = s2 - s1
      go to 82
81 alpha = s1 - s2
   beta = s1 + s2
82 bi = cf1*(alpha*cn + beta*si)
   if (x .ge. 0.0) go to 83
      alpha = s3 - s4
      beta = s3 + s4
      go to 84
83 alpha = s3 + s4
   beta = s4 - s3
84 bip = cf2*(alpha*cn + beta*si)
   if (y .ge. 0.0) return
   bi = conjg(bi)
   bip = conjg(bip)
   return
!
!            RETURN WITH ZERO VALUES IF SCALING IS NEEDED.
!
90 bi = (0.0, 0.0)
bip = (0.0, 0.0)
ierr = 1
return
end subroutine bia

subroutine ia(z, i1, i2, i1m, i2m)
implicit none
!-------------------------------------------------------------
!     Calculates the modified Bessel function of the first
!     kind for orders 1/3, 2/3, -1/3, and -2/3 and for complex
!     ARGUMENT z, WHERE -PI .LT. ARG(z) .LE. PI.  i1 AND i2
!     are replaced by the functions of orders 1/3 and 2/3,
!     respectively, and i1m and i2m by the functions of orders
!     -1/3 and -2/3, respectively.
!-------------------------------------------------------------
complex :: z
complex, intent(inout) :: i1, i2, i1m, i2m
complex :: cz, ex13, ex13c, ex23, ex23c
!
!     ex13 = exp(i*pi/3)
!     ex13c = exp(-i*pi/3)
!     ex23 = exp(2*i*pi/3)
!     ex23c = exp(-2*i*pi/3)
!
data ex13/(5.0e-01, 8.66025403784439e-01)/
data ex13c/(5.0e-01, -8.66025403784439e-01)/
data ex23/(-5.0e-01, 8.66025403784439e-01)/
data ex23c/(-5.0e-01, -8.66025403784439e-01)/
if(real(z) .ge. 0.0) go to 20
   cz = -z
!
!     CALCULATION OF i1, i2, i1m, AND i2m WHEN real(cz) .GT. 0.
!
   call imc(cz, i1, i2, i1m, i2m)
!
!     Final assembly
!
   if(aimag(z) .lt. 0.0) go to 10
      i1 = ex13*i1
      i2 = ex23*i2
      i1m = ex13c*i1m
      i2m = ex23c*i2m
      return
10 i1 = ex13c*i1
   i2 = ex23c*i2
   i1m = ex13*i1m
   i2m = ex23*i2m
   return
20 call imc(z, i1, i2, i1m, i2m)
   return
   end subroutine ia

subroutine imc(z, i1, i2, i1m, i2m)
implicit none
integer :: i, n, n1
real :: a, an, b, c1, c2, cfa, cfb, cn1, cn2, gm1, gm2
!----------------------------------------------------------------
!     Calculates the modified Bessel function of the first
!     kind for orders 1/3, 2/3, -1/3, and -2/3 and for complex
!     argument z. the Maclaurin expansion and backward recurrence
!     are used. i1 and i2 are replaced by the functions of orders
!     1/3 and 2/3, respectively, and i1m and i2m by the functions
!     of orders -1/3 and -2/3, respectively.  For greatest
!     ACCURACY, z SHOULD LIE IN THE REGION real(z) .GE. 0.
!----------------------------------------------------------------
complex :: z, ia1, ia2, ia3, ib1, ib2, ib3
complex, intent(inout) :: i1, i2, i1m, i2m
complex :: sz, zh, e, cf1, cf2, cf3, cf4
real :: m
!
!     gm1 = gamma(4.0/3.0)
!     gm2 = gamma(5.0/3.0)
!
data c1/.333333333333333e+00/
data c2/.666666666666667e+00/
data gm1/.892979511569248e+00/
data gm2/.902745292950932e+00/
zh = 0.5*z
sz = zh*zh
a = real(zh)
b = aimag(zh)
an = aint(a*a + b*b)
cn1 = c1 + an
cn2 = c2 + an
!
!     Calculation of initial values for backward recurrence by
!     use of the Maclaurin expansion.
!
call bim(z, cn1, ia1)
call bim(z, cn1 + 1.0, ia2)
call bim(z, cn2, ib1)
call bim(z, cn2 + 1.0, ib2)
!
!     Backward recurrence
!
n = an
m = an
n1 = n + 1
do 10 i = 1, n1
   ia3 = ia2
   ia2 = ia1
   ib3 = ib2
   ib2 = ib1
   cfa = (m + c1)*(m + c1 + 1.0)
   cfb = (m + c2)*(m + c2 + 1.0)
   m = m - 1.0
   ia1 = ia2 + (sz/cfa)*ia3
10 ib1 = ib2 + (sz/cfb)*ib3
e = cexp(c1*clog(zh))
cf1 = e/gm1
cf2 = e*e/gm2
cf3 = c2*cf2/zh
cf4 = c1*cf1/zh
i1 = cf1*ia2
i2 = cf2*ib2
i1m = cf3*ib1
i2m = cf4*ia1
return
end subroutine imc

subroutine bim(z,cn,w)
implicit none
real, intent(in) :: cn
real :: d, eps
real :: anorm
real :: spmpar
!-------------------------------------------------------------
!     Calculates the modified Bessel function of the first kind
!     FOR REAL ORDER cn .GT. -1 AND COMPLEX ARGUMENT z BY MEANS
!     of the Maclaurin expansion.  w is replaced by the
!     calculated value.
!-------------------------------------------------------------
real :: m
complex :: z
complex, intent(inout) :: w
complex :: sz, t
!------------------
anorm(z) = amax1(abs(real(z)),abs(aimag(z)))
!-------------------------------------------------------------
!     Eps is a machine dependent constant.  Eps is the smallest
!     NUMBER SUCH THAT 1 + eps .GT. 1.
!
eps = spmpar(1)
!
!-------------------------------------------------------------
sz = 0.25*z*z
!
!     Initialization of Maclaurin expansion
!
m = 1.0
t = sz/(cn + 1.0)
w = t
!
!     Summation of Maclaurin expansion
!
10 m = m + 1.0
   d = m*(cn + m)
   t = t*(sz/d)
   w = w + t
   if(anorm(t) .gt. eps*anorm(w)) go to 10
!
w = w + 1.0
return
end subroutine bim

subroutine ja(z, i1, i2, i1m, i2m)
implicit none
!------------------------------------------------------------
!     Calculates the Bessel function of the first kind for
!     orders 1/3, 2/3, -1/3, and -2/3 and for complex argument
!     z, WHERE -PI .LT. ARG(z) .LE. PI.  i1 AND i2 ARE REPLACED
!     by the functions of orders 1/3 and 2/3, respectively, and
!     i1m and i2m by functions of orders -1/3 and -2/3,
!     respectively.
!--------------------------------------------------------------
complex :: z
complex, intent(inout) :: i1, i2, i1m, i2m
complex :: cz, ex13, ex13c, ex23, ex23c
!
!     ex13 = exp(i*pi/3)
!     ex13c = exp(-i*pi/3)
!     ex23 = exp(2*i*pi/3)
!     ex23c = exp(-2*i*pi/3)
!
data ex13/(5.0e-01, 8.66025403784439e-01)/
data ex13c/(5.0e-01, -8.66025403784439e-01)/
data ex23/(-5.0e-01, 8.66025403784439e-01)/
data ex23c/(-5.0e-01, -8.66025403784439e-01)/
if(real(z) .ge. 0.0) go to 20
   cz = -z
!
!     CALCULATION OF i1, i2, i1m, AND i2m WHEN real(cz) .GT. 0.0
!
   call jmc(cz, i1, i2, i1m, i2m)
!
!     Final assembly
!
   if(aimag(z) .lt. 0.0) go to 10
      i1 = ex13*i1
      i2 = ex23*i2
      i1m = ex13c*i1m
      i2m = ex23c*i2m
      return
10 i1 = ex13c*i1
   i2 = ex23c*i2
   i1m = ex13*i1m
   i2m = ex23*i2m
   return
20 call jmc(z, i1, i2, i1m, i2m)
   return
   end subroutine ja

subroutine jmc(z, i1, i2, i1m, i2m)
implicit none
integer :: i, n, n1
real :: a, an, b, c1, c2, cfa, cfb, cn1, cn2, gm1, gm2
!----------------------------------------------------------------
!     Calculates the Bessel function of the first
!     kind for orders 1/3, 2/3, -1/3, and -2/3 and for complex
!     argument z. the Maclaurin expansion and backward recurrence
!     are used. i1 and i2 are replaced by the functions of orders
!     1/3 and 2/3, respectively, and i1m and i2m by the functions
!     of orders -1/3 and -2/3, respectively.  For greatest
!     ACCURACY, z SHOULD LIE IN THE REGION real(z) .GE. 0.
!----------------------------------------------------------------
complex :: z, ia1, ia2, ia3, ib1, ib2, ib3
complex, intent(inout) :: i1, i2, i1m, i2m
complex :: sz, zh, e, cf1, cf2, cf3, cf4
real :: m
!
!     gm1 = gamma(4.0/3.0)
!     gm2 = gamma(5.0/3.0)
!
data c1/.333333333333333e+00/
data c2/.666666666666667e+00/
data gm1/.892979511569248e+00/
data gm2/.902745292950932e+00/
zh = 0.5*z
sz = zh*zh
a = real(zh)
b = aimag(zh)
an = aint(a*a + b*b)
cn1 = c1 + an
cn2 = c2 + an
!
!     Calculation of initial values for backward recurrence by
!     use of the Maclaurin expansion.
!
call bjm(z, cn1, ia1)
call bjm(z, cn1 + 1.0, ia2)
call bjm(z, cn2, ib1)
call bjm(z, cn2 + 1.0, ib2)
!
!     Backward recurrence
!
n = an
n1 = n + 1
m = an
do 10 i = 1, n1
   ia3 = ia2
   ia2 = ia1
   ib3 = ib2
   ib2 = ib1
   cfa = (m + c1)*(m + c1 + 1.0)
   cfb = (m + c2)*(m + c2 + 1.0)
   m = m - 1.0
   ia1 = ia2 - (sz/cfa)*ia3
10 ib1 = ib2 - (sz/cfb)*ib3
e = cexp(c1*clog(zh))
cf1 = e/gm1
cf2 = e*e/gm2
cf3 = c2*cf2/zh
cf4 = c1*cf1/zh
i1 = cf1*ia2
i2 = cf2*ib2
i1m = cf3*ib1
i2m = cf4*ia1
return
end subroutine jmc

subroutine bjm(z,cn,w)
implicit none
real, intent(in) :: cn
real :: d, eps
real :: anorm
real :: spmpar
!-------------------------------------------------------------
!     Calculates the Bessel function of the first kind
!     FOR REAL ORDER cn .GT. -1 AND COMPLEX ARGUMENT z BY MEANS
!     of the Maclaurin expansion.  w is replaced by the
!     calculated value.
!-------------------------------------------------------------
real :: m
complex :: z
complex, intent(inout) :: w
complex :: sz, t
!------------------
anorm(z) = amax1(abs(real(z)),abs(aimag(z)))
!-------------------------------------------------------------
!     Eps is a machine dependent constant.  Eps is the smallest
!     NUMBER SUCH THAT 1 + eps .GT. 1.
!
eps = spmpar(1)
!
!-------------------------------------------------------------
sz = -0.25*z*z
!
!     Initialization of Maclaurin expansion
!
m = 1.0
t = sz/(cn + 1.0)
w = t
!
!     Summation of Maclaurin expansion
!
10 m = m + 1.0
   d = m*(cn + m)
   t = t*(sz/d)
   w = w + t
   if(anorm(t) .gt. eps*anorm(w)) go to 10
!
w = w + 1.0
return
end subroutine bjm

subroutine ka(ind, z, k1, k2)
implicit none
integer, intent(in) :: ind
integer :: ind1
real :: a, b, pi
!------------------------------------------------------------
!     Calculates the modified Bessel function of the second
!     kind for orders 1/3 and 2/3 and for complex argument z,
!     WHERE -pi .LT. ARG(z) .LE pi.  k1 IS REPLACED BY THE
!     function of order 1/3, and k2 by the function of order
!     2/3.
!------------------------------------------------------------
complex, intent(in) :: z
complex, intent(inout) :: k1, k2
complex :: i1, i2, i1m, i2m, cz, ex13c, ex23c, j, e
!
!     ex13c = exp(-pi*i/3)
!     ex23c = exp(-2*pi*i/3)
!
data pi/3.14159265358979e+00/
data ex13c/(5.0e-01, -8.66025403784439e-01)/
data ex23c/(-5.0e-01, -8.66025403784439e-01)/
data j/(0.0, 1.0)/
a = real(z)
b = aimag(z)
if (abs(b) .lt. -0.5*a) go to 10
!
!            ----  abs(b) .GE. -0.5*a  ----
!
   call kml(ind, z, k1, k2)
   return
!
!            ----  abs(b) .LT. -0.5*a  ----
!
10 cz = -z
   if(aimag(z) .lt. 0.0) cz = conjg(cz)
   ind1 = 0
   call kml(ind1, cz, k1, k2)
   call imc(cz, i1, i2, i1m, i2m)
   k1 = ex13c*k1 - j*pi*i1
   k2 = ex23c*k2 - j*pi*i2
   if (ind .eq. 0) go to 20
   e = cexp(z)
   k1 = k1*e
   k2 = k2*e
20 if(aimag(z) .ge. 0.0) return
      k1 = conjg(k1)
      k2 = conjg(k2)
      return
end subroutine ka

subroutine kml(ind, z, k1, k2)
implicit none
integer, intent(in) :: ind
integer :: i, l, m
real :: a, ai, al, b, c, c1, eps, r, th, x1, x2
real :: spmpar
!------------------------------------------------------------
!     Calculates the modified Bessel function of the second
!     kind for orders 1/3 and 2/3 and for complex argument z
!     by use of the Miller algorithm.  k1 is replaced by the
!     function of order 1/3, and k2 by the function of order
!     2/3.  For greatest accuracy, z should lie in the region
!     real(z) .GE. 0.
!------------------------------------------------------------
complex, intent(in) :: z
complex, intent(inout) :: k1, k2
complex :: bi, u1, u2, u3, s, e
!
!     c1 = sqrt(pi/2)
!
data c1/1.25331413731550e+00/
eps = spmpar(1)
x1 = real(z)
x2 = aimag(z)
!
!     Calculation of m for use in Miller algorithm.
!
call capo(x1, x2, r, th)
a = 3.0/(1.0 + r)
b = 14.7/(28.0 + r)
c = 2.0/(c1*eps*(2.0*r)**(0.25))
m = (0.485/r)*(alog(c) + r*cos(a*th)/(1.0 + 0.008*r))**2/ &
&(2.0*cos(b*th))**2 + 1.5
!
!     Backward recurrence in Miller algorithm.
!
s = 0.0
u2 = 0.0
u1 = eps
l = m
do 10 i = 1, m
   al = l
   u3 = u2
   u2 = u1
   ai = ((al - 0.5)**2 - 1.0/9.0)/(al*(al + 1.0))
   bi = 2.0*(al + z)/(al + 1.0)
   u1 = (bi*u2 - u3)/ai
   s = s + u1
10 l = l - 1
!
!     Final assembly
!
k1 = c1*u1/(s*csqrt(z))
k2 = k1*(z  + 1.0/6.0 - u2/u1)/z
if (ind .ne. 0) return
   e = cexp(-z)
   k1 = k1*e
   k2 = k2*e
   return
end subroutine kml

real function ai(x)
implicit none
real, intent(in) :: x
integer :: n, n2
real :: ad0, ad1, ad2, ad3, an0, an1, an2, an3, an4, an5, an6, &
&an7, an8, an9, bd0, bd1, bd2, bd3, bd4, bd5, bn0, bn1, bn2, bn3, &
