alfa = pn * (xnroot + ynroot + znroot) + xnroot * ynroot * znroot
alfa = alfa * alfa
beta = pn * (pn + lamda) * (pn + lamda)
call drcvl1 (alfa, beta, etolrc, rc, ierr)
if (ierr .ne. 0) return
sigma = sigma + power4 * rc
power4 = power4 * 0.25d0
xn = (xn + lamda) * 0.25d0
