zi = 1.1547005383792515e0*aimag(z) + 0.5e0
m = int(zi)
if (zi.lt.0e0) m = m - 1
zr = real(z) - 0.5e0*float(m) + 0.5e0
n = int(zr)
if (zr.lt.0e0) n = n - 1
z1 = z - float(n) - (0.5e0,0.86602540378443865e0)*float(m)
