!
20 m = mod(n,7)
if( m .eq. 0 ) go to 40
do i = 1,m
  dy(i) = dx(i)
end do
if( n .lt. 7 ) return
40 mp1 = m + 1
do i = mp1,n,7
  dy(i) = dx(i)
  dy(i + 1) = dx(i + 1)
  dy(i + 2) = dx(i + 2)
  dy(i + 3) = dx(i + 3)
  dy(i + 4) = dx(i + 4)
  dy(i + 5) = dx(i + 5)
  dy(i + 6) = dx(i + 6)
end do
return
end subroutine dcopy

subroutine  ccopy(n,cx,incx,cy,incy)
implicit none
!
!     Copies a vector, X, to a vector, Y.
!     Jack dongarra, LINPACK, 3/11/78.
!
complex, intent(in) :: cx(*)
complex, intent(inout) :: cy(*)
integer :: i
integer, intent(in) :: incx, incy
integer :: ix, iy
integer, intent(in) :: n
