subroutine iswap (n,ix,incx,iy,incy)
implicit none
integer, intent(in) :: incx, incy, n
integer :: i, iix, iiy, m, mp1, ns
!
!                Extended B L A S  subprogram
!
!    Description of parameters
!
!     --Input--
!        n  number of elements in input VECTOR(S)
!       ix  integer vector with n elements
!     incx  storage spacing between elements of ix
!       iy  integer vector with n elements
!     incy  storage spacing between elements of iy
!
!     --Output--
!       ix  INPUT VECTOR iy (UNCHANGED IF n .LE. 0)
!       iy  INPUT VECTOR ix (UNCHANGED IF n .LE. 0)
!
!     Interchange integer ix and integer iy.
!     FOR i = 0 TO n-1, INTERCHANGE  ix(LX+i*incx) AND iy(LY+i*incy),
!     WHERE LX = 1 IF incx .GE. 0, ELSE LX = (-incx)*n, AND LY IS
!     defined in a similar way using incy.
!
!***AUTHOR  VANDEVENDER, W. (SNLA), 1985
!
integer, intent(inout) :: ix(*), iy(*)
integer :: itemp1, itemp2, itemp3
!
if (n .le. 0) return
if (incx .ne. incy) go to 5
if (incx-1) 5,20,60
5 continue
!
!       Code for unequal or nonpositive increments.
!
iix = 1
iiy = 1
if (incx .lt. 0) iix = (1-n)*incx + 1
if (incy .lt. 0) iiy = (1-n)*incy + 1
do i = 1,n
   itemp1 = ix(iix)
   ix(iix) = iy(iiy)
   iy(iiy) = itemp1
   iix = iix + incx
   iiy = iiy + incy
end do
return
!
!       Code for both increments equal to 1
!
!
!       Clean-up loop so remaining vector LENGTH is a multiple of 3.
!
20 m = mod(n,3)
if (m .eq. 0) go to 40
do i = 1,m
   itemp1 = ix(i)
   ix(i) = iy(i)
   iy(i) = itemp1
end do
if (n .lt. 3) return
!
40 mp1 = m + 1
do i = mp1,n,3
   itemp1 = ix(i)
   itemp2 = ix(i+1)
   itemp3 = ix(i+2)
   ix(i) = iy(i)
   ix(i+1) = iy(i+1)
   ix(i+2) = iy(i+2)
   iy(i) = itemp1
   iy(i+1) = itemp2
   iy(i+2) = itemp3
end do
return
!
!     Code for equal, positive, nonunit increments.
!
60 ns = n*incx
do i = 1,ns,incx
   itemp1 = ix(i)
   ix(i) = iy(i)
   iy(i) = itemp1
end do
return
end subroutine iswap

subroutine  sswap (n,sx,incx,sy,incy)
implicit none
!
!     Interchanges two vectors.
!     Uses unrolled loops for increments equal to 1.
!     Jack dongarra, LINPACK, 3/11/78.
!
real, intent(inout) :: sx(*), sy(*)
real :: stemp
integer :: i
integer, intent(in) :: incx, incy
integer :: ix, iy, m, mp1
integer, intent(in) :: n
!
if(n.le.0)return
if(incx.eq.1.and.incy.eq.1)go to 20
!
!       Code for unequal increments or equal increments not equal
!         to 1
!
ix = 1
iy = 1
if(incx.lt.0)ix = (-n+1)*incx + 1
if(incy.lt.0)iy = (-n+1)*incy + 1
do i = 1,n
  stemp = sx(ix)
  sx(ix) = sy(iy)
  sy(iy) = stemp
  ix = ix + incx
  iy = iy + incy
end do
return
!
!       Code for both increments equal to 1
!
!
!       Clean-up loop
!
20 m = mod(n,3)
if( m .eq. 0 ) go to 40
do i = 1,m
  stemp = sx(i)
  sx(i) = sy(i)
  sy(i) = stemp
end do
if( n .lt. 3 ) return
40 mp1 = m + 1
do i = mp1,n,3
  stemp = sx(i)
  sx(i) = sy(i)
  sy(i) = stemp
  stemp = sx(i + 1)
  sx(i + 1) = sy(i + 1)
  sy(i + 1) = stemp
  stemp = sx(i + 2)
  sx(i + 2) = sy(i + 2)
  sy(i + 2) = stemp
end do
return
end subroutine sswap

