subroutine srotmg (sd1,sd2,sx1,sy1,sparam)
implicit none
real, intent(inout) :: sd1, sd2, sparam(5), sx1
real, intent(in) :: sy1
real :: gam, gamsq, one, rgamsq, sflag, sh11, sh12, sh21, sh22, &
&sp1, sp2, sq1, sq2, stemp, su, two, zero
!
!     Construct the modified Givens transformation matrix H which zeros
!     the second component of the 2-vector  (sqrt(sd1)*sx1,sqrt(sd2)*
!     sy1)**T.
!     WITH sparam(1)=sflag, H HAS ONE OF THE FOLLOWING FORMS..
!
!     sflag=-1.e0     sflag=0.e0        sflag=1.e0     sflag=-2.e0
!
!       (sh11  sh12)    (1.E0  sh12)    (sh11  1.E0)    (1.E0  0.E0)
!     h=(          )    (          )    (          )    (          )
!       (sh21  sh22),   (sh21  1.E0),   (-1.E0 sh22),   (0.E0  1.E0).
!
!     Locations 2-4 of sparam contain sh11,sh21,sh12, and sh22
!     respectively. (Values of 1.E0, -1.E0, or 0.E0 implied by the
!     value of sparam(1) are not stored in sparam.)
!
!     IT IS ASSUMED THAT gamsq = gam*gam AND rgamsq = one/(gam*gam).
!     The values of gamsq and rgamsq set in the data statement may be
!     inexact.  This is OK as they are only used for testing the size
!     of sd1 and sd2.  All actual scaling of data is done using gam.
!
!
data zero,one,two /0.e0,1.e0,2.e0/
data gam,gamsq,rgamsq/4096.e0,1.67772e7,5.96046e-8/
!
if (sd1 .lt. zero) go to 60
sp2 = sd2*sy1
if (sp2 .ne. zero) go to 20
    sflag = -two
    go to 260
!
!     Regular-case..
!
20 sp1 = sd1*sx1
sq1 = sp1*sx1
sq2 = sp2*sy1
!
if (abs(sq1) .le. abs(sq2)) go to 40
    sh21 = -sy1/sx1
    sh12 = sp2/sp1
!
    su = one - sh12*sh21
    if (su .le. zero) go to 60
!
         sflag = zero
         sh11 = one
         sh22 = one
         sd1 = sd1/su
         sd2 = sd2/su
         sx1 = sx1*su
!         Go scale-check..
         go to 100
!
40 continue
    if (sd2 .lt. zero) go to 60
         sflag = one
         sh11 = sp1/sp2
         sh21 = -one
         sh12 = one
         sh22 = sx1/sy1
!
         su = one + sh11*sh22
         stemp = sd2/su
         sd2 = sd1/su
         sd1 = stemp
         sx1 = sy1*su
!         Go scale-check
         go to 100
!
!     Procedure..zero-H-D-and-sx1..
!
60 continue
    sflag = -one
    sh11 = zero
    sh12 = zero
    sh21 = zero
    sh22 = zero
!
    sd1 = zero
    sd2 = zero
    sx1 = zero
    go to 250
!
!     Procedure..scale-check
!
100 continue
110 continue
    if (sd1 .gt. rgamsq) go to 130
         if (sd1 .eq. zero) go to 160
         sflag = -one
         sd1 = sd1*(gam*gam)
         sx1 = sx1/gam
         sh11 = sh11/gam
         sh12 = sh12/gam
    go to 110
!
130 continue
140 continue
    if (sd1 .lt. gamsq) go to 160
         sflag = -one
         sd1 = sd1/(gam*gam)
         sx1 = sx1*gam
         sh11 = sh11*gam
         sh12 = sh12*gam
    go to 140
!
160 continue
170 continue
    if (abs(sd2) .gt. rgamsq) go to 190
         if (sd2 .eq. zero) go to 220
         sflag = -one
         sd2 = sd2*(gam*gam)
         sh21 = sh21/gam
         sh22 = sh22/gam
    go to 170
!
190 continue
200 continue
    if (abs(sd2) .lt. gamsq) go to 220
         sflag = -one
         sd2 = sd2/(gam*gam)
         sh21 = sh21*gam
         sh22 = sh22*gam
    go to 200
!
220 continue
    if(sflag)250,230,240
230 continue
         sparam(3)=sh21
         sparam(4)=sh12
         go to 260
240 continue
         sparam(2)=sh11
         sparam(5)=sh22
         go to 260
250 continue
         sparam(2)=sh11
         sparam(3)=sh21
         sparam(4)=sh12
         sparam(5)=sh22
260 continue
    sparam(1)=sflag
    return
end subroutine srotmg

subroutine srotm (n,sx,incx,sy,incy,sparam)
implicit none
integer, intent(in) :: incx, incy, n
real :: sparam(5)
real, intent(inout) :: sx(*), sy(*)
integer :: i, kx, ky, nsteps
real :: sflag, sh11, sh12, sh21, sh22, two, w, z, zero
!
!     Apply the modified Givens transformation, H, to the 2 by n matrix
!
!     (sx**T), WHERE **T INDICATES TRANSPOSE. THE ELEMENTS OF sx ARE IN
!     (sy**T)
!
!     sx(LX+i*incx), i = 0 TO n-1, WHERE LX = 1 IF incx .GE. 0, ELSE
!     LX = (-incx)*n, AND SIMILARLY FOR sy USING USING LY AND INCY.
!
!     WITH sparam(1)=sflag, H HAS ONE OF THE FOLLOWING FORMS..
!
!     sflag=-1.e0     sflag=0.e0        sflag=1.e0     sflag=-2.e0
!
!       (sh11  sh12)    (1.E0  sh12)    (sh11  1.E0)    (1.E0  0.E0)
!     h=(          )    (          )    (          )    (          )
!       (sh21  sh22),   (sh21  1.E0),   (-1.E0 sh22),   (0.E0  1.E0).
!
!
data zero,two/0.e0,2.e0/
!
sflag=sparam(1)
if(n .le. 0 .or.(sflag+two.eq.zero)) go to 140
    if(.not.(incx.eq.incy.and. incx .gt.0)) go to 70
!
         nsteps=n*incx
         if(sflag) 50,10,30
10 continue
         sh21=sparam(3)
         sh12=sparam(4)
              do i=1,nsteps,incx
              w=sx(i)
              z=sy(i)
              sx(i)=w+z*sh12
              sy(i)=w*sh21+z
              end do
         go to 140
30 continue
         sh11=sparam(2)
         sh22=sparam(5)
              do i=1,nsteps,incx
              w=sx(i)
              z=sy(i)
              sx(i)=w*sh11+z
              sy(i)=-w+sh22*z
              end do
         go to 140
50 continue
         sh11=sparam(2)
         sh21=sparam(3)
         sh12=sparam(4)
         sh22=sparam(5)
              do i=1,nsteps,incx
              w=sx(i)
              z=sy(i)
              sx(i)=w*sh11+z*sh12
              sy(i)=w*sh21+z*sh22
              end do
         go to 140
70 continue
    kx=1
    ky=1
    if(incx .lt. 0) kx=1+(1-n)*incx
    if(incy .lt. 0) ky=1+(1-n)*incy
!
    if(sflag)120,80,100
80 continue
    sh21=sparam(3)
    sh12=sparam(4)
         do i=1,n
         w=sx(kx)
         z=sy(ky)
         sx(kx)=w+z*sh12
         sy(ky)=w*sh21+z
         kx=kx+incx
         ky=ky+incy
         end do
    go to 140
100 continue
    sh11=sparam(2)
    sh22=sparam(5)
         do i=1,n
         w=sx(kx)
         z=sy(ky)
         sx(kx)=w*sh11+z
         sy(ky)=-w+sh22*z
         kx=kx+incx
         ky=ky+incy
         end do
    go to 140
120 continue
    sh11=sparam(2)
    sh21=sparam(3)
    sh12=sparam(4)
    sh22=sparam(5)
         do i=1,n
         w=sx(kx)
         z=sy(ky)
         sx(kx)=w*sh11+z*sh12
         sy(ky)=w*sh21+z*sh22
         kx=kx+incx
         ky=ky+incy
         end do
140 continue
    return
    end subroutine srotm

subroutine drotmg (dd1,dd2,dx1,dy1,dparam)
implicit none
!
!     Construct the modified Givens transformation matrix H which zeros
!     the second component of the 2-vector  (dsqrt(dd1)*dx1,dsqrt(dd2)*
!     dy1)**T.
!     WITH dparam(1)=dflag, H HAS ONE OF THE FOLLOWING FORMS..
!
!     dflag=-1.d0     dflag=0.d0        dflag=1.d0     dflag=-2.d0
!
!       (dh11  dh12)    (1.D0  dh12)    (dh11  1.D0)    (1.D0  0.D0)
!     h=(          )    (          )    (          )    (          )
!       (dh21  dh22),   (dh21  1.D0),   (-1.D0 dh22),   (0.D0  1.D0).
!
!     Locations 2-4 of dparam contain dh11,dh21,dh12, and dh22
!     respectively. (Values of 1.D0, -1.D0, or 0.D0 implied by the
!     value of dparam(1) are not stored in dparam.)
!
!     IT IS ASSUMED THAT gamsq = gam*gam AND rgamsq = one/(gam*gam).
!     The values of gamsq and rgamsq set in the data statement may be
!     inexact.  This is OK as they are only used for testing the size
!     of dd1 and dd2.  All actual scaling of data is done using gam.
!
double precision :: gam, one, rgamsq
double precision, intent(inout) :: dd2
double precision :: dh11, dh21
double precision, intent(inout) :: dparam(5)
double precision :: dp2, dq2, du
double precision, intent(in) :: dy1
double precision :: zero, gamsq
double precision, intent(inout) :: dd1
double precision :: dflag, dh12, dh22, dp1, dq1, dtemp
double precision, intent(inout) :: dx1
double precision :: two
!
data zero,one,two /0.d0,1.d0,2.d0/
data gam,gamsq,rgamsq/4096.d0,16777216.d0,5.9604645d-8/
!
if (dd1 .lt. zero) go to 60
dp2 = dd2*dy1
if (dp2 .ne. zero) go to 20
    dflag = -two
    go to 260
!
!     Regular-case..
!
20 dp1 = dd1*dx1
dq1 = dp1*dx1
dq2 = dp2*dy1
!
if (dabs(dq1) .le. dabs(dq2)) go to 40
    dh21 = -dy1/dx1
    dh12 = dp2/dp1
!
    du = one - dh12*dh21
    if (du .le. zero) go to 60
!
         dflag = zero
         dh11 = one
         dh22 = one
         dd1 = dd1/du
         dd2 = dd2/du
         dx1 = dx1*du
!         Go scale-check..
         go to 100
!
40 continue
    if (dd2 .lt. zero) go to 60
         dflag = one
         dh11 = dp1/dp2
         dh21 = -one
         dh12 = one
         dh22 = dx1/dy1
!
         du = one + dh11*dh22
         dtemp = dd2/du
         dd2 = dd1/du
         dd1 = dtemp
         dx1 = dy1*du
!         Go scale-check
         go to 100
!
!     Procedure..zero-H-D-and-dx1..
!
60 continue
    dflag = -one
    dh11 = zero
    dh12 = zero
    dh21 = zero
    dh22 = zero
!
    dd1 = zero
    dd2 = zero
    dx1 = zero
    go to 250
!
!     Procedure..scale-check
!
100 continue
110 continue
    if (dd1 .gt. rgamsq) go to 130
         if (dd1 .eq. zero) go to 160
         dflag = -one
         dd1 = dd1*(gam*gam)
         dx1 = dx1/gam
         dh11 = dh11/gam
         dh12 = dh12/gam
    go to 110
!
130 continue
140 continue
    if (dd1 .lt. gamsq) go to 160
         dflag = -one
         dd1 = dd1/(gam*gam)
         dx1 = dx1*gam
         dh11 = dh11*gam
         dh12 = dh12*gam
    go to 140
!
160 continue
170 continue
    if (dabs(dd2) .gt. rgamsq) go to 190
         if (dd2 .eq. zero) go to 220
         dflag = -one
         dd2 = dd2*(gam*gam)
         dh21 = dh21/gam
         dh22 = dh22/gam
    go to 170
!
190 continue
200 continue
    if (dabs(dd2) .lt. gamsq) go to 220
         dflag = -one
         dd2 = dd2/(gam*gam)
         dh21 = dh21*gam
         dh22 = dh22*gam
    go to 200
!
220 continue
    if(dflag)250,230,240
230 continue
         dparam(3)=dh21
         dparam(4)=dh12
         go to 260
240 continue
         dparam(2)=dh11
         dparam(5)=dh22
         go to 260
250 continue
         dparam(2)=dh11
         dparam(3)=dh21
         dparam(4)=dh12
         dparam(5)=dh22
260 continue
    dparam(1)=dflag
    return
end subroutine drotmg

subroutine drotm (n,dx,incx,dy,incy,dparam)
implicit none
integer, intent(in) :: incx, incy, n
integer :: i, kx, ky, nsteps
!
!     Apply the modified Givens transformation, H, to the 2 by n matrix
!
!     (dx**T), WHERE **T INDICATES TRANSPOSE. THE ELEMENTS OF dx ARE IN
!     (dy**T)
!
!     dx(LX+i*incx), i = 0 TO n-1, WHERE LX = 1 IF incx .GE. 0, ELSE
!     LX = (-incx)*n, AND SIMILARLY FOR SY USING LY AND INCY.
!
!     WITH dparam(1)=dflag, H HAS ONE OF THE FOLLOWING FORMS..
!
!     dflag=-1.d0     dflag=0.d0        dflag=1.d0     dflag=-2.d0
!
!       (dh11  dh12)    (1.D0  dh12)    (dh11  1.D0)    (1.D0  0.D0)
!     h=(          )    (          )    (          )    (          )
!       (dh21  dh22),   (dh21  1.D0),   (-1.D0 dh22),   (0.D0  1.D0).
!
double precision :: dflag, dh12, dh22
double precision, intent(inout) :: dx(*)
double precision :: two, z, dh11, dh21, dparam(5)
double precision, intent(inout) :: dy(*)
double precision :: w, zero
!
data zero,two/0.d0,2.d0/
!
dflag=dparam(1)
if(n .le. 0 .or.(dflag+two.eq.zero)) go to 140
    if(.not.(incx.eq.incy.and. incx .gt.0)) go to 70
!
         nsteps=n*incx
         if(dflag) 50,10,30
10 continue
         dh21=dparam(3)
         dh12=dparam(4)
              do i=1,nsteps,incx
              w=dx(i)
              z=dy(i)
              dx(i)=w+z*dh12
              dy(i)=w*dh21+z
              end do
         go to 140
30 continue
         dh11=dparam(2)
         dh22=dparam(5)
              do i=1,nsteps,incx
              w=dx(i)
              z=dy(i)
              dx(i)=w*dh11+z
              dy(i)=-w+dh22*z
              end do
         go to 140
50 continue
         dh11=dparam(2)
         dh21=dparam(3)
         dh12=dparam(4)
         dh22=dparam(5)
              do i=1,nsteps,incx
              w=dx(i)
              z=dy(i)
              dx(i)=w*dh11+z*dh12
              dy(i)=w*dh21+z*dh22
              end do
         go to 140
70 continue
    kx=1
    ky=1
    if(incx .lt. 0) kx=1+(1-n)*incx
    if(incy .lt. 0) ky=1+(1-n)*incy
!
    if(dflag)120,80,100
80 continue
    dh21=dparam(3)
    dh12=dparam(4)
         do i=1,n
         w=dx(kx)
         z=dy(ky)
         dx(kx)=w+z*dh12
         dy(ky)=w*dh21+z
         kx=kx+incx
         ky=ky+incy
         end do
    go to 140
100 continue
    dh11=dparam(2)
    dh22=dparam(5)
         do i=1,n
         w=dx(kx)
         z=dy(ky)
         dx(kx)=w*dh11+z
         dy(ky)=-w+dh22*z
         kx=kx+incx
         ky=ky+incy
         end do
    go to 140
120 continue
    dh11=dparam(2)
    dh21=dparam(3)
    dh12=dparam(4)
    dh22=dparam(5)
         do i=1,n
         w=dx(kx)
         z=dy(ky)
         dx(kx)=w*dh11+z*dh12
         dy(ky)=w*dh21+z*dh22
         kx=kx+incx
         ky=ky+incy
         end do
140 continue
    return
    end subroutine drotm

real function sdot(n,sx,incx,sy,incy)
implicit none
!
!     Forms the dot product of two vectors.
!     Uses unrolled loops for increments equal to one.
!     Jack dongarra, LINPACK, 3/11/78.
!
real, intent(in) :: sx(*), sy(*)
real :: stemp
integer :: i
integer, intent(in) :: incx, incy
integer :: ix, iy, m, mp1
integer, intent(in) :: n
!
stemp = 0.0e0
sdot = 0.0e0
if(n.le.0)return
if(incx.eq.1.and.incy.eq.1)go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if(incx.lt.0)ix = (-n+1)*incx + 1
if(incy.lt.0)iy = (-n+1)*incy + 1
do i = 1,n
  stemp = stemp + sx(ix)*sy(iy)
  ix = ix + incx
  iy = iy + incy
end do
sdot = stemp
return
!
!        Code for both increments equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,5)
if( m .eq. 0 ) go to 40
do i = 1,m
  stemp = stemp + sx(i)*sy(i)
end do
if( n .lt. 5 ) go to 60
40 mp1 = m + 1
do i = mp1,n,5
  stemp = stemp + sx(i)*sy(i) + sx(i + 1)*sy(i + 1) + &
&sx(i + 2)*sy(i + 2) + sx(i + 3)*sy(i + 3) + sx(i + 4)*sy(i + 4)
end do
60 sdot = stemp
return
end function sdot

double precision function ddot(n,dx,incx,dy,incy)
implicit none
!
!     Forms the dot product of two vectors.
!     Uses unrolled loops for increments equal to one.
!     Jack dongarra, LINPACK, 3/11/78.
!
double precision, intent(in) :: dx(*), dy(*)
double precision :: dtemp
integer :: i
integer, intent(in) :: incx, incy
integer :: ix, iy, m, mp1
integer, intent(in) :: n
!
ddot = 0.0d0
dtemp = 0.0d0
if(n.le.0)return
if(incx.eq.1.and.incy.eq.1)go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if(incx.lt.0)ix = (-n+1)*incx + 1
if(incy.lt.0)iy = (-n+1)*incy + 1
do i = 1,n
  dtemp = dtemp + dx(ix)*dy(iy)
  ix = ix + incx
  iy = iy + incy
end do
ddot = dtemp
return
!
!        Code for both increments equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,5)
if( m .eq. 0 ) go to 40
do i = 1,m
  dtemp = dtemp + dx(i)*dy(i)
end do
if( n .lt. 5 ) go to 60
40 mp1 = m + 1
do i = mp1,n,5
  dtemp = dtemp + dx(i)*dy(i) + dx(i + 1)*dy(i + 1) + &
&dx(i + 2)*dy(i + 2) + dx(i + 3)*dy(i + 3) + dx(i + 4)*dy(i + 4)
end do
60 ddot = dtemp
return
end function ddot

complex function cdotc(n,cx,incx,cy,incy)
implicit none
!
!     Forms the dot product of two vectors, conjugating the first
!     vector.
!     Jack dongarra, LINPACK,  3/11/78.
!
complex, intent(in) :: cx(*), cy(*)
complex :: ctemp
integer :: i
integer, intent(in) :: incx, incy
integer :: ix, iy
integer, intent(in) :: n
!
ctemp = (0.0,0.0)
cdotc = (0.0,0.0)
if(n.le.0)return
if(incx.eq.1.and.incy.eq.1)go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if(incx.lt.0)ix = (-n+1)*incx + 1
if(incy.lt.0)iy = (-n+1)*incy + 1
do i = 1,n
  ctemp = ctemp + conjg(cx(ix))*cy(iy)
  ix = ix + incx
  iy = iy + incy
end do
cdotc = ctemp
return
!
!        Code for both increments equal to 1
!
20 do i = 1,n
  ctemp = ctemp + conjg(cx(i))*cy(i)
end do
cdotc = ctemp
return
end function cdotc

