subroutine  sscal(n,sa,sx,incx)
implicit none
!
!     Scales a vector BY a constant.
!     Uses unrolled loops for increment equal to 1.
!     Jack dongarra, LINPACK, 3/11/78.
!
real, intent(in) :: sa
real, intent(inout) :: sx(*)
integer :: i
integer, intent(in) :: incx
integer :: m, mp1
integer, intent(in) :: n
integer :: nincx
!
if(n.le.0)return
if(incx.eq.1)go to 20
!
!        Code for increment not equal to 1
!
nincx = n*incx
do i = 1,nincx,incx
  sx(i) = sa*sx(i)
end do
return
!
!        Code for increment equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,5)
if( m .eq. 0 ) go to 40
do i = 1,m
  sx(i) = sa*sx(i)
end do
if( n .lt. 5 ) return
40 mp1 = m + 1
do i = mp1,n,5
  sx(i) = sa*sx(i)
  sx(i + 1) = sa*sx(i + 1)
  sx(i + 2) = sa*sx(i + 2)
  sx(i + 3) = sa*sx(i + 3)
  sx(i + 4) = sa*sx(i + 4)
end do
return
end subroutine sscal

