end subroutine caxpy

real function sasum(n,sx,incx)
implicit none
!
!     Takes the sum of the absolute values.
!     Uses unrolled loops for increment equal to one.
!     Jack dongarra, LINPACK, 3/11/78.
!
real, intent(in) :: sx(*)
real :: stemp
integer :: i
integer, intent(in) :: incx
integer :: m, mp1
integer, intent(in) :: n
integer :: nincx
!
sasum = 0.0e0
stemp = 0.0e0
if(n.le.0)return
if(incx.eq.1)go to 20
!
!        Code for increment not equal to 1
!
nincx = n*incx
do i = 1,nincx,incx
  stemp = stemp + abs(sx(i))
end do
sasum = stemp
return
!
!        Code for increment equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,6)
if( m .eq. 0 ) go to 40
do i = 1,m
  stemp = stemp + abs(sx(i))
end do
if( n .lt. 6 ) go to 60
40 mp1 = m + 1
do i = mp1,n,6
  stemp = stemp + abs(sx(i)) + abs(sx(i + 1)) + abs(sx(i + 2)) &
&+ abs(sx(i + 3)) + abs(sx(i + 4)) + abs(sx(i + 5))
end do
60 sasum = stemp
return
end function sasum

double precision function dasum(n,dx,incx)
implicit none
!
!     Takes the sum of the absolute values.
!     Jack dongarra, LINPACK, 3/11/78.
!
double precision, intent(in) :: dx(*)
double precision :: dtemp
integer :: i
integer, intent(in) :: incx
integer :: m, mp1
integer, intent(in) :: n
integer :: nincx
!
dasum = 0.0d0
dtemp = 0.0d0
if(n.le.0)return
if(incx.eq.1)go to 20
!
!        Code for increment not equal to 1
!
nincx = n*incx
do i = 1,nincx,incx
  dtemp = dtemp + dabs(dx(i))
end do
dasum = dtemp
return
!
!        Code for increment equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,6)
if( m .eq. 0 ) go to 40
do i = 1,m
  dtemp = dtemp + dabs(dx(i))
end do
if( n .lt. 6 ) go to 60
40 mp1 = m + 1
do i = mp1,n,6
  dtemp = dtemp + dabs(dx(i)) + dabs(dx(i + 1)) + dabs(dx(i + 2)) &
&+ dabs(dx(i + 3)) + dabs(dx(i + 4)) + dabs(dx(i + 5))
end do
60 dasum = dtemp
return
end function dasum

real function scasum(n,cx,incx)
implicit none
!
!     Takes the sum of the absolute values of a complex vector and
!     returns a single precision result.
!     Jack dongarra, LINPACK, 3/11/78.
!
complex, intent(in) :: cx(*)
real :: stemp
integer :: i
integer, intent(in) :: incx, n
integer :: nincx
!
scasum = 0.0e0
stemp = 0.0e0
if(n.le.0)return
if(incx.eq.1)go to 20
!
!        Code for increment not equal to 1
!
nincx = n*incx
do i = 1,nincx,incx
  stemp = stemp + abs(real(cx(i))) + abs(aimag(cx(i)))
end do
scasum = stemp
return
!
!        Code for increment equal to 1
!
20 do i = 1,n
  stemp = stemp + abs(real(cx(i))) + abs(aimag(cx(i)))
end do
scasum = stemp
return
end function scasum

real function snrm2 ( n, sx, incx)
implicit none
integer, intent(in) :: incx, n
integer :: i, j, nn
integer :: next
real, intent(in) :: sx(*)
real :: cutlo, cuthi, hitest, sum, xmax, zero, one
data   zero, one /0.0e0, 1.0e0/
!
!     Euclidean norm of the n-vector stored in sx() with storage
!     increment incx .
!     IF    n .LE. 0 RETURN WITH RESULT = 0.
!     IF n .GE. 1 THEN incx MUST BE .GE. 1
!
!           C.L.Lawson, 1978 jan 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     hopefully applicable to all machines.
!         cutlo = MAXIMUM OF  sqrt(U/EPS)  OVER ALL KNOWN MACHINES.
!         cuthi = MINIMUM OF  sqrt(V)      OVER ALL KNOWN MACHINES.
!     Where
!         EPS = SMALLEST NO. SUCH THAT EPS + 1. .GT. 1.
!         U   = SMALLEST POSITIVE NO.   (UNDERFLOW LIMIT)
!         V   = LARGEST  NO.            (OVERFLOW  LIMIT)
!
!     Brief outline of algorithm..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     MOVE TO PHASE 2 WHEN A COMPONENT IS NONZERO AND .LE. cutlo
!     MOVE TO PHASE 3 WHEN A COMPONENT IS .GT. cutlo
!     MOVE TO PHASE 4 WHEN A COMPONENT IS .GE. cuthi/M
!     WHERE M = n FOR X() REAL AND M = 2*n FOR COMPLEX.
!
!     Values for cutlo and cuthi..
!     From the environmental parameters listed in the IMSL converter
!     document the limiting values are as follows..
!     cutlo, S.P.   U/EPS = 2**(-102) FOR  HONEYWELL.  CLOSE SECONDS ARE
!                   UNIVAC AND DEC AT 2**(-103)
!                   THUS cutlo = 2**(-51) = 4.44089E-16
!     cuthi, S.P.   V = 2**127 FOR UNIVAC, HONEYWELL, AND DEC.
!                   THUS cuthi = 2**(63.5) = 1.30438E19
!     cutlo, D.P.   U/EPS = 2**(-67) FOR HONEYWELL AND DEC.
!                   THUS cutlo = 2**(-33.5) = 8.23181D-11
!     cuthi, D.P.   SAME AS S.P.  cuthi = 1.30438D19
!     DATA cutlo, cuthi / 8.232D-11,  1.304D19 /
!     DATA cutlo, cuthi / 4.441E-16,  1.304E19 /
data cutlo, cuthi / 4.441e-16,  1.304e19 /
!
if(n .gt. 0) go to 10
   snrm2  = zero
   go to 300
!
10 assign 30 to next
sum = zero
nn = n * incx
!                                                 Begin main loop
i = 1
20 go to next,(30, 50, 70, 110)
30 if( abs(sx(i)) .gt. cutlo) go to 85
assign 50 to next
xmax = zero
!
!                        Phase 1.  Sum is zero
!
50 if( sx(i) .eq. zero) go to 200
if( abs(sx(i)) .gt. cutlo) go to 85
!
!                                Prepare for phase 2.
assign 70 to next
go to 105
!
!                                Prepare for phase 4.
!
100 i = j
assign 110 to next
sum = (sum / sx(i)) / sx(i)
105 xmax = abs(sx(i))
go to 115
!
!                   Phase 2.  Sum is small.
!                             Scale to avoid destructive underflow.
!
70 if( abs(sx(i)) .gt. cutlo ) go to 75
!
!                     Common code for phases 2 and 4.
!                     In phase 4 sum is large.  Scale to avoid overflow.
!
110 if( abs(sx(i)) .le. xmax ) go to 115
   sum = one + sum * (xmax / sx(i))**2
   xmax = abs(sx(i))
   go to 200
!
115 sum = sum + (sx(i)/xmax)**2
go to 200
!
!
!                  Prepare for phase 3.
!
75 sum = (sum * xmax) * xmax
!
!
!     FOR REAL OR D.P. SET hitest = cuthi/n
!     FOR COMPLEX      SET hitest = cuthi/(2*n)
!
85 hitest = cuthi/float( n )
!
!                   Phase 3.  Sum is mid-range.  No scaling.
!
do 95 j = i,nn,incx
if(abs(sx(j)) .ge. hitest) go to 100
95 sum = sum + sx(j)**2
snrm2 = sqrt( sum )
go to 300
!
200 continue
i = i + incx
if ( i .le. nn ) go to 20
!
!              END OF MAIN LOOP.
!
!              Compute square root and adjust for scaling.
!
snrm2 = xmax * sqrt(sum)
300 continue
return
end function snrm2

double precision function dnrm2 ( n, dx, incx)
implicit none
integer, intent(in) :: incx, n
integer :: i, j, nn
integer :: next
double precision, intent(in) :: dx(*)
double precision :: cutlo, cuthi, hitest, sum, xmax, zero, one
data   zero, one /0.0d0, 1.0d0/
!
!     Euclidean norm of the n-vector stored in dx() with storage
!     increment incx .
!     IF    n .LE. 0 RETURN WITH RESULT = 0.
!     IF n .GE. 1 THEN incx MUST BE .GE. 1
!
!           C.L.Lawson, 1978 jan 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     hopefully applicable to all machines.
!         cutlo = MAXIMUM OF  dsqrt(U/EPS)  OVER ALL KNOWN MACHINES.
!         cuthi = MINIMUM OF  dsqrt(V)      OVER ALL KNOWN MACHINES.
!     Where
!         EPS = SMALLEST NO. SUCH THAT EPS + 1. .GT. 1.
!         U   = SMALLEST POSITIVE NO.   (UNDERFLOW LIMIT)
!         V   = LARGEST  NO.            (OVERFLOW  LIMIT)
!
!     Brief outline of algorithm..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     MOVE TO PHASE 2 WHEN A COMPONENT IS NONZERO AND .LE. cutlo
!     MOVE TO PHASE 3 WHEN A COMPONENT IS .GT. cutlo
!     MOVE TO PHASE 4 WHEN A COMPONENT IS .GE. cuthi/M
!     WHERE M = n FOR X() REAL AND M = 2*n FOR COMPLEX.
!
!     Values for cutlo and cuthi..
!     From the environmental parameters listed in the IMSL converter
!     document the limiting values are as follows..
!     cutlo, S.P.   U/EPS = 2**(-102) FOR  HONEYWELL.  CLOSE SECONDS ARE
!                   UNIVAC AND DEC AT 2**(-103)
!                   THUS cutlo = 2**(-51) = 4.44089E-16
!     cuthi, S.P.   V = 2**127 FOR UNIVAC, HONEYWELL, AND DEC.
!                   THUS cuthi = 2**(63.5) = 1.30438E19
!     cutlo, D.P.   U/EPS = 2**(-67) FOR HONEYWELL AND DEC.
!                   THUS cutlo = 2**(-33.5) = 8.23181D-11
!     cuthi, D.P.   SAME AS S.P.  cuthi = 1.30438D19
!     DATA cutlo, cuthi / 8.232D-11,  1.304D19 /
!     DATA cutlo, cuthi / 4.441E-16,  1.304E19 /
data cutlo, cuthi / 8.232d-11,  1.304d19 /
!
if(n .gt. 0) go to 10
   dnrm2  = zero
   go to 300
!
10 assign 30 to next
sum = zero
nn = n * incx
!                                                 Begin main loop
i = 1
20 go to next,(30, 50, 70, 110)
30 if( dabs(dx(i)) .gt. cutlo) go to 85
assign 50 to next
xmax = zero
!
!                        Phase 1.  Sum is zero
!
50 if( dx(i) .eq. zero) go to 200
if( dabs(dx(i)) .gt. cutlo) go to 85
!
!                                Prepare for phase 2.
assign 70 to next
go to 105
!
!                                Prepare for phase 4.
!
100 i = j
assign 110 to next
sum = (sum / dx(i)) / dx(i)
105 xmax = dabs(dx(i))
go to 115
!
!                   Phase 2.  Sum is small.
!                             Scale to avoid destructive underflow.
!
70 if( dabs(dx(i)) .gt. cutlo ) go to 75
!
!                     Common code for phases 2 and 4.
!                     In phase 4 sum is large.  Scale to avoid overflow.
!
110 if( dabs(dx(i)) .le. xmax ) go to 115
   sum = one + sum * (xmax / dx(i))**2
   xmax = dabs(dx(i))
   go to 200
!
115 sum = sum + (dx(i)/xmax)**2
go to 200
!
!
!                  Prepare for phase 3.
!
75 sum = (sum * xmax) * xmax
!
!
!     FOR REAL OR D.P. SET hitest = cuthi/n
!     FOR COMPLEX      SET hitest = cuthi/(2*n)
!
85 hitest = cuthi/float( n )
!
!                   Phase 3.  Sum is mid-range.  No scaling.
!
do 95 j = i,nn,incx
if(dabs(dx(j)) .ge. hitest) go to 100
95 sum = sum + dx(j)**2
dnrm2 = dsqrt( sum )
go to 300
!
200 continue
i = i + incx
if ( i .le. nn ) go to 20
!
!              END OF MAIN LOOP.
!
!              Compute square root and adjust for scaling.
!
dnrm2 = xmax * dsqrt(sum)
300 continue
return
end function dnrm2

real function scnrm2( n, cx, incx)
implicit none
integer, intent(in) :: incx, n
integer :: i, nn
logical :: imag, scale
integer :: next
real :: cutlo, cuthi, hitest, sum, xmax, absx, zero, one
complex, intent(in) :: cx(*)
data         zero, one /0.0e0, 1.0e0/
!
!     Unitary norm of the complex n-vector stored in cx() with storage
!     increment incx .
!     IF    n .LE. 0 RETURN WITH RESULT = 0.
!     IF n .GE. 1 THEN incx MUST BE .GE. 1
!
!           C.L.Lawson , 1978 jan 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     hopefully applicable to all machines.
!         cutlo = MAXIMUM OF  sqrt(U/EPS)  OVER ALL KNOWN MACHINES.
!         cuthi = MINIMUM OF  sqrt(V)      OVER ALL KNOWN MACHINES.
!     Where
!         EPS = SMALLEST NO. SUCH THAT EPS + 1. .GT. 1.
!         U   = SMALLEST POSITIVE NO.   (UNDERFLOW LIMIT)
!         V   = LARGEST  NO.            (OVERFLOW  LIMIT)
!
!     Brief outline of algorithm..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     MOVE TO PHASE 2 WHEN A COMPONENT IS NONZERO AND .LE. cutlo
!     MOVE TO PHASE 3 WHEN A COMPONENT IS .GT. cutlo
!     MOVE TO PHASE 4 WHEN A COMPONENT IS .GE. cuthi/M
!     WHERE M = n FOR X() REAL AND M = 2*n FOR COMPLEX.
!
!     Values for cutlo and cuthi..
!     From the environmental parameters listed in the IMSL converter
!     document the limiting values are as follows..
!     cutlo, S.P.   U/EPS = 2**(-102) FOR  HONEYWELL.  CLOSE SECONDS ARE
!                   UNIVAC AND DEC AT 2**(-103)
!                   THUS cutlo = 2**(-51) = 4.44089E-16
!     cuthi, S.P.   V = 2**127 FOR UNIVAC, HONEYWELL, AND DEC.
!                   THUS cuthi = 2**(63.5) = 1.30438E19
!     cutlo, D.P.   U/EPS = 2**(-67) FOR HONEYWELL AND DEC.
!                   THUS cutlo = 2**(-33.5) = 8.23181D-11
!     cuthi, D.P.   SAME AS S.P.  cuthi = 1.30438D19
!     DATA cutlo, cuthi / 8.232D-11,  1.304D19 /
!     DATA cutlo, cuthi / 4.441E-16,  1.304E19 /
data cutlo, cuthi / 4.441e-16,  1.304e19 /
!
if(n .gt. 0) go to 10
   scnrm2  = zero
   go to 300
!
10 assign 30 to next
sum = zero
nn = n * incx
!                                                 Begin main loop
do 210 i = 1,nn,incx
   absx = abs(real(cx(i)))
   imag = .false.
   go to next,(30, 50, 70, 90, 110)
30 if( absx .gt. cutlo) go to 85
assign 50 to next
scale = .false.
!
!                        Phase 1.  Sum is zero
!
50 if( absx .eq. zero) go to 200
if( absx .gt. cutlo) go to 85
!
!                                Prepare for phase 2.
assign 70 to next
go to 105
!
!                                Prepare for phase 4.
!
100 assign 110 to next
sum = (sum / absx) / absx
105 scale = .true.
xmax = absx
go to 115
!
!                   Phase 2.  Sum is small.
!                             Scale to avoid destructive underflow.
!
70 if( absx .gt. cutlo ) go to 75
!
!                     Common code for phases 2 and 4.
!                     In phase 4 sum is large.  Scale to avoid overflow.
!
110 if( absx .le. xmax ) go to 115
   sum = one + sum * (xmax / absx)**2
   xmax = absx
   go to 200
!
115 sum = sum + (absx/xmax)**2
go to 200
!
!
!                  Prepare for phase 3.
!
75 sum = (sum * xmax) * xmax
!
85 assign 90 to next
scale = .false.
!
!     FOR REAL OR D.P. SET hitest = cuthi/n
!     FOR COMPLEX      SET hitest = cuthi/(2*n)
!
hitest = cuthi/float( n )
hitest = hitest * 0.5
!
!                   Phase 3.  Sum is mid-range.  No scaling.
!
90 if(absx .ge. hitest) go to 100
   sum = sum + absx**2
200 continue
!                  Control selection of real and imaginary parts.
!
if(imag) go to 210
   absx = abs(aimag(cx(i)))
   imag = .true.
go to next,(  50, 70, 90, 110 )
!
210 continue
!
!              END OF MAIN LOOP.
!              Compute square root and adjust for scaling.
!
scnrm2 = sqrt(sum)
if(scale) scnrm2 = scnrm2 * xmax
300 continue
return
end function scnrm2

integer function isamax(n,sx,incx)
implicit none
!
!     Finds the index of element having max. Absolute value.
!     Jack dongarra, LINPACK, 3/11/78.
!
real, intent(in) :: sx(*)
real :: smax
integer :: i
integer, intent(in) :: incx
integer :: ix
integer, intent(in) :: n
!
isamax = 0
if( n .lt. 1 ) return
isamax = 1
if(n.eq.1)return
if(incx.eq.1)go to 20
!
!        Code for increment not equal to 1
!
ix = 1
smax = abs(sx(1))
ix = ix + incx
do i = 2,n
   if(abs(sx(ix)).le.smax) go to 5
   isamax = i
   smax = abs(sx(ix))
5 ix = ix + incx
end do
return
!
!        Code for increment equal to 1
!
20 smax = abs(sx(1))
do 30 i = 2,n
   if(abs(sx(i)).le.smax) go to 30
   isamax = i
   smax = abs(sx(i))
30 continue
return
end function isamax

integer function idamax(n,dx,incx)
implicit none
!
!     Finds the index of element having max. Absolute value.
!     Jack dongarra, LINPACK, 3/11/78.
!
double precision, intent(in) :: dx(*)
double precision :: dmax
integer :: i
integer, intent(in) :: incx
integer :: ix
integer, intent(in) :: n
!
idamax = 0
if( n .lt. 1 ) return
idamax = 1
if(n.eq.1)return
if(incx.eq.1)go to 20
!
!        Code for increment not equal to 1
!
ix = 1
dmax = dabs(dx(1))
ix = ix + incx
do i = 2,n
   if(dabs(dx(ix)).le.dmax) go to 5
   idamax = i
   dmax = dabs(dx(ix))
5 ix = ix + incx
end do
return
!
!        Code for increment equal to 1
!
20 dmax = dabs(dx(1))
do 30 i = 2,n
   if(dabs(dx(i)).le.dmax) go to 30
   idamax = i
   dmax = dabs(dx(i))
30 continue
return
end function idamax

integer function icamax(n,cx,incx)
implicit none
!
!     Finds the index of element having max. Absolute value.
!     Jack dongarra, LINPACK, 3/11/78.
!
complex :: cx(*)
real :: smax
integer :: i
integer, intent(in) :: incx
integer :: ix
integer, intent(in) :: n
complex :: zdum
real :: cabs1
cabs1(zdum) = abs(real(zdum)) + abs(aimag(zdum))
!
icamax = 0
if( n .lt. 1 ) return
icamax = 1
if(n.eq.1)return
if(incx.eq.1)go to 20
!
!        Code for increment not equal to 1
!
ix = 1
smax = cabs1(cx(1))
ix = ix + incx
do i = 2,n
   if(cabs1(cx(ix)).le.smax) go to 5
   icamax = i
   smax = cabs1(cx(ix))
5 ix = ix + incx
end do
return
!
!        Code for increment equal to 1
!
20 smax = cabs1(cx(1))
do 30 i = 2,n
   if(cabs1(cx(i)).le.smax) go to 30
   icamax = i
   smax = cabs1(cx(i))
30 continue
return
end function icamax

subroutine mcvfs(a,ka,n,b)
implicit none
integer, intent(in) :: ka, n
integer :: i, j, l
real, intent(in) :: a(ka,n)
real, intent(inout) :: b(*)
!
l = 0
do j = 1,n
   do 10 i = 1,j
   l = l + 1
10 b(l) = a(i,j)
end do
return
end subroutine mcvfs

subroutine dmcvfs(a,ka,n,b)
implicit none
integer, intent(in) :: ka, n
integer :: i, j, l
double precision, intent(in) :: a(ka,n)
double precision, intent(inout) :: b(*)
!
l = 0
do j = 1,n
   do 10 i = 1,j
   l = l + 1
10 b(l) = a(i,j)
end do
return
end subroutine dmcvfs

subroutine mcvsf(a,ka,n,b)
implicit none
integer, intent(in) :: ka, n
integer :: i, ii, im1, j, jj, l
real, intent(inout) :: a(ka,n)
real, intent(in) :: b(*)
!
a(1,1) = b(1)
if (n .lt. 2) return
l = (n*(n + 1))/2
!
j = n
do 11 jj = 2,n
i = j
   do 10 ii = 1,j
   a(i,j) = b(l)
   i = i - 1
10 l = l - 1
11 j = j - 1
!
do i = 2,n
im1 = i - 1
   do 20 j = 1,im1
20 a(i,j) = a(j,i)
end do
return
end subroutine mcvsf

subroutine dmcvsf(a,ka,n,b)
implicit none
integer, intent(in) :: ka, n
integer :: i, ii, im1, j, jj, l
double precision, intent(inout) :: a(ka,n)
double precision, intent(in) :: b(*)
!
a(1,1) = b(1)
if (n .lt. 2) return
l = (n*(n + 1))/2
!
j = n
do 11 jj = 2,n
i = j
   do 10 ii = 1,j
   a(i,j) = b(l)
   i = i - 1
10 l = l - 1
11 j = j - 1
!
do i = 2,n
im1 = i - 1
   do 20 j = 1,im1
20 a(i,j) = a(j,i)
end do
return
end subroutine dmcvsf

