!
l = 1
do 20 k = 2,n
km1 = k - 1
xk = x(k)
yk = 0.d0
!
do 10 i = 1,km1
l = l + 1
y(i) = y(i) + a(l)*xk
10 yk = yk + a(l)*x(i)
!
l = l + 1
20 y(k) = yk + a(l)*xk
return
end subroutine dsvprd

