if (ml .eq. 0) go to 30
l = ml
do i = 1,ml
   jmax = min0(n,i + mu)
   j = jmax
   do 10 jj = 1,jmax
      k = j + l
      b(i,k) = a(i,j)
10 j = j - 1
   l = l - 1
end do
!
!     Insert zeros in the upper left corner
!
imax = ml
do j = 1,ml
   do 20 i = 1,imax
20 b(i,j) = 0.0
   imax = imax - 1
end do
!
!     Store the remaining nonzero data
!
30 imin = ml + 1
imax = min0(m,ml + n)
do i = imin,imax
   jmin = i - ml
   jmax = min0(n,i + mu)
   k = 0
   do 31 j = jmin,jmax
      k = k + 1
31 b(i,k) = a(i,j)
end do
!
!     Insert zeros in the lower right corner
!
jmax = ml + mu + 1
if (k .eq. jmax) go to 50
jmin = k + 1
imin = imax
do j = jmin,jmax
   do 40 i = imin,imax
40 b(i,j) = 0.0
   imin = imin - 1
end do
!
!     Store zeros in the final m-imax rows
!
50 if (imax .eq. m) return
imin = imax + 1
do j = 1,jmax
   do 51 i = imin,m
51 b(i,j) = 0.0
end do
return
end subroutine cvrb

subroutine cvrb1 (a,ka,m,n,ml,mu,b,kb,nb,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, m
integer, intent(inout) :: ml, mu
integer, intent(in) :: n, nb
integer :: i, imax, imin, j, jmax, jmin, kmax, l, mm1, nm1
!-----------------------------------------------------------------------
!           Conversion of real matrices from standard
!                        to banded form
!-----------------------------------------------------------------------
real, intent(in) :: a(ka,n)
real, intent(inout) :: b(kb,nb)
!
!     Computation of ml and mu
!
nm1 = n - 1
imin = m
if (m .eq. 1) go to 20
do l = 2,m
   j = 1
   imax = min0(m,imin + nm1)
   do 10 i = imin,imax
      if (a(i,j) .ne. 0.0) go to 20
10 j = j + 1
   imin = imin - 1
end do
!
20 mm1 = m - 1
jmin = n
if (n .eq. 1) go to 30
do l = 2,n
   i = 1
   jmax = min0(n,jmin + mm1)
   do 21 j = jmin,jmax
      if (a(i,j) .ne. 0.0) go to 30
21 i = i + 1
   jmin = jmin - 1
end do
!
30 ml = imin - 1
mu = jmin - 1
kmax = ml + mu + 1
if (kmax .gt. nb) go to 40
!
!     Store the matrix in b
!
ierr = 0
call cvrb (a,ka,m,n,ml,mu,b,kb)
return
!
!     Error return
!
40 ierr = kmax
return
end subroutine cvrb1

