subroutine bcvrd (a, ka, m, n, ml, mu, b, kb)
implicit none
integer, intent(in) :: ka, kb, m, ml, mu, n
integer :: i, j, num
!-----------------------------------------------------------------------
!        Conversion of banded matrices from single to double
!                          precision form
!-----------------------------------------------------------------------
real, intent(in) :: a(ka,*)
double precision, intent(inout) :: b(kb,*)
!
num = ml + mu + 1
do j = 1,num
   do i = 1,m
      b(i,j) = a(i,j)
   end do
end do
return
end subroutine bcvrd

