subroutine breal (a, ka, m, n, ml, mu, b, kb, l, nl, nu, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, l, m, ml, mu, n
integer, intent(out) :: nl
integer, intent(inout) :: nu
integer :: i, imin, j, k, num
!-----------------------------------------------------------------------
!              Real part of a banded complex matrix
!-----------------------------------------------------------------------
complex, intent(in) :: a(ka,*)
real, intent(inout) :: b(kb,l)
!
!     Computation of nl and nu
!
nl = ml
if (ml .eq. 0) go to 30
imin = ml + 1
do j = 1,ml
   do i = imin,m
      if (real(a(i,j)) .ne. 0.0) go to 30
   end do
   nl = nl - 1
   imin = imin - 1
end do
!
30 nu = mu
if (mu .eq. 0) go to 60
j = ml + mu + 1
do k = 1,mu
   do i = 1,m
      if (real(a(i,j)) .ne. 0.0) go to 60
   end do
   nu = nu - 1
   j = j - 1
end do
!
!     Store the real part of A in b
!
60 num = nl + nu + 1
if (num .gt. l) go to 100
ierr = 0
k = ml - nl
do j = 1,num
   k = k + 1
   do i = 1,m
      b(i,j) = real(a(i,k))
   end do
end do
return
!
!     Error return
!
100 ierr = num
return
end subroutine breal

subroutine bimag (a, ka, m, n, ml, mu, b, kb, l, nl, nu, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, l, m, ml, mu, n
integer, intent(out) :: nl
integer, intent(inout) :: nu
integer :: i, imin, j, k, num
!-----------------------------------------------------------------------
!            Imaginary part of a banded complex matrix
!-----------------------------------------------------------------------
complex, intent(in) :: a(ka,*)
real, intent(inout) :: b(kb,l)
!
!     Computation of nl and nu
!
nl = ml
if (ml .eq. 0) go to 30
imin = ml + 1
do j = 1,ml
   do i = imin,m
      if (aimag(a(i,j)) .ne. 0.0) go to 30
   end do
   nl = nl - 1
   imin = imin - 1
end do
!
30 nu = mu
if (mu .eq. 0) go to 60
j = ml + mu + 1
do k = 1,mu
   do i = 1,m
      if (aimag(a(i,j)) .ne. 0.0) go to 60
   end do
   nu = nu - 1
   j = j - 1
end do
!
!     Store the imaginary part of A in b
!
60 num = nl + nu + 1
if (num .gt. l) go to 100
ierr = 0
k = ml - nl
do j = 1,num
   k = k + 1
   do i = 1,m
      b(i,j) = aimag(a(i,k))
   end do
end do
return
!
!     Error return
!
100 ierr = num
return
end subroutine bimag

subroutine bcvrc (m,n,a,ka,ml,mu,b,kb,nl,nu,c,kc,l,mcl,mcu,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, kc, l, m
integer, intent(out) :: mcl, mcu
integer, intent(in) :: ml, mu, n, nl, nu
integer :: i, j, ja, jb, jc, jmax, k, num
!-----------------------------------------------------------------------
!        Compute a + BI for the banded real matrices A and b
!-----------------------------------------------------------------------
real, intent(in) :: a(ka,*), b(kb,*)
complex, intent(inout) :: c(kc,l)
!
mcl = max0(ml,nl)
mcu = max0(mu,nu)
num = mcl + mcu + 1
if (num .gt. l) go to 200
!
ierr = 0
k = min0(mu,nu) + 1
!
!     Insert the first abs(ml - nl) diagonals
!
if (nl .ge. ml) go to 30
ja = ml - nl
jb = 0
jc = ja
jmax = nl + k
do j = 1,jc
   do i = 1,m
      c(i,j) = cmplx(a(i,j),0.0)
   end do
end do
go to 60
!
30 ja = 0
jb = nl - ml
jc = jb
jmax = ml + k
if (jc .eq. 0) go to 60
do j = 1,jc
   do i = 1,m
      c(i,j) = cmplx(0.0,b(i,j))
   end do
end do
!
!     Addition of the common diagonals
!
60 do j = 1,jmax
   ja = ja + 1
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = cmplx(a(i,ja),b(i,jb))
   end do
end do
!
!     Insertion of the remaining diagonals
!
if (nu .ge. mu) go to 120
jmax = mu - nu
do j = 1,jmax
   ja = ja + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = cmplx(a(i,ja),0.0)
   end do
end do
return
!
120 jmax = nu - mu
if (jmax .eq. 0) return
do j = 1,jmax
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = cmplx(0.0,b(i,jb))
   end do
end do
return
!
!     Error return
!
200 ierr = num
return
end subroutine bcvrc

subroutine bpose (a, ka, m, n, ml, mu, b, kb)
implicit none
integer, intent(in) :: ka, kb, m, ml, mu, n
integer :: i, imax, imin, j, jmin, k, l, lj, lp1, ndiag
!-----------------------------------------------------------------------
!                Transposition of real banded matrices
!-----------------------------------------------------------------------
real, intent(in) :: a(ka,*)
real, intent(inout) :: b(kb,*)
!
l = ml + mu + 1
lp1 = l + 1
if (mu .eq. 0) go to 40
!
!     Define the first mu columns of b
!
ndiag = mu
do 31 j = 1,mu
   do i = 1,ndiag
      b(i,j) = 0.0
   end do
!
   lj = lp1 - j
   imax = min0(m,n - ndiag)
   do i = 1,imax
      k = ndiag + i
      b(k,j) = a(i,lj)
   end do
!
   if (k .eq. n) go to 31
   imin = k + 1
   do i = imin,n
      b(i,j) = 0.0
   end do
31 ndiag = ndiag - 1
!
!     Define the remaining columns of b
!
40 jmin = mu + 1
ndiag = 0
do 61 j = jmin,l
   lj = lp1 - j
   imax = min0(m - ndiag,n)
   do i = 1,imax
      k = ndiag + i
      b(i,j) = a(k,lj)
   end do
!
   if (imax .eq. n) go to 61
   imin = imax + 1
   do i = imin,n
      b(i,j) = 0.0
   end do
61 ndiag = ndiag + 1
return
end subroutine bpose

subroutine dbpose (a, ka, m, n, ml, mu, b, kb)
implicit none
integer, intent(in) :: ka, kb, m, ml, mu, n
integer :: i, imax, imin, j, jmin, k, l, lj, lp1, ndiag
!-----------------------------------------------------------------------
!          Transposition of double precision banded matrices
!-----------------------------------------------------------------------
double precision, intent(in) :: a(ka,*)
double precision, intent(inout) :: b(kb,*)
!
l = ml + mu + 1
lp1 = l + 1
if (mu .eq. 0) go to 40
!
!     Define the first mu columns of b
!
ndiag = mu
do 31 j = 1,mu
   do i = 1,ndiag
      b(i,j) = 0.d0
   end do
!
   lj = lp1 - j
   imax = min0(m,n - ndiag)
   do i = 1,imax
      k = ndiag + i
      b(k,j) = a(i,lj)
   end do
!
   if (k .eq. n) go to 31
   imin = k + 1
   do i = imin,n
      b(i,j) = 0.d0
   end do
31 ndiag = ndiag - 1
!
!     Define the remaining columns of b
!
40 jmin = mu + 1
ndiag = 0
do 61 j = jmin,l
   lj = lp1 - j
   imax = min0(m - ndiag,n)
   do i = 1,imax
      k = ndiag + i
      b(i,j) = a(k,lj)
   end do
!
   if (imax .eq. n) go to 61
   imin = imax + 1
   do i = imin,n
      b(i,j) = 0.d0
   end do
61 ndiag = ndiag + 1
return
end subroutine dbpose

subroutine cbpose (a, ka, m, n, ml, mu, b, kb)
implicit none
integer, intent(in) :: ka, kb, m, ml, mu, n
integer :: i, imax, imin, j, jmin, k, l, lj, lp1, ndiag
!-----------------------------------------------------------------------
!              Transposition of complex banded matrices
!-----------------------------------------------------------------------
complex, intent(in) :: a(ka,*)
complex, intent(inout) :: b(kb,*)
!
l = ml + mu + 1
lp1 = l + 1
if (mu .eq. 0) go to 40
!
!     Define the first mu columns of b
!
ndiag = mu
do 31 j = 1,mu
   do i = 1,ndiag
      b(i,j) = (0.0,0.0)
   end do
!
   lj = lp1 - j
   imax = min0(m,n - ndiag)
   do i = 1,imax
      k = ndiag + i
      b(k,j) = a(i,lj)
   end do
!
   if (k .eq. n) go to 31
   imin = k + 1
   do i = imin,n
      b(i,j) = (0.0,0.0)
   end do
31 ndiag = ndiag - 1
!
!     Define the remaining columns of b
!
40 jmin = mu + 1
ndiag = 0
do 61 j = jmin,l
   lj = lp1 - j
   imax = min0(m - ndiag,n)
   do i = 1,imax
      k = ndiag + i
      b(i,j) = a(k,lj)
   end do
!
   if (imax .eq. n) go to 61
   imin = imax + 1
   do i = imin,n
      b(i,j) = (0.0,0.0)
   end do
61 ndiag = ndiag + 1
return
end subroutine cbpose

subroutine badd (m,n,a,ka,ml,mu,b,kb,nl,nu,c,kc,l,mcl,mcu,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ka, kb, kc, l, m
integer, intent(inout) :: mcl, mcu
integer, intent(in) :: ml, mu, n, nl, nu
integer :: i, imin, j, ja, jb, jc, jmax, la, lb, num
!-----------------------------------------------------------------------
