      kmax = min0(n,i + mu,j + nl)
      kk = mlp1 - i + kmin
      jj = nlp1 + j - kmin
      do k = kmin,kmax
         sum = sum + a(i,kk)*b(k,jj)
         kk = kk + 1
         jj = jj - 1
      end do
      c(i,jc) = sum
   end do
end do
!
!     Find the last nonzero upper diagonal
!
100 jc = jc + 1
mcu = min0(l - 1,mu + nu)
if (mcu .eq. 0) go to 130
!
maxd = mcu
do ndiag = 1,maxd
   jmi = maxd + 1 - ndiag
   imax = min0(m,l - jmi,npml,npnu - jmi)
   do i = 1,imax
      j = i + jmi
      sum = 0.0
      kmin = max0(1,i - ml,j - nu)
      kmax = min0(n,i + mu,j + nl)
      kk = mlp1 - i + kmin
      jj = nlp1 + j - kmin
      do k = kmin,kmax
         sum = sum + a(i,kk)*b(k,jj)
         kk = kk + 1
         jj = jj - 1
      end do
      c(i,jc) = sum
   end do
!
   do i = 1,imax
      if (c(i,jc) .ne. 0.0) go to 130
   end do
   mcu = mcu - 1
end do
!
130 last = mcl + mcu + 1
if (last .gt. nc) go to 200
if (mcu .eq. 0) go to 140
do i = 1,imax
   c(i,last) = c(i,jc)
   c(i,jc) = 0.0
end do
!
!     Compute the main diagonal and the remaining upper diagonals
!
140 maxd = max0(1,mcu)
do ndiag = 1,maxd
   jmi = ndiag - 1
   imax = min0(m,l - jmi,npml,npnu - jmi)
   do i = 1,imax
      j = i + jmi
      sum = 0.0
