subroutine bvprd (m,n,a,ka,ml,mu,x,y)
implicit none
integer, intent(in) :: ka, m, ml, mu, n
integer :: i, imax, imin, jmin, k, kk, kmax, kmin, mlp1
real :: sum
!-----------------------------------------------------------------------
!         Product of a real banded matrix and a real vector
!-----------------------------------------------------------------------
real, intent(in) :: a(ka,*), x(n)
real, intent(inout) :: y(m)
!
!     Compute the first ml components
!
mlp1 = ml + 1
if (ml .eq. 0) go to 20
jmin = mlp1
do i = 1,ml
   kmax = min0(n,i + mu)
   kk = jmin
   sum = 0.0
   do k = 1,kmax
      sum = sum + a(i,kk)*x(k)
      kk = kk + 1
   end do
   y(i) = sum
   jmin = jmin - 1
end do
!
!     Compute the remaining nonzero components
!
20 imax = min0(m,n + ml)
do i = mlp1,imax
   kmin = i - ml
   kmax = min0(n,i + mu)
   kk = 1
   sum = 0.0
   do k = kmin,kmax
      sum = sum + a(i,kk)*x(k)
      kk = kk + 1
   end do
   y(i) = sum
end do
!
!     Store zeros in the final m-imax components
!
if (imax .eq. m) return
imin = imax + 1
do i = imin,m
   y(i) = 0.0
end do
return
end subroutine bvprd

