!-----------------------------------------------------------------------
!        SETTING y = x*a + y WHERE A IS A REAL BANDED MATRIX
!                     and x,y are real vectors
!-----------------------------------------------------------------------
real, intent(in) :: a(ka,*), x(m)
real, intent(inout) :: y(n)
!
!     Compute the first mu components
!
if (mu .eq. 0) go to 20
do j = 1,mu
   jj = ml + j
   kmax = min0(m,jj)
   sum = y(j)
   do k = 1,kmax
      sum = sum + a(k,jj)*x(k)
      jj = jj - 1
   end do
   y(j) = sum
end do
!
!     Compute the remaining components
!
20 num = ml + mu + 1
jmin = mu + 1
jmax = min0(n,m + mu)
do j = jmin,jmax
   kmin = j - mu
   kmax = min0(m,j + ml)
   jj = num
   sum = y(j)
   do k = kmin,kmax
      sum = sum + a(k,jj)*x(k)
      jj = jj - 1
   end do
   y(j) = sum
end do
return
end subroutine btprd1

subroutine dbtpd (m,n,a,ka,ml,mu,x,y)
implicit none
integer, intent(in) :: ka, m, ml, mu, n
integer :: j, jj, jmax, jmin, k, kmax, kmin, num
!-----------------------------------------------------------------------
!              Product of a double precision vector and
!                  a double precision banded matrix
!-----------------------------------------------------------------------
double precision, intent(in) :: a(ka,*), x(m)
double precision, intent(inout) :: y(n)
double precision :: sum
!
!     Compute the first mu components
!
if (mu .eq. 0) go to 20
do j = 1,mu
   jj = ml + j
   kmax = min0(m,jj)
   sum = 0.d0
   do k = 1,kmax
      sum = sum + a(k,jj)*x(k)
      jj = jj - 1
   end do
   y(j) = sum
end do
!
!     Compute the remaining nonzero components
!
20 num = ml + mu + 1
jmin = mu + 1
jmax = min0(n,m + mu)
do j = jmin,jmax
   kmin = j - mu
   kmax = min0(m,j + ml)
   jj = num
   sum = 0.d0
   do k = kmin,kmax
      sum = sum + a(k,jj)*x(k)
      jj = jj - 1
   end do
   y(j) = sum
end do
!
!     Store zeros in the final n-jmax components
!
if (jmax .eq. n) return
jmin = jmax + 1
do j = jmin,n
   y(j) = 0.d0
end do
return
end subroutine dbtpd

