!
20 ierr = i
return
end subroutine cvcs

subroutine cvsr (a, ia, ja, b, kb, m, n)
implicit none
integer, intent(in) :: kb, m, n
integer :: i, ip, ipmax, ipmin, j
real, intent(in) :: a(*)
real, intent(inout) :: b(kb,n)
integer, intent(in) :: ia(*), ja(*)
!
do 30 i = 1,m
!
!                 Clear the i-TH row
!
   do j = 1,n
      b(i,j) = 0.0
   end do
!
!                 Store the i-TH row
!
   ipmin = ia(i)
   ipmax = ia(i+1) - 1
   if (ipmin .gt. ipmax) go to 30
   do ip = ipmin,ipmax
      j = ja(ip)
      b(i,j) = a(ip)
   end do
!
30 continue
return
end subroutine cvsr

