subroutine csreal (a, ia, ja, b, ib, jb, m)
implicit none
integer, intent(in) :: m
integer :: i, ibeg, iend, ip, l
real :: t
!-----------------------------------------------------------------------
!              Real part of a sparse complex matrix
!-----------------------------------------------------------------------
complex, intent(in) :: a(*)
real, intent(inout) :: b(*)
integer, intent(in) :: ia(*), ja(*)
integer, intent(inout) :: ib(*), jb(*)
!
l = 1
do 20 i = 1,m
   ib(i) = l
   ibeg = ia(i)
   iend = ia(i+1) - 1
   if (ibeg .gt. iend) go to 20
   do 10 ip = ibeg,iend
      t = real(a(ip))
      if (t .eq. 0.0) go to 10
      b(l) = t
      jb(l) = ja(ip)
      l = l + 1
10 continue
20 continue
ib(m + 1) = l
return
end subroutine csreal

subroutine csimag (a, ia, ja, b, ib, jb, m)
implicit none
integer, intent(in) :: m
integer :: i, ibeg, iend, ip, l
real :: t
!-----------------------------------------------------------------------
!            Imaginary part of a sparse complex matrix
!-----------------------------------------------------------------------
complex, intent(in) :: a(*)
real, intent(inout) :: b(*)
integer, intent(in) :: ia(*), ja(*)
integer, intent(inout) :: ib(*), jb(*)
!
l = 1
do 20 i = 1,m
   ib(i) = l
   ibeg = ia(i)
   iend = ia(i+1) - 1
   if (ibeg .gt. iend) go to 20
   do 10 ip = ibeg,iend
      t = aimag(a(ip))
      if (t .eq. 0.0) go to 10
      b(l) = t
      jb(l) = ja(ip)
      l = l + 1
10 continue
20 continue
ib(m + 1) = l
return
end subroutine csimag

subroutine scvrc (a,ia,ja,b,ib,jb,c,ic,jc,m,n,num,wk,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: m, n, num
integer :: i, ip, j, l, maxa, maxb, mina, minb
!-----------------------------------------------------------------------
!       Compute a + BI for the sparse real matrices A and b
!-----------------------------------------------------------------------
real, intent(in) :: a(*), b(*)
real, intent(inout) :: wk(n)
complex, intent(inout) :: c(*)
complex :: t
integer, intent(in) :: ia(*), ja(*), ib(*), jb(*)
integer, intent(inout) :: ic(*), jc(*)
!-------------------------
do j = 1,n
   wk(j) = 0.0
end do
!
!                  Compute the i-TH row of c
!
ip = 1
do 42 i = 1,m
   ic(i) = ip
   mina = ia(i)
   maxa = ia(i+1) - 1
   if (mina .gt. maxa) go to 30
   do l = mina,maxa
      j = ja(l)
      wk(j) = a(l)
   end do
!
30 minb = ib(i)
   maxb = ib(i+1) - 1
   if (minb .gt. maxb) go to 40
   do 31 l = minb,maxb
      if (b(l) .eq. 0.0) go to 31
      j = jb(l)
      t = cmplx (wk(j), b(l))
      wk(j) = 0.0
      if (ip .gt. num) go to 50
      c(ip) = t
      jc(ip) = j
      ip = ip + 1
31 continue
!
40 if (mina .gt. maxa) go to 42
   do 41 l = mina,maxa
      j = ja(l)
      if (wk(j) .eq. 0.0) go to 41
      if (ip .gt. num) go to 50
      c(ip) = cmplx (wk(j), 0.0)
      wk(j) = 0.0
      jc(ip) = j
      ip = ip + 1
41 continue
42 continue
ic(m + 1) = ip
ierr = 0
return
!
!                        Error return
!
50 ierr = i
return
end subroutine scvrc

subroutine rscopy (a, ia, ja, b, ib, jb, m)
implicit none
integer, intent(in) :: m
integer :: i, ibeg, iend, ip, l
!-----------------------------------------------------------------------
!                  Copying a sparse real matrix
!-----------------------------------------------------------------------
real, intent(in) :: a(*)
real, intent(inout) :: b(*)
integer, intent(in) :: ia(*), ja(*)
integer, intent(inout) :: ib(*), jb(*)
!
l = 1
do 20 i = 1,m
   ib(i) = l
   ibeg = ia(i)
   iend = ia(i+1) - 1
   if (ibeg .gt. iend) go to 20
   do 10 ip = ibeg,iend
      if (a(ip) .eq. 0.0) go to 10
      b(l) = a(ip)
      jb(l) = ja(ip)
      l = l + 1
10 continue
20 continue
ib(m + 1) = l
return
end subroutine rscopy

