   ic(i) = ip
   mina = ia(i)
   maxa = ia(i+1) - 1
   if (mina .gt. maxa) go to 30
   do l = mina,maxa
      j = ja(l)
      wk(j) = a(l)
   end do
!
30 minb = ib(i)
   maxb = ib(i+1) - 1
   if (minb .gt. maxb) go to 40
   do 31 l = minb,maxb
      j = jb(l)
      t = wk(j) - b(l)
      wk(j) = 0.d0
      if (t .eq. 0.d0) go to 31
      if (ip .gt. num) go to 50
      c(ip) = t
      jc(ip) = j
      ip = ip + 1
31 continue
!
40 if (mina .gt. maxa) go to 42
   do 41 l = mina,maxa
      j = ja(l)
      if (wk(j) .eq. 0.d0) go to 41
      if (ip .gt. num) go to 50
      c(ip) = wk(j)
      wk(j) = 0.d0
      jc(ip) = j
      ip = ip + 1
41 continue
42 continue
ic(m + 1) = ip
ierr = 0
return
!
!                        Error return
!
50 ierr = i
return
end subroutine dssubt

