subroutine balanc(nm,n,a,low,igh,scale)
implicit none
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: jj
integer, intent(in) :: nm
integer, intent(inout) :: igh, low
integer :: iexc
real, intent(inout) :: a(nm,n), scale(n)
real :: c, f, g, r, s, b2, radix
integer :: ipmpar
!     real abs
logical :: noconv
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure balance,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.II-linear algebra, 315-326(1971).
!
!     This subroutine balances a real matrix and isolates
!     eigenvalues whenever possible.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        A contains the input matrix to be balanced.
!
!     On output-
!
!        A contains the balanced matrix,
!
!        Low and igh are two integers such that a(i,j)
!          is equal to zero if
!           (1) i is greater than j and
!           (2) j=1,...,low-1 OR i=igh+1,...,n,
!
!        Scale contains information determining the
!           permutations and scaling factors used.
!
!     Suppose that the principal submatrix in rows low through igh
!     has been balanced, that P(j) denotes the index interchanged
!     with j during the permutation step, and that the elements
!     of the diagonal matrix used are denoted by D(i,j).  Then
!        scale(j) = P(j),    FOR j = 1,...,low-1
!                 = D(j,j),      j = low,...,igh
!                 = P(j)         j = igh+1,...,n.
!     The order in which the interchanges are made is n to igh+1,
!     then 1 to low-1.
!
!     Note that 1 is returned for igh if igh is zero formally.
!
!     The Algol procedure exc contained in balance appears in
!     balanc  in line.  (Note that the Algol roles of identifiers
!     k,l have been reversed.)
!
!-----------------------------------------------------------------------
!
!     ********** radix IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                the base of the machine floating point representation.
!
           radix = ipmpar(4)
!
!                **********
!
b2 = radix * radix
k = 1
l = n
go to 100
!     ********** IN-LINE PROCEDURE FOR ROW AND
!                COLUMN EXCHANGE **********
20 scale(m) = j
if (j .eq. m) go to 50
!
do i = 1, l
   f = a(i,j)
   a(i,j) = a(i,m)
   a(i,m) = f
end do
!
do i = k, n
   f = a(j,i)
   a(j,i) = a(m,i)
   a(m,i) = f
end do
!
50 go to (80,130), iexc
!     ********** SEARCH FOR ROWS ISOLATING AN EIGENVALUE
!                AND PUSH THEM DOWN **********
80 if (l .eq. 1) go to 280
l = l - 1
!     ********** FOR j=l STEP -1 UNTIL 1 DO -- **********
100 do 120 jj = 1, l
   j = l + 1 - jj
!
   do 110 i = 1, l
      if (i .eq. j) go to 110
      if (a(j,i) .ne. 0.0) go to 120
110 continue
!
   m = l
   iexc = 1
   go to 20
120 continue
!
go to 140
!     ********** SEARCH FOR COLUMNS ISOLATING AN EIGENVALUE
!                AND PUSH THEM LEFT **********
130 k = k + 1
!
140 do 170 j = k, l
!
   do 150 i = k, l
      if (i .eq. j) go to 150
      if (a(i,j) .ne. 0.0) go to 170
150 continue
!
   m = k
   iexc = 2
   go to 20
170 continue
!     ********** NOW BALANCE THE SUBMATRIX IN ROWS k TO l **********
do 180 i = k, l
180 scale(i) = 1.0
!     ********** ITERATIVE LOOP FOR NORM REDUCTION **********
190 noconv = .false.
!
do 270 i = k, l
   c = 0.0
   r = 0.0
!
   do 200 j = k, l
      if (j .eq. i) go to 200
      c = c + abs(a(j,i))
      r = r + abs(a(i,j))
200 continue
!     ********** GUARD AGAINST ZERO c OR r DUE TO UNDERFLOW **********
   if (c .eq. 0.0 .or. r .eq. 0.0) go to 270
   g = r / radix
   f = 1.0
   s = c + r
210 if (c .ge. g) go to 220
   f = f * radix
   c = c * b2
   go to 210
220 g = r * radix
230 if (c .lt. g) go to 240
   f = f / radix
   c = c / b2
   go to 230
!     ********** NOW BALANCE **********
240 if ((c + r) / f .ge. 0.95 * s) go to 270
   g = 1.0 / f
   scale(i) = scale(i) * f
   noconv = .true.
!
   do 250 j = k, n
250 a(i,j) = a(i,j) * g
!
   do 260 j = 1, l
260 a(j,i) = a(j,i) * f
!
270 continue
!
if (noconv) go to 190
!
280 low = k
igh = l
return
end subroutine balanc

subroutine balinv (nz,n,z,low,igh,scale)
implicit none
integer :: i, j, k
integer, intent(in) :: n
integer :: ii
integer, intent(in) :: nz, igh, low
real, intent(inout) :: z(nz,n)
real, intent(in) :: scale(n)
real :: s
!-----------------------------------------------------------------------
!        Given A matrix A of order n. balanc transforms A into
!     the matrix B by the similarity transformation
!             b = d**(-1)*transpose(p)*a*p*d
!     where D is a diagonal matrix and P a permutation matrix.
!     The information concerning D and P is stored in igh, low,
!     and scale. The order in which the interchanges were made
!     is n to igh + 1, and then 1 to low - 1.
!
!        z is a matrix of order n. balinv transforms z into the
!     matrix W using the inverse similarity transform
!             w = p*d*z*d**(-1)*transpose(p)
!
!     On input-
!
!        nz is the row dimension of the matrix z in the calling
!          program,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by  balanc,
!
!        Scale contains information determining the permutations
!          and scaling factors used by  balanc,
!
!     On output-
!
!        z contains the transformed matrix W
!
!-----------------------------------------------------------------------
!
if (igh .eq. low) go to 30
!
do i = low, igh
s = scale(i)
   do 10 j = 1, n
10 z(i,j) = z(i,j) * s
end do
!
do j = low, igh
s = 1.0/scale(j)
   do 20 i = 1, n
20 z(i,j) = z(i,j) * s
end do
!
!     ********- FOR i=low-1 STEP -1 UNTIL 1,
!               igh+1 STEP 1 UNTIL n DO -- **********
!
30 do 60 ii = 1, n
   i = ii
   if (i .ge. low .and. i .le. igh) go to 60
   if (i .lt. low) i = low - ii
   k = scale(i)
   if (k .eq. i) go to 60
!
   do 40 j = 1, n
      s = z(i,j)
      z(i,j) = z(k,j)
40 z(k,j) = s
!
   do 50 j = 1, n
      s = z(j,i)
      z(j,i) = z(j,k)
50 z(j,k) = s
60 continue
return
end subroutine balinv

subroutine elmhes(nm,n,low,igh,a,int)
implicit none
!
integer :: i, j, m
integer, intent(in) :: n
integer :: la
integer, intent(in) :: nm, igh
integer :: kp1
integer, intent(in) :: low
integer :: mm1, mp1
real, intent(inout) :: a(nm,n)
real :: x, y
!     real abs
integer, intent(inout) :: int(igh)
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure elmhes,
!     NUM. Math. 12, 349-368(1968) By Martin and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 339-358(1971).
!
!     Given a real general matrix, this subroutine
!     reduces a submatrix situated in rows and columns
!     low through igh to upper Hessenberg form by
!     stabilized elementary similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          SET low=1, igh=n,
!
!        A contains the input matrix.
!
!     On output-
!
!        A contains the Hessenberg matrix.  The multipliers
!          which were used in the reduction are stored in the
!          remaining triangle under the Hessenberg matrix,
!
!        Int contains information on the rows and columns
!          interchanged in the reduction.
!          Only elements low through igh are used.
!
!-----------------------------------------------------------------------
!
la = igh - 1
kp1 = low + 1
if (la .lt. kp1) go to 200
!
do 180 m = kp1, la
   mm1 = m - 1
   x = 0.0
   i = m
!
   do 100 j = m, igh
      if (abs(a(j,mm1)) .le. abs(x)) go to 100
      x = a(j,mm1)
      i = j
100 continue
!
   int(m) = i
   if (i .eq. m) go to 130
!    ********** INTERCHANGE ROWS AND COLUMNS OF a **********
   do j = mm1, n
      y = a(i,j)
      a(i,j) = a(m,j)
      a(m,j) = y
   end do
!
   do j = 1, igh
      y = a(j,i)
      a(j,i) = a(j,m)
      a(j,m) = y
   end do
!    ********** END INTERCHANGE **********
130 if (x .eq. 0.0) go to 180
   mp1 = m + 1
!
   do 160 i = mp1, igh
      y = a(i,mm1)
      if (y .eq. 0.0) go to 160
      y = y / x
      a(i,mm1) = y
!
      do 140 j = m, n
140 a(i,j) = a(i,j) - y * a(m,j)
!
      do 150 j = 1, igh
150 a(j,m) = a(j,m) + y * a(j,i)
!
160 continue
!
180 continue
!
200 return
end subroutine elmhes

subroutine elmhs0(nm,n,low,igh,a,int)
implicit none
!
integer :: i, j, m
integer, intent(in) :: n
integer :: la
integer, intent(in) :: nm, igh
integer :: kp1
integer, intent(in) :: low
integer :: mm1, mp1
real, intent(inout) :: a(nm,n)
real :: x, y
!     real abs
real, intent(inout) :: int(igh)
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure elmhes,
!     NUM. Math. 12, 349-368(1968) By Martin and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 339-358(1971).
!
!     Given a real general matrix, this subroutine
!     reduces a submatrix situated in rows and columns
!     low through igh to upper Hessenberg form by
!     stabilized elementary similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          SET low=1, igh=n,
!
!        A contains the input matrix.
!
!     On output-
!
!        A contains the Hessenberg matrix.  The multipliers
!          which were used in the reduction are stored in the
!          remaining triangle under the Hessenberg matrix,
!
!        Int contains information on the rows and columns
!          interchanged in the reduction.
!          Only elements low through igh are used.
!
!-----------------------------------------------------------------------
!
la = igh - 1
kp1 = low + 1
if (la .lt. kp1) go to 200
!
do 180 m = kp1, la
   mm1 = m - 1
   x = 0.0
   i = m
!
   do 100 j = m, igh
      if (abs(a(j,mm1)) .le. abs(x)) go to 100
      x = a(j,mm1)
      i = j
100 continue
!
   int(m) = i
   if (i .eq. m) go to 130
!    ********** INTERCHANGE ROWS AND COLUMNS OF a **********
   do j = mm1, n
      y = a(i,j)
      a(i,j) = a(m,j)
      a(m,j) = y
   end do
!
   do j = 1, igh
      y = a(j,i)
      a(j,i) = a(j,m)
      a(j,m) = y
   end do
!    ********** END INTERCHANGE **********
130 if (x .eq. 0.0) go to 180
   mp1 = m + 1
!
   do 160 i = mp1, igh
      y = a(i,mm1)
      if (y .eq. 0.0) go to 160
      y = y / x
      a(i,mm1) = y
!
      do 140 j = m, n
140 a(i,j) = a(i,j) - y * a(m,j)
!
      do 150 j = 1, igh
150 a(j,m) = a(j,m) + y * a(j,i)
!
160 continue
!
180 continue
!
200 return
end subroutine elmhs0

subroutine orthes(nm,n,low,igh,a,ort)
implicit none
!
integer :: i, j, m
integer, intent(in) :: n
integer :: ii, jj, la, mp
integer, intent(in) :: nm, igh
integer :: kp1
integer, intent(in) :: low
real, intent(inout) :: a(nm,n), ort(igh)
real :: f, g, h, scale
!     real sqrt,abs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure orthes,
!     NUM. Math. 12, 349-368(1968) By Martin and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 339-358(1971).
!
!     Given a real general matrix, this subroutine
!     reduces a submatrix situated in rows and columns
!     low through igh to upper Hessenberg form by
!     orthogonal similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          SET low=1, igh=n,
!
!        A contains the input matrix.
!
!     On output-
!
!        A contains the Hessenberg matrix.  Information about
!          the orthogonal transformations used in the reduction
!          is stored in the remaining triangle under the
!          Hessenberg matrix,
!
!        Ort contains further information about the transformations.
!          Only elements low through igh are used.
!
!-----------------------------------------------------------------------
!
la = igh - 1
kp1 = low + 1
if (la .lt. kp1) go to 200
!
do 180 m = kp1, la
   h = 0.0
   ort(m) = 0.0
   scale = 0.0
!     ********** scale COLUMN (ALGOL TOL THEN NOT NEEDED) **********
   do 90 i = m, igh
90 scale = scale + abs(a(i,m-1))
!
   if (scale .eq. 0.0) go to 180
   mp = m + igh
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
   do ii = m, igh
      i = mp - ii
      ort(i) = a(i,m-1) / scale
      h = h + ort(i) * ort(i)
   end do
!
   g = sqrt(h)
   if (ort(m) .ge. 0.0) g = -g
   h = h - ort(m) * g
   ort(m) = ort(m) - g
!     ********** FORM (i-(U*UT)/h) * a **********
   do j = m, n
      f = 0.0
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
      do ii = m, igh
         i = mp - ii
         f = f + ort(i) * a(i,j)
      end do
!
      f = f / h
!
      do 120 i = m, igh
120 a(i,j) = a(i,j) - f * ort(i)
!
   end do
!     ********** FORM (i-(U*UT)/h)*a*(i-(U*UT)/h) **********
   do i = 1, igh
      f = 0.0
!     ********** FOR j=igh STEP -1 UNTIL m DO -- **********
      do jj = m, igh
         j = mp - jj
         f = f + ort(j) * a(i,j)
      end do
!
      f = f / h
!
      do 150 j = m, igh
150 a(i,j) = a(i,j) - f * ort(j)
!
   end do
!
   ort(m) = scale * ort(m)
   a(m,m-1) = scale * g
180 continue
!
200 return
end subroutine orthes

subroutine hqr(nm,n,low,igh,h,wr,wi,ierr)
implicit none
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: en, ll, mm, na
integer, intent(in) :: nm, igh
integer :: its
integer, intent(in) :: low
integer :: mp2, enm2
integer, intent(out) :: ierr
real, intent(inout) :: h(nm,n), wr(n), wi(n)
real :: p, q, r, s, t, w, x, y, zz, norm, machep, spmpar
!     real sqrt,abs
!     integer min0
logical :: notlas
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure hqr,
!     NUM. Math. 14, 219-231(1970) By Martin, peters, and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 359-371(1971).
!
!     This subroutine finds the eigenvalues of a real
!     upper Hessenberg matrix BY the QR method.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          SET low=1, igh=n,
!
!        h contains the upper Hessenberg matrix.  Information about
!          the transformations used in the reduction to Hessenberg
!          form by  elmhes  or  orthes, if performed, is stored
!          in the remaining triangle under the Hessenberg matrix.
!
!     On output-
!
!        h has been destroyed.  Therefore, it must be saved
!          before calling  hqr  if subsequent calculation and
!          back transformation of eigenvectors is to be performed,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  The eigenvalues
!          are unordered except that complex conjugate pairs
!          of values appear consecutively with the eigenvalue
!          having the positive imaginary part first.  If an
!          error exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 30 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                machep the value U where U is the smallest positive
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           machep = spmpar(1)
!
!                **********
!
ierr = 0
norm = 0.0
k = 1
!     ********** STORE ROOTS ISOLATED BY balanc
!                AND COMPUTE MATRIX norm **********
do 50 i = 1, n
!
   do 40 j = k, n
40 norm = norm + abs(h(i,j))
!
   k = i
   if (i .ge. low .and. i .le. igh) go to 50
   wr(i) = h(i,i)
   wi(i) = 0.0
50 continue
!
en = igh
t = 0.0
!     ********** SEARCH FOR NEXT EIGENVALUES **********
60 if (en .lt. low) go to 1001
its = 0
na = en - 1
enm2 = na - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR l=en STEP -1 UNTIL LOW DO -- **********
70 do ll = low, en
   l = en + low - ll
   if (l .eq. low) go to 100
   s = abs(h(l-1,l-1)) + abs(h(l,l))
   if (s .eq. 0.0) s = norm
   if (abs(h(l,l-1)) .le. machep * s) go to 100
end do
!     ********** FORM SHIFT **********
100 x = h(en,en)
if (l .eq. en) go to 270
y = h(na,na)
w = h(en,na) * h(na,en)
if (l .eq. na) go to 280
if (its .eq. 30) go to 1000
if (its .ne. 10 .and. its .ne. 20) go to 130
!     ********** FORM EXCEPTIONAL SHIFT **********
t = t + x
!
do 120 i = low, en
120 h(i,i) = h(i,i) - x
!
s = abs(h(en,na)) + abs(h(na,enm2))
x = 0.75 * s
y = x
w = -0.4375 * s * s
130 its = its + 1
!     ********** LOOK FOR TWO CONSECUTIVE SMALL
!                sub-diagonal elements.
!                FOR m=en-2 STEP -1 UNTIL l DO -- **********
do mm = l, enm2
   m = enm2 + l - mm
   zz = h(m,m)
   r = x - zz
   s = y - zz
   p = (r * s - w) / h(m+1,m) + h(m,m+1)
   q = h(m+1,m+1) - zz - r - s
   r = h(m+2,m+1)
   s = abs(p) + abs(q) + abs(r)
   p = p / s
   q = q / s
   r = r / s
   if (m .eq. l) go to 150
   if (abs(h(m,m-1)) * (abs(q) + abs(r)) .le. machep * abs(p) &
&* (abs(h(m-1,m-1)) + abs(zz) + abs(h(m+1,m+1)))) go to 150
end do
!
150 mp2 = m + 2
!
do 160 i = mp2, en
   h(i,i-2) = 0.0
   if (i .eq. mp2) go to 160
   h(i,i-3) = 0.0
160 continue
!     ********** DOUBLE QR STEP INVOLVING ROWS l TO en AND
!                COLUMNS m TO en **********
do 260 k = m, na
   notlas = k .ne. na
   if (k .eq. m) go to 170
   p = h(k,k-1)
   q = h(k+1,k-1)
   r = 0.0
   if (notlas) r = h(k+2,k-1)
   x = abs(p) + abs(q) + abs(r)
   if (x .eq. 0.0) go to 260
   p = p / x
   q = q / x
   r = r / x
170 s = sqrt(p*p + q*q + r*r)
   if (p .lt. 0.0) s = -s
   if (k .eq. m) go to 180
   h(k,k-1) = -s * x
   go to 190
180 if (l .ne. m) h(k,k-1) = -h(k,k-1)
190 p = p + s
   x = p / s
   y = q / s
   zz = r / s
   q = q / p
   r = r / p
!     ********** ROW MODIFICATION **********
   do j = k, en
      p = h(k,j) + q * h(k+1,j)
      if (.not. notlas) go to 200
      p = p + r * h(k+2,j)
      h(k+2,j) = h(k+2,j) - p * zz
200 h(k+1,j) = h(k+1,j) - p * y
      h(k,j) = h(k,j) - p * x
   end do
!
   j = min0(en,k+3)
!     ********** COLUMN MODIFICATION **********
   do i = l, j
      p = x * h(i,k) + y * h(i,k+1)
      if (.not. notlas) go to 220
      p = p + zz * h(i,k+2)
      h(i,k+2) = h(i,k+2) - p * r
220 h(i,k+1) = h(i,k+1) - p * q
      h(i,k) = h(i,k) - p
   end do
!
260 continue
!
go to 70
!     ********** ONE ROOT FOUND **********
270 wr(en) = x + t
wi(en) = 0.0
en = na
go to 60
!     ********** TWO ROOTS FOUND **********
280 p = (y - x) / 2.0
q = p * p + w
zz = sqrt(abs(q))
x = x + t
if (q .lt. 0.0) go to 320
!     ********** REAL PAIR **********
if (p .lt. 0.0) zz = -zz
zz = p + zz
wr(na) = x + zz
wr(en) = wr(na)
if (zz .ne. 0.0) wr(en) = x - w / zz
wi(na) = 0.0
wi(en) = 0.0
go to 330
!     ********** COMPLEX PAIR **********
320 wr(na) = x + p
wr(en) = x + p
wi(na) = zz
wi(en) = -zz
330 en = enm2
go to 60
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 ierr = en
1001 return
end subroutine hqr

subroutine balbak(nm,n,low,igh,scale,m,z)
implicit none
!
integer :: i, j, k
integer, intent(in) :: m, n
integer :: ii
integer, intent(in) :: nm, igh, low
real, intent(in) :: scale(n)
real, intent(inout) :: z(nm,m)
real :: s
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure balbak,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 315-326(1971).
!
!     This subroutine forms the eigenvectors of a real general
!     matrix BY back transforming those of the corresponding
!     balanced matrix determined by  balanc.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by  balanc,
!
!        Scale contains information determining the permutations
!          and scaling factors used by  balanc,
!
!        m is the number of columns of z to be back transformed,
!
!        z contains the real and imaginary parts of the eigen-
!          vectors to be back transformed in its first m columns.
!
!     On output-
!
!        z contains the real and imaginary parts of the
!          transformed eigenvectors in its first m columns.
!
!-----------------------------------------------------------------------
!
if (m .eq. 0) go to 200
if (igh .eq. low) go to 120
!
do i = low, igh
   s = scale(i)
!     ********** LEFT HAND EIGENVECTORS ARE BACK TRANSFORMED
!                if the foregoing statement is replaced by
!                s=1.0/scale(i). **********
   do 100 j = 1, m
100 z(i,j) = z(i,j) * s
!
end do
!     ********- FOR i=low-1 STEP -1 UNTIL 1,
!               igh+1 STEP 1 UNTIL n DO -- **********
120 do 140 ii = 1, n
   i = ii
   if (i .ge. low .and. i .le. igh) go to 140
   if (i .lt. low) i = low - ii
   k = scale(i)
   if (k .eq. i) go to 140
!
   do j = 1, m
      s = z(i,j)
      z(i,j) = z(k,j)
      z(k,j) = s
   end do
!
140 continue
!
200 return
end subroutine balbak

subroutine eltran(nm,n,low,igh,a,int,z)
implicit none
!
integer :: i, j
integer, intent(in) :: n
integer :: kl, mm, mp
integer, intent(in) :: nm, igh, low
integer :: mp1
real, intent(in) :: a(nm,igh)
real, intent(inout) :: z(nm,n)
integer, intent(in) :: int(igh)
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ELMTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the stabilized elementary
!     similarity transformations used in the reduction of A
!     real general matrix to upper Hessenberg form by  elmhes.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          SET low=1, igh=n,
!
!        A contains the multipliers which were used in the
!          reduction by  elmhes  in its lower triangle
!          below the subdiagonal,
!
!        Int contains information on the rows and columns
!          interchanged in the reduction by  elmhes.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by  elmhes.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE z TO IDENTITY MATRIX **********
do i = 1, n
!
   do 60 j = 1, n
60 z(i,j) = 0.0
!
   z(i,i) = 1.0
end do
!
kl = igh - low - 1
if (kl .lt. 1) go to 200
!     ********** FOR mp=igh-1 STEP -1 UNTIL low+1 DO -- **********
do 140 mm = 1, kl
   mp = igh - mm
   mp1 = mp + 1
!
   do 100 i = mp1, igh
100 z(i,mp) = a(i,mp-1)
!
   i = int(mp)
   if (i .eq. mp) go to 140
!
   do j = mp, igh
      z(mp,j) = z(i,j)
      z(i,j) = 0.0
   end do
!
   z(i,mp) = 1.0
140 continue
!
200 return
end subroutine eltran

subroutine eltrn0(nm,n,low,igh,a,int,z)
implicit none
!
integer :: i, j
integer, intent(in) :: n
integer :: kl, mm, mp
integer, intent(in) :: nm, igh, low
integer :: mp1
real, intent(in) :: a(nm,igh)
real, intent(inout) :: z(nm,n)
real, intent(in) :: int(igh)
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ELMTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the stabilized elementary
!     similarity transformations used in the reduction of A
!     real general matrix to upper Hessenberg form by  elmhs0.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          SET low=1, igh=n,
!
!        A contains the multipliers which were used in the
!          reduction by  elmhs0  in its lower triangle
!          below the subdiagonal,
!
!        Int contains information on the rows and columns
!          interchanged in the reduction by  elmhs0.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by  elmhs0.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE z TO IDENTITY MATRIX **********
do i = 1, n
!
   do 60 j = 1, n
60 z(i,j) = 0.0
!
   z(i,i) = 1.0
end do
!
kl = igh - low - 1
if (kl .lt. 1) go to 200
!     ********** FOR mp=igh-1 STEP -1 UNTIL low+1 DO -- **********
do 140 mm = 1, kl
   mp = igh - mm
   mp1 = mp + 1
!
   do 100 i = mp1, igh
100 z(i,mp) = a(i,mp-1)
!
   i = int(mp)
   if (i .eq. mp) go to 140
!
   do j = mp, igh
      z(mp,j) = z(i,j)
      z(i,j) = 0.0
   end do
!
   z(i,mp) = 1.0
140 continue
!
200 return
end subroutine eltrn0

subroutine ortran(nm,n,low,igh,a,ort,z)
implicit none
!
integer :: i, j
integer, intent(in) :: n
integer :: kl, mm, mp
integer, intent(in) :: nm, igh, low
integer :: mp1
real, intent(in) :: a(nm,igh)
real, intent(inout) :: ort(igh), z(nm,n)
real :: g
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ORTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the orthogonal similarity
!     transformations used in the reduction of a real general
!     matrix to upper Hessenberg form by  orthes.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          SET low=1, igh=n,
!
!        A contains information about the orthogonal trans-
!          formations used in the reduction by  orthes
!          in its strict lower triangle,
!
!        Ort contains further information about the trans-
!          formations used in the reduction by  orthes.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by  orthes,
!
!        Ort has been altered.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE z TO IDENTITY MATRIX **********
do i = 1, n
!
   do 60 j = 1, n
60 z(i,j) = 0.0
!
   z(i,i) = 1.0
end do
!
kl = igh - low - 1
if (kl .lt. 1) go to 200
!     ********** FOR mp=igh-1 STEP -1 UNTIL low+1 DO -- **********
do 140 mm = 1, kl
   mp = igh - mm
   if (a(mp,mp-1) .eq. 0.0) go to 140
   mp1 = mp + 1
!
   do 100 i = mp1, igh
100 ort(i) = a(i,mp-1)
!
   do j = mp, igh
      g = 0.0
!
      do 110 i = mp, igh
110 g = g + ort(i) * z(i,j)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN orthes.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      g = (g / ort(mp)) / a(mp,mp-1)
!
      do 120 i = mp, igh
120 z(i,j) = z(i,j) + g * ort(i)
!
   end do
!
140 continue
!
200 return
end subroutine ortran

subroutine ortrn1(n,low,igh,a,na,z,nz,ort)
implicit none
!
integer :: i, j
integer, intent(in) :: n
integer :: kl, mm, mp
integer, intent(in) :: na, igh, low
integer :: mp1
integer, intent(in) :: nz
real, intent(in) :: a(na,igh)
real, intent(inout) :: ort(igh), z(nz,n)
real :: g
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ORTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the orthogonal similarity
!     transformations used in the reduction of a real general
!     matrix to upper Hessenberg form by  orthes.
!
!     On input-
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          SET low=1, igh=n,
!
!        A contains information about the orthogonal trans-
!          formations used in the reduction by  orthes
!          in its strict lower triangle,
!
!        na must be set to the row dimension of the 2-dimensional
!          array parameter  a  as declared in the calling program
!          dimension statement,
!
!        nz must be set to the row dimension of the 2-dimensional
!          array parameter  z  as declared in the calling program
!          dimension statement,
!
!        Ort contains further information about the trans-
!          formations used in the reduction by  orthes.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by  orthes,
!
!        Ort has been altered.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE z TO IDENTITY MATRIX **********
do i = 1, n
!
   do 60 j = 1, n
60 z(i,j) = 0.0
!
   z(i,i) = 1.0
end do
!
kl = igh - low - 1
if (kl .lt. 1) go to 200
!     ********** FOR mp=igh-1 STEP -1 UNTIL low+1 DO -- **********
do 140 mm = 1, kl
   mp = igh - mm
   if (a(mp,mp-1) .eq. 0.0) go to 140
   mp1 = mp + 1
!
   do 100 i = mp1, igh
100 ort(i) = a(i,mp-1)
!
   do j = mp, igh
      g = 0.0
!
      do 110 i = mp, igh
110 g = g + ort(i) * z(i,j)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN orthes.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      g = (g / ort(mp)) / a(mp,mp-1)
!
      do 120 i = mp, igh
120 z(i,j) = z(i,j) + g * ort(i)
!
   end do
!
140 continue
!
200 return
end subroutine ortrn1

subroutine hqr2(nm,n,low,igh,h,wr,wi,z,ierr)
implicit none
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: en, ii, jj, ll, mm, na
integer, intent(in) :: nm
integer :: nn
integer, intent(in) :: igh
integer :: its
integer, intent(in) :: low
integer :: mp2, enm2
integer, intent(out) :: ierr
real, intent(inout) :: h(nm,n), wr(n), wi(n), z(nm,n)
real :: p, q, r, s, t, w, x, y, ra, sa, vi, vr, zz, norm, machep, &
&spmpar
!     real sqrt,abs
!     integer min0
logical :: notlas
complex :: z3
!     complex cmplx
!     real real,aimag
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure hqr2,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 372-395(1971).
!
!     This subroutine finds the eigenvalues and eigenvectors
!     of a real upper Hessenberg matrix BY the QR method.  The
!     eigenvectors of a real general matrix can also be found
!     if  elmhes  and  eltran  or  orthes  and  ortran  have
!     been used to reduce this general matrix to Hessenberg form
!     and to accumulate the similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          SET low=1, igh=n,
!
!        h contains the upper Hessenberg matrix,
!
!        z contains the transformation matrix produced by  eltran
!          after the reduction by  elmhes, or by  ortran  after the
!          reduction by  orthes, if performed.  If the eigenvectors
!          of the Hessenberg matrix are desired, z must contain the
!          identity matrix.
!
!     On output-
!
!        h has been destroyed,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  The eigenvalues
!          are unordered except that complex conjugate pairs
!          of values appear consecutively with the eigenvalue
!          having the positive imaginary part first.  If an
!          error exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        z contains the real and imaginary parts of the eigenvectors.
!          If the i-TH eigenvalue is real, the i-TH column of z
!          contains its eigenvector.  If the i-TH eigenvalue is complex
!          with positive imaginary part, the i-TH and (i+1)-TH
!          columns of z contain the real and imaginary parts of its
!          eigenvector.  The eigenvectors are unnormalized.  If an
!          error exit is made, none of the eigenvectors has been found,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 30 iterations.
!
!     Arithmetic is real except for the replacement of the Algol
!     procedure cdiv by complex division.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                machep the value U where U is the smallest positive
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           machep = spmpar(1)
!
!                **********
!
ierr = 0
norm = 0.0
k = 1
!     ********** STORE ROOTS ISOLATED BY balanc
!                AND COMPUTE MATRIX norm **********
do 50 i = 1, n
!
   do 40 j = k, n
40 norm = norm + abs(h(i,j))
!
   k = i
   if (i .ge. low .and. i .le. igh) go to 50
   wr(i) = h(i,i)
   wi(i) = 0.0
50 continue
!
en = igh
t = 0.0
!     ********** SEARCH FOR NEXT EIGENVALUES **********
60 if (en .lt. low) go to 340
its = 0
na = en - 1
enm2 = na - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR l=en STEP -1 UNTIL LOW DO -- **********
70 do ll = low, en
   l = en + low - ll
   if (l .eq. low) go to 100
   s = abs(h(l-1,l-1)) + abs(h(l,l))
   if (s .eq. 0.0) s = norm
   if (abs(h(l,l-1)) .le. machep * s) go to 100
end do
!     ********** FORM SHIFT **********
100 x = h(en,en)
if (l .eq. en) go to 270
y = h(na,na)
w = h(en,na) * h(na,en)
if (l .eq. na) go to 280
if (its .eq. 30) go to 1000
if (its .ne. 10 .and. its .ne. 20) go to 130
!     ********** FORM EXCEPTIONAL SHIFT **********
t = t + x
!
do 120 i = low, en
120 h(i,i) = h(i,i) - x
!
s = abs(h(en,na)) + abs(h(na,enm2))
x = 0.75 * s
y = x
w = -0.4375 * s * s
130 its = its + 1
!     ********** LOOK FOR TWO CONSECUTIVE SMALL
!                sub-diagonal elements.
!                FOR m=en-2 STEP -1 UNTIL l DO -- **********
do mm = l, enm2
   m = enm2 + l - mm
   zz = h(m,m)
   r = x - zz
   s = y - zz
   p = (r * s - w) / h(m+1,m) + h(m,m+1)
   q = h(m+1,m+1) - zz - r - s
   r = h(m+2,m+1)
   s = abs(p) + abs(q) + abs(r)
   p = p / s
   q = q / s
   r = r / s
   if (m .eq. l) go to 150
   if (abs(h(m,m-1)) * (abs(q) + abs(r)) .le. machep * abs(p) &
&* (abs(h(m-1,m-1)) + abs(zz) + abs(h(m+1,m+1)))) go to 150
end do
!
150 mp2 = m + 2
!
do 160 i = mp2, en
   h(i,i-2) = 0.0
   if (i .eq. mp2) go to 160
   h(i,i-3) = 0.0
160 continue
!     ********** DOUBLE QR STEP INVOLVING ROWS l TO en AND
!                COLUMNS m TO en **********
do 260 k = m, na
   notlas = k .ne. na
   if (k .eq. m) go to 170
   p = h(k,k-1)
   q = h(k+1,k-1)
   r = 0.0
   if (notlas) r = h(k+2,k-1)
   x = abs(p) + abs(q) + abs(r)
   if (x .eq. 0.0) go to 260
   p = p / x
   q = q / x
   r = r / x
170 s = sqrt(p*p + q*q + r*r)
   if (p .lt. 0.0) s = -s
   if (k .eq. m) go to 180
   h(k,k-1) = -s * x
   go to 190
180 if (l .ne. m) h(k,k-1) = -h(k,k-1)
190 p = p + s
   x = p / s
   y = q / s
   zz = r / s
   q = q / p
   r = r / p
!     ********** ROW MODIFICATION **********
   do j = k, n
      p = h(k,j) + q * h(k+1,j)
      if (.not. notlas) go to 200
      p = p + r * h(k+2,j)
      h(k+2,j) = h(k+2,j) - p * zz
200 h(k+1,j) = h(k+1,j) - p * y
      h(k,j) = h(k,j) - p * x
   end do
!
   j = min0(en,k+3)
!     ********** COLUMN MODIFICATION **********
   do i = 1, j
      p = x * h(i,k) + y * h(i,k+1)
      if (.not. notlas) go to 220
      p = p + zz * h(i,k+2)
      h(i,k+2) = h(i,k+2) - p * r
220 h(i,k+1) = h(i,k+1) - p * q
      h(i,k) = h(i,k) - p
   end do
!     ********** ACCUMULATE TRANSFORMATIONS **********
   do i = low, igh
      p = x * z(i,k) + y * z(i,k+1)
      if (.not. notlas) go to 240
      p = p + zz * z(i,k+2)
      z(i,k+2) = z(i,k+2) - p * r
240 z(i,k+1) = z(i,k+1) - p * q
      z(i,k) = z(i,k) - p
   end do
!
260 continue
!
go to 70
!     ********** ONE ROOT FOUND **********
270 h(en,en) = x + t
wr(en) = h(en,en)
wi(en) = 0.0
en = na
go to 60
!     ********** TWO ROOTS FOUND **********
280 p = (y - x) / 2.0
q = p * p + w
zz = sqrt(abs(q))
h(en,en) = x + t
x = h(en,en)
h(na,na) = y + t
if (q .lt. 0.0) go to 320
!     ********** REAL PAIR **********
if (p .lt. 0.0) zz = -zz
zz = p + zz
wr(na) = x + zz
wr(en) = wr(na)
if (zz .ne. 0.0) wr(en) = x - w / zz
wi(na) = 0.0
wi(en) = 0.0
x = h(en,na)
s = abs(x) + abs(zz)
p = x / s
q = zz / s
r = sqrt(p*p+q*q)
p = p / r
q = q / r
!     ********** ROW MODIFICATION **********
do j = na, n
   zz = h(na,j)
   h(na,j) = q * zz + p * h(en,j)
   h(en,j) = q * h(en,j) - p * zz
end do
!     ********** COLUMN MODIFICATION **********
do i = 1, en
   zz = h(i,na)
   h(i,na) = q * zz + p * h(i,en)
   h(i,en) = q * h(i,en) - p * zz
end do
!     ********** ACCUMULATE TRANSFORMATIONS **********
do i = low, igh
   zz = z(i,na)
   z(i,na) = q * zz + p * z(i,en)
   z(i,en) = q * z(i,en) - p * zz
end do
!
go to 330
!     ********** COMPLEX PAIR **********
320 wr(na) = x + p
wr(en) = x + p
wi(na) = zz
wi(en) = -zz
330 en = enm2
go to 60
!     ********** ALL ROOTS FOUND.  BACKSUBSTITUTE TO FIND
!                VECTORS OF UPPER TRIANGULAR FORM **********
340 if (norm .eq. 0.0) go to 1001
!     ********** FOR en=n STEP -1 UNTIL 1 DO -- **********
do 800 nn = 1, n
   en = n + 1 - nn
   p = wr(en)
   q = wi(en)
   na = en - 1
   if (q) 710, 600, 800
!     ********** REAL VECTOR **********
600 m = en
   h(en,en) = 1.0
   if (na .eq. 0) go to 800
!     ********** FOR i=en-1 STEP -1 UNTIL 1 DO -- **********
   do 700 ii = 1, na
      i = en - ii
      w = h(i,i) - p
      r = h(i,en)
      if (m .gt. na) go to 620
!
      do 610 j = m, na
610 r = r + h(i,j) * h(j,en)
!
620 if (wi(i) .ge. 0.0) go to 630
      zz = w
      s = r
      go to 700
630 m = i
      if (wi(i) .ne. 0.0) go to 640
      t = w
      if (w .eq. 0.0) t = machep * norm
      h(i,en) = -r / t
      go to 700
!     ********** SOLVE REAL EQUATIONS **********
640 x = h(i,i+1)
      y = h(i+1,i)
      q = (wr(i) - p) * (wr(i) - p) + wi(i) * wi(i)
      t = (x * s - zz * r) / q
      h(i,en) = t
      if (abs(x) .le. abs(zz)) go to 650
      h(i+1,en) = (-r - w * t) / x
      go to 700
650 h(i+1,en) = (-s - y * t) / zz
700 continue
!     ********** END REAL VECTOR **********
   go to 800
!     ********** COMPLEX VECTOR **********
710 m = na
!     ********** LAST VECTOR COMPONENT CHOSEN IMAGINARY SO THAT
!                EIGENVECTOR MATRIX IS TRIANGULAR **********
   if (abs(h(en,na)) .le. abs(h(na,en))) go to 720
   h(na,na) = q / h(en,na)
   h(na,en) = -(h(en,en) - p) / h(en,na)
   go to 730
720 z3 = cmplx(0.0,-h(na,en)) / cmplx(h(na,na)-p,q)
   h(na,na) = real(z3)
   h(na,en) = aimag(z3)
730 h(en,na) = 0.0
   h(en,en) = 1.0
   enm2 = na - 1
   if (enm2 .eq. 0) go to 800
!     ********** FOR i=en-2 STEP -1 UNTIL 1 DO -- **********
   do 790 ii = 1, enm2
      i = na - ii
      w = h(i,i) - p
      ra = 0.0
      sa = h(i,en)
!
      do j = m, na
         ra = ra + h(i,j) * h(j,na)
         sa = sa + h(i,j) * h(j,en)
      end do
!
      if (wi(i) .ge. 0.0) go to 770
      zz = w
      r = ra
      s = sa
      go to 790
770 m = i
      if (wi(i) .ne. 0.0) go to 780
      z3 = cmplx(-ra,-sa) / cmplx(w,q)
      h(i,na) = real(z3)
      h(i,en) = aimag(z3)
      go to 790
!     ********** SOLVE COMPLEX EQUATIONS **********
780 x = h(i,i+1)
      y = h(i+1,i)
      vr = (wr(i) - p) * (wr(i) - p) + wi(i) * wi(i) - q * q
      vi = (wr(i) - p) * 2.0 * q
      if (vr .eq. 0.0 .and. vi .eq. 0.0) vr = machep * norm &
&* (abs(w) + abs(q) + abs(x) + abs(y) + abs(zz))
      z3 = cmplx(x*r-zz*ra+q*sa,x*s-zz*sa-q*ra) / cmplx(vr,vi)
      h(i,na) = real(z3)
      h(i,en) = aimag(z3)
      if (abs(x) .le. abs(zz) + abs(q)) go to 785
      h(i+1,na) = (-ra - w * h(i,na) + q * h(i,en)) / x
      h(i+1,en) = (-sa - w * h(i,en) - q * h(i,na)) / x
      go to 790
785 z3 = cmplx(-r-y*h(i,na),-s-y*h(i,en)) / cmplx(zz,q)
      h(i+1,na) = real(z3)
      h(i+1,en) = aimag(z3)
790 continue
!     ********** END COMPLEX VECTOR **********
800 continue
!     ********** END BACK SUBSTITUTION.
!                VECTORS OF ISOLATED ROOTS **********
do 840 i = 1, n
   if (i .ge. low .and. i .le. igh) go to 840
!
   do 820 j = i, n
820 z(i,j) = h(i,j)
!
840 continue
!     ********** MULTIPLY BY TRANSFORMATION MATRIX TO GIVE
!                vectors of original full matrix.
!                FOR j=n STEP -1 UNTIL LOW DO -- **********
do 880 jj = low, n
   j = n + low - jj
   m = min0(j,igh)
!
   do 880 i = low, igh
      zz = 0.0
!
      do 860 k = low, m
860 zz = zz + z(i,k) * h(k,j)
!
      z(i,j) = zz
880 continue
!
go to 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 ierr = en
1001 return
end subroutine hqr2

subroutine deig (ibal,a,ka,n,wr,wi,ierr)
implicit none
integer, intent(in) :: ibal
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
integer :: igh, low
!-----------------------------------------------------------------------
!                Eigenvalues of double precision matrices
!-----------------------------------------------------------------------
double precision, intent(inout) :: a(ka,n), wr(n), wi(n)
!
low = 1
igh = n
if (ibal .ne. 0) call dbal (ka,n,a,low,igh,wr)
call dorth (ka,n,low,igh,a,wr)
call dhqr (ka,n,low,igh,a,wr,wi,ierr)
return
end subroutine deig

subroutine deigv (ibal,a,ka,n,wr,wi,zr,zi,ierr)
implicit none
integer, intent(in) :: ibal
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
integer :: igh, j, k, kp1, low
!-----------------------------------------------------------------------
!     Eigenvalues and eigenvectors of double precision matrices
!-----------------------------------------------------------------------
double precision, intent(inout) :: a(ka,n), wr(n), wi(n), &
&zr(ka,n), zi(ka,n)
!
low = 1
igh = n
if (ibal .ne. 0) call dbal (ka,n,a,low,igh,zi)
call dorth (ka,n,low,igh,a,wr)
call dortrn (ka,n,low,igh,a,wr,zr)
call dhqr2 (ka,n,low,igh,a,wr,wi,zr,ierr)
if (ierr .ne. 0) return
if (ibal .ne. 0) call dbabk (ka,n,low,igh,zi,n,zr)
!
do 30 k = 1,n
   if (wi(k)) 30,10,20
10 do 11 j = 1,n
11 zi(j,k) = 0.d0
   go to 30
20 kp1 = k + 1
   do 21 j = 1,n
      zi(j,k) = zr(j,kp1)
      zr(j,kp1) = zr(j,k)
21 zi(j,kp1) = -zi(j,k)
30 continue
return
end subroutine deigv

subroutine dbal(nm,n,a,low,igh,scale)
implicit none
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: jj
integer, intent(in) :: nm
integer, intent(inout) :: igh, low
integer :: iexc
double precision, intent(inout) :: a(nm,n), scale(n)
double precision :: c, f, g, r, s, b2, radix
integer :: ipmpar
!     double precision dabs
logical :: noconv
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure balance,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.II-linear algebra, 315-326(1971).
!
!     Dbal balances a double precision real matrix and isolates
!     eigenvalues whenever possible.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        A contains the input matrix to be balanced.
!
!     On output-
!
!        A contains the balanced matrix,
!
!        Low and igh are two integers such that a(i,j)
!          is equal to zero if
!           (1) i is greater than j and
!           (2) j=1,...,low-1 OR i=igh+1,...,n,
!
!        Scale contains information determining the
!           permutations and scaling factors used.
!
!     Suppose that the principal submatrix in rows low through igh
!     has been balanced, that P(j) denotes the index interchanged
!     with j during the permutation step, and that the elements
!     of the diagonal matrix used are denoted by D(i,j).  Then
!        scale(j) = P(j),    FOR j = 1,...,low-1
!                 = D(j,j),      j = low,...,igh
!                 = P(j)         j = igh+1,...,n.
!     The order in which the interchanges are made is n to igh+1,
!     then 1 to low-1.
!
!     Note that 1 is returned for igh if igh is zero formally.
!
!     The Algol procedure exc contained in balance appears in
!     dbal in line.  (Note that the Algol roles of identifiers
!     k,l have been reversed.)
!
!-----------------------------------------------------------------------
!
!     ********** radix IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                the base of the machine floating point representation.
!
           radix = ipmpar(4)
!
!                **********
!
b2 = radix * radix
k = 1
l = n
go to 100
!     ********** IN-LINE PROCEDURE FOR ROW AND
!                COLUMN EXCHANGE **********
20 scale(m) = j
if (j .eq. m) go to 50
!
do i = 1, l
   f = a(i,j)
   a(i,j) = a(i,m)
   a(i,m) = f
end do
!
do i = k, n
   f = a(j,i)
   a(j,i) = a(m,i)
   a(m,i) = f
end do
!
50 go to (80,130), iexc
!     ********** SEARCH FOR ROWS ISOLATING AN EIGENVALUE
!                AND PUSH THEM DOWN **********
80 if (l .eq. 1) go to 280
l = l - 1
!     ********** FOR j=l STEP -1 UNTIL 1 DO -- **********
100 do 120 jj = 1, l
   j = l + 1 - jj
!
   do 110 i = 1, l
      if (i .eq. j) go to 110
      if (a(j,i) .ne. 0.d0) go to 120
110 continue
!
   m = l
   iexc = 1
   go to 20
120 continue
!
go to 140
!     ********** SEARCH FOR COLUMNS ISOLATING AN EIGENVALUE
!                AND PUSH THEM LEFT **********
130 k = k + 1
!
140 do 170 j = k, l
!
   do 150 i = k, l
      if (i .eq. j) go to 150
      if (a(i,j) .ne. 0.d0) go to 170
150 continue
!
   m = k
   iexc = 2
   go to 20
170 continue
!     ********** NOW BALANCE THE SUBMATRIX IN ROWS k TO l **********
do 180 i = k, l
180 scale(i) = 1.d0
!     ********** ITERATIVE LOOP FOR NORM REDUCTION **********
190 noconv = .false.
!
do 270 i = k, l
   c = 0.d0
   r = 0.d0
!
   do 200 j = k, l
      if (j .eq. i) go to 200
      c = c + dabs(a(j,i))
      r = r + dabs(a(i,j))
200 continue
!     ********** GUARD AGAINST ZERO c OR r DUE TO UNDERFLOW **********
   if (c .eq. 0.d0 .or. r .eq. 0.d0) go to 270
   g = r / radix
   f = 1.d0
   s = c + r
210 if (c .ge. g) go to 220
   f = f * radix
   c = c * b2
   go to 210
220 g = r * radix
230 if (c .lt. g) go to 240
   f = f / radix
   c = c / b2
   go to 230
!     ********** NOW BALANCE **********
240 if ((c + r) / f .ge. 0.95d0 * s) go to 270
   g = 1.d0 / f
   scale(i) = scale(i) * f
   noconv = .true.
!
   do 250 j = k, n
250 a(i,j) = a(i,j) * g
!
   do 260 j = 1, l
260 a(j,i) = a(j,i) * f
!
270 continue
!
if (noconv) go to 190
!
280 low = k
igh = l
return
end subroutine dbal

subroutine dbalnv (nz,n,z,low,igh,scale)
implicit none
integer :: i, j, k
integer, intent(in) :: n
integer :: ii
integer, intent(in) :: nz, igh, low
double precision, intent(inout) :: z(nz,n)
double precision, intent(in) :: scale(n)
double precision :: s
!-----------------------------------------------------------------------
!        Given A matrix A of order n. dbal transforms A into
!     the matrix B by the similarity transformation
!             b = d**(-1)*transpose(p)*a*p*d
!     where D is a diagonal matrix and P a permutation matrix.
!     The information concerning D and P is stored in igh, low,
!     and scale. The order in which the interchanges were made
!     is n to igh + 1, and then 1 to low - 1.
!
!        z is a matrix of order n. dbalnv transforms z into the
!     matrix W using the inverse similarity transform
!             w = p*d*z*d**(-1)*transpose(p)
!
!     On input-
!
!        nz is the row dimension of the matrix z in the calling
!          program,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by  dbal,
!
!        Scale contains information determining the permutations
!          and scaling factors used by  dbal,
!
!     On output-
!
!        z contains the transformed matrix W
!
!-----------------------------------------------------------------------
!
if (igh .eq. low) go to 30
!
do i = low, igh
s = scale(i)
   do 10 j = 1, n
10 z(i,j) = z(i,j) * s
end do
!
do j = low, igh
s = 1.d0/scale(j)
   do 20 i = 1, n
20 z(i,j) = z(i,j) * s
end do
!
!     ********- FOR i=low-1 STEP -1 UNTIL 1,
!               igh+1 STEP 1 UNTIL n DO -- **********
!
30 do 60 ii = 1, n
   i = ii
   if (i .ge. low .and. i .le. igh) go to 60
   if (i .lt. low) i = low - ii
   k = scale(i)
   if (k .eq. i) go to 60
!
   do 40 j = 1, n
      s = z(i,j)
      z(i,j) = z(k,j)
40 z(k,j) = s
!
   do 50 j = 1, n
      s = z(j,i)
      z(j,i) = z(j,k)
50 z(j,k) = s
60 continue
return
end subroutine dbalnv

subroutine dorth(nm,n,low,igh,a,ort)
implicit none
!
integer :: i, j, m
integer, intent(in) :: n
integer :: ii, jj, la, mp
integer, intent(in) :: nm, igh
integer :: kp1
integer, intent(in) :: low
double precision, intent(inout) :: a(nm,n), ort(igh)
double precision :: f, g, h, scale
!     double precision dsqrt,dabs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure orthes,
!     NUM. Math. 12, 349-368(1968) By Martin and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 339-358(1971).
!
!     Given a real general matrix, this subroutine
!     reduces a submatrix situated in rows and columns
!     low through igh to upper Hessenberg form by
!     orthogonal similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dbal.  If dbal has not been used then
!          SET low=1, igh=n,
!
!        A contains the input matrix.
!
!     On output-
!
!        A contains the Hessenberg matrix.  Information about
!          the orthogonal transformations used in the reduction
!          is stored in the remaining triangle under the
!          Hessenberg matrix,
!
!        Ort contains further information about the transformations.
!          Only elements low through igh are used.
!
!-----------------------------------------------------------------------
!
la = igh - 1
kp1 = low + 1
if (la .lt. kp1) go to 200
!
do 180 m = kp1, la
   h = 0.d0
   ort(m) = 0.d0
   scale = 0.d0
!     ********** scale COLUMN (ALGOL TOL THEN NOT NEEDED) **********
   do 90 i = m, igh
90 scale = scale + dabs(a(i,m-1))
!
   if (scale .eq. 0.d0) go to 180
   mp = m + igh
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
   do ii = m, igh
      i = mp - ii
      ort(i) = a(i,m-1) / scale
      h = h + ort(i) * ort(i)
   end do
!
   g = dsqrt(h)
   if (ort(m) .ge. 0.d0) g = -g
   h = h - ort(m) * g
   ort(m) = ort(m) - g
!     ********** FORM (i-(U*UT)/h) * a **********
   do j = m, n
      f = 0.d0
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
      do ii = m, igh
         i = mp - ii
         f = f + ort(i) * a(i,j)
      end do
!
      f = f / h
!
      do 120 i = m, igh
120 a(i,j) = a(i,j) - f * ort(i)
!
   end do
!     ********** FORM (i-(U*UT)/h)*a*(i-(U*UT)/h) **********
   do i = 1, igh
      f = 0.d0
!     ********** FOR j=igh STEP -1 UNTIL m DO -- **********
      do jj = m, igh
         j = mp - jj
         f = f + ort(j) * a(i,j)
      end do
!
      f = f / h
!
      do 150 j = m, igh
150 a(i,j) = a(i,j) - f * ort(j)
!
   end do
!
   ort(m) = scale * ort(m)
   a(m,m-1) = scale * g
180 continue
!
200 return
end subroutine dorth

subroutine dhqr(nm,n,low,igh,h,wr,wi,ierr)
implicit none
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: en, ll, mm, na
integer, intent(in) :: nm, igh
integer :: its
integer, intent(in) :: low
integer :: mp2, enm2
integer, intent(out) :: ierr
double precision, intent(inout) :: h(nm,n), wr(n), wi(n)
double precision :: p, q, r, s, t, w, x, y, zz, norm, machep, &
&dpmpar
!     double precision dsqrt,dabs
!     integer min0
logical :: notlas
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure hqr,
!     NUM. Math. 14, 219-231(1970) By Martin, peters, and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 359-371(1971).
!
!     dhqr finds the eigenvalues of a double precision real
!     upper Hessenberg matrix BY the QR method.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dbal.  If dbal has not been used then
!          SET low=1, igh=n,
!
!        h contains the upper Hessenberg matrix.  Information about
!          the transformations used in the reduction to Hessenberg
!          form by dorth, if performed, is stored
!          in the remaining triangle under the Hessenberg matrix.
!
!     On output-
!
!        h has been destroyed.  Therefore, it must be saved
!          before calling  hqr  if subsequent calculation and
!          back transformation of eigenvectors is to be performed,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  The eigenvalues
!          are unordered except that complex conjugate pairs
!          of values appear consecutively with the eigenvalue
!          having the positive imaginary part first.  If an
!          error exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 50 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                machep the value U where U is the smallest positive
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0
!                in the double precision arithmetic being used.
!
           machep = dpmpar(1)
!
!                **********
!
ierr = 0
norm = 0.d0
k = 1
!     ********** STORE ROOTS ISOLATED BY DBAL
!                AND COMPUTE MATRIX norm **********
do 50 i = 1, n
!
   do 40 j = k, n
40 norm = norm + dabs(h(i,j))
!
   k = i
   if (i .ge. low .and. i .le. igh) go to 50
   wr(i) = h(i,i)
   wi(i) = 0.d0
50 continue
!
en = igh
t = 0.d0
!     ********** SEARCH FOR NEXT EIGENVALUES **********
60 if (en .lt. low) go to 1001
its = 0
na = en - 1
enm2 = na - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR l=en STEP -1 UNTIL LOW DO -- **********
70 do ll = low, en
   l = en + low - ll
   if (l .eq. low) go to 100
   s = dabs(h(l-1,l-1)) + dabs(h(l,l))
   if (s .eq. 0.d0) s = norm
   if (dabs(h(l,l-1)) .le. machep * s) go to 100
end do
!     ********** FORM SHIFT **********
100 x = h(en,en)
if (l .eq. en) go to 270
y = h(na,na)
w = h(en,na) * h(na,en)
if (l .eq. na) go to 280
if (its .eq. 50) go to 1000
if (its .ne. 10 .and. its .ne. 20 .and. its .ne. 30) go to 130
!     ********** FORM EXCEPTIONAL SHIFT **********
t = t + x
!
do 120 i = low, en
120 h(i,i) = h(i,i) - x
!
s = dabs(h(en,na)) + dabs(h(na,enm2))
x = .75d0 * s
y = x
w = -.4375d0 * s * s
130 its = its + 1
!     ********** LOOK FOR TWO CONSECUTIVE SMALL
!                sub-diagonal elements.
!                FOR m=en-2 STEP -1 UNTIL l DO -- **********
do mm = l, enm2
   m = enm2 + l - mm
   zz = h(m,m)
   r = x - zz
   s = y - zz
   p = (r * s - w) / h(m+1,m) + h(m,m+1)
   q = h(m+1,m+1) - zz - r - s
   r = h(m+2,m+1)
   s = dabs(p) + dabs(q) + dabs(r)
   p = p / s
   q = q / s
   r = r / s
   if (m .eq. l) go to 150
   if (dabs(h(m,m-1)) * (dabs(q) + dabs(r)) .le. machep * dabs(p) &
&* (dabs(h(m-1,m-1)) + dabs(zz) + dabs(h(m+1,m+1)))) go to 150
end do
!
150 mp2 = m + 2
!
do 160 i = mp2, en
   h(i,i-2) = 0.d0
   if (i .eq. mp2) go to 160
   h(i,i-3) = 0.d0
160 continue
!     ********** DOUBLE QR STEP INVOLVING ROWS l TO en AND
!                COLUMNS m TO en **********
do 260 k = m, na
   notlas = k .ne. na
   if (k .eq. m) go to 170
   p = h(k,k-1)
   q = h(k+1,k-1)
   r = 0.d0
   if (notlas) r = h(k+2,k-1)
   x = dabs(p) + dabs(q) + dabs(r)
   if (x .eq. 0.d0) go to 260
   p = p / x
   q = q / x
   r = r / x
170 s = dsqrt(p*p + q*q + r*r)
   if (p .lt. 0.d0) s = -s
   if (k .eq. m) go to 180
   h(k,k-1) = -s * x
   go to 190
180 if (l .ne. m) h(k,k-1) = -h(k,k-1)
190 p = p + s
   x = p / s
   y = q / s
   zz = r / s
   q = q / p
   r = r / p
!     ********** ROW MODIFICATION **********
   do j = k, en
      p = h(k,j) + q * h(k+1,j)
      if (.not. notlas) go to 200
      p = p + r * h(k+2,j)
      h(k+2,j) = h(k+2,j) - p * zz
200 h(k+1,j) = h(k+1,j) - p * y
      h(k,j) = h(k,j) - p * x
   end do
!
   j = min0(en,k+3)
!     ********** COLUMN MODIFICATION **********
   do i = l, j
      p = x * h(i,k) + y * h(i,k+1)
      if (.not. notlas) go to 220
      p = p + zz * h(i,k+2)
      h(i,k+2) = h(i,k+2) - p * r
220 h(i,k+1) = h(i,k+1) - p * q
      h(i,k) = h(i,k) - p
   end do
!
260 continue
!
go to 70
!     ********** ONE ROOT FOUND **********
270 wr(en) = x + t
wi(en) = 0.d0
en = na
go to 60
!     ********** TWO ROOTS FOUND **********
280 p = (y - x) / 2.d0
q = p * p + w
zz = dsqrt(dabs(q))
x = x + t
if (q .lt. 0.d0) go to 320
!     ********** REAL PAIR **********
if (p .lt. 0.d0) zz = -zz
zz = p + zz
wr(na) = x + zz
wr(en) = wr(na)
if (zz .ne. 0.d0) wr(en) = x - w / zz
wi(na) = 0.d0
wi(en) = 0.d0
go to 330
!     ********** COMPLEX PAIR **********
320 wr(na) = x + p
wr(en) = x + p
wi(na) = zz
wi(en) = -zz
330 en = enm2
go to 60
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 ierr = en
1001 return
end subroutine dhqr

subroutine dbabk(nm,n,low,igh,scale,m,z)
implicit none
!
integer :: i, j, k
integer, intent(in) :: m, n
integer :: ii
integer, intent(in) :: nm, igh, low
double precision, intent(in) :: scale(n)
double precision, intent(inout) :: z(nm,m)
double precision :: s
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure balbak,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 315-326(1971).
!
!     This subroutine forms the eigenvectors of a real general
!     matrix BY back transforming those of the corresponding
!     balanced matrix determined by dbal.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by dbal,
!
!        Scale contains information determining the permutations
!          and scaling factors used by dbal,
!
!        m is the number of columns of z to be back transformed,
!
!        z contains the real and imaginary parts of the eigen-
!          vectors to be back transformed in its first m columns.
!
!     On output-
!
!        z contains the real and imaginary parts of the
!          transformed eigenvectors in its first m columns.
!
!-----------------------------------------------------------------------
!
if (m .eq. 0) go to 200
if (igh .eq. low) go to 120
!
do i = low, igh
   s = scale(i)
!     ********** LEFT HAND EIGENVECTORS ARE BACK TRANSFORMED
!                if the foregoing statement is replaced by
!                s=1.0/scale(i). **********
   do 100 j = 1, m
100 z(i,j) = z(i,j) * s
!
end do
!     ********- FOR i=low-1 STEP -1 UNTIL 1,
!               igh+1 STEP 1 UNTIL n DO -- **********
120 do 140 ii = 1, n
   i = ii
   if (i .ge. low .and. i .le. igh) go to 140
   if (i .lt. low) i = low - ii
   k = scale(i)
   if (k .eq. i) go to 140
!
   do j = 1, m
      s = z(i,j)
      z(i,j) = z(k,j)
      z(k,j) = s
   end do
!
140 continue
!
200 return
end subroutine dbabk

subroutine dortrn(nm,n,low,igh,a,ort,z)
implicit none
!
integer :: i, j
integer, intent(in) :: n
integer :: kl, mm, mp
integer, intent(in) :: nm, igh, low
integer :: mp1
double precision, intent(in) :: a(nm,igh)
double precision, intent(inout) :: ort(igh), z(nm,n)
double precision :: g
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ORTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the orthogonal similarity
!     transformations used in the reduction of a real double
!     precision matrix to upper Hessenberg form by dorth.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dbal.  If dbal has not been used then
!          SET low=1, igh=n,
!
!        A contains information about the orthogonal trans-
!          formations used in the reduction by dorth
!          in its strict lower triangle,
!
!        Ort contains further information about the trans-
!          formations used in the reduction by dorth.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by dorth,
!
!        Ort has been altered.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE z TO IDENTITY MATRIX **********
do i = 1, n
!
   do 60 j = 1, n
60 z(i,j) = 0.d0
!
   z(i,i) = 1.d0
end do
!
kl = igh - low - 1
if (kl .lt. 1) go to 200
!     ********** FOR mp=igh-1 STEP -1 UNTIL low+1 DO -- **********
do 140 mm = 1, kl
   mp = igh - mm
   if (a(mp,mp-1) .eq. 0.d0) go to 140
   mp1 = mp + 1
!
   do 100 i = mp1, igh
100 ort(i) = a(i,mp-1)
!
   do j = mp, igh
      g = 0.d0
!
      do 110 i = mp, igh
110 g = g + ort(i) * z(i,j)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN orthes.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      g = (g / ort(mp)) / a(mp,mp-1)
!
      do 120 i = mp, igh
120 z(i,j) = z(i,j) + g * ort(i)
!
   end do
!
140 continue
!
200 return
end subroutine dortrn

subroutine drtrn1(n,low,igh,a,na,z,nz,ort)
implicit none
!
integer :: i, j
integer, intent(in) :: n
integer :: kl, mm, mp
integer, intent(in) :: na, igh, low
integer :: mp1
integer, intent(in) :: nz
double precision, intent(in) :: a(na,igh)
double precision, intent(inout) :: ort(igh), z(nz,n)
double precision :: g
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ORTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the orthogonal similarity
!     transformations used in the reduction of a real double
!     precision matrix to upper Hessenberg form by dorth.
!
!     On input-
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dbal.  If dbal has not been used then
!          SET low=1, igh=n,
!
!        A contains information about the orthogonal trans-
!          formations used in the reduction by dorth
!          in its strict lower triangle,
!
!        na must be set to the row dimension of the 2-dimensional
!          array parameter  a  as declared in the calling program
!          dimension statement,
!
!        nz must be set to the row dimension of the 2-dimensional
!          array parameter  z  as declared in the calling program
!          dimension statement,
!
!        Ort contains further information about the trans-
!          formations used in the reduction by dorth.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by dorth,
!
!        Ort has been altered.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE z TO IDENTITY MATRIX **********
do i = 1, n
!
   do 60 j = 1, n
60 z(i,j) = 0.d0
!
   z(i,i) = 1.d0
end do
!
kl = igh - low - 1
if (kl .lt. 1) go to 200
!     ********** FOR mp=igh-1 STEP -1 UNTIL low+1 DO -- **********
do 140 mm = 1, kl
   mp = igh - mm
   if (a(mp,mp-1) .eq. 0.d0) go to 140
   mp1 = mp + 1
!
   do 100 i = mp1, igh
100 ort(i) = a(i,mp-1)
!
   do j = mp, igh
      g = 0.d0
!
      do 110 i = mp, igh
110 g = g + ort(i) * z(i,j)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN orthes.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      g = (g / ort(mp)) / a(mp,mp-1)
!
      do 120 i = mp, igh
120 z(i,j) = z(i,j) + g * ort(i)
!
   end do
!
140 continue
!
200 return
end subroutine drtrn1

subroutine dhqr2(nm,n,low,igh,h,wr,wi,z,ierr)
implicit none
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: en, ii, jj, ll, mm, na
integer, intent(in) :: nm
integer :: nn
integer, intent(in) :: igh
integer :: its
integer, intent(in) :: low
integer :: mp2, enm2
integer, intent(out) :: ierr
double precision, intent(inout) :: h(nm,n), wr(n), wi(n), z(nm,n)
double precision :: a, b, d, p, q, r, s, t, u, w, x, y
double precision :: ra, sa, vi, vr, zz, norm, machep
!     integer min0
!     double precision dsqrt,dabs
double precision :: dpmpar
logical :: notlas
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure hqr2,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 372-395(1971).
!
!     This subroutine finds the eigenvalues and eigenvectors
!     of a real double precision upper Hessenberg matrix BY the
!     QR method.  The eigenvectors of a real general matrix can
!     also be found if dorth and dortrn have been used to reduce
!     this general matrix to Hessenberg form and to accumulate
!     the similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dbal.  If dbal has not been used then
!          SET low=1, igh=n,
!
!        h contains the upper Hessenberg matrix,
!
!        z contains the transformation matrix produced by dortrn
!          after the reduction by dorth, if performed. If the
!          eigenvectors of the Hessenberg matrix are desired,
!          z must contain the identity matrix.
!
!     On output-
!
!        h has been destroyed,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  The eigenvalues
!          are unordered except that complex conjugate pairs
!          of values appear consecutively with the eigenvalue
!          having the positive imaginary part first.  If an
!          error exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        z contains the real and imaginary parts of the eigenvectors.
!          If the i-TH eigenvalue is real, the i-TH column of z
!          contains its eigenvector.  If the i-TH eigenvalue is complex
!          with positive imaginary part, the i-TH and (i+1)-TH
!          columns of z contain the real and imaginary parts of its
!          eigenvector.  The eigenvectors are unnormalized.  If an
!          error exit is made, none of the eigenvectors has been found,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 50 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                machep the value u where u is the smallest positive
!                FLOATING POINT NUMBER SUCH THAT 1.0 + u .GT. 1.0
!                in the double precision arithmetic being used.
!
           machep = dpmpar(1)
!
!                **********
!
ierr = 0
norm = 0.d0
k = 1
!     ********** STORE ROOTS ISOLATED BY DBAL
!                AND COMPUTE MATRIX norm **********
do 50 i = 1, n
!
   do 40 j = k, n
40 norm = norm + dabs(h(i,j))
!
   k = i
   if (i .ge. low .and. i .le. igh) go to 50
   wr(i) = h(i,i)
   wi(i) = 0.d0
50 continue
!
en = igh
t = 0.d0
!     ********** SEARCH FOR NEXT EIGENVALUES **********
60 if (en .lt. low) go to 340
its = 0
na = en - 1
enm2 = na - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR l=en STEP -1 UNTIL LOW DO -- **********
70 do ll = low, en
   l = en + low - ll
   if (l .eq. low) go to 100
   s = dabs(h(l-1,l-1)) + dabs(h(l,l))
   if (s .eq. 0.d0) s = norm
   if (dabs(h(l,l-1)) .le. machep * s) go to 100
end do
!     ********** FORM SHIFT **********
100 x = h(en,en)
if (l .eq. en) go to 270
y = h(na,na)
w = h(en,na) * h(na,en)
if (l .eq. na) go to 280
if (its .eq. 50) go to 1000
if (its .ne. 10 .and. its .ne. 20 .and. its .ne. 30) go to 130
!     ********** FORM EXCEPTIONAL SHIFT **********
t = t + x
!
do 120 i = low, en
120 h(i,i) = h(i,i) - x
!
s = dabs(h(en,na)) + dabs(h(na,enm2))
x = .75d0 * s
y = x
w = -.4375d0 * s * s
130 its = its + 1
!     ********** LOOK FOR TWO CONSECUTIVE SMALL
!                sub-diagonal elements.
!                FOR m=en-2 STEP -1 UNTIL l DO -- **********
do mm = l, enm2
   m = enm2 + l - mm
   zz = h(m,m)
   r = x - zz
   s = y - zz
   p = (r * s - w) / h(m+1,m) + h(m,m+1)
   q = h(m+1,m+1) - zz - r - s
   r = h(m+2,m+1)
   s = dabs(p) + dabs(q) + dabs(r)
   p = p / s
   q = q / s
   r = r / s
   if (m .eq. l) go to 150
   if (dabs(h(m,m-1)) * (dabs(q) + dabs(r)) .le. machep * dabs(p) &
&* (dabs(h(m-1,m-1)) + dabs(zz) + dabs(h(m+1,m+1)))) go to 150
end do
!
150 mp2 = m + 2
!
do 160 i = mp2, en
   h(i,i-2) = 0.d0
   if (i .eq. mp2) go to 160
   h(i,i-3) = 0.d0
160 continue
!     ********** DOUBLE QR STEP INVOLVING ROWS l TO en AND
!                COLUMNS m TO en **********
do 260 k = m, na
   notlas = k .ne. na
   if (k .eq. m) go to 170
   p = h(k,k-1)
   q = h(k+1,k-1)
   r = 0.d0
   if (notlas) r = h(k+2,k-1)
   x = dabs(p) + dabs(q) + dabs(r)
   if (x .eq. 0.d0) go to 260
   p = p / x
   q = q / x
   r = r / x
170 s = dsqrt(p*p + q*q + r*r)
   if (p .lt. 0.d0) s = -s
   if (k .eq. m) go to 180
   h(k,k-1) = -s * x
   go to 190
180 if (l .ne. m) h(k,k-1) = -h(k,k-1)
190 p = p + s
   x = p / s
   y = q / s
   zz = r / s
   q = q / p
   r = r / p
!     ********** ROW MODIFICATION **********
   do j = k, n
      p = h(k,j) + q * h(k+1,j)
      if (.not. notlas) go to 200
      p = p + r * h(k+2,j)
      h(k+2,j) = h(k+2,j) - p * zz
200 h(k+1,j) = h(k+1,j) - p * y
      h(k,j) = h(k,j) - p * x
   end do
!
   j = min0(en,k+3)
!     ********** COLUMN MODIFICATION **********
   do i = 1, j
      p = x * h(i,k) + y * h(i,k+1)
      if (.not. notlas) go to 220
      p = p + zz * h(i,k+2)
      h(i,k+2) = h(i,k+2) - p * r
220 h(i,k+1) = h(i,k+1) - p * q
      h(i,k) = h(i,k) - p
   end do
!     ********** ACCUMULATE TRANSFORMATIONS **********
   do i = low, igh
      p = x * z(i,k) + y * z(i,k+1)
      if (.not. notlas) go to 240
      p = p + zz * z(i,k+2)
      z(i,k+2) = z(i,k+2) - p * r
240 z(i,k+1) = z(i,k+1) - p * q
      z(i,k) = z(i,k) - p
   end do
!
260 continue
!
go to 70
!     ********** ONE ROOT FOUND **********
270 h(en,en) = x + t
wr(en) = h(en,en)
wi(en) = 0.d0
en = na
go to 60
!     ********** TWO ROOTS FOUND **********
280 p = (y - x) / 2.d0
q = p * p + w
zz = dsqrt(dabs(q))
h(en,en) = x + t
x = h(en,en)
h(na,na) = y + t
if (q .lt. 0.d0) go to 320
!     ********** REAL PAIR **********
if (p .lt. 0.d0) zz = -zz
zz = p + zz
wr(na) = x + zz
wr(en) = wr(na)
if (zz .ne. 0.d0) wr(en) = x - w / zz
wi(na) = 0.d0
wi(en) = 0.d0
x = h(en,na)
s = dabs(x) + dabs(zz)
p = x / s
q = zz / s
r = dsqrt(p*p+q*q)
p = p / r
q = q / r
!     ********** ROW MODIFICATION **********
do j = na, n
   zz = h(na,j)
   h(na,j) = q * zz + p * h(en,j)
   h(en,j) = q * h(en,j) - p * zz
end do
!     ********** COLUMN MODIFICATION **********
do i = 1, en
   zz = h(i,na)
   h(i,na) = q * zz + p * h(i,en)
   h(i,en) = q * h(i,en) - p * zz
end do
!     ********** ACCUMULATE TRANSFORMATIONS **********
do i = low, igh
   zz = z(i,na)
   z(i,na) = q * zz + p * z(i,en)
   z(i,en) = q * z(i,en) - p * zz
end do
!
go to 330
!     ********** COMPLEX PAIR **********
320 wr(na) = x + p
wr(en) = x + p
wi(na) = zz
wi(en) = -zz
330 en = enm2
go to 60
!     ********** ALL ROOTS FOUND.  BACKSUBSTITUTE TO FIND
!                VECTORS OF UPPER TRIANGULAR FORM **********
340 if (norm .eq. 0.d0) go to 1001
!     ********** FOR en=n STEP -1 UNTIL 1 DO -- **********
do 800 nn = 1, n
   en = n + 1 - nn
   p = wr(en)
   q = wi(en)
   na = en - 1
   if (q) 710, 600, 800
!     ********** REAL VECTOR **********
600 m = en
   h(en,en) = 1.d0
   if (na .eq. 0) go to 800
!     ********** FOR i=en-1 STEP -1 UNTIL 1 DO -- **********
   do 700 ii = 1, na
      i = en - ii
      w = h(i,i) - p
      r = h(i,en)
      if (m .gt. na) go to 620
!
      do 610 j = m, na
610 r = r + h(i,j) * h(j,en)
!
620 if (wi(i) .ge. 0.d0) go to 630
      zz = w
      s = r
      go to 700
630 m = i
      if (wi(i) .ne. 0.d0) go to 640
      t = w
      if (w .eq. 0.d0) t = machep * norm
      h(i,en) = -r / t
      go to 700
!     ********** SOLVE REAL EQUATIONS **********
640 x = h(i,i+1)
      y = h(i+1,i)
      q = (wr(i) - p) * (wr(i) - p) + wi(i) * wi(i)
      t = (x * s - zz * r) / q
      h(i,en) = t
      if (dabs(x) .le. dabs(zz)) go to 650
      h(i+1,en) = (-r - w * t) / x
      go to 700
650 h(i+1,en) = (-s - y * t) / zz
700 continue
!     ********** END REAL VECTOR **********
   go to 800
!     ********** COMPLEX VECTOR **********
710 m = na
!     ********** LAST VECTOR COMPONENT CHOSEN IMAGINARY SO THAT
!                EIGENVECTOR MATRIX IS TRIANGULAR **********
   if (dabs(h(en,na)) .le. dabs(h(na,en))) go to 720
   h(na,na) = q / h(en,na)
   h(na,en) = -(h(en,en) - p) / h(en,na)
   go to 730
720 u = h(na,na) - p
   b = -h(na,en) / (u * u + q * q)
   h(na,na) = b * q
   h(na,en) = b * u
730 h(en,na) = 0.d0
   h(en,en) = 1.d0
   enm2 = na - 1
   if (enm2 .eq. 0) go to 800
!     ********** FOR i=en-2 STEP -1 UNTIL 1 DO -- **********
   do 790 ii = 1, enm2
      i = na - ii
      w = h(i,i) - p
      ra = 0.d0
      sa = h(i,en)
!
      do j = m, na
         ra = ra + h(i,j) * h(j,na)
         sa = sa + h(i,j) * h(j,en)
      end do
!
      if (wi(i) .ge. 0.d0) go to 770
      zz = w
      r = ra
      s = sa
      go to 790
770 m = i
      if (wi(i) .ne. 0.d0) go to 780
      d = w * w + q * q
      h(i,na) = -(ra * w + sa * q) / d
      h(i,en) = (ra * q - sa * w) / d
      go to 790
!     ********** SOLVE COMPLEX EQUATIONS **********
780 x = h(i,i+1)
      y = h(i+1,i)
      vr = (wr(i) - p) * (wr(i) - p) + wi(i) * wi(i) - q * q
      vi = (wr(i) - p) * 2.d0 * q
      if (vr .eq. 0.d0 .and. vi .eq. 0.d0) vr = machep * norm &
&* (dabs(w) + dabs(q) + dabs(x) + dabs(y) + dabs(zz))
      a = x * r - zz * ra + q * sa
      b = x * s - zz * sa - q * ra
      d = vr * vr + vi * vi
      h(i,na) = (a * vr + b * vi) / d
      h(i,en) = (b * vr - a * vi) / d
      if (dabs(x) .le. dabs(zz) + dabs(q)) go to 785
      h(i+1,na) = (-ra - w * h(i,na) + q * h(i,en)) / x
      h(i+1,en) = (-sa - w * h(i,en) - q * h(i,na)) / x
      go to 790
785 a = -r - y * h(i,na)
      b = -s - y * h(i,en)
      d = zz * zz + q * q
      h(i+1,na) = (a * zz + b * q) / d
      h(i+1,en) = (b * zz - a * q) / d
790 continue
!     ********** END COMPLEX VECTOR **********
800 continue
!     ********** END BACK SUBSTITUTION.
!                VECTORS OF ISOLATED ROOTS **********
do 840 i = 1, n
   if (i .ge. low .and. i .le. igh) go to 840
!
   do 820 j = i, n
820 z(i,j) = h(i,j)
!
840 continue
!     ********** MULTIPLY BY TRANSFORMATION MATRIX TO GIVE
!                vectors of original full matrix.
!                FOR j=n STEP -1 UNTIL LOW DO -- **********
do 880 jj = low, n
   j = n + low - jj
   m = min0(j,igh)
!
   do 880 i = low, igh
      zz = 0.d0
!
      do 860 k = low, m
860 zz = zz + z(i,k) * h(k,j)
!
      z(i,j) = zz
880 continue
!
go to 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 ierr = en
1001 return
end subroutine dhqr2

subroutine seig (a, ka, n, w, t, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka
integer :: n
integer :: l
!-----------------------------------------------------------------------
!               Eigenvalues of symmetric real matrices
!-----------------------------------------------------------------------
real, intent(inout) :: a(*), w(n), t(*)
!
if (ka .eq. 0) go to 10
   call tred1 (ka, n, a, w, t(n+1), t(1))
   call tqlrat (n, w, t, ierr)
   return
10 l = n*(n + 1)
l = l/2
call tred3 (n, l, a, w, t(n+1), t(1))
call tqlrat (n, w, t, ierr)
return
end subroutine seig

subroutine seig1 (a, ka, n, w, t, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
integer :: l
!-----------------------------------------------------------------------
!               Eigenvalues of symmetric real matrices
!-----------------------------------------------------------------------
real, intent(inout) :: a(*), w(n), t(n)
!
if (ka .eq. 0) go to 10
   call tred1 (ka, n, a, w, t, t)
   call imtql1 (n, w, t, ierr)
   return
10 l = n*(n + 1)
l = l/2
call tred3 (n, l, a, w, t, t)
call imtql1 (n, w, t, ierr)
return
end subroutine seig1

subroutine seigv (a, ka, n, w, z, t, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
!-----------------------------------------------------------------------
!        Eigenvalues and eigenvectors of symmetric real matrices
!-----------------------------------------------------------------------
real, intent(in) :: a(ka,n)
real, intent(inout) :: w(n), z(ka,n), t(n)
!
call tred2 (ka, n, a, w, t, z)
call tql2 (ka, n, w, t, z, ierr)
return
end subroutine seigv

subroutine seigv1 (a, ka, n, w, z, t, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
!-----------------------------------------------------------------------
!        Eigenvalues and eigenvectors of symmetric real matrices
!-----------------------------------------------------------------------
real, intent(in) :: a(ka,n)
real, intent(inout) :: w(n), z(ka,n), t(n)
!
call tred2 (ka, n, a, w, t, z)
call imtql2 (ka, n, w, t, z, ierr)
return
end subroutine seigv1

subroutine tred1(nm,n,a,d,e,e2)
implicit none
!
integer :: i, j, k, l
integer, intent(in) :: n
integer :: ii
integer, intent(in) :: nm
integer :: jp1
real, intent(inout) :: a(nm,n), d(n), e(n), e2(n)
real :: f, g, h, scale
!     real sqrt,abs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure tred1,
!     NUM. Math. 11, 181-195(1968) By Martin, Reinsch, and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 212-226(1971).
!
!     This subroutine reduces a real symmetric matrix
!     to a symmetric tridiagonal matrix using
!     orthogonal similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        A contains the real symmetric input matrix.  Only the
!          lower triangle of the matrix need be supplied.
!
!     On output-
!
!        A contains information about the orthogonal trans-
!          formations used in the reduction in its strict lower
!          triangle.  The full upper triangle of A is unaltered,
!
!        d contains the diagonal elements of the tridiagonal matrix,
!
!        e contains the subdiagonal elements of the tridiagonal
!          matrix in its last n-1 positions.  e(1) is set to zero,
!
!        e2 contains the squares of the corresponding elements of e.
!          e2 may coincide with e if the squares are not needed.
!
!-----------------------------------------------------------------------
!
do 100 i = 1, n
100 d(i) = a(i,i)
!     ********** FOR i=n STEP -1 UNTIL 1 DO -- **********
do ii = 1, n
   i = n + 1 - ii
   l = i - 1
   h = 0.0
   scale = 0.0
   if (l .lt. 1) go to 130
!     ********** scale ROW (ALGOL TOL THEN NOT NEEDED) **********
   do 120 k = 1, l
120 scale = scale + abs(a(i,k))
!
   if (scale .ne. 0.0) go to 140
130 e(i) = 0.0
   e2(i) = 0.0
   go to 290
!
140 do k = 1, l
      a(i,k) = a(i,k) / scale
      h = h + a(i,k) * a(i,k)
   end do
!
   e2(i) = scale * scale * h
   f = a(i,l)
   g = sqrt(h)
   if (f .ge. 0.0) g = -g
   e(i) = scale * g
   h = h - f * g
   a(i,l) = f - g
   if (l .eq. 1) go to 270
   f = 0.0
!
   do j = 1, l
      g = 0.0
!     ********** FORM ELEMENT OF a*U **********
      do 180 k = 1, j
180 g = g + a(j,k) * a(i,k)
!
      jp1 = j + 1
      if (l .lt. jp1) go to 220
!
      do 200 k = jp1, l
200 g = g + a(k,j) * a(i,k)
!     ********** FORM ELEMENT OF P **********
220 e(j) = g / h
      f = f + e(j) * a(i,j)
   end do
!
   h = f / (h + h)
!     ********** FORM REDUCED a **********
   do 260 j = 1, l
      f = a(i,j)
      g = e(j) - h * f
      e(j) = g
!
      do 260 k = 1, j
         a(j,k) = a(j,k) - f * e(k) - g * a(i,k)
260 continue
!
270 do 280 k = 1, l
280 a(i,k) = scale * a(i,k)
!
290 h = d(i)
   d(i) = a(i,i)
   a(i,i) = h
end do
!
return
!     ********** LAST CARD OF tred1 **********
end subroutine tred1

subroutine tred3(n,nv,a,d,e,e2)
implicit none
!
integer :: i, j, k, l
integer, intent(in) :: n
integer :: ii, iz, jk
integer, intent(in) :: nv
real, intent(inout) :: a(nv), d(n), e(n), e2(n)
real :: f, g, h, hh, scale
!     real sqrt,abs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure tred3,
!     NUM. Math. 11, 181-195(1968) By Martin, Reinsch, and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 212-226(1971).
!
!     This subroutine reduces a real symmetric matrix, stored as
!     a one-dimensional array, to a symmetric tridiagonal matrix
!     using orthogonal similarity transformations.
!
!     On input-
!
!        n is the order of the matrix,
!
!        nv must be set to the dimension of the array parameter A
!          as declared in the calling program dimension statement,
!
!        A contains the lower triangle of the real symmetric
!          input matrix, stored row-wise as a one-dimensional
!          array, in its first n*(n+1)/2 positions.
!
!     On output-
!
!        A contains information about the orthogonal
!          transformations used in the reduction,
!
!        d contains the diagonal elements of the tridiagonal matrix,
!
!        e contains the subdiagonal elements of the tridiagonal
!          matrix in its last n-1 positions.  e(1) is set to zero,
!
!        e2 contains the squares of the corresponding elements of e.
!          e2 may coincide with e if the squares are not needed.
!
!-----------------------------------------------------------------------
!
!     ********** FOR i=n STEP -1 UNTIL 1 DO -- **********
do ii = 1, n
   i = n + 1 - ii
   l = i - 1
   iz = (i * l) / 2
   h = 0.0
   scale = 0.0
   if (l .lt. 1) go to 130
!     ********** scale ROW (ALGOL TOL THEN NOT NEEDED) **********
   do k = 1, l
      iz = iz + 1
      d(k) = a(iz)
      scale = scale + abs(d(k))
   end do
!
   if (scale .ne. 0.0) go to 140
130 e(i) = 0.0
   e2(i) = 0.0
   go to 290
!
140 do k = 1, l
      d(k) = d(k) / scale
      h = h + d(k) * d(k)
   end do
!
   e2(i) = scale * scale * h
   f = d(l)
   g = sqrt(h)
   if (f .ge. 0.0) g = -g
   e(i) = scale * g
   h = h - f * g
   d(l) = f - g
   a(iz) = scale * d(l)
   if (l .eq. 1) go to 290
   f = 0.0
!
   do j = 1, l
      g = 0.0
      jk = (j * (j-1)) / 2
!     ********** FORM ELEMENT OF a*U **********
      do k = 1, l
         jk = jk + 1
         if (k .gt. j) jk = jk + k - 2
         g = g + a(jk) * d(k)
      end do
!     ********** FORM ELEMENT OF P **********
      e(j) = g / h
      f = f + e(j) * d(j)
   end do
!
   hh = f / (h + h)
   jk = 0
!     ********** FORM REDUCED a **********
   do 260 j = 1, l
      f = d(j)
      g = e(j) - hh * f
      e(j) = g
!
      do 260 k = 1, j
         jk = jk + 1
         a(jk) = a(jk) - f * e(k) - g * d(k)
260 continue
!
290 d(i) = a(iz+1)
   a(iz+1) = scale * sqrt(h)
end do
!
return
!     ********** LAST CARD OF tred3 **********
end subroutine tred3

subroutine tqlrat(n,d,e2,ierr)
implicit none
real :: spmpar
!
integer :: i, j, l, m
integer, intent(in) :: n
integer :: ii, l1, mml
integer, intent(out) :: ierr
real, intent(inout) :: d(n), e2(n)
real :: b, c, f, g, h, p, r, s, machep
!     real sqrt,abs,spmpar
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure tqlrat,
!     algorithm 464, comm. ACM 16, 689(1973) by Reinsch.
!
!     This subroutine finds the eigenvalues of a symmetric
!     tridiagonal matrix BY the rational QL method.
!
!     On input-
!
!        n is the order of the matrix,
!
!        d contains the diagonal elements of the input matrix,
!
!        e2 contains the squares of the subdiagonal elements of the
!          input matrix in its last n-1 positions.  e2(1) is arbitrary.
!
!      On output-
!
!        d contains the eigenvalues in ascending order.  If an
!          error exit is made, the eigenvalues are correct and
!          ordered for indices 1,2,...ierr-1, but may not be
!          the smallest eigenvalues,
!
!        e2 has been destroyed,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 30 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                machep the value U where U is the smallest positive
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           machep = spmpar(1)
!
!                **********
!
ierr = 0
if (n .eq. 1) go to 1001
!
do 100 i = 2, n
100 e2(i-1) = e2(i)
!
f = 0.0
b = 0.0
e2(n) = 0.0
!
do l = 1, n
   j = 0
   h = machep * (abs(d(l)) + sqrt(e2(l)))
   if (b .gt. h) go to 105
   b = h
   c = b * b
!     ********** LOOK FOR SMALL SQUARED SUB-DIAGONAL ELEMENT **********
105 do m = l, n
      if (e2(m) .le. c) go to 120
!     ********** e2(n) IS ALWAYS ZERO, SO THERE IS NO EXIT
!                THROUGH THE BOTTOM OF THE LOOP **********
   end do
!
120 if (m .eq. l) go to 210
130 if (j .eq. 30) go to 1000
   j = j + 1
!     ********** FORM SHIFT **********
   l1 = l + 1
   s = sqrt(e2(l))
   g = d(l)
   p = (d(l1) - g) / (2.0 * s)
   r = sqrt(p*p+1.0)
   if (p .lt. 0.0) r = -r
   d(l) = s / (p + r)
   h = g - d(l)
!
   do 140 i = l1, n
140 d(i) = d(i) - h
!
   f = f + h
!     ********** RATIONAL QL TRANSFORMATION **********
   g = d(m)
   if (g .eq. 0.0) g = b
   h = g
   s = 0.0
   mml = m - l
!     ********** FOR i=m-1 STEP -1 UNTIL l DO -- **********
   do ii = 1, mml
      i = m - ii
      p = g * h
      r = p + e2(i)
      e2(i+1) = s * r
      s = e2(i) / r
      d(i+1) = h + s * (h + d(i))
      g = d(i) - e2(i) / g
      if (g .eq. 0.0) g = b
      h = g * p / r
   end do
!
   e2(l) = s * g
   d(l) = h
!     ********** GUARD AGAINST UNDERFLOW IN CONVERGENCE TEST **********
   if (h .eq. 0.0) go to 210
   if (abs(e2(l)) .le. abs(c/h)) go to 210
   e2(l) = h * e2(l)
   if (e2(l) .ne. 0.0) go to 130
210 p = d(l) + f
!     ********** ORDER EIGENVALUES **********
   if (l .eq. 1) go to 250
!     ********** FOR i=l STEP -1 UNTIL 2 DO -- **********
   do ii = 2, l
      i = l + 2 - ii
      if (p .ge. d(i-1)) go to 270
      d(i) = d(i-1)
   end do
!
250 i = 1
270 d(i) = p
end do
!
go to 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 ierr = l
1001 return
!     ********** LAST CARD OF tqlrat **********
end subroutine tqlrat

subroutine imtql1(n,d,e,ierr)
implicit none
real :: spmpar
!
integer :: i, j, l, m
integer, intent(in) :: n
integer :: ii, mml
integer, intent(out) :: ierr
real, intent(inout) :: d(n), e(n)
real :: b, c, f, g, p, r, s, machep
!     real sqrt,abs,spmpar
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure imtql1,
!     NUM. Math. 12, 377-383(1968) By Martin and Wilkinson,
!     as modified in NUM. Math. 15, 450(1970) By Dubrulle.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 241-248(1971).
!
!     This subroutine finds the eigenvalues of a symmetric
!     tridiagonal matrix BY the implicit QL method.
!
!     On input-
!
!        n is the order of the matrix,
!
!        d contains the diagonal elements of the input matrix,
!
!        e contains the subdiagonal elements of the input matrix
!          in its last n-1 positions.  e(1) is arbitrary.
!
!      On output-
!
!        d contains the eigenvalues in ascending order.  If an
!          error exit is made, the eigenvalues are correct and
!          ordered for indices 1,2,...ierr-1, but may not be
!          the smallest eigenvalues,
!
!        e has been destroyed,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 30 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                machep the value U where U is the smallest positive
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           machep = spmpar(1)
!
!                **********
!
ierr = 0
if (n .eq. 1) go to 1001
!
do 100 i = 2, n
100 e(i-1) = e(i)
!
e(n) = 0.0
!
do l = 1, n
   j = 0
!     ********** LOOK FOR SMALL SUB-DIAGONAL ELEMENT **********
105 do m = l, n
      if (m .eq. n) go to 120
      if (abs(e(m)) .le. machep * (abs(d(m)) + abs(d(m+1)))) &
&go to 120
   end do
!
120 p = d(l)
   if (m .eq. l) go to 215
   if (j .eq. 30) go to 1000
   j = j + 1
!     ********** FORM SHIFT **********
   g = (d(l+1) - p) / (2.0 * e(l))
   r = sqrt(g*g+1.0)
   if (g .lt. 0.0) r = -r
   g = d(m) - p + e(l) / (g + r)
   s = 1.0
   c = 1.0
   p = 0.0
   mml = m - l
!     ********** FOR i=m-1 STEP -1 UNTIL l DO -- **********
   do ii = 1, mml
      i = m - ii
      f = s * e(i)
      b = c * e(i)
      if (abs(f) .lt. abs(g)) go to 150
      c = g / f
      r = sqrt(c*c+1.0)
      e(i+1) = f * r
      s = 1.0 / r
      c = c * s
      go to 160
150 s = f / g
      r = sqrt(s*s+1.0)
      e(i+1) = g * r
      c = 1.0 / r
      s = s * c
160 g = d(i+1) - p
      r = (d(i) - g) * s + 2.0 * c * b
      p = s * r
      d(i+1) = g + p
      g = c * r - b
   end do
!
   d(l) = d(l) - p
   e(l) = g
   e(m) = 0.0
   go to 105
!     ********** ORDER EIGENVALUES **********
215 if (l .eq. 1) go to 250
!     ********** FOR i=l STEP -1 UNTIL 2 DO -- **********
   do ii = 2, l
      i = l + 2 - ii
      if (p .ge. d(i-1)) go to 270
      d(i) = d(i-1)
   end do
!
250 i = 1
270 d(i) = p
end do
!
go to 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 ierr = l
1001 return
!     ********** LAST CARD OF imtql1 **********
end subroutine imtql1

subroutine tred2(nm,n,a,d,e,z)
implicit none
!
integer :: i, j, k, l
integer, intent(in) :: n
integer :: ii
integer, intent(in) :: nm
integer :: jp1
real, intent(in) :: a(nm,n)
real, intent(inout) :: d(n), e(n), z(nm,n)
real :: f, g, h, hh, scale
!     real sqrt,abs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure tred2,
!     NUM. Math. 11, 181-195(1968) By Martin, Reinsch, and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 212-226(1971).
!
!     This subroutine reduces a real symmetric matrix to A
!     symmetric tridiagonal matrix using and accumulating
!     orthogonal similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        A contains the real symmetric input matrix.  Only the
!          lower triangle of the matrix need be supplied.
!
!     On output-
!
!        d contains the diagonal elements of the tridiagonal matrix,
!
!        e contains the subdiagonal elements of the tridiagonal
!          matrix in its last n-1 positions.  e(1) is set to zero,
!
!        z contains the orthogonal transformation matrix
!          produced in the reduction,
!
!        A and z may coincide.  If distinct, A is unaltered.
!
!-----------------------------------------------------------------------
!
do 100 i = 1, n
!
   do 100 j = 1, i
      z(i,j) = a(i,j)
100 continue
!
if (n .eq. 1) go to 320
!     ********** FOR i=n STEP -1 UNTIL 2 DO -- **********
do ii = 2, n
   i = n + 2 - ii
   l = i - 1
   h = 0.0
   scale = 0.0
   if (l .lt. 2) go to 130
!     ********** scale ROW (ALGOL TOL THEN NOT NEEDED) **********
   do 120 k = 1, l
120 scale = scale + abs(z(i,k))
!
   if (scale .ne. 0.0) go to 140
130 e(i) = z(i,l)
   go to 290
!
140 do k = 1, l
      z(i,k) = z(i,k) / scale
      h = h + z(i,k) * z(i,k)
   end do
!
   f = z(i,l)
   g = sqrt(h)
   if (f .ge. 0.0) g = -g
   e(i) = scale * g
   h = h - f * g
   z(i,l) = f - g
   f = 0.0
!
   do j = 1, l
      z(j,i) = z(i,j) / h
      g = 0.0
!     ********** FORM ELEMENT OF a*U **********
      do 180 k = 1, j
180 g = g + z(j,k) * z(i,k)
!
      jp1 = j + 1
      if (l .lt. jp1) go to 220
!
      do 200 k = jp1, l
200 g = g + z(k,j) * z(i,k)
!     ********** FORM ELEMENT OF P **********
220 e(j) = g / h
      f = f + e(j) * z(i,j)
   end do
!
   hh = f / (h + h)
!     ********** FORM REDUCED a **********
   do 260 j = 1, l
      f = z(i,j)
      g = e(j) - hh * f
      e(j) = g
!
      do 260 k = 1, j
         z(j,k) = z(j,k) - f * e(k) - g * z(i,k)
260 continue
!
290 d(i) = h
end do
!
320 d(1) = 0.0
e(1) = 0.0
!     ********** ACCUMULATION OF TRANSFORMATION MATRICES **********
do 500 i = 1, n
   l = i - 1
   if (d(i) .eq. 0.0) go to 380
!
   do 360 j = 1, l
      g = 0.0
!
      do 340 k = 1, l
340 g = g + z(i,k) * z(k,j)
!
      do 360 k = 1, l
         z(k,j) = z(k,j) - g * z(k,i)
360 continue
!
380 d(i) = z(i,i)
   z(i,i) = 1.0
   if (l .lt. 1) go to 500
!
   do j = 1, l
      z(i,j) = 0.0
      z(j,i) = 0.0
   end do
!
500 continue
!
return
!     ********** LAST CARD OF tred2 **********
end subroutine tred2

subroutine tql2(nm,n,d,e,z,ierr)
implicit none
real :: spmpar
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: ii, l1
integer, intent(in) :: nm
integer :: mml
integer, intent(out) :: ierr
real, intent(inout) :: d(n), e(n), z(nm,n)
real :: b, c, f, g, h, p, r, s, machep
!     real sqrt,abs,spmpar
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure tql2,
!     NUM. Math. 11, 293-306(1968) By Bowdler, Martin, Reinsch, and
!     Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 227-240(1971).
!
!     This subroutine finds the eigenvalues and eigenvectors
!     of a symmetric tridiagonal matrix BY the QL method.
!     The eigenvectors of a full symmetric matrix can also
!     be found if  tred2  has been used to reduce this
!     full matrix to tridiagonal form.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        d contains the diagonal elements of the input matrix,
!
!        e contains the subdiagonal elements of the input matrix
!          in its last n-1 positions.  e(1) is arbitrary,
!
!        z contains the transformation matrix produced in the
!          reduction by  tred2, if performed.  If the eigenvectors
!          of the tridiagonal matrix are desired, z must contain
!          the identity matrix.
!
!      On output-
!
!        d contains the eigenvalues in ascending order.  If an
!          error exit is made, the eigenvalues are correct but
!          unordered for indices 1,2,...,ierr-1,
!
!        e has been destroyed,
!
!        z contains orthonormal eigenvectors of the symmetric
!          tridiagonal (or full) matrix.  If an error exit is made,
!          z contains the eigenvectors associated with the stored
!          eigenvalues,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 30 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                machep the value U where U is the smallest positive
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           machep = spmpar(1)
!
!                **********
!
ierr = 0
if (n .eq. 1) go to 1001
!
do 100 i = 2, n
100 e(i-1) = e(i)
!
f = 0.0
b = 0.0
e(n) = 0.0
!
do l = 1, n
   j = 0
   h = machep * (abs(d(l)) + abs(e(l)))
   if (b .lt. h) b = h
!     ********** LOOK FOR SMALL SUB-DIAGONAL ELEMENT **********
   do m = l, n
      if (abs(e(m)) .le. b) go to 120
!     ********** e(n) IS ALWAYS ZERO, SO THERE IS NO EXIT
!                THROUGH THE BOTTOM OF THE LOOP **********
   end do
!
120 if (m .eq. l) go to 220
130 if (j .eq. 30) go to 1000
   j = j + 1
!     ********** FORM SHIFT **********
   l1 = l + 1
   g = d(l)
   p = (d(l1) - g) / (2.0 * e(l))
   r = sqrt(p*p+1.0)
   if (p .lt. 0.0) r = -r
   d(l) = e(l) / (p + r)
   h = g - d(l)
!
   do 140 i = l1, n
140 d(i) = d(i) - h
!
   f = f + h
!     ********** QL TRANSFORMATION **********
   p = d(m)
   c = 1.0
   s = 0.0
   mml = m - l
!     ********** FOR i=m-1 STEP -1 UNTIL l DO -- **********
   do ii = 1, mml
      i = m - ii
      g = c * e(i)
      h = c * p
      if (abs(p) .lt. abs(e(i))) go to 150
      c = e(i) / p
      r = sqrt(c*c+1.0)
      e(i+1) = s * p * r
      s = c / r
      c = 1.0 / r
      go to 160
150 c = p / e(i)
      r = sqrt(c*c+1.0)
      e(i+1) = s * e(i) * r
      s = 1.0 / r
      c = c * s
160 p = c * d(i) - s * g
      d(i+1) = h + s * (c * g + s * d(i))
!     ********** FORM VECTOR **********
      do k = 1, n
         h = z(k,i+1)
         z(k,i+1) = s * z(k,i) + c * h
         z(k,i) = c * z(k,i) - s * h
      end do
!
   end do
!
   e(l) = s * p
   d(l) = c * p
   if (abs(e(l)) .gt. b) go to 130
220 d(l) = d(l) + f
end do
!     ********** ORDER EIGENVALUES AND EIGENVECTORS **********
do 300 ii = 2, n
   i = ii - 1
   k = i
   p = d(i)
!
   do 260 j = ii, n
      if (d(j) .ge. p) go to 260
      k = j
      p = d(j)
260 continue
!
   if (k .eq. i) go to 300
   d(k) = d(i)
   d(i) = p
!
   do j = 1, n
      p = z(j,i)
      z(j,i) = z(j,k)
      z(j,k) = p
   end do
!
300 continue
!
go to 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 ierr = l
1001 return
!     ********** LAST CARD OF tql2 **********
end subroutine tql2

subroutine imtql2(nm,n,d,e,z,ierr)
implicit none
real :: spmpar
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: ii
integer, intent(in) :: nm
integer :: mml
integer, intent(out) :: ierr
real, intent(inout) :: d(n), e(n), z(nm,n)
real :: b, c, f, g, p, r, s, machep
!     real sqrt,abs,spmpar
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure imtql2,
!     NUM. Math. 12, 377-383(1968) By Martin and Wilkinson,
!     as modified in NUM. Math. 15, 450(1970) By Dubrulle.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 241-248(1971).
!
!     This subroutine finds the eigenvalues and eigenvectors
!     of a symmetric tridiagonal matrix BY the implicit QL method.
!     The eigenvectors of a full symmetric matrix can also
!     be found if  tred2  has been used to reduce this
!     full matrix to tridiagonal form.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        d contains the diagonal elements of the input matrix,
!
!        e contains the subdiagonal elements of the input matrix
!          in its last n-1 positions.  e(1) is arbitrary,
!
!        z contains the transformation matrix produced in the
!          reduction by  tred2, if performed.  If the eigenvectors
!          of the tridiagonal matrix are desired, z must contain
!          the identity matrix.
!
!      On output-
!
!        d contains the eigenvalues in ascending order.  If an
!          error exit is made, the eigenvalues are correct but
!          unordered for indices 1,2,...,ierr-1,
!
!        e has been destroyed,
!
!        z contains orthonormal eigenvectors of the symmetric
!          tridiagonal (or full) matrix.  If an error exit is made,
!          z contains the eigenvectors associated with the stored
!          eigenvalues,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 30 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                machep the value U where U is the smallest positive
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           machep = spmpar(1)
!
!                **********
!
ierr = 0
if (n .eq. 1) go to 1001
!
do 100 i = 2, n
100 e(i-1) = e(i)
!
e(n) = 0.0
!
do 240 l = 1, n
   j = 0
!     ********** LOOK FOR SMALL SUB-DIAGONAL ELEMENT **********
105 do m = l, n
      if (m .eq. n) go to 120
      if (abs(e(m)) .le. machep * (abs(d(m)) + abs(d(m+1)))) &
&go to 120
   end do
!
120 p = d(l)
   if (m .eq. l) go to 240
   if (j .eq. 30) go to 1000
   j = j + 1
!     ********** FORM SHIFT **********
   g = (d(l+1) - p) / (2.0 * e(l))
   r = sqrt(g*g+1.0)
   if (g .lt. 0.0) r = -r
   g = d(m) - p + e(l) / (g + r)
   s = 1.0
   c = 1.0
   p = 0.0
   mml = m - l
!     ********** FOR i=m-1 STEP -1 UNTIL l DO -- **********
   do ii = 1, mml
      i = m - ii
      f = s * e(i)
      b = c * e(i)
      if (abs(f) .lt. abs(g)) go to 150
      c = g / f
      r = sqrt(c*c+1.0)
      e(i+1) = f * r
      s = 1.0 / r
      c = c * s
      go to 160
150 s = f / g
      r = sqrt(s*s+1.0)
      e(i+1) = g * r
      c = 1.0 / r
      s = s * c
160 g = d(i+1) - p
      r = (d(i) - g) * s + 2.0 * c * b
      p = s * r
      d(i+1) = g + p
      g = c * r - b
!     ********** FORM VECTOR **********
      do k = 1, n
         f = z(k,i+1)
         z(k,i+1) = s * z(k,i) + c * f
         z(k,i) = c * z(k,i) - s * f
      end do
!
   end do
!
   d(l) = d(l) - p
   e(l) = g
   e(m) = 0.0
   go to 105
240 continue
!     ********** ORDER EIGENVALUES AND EIGENVECTORS **********
do 300 ii = 2, n
   i = ii - 1
   k = i
   p = d(i)
!
   do 260 j = ii, n
      if (d(j) .ge. p) go to 260
      k = j
      p = d(j)
260 continue
!
   if (k .eq. i) go to 300
   d(k) = d(i)
   d(i) = p
!
   do j = 1, n
      p = z(j,i)
      z(j,i) = z(j,k)
      z(j,k) = p
   end do
!
300 continue
!
go to 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 ierr = l
1001 return
!     ********** LAST CARD OF imtql2 **********
end subroutine imtql2

subroutine dseig (a, ka, n, w, t, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka
integer :: n
integer :: l
!-----------------------------------------------------------------------
!                Double precision computation of the
!               eigenvalues of symmetric real matrices
!-----------------------------------------------------------------------
double precision, intent(inout) :: a(*), w(n), t(*)
!
if (ka .eq. 0) go to 10
   call dtred1 (ka, n, a, w, t(n+1), t(1))
   call dtql (n, w, t, ierr)
   return
10 l = n*(n + 1)
l = l/2
call dtred3 (n, l, a, w, t(n+1), t(1))
call dtql (n, w, t, ierr)
return
end subroutine dseig

subroutine dseigv (a, ka, n, w, z, t, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
!-----------------------------------------------------------------------
!                 Double precision computation of
!                 eigenvalues and eigenvectors of
!                     symmetric real matrices
!-----------------------------------------------------------------------
double precision, intent(in) :: a(ka,n)
double precision, intent(inout) :: w(n), z(ka,n), t(n)
!
call dtred2 (ka, n, a, w, t, z)
call dtql2 (ka, n, w, t, z, ierr)
return
end subroutine dseigv

subroutine dtred1 (nm,n,a,d,e,e2)
implicit none
!
integer :: i, j, k, l
integer, intent(in) :: n
integer :: ii
integer, intent(in) :: nm
integer :: jp1
double precision, intent(inout) :: a(nm,n), d(n), e(n), e2(n)
double precision :: f, g, h, scale
!     double precision dsqrt,dabs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure tred1,
!     NUM. Math. 11, 181-195(1968) By Martin, Reinsch, and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 212-226(1971).
!
!     This subroutine reduces a real symmetric matrix
!     to a symmetric tridiagonal matrix using
!     orthogonal similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        A contains the real symmetric input matrix.  Only the
!          lower triangle of the matrix need be supplied.
!
!     On output-
!
!        A contains information about the orthogonal trans-
!          formations used in the reduction in its strict lower
!          triangle.  The full upper triangle of A is unaltered,
!
!        d contains the diagonal elements of the tridiagonal matrix,
!
!        e contains the subdiagonal elements of the tridiagonal
!          matrix in its last n-1 positions.  e(1) is set to zero,
!
!        e2 contains the squares of the corresponding elements of e.
!          e2 may coincide with e if the squares are not needed.
!
!-----------------------------------------------------------------------
!
do 100 i = 1, n
100 d(i) = a(i,i)
!     ********** FOR i=n STEP -1 UNTIL 1 DO -- **********
do ii = 1, n
   i = n + 1 - ii
   l = i - 1
   h = 0.d0
   scale = 0.d0
   if (l .lt. 1) go to 130
!     ********** scale ROW (ALGOL TOL THEN NOT NEEDED) **********
   do 120 k = 1, l
120 scale = scale + dabs(a(i,k))
!
   if (scale .ne. 0.d0) go to 140
130 e(i) = 0.d0
   e2(i) = 0.d0
   go to 290
!
140 do k = 1, l
      a(i,k) = a(i,k) / scale
      h = h + a(i,k) * a(i,k)
   end do
!
   e2(i) = scale * scale * h
   f = a(i,l)
   g = dsqrt(h)
   if (f .ge. 0.d0) g = -g
   e(i) = scale * g
   h = h - f * g
   a(i,l) = f - g
   if (l .eq. 1) go to 270
   f = 0.d0
!
   do j = 1, l
      g = 0.d0
!     ********** FORM ELEMENT OF a*U **********
      do 180 k = 1, j
180 g = g + a(j,k) * a(i,k)
!
      jp1 = j + 1
      if (l .lt. jp1) go to 220
!
      do 200 k = jp1, l
200 g = g + a(k,j) * a(i,k)
!     ********** FORM ELEMENT OF P **********
220 e(j) = g / h
      f = f + e(j) * a(i,j)
   end do
!
   h = f / (h + h)
!     ********** FORM REDUCED a **********
   do 260 j = 1, l
      f = a(i,j)
      g = e(j) - h * f
      e(j) = g
!
      do 260 k = 1, j
         a(j,k) = a(j,k) - f * e(k) - g * a(i,k)
260 continue
!
270 do 280 k = 1, l
280 a(i,k) = scale * a(i,k)
!
290 h = d(i)
   d(i) = a(i,i)
   a(i,i) = h
end do
!
return
!     ********** LAST CARD OF dtred1 **********
end subroutine dtred1

subroutine dtred3 (n,nv,a,d,e,e2)
implicit none
!
integer :: i, j, k, l
integer, intent(in) :: n
integer :: ii, iz, jk
integer, intent(in) :: nv
double precision, intent(inout) :: a(nv), d(n), e(n), e2(n)
double precision :: f, g, h, hh, scale
!     double precision dsqrt,dabs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure tred3,
!     NUM. Math. 11, 181-195(1968) By Martin, Reinsch, and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 212-226(1971).
!
!     This subroutine reduces a real symmetric matrix, stored as
!     a one-dimensional array, to a symmetric tridiagonal matrix
!     using orthogonal similarity transformations.
!
!     On input-
!
!        n is the order of the matrix,
!
!        nv must be set to the dimension of the array parameter A
!          as declared in the calling program dimension statement,
!
!        A contains the lower triangle of the real symmetric
!          input matrix, stored row-wise as a one-dimensional
!          array, in its first n*(n+1)/2 positions.
!
!     On output-
!
!        A contains information about the orthogonal
!          transformations used in the reduction,
!
!        d contains the diagonal elements of the tridiagonal matrix,
!
!        e contains the subdiagonal elements of the tridiagonal
!          matrix in its last n-1 positions.  e(1) is set to zero,
!
!        e2 contains the squares of the corresponding elements of e.
!          e2 may coincide with e if the squares are not needed.
!
!-----------------------------------------------------------------------
!
!     ********** FOR i=n STEP -1 UNTIL 1 DO -- **********
do ii = 1, n
   i = n + 1 - ii
   l = i - 1
   iz = (i * l) / 2
   h = 0.d0
   scale = 0.d0
   if (l .lt. 1) go to 130
!     ********** scale ROW (ALGOL TOL THEN NOT NEEDED) **********
   do k = 1, l
      iz = iz + 1
      d(k) = a(iz)
      scale = scale + dabs(d(k))
   end do
!
   if (scale .ne. 0.d0) go to 140
130 e(i) = 0.d0
   e2(i) = 0.d0
   go to 290
!
140 do k = 1, l
      d(k) = d(k) / scale
      h = h + d(k) * d(k)
   end do
!
   e2(i) = scale * scale * h
   f = d(l)
   g = dsqrt(h)
   if (f .ge. 0.d0) g = -g
   e(i) = scale * g
   h = h - f * g
   d(l) = f - g
   a(iz) = scale * d(l)
   if (l .eq. 1) go to 290
   f = 0.d0
!
   do j = 1, l
      g = 0.d0
      jk = (j * (j-1)) / 2
!     ********** FORM ELEMENT OF a*U **********
      do k = 1, l
         jk = jk + 1
         if (k .gt. j) jk = jk + k - 2
         g = g + a(jk) * d(k)
      end do
!     ********** FORM ELEMENT OF P **********
      e(j) = g / h
      f = f + e(j) * d(j)
   end do
!
   hh = f / (h + h)
   jk = 0
!     ********** FORM REDUCED a **********
   do 260 j = 1, l
      f = d(j)
      g = e(j) - hh * f
      e(j) = g
!
      do 260 k = 1, j
         jk = jk + 1
         a(jk) = a(jk) - f * e(k) - g * d(k)
260 continue
!
290 d(i) = a(iz+1)
   a(iz+1) = scale * dsqrt(h)
end do
!
return
!     ********** LAST CARD OF dtred3 **********
end subroutine dtred3

subroutine dtql (n,d,e2,ierr)
implicit none
!
integer :: i, j, l, m
integer, intent(in) :: n
integer :: ii, l1, mml
integer, intent(out) :: ierr
double precision, intent(inout) :: d(n), e2(n)
double precision :: b, c, f, g, h, p, r, s, machep
double precision :: dpmpar
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure tqlrat,
!     algorithm 464, comm. ACM 16, 689(1973) by Reinsch.
!
!     This subroutine finds the eigenvalues of a symmetric
!     tridiagonal matrix BY the rational QL method.
!
!     On input-
!
!        n is the order of the matrix,
!
!        d contains the diagonal elements of the input matrix,
!
!        e2 contains the squares of the subdiagonal elements of the
!          input matrix in its last n-1 positions.  e2(1) is arbitrary.
!
!      On output-
!
!        d contains the eigenvalues in ascending order.  If an
!          error exit is made, the eigenvalues are correct and
!          ordered for indices 1,2,...ierr-1, but may not be
!          the smallest eigenvalues,
!
!        e2 has been destroyed,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 50 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                machep the value U where U is the smallest positive
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           machep = dpmpar(1)
!
!                **********
!
ierr = 0
if (n .eq. 1) go to 1001
!
do 100 i = 2, n
100 e2(i-1) = e2(i)
!
f = 0.d0
b = 0.d0
e2(n) = 0.d0
!
do l = 1, n
   j = 0
   h = machep * (dabs(d(l)) + dsqrt(e2(l)))
   if (b .gt. h) go to 105
   b = h
   c = b * b
!     ********** LOOK FOR SMALL SQUARED SUB-DIAGONAL ELEMENT **********
105 do m = l, n
      if (e2(m) .le. c) go to 120
!     ********** e2(n) IS ALWAYS ZERO, SO THERE IS NO EXIT
!                THROUGH THE BOTTOM OF THE LOOP **********
   end do
!
120 if (m .eq. l) go to 210
130 if (j .eq. 50) go to 1000
   j = j + 1
!     ********** FORM SHIFT **********
   l1 = l + 1
   s = dsqrt(e2(l))
   g = d(l)
   p = (d(l1) - g) / (2.d0 * s)
   r = dsqrt(p*p + 1.d0)
   if (p .lt. 0.d0) r = -r
   d(l) = s / (p + r)
   h = g - d(l)
!
   do 140 i = l1, n
140 d(i) = d(i) - h
!
   f = f + h
!     ********** RATIONAL QL TRANSFORMATION **********
   g = d(m)
   if (g .eq. 0.d0) g = b
   h = g
   s = 0.d0
   mml = m - l
!     ********** FOR i=m-1 STEP -1 UNTIL l DO -- **********
   do ii = 1, mml
      i = m - ii
      p = g * h
      r = p + e2(i)
      e2(i+1) = s * r
      s = e2(i) / r
      d(i+1) = h + s * (h + d(i))
      g = d(i) - e2(i) / g
      if (g .eq. 0.d0) g = b
      h = g * p / r
   end do
!
   e2(l) = s * g
   d(l) = h
!     ********** GUARD AGAINST UNDERFLOW IN CONVERGENCE TEST **********
   if (h .eq. 0.d0) go to 210
   if (dabs(e2(l)) .le. dabs(c/h)) go to 210
   e2(l) = h * e2(l)
   if (e2(l) .ne. 0.d0) go to 130
210 p = d(l) + f
!     ********** ORDER EIGENVALUES **********
   if (l .eq. 1) go to 250
!     ********** FOR i=l STEP -1 UNTIL 2 DO -- **********
   do ii = 2, l
      i = l + 2 - ii
      if (p .ge. d(i-1)) go to 270
      d(i) = d(i-1)
   end do
!
250 i = 1
270 d(i) = p
end do
!
go to 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 ierr = l
1001 return
!     ********** LAST CARD OF dtql **********
end subroutine dtql

subroutine dtred2 (nm,n,a,d,e,z)
implicit none
!
integer :: i, j, k, l
integer, intent(in) :: n
integer :: ii
integer, intent(in) :: nm
integer :: jp1
double precision, intent(in) :: a(nm,n)
double precision, intent(inout) :: d(n), e(n), z(nm,n)
double precision :: f, g, h, hh, scale
!     double precision dsqrt,dabs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure tred2,
!     NUM. Math. 11, 181-195(1968) By Martin, Reinsch, and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 212-226(1971).
!
!     This subroutine reduces a real symmetric matrix to A
!     symmetric tridiagonal matrix using and accumulating
!     orthogonal similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        A contains the real symmetric input matrix.  Only the
!          lower triangle of the matrix need be supplied.
!
!     On output-
!
!        d contains the diagonal elements of the tridiagonal matrix,
!
!        e contains the subdiagonal elements of the tridiagonal
!          matrix in its last n-1 positions.  e(1) is set to zero,
!
!        z contains the orthogonal transformation matrix
!          produced in the reduction,
!
!        A and z may coincide.  If distinct, A is unaltered.
!
!-----------------------------------------------------------------------
!
do 100 i = 1, n
!
   do 100 j = 1, i
      z(i,j) = a(i,j)
100 continue
!
if (n .eq. 1) go to 320
!     ********** FOR i=n STEP -1 UNTIL 2 DO -- **********
do ii = 2, n
   i = n + 2 - ii
   l = i - 1
   h = 0.d0
   scale = 0.d0
   if (l .lt. 2) go to 130
!     ********** scale ROW (ALGOL TOL THEN NOT NEEDED) **********
   do 120 k = 1, l
120 scale = scale + dabs(z(i,k))
!
   if (scale .ne. 0.d0) go to 140
130 e(i) = z(i,l)
   go to 290
!
140 do k = 1, l
      z(i,k) = z(i,k) / scale
      h = h + z(i,k) * z(i,k)
   end do
!
   f = z(i,l)
   g = dsqrt(h)
   if (f .ge. 0.d0) g = -g
   e(i) = scale * g
   h = h - f * g
   z(i,l) = f - g
   f = 0.d0
!
   do j = 1, l
      z(j,i) = z(i,j) / h
      g = 0.d0
!     ********** FORM ELEMENT OF a*U **********
      do 180 k = 1, j
180 g = g + z(j,k) * z(i,k)
!
      jp1 = j + 1
      if (l .lt. jp1) go to 220
!
      do 200 k = jp1, l
200 g = g + z(k,j) * z(i,k)
!     ********** FORM ELEMENT OF P **********
220 e(j) = g / h
      f = f + e(j) * z(i,j)
   end do
!
   hh = f / (h + h)
!     ********** FORM REDUCED a **********
   do 260 j = 1, l
      f = z(i,j)
      g = e(j) - hh * f
      e(j) = g
!
      do 260 k = 1, j
         z(j,k) = z(j,k) - f * e(k) - g * z(i,k)
260 continue
!
290 d(i) = h
end do
!
320 d(1) = 0.d0
e(1) = 0.d0
!     ********** ACCUMULATION OF TRANSFORMATION MATRICES **********
do 500 i = 1, n
   l = i - 1
   if (d(i) .eq. 0.d0) go to 380
!
   do 360 j = 1, l
      g = 0.d0
!
      do 340 k = 1, l
340 g = g + z(i,k) * z(k,j)
!
      do 360 k = 1, l
         z(k,j) = z(k,j) - g * z(k,i)
360 continue
!
380 d(i) = z(i,i)
   z(i,i) = 1.d0
   if (l .lt. 1) go to 500
!
   do j = 1, l
      z(i,j) = 0.d0
      z(j,i) = 0.d0
   end do
!
500 continue
!
return
!     ********** LAST CARD OF dtred2 **********
end subroutine dtred2

subroutine dtql2 (nm,n,d,e,z,ierr)
implicit none
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: ii, l1
integer, intent(in) :: nm
integer :: mml
integer, intent(out) :: ierr
double precision, intent(inout) :: d(n), e(n), z(nm,n)
double precision :: b, c, f, g, h, p, r, s, machep
double precision :: dpmpar
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure tql2,
!     NUM. Math. 11, 293-306(1968) By Bowdler, Martin, Reinsch, and
!     Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 227-240(1971).
!
!     This subroutine finds the eigenvalues and eigenvectors
!     of a symmetric tridiagonal matrix BY the QL method.
!     The eigenvectors of a full symmetric matrix can also
!     be found if  tred2  has been used to reduce this
!     full matrix to tridiagonal form.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        d contains the diagonal elements of the input matrix,
!
!        e contains the subdiagonal elements of the input matrix
!          in its last n-1 positions.  e(1) is arbitrary,
!
!        z contains the transformation matrix produced in the
!          reduction by  tred2, if performed.  If the eigenvectors
!          of the tridiagonal matrix are desired, z must contain
!          the identity matrix.
!
!      On output-
!
!        d contains the eigenvalues in ascending order.  If an
!          error exit is made, the eigenvalues are correct but
!          unordered for indices 1,2,...,ierr-1,
!
!        e has been destroyed,
!
!        z contains orthonormal eigenvectors of the symmetric
!          tridiagonal (or full) matrix.  If an error exit is made,
!          z contains the eigenvectors associated with the stored
!          eigenvalues,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 50 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                machep the value U where U is the smallest positive
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           machep = dpmpar(1)
!
!                **********
!
ierr = 0
if (n .eq. 1) go to 1001
!
do 100 i = 2, n
100 e(i-1) = e(i)
!
f = 0.d0
b = 0.d0
e(n) = 0.d0
!
do l = 1, n
   j = 0
   h = machep * (dabs(d(l)) + dabs(e(l)))
   if (b .lt. h) b = h
!     ********** LOOK FOR SMALL SUB-DIAGONAL ELEMENT **********
   do m = l, n
      if (dabs(e(m)) .le. b) go to 120
!     ********** e(n) IS ALWAYS ZERO, SO THERE IS NO EXIT
!                THROUGH THE BOTTOM OF THE LOOP **********
   end do
!
120 if (m .eq. l) go to 220
130 if (j .eq. 50) go to 1000
   j = j + 1
!     ********** FORM SHIFT **********
   l1 = l + 1
   g = d(l)
   p = (d(l1) - g) / (2.d0 * e(l))
   r = dsqrt(p*p + 1.d0)
   if (p .lt. 0.d0) r = -r
   d(l) = e(l) / (p + r)
   h = g - d(l)
!
   do 140 i = l1, n
140 d(i) = d(i) - h
!
   f = f + h
!     ********** QL TRANSFORMATION **********
   p = d(m)
   c = 1.d0
   s = 0.d0
   mml = m - l
!     ********** FOR i=m-1 STEP -1 UNTIL l DO -- **********
   do ii = 1, mml
      i = m - ii
      g = c * e(i)
      h = c * p
      if (dabs(p) .lt. dabs(e(i))) go to 150
      c = e(i) / p
      r = dsqrt(c*c + 1.d0)
      e(i+1) = s * p * r
      s = c / r
      c = 1.d0 / r
      go to 160
150 c = p / e(i)
      r = dsqrt(c*c + 1.d0)
      e(i+1) = s * e(i) * r
      s = 1.d0 / r
      c = c * s
160 p = c * d(i) - s * g
      d(i+1) = h + s * (c * g + s * d(i))
!     ********** FORM VECTOR **********
      do k = 1, n
         h = z(k,i+1)
         z(k,i+1) = s * z(k,i) + c * h
         z(k,i) = c * z(k,i) - s * h
      end do
!
   end do
!
   e(l) = s * p
   d(l) = c * p
   if (dabs(e(l)) .gt. b) go to 130
220 d(l) = d(l) + f
end do
!     ********** ORDER EIGENVALUES AND EIGENVECTORS **********
do 300 ii = 2, n
   i = ii - 1
   k = i
   p = d(i)
!
   do 260 j = ii, n
      if (d(j) .ge. p) go to 260
      k = j
      p = d(j)
260 continue
!
   if (k .eq. i) go to 300
   d(k) = d(i)
   d(i) = p
!
   do j = 1, n
      p = z(j,i)
      z(j,i) = z(j,k)
      z(j,k) = p
   end do
!
300 continue
!
go to 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 ierr = l
1001 return
!     ********** LAST CARD OF dtql2 **********
end subroutine dtql2

subroutine ceig(ibal,ar,ai,ka,n,wr,wi,ierr)
implicit none
integer, intent(in) :: ibal
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
integer :: igh, low
!-----------------------------------------------------------------------
!                Eigenvalues of complex matrices
!-----------------------------------------------------------------------
real, intent(inout) :: ar(ka,n), ai(ka,n), wr(n), wi(n)
!
low = 1
igh = n
if (ibal .ne. 0) call cbal(ka,n,ar,ai,low,igh,wr)
call corth(ka,n,low,igh,ar,ai,wr,wi)
call comqr(ka,n,low,igh,ar,ai,wr,wi,ierr)
return
end subroutine ceig

subroutine ceigv(ibal,ar,ai,ka,n,wr,wi,zr,zi,ierr,temp)
implicit none
integer, intent(in) :: ibal
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
integer :: i1, i2, i3, igh, low
!-----------------------------------------------------------------------
!          Eigenvalues and eigenvectors of complex matrices
!-----------------------------------------------------------------------
real, intent(inout) :: ar(ka,n), ai(ka,n), wr(n), wi(n), zr(ka,n), &
&zi(ka,n), temp(*)
!----------------------
!     Temp is a temporary storage area
!        DIMENSION(TEMP) .GE. 2*n    IF ibal .EQ. 0
!        DIMENSION(TEMP) .GE. 3*n    IF ibal .NE. 0
!----------------------
i2 = 1
i3 = n + 1
i1 = n + i3
low = 1
igh = n
if (ibal .ne. 0) call cbal(ka,n,ar,ai,low,igh,temp(i1))
call corth(ka,n,low,igh,ar,ai,temp(i2),temp(i3))
call comqr2(ka,n,low,igh,temp(i2),temp(i3),ar,ai,wr,wi,zr,zi,ierr)
if (ierr .ne. 0) return
if (ibal .ne. 0) call cbabk2(ka,n,low,igh,temp(i1),n,zr,zi)
return
end subroutine ceigv

subroutine cbal(nm,n,ar,ai,low,igh,scale)
implicit none
integer :: ipmpar
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: jj
integer, intent(in) :: nm
integer, intent(inout) :: igh, low
integer :: iexc
real, intent(inout) :: ar(nm,n), ai(nm,n), scale(n)
real :: c, f, g, r, s, b2, radix
!     real abs
logical :: noconv
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure
!     CBALANCE, which is a complex version of balance,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.II-linear algebra, 315-326(1971).
!
!     This subroutine balances a complex matrix and isolates
!     eigenvalues whenever possible.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        ar and ai contain the real and imaginary parts,
!          respectively, of the complex matrix to be balanced.
!
!     On output-
!
!        ar and ai contain the real and imaginary parts,
!          respectively, of the balanced matrix,
!
!        Low and igh are two integers such that ar(i,j) and ai(i,j)
!          are equal to zero if
!           (1) i is greater than j and
!           (2) j=1,...,low-1 OR i=igh+1,...,n,
!
!        Scale contains information determining the
!           permutations and scaling factors used.
!
!     Suppose that the principal submatrix in rows low through igh
!     has been balanced, that P(j) denotes the index interchanged
!     with j during the permutation step, and that the elements
!     of the diagonal matrix used are denoted by D(i,j).  Then
!        scale(j) = P(j),    FOR j = 1,...,low-1
!                 = D(j,j)       j = low,...,igh
!                 = P(j)         j = igh+1,...,n.
!     The order in which the interchanges are made is n to igh+1,
!     then 1 to low-1.
!
!     Note that 1 is returned for igh if igh is zero formally.
!
!     The Algol procedure exc contained in CBALANCE appears in
!     cbal  in line.  (Note that the Algol roles of identifiers
!     k,l have been reversed.)
!
!-----------------------------------------------------------------------
!
!     ********** radix IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                the base of the machine floating point representation.
!
           radix = ipmpar(4)
!
!                **********
!
b2 = radix * radix
k = 1
l = n
go to 100
!     ********** IN-LINE PROCEDURE FOR ROW AND
!                COLUMN EXCHANGE **********
20 scale(m) = j
if (j .eq. m) go to 50
!
do i = 1, l
   f = ar(i,j)
   ar(i,j) = ar(i,m)
   ar(i,m) = f
   f = ai(i,j)
   ai(i,j) = ai(i,m)
   ai(i,m) = f
end do
!
do i = k, n
   f = ar(j,i)
   ar(j,i) = ar(m,i)
   ar(m,i) = f
   f = ai(j,i)
   ai(j,i) = ai(m,i)
   ai(m,i) = f
end do
!
50 go to (80,130), iexc
!     ********** SEARCH FOR ROWS ISOLATING AN EIGENVALUE
!                AND PUSH THEM DOWN **********
80 if (l .eq. 1) go to 280
l = l - 1
!     ********** FOR j=l STEP -1 UNTIL 1 DO -- **********
100 do 120 jj = 1, l
   j = l + 1 - jj
!
   do 110 i = 1, l
      if (i .eq. j) go to 110
      if (ar(j,i) .ne. 0.0 .or. ai(j,i) .ne. 0.0) go to 120
110 continue
!
   m = l
   iexc = 1
   go to 20
120 continue
!
go to 140
!     ********** SEARCH FOR COLUMNS ISOLATING AN EIGENVALUE
!                AND PUSH THEM LEFT **********
130 k = k + 1
!
140 do 170 j = k, l
!
   do 150 i = k, l
      if (i .eq. j) go to 150
      if (ar(i,j) .ne. 0.0 .or. ai(i,j) .ne. 0.0) go to 170
150 continue
!
   m = k
   iexc = 2
   go to 20
170 continue
!     ********** NOW BALANCE THE SUBMATRIX IN ROWS k TO l **********
do 180 i = k, l
180 scale(i) = 1.0
!     ********** ITERATIVE LOOP FOR NORM REDUCTION **********
190 noconv = .false.
!
do 270 i = k, l
   c = 0.0
   r = 0.0
!
   do 200 j = k, l
      if (j .eq. i) go to 200
      c = c + abs(ar(j,i)) + abs(ai(j,i))
      r = r + abs(ar(i,j)) + abs(ai(i,j))
200 continue
!     ********** GUARD AGAINST ZERO c OR r DUE TO UNDERFLOW **********
   if (c .eq. 0.0 .or. r .eq. 0.0) go to 270
   g = r / radix
   f = 1.0
   s = c + r
210 if (c .ge. g) go to 220
   f = f * radix
   c = c * b2
   go to 210
220 g = r * radix
230 if (c .lt. g) go to 240
   f = f / radix
   c = c / b2
   go to 230
!     ********** NOW BALANCE **********
240 if ((c + r) / f .ge. 0.95 * s) go to 270
   g = 1.0 / f
   scale(i) = scale(i) * f
   noconv = .true.
!
   do j = k, n
      ar(i,j) = ar(i,j) * g
      ai(i,j) = ai(i,j) * g
   end do
!
   do j = 1, l
      ar(j,i) = ar(j,i) * f
      ai(j,i) = ai(j,i) * f
   end do
!
270 continue
!
if (noconv) go to 190
!
280 low = k
igh = l
return
!     ********** LAST CARD OF cbal **********
end subroutine cbal

subroutine corth(nm,n,low,igh,ar,ai,ortr,orti)
implicit none
!
integer :: i, j, m
integer, intent(in) :: n
integer :: ii, jj, la, mp
integer, intent(in) :: nm, igh
integer :: kp1
integer, intent(in) :: low
real, intent(inout) :: ar(nm,n), ai(nm,n), ortr(igh), orti(igh)
real :: f, g, h, fi, fr, scale
!     real sqrt,cabs,abs
!     complex cmplx
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of a complex analogue of
!     the Algol procedure orthes, NUM. Math. 12, 349-368(1968)
!     by Martin and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 339-358(1971).
!
!     Given a complex general matrix, this subroutine
!     reduces a submatrix situated in rows and columns
!     low through igh to upper Hessenberg form by
!     unitary similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  cbal.  If  cbal  has not been used,
!          SET low=1, igh=n,
!
!        ar and ai contain the real and imaginary parts,
!          respectively, of the complex input matrix.
!
!     On output-
!
!        ar and ai contain the real and imaginary parts,
!          respectively, of the Hessenberg matrix.  Information
!          about the unitary transformations used in the reduction
!          is stored in the remaining triangles under the
!          Hessenberg matrix,
!
!        ortr and orti contain further information about the
!          transformations.  Only elements low through igh are used.
!
!-----------------------------------------------------------------------
la = igh - 1
kp1 = low + 1
if (la .lt. kp1) go to 200
!
do 180 m = kp1, la
   h = 0.0
   ortr(m) = 0.0
   orti(m) = 0.0
   scale = 0.0
!     ********** scale COLUMN (ALGOL TOL THEN NOT NEEDED) **********
   do 90 i = m, igh
90 scale = scale + abs(ar(i,m-1)) + abs(ai(i,m-1))
!
   if (scale .eq. 0.0) go to 180
   mp = m + igh
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
   do ii = m, igh
      i = mp - ii
      ortr(i) = ar(i,m-1) / scale
      orti(i) = ai(i,m-1) / scale
      h = h + ortr(i) * ortr(i) + orti(i) * orti(i)
   end do
!
   g = sqrt(h)
   f = cabs(cmplx(ortr(m),orti(m)))
   if (f .eq. 0.0) go to 103
   h = h + f * g
   g = g / f
   ortr(m) = (1.0 + g) * ortr(m)
   orti(m) = (1.0 + g) * orti(m)
   go to 105
!
103 ortr(m) = g
   ar(m,m-1) = scale
!     ********** FORM (i-(U*UT)/h) * A **********
105 do j = m, n
      fr = 0.0
      fi = 0.0
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
      do ii = m, igh
         i = mp - ii
         fr = fr + ortr(i) * ar(i,j) + orti(i) * ai(i,j)
         fi = fi + ortr(i) * ai(i,j) - orti(i) * ar(i,j)
      end do
!
      fr = fr / h
      fi = fi / h
!
      do i = m, igh
         ar(i,j) = ar(i,j) - fr * ortr(i) + fi * orti(i)
         ai(i,j) = ai(i,j) - fr * orti(i) - fi * ortr(i)
      end do
!
   end do
!     ********** FORM (i-(U*UT)/h)*A*(i-(U*UT)/h) **********
   do i = 1, igh
      fr = 0.0
      fi = 0.0
!     ********** FOR j=igh STEP -1 UNTIL m DO -- **********
      do jj = m, igh
         j = mp - jj
         fr = fr + ortr(j) * ar(i,j) - orti(j) * ai(i,j)
         fi = fi + ortr(j) * ai(i,j) + orti(j) * ar(i,j)
      end do
!
      fr = fr / h
      fi = fi / h
!
      do j = m, igh
         ar(i,j) = ar(i,j) - fr * ortr(j) - fi * orti(j)
         ai(i,j) = ai(i,j) + fr * orti(j) - fi * ortr(j)
      end do
!
   end do
!
   ortr(m) = scale * ortr(m)
   orti(m) = scale * orti(m)
   ar(m,m-1) = -g * ar(m,m-1)
   ai(m,m-1) = -g * ai(m,m-1)
180 continue
!
200 return
!     ********** LAST CARD OF corth **********
end subroutine corth

subroutine comqr(nm,n,low,igh,hr,hi,wr,wi,ierr)
implicit none
!
integer :: i, j, l
integer, intent(in) :: n
integer :: en, ll
integer, intent(in) :: nm, igh
integer :: its
integer, intent(in) :: low
integer :: lp1, enm1
integer, intent(out) :: ierr
real, intent(inout) :: hr(nm,n), hi(nm,n), wr(n), wi(n)
real :: si, sr, ti, tr, xi, xr, yi, yr, zzi, zzr, norm, machep
complex :: z3
real :: spmpar
!     integer min0
!     real sqrt,cabs,abs,real,aimag
!     complex csqrt,cmplx
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of a unitary analogue of the
!     Algol procedure  COMLR, NUM. Math. 12, 369-376(1968) By Martin
!     and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 396-403(1971).
!     The unitary analogue substitutes the QR algorithm of Francis
!     (comp. Jour. 4, 332-345(1962)) For the LR algorithm.
!
!     This subroutine finds the eigenvalues of a complex
!     upper Hessenberg matrix BY the QR method.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  cbal.  If  cbal  has not been used,
!          SET low=1, igh=n,
!
!        hr and hi contain the real and imaginary parts,
!          respectively, of the complex upper Hessenberg matrix.
!          Their lower triangles below the subdiagonal contain
!          information about the unitary transformations used in
!          the reduction by  corth, if performed.
!
!     On output-
!
!        The upper Hessenberg portions of hr and hi have been
!          destroyed.  Therefore, they must be saved before
!          calling  comqr  if subsequent calculation of
!          eigenvectors is to be performed,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  If an error
!          exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 30 iterations.
!
!     Arithmetic is real except for the replacement of the Algol
!     procedure cdiv by complex division and use of the subroutines
!     CSQRT and cmplx in computing complex square roots.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                the relative precision of floating point arithmetic.
!
           machep = spmpar(1)
!
!                **********
!
ierr = 0
if (low .eq. igh) go to 180
!     ********** CREATE REAL SUBDIAGONAL ELEMENTS **********
l = low + 1
!
do 170 i = l, igh
   ll = min0(i+1,igh)
   if (hi(i,i-1) .eq. 0.0) go to 170
   norm = cabs(cmplx(hr(i,i-1),hi(i,i-1)))
   yr = hr(i,i-1) / norm
   yi = hi(i,i-1) / norm
   hr(i,i-1) = norm
   hi(i,i-1) = 0.0
!
   do j = i, igh
      si = yr * hi(i,j) - yi * hr(i,j)
      hr(i,j) = yr * hr(i,j) + yi * hi(i,j)
      hi(i,j) = si
   end do
!
   do j = low, ll
      si = yr * hi(j,i) + yi * hr(j,i)
      hr(j,i) = yr * hr(j,i) - yi * hi(j,i)
      hi(j,i) = si
   end do
!
170 continue
!     ********** STORE ROOTS ISOLATED BY cbal **********
180 do 200 i = 1, n
   if (i .ge. low .and. i .le. igh) go to 200
   wr(i) = hr(i,i)
   wi(i) = hi(i,i)
200 continue
!
en = igh
tr = 0.0
ti = 0.0
!     ********** SEARCH FOR NEXT EIGENVALUE **********
220 if (en .lt. low) go to 1001
its = 0
enm1 = en - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR l=en STEP -1 UNTIL low  -- **********
240 do ll = low, en
   l = en + low - ll
   if (l .eq. low) go to 300
   if (abs(hr(l,l-1)) .le. &
&machep * (abs(hr(l-1,l-1)) + abs(hi(l-1,l-1)) &
&+ abs(hr(l,l)) +abs(hi(l,l)))) go to 300
end do
!     ********** FORM SHIFT **********
300 if (l .eq. en) go to 660
if (its .eq. 30) go to 1000
if (its .eq. 10 .or. its .eq. 20) go to 320
sr = hr(en,en)
si = hi(en,en)
xr = hr(enm1,en) * hr(en,enm1)
xi = hi(enm1,en) * hr(en,enm1)
if (xr .eq. 0.0 .and. xi .eq. 0.0) go to 340
yr = (hr(enm1,enm1) - sr) / 2.0
yi = (hi(enm1,enm1) - si) / 2.0
z3 = csqrt(cmplx(yr**2-yi**2+xr,2.0*yr*yi+xi))
zzr = real(z3)
zzi = aimag(z3)
if (yr * zzr + yi * zzi .ge. 0.0) go to 310
zzr = -zzr
zzi = -zzi
310 z3 = cmplx(xr,xi) / cmplx(yr+zzr,yi+zzi)
sr = sr - real(z3)
si = si - aimag(z3)
go to 340
!     ********** FORM EXCEPTIONAL SHIFT **********
320 sr = abs(hr(en,enm1)) + abs(hr(enm1,en-2))
si = 0.0
!
340 do i = low, en
   hr(i,i) = hr(i,i) - sr
   hi(i,i) = hi(i,i) - si
end do
!
tr = tr + sr
ti = ti + si
its = its + 1
!     ********** REDUCE TO TRIANGLE (ROWS) **********
lp1 = l + 1
!
do i = lp1, en
   sr = hr(i,i-1)
   hr(i,i-1) = 0.0
   norm = sqrt(hr(i-1,i-1)*hr(i-1,i-1)+hi(i-1,i-1)*hi(i-1,i-1) &
&+sr*sr)
   xr = hr(i-1,i-1) / norm
   wr(i-1) = xr
   xi = hi(i-1,i-1) / norm
   wi(i-1) = xi
   hr(i-1,i-1) = norm
   hi(i-1,i-1) = 0.0
   hi(i,i-1) = sr / norm
!
   do j = i, en
      yr = hr(i-1,j)
      yi = hi(i-1,j)
      zzr = hr(i,j)
      zzi = hi(i,j)
      hr(i-1,j) = xr * yr + xi * yi + hi(i,i-1) * zzr
      hi(i-1,j) = xr * yi - xi * yr + hi(i,i-1) * zzi
      hr(i,j) = xr * zzr - xi * zzi - hi(i,i-1) * yr
      hi(i,j) = xr * zzi + xi * zzr - hi(i,i-1) * yi
   end do
!
end do
!
si = hi(en,en)
if (si .eq. 0.0) go to 540
norm = cabs(cmplx(hr(en,en),si))
sr = hr(en,en) / norm
si = si / norm
hr(en,en) = norm
hi(en,en) = 0.0
!     ********** INVERSE OPERATION (COLUMNS) **********
540 do j = lp1, en
   xr = wr(j-1)
   xi = wi(j-1)
!
   do i = l, j
      yr = hr(i,j-1)
      yi = 0.0
      zzr = hr(i,j)
      zzi = hi(i,j)
      if (i .eq. j) go to 560
      yi = hi(i,j-1)
      hi(i,j-1) = xr * yi + xi * yr + hi(j,j-1) * zzi
560 hr(i,j-1) = xr * yr - xi * yi + hi(j,j-1) * zzr
      hr(i,j) = xr * zzr + xi * zzi - hi(j,j-1) * yr
      hi(i,j) = xr * zzi - xi * zzr - hi(j,j-1) * yi
   end do
!
end do
!
if (si .eq. 0.0) go to 240
!
do i = l, en
   yr = hr(i,en)
   yi = hi(i,en)
   hr(i,en) = sr * yr - si * yi
   hi(i,en) = sr * yi + si * yr
end do
!
go to 240
!     ********** A ROOT FOUND **********
660 wr(en) = hr(en,en) + tr
wi(en) = hi(en,en) + ti
en = enm1
go to 220
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 ierr = en
1001 return
!     ********** LAST CARD OF comqr **********
end subroutine comqr

subroutine cbabk2(nm,n,low,igh,scale,m,zr,zi)
implicit none
!
integer :: i, j, k
integer, intent(in) :: m, n
integer :: ii
integer, intent(in) :: nm, igh, low
real, intent(in) :: scale(n)
real, intent(inout) :: zr(nm,m), zi(nm,m)
real :: s
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure
!     cbabk2, which is a complex version of balbak,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 315-326(1971).
!
!     This subroutine forms the eigenvectors of a complex general
!     matrix BY back transforming those of the corresponding
!     balanced matrix determined by  cbal.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by  cbal,
!
!        Scale contains information determining the permutations
!          and scaling factors used by  cbal,
!
!        m is the number of eigenvectors to be back transformed,
!
!        zr and zi contain the real and imaginary parts,
!          respectively, of the eigenvectors to be
!          back transformed in their first m columns.
!
!     On output-
!
!        zr and zi contain the real and imaginary parts,
!          respectively, of the transformed eigenvectors
!          in their first m columns.
!
!-----------------------------------------------------------------------
if (m .eq. 0) go to 200
if (igh .eq. low) go to 120
!
do i = low, igh
   s = scale(i)
!     ********** LEFT HAND EIGENVECTORS ARE BACK TRANSFORMED
!                if the foregoing statement is replaced by
!                s=1.0/scale(i). **********
   do j = 1, m
      zr(i,j) = zr(i,j) * s
      zi(i,j) = zi(i,j) * s
   end do
!
end do
!     ********** FOR i=low-1 STEP -1 UNTIL 1,
!                igh+1 STEP 1 UNTIL n DO -- **********
120 do 140 ii = 1, n
   i = ii
   if (i .ge. low .and. i .le. igh) go to 140
   if (i .lt. low) i = low - ii
   k = scale(i)
   if (k .eq. i) go to 140
!
   do j = 1, m
      s = zr(i,j)
      zr(i,j) = zr(k,j)
      zr(k,j) = s
      s = zi(i,j)
      zi(i,j) = zi(k,j)
      zi(k,j) = s
   end do
!
140 continue
!
200 return
!     ********** LAST CARD OF cbabk2 **********
end subroutine cbabk2

subroutine comqr2(nm,n,low,igh,ortr,orti,hr,hi,wr,wi,zr,zi,ierr)
implicit none
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: en, ii, jj, ll
integer, intent(in) :: nm
integer :: nn
integer, intent(in) :: igh
integer :: ip1, its
integer, intent(in) :: low
integer :: lp1, enm1, iend
integer, intent(out) :: ierr
real, intent(inout) :: hr(nm,n), hi(nm,n), wr(n), wi(n), zr(nm,n), &
&zi(nm,n), ortr(igh), orti(igh)
real :: si, sr, ti, tr, xi, xr, yi, yr, zzi, zzr, norm, machep
complex :: z3
real :: spmpar
!     integer min0
!     real sqrt,cabs,abs,real,aimag
!     complex csqrt,cmplx
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of a unitary analogue of the
!     Algol procedure  COMLR2, NUM. Math. 16, 181-204(1970) By peters
!     and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 372-395(1971).
!     The unitary analogue substitutes the QR algorithm of Francis
!     (comp. Jour. 4, 332-345(1962)) For the LR algorithm.
!
!     This subroutine finds the eigenvalues and eigenvectors
!     of a complex upper Hessenberg matrix BY the QR
!     method.  The eigenvectors of a complex general matrix
!     can also be found if  corth  has been used to reduce
!     this general matrix to Hessenberg form.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  cbal.  If  cbal  has not been used,
!          SET low=1, igh=n,
!
!        ORTR and ORTI contain information about the unitary trans-
!          formations used in the reduction by  corth, if performed.
!          Only elements low through igh are used.  If the eigenvectors
!          of the Hessenberg matrix are desired, set ORTR(j) and
!          ORTI(j) to 0.0 for these elements,
!
!        hr and hi contain the real and imaginary parts,
!          respectively, of the complex upper Hessenberg matrix.
!          Their lower triangles below the subdiagonal contain further
!          information about the transformations which were used in the
!          reduction by  corth, if performed.  If the eigenvectors of
!          the Hessenberg matrix are desired, these elements may be
!          arbitrary.
!
!     On output-
!
!        ORTR, ORTI, and the upper Hessenberg portions of hr and hi
!          have been destroyed,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  If an error
!          exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        zr and ZI contain the real and imaginary parts,
!          respectively, of the eigenvectors.  The eigenvectors
!          are unnormalized.  If an error exit is made, none of
!          the eigenvectors has been found,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 30 iterations.
!
!     Arithmetic is real except for the replacement of the Algol
!     procedure cdiv by complex division and use of the subroutines
!     CSQRT and cmplx in computing complex square roots.
!
!-----------------------------------------------------------------------
!
!     ********** machep IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                the relative precision of floating point arithmetic.
!
           machep = spmpar(1)
!
!                **********
!
ierr = 0
!     ********** INITIALIZE EIGENVECTOR MATRIX **********
do 100 i = 1, n
!
   do 100 j = 1, n
      zr(i,j) = 0.0
      zi(i,j) = 0.0
      if (i .eq. j) zr(i,j) = 1.0
100 continue
!     ********** FORM THE MATRIX OF ACCUMULATED TRANSFORMATIONS
!                FROM THE INFORMATION LEFT BY corth **********
iend = igh - low - 1
if (iend) 180, 150, 105
!     ********** FOR i=igh-1 STEP -1 UNTIL low+1 DO -- **********
105 do 140 ii = 1, iend
   i = igh - ii
   if (ortr(i) .eq. 0.0 .and. orti(i) .eq. 0.0) go to 140
   if (hr(i,i-1) .eq. 0.0 .and. hi(i,i-1) .eq. 0.0) go to 140
!     ********** norm BELOW IS NEGATIVE OF H FORMED IN corth **********
   norm = hr(i,i-1) * ortr(i) + hi(i,i-1) * orti(i)
   ip1 = i + 1
!
   do k = ip1, igh
      ortr(k) = hr(k,i-1)
      orti(k) = hi(k,i-1)
   end do
!
   do j = i, igh
      sr = 0.0
      si = 0.0
!
      do k = i, igh
         sr = sr + ortr(k) * zr(k,j) + orti(k) * zi(k,j)
         si = si + ortr(k) * zi(k,j) - orti(k) * zr(k,j)
      end do
!
      sr = sr / norm
      si = si / norm
!
      do k = i, igh
         zr(k,j) = zr(k,j) + sr * ortr(k) - si * orti(k)
         zi(k,j) = zi(k,j) + sr * orti(k) + si * ortr(k)
      end do
!
   end do
!
140 continue
!     ********** CREATE REAL SUBDIAGONAL ELEMENTS **********
150 l = low + 1
!
do 170 i = l, igh
   ll = min0(i+1,igh)
   if (hi(i,i-1) .eq. 0.0) go to 170
   norm = cabs(cmplx(hr(i,i-1),hi(i,i-1)))
   yr = hr(i,i-1) / norm
   yi = hi(i,i-1) / norm
   hr(i,i-1) = norm
   hi(i,i-1) = 0.0
!
   do j = i, n
      si = yr * hi(i,j) - yi * hr(i,j)
      hr(i,j) = yr * hr(i,j) + yi * hi(i,j)
      hi(i,j) = si
   end do
!
   do j = 1, ll
      si = yr * hi(j,i) + yi * hr(j,i)
      hr(j,i) = yr * hr(j,i) - yi * hi(j,i)
      hi(j,i) = si
   end do
!
   do j = low, igh
      si = yr * zi(j,i) + yi * zr(j,i)
      zr(j,i) = yr * zr(j,i) - yi * zi(j,i)
      zi(j,i) = si
   end do
!
170 continue
!     ********** STORE ROOTS ISOLATED BY cbal **********
180 do 200 i = 1, n
   if (i .ge. low .and. i .le. igh) go to 200
   wr(i) = hr(i,i)
   wi(i) = hi(i,i)
200 continue
!
en = igh
tr = 0.0
ti = 0.0
!     ********** SEARCH FOR NEXT EIGENVALUE **********
220 if (en .lt. low) go to 680
its = 0
enm1 = en - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR l=en STEP -1 UNTIL LOW DO -- **********
240 do ll = low, en
   l = en + low - ll
   if (l .eq. low) go to 300
   if (abs(hr(l,l-1)) .le. &
&machep * (abs(hr(l-1,l-1)) + abs(hi(l-1,l-1)) &
&+ abs(hr(l,l)) +abs(hi(l,l)))) go to 300
end do
!     ********** FORM SHIFT **********
300 if (l .eq. en) go to 660
if (its .eq. 30) go to 1000
if (its .eq. 10 .or. its .eq. 20) go to 320
sr = hr(en,en)
si = hi(en,en)
xr = hr(enm1,en) * hr(en,enm1)
xi = hi(enm1,en) * hr(en,enm1)
if (xr .eq. 0.0 .and. xi .eq. 0.0) go to 340
yr = (hr(enm1,enm1) - sr) / 2.0
yi = (hi(enm1,enm1) - si) / 2.0
z3 = csqrt(cmplx(yr**2-yi**2+xr,2.0*yr*yi+xi))
zzr = real(z3)
zzi = aimag(z3)
if (yr * zzr + yi * zzi .ge. 0.0) go to 310
zzr = -zzr
zzi = -zzi
310 z3 = cmplx(xr,xi) / cmplx(yr+zzr,yi+zzi)
sr = sr - real(z3)
si = si - aimag(z3)
go to 340
!     ********** FORM EXCEPTIONAL SHIFT **********
320 sr = abs(hr(en,enm1)) + abs(hr(enm1,en-2))
si = 0.0
!
340 do i = low, en
   hr(i,i) = hr(i,i) - sr
   hi(i,i) = hi(i,i) - si
end do
!
tr = tr + sr
ti = ti + si
its = its + 1
!     ********** REDUCE TO TRIANGLE (ROWS) **********
lp1 = l + 1
!
do i = lp1, en
   sr = hr(i,i-1)
   hr(i,i-1) = 0.0
   norm = sqrt(hr(i-1,i-1)*hr(i-1,i-1)+hi(i-1,i-1)*hi(i-1,i-1) &
&+sr*sr)
   xr = hr(i-1,i-1) / norm
   wr(i-1) = xr
   xi = hi(i-1,i-1) / norm
   wi(i-1) = xi
   hr(i-1,i-1) = norm
   hi(i-1,i-1) = 0.0
   hi(i,i-1) = sr / norm
!
   do j = i, n
      yr = hr(i-1,j)
      yi = hi(i-1,j)
      zzr = hr(i,j)
      zzi = hi(i,j)
      hr(i-1,j) = xr * yr + xi * yi + hi(i,i-1) * zzr
      hi(i-1,j) = xr * yi - xi * yr + hi(i,i-1) * zzi
      hr(i,j) = xr * zzr - xi * zzi - hi(i,i-1) * yr
      hi(i,j) = xr * zzi + xi * zzr - hi(i,i-1) * yi
   end do
!
end do
!
si = hi(en,en)
if (si .eq. 0.0) go to 540
norm = cabs(cmplx(hr(en,en),si))
sr = hr(en,en) / norm
si = si / norm
hr(en,en) = norm
hi(en,en) = 0.0
if (en .eq. n) go to 540
ip1 = en + 1
!
do j = ip1, n
   yr = hr(en,j)
   yi = hi(en,j)
   hr(en,j) = sr * yr + si * yi
   hi(en,j) = sr * yi - si * yr
end do
!     ********** INVERSE OPERATION (COLUMNS) **********
540 do j = lp1, en
   xr = wr(j-1)
   xi = wi(j-1)
!
   do i = 1, j
      yr = hr(i,j-1)
      yi = 0.0
      zzr = hr(i,j)
      zzi = hi(i,j)
      if (i .eq. j) go to 560
      yi = hi(i,j-1)
      hi(i,j-1) = xr * yi + xi * yr + hi(j,j-1) * zzi
560 hr(i,j-1) = xr * yr - xi * yi + hi(j,j-1) * zzr
      hr(i,j) = xr * zzr + xi * zzi - hi(j,j-1) * yr
      hi(i,j) = xr * zzi - xi * zzr - hi(j,j-1) * yi
   end do
!
   do i = low, igh
      yr = zr(i,j-1)
      yi = zi(i,j-1)
      zzr = zr(i,j)
      zzi = zi(i,j)
      zr(i,j-1) = xr * yr - xi * yi + hi(j,j-1) * zzr
      zi(i,j-1) = xr * yi + xi * yr + hi(j,j-1) * zzi
      zr(i,j) = xr * zzr + xi * zzi - hi(j,j-1) * yr
      zi(i,j) = xr * zzi - xi * zzr - hi(j,j-1) * yi
   end do
!
end do
!
if (si .eq. 0.0) go to 240
!
do i = 1, en
   yr = hr(i,en)
   yi = hi(i,en)
   hr(i,en) = sr * yr - si * yi
   hi(i,en) = sr * yi + si * yr
end do
!
do i = low, igh
   yr = zr(i,en)
   yi = zi(i,en)
   zr(i,en) = sr * yr - si * yi
   zi(i,en) = sr * yi + si * yr
end do
!
go to 240
!     ********** A ROOT FOUND **********
660 hr(en,en) = hr(en,en) + tr
wr(en) = hr(en,en)
hi(en,en) = hi(en,en) + ti
wi(en) = hi(en,en)
en = enm1
go to 220
!     ********** ALL ROOTS FOUND.  BACKSUBSTITUTE TO FIND
!                VECTORS OF UPPER TRIANGULAR FORM **********
680 norm = 0.0
!
do 720 i = 1, n
!
   do 720 j = i, n
      norm = norm + abs(hr(i,j)) + abs(hi(i,j))
720 continue
!
if (n .eq. 1 .or. norm .eq. 0.0) go to 1001
!     ********** FOR en=n STEP -1 UNTIL 2 DO -- **********
do nn = 2, n
   en = n + 2 - nn
   xr = wr(en)
   xi = wi(en)
   enm1 = en - 1
!     ********** FOR i=en-1 STEP -1 UNTIL 1 DO -- **********
   do ii = 1, enm1
      i = en - ii
      zzr = hr(i,en)
      zzi = hi(i,en)
      if (i .eq. enm1) go to 760
      ip1 = i + 1
!
      do j = ip1, enm1
         zzr = zzr + hr(i,j) * hr(j,en) - hi(i,j) * hi(j,en)
         zzi = zzi + hr(i,j) * hi(j,en) + hi(i,j) * hr(j,en)
      end do
!
760 yr = xr - wr(i)
      yi = xi - wi(i)
      if (yr .eq. 0.0 .and. yi .eq. 0.0) yr = machep * norm
      z3 = cmplx(zzr,zzi) / cmplx(yr,yi)
      hr(i,en) = real(z3)
      hi(i,en) = aimag(z3)
   end do
!
end do
!     ********** END BACKSUBSTITUTION **********
enm1 = n - 1
!     ********** VECTORS OF ISOLATED ROOTS **********
do 840 i = 1, enm1
   if (i .ge. low .and. i .le. igh) go to 840
   ip1 = i + 1
!
   do j = ip1, n
      zr(i,j) = hr(i,j)
      zi(i,j) = hi(i,j)
   end do
!
840 continue
!     ********** MULTIPLY BY TRANSFORMATION MATRIX TO GIVE
!                vectors of original full matrix.
!                FOR j=n STEP -1 UNTIL low+1 DO -- **********
do 880 jj = low, enm1
   j = n + low - jj
   m = min0(j-1,igh)
!
   do 880 i = low, igh
      zzr = zr(i,j)
      zzi = zi(i,j)
!
      do k = low, m
         zzr = zzr + zr(i,k) * hr(k,j) - zi(i,k) * hi(k,j)
         zzi = zzi + zr(i,k) * hi(k,j) + zi(i,k) * hr(k,j)
      end do
!
      zr(i,j) = zzr
      zi(i,j) = zzi
880 continue
!
go to 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 ierr = en
1001 return
!     ********** LAST CARD OF comqr2 **********
end subroutine comqr2

subroutine dceig(ibal,ar,ai,ka,n,wr,wi,ierr)
implicit none
integer, intent(in) :: ibal
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
integer :: igh, low
!-----------------------------------------------------------------------
!            Eigenvalues of double precision complex matrices
!-----------------------------------------------------------------------
double precision, intent(inout) :: ar(ka,n), ai(ka,n), wr(n), &
&wi(n)
!
low = 1
igh = n
if (ibal .ne. 0) call dcbal(ka,n,ar,ai,low,igh,wr)
call dcorth(ka,n,low,igh,ar,ai,wr,wi)
call dcomqr(ka,n,low,igh,ar,ai,wr,wi,ierr)
return
end subroutine dceig

subroutine dceigv (ibal,ar,ai,ka,n,wr,wi,zr,zi,ierr,temp)
implicit none
integer, intent(in) :: ibal
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
integer :: i1, i2, i3, igh, low
!-----------------------------------------------------------------------
!                     Eigenvalues and eigenvectors
!                 of double precision complex matrices
!-----------------------------------------------------------------------
double precision, intent(inout) :: ar(ka,n), ai(ka,n), wr(n), &
&wi(n), zr(ka,n), zi(ka,n), temp(*)
!----------------------
!     Temp is a temporary storage area
!        DIMENSION(TEMP) .GE. 2*n    IF ibal .EQ. 0
!        DIMENSION(TEMP) .GE. 3*n    IF ibal .NE. 0
!----------------------
i2 = 1
i3 = n + 1
i1 = n + i3
low = 1
igh = n
if (ibal .ne. 0) call dcbal(ka,n,ar,ai,low,igh,temp(i1))
call dcorth(ka,n,low,igh,ar,ai,temp(i2),temp(i3))
call dcmqr2(ka,n,low,igh,temp(i2),temp(i3),ar,ai,wr,wi, &
&zr,zi,ierr)
if (ierr .ne. 0) return
if (ibal .ne. 0) call dcbabk(ka,n,low,igh,temp(i1),n,zr,zi)
return
end subroutine dceigv

subroutine dcbal(nm,n,ar,ai,low,igh,scale)
implicit none
integer :: ipmpar
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: jj
integer, intent(in) :: nm
integer, intent(inout) :: igh, low
integer :: iexc
double precision, intent(inout) :: ar(nm,n), ai(nm,n), scale(n)
double precision :: c, f, g, r, s, b2, radix
logical :: noconv
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure
!     CBALANCE, which is a complex version of balance,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.II-linear algebra, 315-326(1971).
!
!     dcbal balances a double precision complex matrix and
!     isolates eigenvalues whenever possible.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        ar and ai contain the real and imaginary parts,
!          respectively, of the complex matrix to be balanced.
!
!     On output-
!
!        ar and ai contain the real and imaginary parts,
!          respectively, of the balanced matrix,
!
!        Low and igh are two integers such that ar(i,j) and ai(i,j)
!          are equal to zero if
!           (1) i is greater than j and
!           (2) j=1,...,low-1 OR i=igh+1,...,n,
!
!        Scale contains information determining the
!           permutations and scaling factors used.
!
!     Suppose that the principal submatrix in rows low through igh
!     has been balanced, that P(j) denotes the index interchanged
!     with j during the permutation step, and that the elements
!     of the diagonal matrix used are denoted by D(i,j).  Then
!        scale(j) = P(j),    FOR j = 1,...,low-1
!                 = D(j,j)       j = low,...,igh
!                 = P(j)         j = igh+1,...,n.
!     The order in which the interchanges are made is n to igh+1,
!     then 1 to low-1.
!
!     Note that 1 is returned for igh if igh is zero formally.
!
!     The Algol procedure exc contained in CBALANCE appears in
!     dcbal in line.  (Note that the Algol roles of identifiers
!     k,l have been reversed.)
!
!-----------------------------------------------------------------------
!
!     ********** radix IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                the base of the machine floating point representation.
!
           radix = ipmpar(4)
!
!                **********
!
b2 = radix * radix
k = 1
l = n
go to 100
!     ********** IN-LINE PROCEDURE FOR ROW AND
!                COLUMN EXCHANGE **********
20 scale(m) = j
if (j .eq. m) go to 50
!
do i = 1, l
   f = ar(i,j)
   ar(i,j) = ar(i,m)
   ar(i,m) = f
   f = ai(i,j)
   ai(i,j) = ai(i,m)
   ai(i,m) = f
end do
!
do i = k, n
   f = ar(j,i)
   ar(j,i) = ar(m,i)
   ar(m,i) = f
   f = ai(j,i)
   ai(j,i) = ai(m,i)
   ai(m,i) = f
end do
!
50 go to (80,130), iexc
!     ********** SEARCH FOR ROWS ISOLATING AN EIGENVALUE
!                AND PUSH THEM DOWN **********
80 if (l .eq. 1) go to 280
l = l - 1
!     ********** FOR j=l STEP -1 UNTIL 1 DO -- **********
100 do 120 jj = 1, l
   j = l + 1 - jj
!
   do 110 i = 1, l
      if (i .eq. j) go to 110
      if (ar(j,i) .ne. 0.d0 .or. ai(j,i) .ne. 0.d0) go to 120
110 continue
!
   m = l
   iexc = 1
   go to 20
120 continue
!
go to 140
!     ********** SEARCH FOR COLUMNS ISOLATING AN EIGENVALUE
!                AND PUSH THEM LEFT **********
130 k = k + 1
!
140 do 170 j = k, l
!
   do 150 i = k, l
      if (i .eq. j) go to 150
      if (ar(i,j) .ne. 0.d0 .or. ai(i,j) .ne. 0.d0) go to 170
150 continue
!
   m = k
   iexc = 2
   go to 20
170 continue
!     ********** NOW BALANCE THE SUBMATRIX IN ROWS k TO l **********
do 180 i = k, l
180 scale(i) = 1.d0
!     ********** ITERATIVE LOOP FOR NORM REDUCTION **********
190 noconv = .false.
!
do 270 i = k, l
   c = 0.d0
   r = 0.d0
!
   do 200 j = k, l
      if (j .eq. i) go to 200
      c = c + dabs(ar(j,i)) + dabs(ai(j,i))
      r = r + dabs(ar(i,j)) + dabs(ai(i,j))
200 continue
!     ********** GUARD AGAINST ZERO c OR r DUE TO UNDERFLOW **********
   if (c .eq. 0.d0 .or. r .eq. 0.d0) go to 270
   g = r / radix
   f = 1.d0
   s = c + r
210 if (c .ge. g) go to 220
   f = f * radix
   c = c * b2
   go to 210
220 g = r * radix
230 if (c .lt. g) go to 240
   f = f / radix
   c = c / b2
   go to 230
!     ********** NOW BALANCE **********
240 if ((c + r) / f .ge. 0.95d0 * s) go to 270
   g = 1.d0 / f
   scale(i) = scale(i) * f
   noconv = .true.
!
   do j = k, n
      ar(i,j) = ar(i,j) * g
      ai(i,j) = ai(i,j) * g
   end do
!
   do j = 1, l
      ar(j,i) = ar(j,i) * f
      ai(j,i) = ai(j,i) * f
   end do
!
270 continue
!
if (noconv) go to 190
!
280 low = k
igh = l
return
!     ********** LAST CARD OF dcbal **********
end subroutine dcbal

subroutine dcorth(nm,n,low,igh,ar,ai,ortr,orti)
implicit none
!
integer :: i, j, m
integer, intent(in) :: n
integer :: ii, jj, la, mp
integer, intent(in) :: nm, igh
integer :: kp1
integer, intent(in) :: low
double precision, intent(inout) :: ar(nm,n), ai(nm,n), ortr(igh), &
&orti(igh)
double precision :: f, g, h, fi, fr, scale
double precision :: dcpabs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of a complex analogue of
!     the Algol procedure orthes, NUM. Math. 12, 349-368(1968)
!     by Martin and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 339-358(1971).
!
!     Given a double precision complex matrix, dcorth
!     reduces a submatrix situated in rows and columns
!     low through igh to upper Hessenberg form by
!     unitary similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dcbal.  If dcbal has not been used,
!          SET low=1, igh=n,
!
!        ar and ai contain the real and imaginary parts,
!          respectively, of the complex input matrix.
!
!     On output-
!
!        ar and ai contain the real and imaginary parts,
!          respectively, of the Hessenberg matrix.  Information
!          about the unitary transformations used in the reduction
!          is stored in the remaining triangles under the
!          Hessenberg matrix,
!
!        ortr and ORTI contain further information about the
!          transformations.  Only elements low through igh are used.
!
!-----------------------------------------------------------------------
la = igh - 1
kp1 = low + 1
if (la .lt. kp1) go to 200
!
do 180 m = kp1, la
   h = 0.d0
   ortr(m) = 0.d0
   orti(m) = 0.d0
   scale = 0.d0
!     ********** scale COLUMN (ALGOL TOL THEN NOT NEEDED) **********
   do 90 i = m, igh
90 scale = scale + dabs(ar(i,m-1)) + dabs(ai(i,m-1))
!
   if (scale .eq. 0.d0) go to 180
   mp = m + igh
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
   do ii = m, igh
      i = mp - ii
      ortr(i) = ar(i,m-1) / scale
      orti(i) = ai(i,m-1) / scale
      h = h + ortr(i) * ortr(i) + orti(i) * orti(i)
   end do
!
   g = dsqrt(h)
   f = dcpabs(ortr(m),orti(m))
   if (f .eq. 0.d0) go to 103
   h = h + f * g
   g = g / f
   ortr(m) = (1.d0 + g) * ortr(m)
   orti(m) = (1.d0 + g) * orti(m)
   go to 105
!
103 ortr(m) = g
   ar(m,m-1) = scale
!     ********** FORM (i-(U*UT)/h) * A **********
105 do j = m, n
      fr = 0.d0
      fi = 0.d0
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
      do ii = m, igh
         i = mp - ii
         fr = fr + ortr(i) * ar(i,j) + orti(i) * ai(i,j)
         fi = fi + ortr(i) * ai(i,j) - orti(i) * ar(i,j)
      end do
!
      fr = fr / h
      fi = fi / h
!
      do i = m, igh
         ar(i,j) = ar(i,j) - fr * ortr(i) + fi * orti(i)
         ai(i,j) = ai(i,j) - fr * orti(i) - fi * ortr(i)
      end do
!
   end do
!     ********** FORM (i-(U*UT)/h)*A*(i-(U*UT)/h) **********
   do i = 1, igh
      fr = 0.d0
      fi = 0.d0
!     ********** FOR j=igh STEP -1 UNTIL m DO -- **********
      do jj = m, igh
         j = mp - jj
         fr = fr + ortr(j) * ar(i,j) - orti(j) * ai(i,j)
         fi = fi + ortr(j) * ai(i,j) + orti(j) * ar(i,j)
      end do
!
      fr = fr / h
      fi = fi / h
!
      do j = m, igh
         ar(i,j) = ar(i,j) - fr * ortr(j) - fi * orti(j)
         ai(i,j) = ai(i,j) + fr * orti(j) - fi * ortr(j)
      end do
!
   end do
!
   ortr(m) = scale * ortr(m)
   orti(m) = scale * orti(m)
   ar(m,m-1) = -g * ar(m,m-1)
   ai(m,m-1) = -g * ai(m,m-1)
180 continue
!
200 return
!     ********** LAST CARD OF dcorth **********
end subroutine dcorth

subroutine dcomqr(nm,n,low,igh,hr,hi,wr,wi,ierr)
implicit none
!
integer :: i, j, l
integer, intent(in) :: n
integer :: en, ll
integer, intent(in) :: nm, igh
integer :: its
integer, intent(in) :: low
integer :: lp1, enm1
integer, intent(out) :: ierr
double precision, intent(inout) :: hr(nm,n), hi(nm,n), wr(n), &
&wi(n)
double precision :: si, sr, ti, tr, xi, xr, yi, yr, zzi, zzr, &
&norm, machep
double precision :: r2, w(2), z(2)
double precision :: dpmpar, dcpabs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of a unitary analogue of the
!     Algol procedure  COMLR, NUM. Math. 12, 369-376(1968) By Martin
!     and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 396-403(1971).
!     The unitary analogue substitutes the QR algorithm of Francis
!     (comp. Jour. 4, 332-345(1962)) For the LR algorithm.
!
!     This subroutine finds the eigenvalues of a double precision
!     complex upper Hessenberg matrix BY the QR method.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dcbal.  If dcbal has not been used,
!          SET low=1, igh=n,
!
!        hr and hi contain the real and imaginary parts,
!          respectively, of the complex upper Hessenberg matrix.
!          Their lower triangles below the subdiagonal contain
!          information about the unitary transformations used in
!          the reduction by dcorth, if performed.
!
!     On output-
!
!        The upper Hessenberg portions of hr and hi have been
!          destroyed.  Therefore, they must be saved before
!          calling dcomqr if subsequent calculation of
!          eigenvectors is to be performed,
!
!        wr and WI contain the real and imaginary parts,
!          respectively, of the eigenvalues.  If an error
!          exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 50 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                the relative precision of floating point arithmetic.
!
           machep = dpmpar(1)
!
!                **********
!
ierr = 0
if (low .eq. igh) go to 180
!     ********** CREATE REAL SUBDIAGONAL ELEMENTS **********
l = low + 1
!
do 170 i = l, igh
   ll = min0(i+1,igh)
   if (hi(i,i-1) .eq. 0.d0) go to 170
   norm = dcpabs(hr(i,i-1),hi(i,i-1))
   yr = hr(i,i-1) / norm
   yi = hi(i,i-1) / norm
   hr(i,i-1) = norm
   hi(i,i-1) = 0.d0
!
   do j = i, igh
      si = yr * hi(i,j) - yi * hr(i,j)
      hr(i,j) = yr * hr(i,j) + yi * hi(i,j)
      hi(i,j) = si
   end do
!
   do j = low, ll
      si = yr * hi(j,i) + yi * hr(j,i)
      hr(j,i) = yr * hr(j,i) - yi * hi(j,i)
      hi(j,i) = si
   end do
!
170 continue
!     ********** STORE ROOTS ISOLATED BY dcbal **********
180 do 200 i = 1, n
   if (i .ge. low .and. i .le. igh) go to 200
   wr(i) = hr(i,i)
   wi(i) = hi(i,i)
200 continue
!
en = igh
tr = 0.d0
ti = 0.d0
!     ********** SEARCH FOR NEXT EIGENVALUE **********
220 if (en .lt. low) go to 1001
its = 0
enm1 = en - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR l=en STEP -1 UNTIL low  -- **********
240 do ll = low, en
   l = en + low - ll
   if (l .eq. low) go to 300
   if (dabs(hr(l,l-1)) .le. &
&machep * (dabs(hr(l-1,l-1)) + dabs(hi(l-1,l-1)) &
&+ dabs(hr(l,l)) + dabs(hi(l,l)))) go to 300
end do
!     ********** FORM SHIFT **********
300 if (l .eq. en) go to 660
if (its .eq. 50) go to 1000
if (its .eq. 10 .or. its .eq. 20 .or. its .eq. 30) go to 320
sr = hr(en,en)
si = hi(en,en)
xr = hr(enm1,en) * hr(en,enm1)
xi = hi(enm1,en) * hr(en,enm1)
if (xr .eq. 0.d0 .and. xi .eq. 0.d0) go to 340
yr = (hr(enm1,enm1) - sr) / 2.d0
yi = (hi(enm1,enm1) - si) / 2.d0
z(1) = yr*yr - yi*yi + xr
z(2) = 2.d0*yr*yi + xi
call dcsqrt(z,w)
zzr = w(1)
zzi = w(2)
if (yr * zzr + yi * zzi .ge. 0.d0) go to 310
zzr = -zzr
zzi = -zzi
310 z(1) = yr + zzr
z(2) = yi + zzi
r2 = z(1)**2 + z(2)**2
sr = sr - (xr*z(1) + xi*z(2))/r2
si = si - (xi*z(1) - xr*z(2))/r2
go to 340
!     ********** FORM EXCEPTIONAL SHIFT **********
320 sr = dabs(hr(en,enm1)) + dabs(hr(enm1,en-2))
si = 0.d0
!
340 do i = low, en
   hr(i,i) = hr(i,i) - sr
   hi(i,i) = hi(i,i) - si
end do
!
tr = tr + sr
ti = ti + si
its = its + 1
!     ********** REDUCE TO TRIANGLE (ROWS) **********
lp1 = l + 1
!
do i = lp1, en
   sr = hr(i,i-1)
   hr(i,i-1) = 0.d0
   norm = dsqrt(hr(i-1,i-1)*hr(i-1,i-1)+hi(i-1,i-1)*hi(i-1,i-1) &
&+ sr*sr)
   xr = hr(i-1,i-1) / norm
   wr(i-1) = xr
   xi = hi(i-1,i-1) / norm
   wi(i-1) = xi
   hr(i-1,i-1) = norm
   hi(i-1,i-1) = 0.d0
   hi(i,i-1) = sr / norm
!
   do j = i, en
      yr = hr(i-1,j)
      yi = hi(i-1,j)
      zzr = hr(i,j)
      zzi = hi(i,j)
      hr(i-1,j) = xr * yr + xi * yi + hi(i,i-1) * zzr
      hi(i-1,j) = xr * yi - xi * yr + hi(i,i-1) * zzi
      hr(i,j) = xr * zzr - xi * zzi - hi(i,i-1) * yr
      hi(i,j) = xr * zzi + xi * zzr - hi(i,i-1) * yi
   end do
!
end do
!
si = hi(en,en)
if (si .eq. 0.d0) go to 540
norm = dcpabs(hr(en,en),si)
sr = hr(en,en) / norm
si = si / norm
hr(en,en) = norm
hi(en,en) = 0.d0
!     ********** INVERSE OPERATION (COLUMNS) **********
540 do j = lp1, en
   xr = wr(j-1)
   xi = wi(j-1)
!
   do i = l, j
      yr = hr(i,j-1)
      yi = 0.d0
      zzr = hr(i,j)
      zzi = hi(i,j)
      if (i .eq. j) go to 560
      yi = hi(i,j-1)
      hi(i,j-1) = xr * yi + xi * yr + hi(j,j-1) * zzi
560 hr(i,j-1) = xr * yr - xi * yi + hi(j,j-1) * zzr
      hr(i,j) = xr * zzr + xi * zzi - hi(j,j-1) * yr
      hi(i,j) = xr * zzi - xi * zzr - hi(j,j-1) * yi
   end do
!
end do
!
if (si .eq. 0.d0) go to 240
!
do i = l, en
   yr = hr(i,en)
   yi = hi(i,en)
   hr(i,en) = sr * yr - si * yi
   hi(i,en) = sr * yi + si * yr
end do
!
go to 240
!     ********** A ROOT FOUND **********
660 wr(en) = hr(en,en) + tr
wi(en) = hi(en,en) + ti
en = enm1
go to 220
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 ierr = en
1001 return
end subroutine dcomqr

subroutine dcbabk (nm,n,low,igh,scale,m,zr,zi)
implicit none
!
integer :: i, j, k
integer, intent(in) :: m, n
integer :: ii
integer, intent(in) :: nm, igh, low
double precision, intent(in) :: scale(n)
double precision, intent(inout) :: zr(nm,m), zi(nm,m)
double precision :: s
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure
!     cbabk2, which is a complex version of balbak,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 315-326(1971).
!
!     This subroutine forms the eigenvectors of a double precision
!     complex matrix BY back transforming those of the corresponding
!     balanced matrix determined by dcbal.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by dcbal,
!
!        Scale contains information determining the permutations
!          and scaling factors used by dcbal,
!
!        m is the number of eigenvectors to be back transformed,
!
!        zr and zi contain the real and imaginary parts,
!          respectively, of the eigenvectors to be
!          back transformed in their first m columns.
!
!     On output-
!
!        zr and zi contain the real and imaginary parts,
!          respectively, of the transformed eigenvectors
!          in their first m columns.
!
!-----------------------------------------------------------------------
if (m .eq. 0) go to 200
if (igh .eq. low) go to 120
!
do i = low, igh
   s = scale(i)
!     ********** LEFT HAND EIGENVECTORS ARE BACK TRANSFORMED
!                if the foregoing statement is replaced by
!                s=1.0/scale(i). **********
   do j = 1, m
      zr(i,j) = zr(i,j) * s
      zi(i,j) = zi(i,j) * s
   end do
!
end do
!
!     ********** FOR i=low-1 STEP -1 UNTIL 1,
!                igh+1 STEP 1 UNTIL n DO -- **********
120 do 140 ii = 1, n
   i = ii
   if (i .ge. low .and. i .le. igh) go to 140
   if (i .lt. low) i = low - ii
   k = scale(i)
   if (k .eq. i) go to 140
!
   do j = 1, m
      s = zr(i,j)
      zr(i,j) = zr(k,j)
      zr(k,j) = s
      s = zi(i,j)
      zi(i,j) = zi(k,j)
      zi(k,j) = s
   end do
!
140 continue
!
200 return
!     ********** LAST CARD OF dcbabk **********
end subroutine dcbabk

subroutine dcmqr2 (nm,n,low,igh,ortr,orti,hr,hi,wr,wi,zr,zi,ierr)
implicit none
!
integer :: i, j, k, l, m
integer, intent(in) :: n
integer :: en, ii, jj, ll
integer, intent(in) :: nm
integer :: nn
integer, intent(in) :: igh
integer :: ip1, its
integer, intent(in) :: low
integer :: lp1, enm1, iend
integer, intent(out) :: ierr
double precision, intent(inout) :: hr(nm,n), hi(nm,n), wr(n), &
&wi(n), zr(nm,n), zi(nm,n), ortr(igh), orti(igh)
double precision :: si, sr, ti, tr, xi, xr, yi, yr, zzi, zzr, &
&norm, machep
double precision :: r2, w(2), z(2)
double precision :: dpmpar, dcpabs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of a unitary analogue of the
!     Algol procedure  COMLR2, NUM. Math. 16, 181-204(1970) By peters
!     and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 372-395(1971).
!     The unitary analogue substitutes the QR algorithm of Francis
!     (comp. Jour. 4, 332-345(1962)) For the LR algorithm.
!
!     This subroutine finds the eigenvalues and eigenvectors of
!     a double precision complex upper Hessenberg matrix BY the
!     QR method.  The eigenvectors of a complex general matrix
!     can also be found if dcorth has been used to reduce
!     this general matrix to Hessenberg form.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dcbal.  If dcbal has not been used,
!          SET low=1, igh=n,
!
!        ORTR and ORTI contain information about the unitary trans-
!          formations used in the reduction by dcorth, if performed.
!          Only elements low through igh are used.  If the eigenvectors
!          of the Hessenberg matrix are desired, set ORTR(j) and
!          ORTI(j) to 0.0 for these elements,
!
!        hr and hi contain the real and imaginary parts,
!          respectively, of the complex upper Hessenberg matrix.
!          Their lower triangles below the subdiagonal contain further
!          information about the transformations which were used in the
!          reduction by dcorth, if performed.  If the eigenvectors of
!          the Hessenberg matrix are desired, these elements may be
!          arbitrary.
!
!     On output-
!
!        ORTR, ORTI, and the upper Hessenberg portions of hr and hi
!          have been destroyed,
!
!        wr and WI contain the real and imaginary parts,
!          respectively, of the eigenvalues.  If an error
!          exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        ZR and ZI contain the real and imaginary parts,
!          respectively, of the eigenvectors.  The eigenvectors
!          are unnormalized.  If an error exit is made, none of
!          the eigenvectors has been found,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 50 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                the relative precision of floating point arithmetic.
!
           machep = dpmpar(1)
!
!                **********
!
ierr = 0
!     ********** INITIALIZE EIGENVECTOR MATRIX **********
do 100 i = 1, n
!
   do 100 j = 1, n
      zr(i,j) = 0.d0
      zi(i,j) = 0.d0
      if (i .eq. j) zr(i,j) = 1.d0
100 continue
!     ********** FORM THE MATRIX OF ACCUMULATED TRANSFORMATIONS
!                FROM THE INFORMATION LEFT BY dcorth **********
iend = igh - low - 1
if (iend) 180, 150, 105
!     ********** FOR i=igh-1 STEP -1 UNTIL low+1 DO -- **********
105 do 140 ii = 1, iend
   i = igh - ii
   if (ortr(i) .eq. 0.d0 .and. orti(i) .eq. 0.d0) go to 140
   if (hr(i,i-1) .eq. 0.d0 .and. hi(i,i-1) .eq. 0.d0) go to 140
!     ********** NORM BELOW IS NEGATIVE OF H FORMED IN dcorth **********
   norm = hr(i,i-1) * ortr(i) + hi(i,i-1) * orti(i)
   ip1 = i + 1
!
   do k = ip1, igh
      ortr(k) = hr(k,i-1)
      orti(k) = hi(k,i-1)
   end do
!
   do j = i, igh
      sr = 0.d0
      si = 0.d0
!
      do k = i, igh
         sr = sr + ortr(k) * zr(k,j) + orti(k) * zi(k,j)
         si = si + ortr(k) * zi(k,j) - orti(k) * zr(k,j)
      end do
!
      sr = sr / norm
      si = si / norm
!
      do k = i, igh
         zr(k,j) = zr(k,j) + sr * ortr(k) - si * orti(k)
         zi(k,j) = zi(k,j) + sr * orti(k) + si * ortr(k)
      end do
!
   end do
!
140 continue
!     ********** CREATE REAL SUBDIAGONAL ELEMENTS **********
150 l = low + 1
!
do 170 i = l, igh
   ll = min0(i+1,igh)
   if (hi(i,i-1) .eq. 0.d0) go to 170
   norm = dcpabs(hr(i,i-1),hi(i,i-1))
   yr = hr(i,i-1) / norm
   yi = hi(i,i-1) / norm
   hr(i,i-1) = norm
   hi(i,i-1) = 0.d0
!
   do j = i, n
      si = yr * hi(i,j) - yi * hr(i,j)
      hr(i,j) = yr * hr(i,j) + yi * hi(i,j)
      hi(i,j) = si
   end do
!
   do j = 1, ll
      si = yr * hi(j,i) + yi * hr(j,i)
      hr(j,i) = yr * hr(j,i) - yi * hi(j,i)
      hi(j,i) = si
   end do
!
   do j = low, igh
      si = yr * zi(j,i) + yi * zr(j,i)
      zr(j,i) = yr * zr(j,i) - yi * zi(j,i)
      zi(j,i) = si
   end do
!
170 continue
!     ********** STORE ROOTS ISOLATED BY dcbal **********
180 do 200 i = 1, n
   if (i .ge. low .and. i .le. igh) go to 200
   wr(i) = hr(i,i)
   wi(i) = hi(i,i)
200 continue
!
en = igh
tr = 0.d0
ti = 0.d0
!     ********** SEARCH FOR NEXT EIGENVALUE **********
220 if (en .lt. low) go to 680
its = 0
enm1 = en - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR l=en STEP -1 UNTIL LOW DO -- **********
240 do ll = low, en
   l = en + low - ll
   if (l .eq. low) go to 300
   if (dabs(hr(l,l-1)) .le. &
&machep * (dabs(hr(l-1,l-1)) + dabs(hi(l-1,l-1)) &
&+ dabs(hr(l,l)) + dabs(hi(l,l)))) go to 300
end do
!     ********** FORM SHIFT **********
300 if (l .eq. en) go to 660
if (its .eq. 50) go to 1000
if (its .eq. 10 .or. its .eq. 20 .or. its .eq. 30) go to 320
sr = hr(en,en)
si = hi(en,en)
xr = hr(enm1,en) * hr(en,enm1)
xi = hi(enm1,en) * hr(en,enm1)
if (xr .eq. 0.d0 .and. xi .eq. 0.d0) go to 340
yr = (hr(enm1,enm1) - sr) / 2.d0
yi = (hi(enm1,enm1) - si) / 2.d0
z(1) = yr*yr - yi*yi + xr
z(2) = 2.d0*yr*yi + xi
call dcsqrt(z,w)
zzr = w(1)
zzi = w(2)
if (yr * zzr + yi * zzi .ge. 0.d0) go to 310
zzr = -zzr
zzi = -zzi
310 z(1) = yr + zzr
z(2) = yi + zzi
r2 = z(1)**2 + z(2)**2
sr = sr - (xr*z(1) + xi*z(2))/r2
si = si - (xi*z(1) - xr*z(2))/r2
go to 340
!     ********** FORM EXCEPTIONAL SHIFT **********
320 sr = dabs(hr(en,enm1)) + dabs(hr(enm1,en-2))
si = 0.d0
!
340 do i = low, en
   hr(i,i) = hr(i,i) - sr
   hi(i,i) = hi(i,i) - si
end do
!
tr = tr + sr
ti = ti + si
its = its + 1
!     ********** REDUCE TO TRIANGLE (ROWS) **********
lp1 = l + 1
!
do i = lp1, en
   sr = hr(i,i-1)
   hr(i,i-1) = 0.d0
   norm = dsqrt(hr(i-1,i-1)*hr(i-1,i-1)+hi(i-1,i-1)*hi(i-1,i-1) &
&+ sr*sr)
   xr = hr(i-1,i-1) / norm
   wr(i-1) = xr
   xi = hi(i-1,i-1) / norm
   wi(i-1) = xi
   hr(i-1,i-1) = norm
   hi(i-1,i-1) = 0.d0
   hi(i,i-1) = sr / norm
!
   do j = i, n
      yr = hr(i-1,j)
      yi = hi(i-1,j)
      zzr = hr(i,j)
      zzi = hi(i,j)
      hr(i-1,j) = xr * yr + xi * yi + hi(i,i-1) * zzr
      hi(i-1,j) = xr * yi - xi * yr + hi(i,i-1) * zzi
      hr(i,j) = xr * zzr - xi * zzi - hi(i,i-1) * yr
      hi(i,j) = xr * zzi + xi * zzr - hi(i,i-1) * yi
   end do
!
end do
!
si = hi(en,en)
if (si .eq. 0.d0) go to 540
norm = dcpabs(hr(en,en),si)
sr = hr(en,en) / norm
si = si / norm
hr(en,en) = norm
hi(en,en) = 0.d0
if (en .eq. n) go to 540
ip1 = en + 1
!
do j = ip1, n
   yr = hr(en,j)
   yi = hi(en,j)
   hr(en,j) = sr * yr + si * yi
   hi(en,j) = sr * yi - si * yr
end do
!     ********** INVERSE OPERATION (COLUMNS) **********
540 do j = lp1, en
   xr = wr(j-1)
   xi = wi(j-1)
!
   do i = 1, j
      yr = hr(i,j-1)
      yi = 0.d0
      zzr = hr(i,j)
      zzi = hi(i,j)
      if (i .eq. j) go to 560
      yi = hi(i,j-1)
      hi(i,j-1) = xr * yi + xi * yr + hi(j,j-1) * zzi
560 hr(i,j-1) = xr * yr - xi * yi + hi(j,j-1) * zzr
      hr(i,j) = xr * zzr + xi * zzi - hi(j,j-1) * yr
      hi(i,j) = xr * zzi - xi * zzr - hi(j,j-1) * yi
   end do
!
   do i = low, igh
      yr = zr(i,j-1)
      yi = zi(i,j-1)
      zzr = zr(i,j)
      zzi = zi(i,j)
      zr(i,j-1) = xr * yr - xi * yi + hi(j,j-1) * zzr
      zi(i,j-1) = xr * yi + xi * yr + hi(j,j-1) * zzi
      zr(i,j) = xr * zzr + xi * zzi - hi(j,j-1) * yr
      zi(i,j) = xr * zzi - xi * zzr - hi(j,j-1) * yi
   end do
!
end do
!
if (si .eq. 0.d0) go to 240
!
do i = 1, en
   yr = hr(i,en)
   yi = hi(i,en)
   hr(i,en) = sr * yr - si * yi
   hi(i,en) = sr * yi + si * yr
end do
!
do i = low, igh
   yr = zr(i,en)
   yi = zi(i,en)
   zr(i,en) = sr * yr - si * yi
   zi(i,en) = sr * yi + si * yr
end do
!
go to 240
!     ********** A ROOT FOUND **********
660 hr(en,en) = hr(en,en) + tr
wr(en) = hr(en,en)
hi(en,en) = hi(en,en) + ti
wi(en) = hi(en,en)
en = enm1
go to 220
!     ********** ALL ROOTS FOUND.  BACKSUBSTITUTE TO FIND
!                VECTORS OF UPPER TRIANGULAR FORM **********
680 norm = 0.d0
!
do 720 i = 1, n
!
   do 720 j = i, n
      norm = norm + dabs(hr(i,j)) + dabs(hi(i,j))
720 continue
!
if (n .eq. 1 .or. norm .eq. 0.d0) go to 1001
!     ********** FOR en=n STEP -1 UNTIL 2 DO -- **********
do nn = 2, n
   en = n + 2 - nn
   xr = wr(en)
   xi = wi(en)
   enm1 = en - 1
!     ********** FOR i=en-1 STEP -1 UNTIL 1 DO -- **********
   do ii = 1, enm1
      i = en - ii
      zzr = hr(i,en)
      zzi = hi(i,en)
      if (i .eq. enm1) go to 760
      ip1 = i + 1
!
      do j = ip1, enm1
         zzr = zzr + hr(i,j) * hr(j,en) - hi(i,j) * hi(j,en)
         zzi = zzi + hr(i,j) * hi(j,en) + hi(i,j) * hr(j,en)
      end do
!
760 yr = xr - wr(i)
      yi = xi - wi(i)
      if (yr .eq. 0.d0 .and. yi .eq. 0.d0) yr = machep * norm
      r2 = yr*yr + yi*yi
      hr(i,en) = (zzr*yr + zzi*yi)/r2
      hi(i,en) = (zzi*yr - zzr*yi)/r2
   end do
!
end do
!     ********** END BACKSUBSTITUTION **********
enm1 = n - 1
!     ********** VECTORS OF ISOLATED ROOTS **********
do 840 i = 1, enm1
   if (i .ge. low .and. i .le. igh) go to 840
   ip1 = i + 1
!
   do j = ip1, n
      zr(i,j) = hr(i,j)
      zi(i,j) = hi(i,j)
   end do
!
840 continue
!     ********** MULTIPLY BY TRANSFORMATION MATRIX TO GIVE
!                vectors of original full matrix.
!                FOR j=n STEP -1 UNTIL low+1 DO -- **********
do 880 jj = low, enm1
   j = n + low - jj
   m = min0(j-1,igh)
!
   do 880 i = low, igh
      zzr = zr(i,j)
      zzi = zi(i,j)
!
      do k = low, m
         zzr = zzr + zr(i,k) * hr(k,j) - zi(i,k) * hi(k,j)
         zzi = zzi + zr(i,k) * hi(k,j) + zi(i,k) * hr(k,j)
      end do
!
      zr(i,j) = zzr
      zi(i,j) = zzi
880 continue
!
go to 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 ierr = en
1001 return
!     ********** LAST CARD OF dcmqr2 **********
end subroutine dcmqr2

subroutine cl1(k, l, m, n, q, kq, kode, toler, iter, x, res, &
&error, wk, iwk)
implicit none
integer, intent(inout) :: iter, iwk(*)
integer, intent(in) :: k
integer, intent(inout) :: kode
integer, intent(in) :: kq, l, m, n
real, intent(inout) :: error, q(kq,*), res(*)
real, intent(in) :: toler
real, intent(inout) :: wk(*), x(*)
integer :: klm
!     -------------------
klm = k + l + m
call xl1(k, l, m, n, klm, kq, klm + n, n + 2, q, kode, toler, &
&iter, x, res, error, wk, iwk(klm+1), iwk(1))
return
end subroutine cl1

subroutine xl1(k, l, m, n, klmd, klm2d, nklmd, n2d, &
&q, kode, toler, iter, x, res, error, cu, iu, s)
implicit none
!
! This subroutine uses a modification of the simplex
! method of linear programming to calculate an L1 solution
! to A k by n system of linear equations
!             ax=b
! subject to l linear equality constraints
!             cx=d
! and m linear inequality constraints
!             EX.LE.F.
! Description of parameters
! k      NUMBER OF ROWS OF THE MATRIX A (k.GE.1).
! l      NUMBER OF ROWS OF THE MATRIX C (l.GE.0).
! m      NUMBER OF ROWS OF THE MATRIX E (m.GE.0).
! n      NUMBER OF COLUMNS OF THE MATRICES A,C,E (n.GE.1).
! klmd   SET TO AT LEAST k+l+m FOR ADJUSTABLE DIMENSIONS.
! klm2d  set to at least k+l+m+2 for adjustable dimensions.
! nklmd  set to at least n+k+l+m for adjustable dimensions.
! n2d    SET TO AT LEAST n+2 FOR ADJUSTABLE DIMENSIONS
! q      TWO DIMENSIONAL REAL ARRAY WITH klm2d ROWS AND
!        at least n2d columns.
!        On entry the matrices A,C and E, and the vectors
!        B,D and F must be stored in the first k+l+m rows
!        and n+1 columns of q as follows
!             A B
!         q = C D
!             E F
!        these values are destroyed by the subroutine.
! kode   A CODE USED ON ENTRY TO, AND EXIT
!        from, the subroutine.
!        On entry, this should normally be set to 0.
!        However, if certain nonnegativity constraints
!        are to be included implicitly, rather than
!        EXPLICITLY IN THE CONSTRAINTS EX.LE.F, THEN kode
!        should be set to 1, and the nonnegativity
!        constraints included in the arrays x and
!        res (see below).
!        On exit, kode has one of the
!        following values
!             0- optimal solution found,
!             1- no feasible solution to the
!                constraints,
!             2- calculations terminated
!                prematurely due to rounding errors,
!             3- maximum number of iterations reached.
! toler  a small positive tolerance. Empirical
!        EVIDENCE SUGGESTS toler = 10**(-D*2/3),
!        where D represents the number of decimal
!        digits of accuracy available. Essentially,
!        the subroutine CANNOT distinguish between zero
!        and any quantity whose magnitude does not exceed
!        toler. In particular, it will not pivot on any
!        number whose magnitude does not exceed toler.
! ITER   ON ENTRY ITER MUST CONTAIN AN UPPER BOUND ON
!        the maximum number of iterations allowed.
!        A suggested value is 10*(k+l+m). On exit iter
!        gives the number of simplex iterations.
! x      ONE DIMENSIONAL REAL ARRAY OF SIZE AT LEAST n2d.
!        On exit this array contains A
!        SOLUTION TO THE L1 PROBLEM. IF kode=1
!        on entry, this array is also used to include
!        simple nonnegativity constraints on the
!        variables. The values -1, 0, or 1
!        for x(j) indicate that the j-TH variable
!        IS RESTRICTED TO BE .LE.0, UNRESTRICTED,
!        OR .GE.0 RESPECTIVELY.
! RES    ONE DIMENSIONAL REAL ARRAY OF SIZE AT LEAST klmd.
!        On exit this contains the residuals B-AX
!        in the first k components, D-CX in the
!        NEXT l COMPONENTS (THESE WILL BE =0),AND
!        F-EX IN THE NEXT m COMPONENTS. IF kode=1 ON
!        entry, this array is also used to include simple
!        nonnegativity constraints on the residuals
!        B-AX. The values -1, 0, or 1 for res(i)
!        INDICATE THAT THE i-TH RESIDUAL (1.le.i.le.k) IS
!        RESTRICTED TO BE .LE.0, UNRESTRICTED, OR .GE.0
!        respectively.
! Error  on exit, this gives the minimum sum of
!        absolute values of the residuals.
! cu     A TWO DIMENSIONAL REAL ARRAY WITH TWO ROWS AND
!        at least nklmd columns used for workspace.
! iu     A TWO DIMENSIONAL INTEGER ARRAY WITH TWO ROWS AND
!        at least nklmd columns used for workspace.
! s      INTEGER ARRAY OF SIZE AT LEAST klmd, USED FOR
!        workspace.
! If your Fortran compiler permits a single column of a two
! dimensional array to be passed to a one dimensional array
! through a subroutine CALL, considerable savings in
! execution time may be achieved through the use of the
! following subroutine, which operates on column vectors.
!     subroutine col(v1, v2, xmlt, notrow, k)
! this subroutine adds to the vector v1 a multiple of the
! vector v2 (elements 1 through k excluding NOTROW).
!     dimension v1(k), v2(k)
!     kend = notrow - 1
!     kstart = notrow + 1
!     if (kend .lt. 1) go to 20
!     do 10 i=1,kend
!        v1(i) = v1(i) + xmlt*v2(i)
!  10 continue
!     if(kstart .gt. k) go to 40
!  20 do 30 i=kstart,k
!       v1(i) = v1(i) + xmlt*v2(i)
!  30 continue
!  40 return
!     end
! see comments following statement labelled 440 for
! instructions on the implementation of this modification.
!
double precision :: sum
real, intent(inout) :: q, x
real :: z
real, intent(inout) :: cu
real :: sn, zu, zv, cuv
real, intent(inout) :: res
real :: xmax, xmin
real, intent(inout) :: error
real :: pivot
real, intent(in) :: toler
real :: tpivot
integer :: i, j
integer, intent(in) :: k, l, m, n
integer, intent(inout) :: s
integer :: ia, ii, in
integer, intent(inout) :: iu
integer :: js, kk, nk, n1, n2, jmn, jpn, klm, nkl, nk1
integer, intent(in) :: n2d
integer :: iimn, iout
integer, intent(inout) :: iter
integer, intent(in) :: klmd
integer :: klm1, klm2
integer, intent(inout) :: kode
integer :: nklm, nkl1
integer, intent(in) :: klm2d
integer :: maxit
integer, intent(in) :: nklmd
integer :: iphase, kforce, iineg
dimension q(klm2d,n2d), x(n2d), res(klmd), &
&cu(2,nklmd), iu(2,nklmd), s(klmd)
!
! Initialization.
!
maxit = iter
n1 = n + 1
n2 = n + 2
nk = n + k
nk1 = nk + 1
nkl = nk + l
nkl1 = nkl + 1
klm = k + l + m
klm1 = klm + 1
klm2 = klm + 2
nklm = n + klm
kforce = 1
iter = 0
js = 1
ia = 0
! Set up labels in q.
do j=1,n
   q(klm2,j) = j
end do
do 30 i = 1,klm
   q(i,n2) = n + i
   if (q(i,n1).ge.0.) go to 30
   do j=1,n2
      q(i,j) = -q(i,j)
   end do
30 continue
! Set up phase 1 costs.
iphase = 2
do j=1,nklm
   cu(1,j) = 0.
   cu(2,j) = 0.
   iu(1,j) = 0
   iu(2,j) = 0
end do
if (l.eq.0) go to 60
do j=nk1,nkl
   cu(1,j) = 1.
   cu(2,j) = 1.
   iu(1,j) = 1
   iu(2,j) = 1
end do
iphase = 1
60 if (m.eq.0) go to 80
do j=nkl1,nklm
   cu(2,j) = 1.
   iu(2,j) = 1
   jmn = j - n
   if (q(jmn,n2).lt.0.) iphase = 1
end do
80 if (kode.eq.0) go to 150
do 110 j = 1,n
   if (x(j)) 90, 110, 100
90 cu(1,j) = 1.
   iu(1,j) = 1
   go to 110
100 cu(2,j) = 1.
   iu(2,j) = 1
110 continue
do 140 j = 1,k
   jpn = j + n
   if (res(j)) 120, 140, 130
120 cu(1,jpn) = 1.
   iu(1,jpn) = 1
   if (q(j,n2).gt.0.0) iphase = 1
   go to 140
130 cu(2,jpn) = 1.
   iu(2,jpn) = 1
   if (q(j,n2).lt.0.0) iphase = 1
140 continue
150 if (iphase.eq.2) go to 500
! Compute the marginal costs.
160 do j=js,n1
   sum = 0.d0
   do i=1,klm
      ii = q(i,n2)
      if (ii.lt.0) go to 170
      z = cu(1,ii)
      go to 180
170 iineg = -ii
      z = cu(2,iineg)
180 sum = sum + dble(q(i,j))*dble(z)
   end do
   q(klm1,j) = sum
end do
do j=js,n
   ii = q(klm2,j)
   if (ii.lt.0) go to 210
   z = cu(1,ii)
   go to 220
210 iineg = -ii
   z = cu(2,iineg)
220 q(klm1,j) = q(klm1,j) - z
end do
! Determine the vector to enter the basis.
240 xmax = 0.
if (js.gt.n) go to 490
do 280 j = js,n
   zu = q(klm1,j)
   ii = q(klm2,j)
   if (ii.gt.0) go to 250
   ii = -ii
   zv = zu
   zu = -zu - cu(1,ii) - cu(2,ii)
   go to 260
250 zv = -zu - cu(1,ii) - cu(2,ii)
260 if (kforce.eq.1 .and. ii.gt.n) go to 280
   if (iu(1,ii).eq.1) go to 270
   if (zu.le.xmax) go to 270
   xmax = zu
   in = j
270 if (iu(2,ii).eq.1) go to 280
   if (zv.le.xmax) go to 280
   xmax = zv
   in = j
280 continue
if (xmax.le.toler) go to 490
if (q(klm1,in).eq.xmax) go to 300
do i=1,klm2
   q(i,in) = -q(i,in)
end do
q(klm1,in) = xmax
! Determine the vector to leave the basis.
300 if (iphase.eq.1 .or. ia.eq.0) go to 330
xmax = 0.
do 310 i = 1,ia
   z = abs(q(i,in))
   if (z.le.xmax) go to 310
   xmax = z
   iout = i
310 continue
if (xmax.le.toler) go to 330
do j=1,n2
   z = q(ia,j)
   q(ia,j) = q(iout,j)
   q(iout,j) = z
end do
iout = ia
ia = ia - 1
pivot = q(iout,in)
go to 420
330 kk = 0
do 340 i = 1,klm
   z = q(i,in)
   if (z.le.toler) go to 340
   kk = kk + 1
   res(kk) = q(i,n1)/z
   s(kk) = i
340 continue
350 if (kk.gt.0) go to 360
kode = 2
go to 590
360 xmin = res(1)
iout = s(1)
j = 1
if (kk.eq.1) go to 380
do 370 i = 2,kk
   if (res(i).ge.xmin) go to 370
   j = i
   xmin = res(i)
   iout = s(i)
370 continue
res(j) = res(kk)
s(j) = s(kk)
380 kk = kk - 1
pivot = q(iout,in)
ii = q(iout,n2)
if (iphase.eq.1) go to 400
if (ii.lt.0) go to 390
if (iu(2,ii).eq.1) go to 420
go to 400
390 iineg = -ii
if (iu(1,iineg).eq.1) go to 420
400 ii = iabs(ii)
cuv = cu(1,ii) + cu(2,ii)
if (q(klm1,in)-pivot*cuv.le.toler) go to 420
! Bypass intermediate vertices.
do j=js,n1
   z = q(iout,j)
   q(klm1,j) = q(klm1,j) - z*cuv
   q(iout,j) = -z
end do
q(iout,n2) = -q(iout,n2)
go to 350
! Gauss-Jordan elimination.
420 if (iter.lt.maxit) go to 430
kode = 3
go to 590
430 iter = iter + 1
do j=js,n1
   if (j.ne.in) q(iout,j) = q(iout,j)/pivot
end do
! If permitted, use subroutine col of the description
! section and replace the following seven statements down
! to and including statement number 460 by..
!     do 460 j=js,n1
!        if(j .eq. in) go to 460
!        z = -q(iout,j)
!        call col(q(1,j), q(1,in), z, iout, klm1)
! 460 continue
do 460 j = js,n1
   if (j.eq.in) go to 460
   z = -q(iout,j)
   do i=1,klm1
      if (i.ne.iout) q(i,j) = q(i,j) + z*q(i,in)
   end do
460 continue
tpivot = -pivot
do i=1,klm1
   if (i.ne.iout) q(i,in) = q(i,in)/tpivot
end do
q(iout,in) = 1./pivot
z = q(iout,n2)
q(iout,n2) = q(klm2,in)
q(klm2,in) = z
ii = abs(z)
if (iu(1,ii).eq.0 .or. iu(2,ii).eq.0) go to 240
do i=1,klm2
   z = q(i,in)
   q(i,in) = q(i,js)
   q(i,js) = z
end do
js = js + 1
go to 240
! Test for optimality.
490 if (kforce.eq.0) go to 580
if (iphase.eq.1 .and. q(klm1,n1).le.toler) go to 500
kforce = 0
go to 240
! Set up phase 2 costs.
500 iphase = 2
do j=1,nklm
   cu(1,j) = 0.
   cu(2,j) = 0.
end do
do j=n1,nk
   cu(1,j) = 1.
   cu(2,j) = 1.
end do
do 560 i = 1,klm
   ii = q(i,n2)
   if (ii.gt.0) go to 530
   ii = -ii
   if (iu(2,ii).eq.0) go to 560
   cu(2,ii) = 0.
   go to 540
530 if (iu(1,ii).eq.0) go to 560
   cu(1,ii) = 0.
540 ia = ia + 1
   do j=1,n2
      z = q(ia,j)
      q(ia,j) = q(i,j)
      q(i,j) = z
   end do
560 continue
go to 160
570 if (q(klm1,n1).le.toler) go to 500
kode = 1
go to 590
580 if (iphase.eq.1) go to 570
! Prepare output.
kode = 0
590 sum = 0.d0
do j=1,n
   x(j) = 0.
end do
do i=1,klm
   res(i) = 0.
end do
do 640 i = 1,klm
   ii = q(i,n2)
   sn = 1.
   if (ii.gt.0) go to 620
   ii = -ii
   sn = -1.
620 if (ii.gt.n) go to 630
   x(ii) = sn*q(i,n1)
   go to 640
630 iimn = ii - n
   res(iimn) = sn*q(i,n1)
   if (ii.ge.n1 .and. ii.le.nk) sum = sum + &
&dble(q(i,n1))
640 continue
error = sum
return
end subroutine xl1

subroutine llsq(m,n,a,ka,b,kb,nb,wk,iwk,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(inout) :: iwk
integer, intent(in) :: ka, kb, m, n, nb
real, intent(inout) :: a(ka,n), b(kb,nb), wk(n)
integer :: i, j, np1
real :: rnorm
dimension iwk(n)
logical :: exit
!     --------------
ierr = 0
if (1 .lt. n .and. n .le. m) go to 10
ierr = 1
return
!
10 np1 = n + 1
call ortho(m,n,a,ka,wk,iwk,exit)
if (exit) go to 20
ierr = 2
return
!
20 do 22 j = 1,nb
call orsol(m,n,a,ka,wk,iwk,b(1,j))
if (m .eq. n) go to 22
rnorm = 0.0
do 21 i = np1,m
21 rnorm = rnorm + b(i,j)*b(i,j)
b(np1,j) = sqrt(rnorm)
22 continue
return
end subroutine llsq

subroutine llsqmp(m,n,a,ka,b,kb,nb,wk,iwk,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(inout) :: iwk
integer, intent(in) :: ka, kb, m, n, nb
real :: a(ka,n)
real, intent(inout) :: b(kb,nb), wk(*)
integer :: i, j, lq, lr, ls, np1
real :: rnorm
dimension iwk(n)
logical :: exit
!     -------------------
!     dimension wk(mn + 2m + n)
!     -------------------
ierr = 0
if (1.lt.n .and. n.le.m) go to 10
ierr = 2
return
!
10 np1 = n + 1
lr = m + 1
ls = lr + m
lq = ls + n
!
call mcopy(m, n, a, ka, wk(lq), m)
call ortho(m, n, wk(lq), m, wk(ls), iwk, exit)
if (exit) go to 20
ierr = 3
return
!
20 do 31 j = 1,nb
do 21 i = 1,m
21 wk(i) = b(i,j)
call orsol(m, n, wk(lq), m, wk(ls), iwk, wk(1))
call orimp(m, n, a, ka, wk(lq), m, wk(ls), iwk, b(1,j), &
&wk(1), wk(lr), exit)
do 22 i = 1,n
22 b(i,j) = wk(i)
if (.not.exit) ierr = 1
if (m .eq. n) go to 31
!
rnorm = 0.0
do 30 i = np1,m
30 rnorm = rnorm + wk(i)*wk(i)
b(np1,j) = sqrt(rnorm)
31 continue
return
end subroutine llsqmp

subroutine ortho(m, n, qr, ms, s, ip, exit)
implicit none
integer, intent(inout) :: ip
integer, intent(in) :: m, ms, n
real, intent(inout) :: qr(ms,n), s(n)
integer :: i, j, jp, k, kj, nn
real :: ajj, sav, ss, y
!***********************************************************************
!      Identification
!        ortho - orthogonal transformation of a given general m by n
!                matrix A to upper triangular form
!        Fortran subroutine subprogram
!        aerospace research laboratories
!        wright-patterson afb, ohio  45433
!      purpose
!        ortho computes an implicit orthogonal matrix Q and an explicit
!        upper triangular matrix R and a permutation matrix P satisfying
!        qr = PA GIVEN AN m BY n REAL MATRIX A.  ORTHO IS INTENDED FOR
!        use with the subroutine orsol to produce the least squares
!        SOLUTION OF THE EQUATION AX = B.
!      Control
!
!        dimension qr(ms,n), s(n), ip(n)
!        logical exit
!        .
!        .
!        .
!        call ortho(m, n, qr, ms, s, ip, exit)
!
!        Where
!        m    IS AN INTEGER INPUT VARIABLE, THE NUMBER OF ROWS OF A.
!        n    IS AN INTEGER INPUT VARIABLE, THE NUMBER OF COLUMNS OF A,
!             (1 .LT. n .LE. m).
!        QR   AS A REAL INPUT ARRAY IS MATRIX A TO BE TRIANGULARIZED.
!        QR   AS A REAL OUTPUT ARRAY IS THE UPPER TRIANGULAR FACTOR R IN
!             qr(i,j), i .LE. j, AND THE RELEVANT PARTS OF Q IN qr(i,j),
!             i .GT. j.
!        ms   IS AN INTEGER INPUT VARIABLE, THE LEADING DIMENSION OF
!             QR in the calling program.
!        s    IS A REAL OUTPUT ARRAY, THE RELEVANT PARTS OF Q.
!        ip   IS AN INTEGER OUTPUT ARRAY CONTAINING IN ip(i), i=1,...,n,
!             the images of the permutation corresponding to the PERMU-
!             TATION matrix P.
!        Exit is set to the value .True. If the rank of A is equal to n
!             and .False. Otherwise.
!      Method
!        the matrix A in the array qr is reduced to upper triangular
!        form using orthogonal transformation with partial pivoting.
!      References
!        (1) peter Businger and G.H. Golub, linear least squares SOLU-
!            TIONS by Householder transformations, numer. Math. 7(1965),
!            269-276.
!        (2) N.K. Tsao and P.J. nikolai, procedures using orthogonal
!            transformations for linear least squares problems, ARL
!            technical report ARL TR 74-0124(1974).
!***********************************************************************
dimension ip(n)
logical, intent(out) :: exit
!
exit = .true.
nn = n
if (n .eq. m) nn = n - 1
do 80 j = 1, nn
  ip(j) = j
  jp = j + 1
  kj = j
!                                       Search for pivot in the j-TH
!                                       column and interchange rows.
  do k = jp, m
     if (abs(qr(k,j)) .gt. abs(qr(kj,j))) kj = k
  end do
  if (qr(kj,j) .eq. 0.0) go to 90
  if (kj .eq. j) go to 30
  ip(j) = kj
  do 20 i = j, n
     sav = qr(j,i)
     qr(j,i) = qr(kj,i)
20 qr(kj,i) = sav
!                                       Normalize the pivoting column
!                                       and find its norm.
30 ajj = qr(j,j)
  do 31 i = jp, m
31 qr(i,j) = qr(i,j)/ajj
  sav = 1.0
  do 40 i = jp, m
40 sav = sav + qr(i,j)*qr(i,j)
  s(j) = -sqrt(sav)
  qr(j,j) = s(j)*ajj
  if (jp .gt. n) go to 80
!                                       Premultiply QR with the j-TH
!                                       orthogonal matrix.
  y = 1.0 - s(j)
  do k = jp, n
     sav = qr(j,k)
     do 50 i = jp, m
50 sav = sav + qr(i,j)*qr(i,k)
     ss = qr(j,k)
     qr(j,k) = sav/s(j)
     ss = (ss - qr(j,k))/y
     do 60 i = jp, m
60 qr(i,k) = qr(i,k) - qr(i,j)*ss
  end do
80 continue
return
!
90 exit = .false.
return
end subroutine ortho

subroutine orsol(m, n, qr, ms, s, ip, x)
implicit none
integer :: ip
integer, intent(in) :: m, ms, n
real :: qr(ms,n), s(n)
real, intent(inout) :: x(m)
integer :: i, ij, j, jp, k, ni, nm, nn
real :: sav, ss, y
!***********************************************************************
!      Identification
!        orsol - least squares solution of a linear system given an
!                orthogonal-triangular factorization of the coefficient
!                matrix produced by subroutine ortho
!        Fortran subroutine subprogram
!        aerospace research laboratories
!        wright-patterson afb, ohio  45433
!      purpose
!        orsol computes the least squares solution of the linear system
!        QRX = PAX = B WHERE Q, R, AND P ARE DETERMINED FROM A BY ORTHO.
!      Control
!
!        dimension qr(ms,n), s(n), ip(n), x(m)
!        .
!        .
!        .
!        call orsol(m, n, qr, ms, s, ip, x)
!
!        Where
!        m  is an integer input variable, the number of rows of A.
!        n  is an integer input variable, the number of columns of A
!             (1 .LT. n .LE. m).
!        QR is a real input array, the orthogonal and triangular factors
!           of a produced by ortho.
!        ms is an integer input variable, the leading dimension of
!           QR in the calling program.
!        s  is a real input array, the relevant parts of Q produced by
!           ortho.
!        ip is an integer input array, the permutation information
!           produced by ortho.
!        x  AS A REAL INPUT ARRAY IS THE RIGHT-HAND SIDE B OF AX = B.
!        x  AS A REAL OUTPUT ARRAY IS x(i), i = 1, ..., n, THE LEAST
!           SQUARES SOLUTION, AND x(j), j = n+1, ..., m, THE VECTOR
!           whose length is the minimum of all residual B - AX.
!      Method
!        THE FACTORED SYSTEM QRX = PAX = PB ARE SOLVED IN THE SEQUENCE
!        OF QY = PB AND RX = y. FULL RANK FOR THE MATRIX A IS ASSUMED
!        which can be checked by interrogating the logical output
!        variable produced by ortho.
!      References
!        (1) peter Businger and G.H. Golub, linear least squares SOLU-
!            TIONS by Householder transformations, numer. Math. 7(1965),
!            269-276.
!        (2) N.K. Tsao and P.J. nikolai, procedures using orthogonal
!            transformations for linear least squares problems, ARL
!            technical report ARL TR 74-0124(1974).
!***********************************************************************
dimension ip(n)
!
nn = n
if (n .eq. m) nn = n - 1
do j = 1, nn
  jp = j + 1
  ij = ip(j)
  y = 1.0 - s(j)
  sav = x(j)
  x(j) = x(ij)
  x(ij) = sav
!                                       Premultiply x with the j-TH
!                                       orthogonal matrix.
  sav = x(j)
  do 10 k = jp, m
10 sav = sav + qr(k,j)*x(k)
  ss = x(j)
  x(j) = sav/s(j)
  ss = (ss - x(j))/y
  do 20 k = jp, m
20 x(k) = x(k) - qr(k,j)*ss
end do
!                                       Back substitute to find the
!                                       least squares solution.
x(n) = x(n)/qr(n,n)
nm = n - 1
do i = 1, nm
  ni = n - i
  nn = n
  do 40 j = 1, i
    x(ni) = x(ni) - qr(ni,nn)*x(nn)
40 nn = nn - 1
  x(ni) = x(ni)/qr(ni,ni)
end do
return
end subroutine orsol

subroutine orimp(m, n, a, ka, qr, ms, s, ip, b, x, r, exit)
implicit none
integer :: ip
integer, intent(in) :: ka, m, ms, n
real :: a(ka,n), b(m), qr(ms,n)
real, intent(inout) :: r(m)
real :: s(n)
real, intent(inout) :: x(m)
integer :: i, j, k, np1
real :: eps, eps2, four, fourth, one, rat, ratio, rnrm2, xnrm2, &
&zero
real :: spmpar
! ----------------------------------------------------------------------
!      Purpose
!        given an approximate least squares solution x of a linear
!        SYSTEM AX = b OBTAINED USING orsol. orimp ATTEMPTS TO COMPUTE
!        an improved solution correct to machine precision.
!
!      Control
!
!        dimension a(ka,n), qr(ms,n), b(m), x(m), r(m), s(n), ip(n)
!        logical exit
!        .
!        .
!        .
!        call orimp(m, n, a, ka, qr, ms, s, ip, b, x, r, exit)
!
!        Where
!        m    IS AN INTEGER INPUT VARIABLE, THE NUMBER OF ROWS OF A.
!        n    IS AN INTEGER INPUT VARIABLE, THE NUMBER OF COLUMNS OF A
!             (1 .LT. n .LE. m).
!        A    IS A REAL INPUT ARRAY, THE GIVEN m BY n MATRIX.
!        QR   IS A REAL INPUT ARRAY, THE ORTHOGONAL AND TRIANGULAR
!             factors of a produced by ortho.
!        b    IS A REAL INPUT ARRAY, THE RIGHT HAND SIDE OF AX = b.
!        x    AS A REAL INPUT ARRAY IS THE APPROXIMATE LEAST SQUARES
!             solution together with the residual information produced
!             BY orsol.
!        x    AS A REAL OUTPUT ARRAY IS THE IMPROVED LEAST SQUARES
!             solution with a residual of minimum length.
!        r    IS A REAL OUTPUT ARRAY, THE CORRECTION VECTOR ADDED TO x.
!        ka   IS AN INTEGER INPUT VARIABLE, THE LEADING DIMENSION OF
!             of A in the calling program.
!        ms   IS AN INTEGER INPUT VARIABLE, THE LEADING DIMENSION OF
!             of QR in the calling program.
!        s    IS A REAL INPUT ARRAY, A RELEVANT PART OF Q PRODUCED BY
!             ortho.
!        ip   IS AN INTEGER INPUT ARRAY, THE PERMUTATION INFORMATION
!             produced by ortho.
!        Exit is set to the value .True. If improvement of x is success-
!             ful with a gain in accuracy of at least 50 per cent each
!             iteration and .False. Otherwise.
!
!      Method
!        orimp executes the iteration cycle
!              (1)  AR = b - AX
!              (2)  x = x + r
!        with a given initial x.  the residual vector b - AX is computed
!        to high accuracy by double precision.  orsol is then used to
!        solve (1).
!
! ----------------------------------------------------------------------
!
dimension ip(n)
logical, intent(out) :: exit
double precision :: dsum
data zero/0.0/, one/1.0/, four/4.0/, fourth/0.25/
!
!     ********** eps IS A MACHINE DEPENDENT PARAMETER. ASSIGN EPS
!                the value U where U is the smallest positive floating
!                POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0.
!
eps = spmpar(1)
!
exit = .true.
np1 = n + 1
eps2 = eps*eps
!
xnrm2 = zero
do 10 i = 1,n
10 xnrm2 = xnrm2 + x(i)*x(i)
if (xnrm2 .eq. zero) return
ratio = one
!
!                                       Find the residual vector.
!
20 do 22 k = 1,m
dsum = b(k)
do 21 j = 1,n
21 dsum = dsum - dble(a(k,j))*dble(x(j))
22 r(k) = dsum
!
!                                       Find the correction vector.
!
call orsol(m, n, qr, ms, s, ip, r)
rnrm2 = zero
do 30 k = 1,n
30 rnrm2 = rnrm2 + r(k)*r(k)
if (rnrm2 .le. eps2*xnrm2) return
!
!                                       Form new approximate solution.
!
do 40 k = 1,n
40 x(k) = x(k) + r(k)
xnrm2 = zero
do 41 k = 1,n
41 xnrm2 = xnrm2 + x(k)*x(k)
if (m .eq. n) go to 50
do 42 k = np1,m
42 x(k) = r(k)
!
50 if (xnrm2 .eq. zero) return
rat = ratio
ratio = rnrm2/xnrm2
if (ratio .le. fourth*rat) go to 20
!
if (ratio .le. amin1(rat,four*eps2)) return
exit = .false.
return
end subroutine orimp

subroutine dllsq(m,n,a,ka,b,kb,nb,wk,iwk,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ka, kb, m, n, nb
integer :: i, j, np1
double precision, intent(inout) :: a(ka,n), b(kb,nb), wk(n)
integer, intent(inout) :: iwk(n)
double precision :: rnorm
logical :: exit
!     --------------
ierr = 0
if (1 .lt. n .and. n .le. m) go to 10
ierr = 1
return
!
10 np1 = n + 1
call dortho(m,n,a,ka,wk,iwk,exit)
if (exit) go to 20
ierr = 2
return
!
20 do 22 j = 1,nb
call dorsol(m,n,a,ka,wk,iwk,b(1,j))
if (m .eq. n) go to 22
rnorm = 0.d0
   do 21 i = np1,m
21 rnorm = rnorm + b(i,j)*b(i,j)
b(np1,j) = dsqrt(rnorm)
22 continue
return
end subroutine dllsq

subroutine dortho(m, n, qr, ms, s, ip, exit)
implicit none
integer, intent(in) :: m, ms, n
integer :: i, j, jp, k, kj, nn
!***********************************************************************
!      Identification
!        dortho - orthogonal transformation of a given general m by n
!                matrix A to upper triangular form
!        Fortran subroutine subprogram
!        aerospace research laboratories
!        wright-patterson afb, ohio  45433
!      purpose
!        dortho computes an implicit orthogonal matrix Q and an explicit
!        upper triangular matrix R and a permutation matrix P satisfying
!        qr = PA GIVEN AN m BY n REAL MATRIX A.  dortho IS INTENDED FOR
!        use with the subroutine dorsol to produce the least squares
!        SOLUTION OF THE EQUATION AX = B.
!      Control
!
!        dimension qr(ms,n), s(n), ip(n)
!        logical exit
!        .
!        .
!        .
!        call dortho(m, n, qr, ms, s, ip, exit)
!
!        Where
!        m    IS AN INTEGER INPUT VARIABLE, THE NUMBER OF ROWS OF A.
!        n    IS AN INTEGER INPUT VARIABLE, THE NUMBER OF COLUMNS OF A,
!             (1 .LT. n .LE. m).
!        QR   AS A REAL INPUT ARRAY IS MATRIX A TO BE TRIANGULARIZED.
!        QR   AS A REAL OUTPUT ARRAY IS THE UPPER TRIANGULAR FACTOR R IN
!             qr(i,j), i .LE. j, AND THE RELEVANT PARTS OF Q IN qr(i,j),
!             i .GT. j.
!        ms   IS AN INTEGER INPUT VARIABLE, THE LEADING DIMENSION OF
!             QR in the calling program.
!        s    IS A REAL OUTPUT ARRAY, THE RELEVANT PARTS OF Q.
!        ip   IS AN INTEGER OUTPUT ARRAY CONTAINING IN ip(i), i=1,...,n,
!             the images of the permutation corresponding to the PERMU-
!             TATION matrix P.
!        Exit is set to the value .True. If the rank of A is equal to n
!             and .False. Otherwise.
!      Method
!        the matrix A in the array qr is reduced to upper triangular
!        form using orthogonal transformation with partial pivoting.
!      References
!        (1) peter Businger and G.H. Golub, linear least squares SOLU-
!            TIONS by Householder transformations, numer. Math. 7(1965),
!            269-276.
!        (2) N.K. Tsao and P.J. nikolai, procedures using orthogonal
!            transformations for linear least squares problems, ARL
!            technical report ARL TR 74-0124(1974).
!***********************************************************************
double precision, intent(inout) :: qr(ms,n), s(n)
integer, intent(inout) :: ip(n)
double precision :: ajj, sav, ss, y
logical, intent(out) :: exit
!
exit = .true.
nn = n
if (n .eq. m) nn = n - 1
do 80 j = 1, nn
  ip(j) = j
  jp = j + 1
  kj = j
!                                       Search for pivot in the j-TH
!                                       column and interchange rows.
  do k = jp, m
     if (dabs(qr(k,j)) .gt. dabs(qr(kj,j))) kj = k
  end do
  if (qr(kj,j) .eq. 0.d0) go to 90
  if (kj .eq. j) go to 30
  ip(j) = kj
  do 20 i = j, n
     sav = qr(j,i)
     qr(j,i) = qr(kj,i)
20 qr(kj,i) = sav
!                                       Normalize the pivoting column
!                                       and find its norm.
30 ajj = qr(j,j)
  do 31 i = jp, m
31 qr(i,j) = qr(i,j)/ajj
  sav = 1.d0
  do 40 i = jp, m
40 sav = sav + qr(i,j)*qr(i,j)
  s(j) = -dsqrt(sav)
  qr(j,j) = s(j)*ajj
  if (jp .gt. n) go to 80
!                                       Premultiply QR with the j-TH
!                                       orthogonal matrix.
  y = 1.d0 - s(j)
  do k = jp, n
     sav = qr(j,k)
     do 50 i = jp, m
50 sav = sav + qr(i,j)*qr(i,k)
     ss = qr(j,k)
     qr(j,k) = sav/s(j)
     ss = (ss - qr(j,k))/y
     do 60 i = jp, m
60 qr(i,k) = qr(i,k) - qr(i,j)*ss
  end do
80 continue
return
!
90 exit = .false.
return
end subroutine dortho

subroutine dorsol(m, n, qr, ms, s, ip, x)
implicit none
integer, intent(in) :: m, ms, n
integer :: i, ij, j, jp, k, ni, nm, nn
!***********************************************************************
!      Identification
!        dorsol - least squares solution of a linear system given an
!                orthogonal-triangular factorization of the coefficient
!                matrix produced by subroutine dortho
!        Fortran subroutine subprogram
!        aerospace research laboratories
!        wright-patterson afb, ohio  45433
!      purpose
!        dorsol computes the least squares solution of the linear system
!        QRX = PAX = B WHERE Q, R, AND P ARE DETERMINED FROM A BY dortho
!      control
!
!        dimension qr(ms,n), s(n), ip(n), x(m)
!        .
!        .
!        .
!        call dorsol(m, n, qr, ms, s, ip, x)
!
!        Where
!        m  is an integer input variable, the number of rows of A.
!        n  is an integer input variable, the number of columns of A
!             (1 .LT. n .LE. m).
!        QR is a real input array, the orthogonal and triangular factors
!           of a produced by dortho.
!        ms is an integer input variable, the leading dimension of
!           QR in the calling program.
!        s  is a real input array, the relevant parts of Q produced by
!           dortho.
!        ip is an integer input array, the permutation information
!           produced by dortho.
!        x  AS A REAL INPUT ARRAY IS THE RIGHT-HAND SIDE B OF AX = B.
!        x  AS A REAL OUTPUT ARRAY IS x(i), i = 1, ..., n, THE LEAST
!           SQUARES SOLUTION, AND x(j), j = n+1, ..., m, THE VECTOR
!           whose length is the minimum of all residual B - AX.
!      Method
!        THE FACTORED SYSTEM QRX = PAX = PB ARE SOLVED IN THE SEQUENCE
!        OF QY = PB AND RX = y. FULL RANK FOR THE MATRIX A IS ASSUMED
!        which can be checked by interrogating the logical output
!        variable produced by dortho.
!      References
!        (1) peter Businger and G.H. Golub, linear least squares SOLU-
!            TIONS by Householder transformations, numer. Math. 7(1965),
!            269-276.
!        (2) N.K. Tsao and P.J. nikolai, procedures using orthogonal
!            transformations for linear least squares problems, ARL
!            technical report ARL TR 74-0124(1974).
!***********************************************************************
double precision, intent(in) :: qr(ms,n), s(n)
double precision, intent(inout) :: x(m)
integer, intent(in) :: ip(n)
double precision :: sav, ss, y
!
nn = n
if(n .eq. m) nn = n - 1
do j = 1, nn
  jp = j + 1
  ij = ip(j)
  y = 1.d0 - s(j)
  sav = x(j)
  x(j) = x(ij)
  x(ij) = sav
!                                       Premultiply x with the j-TH
!                                       orthogonal matrix.
  sav = x(j)
  do 10 k = jp, m
10 sav = sav + qr(k,j)*x(k)
  ss = x(j)
  x(j) = sav/s(j)
  ss = (ss - x(j))/y
  do 20 k = jp, m
20 x(k) = x(k) - qr(k,j)*ss
end do
!                                       Back substitute to find the
!                                       least squares solution.
x(n) = x(n)/qr(n,n)
nm = n - 1
do i = 1, nm
  ni = n - i
  nn = n
  do 40 j = 1, i
    x(ni) = x(ni) - qr(ni,nn)*x(nn)
40 nn = nn - 1
  x(ni) = x(ni)/qr(ni,ni)
end do
return
end subroutine dorsol

subroutine lsqr (ind, a, mda, m, n, b, mdb, nb, re, ae, krank, &
&ksure, rnorm, work, lw, iwork, liw, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ind
integer, intent(inout) :: krank, ksure
integer, intent(in) :: liw, lw, m, mda, mdb, n, nb
real, intent(in) :: ae, re
integer :: i, imax, info, m0, m1, m2, m3, m4, m5, mode, n0, np
real :: eps, rerr
real :: spmpar
!-----------------------------------------------------------------------
!
!              Least squares solution of linear equations
!
!                            --------------
!
!     lsqr solves both underdetermined and overdetermined linear
!     SYSTEMS AX = b, WHERE A IS AN m BY n MATRIX AND b IS AN m BY
!     nb MATRIX OF RIGHT HAND SIDES. IF m .GE. n, THE LEAST SQUARES
!     solution is computed by decomposing the matrix a into the
!     product of an orthogonal matrix Q and upper triangular matrix
!     R (QR FACTORIZATION). IF m .LT. n, THE MINIMAL LENGTH SOLUTION
!     is computed by factoring the matrix a into the product of a
!     lower triangular matrix L and orthogonal matrix Q (LQ factor-
!     ization). If the matrix a is determined to be rank deficient,
!     then the minimal length least squares solution is computed.
!
!     User input bounds on the uncertainty of the elements of A are
!     used to detect numerical rank deficiency. The algorithm uses
!     a row and column pivot strategy to minimize the growth of
!     uncertainty and round-off errors.
!
!   ******************************************************************
!   *                                                                *
!   *         WARNING - ALL INPUT ARRAYS ARE CHANGED ON EXIT.        *
!   *                                                                *
!   ******************************************************************
!
!     Input..
!
!     IND           INTEGER WHICH INDICATES IF THE ROUTINE IS BEING
!                   called for the first time.
!                      ind = 0      ORIGINAL CALL
!                      ind .NE. 0   SUBSEQUENT CALLS
!                   on subsequent calls a new set b of equations can
!                   be solved (using the same coefficient matrix a).
!                   It is assumed that A, mda, m, n, krank, iwork,
!                   liw, and the first 2*min(m,n) locations of work
!                   have not been modified by the user. re, ae, and
!                   ksure are not used.
!
!     a(,)          LINEAR COEFFICIENT MATRIX OF AX=b, WITH mda THE
!      mda,m,n      ACTUAL FIRST DIMENSION OF A IN THE CALLING PROGRAM.
!                   m is the row dimension (no. of equations of the
!                   problem) and n the col dimension (no. of unknowns).
!                   MUST HAVE mda .GE. m.
!
!     b(,)          RIGHT HAND SIDE(S), WITH MDB THE ACTUAL FIRST
!      MDB,nb       DIMENSION OF b IN THE CALLING PROGRAM. nb IS THE
!                   number of m by 1 right hand sides. Must have
!                   mdb .GE. max(m,n). IF nb .LE. 0 THEN b AND MDB
!                   are ignored.
!
!     re            re IS THE MAXIMUM RELATIVE UNCERTAINTY OF THE
!                   ELEMENTS OF THE MATRIX a (0 .le. re .LT. 1).
!
!     ae            ae IS THE MAXIMUM ABSOLUTE UNCERTAINTY OF THE
!                   ELEMENTS OF THE MATRIX a (ae .GE. 0).
!
!     work()        A REAL WORK ARRAY DIMENSIONED 5*min(m,n).
!
!     lw            ACTUAL DIMENSION OF WORK
!
!     iwork()       INTEGER WORK ARRAY DIMENSIONED AT LEAST n+m.
!
!     liw           ACTUAL DIMENSION OF iwork.
!
!     Output..
!
!     a(,)          CONTAINS THE TRIANGULAR PART OF THE REDUCED MATRIX
!                   and the transformation information. A and the first
!                   2*min(m,n) elements of work (see below) completely
!                   specify the factorization of the matrix a.
!
!     b(,)          CONTAINS THE n BY nb SOLUTION MATRIX FOR X.
!
!     krank,ksure   THE NUMERICAL RANK OF A,  BASED UPON THE RELATIVE
!                   and absolute bounds on uncertainty, is bounded
!                   above by krank and below by ksure. The algorithm
!                   returns a solution based on krank. ksure provides
!                   an indication of the precision of the rank.
!
!     rnorm()       CONTAINS THE EUCLIDEAN LENGTH OF THE nb RESIDUAL
!                   VECTORS  b(i) - AX(i), i=1,...,nb.
!
!     work()        THE FIRST 2*min(m,n) LOCATIONS OF WORK CONTAIN
!                   the values necessary to reproduce the Householder
!                   factorization of A.
!
!     iwork()       AN ARRAY OF LENGTH m + n CONTAINING THE ORDERS IN
!                   WHICH THE ROWS AND COLUMNS WERE USED. IF m .GE. n
!                   then the first n locations contain the order of
!                   the columns and the next m locations the order of
!                   THE ROWS. IF m .LT. n THEN THE ORDER OF THE ROWS
!                   precedes the order of the columns.
!
!     ierr          FLAG TO INDICATE THE STATUS OF THE RESULTS
!                     0     - SATISFACTORY COMPLETION
!                   .GT. 0  - INPUT ERROR
!
!----------------
!     The subroutines u11ls, u12ls, u11us, and u12us were written by
!     T. Manteuffel (LANL) in 1981. The driver routine lsqr was written
!     by A.H. Morris (NSWC) in 1991.
!----------------
!     Reference.  Manteuffel, T., An interval analysis approach to rank
!                 determination in linear least squares problems,
!                 Sandia Laboratories report SAND80-0655, June, 1980.
!-----------------------------------------------------------------------
real, intent(inout) :: a(mda,n), b(mdb,*), rnorm(*), work(lw)
integer, intent(inout) :: iwork(liw)
!----------------
!     np            IF m .GE. n THEN THE FIRST np COLUMNS OF A
!                   are never interchanged.
!                   IF m .LT. n THEN THE FIRST np ROWS OF A ARE
!                   never interchanged. np is not referenced on
!                   a continuation call to the routine.
!
!     MODE          THE INTEGER MODE INDICATES HOW THE ROUTINE
!                   is to react if rank deficiency is detected.
!                   IF mode = 0 RETURN IMMEDIATELY, NO SOLUTION
!                             1 compute truncated solution
!                             2 compute minimal length solution
!                   mode must not be modified on a continuation
!                   CALL TO THE ROUTINE. IF MODE LT. 2, ONLY THE
!                   first n locations of work are used.
!----------------
np = 0
mode = 2
!
!     Check the input
!
if (nb .le. 0 .and. ind .ne. 0) go to 200
if (m .lt. 1 .or. n .lt. 1) go to 210
if (mda .lt. m) go to 220
if (liw .lt. m + n) go to 240
!
m0 = min0(m,n)
n0 = max0(m,n)
!     num = 0
!
if (nb .le. 0) go to 10
if (mdb .lt. n0) go to 230
if (ind .ne. 0) go to 100
!
10 if (lw .lt. 5*m0) go to 250
if (re .lt. 0.0 .or. ae .lt. 0.0) go to 260
!
!     Define the relative and absolute tolerance lists
!
m1 = 1
m2 = m1 + m0
m3 = m2 + m0
m4 = m3 + m0
m5 = m4 + m0
!
eps = 10.0*spmpar(1)
rerr = amax1(eps,re)
!
imax = m5 - 1
do i = m4,imax
   work(i) = rerr
end do
imax = imax + m0
do i = m5,imax
   work(i) = ae
end do
!
!     Factor the matrix a
!
!     num = np
if (m .lt. n) go to 40
!
   call u11ls (a,mda,m,n,work(m4),work(m5),mode,np,krank,ksure, &
&work(m1),work(m2),work(m3),iwork(m1),iwork(m2))
   go to 100
!
40 call u11us (a,mda,m,n,work(m4),work(m5),mode,np,krank,ksure, &
&work(m1),work(m2),work(m3),iwork(m1),iwork(m2))
!
!     Solution phase
!
100 ierr = 0
info = 0
if (krank .eq. m0) go to 110
if (krank .eq. 0) go to 110
!     if (krank .lt. num) go to 280
!     if (mode .eq. 0) return
info = mode
!
110 if (nb .le. 0) return
!
m1 = 1
m2 = 1 + m0
if (info .eq. 2) go to 130
!
!     Only min(m,n) elements of work are needed
!
if (lw .lt. m0) go to 250
if (m .lt. n) go to 120
!
   call u12ls (a,mda,m,n,b,mdb,nb,mode,krank,rnorm, &
&work(m1),work(m1),iwork(m1),iwork(m2))
   return
!
120 call u12us (a,mda,m,n,b,mdb,nb,mode,krank,rnorm, &
&work(m1),work(m1),iwork(m1),iwork(m2))
return
!
!     Here 2*min(m,n) elements of work are needed
!
130 if (lw .lt. 2*m0) go to 250
if (m .lt. n) go to 140
!
   call u12ls (a,mda,m,n,b,mdb,nb,mode,krank,rnorm, &
&work(m1),work(m2),iwork(m1),iwork(m2))
   return
!
140 call u12us (a,mda,m,n,b,mdb,nb,mode,krank,rnorm, &
&work(m1),work(m2),iwork(m1),iwork(m2))
return
!
!     Error return
!
!                             nb .LE. 0  ON A CONTINUATION CALL
200 ierr = 7
return
!                             m .LT. 1 OR n .LT. 1
210 ierr = 1
return
!                             mda .LT. m
220 ierr = 2
return
!                             mdb .LT. max(m,n)
230 ierr = 3
return
!                             liw .LT. m + n
240 ierr = 4
return
!                             lw too small
250 ierr = 5
return
!                             re or ae is negative
260 ierr = 6
return
!                             0 .LT. krank .LT. np
! 280 ierr = 8
!     return
end subroutine lsqr

subroutine u11ls (a,mda,m,n,ub,db,mode,np,krank,ksure,h,w,eb, &
&ic,ir)
implicit none
integer, intent(out) :: krank
integer, intent(inout) :: ksure
integer, intent(in) :: m, mda, mode, n, np
real, intent(inout) :: a(mda,n), db(n), eb(n), h(n), ub(n), w(n)
integer :: i, ii, im1, imin, is, j, jm1, jmax, jp1, kk, km1, kmi, &
&kp1, kz, l, lm1, mm, nmk
real :: bb, r2, rmin, sum, t, temp, tn, tt
real :: snrm2
real :: sdot
integer :: isamax
!
!       This routine performs A QR factorization of A
!       using Householder transformations. Row and
!       column pivots are chosen to reduce the growth
!       of round-off and to help detect possible rank
!       deficiency.
!
integer, intent(inout) :: ic(n), ir(m)
!
!        Initialization
!
j = 0
krank = n
do i = 1,n
   ic(i) = i
end do
do i = 1,m
   ir(i) = i
end do
!
!        Determine rel and abs error vectors
!
!
!        Calculate col length
!
do i = 1,n
   h(i) = snrm2(m,a(1,i),1)
   w(i) = h(i)
end do
!
!         Initialize error bounds
!
do i = 1,n
   eb(i) = amax1(db(i),ub(i)*h(i))
   ub(i) = eb(i)
   db(i) = 0.0
end do
!
!          Discard self dependent columns
!
i = 1
50 if (eb(i) .ge. h(i)) go to 60
if (i .eq. krank) go to 70
i = i + 1
go to 50
!
!          Matrix reduction
!
60 kk = krank
krank = krank - 1
if (mode .eq. 0) return
if (i .le. np) go to 400
if (i .gt. krank) go to 70
call sswap (1,eb(i),1,eb(kk),1)
call sswap (1,ub(i),1,ub(kk),1)
call sswap (1,w(i),1,w(kk),1)
call sswap (1,h(i),1,h(kk),1)
call iswap (1,ic(i),1,ic(kk),1)
call sswap (m,a(1,i),1,a(1,kk),1)
go to 50
!
!           Test for zero rank
!
70 if (krank .gt. 0) go to 100
krank = 0
ksure = 0
return
!
!        m A i n    L O O P
!
100 j = j + 1
jp1 = j + 1
jm1 = j - 1
kz = krank
if (j .le. np) kz = j
!
!        EACH COL HAS MM=m-j+1 COMPONENTS
!
mm = m - j + 1
!
!         ub determines column pivot
!
110 imin = j
if (h(j) .eq. 0.0) go to 170
rmin = ub(j)/h(j)
do 120 i = j,kz
   if (ub(i) .ge. h(i)*rmin) go to 120
   rmin = ub(i)/h(i)
   imin = i
120 continue
!
!     Test for rank deficiency
!
if (rmin .lt. 1.0) go to 200
tt = (eb(imin) + abs(db(imin)))/h(imin)
if (tt .ge. 1.0) go to 170
!
!     Compute exact ub
!
do i = 1,jm1
   w(i) = a(i,imin)
end do
!
l = jm1
130 w(l) = w(l)/a(l,l)
if (l .eq. 1) go to 150
lm1 = l - 1
do i = l,jm1
   w(lm1) = w(lm1) - a(lm1,i)*w(i)
end do
l = lm1
go to 130
!
150 tt = eb(imin)
do i = 1,jm1
   tt = tt + abs(w(i))*eb(i)
end do
ub(imin) = tt
if (ub(imin)/h(imin) .ge. 1.0) go to 170
go to 200
!
!        Matrix reduction
!
170 kk = krank
krank = krank - 1
kz = krank
if (mode .eq. 0) return
if (j .le. np) go to 410
if (imin .gt. krank) go to 180
   call iswap (1,ic(imin),1,ic(kk),1)
   call sswap (m,a(1,imin),1,a(1,kk),1)
   call sswap (1,eb(imin),1,eb(kk),1)
   call sswap (1,ub(imin),1,ub(kk),1)
   call sswap (1,db(imin),1,db(kk),1)
   call sswap (1,w(imin),1,w(kk),1)
   call sswap (1,h(imin),1,h(kk),1)
180 if (j .gt. krank) go to 300
go to 110
!
!        Column pivot
!
200 if (imin .eq. j) go to 210
call sswap (1,h(j),1,h(imin),1)
call sswap (m,a(1,j),1,a(1,imin),1)
call sswap (1,eb(j),1,eb(imin),1)
call sswap (1,ub(j),1,ub(imin),1)
call sswap (1,db(j),1,db(imin),1)
call sswap (1,w(j),1,w(imin),1)
call iswap (1,ic(j),1,ic(imin),1)
!
!        Row pivot
!
210 jmax = isamax(mm,a(j,j),1)
jmax = jmax + j - 1
if (jmax .eq. j) go to 220
call sswap (n,a(j,1),mda,a(jmax,1),mda)
call iswap (1,ir(j),1,ir(jmax),1)
!
!     Apply Householder transformation
!
220 tn = snrm2(mm,a(j,j),1)
if (tn .eq. 0.0) go to 170
if (a(j,j) .ne. 0.0) tn = sign(tn,a(j,j))
call sscal (mm,1.0/tn,a(j,j),1)
a(j,j) = a(j,j) + 1.0
if (j .eq. n) go to 250
do 240 i = jp1,n
   bb = -sdot(mm,a(j,j),1,a(j,i),1)/a(j,j)
   call saxpy (mm,bb,a(j,j),1,a(j,i),1)
   if (i .le. np) go to 240
   if (h(i) .eq. 0.0) go to 240
   tt = 1.0 - (a(j,i)/h(i))**2
   tt = amax1(tt,0.0)
   t = tt
   tt = 1.0 + 0.05*tt*(h(i)/w(i))**2
   if (tt .eq. 1.0) go to 230
      h(i) = h(i)*sqrt(t)
      go to 240
230 h(i) = snrm2(m-j,a(j+1,i),1)
   w(i) = h(i)
240 continue
!
250 h(j) = a(j,j)
a(j,j) = -tn
!
!          Update ub, db
!
ub(j) = ub(j)/abs(a(j,j))
db(j) = (sign(eb(j),db(j)) + db(j))/a(j,j)
if (j .eq. krank) go to 300
do i = jp1,krank
   ub(i) = ub(i) + abs(a(j,i))*ub(j)
   db(i) = db(i) - a(j,i)*db(j)
end do
go to 100
!
!        E n D    m A i n    L O O P
!
300 continue
!
!        Compute ksure
!
km1 = krank - 1
do i = 1,km1
   is = 0
   kmi = krank - i
   do 310 ii = 1,kmi
      if (ub(ii) .le. ub(ii + 1)) go to 310
      is = 1
      temp = ub(ii)
      ub(ii) = ub(ii + 1)
      ub(ii + 1) = temp
310 continue
   if (is .eq. 0) go to 320
end do
!
320 ksure = 0
sum = 0.0
do i = 1,krank
   r2 = ub(i)*ub(i)
   if (r2 + sum .ge. 1.0) go to 330
   sum = sum + r2
   ksure = ksure + 1
end do
!
!     IF SYSTEM IS OF REDUCED RANK AND mode = 2
!     complete the decomposition for shortest least squares solution
!
330 if (krank .eq. n .or. mode .lt. 2) return
nmk = n - krank
kp1 = krank + 1
i = krank
340 tn = snrm2(nmk,a(i,kp1),mda)/a(i,i)
   tn = a(i,i)*sqrt(1.0 + tn*tn)
   call sscal (nmk,1.0/tn,a(i,kp1),mda)
   w(i) = a(i,i)/tn + 1.0
   a(i,i) = -tn
   if (i .eq. 1) go to 350
   im1 = i - 1
   do ii = 1,im1
      tt = -sdot(nmk,a(ii,kp1),mda,a(i,kp1),mda)/w(i)
      tt = tt - a(ii,i)
      call saxpy (nmk,tt,a(i,kp1),mda,a(ii,kp1),mda)
      a(ii,i) = a(ii,i) + tt*w(i)
   end do
   i = i - 1
   go to 340
!
350 continue
return
!
!     First np columns are linearly dependent
!
400 krank = i - 1
return
410 krank = j - 1
return
end subroutine u11ls

subroutine u12ls (a,mda,m,n,b,mdb,nb,mode,krank,rnorm,h,w,ic,ir)
implicit none
integer, intent(in) :: krank, m, mda, mdb, mode, n, nb
real, intent(inout) :: a(mda,n), b(mdb,nb)
real :: h(n)
real, intent(inout) :: rnorm(nb)
real :: w(n)
integer :: i, ij, im1, j, jb, k, kp1, nmk
real :: bb, tt
real :: snrm2
real :: sdot
!
!        Given the Householder QR factorization of A, this
!        SUBROUTINE SOLVES THE SYSTEM AX=b. IF THE SYSTEM
!        is of reduced rank, this routine returns a solution
!        according to the selected mode.
!
!       NOTE - IF mode.NE.2, w IS NEVER ACCESSED.
!
integer, intent(inout) :: ic(n), ir(m)
!
k = krank
kp1 = k + 1
if (k .gt. 0) go to 30
!
!        rank=0
!
do jb = 1,nb
   rnorm(jb) = snrm2(m,b(1,jb),1)
end do
do jb = 1,nb
   do i = 1,n
      b(i,jb) = 0.0
   end do
end do
return
!
30 i = 0
!
!     Reorder b to reflect row interchanges
!
40 i = i + 1
   if (i .eq. m) go to 100
   j = ir(i)
   if (j .eq. i) go to 40
   if (j .lt. 0) go to 40
!
   ir(i) = -ir(i)
   do jb = 1,nb
      rnorm(jb) = b(i,jb)
   end do
!
   ij = i
60 do jb = 1,nb
         b(ij,jb) = b(j,jb)
      end do
      ij = j
      j = ir(ij)
      ir(ij) = -ir(ij)
   if (j .ne. i) go to 60
!
   do jb = 1,nb
      b(ij,jb) = rnorm(jb)
   end do
   go to 40
!
100 do i = 1,m
   ir(i) = iabs(ir(i))
end do
!
!     Apply Householder transformations to b
!
do j = 1,k
   tt = a(j,j)
   a(j,j) = h(j)
   do i = 1,nb
      bb = -sdot (m-j+1,a(j,j),1,b(j,i),1)/h(j)
      call saxpy (m-j+1,bb,a(j,j),1,b(j,i),1)
   end do
   a(j,j) = tt
end do
!
!        Find norms of residual VECTOR(S)..(before overwrite b)
!
do jb = 1,nb
   rnorm(jb) = snrm2(m-k,b(kp1,jb),1)
end do
!
!     Back solve upper triangular R
!
i = k
150 do jb = 1,nb
   b(i,jb) = b(i,jb)/a(i,i)
end do
if (i .eq. 1) go to 200
im1 = i - 1
do jb = 1,nb
   call saxpy (im1,-b(i,jb),a(1,i),1,b(1,jb),1)
end do
i = im1
go to 150
!
!     RANK LT n
!
!      Truncated solution
!
200 if (k .eq. n) go to 230
do jb = 1,nb
   do i = kp1,n
      b(i,jb) = 0.0
   end do
end do
if (mode .eq. 1) go to 230
!
!      Minimal length solution
!
nmk = n - k
do jb = 1,nb
   do i = 1,k
      tt = -sdot(nmk,a(i,kp1),mda,b(kp1,jb),1)/w(i)
      tt = tt - b(i,jb)
      call saxpy (nmk,tt,a(i,kp1),mda,b(kp1,jb),1)
      b(i,jb) = b(i,jb) + tt*w(i)
   end do
end do
!
!     Reorder b to reflect column interchanges
!
230 i = 0
!
240 i = i + 1
   if (i .eq. n) go to 260
   j = ic(i)
   if (j .eq. i) go to 240
   if (j .lt. 0) go to 240
!
   ic(i) = -ic(i)
250 call sswap (nb,b(j,1),mdb,b(i,1),mdb)
      ij = ic(j)
      ic(j) = -ic(j)
      j = ij
   if (j .ne. i) go to 250
   go to 240
!
260 do i = 1,n
   ic(i) = iabs(ic(i))
end do
return
end subroutine u12ls

subroutine u11us (a,mda,m,n,ub,db,mode,np,krank,ksure,h,w,eb, &
&ir,ic)
implicit none
integer, intent(out) :: krank
integer, intent(inout) :: ksure
integer, intent(in) :: m, mda, mode, n, np
real, intent(inout) :: a(mda,n), db(m), eb(m), h(m), ub(m), w(m)
integer :: i, ii, im1, imin, is, j, jm1, jmax, jp1, kk, km1, kmi, &
&kp1, kz, l, lm1, mmk, nn
real :: bb, r2, rmin, sum, t, temp, tn, tt
real :: snrm2
real :: sdot
integer :: isamax
!
!       This routine performs an LQ factorization of the
!       matrix a using Householder transformations. Row
!       and column pivots are chosen to reduce the growth
!       of round-off and to help detect possible rank
!       deficiency.
!
integer, intent(inout) :: ic(n), ir(m)
!
!        Initialization
!
j = 0
krank = m
do i = 1,n
   ic(i) = i
end do
do i = 1,m
   ir(i) = i
end do
!
!        Determine rel and abs error vectors
!
!
!        Calculate row length
!
do i = 1,m
   h(i) = snrm2(n,a(i,1),mda)
   w(i) = h(i)
end do
!
!         Initialize error bounds
!
do i = 1,m
   eb(i) = amax1(db(i),ub(i)*h(i))
   ub(i) = eb(i)
   db(i) = 0.0
end do
!
!          Discard self dependent rows
!
i = 1
50 if (eb(i) .ge. h(i)) go to 60
if (i .eq. krank) go to 70
i = i + 1
go to 50
!
!          Matrix reduction
!
60 kk = krank
krank = krank - 1
if (mode .eq. 0) return
if (i .le. np) go to 400
if (i .gt. krank) go to 70
call sswap (1,eb(i),1,eb(kk),1)
call sswap (1,ub(i),1,ub(kk),1)
call sswap (1,w(i),1,w(kk),1)
call sswap (1,h(i),1,h(kk),1)
call iswap (1,ir(i),1,ir(kk),1)
call sswap (n,a(i,1),mda,a(kk,1),mda)
go to 50
!
!           Test for zero rank
!
70 if (krank .gt. 0) go to 100
krank = 0
ksure = 0
return
!
!        m A i n    L O O P
!
100 j = j + 1
jp1 = j + 1
jm1 = j - 1
kz = krank
if (j .le. np) kz = j
!
!        EACH ROW HAS NN=n-j+1 COMPONENTS
!
nn = n - j + 1
!
!         ub determines row pivot
!
110 imin = j
if (h(j) .eq. 0.0) go to 170
rmin = ub(j)/h(j)
do 120 i = j,kz
   if (ub(i) .ge. h(i)*rmin) go to 120
   rmin = ub(i)/h(i)
   imin = i
120 continue
!
!     Test for rank deficiency
!
if (rmin .lt. 1.0) go to 200
tt = (eb(imin) + abs(db(imin)))/h(imin)
if (tt .ge. 1.0) go to 170
!
!     Compute exact ub
!
do i = 1,jm1
   w(i) = a(imin,i)
end do
!
l = jm1
130 w(l) = w(l)/a(l,l)
if (l .eq. 1) go to 150
lm1 = l - 1
do i = l,jm1
   w(lm1) = w(lm1) - a(i,lm1)*w(i)
end do
l = lm1
go to 130
!
150 tt = eb(imin)
do i = 1,jm1
   tt = tt + abs(w(i))*eb(i)
end do
ub(imin) = tt
if (ub(imin)/h(imin) .ge. 1.0) go to 170
go to 200
!
!        Matrix reduction
!
170 kk = krank
krank = krank - 1
kz = krank
if (mode .eq. 0) return
if (j .le. np) go to 410
if (imin .gt. krank) go to 180
   call iswap (1,ir(imin),1,ir(kk),1)
   call sswap (n,a(imin,1),mda,a(kk,1),mda)
   call sswap (1,eb(imin),1,eb(kk),1)
   call sswap (1,ub(imin),1,ub(kk),1)
   call sswap (1,db(imin),1,db(kk),1)
   call sswap (1,w(imin),1,w(kk),1)
   call sswap (1,h(imin),1,h(kk),1)
180 if (j .gt. krank) go to 300
go to 110
!
!        Row pivot
!
200 if (imin .eq. j) go to 210
call sswap (1,h(j),1,h(imin),1)
call sswap (n,a(j,1),mda,a(imin,1),mda)
call sswap (1,eb(j),1,eb(imin),1)
call sswap (1,ub(j),1,ub(imin),1)
call sswap (1,db(j),1,db(imin),1)
call sswap (1,w(j),1,w(imin),1)
call iswap (1,ir(j),1,ir(imin),1)
!
!        Column pivot
!
210 jmax = isamax(nn,a(j,j),mda)
jmax = jmax + j - 1
if (jmax .eq. j) go to 220
call sswap (m,a(1,j),1,a(1,jmax),1)
call iswap (1,ic(j),1,ic(jmax),1)
!
!     Apply Householder transformation
!
220 tn = snrm2(nn,a(j,j),mda)
if (tn .eq. 0.0) go to 170
if (a(j,j) .ne. 0.0) tn = sign(tn,a(j,j))
call sscal (nn,1.0/tn,a(j,j),mda)
a(j,j) = a(j,j) + 1.0
if (j .eq. m) go to 250
do 240 i = jp1,m
   bb = -sdot(nn,a(j,j),mda,a(i,j),mda)/a(j,j)
   call saxpy (nn,bb,a(j,j),mda,a(i,j),mda)
   if (i .le. np) go to 240
   if (h(i) .eq. 0.0) go to 240
   tt = 1.0 - (a(i,j)/h(i))**2
   tt = amax1(tt,0.0)
   t = tt
   tt = 1.0 + 0.05*tt*(h(i)/w(i))**2
   if (tt .eq. 1.0) go to 230
      h(i) = h(i)*sqrt(t)
      go to 240
230 h(i) = snrm2(n-j,a(i,j+1),mda)
   w(i) = h(i)
240 continue
!
250 h(j) = a(j,j)
a(j,j) = -tn
!
!          Update ub, db
!
ub(j) = ub(j)/abs(a(j,j))
db(j) = (sign(eb(j),db(j))+db(j))/a(j,j)
if (j .eq. krank) go to 300
do i = jp1,krank
   ub(i) = ub(i) + abs(a(i,j))*ub(j)
   db(i) = db(i) - a(i,j)*db(j)
end do
go to 100
!
!        E n D    m A i n    L O O P
!
300 continue
!
!        Compute ksure
!
km1 = krank - 1
do i = 1,km1
   is = 0
   kmi = krank - i
   do 310 ii = 1,kmi
      if (ub(ii) .le. ub(ii + 1)) go to 310
      is = 1
      temp = ub(ii)
      ub(ii) = ub(ii + 1)
      ub(ii + 1) = temp
310 continue
   if (is .eq. 0) go to 320
end do
!
320 ksure = 0
sum = 0.0
do i = 1,krank
   r2 = ub(i)*ub(i)
   if (r2 + sum .ge. 1.0) go to 330
   sum = sum + r2
   ksure = ksure + 1
end do
!
!     IF SYSTEM IS OF REDUCED RANK AND mode = 2
!     complete the decomposition for shortest least squares solution
!
330 if (krank .eq. m .or. mode .lt. 2) return
mmk = m - krank
kp1 = krank + 1
i = krank
340 tn = snrm2(mmk,a(kp1,i),1)/a(i,i)
   tn = a(i,i)*sqrt(1.0 + tn*tn)
   call sscal (mmk,1.0/tn,a(kp1,i),1)
   w(i) = a(i,i)/tn + 1.0
   a(i,i) = -tn
   if (i .eq. 1) go to 350
   im1 = i - 1
   do ii = 1,im1
      tt = -sdot(mmk,a(kp1,ii),1,a(kp1,i),1)/w(i)
      tt = tt - a(i,ii)
      call saxpy (mmk,tt,a(kp1,i),1,a(kp1,ii),1)
      a(i,ii) = a(i,ii) + tt*w(i)
   end do
   i = i - 1
   go to 340
!
350 continue
return
!
!     First np rows are linearly dependent
!
400 krank = i - 1
return
410 krank = j - 1
return
end subroutine u11us

subroutine u12us (a,mda,m,n,b,mdb,nb,mode,krank,rnorm,h,w,ir,ic)
implicit none
integer, intent(in) :: krank, m, mda, mdb, mode, n, nb
real, intent(inout) :: a(mda,n), b(mdb,nb)
real :: h(m)
real, intent(inout) :: rnorm(nb)
real :: w(m)
integer :: i, ij, ip1, j, jb, k, kp1, mmk
real :: bb, tt
real :: snrm2
real :: sdot
!
!        Given the Householder LQ factorization of A, this
!        SUBROUTINE SOLVES THE SYSTEM AX=b. IF THE SYSTEM
!        is of reduced rank, this routine returns a solution
!        according to the selected mode.
!
!       NOTE - IF mode.NE.2, w IS NEVER ACCESSED.
!
integer, intent(inout) :: ic(n), ir(m)
!
k = krank
kp1 = k + 1
if (k .gt. 0) go to 30
!
!        rank=0
!
do jb = 1,nb
   rnorm(jb) = snrm2(m,b(1,jb),1)
end do
do jb = 1,nb
   do i = 1,n
      b(i,jb) = 0.0
   end do
end do
return
!
30 i = 0
!
!     Reorder b to reflect row interchanges
!
40 i = i + 1
   if (i .eq. m) go to 100
   j = ir(i)
   if (j .eq. i) go to 40
   if (j .lt. 0) go to 40
!
   ir(i) = -ir(i)
   do jb = 1,nb
      rnorm(jb) = b(i,jb)
   end do
!
   ij = i
60 do jb = 1,nb
         b(ij,jb) = b(j,jb)
      end do
      ij = j
      j = ir(ij)
      ir(ij) = -ir(ij)
   if (j .ne. i) go to 60
!
   do jb = 1,nb
      b(ij,jb) = rnorm(jb)
   end do
   go to 40
!
100 do i = 1,m
   ir(i) = iabs(ir(i))
end do
!
!     IF A IS OF REDUCED RANK AND mode=2,
!     apply Householder transformations to b
!
if (mode .lt. 2 .or. k .eq. m) go to 140
mmk = m - k
do jb = 1,nb
   do j = 1,k
      i = kp1 - j
      tt = -sdot(mmk,a(kp1,i),1,b(kp1,jb),1)/w(i)
      tt = tt - b(i,jb)
      call saxpy (mmk,tt,a(kp1,i),1,b(kp1,jb),1)
      b(i,jb) = b(i,jb) + tt*w(i)
   end do
end do
!
!     Find norms of residual VECTOR(S)..(before overwrite b)
!
140 do jb = 1,nb
   rnorm(jb) = snrm2(m-k,b(kp1,jb),1)
end do
!
!     Back solve lower triangular L
!
do 170 jb = 1,nb
   do i = 1,k
      b(i,jb) = b(i,jb)/a(i,i)
      if (i .eq. k) go to 170
      ip1 = i + 1
      call saxpy(k-i,-b(i,jb),a(ip1,i),1,b(ip1,jb),1)
   end do
170 continue
!
!      Truncated solution
!
if (k .eq. n) go to 210
do jb = 1,nb
   do i = kp1,n
      b(i,jb) = 0.0
   end do
end do
!
!     Apply Householder transformations to b
!
210 do i = 1,k
   j = kp1 - i
   tt = a(j,j)
   a(j,j) = h(j)
   do jb = 1,nb
      bb = -sdot(n-j+1,a(j,j),mda,b(j,jb),1)/h(j)
      call saxpy(n-j+1,bb,a(j,j),mda,b(j,jb),1)
   end do
   a(j,j) = tt
end do
!
!     Reorder b to reflect column interchanges
!
i = 0
!
240 i = i + 1
   if (i .eq. n) go to 260
   j = ic(i)
   if (j .eq. i) go to 240
   if (j .lt. 0) go to 240
!
   ic(i) = -ic(i)
250 call sswap (nb,b(j,1),mdb,b(i,1),mdb)
      ij = ic(j)
      ic(j) = -ic(j)
      j = ij
   if (j .ne. i) go to 250
   go to 240
!
260 do i = 1,n
   ic(i) = iabs(ic(i))
end do
return
end subroutine u12us

subroutine dlsqr (ind, a, mda, m, n, b, mdb, nb, re, ae, krank, &
&ksure, rnorm, work, lw, iwork, liw, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ind
integer, intent(inout) :: krank, ksure
integer, intent(in) :: liw, lw, m, mda, mdb, n, nb
integer :: i, imax, info, m0, m1, m2, m3, m4, m5, mode, n0, np
!-----------------------------------------------------------------------
!
!              Least squares solution of linear equations
!
!                            --------------
!
!     dlsqr solves both underdetermined and overdetermined linear
!     SYSTEMS AX = b, WHERE A IS AN m BY n MATRIX AND b IS AN m BY
!     nb MATRIX OF RIGHT HAND SIDES. IF m .GE. n, THE LEAST SQUARES
!     solution is computed by decomposing the matrix a into the
!     product of an orthogonal matrix Q and upper triangular matrix
!     R (QR FACTORIZATION). IF m .LT. n, THE MINIMAL LENGTH SOLUTION
!     is computed by factoring the matrix a into the product of a
!     lower triangular matrix L and orthogonal matrix Q (LQ factor-
!     ization). If the matrix a is determined to be rank deficient,
!     then the minimal length least squares solution is computed.
!
!     User input bounds on the uncertainty of the elements of A are
!     used to detect numerical rank deficiency. The algorithm uses
!     a row and column pivot strategy to minimize the growth of
!     uncertainty and round-off errors.
!
!   ******************************************************************
!   *                                                                *
!   *         WARNING - ALL INPUT ARRAYS ARE CHANGED ON EXIT.        *
!   *                                                                *
!   ******************************************************************
!
!     Input..
!
!     IND           INTEGER WHICH INDICATES IF THE ROUTINE IS BEING
!                   called for the first time.
!                      ind = 0      ORIGINAL CALL
!                      ind .NE. 0   SUBSEQUENT CALLS
!                   on subsequent calls a new set b of equations can
!                   be solved (using the same coefficient matrix a).
!                   It is assumed that A, mda, m, n, krank, iwork,
!                   liw, and the first 2*min(m,n) locations of work
!                   have not been modified by the user. re, ae, and
!                   ksure are not used.
!
!     a(,)          LINEAR COEFFICIENT MATRIX OF AX=b, WITH mda THE
!      mda,m,n      ACTUAL FIRST DIMENSION OF A IN THE CALLING PROGRAM.
!                   m is the row dimension (no. of equations of the
!                   problem) and n the col dimension (no. of unknowns).
!                   MUST HAVE mda .GE. m.
!
!     b(,)          RIGHT HAND SIDE(S), WITH MDB THE ACTUAL FIRST
!      MDB,nb       DIMENSION OF b IN THE CALLING PROGRAM. nb IS THE
!                   number of m by 1 right hand sides. Must have
!                   mdb .GE. max(m,n). IF nb .LE. 0 THEN b AND MDB
!                   are ignored.
!
!     re            re IS THE MAXIMUM RELATIVE UNCERTAINTY OF THE
!                   ELEMENTS OF THE MATRIX a (0 .le. re .LT. 1).
!
!     ae            ae IS THE MAXIMUM ABSOLUTE UNCERTAINTY OF THE
!                   ELEMENTS OF THE MATRIX a (ae .GE. 0).
!
!     work()        A REAL WORK ARRAY DIMENSIONED 5*min(m,n).
!
!     lw            ACTUAL DIMENSION OF WORK
!
!     iwork()       INTEGER WORK ARRAY DIMENSIONED AT LEAST n+m.
!
!     liw           ACTUAL DIMENSION OF iwork.
!
!     Output..
!
!     a(,)          CONTAINS THE TRIANGULAR PART OF THE REDUCED MATRIX
!                   and the transformation information.Ind together with
!                   the first 2*min(m,n) elements of work (see below)
!                   completely specify the factorization of A.
!
!     b(,)          CONTAINS THE n BY nb SOLUTION MATRIX FOR X.
!
!     krank,ksure   THE NUMERICAL RANK OF A,  BASED UPON THE RELATIVE
!                   and absolute bounds on uncertainty, is bounded
!                   above by krank and below by ksure. The algorithm
!                   returns a solution based on krank. ksure provides
!                   an indication of the precision of the rank.
!
!     rnorm()       CONTAINS THE EUCLIDEAN LENGTH OF THE nb RESIDUAL
!                   VECTORS  b(i) - AX(i), i=1,...,nb.
!
!     work()        THE FIRST 2*min(m,n) LOCATIONS OF WORK CONTAIN
!                   the values necessary to reproduce the Householder
!                   factorization of A.
!
!     iwork()       AN ARRAY OF LENGTH m + n CONTAINING THE ORDERS IN
!                   WHICH THE ROWS AND COLUMNS WERE USED. IF m .GE. n
!                   then the first n locations contain the order of
!                   the columns and the next m locations the order of
!                   THE ROWS. IF m .LT. n THEN THE ORDER OF THE ROWS
!                   precedes the order of the columns.
!
!     ierr          FLAG TO INDICATE THE STATUS OF THE RESULTS
!                     0     - SATISFACTORY COMPLETION
!                   .GT. 0  - INPUT ERROR
!
!----------------
!     The subroutines du11ls, du12ls, du11us, and du12us were written by
!     T. Manteuffel (LANL) in 1981. The driver routine dlsqr was written
!     by A.H. Morris (NSWC) in 1991.
!----------------
!     Reference.  Manteuffel, T., *An interval analysis approach to rank
!                 determination in linear least squares problems*,
!                 Sandia Laboratories report SAND80-0655, June, 1980.
!-----------------------------------------------------------------------
double precision, intent(inout) :: a(mda,n), b(mdb,*)
double precision, intent(in) :: re, ae
double precision, intent(inout) :: rnorm(*), work(lw)
integer, intent(inout) :: iwork(liw)
double precision :: eps, rerr
double precision :: dpmpar
!----------------
!     np            IF m .GE. n THEN THE FIRST np COLUMNS OF A
!                   are never interchanged.
!                   IF m .LT. n THEN THE FIRST np ROWS OF A ARE
!                   never interchanged. np is not referenced on
!                   a continuation call to the routine.
!
!     MODE          THE INTEGER MODE INDICATES HOW THE ROUTINE
!                   is to react if rank deficiency is detected.
!                   IF mode = 0 RETURN IMMEDIATELY, NO SOLUTION
!                             1 compute truncated solution
!                             2 compute minimal length solution
!                   mode must not be modified on a continuation
!                   CALL TO THE ROUTINE. IF MODE LT. 2, ONLY THE
!                   first n locations of work are used.
!----------------
np = 0
mode = 2
!
!     Check the input
!
if (nb .le. 0 .and. ind .ne. 0) go to 200
if (m .lt. 1 .or. n .lt. 1) go to 210
if (mda .lt. m) go to 220
if (liw .lt. m + n) go to 240
!
m0 = min0(m,n)
n0 = max0(m,n)
!     num = 0
!
if (nb .le. 0) go to 10
if (mdb .lt. n0) go to 230
if (ind .ne. 0) go to 100
!
10 if (lw .lt. 5*m0) go to 250
if (re .lt. 0.d0 .or. ae .lt. 0.d0) go to 260
!
!     Define the relative and absolute tolerance lists
!
m1 = 1
m2 = m1 + m0
m3 = m2 + m0
m4 = m3 + m0
m5 = m4 + m0
!
eps = 10.d0*dpmpar(1)
rerr = dmax1(eps,re)
!
imax = m5 - 1
do i = m4,imax
   work(i) = rerr
end do
imax = imax + m0
do i = m5,imax
   work(i) = ae
end do
!
!     Factor the matrix a
!
!     num = np
if (m .lt. n) go to 40
!
   call du11ls (a,mda,m,n,work(m4),work(m5),mode,np,krank,ksure, &
&work(m1),work(m2),work(m3),iwork(m1),iwork(m2))
   go to 100
!
40 call du11us (a,mda,m,n,work(m4),work(m5),mode,np,krank,ksure, &
&work(m1),work(m2),work(m3),iwork(m1),iwork(m2))
!
!     Solution phase
!
100 ierr = 0
info = 0
if (krank .eq. m0) go to 110
if (krank .eq. 0) go to 110
!     if (krank .lt. num) go to 280
!     if (mode .eq. 0) return
info = mode
!
110 if (nb .le. 0) return
!
m1 = 1
m2 = 1 + m0
if (info .eq. 2) go to 130
!
!     Only min(m,n) elements of work are needed
!
if (lw .lt. m0) go to 250
if (m .lt. n) go to 120
!
   call du12ls (a,mda,m,n,b,mdb,nb,mode,krank,rnorm, &
&work(m1),work(m1),iwork(m1),iwork(m2))
   return
!
120 call du12us (a,mda,m,n,b,mdb,nb,mode,krank,rnorm, &
&work(m1),work(m1),iwork(m1),iwork(m2))
return
!
!     Here 2*min(m,n) elements of work are needed
!
130 if (lw .lt. 2*m0) go to 250
if (m .lt. n) go to 140
!
   call du12ls (a,mda,m,n,b,mdb,nb,mode,krank,rnorm, &
&work(m1),work(m2),iwork(m1),iwork(m2))
   return
!
140 call du12us (a,mda,m,n,b,mdb,nb,mode,krank,rnorm, &
&work(m1),work(m2),iwork(m1),iwork(m2))
return
!
!     Error return
!
!                             nb .LE. 0  ON A CONTINUATION CALL
200 ierr = 7
return
!                             m .LT. 1 OR n .LT. 1
210 ierr = 1
return
!                             mda .LT. m
220 ierr = 2
return
!                             mdb .LT. max(m,n)
230 ierr = 3
return
!                             liw .LT. m + n
240 ierr = 4
return
!                             lw too small
250 ierr = 5
return
!                             re or ae is negative
260 ierr = 6
return
!                             0 .LT. krank .LT. np
! 280 ierr = 8
!     return
end subroutine dlsqr

subroutine du11ls (a,mda,m,n,ub,db,mode,np,krank,ksure,h,w,eb, &
&ic,ir)
implicit none
integer, intent(out) :: krank
integer, intent(inout) :: ksure
integer, intent(in) :: m, mda, mode, n, np
integer :: i, ii, im1, imin, is, j, jm1, jmax, jp1, kk, km1, kmi, &
&kp1, kz, l, lm1, mm, nmk
integer :: idamax
!
!       This routine performs A QR factorization of A
!       using Householder transformations. Row and
!       column pivots are chosen to reduce the growth
!       of round-off and to help detect possible rank
!       deficiency.
!
double precision, intent(inout) :: a(mda,n), ub(n), db(n), h(n), &
&w(n), eb(n)
integer, intent(inout) :: ic(n), ir(m)
double precision :: bb, rmin, r2, sum, t, temp, tn, tt
double precision :: ddot, dnrm2
!
!        Initialization
!
j = 0
krank = n
do i = 1,n
   ic(i) = i
end do
do i = 1,m
   ir(i) = i
end do
!
!        Determine rel and abs error vectors
!
!
!        Calculate col length
!
do i = 1,n
   h(i) = dnrm2(m,a(1,i),1)
   w(i) = h(i)
end do
!
!         Initialize error bounds
!
do i = 1,n
   eb(i) = dmax1(db(i),ub(i)*h(i))
   ub(i) = eb(i)
   db(i) = 0.d0
end do
!
!          Discard self dependent columns
!
i = 1
50 if (eb(i) .ge. h(i)) go to 60
if (i .eq. krank) go to 70
i = i + 1
go to 50
!
!          Matrix reduction
!
60 kk = krank
krank = krank - 1
if (mode .eq. 0) return
if (i .le. np) go to 400
if (i .gt. krank) go to 70
call dswap (1,eb(i),1,eb(kk),1)
call dswap (1,ub(i),1,ub(kk),1)
call dswap (1,w(i),1,w(kk),1)
call dswap (1,h(i),1,h(kk),1)
call iswap (1,ic(i),1,ic(kk),1)
call dswap (m,a(1,i),1,a(1,kk),1)
go to 50
!
!           Test for zero rank
!
70 if (krank .gt. 0) go to 100
krank = 0
ksure = 0
return
!
!        m A i n    L O O P
!
100 j = j + 1
jp1 = j + 1
jm1 = j - 1
kz = krank
if (j .le. np) kz = j
!
!        EACH COL HAS MM=m-j+1 COMPONENTS
!
mm = m - j + 1
!
!         ub determines column pivot
!
110 imin = j
if (h(j) .eq. 0.d0) go to 170
rmin = ub(j)/h(j)
do 120 i = j,kz
   if (ub(i) .ge. h(i)*rmin) go to 120
   rmin = ub(i)/h(i)
   imin = i
120 continue
!
!     Test for rank deficiency
!
if (rmin .lt. 1.d0) go to 200
tt = (eb(imin) + dabs(db(imin)))/h(imin)
if (tt .ge. 1.d0) go to 170
!
!     Compute exact ub
!
do i = 1,jm1
   w(i) = a(i,imin)
end do
!
l = jm1
130 w(l) = w(l)/a(l,l)
if (l .eq. 1) go to 150
lm1 = l - 1
do i = l,jm1
   w(lm1) = w(lm1) - a(lm1,i)*w(i)
end do
l = lm1
go to 130
!
150 tt = eb(imin)
do i = 1,jm1
   tt = tt + dabs(w(i))*eb(i)
end do
ub(imin) = tt
if (ub(imin)/h(imin) .ge. 1.d0) go to 170
go to 200
!
!        Matrix reduction
!
170 kk = krank
krank = krank - 1
kz = krank
if (mode .eq. 0) return
if (j .le. np) go to 410
if (imin .gt. krank) go to 180
   call iswap (1,ic(imin),1,ic(kk),1)
   call dswap (m,a(1,imin),1,a(1,kk),1)
   call dswap (1,eb(imin),1,eb(kk),1)
   call dswap (1,ub(imin),1,ub(kk),1)
   call dswap (1,db(imin),1,db(kk),1)
   call dswap (1,w(imin),1,w(kk),1)
   call dswap (1,h(imin),1,h(kk),1)
180 if (j .gt. krank) go to 300
go to 110
!
!        Column pivot
!
200 if (imin .eq. j) go to 210
call dswap (1,h(j),1,h(imin),1)
call dswap (m,a(1,j),1,a(1,imin),1)
call dswap (1,eb(j),1,eb(imin),1)
call dswap (1,ub(j),1,ub(imin),1)
call dswap (1,db(j),1,db(imin),1)
call dswap (1,w(j),1,w(imin),1)
call iswap (1,ic(j),1,ic(imin),1)
!
!        Row pivot
!
210 jmax = idamax(mm,a(j,j),1)
jmax = jmax + j - 1
if (jmax .eq. j) go to 220
call dswap (n,a(j,1),mda,a(jmax,1),mda)
call iswap (1,ir(j),1,ir(jmax),1)
!
!     Apply Householder transformation
!
220 tn = dnrm2(mm,a(j,j),1)
if (tn .eq. 0.d0) go to 170
if (a(j,j) .ne. 0.d0) tn = dsign(tn,a(j,j))
call dscal (mm,1.d0/tn,a(j,j),1)
a(j,j) = a(j,j) + 1.d0
if (j .eq. n) go to 250
do 240 i = jp1,n
   bb = -ddot(mm,a(j,j),1,a(j,i),1)/a(j,j)
   call daxpy (mm,bb,a(j,j),1,a(j,i),1)
   if (i .le. np) go to 240
   if (h(i) .eq. 0.d0) go to 240
   tt = 1.d0 - (a(j,i)/h(i))**2
   tt = dmax1(tt,0.d0)
   t = tt
   tt = 1.d0 + 0.05d0*tt*(h(i)/w(i))**2
   if (tt .eq. 1.d0) go to 230
      h(i) = h(i)*dsqrt(t)
      go to 240
230 h(i) = dnrm2(m-j,a(j+1,i),1)
   w(i) = h(i)
240 continue
!
250 h(j) = a(j,j)
a(j,j) = -tn
!
!          Update ub, db
!
ub(j) = ub(j)/dabs(a(j,j))
db(j) = (dsign(eb(j),db(j)) + db(j))/a(j,j)
if (j .eq. krank) go to 300
do i = jp1,krank
   ub(i) = ub(i) + dabs(a(j,i))*ub(j)
   db(i) = db(i) - a(j,i)*db(j)
end do
go to 100
!
!        E n D    m A i n    L O O P
!
300 continue
!
!        Compute ksure
!
km1 = krank - 1
do i = 1,km1
   is = 0
   kmi = krank - i
   do 310 ii = 1,kmi
      if (ub(ii) .le. ub(ii + 1)) go to 310
      is = 1
      temp = ub(ii)
      ub(ii) = ub(ii + 1)
      ub(ii + 1) = temp
310 continue
   if (is .eq. 0) go to 320
end do
!
320 ksure = 0
sum = 0.d0
do i = 1,krank
   r2 = ub(i)*ub(i)
   if (r2 + sum .ge. 1.d0) go to 330
   sum = sum + r2
   ksure = ksure + 1
end do
!
!     IF SYSTEM IS OF REDUCED RANK AND mode = 2
!     complete the decomposition for shortest least squares solution
!
330 if (krank .eq. n .or. mode .lt. 2) return
nmk = n - krank
kp1 = krank + 1
i = krank
340 tn = dnrm2(nmk,a(i,kp1),mda)/a(i,i)
   tn = a(i,i)*dsqrt(1.d0 + tn*tn)
   call dscal (nmk,1.d0/tn,a(i,kp1),mda)
   w(i) = a(i,i)/tn + 1.d0
   a(i,i) = -tn
   if (i .eq. 1) go to 350
   im1 = i - 1
   do ii = 1,im1
      tt = -ddot(nmk,a(ii,kp1),mda,a(i,kp1),mda)/w(i)
      tt = tt - a(ii,i)
      call daxpy (nmk,tt,a(i,kp1),mda,a(ii,kp1),mda)
      a(ii,i) = a(ii,i) + tt*w(i)
   end do
   i = i - 1
   go to 340
!
350 continue
return
!
!     First np columns are linearly dependent
!
400 krank = i - 1
return
410 krank = j - 1
return
end subroutine du11ls

subroutine du12ls (a,mda,m,n,b,mdb,nb,mode,krank,rnorm,h,w,ic,ir)
implicit none
integer, intent(in) :: krank, m, mda, mdb, mode, n, nb
integer :: i, ij, im1, j, jb, k, kp1, nmk
!
!        Given the Householder QR factorization of A, this
!        SUBROUTINE SOLVES THE SYSTEM AX=b. IF THE SYSTEM
!        is of reduced rank, this routine returns a solution
!        according to the selected mode.
!
!       NOTE - IF mode.NE.2, w IS NEVER ACCESSED.
!
double precision, intent(inout) :: a(mda,n), b(mdb,nb), rnorm(nb)
double precision, intent(in) :: h(n), w(n)
integer, intent(inout) :: ic(n), ir(m)
double precision :: bb, tt
double precision :: ddot, dnrm2
!
k = krank
kp1 = k + 1
if (k .gt. 0) go to 30
!
!        rank=0
!
do jb = 1,nb
   rnorm(jb) = dnrm2(m,b(1,jb),1)
end do
do jb = 1,nb
   do i = 1,n
      b(i,jb) = 0.d0
   end do
end do
return
!
30 i = 0
!
!     Reorder b to reflect row interchanges
!
40 i = i + 1
   if (i .eq. m) go to 100
   j = ir(i)
   if (j .eq. i) go to 40
   if (j .lt. 0) go to 40
!
   ir(i) = -ir(i)
   do jb = 1,nb
      rnorm(jb) = b(i,jb)
   end do
!
   ij = i
60 do jb = 1,nb
         b(ij,jb) = b(j,jb)
      end do
      ij = j
      j = ir(ij)
      ir(ij) = -ir(ij)
   if (j .ne. i) go to 60
!
   do jb = 1,nb
      b(ij,jb) = rnorm(jb)
   end do
   go to 40
!
100 do i = 1,m
   ir(i) = iabs(ir(i))
end do
!
!     Apply Householder transformations to b
!
do j = 1,k
   tt = a(j,j)
   a(j,j) = h(j)
   do i = 1,nb
      bb = -ddot (m-j+1,a(j,j),1,b(j,i),1)/h(j)
      call daxpy (m-j+1,bb,a(j,j),1,b(j,i),1)
   end do
   a(j,j) = tt
end do
!
!        Find norms of residual VECTOR(S)..(before overwrite b)
!
do jb = 1,nb
   rnorm(jb) = dnrm2(m-k,b(kp1,jb),1)
end do
!
!     Back solve upper triangular R
!
i = k
150 do jb = 1,nb
   b(i,jb) = b(i,jb)/a(i,i)
end do
if (i .eq. 1) go to 200
im1 = i - 1
do jb = 1,nb
   call daxpy (im1,-b(i,jb),a(1,i),1,b(1,jb),1)
end do
i = im1
go to 150
!
!     RANK LT n
!
!      Truncated solution
!
200 if (k .eq. n) go to 230
do jb = 1,nb
   do i = kp1,n
      b(i,jb) = 0.d0
   end do
end do
if (mode .eq. 1) go to 230
!
!      Minimal length solution
!
nmk = n - k
do jb = 1,nb
   do i = 1,k
      tt = -ddot(nmk,a(i,kp1),mda,b(kp1,jb),1)/w(i)
      tt = tt - b(i,jb)
      call daxpy (nmk,tt,a(i,kp1),mda,b(kp1,jb),1)
      b(i,jb) = b(i,jb) + tt*w(i)
   end do
end do
!
!     Reorder b to reflect column interchanges
!
230 i = 0
!
240 i = i + 1
   if (i .eq. n) go to 260
   j = ic(i)
   if (j .eq. i) go to 240
   if (j .lt. 0) go to 240
!
   ic(i) = -ic(i)
250 call dswap (nb,b(j,1),mdb,b(i,1),mdb)
      ij = ic(j)
      ic(j) = -ic(j)
      j = ij
   if (j .ne. i) go to 250
   go to 240
!
260 do i = 1,n
   ic(i) = iabs(ic(i))
end do
return
end subroutine du12ls

subroutine du11us (a,mda,m,n,ub,db,mode,np,krank,ksure,h,w,eb, &
&ir,ic)
implicit none
integer, intent(out) :: krank
integer, intent(inout) :: ksure
integer, intent(in) :: m, mda, mode, n, np
integer :: i, ii, im1, imin, is, j, jm1, jmax, jp1, kk, km1, kmi, &
&kp1, kz, l, lm1, mmk, nn
integer :: idamax
!
!       This routine performs an LQ factorization of the
!       matrix a using Householder transformations. Row
!       and column pivots are chosen to reduce the growth
!       of round-off and to help detect possible rank
!       deficiency.
!
double precision, intent(inout) :: a(mda,n), ub(m), db(m), h(m), &
&w(m), eb(m)
integer, intent(inout) :: ic(n), ir(m)
double precision :: bb, rmin, r2, sum, t, temp, tn, tt
double precision :: ddot, dnrm2
!
!        Initialization
!
j = 0
krank = m
do i = 1,n
   ic(i) = i
end do
do i = 1,m
   ir(i) = i
end do
!
!        Determine rel and abs error vectors
!
!
!        Calculate row length
!
do i = 1,m
   h(i) = dnrm2(n,a(i,1),mda)
   w(i) = h(i)
end do
!
!         Initialize error bounds
!
do i = 1,m
   eb(i) = dmax1(db(i),ub(i)*h(i))
   ub(i) = eb(i)
   db(i) = 0.d0
end do
!
!          Discard self dependent rows
!
i = 1
50 if (eb(i) .ge. h(i)) go to 60
if (i .eq. krank) go to 70
i = i + 1
go to 50
!
!          Matrix reduction
!
60 kk = krank
krank = krank - 1
if (mode .eq. 0) return
if (i .le. np) go to 400
if (i .gt. krank) go to 70
call dswap (1,eb(i),1,eb(kk),1)
call dswap (1,ub(i),1,ub(kk),1)
call dswap (1,w(i),1,w(kk),1)
call dswap (1,h(i),1,h(kk),1)
call iswap (1,ir(i),1,ir(kk),1)
call dswap (n,a(i,1),mda,a(kk,1),mda)
go to 50
!
!           Test for zero rank
!
70 if (krank .gt. 0) go to 100
krank = 0
ksure = 0
return
!
!        m A i n    L O O P
!
100 j = j + 1
jp1 = j + 1
jm1 = j - 1
kz = krank
if (j .le. np) kz = j
!
!        EACH ROW HAS NN=n-j+1 COMPONENTS
!
nn = n - j + 1
!
!         ub determines row pivot
!
110 imin = j
if (h(j) .eq. 0.d0) go to 170
rmin = ub(j)/h(j)
do 120 i = j,kz
   if (ub(i) .ge. h(i)*rmin) go to 120
   rmin = ub(i)/h(i)
   imin = i
120 continue
!
!     Test for rank deficiency
!
if (rmin .lt. 1.d0) go to 200
tt = (eb(imin) + dabs(db(imin)))/h(imin)
if (tt .ge. 1.d0) go to 170
!
!     Compute exact ub
!
do i = 1,jm1
   w(i) = a(imin,i)
end do
!
l = jm1
130 w(l) = w(l)/a(l,l)
if (l .eq. 1) go to 150
lm1 = l - 1
do i = l,jm1
   w(lm1) = w(lm1) - a(i,lm1)*w(i)
end do
l = lm1
go to 130
!
150 tt = eb(imin)
do i = 1,jm1
   tt = tt + dabs(w(i))*eb(i)
end do
ub(imin) = tt
if (ub(imin)/h(imin) .ge. 1.d0) go to 170
go to 200
!
!        Matrix reduction
!
170 kk = krank
krank = krank - 1
kz = krank
if (mode .eq. 0) return
if (j .le. np) go to 410
if (imin .gt. krank) go to 180
   call iswap (1,ir(imin),1,ir(kk),1)
   call dswap (n,a(imin,1),mda,a(kk,1),mda)
   call dswap (1,eb(imin),1,eb(kk),1)
   call dswap (1,ub(imin),1,ub(kk),1)
   call dswap (1,db(imin),1,db(kk),1)
   call dswap (1,w(imin),1,w(kk),1)
   call dswap (1,h(imin),1,h(kk),1)
180 if (j .gt. krank) go to 300
go to 110
!
!        Row pivot
!
200 if (imin .eq. j) go to 210
call dswap (1,h(j),1,h(imin),1)
call dswap (n,a(j,1),mda,a(imin,1),mda)
call dswap (1,eb(j),1,eb(imin),1)
call dswap (1,ub(j),1,ub(imin),1)
call dswap (1,db(j),1,db(imin),1)
call dswap (1,w(j),1,w(imin),1)
call iswap (1,ir(j),1,ir(imin),1)
!
!        Column pivot
!
210 jmax = idamax(nn,a(j,j),mda)
jmax = jmax + j - 1
if (jmax .eq. j) go to 220
call dswap (m,a(1,j),1,a(1,jmax),1)
call iswap (1,ic(j),1,ic(jmax),1)
!
!     Apply Householder transformation
!
220 tn = dnrm2(nn,a(j,j),mda)
if (tn .eq. 0.d0) go to 170
if (a(j,j) .ne. 0.d0) tn = dsign(tn,a(j,j))
call dscal (nn,1.d0/tn,a(j,j),mda)
a(j,j) = a(j,j) + 1.d0
if (j .eq. m) go to 250
do 240 i = jp1,m
   bb = -ddot(nn,a(j,j),mda,a(i,j),mda)/a(j,j)
   call daxpy (nn,bb,a(j,j),mda,a(i,j),mda)
   if (i .le. np) go to 240
   if (h(i) .eq. 0.d0) go to 240
   tt = 1.0 - (a(i,j)/h(i))**2
   tt = dmax1(tt,0.d0)
   t = tt
   tt = 1.d0 + 0.05d0*tt*(h(i)/w(i))**2
   if (tt .eq. 1.d0) go to 230
      h(i) = h(i)*dsqrt(t)
      go to 240
230 h(i) = dnrm2(n-j,a(i,j+1),mda)
   w(i) = h(i)
240 continue
!
250 h(j) = a(j,j)
a(j,j) = -tn
!
!          Update ub, db
!
ub(j) = ub(j)/dabs(a(j,j))
db(j) = (dsign(eb(j),db(j)) + db(j))/a(j,j)
if (j .eq. krank) go to 300
do i = jp1,krank
   ub(i) = ub(i) + dabs(a(i,j))*ub(j)
   db(i) = db(i) - a(i,j)*db(j)
end do
go to 100
!
!        E n D    m A i n    L O O P
!
300 continue
!
!        Compute ksure
!
km1 = krank - 1
do i = 1,km1
   is = 0
   kmi = krank - i
   do 310 ii = 1,kmi
      if (ub(ii) .le. ub(ii + 1)) go to 310
      is = 1
      temp = ub(ii)
      ub(ii) = ub(ii + 1)
      ub(ii + 1) = temp
310 continue
   if (is .eq. 0) go to 320
end do
!
320 ksure = 0
sum = 0.d0
do i = 1,krank
   r2 = ub(i)*ub(i)
   if (r2 + sum .ge. 1.d0) go to 330
   sum = sum + r2
   ksure = ksure + 1
end do
!
!     IF SYSTEM IS OF REDUCED RANK AND mode = 2
!     complete the decomposition for shortest least squares solution
!
330 if (krank .eq. m .or. mode .lt. 2) return
mmk = m - krank
kp1 = krank + 1
i = krank
340 tn = dnrm2(mmk,a(kp1,i),1)/a(i,i)
   tn = a(i,i)*dsqrt(1.d0 + tn*tn)
   call dscal (mmk,1.d0/tn,a(kp1,i),1)
   w(i) = a(i,i)/tn + 1.d0
   a(i,i) = -tn
   if (i .eq. 1) go to 350
   im1 = i - 1
   do ii = 1,im1
      tt = -ddot(mmk,a(kp1,ii),1,a(kp1,i),1)/w(i)
      tt = tt - a(i,ii)
      call daxpy (mmk,tt,a(kp1,i),1,a(kp1,ii),1)
      a(i,ii) = a(i,ii) + tt*w(i)
   end do
   i = i - 1
   go to 340
!
350 continue
return
!
!     First np rows are linearly dependent
!
400 krank = i - 1
return
410 krank = j - 1
return
end subroutine du11us

subroutine du12us (a,mda,m,n,b,mdb,nb,mode,krank,rnorm,h,w,ir,ic)
implicit none
integer, intent(in) :: krank, m, mda, mdb, mode, n, nb
integer :: i, ij, ip1, j, jb, k, kp1, mmk
!
!        Given the Householder LQ factorization of A, this
!        SUBROUTINE SOLVES THE SYSTEM AX=b. IF THE SYSTEM
!        is of reduced rank, this routine returns a solution
!        according to the selected mode.
!
!       NOTE - IF mode.NE.2, w IS NEVER ACCESSED.
!
double precision, intent(inout) :: a(mda,n), b(mdb,nb), rnorm(nb)
double precision, intent(in) :: h(m), w(m)
integer, intent(inout) :: ic(n), ir(m)
double precision :: bb, tt
double precision :: ddot, dnrm2
!
k = krank
kp1 = k + 1
if (k .gt. 0) go to 30
!
!        rank=0
!
do jb = 1,nb
   rnorm(jb) = dnrm2(m,b(1,jb),1)
end do
do jb = 1,nb
   do i = 1,n
      b(i,jb) = 0.d0
   end do
end do
return
!
30 i = 0
!
!     Reorder b to reflect row interchanges
!
40 i = i + 1
   if (i .eq. m) go to 100
   j = ir(i)
   if (j .eq. i) go to 40
   if (j .lt. 0) go to 40
!
   ir(i) = -ir(i)
   do jb = 1,nb
      rnorm(jb) = b(i,jb)
   end do
!
   ij = i
60 do jb = 1,nb
         b(ij,jb) = b(j,jb)
      end do
      ij = j
      j = ir(ij)
      ir(ij) = -ir(ij)
   if (j .ne. i) go to 60
!
   do jb = 1,nb
      b(ij,jb) = rnorm(jb)
   end do
   go to 40
!
100 do i = 1,m
   ir(i) = iabs(ir(i))
end do
!
!     IF A IS OF REDUCED RANK AND mode=2,
!     apply Householder transformations to b
!
if (mode .lt. 2 .or. k .eq. m) go to 140
mmk = m - k
do jb = 1,nb
   do j = 1,k
      i = kp1 - j
      tt = -ddot(mmk,a(kp1,i),1,b(kp1,jb),1)/w(i)
      tt = tt - b(i,jb)
      call daxpy (mmk,tt,a(kp1,i),1,b(kp1,jb),1)
      b(i,jb) = b(i,jb) + tt*w(i)
   end do
end do
!
!     Find norms of residual VECTOR(S)..(before overwrite b)
!
140 do jb = 1,nb
   rnorm(jb) = dnrm2(m-k,b(kp1,jb),1)
end do
!
!     Back solve lower triangular L
!
do 170 jb = 1,nb
   do i = 1,k
      b(i,jb) = b(i,jb)/a(i,i)
      if (i .eq. k) go to 170
      ip1 = i + 1
      call daxpy(k-i,-b(i,jb),a(ip1,i),1,b(ip1,jb),1)
   end do
170 continue
!
!      Truncated solution
!
if (k .eq. n) go to 210
do jb = 1,nb
   do i = kp1,n
      b(i,jb) = 0.d0
   end do
end do
!
!     Apply Householder transformations to b
!
210 do i = 1,k
   j = kp1 - i
   tt = a(j,j)
   a(j,j) = h(j)
   do jb = 1,nb
      bb = -ddot(n-j+1,a(j,j),mda,b(j,jb),1)/h(j)
      call daxpy(n-j+1,bb,a(j,j),mda,b(j,jb),1)
   end do
   a(j,j) = tt
end do
!
!     Reorder b to reflect column interchanges
!
i = 0
!
240 i = i + 1
   if (i .eq. n) go to 260
   j = ic(i)
   if (j .eq. i) go to 240
   if (j .lt. 0) go to 240
!
   ic(i) = -ic(i)
250 call dswap (nb,b(j,1),mdb,b(i,1),mdb)
      ij = ic(j)
      ic(j) = -ic(j)
      j = ij
   if (j .ne. i) go to 250
   go to 240
!
260 do i = 1,n
   ic(i) = iabs(ic(i))
end do
return
end subroutine du12us

subroutine hfti (a,mda,m,n,b,mdb,nb,tau,k,rnorm,h,g,ip)
implicit none
integer, intent(out) :: k
integer, intent(in) :: m, mda, mdb, n, nb
real, intent(inout) :: a(mda,n), b(mdb,*), g(n), h(n), rnorm(*)
real, intent(in) :: tau
integer :: i, ii, ip1, j, jb, jj, kp1, l, ldiag, lmax
real :: factor, hmax, sm1, tmp, z
!-----------------------------------------------------------------------
!     dimension a(mda,n),(b(mdb,nb) or b(m)),rnorm(nb),h(n),g(n),ip(n)
!
!     Written by C.L. Lawson and R.J. Hanson.
!     From the book solving least squares problems, Prentice-Hall, 1974.
!     For algorithmic details see algorithm hfti in chapter 14.
!
!     Abstract
!
!     This subroutine solves a linear least squares problem or a set of
!     linear least squares problems having the same matrix but different
!     right-side vectors.  The problem data consists of an m by n matrix
!     A, an m by nb matrix b, and an absolute tolerance parameter tau
!     whose usage is described below.  The nb column vectors of b
!     represent right-side vectors for nb distinct linear least squares
!     problems.
!
!     This set of problems can also be written as the matrix least
!     squares problem
!
!                       ax = b,
!
!     Where X is the n by nb solution matrix.
!
!     Note that if b is the m by m identity matrix, then X will be the
!     pseudo-inverse of A.
!
!     This subroutine first transforms the augmented matrix (A b) to A
!     matrix (R C) using premultiplying Householder transformations with
!     column interchanges.  All subdiagonal elements in the matrix R are
!     zero and its diagonal elements satisfy
!
!                       abs(R(i,i)).GE.abs(R(i+1,i+1)),
!
!                       i = 1,...,l-1, where
!
!                       l = min(m,n).
!
!     The subroutine sets k to be the number of diagonal elements
!     of R that exceed tau in magnitude. Then the solution of minimum
!     Euclidean length is computed using the first k rows of (R C).
!
!     To be specific we suggest that the user consider an easily
!     computable matrix NORM, such as, the maximum of all column sums of
!     magnitudes.
!
!     Now if the relative uncertainty of b is eps, (norm of uncertainty/
!     norm of b), it is suggested that tau be set approximately equal to
!     eps*(norm of A).
!
!     The entire set of parameters for hfti are
!
!     Input..
!
!     a(*,*),mda,m,n    THE ARRAY a(*,*) INITIALLY CONTAINS THE m BY n
!                       MATRIX a OF THE LEAST SQUARES PROBLEM AX = b.
!                       The first dimensioning parameter of the array
!                       a(*,*) IS mda, WHICH MUST SATISFY mda.GE.m
!                       EITHER m.GE.n OR m.LT.n IS PERMITTED.  THERE
!                       is no restriction on the rank of A.  the
!                       CONDITION mda.LT.m IS CONSIDERED AN ERROR.
!
!     b(*),MDB,nb       IF nb = 0 THE SUBROUTINE WILL PERFORM THE
!                       orthogonal decomposition but will make no
!                       REFERENCES TO THE ARRAY b(*).  IF nb.GT.0
!                       the array b(*) must initially contain the m by
!                       nb MATRIX b OF THE LEAST SQUARES PROBLEM AX =
!                       b.  IF nb.GE.2 THE ARRAY b(*) MUST BE DOUBLY
!                       subscripted with first dimensioning parameter
!                       mdb.GE.max(m,n).  IF nb = 1 THE ARRAY b(*) MAY
!                       be either doubly or singly subscripted.  In
!                       the latter case the value of mdb is arbitrary
!                       but it should be set to some valid integer
!                       VALUE SUCH AS mdb = m.
!
!                       THE CONDITION OF nb.GT.1.AND.mdb.LT. max(m,n)
!                       is considered an error.
!
!     tau               ABSOLUTE TOLERANCE PARAMETER PROVIDED BY USER
!                       for pseudorank determination.
!
!     h(*),g(*),ip(*)   ARRAYS OF WORKING SPACE USED BY hfti.
!
!     Output..
!
!     a(*,*)            THE CONTENTS OF THE ARRAY a(*,*) WILL BE
!                       modified by the subroutine.  These contents
!                       are not generally required by the user.
!
!     b(*)              ON RETURN THE ARRAY b(*) WILL CONTAIN THE n BY
!                       nb solution matrix X.
!
!     k                 SET BY THE SUBROUTINE TO INDICATE THE
!                       pseudorank of A.
!
!     rnorm(*)          ON RETURN, rnorm(j) WILL CONTAIN THE EUCLIDEAN
!                       norm of the residual vector for the problem
!                       defined by the j-TH column vector of the array
!                       b(*,*) FOR j = 1,...,nb.
!
!     h(*),g(*)         ON RETURN THESE ARRAYS RESPECTIVELY CONTAIN
!                       elements of the pre- and post-multiplying
!                       Householder transformations used to compute
!                       the minimum Euclidean length solution.
!
!     ip(*)             ARRAY IN WHICH THE SUBROUTINE RECORDS INDICES
!                       describing the permutation of column vectors.
!                       The contents of arrays h(*),g(*) and ip(*)
!                       are not generally required by the user.
!-----------------------------------------------------------------------
integer, intent(inout) :: ip(n)
double precision :: sm
!---------------------
data factor /1.e-3/
!
k = 0
ldiag = min0(m,n)
if (ldiag .le. 0) go to 270
    do 80 j = 1,ldiag
    if (j .eq. 1) go to 20
!
!     Update squared column lengths and find lmax
!    ..
    lmax = j
        do l = j,n
        h(l) = h(l) - a(j-1,l)**2
        if (h(l) .gt. h(lmax)) lmax = l
        end do
    z = hmax + factor*h(lmax)
    if (z .gt. hmax) go to 50
!
!     Compute squared column lengths and find lmax
!    ..
20 lmax=j
        do l = j,n
        h(l) = 0.0
            do 30 i = j,m
30 h(l) = h(l) + a(i,l)**2
        if (h(l) .gt. h(lmax)) lmax = l
        end do
    hmax = h(lmax)
!    ..
!     lmax has been determined
!
!     Do column interchanges if needed.
!    ..
50 ip(j) = lmax
    if (ip(j) .eq. j) go to 70
        do 60 i = 1,m
        tmp = a(i,j)
        a(i,j) = a(i,lmax)
60 a(i,lmax) = tmp
    h(lmax) = h(j)
!
!     Compute the j-TH transformation and apply it to A and b.
!    ..
70 call h12 (1,j,j+1,m,a(1,j),1,h(j),a(1,j+1),1,mda,n-j)
80 call h12 (2,j,j+1,m,a(1,j),1,h(j),b,1,mdb,nb)
!
!     Determine the pseudorank, k, using the tolerance, tau.
!    ..
    do j = 1,ldiag
    if (abs(a(j,j)) .le. tau) go to 100
    end do
k = ldiag
go to 110
100 k = j - 1
110 kp1 = k + 1
!
!     Compute the norms of the residual vectors.
!
if (nb .le. 0) go to 140
    do 130 jb = 1,nb
    tmp = 0.0
    if (kp1 .gt. m) go to 130
        do 120 i = kp1,m
120 tmp = tmp + b(i,jb)**2
130 rnorm(jb) = sqrt(tmp)
140 continue
!                                           SPECIAL FOR PSEUDORANK = 0
if (k .gt. 0) go to 160
if (nb .le. 0) go to 270
    do jb = 1,nb
        do 150 i = 1,n
150 b(i,jb) = 0.0
    end do
go to 270
!
!     If the pseudorank is less than n compute Householder
!     decomposition of first k rows.
!    ..
160 if (k .eq. n) go to 180
    do 170 ii = 1,k
    i = kp1 - ii
170 call h12 (1,i,kp1,n,a(i,1),mda,g(i),a,mda,1,i-1)
180 continue
!
!
if (nb .le. 0) go to 270
    do jb = 1,nb
!
!     Solve the k by k triangular system.
!    ..
        do 210 l = 1,k
        sm = 0.d0
        i = kp1 - l
        if (i .eq. k) go to 200
        ip1 = i + 1
            do 190 j = ip1,k
190 sm = sm + dble(a(i,j))*dble(b(j,jb))
200 sm1 = dble(b(i,jb)) - sm
210 b(i,jb) = sm1/a(i,i)
!
!     Complete computation of solution vector.
!    ..
    if (k .eq. n) go to 240
        do 220 j = kp1,n
220 b(j,jb) = 0.0
        do 230 i = 1,k
230 call h12 (2,i,kp1,n,a(i,1),mda,g(i),b(1,jb),1,mdb,1)
!
!      RE-order the solution vector to compensate for the
!      column interchanges.
!    ..
240 do 250 jj = 1,ldiag
        j = ldiag + 1 - jj
        if (ip(j) .eq. j) go to 250
        l = ip(j)
        tmp = b(l,jb)
        b(l,jb) = b(j,jb)
        b(j,jb) = tmp
250 continue
    end do
!    ..
!     The solution vectors, X, are now
!     in the first  n  rows of the array b(,).
!
270 return
end subroutine hfti

subroutine hfti2(a,mda,m,n,b,mdb,nb,d,tau,k,rnorm,h,g,ip,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(out) :: k
integer, intent(in) :: m, mda, mdb, n, nb
real, intent(inout) :: a(mda,n), b(mdb,*), d(*), g(n), h(n), &
&rnorm(*)
real, intent(in) :: tau
integer :: i, ii, ip1, j, jb, jj, kp1, l, ldiag, lmax
real :: factor, hmax, sm1, tmp, z
!-----------------------------------------------------------------------
!     dimension a(mda,n),(b(mdb,nb) or b(m))
!     dimension d(l) where l = min(m,n)
!     dimension rnorm(nb),h(n),g(n),ip(n)
!
!     Written by C.L. Lawson and R.J. Hanson. Modified by A.H. Morris.
!     From the book solving least squares problems, Prentice-Hall, 1974.
!     For algorithmic details see algorithm hfti in chapter 14.
!
!     Abstract
!
!     This subroutine solves a linear least squares problem or a set of
!     linear least squares problems having the same matrix but different
!     right-side vectors.  The problem data consists of an m by n matrix
!     A, an m by nb matrix b, and an absolute tolerance parameter tau
!     whose usage is described below.  The nb column vectors of b
!     represent right-side vectors for nb distinct linear least squares
!     problems.
!
!     This set of problems can also be written as the matrix least
!     squares problem
!
!                       ax = b,
!
!     Where X is the n by nb solution matrix.
!
!     Note that if b is the m by m identity matrix, then X will be the
!     pseudo-inverse of A.
!
!     This subroutine first transforms the augmented matrix (A b) to A
!     matrix (R C) using premultiplying Householder transformations with
!     column interchanges.  All subdiagonal elements in the matrix R are
!     zero and its diagonal elements satisfy
!
!                       abs(R(i,i)).GE.abs(R(i+1,i+1)),
!
!                       i = 1,...,l-1, where
!
!                       l = min(m,n).
!
!     The array d will contain the diagonal elements R(1,1),...,R(l,l).
!     The subroutine sets k to be the number of diagonal elements that
!     exceed tau in magnitude.  Then the solution of minimum Euclidean
!     length is computed using the first k rows of (R C).
!
!     To be specific we suggest that the user consider an easily
!     computable matrix NORM, such as, the maximum of all column sums of
!     magnitudes.
!
!     Now if the relative uncertainty of b is eps, (norm of uncertainty/
!     norm of b), it is suggested that tau be set approximately equal to
!     eps*(norm of A).
!
!     The entire set of parameters for hfti2 are
!
!     Input..
!
!     a(*,*),mda,m,n    THE ARRAY a(*,*) INITIALLY CONTAINS THE m BY n
!                       MATRIX a OF THE LEAST SQUARES PROBLEM AX = b.
!                       The first dimensioning parameter of the array
!                       a(*,*) IS mda, WHICH MUST SATISFY mda.GE.m
!                       EITHER m.GE.n OR m.LT.n IS PERMITTED.  THERE
!                       is no restriction on the rank of A.  the
!                       CONDITION mda.LT.m IS CONSIDERED AN ERROR.
!
!     b(*),MDB,nb       IF nb = 0 THE SUBROUTINE WILL PERFORM THE
!                       orthogonal decomposition but will make no
!                       REFERENCES TO THE ARRAY b(*).  IF nb.GT.0
!                       the array b(*) must initially contain the m by
!                       nb MATRIX b OF THE LEAST SQUARES PROBLEM AX =
!                       b.  IF nb.GE.2 THE ARRAY b(*) MUST BE DOUBLY
!                       subscripted with first dimensioning parameter
!                       mdb.GE.max(m,n).  IF nb = 1 THE ARRAY b(*) MAY
!                       be either doubly or singly subscripted.  In
!                       the latter case the value of mdb is arbitrary
!                       but it should be set to some valid integer
!                       VALUE SUCH AS mdb = m.
!
!                       THE CONDITION OF nb.GT.1.AND.mdb.LT. max(m,n)
!                       is considered an error.
!
!     tau               ABSOLUTE TOLERANCE PARAMETER PROVIDED BY USER
!                       for pseudorank determination.
!
!     h(*),g(*),ip(*)   ARRAYS OF WORKING SPACE USED BY hfti2.
!
!     Output..
!
!     a(*,*)            THE CONTENTS OF THE ARRAY a(*,*) WILL BE
!                       modified by the subroutine.  These contents
!                       are not generally required by the user.
!
!     b(*)              ON RETURN THE ARRAY b(*) WILL CONTAIN THE n BY
!                       nb solution matrix X.
!
!     d(*)              THE ARRAY OF DIAGONAL ELEMENTS OF THE
!                       triangular matrix R
!
!     k                 SET BY THE SUBROUTINE TO INDICATE THE
!                       pseudorank of A.
!
!     RNORM(*)          ON RETURN, RNORM(j) WILL CONTAIN THE EUCLIDEAN
!                       norm of the residual vector for the problem
!                       defined by the j-TH column vector of the array
!                       b(*,*) FOR j = 1,...,nb.
!
!     h(*),g(*)         ON RETURN THESE ARRAYS RESPECTIVELY CONTAIN
!                       elements of the pre- and post-multiplying
!                       Householder transformations used to compute
!                       the minimum Euclidean length solution.
!
!     ip(*)             ARRAY IN WHICH THE SUBROUTINE RECORDS INDICES
!                       describing the permutation of column vectors.
!                       The contents of arrays h(*),g(*) and ip(*)
!                       are not generally required by the user.
!
!     ierr              ERROR INDICATOR. IF NO INPUT ERRORS ARE
!                       detected then ierr is set to 0. Otherwise
!                          ierr = 1  IF mda.LT.m
!                          ierr = 2  IF nb.GT.1 AND mdb.LT.max(m,n)
!                       these errors are fatal.
!-----------------------------------------------------------------------
integer, intent(inout) :: ip(n)
double precision :: sm
!---------------------
data factor /1.e-3/
!
k = 0
ldiag = min0(m,n)
if (ldiag .le. 0) go to 270
if (m .gt. mda) go to 300
if (nb .gt. 1 .and. max0(m,n) .gt. mdb) go to 310
!
    do 80 j = 1,ldiag
    if (j .eq. 1) go to 20
!
!     Update squared column lengths and find lmax
!    ..
    lmax = j
        do l = j,n
        h(l) = h(l) - a(j-1,l)**2
        if (h(l) .gt. h(lmax)) lmax = l
        end do
    z = hmax + factor*h(lmax)
    if (z .gt. hmax) go to 50
!
!     Compute squared column lengths and find lmax
!    ..
20 lmax = j
        do l = j,n
        h(l) = 0.0
            do 30 i = j,m
30 h(l) = h(l) + a(i,l)**2
        if (h(l) .gt. h(lmax)) lmax = l
        end do
    hmax = h(lmax)
!    ..
!     lmax has been determined
!
!     Do column interchanges if needed.
!    ..
50 ip(j) = lmax
    if (ip(j) .eq. j) go to 70
        do 60 i = 1,m
        tmp = a(i,j)
        a(i,j) = a(i,lmax)
60 a(i,lmax) = tmp
    h(lmax) = h(j)
!
!     Compute the j-TH transformation and apply it to A and b.
!    ..
70 call h12 (1,j,j+1,m,a(1,j),1,h(j),a(1,j+1),1,mda,n-j)
80 call h12 (2,j,j+1,m,a(1,j),1,h(j),b,1,mdb,nb)
!
!     Determine the pseudorank, k, using the tolerance, tau.
!     Also store the diagonal elements in the array d.
!    ..
    do 90 j = 1,ldiag
    if (abs(a(j,j)) .le. tau) go to 100
90 d(j) = a(j,j)
    k = ldiag
    kp1 = k + 1
    go to 110
!
100 k = j - 1
    kp1 = j
    do 105 j = kp1,ldiag
105 d(j) = a(j,j)
!
!     Compute the norms of the residual vectors.
!
110 if (nb .le. 0) go to 140
    do 130 jb = 1,nb
    tmp = 0.0
    if (kp1 .gt. m) go to 130
        do 120 i = kp1,m
120 tmp = tmp + b(i,jb)**2
130 rnorm(jb) = sqrt(tmp)
140 continue
!                                           SPECIAL FOR PSEUDORANK = 0
if (k .gt. 0) go to 160
if (nb .le. 0) go to 270
    do jb = 1,nb
        do 150 i = 1,n
150 b(i,jb) = 0.0
    end do
go to 270
!
!     If the pseudorank is less than n compute Householder
!     decomposition of first k rows.
!    ..
160 if (k .eq. n) go to 180
    do 170 ii = 1,k
    i = kp1 - ii
170 call h12 (1,i,kp1,n,a(i,1),mda,g(i),a,mda,1,i-1)
180 continue
!
!
if (nb .le. 0) go to 270
    do jb = 1,nb
!
!     Solve the k by k triangular system.
!    ..
        do 210 l = 1,k
        sm = 0.d0
        i = kp1 - l
        if (i .eq. k) go to 200
        ip1 = i + 1
            do 190 j = ip1,k
190 sm = sm + dble(a(i,j))*dble(b(j,jb))
200 sm1 = dble(b(i,jb)) - sm
210 b(i,jb)=sm1/a(i,i)
!
!     Complete computation of solution vector.
!    ..
    if (k .eq. n) go to 240
        do 220 j = kp1,n
220 b(j,jb) = 0.0
        do 230 i = 1,k
230 call h12 (2,i,kp1,n,a(i,1),mda,g(i),b(1,jb),1,mdb,1)
!
!      RE-order the solution vector to compensate for the
!      column interchanges.
!    ..
240 do 250 jj = 1,ldiag
        j = ldiag + 1 - jj
        if (ip(j) .eq. j) go to 250
        l = ip(j)
        tmp = b(l,jb)
        b(l,jb) = b(j,jb)
        b(j,jb) = tmp
250 continue
    end do
!    ..
!     The solution vectors, X, are now
!     in the first  n  rows of the array b(,).
!
270 ierr = 0
return
!
!     Error return
!
300 ierr = 1
return
310 ierr = 2
return
end subroutine hfti2

subroutine h12 (mode,lpivot,l1,m,u,iue,up,c,ice,icv,ncv)
implicit none
integer, intent(in) :: ice, icv, iue, l1, lpivot, m, mode, ncv
real, intent(inout) :: c(*), u(iue,m), up
integer :: i, i2, i3, i4, incr, j
real :: cl, d, sm1
!-----------------------------------------------------------------------
!     Written by C.L. Lawson and R.J. Hanson.  Modified by A.H. Morris.
!     From the book solving least squares problems, Prentice-Hall, 1974.
!
!     Construction and/or application of a single
!     HOUSEHOLDER TRANSFORMATION..     Q = i + u*(u**T)/b
!
!     mode    = 1 OR 2   TO SELECT ALGORITHM  H1  OR  H2 .
!     lpivot is the index of the pivot element.
!     l1,m   IF l1 .LE. m   THE TRANSFORMATION WILL BE CONSTRUCTED TO
!            ZERO ELEMENTS INDEXED FROM l1 THROUGH m.   IF l1 GT. m
!            the subroutine does an identity transformation.
!     u(),iue,UP    ON ENTRY TO H1 u() CONTAINS THE PIVOT VECTOR.
!                   iue is the storage increment between elements.
!                                       On exit from H1 u() and up
!                   contain quantities defining the vector u of the
!                   HOUSEHOLDER TRANSFORMATION.   ON ENTRY TO H2 u()
!                   and up should contain quantities previously computed
!                   by H1.  These will not be modified by H2.
!     c()    ON ENTRY TO H1 OR H2 c() CONTAINS A MATRIX WHICH WILL BE
!            regarded as a set of vectors to which the Householder
!            transformation is to be applied.  On exit c() contains the
!            set of transformed vectors.
!     ICE    STORAGE INCREMENT BETWEEN ELEMENTS OF VECTORS IN c().
!     icv    STORAGE INCREMENT BETWEEN VECTORS IN c().
!     ncv    NUMBER OF VECTORS IN c() TO BE TRANSFORMED. IF ncv .LE. 0
!            no operations will be done on c().
!-----------------------------------------------------------------------
double precision :: sm, b
!
if (0 .ge. lpivot .or. lpivot .ge. l1 .or. l1 .gt. m) return
cl = abs(u(1,lpivot))
if (mode .eq. 2) go to 60
!
!                            ****** CONSTRUCT THE TRANSFORMATION. ******
!
    do 10 j = l1,m
10 cl = amax1(abs(u(1,j)),cl)
if (cl .le. 0.0) go to 130
d = u(1,lpivot)/cl
sm = d*d
    do 20 j = l1,m
    d = u(1,j)/cl
20 sm = sm + dble(d*d)
!
sm1 = sm
cl = cl*sqrt(sm1)
if (u(1,lpivot) .gt. 0.0) cl = -cl
up = u(1,lpivot) - cl
u(1,lpivot) = cl
go to 70
!
!            ****** APPLY THE TRANSFORMATION  i+u*(u**T)/b  TO c. ******
!
60 if (cl) 130,130,70
70 if (ncv .le. 0) return
b = dble(up)*dble(u(1,lpivot))
!
!                       b  MUST BE NONPOSITIVE HERE.  IF b = 0., RETURN.
!
if (b .ge. 0.d0) go to 130
b = 1.d0/b
i2 = 1 - icv + ice*(lpivot - 1)
incr = ice*(l1 - lpivot)
    do 120 j = 1,ncv
    i2 = i2 + icv
    i3 = i2 + incr
    i4 = i3
    sm = dble(c(i2))*dble(up)
        do 90 i = l1,m
        sm = sm + dble(c(i3))*dble(u(1,i))
90 i3 = i3 + ice
    if (sm .eq. 0.d0) go to 120
    sm = sm*b
    c(i2) = c(i2) + sm*dble(up)
        do 110 i = l1,m
        c(i4) = c(i4) + sm*dble(u(1,i))
110 i4 = i4 + ice
120 continue
130 return
end subroutine h12

subroutine dhfti (a,mda,m,n,b,mdb,nb,tau,k,rnorm,h,g,ip)
implicit none
integer, intent(out) :: k
integer, intent(in) :: m, mda, mdb, n, nb
integer :: i, ii, ip1, j, jb, jj, kp1, l, ldiag, lmax
!-----------------------------------------------------------------------
!     double precision a(mda,n),(b(mdb,nb) or b(m))
!     double precision tau,rnorm(nb),h(n),g(n)
!     integer ip(n)
!
!     Written by C.L. Lawson and R.J. Hanson.
!     From the book solving least squares problems, Prentice-Hall, 1974.
!     For algorithmic details see algorithm hfti in chapter 14.
!
!     Abstract
!
!     This subroutine solves a linear least squares problem or a set of
!     linear least squares problems having the same matrix but different
!     right-side vectors.  The problem data consists of an m by n matrix
!     A, an m by nb matrix b, and an absolute tolerance parameter tau
!     whose usage is described below.  The nb column vectors of b
!     represent right-side vectors for nb distinct linear least squares
!     problems.
!
!     This set of problems can also be written as the matrix least
!     squares problem
!
!                       ax = b,
!
!     Where X is the n by nb solution matrix.
!
!     Note that if b is the m by m identity matrix, then X will be the
!     pseudo-inverse of A.
!
!     This subroutine first transforms the augmented matrix (A b) to A
!     matrix (R C) using premultiplying Householder transformations with
!     column interchanges.  All subdiagonal elements in the matrix R are
!     zero and its diagonal elements satisfy
!
!                       dabs(R(i,i)).GE.dabs(R(i+1,i+1)),
!
!                       i = 1,...,l-1, where
!
!                       l = min(m,n).
!
!     The subroutine sets k to be the number of diagonal elements
!     of R that exceed tau in magnitude. Then the solution of minimum
!     Euclidean length is computed using the first k rows of (R C).
!
!     To be specific we suggest that the user consider an easily
!     computable matrix NORM, such as, the maximum of all column sums of
!     magnitudes.
!
!     Now if the relative uncertainty of b is eps, (norm of uncertainty/
!     norm of b), it is suggested that tau be set approximately equal to
!     eps*(norm of A).
!
!     The entire set of parameters for dhfti are
!
!     Input..
!
!     a(*,*),mda,m,n    THE ARRAY a(*,*) INITIALLY CONTAINS THE m BY n
!                       MATRIX a OF THE LEAST SQUARES PROBLEM AX = b.
!                       The first dimensioning parameter of the array
!                       a(*,*) IS mda, WHICH MUST SATISFY mda.GE.m
!                       EITHER m.GE.n OR m.LT.n IS PERMITTED.  THERE
!                       is no restriction on the rank of A.  the
!                       CONDITION mda.LT.m IS CONSIDERED AN ERROR.
!
!     b(*),MDB,nb       IF nb = 0 THE SUBROUTINE WILL PERFORM THE
!                       orthogonal decomposition but will make no
!                       REFERENCES TO THE ARRAY b(*).  IF nb.GT.0
!                       the array b(*) must initially contain the m by
!                       nb MATRIX b OF THE LEAST SQUARES PROBLEM AX =
!                       b.  IF nb.GE.2 THE ARRAY b(*) MUST BE DOUBLY
!                       subscripted with first dimensioning parameter
!                       mdb.GE.max(m,n).  IF nb = 1 THE ARRAY b(*) MAY
!                       be either doubly or singly subscripted.  In
!                       the latter case the value of mdb is arbitrary
!                       but it should be set to some valid integer
!                       VALUE SUCH AS mdb = m.
!
!                       THE CONDITION OF nb.GT.1.AND.mdb.LT. max(m,n)
!                       is considered an error.
!
!     tau               ABSOLUTE TOLERANCE PARAMETER PROVIDED BY USER
!                       for pseudorank determination.
!
!     h(*),g(*),ip(*)   ARRAYS OF WORKING SPACE USED BY dhfti.
!
!     Output..
!
!     a(*,*)            THE CONTENTS OF THE ARRAY a(*,*) WILL BE
!                       modified by the subroutine.  These contents
!                       are not generally required by the user.
!
!     b(*)              ON RETURN THE ARRAY b(*) WILL CONTAIN THE n BY
!                       nb solution matrix X.
!
!     k                 SET BY THE SUBROUTINE TO INDICATE THE
!                       pseudorank of A.
!
!     rnorm(*)          ON RETURN, rnorm(j) WILL CONTAIN THE EUCLIDEAN
!                       norm of the residual vector for the problem
!                       defined by the j-TH column vector of the array
!                       b(*,*) FOR j = 1,...,nb.
!
!     h(*),g(*)         ON RETURN THESE ARRAYS RESPECTIVELY CONTAIN
!                       elements of the pre- and post-multiplying
!                       Householder transformations used to compute
!                       the minimum Euclidean length solution.
!
!     ip(*)             ARRAY IN WHICH THE SUBROUTINE RECORDS INDICES
!                       describing the permutation of column vectors.
!                       The contents of arrays h(*),g(*) and ip(*)
!                       are not generally required by the user.
!-----------------------------------------------------------------------
double precision, intent(inout) :: a(mda,n), b(mdb,*)
double precision, intent(in) :: tau
double precision, intent(inout) :: rnorm(*), h(n), g(n)
integer, intent(inout) :: ip(n)
double precision :: factor, hmax, sm, sm1, tmp, z
!---------------------
data factor /1.d-3/
!
k = 0
ldiag = min0(m,n)
if (ldiag .le. 0) go to 270
    do 80 j = 1,ldiag
    if (j .eq. 1) go to 20
!
!     Update squared column lengths and find lmax
!    ..
    lmax = j
        do l = j,n
        h(l) = h(l) - a(j-1,l)**2
        if (h(l) .gt. h(lmax)) lmax = l
        end do
    z = hmax + factor*h(lmax)
    if (z .gt. hmax) go to 50
!
!     Compute squared column lengths and find lmax
!    ..
20 lmax=j
        do l = j,n
        h(l) = 0.d0
            do 30 i = j,m
30 h(l) = h(l) + a(i,l)**2
        if (h(l) .gt. h(lmax)) lmax = l
        end do
    hmax = h(lmax)
!    ..
!     lmax has been determined
!
!     Do column interchanges if needed.
!    ..
50 ip(j) = lmax
    if (ip(j) .eq. j) go to 70
        do 60 i = 1,m
        tmp = a(i,j)
        a(i,j) = a(i,lmax)
60 a(i,lmax) = tmp
    h(lmax) = h(j)
!
!     Compute the j-TH transformation and apply it to A and b.
!    ..
70 call dh12 (1,j,j+1,m,a(1,j),1,h(j),a(1,j+1),1,mda,n-j)
80 call dh12 (2,j,j+1,m,a(1,j),1,h(j),b,1,mdb,nb)
!
!     Determine the pseudorank, k, using the tolerance, tau.
!    ..
    do j = 1,ldiag
    if (dabs(a(j,j)) .le. tau) go to 100
    end do
k = ldiag
go to 110
100 k = j - 1
110 kp1 = k + 1
!
!     Compute the norms of the residual vectors.
!
if (nb .le. 0) go to 140
    do 130 jb = 1,nb
    tmp = 0.d0
    if (kp1 .gt. m) go to 130
        do 120 i = kp1,m
120 tmp = tmp + b(i,jb)**2
130 rnorm(jb) = dsqrt(tmp)
140 continue
!                                           SPECIAL FOR PSEUDORANK = 0
if (k .gt. 0) go to 160
if (nb .le. 0) go to 270
    do jb = 1,nb
        do 150 i = 1,n
150 b(i,jb) = 0.d0
    end do
go to 270
!
!     If the pseudorank is less than n compute Householder
!     decomposition of first k rows.
!    ..
160 if (k .eq. n) go to 180
    do 170 ii = 1,k
    i = kp1 - ii
170 call dh12 (1,i,kp1,n,a(i,1),mda,g(i),a,mda,1,i-1)
180 continue
!
!
if (nb .le. 0) go to 270
    do jb = 1,nb
!
!     Solve the k by k triangular system.
!    ..
        do 210 l = 1,k
        sm = 0.d0
        i = kp1 - l
        if (i .eq. k) go to 200
        ip1 = i + 1
            do 190 j = ip1,k
190 sm = sm + a(i,j)*b(j,jb)
200 sm1 = b(i,jb) - sm
210 b(i,jb) = sm1/a(i,i)
!
!     Complete computation of solution vector.
!    ..
    if (k .eq. n) go to 240
        do 220 j = kp1,n
220 b(j,jb) = 0.d0
        do 230 i = 1,k
230 call dh12 (2,i,kp1,n,a(i,1),mda,g(i),b(1,jb),1,mdb,1)
!
!      RE-order the solution vector to compensate for the
!      column interchanges.
!    ..
240 do 250 jj = 1,ldiag
        j = ldiag + 1 - jj
        if (ip(j) .eq. j) go to 250
        l = ip(j)
        tmp = b(l,jb)
        b(l,jb) = b(j,jb)
        b(j,jb) = tmp
250 continue
    end do
!    ..
!     The solution vectors, X, are now
!     in the first  n  rows of the array b(,).
!
270 return
end subroutine dhfti

subroutine dhfti2(a,mda,m,n,b,mdb,nb,d,tau,k,rnorm,h,g,ip,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(out) :: k
integer, intent(in) :: m, mda, mdb, n, nb
integer :: i, ii, ip1, j, jb, jj, kp1, l, ldiag, lmax
!-----------------------------------------------------------------------
!     double precision a(mda,n),(b(mdb,nb) or b(m))
!     double precision d(l) where l = min(m,n)
!     double precision tau,rnorm(nb),h(n),g(n)
!     integer ip(n)
!
!     Written by C.L. Lawson and R.J. Hanson. Modified by A.H. Morris.
!     From the book solving least squares problems, Prentice-Hall, 1974.
!     For algorithmic details see algorithm hfti in chapter 14.
!
!     Abstract
!
!     This subroutine solves a linear least squares problem or a set of
!     linear least squares problems having the same matrix but different
!     right-side vectors.  The problem data consists of an m by n matrix
!     A, an m by nb matrix b, and an absolute tolerance parameter tau
!     whose usage is described below.  The nb column vectors of b
!     represent right-side vectors for nb distinct linear least squares
!     problems.
!
!     This set of problems can also be written as the matrix least
!     squares problem
!
!                       ax = b,
!
!     Where X is the n by nb solution matrix.
!
!     Note that if b is the m by m identity matrix, then X will be the
!     pseudo-inverse of A.
!
!     This subroutine first transforms the augmented matrix (A b) to A
!     matrix (R C) using premultiplying Householder transformations with
!     column interchanges.  All subdiagonal elements in the matrix R are
!     zero and its diagonal elements satisfy
!
!                       dabs(R(i,i)).GE.dabs(R(i+1,i+1)),
!
!                       i = 1,...,l-1, where
!
!                       l = min(m,n).
!
!     The array d will contain the diagonal elements R(1,1),...,R(l,l).
!     The subroutine sets k to be the number of diagonal elements that
!     exceed tau in magnitude.  Then the solution of minimum Euclidean
!     length is computed using the first k rows of (R C).
!
!     To be specific we suggest that the user consider an easily
!     computable matrix NORM, such as, the maximum of all column sums of
!     magnitudes.
!
!     Now if the relative uncertainty of b is eps, (norm of uncertainty/
!     norm of b), it is suggested that tau be set approximately equal to
!     eps*(norm of A).
!
!     The entire set of parameters for dhfti2 are
!
!     Input..
!
!     a(*,*),mda,m,n    THE ARRAY a(*,*) INITIALLY CONTAINS THE m BY n
!                       MATRIX a OF THE LEAST SQUARES PROBLEM AX = b.
!                       The first dimensioning parameter of the array
!                       a(*,*) IS mda, WHICH MUST SATISFY mda.GE.m
!                       EITHER m.GE.n OR m.LT.n IS PERMITTED.  THERE
!                       is no restriction on the rank of A.  the
!                       CONDITION mda.LT.m IS CONSIDERED AN ERROR.
!
!     b(*),MDB,nb       IF nb = 0 THE SUBROUTINE WILL PERFORM THE
!                       orthogonal decomposition but will make no
!                       REFERENCES TO THE ARRAY b(*).  IF nb.GT.0
!                       the array b(*) must initially contain the m by
!                       nb MATRIX b OF THE LEAST SQUARES PROBLEM AX =
!                       b.  IF nb.GE.2 THE ARRAY b(*) MUST BE DOUBLY
!                       subscripted with first dimensioning parameter
!                       mdb.GE.max(m,n).  IF nb = 1 THE ARRAY b(*) MAY
!                       be either doubly or singly subscripted.  In
!                       the latter case the value of mdb is arbitrary
!                       but it should be set to some valid integer
!                       VALUE SUCH AS mdb = m.
!
!                       THE CONDITION OF nb.GT.1.AND.mdb.LT. max(m,n)
!                       is considered an error.
!
!     tau               ABSOLUTE TOLERANCE PARAMETER PROVIDED BY USER
!                       for pseudorank determination.
!
!     h(*),g(*),ip(*)   ARRAYS OF WORKING SPACE USED BY dhfti2.
!
!     Output..
!
!     a(*,*)            THE CONTENTS OF THE ARRAY a(*,*) WILL BE
!                       modified by the subroutine.  These contents
!                       are not generally required by the user.
!
!     b(*)              ON RETURN THE ARRAY b(*) WILL CONTAIN THE n BY
!                       nb solution matrix X.
!
!     d(*)              THE ARRAY OF DIAGONAL ELEMENTS OF THE
!                       triangular matrix R
!
!     k                 SET BY THE SUBROUTINE TO INDICATE THE
!                       pseudorank of A.
!
!     rnorm(*)          ON RETURN, rnorm(j) WILL CONTAIN THE EUCLIDEAN
!                       norm of the residual vector for the problem
!                       defined by the j-TH column vector of the array
!                       b(*,*) FOR j = 1,...,nb.
!
!     h(*),g(*)         ON RETURN THESE ARRAYS RESPECTIVELY CONTAIN
!                       elements of the pre- and post-multiplying
!                       Householder transformations used to compute
!                       the minimum Euclidean length solution.
!
!     ip(*)             ARRAY IN WHICH THE SUBROUTINE RECORDS INDICES
!                       describing the permutation of column vectors.
!                       The contents of arrays h(*),g(*) and ip(*)
!                       are not generally required by the user.
!
!     ierr              ERROR INDICATOR. IF NO INPUT ERRORS ARE
!                       detected then ierr is set to 0. Otherwise
!                          ierr = 1  IF mda.LT.m
!                          ierr = 2  IF nb.GT.1 AND mdb.LT.max(m,n)
!                       these errors are fatal.
!-----------------------------------------------------------------------
double precision, intent(inout) :: a(mda,n), b(mdb,*), d(*)
double precision, intent(in) :: tau
double precision, intent(inout) :: rnorm(*), h(n), g(n)
integer, intent(inout) :: ip(n)
double precision :: factor, hmax, sm, sm1, tmp, z
!---------------------
data factor /1.d-3/
!
k = 0
ldiag = min0(m,n)
if (ldiag .le. 0) go to 270
if (m .gt. mda) go to 300
if (nb .gt. 1 .and. max0(m,n) .gt. mdb) go to 310
!
    do 80 j = 1,ldiag
    if (j .eq. 1) go to 20
!
!     Update squared column lengths and find lmax
!    ..
    lmax = j
        do l = j,n
        h(l) = h(l) - a(j-1,l)**2
        if (h(l) .gt. h(lmax)) lmax = l
        end do
    z = hmax + factor*h(lmax)
    if (z .gt. hmax) go to 50
!
!     Compute squared column lengths and find lmax
!    ..
20 lmax = j
        do l = j,n
        h(l) = 0.d0
            do 30 i = j,m
30 h(l) = h(l) + a(i,l)**2
        if (h(l) .gt. h(lmax)) lmax = l
        end do
    hmax = h(lmax)
!    ..
!     lmax has been determined
!
!     Do column interchanges if needed.
!    ..
50 ip(j) = lmax
    if (ip(j) .eq. j) go to 70
        do 60 i = 1,m
        tmp = a(i,j)
        a(i,j) = a(i,lmax)
60 a(i,lmax) = tmp
    h(lmax) = h(j)
!
!     Compute the j-TH transformation and apply it to A and b.
!    ..
70 call dh12 (1,j,j+1,m,a(1,j),1,h(j),a(1,j+1),1,mda,n-j)
80 call dh12 (2,j,j+1,m,a(1,j),1,h(j),b,1,mdb,nb)
!
!     Determine the pseudorank, k, using the tolerance, tau.
!     Also store the diagonal elements in the array d.
!    ..
    do 90 j = 1,ldiag
    if (dabs(a(j,j)) .le. tau) go to 100
90 d(j) = a(j,j)
    k = ldiag
    kp1 = k + 1
    go to 110
!
100 k = j - 1
    kp1 = j
    do 105 j = kp1,ldiag
105 d(j) = a(j,j)
!
!     Compute the norms of the residual vectors.
!
110 if (nb .le. 0) go to 140
    do 130 jb = 1,nb
    tmp = 0.d0
    if (kp1 .gt. m) go to 130
        do 120 i = kp1,m
120 tmp = tmp + b(i,jb)**2
130 rnorm(jb) = dsqrt(tmp)
140 continue
!                                           SPECIAL FOR PSEUDORANK = 0
if (k .gt. 0) go to 160
if (nb .le. 0) go to 270
    do jb = 1,nb
        do 150 i = 1,n
150 b(i,jb) = 0.d0
    end do
go to 270
!
!     If the pseudorank is less than n compute Householder
!     decomposition of first k rows.
!    ..
160 if (k .eq. n) go to 180
    do 170 ii = 1,k
    i = kp1 - ii
170 call dh12 (1,i,kp1,n,a(i,1),mda,g(i),a,mda,1,i-1)
180 continue
!
!
if (nb .le. 0) go to 270
    do jb = 1,nb
!
!     Solve the k by k triangular system.
!    ..
        do 210 l = 1,k
        sm = 0.d0
        i = kp1 - l
        if (i .eq. k) go to 200
        ip1 = i + 1
            do 190 j = ip1,k
190 sm = sm + a(i,j)*b(j,jb)
200 sm1 = b(i,jb) - sm
210 b(i,jb)=sm1/a(i,i)
!
!     Complete computation of solution vector.
!    ..
    if (k .eq. n) go to 240
        do 220 j = kp1,n
220 b(j,jb) = 0.d0
        do 230 i = 1,k
230 call dh12 (2,i,kp1,n,a(i,1),mda,g(i),b(1,jb),1,mdb,1)
!
!      RE-order the solution vector to compensate for the
!      column interchanges.
!    ..
240 do 250 jj = 1,ldiag
        j = ldiag + 1 - jj
        if (ip(j) .eq. j) go to 250
        l = ip(j)
        tmp = b(l,jb)
        b(l,jb) = b(j,jb)
        b(j,jb) = tmp
250 continue
    end do
!    ..
!     The solution vectors, X, are now
!     in the first  n  rows of the array b(,).
!
270 ierr = 0
return
!
!     Error return
!
300 ierr = 1
return
310 ierr = 2
return
end subroutine dhfti2

subroutine dh12 (mode,lpivot,l1,m,u,iue,up,c,ice,icv,ncv)
implicit none
integer, intent(in) :: ice, icv, iue, l1, lpivot, m, mode, ncv
integer :: i, i2, i3, i4, incr, j
!-----------------------------------------------------------------------
!     Written by C.L. Lawson and R.J. Hanson.  Modified by A.H. Morris.
!     From the book solving least squares problems, Prentice-Hall, 1974.
!
!     Construction and/or application of a single
!     HOUSEHOLDER TRANSFORMATION..     Q = i + u*(u**T)/b
!
!     mode    = 1 OR 2   TO SELECT ALGORITHM  H1  OR  H2 .
!     lpivot is the index of the pivot element.
!     l1,m   IF l1 .LE. m   THE TRANSFORMATION WILL BE CONSTRUCTED TO
!            ZERO ELEMENTS INDEXED FROM l1 THROUGH m.   IF l1 GT. m
!            the subroutine does an identity transformation.
!     u(),iue,UP    ON ENTRY TO H1 u() CONTAINS THE PIVOT VECTOR.
!                   iue is the storage increment between elements.
!                                       On exit from H1 u() and up
!                   contain quantities defining the vector u of the
!                   HOUSEHOLDER TRANSFORMATION.   ON ENTRY TO H2 u()
!                   and up should contain quantities previously computed
!                   by H1.  These will not be modified by H2.
!     c()    ON ENTRY TO H1 OR H2 c() CONTAINS A MATRIX WHICH WILL BE
!            regarded as a set of vectors to which the Householder
!            transformation is to be applied.  On exit c() contains the
!            set of transformed vectors.
!     ICE    STORAGE INCREMENT BETWEEN ELEMENTS OF VECTORS IN c().
!     icv    STORAGE INCREMENT BETWEEN VECTORS IN c().
!     ncv    NUMBER OF VECTORS IN c() TO BE TRANSFORMED. IF ncv .LE. 0
!            no operations will be done on c().
!-----------------------------------------------------------------------
double precision, intent(inout) :: u(iue,m), up, c(*)
double precision :: b, cl, d, sm
!
if (0 .ge. lpivot .or. lpivot .ge. l1 .or. l1 .gt. m) return
cl = dabs(u(1,lpivot))
if (mode .eq. 2) go to 60
!
!                            ****** CONSTRUCT THE TRANSFORMATION. ******
!
    do 10 j = l1,m
10 cl = dmax1(dabs(u(1,j)),cl)
if (cl .le. 0.d0) go to 130
d = u(1,lpivot)/cl
sm = d*d
    do 20 j = l1,m
    d = u(1,j)/cl
20 sm = sm + d*d
!
cl = cl*dsqrt(sm)
if (u(1,lpivot) .gt. 0.d0) cl = -cl
up = u(1,lpivot) - cl
u(1,lpivot) = cl
go to 70
!
!            ****** APPLY THE TRANSFORMATION  i+u*(u**T)/b  TO c. ******
!
60 if (cl) 130,130,70
70 if (ncv .le. 0) return
b = up*u(1,lpivot)
!
!                       b  MUST BE NONPOSITIVE HERE.  IF b = 0., RETURN.
!
if (b .ge. 0.d0) go to 130
b = 1.d0/b
i2 = 1 - icv + ice*(lpivot - 1)
incr = ice*(l1 - lpivot)
    do 120 j = 1,ncv
    i2 = i2 + icv
    i3 = i2 + incr
    i4 = i3
    sm = c(i2)*up
        do 90 i = l1,m
        sm = sm + c(i3)*u(1,i)
90 i3 = i3 + ice
    if (sm .eq. 0.d0) go to 120
    sm = sm*b
    c(i2) = c(i2) + sm*up
        do 110 i = l1,m
        c(i4) = c(i4) + sm*u(1,i)
110 i4 = i4 + ice
120 continue
130 return
end subroutine dh12

subroutine lsei(w, mdw, me, ma, mg, n, prgopt, x, rnorme, rnorml, &
&mode, ws, ip)
implicit none
integer, intent(in) :: ma, mdw, me, mg
integer, intent(out) :: mode
integer :: n
real, intent(inout) :: rnorme, rnorml
integer :: i, ii, imax, j, jj, jp1, k, key, kk, kranke, l, last, &
&link, m, mapke1, mdeqc, mend, mep1, n1, n2, next, nlink, nopt, &
&np1, ntimes
real :: enorm, fnorm, gam, half, one, rb, rn, rnmax, size, sn, &
&snmax, srelpr, t, tau, uj, up, vj, xnorm, xnrme, zero
real :: snrm2
real :: sasum
real :: sdot
real :: spmpar
!
!     dimension w(mdw,n+1),prgopt(*),x(n),
!     ws(2*(me+n)+k+(mg+2)*(n+7)),ip(mg+2*n+2)
!     ABOVE, k=max(ma+mg,n).
!
!     Written by R. J. Hanson and K. H. Haskell.  For further math.
!     And algorithmic details see Sandia Laboratories tech. REPTS.
!     SAND77-0552, (1978), and SAND78-1290, (1979), and math.
!     Programming (21), 1981, PP. 98-118. modified by A.H. Morris.
!
!     Abstract
!
!     This subprogram solves a linearly constrained least squares
!     problem with both equality and inequality constraints, and, if the
!     user requests, obtains a covariance matrix of the solution
!     parameters.
!
!     Suppose there are given matrices E, A and G of respective
!     dimensions me by n, ma by n and mg by n, and vectors F, B and H of
!     respective lengths me, ma and mg.  This subroutine solves the
!     linearly constrained least squares problem
!
!                   EX = F, (E ME BY n) (EQUATIONS TO BE EXACTLY
!                                       satisfied)
!                   AX = B, (A ma BY n) (EQUATIONS TO BE
!                                       approximately satisfied,
!                                       least squares sense)
!                   GX.GE.H,(G mg BY n) (INEQUALITY CONSTRAINTS)
!
!     THE INEQUALITIES GX.GE.H MEAN THAT EVERY COMPONENT OF THE PRODUCT
!     GX MUST BE .GE. THE CORRESPONDING COMPONENT OF H.
!
!     In case the equality constraints cannot be satisfied, A
!     generalized inverse solution residual vector LENGTH is obtained
!     for F-EX. This is the minimal length possible for F-EX.
!
!
!     ANY VALUES me.GE.0, ma.GE.0, OR mg.GE.0 ARE PERMITTED.  THE
!     rank of the matrix E is estimated during the computation. We call
!     this value kranke. It is an output parameter in ip(1) defined
!     BELOW. USING A GENERALIZED INVERSE SOLUTION OF EX=F, A REDUCED
!     least squares problem with inequality constraints is obtained.
!     The tolerances used in these tests for determining the rank
!     of E and the rank of the reduced least squares problem are
!     given in sandia tech. Rept. SAND78-1290. They can be
!     modified by the user if new values are provided in
!     the option list of the array prgopt(*).
!
!     The user must dimension all arrays appearing in the call list..
!     w(mdw,n+1),prgopt(*),x(n),ws(2*(me+n)+k+(mg+2)*(n+7)),ip(mg+2*n+2)
!     WHERE k=max(ma+mg,n).  THIS ALLOWS FOR A SOLUTION OF A RANGE OF
!     problems in the given working space.  The dimension of ws(*)
!     given is a necessary overestimate.  Once a particular problem
!     has been run, the output parameter ip(3) gives the actual
!     dimension required for that problem.
!
!     The parameters for lsei( ) are
!
!     Input..
!
!     w(*,*),mdw,   THE ARRAY w(*,*) IS DOUBLY SUBSCRIPTED WITH
!     ME,ma,mg,n    FIRST DIMENSIONING PARAMETER EQUAL TO mdw.
!                   FOR THIS DISCUSSION LET US CALL M = me+ma+mg.  THEN
!                   mdw MUST SATISFY mdw.GE.M.  THE CONDITION
!                   mdw.LT.M IS AN ERROR.
!
!                   The array w(*,*) contains the matrices and vectors
!
!                                  (E  F)
!                                  (A  B)
!                                  (G  H)
!
!                   In rows and columns 1,...,M and 1,...,n+1
!                   respectively.
!
!                   The integers me, ma, and mg are the
!                   respective matrix ROW dimensions
!                   of E, A and G. each matrix HAS n columns.
!
!     prgopt(*)    THIS REAL-VALUED ARRAY IS THE OPTION VECTOR.
!                  If the user is satisfied with the nominal
!                  subprogram features set
!
!                  prgopt(1)=1 (OR prgopt(1)=1.0)
!
!                  Otherwise prgopt(*) is a linked list consisting of
!                  groups of data of the following form
!
!                  Link
!                  key
!                  data set
!
!                  The parameters link and key are each one word.
!                  The data set can be comprised of several words.
!                  The number of items depends on the value of key.
!                  The value of link points to the first
!                  entry of the next group of data within
!                  prgopt(*).  The exception is when there are
!                  no more options to change.  In that
!                  CASE LINK=1 AND THE VALUES KEY AND DATA SET
!                  are not referenced. The general layout of
!                  prgopt(*) is as follows.
!
!               ...prgopt(1)=LINK1 (LINK TO FIRST ENTRY OF NEXT GROUP)
!               .  prgopt(2)=KEY1 (KEY TO THE OPTION CHANGE)
!               .  prgopt(3)=DATA VALUE (DATA VALUE FOR THIS CHANGE)
!               .       .
!               .       .
!               .       .
!               ...prgopt(LINK1)=LINK2 (LINK TO THE FIRST ENTRY OF
!               .                       NEXT GROUP)
!               .  prgopt(LINK1+1)=KEY2 (KEY TO THE OPTION CHANGE)
!               .  prgopt(LINK1+2)=DATA VALUE
!               ...     .
!               .       .
!               .       .
!               ...prgopt(LINK)=1 (NO MORE OPTIONS TO CHANGE)
!
!                  Values of link that are nonpositive are errors.
!                  A VALUE OF LINK.GT.NLINK=100000 IS ALSO AN ERROR.
!                  This helps prevent using invalid but positive
!                  values of link that will probably extend
!                  beyond the program limits of prgopt(*).
!                  Unrecognized values of key are ignored.  The
!                  order of the options is arbitrary and any number
!                  of options can be changed with the following
!                  restriction.  To prevent cycling in the
!                  processing of the option array A count of the
!                  number of options changed is maintained.
!                  WHENEVER THIS COUNT EXCEEDS NOPT=1000 THE
!                  routine terminates.
!
!                  Options..
!
!                  key=1
!                         compute in w(*,*) the n by n
!                  covariance matrix of the solution variables
!                  as an output paramter.  Nominally the
!                  covariance matrix will not be computed.
!                  (This requires no user input.)
!                  the data set for this option is a single value.
!                  It must be nonzero when the covariance matrix
!                  is desired.  If it is zero, the covariance
!                  matrix is not computed.  When the covariance matrix
!                  is computed, the first dimensioning parameter
!                  OF THE ARRAY w(*,*) MUST SATISFY mdw.GE.MAX0(M,n).
!
!                  key=2
!                         scale the nonzero columns of the
!                         entire data matrix.
!                  (E)
!                  (A)
!                  (G)
!
!                  To have length one.  The data set for this
!                  option is a single value.  It must be
!                  nonzero if unit length column scaling
!                  is desired.
!
!                  key=3
!                         scale columns of the entire data matrix
!                  (E)
!                  (A)
!                  (G)
!
!                  With a user-provided diagonal matrix.
!                  The data set for this option consists
!                  of the n diagonal scaling factors, one for
!                  each matrix column.
!
!                  key=4
!                         change the rank determination tolerance for
!                  the equality constraint equations from
!                  the nominal value of sqrt(SRELPR).  This quantity
!                  can be no smaller than SRELPR, the arithmetic-
!                  storage precision.  The quantity SRELPR is the
!                  LARGEST POSITIVE NUMBER SUCH THAT T=1.+SRELPR
!                  SATISFIES T.EQ.1.  THE QUANTITY USED
!                  here is internally restricted to be at
!                  least SRELPR.  The data set for this option
!                  is the new tolerance.
!
!                  key=5
!                         change the rank determination tolerance for
!                  the reduced least squares equations from
!                  the nominal value of sqrt(SRELPR).  This quantity
!                  can be no smaller than SRELPR, the arithmetic-
!                  storage precision.  The quantity used
!                  here is internally restricted to be at
!                  least SRELPR.  The data set for this option
!                  is the new tolerance.
!
!                  For example, suppose we want to change
!                  the tolerance for the reduced least squares
!                  problem, compute the covariance matrix of
!                  the solution parameters, and provide
!                  column scaling for the data matrix.  For
!                  these options the dimension of prgopt(*)
!                  must be at least n+9.  The Fortran statements
!                  defining these options would be as follows.
!
!                  prgopt(1)=4 (LINK TO ENTRY 4 IN prgopt(*))
!                  prgopt(2)=1 (COVARIANCE MATRIX key)
!                  prgopt(3)=1 (COVARIANCE MATRIX WANTED)
!
!                  prgopt(4)=7 (LINK TO ENTRY 7 IN prgopt(*))
!                  prgopt(5)=5 (LEAST SQUARES EQUAS. TOLERANCE KEY)
!                  prgopt(6)=... (NEW VALUE OF THE TOLERANCE)
!
!                  prgopt(7)=n+9 (LINK TO ENTRY n+9 IN prgopt(*))
!                  prgopt(8)=3 (USER-PROVIDED COLUMN SCALING KEY)
!
!                  call scopy(n,d,1,prgopt(9),1)  (copy the n
!                    scaling factors from the user array D(*)
!                    TO prgopt(9)-prgopt(n+8))
!
!                  prgopt(n+9)=1 (NO MORE OPTIONS TO CHANGE)
!
!                  The contents of prgopt(*) are not modified
!                  by the subprogram.
!                  The key 8 and 9 options for wnnls( ) can also
!                  be included in this array.  Their functions
!                  are documented in the usage instructions for
!                  SUBPROGRAM wnnls( ).
!
!     Output..
!
!     x(*),rnorme,  the array x(*) contains the solution parameters
!     rnorml        IF THE INTEGER OUTPUT FLAG mode = 0 OR 1.
!                   The definition of mode is given directly below.
!                   WHEN mode = 0 OR 1, rnorme AND rnorml
!                   respectively contain the residual vector
!                   Euclidean lengths of F - EX and B - AX.  When
!                   mode=1 THE EQUALITY CONSTRAINT EQUATIONS EX=F
!                   ARE CONTRADICTORY, SO rnorme.NE.0. THE RESIDUAL
!                   vector F-EX has minimal Euclidean length. For
!                   mode.GE.2, NONE OF THESE PARAMETERS ARE
!                   defined.
!
!     MODE          INTEGER FLAG THAT INDICATES THE SUBPROGRAM
!                   STATUS AFTER COMPLETION.  IF mode.GE.2, NO
!                   solution has been computed.
!
!                   mode =
!
!                   0  Both equality and inequality constraints
!                      are compatible and have been satisfied.
!
!                   1  Equality constraints are contradictory.
!                      A GENERALIZED INVERSE SOLUTION OF EX=F WAS USED
!                      to minimize the residual vector LENGTH F-EX.
!                      In this sense, the solution is still meaningful.
!
!                   2  No solution could be obtained. The constraints
!                      are contradictory.
!
!                   4  Usage error occurred.  The value
!                      OF mdw IS .LT. me+ma+mg, mdw IS
!                      .LT. n AND A COVARIANCE MATRIX IS
!                      requested, or the option vector
!                      prgopt(*) is not properly defined.
!
!     w(*,*)        THE ARRAY w(*,*) CONTAINS THE n BY n SYMMETRIC
!                   covariance matrix of the solution parameters,
!                   provided this was requested on input with
!                   the option vector prgopt(*) and the output
!                   FLAG IS RETURNED WITH mode = 0 OR 1.
!
!     ip(*)         THE INTEGER WORKING ARRAY HAS THREE ENTRIES
!                   that provide rank and working array LENGTH
!                   information after completion.
!
!                      ip(1) = RANK OF EQUALITY CONSTRAINT
!                              matrix.  Define this quantity
!                              AS kranke.
!
!                      ip(2) = RANK OF REDUCED LEAST SQUARES
!                              problem.
!
!                      ip(3) = THE AMOUNT OF STORAGE IN THE
!                              working array ws(*) that was
!                              actually used by the subprogram.
!                              The formula given above for the length
!                              of ws(*) is a necessary overestimate.
!     User designated
!     working arrays..
!
!     ws(*),ip(*)              THESE ARE RESPECTIVELY TYPE REAL
!                              and type integer working arrays.
!                              Their required minimal lengths are
!                              given above.
!
!
!     Subroutines called
!
!     lsi           PART OF THIS PACKAGE.  SOLVES A
!                   constrained least squares problem with
!                   inequality constraints.
!
!     sdot,sscal,   SUBROUTINES FROM THE BLAS PACKAGE.
!     saxpy,sasum,  see trans. Math software (5), P. 308.
!     scopy,snrm2,
!     sswap,isamax
!
!     h12           SUBROUTINE TO CONSTRUCT AND APPLY A
!                   Householder transformation.
!
!     spmpar        FUNCTION TO COMPUTE THE RELATIVE MACHINE
!                   precision.
!
!     Revised oct. 1, 1989.
!
real, intent(inout) :: w(mdw,*)
real, intent(in) :: prgopt(*)
real, intent(inout) :: x(*), ws(*)
integer, intent(inout) :: ip(*)
logical :: cov
data zero /0.e0/, one /1.e0/, half /0.5e0/
!
!     Compute machine precision
!
srelpr = spmpar(1)
!
!     Compute number of possible right multiplying Householder
!     transformations.
!
m = me + ma + mg
mode = 0
if (n .le. 0 .or. me + ma .le. 0) return
if (.not.(mdw.lt.m)) go to 80
mode = 4
return
80 np1 = n + 1
kranke = min0(me,n)
n1 = 2*kranke + 1
n2 = n1 + n
!
!     Process-option-vector
!
go to 480
90 if (.not.(cov .and. mdw.lt.n)) go to 100
mode = 4
return
100 l = kranke
!
!     Compute norm of equality constraint matrix and RT side.
!
enorm = zero
do j = 1,n
  enorm = amax1(enorm,sasum(me,w(1,j),1))
end do
fnorm = sasum(me,w(1,np1),1)
if (.not.(l.gt.0)) go to 200
snmax = zero
rnmax = zero
do 180 i = 1,l
!
!     Compute maximum ratio of vector lengths. Partition
!     is at col. i.
  do 150 k = i,me
     sn = sdot(n-i+1,w(k,i),mdw,w(k,i),mdw)
     rn = sdot(i-1,w(k,1),mdw,w(k,1),mdw)
     if (.not.(rn.eq.zero .and. sn.gt.snmax)) go to 120
     snmax = sn
     imax = k
     go to 150
120 if (.not.(k.eq.i .or. (sn*rnmax.gt.rn*snmax))) go to 150
     snmax = sn
     rnmax = rn
     imax = k
150 continue
!
!     Interchange rows if necessary.
  if (i.ne.imax) call sswap(np1, w(i,1), mdw, w(imax,1), mdw)
  if (.not.(snmax.gt.tau**2*rnmax)) go to 160
!
!     Eliminate elems i+1,...,n in row i.
  call h12(1, i, i+1, n, w(i,1), mdw, ws(i), w(i+1,1), mdw, 1, &
&m-i)
  go to 180
160 kranke = i - 1
  go to 200
180 continue
!
!     Save diag. Terms of lower trap. Matrix.
!
200 call scopy(kranke, w, mdw+1, ws(kranke+1), 1)
!
!     Use Householder trans from left to achieve kranke by kranke upper
!     triangular form.
!
if (.not.(kranke.gt.0 .and. kranke.lt.me)) go to 220
do kk = 1,kranke
  k = kranke + 1 - kk
!
!     Apply tranformation to matrix cols. 1,...,k-1.
  call h12(1, k, kranke+1, me, w(1,k), 1, up, w, 1, mdw, k-1)
!
!     Apply to RT side vector.
  call h12(2, k, kranke+1, me, w(1,k), 1, up, w(1,np1), 1, 1, 1)
end do
220 if (.not.(kranke.gt.0)) go to 240
!
!     Solve for variables 1,...,kranke in new coordinates.
call scopy(kranke, w(1,np1), 1, x, 1)
do i=1,kranke
  x(i) = (x(i)-sdot(i-1,w(i,1),mdw,x,1))/w(i,i)
end do
!
!     Compute residuals for reduced problem.
!
240 mep1 = me + 1
rnorml = zero
if (.not.(me.lt.m)) go to 270
do 260 i = mep1,m
  w(i,np1) = w(i,np1) - sdot(kranke,w(i,1),mdw,x,1)
  sn = sdot(kranke,w(i,1),mdw,w(i,1),mdw)
  rn = sdot(n-kranke,w(i,kranke+1),mdw,w(i,kranke+1),mdw)
  if (.not.(rn.le.tau**2*sn .and. kranke.lt.n)) go to 260
  w(i,kranke+1) = zero
  call scopy(n-kranke, w(i,kranke+1), 0, w(i,kranke+1), mdw)
260 continue
!
!     Compute equal. Constraint equas. Residual length.
270 rnorme = snrm2(me-kranke,w(kranke+1,np1),1)
!
!     MOVE REDUCED PROBLEM DATA UPWARD IF kranke.LT.ME.
!
if (.not.(kranke.lt.me)) go to 290
do j=1,np1
  call scopy(m-me, w(me+1,j), 1, w(kranke+1,j), 1)
end do
!
!     Compute soln of reduced problem.
!
290 call lsi(w(kranke+1,kranke+1), mdw, ma, mg, n-kranke, prgopt, &
&x(kranke+1), rnorml, mode, ws(n2), ip(2))
if (mode .gt. 1) go to 470
if (.not.(me.gt.0)) go to 330
!
!     Test for consistency of equality constraints.
!
mdeqc = 0
xnrme = sasum(kranke,w(1,np1),1)
if (rnorme.gt.tau*(enorm*xnrme+fnorm)) mdeqc = 1
mode = mode + mdeqc
!
!     Check if soln to equal. Constraints satisfies inequal.
!     Constraints when there are no degrees of freedom left.
!
if (.not.(kranke.eq.n .and. mg.gt.0)) go to 330
xnorm = sasum(n,x,1)
mapke1 = ma + kranke + 1
mend = ma + kranke + mg
do 310 i = mapke1,mend
  size = sasum(n,w(i,1),mdw)*xnorm + abs(w(i,np1))
  if (.not.(w(i,np1).gt.tau*size)) go to 310
  mode = 2
  go to 470
310 continue
330 if (.not.(kranke.gt.0)) go to 420
!
!     Replace diag. Terms of lower trap. Matrix.
call scopy(kranke, ws(kranke+1), 1, w, mdw+1)
!
!     Reapply trans to put soln in original coordinates.
!
do ii = 1,kranke
  i = kranke + 1 - ii
  call h12(2, i, i+1, n, w(i,1), mdw, ws(i), x, 1, 1, 1)
end do
!
!     Compute cov matrix of equal. Constrained problem.
!
if (.not.(cov)) go to 450
do 400 jj = 1,kranke
  j = kranke + 1 - jj
  if (.not.(j.lt.n)) go to 400
  rb = ws(j)*w(j,j)
  if (rb.ne.zero) rb = one/rb
  jp1 = j + 1
  do i=jp1,n
    w(i,j) = sdot(n-j,w(i,jp1),mdw,w(j,jp1),mdw)*rb
  end do
  gam = sdot(n-j,w(jp1,j),1,w(j,jp1),mdw)*rb
  gam = half*gam
  call saxpy(n-j, gam, w(j,jp1), mdw, w(jp1,j), 1)
  do i=jp1,n
    do k=i,n
      w(i,k) = w(i,k) + w(j,i)*w(k,j) + w(i,j)*w(j,k)
      w(k,i) = w(i,k)
    end do
  end do
  uj = ws(j)
  vj = gam*uj
  w(j,j) = uj*vj + uj*vj
  do i=jp1,n
    w(j,i) = uj*w(i,j) + vj*w(j,i)
  end do
  call scopy(n-j, w(j,jp1), mdw, w(jp1,j), 1)
400 continue
!
!     Apply the scaling to the covariance matrix.
!
420 if (.not.(cov)) go to 450
do i = 1,n
  l = n1 + i
  call sscal(n, ws(l-1), w(i,1), mdw)
  call sscal(n, ws(l-1), w(1,i), 1)
end do
!
!     Rescale soln. Vector.
!
450 if (mode .gt. 1) go to 470
do j = 1,n
  l = n1 + j
  x(j) = x(j)*ws(l-1)
end do
470 ip(1) = kranke
ip(3) = ip(3) + 2*kranke + n
return
480 continue
!     To process-option-vector
!
!     The nominal tolerance used in the code
!     for the equality constraint equations.
tau = sqrt(srelpr)
!
!     The nominal column scaling used in the code is
!     the identity scaling.
ws(n1) = one
call scopy(n, ws(n1), 0, ws(n1), 1)
!
!     No covariance matrix is nominally computed.
cov = .false.
!
!     Define bound for number of options to change.
nopt = 1000
ntimes = 0
!
!     Define bound for positive values of link.
nlink = 100000
last = 1
link = prgopt(1)
if (.not.(link.le.0 .or. link.gt.nlink)) go to 490
mode = 4
return
490 if (.not.(link.gt.1)) go to 540
ntimes = ntimes + 1
if (.not.(ntimes.gt.nopt)) go to 500
mode = 4
return
500 key = prgopt(last+1)
if (key.eq.1) cov = prgopt(last+2).ne.zero
if (.not.(key.eq.2 .and. prgopt(last+2).ne.zero)) go to 520
do j=1,n
  t = snrm2(m,w(1,j),1)
  if (t.ne.zero) t = one/t
  l = n1 + j
  ws(l-1) = t
end do
520 if (key.eq.3) call scopy(n, prgopt(last+2), 1, ws(n1), 1)
if (key.eq.4) tau = amax1(srelpr,prgopt(last+2))
next = prgopt(link)
if (.not.(next.le.0 .or. next.gt.nlink)) go to 530
mode = 4
return
530 last = link
link = next
go to 490
540 do j=1,n
  l = n1 + j
  call sscal(m, ws(l-1), w(1,j), 1)
end do
go to 90
end subroutine lsei

subroutine lsi(w, mdw, ma, mg, n, prgopt, x, rnorm, mode, ws, ip)
implicit none
integer, intent(in) :: ma, mdw, mg
integer, intent(out) :: mode
integer :: n
real, intent(out) :: rnorm
integer :: i, ii, il, im1, ip1, j, k, key, key8, key9, krank, &
&krm1, krp1, l, last, link, m, map1, mdlpdp, minman, n1, n2, n3, &
&next, np1
real :: anorm, blowup, eps, fac, gam, half, one, rb, srelpr, tau, &
&tol, xnorm, zero
real :: sasum
real :: sdot
real :: spmpar
!
!     This is a companion subprogram to lsei( ).
!     The documentation for lsei( ) has more complete
!     usage instructions.
!     Written by R. J. Hanson, sla.
!
!     Solve..
!              AX = B,  A  ma BY n  (LEAST SQUARES EQUATIONS)
!     subject to..
!
!              GX.GE.H, G  mg BY n  (INEQUALITY CONSTRAINTS)
!
!     Input..
!
!      w(*,*) contains  (A B) in rows 1,...,ma+mg, cols 1,...,n+1.
!                       (G H)
!
!     mdw,ma,mg,n
!              contain (resp) var. Dimension of w(*,*),
!              and matrix dimensions.
!
!     prgopt(*),
!              program option vector.
!
!     Output..
!
!      x(*),rnorm
!
!              SOLUTION VECTOR(UNLESS mode=2), LENGTH OF AX-B.
!
!      Mode
!              =0   INEQUALITY CONSTRAINTS ARE COMPATIBLE.
!              =2   INEQUALITY CONSTRAINTS CONTRADICTORY.
!
!      ws(*),
!              working storage of dimension k+n+(mg+2)*(n+7),
!              WHERE k=max(ma+mg,n).
!      ip(mg+2*n+1)
!              integer working storage
!
!     Subroutines called
!
!     lpdp          THIS SUBPROGRAM MINIMIZES A SUM OF SQUARES
!                   of unknowns subject to linear inequality
!                   constraints.  Part of this package.
!
!     sdot,sscal    SUBROUTINES FROM THE BLAS PACKAGE.
!     saxpy,sasum,  see trans. Math software (5), P. 308.
!     scopy,sswap
!
!     hfti          SOLVES AN UNCONSTRAINED LINEAR LEAST SQUARES
!                   problem.
!
!     h12           SUBROUTINE TO CONSTRUCT AND APPLY A HOUSEHOLDER
!                   transformation.
!
!     spmpar        FUNCTION TO COMPUTE THE RELATIVE MACHINE
!                   precision.
!
real, intent(inout) :: w(mdw,*)
real, intent(in) :: prgopt(*)
real, intent(inout) :: x(*), ws(*)
real :: rnrm(1), opt(7)
integer, intent(inout) :: ip(*)
logical :: cov
!
data zero /0.e0/, one /1.e0/, half /0.5e0/
!
srelpr = spmpar(1)
mode = 0
rnorm = zero
m = ma + mg
np1 = n + 1
krank = 0
if (n.le.0 .or. m.le.0) go to 70
!
!     Process-option-vector
!
go to 500
!
!     Compute matrix NORM of least squares equas.
!
40 anorm = zero
do j = 1,n
  anorm = amax1(anorm,sasum(ma,w(1,j),1))
end do
!
!     Set TOL for hfti( ) rank test.
tau = tol*anorm
!
!     Compute Householder orthogonal decomp of matrix.
!
if (n.gt.0) ws(1) = zero
call scopy(n, ws, 0, ws, 1)
call scopy(ma, w(1,np1), 1, ws, 1)
k = max0(m,n)
minman = min0(ma,n)
n1 = k + 1
n2 = n1 + n
call hfti(w, mdw, ma, n, ws, 1, 1, tau, krank, rnrm, ws(n2), &
&ws(n1), ip)
rnorm = rnrm(1)
fac = one
gam = ma - krank
if (krank .lt. ma) fac = rnorm**2/gam
go to 80
!
!     Reduce-to-lpdp-and-solve
!
70 ip(1) = krank
ip(2) = n + max0(m,n) + (mg+2)*(n+7)
return
!
!     To reduce-to-lpdp-and-solve
!
80 map1 = ma + 1
!
!     Compute ineq. RT-hand side for lpdp.
!
if (.not.(ma.lt.m)) go to 260
if (.not.(minman.gt.0)) go to 160
do i = map1,m
  w(i,np1) = w(i,np1) - sdot(n,w(i,1),mdw,ws,1)
end do
do i = 1,minman
  j = ip(i)
!
!     Apply permutations to cols of ineq. Constraint matrix.
  call sswap(mg, w(map1,i), 1, w(map1,j), 1)
end do
!
!     Apply Householder transformations to constraint matrix.
!
if (.not.(0.lt.krank .and. krank.lt.n)) go to 120
do ii = 1,krank
  i = krank + 1 - ii
  l = n1 + i
  call h12(2, i, krank+1, n, w(i,1), mdw, ws(l-1), w(map1,1), &
&mdw, 1, mg)
end do
!
!     Compute permuted ineq. Constr. Matrix times R-inverse.
!
120 do 150 i = map1,m
  if (.not.(0.lt.krank)) go to 150
  do j=1,krank
    w(i,j) = (w(i,j)-sdot(j-1,w(1,j),1,w(i,1),mdw))/w(j,j)
  end do
150 continue
!
!     Solve the reduced problem with lpdp algorithm,
!     the least projected distance problem.
!
160 call lpdp(w(map1,1), mdw, mg, krank, n-krank, opt, x, xnorm, &
&mdlpdp, ws(n2), ip(n+1))
if (mdlpdp .ne. 1) go to 240
if (.not.(krank.gt.0)) go to 180
!
!     Compute soln in original coordinates.
!
do ii = 1,krank
  i = krank + 1 - ii
  x(i) = (x(i)-sdot(ii-1,w(i,i+1),mdw,x(i+1),1))/w(i,i)
end do
!
!     Apply Householder trans. To soln vector.
!
180 if (.not.(0.lt.krank .and. krank.lt.n)) go to 200
do i = 1,krank
  l = n1 + i
  call h12(2, i, krank+1, n, w(i,1), mdw, ws(l-1), x, 1, 1, 1)
end do
200 if (.not.(minman.gt.0)) go to 270
!
!     Repermute variables to their input order.
do ii=1,minman
  i = minman + 1 - ii
  j = ip(i)
  call sswap(1, x(i), 1, x(j), 1)
end do
!
!     Variables are now in orig. Coordinates.
!     Add soln of unsconstrained prob.
do i = 1,n
  x(i) = x(i) + ws(i)
end do
!
!     Compute the residual vector NORM.
rnorm = sqrt(rnorm**2+xnorm**2)
go to 270
240 mode = 2
go to 270
260 call scopy(n, ws, 1, x, 1)
270 if (.not.(cov .and. krank.gt.0)) go to 70
!
!     Compute covariance matrix based on the orthogonal decomp.
!     FROM hfti( ).
!
krm1 = krank - 1
krp1 = krank + 1
!
!     Copy diag. Terms to working array.
call scopy(krank, w, mdw+1, ws(n2), 1)
!
!     Reciprocate diag. Terms.
do j = 1,krank
  w(j,j) = one/w(j,j)
end do
if (.not.(krank.gt.1)) go to 310
!
!     Invert the upper triangular QR factor on itself.
do i=1,krm1
  ip1 = i + 1
  do j=ip1,krank
    w(i,j) = -sdot(j-i,w(i,i),mdw,w(i,j),1)*w(j,j)
  end do
end do
!
!     Compute the inverted factor times its transpose.
310 do i=1,krank
  do j=i,krank
    w(i,j) = sdot(krank+1-j,w(i,j),mdw,w(j,j),mdw)
  end do
end do
if (.not.(krank.lt.n)) go to 450
!
!     Zero out lower trapezoidal part.
!     Copy upper TRI. To lower TRI. Part.
do j=1,krank
  call scopy(j, w(1,j), 1, w(j,1), mdw)
end do
do i=krp1,n
  w(i,1) = zero
  call scopy(i, w(i,1), 0, w(i,1), mdw)
end do
!
!     Apply right side transformations to lower TRI.
n3 = n2 + krp1
do i=1,krank
  l = n1 + i
  k = n2 + i
  rb = ws(l-1)*ws(k-1)
  if (.not.(rb.lt.zero)) go to 420
!
!     IF rb.GE.ZERO, TRANSFORMATION CAN BE REGARDED AS ZERO.
  rb = one/rb
!
!     Store unscaled rank-one Householder update in work array.
  ws(n3) = zero
  call scopy(n, ws(n3), 0, ws(n3), 1)
  l = n1 + i
  k = n3 + i
  ws(k-1) = ws(l-1)
  do j=krp1,n
    k = n3 + j
    ws(k-1) = w(i,j)
  end do
  do j=1,n
    l = n3 + i
    k = n3 + j
    ws(j) = sdot(j-i,w(j,i),mdw,ws(l-1),1) + sdot(n-j+1,w(j,j),1, &
&ws(k-1),1)
    ws(j) = ws(j)*rb
  end do
  l = n3 + i
  gam = sdot(n-i+1,ws(l-1),1,ws(i),1)*rb
  gam = gam*half
  call saxpy(n-i+1, gam, ws(l-1), 1, ws(i), 1)
  do j=i,n
    if (.not.(i.gt.1)) go to 390
    im1 = i - 1
    k = n3 + j
    do l=1,im1
      w(j,l) = w(j,l) + ws(k-1)*ws(l)
    end do
390 k = n3 + j
    do l=i,j
      il = n3 + l
      w(j,l) = w(j,l) + ws(j)*ws(il-1) + ws(l)*ws(k-1)
    end do
  end do
420 continue
end do
!
!     Copy lower TRI. To upper TRI. To symmetrize the covariance matrix.
!
do i = 1,n
  call scopy(i, w(i,1), mdw, w(1,i), 1)
end do
!
!     Repermute rows and cols.
!
450 do 470 ii = 1,minman
  i = minman + 1 - ii
  k = ip(i)
  if (.not.(i.ne.k)) go to 470
  call sswap(1, w(i,i), 1, w(k,k), 1)
  call sswap(i-1, w(1,i), 1, w(1,k), 1)
  call sswap(k-i-1, w(i,i+1), mdw, w(i+1,k), 1)
  call sswap(n-k, w(i,k+1), mdw, w(k,k+1), mdw)
470 continue
!
!     Put in normalized residual sum of squares scale factor
!     and symmetrize the resulting covariance marix.
!
do j = 1,n
  call sscal(j, fac, w(1,j), 1)
  call scopy(j, w(1,j), 1, w(j,1), mdw)
end do
go to 70
!
!     To process-option-vector
!
!     The nominal tolerance used in the code,
500 tol = sqrt(srelpr)
cov = .false.
last = 1
link = prgopt(1)
key8 = 0
key9 = 0
510 if (.not.(link.gt.1)) go to 540
   key = prgopt(last+1)
   if (key .eq. 1) cov = prgopt(last+2).ne.zero
   if (key .eq. 5) tol = amax1(srelpr,prgopt(last+2))
   if (key .ne. 8) go to 520
      key8 = 1
      eps = prgopt(last+2)
      go to 530
520 if (key .ne. 9) go to 530
      key9 = 1
      blowup = prgopt(last+2)
530 next = prgopt(link)
   last = link
   link = next
   go to 510
!
!     Prepare the option vector for wnnls
!
540 j = 1
if (key8 .eq. 0) go to 550
   opt(1) = 4.0
   opt(2) = 8.0
   opt(3) = eps
   j = 4
550 if (key9 .eq. 0) go to 560
   opt(j) = j + 3
   opt(j+1) = 9.0
   opt(j+2) = blowup
   j = j + 3
560 opt(j) = 1.0
go to 40
end subroutine lsi

subroutine lpdp(a, mda, m, n1, n2, prgopt, x, wnorm, mode, ws, is)
implicit none
integer, intent(inout) :: is(*)
integer, intent(in) :: m, mda
integer, intent(out) :: mode
integer, intent(in) :: n1, n2
real, intent(inout) :: a(mda,*)
real :: prgopt(*)
real, intent(inout) :: wnorm, ws(*), x(*)
integer :: i, iw, ix, j, l, modew, n, np1
real :: fac, one, rnorm, sc, ynorm, zero
real :: snrm2
real :: sdot
!
!     dimension a(mda,n+1),prgopt(*),x(n),ws((m+2)*(n+7)),is(m+n+1),
!     WHERE n=n1+n2.  THIS IS A SLIGHT OVERESTIMATE FOR ws(*).
!
!     Written by R. J. Hanson and K. H. Haskell, sandia labs
!
!     Determine an n1-vector W, and
!               an n2-vector Z
!     which minimizes the Euclidean length of W
!     SUBJECT TO G*W+H*Z .GE. Y.
!     This is the least projected distance problem, lpdp.
!     The matrices G and H are of respective
!     dimensions m by n1 and m by n2.
!
!     Called by subprogram lsi( ).
!
!     The matrix
!                (G H Y)
!
!     Occupies rows 1,...,m and cols 1,...,n1+n2+1 of a(*,*).
!
!     The solution (W) is returned in x(*).
!                  (Z)
!
!     The value of mode indicates the status of
!     the computation after returning to the user.
!
!          mode=1  THE SOLUTION WAS SUCCESSFULLY OBTAINED.
!
!          mode=2  THE INEQUALITIES ARE INCONSISTENT.
!
!     Subroutines called
!
!     wnnls         SOLVES A NONNEGATIVELY CONSTRAINED LINEAR LEAST
!                   squares problem with linear equality constraints.
!                   Part of this package.
!
!     sdot,scopy    SUBROUTINES FROM THE BLAS PACKAGE.
!     sscal,snrm2   SEE TRANS. MATH SOFTWARE (5), P. 308.
!
data zero, one /0.e0,1.e0/, fac /0.1e0/
!
n = n1 + n2
mode = 1
if (.not.(m.le.0)) go to 20
if (.not.(n.gt.0)) go to 10
x(1) = zero
call scopy(n, x, 0, x, 1)
10 wnorm = zero
return
20 np1 = n + 1
!
!     Scale nonzero rows of inequality matrix to have length one.
!
do 40 i = 1,m
   sc = snrm2(n,a(i,1),mda)
   if (sc .eq. zero) go to 40
   sc = one/sc
   call sscal(np1, sc, a(i,1), mda)
40 continue
!
!     Scale RT.-Side vector to have length one (or zero).
ynorm = snrm2(m,a(1,np1),1)
if (ynorm .eq. zero) go to 50
sc = one/ynorm
call sscal(m, sc, a(1,np1), 1)
!
!     Scale cols of matrix H.
50 j = n1 + 1
60 if (j .gt. n) go to 70
sc = snrm2(m,a(1,j),1)
if (sc .ne. zero) sc = one/sc
call sscal(m, sc, a(1,j), 1)
x(j) = sc
j = j + 1
go to 60
70 if (.not.(n1.gt.0)) go to 130
!
!     Copy transpose of (H G Y) to work array ws(*).
iw = 0
do i=1,m
!
!     Move col of transpose of H into work array.
   call scopy(n2, a(i,n1+1), mda, ws(iw+1), 1)
   iw = iw + n2
!
!     Move col of transpose of G into work array.
   call scopy(n1, a(i,1), mda, ws(iw+1), 1)
   iw = iw + n1
!
!     Move component of vector Y into work array.
   ws(iw+1) = a(i,np1)
   iw = iw + 1
end do
ws(iw+1) = zero
call scopy(n, ws(iw+1), 0, ws(iw+1), 1)
iw = iw + n
ws(iw+1) = one
iw = iw + 1
!
!     SOLVE EU=F SUBJECT TO (TRANSPOSE OF H)U=0, U.GE.0.  THE
!     MATRIX E = TRANSPOSE OF (G Y), AND THE (n+1)-VECTOR
!     F = TRANSPOSE OF (0,...,0,1).
ix = iw + 1
iw = iw + m
call wnnls(ws, np1, n2, np1-n2, m, 0, prgopt, ws(ix), rnorm, &
&modew, is, ws(iw+1))
!
!     Compute the components of the soln denoted above by W.
sc = one - sdot(m,a(1,np1),1,ws(ix),1)
if (.not.(one+fac*abs(sc).ne.one .and. rnorm.gt.zero)) go to 110
sc = one/sc
do j=1,n1
   x(j) = sc*sdot(m,a(1,j),1,ws(ix),1)
end do
!
!     COMPUTE THE VECTOR Q=Y-GW.  OVERWRITE Y WITH THIS VECTOR.
do i=1,m
   a(i,np1) = a(i,np1) - sdot(n1,a(i,1),mda,x,1)
end do
go to 130
110 mode = 2
return
130 if (.not.(n2.gt.0)) go to 180
!
!     Copy transpose of (H Q) to work array ws(*).
iw = 0
do i=1,m
   call scopy(n2, a(i,n1+1), mda, ws(iw+1), 1)
   iw = iw + n2
   ws(iw+1) = a(i,np1)
   iw = iw + 1
end do
ws(iw+1) = zero
call scopy(n2, ws(iw+1), 0, ws(iw+1), 1)
iw = iw + n2
ws(iw+1) = one
iw = iw + 1
ix = iw + 1
iw = iw + m
!
!     SOLVE RV=S SUBJECT TO V.GE.0.  THE MATRIX R =(TRANSPOSE
!     OF (H Q)), WHERE Q=Y-GW.  THE (n2+1)-VECTOR S =(TRANSPOSE
!     of (0,...,0,1)).
!
call wnnls(ws, n2+1, 0, n2+1, m, 0, prgopt, ws(ix), rnorm, modew, &
&is, ws(iw+1))
!
!     Compute the components of the soln denoted above by Z.
!
sc = one - sdot(m,a(1,np1),1,ws(ix),1)
if (.not.(one+fac*abs(sc).ne.one .and. rnorm.gt.zero)) go to 160
sc = one/sc
do j=1,n2
   l = n1 + j
   x(l) = sc*sdot(m,a(1,l),1,ws(ix),1)*x(l)
end do
go to 180
160 mode = 2
return
!
!     Account for scaling of RT.-Side vector in solution.
180 call sscal(n, ynorm, x, 1)
wnorm = snrm2(n1,x,1)
return
end subroutine lpdp

subroutine wnnls(w, mdw, me, ma, n, l, prgopt, x, rnorm, mode, &
&iwork, work)
implicit none
integer, intent(in) :: l, ma, mdw, me
integer, intent(out) :: mode
integer, intent(in) :: n
real, intent(inout) :: rnorm
integer :: l1, l2, l3, l4, l5
!
!     dimension w(mdw,n+1),prgopt(*),x(n),iwork(m+n),work(m+5*n)
!
!     Abstract
!
!     This subprogram solves a linearly constrained least squares
!     problem.  Suppose there are given matrices E and A of
!     respective dimensions me by n and ma by n, and vectors F
!     and B of respective lengths me and ma.  This subroutine
!     solves the problem
!
!               EX = F, (EQUATIONS TO BE EXACTLY SATISFIED)
!
!               AX = B, (EQUATIONS TO BE APPROXIMATELY SATISFIED,
!                        in the least squares sense)
!
!               Subject to components l+1,...,n nonnegative
!
!     ANY VALUES me.GE.0, ma.GE.0 AND 0.LE. l .LE.n ARE PERMITTED.
!
!     The problem is reposed as problem wnnls
!
!               (WT*E)x = (WT*F)
!               (   A)    (   B), (LEAST SQUARES)
!               subject to components l+1,...,n nonnegative.
!
!     The subprogram chooses the heavy weight (or penalty parameter) WT.
!
!     The parameters for wnnls are
!
!     Input..
!
!     w(*,*),mdw,  the array w(*,*) is double subscripted with first
!     ME,ma,n,l    DIMENSIONING PARAMETER EQUAL TO mdw.  FOR THIS
!                  DISCUSSION LET US CALL M = me + ma.  THEN mdw
!                  MUST SATISFY mdw.GE.M.  THE CONDITION mdw.LT.M
!                  is an error.
!
!                  The array w(*,*) contains the matrices and vectors
!
!                       (E  F)
!                       (A  B)
!
!                  In rows and columns 1,...,M and 1,...,n+1
!                  respectively.  Columns 1,...,l correspond to
!                  unconstrained variables x(1),...,x(l).  The
!                  remaining variables are constrained to be
!                  NONNEGATIVE.  THE CONDITION l.LT.0 .OR. l.GT.n IS
!                  an error.
!
!     prgopt(*)    THIS ARRAY IS THE OPTION VECTOR.
!                  If the user is satisfied with the nominal
!                  subprogram features set
!
!                  prgopt(1)=1 (OR prgopt(1)=1.0)
!
!                  Otherwise prgopt(*) is a linked list consisting of
!                  groups of data of the following form
!
!                  Link
!                  key
!                  data set
!
!                  The parameters link and key are each one word.
!                  The data set can be comprised of several words.
!                  The number of items depends on the value of key.
!                  The value of link points to the first
!                  entry of the next group of data within
!                  prgopt(*).  The exception is when there are
!                  no more options to change.  In that
!                  CASE LINK=1 AND THE VALUES KEY AND DATA SET
!                  are not referenced. The general layout of
!                  prgopt(*) is as follows.
!
!               ...prgopt(1)=LINK1 (LINK TO FIRST ENTRY OF NEXT GROUP)
!               .  prgopt(2)=KEY1 (KEY TO THE OPTION CHANGE)
!               .  prgopt(3)=DATA VALUE (DATA VALUE FOR THIS CHANGE)
!               .       .
!               .       .
!               .       .
!               ...prgopt(LINK1)=LINK2 (LINK TO THE FIRST ENTRY OF
!               .                       NEXT GROUP)
!               .  prgopt(LINK1+1)=KEY2 (KEY TO THE OPTION CHANGE)
!               .  prgopt(LINK1+2)=DATA VALUE
!               ...     .
!               .       .
!               .       .
!               ...prgopt(LINK)=1 (NO MORE OPTIONS TO CHANGE)
!
!                  Values of link that are nonpositive are errors.
!                  A VALUE OF LINK.GT.NLINK=100000 IS ALSO AN ERROR.
!                  This helps prevent using invalid but positive
!                  values of link that will probably extend
!                  beyond the program limits of prgopt(*).
!                  Unrecognized values of key are ignored.  The
!                  order of the options is arbitrary and any number
!                  of options can be changed with the following
!                  restriction.  To prevent cycling in the
!                  processing of the option array A count of the
!                  number of options changed is maintained.
!                  WHENEVER THIS COUNT EXCEEDS NOPT=1000 THE
!                  routine terminates.
!
!                  Options..
!
!                  key=6
!                         scale the nonzero columns of the
!                  entire data matrix
!                  (E)
!                  (A)
!                  to have length one.  The data set for
!                  this option is a single value.  It must
!                  be nonzero if unit length column scaling is
!                  desired.
!
!                  key=7
!                         scale columns of the entire data matrix
!                  (E)
!                  (A)
!                  with a user-provided diagonal matrix.
!                  The data set for this option consists
!                  of the n diagonal scaling factors, one for
!                  each matrix column.
!
!                  key=8
!                         change the rank determination tolerance from
!                  the nominal value of sqrt(EPS).  This quantity can
!                  be no smaller than eps, the arithmetic-
!                  storage precision.  The quantity used
!                  here is internally restricted to be at
!                  least eps.  The data set for this option
!                  is the new tolerance.
!
!                  key=9
!                         change the blow-up parameter from the
!                  nominal value of sqrt(EPS).  The reciprocal of
!                  this parameter is used in rejecting solution
!                  components as too large when a variable is
!                  first brought into the active set.  Too large
!                  means that the proposed component times the
!                  reciprocal of the parameteris not less than
!                  the ratio of the norms of the right-side
!                  vector and the data matrix.
!                  This parameter can be no smaller than eps,
!                  the arithmetic-storage precision.
!
!                  For example, suppose we want to provide
!                  a diagonal matrix to scale the problem
!                  matrix and change the tolerance used for
!                  determining linear dependence of dropped col
!                  vectors.  For these options the dimensions of
!                  prgopt(*) must be at least n+6.  The Fortran
!                  statements defining these options would
!                  be as follows.
!
!                  prgopt(1)=n+3 (LINK TO ENTRY n+3 IN prgopt(*))
!                  prgopt(2)=7 (USER-PROVIDED SCALING KEY)
!
!                  call scopy(n,d,1,prgopt(3),1) (copy the n
!                  scaling factors from a user array called D(*)
!                  INTO prgopt(3)-prgopt(n+2))
!
!                  prgopt(n+3)=n+6 (LINK TO ENTRY n+6 OF prgopt(*))
!                  prgopt(n+4)=8 (LINEAR DEPENDENCE TOLERANCE KEY)
!                  prgopt(n+5)=... (NEW VALUE OF THE TOLERANCE)
!
!                  prgopt(n+6)=1 (NO MORE OPTIONS TO CHANGE)
!
!     Output..
!
!     x(*)         AN ARRAY DIMENSIONED AT LEAST n, WHICH WILL
!                  contain the n components of the solution vector
!                  on output.
!
!     rnorm        THE RESIDUAL NORM OF THE SOLUTION.  THE VALUE OF
!                  rnorm contains the residual vector LENGTH of the
!                  equality constraints and least squares equations.
!
!     MODE         THE VALUE OF MODE INDICATES THE SUCCESS OR FAILURE
!                  of the subprogram.
!
!                  mode = 0  SUBPROGRAM COMPLETED SUCCESSFULLY.
!
!                       = 1  MAX. NUMBER OF ITERATIONS (EQUAL TO
!                            3*(n-l)) exceeded. Nearly all problems
!                            should complete in fewer than this
!                            number of iterations. An approximate
!                            solution and its corresponding residual
!                            vector LENGTH are in x(*) and rnorm.
!
!                       = 2  USAGE ERROR OCCURRED.  EITHER
!                            mdw .LT. me + ma, l .LT. 0, l .GT. n,
!                            or the option vector prgopt(*) is
!                            not properly defined.
!
!     User-designated
!     working arrays..
!
!     work(*)      A WORKING ARRAY OF LENGTH AT LEAST
!                  M + 5*n.
!
!     iwork(*)     AN INTEGER-VALUED WORKING ARRAY OF LENGTH AT LEAST
!                  M+n.
!
!     Written by karen H. Haskell, Sandia Laboratories,
!     and R.J. Hanson, Sandia Laboratories.
!     Revised oct. 1, 1989.
!
!
!     Subroutines called by wnnls( )
!
!     wnlsm         COMPANION SUBROUTINE TO wnnls( ), WHERE
!                   most of the computation takes place.
!
!
!     References
!
!     1. Solving least squares problems, by C.L. Lawson
!        and R.J. Hanson.  Prentice-Hall, inc. (1974).
!
!     2. BASIC linear algebra subprograms for Fortran usage, by
!        C.L. Lawson, R.J. Hanson, D.R. kincaid, and F.T. krogh.
!        Toms, V. 5, No. 3, P. 308.  Also available as
!        sandia technical report no. SAND77-0898.
!
!     3. An algorithm for linear least squares with equality
!        and nonnegativity constraints, by K.H. Haskell and
!        R.J. Hanson.  Available as sandia technical report no.
!        SAND77-0552, and math. Programming, vol. 21, (1981), P. 98-118.
!
real, intent(inout) :: w(mdw,*)
real, intent(in) :: prgopt(*)
real, intent(inout) :: x(n), work(*)
integer, intent(inout) :: iwork(*)
!
mode = 0
if (ma+me .le. 0 .or. n .le. 0) return
if (.not.(mdw.lt.me+ma)) go to 10
mode = 2
return
10 if (0.le.l .and. l.le.n) go to 20
mode = 2
return
!
!     The purpose of this subroutine is to break up the arrays
!     work(*) and iwork(*) into separate work arrays
!     required by the main subroutine wnlsm( ).
!
20 l1 = n + 1
l2 = l1 + n
l3 = l2 + me + ma
l4 = l3 + n
l5 = l4 + n
!
call wnlsm(w, mdw, me, ma, n, l, prgopt, x, rnorm, mode, iwork, &
&iwork(l1), work(1), work(l1), work(l2), work(l3), work(l4), &
&work(l5))
return
end subroutine wnnls

subroutine wnlsm(w, mdw, mme, ma, n, l, prgopt, x, rnorm, mode, &
&ipivot, itype, wd, h, scale, z, temp, d)
implicit none
integer, intent(in) :: l, ma, mdw, mme
integer, intent(inout) :: mode
integer, intent(in) :: n
real, intent(inout) :: rnorm
integer :: i, igo897, igo938, igo958, imax, isol, itemp, iter, &
&itmax, iwmax, j, jcon, jj, jm1, jp, key, krank, krp1, l1, last, &
&link, lp1, m, me, mep1, next, niv, niv1, nlink, nm1, nopt, np1, &
&nsoln, nsp1, ntimes
real :: alamda, alpha, alsq, amax, blowup, bnorm, eanorm, fac, &
&one, sm, srelpr, t, tau, two, wmax, z2, zero, zz
real :: snrm2
real :: sasum
real :: spmpar
integer :: isamax
!
!     This is a companion subprogram to wnnls( ).
!     The documentation for wnnls( ) has more complete
!     usage instructions.
!
!     Written by karen h. Haskell, Sandia Laboratories,
!     with the help of R.J. Hanson, Sandia Laboratories.
!
!     In addition to the parameters discussed in the prologue to
!     subroutine wnnls, the following work arrays are used in
!     subroutine wnlsm  (they are passed through the calling
!     sequence from wnnls for purposes of variable dimensioning).
!     Their contents will in general be of no interest to the user.
!
!         ipivot(*)
!            an array of length n.  upon completion it contains the
!         pivoting information for the cols of w(*,*).
!
!         itype(*)
!            an array of length M which is used to keep track
!         OF THE CLASSIFICATION OF THE EQUATIONS.  itype(i)=0
!         denotes equation i as an equality constraint.
!         itype(i)=1 DENOTES EQUATION i AS A LEAST SQUARES
!         equation.
!
!         wd(*)
!            an array of length n.  upon completion it contains the
!         dual solution vector.
!
!         h(*)
!            an array of length n.  upon completion it contains the
!         pivot scalars of the Householder transformations performed
!         IN THE CASE KRANK.LT.l.
!
!         scale(*)
!            an array of length M which is used by the subroutine
!         to store the diagonal matrix of weights.
!         These are used to apply the modified Givens
!         transformations.
!
!         z(*),temp(*)
!            working arrays of length n.
!
!         d(*)
!            an array of length n that contains the
!         column scaling for the matrix (E).
!                                       (A)
!
!
real, intent(inout) :: w(mdw,*), x(*), wd(*), h(*), scale(*)
real :: dope(4)
real, intent(inout) :: z(*), temp(*)
real, intent(in) :: prgopt(*)
real, intent(inout) :: d(*)
real :: sparam(5)
integer, intent(inout) :: ipivot(*), itype(*)
integer :: idope(8)
logical :: hitcon, feasbl, done, pos
data zero /0.e0/, one /1.e0/, two /2.e0/
!
!     Initialize-variables
!
go to 180
!
!     Perform initial triangularization in the submatrix
!     corresponding to the unconstrained variables using
!     the procedure initially-triangularize.
!
10 go to 280
!
!     Perform wnnls algorithm using the following steps.
!
!     UNTIL(done)
!
!        Compute-search-direction-and-feasible-point
!
!        When (hitcon) add-constraints
!
!        ELSE PERFORM-MULTIPLIER-TEST-AND-DROP-A-CONSTRAINT
!
!        Fin
!
!     Compute-final-solution
!
20 if (done) go to 80
go to 300
!
!     Compute-search-direction-and-feasible-point
!
30 if (.not.(hitcon)) go to 50
go to 370
!
!     When (hitcon) add-constraints
!
50 go to 640
!
!     ELSE PERFORM-MULTIPLIER-TEST-AND-DROP-A-CONSTRAINT
!
80 go to 1000
!
!     Compute-final-solution
!
100 continue
!
!     To process-option-vector
fac = 1.e-4
!
!     The nominal tolerance used in the code,
tau = sqrt(srelpr)
!
!     The nominal blow-up factor used in the code.
blowup = tau
!
!     The nominal column scaling used in the code is
!     the identity scaling.
d(1) = one
call scopy(n, d, 0, d, 1)
!
!     Define bound for number of options to change.
nopt = 1000
!
!     Define bound for positive value of link.
nlink = 100000
ntimes = 0
last = 1
link = prgopt(1)
if (.not.(link.le.0 .or. link.gt.nlink)) go to 110
mode = 2
return
110 if (.not.(link.gt.1)) go to 160
ntimes = ntimes + 1
if (.not.(ntimes.gt.nopt)) go to 120
mode = 2
return
120 key = prgopt(last+1)
if (.not.(key.eq.6 .and. prgopt(last+2).ne.zero)) go to 140
do 130 j = 1,n
  t = snrm2(m,w(1,j),1)
  if (t.ne.zero) t = one/t
  d(j) = t
130 continue
140 if (key.eq.7) call scopy(n, prgopt(last+2), 1, d, 1)
if (key.eq.8) tau = amax1(srelpr,prgopt(last+2))
if (key.eq.9) blowup = amax1(srelpr,prgopt(last+2))
next = prgopt(link)
if (.not.(next.le.0 .or. next.gt.nlink)) go to 150
mode = 2
return
150 last = link
link = next
go to 110
160 do 170 j = 1,n
  call sscal(m, d(j), w(1,j), 1)
170 continue
go to 220
!
!     To initialize-variables
!
!     SRELPR is the precision for the machine being used.
!
180 srelpr = spmpar(1)
!
m = ma + mme
me = mme
mep1 = me + 1
go to 100
!
!     Process-option-vector
220 done = .false.
iter = 0
itmax = 3*(n-l)
mode = 0
lp1 = l + 1
nsoln = l
nsp1 = nsoln + 1
np1 = n + 1
nm1 = n - 1
l1 = min0(m,l)
!
!     Compute scale factor to apply to equal. Constraint equas.
do 230 j = 1,n
  wd(j) = sasum(m,w(1,j),1)
230 continue
imax = isamax(n,wd,1)
eanorm = wd(imax)
bnorm = sasum(m,w(1,np1),1)
alamda = eanorm/(srelpr*fac)
!
!     Define scaling diag matrix for mod Givens usage and
!     classify equation types.
alsq = alamda**2
do 260 i = 1,m
!
!     WHEN EQU i IS HEAVILY WEIGHTED itype(i)=0, ELSE itype(i)=1.
  if (.not.(i.le.me)) go to 240
  t = alsq
  itemp = 0
  go to 250
240 t = one
  itemp = 1
250 scale(i) = t
  itype(i) = itemp
260 continue
!
!     Set the soln vector x(*) to zero and the col interchange
!     matrix to the identity.
x(1) = zero
call scopy(n, x, 0, x, 1)
do 270 i = 1,n
  ipivot(i) = i
270 continue
go to 10
280 continue
!
!     To initially-triangularize
!
!     Set first l comps. Of dual vector to zero because
!     these correspond to the unconstrained variables.
if (.not.(l.gt.0)) go to 290
wd(1) = zero
call scopy(l, wd, 0, wd, 1)
!
!     The arrays idope(*) and dope(*) are used to pass
!     information to wnlit().  This was done to avoid
!     a long calling sequence or the use of common.
290 idope(1) = me
idope(2) = mep1
idope(3) = 0
idope(4) = 1
idope(5) = nsoln
idope(6) = 0
idope(7) = 1
idope(8) = l1
!
dope(1) = alsq
dope(2) = eanorm
dope(3) = fac
dope(4) = tau
call wnlit(w, mdw, m, n, l, ipivot, itype, h, scale, rnorm, &
&idope, dope, done)
me = idope(1)
mep1 = idope(2)
krank = idope(3)
krp1 = idope(4)
nsoln = idope(5)
niv = idope(6)
niv1 = idope(7)
l1 = idope(8)
go to 20
300 continue
!
!     To compute-search-direction-and-feasible-point
!
!     Solve the triangular system of currently non-active
!     variables and store the solution in z(*).
!
!     Solve-system
assign 310 to igo958
go to 1110
!
!     Increment iteration counter and check against max. Number
!     of iterations.
310 iter = iter + 1
if (.not.(iter.gt.itmax)) go to 320
mode = 1
done = .true.
!
!     Check to see if any constraints have become active.
!     If so, calculate an interpolation factor so that all
!     active constraints are removed from the basis.
320 alpha = two
hitcon = .false.
if (.not.(l.lt.nsoln)) go to 360
do 350 j = lp1,nsoln
  zz = z(j)
  if (.not.(zz.le.zero)) go to 350
  t = x(j)/(x(j)-zz)
  if (.not.(t.lt.alpha)) go to 330
  alpha = t
  jcon = j
330 hitcon = .true.
350 continue
360 go to 30
370 continue
!
!     To add-constraints
!
!     Use computed alpha to interpolate between last
!     feasible solution x(*) and current unconstrained
!     (and infeasible) solution z(*).
if (.not.(lp1.le.nsoln)) go to 390
do 380 j = lp1,nsoln
  x(j) = x(j) + alpha*(z(j)-x(j))
380 continue
390 feasbl = .false.
go to 410
400 if (feasbl) go to 20
!
!     Remove col JCON and shift cols JCON+1 through n to the
!     left. Swap col JCON into the n-TH position.  This achieves
!     upper Hessenberg form for the nonactive constraints and
!     leaves an upper Hessenberg matrix to retriangularize.
410 do 420 i = 1,m
  t = w(i,jcon)
  call scopy(n-jcon, w(i,jcon+1), mdw, w(i,jcon), mdw)
  w(i,n) = t
420 continue
!
!     Update permuted index vector to reflect this shift and swap.
itemp = ipivot(jcon)
if (.not.(jcon.lt.n)) go to 440
do 430 i = jcon,nm1
  ipivot(i) = ipivot(i+1)
430 continue
440 ipivot(n) = itemp
!
!     Similarly repermute x(*) vector.
call scopy(n-jcon, x(jcon+1), 1, x(jcon), 1)
x(n) = zero
nsp1 = nsoln
nsoln = nsoln - 1
niv1 = niv
niv = niv - 1
!
!     Retriangularize upper Hessenberg matrix after adding constraints.
j = jcon
i = krank + jcon - l
450 if (.not.(j.le.nsoln)) go to 570
if (.not.(itype(i).eq.0 .and. itype(i+1).eq.0)) go to 470
assign 460 to igo938
go to 620
!
!     (itype(i).EQ.0 .AND. itype(i+1).EQ.0) ZERO-IP1-TO-i-IN-COL-J
460 go to 560
470 if (.not.(itype(i).eq.1 .and. itype(i+1).eq.1)) go to 490
assign 480 to igo938
go to 620
!
!     (itype(i).EQ.1 .AND. itype(i+1).EQ.1) ZERO-IP1-TO-i-IN-COL-J
480 go to 560
490 if (.not.(itype(i).eq.1 .and. itype(i+1).eq.0)) go to 510
call sswap(np1, w(i,1), mdw, w(i+1,1), mdw)
call sswap(1, scale(i), 1, scale(i+1), 1)
itemp = itype(i+1)
itype(i+1) = itype(i)
itype(i) = itemp
!
!     Swapped row was formerly a pivot elt., So it will
!     be large enough to perform ELIM.
assign 500 to igo938
go to 620
!
!     Zero-IP1-to-i-in-col-J
500 go to 560
510 if (.not.(itype(i).eq.0 .and. itype(i+1).eq.1)) go to 550
t = scale(i)*w(i,j)**2/alsq
if (.not.(t.gt.tau**2*eanorm**2)) go to 530
assign 520 to igo938
go to 620
520 go to 540
530 call sswap(np1, w(i,1), mdw, w(i+1,1), mdw)
call sswap(1, scale(i), 1, scale(i+1), 1)
itemp = itype(i+1)
itype(i+1) = itype(i)
itype(i) = itemp
w(i+1,j) = zero
540 continue
550 continue
560 i = i + 1
j = j + 1
go to 450
!
!     See if the remaining coeffs in the soln set are feasible.  They
!     should be because of the way alpha was determined.  If any are
!     infeasible it is due to roundoff error.  Any that are non-
!     positive will be set to zero and removed from the soln set.
570 if (.not.(lp1.le.nsoln)) go to 590
do 580 jcon = lp1,nsoln
  if (x(jcon).le.zero) go to 600
580 continue
590 feasbl = .true.
600 continue
go to 400
620 continue
!
!     To zero-IP1-to-i-in-col-J
if (.not.(w(i+1,j).ne.zero)) go to 630
call srotmg(scale(i), scale(i+1), w(i,j), w(i+1,j), sparam)
w(i+1,j) = zero
call srotm(np1-j, w(i,j+1), mdw, w(i+1,j+1), mdw, sparam)
630 go to 1290
!
!     To perform-multiplier-test-and-drop-A-constraint
!
640 call scopy(nsoln, z, 1, x, 1)
if (.not.(nsoln.lt.n)) go to 650
x(nsp1) = zero
call scopy(n-nsoln, x(nsp1), 0, x(nsp1), 1)
650 i = niv1
660 if (.not.(i.le.me)) go to 690
!
!     Reclassify least squares eqations as equalities as
!     necessary.
if (.not.(itype(i).eq.0)) go to 670
i = i + 1
go to 680
670 call sswap(np1, w(i,1), mdw, w(me,1), mdw)
call sswap(1, scale(i), 1, scale(me), 1)
itemp = itype(i)
itype(i) = itype(me)
itype(me) = itemp
mep1 = me
me = me - 1
680 go to 660
!
!     Form inner product vector wd(*) of dual coeffs.
690 if (.not.(nsp1.le.n)) go to 730
do 720 j = nsp1,n
  sm = zero
  if (.not.(nsoln.lt.m)) go to 710
  do 700 i = nsp1,m
    sm = sm + scale(i)*w(i,j)*w(i,np1)
700 continue
710 wd(j) = sm
720 continue
730 go to 750
740 if (pos .or. done) go to 970
!
!     FIND J SUCH THAT wd(J)=WMAX IS MAXIMUM.  THIS DETERMINES
!     that the incoming col J will reduce the residual vector
!     and be positive.
750 wmax = zero
iwmax = nsp1
if (.not.(nsp1.le.n)) go to 780
do 770 j = nsp1,n
  if (.not.(wd(j).gt.wmax)) go to 760
  wmax = wd(j)
  iwmax = j
760 continue
770 continue
780 if (.not.(wmax.le.zero)) go to 790
done = .true.
go to 960
!
!     Set dual COEFF to zero for incoming col.
790 wd(iwmax) = zero
!
!     WMAX .GT. ZERO, SO OKAY TO MOVE COL IWMAX TO SOLN SET.
!     Perform transformation to retriangularize, and test
!     for near linear dependence.
!     Swap col IWMAX into NSOLN-TH position to maintain upper
!     Hessenberg form of adjacent cols, and add new col to
!     triangular decomposition.
nsoln = nsp1
nsp1 = nsoln + 1
niv = niv1
niv1 = niv + 1
if (.not.(nsoln.ne.iwmax)) go to 800
call sswap(m, w(1,nsoln), 1, w(1,iwmax), 1)
wd(iwmax) = wd(nsoln)
wd(nsoln) = zero
itemp = ipivot(nsoln)
ipivot(nsoln) = ipivot(iwmax)
ipivot(iwmax) = itemp
!
!     Reduce col NSOLN so that the matrix of nonactive
!     constraints variables is triangular.
800 j = m
810 if (.not.(j.gt.niv)) go to 870
jm1 = j - 1
jp = jm1
!
!     When operating near the me line, test to see if the pivot elt.
!     Is near zero.  If so, use the largest elt. Above it as the pivot.
!     This is to maintain the sharp interface between weighted and
!     non-weighted rows in all cases.
if (.not.(j.eq.mep1)) go to 850
imax = me
amax = scale(me)*w(me,nsoln)**2
820 if (.not.(jp.ge.niv)) go to 840
t = scale(jp)*w(jp,nsoln)**2
if (.not.(t.gt.amax)) go to 830
imax = jp
amax = t
830 jp = jp - 1
go to 820
840 jp = imax
850 if (.not.(w(j,nsoln).ne.zero)) go to 860
call srotmg(scale(jp), scale(j), w(jp,nsoln), w(j,nsoln), sparam)
w(j,nsoln) = zero
call srotm(np1-nsoln, w(jp,nsp1), mdw, w(j,nsp1), mdw, sparam)
860 j = jm1
go to 810
!
!     SOLVE FOR z(NSOLN)=PROPOSED NEW VALUE FOR x(NSOLN).
!     Test if this is nonpositive or too large.
!     If this was true or if the pivot term was zero reject
!     the col as dependent.
870 if (.not.(w(niv,nsoln).ne.zero)) go to 890
isol = niv
assign 880 to igo897
go to 980
!
!     Test-proposed-new-component
880 go to 940
890 if (.not.(niv.le.me .and. w(mep1,nsoln).ne.zero)) go to 920
!
!     Try to add row MEP1 as an additional equality constraint.
!     Check size of proposed new soln component.
!     Reject it if it is too large.
isol = mep1
assign 900 to igo897
go to 980
!
!     Test-proposed-new-component
900 if (.not.(pos)) go to 910
!
!     Swap rows MEP1 and NIV, and scale factors for these rows.
call sswap(np1, w(mep1,1), mdw, w(niv,1), mdw)
call sswap(1, scale(mep1), 1, scale(niv), 1)
itemp = itype(mep1)
itype(mep1) = itype(niv)
itype(niv) = itemp
me = mep1
mep1 = me + 1
910 go to 930
920 pos = .false.
930 continue
940 if (pos) go to 950
nsp1 = nsoln
nsoln = nsoln - 1
niv1 = niv
niv = niv - 1
950 continue
960 go to 740
970 go to 20
980 continue
!
!     To test-proposed-new-component
z2 = w(isol,np1)/w(isol,nsoln)
z(nsoln) = z2
pos = z2.gt.zero
if (.not.(z2*eanorm.ge.bnorm .and. pos)) go to 990
pos = .not.(blowup*z2*eanorm.ge.bnorm)
990 go to 1280
1000 continue
!     To compute-final-solution
!
!     Solve system, store results in x(*).
!
assign 1010 to igo958
go to 1110
!     Solve-system
1010 call scopy(nsoln, z, 1, x, 1)
!
!     APPLY HOUSEHOLDER TRANSFORMATIONS TO x(*) IF KRANK.LT.l
if (.not.(0.lt.krank .and. krank.lt.l)) go to 1030
do 1020 i = 1,krank
  call h12(2, i, krp1, l, w(i,1), mdw, h(i), x, 1, 1, 1)
1020 continue
!
!     Fill in trailing zeroes for constrained variables not in soln.
1030 if (.not.(nsoln.lt.n)) go to 1040
x(nsp1) = zero
call scopy(n-nsoln, x(nsp1), 0, x(nsp1), 1)
!
!     Repermute soln vector to natural order.
1040 do 1070 i = 1,n
  j = i
1050 if (ipivot(j).eq.i) go to 1060
  j = j + 1
  go to 1050
1060 ipivot(j) = ipivot(i)
  ipivot(i) = j
  call sswap(1, x(j), 1, x(i), 1)
1070 continue
!
!     Rescale the soln using the col scaling.
do 1080 j = 1,n
  x(j) = x(j)*d(j)
1080 continue
if (.not.(niv.lt.m)) go to 1100
do 1090 i = niv1,m
  t = w(i,np1)
  if (i.le.me) t = t/alamda
  t = (scale(i)*t)*t
  rnorm = rnorm + t
1090 continue
1100 rnorm = sqrt(rnorm)
return
!
!     To solve-system
!
1110 continue
if (.not.(done)) go to 1120
isol = 1
go to 1130
1120 isol = lp1
1130 if (.not.(nsoln.ge.isol)) go to 1270
!
!     Copy RT. Hand side into temp vector to use overwriting method.
call scopy(niv, w(1,np1), 1, temp, 1)
do 1180 jj = isol,nsoln
  j = nsoln - jj + isol
  if (.not.(j.gt.krank)) go to 1140
  i = niv - jj + isol
  go to 1150
1140 i = j
1150 if (.not.(j.gt.krank .and. j.le.l)) go to 1160
  z(j) = zero
  go to 1170
1160 z(j) = temp(i)/w(i,j)
  call saxpy(i-1, -z(j), w(1,j), 1, temp, 1)
1170 continue
1180 continue
!
1270 go to igo958, (310, 1010)
1280 go to igo897, (880, 900)
1290 go to igo938, (460, 480, 500, 520)
end subroutine wnlsm

subroutine wnlit(w, mdw, m, n, l, ipivot, itype, h, scale, rnorm, &
&idope, dope, done)
implicit none
integer, intent(in) :: l, m, mdw, n
real, intent(out) :: rnorm
integer :: i, i1, ic, igo990, igo993, igo996, ip1, ir, irp1, &
&itemp, j, j1, jj, jm1, jp, k, kk, krank, krp1, l1, lb, lend, lp1, &
&max, me, mend, mep1, niv, niv1, np1, nsoln
real :: alsq, eanorm, fac, factor, hbar, one, rn, sn, t, tau, &
&tenm3, zero
!
!     This is a companion subprogram to wnnls( ).
!     The documentation for wnnls( ) has more complete
!     usage instructions.
!
!     Note  the m by (n+1) matrix w( , ) contains the RT. Hand side
!           B as the (n+1)ST col.
!
!
!     TRIANGULARIZE L1 BY L1 SUBSYSTEM, WHERE L1=min(m,l), WITH
!     col interchanges.
!     Revised oct. 1, 1989
!
real, intent(inout) :: w(mdw,*), h(*), scale(*)
real, intent(in) :: dope(*)
real :: sparam(5)
integer, intent(inout) :: itype(*), ipivot(*), idope(*)
integer :: isamax
logical :: indep
logical, intent(inout) :: done
logical :: recalc
data tenm3 /1.e-3/, zero /0.e0/, one /1.e0/
!
me = idope(1)
mep1 = idope(2)
krank = idope(3)
krp1 = idope(4)
nsoln = idope(5)
niv = idope(6)
niv1 = idope(7)
l1 = idope(8)
!
alsq = dope(1)
eanorm = dope(2)
fac = dope(3)
tau = dope(4)
np1 = n + 1
lb = min0(m-1,l)
recalc = .true.
rnorm = zero
krank = 0
!     WE SET factor=1.E0 SO THAT THE HEAVY WEIGHT ALAMDA WILL BE
!     included in the test for col independence.
factor = 1.e0
i = 1
ip1 = 2
lend = l
10 if (.not.(i.le.lb)) go to 150
if (.not.(i.le.me)) go to 130
!
!     Set ir to point to the i-TH row.
ir = i
mend = m
assign 20 to igo996
go to 460
!
!     Update-col-SS-and-find-pivot-col
20 assign 30 to igo993
go to 560
!
!     Perform-col-interchange
!
!     Set ic to point to i-TH col.
30 ic = i
assign 40 to igo990
go to 520
!
!     Test-indep-of-incoming-col
40 if (.not.(indep)) go to 110
!
!     Eliminate i-TH col below diag. Using mod. Givens transformations
!     applied to (A B).
j = m
do 100 jj = ip1,m
  jm1 = j - 1
  jp = jm1
  if (.not.(jj.eq.m)) go to 70
  if (.not.(i.lt.mep1)) go to 80
  j = mep1
  jp = i
  t = scale(jp)*w(jp,i)**2*tau**2
  if (.not.(t.gt.scale(j)*w(j,i)**2)) go to 130
  go to 80
70 if (.not.(j.eq.mep1)) go to 80
  j = jm1
  jm1 = j - 1
  jp = jm1
80 if (.not.(w(j,i).ne.zero)) go to 90
  call srotmg(scale(jp), scale(j), w(jp,i), w(j,i), sparam)
  w(j,i) = zero
  call srotm(np1-i, w(jp,ip1), mdw, w(j,ip1), mdw, sparam)
90 j = jm1
100 continue
go to 140
110 continue
if (.not.(lend.gt.i)) go to 130
!
!     Col i is dependent. Swap with col lend.
max = lend
!
!     Perform-col-interchange
assign 120 to igo993
go to 560
120 continue
lend = lend - 1
!
!     Find col in remaining set with largest SS.
max = isamax(lend-i+1,h(i),1) + i - 1
hbar = h(max)
go to 30
130 continue
krank = i - 1
go to 160
140 i = ip1
ip1 = ip1 + 1
go to 10
150 krank = l1
160 continue
krp1 = krank + 1
if (.not.(krank.lt.me)) go to 290
factor = alsq
do 170 i = krp1,me
  if (l.gt.0) w(i,1) = zero
  call scopy(l, w(i,1), 0, w(i,1), mdw)
170 continue
!
!     Determine the rank of the remaining equality constraint
!     equations by eliminating within the block of constrained
!     variables.  Remove any redundant constraints.
!
ir = krp1
if (.not.(l.lt.n)) go to 245
lp1 = l + 1
recalc = .true.
lb = min0(l+me-krank,n)
i = lp1
ip1 = i + 1
180 if (.not.(i.le.lb)) go to 280
ir = krank + i - l
lend = n
mend = me
assign 190 to igo996
go to 460
!
!     Update-col-SS-and-find-pivot-col
190 assign 200 to igo993
go to 560
!
!     Perform-col-interchange
!
!     Eliminate elements in the i-TH col.
200 j = me
210 if (.not.(j.gt.ir)) go to 230
jm1 = j - 1
if (.not.(w(j,i).ne.zero)) go to 220
call srotmg(scale(jm1), scale(j), w(jm1,i), w(j,i), sparam)
w(j,i) = zero
call srotm(np1-i, w(jm1,ip1), mdw, w(j,ip1), mdw, sparam)
220 j = jm1
go to 210
!
!     SET ic=i=COL BEING ELIMINATED
230 ic = i
assign 240 to igo990
go to 520
!
!     Test-indep-of-incoming-col
240 if (indep) go to 270
!
!     Remove any redundant or dependent equality constraints.
245 continue
jj = ir
250 if (.not.(ir.le.me)) go to 260
w(ir,1) = zero
call scopy(n, w(ir,1), 0, w(ir,1), mdw)
rnorm = rnorm + (scale(ir)*w(ir,np1)/alsq)*w(ir,np1)
w(ir,np1) = zero
scale(ir) = one
!     Reclassify the zeroed row as a least squares equation.
itype(ir) = 1
ir = ir + 1
go to 250
!
!     Reduce me to reflect any discovered dependent equality
!     constraints.
260 continue
me = jj - 1
mep1 = me + 1
go to 300
270 i = ip1
ip1 = ip1 + 1
go to 180
280 continue
290 continue
300 continue
if (.not.(krank.lt.l1)) go to 420
!
!     Try to determine the variables KRANK+1 through L1 from the
!     least squares equations.  Continue the triangularization with
!     pivot element w(MEP1,i).
!
recalc = .true.
!
!     SET factor=alsq TO REMOVE EFFECT OF HEAVY WEIGHT FROM
!     test for col independence.
factor = alsq
kk = krp1
i = kk
ip1 = i + 1
310 if (.not.(i.le.l1)) go to 410
!
!     Set ir to point to the MEP1-ST row.
ir = mep1
lend = l
mend = m
assign 320 to igo996
go to 460
!
!     Update-col-SS-and-find-pivot-col
320 assign 330 to igo993
go to 560
!
!     Perform-col-interchange
!
!     Eliminate i-TH col below the ir-TH element.
330 irp1 = ir + 1
if (.not.(irp1.le.m)) go to 355
j = m
do 350 jj = irp1,m
  jm1 = j - 1
  if (.not.(w(j,i).ne.zero)) go to 340
  call srotmg(scale(jm1), scale(j), w(jm1,i), w(j,i), sparam)
  w(j,i) = zero
  call srotm(np1-i, w(jm1,ip1), mdw, w(j,ip1), mdw, sparam)
340 j = jm1
350 continue
355 continue
!
!     Test if new pivot element is near zero. If so, the col is
!     dependent.
t = scale(ir)*w(ir,i)**2
indep = t.gt.tau**2*eanorm**2
if (.not.indep) go to 380
!
!     Col test passed. Now must pass row norm test to be classified
!     as independent.
rn = zero
do 370 i1 = ir,m
  do 360 j1 = ip1,n
    rn = amax1(rn,scale(i1)*w(i1,j1)**2)
360 continue
370 continue
indep = t.gt.tau**2*rn
!
!     If independent, swap the ir-TH and KRP1-ST rows to maintain the
!     triangular form.  Update the rank indicator KRANK and the
!     equality constraint pointer me.
380 if (.not.(indep)) go to 390
call sswap(np1, w(krp1,1), mdw, w(ir,1), mdw)
call sswap(1, scale(krp1), 1, scale(ir), 1)
!     Reclassify the least SQ. Equation as an equality constraint and
!     rescale it.
itype(ir) = 0
t = sqrt(scale(krp1))
call sscal(np1, t, w(krp1,1), mdw)
scale(krp1) = alsq
me = mep1
mep1 = me + 1
krank = krp1
krp1 = krank + 1
go to 400
390 go to 430
400 i = ip1
ip1 = ip1 + 1
go to 310
410 continue
420 continue
430 continue
!
!     If pseudorank is less than l, apply Householder trans.
!     From right.
if (.not.(krank.lt.l)) go to 450
do 440 i = 1,krank
  j = krp1 - i
  call h12(1, j, krp1, l, w(j,1), mdw, h(j), w, mdw, 1, j-1)
440 continue
450 niv = krank + nsoln - l
niv1 = niv + 1
if (l.eq.n) done = .true.
!
!  END OF INITIAL TRIANGULARIZATION.
idope(1) = me
idope(2) = mep1
idope(3) = krank
idope(4) = krp1
idope(5) = nsoln
idope(6) = niv
idope(7) = niv1
idope(8) = l1
return
460 continue
!
!     To update-col-SS-and-find-pivot-col
!
!     The col SS vector will be updated at each step. When
!     numerically necessary, these values will be recomputed.
!
if (.not.(ir.ne.1 .and. (.not.recalc))) go to 480
!     UPDATE COL SS =SUM OF SQUARES.
do 470 j = i,lend
  h(j) = h(j) - scale(ir-1)*w(ir-1,j)**2
470 continue
!
!     Test for numerical accuracy.
max = isamax(lend-i+1,h(i),1) + i - 1
recalc = hbar + tenm3*h(max).eq.hbar
!
!     If required, recalculate col SS, using rows ir through mend.
480 if (.not.(recalc)) go to 510
do 500 j = i,lend
  h(j) = zero
  do 490 k = ir,mend
    h(j) = h(j) + scale(k)*w(k,j)**2
490 continue
500 continue
!
!     Find col with largest SS.
max = isamax(lend-i+1,h(i),1) + i - 1
hbar = h(max)
510 go to 600
520 continue
!
!     To test-indep-of-incoming-col
!
!     Test the col ic to determine if it is linearly independent
!     of the cols already in the basis.  In the init TRI
!     step, we usually want the heavy weight ALAMDA to
!     be included in the test for independence.  In this case the
!     value of factor will have been set to 1.E0 before this
!     procedure is invoked.  In the potentially rank deficient
!     problem, the value of factor will have been
!     SET TO alsq=ALAMDA**2 TO REMOVE THE EFFECT OF THE HEAVY WEIGHT
!     from the test for independence.
!
!     Write new col as partitioned vector
!             (A1)  NUMBER OF COMPONENTS IN SOLN SO FAR = NIV
!             (A2)  m-NIV COMPONENTS
!     AND COMPUTE  sn = INVERSE WEIGHTED LENGTH OF A1
!                  rn = INVERSE WEIGHTED LENGTH OF A2
!     CALL THE COL INDEPENDENT WHEN rn .GT. tau*sn
sn = zero
rn = zero
do 550 j = 1,mend
  t = scale(j)
  if (j.le.me) t = t/factor
  t = t*w(j,ic)**2
  if (.not.(j.lt.ir)) go to 530
  sn = sn + t
  go to 540
530 rn = rn + t
540 continue
550 continue
indep = rn.gt.tau**2*sn
go to 590
560 continue
!
!     To perform-col-interchange
!
if (.not.(max.ne.i)) go to 570
!     Exchange elements of permuted index vector and perform col
!     interchanges.
itemp = ipivot(i)
ipivot(i) = ipivot(max)
ipivot(max) = itemp
call sswap(m, w(1,max), 1, w(1,i), 1)
t = h(max)
h(max) = h(i)
h(i) = t
570 go to igo993, (30, 200, 330, 120)
590 go to igo990, (40, 240)
600 go to igo996, (20, 190, 320)
end subroutine wnlit

subroutine l2slv(m, n, m1, l, a, mm, b, mb, w, tol, n1, ipivot, &
&x, nn, res, mr, qr, mmpnn, c, ifault)
implicit none
integer, intent(inout) :: ifault
integer, intent(in) :: l, m, m1, mb, mm, mmpnn, mr, n
integer, intent(inout) :: n1
integer, intent(in) :: nn
integer :: i, iter, j, jm1, k, k0, k1, k10, k11, k12, k2, k3, k4, &
&k5, k6, k7, k8, k9, ksum, m1p1, mp1, mpi, mpn, numit
real :: spmpar
! ** PURPOSE **
! subroutine l2slv computes least squares solutions to overdetermined
! and underdetermined systems of linear equations.  The method used is
! a modified Gram-Schmidt orthogonal decomposition with iterative
! refinement of the solution.  The solution may be subject to linear
! equality constraints.  Output includes the least squares
! coefficients, residuals, unscaled covariance matrix, and information
! on the behavior of the iterative refinement procedure.
! Matrix a is the given matrix of a system of m linear equations in n
! unknowns, and matrix w is a given diagonal matrix of weights with all
! DIAGONAL ELEMENTS NONNEGATIVE.  LET H = w*a.
! In the event that n1 (the computed rank of matrix H) is less than n
! (the number of unknown coefficients), a unique solution vector having
! n elements can be obtained by imposing the condition that the
! solution be of minimal Euclidean norm.  Such a solution is sought in
! the case of underdetermined or rank-deficient problems.
!
! ** INPUT VARIABLES **
! m      TOTAL NUMBER OF EQUATIONS.
! n      NUMBER OF UNKNOWN COEFFICIENTS.
! m1     NUMBER OF LINEAR CONSTRAINTS (0.LE.m1.LE.m AND m1.LE.n).
! l      NUMBER OF RIGHT-HAND SIDES (VECTORS OF OBSERVATIONS).
! a      TWO-DIMENSIONAL ARRAY OF size (mm,n).  ON ENTRY, THE ARRAY a
!        contains the given matrix of a system of m linear equations
!        in n unknowns, where the first m1 equations are to be
!        satisfied exactly.  A is left intact on exit.
! b      TWO-DIMENSIONAL ARRAY OF size (mb,l).  ON ENTRY, b CONTAINS
!        the l given right-hand sides (vectors of observations).  b is
!        left intact on exit.
! w      VECTOR OF SIZE m.  ON ENTRY, w CONTAINS THE DIAGONAL ELEMENTS
!        of a given diagonal matrix of weights, all nonnegative.
!        (The first m1 elements of w are set equal to 1.0 by the
!        program when m1 is greater than zero.)
! tol    PARAMETER USED IN DETERMINING THE RANK OF MATRIX H.
!        Note --
!        (1) if tol equals zero, the tolerance used in subroutine
!            decom2 will be based on machine precision.
!        (2) If tol is greater than zero, this value of tol will be
!            used in setting an absolute tolerance for comparison with
!            diagonal elements of the triangular matrix obtained in
!            subroutine decom2.  The value of tol can be based on
!            knowledge concerning the accuracy of the data.
! mm     DIMENSIONING PARAMETER SPECIFYING MAXIMUM NUMBER OF ROWS IN
!        THE ARRAY a.  mm MUST SATISFY mm.GE.m.
! mb     DIMENSIONING PARAMETER SPECIFYING MAXIMUM NUMBER OF ROWS IN
!        THE ARRAY b.  mb MUST SATISFY mb.GE.m.
! mr     DIMENSIONING PARAMETER SPECIFYING MAXIMUM NUMBER OF ROWS IN
!        THE ARRAY res.  mr MUST SATISFY mr.GE.m.
! nn     DIMENSIONING PARAMETER SPECIFYING MAXIMUM NUMBER OF ROWS IN
!        THE ARRAY x.  nn MUST SATISFY nn.GE.n.
! mmpnn  dimensioning parameter specifying maximum number of rows in
!        THE ARRAY qr.  mmpnn MUST SATISFY mmpnn.GE.m+n.
!
! ** OUTPUT VARIABLES AND INTERNAL VARIABLES **
! n1     COMPUTED RANK OF MATRIX H, WHERE H = w*a.
! ipivot vector of size n.  on exit, this array records the order
!        in which the columns of H were selected by the pivoting
!        scheme in the course of the orthogonal decomposition.
!        WHENEVER n1.LT.n, THE FIRST n1 ELEMENTS OF ipivot INDICATE
!        which columns of H were found to be linearly independent.
! x      TWO-DIMENSIONAL ARRAY OF size (nn,l).  ON EXIT, x CONTAINS
!        the solution vectors.
! RES    TWO-DIMENSIONAL ARRAY OF size (mr,l).  ON EXIT, RES CONTAINS
!        the residual vectors.
! QR     TWO-DIMENSIONAL ARRAY OF size (mmpnn,n).  ON EXIT, IF n1 = n
!        then QR contains the unscaled covariance matrix. (QR is used
!        internally to store the results from the subroutine decom2.
!        The results from decom2 are destroyed when the covariance
!        matrix is computed.)
! c      VECTOR HAVING AT LEAST 6*(m+n)+2*l ELEMENTS USED (1) FOR
!        internal work space and (2) for returning information on the
!        behavior of the iterative refinement procedure.
!        (A) NUMIT is the number of iterations carried out during the
!            iterative refinement in attempting to obtain a solution
!            for the k-TH right-hand side.
!            ON EXIT, c(k) = +NUMIT IF THE SOLUTION CONVERGED, AND
!                     c(k) = -NUMIT IF THE SOLUTION FAILED TO CONVERGE.
!        (b) digitx gives an estimate of the number of correct digits
!            in the initial solution of the coefficients for the k-TH
!            RIGHT-HAND SIDE.  ON EXIT, c(k+l) = digitx.
! ifault fault indicator which is zero if no errors were encountered
!        and positive if errors were detected or if evidence of severe
!        ill-conditioning was found.  If ifault is set to 1, 2, 3, 4,
!        5, 6 or 7, execution is terminated.  Execution continues when
!        ifault is set equal to 8, 9 or 10 provided that a solution
!        was obtained for at least one right-hand side.  The value of
!        ifault is used to indicate the following --
!        0 = NO ERRORS ENCOUNTERED.
!        1 = BAD INPUT PARAMETER (m, n OR l).
!        2 = BAD INPUT PARAMETER (m1).
!        3 = BAD DIMENSION.  EITHER m.GT.mm, m.GT.mb, m.GT.mr,
!            n.GT.nn, OR m+n.GT.mmpnn.
!        4 = AT LEAST ONE WEIGHT IS NEGATIVE.
!        5 = EITHER MATRIX H OR MATRIX OF CONSTRAINTS EQUALS ZERO.
!        6 = CONSTRAINTS ARE LINEARLY DEPENDENT.
!        7 = ALL SOLUTIONS FAILED TO CONVERGE.
!        8 = SOLUTION FAILED TO CONVERGE FOR AT LEAST ONE RIGHT-HAND
!            side.
!        9 = LARGE NUMBER OF ITERATIONS REQUIRED FOR CONVERGENCE.
!       10 = ESTIMATED NUMBER OF DIGITS IN INITIAL SOLUTION OF
!            coefficients is small.
!       11 = DIAGONAL ELEMENT OF COVARIANCE MATRIX WAS COMPUTED TO BE
!            negative owing to rounding error. No severe conditioning
!            problems were detected.
!       12 = DIAGONAL ELEMENT OF COVARIANCE MATRIX WAS COMPUTED TO BE
!            negative owing to rounding error. The problem appears to
!            be extremely ill-conditioned.
!
! ** SUBROUTINES REQUIRED **
! SUBROUTINE decom2
!        uses modified Gram-Schmidt algorithm with pivoting to
!        obtain an orthogonal decomposition of the input matrix.
! SUBROUTINE solve2
!        computes coefficients and residuals.  Iterative refinement is
!        used to improve the accuracy of the initial solution.
! SUBROUTINE solve3
!        called only by subroutine solve2.
! SUBROUTINE covar
!        computes unscaled covariance matrix of the coefficients.
!
! ** STORAGE REQUIREMENTS **
! the storage required for the dimensioned arrays in l2slv is
!   m*(2*n + 2*l + 7) + n*(n + l + 7) + 2*l
! locations.  All arrays required in subroutines called by l2slv are
! declared herein and are transmitted only through parameter lists of
! CALL-SEQUENCES.
!
! ** PRECISION OF ARITHMETIC CALCULATIONS **
! single precision arithmetic is used for all calculations except the
! double precision accumulation of inner products.  (The variable SUM
! is declared to be double precision in subroutines decom2, solve2,
! solve3 and covar.)  It is essential for the success of the iterative
! refinement procedure that inner products be accumulated in double
! precision.
!
! ** CONVERSION OF THE PROGRAM TO DOUBLE PRECISION **
! *********************************************************************
! * On computers having short word length (as the IBM 360/370) it may *
! * be desirable to perform all calculations in double precision.  In *
! * this case, the iterative refinement presently included in solve2  *
! * SHOULD BE OMITTED.                                                *
! * TO CONVERT THE PROGRAM TO DOUBLE PRECISION, THE FOLLOWING         *
! * APPROACH IS SUGGESTED.                                            *
! *                                                                   *
! * 1. VARIABLES PRESENTLY DECLARED TO BE REAL SHOULD BE DECLARED     *
! *    DOUBLE PRECISION.  THOSE TYPED INTEGER, DOUBLE PRECISION AND   *
! *    LOGICAL SHOULD NOT BE CHANGED.                                 *
! * 2. THE USE OF FAIL, NUMIT AND digitx SHOULD BE OMITTED.           *
! * 3. DESCRIPTION OF VARIABLE c (AT L2B 690-790) SHOULD READ --      *
! *    c  VECTOR HAVING AT LEAST 6*(m+n) ELEMENTS USED ONLY FOR       *
! *       INTERNAL WORK SPACE.                                        *
! * 4. The value of eta (at L2B 1960) should be set so that it is the *
! *    SMALLEST POSITIVE DOUBLE PRECISION NUMBER SUCH THAT 1.0 + eta  *
! *    IS GREATER THAN 1.0 IN DOUBLE PRECISION ARITHMETIC.            *
! *    FOR IBM COMPUTER TYPE, eta = 16.**(-13)                        *
! *    FOR UNIVAC COMPUTER TYPE, eta = 2.**(-59)                      *
! * 5. THE FOLLOWING FORTRAN FUNCTIONS SHOULD BE CHANGED --           *
! *      SINGLE PRECISION NAME     DOUBLE PRECISION NAME              *
! *             dble(x)                x                              *
! *             FLOAT(n)               dble(FLOAT(n))                 *
! *             sqrt(x)                dsqrt(x)                       *
! *    dble(x) IS USED IN SUBROUTINES decom2, solve2, solve3 AND      *
! *       covar.                                                      *
! *    FLOAT(n) IS USED IN SUBROUTINE decom2.                         *
! *    sqrt(x) IS USED IN SUBROUTINE l2slv.                           *
! * 6. REPLACE STATEMENT L2B 2500 BY A STATEMENT READING              *
! *          k3 = 1                                                   *
! * 7. FURTHER DETAILS ARE GIVEN IN SUBROUTINE solve2 IN CONNECTION   *
! *    WITH THE OMISSION OF ITERATIVE REFINEMENT.                     *
! * 8. In subroutine l2slv, statements L2B 950-1000, 1820-1830, 2020, *
! *    2350-2360, 2480-2490, 3070, 3280-3570 AND 3590-3620 SHOULD BE  *
! *    OMITTED.                                                       *
! *    STATEMENT NUMBERS GIVEN HERE REFER TO THOSE IN THE RIGHT-HAND  *
! *    MARGIN.  CERTAIN COMMENTS IN SUBROUTINE l2slv DO NOT APPLY TO  *
! *    THE DOUBLE PRECISION VERSION.                                  *
! *                                                                   *
! *********************************************************************
!
integer, intent(inout) :: ipivot(n)
real, intent(in) :: a(mm,n), b(mb,l)
real, intent(inout) :: c(*)
real :: eta
real, intent(inout) :: qr(mmpnn,n), res(mr,l), tol, w(m), x(nn,l)
real :: digitx
logical :: fail
logical :: sing
!
! Set value of eta, a machine-dependent parameter.
! eta, the relative machine precision, is the smallest positive real
! number such that 1.0 + eta is greater than 1.0 in floating-point
! arithmetic.
!
eta = spmpar(1)
!
! Default value for tol is zero.
!
if (tol.lt.0.0) tol = 0.0
ifault = 0
ksum = 0
!
! Perform initial checking of input parameters, dimensions and
! weights for possible errors.
!
if (m.gt.0 .and. n.gt.0 .and. l.gt.0) go to 10
ifault = 1
return
10 if (m1.le.m .and. m1.le.n .and. m1.ge.0) go to 20
ifault = 2
return
20 if (m.le.mm .and. m.le.mb .and. m.le.mr .and. n.le.nn &
&.and. m+n.le.mmpnn) go to 30
ifault = 3
return
30 do 40 i = 1,m
  if (m1.gt.0 .and. i.le.m1) w(i) = 1.0
  if (w(i).ge.0.0) go to 40
  ifault = 4
  return
40 continue
!
! Set parameters which allocate vector c to contain certain final
! results and also to be used as work space.
!
! k1 is starting point for NUMIT and fail, of length l.
! k2 is starting point for digitx, of length l.
! k3 is starting point for D, of length n.
! k4 is starting point for k-TH column of b, of length m.
! K5 is starting point for k-TH column of x, of length n.
! K6 is starting point for k-TH column of res, of length m.
! K7 is starting point for work space of length m.
! K8 is starting point for work space of length m.
! K9 is starting point for work space of length n.
! k10 is starting point for work space of length n.
! k11 is starting point for work space of length m + n.
! k12 is starting point for work space of length m + n.
!
k1 = 1
k2 = k1 + l
k3 = k2 + l
k4 = k3 + n
k5 = k4 + m
k6 = k5 + n
k7 = k6 + m
k8 = k7 + m
k9 = k8 + m
k10 = k9 + n
k11 = k10 + n
k12 = k11 + m + n
k = k12 + m + n - 1
!
! Multiply each row of matrix a (m by n) by its appropriate weight and
! store the result in the first m rows of array qr.  Set array c and
! the last n rows of array qr equal to zero.
!
do i=1,k
  c(i) = 0.0
end do
mp1 = m + 1
mpn = m + n
do j=1,n
  do i=1,m
    qr(i,j) = a(i,j)*w(i)
  end do
  do i=mp1,mpn
    qr(i,j) = 0.0
  end do
end do
!
! Obtain an orthogonal decomposition of the matrix stored in the first
! m rows of array qr and compute its rank.
!
call decom2(m, n, m1, eta, tol, qr, c(k3), n1, ipivot, sing, &
&mmpnn)
!
if (.not.sing) go to 110
if (n1.gt.0) go to 100
ifault = 5
return
100 ifault = 6
return
!
! Seek a solution (coefficients and residuals) for each of the l least
! squares problems whose right-hand sides are given in the array b.
!
110 iter = -alog10(eta)
do 200 k = 1,l
! k-TH right-hand side.
  k0 = k4 - 1
  do i=1,m
    k0 = k0 + 1
    c(k0) = b(i,k)
  end do
!
  call solve2(m, n, m1, a, c(k4), w, n1, ipivot, qr, c(k3), &
&eta, fail, numit, digitx, &
&c(k5), c(k6), c(k7), c(k8), c(k9), c(k10), c(k11), c(k12), &
&mm, mmpnn)
!
  k0 = k5 - 1
  do j=1,n
    k0 = k0 + 1
    x(j,k) = c(k0)
  end do
  if (m1.eq.0) go to 150
  do i=1,m1
    res(i,k) = 0.0
  end do
150 m1p1 = m1 + 1
  if (m1p1.gt.m) go to 170
  k0 = k6 + m1 - 1
  do i=m1p1,m
    k0 = k0 + 1
    res(i,k) = c(k0)
  end do
170 continue
!
! For right-hand sides where convergence of a solution is reported,
! a check is made for evidence of severe ill-conditioning.  Such
! evidence is furnished by large values of NUMIT (number of iterations
! before convergence was obtained) and small values of digitx
! (estimate of the number of correct digits in the initial solution
! of the coefficients).  If NUMIT exceeds -ALOG10(eta) then ifault
! is set to 9.  If digitx is less than 0.5 (half a decimal digit)
! then ifault is set to 10.
!
  c(k) = float(numit)
  if (fail) c(k) = -c(k)
  k0 = k2 + k - 1
  c(k0) = digitx
  if (.not.fail) go to 180
! KSUM is a tally of solutions which failed to converge.
  ksum = ksum + 1
  ifault = 8
  go to 200
180 if (numit.le.iter) go to 190
  ifault = 9
190 if (digitx.ge.0.5) go to 200
  ifault = 10
200 continue
if (ksum.lt.l) go to 210
ifault = 7
return
210 if (n1.lt.n) return
do i=1,n
  mpi = m + i
  do j=1,n
    qr(i,j) = qr(mpi,j)
  end do
  qr(i,i) = 0.0
end do
!
! Compute the unscaled covariance matrix of the coefficients.
!
call covar(n, m1, n1, ipivot, qr, c(k3), c(k9), mmpnn)
if (n.eq.1) go to 260
do j=2,n
jm1 = j - 1
  do 240 i = 1,jm1
240 qr(i,j) = qr(j,i)
end do
!
! In certain problems, some diagonal terms of the unscaled covariance
! matrix are equal to zero or to small positive numbers.  Because of
! rounding errors, computed values for these terms may be small
! negative numbers.  ifault is set to 11 if this occurs.
!
260 do j=1,n
  if (qr(j,j).lt.0.0) go to 280
end do
return
280 if (ifault.ne.0) go to 290
ifault = 11
return
290 ifault = 12
return
end subroutine l2slv

!     subroutine decom2(...)
! subroutine decom2 uses a modified Gram-Schmidt algorithm with
! pivoting to obtain an orthogonal decomposition of the input matrix
! given in QR.
! The input parameter tol (equal either to zero or to a positive
! number) is used in determining the rank of matrix qr.
! Note --
!     (1) if tol equals zero, the tolerance used at statement DC2 1180
!         will be based on machine precision.
!         Under this approach, the tolerance (TOL2) is set equal to
!         (FLOAT(n)*eta)**2*D(m1+1) AT STATEMENT DC2 1170.
!         If desired, the user can obtain a more conservative
!         tolerance by replacing n in this statement by a larger
!         quantity.
!     (2) If tol is greater than zero, TOL2 (which is set equal to
!         tol) will be used at statement DC2 1180 as an absolute
!         tolerance for comparison with diagonal elements of the
!         triangular matrix obtained in the decomposition.  Under this
!         approach, the value of tol can be based on knowledge
!         concerning the accuracy of the data.
! On exit, the arrays QR, D and ipivot contain the results of the
! decomposition which are needed for obtaining an initial solution
! and for iterative refinement.
! On exit, n1 is the computed rank of the input matrix qr.
! On exit, sing is set equal to .True. Whenever
!     (1) n1 = 0 (I.E., INPUT MATRIX qr EQUALS ZERO OR MATRIX OF
!         constraints equals zero), or
!     (2) n1 is less than m1 (I.E., The m1 by n matrix of linear
!         constraints is singular).
! OTHERWISE, ON EXIT FROM decom2, sing = .FALSE.
! On exit, the vector ipivot records the order in which the columns
! of QR were selected by the pivoting scheme in the course of the
! orthogonal decomposition.
subroutine decom2(m, n, m1, eta, tol, qr, d, n1, ipivot, sing, &
&mmpnn)
implicit none
integer, intent(in) :: m, m1, mmpnn, n
integer, intent(out) :: n1
integer :: ik, j, jj, k, km1, l, lmm, mh, mp1, mpn1, ms, mv, np, &
&ns, nsp1
integer, intent(inout) :: ipivot(n)
real :: c
real, intent(inout) :: d(*)
real :: dm, ds
real, intent(in) :: eta
real, intent(inout) :: qr(mmpnn,n)
real :: rsj
real, intent(in) :: tol
real :: tol2
double precision :: sum
logical :: finis, fsum
logical, intent(out) :: sing
n1 = 0
sing = .true.
fsum = .true.
mv = 1
mh = m1
ms = m
mp1 = m + 1
finis = .false.
if (tol.gt.0.0) tol2 = tol
do j=1,n
  d(j) = 0.0
  ipivot(j) = j
end do
! Step number NS of the decomposition.
do ns=1,n
  k = m + ns
  if (ns.eq.m1+1) go to 20
  go to 30
20 if (m1.eq.m) go to 200
  mv = m1 + 1
  mh = m
  fsum = .true.
30 if (.not.finis) go to 40
  go to 150
! Pivot search.
40 ds = 0.0
  np = ns
  do 90 j = ns,n
    if (fsum) go to 50
    go to 70
50 sum = 0.0
    do l=mv,mh
      sum = sum + dble(qr(l,j))*dble(qr(l,j))
    end do
    d(j) = sum
70 if (ds.lt.d(j)) go to 80
    go to 90
80 ds = d(j)
    np = j
90 continue
  if (fsum) dm = ds
  if (ds.lt.eta*dm) go to 100
  fsum = .false.
  go to 110
100 fsum = .true.
110 if (fsum) go to 40
  if (np.ne.ns) go to 120
  go to 140
! Column interchange.
120 ik = ipivot(np)
  ipivot(np) = ipivot(ns)
  ipivot(ns) = ik
  d(np) = d(ns)
  km1 = k - 1
  do l=1,km1
    c = qr(l,np)
    qr(l,np) = qr(l,ns)
    qr(l,ns) = c
  end do
! END COLUMN INTERCHANGE.
! END PIVOT SEARCH.
! RETURN HERE IF n1 = 0.  EITHER INPUT MATRIX qr EQUALS ZERO OR
! matrix of constraints equals zero.
140 if (ns.eq.1 .and. ds.eq.0.0) return
  go to 160
150 ms = k - 1
  mh = k - 1
160 if (finis) go to 170
  c = 0.0
  go to 180
170 c = 1.0
180 sum = dble(c)
  do l=mv,mh
    sum = sum + dble(qr(l,ns))*dble(qr(l,ns))
  end do
  d(ns) = sum
  ds = d(ns)
  if (tol.eq.0.0) tol2 = (float(n)*eta)**2*d(m1+1)
  if (.not.finis .and. ns.gt.m1 .and. ds.le.tol2) go to 200
  go to 290
200 finis = .true.
  mv = m + 1
  do np=ns,n
    if (1.gt.m1) go to 250
    do l=1,m1
      qr(l,np) = 0.0
    end do
    do j=1,m1
      sum = 0.0
      do l=1,m
        sum = sum + dble(qr(l,j))*dble(qr(l,np))
      end do
      c = sum
      c = c/d(j)
      do l=1,m1
        qr(l,np) = qr(l,np) - c*qr(l,j)
      end do
    end do
250 mpn1 = m + n1
    do jj=mp1,mpn1
      j = (m + 1) + (m + n1) - jj
      sum = 0.0
      do l=j,mpn1
        lmm = l - m
        sum = sum + dble(qr(j,lmm))*dble(qr(l,np))
      end do
      qr(j,np) = -sum
    end do
  end do
  go to 150
! RETURN HERE IF MATRIX OF CONSTRAINTS IS FOUND TO BE SINGULAR.
290 if (ds.eq.0.0) return
  qr(k,ns) = -1.0
  nsp1 = ns + 1
  if (nsp1.gt.n) go to 340
! Begin orthogonalization.
  do 330 j = nsp1,n
    sum = 0.0
    do l=mv,mh
      sum = sum + dble(qr(l,j))*dble(qr(l,ns))
    end do
    rsj = sum
    rsj = rsj/ds
    qr(k,j) = rsj
    do l=1,ms
      qr(l,j) = qr(l,j) - rsj*qr(l,ns)
    end do
    if (.not.finis) go to 320
    go to 330
320 d(j) = d(j) - ds*rsj*rsj
330 continue
! END ORTHOGONALIZATION.
340 if (.not.finis) n1 = n1 + 1
end do
! END STEP NUMBER NS.
sing = .false.
! Normal return.
return
end subroutine decom2

!     subroutine solve2(...)
! subroutine solve2 uses the orthogonal decomposition stored in QR, d
! and ipivot to compute the solution (coefficients and residuals)
! to the least squares problem whose right-hand side is given in B.
! In the event that n1 (the computed rank of matrix H) is less than n
! (the number of unknown coefficients), a unique solution vector having
! n elements can be obtained by imposing the condition that the
! solution be of minimal Euclidean norm.  Such a solution is sought in
! the case of underdetermined or rank-deficient problems.
! In normal exits, the solution is contained in the vector X
! (coefficients) and the vector RES (residuals).
! Iterative refinement is used to improve the accuracy of the initial
! solution.
! On exit, fail is set equal to .True. If the solution fails to
! IMPROVE SUFFICIENTLY.  OTHERWISE, FAIL = .FALSE.  INFORMATION ON THE
! behavior of the iterative refinement procedure is given by NUMIT and
! DIGITX.  NUMIT is the number of iterations carried out in attempting
! to obtain a solution.  DIGITX is an estimate of the number of
! correct digits in the initial solution of the coefficients.
! This subroutine calls subroutine solve3.
!
! ********* CONVERSION OF THIS SUBROUTINE TO DOUBLE PRECISION *********
! * if the program is converted so that all calculations are done in  *
! * DOUBLE PRECISION ARITHMETIC, THE ITERATIVE REFINEMENT PRESENTLY   *
! * INCLUDED IN solve2 SHOULD BE OMITTED, SINCE THE SUCCESS OF THIS   *
! * PROCEDURE DEPENDS ON COMPUTING INNER PRODUCTS IN GREATER          *
! * PRECISION THAN OTHER CALCULATIONS.                                *
! * SEE COMMENTS IN SUBROUTINE l2slv REGARDING CONVERSION TO DOUBLE   *
! * PRECISION.  IN ADDITION, THE FOLLOWING COMMENTS INDICATE HOW TO   *
! * OMIT THE ITERATIVE REFINEMENT FROM THIS SUBROUTINE.  STATEMENT    *
! * NUMBERS GIVEN HERE REFER TO THOSE IN THE RIGHT-HAND MARGIN.       *
! *                                                                   *
! * 1. IN STATEMENT SV2 470 CHANGE REAL TO DOUBLE PRECISION.          *
! * 2. REPLACE STATEMENT SV2 880 BY A STATEMENT READING               *
! *       30 DO 50 I=1,m                                              *
! * 3. REPLACE STATEMENTS SV2 1310-1400 BY A STATEMENT READING        *
! *          RETURN                                                   *
! * 4. OMIT STATEMENTS SV2 120-190, 440, 490-500, 520-550, 650,       *
! *    750-850, 1650-1830 AND 1850-1910.                              *
! *                                                                   *
! *********************************************************************
!
subroutine solve2(m, n, m1, a, b, w, n1, ipivot, qr, d, &
&eta, fail, numit, digitx, &
&x, res, wres, y1, y2, y, f, g, mm, mmpnn)
implicit none
integer, intent(in) :: m, m1, mm, mmpnn, n, n1
integer, intent(out) :: numit
integer :: i, j, k, kz, l, mp1, mpn, n1p1, np, ns
integer, intent(in) :: ipivot(n)
real, intent(in) :: a(mm,n), b(*)
real :: c
real, intent(in) :: d(*)
real, intent(inout) :: f(*), g(*)
real, intent(in) :: qr(mmpnn,n)
real, intent(inout) :: res(*)
real, intent(in) :: w(m)
real, intent(inout) :: wres(*), x(*), y(*), y1(*), y2(*)
real, intent(inout) :: digitx
real :: dxnorm
real, intent(in) :: eta
real :: eta2, rdr1, rdr2, rdx1, rdx2, rnr, rnx, xnorm
double precision :: sum
logical, intent(inout) :: fail
numit = 0
kz = 0
eta2 = eta*eta
mp1 = m + 1
mpn = m + n
n1p1 = n1 + 1
do 10 i = 1,m
  f(i) = b(i)*w(i)
  g(i) = 0.0
  wres(i) = 0.0
  res(i) = 0.0
  y1(i) = 0.0
  if (w(i).eq.0.0) kz = kz + 1
10 continue
do ns=1,n
  j = m + ns
  f(j) = 0.0
  g(j) = 0.0
  x(ns) = 0.0
  y2(ns) = 0.0
end do
k = 0
rdx2 = 0.0
rdr2 = 0.0
! Begin k-TH iteration step.
30 if (k.lt.2) go to 40
if (((64.*rdx2.lt.rdx1) .and. (rdx2.gt.eta2*rnx)) .or. &
&((64.*rdr2.lt.rdr1) .and. (rdr2.gt.eta2*rnr))) go to 40
go to 270
40 rdx1 = rdx2
rdr1 = rdr2
rdx2 = 0.0
rdr2 = 0.0
if (k.eq.0) go to 160
! New residuals.
do 50 i = 1,m
  wres(i) = wres(i) + f(i)*w(i)
  if (w(i).eq.0.0) go to 50
  res(i) = res(i) + f(i)/w(i)
  y1(i) = y1(i) + g(i)
50 continue
do 100 ns = 1,n
  j = m + ns
  np = ipivot(ns)
  x(np) = x(np) + f(j)
  y2(np) = y2(np) + g(j)
  sum = -dble(x(np))
  do l=1,m
    sum = sum + dble(a(l,np))*dble(y1(l))
  end do
  g(j) = -sum
  if (ns.gt.n1) go to 70
  go to 80
70 f(j) = 0.0
  go to 100
80 sum = 0.0
  do l=1,m
    sum = sum + dble(a(l,np))*dble(wres(l))
  end do
  f(j) = -sum
100 continue
do i=1,m
  sum = 0.0
  if (i.gt.m1) sum = dble(res(i))
  do l=1,n
    sum = sum + dble(a(i,l))*dble(x(l))
  end do
  sum = sum - dble(b(i))
  f(i) = -sum
  f(i) = f(i)*w(i)
  if (w(i).eq.0.0) res(i) = dble(res(i)) - sum
  sum = 0.0
  if (i.gt.m1) sum = dble(y1(i))
  do l=1,n
    sum = sum + dble(a(i,l))*dble(y2(l))
  end do
  g(i) = -sum
end do
if (n1p1.gt.n) go to 160
do i=n1p1,n
  ns = n + n1p1 - i
  j = m + ns
  sum = 0.0
  do l=1,j
    sum = sum + dble(qr(l,ns))*dble(g(l))
  end do
  g(j) = sum
end do
! END NEW RESIDUALS.
!
160 call solve3(f, m1, m, n1, qr, d, y, mmpnn)
!
if (n1p1.gt.n) go to 200
do ns=n1p1,n
  j = m + ns
  sum = dble(g(j))
  do l=mp1,j
    sum = sum + dble(qr(l,ns))*dble(f(l))
  end do
  c = sum
  c = c/d(ns)
  do i=1,j
    f(i) = f(i) - c*qr(i,ns)
  end do
end do
200 do j=mp1,mpn
  g(j) = 0.0
  if (j.le.m+n1) g(j) = g(j) + f(j)
end do
!
call solve3(g, m1, m, n1, qr, d, y, mmpnn)
!
do i=1,m
  rdr2 = rdr2 + f(i)*f(i)
end do
do i=mp1,mpn
  rdx2 = rdx2 + f(i)*f(i)
end do
if (k.ne.0) go to 240
rnr = rdr2
rnx = rdx2
240 if (k.ne.1) go to 260
xnorm = sqrt(rnx)
dxnorm = sqrt(rdx2)
if (xnorm.ne.0.0) go to 250
digitx = -alog10(eta)
go to 260
250 digitx = -alog10(amax1(dxnorm/xnorm,eta))
! END k-TH ITERATION STEP.
260 numit = k
k = k + 1
go to 30
270 if ((m1+kz.eq.m) .and. (rdx2.gt.4.*eta2*rnx)) go to 280
if ((rdr2.gt.4.*eta2*rnr) .and. &
&(rdx2.gt.4.*eta2*rnx)) go to 280
fail = .false.
return
280 fail = .true.
return
end subroutine solve2

subroutine solve3(f, m1, m, n1, qr, d, y, mmpnn)
implicit none
integer, intent(in) :: m, m1, mmpnn, n1
integer :: j, l, lmm, mh, mpl, mpn1, mv, ns, nsm1
! Subroutine solve3 is called only by subroutine solve2.
! This subroutine calculates new values of f.
real :: c
real, intent(in) :: d(*)
real, intent(inout) :: f(*)
real, intent(in) :: qr(mmpnn,n1)
real, intent(inout) :: y(*)
double precision :: sum
mv = 1
mh = m1
do ns=1,n1
  j = m + ns
  if (ns.eq.m1+1) go to 10
  go to 20
10 mv = m1 + 1
  mh = m
20 nsm1 = ns - 1
  sum = -dble(f(j))
  if (ns.eq.1) go to 40
  do l=1,nsm1
    mpl = m + l
    sum = sum + dble(qr(mpl,ns))*dble(y(l))
  end do
40 y(ns) = -sum
  if (ns.gt.m1) go to 50
  go to 60
50 c = -y(ns)
  go to 70
60 c = 0.0
70 sum = dble(c)
  do l=mv,mh
    sum = sum + dble(qr(l,ns))*dble(f(l))
  end do
  c = sum
  c = c/d(ns)
  f(j) = c
  do l=mv,m
    f(l) = f(l) - c*qr(l,ns)
  end do
end do
if (1.gt.m1) go to 150
do l=1,m1
  f(l) = 0.0
end do
do ns=1,m1
  sum = -dble(y(ns))
  do l=1,m
    sum = sum + dble(qr(l,ns))*dble(f(l))
  end do
  c = sum
  c = c/d(ns)
  do l=1,m1
    f(l) = f(l) - c*qr(l,ns)
  end do
end do
150 do ns=1,n1
  j = m + n1 + 1 - ns
  mpn1 = m + n1
  sum = 0.0
  do l=j,mpn1
    lmm = l - m
    sum = sum + dble(qr(j,lmm))*dble(f(l))
  end do
  f(j) = -sum
end do
return
end subroutine solve3

subroutine covar(n, m1, n1, ipivot, c, d, z, nn)
implicit none
integer, intent(in) :: m1, n, n1, nn
integer :: i, j, k, ka, l, n1p1
! Subroutine covar uses results from the orthogonal decomposition
! stored in c, d and ipivot to compute the unscaled covariance matrix
! of the least squares coefficients.
! On entry, the first n rows and the first n columns of c contain the
! upper triangular matrix obtained from the decomposition.  This input
! matrix is destroyed in subsequent calculations.
! On exit, the lower triangular portion of the symmetric unscaled
! covariance matrix is contained in
!     c(1,1)
!     c(2,1) c(2,2)
!     . . .
!     c(n,1) c(n,2) ... c(n,n)
! if n1 is less than n, one or more columns of the matrix
! H = (sqrt(W))*A WERE REJECTED AS BEING LINEARLY DEPENDENT.  WHENEVER
! the k-TH column of H was so rejected, c(i,j) is set equal to zero,
! FOR i = k OR j = k, i.GE.j.
integer, intent(in) :: ipivot(n)
real, intent(inout) :: c(nn,n)
real, intent(in) :: d(*)
real, intent(inout) :: z(*)
double precision :: sum
l = n1
if (l.gt.m1) c(l,l) = 1.0/d(l)
if (l.eq.1) go to 60
10 j = l - 1
if (j.gt.m1) c(j,j) = 1.0/d(j)
do k=l,n1
  z(k) = c(j,k)
end do
i = n1
do ka=j,n1
  sum = 0.0
  if (i.eq.j) sum = dble(c(i,j))
  do k=l,n1
    sum = sum - dble(z(k))*dble(c(k,i))
  end do
  c(i,j) = sum
  i = i - 1
end do
do k=l,n1
  c(j,k) = c(k,j)
end do
l = l - 1
if (l.gt.1) go to 10
60 if (n1.eq.n) go to 90
n1p1 = n1 + 1
do i=1,n
  do j=n1p1,n
    c(i,j) = 0.0
  end do
end do
! Permute the columns and rows of matrix c to account for pivoting.
90 do i=1,n
  do j=1,n
    k = ipivot(j)
    z(k) = c(i,j)
  end do
  do j=1,n
    c(i,j) = z(j)
  end do
end do
do i=1,n
  do j=1,n
    k = ipivot(j)
    z(k) = c(j,i)
  end do
  do j=i,n
    c(j,i) = z(j)
  end do
end do
return
end subroutine covar

subroutine splsq(m,n,a,ia,ja,damp,u,x,atol,btol,conlim,itnlim, &
&istop,itn,acond,rnorm,xnorm,w)
implicit none
integer :: npi
!
integer, intent(in) :: m
integer :: n
integer, intent(in) :: itnlim
integer, intent(inout) :: istop
integer, intent(in) :: ia(*), ja(*)
real, intent(in) :: a(*), damp
real, intent(inout) :: u(m), x(n)
real, intent(in) :: atol, btol, conlim
real, intent(inout) :: acond, rnorm, xnorm, w(*)
!     ------------------------------------------------------------------
!
!     splsq finds a solution x to the following problems ...
!
!     1. UNSYMMETRIC EQUATIONS --    SOLVE  a*x = B
!
!     2. LINEAR LEAST SQUARES  --    SOLVE  a*x = B
!                                    in the least-squares sense
!
!     3. DAMPED LEAST SQUARES  --    SOLVE  (   a    )*x = ( B )
!                                           ( damp*i )     ( 0 )
!                                    in the least-squares sense
!
!     Where A is a matrix with m rows and n columns, B an m-vector,
!     and damp a scalar. (All quantities are real.) The matrix a is
!     a sparse matrix stored rowwise in the arrays A,ia,ja.
!
!     The RHS vector B is input via u, and is subsequently overwritten.
!
!
!     Note. splsq uses an iterative method to approximate the solution.
!     The number of iterations required to reach a certain accuracy
!     depends strongly on the scaling of the problem. Poor scaling of
!     the rows or columns of A should therefore be avoided whenever
!     possible.
!
!     For example, in problem 1 the solution is unaltered by
!     row-scaling.  If a row of A is very small or large compared to
!     the other rows of A, the corresponding row of (A  B) should be
!     scaled up or down.
!
!     In problems 1 and 2, the solution x is easily recovered
!     following column scaling. In the absence of better information,
!     the nonzero columns of A should be scaled so that they all have
!     the same Euclidean norm (E.G.  1.0).
!
!     In problem 3, there is no freedom to RE-scale if damp is
!     nonzero. However, the value of damp should be assigned only
!     after attention has been paid to the scaling of A.
!
!     The parameter damp is intended to help regularize
!     ill-conditioned systems, by preventing the true solution from
!     being very large. Another aid to regularization is provided by
!     the parameter acond, which may be used to terminate iterations
!     before the computed solution becomes very large.
!
!
!     Notation
!     --------
!
!     The following quantities are used in discussing the subroutine
!     parameters...
!
!     abar   =  (   a    ),          bbar  =  ( b )
!               ( damp*i )                    ( 0 )
!
!     r      =  b  -  a*x,           rbar  =  bbar  -  abar*x
!
!     rnorm  =  sqrt( norm(r)**2  +  damp**2 * norm(x)**2 )
!            =  NORM( RBAR )
!
!     RELPR  =  THE SMALLEST FLOATING POINT NUMBER FOR WHICH
!               1 + RELPR .GT. 1.
!
!     splsq  minimizes the function rnorm with respect to x.
!
!
!     Parameters
!     ----------
!
!     m       INPUT      THE NUMBER OF ROWS IN A.
!
!     n       INPUT      THE NUMBER OF COLUMNS IN A.
!
!     a,ia,ja INPUT      THE MATRIX a STORED ROWWISE IN SPARSE FORM.
!
!     DAMP    INPUT      THE DAMPING PARAMETER FOR PROBLEM 3 ABOVE.
!                        (Damp  should be 0.0 for problems 1 and 2.)
!                        IF THE SYSTEM  a*x = B  IS INCOMPATIBLE, VALUES
!                        of damp in the range 0 to sqrt(RELPR)*NORM(a)
!                        will probably have a negligible effect.
!                        Larger values of damp will tend to decrease
!                        the norm of x and to reduce the number of
!                        iterations required by splsq.
!
!                        The work per iteration and the storage needed
!                        by splsq are the same for all values of damp.
!
!     u(m)    INPUT      THE RHS VECTOR B. BE AWARE THAT u IS
!                        over-written by splsq.
!
!     x(n)    OUTPUT     RETURNS THE COMPUTED SOLUTION x.
!
!     atol    INPUT      AN ESTIMATE OF THE RELATIVE ERROR IN THE DATA
!                        defining the matrix a. for example,
!                        if A is accurate to about 6 digits, set
!                        atol = 1.0e-6 .
!
!     btol    INPUT      AN ESTIMATE OF THE RELATIVE ERROR IN THE DATA
!                        defining the RHS vector B. for example,
!                        if B is accurate to about 6 digits, set
!                        btol = 1.0e-6 .
!
!     conlim  INPUT      AN UPPER LIMIT ON COND(ABAR), THE APPARENT
!                        condition number of the matrix abar.
!                        Iterations will be terminated if a computed
!                        estimate of COND(ABAR) exceeds conlim.
!                        This is intended to prevent certain small or
!                        zero singular values of A or ABAR from
!                        coming into effect and causing unwanted growth
!                        in the computed solution.
!
!                        conlim and damp may be used separately or
!                        together to regularize ill-conditioned systems.
!
!                        Normally, conlim should be in the range
!                        1000  TO  1/RELPR.
!                        Suggested value --
!                        conlim = 1/(100*RELPR)  FOR COMPATIBLE SYSTEMS,
!                        conlim = 1/(10*sqrt(RELPR))  FOR LEAST SQUARES.
!
!             Note. If the user is not concerned about the parameters
!             atol, btol, and conlim, any or all of them may be set
!             to zero. The effect will be the same as the values
!             RELPR, RELPR, AND  1/RELPR  RESPECTIVELY.
!
!     itnlim  INPUT      AN UPPER LIMIT ON THE NUMBER OF ITERATIONS.
!                        Suggested value --
!                        itnlim = n/2     FOR WELL CONDITIONED SYSTEMS,
!                        itnlim = 4*n     OTHERWISE.
!
!     istop   OUTPUT     AN INTEGER GIVING THE REASON FOR TERMINATION...
!
!                0       x = 0  IS THE EXACT SOLUTION.
!                        No iterations were performed.
!
!                1       THE EQUATIONS  a*x = B  ARE PROBABLY
!                        compatible. NORM(a*x - B) is sufficiently
!                        small, given the values of atol and btol.
!
!                2       THE SYSTEM  a*x = B  IS PROBABLY NOT
!                        compatible. A least-squares solution has
!                        been obtained which is sufficiently accurate,
!                        given the value of atol.
!
!                3       AN ESTIMATE OF COND(ABAR) HAS EXCEEDED
!                        conlim. THE SYSTEM  a*x = B  APPEARS TO BE
!                        ill-conditioned.
!
!                4       THE EQUATIONS  a*x = B  ARE PROBABLY
!                        compatible. NORM(a*x - B) is as small as
!                        seems reasonable on this machine.
!
!                5       THE SYSTEM  a*x = B  IS PROBABLY NOT
!                        compatible. A least-squares solution has
!                        been obtained which is as accurate as seems
!                        reasonable on this machine.
!
!                6       COND(ABAR) SEEMS TO BE SO LARGE THAT THERE IS
!                        not much point in doing further iterations,
!                        given the precision of this machine.
!
!                7       THE ITERATION LIMIT itnlim WAS REACHED.
!
!
!     itn     OUTPUT     THE NUMBER OF ITERATIONS THAT WERE PERFORMED.
!
!     acond   OUTPUT     AN ESTIMATE OF COND(ABAR), THE CONDITION
!                        number of ABAR.
!
!     rnorm   OUTPUT     AN ESTIMATE OF THE FINAL VALUE OF NORM(RBAR),
!                        the function being minimized (see notation
!                        ABOVE). THIS WILL BE SMALL IF  a*x = B  HAS
!                        A SOLUTION.
!
!     xnorm   OUTPUT     AN ESTIMATE OF THE NORM OF THE FINAL
!                        solution vector x.
!
!     w(2*n)             WORKSPACE
!
!     anorm   LOCAL      AN ESTIMATE OF THE FROBENIUS NORM OF ABAR.
!                        This is the square root of the sum of squares
!                        of the elements of ABAR.
!                        If damp is small and if the columns of A
!                        have all been scaled to have length  1.0,
!                        anorm should increase to roughly sqrt(n).
!
!     arnorm  LOCAL      AN ESTIMATE OF THE FINAL VALUE OF
!                        NORM( ABAR(TRANSPOSE)*RBAR ), the norm of
!                        the residual for the usual normal equations.
!                        This should be small in all cases. (arnorm
!                        will often be smaller than the true value
!                        computed from the output vector x.)
!
!
!     Subroutines and functions used
!     ------------------------------
!
!                normlz,mvprd1,mtprd1
!     BLAS       scopy,snrm2,sscal  (SEE LAWSON ET AL. BELOW)
!                (snrm2 is used only in normlz)
!     FORTRAN    ABS,SQRT
!
!
!     References
!     ----------
!
!     Paige, C.C. and saunders, M.A.  lsqr, an algorithm for sparse
!        linear equations and sparse least squares.
!        ACM transactions on mathematical software 8, 1 (March 1982).
!
!     Lawson, C.L., Hanson, R.J., Kincaid, D.R. and krogh, F.T.
!        BASIC linear algebra subprograms for Fortran usage.
!        ACM transactions on mathematical software 5, 3 (sept 1979),
!        308-323 and 324-325.
!
!     ------------------------------------------------------------------
!
!     Local variables
!
integer :: i
integer, intent(inout) :: itn
integer :: nconv, nstop
real :: alfa, anorm, arnorm, bbnorm, beta, bnorm, cs, cs1, cs2, &
&ctol, dampsq, ddnorm, delta, gamma, gambar, one, phi, phibar, psi, &
&res1, res2, rho, rhobar, rhbar1, rhbar2, rhs, rtol, sn, sn1, sn2, &
&t, tau, test1, test2, test3, theta, t1, t2, t3, xxnorm, z, zbar, &
&zero
!
!
!     Initialize.
!
zero   = 0.0
one    = 1.0
ctol   = zero
if (conlim .gt. zero) ctol = one/conlim
dampsq = damp**2
anorm  = zero
acond  = zero
bbnorm = zero
ddnorm = zero
res2   = zero
xnorm  = zero
xxnorm = zero
cs2    = -one
sn2    = zero
z      = zero
itn    = 0
istop  = 0
nstop  = 0
!
do i = 1, n
   w(i) = zero
   x(i) = zero
end do
!
!     Set up the first vectors for the bidiagonalization.
!     THESE SATISFY   beta*u = B,   alfa*w = a(TRANSPOSE)*u.
!
call normlz(m,u,beta)
call mtprd1(m,n,a,ia,ja,u,w)
call normlz(n,w,alfa)
call scopy (n,w,1,w(n+1),1)
!
rhobar = alfa
phibar = beta
bnorm  = beta
rnorm  = beta
arnorm = alfa*beta
if (arnorm .le. zero) go to 800
!
!     ------------------------------------------------------------------
!     Main iteration loop.
!     ------------------------------------------------------------------
100 itn = itn + 1
!
!     Perform the next step of the bidiagonalization to obtain the
!     next  beta, u, alfa, w.  these satisfy the relations
!                beta*u  =  a*w  -  alfa*u,
!                alfa*w  =  a(TRANSPOSE)*u  -  beta*w.
!
call sscal (m,(-alfa),u,1)
call mvprd1(m,n,a,ia,ja,w,u)
call normlz(m,u,beta)
bbnorm = bbnorm + alfa**2 + beta**2 + dampsq
call sscal (n,(-beta),w,1)
call mtprd1(m,n,a,ia,ja,u,w)
call normlz(n,w,alfa)
!
!
!     Use a plane rotation to eliminate the damping parameter.
!     This alters the diagonal (RHOBAR) of the lower-bidiagonal matrix.
!
rhbar2 = rhobar**2 + dampsq
rhbar1 = sqrt(rhbar2)
cs1    = rhobar/rhbar1
sn1    = damp/rhbar1
psi    = sn1*phibar
phibar = cs1*phibar
!
!
!     Use a plane rotation to eliminate the subdiagonal element (beta)
!     of the lower-bidiagonal matrix, giving an upper-bidiagonal matrix.
!
rho    = sqrt(rhbar2 + beta**2)
cs     = rhbar1/rho
sn     = beta/rho
theta  =  sn*alfa
rhobar = -cs*alfa
phi    =  cs*phibar
phibar =  sn*phibar
tau    =  sn*phi
!
!
!     Update x and w(n+1),...,w(2*n)
!
t1 =    phi/rho
t2 = -theta/rho
t3 =    one/rho
!
do i = 1, n
   npi   = n + i
   t     = w(npi)
   x(i)  = t1*t + x(i)
   w(npi)= t2*t + w(i)
   t     =(t3*t)**2
   ddnorm= t + ddnorm
end do
!
!
!     Use a plane rotation on the right to eliminate the
!     super-diagonal element (THETA) of the upper-bidiagonal matrix.
!     Then use the result to estimate NORM(x).
!
delta  =  sn2*rho
gambar = -cs2*rho
rhs    = phi - delta*z
zbar   = rhs/gambar
xnorm  = sqrt(xxnorm + zbar**2)
gamma  = sqrt(gambar**2 + theta**2)
cs2    = gambar/gamma
sn2    = theta/gamma
z      = rhs/gamma
xxnorm = xxnorm + z**2
!
!
!     Test for convergence.
!     First, estimate the norm and condition of the matrix abar,
!     and the norms of RBAR and ABAR(TRANSPOSE)*RBAR.
!
anorm  = sqrt(bbnorm)
acond  = anorm*sqrt(ddnorm)
res1   = phibar**2
res2   = res2 + psi**2
rnorm  = sqrt(res1 + res2)
arnorm = alfa*abs(tau)
!
!     Now use these norms to estimate certain other quantities,
!     some of which will be small near a solution.
!
test1  = rnorm/bnorm
test2  = arnorm/(anorm*rnorm)
test3  = one/acond
t1     = test1/(one + anorm*xnorm/bnorm)
rtol   = btol +  atol*anorm*xnorm/bnorm
!
!     The following tests guard against extremely small values of
!     atol, btol, or CTOL.  (The user may have set any or all of
!     the parameters atol, btol, conlim to zero.)
!     the effect is equivalent to the normal tests using
!     atol = relpr,  btol = relpr,  conlim = 1/relpr.
!
t3 = one + test3
t2 = one + test2
t1 = one + t1
if (itn .ge. itnlim) istop = 7
if (t3  .le. one   ) istop = 6
if (t2  .le. one   ) istop = 5
if (t1  .le. one   ) istop = 4
!
!     Allow for tolerances set by the user.
!
if (test3 .le. ctol) istop = 3
if (test2 .le. atol) istop = 2
if (test1 .le. rtol) istop = 1
!
!     STOP IF APPROPRIATE.
!     The convergence criteria are required to be met on  nconv
!     consecutive iterations, where  nconv  is set below.
!     SUGGESTED VALUE --   nconv = 1, 2  OR  3.
!
if (istop .eq. 0) nstop = 0
if (istop .eq. 0) go to 100
nconv = 1
nstop = nstop + 1
if (nstop .lt. nconv  .and.  itn .lt. itnlim) istop = 0
if (istop .eq. 0) go to 100
!     ------------------------------------------------------------------
!     END OF ITERATION LOOP.
!     ------------------------------------------------------------------
!
800 return
end subroutine splsq

subroutine normlz(n,x,beta)
implicit none
integer, intent(in) :: n
real, intent(inout) :: x(n)
real, intent(out) :: beta
!
!     normlz computes the Euclidean norm of x and returns the
!     value in beta. If x is nonzero, then x is rescaled so
!     THAT NORM(x) = 1.
!
!     Functions and subroutines
!
!     BLAS       snrm2,sscal
!
real :: one, snrm2, zero
!
data zero/0.0/, one/1.0/
!
!
beta = snrm2(n,x,1)
if (beta .gt. zero) call sscal(n,(one/beta),x,1)
return
end subroutine normlz

subroutine stlsq(m,n,ta,ita,jta,damp,u,x,atol,btol,conlim, &
&itnlim,istop,itn,acond,rnorm,xnorm,w)
implicit none
integer :: npi
!
integer, intent(in) :: m
integer :: n
integer, intent(in) :: itnlim
integer, intent(inout) :: istop
integer, intent(in) :: ita(*), jta(*)
real, intent(in) :: ta(*), damp
real, intent(inout) :: u(m), x(n)
real, intent(in) :: atol, btol, conlim
real, intent(inout) :: acond, rnorm, xnorm, w(*)
!     ------------------------------------------------------------------
!
!     stlsq finds a solution x to the following problems ...
!
!     1. UNSYMMETRIC EQUATIONS --    SOLVE  A*x = B
!
!     2. LINEAR LEAST SQUARES  --    SOLVE  A*x = B
!                                    in the least-squares sense
!
!     3. DAMPED LEAST SQUARES  --    SOLVE  (   A    )*x = ( B )
!                                           ( damp*i )     ( 0 )
!                                    in the least-squares sense
!
!     Where A is a matrix with m rows and n columns, B an m-vector,
!     and damp A scalar. (All quantities are real.) The matrix A is
!     a sparse matrix whose transpose is stored rowwise in the arrays
!     ta,ita,jta.
!
!     The RHS vector B is input via u, and is subsequently overwritten.
!
!
!     Note. stlsq uses an iterative method to approximate the solution.
!     The number of iterations required to reach a certain accuracy
!     depends strongly on the scaling of the problem. Poor scaling of
!     the rows or columns of A should therefore be avoided whenever
!     possible.
!
!     For example, in problem 1 the solution is unaltered by
!     row-scaling.  If a row of A is very small or large compared to
!     the other rows of A, the corresponding row of (A  B) should be
!     scaled up or down.
!
!     In problems 1 and 2, the solution x is easily recovered
!     following column scaling. In the absence of better information,
!     the nonzero columns of A should be scaled so that they all have
!     the same Euclidean norm (E.G.  1.0).
!
!     In problem 3, there is no freedom to RE-scale if damp is
!     nonzero. However, the value of damp should be assigned only
!     after attention has been paid to the scaling of A.
!
!     The parameter damp is intended to help regularize
!     ill-conditioned systems, by preventing the true solution from
!     being very large. Another aid to regularization is provided by
!     the parameter acond, which may be used to terminate iterations
!     before the computed solution becomes very large.
!
!
!     Notation
!     --------
!
!     The following quantities are used in discussing the subroutine
!     parameters...
!
!     abar   =  (   a    ),          bbar  =  ( b )
!               ( damp*i )                    ( 0 )
!
!     r      =  b  -  a*x,           rbar  =  bbar  -  abar*x
!
!     rnorm  =  sqrt( norm(r)**2  +  damp**2 * norm(x)**2 )
!            =  NORM( RBAR )
!
!     RELPR  =  THE SMALLEST FLOATING POINT NUMBER FOR WHICH
!               1 + RELPR .GT. 1.
!
!     stlsq  minimizes the function rnorm with respect to x.
!
!
!     Parameters
!     ----------
!
!     m       INPUT      THE NUMBER OF ROWS IN A.
!
!     n       INPUT      THE NUMBER OF COLUMNS IN A.
!
!     ta,ita  INPUT      THE TRANSPOSE OF THE MATRIX A IS STORED
!      jta               ROWWISE IN SPARSE FORM.
!
!     DAMP    INPUT      THE DAMPING PARAMETER FOR PROBLEM 3 ABOVE.
!                        (Damp  should be 0.0 for problems 1 and 2.)
!                        IF THE SYSTEM  A*x = B  IS INCOMPATIBLE, VALUES
!                        of damp in the range 0 to sqrt(RELPR)*NORM(A)
!                        will probably have a negligible effect.
!                        Larger values of damp will tend to decrease
!                        the norm of x and to reduce the number of
!                        iterations required by stlsq.
!
!                        The work per iteration and the storage needed
!                        by stlsq are the same for all values of damp.
!
!     u(m)    INPUT      THE RHS VECTOR B. BE AWARE THAT u IS
!                        over-written by stlsq.
!
!     x(n)    OUTPUT     RETURNS THE COMPUTED SOLUTION x.
!
!     atol    INPUT      AN ESTIMATE OF THE RELATIVE ERROR IN THE DATA
!                        defining the matrix A. for example,
!                        if A is accurate to about 6 digits, set
!                        atol = 1.0e-6 .
!
!     btol    INPUT      AN ESTIMATE OF THE RELATIVE ERROR IN THE DATA
!                        defining the RHS vector B. for example,
!                        if B is accurate to about 6 digits, set
!                        btol = 1.0e-6 .
!
!     conlim  INPUT      AN UPPER LIMIT ON COND(ABAR), THE APPARENT
!                        condition number of the matrix abar.
!                        Iterations will be terminated if a computed
!                        estimate of COND(ABAR) exceeds conlim.
!                        This is intended to prevent certain small or
!                        zero singular values of A or ABAR from
!                        coming into effect and causing unwanted growth
!                        in the computed solution.
!
!                        conlim and damp may be used separately or
!                        together to regularize ill-conditioned systems.
!
!                        Normally, conlim should be in the range
!                        1000  TO  1/RELPR.
!                        Suggested value --
!                        conlim = 1/(100*RELPR)  FOR COMPATIBLE SYSTEMS,
!                        conlim = 1/(10*sqrt(RELPR))  FOR LEAST SQUARES.
!
!             Note. If the user is not concerned about the parameters
!             atol, btol, and conlim, any or all of them may be set
!             to zero. The effect will be the same as the values
!             RELPR, RELPR, AND  1/RELPR  RESPECTIVELY.
!
!     itnlim  INPUT      AN UPPER LIMIT ON THE NUMBER OF ITERATIONS.
!                        Suggested value --
!                        itnlim = n/2     FOR WELL CONDITIONED SYSTEMS,
!                        itnlim = 4*n     OTHERWISE.
!
!     istop   OUTPUT     AN INTEGER GIVING THE REASON FOR TERMINATION...
!
!                0       x = 0  IS THE EXACT SOLUTION.
!                        No iterations were performed.
!
!                1       THE EQUATIONS  A*x = B  ARE PROBABLY
!                        compatible. NORM(A*x - B) is sufficiently
!                        small, given the values of atol and btol.
!
!                2       THE SYSTEM  A*x = B  IS PROBABLY NOT
!                        compatible. A least-squares solution has
!                        been obtained which is sufficiently accurate,
!                        given the value of atol.
!
!                3       AN ESTIMATE OF COND(ABAR) HAS EXCEEDED
!                        conlim. THE SYSTEM  A*x = B  APPEARS TO BE
!                        ill-conditioned.
!
!                4       THE EQUATIONS  A*x = B  ARE PROBABLY
!                        compatible. NORM(A*x - B) is as small as
!                        seems reasonable on this machine.
!
!                5       THE SYSTEM  A*x = B  IS PROBABLY NOT
!                        compatible. A least-squares solution has
!                        been obtained which is as accurate as seems
!                        reasonable on this machine.
!
!                6       COND(ABAR) SEEMS TO BE SO LARGE THAT THERE IS
!                        not much point in doing further iterations,
!                        given the precision of this machine.
!
!                7       THE ITERATION LIMIT itnlim WAS REACHED.
!
!
!     itn     OUTPUT     THE NUMBER OF ITERATIONS THAT WERE PERFORMED.
!
!     acond   OUTPUT     AN ESTIMATE OF COND(ABAR), THE CONDITION
!                        number of ABAR.
!
!     rnorm   OUTPUT     AN ESTIMATE OF THE FINAL VALUE OF NORM(RBAR),
!                        the function being minimized (see notation
!                        ABOVE). THIS WILL BE SMALL IF  A*x = B  HAS
!                        A SOLUTION.
!
!     xnorm   OUTPUT     AN ESTIMATE OF THE NORM OF THE FINAL
!                        solution vector x.
!
!     w(2*n)             WORKSPACE
!
!     anorm   LOCAL      AN ESTIMATE OF THE FROBENIUS NORM OF ABAR.
!                        This is the square root of the sum of squares
!                        of the elements of ABAR.
!                        If damp is small and if the columns of A
!                        have all been scaled to have length  1.0,
!                        anorm should increase to roughly sqrt(n).
!
!     arnorm  LOCAL      AN ESTIMATE OF THE FINAL VALUE OF
!                        NORM( ABAR(TRANSPOSE)*RBAR ), the norm of
!                        the residual for the usual normal equations.
!                        This should be small in all cases. (arnorm
!                        will often be smaller than the true value
!                        computed from the output vector x.)
!
!
!     Subroutines and functions used
!     ------------------------------
!
!                normlz,mvprd1,mtprd1
!     BLAS       scopy,snrm2,sscal  (SEE LAWSON ET AL. BELOW)
!                (snrm2 is used only in normlz)
!     FORTRAN    ABS,SQRT
!
!
!     References
!     ----------
!
!     Paige, C.C. and saunders, M.A.  lsqr, an algorithm for sparse
!        linear equations and sparse least squares.
!        ACM transactions on mathematical software 8, 1 (March 1982).
!
!     Lawson, C.L., Hanson, R.J., Kincaid, D.R. and krogh, F.T.
!        BASIC linear algebra subprograms for Fortran usage.
!        ACM transactions on mathematical software 5, 3 (sept 1979),
!        308-323 and 324-325.
!
!     ------------------------------------------------------------------
!
!     Local variables
!
integer :: i
integer, intent(inout) :: itn
integer :: nconv, nstop
real :: alfa, anorm, arnorm, bbnorm, beta, bnorm, cs, cs1, cs2, &
&ctol, dampsq, ddnorm, delta, gamma, gambar, one, phi, phibar, psi, &
&res1, res2, rho, rhobar, rhbar1, rhbar2, rhs, rtol, sn, sn1, sn2, &
&t, tau, test1, test2, test3, theta, t1, t2, t3, xxnorm, z, zbar, &
&zero
!
!
!     Initialize.
!
zero   = 0.0
one    = 1.0
ctol   = zero
if (conlim .gt. zero) ctol = one/conlim
dampsq = damp**2
anorm  = zero
acond  = zero
bbnorm = zero
ddnorm = zero
res2   = zero
xnorm  = zero
xxnorm = zero
cs2    = -one
sn2    = zero
z      = zero
itn    = 0
istop  = 0
nstop  = 0
!
do i = 1, n
   w(i) = zero
   x(i) = zero
end do
!
!     Set up the first vectors for the bidiagonalization.
!     THESE SATISFY   beta*u = B,   alfa*w = A(TRANSPOSE)*u.
!
call normlz(m,u,beta)
call mvprd1(n,m,ta,ita,jta,u,w)
call normlz(n,w,alfa)
call scopy (n,w,1,w(n+1),1)
!
rhobar = alfa
phibar = beta
bnorm  = beta
rnorm  = beta
arnorm = alfa*beta
if (arnorm .le. zero) go to 800
!
!     ------------------------------------------------------------------
!     Main iteration loop.
!     ------------------------------------------------------------------
100 itn = itn + 1
!
!     Perform the next step of the bidiagonalization to obtain the
!     next  beta, u, alfa, w.  these satisfy the relations
!                beta*u  =  A*w  -  alfa*u,
!                alfa*w  =  A(TRANSPOSE)*u  -  beta*w.
!
call sscal (m,(-alfa),u,1)
call mtprd1(n,m,ta,ita,jta,w,u)
call normlz(m,u,beta)
bbnorm = bbnorm + alfa**2 + beta**2 + dampsq
call sscal (n,(-beta),w,1)
call mvprd1(n,m,ta,ita,jta,u,w)
call normlz(n,w,alfa)
!
!
!     Use a plane rotation to eliminate the damping parameter.
!     This alters the diagonal (RHOBAR) of the lower-bidiagonal matrix.
!
rhbar2 = rhobar**2 + dampsq
rhbar1 = sqrt(rhbar2)
cs1    = rhobar/rhbar1
sn1    = damp/rhbar1
psi    = sn1*phibar
phibar = cs1*phibar
!
!
!     Use a plane rotation to eliminate the subdiagonal element (beta)
!     of the lower-bidiagonal matrix, giving an upper-bidiagonal matrix.
!
rho    = sqrt(rhbar2 + beta**2)
cs     = rhbar1/rho
sn     = beta/rho
theta  =  sn*alfa
rhobar = -cs*alfa
phi    =  cs*phibar
phibar =  sn*phibar
tau    =  sn*phi
!
!
!     Update x and w(n+1),...,w(2*n)
!
t1 =    phi/rho
t2 = -theta/rho
t3 =    one/rho
!
do i = 1, n
   npi   = n + i
   t     = w(npi)
   x(i)  = t1*t + x(i)
   w(npi)= t2*t + w(i)
   t     =(t3*t)**2
   ddnorm= t + ddnorm
end do
!
!
!     Use a plane rotation on the right to eliminate the
!     super-diagonal element (THETA) of the upper-bidiagonal matrix.
!     Then use the result to estimate NORM(x).
!
delta  =  sn2*rho
gambar = -cs2*rho
rhs    = phi - delta*z
zbar   = rhs/gambar
xnorm  = sqrt(xxnorm + zbar**2)
gamma  = sqrt(gambar**2 + theta**2)
cs2    = gambar/gamma
sn2    = theta/gamma
z      = rhs/gamma
xxnorm = xxnorm + z**2
!
!
!     Test for convergence.
!     First, estimate the norm and condition of the matrix abar,
!     and the norms of RBAR and ABAR(TRANSPOSE)*RBAR.
!
anorm  = sqrt(bbnorm)
acond  = anorm*sqrt(ddnorm)
res1   = phibar**2
res2   = res2 + psi**2
rnorm  = sqrt(res1 + res2)
arnorm = alfa*abs(tau)
!
!     Now use these norms to estimate certain other quantities,
!     some of which will be small near a solution.
!
test1  = rnorm/bnorm
test2  = arnorm/(anorm*rnorm)
test3  = one/acond
t1     = test1/(one + anorm*xnorm/bnorm)
rtol   = btol +  atol*anorm*xnorm/bnorm
!
!     The following tests guard against extremely small values of
!     atol, btol, or CTOL.  (The user may have set any or all of
!     the parameters atol, btol, conlim to zero.)
!     the effect is equivalent to the normal tests using
!     atol = relpr,  btol = relpr,  conlim = 1/relpr.
!
t3 = one + test3
t2 = one + test2
t1 = one + t1
if (itn .ge. itnlim) istop = 7
if (t3  .le. one   ) istop = 6
if (t2  .le. one   ) istop = 5
if (t1  .le. one   ) istop = 4
!
!     Allow for tolerances set by the user.
!
if (test3 .le. ctol) istop = 3
if (test2 .le. atol) istop = 2
if (test1 .le. rtol) istop = 1
!
!     STOP IF APPROPRIATE.
!     The convergence criteria are required to be met on  nconv
!     consecutive iterations, where  nconv  is set below.
!     SUGGESTED VALUE --   nconv = 1, 2  OR  3.
!
if (istop .eq. 0) nstop = 0
if (istop .eq. 0) go to 100
nconv = 1
nstop = nstop + 1
if (nstop .lt. nconv  .and.  itn .lt. itnlim) istop = 0
if (istop .eq. 0) go to 100
!     ------------------------------------------------------------------
!     END OF ITERATION LOOP.
!     ------------------------------------------------------------------
!
800 return
end subroutine stlsq

subroutine blsq(m,n,a,ka,ml,mu,damp,u,x,atol,btol,conlim,itnlim, &
&istop,itn,acond,rnorm,xnorm,w)
implicit none
integer :: npi
!
integer, intent(in) :: m
integer :: n
integer, intent(in) :: ka, ml, mu, itnlim
integer, intent(inout) :: istop
real, intent(in) :: a(ka,n), damp
real, intent(inout) :: u(m), x(n)
real, intent(in) :: atol, btol, conlim
real, intent(inout) :: acond, rnorm, xnorm, w(*)
!     ------------------------------------------------------------------
!
!     blsq finds a solution x to the following problems ...
!
!     1. UNSYMMETRIC EQUATIONS --    SOLVE  a*x = B
!
!     2. LINEAR LEAST SQUARES  --    SOLVE  a*x = B
!                                    in the least-squares sense
!
!     3. DAMPED LEAST SQUARES  --    SOLVE  (   a    )*x = ( B )
!                                           ( damp*i )     ( 0 )
!                                    in the least-squares sense
!
!     Where A is a matrix with m rows and n columns, B an m-vector,
!     and damp a scalar. (All quantities are real.) The matrix a is
!     a banded matrix stored in band form.
!
!     The RHS vector B is input via u, and is subsequently overwritten.
!
!
!     Note. blsq uses an iterative method to approximate the solution.
!     The number of iterations required to reach a certain accuracy
!     depends strongly on the scaling of the problem. Poor scaling of
!     the rows or columns of A should therefore be avoided whenever
!     possible.
!
!     For example, in problem 1 the solution is unaltered by
!     row-scaling.  If a row of A is very small or large compared to
!     the other rows of A, the corresponding row of (A  B) should be
!     scaled up or down.
!
!     In problems 1 and 2, the solution x is easily recovered
!     following column scaling. In the absence of better information,
!     the nonzero columns of A should be scaled so that they all have
!     the same Euclidean norm (E.G.  1.0).
!
!     In problem 3, there is no freedom to RE-scale if damp is
!     nonzero. However, the value of damp should be assigned only
!     after attention has been paid to the scaling of A.
!
!     The parameter damp is intended to help regularize
!     ill-conditioned systems, by preventing the true solution from
!     being very large. Another aid to regularization is provided by
!     the parameter acond, which may be used to terminate iterations
!     before the computed solution becomes very large.
!
!
!     Notation
!     --------
!
!     The following quantities are used in discussing the subroutine
!     parameters...
!
!     abar   =  (   a    ),          bbar  =  ( b )
!               ( damp*i )                    ( 0 )
!
!     r      =  b  -  a*x,           rbar  =  bbar  -  abar*x
!
!     rnorm  =  sqrt( norm(r)**2  +  damp**2 * norm(x)**2 )
!            =  NORM( RBAR )
!
!     RELPR  =  THE SMALLEST FLOATING POINT NUMBER FOR WHICH
!               1 + RELPR .GT. 1.
!
!     blsq   MINIMIZES THE FUNCTION rnorm WITH RESPECT TO x.
!
!
!     Parameters
!     ----------
!
!     m       INPUT      THE NUMBER OF ROWS IN A.
!
!     n       INPUT      THE NUMBER OF COLUMNS IN A.
!
!     a       INPUT      THE MATRIX a STORED IN BAND FORM.
!
!     ka      INPUT      THE NUMBER OF ROWS IN THE DIMENSION STATEMENT
!                        for A in the calling program.
!
!     ml      INPUT      THE LOWER BAND WIDTH OF A.
!
!     mu      INPUT      THE UPPER BAND WIDTH OF A.
!
!     DAMP    INPUT      THE DAMPING PARAMETER FOR PROBLEM 3 ABOVE.
!                        (Damp  should be 0.0 for problems 1 and 2.)
!                        IF THE SYSTEM  a*x = B  IS INCOMPATIBLE, VALUES
!                        of damp in the range 0 to sqrt(RELPR)*NORM(a)
!                        will probably have a negligible effect.
!                        Larger values of damp will tend to decrease
!                        the norm of x and to reduce the number of
!                        iterations required by blsq.
!
!                        The work per iteration and the storage needed
!                        by blsq are the same for all values of damp.
!
!     u(m)    INPUT      THE RHS VECTOR B. BE AWARE THAT u IS
!                        over-written by blsq.
!
!     x(n)    OUTPUT     RETURNS THE COMPUTED SOLUTION x.
!
!     atol    INPUT      AN ESTIMATE OF THE RELATIVE ERROR IN THE DATA
!                        defining the matrix a. for example,
!                        if A is accurate to about 6 digits, set
!                        atol = 1.0e-6 .
!
!     btol    INPUT      AN ESTIMATE OF THE RELATIVE ERROR IN THE DATA
!                        defining the RHS vector B. for example,
!                        if B is accurate to about 6 digits, set
!                        btol = 1.0e-6 .
!
!     conlim  INPUT      AN UPPER LIMIT ON COND(ABAR), THE APPARENT
!                        condition number of the matrix abar.
!                        Iterations will be terminated if a computed
!                        estimate of COND(ABAR) exceeds conlim.
!                        This is intended to prevent certain small or
!                        zero singular values of A or ABAR from
!                        coming into effect and causing unwanted growth
!                        in the computed solution.
!
!                        conlim and damp may be used separately or
!                        together to regularize ill-conditioned systems.
!
!                        Normally, conlim should be in the range
!                        1000  TO  1/RELPR.
!                        Suggested value --
!                        conlim = 1/(100*RELPR)  FOR COMPATIBLE SYSTEMS,
!                        conlim = 1/(10*sqrt(RELPR))  FOR LEAST SQUARES.
!
!             Note. If the user is not concerned about the parameters
!             atol, btol, and conlim, any or all of them may be set
!             to zero. The effect will be the same as the values
!             RELPR, RELPR, AND  1/RELPR  RESPECTIVELY.
!
!     itnlim  INPUT      AN UPPER LIMIT ON THE NUMBER OF ITERATIONS.
!                        Suggested value --
!                        itnlim = n/2     FOR WELL CONDITIONED SYSTEMS,
!                        itnlim = 4*n     OTHERWISE.
!
!     istop   OUTPUT     AN INTEGER GIVING THE REASON FOR TERMINATION...
!
!                0       x = 0  IS THE EXACT SOLUTION.
!                        No iterations were performed.
!
!                1       THE EQUATIONS  a*x = B  ARE PROBABLY
!                        compatible. NORM(a*x - B) is sufficiently
!                        small, given the values of atol and btol.
!
!                2       THE SYSTEM  a*x = B  IS PROBABLY NOT
!                        compatible. A least-squares solution has
!                        been obtained which is sufficiently accurate,
!                        given the value of atol.
!
!                3       AN ESTIMATE OF COND(ABAR) HAS EXCEEDED
!                        conlim. THE SYSTEM  a*x = B  APPEARS TO BE
!                        ill-conditioned.
!
!                4       THE EQUATIONS  a*x = B  ARE PROBABLY
!                        compatible. NORM(a*x - B) is as small as
!                        seems reasonable on this machine.
!
!                5       THE SYSTEM  a*x = B  IS PROBABLY NOT
!                        compatible. A least-squares solution has
!                        been obtained which is as accurate as seems
!                        reasonable on this machine.
!
!                6       COND(ABAR) SEEMS TO BE SO LARGE THAT THERE IS
!                        not much point in doing further iterations,
!                        given the precision of this machine.
!
!                7       THE ITERATION LIMIT itnlim WAS REACHED.
!
!
!     itn     OUTPUT     THE NUMBER OF ITERATIONS THAT WERE PERFORMED.
!
!     acond   OUTPUT     AN ESTIMATE OF COND(ABAR), THE CONDITION
!                        number of ABAR.
!
!     rnorm   OUTPUT     AN ESTIMATE OF THE FINAL VALUE OF NORM(RBAR),
!                        the function being minimized (see notation
!                        ABOVE). THIS WILL BE SMALL IF  a*x = B  HAS
!                        A SOLUTION.
!
!     xnorm   OUTPUT     AN ESTIMATE OF THE NORM OF THE FINAL
!                        solution vector x.
!
!     w(2*n)             WORKSPACE
!
!     anorm   LOCAL      AN ESTIMATE OF THE FROBENIUS NORM OF ABAR.
!                        This is the square root of the sum of squares
!                        of the elements of ABAR.
!                        If damp is small and if the columns of A
!                        have all been scaled to have length  1.0,
!                        anorm should increase to roughly sqrt(n).
!
!     arnorm  LOCAL      AN ESTIMATE OF THE FINAL VALUE OF
!                        NORM( ABAR(TRANSPOSE)*RBAR ), the norm of
!                        the residual for the usual normal equations.
!                        This should be small in all cases. (arnorm
!                        will often be smaller than the true value
!                        computed from the output vector x.)
!
!
!     Subroutines and functions used
!     ------------------------------
!
!                normlz,bvprd1,btprd1
!     BLAS       scopy,snrm2,sscal  (SEE LAWSON ET AL. BELOW)
!                (snrm2 is used only in normlz)
!     FORTRAN    ABS,SQRT
!
!
!     References
!     ----------
!
!     Paige, C.C. and saunders, M.A.  lsqr, an algorithm for sparse
!        linear equations and sparse least squares.
!        ACM transactions on mathematical software 8, 1 (March 1982).
!
!     Lawson, C.L., Hanson, R.J., Kincaid, D.R. and krogh, F.T.
!        BASIC linear algebra subprograms for Fortran usage.
!        ACM transactions on mathematical software 5, 3 (sept 1979),
!        308-323 and 324-325.
!
!     ------------------------------------------------------------------
!
!     Local variables
!
integer :: i
integer, intent(inout) :: itn
integer :: nconv, nstop
real :: alfa, anorm, arnorm, bbnorm, beta, bnorm, cs, cs1, cs2, &
&ctol, dampsq, ddnorm, delta, gamma, gambar, one, phi, phibar, psi, &
&res1, res2, rho, rhobar, rhbar1, rhbar2, rhs, rtol, sn, sn1, sn2, &
&t, tau, test1, test2, test3, theta, t1, t2, t3, xxnorm, z, zbar, &
&zero
!
!
!     Initialize.
!
zero   = 0.0
one    = 1.0
ctol   = zero
if (conlim .gt. zero) ctol = one/conlim
dampsq = damp**2
anorm  = zero
acond  = zero
bbnorm = zero
ddnorm = zero
res2   = zero
xnorm  = zero
xxnorm = zero
cs2    = -one
sn2    = zero
z      = zero
itn    = 0
istop  = 0
nstop  = 0
!
do i = 1, n
   w(i) = zero
   x(i) = zero
end do
!
!     Set up the first vectors for the bidiagonalization.
!     THESE SATISFY   beta*u = B,   alfa*w = a(TRANSPOSE)*u.
!
call normlz(m,u,beta)
call btprd1(m,n,a,ka,ml,mu,u,w)
call normlz(n,w,alfa)
call scopy (n,w,1,w(n+1),1)
!
rhobar = alfa
phibar = beta
bnorm  = beta
rnorm  = beta
arnorm = alfa*beta
if (arnorm .le. zero) go to 800
!
!     ------------------------------------------------------------------
!     Main iteration loop.
!     ------------------------------------------------------------------
100 itn = itn + 1
!
!     Perform the next step of the bidiagonalization to obtain the
!     next  beta, u, alfa, w.  these satisfy the relations
!                beta*u  =  a*w  -  alfa*u,
!                alfa*w  =  a(TRANSPOSE)*u  -  beta*w.
!
call sscal (m,(-alfa),u,1)
call bvprd1(m,n,a,ka,ml,mu,w,u)
call normlz(m,u,beta)
bbnorm = bbnorm + alfa**2 + beta**2 + dampsq
call sscal (n,(-beta),w,1)
call btprd1(m,n,a,ka,ml,mu,u,w)
call normlz(n,w,alfa)
!
!
!     Use a plane rotation to eliminate the damping parameter.
!     This alters the diagonal (RHOBAR) of the lower-bidiagonal matrix.
!
rhbar2 = rhobar**2 + dampsq
rhbar1 = sqrt(rhbar2)
cs1    = rhobar/rhbar1
sn1    = damp/rhbar1
psi    = sn1*phibar
phibar = cs1*phibar
!
!
!     Use a plane rotation to eliminate the subdiagonal element (beta)
!     of the lower-bidiagonal matrix, giving an upper-bidiagonal matrix.
!
rho    = sqrt(rhbar2 + beta**2)
cs     = rhbar1/rho
sn     = beta/rho
theta  =  sn*alfa
rhobar = -cs*alfa
phi    =  cs*phibar
phibar =  sn*phibar
tau    =  sn*phi
!
!
!     Update x and w(n+1),...,w(2*n)
!
t1 =    phi/rho
t2 = -theta/rho
t3 =    one/rho
!
do i = 1, n
   npi   = n + i
   t     = w(npi)
   x(i)  = t1*t + x(i)
   w(npi)= t2*t + w(i)
   t     =(t3*t)**2
   ddnorm= t + ddnorm
end do
!
!
!     Use a plane rotation on the right to eliminate the
!     super-diagonal element (THETA) of the upper-bidiagonal matrix.
!     Then use the result to estimate NORM(x).
!
delta  =  sn2*rho
gambar = -cs2*rho
rhs    = phi - delta*z
zbar   = rhs/gambar
xnorm  = sqrt(xxnorm + zbar**2)
gamma  = sqrt(gambar**2 + theta**2)
cs2    = gambar/gamma
sn2    = theta/gamma
z      = rhs/gamma
xxnorm = xxnorm + z**2
!
!
!     Test for convergence.
!     First, estimate the norm and condition of the matrix abar,
!     and the norms of RBAR and ABAR(TRANSPOSE)*RBAR.
!
anorm  = sqrt(bbnorm)
acond  = anorm*sqrt(ddnorm)
res1   = phibar**2
res2   = res2 + psi**2
rnorm  = sqrt(res1 + res2)
arnorm = alfa*abs(tau)
!
!     Now use these norms to estimate certain other quantities,
!     some of which will be small near a solution.
!
test1  = rnorm/bnorm
test2  = arnorm/(anorm*rnorm)
test3  = one/acond
t1     = test1/(one + anorm*xnorm/bnorm)
rtol   = btol +  atol*anorm*xnorm/bnorm
!
!     The following tests guard against extremely small values of
!     atol, btol, or CTOL.  (The user may have set any or all of
!     the parameters atol, btol, conlim to zero.)
!     the effect is equivalent to the normal tests using
!     atol = relpr,  btol = relpr,  conlim = 1/relpr.
!
t3 = one + test3
t2 = one + test2
t1 = one + t1
if (itn .ge. itnlim) istop = 7
if (t3  .le. one   ) istop = 6
if (t2  .le. one   ) istop = 5
if (t1  .le. one   ) istop = 4
!
!     Allow for tolerances set by the user.
!
if (test3 .le. ctol) istop = 3
if (test2 .le. atol) istop = 2
if (test1 .le. rtol) istop = 1
!
!     STOP IF APPROPRIATE.
!     The convergence criteria are required to be met on  nconv
!     consecutive iterations, where  nconv  is set below.
!     SUGGESTED VALUE --   nconv = 1, 2  OR  3.
!
if (istop .eq. 0) nstop = 0
if (istop .eq. 0) go to 100
nconv = 1
nstop = nstop + 1
if (nstop .lt. nconv  .and.  itn .lt. itnlim) istop = 0
if (istop .eq. 0) go to 100
!     ------------------------------------------------------------------
!     END OF ITERATION LOOP.
!     ------------------------------------------------------------------
!
800 return
end subroutine blsq

subroutine fmin(f, a0, b0, x, w, aerr, rerr, error, ind)
implicit none
integer, intent(out) :: ind
!     ******************************************************************
!     Golden section minimization of a function f(T)
!     ******************************************************************
real :: f
real, intent(in) :: a0, b0
real, intent(inout) :: x, w
real, intent(in) :: aerr, rerr
real, intent(inout) :: error
real :: eps, eps0, atol, ftol, rtol, tol
real :: a, b, c1, c2, e, fu, fv, u, v
real :: spmpar
external f
!     -------------------
!     c1 = 1 - c2
!     c2 = 0.5*(-1 + sqrt(5))
!     -------------------
data eps0/5.e-3/
data c1/.3819660112501052/
data c2/.6180339887498948/
!     -------------------
!     ****** eps IS A MACHINE DEPENDENT CONSTANT. EPS IS THE
!            SMALLEST NUMBER SUCH THAT 1 + eps .GT. 1.
!
             eps = spmpar(1)
!     -------------------
a = a0
b = b0
ind = 0
atol = amax1(aerr,1.e-20)
ftol = amax1(2.0*eps,rerr)
rtol = amax1(7.0*eps,rerr)
!
e = b - a
u = a + c1*e
v = a + c2*e
fu = f(u)
fv = f(v)
!
!        Location of the region of a local minimum
!
10 if (e .le. eps0*(1.0 + abs(a))) go to 40
if (fu - fv) 20,11,30
11 if (fu .gt. f(b)) go to 30
!
20 b = v
e = b - a
v = u
u = a + c1*e
fv = fu
fu = f(u)
go to 10
!
30 a = u
e = b - a
u = v
v = a + c2*e
fu = fv
fv = f(v)
go to 10
!
40 if (a .gt. 0.0 .or. b .lt. 0.0) go to 41
   w = f(0.0)
   if (w .le. amin1(fu,fv)) go to 100
41 if (a .ne. a0) go to 42
   if (a .eq. 0.0) go to 201
   w = f(a)
   if (w .le. amin1(fu,fv)) go to 130
   go to 201
42 if (b .ne. b0) go to 201
   if (b .eq. 0.0) go to 201
   w = f(b)
   if (w .le. amin1(fu,fv)) go to 150
   go to 201
!
!              Check if 0 is a local minimum
!
100 if (b .le. atol) go to 110
x = 0.01*b
if (w .gt. f(x)) go to 180
b = x
go to 100
!
110 if (abs(a) .le. atol) go to 120
x = 0.01*a
if (w .gt. f(x)) go to 180
a = x
go to 110
!
120 x = 0.0
error = amax1(abs(a),b)
return
!
!             Check if a0 is a local minimum
!
130 tol = amax1(rtol*abs(a),atol)
131 x = a + 0.01*e
if (w .gt. f(x)) go to 180
b = x
e = b - a
if (e .gt. tol) go to 131
!
x = a
error = e
return
!
!             Check if b0 is a local minimum
!
150 tol = amax1(rtol*abs(b),atol)
151 x = b - 0.01*e
if (w .gt. f(x)) go to 180
a = x
e = b - a
if (e .gt. tol) go to 151
!
x = b
error = e
return
!
180 e = b - a
u = a + c1*e
v = a + c2*e
fu = f(u)
fv = f(v)
!
!             Refinement of the local minimum
!
200 ind = 0
201 if (fu .gt. fv) go to 210
!
b = v
e = b - a
v = u
u = a + c1*e
fv = fu
fu = f(u)
go to 220
!
210 a = u
e = b - a
u = v
v = a + c2*e
fu = fv
fv = f(v)
!
!        Checking the accuracy of the local minimum
!
220 if (e .le. amax1(rtol*abs(a),atol)) go to 240
if (abs(fv - fu) .gt. ftol*amax1(abs(fu),abs(fv))) go to 200
if (ind .eq. 1) go to 241
ind = 1
go to 201
!
!                    Report the results
!
240 ind = 0
241 if (fu - fv) 242,243,244
242 x = u
w = fu
error = c1*e
return
243 x = v
w = fv
error = e
return
244 x = v
w = fv
error = c1*e
return
end subroutine fmin

subroutine optf (fcn,n,rerr,iter,xpls,fpls,ierr,wrk)
implicit none
integer, intent(inout) :: ierr, iter
integer :: n
real, intent(inout) :: fpls
real, intent(in) :: rerr
integer :: i, itncnt, itnlim, mo
real :: eps, fscale, gradtl, stepmx, steptl
real :: spmpar
!-----------------------------------------------------------------------
!                 Interface to minimization package
!-----------------------------------------------------------------------
!
!     Input ...
!
!       FCN        NAME OF ROUTINE TO EVALUATE MINIMIZATION FUNCTION.
!                  Must be declared external in calling routine.
!       n          DIMENSION OF PROBLEM
!       rerr       RELATIVE ACCURACY OF SUBROUTINE fcn.
!
!     Input/output ...
!
!       ITER       ON INPUT ITER IS THE MAXIMUM NUMBER OF ITERATIONS
!                  that are permitted. On output iter is the number
!                  of iterations that were actually performed.
!       xpls(n)    LOCAL MINIMUM
!
!     Output ...
!
!       fpls       FUNCTION VALUE AT LOCAL MINIMUM xpls
!       ierr       TERMINATION CODE
!
!     Workspace ...
!
!       wrk(n,n+8)
!
!-----------------------------------------------------------------------
real, intent(inout) :: xpls(n), wrk(n,*)
external fcn
!
!     equivalence wrk(n,1) = x(n)
!                 wrk(n,2) = typsiz(n)
!                 wrk(n,3) = gpls(n)
!                 wrk(n,4) = g(n)
!                 wrk(n,5) = p(n)
!                 wrk(n,6) = wrk0(n)
!                 wrk(n,7) = wrk1(n)
!                 wrk(n,8) = wrk2(n)
!                 wrk(n,9) = a(n,n)
!
!
!     Set tolerances
!
eps = amax1(spmpar(1),abs(rerr))
gradtl = eps**0.4
stepmx = 0.0
steptl = eps
if (eps .le. 1.e-10) steptl = 10.0*eps
if (eps .lt. 1.e-13) steptl = 1.e2*eps
!
!     Initialization
!
mo = 0
itnlim = iter
iter = 0
do 10 i = 1,n
   wrk(i,1) = xpls(i)
   wrk(i,2) = 1.0
10 continue
fscale = 1.0
!
!     OPTIMIZE FCN
!
20 call optdrv(mo,n,n,wrk(1,1),fcn,wrk(1,2),fscale,rerr, &
&itnlim,itncnt,gradtl,stepmx,steptl,xpls,fpls,wrk(1,3), &
&ierr,wrk(1,9),wrk(1,4),wrk(1,5),wrk(1,6),wrk(1,7), &
&wrk(1,8))
iter = iter + itncnt
if (ierr .ne. -10) return
itnlim = itnlim - itncnt
go to 20
end subroutine optf

subroutine optdrv (mo,nr,n,x,fcn,typsiz,fscale,rerr, &
&itnlim,itncnt,gradtl,stepmx,steptl,xpls,fpls,gpls, &
&ierr,a,g,p,wrk0,wrk1,wrk2)
implicit none
integer, intent(inout) :: ierr, itncnt
integer, intent(in) :: itnlim
integer, intent(inout) :: mo
integer :: n
integer, intent(in) :: nr
real, intent(inout) :: a(nr,n), fpls, fscale, g(n), gpls(n)
real, intent(in) :: gradtl
real, intent(inout) :: p(n)
real, intent(in) :: rerr
real, intent(inout) :: stepmx
real, intent(in) :: steptl
real, intent(inout) :: typsiz(n), wrk0(n), wrk1(n), wrk2(n), x(n), &
&xpls(n)
integer :: i, iagflg, icscmx, iretcd, j, jp1, nm1, ns
real :: cbrnf, f, fstack(30), rnf, sqrnf, stmx
real :: spmpar
!-----------------------------------------------------------------------
!             Driver for non-linear optimization problem
!-----------------------------------------------------------------------
!
!     Input ...
!
!       nr         ROW DIMENSION OF MATRIX
!       n          DIMENSION OF PROBLEM
!       FCN        SUBROUTINE.  FCN EVALUATES THE FUNCTION TO BE
!                  optimized. FCN must be declared external in the
!                  calling program. The routine HAS the format
!                         call fcn (n, x, fval)
!                  where x is a point and FVAL is the value of the
!                  function at the point.
!       rerr       RELATIVE ACCURACY OF SUBROUTINE fcn. IT IS
!                  ASSUMED THAT rerr IS NONNEGATIVE. IF rerr = 0
!                  then FCN is accurate to machine precision.
!       itnlim     MAXIMUM NUMBER OF ALLOWABLE ITERATIONS
!       gradtl     TOLERANCE AT WHICH THE GRADIENT IS CONSIDERED
!                  close enough to zero to terminate algorithm.
!                  (Used only in the subroutine opstp.)
!       steptl     RELATIVE STEP SIZE AT WHICH SUCCESSIVE ITERATES
!                  considered close enough to terminate algorithm
!
!     Input/output ...
!
!       mo         NUMBER OF RESCALINGS OF THE VARIABLES.
!       x(n)       ESTIMATE OF A LOCAL MINIMUM OF FCN
!       typsiz(n)  typical size for each component of x
!       fscale     ESTIMATE OF SCALE OF MINIMUM VALUE OF FCN.
!                  (Used only in the subroutine opstp.)
!       stepmx     MAXIMUM ALLOWABLE STEP SIZE
!
!     Output ...
!
!       itncnt     NUMBER OF ITERATIONS COMPLETED
!       XPLS(n)    ESTIMATE OF A LOCAL MINIMUM OF FCN
!       fpls       FUNCTION VALUE AT XPLS
!       gpls(n)    GRADIENT AT XPLS
!       ierr       TERMINATION CODE
!
!     Work spaces ...
!
!       a(n,n)     CHOLESKY DECOMPOSITION OF HESSIAN
!       g(n)       GRADIENT AT THE CURRENT ITERATE
!       p(n)       STEP
!       wrk0(n)    WORKSPACE
!       wrk1(n)    WORKSPACE
!       wrk2(n)    WORKSPACE
!
!-----------------------------------------------------------------------
!     Internal parameters ...
!
!       rnf        NOISE IN THE SUBROUTINE fcn
!       f          FUNCTION VALUE  FCN(x)
!       fstack(ns) stack of previous function values
!       ns         LENGTH OF THE ARRAY fstack
!       sptr       POINTER TO AN ELEMENT IN fstack
!-----------------------------------------------------------------------
integer :: sptr
logical :: mxtake, noupdt
external fcn
!
!     Initialization
!     --------------
ns = 30
stmx = stepmx
stepmx = 0.0
call opchk1 (n,x,typsiz,fscale,gradtl,itnlim,rerr,stepmx,ierr)
if (ierr .lt. 0) return
if (mo .ne. 0) stepmx = amax1(stmx,stepmx)
!
rnf = 2.0*amax1(rerr,spmpar(1))
sqrnf = sqrt(rnf)
!
itncnt = 0
iagflg = 0
iretcd = -1
icscmx = 0
!
!     Evaluate FCN(x)
!
call fcn(n,x,f)
!
!     Evaluate finite difference gradient
!
call fstofd (n, x, fcn, f, g, typsiz, sqrnf)
!
call opstp (n,x,f,g,wrk1,itncnt,icscmx,ierr,gradtl,steptl, &
&typsiz,fscale,itnlim,iretcd,mxtake,fstack,ns,sptr)
if (ierr .eq. 0) go to 10
if (mo .ne. 0) go to 210
!
!        Apply the fixed step coordinate descent procedure
!        for one step and check if the gradient is nonzero
!
   call fxdec (fcn, n, x, f, 10.0)
!
   stepmx = 0.0
   call opchk1 (n,x,typsiz,fscale,gradtl,itnlim,rerr,stepmx,ierr)
   call fstofd (n, x, fcn, f, g, typsiz, sqrnf)
   call opstp (n,x,f,g,wrk1,itncnt,icscmx,ierr,gradtl,steptl, &
&typsiz,fscale,itnlim,iretcd,mxtake,fstack,ns,sptr)
   if (ierr .ne. 0) go to 210
!
!     The hessian will be obtained by secant updates.
!     Set A to the initial hessian.
!
10 nm1 = n - 1
do j = 1,nm1
   a(j,j) = 1.0/typsiz(j)
   jp1 = j + 1
   do i = jp1,n
      a(i,j) = 0.0
   end do
end do
a(n,n) = 1.0/typsiz(n)
go to 101
!
!
!     Iteration
!     ---------
100 if (mo .gt. 1) go to 101
if (mod(itncnt,10) .ne. 0) go to 101
if (itncnt + 10 .ge. itnlim) go to 101
   call scalex (mo, x, typsiz, n, ierr)
   if (ierr .eq. 0) go to 101
   mo = mo + 1
   return
101 itncnt = itncnt + 1
!
!     SOLVE  a*p = -g  FOR NEWTON STEP
!
105 do i = 1,n
  wrk1(i) = -g(i)
end do
call lltslv(nr,n,a,p,wrk1)
!
!     Take a step, arriving at the point XPLS
!
call lnsrch(n,x,f,g,p,xpls,fpls,fcn,mxtake,iretcd, &
&stepmx,steptl,typsiz)
!
!     If a satisfactory step could not be found and forward difference
!     gradient was used, retry using a central difference gradient.
!
if (iretcd .ne. 1 .or. iagflg .ne. 0) go to 120
!
!        Set iagflg for central differences
!
   iagflg = -1
   cbrnf = rnf**(1.0/3.0)
   call fstocd (n, x, fcn, typsiz, cbrnf, g)
   go to 105
!
!     Calculate gradient at XPLS
!
120 if (iagflg .eq. 0) go to 130
   call fstocd (n, xpls, fcn, typsiz, cbrnf, gpls)
   go to 140
130 call fstofd (n, xpls, fcn, fpls, gpls, typsiz, sqrnf)
!
!     Check whether the stopping criteria satisfied
!
140 call opstp (n,xpls,fpls,gpls,x,itncnt,icscmx,ierr,gradtl,steptl, &
&typsiz,fscale,itnlim,iretcd,mxtake,fstack,ns,sptr)
if (ierr .ne. 0) go to 200
!
!     Evaluate hessian at XPLS
!
call secfac(nr,n,x,g,a,xpls,gpls,itncnt,sqrnf, &
&noupdt,wrk0,wrk1,wrk2)
!
!     Update f, x, and g
!
f = fpls
do i = 1,n
  x(i) = xpls(i)
  g(i) = gpls(i)
end do
go to 100
!
!     Termination
!     -----------
!     Reset XPLS,fpls,gpls  if previous iterate solution
!
200 if (ierr .ne. 3) return
!
210 fpls = f
do i = 1,n
   xpls(i) = x(i)
   gpls(i) = g(i)
end do
return
end subroutine optdrv

subroutine opchk1 (n,x,typsiz,fscale,gradtl,itnlim,rerr, &
&stepmx,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: itnlim, n
real, intent(inout) :: fscale
real, intent(in) :: gradtl, rerr
real, intent(inout) :: stepmx
integer :: i
real :: stpsiz
!-----------------------------------------------------------------------
!                  Check input for reasonableness
!-----------------------------------------------------------------------
!
!     Input ...
!
!       n          DIMENSION OF PROBLEM
!       x(n)       ESTIMATE OF MINIMUM OF FCN
!       gradtl     TOLERANCE AT WHICH GRADIENT CONSIDERED CLOSE
!                  enough to zero to terminate algorithm
!       itnlim     MAXIMUM NUMBER OF ALLOWABLE ITERATIONS
!       rerr       RELATIVE ACCURACY OF SUBROUTINE fcn
!
!     Input/output ...
!
!       typsiz(n)  scaling vector for x
!       fscale     ESTIMATE OF SCALE OF OBJECTIVE FUNCTION fcn
!       stepmx     MAXIMUM STEP SIZE
!
!     Output ...
!
!       ierr       ERROR INDICATOR
!
!-----------------------------------------------------------------------
real, intent(in) :: x(n)
real, intent(inout) :: typsiz(n)
!
!     Check that parameters only take on acceptable values.
!     If not, set them to default values.
!
ierr = 0
!
!     Check dimension of problem
!
if (n .le. 0) go to 805
if (n .eq. 1) go to 810
!
!     Compute scale matrix
!
do i = 1,n
  typsiz(i) = abs(typsiz(i))
  if (typsiz(i) .eq. 0.0) typsiz(i) = 1.0
end do
!
!     Check maximum step size
!
if (stepmx .gt. 0.0) go to 20
stpsiz = 0.0
do i = 1, n
   stpsiz = stpsiz + (x(i)/typsiz(i))**2
end do
stpsiz = sqrt(stpsiz)
stepmx = amax1(1.0e3*stpsiz, 1.0e3)
20 continue
!
!     Check function SCALE
!
fscale = abs(fscale)
if (fscale .eq. 0.0) fscale = 1.0
!
!     Check gradient tolerance
!
if (gradtl .lt. 0.0) go to 815
!
!     Check iteration limit
!
if (itnlim .le. 0) go to 820
!
!     Check the accuracy of FCN
!
if (rerr .lt. 0.0 .or. rerr .gt. 1.e-4) go to 825
return
!
!     Error exits
!
805 ierr = -1
go to 895
810 ierr = -2
go to 895
815 ierr = -3
go to 895
820 ierr = -4
go to 895
825 ierr = -5
895 return
end subroutine opchk1

subroutine opstp(n,xpls,fpls,gpls,x,itncnt,icscmx,ierr, &
&gradtl,steptl,typsiz,fscale,itnlim,iretcd,mxtake, &
&fstack,ns,sptr)
implicit none
integer, intent(inout) :: icscmx
integer, intent(out) :: ierr
integer, intent(in) :: iretcd, itncnt, itnlim, n, ns
real, intent(in) :: fpls
real, intent(inout) :: fscale
real, intent(in) :: gradtl, steptl
integer :: i, jerr
real :: d, grd, relstp, rgx, rsx
!-----------------------------------------------------------------------
!            Unconstrained minimization stopping criteria
!-----------------------------------------------------------------------
!
!     Input ...
!
!       n          DIMENSION OF PROBLEM
!       xpls(n)    NEW ITERATE x(K)
!       fpls       FUNCTION VALUE AT NEW ITERATE, F(xpls)
!       gpls(n)    GRADIENT AT NEW ITERATE, G(xpls), OR APPROXIMATE
!       x(n)       OLD ITERATE x(K-1)
!       itncnt     CURRENT ITERATION K
!       icscmx     NUMBER CONSECUTIVE STEPS .GE. STEPMX
!       gradtl     TOLERANCE AT WHICH RELATIVE GRADIENT CONSIDERED CLOSE
!                  enough to zero to terminate algorithm
!       steptl     RELATIVE STEP SIZE AT WHICH SUCCESSIVE ITERATES
!                  considered close enough to terminate algorithm
!       typsiz(n)  scaling vector for x
!       itnlim     MAXIMUM NUMBER OF ALLOWABLE ITERATIONS
!       iretcd     CODE WHICH WAS SET WHEN THE POINT xpls WAS OBTAINED
!       mxtake     BOOLEAN FLAG INDICATING STEP OF MAXIMUM LENGTH USED
!       ns         LENGTH OF THE ARRAY fstack
!
!     Input/output ...
!
!       fscale     ESTIMATE OF SCALE OF OBJECTIVE FUNCTION
!       fstack(ns) stack of previous function values
!       sptr       POINTER TO AN ELEMENT IN fstack
!
!     Output ...
!
!       icscmx     NUMBER CONSECUTIVE STEPS .GE. STEPMX
!                  (retain value between successive calls)
!       ierr       TERMINATION CODE
!
!-----------------------------------------------------------------------
real, intent(in) :: xpls(n), gpls(n), x(n), typsiz(n)
real, intent(inout) :: fstack(ns)
integer, intent(inout) :: sptr
logical, intent(in) :: mxtake
!
ierr = 0
!
!     Last global step failed to locate a point lower than x
!
if (iretcd .ne. 1) go to 10
   ierr = 3
   return
10 continue
!
!     Find direction in which relative gradient maximum.
!     Check whether within tolerance.
!
d = amax1(abs(fpls),fscale)
rgx = 0.0
do 20 i = 1,n
   grd = abs(gpls(i))*amax1(abs(xpls(i)),typsiz(i))
   rgx = amax1(rgx, grd)
20 continue
jerr = 1
if (rgx .gt. gradtl*d) go to 30
   if (abs(fpls) .le. 1.e-9) go to 100
   if (abs(fpls) .gt. 0.5*fscale) go to 100
   fscale = abs(fpls)
30 if (itncnt .eq. 0) return
!
!     Find direction in which relative stepsize maximum
!     check whether within tolerance.
!
rsx = 0.0
do i = 1,n
   relstp = abs(xpls(i) - x(i))/amax1(abs(xpls(i)),typsiz(i))
   rsx = amax1(rsx,relstp)
end do
jerr = 2
if (rsx .le. steptl) go to 100
!
!     Check if fpls is sufficiently less than the ns-TH
!     previous value of FCN.
!
if (itncnt .gt. ns) go to 50
   sptr = itncnt
   fstack(sptr) = fpls
   go to 60
50 sptr = sptr + 1
if (sptr .gt. ns) sptr = 1
jerr = 3
if (fpls .ge. (fstack(sptr) - 1.e-3*abs(fstack(sptr)))) &
&go to 100
fstack(sptr) = fpls
!
!     Check iteration limit
!
60 jerr = 4
if (itncnt .ge. itnlim) go to 100
!
!     Check number of consecutive steps of size STEPMX
!
if (mxtake) go to 70
   icscmx = 0
   return
70 icscmx = icscmx + 1
if (icscmx .ge. 20) ierr = 5
return
!
!     Terminate
!
100 ierr = jerr
return
end subroutine opstp

subroutine fxdec (fcn, n, x, fx, r)
implicit none
integer :: n
real, intent(inout) :: fx
real, intent(in) :: r
integer :: i
real :: fminus, fplus, h, xi, xminus, xplus
!-----------------------------------------------------------------------
!     Fixed step coordinate descent procedure / one iteration
!-----------------------------------------------------------------------
real, intent(inout) :: x(n)
external fcn
!
do 20 i = 1,n
   h = r * amax1(abs(x(i)), 1.0)
   xi = x(i)
   xplus = xi + h
   x(i) = xplus
   call fcn (n, x, fplus)
   xminus = xi - 1.1*h
   x(i) = xminus
   call fcn (n, x, fminus)
   x(i) = xi
!
   if (fx .le. fplus) go to 10
      fx = fplus
      x(i) = xplus
10 if (fx .le. fminus) go to 20
      fx = fminus
      x(i) = xminus
20 continue
return
end subroutine fxdec

subroutine scalex (mo, x, typsiz, n, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: mo, n
integer :: i
real :: big, c, t, xmin
real :: spmpar
real, intent(in) :: x(n)
real, intent(inout) :: typsiz(n)
!-----------------------------------------------------------------------
!     Rescale the variables
!-----------------------------------------------------------------------
xmin = 1.e-5*spmpar(3)
do 10 i = 1,n
   t = amax1(abs(x(i)), 1.e-20)
   xmin = amin1(t, xmin)
10 continue
!
c = 1.e3
if (mo .ne. 0) c = 1.e2
big = c*xmin
do 20 i = 1,n
   if (abs(x(i)) .ge. big) go to 30
20 continue
ierr = 0
return
!
30 do i = 1,n
   t = abs(x(i))/c
   typsiz(i) = amax1(t, xmin)
end do
ierr = -10
return
end subroutine scalex

subroutine lltslv (nr,n,a,x,b)
implicit none
integer, intent(in) :: n, nr
integer :: i, ii, im1, ip1, j
real :: sum
!-----------------------------------------------------------------------
!        SOLUTION OF AX = b WHERE A HAS THE FORM L(L-TRANSPOSE)
!           but only the lower triangular part L is stored.
!-----------------------------------------------------------------------
!
!     Input ...
!
!       nr       ROW DIMENSION OF MATRIX
!       n        ORDER OF THE MATRIX
!       a(n,n)   MATRIX OF FORM L(L-TRANSPOSE). A IS NOT
!                modified by the routine.
!       b(n)     RIGHT-HAND SIDE VECTOR
!
!     Output ...
!
!       x(n)     SOLUTION VECTOR
!
!-----------------------------------------------------------------------
!     Note.  b and x may share the same storage area.
!-----------------------------------------------------------------------
real, intent(in) :: a(nr,n)
real, intent(inout) :: x(n)
real, intent(in) :: b(n)
!
!                  Forward solve, result in x
!
x(1) = b(1)/a(1,1)
if (n .eq. 1) go to 30
do i = 2,n
   sum = 0.0
   im1 = i - 1
   do j = 1,im1
      sum = sum + a(i,j)*x(j)
   end do
   x(i) = (b(i) - sum)/a(i,i)
end do
!
!                   Back solve, result in x
!
30 x(n) = x(n)/a(n,n)
if (n .eq. 1) return
i = n
do ii = 2,n
   ip1 = i
   i = i - 1
   sum = 0.0
   do j = ip1,n
      sum = sum + a(j,i)*x(j)
   end do
   x(i) = (x(i) - sum)/a(i,i)
end do
return
end subroutine lltslv

subroutine fstofd (n, x, fcn, fx, g, typsiz, r)
implicit none
integer :: n
real, intent(in) :: fx
real, intent(inout) :: g(n)
real, intent(in) :: r
real :: typsiz(n)
real, intent(inout) :: x(n)
integer :: j
real :: fplus, stepsz, xtmpj
!-----------------------------------------------------------------------
!     Find forward difference approximation g to the first derivative
!     (gradient) of the function defined by FCN at the point x.
!-----------------------------------------------------------------------
!
!     Input ...
!
!       n          DIMENSION OF PROBLEM
!       x(n)       POINT AT WHICH THE GRADIENT IS TO BE APPROXIMATED
!       FCN        NAME OF SUBROUTINE TO EVALUATE FUNCTION
!       FX         VALUE OF FCN AT THE POINT x
!       typsiz(n)  scaling vector for x
!       r          STEPSIZE FACTOR
!
!     Output ...
!
!       g(n)       FINITE DIFFERENCE APPROXIMATION TO THE GRADIENT
!
!-----------------------------------------------------------------------
external fcn
!
do j = 1,n
  stepsz = r * amax1(abs(x(j)),typsiz(j))
  xtmpj = x(j)
  x(j) = xtmpj + stepsz
  call fcn (n, x, fplus)
  x(j) = xtmpj
  g(j) = (fplus - fx)/stepsz
end do
return
end subroutine fstofd

subroutine fstocd (n, x, fcn, typsiz, r, g)
implicit none
integer :: n
real, intent(in) :: r
integer :: i
real :: fminus, fplus, stepi, xtempi
!-----------------------------------------------------------------------
!     Find central difference approximation g to the first derivative
!     (gradient) of the function defined by FCN at the point x.
!-----------------------------------------------------------------------
!
!     Input ...
!
!       n          DIMENSION OF PROBLEM
!       x(n)       POINT AT WHICH GRADIENT IS TO BE APPROXIMATED
!       FCN        NAME OF SUBROUTINE TO EVALUATE FUNCTION
!       typsiz(n)  scaling vector for x
!       r          STEPSIZE FACTOR
!
!     Output ...
!
!       g(n)       CENTRAL DIFFERENCE APPROXIMATION TO GRADIENT
!
!-----------------------------------------------------------------------
real, intent(inout) :: x(n)
real, intent(in) :: typsiz(n)
real, intent(inout) :: g(n)
external fcn
!
!     Find i-TH  stepsize, evaluate two neighbors in direction of
!     i-TH unit vector, and evaluate i-TH  component of gradient.
!
do i = 1, n
   stepi = r * amax1(abs(x(i)),typsiz(i))
   xtempi = x(i)
   x(i) = xtempi + stepi
   call fcn (n, x, fplus)
   x(i) = xtempi - stepi
   call fcn (n, x, fminus)
   x(i) = xtempi
   g(i) = (fplus - fminus)/(2.0*stepi)
end do
return
end subroutine fstocd

subroutine lnsrch(n,x,f,g,p,xpls,fpls,fcn,mxtake,iretcd, &
&stepmx,steptl,typsiz)
implicit none
integer, intent(out) :: iretcd
integer :: n
real, intent(in) :: f
real :: fpls
real, intent(in) :: stepmx, steptl
integer :: i
real :: a, b, disc, pfpls, plmbda, rln, rmnlmb, scl, sln, slp, t1, &
&t2, t3, tlmbda, tmp, w
real :: sdot
!-----------------------------------------------------------------------
!             Find a next Newton iterate by line search
!-----------------------------------------------------------------------
!
!     Input ...
!
!       n         DIMENSION OF PROBLEM
!       x(n)      OLD ITERATE x(K-1)
!       f         FUNCTION VALUE AT OLD ITERATE, f(x)
!       g(n)      GRADIENT AT OLD ITERATE, g(x)
!       p(n)      NON-ZERO NEWTON STEP
!       FCN       NAME OF SUBROUTINE TO EVALUATE FUNCTION
!       stepmx    MAXIMUM ALLOWABLE STEP SIZE
!       steptl    RELATIVE STEP SIZE AT WHICH SUCCESSIVE ITERATES
!                 considered close enough to terminate algorithm
!       typsiz(n) scaling vector for x
!
!     Output ...
!
!       xpls(n)   NEW ITERATE x(K)
!       fpls      FUNCTION VALUE AT NEW ITERATE, f(xpls)
!       iretcd    RETURN CODE
!       mxtake    BOOLEAN FLAG INDICATING STEP OF MAXIMUM LENGTH USED
!
!-----------------------------------------------------------------------
!     Internal variables ...
!
!       sln      NEWTON LENGTH
!       rln      RELATIVE LENGTH OF NEWTON STEP
!-----------------------------------------------------------------------
real, intent(in) :: x(n), g(n)
real, intent(inout) :: p(n), xpls(n)
real, intent(in) :: typsiz(n)
real :: lambda
logical, intent(out) :: mxtake
external fcn
!
mxtake = .false.
iretcd = 2
tmp = 0.0
do 10 i = 1,n
   tmp = tmp + (p(i)/typsiz(i))**2
10 continue
sln = sqrt(tmp)
!
if (sln .le. stepmx) go to 30
!
!     Newton step longer than maximum allowed
!
   scl = stepmx/sln
   do i = 1,n
      p(i) = scl*p(i)
   end do
   sln = stepmx
!
30 slp = sdot(n,g,1,p,1)
rln = 0.0
do i = 1,n
   rln = amax1(rln,abs(p(i))/amax1(abs(x(i)),typsiz(i)))
end do
rmnlmb = steptl/rln
lambda = 1.0
!
!     Loop.  Check if the new iterate is satisfactory.
!
100 do i = 1,n
  xpls(i) = x(i) + lambda*p(i)
end do
call fcn(n,xpls,fpls)
if (fpls .le. f + slp*1.e-4*lambda) go to 200
!
!     Solution not (yet) found
!
  if (lambda .lt. rmnlmb) go to 210
!
!     Calculate new lambda
!
  if (lambda .ne. 1.0) go to 120
!
!     First backtrack. Quadratic fit
!
      tlmbda = amin1(-slp/(2.0*(fpls - f - slp)), 0.9)
      go to 170
!
!     All subsequent backtracks. Cubic fit
!
120 t1 = (fpls - f - lambda*slp)/(lambda*lambda)
      t2 = (pfpls - f - plmbda*slp)/(plmbda*plmbda)
      t3 = 1.0/(lambda - plmbda)
      a = t3*(t1 - t2)
      b = t3*(t2*lambda - t1*plmbda)
      w = 10.0*abs(t1*t3)
      if ((abs(a) + w) .ne. w) go to 130
!
!     The cubic fit degenerates to a quadratic fit
!
         tlmbda = -slp/(2.0*b)
         go to 160
!
!     The cubic is nondegenerate
!
130 disc = b*b - 3.0*a*slp
      if (disc .le. b*b) go to 140
!
!     Only one positive critical point, must be minimum
!
         tlmbda = (-b + sign(1.0,a)*sqrt(disc))/(3.0*a)
         go to 160
!
!     Both critical points positive, first is minimum
!
140 if (disc .gt. 0.0) go to 150
            tlmbda = -b/(3.0*a)
            go to 160
150 tlmbda = (-b - sign(1.0,a)*sqrt(disc))/(3.0*a)
!
160 if (tlmbda .gt. 0.5*lambda) tlmbda = 0.5*lambda
!
!
170 plmbda = lambda
    pfpls = fpls
    if (tlmbda .ge. lambda*0.1) go to 180
      lambda = lambda*0.1
      go to 100
180 lambda = tlmbda
    go to 100
!
!     A suitable value for xpls has been obtained
!
200 iretcd = 0
if (lambda .eq. 1.0 .and. sln .gt. 0.99*stepmx) mxtake =.true.
return
!
!     No satisfactory xpls found sufficiently distinct from x
!
210 iretcd = 1
return
end subroutine lnsrch

subroutine secfac (nr,n,x,g,a,xpls,gpls,itncnt,tol, &
&noupdt,s,y,w)
implicit none
integer, intent(in) :: itncnt, n, nr
real, intent(in) :: tol
integer :: i, im1, j
real :: alp, den1, den2, snorm2, sum, ynrm2
real :: snrm2
real :: sdot
!-----------------------------------------------------------------------
!           Update hessian by the BFGS factored method
!-----------------------------------------------------------------------
!
!     Input ...
!
!       nr        ROW DIMENSION OF MATRIX
!       n         ORDER OF THE MATRIX
!       x(n)      OLD ITERATE x(K-1)
!       g(n)      GRADIENT AT THE OLD ITERATE
!       xpls(n)   NEW ITERATE x(K)
!       gpls(n)   GRADIENT AT THE NEW ITERATE
!       itncnt    ITERATION COUNT
!       tol       RELATIVE TOLERANCE TO BE USED FOR NOISE
!
!     Input/output ...
!
!       a(n,n)    ON ENTRY, CHOLESKY DECOMPOSITION OF HESSIAN IN
!                    the lower part and diagonal.
!                 On exit,  updated Cholesky decomposition of hessian
!                    in the lower triangular part and diagonal.
!       noupdt    BOOLEAN. NO UPDATE YET.
!
!     Work spaces ...  s(n), y(n), w(n)
!
!-----------------------------------------------------------------------
real, intent(in) :: x(n), xpls(n), g(n), gpls(n)
real, intent(inout) :: a(nr,n)
real, intent(inout) :: s(n), y(n), w(n)
logical, intent(inout) :: noupdt
!
if (itncnt .eq. 1) noupdt = .true.
do i = 1,n
   s(i) = xpls(i) - x(i)
   y(i) = gpls(i) - g(i)
end do
den1 = sdot(n,s,1,y,1)
snorm2 = snrm2(n,s,1)
ynrm2 = snrm2(n,y,1)
if (den1 .lt. tol*snorm2*ynrm2) return
!
!     SET s = TRANSPOSE(L)*s
!
do i = 1,n
   sum = 0.0
   do j = i,n
      sum = sum + a(j,i)*s(j)
   end do
   s(i) = sum
end do
den2 = sdot(n,s,1,s,1)
!
!     SET alp = sqrt(den1/den2)
!
alp = sqrt(den1/den2)
if (.not.noupdt) go to 40
!
!        ON THE INITIAL UPDATE SET L = alp*L. THEN s MUST BE
!        RESET TO alp*s. AFTER THIS IS DONE THEN den2 = den1
!        and alp has the value 1.
!
   do j = 1,n
      s(j) = alp*s(j)
      do i = j,n
         a(i,j) = alp*a(i,j)
      end do
   end do
   noupdt = .false.
   alp = 1.0
!
!     SET w = L*s
!
40 do i = 1,n
   sum = 0.0
   do j = 1,i
      sum = sum + a(i,j)*s(j)
   end do
   w(i) = sum
end do
!
!     If abs(y(i) - w(i)) is less than the estimated noise in y(i)
!     for each i, then the update is skipped.
!
do i = 1,n
if (abs(y(i) - w(i)) .ge. tol*amax1(abs(g(i)),abs(gpls(i)))) &
&go to 70
end do
return
!
!     w = y - alp*l*s
!
70 do i = 1,n
   w(i) = y(i) - alp*w(i)
end do
!
!     s = s/sqrt(den1*den2)
!
alp = alp/den1
do i = 1,n
   s(i) = alp*s(i)
end do
!
!     Copy L into upper triangular part.  Zero L.
!
do i = 2,n
   im1 = i - 1
   do j = 1,im1
      a(j,i) = a(i,j)
      a(i,j) = 0.0
   end do
end do
!
!     FIND Q AND R SUCH THAT  Q*R = (L+) + s*(w+)
!
call qrupdt (nr, n, a, s, w)
!
!     Upper triangular part and diagonal of a now contain updated
!     Cholesky decomposition of hessian.  Copy back to lower
!     triangular part.
!
do i = 2,n
   im1 = i - 1
   do j = 1,im1
      a(i,j) = a(j,i)
   end do
end do
return
end subroutine secfac

subroutine qrupdt (nr,n,a,u,v)
implicit none
integer, intent(in) :: n, nr
integer :: i, ii, j, k, km1
real :: r
!-----------------------------------------------------------------------
!     Find an orthogonal matrix (Q*) and an upper triangular
!          MATRIX (r*) SUCH THAT (Q*)(r*) = r + u(v+)
!-----------------------------------------------------------------------
!
!     Parameters ...
!
!       nr      ROW DIMENSION OF THE MATRIX
!       n       ORDER OF THE MATRIX
!       a(n,n)  on input,  contains r
!               on output, contains (r*)
!       u(n)    VECTOR
!       v(n)    VECTOR
!
!-----------------------------------------------------------------------
real, intent(inout) :: a(nr,n), u(n)
real, intent(in) :: v(n)
!
!                Determine last non-zero in u
!
k = n
10 if (u(k) .ne. 0.0 .or. k .eq. 1) go to 20
   k = k - 1
   go to 10
!
!               k-1 Jacobi rotations transform
!             r + u(v+)  TO  (r*) + (u(1)*E1)(v+)
!                 which is upper Hessenberg
!
20 km1 = k - 1
if (k .le. 1) go to 40
do ii = 1,km1
   i = k - ii
   call jrot (nr,n,a,i,u(i),-u(i+1),r)
   u(i) = r
end do
!
! SET r = r + (u(1)*E1)(v+)
!
40 do j = 1,n
   a(1,j) = a(1,j) + u(1)*v(j)
end do
if (k .le. 1) return
!
!       k-1 Jacobi rotations transform upper Hessenberg r
!                   to upper triangular r*
!
do i = 1,km1
   call jrot (nr,n,a,i,a(i,i),-a(i+1,i),r)
end do
return
end subroutine qrupdt

subroutine jrot (nr,n,h,i,a,b,r)
implicit none
integer, intent(in) :: i, n, nr
real, intent(in) :: a, b
real, intent(inout) :: r
integer :: j
real :: c, s, t, z
!-----------------------------------------------------------------------
!         Pre-multiplication of an upper Hessenberg matrix h
!               by the Jacobian rotation j(i,i+1,a,b)
!-----------------------------------------------------------------------
!
!     Input ...
!
!       nr      ROW DIMENSION OF THE MATRIX
!       n       ORDER OF THE MATRIX
!       h(n,n)  upper hessenber matrix
!       i       INDEX OF ROW
!       A,b     SCALARS
!
!     Output ...
!
!       h(n,n)  the modified Hessenberg matrix
!       r       r = sqrt(a*a + b*b)
!
!-----------------------------------------------------------------------
real, intent(inout) :: h(nr,n)
!
!                COMPUTE c = a/r  AND s = b/r
!
if (abs(a) .le. abs(b)) go to 10
   t = b/a
   z = sqrt(1.0 + t*t)
   c = sign(1.0/z, a)
   s = t*c
   r = z*abs(a)
   go to 20
10 if (a .eq. 0.0) go to 40
t = a/b
z = sqrt(1.0 + t*t)
s = sign(1.0/z, b)
c = t*s
r = z*abs(b)
!
!            Apply the rotation when A is nonzero
!
20 do j = i,n
   t = h(i,j)
   z = h(i+1,j)
   h(i,j) = c*t - s*z
   h(i+1,j) = s*t + c*z
end do
return
!
!                     CASE WHEN a = 0
!
40 s = sign(1.0, b)
r = abs(b)
do j = i,n
   t = h(i,j)
   h(i,j) = - s*h(i+1,j)
   h(i+1,j) = s*t
end do
return
end subroutine jrot

subroutine lmdiff (fcn,m,n,x,fvec,epsfcn,tol,info,iwa,wa,lwa)
implicit none
integer :: m, n
integer, intent(out) :: info
integer, intent(in) :: lwa
integer, intent(inout) :: iwa(n)
real, intent(in) :: epsfcn, tol
real, intent(inout) :: x(n), fvec(m), wa(lwa)
external fcn
!     **********
!
!     SUBROUTINE lmdiff
!
!     The purpose of lmdiff is to minimize the sum of the squares of
!     m nonlinear functions in n variables by a modification of the
!     Levenberg-Marquardt algorithm. This is done by using the more
!     general least-squares solver lmdif. The user must provide A
!     subroutine which calculates the functions. The Jacobian is
!     then calculated by a forward-difference approximation.
!
!     The subroutine statement is
!
!       subroutine lmdiff(fcn,m,n,x,fvec,epsfcn,tol,info,iwa,wa,lwa)
!
!     Where
!
!       FCN is the name of the user-supplied subroutine which
!         calculates the functions. FCN must be declared
!         in an external statement in the user calling
!         program, and should be written as follows.
!
!         subroutine fcn(m,n,x,fvec,iflag)
!         integer m,n,iflag
!         real x(n),fvec(m)
!         ----------
!         Calculate the functions at x and
!         RETURN THIS VECTOR IN fvec.
!         ----------
!         return
!         end
!
!         The value of IFLAG should not be changed by FCN unless
!         the user wants to terminate execution of lmdiff.
!         In this case set IFLAG to a negative integer.
!
!       m is a positive integer input variable SET to the number
!         of functions.
!
!       n is a positive integer input variable SET to the number
!         of variables. n must not exceed m.
!
!       x is an array of length n. on input x must contain
!         an initial estimate of the solution vector. On output x
!         contains the final estimate of the solution vector.
!
!       fvec is an output array of length m which contains
!         the functions evaluated at the output x.
!
!       epsfcn is an input variable used in determining a suitable
!         step length for the forward-difference approximation. This
!         approximation assumes that the relative errors in the
!         functions are of the order of epsfcn. If epsfcn is less
!         than the machine precision, it is assumed that the relative
!         errors in the functions are of the order of the machine
!         precision.
!
!       tol is a nonnegative input variable. Termination occurs
!         when the algorithm estimates either that the relative
!         error in the sum of squares is at most tol or that
!         the relative error between x and the solution is at
!         MOST tol.
!
!       Info is an integer output variable. If the user has
!         terminated execution, info is set to the (negative)
!         value of IFLAG. See description of FCN. Otherwise,
!         info is set as follows.
!
!         info = 0  IMPROPER INPUT PARAMETERS.
!
!         info = 1  ALGORITHM ESTIMATES THAT THE RELATIVE ERROR
!                   in the sum of squares is at most tol.
!
!         info = 2  ALGORITHM ESTIMATES THAT THE RELATIVE ERROR
!                   between x and the solution is at most tol.
!
!         info = 3  CONDITIONS FOR info = 1 AND info = 2 BOTH HOLD.
!
!         info = 4  fvec IS ORTHOGONAL TO THE COLUMNS OF THE
!                   Jacobian to machine precision.
!
!         info = 5  NUMBER OF CALLS TO FCN HAS REACHED OR
!                   EXCEEDED 200*(n+1).
!
!         info = 6  tol IS TOO SMALL. NO FURTHER REDUCTION IN
!                   the sum of squares is possible.
!
!         info = 7  tol IS TOO SMALL. NO FURTHER IMPROVEMENT IN
!                   the approximate solution x is possible.
!
!       iwa is an integer work array of length n.
!
!       wa is a work array of length lwa.
!
!       lwa is a positive integer input variable NOT less than
!         m*n+5*n+m.
!
!     Subprograms called
!
!       User-supplied ...... FCN
!
!       MINPACK-supplied ... lmdif
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge J. more
!
!     **********
integer :: maxfev, mode, mp5n, nfev, nprint
real :: factor, ftol, gtol, xtol
data factor /1.0e2/
info = 0
!
!     Check the input parameters for errors.
!
if (n .le. 0 .or. m .lt. n .or. epsfcn .lt. 0.0 &
&.or. tol .lt. 0.0 .or. lwa .lt. m*n + 5*n + m) go to 10
!
!     CALL lmdif.
!
maxfev = 200*(n + 1)
ftol = tol
xtol = tol
gtol = 0.0
mode = 1
nprint = 0
mp5n = m + 5*n
call lmdif(fcn,m,n,x,fvec,ftol,xtol,gtol,maxfev,epsfcn,wa(1), &
&mode,factor,nprint,info,nfev,wa(mp5n+1),m,iwa, &
&wa(n+1),wa(2*n+1),wa(3*n+1),wa(4*n+1),wa(5*n+1))
if (info .eq. 8) info = 4
10 continue
return
end subroutine lmdiff

subroutine lmdif(fcn,m,n,x,fvec,ftol,xtol,gtol,maxfev,epsfcn, &
&diag,mode,factor,nprint,info,nfev,fjac,ldfjac, &
&ipvt,qtf,wa1,wa2,wa3,wa4)
implicit none
integer :: m, n
integer, intent(in) :: maxfev, mode, nprint
integer, intent(out) :: info, nfev
integer, intent(in) :: ldfjac
integer, intent(inout) :: ipvt(n)
real, intent(in) :: ftol, xtol, gtol, epsfcn, factor
real, intent(inout) :: x(n), fvec(m), diag(n), fjac(ldfjac,n), &
&qtf(n), wa1(n), wa2(n), wa3(n), wa4(m)
external fcn
!     **********
!
!     SUBROUTINE lmdif
!
!     The purpose of lmdif is to minimize the sum of the squares of
!     m nonlinear functions in n variables by a modification of
!     the Levenberg-Marquardt algorithm. The user must provide A
!     subroutine which calculates the functions. The Jacobian is
!     then calculated by a forward-difference approximation.
!
!     The subroutine statement is
!
!       subroutine lmdif(fcn,m,n,x,fvec,ftol,xtol,gtol,maxfev,epsfcn,
!                        diag,mode,factor,nprint,info,nfev,fjac,
!                        ldfjac,ipvt,QTF,WA1,WA2,WA3,WA4)
!
!     Where
!
!       FCN is the name of the user-supplied subroutine which
!         calculates the functions. FCN must be declared
!         in an external statement in the user calling
!         program, and should be written as follows.
!
!         subroutine fcn(m,n,x,fvec,iflag)
!         integer m,n,iflag
!         real x(n),fvec(m)
!         ----------
!         Calculate the functions at x and
!         RETURN THIS VECTOR IN fvec.
!         ----------
!         return
!         end
!
!         The value of iflag should not be changed by FCN unless
!         the user wants to terminate execution of lmdif.
!         In this case set iflag to a negative integer.
!
!       m is a positive integer input variable SET to the number
!         of functions.
!
!       n is a positive integer input variable SET to the number
!         of variables. n must not exceed m.
!
!       x is an array of length n. on input x must contain
!         an initial estimate of the solution vector. On output x
!         contains the final estimate of the solution vector.
!
!       fvec is an output array of length m which contains
!         the functions evaluated at the output x.
!
!       ftol is a nonnegative input variable. Termination
!         occurs when both the actual and predicted relative
!         reductions in the sum of squares are at most ftol.
!         Therefore, ftol measures the relative error desired
!         in the sum of squares.
!
!       xtol is a nonnegative input variable. Termination
!         occurs when the relative error between two consecutive
!         iterates is at most xtol. Therefore, xtol measures the
!         relative error desired in the approximate solution.
!
!       gtol is a nonnegative input variable. Termination
!         occurs when the cosine of the angle between fvec and
!         any column of the Jacobian is at most gtol in absolute
!         value. Therefore, gtol measures the orthogonality
!         desired between the function vector and the columns
!         of the Jacobian.
!
!       maxfev is a positive integer input variable. Termination
!         occurs when the number of calls to FCN is at least
!         maxfev by the end of an iteration.
!
!       epsfcn is an input variable used in determining a suitable
!         step length for the forward-difference approximation. This
!         approximation assumes that the relative errors in the
!         functions are of the order of epsfcn. If epsfcn is less
!         than the machine precision, it is assumed that the relative
!         errors in the functions are of the order of the machine
!         precision.
!
!       DIAG IS AN ARRAY OF LENGTH n. IF mode = 1 (SEE
!         BELOW), DIAG IS INTERNALLY SET. IF mode = 2, DIAG
!         must contain positive entries that serve as
!         multiplicative scale factors for the variables.
!
!       MODE IS AN INTEGER INPUT VARIABLE. IF mode = 1, THE
!         VARIABLES WILL BE SCALED INTERNALLY. IF mode = 2,
!         the scaling is specified by the input diag. Other
!         VALUES OF MODE ARE EQUIVALENT TO mode = 1.
!
!       Factor is a positive input variable used in determining the
!         initial step bound. This bound is set to the product of
!         factor and the Euclidean norm of diag*x if nonzero, or else
!         to factor itself. In most cases factor should lie in the
!         interval (.1,100.). 100. Is a generally recommended value.
!
!       nprint is an integer input variable that enables controlled
!         printing of iterates if it is positive. In this case,
!         FCN IS CALLED WITH iflag = 0 AT THE BEGINNING OF THE FIRST
!         iteration and every nprint iterations thereafter and
!         immediately prior to return, with x and fvec available
!         for printing. If nprint is not positive, no special calls
!         OF FCN WITH iflag = 0 ARE MADE.
!
!       Info is an integer output variable. If the user has
!         terminated execution, info is set to the (negative)
!         value of iflag. See description of FCN. Otherwise,
!         info is set as follows.
!
!         info = 0  IMPROPER INPUT PARAMETERS.
!
!         info = 1  BOTH ACTUAL AND PREDICTED RELATIVE REDUCTIONS
!                   in the sum of squares are at most ftol.
!
!         info = 2  RELATIVE ERROR BETWEEN TWO CONSECUTIVE ITERATES
!                   is at most xtol.
!
!         info = 3  CONDITIONS FOR info = 1 AND info = 2 BOTH HOLD.
!
!         info = 4  THE COSINE OF THE ANGLE BETWEEN fvec AND ANY
!                   column of the Jacobian is at most gtol in
!                   absolute value.
!
!         info = 5  NUMBER OF CALLS TO FCN HAS REACHED OR
!                   EXCEEDED maxfev.
!
!         info = 6  ftol IS TOO SMALL. NO FURTHER REDUCTION IN
!                   the sum of squares is possible.
!
!         info = 7  xtol IS TOO SMALL. NO FURTHER IMPROVEMENT IN
!                   the approximate solution x is possible.
!
!         info = 8  gtol IS TOO SMALL. fvec IS ORTHOGONAL TO THE
!                   columns of the Jacobian to machine precision.
!
!       nfev is an integer output variable SET to the number of
!         calls to FCN.
!
!       fjac is an output m by n array. The upper n by n submatrix
!         of fjac contains an upper triangular matrix R with
!         diagonal elements of nonincreasing magnitude such that
!
!                T     T           T
!               P *(JAC *JAC)*P = R *R,
!
!         Where P is a permutation matrix and JAC is the final
!         calculated Jacobian. Column j of P is column ipvt(j)
!         (see below) of the identity matrix. The lower trapezoidal
!         part of fjac contains information generated during
!         the computation of R.
!
!       ldfjac is a positive integer input variable NOT less than m
!         which specifies the leading dimension of the array fjac.
!
!       ipvt is an integer output array of length n. ipvt
!         DEFINES A PERMUTATION MATRIX P SUCH THAT JAC*P = Q*R,
!         where JAC is the final calculated Jacobian, Q is
!         orthogonal (not stored), and R is upper triangular
!         with diagonal elements of nonincreasing magnitude.
!         Column j of P is column ipvt(j) of the identity matrix.
!
!       QTF is an output array of length n which contains
!         the first n elements of the vector (Q transpose)*fvec.
!
!       WA1, WA2, and WA3 are work arrays of length n.
!
!       WA4 is a work array of length m.
!
!     Subprograms called
!
!       User-supplied ...... FCN
!
!       MINPACK-supplied ... spmpar,enorm,fdjac2,lmpar,qrfac
!
!       Fortran-supplied ... abs,AMAX1,AMIN1,sqrt,mod
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge j. more
!
!     **********
integer :: i, iflag, iter, j, l
real :: actred, delta, dirder, eps, fnorm, fnorm1, gnorm, par, &
&pnorm, prered, p1, p5, p25, p75, p0001, ratio, sum, temp, temp1, &
&temp2, xnorm
real :: spmpar, enorm
data p1,p5,p25,p75,p0001 &
&/1.0e-1,5.0e-1,2.5e-1,7.5e-1,1.0e-4/
!
!     Eps is the machine precision.
!
eps = spmpar(1)
!
info = 0
iflag = 0
nfev = 0
!
!     Check the input parameters for errors.
!
if (n .le. 0 .or. m .lt. n .or. ldfjac .lt. m &
&.or. ftol .lt. 0.0 .or. xtol .lt. 0.0 .or. gtol .lt. 0.0 &
&.or. maxfev .le. 0 .or. factor .le. 0.0) go to 300
if (mode .ne. 2) go to 20
do j = 1, n
   if (diag(j) .le. 0.0) go to 300
   end do
20 continue
!
!     Evaluate the function at the starting point
!     and calculate its norm.
!
iflag = 1
call fcn(m,n,x,fvec,iflag)
nfev = 1
if (iflag .lt. 0) go to 300
fnorm = enorm(m,fvec)
!
!     Initialize Levenberg-Marquardt parameter and iteration counter.
!
par = 0.0
iter = 1
!
!     Beginning of the outer loop.
!
30 continue
!
!        Calculate the Jacobian matrix.
!
   iflag = 2
   call fdjac2(fcn,m,n,x,fvec,fjac,ldfjac,iflag,epsfcn,wa4)
   nfev = nfev + n
   if (iflag .lt. 0) go to 300
!
!        If requested, call FCN to enable printing of iterates.
!
   if (nprint .le. 0) go to 40
   iflag = 0
   if (mod(iter-1,nprint) .eq. 0) call fcn(m,n,x,fvec,iflag)
   if (iflag .lt. 0) go to 300
40 continue
!
!        Compute the QR factorization of the Jacobian.
!
   call qrfac(m,n,fjac,ldfjac,.true.,ipvt,n,wa1,wa2,wa3)
!
!        On the first iteration and if mode is 1, scale according
!        to the norms of the columns of the initial Jacobian.
!
   if (iter .ne. 1) go to 80
   if (mode .eq. 2) go to 60
   do j = 1, n
      diag(j) = wa2(j)
      if (wa2(j) .eq. 0.0) diag(j) = 1.0
      end do
60 continue
!
!        On the first iteration, calculate the norm of the scaled x
!        and initialize the step bound delta.
!
   do j = 1, n
      wa3(j) = diag(j)*x(j)
      end do
   xnorm = enorm(n,wa3)
   delta = factor*xnorm
   if (delta .eq. 0.0) delta = factor
80 continue
!
!        Form (Q transpose)*fvec and store the first n components in
!        QTF.
!
   do i = 1, m
      wa4(i) = fvec(i)
      end do
   do j = 1, n
      if (fjac(j,j) .eq. 0.0) go to 120
      sum = 0.0
      do i = j, m
         sum = sum + fjac(i,j)*wa4(i)
         end do
      temp = -sum/fjac(j,j)
      do i = j, m
         wa4(i) = wa4(i) + fjac(i,j)*temp
         end do
120 continue
      fjac(j,j) = wa1(j)
      qtf(j) = wa4(j)
      end do
!
!        Compute the norm of the scaled gradient.
!
   gnorm = 0.0
   if (fnorm .eq. 0.0) go to 170
   do j = 1, n
      l = ipvt(j)
      if (wa2(l) .eq. 0.0) go to 150
      sum = 0.0
      do i = 1, j
         sum = sum + fjac(i,j)*(qtf(i)/fnorm)
         end do
      gnorm = amax1(gnorm,abs(sum/wa2(l)))
150 continue
      end do
170 continue
!
!        Test for convergence of the gradient norm.
!
   if (gnorm .le. gtol) info = 4
   if (info .ne. 0) go to 300
!
!        Rescale if necessary.
!
   if (mode .eq. 2) go to 190
   do j = 1, n
      diag(j) = amax1(diag(j),wa2(j))
      end do
190 continue
!
!        Beginning of the inner loop.
!
200 continue
!
!           Determine the Levenberg-Marquardt parameter.
!
      call lmpar(n,fjac,ldfjac,ipvt,diag,qtf,delta,par,wa1,wa2, &
&wa3,wa4)
!
!           Store the direction P and x + P. calculate the norm of P.
!
      do j = 1, n
         wa1(j) = -wa1(j)
         wa2(j) = x(j) + wa1(j)
         wa3(j) = diag(j)*wa1(j)
         end do
      pnorm = enorm(n,wa3)
!
!           On the first iteration, adjust the initial step bound.
!
      if (iter .eq. 1) delta = amin1(delta,pnorm)
!
!           Evaluate the function at x + P and calculate its norm.
!
      iflag = 1
      call fcn(m,n,wa2,wa4,iflag)
      nfev = nfev + 1
      if (iflag .lt. 0) go to 300
      fnorm1 = enorm(m,wa4)
!
!           Compute the scaled actual reduction.
!
      actred = -1.0
      if (p1*fnorm1 .lt. fnorm) actred = 1.0 - (fnorm1/fnorm)**2
!
!           Compute the scaled predicted reduction and
!           the scaled directional derivative.
!
      do j = 1, n
         wa3(j) = 0.0
         l = ipvt(j)
         temp = wa1(l)
         do i = 1, j
            wa3(i) = wa3(i) + fjac(i,j)*temp
            end do
         end do
      temp1 = enorm(n,wa3)/fnorm
      temp2 = (sqrt(par)*pnorm)/fnorm
      prered = temp1**2 + temp2**2/p5
      dirder = -(temp1**2 + temp2**2)
!
!           Compute the ratio of the actual to the predicted
!           reduction.
!
      ratio = 0.0
      if (prered .ne. 0.0) ratio = actred/prered
!
!           Update the step bound.
!
      if (ratio .gt. p25) go to 240
         if (actred .ge. 0.0) temp = p5
         if (actred .lt. 0.0) &
&temp = p5*dirder/(dirder + p5*actred)
         if (p1*fnorm1 .ge. fnorm .or. temp .lt. p1) temp = p1
         delta = temp*amin1(delta,pnorm/p1)
         par = par/temp
         go to 260
240 continue
         if (par .ne. 0.0 .and. ratio .lt. p75) go to 250
         delta = pnorm/p5
         par = p5*par
250 continue
260 continue
!
!           Test for successful iteration.
!
      if (ratio .lt. p0001) go to 290
!
!           Successful iteration. Update x, fvec, and their norms.
!
      do j = 1, n
         x(j) = wa2(j)
         wa2(j) = diag(j)*x(j)
         end do
      do i = 1, m
         fvec(i) = wa4(i)
         end do
      xnorm = enorm(n,wa2)
      fnorm = fnorm1
      iter = iter + 1
290 continue
!
!           Tests for convergence.
!
      if (abs(actred) .le. ftol .and. prered .le. ftol &
&.and. p5*ratio .le. 1.0) info = 1
      if (delta .le. xtol*xnorm) info = 2
      if (abs(actred) .le. ftol .and. prered .le. ftol &
&.and. p5*ratio .le. 1.0 .and. info .eq. 2) info = 3
      if (info .ne. 0) go to 300
!
!           Tests for termination and stringent tolerances.
!
      if (nfev .ge. maxfev) info = 5
      if (abs(actred) .le. eps .and. prered .le. eps &
&.and. p5*ratio .le. 1.0) info = 6
      if (delta .le. eps*xnorm) info = 7
      if (gnorm .le. eps) info = 8
      if (info .ne. 0) go to 300
!
!           END OF THE INNER LOOP. REPEAT IF ITERATION UNSUCCESSFUL.
!
      if (ratio .lt. p0001) go to 200
!
!        END OF THE OUTER LOOP.
!
   go to 30
300 continue
!
!     Termination, either normal or user imposed.
!
if (iflag .lt. 0) info = iflag
iflag = 0
if (nprint .gt. 0) call fcn(m,n,x,fvec,iflag)
return
end subroutine lmdif

real function enorm(n,x)
implicit none
integer, intent(in) :: n
real, intent(in) :: x(n)
!     **********
!
!     FUNCTION enorm
!
!     Given an n-vector x, this function calculates the
!     Euclidean norm of x.
!
!     The Euclidean norm is computed by accumulating the sum of
!     squares in three different sums. The sums of squares for the
!     small and large components are scaled so that no overflows
!     occur. Non-destructive underflows are permitted. Underflows
!     and overflows do not occur in the computation of the unscaled
!     sum of squares for the intermediate components.
!     The definitions of small, intermediate and large components
!     depend on two constants, rdwarf and rgiant. The main
!     RESTRICTIONS ON THESE CONSTANTS ARE THAT rdwarf**2 NOT
!     UNDERFLOW AND rgiant**2 NOT OVERFLOW. THE CONSTANTS
!     given here are suitable for every known computer.
!
!     The function statement is
!
!       REAL FUNCTION enorm(n,x)
!
!     Where
!
!       n is a positive integer input variable.
!
!       x is an input array of length n.
!
!     Subprograms called
!
!       Fortran-supplied ... abs,sqrt
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge J. more
!
!     **********
integer :: i
real :: agiant, floatn, rdwarf, rgiant, s1, s2, s3, xabs, x1max, &
&x3max
data rdwarf,rgiant /3.834e-20,1.304e19/
!
s1 = 0.0
s2 = 0.0
s3 = 0.0
x1max = 0.0
x3max = 0.0
floatn = n
agiant = rgiant/floatn
do 90 i = 1, n
   xabs = abs(x(i))
   if (xabs .gt. rdwarf .and. xabs .lt. agiant) go to 70
      if (xabs .le. rdwarf) go to 30
!
!              Sum for large components.
!
         if (xabs .le. x1max) go to 10
            s1 = 1.0 + s1*(x1max/xabs)**2
            x1max = xabs
            go to 20
10 continue
            s1 = s1 + (xabs/x1max)**2
20 continue
         go to 60
30 continue
!
!              Sum for small components.
!
         if (xabs .le. x3max) go to 40
            s3 = 1.0 + s3*(x3max/xabs)**2
            x3max = xabs
            go to 50
40 continue
            if (xabs .ne. 0.0) s3 = s3 + (xabs/x3max)**2
50 continue
60 continue
      go to 80
70 continue
!
!           Sum for intermediate components.
!
      s2 = s2 + xabs**2
80 continue
90 continue
!
!     Calculation of norm.
!
if (s1 .eq. 0.0) go to 100
   enorm = x1max*sqrt(s1 + (s2/x1max)/x1max)
   go to 130
100 continue
   if (s2 .eq. 0.0) go to 110
      if (s2 .ge. x3max) &
&enorm = sqrt(s2*(1.0 + (x3max/s2)*(x3max*s3)))
      if (s2 .lt. x3max) &
&enorm = sqrt(x3max*((s2/x3max) + (x3max*s3)))
      go to 120
110 continue
      enorm = x3max*sqrt(s3)
120 continue
130 continue
return
end function enorm

subroutine dogleg(n,r,lr,diag,qtb,delta,x,wa1,wa2)
implicit none
integer, intent(in) :: n, lr
real, intent(in) :: delta
real, intent(in) :: r(lr), diag(n), qtb(n)
real, intent(inout) :: x(n), wa1(n), wa2(n)
!     **********
!
!     Subroutine dogleg
!
!     Given an M by n matrix A, an n by n nonsingular diagonal
!     matrix D, an M-vector B, and a positive number delta, the
!     problem is to determine the convex combination x of the
!     Gauss-Newton and scaled gradient directions that minimizes
!     (A*x - B) in the least squares sense, subject to the
!     restriction that the Euclidean norm of D*x be at most delta.
!
!     This subroutine completes the solution of the problem
!     if it is provided with the necessary information from the
!     QR FACTORIZATION OF A. THAT IS, IF A = Q*r, WHERE Q HAS
!     orthogonal columns and r is an upper triangular matrix,
!     then dogleg expects the full upper triangle of r and
!     the first n components of (Q transpose)*B.
!
!     The subroutine statement is
!
!       subroutine dogleg(n,r,lr,diag,qtb,delta,x,wa1,wa2)
!
!     Where
!
!       n is a positive integer input variable SET to the order of r.
!
!       r is an input array of length lr which must contain the upper
!         triangular matrix r stored by rows.
!
!       lr is a positive integer input variable NOT less than
!         (n*(n+1))/2.
!
!       Diag is an input array of length n which must contain the
!         diagonal elements of the matrix D.
!
!       qtb is an input array of length n which must contain the first
!         n elements of the vector (Q transpose)*B.
!
!       delta is a positive input variable which specifies an upper
!         bound on the Euclidean norm of D*x.
!
!       x is an output array of length n which contains the desired
!         convex combination of the Gauss-Newton direction and the
!         scaled gradient direction.
!
!       wa1 and wa2 are work arrays of length n.
!
!     Subprograms called
!
!       MINPACK-supplied ... spmpar,enorm
!
!       Fortran-supplied ... abs,AMAX1,AMIN1,sqrt
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge j. more
!
!     **********
integer :: i, j, jj, jp1, k, l
real :: alpha, bnorm, epsmch, gnorm, qnorm, sgnorm, sum, temp
real :: spmpar, enorm
!
!     epsmch is the machine precision.
!
epsmch = spmpar(1)
!
!     First, calculate the Gauss-Newton direction.
!
jj = (n*(n + 1))/2 + 1
do k = 1, n
   j = n - k + 1
   jp1 = j + 1
   jj = jj - k
   l = jj + 1
   sum = 0.0
   if (n .lt. jp1) go to 20
   do i = jp1, n
      sum = sum + r(l)*x(i)
      l = l + 1
      end do
20 continue
   temp = r(jj)
   if (temp .ne. 0.0) go to 40
   l = j
   do i = 1, j
      temp = amax1(temp,abs(r(l)))
      l = l + n - i
      end do
   temp = epsmch*temp
   if (temp .eq. 0.0) temp = epsmch
40 continue
   x(j) = (qtb(j) - sum)/temp
   end do
!
!     Test whether the Gauss-Newton direction is acceptable.
!
do j = 1, n
   wa1(j) = 0.0
   wa2(j) = diag(j)*x(j)
   end do
qnorm = enorm(n,wa2)
if (qnorm .le. delta) go to 140
!
!     The Gauss-Newton direction is not acceptable.
!     Next, calculate the scaled gradient direction.
!
l = 1
do j = 1, n
   temp = qtb(j)
   do i = j, n
      wa1(i) = wa1(i) + r(l)*temp
      l = l + 1
      end do
   wa1(j) = wa1(j)/diag(j)
   end do
!
!     Calculate the norm of the scaled gradient and test for
!     the special case in which the scaled gradient is zero.
!
gnorm = enorm(n,wa1)
sgnorm = 0.0
alpha = delta/qnorm
if (gnorm .eq. 0.0) go to 120
!
!     Calculate the point along the scaled gradient
!     at which the quadratic is minimized.
!
do j = 1, n
   wa1(j) = (wa1(j)/gnorm)/diag(j)
   end do
l = 1
do j = 1, n
   sum = 0.0
   do i = j, n
      sum = sum + r(l)*wa1(i)
      l = l + 1
      end do
   wa2(j) = sum
   end do
temp = enorm(n,wa2)
sgnorm = (gnorm/temp)/temp
!
!     Test whether the scaled gradient direction is acceptable.
!
alpha = 0.0
if (sgnorm .ge. delta) go to 120
!
!     The scaled gradient direction is not acceptable.
!     Finally, calculate the point along the dogleg
!     at which the quadratic is minimized.
!
bnorm = enorm(n,qtb)
temp = (bnorm/gnorm)*(bnorm/qnorm)*(sgnorm/delta)
temp = temp - (delta/qnorm)*(sgnorm/delta)**2 &
&+ sqrt((temp-(delta/qnorm))**2 &
&+(1.0-(delta/qnorm)**2)*(1.0-(sgnorm/delta)**2))
alpha = ((delta/qnorm)*(1.0 - (sgnorm/delta)**2))/temp
120 continue
!
!     Form appropriate convex combination of the Gauss-Newton
!     direction and the scaled gradient direction.
!
temp = (1.0 - alpha)*amin1(sgnorm,delta)
do j = 1, n
   x(j) = temp*wa1(j) + alpha*x(j)
   end do
140 continue
return
end subroutine dogleg

subroutine fdjac1(fcn,n,x,fvec,fjac,ldfjac,iflag,ml,mu,epsfcn, &
&wa1,wa2)
implicit none
integer :: n
integer, intent(in) :: ldfjac
integer :: iflag
integer, intent(in) :: ml, mu
real, intent(in) :: epsfcn
real, intent(inout) :: x(n)
real, intent(in) :: fvec(n)
real, intent(inout) :: fjac(ldfjac,n)
real :: wa1(n)
real, intent(inout) :: wa2(n)
external fcn
!     **********
!
!     SUBROUTINE fdjac1
!
!     This subroutine computes a forward-difference approximation
!     to the n by n Jacobian matrix associated with a specified
!     problem of n functions in n variables. If the Jacobian has
!     a banded form, then function evaluations are saved by only
!     approximating the nonzero terms.
!
!     The subroutine statement is
!
!       subroutine fdjac1(fcn,n,x,fvec,fjac,ldfjac,iflag,ml,mu,epsfcn,
!                         wa1,wa2)
!
!     Where
!
!       FCN is the name of the user-supplied subroutine which
!         calculates the functions. FCN must be declared
!         in an external statement in the user calling
!         program, and should be written as follows.
!
!         subroutine fcn(n,x,fvec,iflag)
!         integer n,iflag
!         real x(n),fvec(n)
!         ----------
!         Calculate the functions at x and
!         RETURN THIS VECTOR IN fvec.
!         ----------
!         return
!         end
!
!         The value of iflag should not be changed by FCN unless
!         the user wants to terminate execution of fdjac1.
!         In this case set iflag to a negative integer.
!
!       n is a positive integer input variable SET to the number
!         of functions and variables.
!
!       x is an input array of length n.
!
!       fvec is an input array of length n which must contain the
!         functions evaluated at x.
!
!       fjac is an output n by n array which contains the
!         approximation to the Jacobian matrix evaluated at x.
!
!       ldfjac is a positive integer input variable NOT less than n
!         which specifies the leading dimension of the array fjac.
!
!       iflag is an integer variable which can be used to terminate
!         the execution of fdjac1. See description of FCN.
!
!       ml is a nonnegative integer input variable which specifies
!         the number of subdiagonals within the band of the
!         Jacobian matrix. If the Jacobian is not banded, set
!         ml to at least n - 1.
!
!       epsfcn is an input variable used in determining a suitable
!         step length for the forward-difference approximation. This
!         approximation assumes that the relative errors in the
!         functions are of the order of epsfcn. If epsfcn is less
!         than the machine precision, it is assumed that the relative
!         errors in the functions are of the order of the machine
!         precision.
!
!       mu is a nonnegative integer input variable which specifies
!         the number of superdiagonals within the band of the
!         Jacobian matrix. If the Jacobian is not banded, set
!         mu to at least n - 1.
!
!       wa1 and wa2 are work arrays of length n. if ml + mu + 1 is at
!         least n, then the Jacobian is considered dense, and wa2 is
!         not referenced.
!
!     Subprograms called
!
!       MINPACK-supplied ... spmpar
!
!       Fortran-supplied ... abs,AMAX1,sqrt
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge j. more
!
!     **********
integer :: i, j, k, msum
real :: eps, epsmch, h, temp, zero
real :: spmpar
data zero /0.0e0/
!
!     epsmch is the machine precision.
!
epsmch = spmpar(1)
!
eps = sqrt(amax1(epsfcn,epsmch))
msum = ml + mu + 1
if (msum .lt. n) go to 40
!
!        Computation of dense approximate Jacobian.
!
   do j = 1, n
      temp = x(j)
      h = eps*abs(temp)
      if (h .eq. zero) h = eps
      x(j) = temp + h
      call fcn(n,x,wa1,iflag)
      if (iflag .lt. 0) go to 30
      x(j) = temp
      do i = 1, n
         fjac(i,j) = (wa1(i) - fvec(i))/h
         end do
      end do
30 continue
   go to 110
40 continue
!
!        Computation of banded approximate Jacobian.
!
   do k = 1, msum
      do j = k, n, msum
         wa2(j) = x(j)
         h = eps*abs(wa2(j))
         if (h .eq. zero) h = eps
         x(j) = wa2(j) + h
         end do
      call fcn(n,x,wa1,iflag)
      if (iflag .lt. 0) go to 100
      do j = k, n, msum
         x(j) = wa2(j)
         h = eps*abs(wa2(j))
         if (h .eq. zero) h = eps
         do i = 1, n
            fjac(i,j) = zero
            if (i .ge. j - mu .and. i .le. j + ml) &
&fjac(i,j) = (wa1(i) - fvec(i))/h
            end do
         end do
      end do
100 continue
110 continue
return
!
!     Last card of subroutine fdjac1.
!
end subroutine fdjac1

subroutine fdjac2(fcn,m,n,x,fvec,fjac,ldfjac,iflag,epsfcn,wa)
implicit none
integer :: m, n
integer, intent(in) :: ldfjac
integer :: iflag
real, intent(in) :: epsfcn
real, intent(inout) :: x(n)
real, intent(in) :: fvec(m)
real, intent(inout) :: fjac(ldfjac,n)
real :: wa(m)
external fcn
!     **********
!
!     SUBROUTINE fdjac2
!
!     This subroutine computes a forward-difference approximation
!     to the m by n Jacobian matrix associated with a specified
!     problem of m functions in n variables.
!
!     The subroutine statement is
!
!       subroutine fdjac2(fcn,m,n,x,fvec,fjac,ldfjac,iflag,epsfcn,wa)
!
!     Where
!
!       FCN is the name of the user-supplied subroutine which
!         calculates the functions. FCN must be declared
!         in an external statement in the user calling
!         program, and should be written as follows.
!
!         subroutine fcn(m,n,x,fvec,iflag)
!         integer m,n,iflag
!         real x(n),fvec(m)
!         ----------
!         Calculate the functions at x and
!         RETURN THIS VECTOR IN fvec.
!         ----------
!         return
!         end
!
!         The value of iflag should not be changed by FCN unless
!         the user wants to terminate execution of fdjac2.
!         In this case set iflag to a negative integer.
!
!       m is a positive integer input variable SET to the number
!         of functions.
!
!       n is a positive integer input variable SET to the number
!         of variables. n must not exceed m.
!
!       x is an input array of length n.
!
!       fvec is an input array of length m which must contain the
!         functions evaluated at x.
!
!       fjac is an output m by n array which contains the
!         approximation to the Jacobian matrix evaluated at x.
!
!       ldfjac is a positive integer input variable NOT less than m
!         which specifies the leading dimension of the array fjac.
!
!       iflag is an integer variable which can be used to terminate
!         the execution of fdjac2. See description of FCN.
!
!       epsfcn is an input variable used in determining a suitable
!         step length for the forward-difference approximation. This
!         approximation assumes that the relative errors in the
!         functions are of the order of epsfcn. If epsfcn is less
!         than the machine precision, it is assumed that the relative
!         errors in the functions are of the order of the machine
!         precision.
!
!       wa is a work array of length m.
!
!     Subprograms called
!
!       User-supplied ...... FCN
!
!       MINPACK-supplied ... spmpar
!
!       Fortran-supplied ... abs,AMAX1,sqrt
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge j. more
!
!     **********
integer :: i, j
real :: eps, epsmch, h, temp, zero
real :: spmpar
data zero /0.0e0/
!
!     epsmch is the machine precision.
!
epsmch = spmpar(1)
!
eps = sqrt(amax1(epsfcn,epsmch))
do j = 1, n
   temp = x(j)
   h = eps*abs(temp)
   if (h .eq. zero) h = eps
   x(j) = temp + h
   call fcn(m,n,x,wa,iflag)
   if (iflag .lt. 0) go to 30
   x(j) = temp
   do i = 1, m
      fjac(i,j) = (wa(i) - fvec(i))/h
      end do
   end do
30 continue
return
!
!     Last card of subroutine fdjac2.
!
end subroutine fdjac2

subroutine lmpar(n,r,ldr,ipvt,diag,qtb,delta,par,x,sdiag,wa1, &
&wa2)
implicit none
integer, intent(in) :: n, ldr
integer, intent(in) :: ipvt(n)
real, intent(in) :: delta
real, intent(inout) :: par
real, intent(inout) :: r(ldr,n)
real, intent(in) :: diag(n), qtb(n)
real, intent(inout) :: x(n), sdiag(n), wa1(n), wa2(n)
!     **********
!
!     SUBROUTINE lmpar
!
!     Given an M by n matrix A, an n by n nonsingular diagonal
!     matrix D, an M-vector B, and a positive number delta,
!     the problem is to determine a value for the parameter
!     par such that if x solves the system
!
!           A*x = B ,     sqrt(par)*D*x = 0 ,
!
!     In the least squares sense, and dxnorm is the Euclidean
!     norm of D*x, then either par is zero and
!
!           (dxnorm-delta) .LE. 0.1*delta ,
!
!     Or par is positive and
!
!           abs(dxnorm-delta) .LE. 0.1*delta .
!
!     This subroutine completes the solution of the problem
!     if it is provided with the necessary information from the
!     QR factorization, with column pivoting, of A. that is, if
!     A*P = Q*r, WHERE P IS A PERMUTATION MATRIX, Q HAS ORTHOGONAL
!     columns, and r is an upper triangular matrix with diagonal
!     elements of nonincreasing magnitude, then lmpar expects
!     the full upper triangle of r, the permutation matrix P,
!     and the first n components of (Q transpose)*B. on output
!     lmpar also provides an upper triangular matrix S such that
!
!            T   T                   T
!           P *(A *A + par*D*D)*P = S *S .
!
!     S is employed within lmpar and may be of separate interest.
!
!     Only a few iterations are generally needed for convergence
!     of the algorithm. If, however, the limit of 10 iterations
!     is reached, then the output par will contain the best
!     value obtained so far.
!
!     The subroutine statement is
!
!       subroutine lmpar(n,r,ldr,ipvt,diag,qtb,delta,par,x,sdiag,
!                        wa1,wa2)
!
!     Where
!
!       n is a positive integer input variable SET to the order of r.
!
!       r is an n by n array. On input the full upper triangle
!         must contain the full upper triangle of the matrix r.
!         On output the full upper triangle is unaltered, and the
!         strict lower triangle contains the strict upper triangle
!         (transposed) of the upper triangular matrix S.
!
!       ldr is a positive integer input variable NOT less than n
!         which specifies the leading dimension of the array r.
!
!       ipvt is an integer input array of length n which defines the
!         PERMUTATION MATRIX P SUCH THAT A*P = Q*r. COLUMN j OF P
!         is column ipvt(j) of the identity matrix.
!
!       Diag is an input array of length n which must contain the
!         diagonal elements of the matrix D.
!
!       qtb is an input array of length n which must contain the first
!         n elements of the vector (Q transpose)*B.
!
!       delta is a positive input variable which specifies an upper
!         bound on the Euclidean norm of D*x.
!
!       Par is a nonnegative variable. On input par contains an
!         initial estimate of the Levenberg-Marquardt parameter.
!         On output par contains the final estimate.
!
!       x is an output array of length n which contains the least
!         SQUARES SOLUTION OF THE SYSTEM A*x = B, sqrt(par)*D*x = 0,
!         for the output par.
!
!       sdiag is an output array of length n which contains the
!         diagonal elements of the upper triangular matrix S.
!
!       wa1 and wa2 are work arrays of length n.
!
!     Subprograms called
!
!       MINPACK-supplied ... spmpar,enorm,qrsolv
!
!       Fortran-supplied ... abs,AMAX1,AMIN1,sqrt
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge j. more
!
!     **********
integer :: i, iter, j, jm1, jp1, k, l, nsing
real :: dxnorm, dwarf, fp, gnorm, parc, parl, paru, p1, p001, sum, &
&temp, zero
real :: spmpar, enorm
data p1,p001,zero /1.0e-1,1.0e-3,0.0e0/
!
!     Dwarf is the smallest positive magnitude.
!
dwarf = spmpar(2)
!
!     Compute and store in x the Gauss-Newton direction. If the
!     Jacobian is rank-deficient, obtain a least squares solution.
!
nsing = n
do 10 j = 1, n
   wa1(j) = qtb(j)
   if (r(j,j) .eq. zero .and. nsing .eq. n) nsing = j - 1
   if (nsing .lt. n) wa1(j) = zero
10 continue
if (nsing .lt. 1) go to 50
do k = 1, nsing
   j = nsing - k + 1
   wa1(j) = wa1(j)/r(j,j)
   temp = wa1(j)
   jm1 = j - 1
   if (jm1 .lt. 1) go to 30
   do i = 1, jm1
      wa1(i) = wa1(i) - r(i,j)*temp
      end do
30 continue
   end do
50 continue
do j = 1, n
   l = ipvt(j)
   x(l) = wa1(j)
   end do
!
!     Initialize the iteration counter.
!     Evaluate the function at the origin, and test
!     for acceptance of the Gauss-Newton direction.
!
iter = 0
do j = 1, n
   wa2(j) = diag(j)*x(j)
   end do
dxnorm = enorm(n,wa2)
fp = dxnorm - delta
if (fp .le. p1*delta) go to 220
!
!     If the Jacobian is not rank deficient, the Newton
!     step provides a lower bound, parl, for the zero of
!     the function. Otherwise set this bound to zero.
!
parl = zero
if (nsing .lt. n) go to 120
do j = 1, n
   l = ipvt(j)
   wa1(j) = diag(l)*(wa2(l)/dxnorm)
   end do
do j = 1, n
   sum = zero
   jm1 = j - 1
   if (jm1 .lt. 1) go to 100
   do i = 1, jm1
      sum = sum + r(i,j)*wa1(i)
      end do
100 continue
   wa1(j) = (wa1(j) - sum)/r(j,j)
   end do
temp = enorm(n,wa1)
parl = ((fp/delta)/temp)/temp
120 continue
!
!     Calculate an upper bound, paru, for the zero of the function.
!
do j = 1, n
   sum = zero
   do i = 1, j
      sum = sum + r(i,j)*qtb(i)
      end do
   l = ipvt(j)
   wa1(j) = sum/diag(l)
   end do
gnorm = enorm(n,wa1)
paru = gnorm/delta
if (paru .eq. zero) paru = dwarf/amin1(delta,p1)
!
!     If the input par lies outside of the interval (parl,paru),
!     set par to the closer endpoint.
!
par = amax1(par,parl)
par = amin1(par,paru)
if (par .eq. zero) par = gnorm/dxnorm
!
!     Beginning of an iteration.
!
150 continue
   iter = iter + 1
!
!        Evaluate the function at the current value of par.
!
   if (par .eq. zero) par = amax1(dwarf,p001*paru)
   temp = sqrt(par)
   do j = 1, n
      wa1(j) = temp*diag(j)
      end do
   call qrsolv(n,r,ldr,ipvt,wa1,qtb,x,sdiag,wa2)
   do j = 1, n
      wa2(j) = diag(j)*x(j)
      end do
   dxnorm = enorm(n,wa2)
   temp = fp
   fp = dxnorm - delta
!
!        If the function is small enough, accept the current value
!        of par. Also test for the exceptional cases where parl
!        is zero or the number of iterations has reached 10.
!
   if (abs(fp) .le. p1*delta &
&.or. parl .eq. zero .and. fp .le. temp &
&.and. temp .lt. zero .or. iter .eq. 10) go to 220
!
!        Compute the Newton correction.
!
   do j = 1, n
      l = ipvt(j)
      wa1(j) = diag(l)*(wa2(l)/dxnorm)
      end do
   do j = 1, n
      wa1(j) = wa1(j)/sdiag(j)
      temp = wa1(j)
      jp1 = j + 1
      if (n .lt. jp1) go to 200
      do i = jp1, n
         wa1(i) = wa1(i) - r(i,j)*temp
         end do
200 continue
      end do
   temp = enorm(n,wa1)
   parc = ((fp/delta)/temp)/temp
!
!        Depending on the sign of the function, update parl or paru.
!
   if (fp .gt. zero) parl = amax1(parl,par)
   if (fp .lt. zero) paru = amin1(paru,par)
!
!        Compute an improved estimate for par.
!
   par = amax1(parl,par+parc)
!
!        END OF AN ITERATION.
!
   go to 150
220 continue
!
!     Termination.
!
if (iter .eq. 0) par = zero
return
!
!     Last card of subroutine lmpar.
!
end subroutine lmpar

subroutine qform(m,n,q,ldq,wa)
implicit none
integer, intent(in) :: m, n, ldq
real, intent(inout) :: q(ldq,m), wa(m)
!     **********
!
!     SUBROUTINE qform
!
!     This subroutine proceeds from the computed QR factorization of
!     an m by n matrix A to accumulate the m by m orthogonal matrix
!     q from its factored form.
!
!     The subroutine statement is
!
!       subroutine qform(m,n,q,ldq,wa)
!
!     Where
!
!       m is a positive integer input variable SET to the number
!         of rows of A and the order of q.
!
!       n is a positive integer input variable SET to the number
!         of columns of A.
!
!       q is an m by m array. On input the full lower trapezoid in
!         the first min(m,n) columns of q contains the factored form.
!         On output q has been accumulated into a square matrix.
!
!       ldq is a positive integer input variable NOT less than m
!         which specifies the leading dimension of the array q.
!
!       wa is a work array of length m.
!
!     Subprograms called
!
!       Fortran-supplied ... MIN0
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge j. more
!
!     **********
integer :: i, j, jm1, k, l, minmn, np1
real :: one, sum, temp, zero
data one,zero /1.0e0,0.0e0/
!
!     Zero out upper triangle of q in the first min(m,n) columns.
!
minmn = min0(m,n)
if (minmn .lt. 2) go to 30
do j = 2, minmn
   jm1 = j - 1
   do i = 1, jm1
      q(i,j) = zero
      end do
   end do
30 continue
!
!     Initialize remaining columns to those of the identity matrix.
!
np1 = n + 1
if (m .lt. np1) go to 60
do j = np1, m
   do i = 1, m
      q(i,j) = zero
      end do
   q(j,j) = one
   end do
60 continue
!
!     Accumulate q from its factored form.
!
do l = 1, minmn
   k = minmn - l + 1
   do i = k, m
      wa(i) = q(i,k)
      q(i,k) = zero
      end do
   q(k,k) = one
   if (wa(k) .eq. zero) go to 110
   do j = k, m
      sum = zero
      do i = k, m
         sum = sum + q(i,j)*wa(i)
         end do
      temp = sum/wa(k)
      do i = k, m
         q(i,j) = q(i,j) - temp*wa(i)
         end do
      end do
110 continue
   end do
return
!
!     Last card of subroutine qform.
!
end subroutine qform

subroutine qrfac(m,n,a,lda,pivot,ipvt,lipvt,rdiag,acnorm,wa)
implicit none
integer, intent(in) :: m, n, lda, lipvt
integer, intent(inout) :: ipvt(lipvt)
logical, intent(in) :: pivot
real, intent(inout) :: a(lda,n), rdiag(n), acnorm(n), wa(n)
!     **********
!
!     SUBROUTINE qrfac
!
!     This subroutine uses Householder transformations with column
!     pivoting (optional) to compute A QR factorization of the
!     m by n matrix a. that is, qrfac determines an orthogonal
!     matrix Q, a permutation matrix P, and an upper trapezoidal
!     matrix R with diagonal elements of nonincreasing magnitude,
!     SUCH THAT a*P = Q*R. THE HOUSEHOLDER TRANSFORMATION FOR
!     COLUMN k, k = 1,2,...,min(m,n), IS OF THE FORM
!
!                           T
!           i - (1/U(k))*U*U
!
!     Where U has zeros in the first k-1 positions. The form of
!     this transformation and the method of pivoting first
!     appeared in the corresponding LINPACK subroutine.
!
!     The subroutine statement is
!
!       subroutine qrfac(m,n,a,lda,pivot,ipvt,lipvt,rdiag,acnorm,wa)
!
!     Where
!
!       m is a positive integer input variable SET to the number
!         of rows of A.
!
!       n is a positive integer input variable SET to the number
!         of columns of A.
!
!       A is an m by n array. On input a contains the matrix for
!         which the QR factorization is to be computed. On output
!         the strict upper trapezoidal part of a contains the strict
!         upper trapezoidal part of R, and the lower trapezoidal
!         part of a contains a factored form of Q (the non-trivial
!         elements of the U vectors described above).
!
!       lda is a positive integer input variable NOT less than m
!         which specifies the leading dimension of the array a.
!
!       Pivot is a logical input variable. If pivot is set true,
!         then column pivoting is enforced. If pivot is set false,
!         then no column pivoting is done.
!
!       ipvt is an integer output array of length lipvt. ipvt
!         DEFINES THE PERMUTATION MATRIX P SUCH THAT a*P = Q*R.
!         Column j of P is column ipvt(j) of the identity matrix.
!         If pivot is false, ipvt is not referenced.
!
!       lipvt is a positive integer input variable. If pivot is false,
!         then lipvt may be as small as 1. If pivot is true, then
!         lipvt must be at least n.
!
!       rdiag is an output array of length n which contains the
!         diagonal elements of R.
!
!       acnorm is an output array of length n which contains the
!         norms of the corresponding columns of the input matrix a.
!         If this information is not needed, then acnorm can coincide
!         WITH rdiag.
!
!       wa is a work array of length n. if pivot is false, then wa
!         can coincide with rdiag.
!
!     Subprograms called
!
!       MINPACK-supplied ... spmpar,enorm
!
!       Fortran-supplied ... AMAX1,sqrt,MIN0
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge j. more
!
!     **********
integer :: i, j, jp1, k, kmax, minmn
real :: ajnorm, epsmch, one, p05, sum, temp, zero
real :: spmpar, enorm
data one,p05,zero /1.0e0,5.0e-2,0.0e0/
!
!     epsmch is the machine precision.
!
epsmch = spmpar(1)
!
!     Compute the initial column norms and initialize several arrays.
!
do j = 1, n
   acnorm(j) = enorm(m,a(1,j))
   rdiag(j) = acnorm(j)
   wa(j) = rdiag(j)
   if (pivot) ipvt(j) = j
   end do
!
!     Reduce A to R with Householder transformations.
!
minmn = min0(m,n)
do j = 1, minmn
   if (.not.pivot) go to 40
!
!        Bring the column of largest norm into the pivot position.
!
   kmax = j
   do k = j, n
      if (rdiag(k) .gt. rdiag(kmax)) kmax = k
      end do
   if (kmax .eq. j) go to 40
   do i = 1, m
      temp = a(i,j)
      a(i,j) = a(i,kmax)
      a(i,kmax) = temp
      end do
   rdiag(kmax) = rdiag(j)
   wa(kmax) = wa(j)
   k = ipvt(j)
   ipvt(j) = ipvt(kmax)
   ipvt(kmax) = k
40 continue
!
!        Compute the Householder transformation to reduce the
!        j-TH column of A to a multiple of the j-TH unit vector.
!
   ajnorm = enorm(m-j+1,a(j,j))
   if (ajnorm .eq. zero) go to 100
   if (a(j,j) .lt. zero) ajnorm = -ajnorm
   do i = j, m
      a(i,j) = a(i,j)/ajnorm
      end do
   a(j,j) = a(j,j) + one
!
!        Apply the transformation to the remaining columns
!        and update the norms.
!
   jp1 = j + 1
   if (n .lt. jp1) go to 100
   do k = jp1, n
      sum = zero
      do i = j, m
         sum = sum + a(i,j)*a(i,k)
         end do
      temp = sum/a(j,j)
      do i = j, m
         a(i,k) = a(i,k) - temp*a(i,j)
         end do
      if (.not.pivot .or. rdiag(k) .eq. zero) go to 80
      temp = a(j,k)/rdiag(k)
      rdiag(k) = rdiag(k)*sqrt(amax1(zero,one-temp**2))
      if (p05*(rdiag(k)/wa(k))**2 .gt. epsmch) go to 80
      rdiag(k) = enorm(m-j,a(jp1,k))
      wa(k) = rdiag(k)
80 continue
      end do
100 continue
   rdiag(j) = -ajnorm
   end do
return
!
!     Last card of subroutine qrfac.
!
end subroutine qrfac

subroutine qrsolv(n,r,ldr,ipvt,diag,qtb,x,sdiag,wa)
implicit none
integer, intent(in) :: n, ldr
integer, intent(in) :: ipvt(n)
real, intent(inout) :: r(ldr,n)
real, intent(in) :: diag(n), qtb(n)
real, intent(inout) :: x(n), sdiag(n), wa(n)
!     **********
!
!     SUBROUTINE qrsolv
!
!     Given an M by n matrix A, an n by n diagonal matrix D,
!     and an M-vector B, the problem is to determine an x which
!     solves the system
!
!           A*x = B ,     D*x = 0 ,
!
!     In the least squares sense.
!
!     This subroutine completes the solution of the problem
!     if it is provided with the necessary information from the
!     QR factorization, with column pivoting, of A. that is, if
!     A*P = Q*r, WHERE P IS A PERMUTATION MATRIX, Q HAS ORTHOGONAL
!     columns, and r is an upper triangular matrix with diagonal
!     elements of nonincreasing magnitude, then qrsolv expects
!     the full upper triangle of r, the permutation matrix P,
!     and the first n components of (Q transpose)*B. the system
!     A*x = B, D*x = 0, IS THEN EQUIVALENT TO
!
!                  T       T
!           r*Z = Q *B ,  P *D*P*Z = 0 ,
!
!     WHERE x = P*Z. IF THIS SYSTEM DOES NOT HAVE FULL RANK,
!     then a least squares solution is obtained. On output qrsolv
!     also provides an upper triangular matrix S such that
!
!            T   T               T
!           P *(A *A + D*D)*P = S *S .
!
!     S is computed within qrsolv and may be of separate interest.
!
!     The subroutine statement is
!
!       subroutine qrsolv(n,r,ldr,ipvt,diag,qtb,x,sdiag,wa)
!
!     Where
!
!       n is a positive integer input variable SET to the order of r.
!
!       r is an n by n array. On input the full upper triangle
!         must contain the full upper triangle of the matrix r.
!         On output the full upper triangle is unaltered, and the
!         strict lower triangle contains the strict upper triangle
!         (transposed) of the upper triangular matrix S.
!
!       ldr is a positive integer input variable NOT less than n
!         which specifies the leading dimension of the array r.
!
!       ipvt is an integer input array of length n which defines the
!         PERMUTATION MATRIX P SUCH THAT A*P = Q*r. COLUMN j OF P
!         is column ipvt(j) of the identity matrix.
!
!       Diag is an input array of length n which must contain the
!         diagonal elements of the matrix D.
!
!       qtb is an input array of length n which must contain the first
!         n elements of the vector (Q transpose)*B.
!
!       x is an output array of length n which contains the least
!         SQUARES SOLUTION OF THE SYSTEM A*x = B, D*x = 0.
!
!       sdiag is an output array of length n which contains the
!         diagonal elements of the upper triangular matrix S.
!
!       wa is a work array of length n.
!
!     Subprograms called
!
!       Fortran-supplied ... abs,sqrt
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge j. more
!
!     **********
integer :: i, j, jp1, k, kp1, l, nsing
real :: cos, cotan, p5, p25, qtbpj, sin, sum, tan, temp, zero
data p5,p25,zero /5.0e-1,2.5e-1,0.0e0/
!
!     Copy r and (Q transpose)*B to preserve input and initialize S.
!     In particular, save the diagonal elements of r in x.
!
do j = 1, n
   do i = j, n
      r(i,j) = r(j,i)
      end do
   x(j) = r(j,j)
   wa(j) = qtb(j)
   end do
!
!     Eliminate the diagonal matrix D using a Givens rotation.
!
do j = 1, n
!
!        Prepare the row of D to be eliminated, locating the
!        diagonal element using P from the QR factorization.
!
   l = ipvt(j)
   if (diag(l) .eq. zero) go to 90
   do k = j, n
      sdiag(k) = zero
      end do
   sdiag(j) = diag(l)
!
!        The transformations to eliminate the row of D
!        modify only a single element of (Q transpose)*B
!        beyond the first n, which is initially zero.
!
   qtbpj = zero
   do k = j, n
!
!           Determine a Givens rotation which eliminates the
!           appropriate element in the current row of D.
!
      if (sdiag(k) .eq. zero) go to 70
      if (abs(r(k,k)) .ge. abs(sdiag(k))) go to 40
         cotan = r(k,k)/sdiag(k)
         sin = p5/sqrt(p25+p25*cotan**2)
         cos = sin*cotan
         go to 50
40 continue
         tan = sdiag(k)/r(k,k)
         cos = p5/sqrt(p25+p25*tan**2)
         sin = cos*tan
50 continue
!
!           Compute the modified diagonal element of r and
!           the modified element of ((Q transpose)*B,0).
!
      r(k,k) = cos*r(k,k) + sin*sdiag(k)
      temp = cos*wa(k) + sin*qtbpj
      qtbpj = -sin*wa(k) + cos*qtbpj
      wa(k) = temp
!
!           Accumulate the tranformation in the row of S.
!
      kp1 = k + 1
      if (n .lt. kp1) go to 70
      do i = kp1, n
         temp = cos*r(i,k) + sin*sdiag(i)
         sdiag(i) = -sin*r(i,k) + cos*sdiag(i)
         r(i,k) = temp
         end do
70 continue
      end do
90 continue
!
!        Store the diagonal element of S and restore
!        the corresponding diagonal element of r.
!
   sdiag(j) = r(j,j)
   r(j,j) = x(j)
   end do
!
!     Solve the triangular system for Z. if the system is
!     singular, then obtain a least squares solution.
!
nsing = n
do j = 1, n
   if (sdiag(j) .eq. zero .and. nsing .eq. n) nsing = j - 1
   if (nsing .lt. n) wa(j) = zero
   end do
if (nsing .lt. 1) go to 150
do k = 1, nsing
   j = nsing - k + 1
   sum = zero
   jp1 = j + 1
   if (nsing .lt. jp1) go to 130
   do i = jp1, nsing
      sum = sum + r(i,j)*wa(i)
      end do
130 continue
   wa(j) = (wa(j) - sum)/sdiag(j)
   end do
150 continue
!
!     Permute the components of Z back to components of x.
!
do j = 1, n
   l = ipvt(j)
   x(l) = wa(j)
   end do
return
!
!     Last card of subroutine qrsolv.
!
end subroutine qrsolv

subroutine r1mpyq(m,n,a,lda,v,w)
implicit none
integer, intent(in) :: m, n, lda
real, intent(inout) :: a(lda,n)
real, intent(in) :: v(n), w(n)
!     **********
!
!     SUBROUTINE r1mpyq
!
!     Given an m by n matrix a, this subroutine computes a*Q where
!     Q is the product of 2*(n - 1) transformations
!
!           GV(n-1)*...*GV(1)*GW(1)*...*GW(n-1)
!
!     And GV(i), GW(i) are Givens rotations in the (i,n) plane which
!     eliminate elements in the i-TH and n-TH planes, respectively.
!     Q itself is not given, rather the information to recover the
!     GV, GW ROTATIONS IS SUPPLIED.
!
!     The subroutine statement is
!
!       subroutine r1mpyq(m,n,a,lda,v,w)
!
!     Where
!
!       m is a positive integer input variable SET to the number
!         of rows of A.
!
!       n is a positive integer input variable SET to the number
!         of columns of A.
!
!       A is an m by n array. On input A must contain the matrix
!         to be postmultiplied by the orthogonal matrix Q
!         described above. On output a*Q has replaced A.
!
!       lda is a positive integer input variable NOT less than m
!         which specifies the leading dimension of the array a.
!
!       v is an input array of length n. v(i) must contain the
!         information necessary to recover the Givens rotation GV(i)
!         described above.
!
!       w is an input array of length n. w(i) must contain the
!         information necessary to recover the Givens rotation GW(i)
!         described above.
!
!     Subroutines called
!
!       Fortran-supplied ... abs,sqrt
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge j. more
!
!     **********
integer :: i, j, nmj, nm1
real :: cos, one, sin, temp
data one /1.0e0/
!
!     Apply the first set of Givens rotations to A.
!
nm1 = n - 1
if (nm1 .lt. 1) go to 50
do nmj = 1, nm1
   j = n - nmj
   if (abs(v(j)) .gt. one) cos = one/v(j)
   if (abs(v(j)) .gt. one) sin = sqrt(one-cos**2)
   if (abs(v(j)) .le. one) sin = v(j)
   if (abs(v(j)) .le. one) cos = sqrt(one-sin**2)
   do i = 1, m
      temp = cos*a(i,j) - sin*a(i,n)
      a(i,n) = sin*a(i,j) + cos*a(i,n)
      a(i,j) = temp
      end do
   end do
!
!     Apply the second set of Givens rotations to A.
!
do j = 1, nm1
   if (abs(w(j)) .gt. one) cos = one/w(j)
   if (abs(w(j)) .gt. one) sin = sqrt(one-cos**2)
   if (abs(w(j)) .le. one) sin = w(j)
   if (abs(w(j)) .le. one) cos = sqrt(one-sin**2)
   do i = 1, m
      temp = cos*a(i,j) + sin*a(i,n)
      a(i,n) = -sin*a(i,j) + cos*a(i,n)
      a(i,j) = temp
      end do
   end do
50 continue
return
!
!     Last card of subroutine r1mpyq.
!
end subroutine r1mpyq

subroutine r1updt(m,n,s,ls,u,v,w,sing)
implicit none
integer, intent(in) :: m, n, ls
logical, intent(inout) :: sing
real, intent(inout) :: s(ls)
real, intent(in) :: u(m)
real, intent(inout) :: v(n), w(m)
!     **********
!
!     SUBROUTINE r1updt
!
!     Given an m by n lower trapezoidal matrix s, an m-vector u,
!     and an n-vector v, the problem is to determine an
!     orthogonal matrix Q such that
!
!                   T
!           (s + u*v )*Q
!
!     Is again lower trapezoidal.
!
!     This subroutine determines Q as the product of 2*(n - 1)
!     transformations
!
!           GV(n-1)*...*GV(1)*GW(1)*...*GW(n-1)
!
!     Where GV(i), GW(i) are Givens rotations in the (i,n) plane
!     which eliminate elements in the i-TH and n-TH planes,
!     respectively. Q itself is not accumulated, rather the
!     information to recover the GV, GW rotations is returned.
!
!     The subroutine statement is
!
!       subroutine r1updt(m,n,s,ls,u,v,w,sing)
!
!     Where
!
!       m is a positive integer input variable SET to the number
!         of rows of s.
!
!       n is a positive integer input variable SET to the number
!         of columns of s. n must not exceed m.
!
!       s is an array of length ls. On input s must contain the lower
!         trapezoidal matrix s stored by columns. On output s contains
!         the lower trapezoidal matrix produced as described above.
!
!       ls is a positive integer input variable NOT less than
!         (n*(2*m-n+1))/2.
!
!       u is an input array of length m which must contain the
!         VECTOR u.
!
!       v is an array of length n. on input v must contain the vector
!         v. on output v(i) contains the information necessary to
!         recover the Givens rotation GV(i) described above.
!
!       w is an output array of length m. w(i) contains information
!         necessary to recover the Givens rotation GW(i) described
!         above.
!
!       Sing is a logical output variable. Sing is set true if any
!         of the diagonal elements of the output s are zero. Otherwise
!         sing is set false.
!
!     Subprograms called
!
!       MINPACK-supplied ... spmpar
!
!       Fortran-supplied ... abs,sqrt
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton s. Garbow, kenneth E. Hillstrom, jorge j. more,
!     john l. nazareth
!
!     **********
integer :: i, j, jj, l, nmj, nm1
real :: cos, cotan, giant, one, p5, p25, sin, tan, tau, temp, zero
real :: spmpar
data one,p5,p25,zero /1.0e0,5.0e-1,2.5e-1,0.0e0/
!
!     Giant is the largest magnitude.
!
giant = spmpar(3)
!
!     Initialize the diagonal element pointer.
!
jj = (n*(2*m - n + 1))/2 - (m - n)
!
!     Move the nontrivial part of the last column of s into w.
!
l = jj
do i = n, m
   w(i) = s(l)
   l = l + 1
   end do
!
!     Rotate the vector v into a multiple of the n-TH unit vector
!     in such a way that a spike is introduced into w.
!
nm1 = n - 1
if (nm1 .lt. 1) go to 70
do nmj = 1, nm1
   j = n - nmj
   jj = jj - (m - j + 1)
   w(j) = zero
   if (v(j) .eq. zero) go to 50
!
!        Determine a Givens rotation which eliminates the
!        j-TH element of v.
!
   if (abs(v(n)) .ge. abs(v(j))) go to 20
      cotan = v(n)/v(j)
      sin = p5/sqrt(p25+p25*cotan**2)
      cos = sin*cotan
      tau = one
      if (abs(cos)*giant .gt. one) tau = one/cos
      go to 30
20 continue
      tan = v(j)/v(n)
      cos = p5/sqrt(p25+p25*tan**2)
      sin = cos*tan
      tau = sin
30 continue
!
!        Apply the transformation to v and store the information
!        necessary to recover the Givens rotation.
!
   v(n) = sin*v(j) + cos*v(n)
   v(j) = tau
!
!        Apply the transformation to s and extend the spike in w.
!
   l = jj
   do i = j, m
      temp = cos*s(l) - sin*w(i)
      w(i) = sin*s(l) + cos*w(i)
      s(l) = temp
      l = l + 1
      end do
50 continue
   end do
70 continue
!
!     Add the spike from the rank 1 update to w.
!
do i = 1, m
   w(i) = w(i) + v(n)*u(i)
   end do
!
!     Eliminate the spike.
!
sing = .false.
if (nm1 .lt. 1) go to 140
do j = 1, nm1
   if (w(j) .eq. zero) go to 120
!
!        Determine a Givens rotation which eliminates the
!        j-TH element of the spike.
!
   if (abs(s(jj)) .ge. abs(w(j))) go to 90
      cotan = s(jj)/w(j)
      sin = p5/sqrt(p25+p25*cotan**2)
      cos = sin*cotan
      tau = one
      if (abs(cos)*giant .gt. one) tau = one/cos
      go to 100
90 continue
      tan = w(j)/s(jj)
      cos = p5/sqrt(p25+p25*tan**2)
      sin = cos*tan
      tau = sin
100 continue
!
!        Apply the transformation to s and reduce the spike in w.
!
   l = jj
   do i = j, m
      temp = cos*s(l) + sin*w(i)
      w(i) = -sin*s(l) + cos*w(i)
      s(l) = temp
      l = l + 1
      end do
!
!        Store the information necessary to recover the
!        Givens rotation.
!
   w(j) = tau
120 continue
!
!        Test for zero diagonal elements in the output s.
!
   if (s(jj) .eq. zero) sing = .true.
   jj = jj + (m - j + 1)
   end do
140 continue
!
!     Move w back into the last column of the output s.
!
l = jj
do i = n, m
   s(l) = w(i)
   l = l + 1
   end do
if (s(jj) .eq. zero) sing = .true.
return
!
!     Last card of subroutine r1updt.
!
end subroutine r1updt

subroutine smplx (a,b0,c,ka,m,n0,ind,ibasis,x,z,iter,mxiter, &
&numle,numge,bi,wk,iwk)
implicit none
integer, intent(inout) :: ibasis, ind, iter, iwk(*)
integer, intent(in) :: ka
integer :: m
integer, intent(in) :: mxiter, n0, numge, numle
real :: a(ka,n0), b0(m)
real, intent(inout) :: bi(m,m)
real :: c(n0)
real, intent(inout) :: wk(*), x(*), z
integer :: ip
real :: eps0, rerr, rerrmn, rerrmx
real :: spmpar
!-----------------------------------------------------------------------
!     Simplex procedure for solving linear programming problems
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris Jr.
!        naval surface weapons center
!        Dahlgren, Virginia
!------------------------
!     Initial version  DEC  1977
!     LAST UPDATE      OCT  1990
!------------------------
dimension ibasis(m)
!------------------------
!     dimension x(n0+numle+numge)
!     dimension wk(2*m),iwk(2*m+n0)
!------------------------
!
!     ********** eps0 IS A MACHINE DEPENDENT PARAMETER. ASSIGN eps0
!                the value U where U is the smallest positive floating
!                POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0.
!
                    eps0 = spmpar(1)
!
!------------------------
rerrmn = 10.0*eps0
rerrmx = 1.e-4
if (eps0 .lt. 1.e-13) rerrmx = 1.e-5
!
ip = m + n0 + 1
call smplx1(a,b0,c,ka,m,n0,ind,ibasis,x,z,iter,mxiter, &
&eps0,rerrmn,rerrmx,rerr,numle,numge,bi, &
&wk(1),wk(m+1),iwk(1),iwk(ip))
return
end subroutine smplx

subroutine smplx1 (a,b0,c,ka,m,n0,ind,ibasis,r,z,iter,mxiter, &
&eps0,rerrmn,rerrmx,rerr,numle,numge,bi,xb,y,basis,index)
implicit none
integer, intent(inout) :: ind
integer, intent(out) :: iter
integer, intent(in) :: ka, m, mxiter, n0, numge, numle
real, intent(in) :: eps0
real, intent(inout) :: rerr
real, intent(in) :: rerrmn, rerrmx
real, intent(out) :: z
integer :: i, ibeg, icount, iend, ierr, ii, il, imin, iout, ip, j, &
&jcol, jj, jmin, jp, k, ki, kj, l, ll, lrow, m0, mcheck, ms, n, &
&npos, nrow, ns, nstep, num
real :: amax, binorm, bmax, bmin, bnorm, cmin, const, eps, epsi, &
&ratio, rerr1, rmin, rtol, s, sgn, sum, t, tol, w, xmax
real :: spmpar
!----------------------
!     NSTEP = 1   ELIMINATE THE NEGATIVE VARIABLES
!     NSTEP = 2   PHASE 1 OF THE SIMPLEX ALGORITHM
!     NSTEP = 3   PHASE 2 OF THE SIMPLEX ALGORITHM
!----------------------
!     mxiter = THE MAXIMUM NUMBER OF ITERATIONS PERMITTED
!     iter = THE NUMBER OF THE CURRENT ITERATION
!     icount = THE NUMBER OF ITERATIONS SINCE THE LAST INVERSION
!----------------------
!     numle = THE NUMBER OF .LE. CONSTRAINTS
!     numge = THE NUMBER OF .GE. CONSTRAINTS
!----------------------
!     THE ROUTINE ASSUMES THAT THE .LE. CONSTRAINTS PRECEDE THE .GE.
!     CONSTRAINTS AND THAT THE .EQ. CONSTRAINTS COME LAST. THERE ARE
!     m constraints. X(n0+i) is the slack, surplus, or artificial
!     VARIABLE FOR THE i-TH CONSTRAINT (i=1,...,m).
!----------------------
!     n0 = THE NUMBER OF ORGINAL VARIABLES
!     NS = THE NUMBER OF ORGINAL AND SLACK VARIABLES
!     N  = THE NUMBER OF ORGINAL, SLACK, AND SURPLUS VARIABLES
!     NUM = THE TOTAL NUMBER OF VARIABLES
!----------------------
!     rerrmn = THE SMALLEST RELATIVE ERROR TOLERANCE USED
!     rerrmx = THE LARGEST RELATIVE ERROR TOLERACE USED
!     rerr   = THE ESTIMATED CURRENT RELATIVE ERROR
!----------------------
!     Assume that
!         b0 = (b0(1),...,b0(m))
!         c  = (c(1),...,c(n0))
!         z  = c(1)*x(1)+...+c(n0)*x(n0)
!     the problem is to maximize z subject to
!         AX(le,EQ,GE)b0
!         X.GE.0
!----------------------
!     On input ind can have the values
!         ind = 0   NO BEGINNING BASIS IS PROVIDED BY THE USER
!         ind = 1   THE ARRAY ibasis HAS BEEN SET BY THE USER
!     on output ind is assigned one of the values
!         ind = 0   z WAS SUCCESSFULLY MAXIMIZED
!         ind = 1   THE PROBLEM HAS NO FEASIBLE SOLUTION
!         ind = 2   mxiter ITERATIONS WERE PERFORMED
!         ind = 3   SUFFICIENT ACCURACY CANNOT BE MAINTAINED
!         ind = 4   THE PROBLEM HAS AN UNBOUNDED SOLUTION
!         ind = 5   THERE IS AN INPUT ERROR
!         ind = 6   z WAS POSSIBLY MAXIMIZED
!----------------------
!     BASIS IS AN INTEGER ARRAY OF DIMENSION n0+m. FOR j.LE.N
!         basis(j) = 1  IF X(j) IS A BASIC VARIABLE
!         basis(j) = 0  IF X(j) IS NOT A BASIC VARIABLE
!     if the BASIC variables are X(I1),...,X(IM) then
!         ibasis = (i1,...,im)
!     also xb(1),...,xb(m) are the corresponding values of the
!     BASIC variables.
!----------------------
!     bi is an MXM array containing the inverse of the basis matrix.
!----------------------
!     r is an array of dimension N. on output r contains the current
!     value of X. during computation r normally contains the reduced
!     costs used for the selection of the variable to be made BASIC.
!----------------------
real, intent(in) :: a(ka,n0), b0(m), c(n0)
real, intent(inout) :: bi(m,m), xb(m), y(m), r(*)
integer, intent(inout) :: ibasis(m), basis(*)
integer :: bflag
integer, intent(inout) :: index(m)
double precision :: dsum, dsump, dsumn, dt
!----------------------
!
!     ****** XMAX IS A MACHINE DEPENDENT CONSTANT. XMAX IS THE
!            largest positive floating point number.
!
           xmax = spmpar(3)
!
!----------------------
iter = 0
icount = 0
mcheck = min0(5,1 + m/15)
z = 0.0
!
!                Check for input errors
!
ms = numle + numge
if (m .lt. 2 .or. n0 .lt. 2 .or. ms .gt. m .or. ka .lt. m) &
&go to 12
do 10 i = 1,m
   if (b0(i) .lt. 0.0) go to 12
10 xb(i) = 0.0
rtol = xmax
do i = 1,n0
   if (c(i) .ne. 0.0) rtol = amin1(abs(c(i)),rtol)
end do
rtol = rerrmx*rtol
go to 20
!
12 ind = 5
return
!
!     FORMATION OF THE ibasis AND BASIS ARRAYS. (IF ind = 1
!     then the ibasis array is defined by the user.)
!
20 ns = n0 + numle
n = ns + numge
if (ind .eq. 0) go to 30
num = n
do i = 1,m
   if (ibasis(i) .gt. n) num = num + 1
end do
go to 32
22 if (ind .eq. 0) go to 590
ind = 0
!
30 num = n0 + m
do 31 i = 1,m
31 ibasis(i) = n0 + i
32 bflag = 0
do 33 i = 1,n
33 basis(i) = 0
do 34 i = 1,m
   ki = ibasis(i)
34 basis(ki) = 1
if (ind .eq. 1) go to 100
!
!          CALCULATION OF xb AND bi WHEN ind = 0
!
rerr = rerrmn
do j = 1,m
   xb(j) = b0(j)
   do 40 i = 1,m
40 bi(i,j) = 0.0
   bi(j,j) = 1.0
end do
if (numge .eq. 0) go to 630
jmin = numle + 1
do j = jmin,ms
   xb(j) = -xb(j)
   bi(j,j) = -1.0
end do
go to 601
!
!                  Reorder the basis
!
100 ibeg = 1
iend = m
do 102 i = 1,m
   if (ibasis(i) .le. n0) go to 101
      index(ibeg) = ibasis(i)
      ibeg = ibeg + 1
      go to 102
101 index(iend) = ibasis(i)
   iend = iend - 1
102 continue
if (iend .eq. m) go to 22
do 103 i = 1,m
103 ibasis(i) = index(i)
!
!            REINVERSION of the basis matrix
!
do 132 j = 1,m
   kj = ibasis(j)
   if (kj .le. n0) go to 110
   if (kj .le. ns) go to 120
   if (kj .le. n) go to 130
   go to 120
!
110 do 111 i = 1,m
111 bi(i,j) = a(i,kj)
   go to 132
!
120 l = kj - n0
   do 121 i = 1,m
121 bi(i,j) = 0.0
   bi(l,j) = 1.0
   go to 132
!
130 l = kj - n0
   do 131 i = 1,m
131 bi(i,j) = 0.0
   bi(l,j) = -1.0
132 continue
!
icount = 0
call crout1 (bi, m, m, iend, index, y, jcol, ierr)
if (ierr .ne. 0) go to 580
!
!         Check the accuracy of bi and reset rerr
!
bnorm = 0.0
do 142 j = 1,m
   kj = ibasis(j)
   if (kj .le. n0) go to 140
      sum = 1.0
      go to 142
140 sum = 0.0
   do 141 i = 1,m
141 sum = sum + abs(a(i,kj))
142 bnorm = amax1(bnorm,sum)
!
binorm = 0.0
do j = 1,m
   sum = 0.0
   do 150 i = 1,m
150 sum = sum + abs(bi(i,j))
   binorm = amax1(binorm,sum)
end do
rerr = amax1(rerrmn,eps0*bnorm*binorm)
if (rerr .gt. 1.e-2) go to 580
bflag = 0
!
!                 Recalculation of xb
!
180 do i = 1,m
   dsump = 0.d0
   dsumn = 0.d0
   do 182 l = 1,m
      dt = bi(i,l)*b0(l)
      if (dt .gt. 0.d0) go to 181
         dsumn = dsumn + dt
         go to 182
181 dsump = dsump + dt
182 continue
   xb(i) = dsump + dsumn
   s = dsump
   t = dsumn
   tol = rerrmx*amax1(s,-t)
   if (abs(xb(i)) .lt. tol) xb(i) = 0.0
end do
go to 601
!
!     Find the next vector a(--,JP) to be inserted into
!                       the basis
!
200 jp = 0
rmin = 0.0
if (nstep .eq. 3) rmin = -rtol
do 201 j = 1,n0
   if (basis(j) .ne. 0) go to 201
   if (r(j) .ge. rmin) go to 201
   jp = j
   rmin = r(j)
201 continue
if (n0 .eq. n) go to 203
jmin = n0 + 1
rmin = rmin*1.1
do 202 j = jmin,n
   if (basis(j) .ne. 0) go to 202
   if (r(j) .ge. rmin) go to 202
   jp = j
   rmin = r(j)
202 continue
203 if (jp .ne. 0) go to 300
if (nstep - 2) 800,230,250
!
!     Insert the values of the orginal, slack, and surplus
!             variables into r. then terminate.
!
220 do 221 j = 1,n
221 r(j) = 0.0
do i = 1,m
   ki = ibasis(i)
   if (ki .le. n) r(ki) = xb(i)
end do
return
!
!             COMPLETION OF THE NSTEP = 2 CASE
!
230 do 231 i = 1,m
   if (ibasis(i) .le. n) go to 231
   if (xb(i) .gt. 0.0) go to 800
231 continue
go to 680
!
240 if (icount .ge. 5) go to 100
ind = 1
go to 220
!
!             COMPLETION OF THE NSTEP = 3 CASE
!
250 if (rerr .gt. 1.e-2) go to 251
   ind = 0
   go to 800
251 if (icount .ge. 5) go to 100
ind = 6
go to 800
!
!     If mxiter iterations have not been performed then
!     begin the next iteration. Compute the JP-TH column
!               of bi*a and store it in y.
!
300 if (iter .lt. mxiter) go to 301
   ind = 2
   go to 220
301 iter = iter + 1
icount = icount + 1
if (jp .gt. ns) go to 330
if (jp .gt. n0) go to 320
!
nrow = 0
amax = 0.0
do 305 i = 1,m
   if (a(i,jp) .eq. 0.0) go to 305
   nrow = nrow + 1
   index(nrow) = i
   amax = amax1(abs(a(i,jp)),amax)
305 continue
if (nrow .ne. 0) go to 310
ind = 4
go to 220
!
310 rerr1 = rerrmx*amax
do 313 i = 1,m
   dsum = 0.d0
   do ll = 1,nrow
      l = index(ll)
      dsum = dsum + dble(bi(i,l)*a(l,jp))
   end do
   y(i) = dsum
   if (abs(y(i)) .ge. 5.e-3) go to 313
   bmax = 0.0
   do l = 1,m
      bmax = amax1(abs(bi(i,l)),bmax)
   end do
   tol = rerr1*bmax
   if (abs(y(i)) .lt. tol) y(i) = 0.0
313 continue
go to 350
!
320 l = jp - n0
do i = 1,m
   y(i) = bi(i,l)
end do
go to 350
!
330 l = jp - n0
do i = 1,m
   y(i) = -bi(i,l)
end do
!
350 do i = 1,m
   if (y(i) .ne. 0.0) go to 360
end do
r(jp) = 0.0
iter = iter - 1
icount = icount - 1
go to 200
!
360 if (nstep - 2) 400,430,440
!
!     Finding the variable xb(ip) to be made nonbasic
!               FOR THE NSTEP = 1 CASE
!
400 npos = 0
ip = 0
eps = 0.0
epsi = xmax
do 403 i = 1,m
   if (xb(i) .lt. 0.0 .or. y(i) .le. 0.0) go to 403
   ratio = xb(i)/y(i)
   if (ratio - epsi) 401,402,403
401 epsi = ratio
   npos = 1
   index(1) = i
   go to 403
402 npos = npos + 1
   index(npos) = i
403 continue
if (npos .eq. 0) go to 420
if (epsi .eq. 0.0) go to 460
!
do 410 i = 1,m
   if (xb(i) .ge. 0.0 .or. y(i) .ge. 0.0) go to 410
   ratio = xb(i)/y(i)
   if (ratio .gt. epsi) go to 410
   if (ratio .lt. eps) go to 410
   eps = ratio
   ip = i
410 continue
if (ip .ne. 0) go to 500
go to 460
!
420 do 421 i = 1,m
   if (xb(i) .ge. 0.0 .or. y(i) .ge. 0.0) go to 421
   ratio = xb(i)/y(i)
   if (ratio .lt. eps) go to 421
   eps = ratio
   ip = i
421 continue
go to 500
!
!     Finding the variable xb(ip) to be made nonbasic
!               FOR THE NSTEP = 2 CASE
!
430 npos = 0
epsi = xmax
do 433 i = 1,m
   if (y(i) .le. 0.0) go to 433
   ratio = xb(i)/y(i)
   if (ratio - epsi) 431,432,433
431 epsi = ratio
   npos = 1
   index(1) = i
   go to 433
432 npos = npos + 1
   index(npos) = i
433 continue
go to 450
!
!     Finding the variable xb(ip) to be made nonbasic
!               FOR THE NSTEP = 3 CASE
!
440 npos = 0
epsi = xmax
do 445 i = 1,m
   if (y(i)) 441,445,442
441 if (ibasis(i) .le. n) go to 445
   ip = i
   go to 500
442 ratio = xb(i)/y(i)
   if (ratio - epsi) 443,444,445
443 epsi = ratio
      npos = 1
      index(1) = i
      go to 445
444 npos = npos + 1
      index(npos) = i
445 continue
!
450 if (npos .ne. 0) go to 460
if (icount .ge. 5) go to 100
ind = 4
go to 220
!
!              Tie breaking procedure
!
460 ip = index(1)
if (npos .eq. 1) go to 500
ip = 0
bmin = xmax
cmin = xmax
do 464 ii = 1,npos
   i = index(ii)
   l = ibasis(i)
   if (l .gt. n0) go to 461
      if (c(l) .le. 0.0) cmin = amin1(0.0,cmin)
      if (c(l) .gt. cmin) go to 464
      imin = i
      cmin = c(l)
      go to 464
461 if (l .le. n) go to 462
      ip = i
      go to 500
462 lrow = l - n0
   s = b0(lrow)
   if (lrow .gt. numle) go to 463
      if (s .gt. bmin) go to 464
      ip = i
      bmin = s
      go to 464
463 s = -s
   bmin = amin1(0.0,bmin)
   if (s .gt. bmin) go to 464
   ip = i
   bmin = s
464 continue
if (cmin .le. 0.0 .or. ip .eq. 0) ip = imin
!
!               Transformation of xb
!
500 if (xb(ip) .eq. 0.0) go to 510
const = xb(ip)/y(ip)
do 501 i = 1,m
   s = xb(i)
   xb(i) = xb(i) - const*y(i)
   if (xb(i) .ge. 0.0) go to 501
   if (s .ge. 0.0 .or. xb(i) .ge. rerrmx*s) xb(i) = 0.0
501 continue
xb(ip) = const
!
!               Transformation of bi
!
510 do 512 j = 1,m
   if (bi(ip,j) .eq. 0.0) go to 512
   const = bi(ip,j)/y(ip)
   do 511 i = 1,m
511 bi(i,j) = bi(i,j) - const*y(i)
   bi(ip,j) = const
512 continue
!
!             Updating ibasis and basis
!
iout = ibasis(ip)
ibasis(ip) = jp
basis(iout) = 0
basis(jp) = 1
if (iout .gt. n) num = num - 1
!
!        Check the accuracy of bi and reset rerr
!
if (rerr .gt. 1.e-2) go to 530
k = 0
do 521 j = 1,m
   kj = ibasis(j)
   if (kj .gt. n0) go to 521
   sum = 0.0
   do l = 1,m
      if (a(l,kj) .ne. 0.0) sum = sum + bi(j,l)*a(l,kj)
   end do
   rerr = amax1(rerr,abs(1.0 - sum))
   k = k + 1
   if (k .ge. mcheck) go to 522
521 continue
522 if (rerr .le. 1.e-2) go to 600
!
!        The accuracy criteria are not satisfied
!
530 if (icount .lt. 5) go to 600
bflag = 1
go to 100
!
580 if (iter .eq. 0) go to 12
if (bflag .eq. 0) go to 590
bflag = 0
do ip = 1,m
   if (jp .eq. ibasis(ip)) go to 582
end do
582 ibasis(ip) = iout
basis(jp) = 0
basis(iout) = 1
if (iout .gt. n) num = num + 1
go to 100
!
590 ind = 3
go to 220
!
!       SET UP THE r ARRAY FOR THE NSTEP = 1 CASE
!
600 if (nstep - 2) 601,630,700
601 do j = 1,m
   if (xb(j) .lt. 0.0) go to 610
end do
go to 630
!
610 nstep = 1
m0 = 0
do 611 l = 1,m
   if (xb(l) .ge. 0.0) go to 611
   m0 = m0 + 1
   index(m0) = l
611 continue
!
do j = 1,m
   dsump = 0.d0
   dsumn = 0.d0
   do 622 ll = 1,m0
      l = index(ll)
      if (bi(l,j)) 620,622,621
620 dsumn = dsumn + dble(bi(l,j))
      go to 622
621 dsump = dsump + dble(bi(l,j))
622 continue
   y(j) = dsump + dsumn
   s = dsump
   t = dsumn
   tol = rerrmx*amax1(s,-t)
   if (abs(y(j)) .lt. tol) y(j) = 0.0
end do
go to 650
!
!       SET UP THE r ARRAY FOR THE NSTEP = 2 CASE
!
630 if (n .eq. num) go to 680
nstep = 2
m0 = 0
do 631 l = 1,m
   if (ibasis(l) .le. n) go to 631
   m0 = m0 + 1
   index(m0) = l
631 continue
!
do j = 1,m
   dsump = 0.d0
   dsumn = 0.d0
   do 642 ll = 1,m0
      l = index(ll)
      if (bi(l,j)) 640,642,641
640 dsumn = dsumn + dble(bi(l,j))
      go to 642
641 dsump = dsump + dble(bi(l,j))
642 continue
   y(j) = -(dsump + dsumn)
   s = dsump
   t = dsumn
   tol = rerrmx*amax1(s,-t)
   if (abs(y(j)) .lt. tol) y(j) = 0.0
end do
!
650 do 652 j = 1,n0
   sum = 0.0
   if (basis(j) .ne. 0) go to 652
   do l = 1,m
      if (a(l,j) .ne. 0.0) sum = sum + y(l)*a(l,j)
   end do
652 r(j) = sum
!
660 if (n0 .eq. ns) go to 670
jmin = n0 + 1
do 661 j = jmin,ns
   r(j) = 0.0
   if (basis(j) .ne. 0) go to 661
   jj = j - n0
   r(j) = y(jj)
661 continue
!
670 if (ns .eq. n) go to 200
jmin = ns + 1
do 671 j = jmin,n
   r(j) = 0.0
   if (basis(j) .ne. 0) go to 671
   jj = j - n0
   r(j) = -y(jj)
671 continue
go to 200
!
!      SET UP A NEW r ARRAY FOR THE NSTEP = 3 CASE
!
680 nstep = 3
do 682 j = 1,m
   dsum = 0.d0
   do l = 1,m
      il = ibasis(l)
      if (il .le. n0) dsum = dsum + dble(c(il)*bi(l,j))
   end do
682 y(j) = dsum
!
do 691 j = 1,n0
   r(j) = 0.0
   if (basis(j) .ne. 0) go to 691
   dsum = -c(j)
   do l = 1,m
      if (a(l,j) .ne. 0.0) dsum = dsum + dble(y(l)*a(l,j))
   end do
   r(j) = dsum
   if (r(j) .ge. 0.0) go to 691
   tol = rerrmx*abs(c(j))
   if (abs(r(j)) .lt. tol) r(j) = 0.0
691 continue
go to 660
!
!       UPDATE THE r ARRAY FOR THE NSTEP = 3 CASE
!
700 const = r(jp)
do 703 j = 1,n0
   if (basis(j) .eq. 0) go to 701
      r(j) = 0.0
      go to 703
701 sum = 0.0
   do l = 1,m
      if (a(l,j) .ne. 0.0) sum = sum + bi(ip,l)*a(l,j)
   end do
   r(j) = r(j) - const*sum
   if (r(j) .ge. 0.0) go to 703
   tol = rerrmx*abs(c(j))
   if (abs(r(j)) .lt. tol) r(j) = 0.0
703 continue
!
710 if (n0 .eq. ns) go to 720
jmin = n0 + 1
do 712 j = jmin,ns
   if (basis(j) .eq. 0) go to 711
      r(j) = 0.0
      go to 712
711 jj = j - n0
   r(j) = r(j) - const*bi(ip,jj)
712 continue
!
720 if (ns .eq. n) go to 200
jmin = ns + 1
do 722 j = jmin,n
   if (basis(j) .eq. 0) go to 721
      r(j) = 0.0
      go to 722
721 jj = j - n0
   r(j) = r(j) + const*bi(ip,jj)
722 continue
go to 200
!-----------------------------------------------------------------------
!               Refine xb and store the result in y
!-----------------------------------------------------------------------
800 do i = 1,m
   y(i) = 0.0
end do
!
m0 = 0
do 831 j = 1,m
   kj = ibasis(j)
   if (kj .le. n0) go to 810
   if (kj .le. ns) go to 820
   if (kj .le. n) go to 830
   go to 820
!
810 m0 = m0 + 1
   index(m0) = j
   go to 831
!
820 l = kj - n0
   y(l) = xb(j)
   go to 831
!
830 l = kj - n0
   y(l) = -xb(j)
831 continue
!
if (m0 .ne. 0) go to 841
   do 840 i = 1,m
840 r(i) = b0(i) - y(i)
   go to 850
841 do i = 1,m
   dsum = y(i)
   do jj = 1,m0
      j = index(jj)
      kj = ibasis(j)
      dsum = dsum + dble(a(i,kj)*xb(j))
   end do
   r(i) = b0(i) - dsum
end do
!
850 rerr1 = amin1(rerrmx,rerr)
do 856 i = 1,m
   y(i) = 0.0
   if (xb(i)) 851,856,852
851 sgn = -1.0
   dsump = 0.d0
   dsumn = xb(i)
   go to 853
852 sgn = 1.0
   dsump = xb(i)
   dsumn = 0.d0
853 do 855 l = 1,m
      dt = bi(i,l)*r(l)
      if (dt .gt. 0.d0) go to 854
         dsumn = dsumn + dt
         go to 855
854 dsump = dsump + dt
855 continue
   w = dsump + dsumn
   if (w .eq. 0.0) go to 856
   if (sgn .ne. sign(1.0,w)) go to 856
   s = dsump
   t = dsumn
   tol = rerr1*amax1(s,-t)
   if (abs(w) .gt. tol) y(i) = w
856 continue
if (nstep - 2) 860,870,880
!
!         CHECK THE REFINEMENT (NSTEP = 1)
!
860 do 861 i = 1,m
   if (y(i) .ge. 0.0) go to 861
   if (y(i) .lt. -rerrmx) go to 240
   y(i) = 0.0
861 xb(i) = y(i)
go to 630
!
!         CHECK THE REFINEMENT (NSTEP = 2)
!
870 do 871 i = 1,m
   if (ibasis(i) .le. n) go to 871
   if (y(i) .gt. rerrmx) go to 240
   y(i) = 0.0
871 xb(i) = y(i)
go to 680
!
!              COMPUTE z  (NSTEP = 3)
!
880 dsum = 0.d0
do 881 i = 1,m
   ki = ibasis(i)
   if (ki .gt. n0) go to 881
   dsum = dsum + dble(c(ki)*y(i))
881 xb(i) = y(i)
z = dsum
go to 220
end subroutine smplx1

subroutine ssplx (ta,ita,jta,b0,c,m,n0,ind,ibasis,x,z,iter,mxiter, &
&numle,numge,bi,wk,iwk)
implicit none
integer, intent(inout) :: ibasis, ind
integer :: ita(*)
integer, intent(inout) :: iter, iwk(*)
integer :: jta(*), m
integer, intent(in) :: mxiter, n0, numge, numle
real :: b0(m)
real, intent(inout) :: bi(m,m)
real :: c(n0), ta(*)
real, intent(inout) :: wk(*), x(*), z
integer :: ip
real :: eps0, rerr, rerrmn, rerrmx
real :: spmpar
!-----------------------------------------------------------------------
!     Simplex procedure for solving linear programming problems
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris Jr.
!        naval surface weapons center
!        Dahlgren, Virginia
!------------------------
!     Initial version  DEC  1977
!     LAST UPDATE      OCT  1990
!------------------------
dimension ibasis(m)
!------------------------
!     dimension x(n0+numle+numge)
!     dimension wk(2*m),iwk(2*m+n0)
!------------------------
!
!     ********** eps0 IS A MACHINE DEPENDENT PARAMETER. ASSIGN eps0
!                the value U where U is the smallest positive floating
!                POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0.
!
                    eps0 = spmpar(1)
!
!------------------------
rerrmn = 10.0*eps0
rerrmx = 1.e-4
if (eps0 .lt. 1.e-13) rerrmx = 1.e-5
!
ip = m + n0 + 1
call ssplx1(ta,ita,jta,b0,c,m,n0,ind,ibasis,x,z,iter,mxiter, &
&eps0,rerrmn,rerrmx,rerr,numle,numge,bi, &
&wk(1),wk(m+1),iwk(1),iwk(ip))
return
end subroutine ssplx

subroutine ssplx1 (ta,ita,jta,b0,c,m,n0,ind,ibasis,r,z, &
&iter,mxiter,eps0,rerrmn,rerrmx,rerr,numle,numge, &
&bi,xb,y,basis,index)
implicit none
integer, intent(inout) :: ind
integer, intent(out) :: iter
integer, intent(in) :: m, mxiter, n0, numge, numle
real, intent(in) :: eps0
real, intent(inout) :: rerr
real, intent(in) :: rerrmn, rerrmx
real, intent(out) :: z
integer :: i, ibeg, icount, iend, ierr, ii, il, imin, iout, ip, j, &
&jcol, jj, jmin, jp, k, ki, kj, l, ll, lmax, lmin, lrow, m0, &
&mcheck, ms, n, npos, ns, nstep, num
real :: amax, binorm, bmax, bmin, bnorm, cmin, const, eps, epsi, &
&ratio, rerr1, rmin, rtol, s, sgn, sum, t, tol, w, xmax
real :: spmpar
!----------------------
!     NSTEP = 1   ELIMINATE THE NEGATIVE VARIABLES
!     NSTEP = 2   PHASE 1 OF THE SIMPLEX ALGORITHM
!     NSTEP = 3   PHASE 2 OF THE SIMPLEX ALGORITHM
!----------------------
!     mxiter = THE MAXIMUM NUMBER OF ITERATIONS PERMITTED
!     iter = THE NUMBER OF THE CURRENT ITERATION
!     icount = THE NUMBER OF ITERATIONS SINCE THE LAST INVERSION
!----------------------
!     numle = THE NUMBER OF .LE. CONSTRAINTS
!     numge = THE NUMBER OF .GE. CONSTRAINTS
!----------------------
!     THE ROUTINE ASSUMES THAT THE .LE. CONSTRAINTS PRECEDE THE .GE.
!     CONSTRAINTS AND THAT THE .EQ. CONSTRAINTS COME LAST. THERE ARE
!     m constraints. X(n0+i) is the slack, surplus, or artificial
!     VARIABLE FOR THE i-TH CONSTRAINT (i=1,...,m).
!----------------------
!     n0 = THE NUMBER OF ORGINAL VARIABLES
!     NS = THE NUMBER OF ORGINAL AND SLACK VARIABLES
!     N  = THE NUMBER OF ORGINAL, SLACK, AND SURPLUS VARIABLES
!     NUM = THE TOTAL NUMBER OF VARIABLES
!----------------------
!     rerrmn = THE SMALLEST RELATIVE ERROR TOLERANCE USED
!     rerrmx = THE LARGEST RELATIVE ERROR TOLERANCE USED
!     rerr   = THE ESTIMATED CURRENT RELATIVE ERROR
!----------------------
!     Let a denote an MXN0 matrix. The transpose of A is stored in
!     sparse form in ta,ita,jta. Assume that
!         b0 = (b0(1),...,b0(m))
!         c  = (c(1),...,c(n0))
!         z  = c(1)*x(1)+...+c(n0)*x(n0)
!     the problem is to maximize z subject to
!         AX(le,EQ,GE)b0
!         X.GE.0
!----------------------
!     On input ind can have the values
!         ind = 0   NO BEGINNING BASIS IS PROVIDED BY THE USER
!         ind = 1   THE ARRAY ibasis HAS BEEN SET BY THE USER
!     on output ind is assigned one of the values
!         ind = 0   z WAS SUCCESSFULLY MAXIMIZED
!         ind = 1   THE PROBLEM HAS NO FEASIBLE SOLUTION
!         ind = 2   mxiter ITERATIONS WERE PERFORMED
!         ind = 3   SUFFICIENT ACCURACY CANNOT BE MAINTAINED
!         ind = 4   THE PROBLEM HAS AN UNBOUNDED SOLUTION
!         ind = 5   THERE IS AN INPUT ERROR
!         ind = 6   z WAS POSSIBLY MAXIMIZED
!----------------------
!     BASIS IS AN INTEGER ARRAY OF DIMENSION n0+m. FOR j.LE.N
!         basis(j) = 1  IF X(j) IS A BASIC VARIABLE
!         basis(j) = 0  IF X(j) IS NOT A BASIC VARIABLE
!     if the BASIC variables are X(I1),...,X(IM) then
!         ibasis = (i1,...,im)
!     also xb(1),...,xb(m) are the corresponding values of the
!     BASIC variables.
!----------------------
!     bi is an MXM array containing the inverse of the basis matrix.
!----------------------
!     r is an array of dimension N. on output r contains the current
!     value of X. during computation r normally contains the reduced
!     costs used for the selection of the variable to be made BASIC.
!----------------------
real, intent(in) :: ta(*), b0(m), c(n0)
real, intent(inout) :: bi(m,m), xb(m), y(m), r(*)
integer, intent(in) :: ita(*), jta(*)
integer, intent(inout) :: ibasis(m), basis(*)
integer :: bflag
integer, intent(inout) :: index(m)
double precision :: dsum, dsump, dsumn, dt
!----------------------
!
!     ****** XMAX IS A MACHINE DEPENDENT CONSTANT. XMAX IS THE
!            largest positive floating point number.
!
           xmax = spmpar(3)
!
!----------------------
iter = 0
icount = 0
mcheck = min0(5,1 + m/15)
z = 0.0
!
!                Check for input errors
!
ms = numle + numge
if (m .lt. 2 .or. n0 .lt. 2 .or. ms .gt. m) go to 12
do 10 i = 1,m
   if (b0(i) .lt. 0.0) go to 12
10 xb(i) = 0.0
rtol = xmax
do i = 1,n0
   if (c(i) .ne. 0.0) rtol = amin1(abs(c(i)),rtol)
end do
rtol = rerrmx*rtol
go to 20
!
12 ind = 5
return
!
!     FORMATION OF THE ibasis AND BASIS ARRAYS. (IF ind = 1
!     then the ibasis array is defined by the user.)
!
20 ns = n0 + numle
n = ns + numge
if (ind .eq. 0) go to 30
num = n
do i = 1,m
   if (ibasis(i) .gt. n) num = num + 1
end do
go to 32
22 if (ind .eq. 0) go to 590
ind = 0
!
30 num = n0 + m
do 31 i = 1,m
31 ibasis(i) = n0 + i
32 bflag = 0
do 33 i = 1,n
33 basis(i) = 0
do 34 i = 1,m
   ki = ibasis(i)
34 basis(ki) = 1
if (ind .eq. 1) go to 100
!
!          CALCULATION OF xb AND bi WHEN ind = 0
!
rerr = rerrmn
do j = 1,m
   xb(j) = b0(j)
   do 40 i = 1,m
40 bi(i,j) = 0.0
   bi(j,j) = 1.0
end do
if (numge .eq. 0) go to 630
jmin = numle + 1
do j = jmin,ms
   xb(j) = -xb(j)
   bi(j,j) = -1.0
end do
go to 601
!
!                  Reorder the basis
!
100 ibeg = 1
iend = m
do 102 i = 1,m
   if (ibasis(i) .le. n0) go to 101
      index(ibeg) = ibasis(i)
      ibeg = ibeg + 1
      go to 102
101 index(iend) = ibasis(i)
   iend = iend - 1
102 continue
if (iend .eq. m) go to 22
do 103 i = 1,m
103 ibasis(i) = index(i)
!
!            REINVERSION of the basis matrix
!
do 132 j = 1,m
   kj = ibasis(j)
   if (kj .le. n0) go to 110
   if (kj .le. ns) go to 120
   if (kj .le. n) go to 130
   go to 120
!
110 do 111 i = 1,m
111 bi(i,j) = 0.0
   lmin = ita(kj)
   lmax = ita(kj + 1) - 1
   if (lmin .gt. lmax) go to 132
   do 112 ll = lmin,lmax
      l = jta(ll)
112 bi(l,j) = ta(ll)
   go to 132
!
120 l = kj - n0
   do 121 i = 1,m
121 bi(i,j) = 0.0
   bi(l,j) = 1.0
   go to 132
!
130 l = kj - n0
   do 131 i = 1,m
131 bi(i,j) = 0.0
   bi(l,j) = -1.0
132 continue
!
icount = 0
call crout1 (bi, m, m, iend, index, y, jcol, ierr)
if (ierr .ne. 0) go to 580
!
!         Check the accuracy of bi and reset rerr
!
bnorm = 0.0
do 142 j = 1,m
   kj = ibasis(j)
   if (kj .le. n0) go to 140
      sum = 1.0
      go to 142
140 sum = 0.0
   lmin = ita(kj)
   lmax = ita(kj + 1) - 1
   do 141 ll = lmin,lmax
141 sum = sum + abs(ta(ll))
142 bnorm = amax1(bnorm,sum)
!
binorm = 0.0
do j = 1,m
   sum = 0.0
   do 150 i = 1,m
150 sum = sum + abs(bi(i,j))
   binorm = amax1(binorm,sum)
end do
rerr = amax1(rerrmn,eps0*bnorm*binorm)
if (rerr .gt. 1.e-2) go to 580
bflag = 0
!
!                 Recalculation of xb
!
180 do i = 1,m
   dsump = 0.d0
   dsumn = 0.d0
   do 182 l = 1,m
      dt = bi(i,l)*b0(l)
      if (dt .gt. 0.d0) go to 181
         dsumn = dsumn + dt
         go to 182
181 dsump = dsump + dt
182 continue
   xb(i) = dsump + dsumn
   s = dsump
   t = dsumn
   tol = rerrmx*amax1(s,-t)
   if (abs(xb(i)) .lt. tol) xb(i) = 0.0
end do
go to 601
!
!     Find the next vector A(--,JP) to be inserted into
!                       the basis
!
200 jp = 0
rmin = 0.0
if (nstep .eq. 3) rmin = -rtol
do 201 j = 1,n0
   if (basis(j) .ne. 0) go to 201
   if (r(j) .ge. rmin) go to 201
   jp = j
   rmin = r(j)
201 continue
if (n0 .eq. n) go to 203
jmin = n0 + 1
rmin = rmin*1.1
do 202 j = jmin,n
   if (basis(j) .ne. 0) go to 202
   if (r(j) .ge. rmin) go to 202
   jp = j
   rmin = r(j)
202 continue
203 if (jp .ne. 0) go to 300
if (nstep - 2) 800,230,250
!
!     Insert the values of the orginal, slack, and surplus
!             variables into r. then terminate.
!
220 do 221 j = 1,n
221 r(j) = 0.0
do i = 1,m
   ki = ibasis(i)
   if (ki .le. n) r(ki) = xb(i)
end do
return
!
!             COMPLETION OF THE NSTEP = 2 CASE
!
230 do 231 i = 1,m
   if (ibasis(i) .le. n) go to 231
   if (xb(i) .gt. 0.0) go to 800
231 continue
go to 680
!
240 if (icount .ge. 5) go to 100
ind = 1
go to 220
!
!             COMPLETION OF THE NSTEP = 3 CASE
!
250 if (rerr .gt. 1.e-2) go to 251
   ind = 0
   go to 800
251 if (icount .ge. 5) go to 100
ind = 6
go to 800
!
!     If mxiter iterations have not been performed then
!     begin the next iteration. Compute the JP-TH column
!               of bi*A and store it in y.
!
300 if (iter .lt. mxiter) go to 301
   ind = 2
   go to 220
301 iter = iter + 1
icount = icount + 1
if (jp .gt. ns) go to 330
if (jp .gt. n0) go to 320
!
lmin = ita(jp)
lmax = ita(jp + 1) - 1
if (lmin .le. lmax) go to 305
   ind = 4
   go to 220
305 amax = 0.0
do ll = lmin,lmax
   amax = amax1(abs(ta(ll)),amax)
end do
!
310 rerr1 = rerrmx*amax
do 313 i = 1,m
   dsum = 0.d0
   do ll = lmin,lmax
      l = jta(ll)
      dsum = dsum + dble(bi(i,l)*ta(ll))
   end do
   y(i) = dsum
   if (abs(y(i)) .ge. 5.e-3) go to 313
   bmax = 0.0
   do l = 1,m
      bmax = amax1(abs(bi(i,l)),bmax)
   end do
   tol = rerr1*bmax
   if (abs(y(i)) .lt. tol) y(i) = 0.0
313 continue
go to 350
!
320 l = jp - n0
do i = 1,m
   y(i) = bi(i,l)
end do
go to 350
!
330 l = jp - n0
do i = 1,m
   y(i) = -bi(i,l)
end do
!
350 do i = 1,m
   if (y(i) .ne. 0.0) go to 360
end do
r(jp) = 0.0
iter = iter - 1
icount = icount - 1
go to 200
!
360 if (nstep - 2) 400,430,440
!
!     Finding the variable xb(ip) to be made nonbasic
!               FOR THE NSTEP = 1 CASE
!
400 npos = 0
ip = 0
eps = 0.0
epsi = xmax
do 403 i = 1,m
   if (xb(i) .lt. 0.0 .or. y(i) .le. 0.0) go to 403
   ratio = xb(i)/y(i)
   if (ratio - epsi) 401,402,403
401 epsi = ratio
   npos = 1
   index(1) = i
   go to 403
402 npos = npos + 1
   index(npos) = i
403 continue
if (npos .eq. 0) go to 420
if (epsi .eq. 0.0) go to 460
!
do 410 i = 1,m
   if (xb(i) .ge. 0.0 .or. y(i) .ge. 0.0) go to 410
   ratio = xb(i)/y(i)
   if (ratio .gt. epsi) go to 410
   if (ratio .lt. eps) go to 410
   eps = ratio
   ip = i
410 continue
if (ip .ne. 0) go to 500
go to 460
!
420 do 421 i = 1,m
   if (xb(i) .ge. 0.0 .or. y(i) .ge. 0.0) go to 421
   ratio = xb(i)/y(i)
   if (ratio .lt. eps) go to 421
   eps = ratio
   ip = i
421 continue
go to 500
!
!     Finding the variable xb(ip) to be made nonbasic
!               FOR THE NSTEP = 2 CASE
!
430 npos = 0
epsi = xmax
do 433 i = 1,m
   if (y(i) .le. 0.0) go to 433
   ratio = xb(i)/y(i)
   if (ratio - epsi) 431,432,433
431 epsi = ratio
   npos = 1
   index(1) = i
   go to 433
432 npos = npos + 1
   index(npos) = i
433 continue
go to 450
!
!     Finding the variable xb(ip) to be made nonbasic
!               FOR THE NSTEP = 3 CASE
!
440 npos = 0
epsi = xmax
do 445 i = 1,m
   if (y(i)) 441,445,442
441 if (ibasis(i) .le. n) go to 445
   ip = i
   go to 500
442 ratio = xb(i)/y(i)
   if (ratio - epsi) 443,444,445
443 epsi = ratio
      npos = 1
      index(1) = i
      go to 445
444 npos = npos + 1
      index(npos) = i
445 continue
!
450 if (npos .ne. 0) go to 460
if (icount .ge. 5) go to 100
ind = 4
go to 220
!
!              Tie breaking procedure
!
460 ip = index(1)
if (npos .eq. 1) go to 500
ip = 0
bmin = xmax
cmin = xmax
do 464 ii = 1,npos
   i = index(ii)
   l = ibasis(i)
   if (l .gt. n0) go to 461
      if (c(l) .le. 0.0) cmin = amin1(0.0,cmin)
      if (c(l) .gt. cmin) go to 464
      imin = i
      cmin = c(l)
      go to 464
461 if (l .le. n) go to 462
      ip = i
      go to 500
462 lrow = l - n0
   s = b0(lrow)
   if (lrow .gt. numle) go to 463
      if (s .gt. bmin) go to 464
      ip = i
      bmin = s
      go to 464
463 s = -s
   bmin = amin1(0.0,bmin)
   if (s .gt. bmin) go to 464
   ip = i
   bmin = s
464 continue
if (cmin .le. 0.0 .or. ip .eq. 0) ip = imin
!
!               Transformation of xb
!
500 if (xb(ip) .eq. 0.0) go to 510
const = xb(ip)/y(ip)
do 501 i = 1,m
   s = xb(i)
   xb(i) = xb(i) - const*y(i)
   if (xb(i) .ge. 0.0) go to 501
   if (s .ge. 0.0 .or. xb(i) .ge. rerrmx*s) xb(i) = 0.0
501 continue
xb(ip) = const
!
!               Transformation of bi
!
510 do 512 j = 1,m
   if (bi(ip,j) .eq. 0.0) go to 512
   const = bi(ip,j)/y(ip)
   do 511 i = 1,m
511 bi(i,j) = bi(i,j) - const*y(i)
   bi(ip,j) = const
512 continue
!
!             Updating ibasis and basis
!
iout = ibasis(ip)
ibasis(ip) = jp
basis(iout) = 0
basis(jp) = 1
if (iout .gt. n) num = num - 1
!
!        Check the accuracy of bi and reset rerr
!
if (rerr .gt. 1.e-2) go to 530
k = 0
do 521 j = 1,m
   kj = ibasis(j)
   if (kj .gt. n0) go to 521
   sum = 0.0
   lmin = ita(kj)
   lmax = ita(kj + 1) - 1
   do ll = lmin,lmax
      l = jta(ll)
      sum = sum + bi(j,l)*ta(ll)
   end do
   rerr = amax1(rerr,abs(1.0-sum))
   k = k + 1
   if (k .ge. mcheck) go to 522
521 continue
522 if (rerr .le. 1.e-2) go to 600
!
!        The accuracy criteria are not satisfied
!
530 if (icount .lt. 5) go to 600
bflag = 1
go to 100
!
580 if (iter .eq. 0) go to 12
if (bflag .eq. 0) go to 590
bflag = 0
do ip = 1,m
   if (jp .eq. ibasis(ip)) go to 582
end do
582 ibasis(ip) = iout
basis(jp) = 0
basis(iout) = 1
if (iout .gt. n) num = num + 1
go to 100
!
590 ind = 3
go to 220
!
!       SET UP THE r ARRAY FOR THE NSTEP = 1 CASE
!
600 if (nstep - 2) 601,630,700
601 do j = 1,m
   if (xb(j) .lt. 0.0) go to 610
end do
go to 630
!
610 nstep = 1
m0 = 0
do 611 l = 1,m
   if (xb(l) .ge. 0.0) go to 611
   m0 = m0 + 1
   index(m0) = l
611 continue
!
do j = 1,m
   dsump = 0.d0
   dsumn = 0.d0
   do 622 ll = 1,m0
      l = index(ll)
      if (bi(l,j)) 620,622,621
620 dsumn = dsumn + dble(bi(l,j))
      go to 622
621 dsump = dsump + dble(bi(l,j))
622 continue
   y(j) = dsump + dsumn
   s = dsump
   t = dsumn
   tol = rerrmx*amax1(s,-t)
   if (abs(y(j)) .lt. tol) y(j) = 0.0
end do
go to 650
!
!       SET UP THE r ARRAY FOR THE NSTEP = 2 CASE
!
630 if (n .eq. num) go to 680
nstep = 2
m0 = 0
do 631 l = 1,m
   if (ibasis(l) .le. n) go to 631
   m0 = m0 + 1
   index(m0) = l
631 continue
!
do j = 1,m
   dsump = 0.d0
   dsumn = 0.d0
   do 642 ll = 1,m0
      l = index(ll)
      if (bi(l,j)) 640,642,641
640 dsumn = dsumn + dble(bi(l,j))
      go to 642
641 dsump = dsump + dble(bi(l,j))
642 continue
   y(j) = -(dsump + dsumn)
   s = dsump
   t = dsumn
   tol = rerrmx*amax1(s,-t)
   if (abs(y(j)) .lt. tol) y(j) = 0.0
end do
!
650 do 652 j = 1,n0
   sum = 0.0
   if (basis(j) .ne. 0) go to 652
   lmin = ita(j)
   lmax = ita(j + 1) - 1
   if (lmin .gt. lmax) go to 652
   do ll = lmin,lmax
      l = jta(ll)
      sum = sum + y(l)*ta(ll)
   end do
652 r(j)=sum
!
660 if (n0 .eq. ns) go to 670
jmin = n0 + 1
do 661 j = jmin,ns
   r(j) = 0.0
   if (basis(j) .ne. 0) go to 661
   jj = j - n0
   r(j) = y(jj)
661 continue
!
670 if (ns .eq. n) go to 200
jmin = ns + 1
do 671 j = jmin,n
   r(j) = 0.0
   if (basis(j) .ne. 0) go to 671
   jj = j - n0
   r(j) = -y(jj)
671 continue
go to 200
!
!      SET UP A NEW r ARRAY FOR THE NSTEP = 3 CASE
!
680 nstep = 3
do 682 j = 1,m
   dsum = 0.d0
   do l = 1,m
      il = ibasis(l)
      if (il .le. n0) dsum = dsum + dble(c(il)*bi(l,j))
   end do
682 y(j) = dsum
!
do 691 j = 1,n0
   r(j) = 0.0
   if (basis(j) .ne. 0) go to 691
   dsum = -c(j)
   lmin = ita(j)
   lmax = ita(j + 1) - 1
   r(j) = -c(j)
   if (lmin .gt. lmax) go to 691
   do ll = lmin,lmax
      l = jta(ll)
      dsum = dsum + dble(y(l)*ta(ll))
   end do
   r(j) = dsum
   if (r(j) .ge. 0.0) go to 691
   tol = rerrmx*abs(c(j))
   if (abs(r(j)) .lt. tol) r(j) = 0.0
691 continue
go to 660
!
!       UPDATE THE r ARRAY FOR THE NSTEP = 3 CASE
!
700 const = r(jp)
do 703 j = 1,n0
   if (basis(j) .eq. 0) go to 701
      r(j) = 0.0
      go to 703
701 sum = 0.0
   lmin = ita(j)
   lmax = ita(j + 1) - 1
   if (lmin .gt. lmax) go to 703
   do ll = lmin,lmax
      l = jta(ll)
      sum = sum + bi(ip,l)*ta(ll)
   end do
   r(j) = r(j) - const*sum
   if (r(j) .ge. 0.0) go to 703
   tol = rerrmx*abs(c(j))
   if (abs(r(j)) .lt. tol) r(j) = 0.0
703 continue
!
710 if (n0 .eq. ns) go to 720
jmin = n0 + 1
do 712 j = jmin,ns
   if (basis(j) .eq. 0) go to 711
      r(j) = 0.0
      go to 712
711 jj = j - n0
   r(j) = r(j) - const*bi(ip,jj)
712 continue
!
720 if (ns .eq. n) go to 200
jmin = ns + 1
do 722 j = jmin,n
   if (basis(j) .eq. 0) go to 721
      r(j) = 0.0
      go to 722
721 jj = j - n0
   r(j) = r(j) + const*bi(ip,jj)
722 continue
go to 200
!-----------------------------------------------------------------------
!               Refine xb and store the result in y
!-----------------------------------------------------------------------
800 do i = 1,m
   r(i) = 0.0
   y(i) = 0.0
end do
!
do 831 j = 1,m
   kj = ibasis(j)
   if (kj .le. n0) go to 810
   if (kj .le. ns) go to 820
   if (kj .le. n) go to 830
   go to 820
!
810 lmin = ita(kj)
   lmax = ita(kj + 1) - 1
   do ll = lmin,lmax
      l = jta(ll)
      dt = dble(r(l)) + dble(y(l))
      dt = dt + dble(ta(ll)*xb(j))
      r(l) = dt
      y(l) = dt - dble(r(l))
   end do
   go to 831
!
820 l = kj - n0
   dt = dble(r(l)) + dble(y(l))
   dt = dt + dble(xb(j))
   r(l) = dt
   y(l) = dt - dble(r(l))
   go to 831
!
830 l = kj - n0
   dt = dble(r(l)) + dble(y(l))
   dt = dt - dble(xb(j))
   r(l) = dt
   y(l) = dt - dble(r(l))
831 continue
!
do i = 1,m
   dt = dble(r(i)) + dble(y(i))
   r(i) = dble(b0(i)) - dt
end do
!
850 rerr1 = amin1(rerrmx,rerr)
do 856 i = 1,m
   y(i) = 0.0
   if (xb(i)) 851,856,852
851 sgn = -1.0
   dsump = 0.d0
   dsumn = xb(i)
   go to 853
852 sgn = 1.0
   dsump = xb(i)
   dsumn = 0.d0
853 do 855 l = 1,m
      dt = bi(i,l)*r(l)
      if (dt .gt. 0.d0) go to 854
         dsumn = dsumn + dt
         go to 855
854 dsump = dsump + dt
855 continue
   w = dsump + dsumn
   if (w .eq. 0.0) go to 856
   if (sgn .ne. sign(1.0,w)) go to 856
   s = dsump
   t = dsumn
   tol = rerr1*amax1(s,-t)
   if (abs(w) .gt. tol) y(i) = w
856 continue
if (nstep - 2) 860,870,880
!
!         CHECK THE REFINEMENT (NSTEP = 1)
!
860 do 861 i = 1,m
   if (y(i) .ge. 0.0) go to 861
   if (y(i) .lt. -rerrmx) go to 240
   y(i) = 0.0
861 xb(i) = y(i)
go to 630
!
!         CHECK THE REFINEMENT (NSTEP = 2)
!
870 do 871 i = 1,m
   if (ibasis(i) .le. n) go to 871
   if (y(i) .gt. rerrmx) go to 240
   y(i) = 0.0
871 xb(i) = y(i)
go to 680
!
!              COMPUTE z  (NSTEP = 3)
!
880 dsum = 0.d0
do 881 i = 1,m
   ki = ibasis(i)
   if (ki .gt. n0) go to 881
   dsum = dsum + dble(c(ki)*y(i))
881 xb(i) = y(i)
z = dsum
go to 220
end subroutine ssplx1

subroutine crout1(a,ka,n,iend,index,temp,jp,ierr)
implicit none
integer, intent(in) :: iend
integer, intent(inout) :: ierr, index(*), jp
integer, intent(in) :: ka, n
real, intent(inout) :: a(*), temp(n)
integer :: i, ibeg, ij, ik, il, j, jcol, jj, k, kcol, kcount, kj, &
&kj0, kk, kl, km1, kp1, l, lj, lj0, lk, lmin, max, mcol, ncol, nk, &
&nm1, nmj, nmk, nn
real :: c, pmin, s
!     ******************************************************************
!     crout procedure for inverting matrices
!     ******************************************************************
!     A is a matrix of order n where n is greater than or equal to 1.
!     The inverse of A is computed and stored in A.
!
!     ka = LENGTH OF THE COLUMNS OF THE ARRAY a
!     jp = THE NUMBER OF THE COLUMN THAT CONTAINS THE SMALLEST PIVOT
!
!     iend may be 0,1,...,n-1.  It is assumed that each of the first
!     iend columns of the matrix a contains only one nonzero element
!     and that the nonzero element is 1 or -1.
!
!     Index is an array of dimension n-1 or larger that is used by the
!     routine for keeping track of the row interchanges that are made.
!
!     Temp is a temporary storage array.
!
!     ierr reports the status of the results. If A is nonsingular then
!     THE INVERSE OF A IS COMPUTED AND ierr=0. OTHERWISE IF A IS FOUND
!     TO BE SINGULAR THEN ierr=1 AND THE ROUTINE TERMINATES.
!     --------------------
double precision :: dsum
max = ka*n
mcol = iend*ka
if (iend .eq. 0) go to 100
!
!           Process the first iend columns of A
!
kcol = 0
do 32 k = 1,iend
kk = kcol + k
nk = kcol + n
do 10 lk = kk,nk
if (a(lk)) 20,10,30
10 continue
jp = k
go to 300
!
20 l = lk - kcol
lj0 = mcol + l
do 21 lj = lj0,max,ka
21 a(lj) = -a(lj)
!
30 l = lk - kcol
index(k) = l
if (k .eq. l) go to 32
lj = lk
do 31 kj = kk,max,ka
c = a(kj)
a(kj) = a(lj)
a(lj) = c
31 lj = lj + ka
32 kcol = kcol + ka
!
!           Process the remaining columns of A
!
100 nm1 = n - 1
jp = 1
ierr = 0
pmin = 0.0
ibeg = iend + 1
if (ibeg .eq. n) go to 190
!
k = ibeg
km1 = iend
kp1 = k + 1
kcol = mcol
kk = kcol + k
do kcount = ibeg,nm1
!
!     SEARCH FOR THE k-TH PIVOT ELEMENT (k=ibeg,...,n-1)
!
l = k
s = abs(a(kk))
do 110 i = kp1,n
ik = kcol + i
c = abs(a(ik))
if (s .ge. c) go to 110
l = i
s = c
110 continue
!
if (k.gt.ibeg .and. s.ge.pmin) go to 120
jp = k
pmin = s
if (s .eq. 0.0) go to 300
!
!              Interchanging rows k and L
!
120 index(k) = l
if (k .eq. l) go to 130
kj0 = mcol + k
lj  = mcol + l
do 121 kj = kj0,max,ka
c = a(kj)
a(kj) = a(lj)
a(lj) = c
121 lj = lj + ka
!
!       COMPUTE THE k-TH ROW OF U (k=ibeg,...,n-1)
!
130 c = a(kk)
if (k .gt. ibeg) go to 140
kj0 = kk + ka
do 131 kj = kj0,max,ka
131 a(kj) = a(kj)/c
go to 160
!
140 kl = mcol + k
do 141 l = ibeg,km1
temp(l) = a(kl)
141 kl = kl + ka
!
kj0 = kk + ka
do 151 kj = kj0,max,ka
jcol = kj - k
dsum = -a(kj)
  do 150 l = ibeg,km1
  lj = jcol + l
150 dsum = dsum + dble(temp(l))*dble(a(lj))
151 a(kj) = sngl(-dsum)/c
!
!      COMPUTE THE k-TH COLUMN OF L (k=ibeg+1,...,n)
!
160 km1 = k
k = kp1
kp1 = k + 1
kcol = kcol + ka
kk = kcol + k
do 161 l = ibeg,km1
lk = kcol + l
161 temp(l) = a(lk)
!
do 171 i = k,n
il = mcol + i
dsum = 0.d0
  do 170 l = ibeg,km1
  dsum = dsum + dble(a(il))*dble(temp(l))
170 il = il + ka
171 a(il) = dble(a(il)) - dsum
end do
!
!           Check the n-TH pivot element
!
190 ncol = max - ka
nn = ncol + n
c = abs(a(nn))
if (c .gt. pmin) go to 200
jp = n
if (c .eq. 0.0) go to 300
!
!          Replace L with the inverse of L
!
200 if (ibeg .eq. n) go to 213
jj = mcol + ibeg
i = ka + 1
do 212 j = ibeg,nm1
a(jj) = 1.0/a(jj)
temp(j) = a(jj)
kj = jj
  do 211 km1 = j,nm1
  k = km1 + 1
  kj = kj + 1
  dsum = 0.d0
  kl = kj
    do 210 l = j,km1
    dsum = dsum + dble(a(kl)*temp(l))
210 kl = kl + ka
  a(kj) = sngl(-dsum)/a(kl)
211 temp(k) = a(kj)
212 jj = jj + i
213 a(nn) = 1.0/a(nn)
if (n .eq. 1) return
!
!       SOLVE UX = Y WHERE Y IS THE INVERSE OF L
!
do nmk = 1,nm1
k = n - nmk
lmin = max0(ibeg,k+1)
kl = (lmin-1)*ka + k
  do 230 l = lmin,n
  temp(l) = a(kl)
  a(kl) = 0.0
230 kl = kl + ka
!
kj0 = mcol + k
  do 241 kj = kj0,max,ka
  dsum = -a(kj)
  lj = (kj - k) + lmin
    do 240 l = lmin,n
    dsum = dsum + dble(temp(l)*a(lj))
240 lj = lj + 1
241 a(kj) = -dsum
end do
!
!                 Column interchanges
!
jcol = ncol - ka
do 251 nmj = 1,nm1
j = n - nmj
k = index(j)
if (j .eq. k) go to 251
ij = jcol
ik = (k-1)*ka
  do 250 i = 1,n
  ij = ij + 1
  ik = ik + 1
  c = a(ij)
  a(ij) = a(ik)
250 a(ik) = c
251 jcol = jcol - ka
return
!
!                    Error return
!
300 ierr = 1
return
end subroutine crout1

subroutine assgn (n,a,c,t,iwk,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n
integer :: i1, i2, i3, i4, i5, i6
!     -------------------
!     Solution of the assignment problem
!     -------------------
integer, intent(inout) :: a(n,*), c(n), t, iwk(*)
!
i1 = n + 1
i2 = i1 + n
i3 = i2 + n
i4 = i3 + n + 1
i5 = i4 + n
i6 = i5 + n
call assgn1(n,a,c,t,iwk(1),iwk(i1),iwk(i2),iwk(i3),iwk(1), &
&iwk(i3),iwk(i4),iwk(i5),iwk(i6),ierr)
return
end subroutine assgn

subroutine assgn1(n,a,c,t,ch,lc,lr,lz,nz,rh,slc,slr, &
&u,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: n
integer :: i, j, k, kslc, kslr, l, lj, lm, m, maxnum, mm, nl, nm, &
&np1
integer :: ipmpar
integer, intent(inout) :: a(n,*), c(n), ch(n), lc(n), lr(n), &
&lz(n), nz(n), rh(*), slc(n), slr(n), u(*)
integer :: h, q, r, s
integer, intent(inout) :: t
!
! This subroutine solves the square assignment problem
! the meaning of the input parameters is
! n = NUMBER OF ROWS AND COLUMNS OF THE COST MATRIX
! a(i,j) = ELEMENT IN ROW i AND COLUMN j OF THE COST MATRIX
! ( at the end of computation the elements of A are changed)
! the meaning of the output parameters is
! c(j) = ROW ASSIGNED TO COLUMN j (j=1,n)
! t = COST OF THE OPTIMAL ASSIGNMENT
! all parameters are integer
! the meaning of the local variables is
! a(i,j) = ELEMENT OF THE COST MATRIX IF a(i,j) IS POSITIVE,
!          column of the unassigned zero following in row i
!          (i=1,n) THE UNASSIGNED ZERO OF COLUMN j (j=1,n)
!          if a(i,j) is not positive
! a(i,n+1) = COLUMN OF THE FIRST UNASSIGNED ZERO OF ROW i
!            (i=1,n)
! ch(i) = COLUMN OF THE NEXT UNEXPLORED AND UNASSIGNED ZERO
!         OF ROW i (i=1,n)
! lc(j) = LABEL OF COLUMN j (j=1,n)
! lr(i) = LABEL OF ROW i (i=1,n)
! LZ(i) = COLUMN OF THE LAST UNASSIGNED ZERO OF ROW i(i=1,n)
! NZ(i) = COLUMN OF THE NEXT UNASSIGNED ZERO OF ROW i(i=1,n)
! RH(i) = UNEXPLORED ROW FOLLOWING THE UNEXPLORED ROW i
!         (i=1,n)
! RH(n+1) = FIRST UNEXPLORED ROW
! SLC(k) = k-TH ELEMENT CONTAINED IN THE SET OF THE LABELLED
!          columns
! SLR(k) = k-TH ELEMENT CONTAINED IN THE SET OF THE LABELLED
!          rows
! U(i) = UNASSIGNED ROW FOLLOWING THE UNASSIGNED ROW i
!        (i=1,n)
! U(n+1) = FIRST UNASSIGNED ROW
! ierr = 0 IF THE ROUTINE TERMINATES SUCCESSFULLY. OTHERWISE
!          ierr = 1
!
! The vectors c,ch,lc,lr,LZ,NZ,SLC,slr must be dimensioned
! at least at (n), the vectors RH,U at  least at (n+1),
! and the matrix a at least at (n,n+1). To save storage
! LZ and RH may use the same storage area, and NZ and ch
! may use the same storage area.
!
! Initialization
maxnum = ipmpar(3)
ierr = 0
np1 = n+1
do j=1,n
  c(j) = 0
  lz(j) = 0
  nz(j) = 0
  u(j) = 0
end do
u(np1) = 0
t = 0
! Reduction of the initial cost matrix
do 40 j = 1,n
  s = a(1,j)
  do l=2,n
    if ( a(l,j) .lt. s ) s = a(l,j)
  end do
  if (s) 20,40,30
20 mm = maxnum + s
  if (t .lt. -mm) go to 400
  t = t + s
  do i = 1,n
    if (a(i,j) .gt. mm) go to 400
    a(i,j) = a(i,j) - s
  end do
  go to 40
30 mm = maxnum - s
  if (t .gt. mm) go to 400
  t = t + s
  do i = 1,n
    a(i,j) = a(i,j) - s
  end do
40 continue
do i=1,n
  q = a(i,1)
  do l=2,n
    if ( a(i,l) .lt. q ) q = a(i,l)
  end do
  mm = maxnum - q
  if (t .gt. mm) go to 400
  t = t + q
  l = np1
  do 60 j = 1,n
    a(i,j) = a(i,j)-q
    if ( a(i,j) .ne. 0 ) go to 60
    a(i,l) = -j
    l = j
60 continue
end do
! Choice of the initial solution
k = np1
do 140 i = 1,n
  lj = np1
  j = -a(i,np1)
80 if ( c(j) .eq. 0 ) go to 130
  lj = j
  j = -a(i,j)
  if ( j .ne. 0 ) go to 80
  lj = np1
  j = -a(i,np1)
90 r = c(j)
  lm = lz(r)
  m = nz(r)
100 if ( m .eq. 0 ) go to 110
  if ( c(m) .eq. 0 ) go to 120
  lm = m
  m = -a(r,m)
  go to 100
110 lj = j
  j = -a(i,j)
  if ( j .ne. 0 ) go to 90
  u(k) = i
  k = i
  go to 140
120 nz(r) = -a(r,m)
  lz(r) = j
  a(r,lm) = -j
  a(r,j) = a(r,m)
  a(r,m) = 0
  c(m) = r
130 c(j) = i
  a(i,lj) = a(i,j)
  nz(i) = -a(i,j)
  lz(i) = lj
  a(i,j) = 0
140 continue
! Research of a new assignment
150 if ( u(np1) .eq. 0 ) return
do i=1,n
  ch(i) = 0
  lc(i) = 0
  lr(i) = 0
  rh(i) = 0
end do
rh(np1) = -1
kslc = 0
kslr = 1
r = u(np1)
lr(r) = -1
slr(1) = r
if ( a(r,np1) .eq. 0 ) go to 220
170 l = -a(r,np1)
if ( a(r,l) .eq. 0 ) go to 180
if ( rh(r) .ne. 0 ) go to 180
rh(r) = rh(np1)
ch(r) = -a(r,l)
rh(np1) = r
180 if ( lc(l) .eq. 0 ) go to 200
if ( rh(r) .eq. 0 ) go to 210
190 l = ch(r)
ch(r) = -a(r,l)
if ( a(r,l) .ne. 0 ) go to 180
rh(np1) = rh(r)
rh(r) = 0
go to 180
200 lc(l) = r
if ( c(l) .eq. 0 ) go to 360
kslc = kslc+1
slc(kslc) = l
r = c(l)
lr(r) = l
kslr = kslr+1
slr(kslr) = r
if ( a(r,np1) .ne. 0 ) go to 170
210 continue
if ( rh(np1) .gt. 0 ) go to 350
! Reduction of the current cost matrix
220 h = maxnum
do 240 j = 1,n
  if ( lc(j) .ne. 0 ) go to 240
  do k=1,kslr
    i = slr(k)
    if ( a(i,j) .lt. h ) h = a(i,j)
  end do
240 continue
mm = maxnum - h
if (mm .eq. 0 .or. t .gt. mm) go to 400
t = t + h
do 290 j = 1,n
  if ( lc(j) .ne. 0 ) go to 290
  do 280 k = 1,kslr
    i = slr(k)
    a(i,j) = a(i,j)-h
    if ( a(i,j) .ne. 0 ) go to 280
    if ( rh(i) .ne. 0 ) go to 250
    rh(i) = rh(np1)
    ch(i) = j
    rh(np1) = i
250 l = np1
260 nl = -a(i,l)
    if ( nl .eq. 0 ) go to 270
    l = nl
    go to 260
270 a(i,l) = -j
280 continue
290 continue
if ( kslc .eq. 0 ) go to 350
do 340 i = 1,n
  if ( lr(i) .ne. 0 ) go to 340
  do 330 k = 1,kslc
    j = slc(k)
    if ( a(i,j) .gt. 0 ) go to 320
    l = np1
300 nl = - a(i,l)
    if ( nl .eq. j ) go to 310
    l = nl
    go to 300
310 a(i,l) = a(i,j)
    a(i,j) = h
    go to 330
320 mm = maxnum - h
    if (a(i,j) .gt. mm) go to 400
    a(i,j) = a(i,j) + h
330 continue
340 continue
350 r = rh(np1)
go to 190
! Assignment of a new row
360 c(l) = r
m = np1
370 nm = -a(r,m)
if ( nm .eq. l ) go to 380
m = nm
go to 370
380 a(r,m) = a(r,l)
a(r,l) = 0
if ( lr(r) .lt. 0 ) go to 390
l = lr(r)
a(r,l) = a(r,np1)
a(r,np1) = -l
r = lc(l)
go to 360
390 u(np1) = u(r)
u(r) = 0
go to 150
! Error return - integer overflow occurs
400 ierr = 1
return
end subroutine assgn1

subroutine mkp (n,m,p,w,k,bck,xstar,vstar,wk,iwk,num)
implicit none
integer, intent(in) :: m, n, num
integer :: i, isumw, j, jj, jn, jnn, l, lx, lxi, maxw, minw, mn, &
&n5, np1, npl
real :: ap, aw
!
! Subroutine to solve A 0-1 multiple knapsack problem of n
! ITEMS (WITH  n .GE. 2) AND  m  KNAPSACKS (WITH  m .GE. 1 ,
! I.E. also suitable for A 0-1 single knapsack problem).
! The problem to be solved is
!
! MAXIMIZE  vstar = p(1)*(x(1,1) + ... + x(m,1)) + ...
!                   ... + p(n)*(x(1,n) + ... + x(m,n))
! subject to
! w(1)*x(i,1) + ... + w(n)*x(i,n) .LE. k(i)   FOR  i=1,...,m
! x(1,j) + ... + x(m,j) .LE. 1   FOR  j=1,...,n
! x(i,j) = 0 OR 1   FOR  i=1,...,m ,  j=1,...,n ,
!
! Where all p(j), w(j), and k(i) are positive integers.
! Before mkp is called, array k must be sorted so that
! k(1) .LE. k(2) .LE. ... .LE. k(m) .
!
! Meaning of the input parameters ...
!
! n    = NUMBER OF ITEMS.
! m    = NUMBER OF KNAPSACKS.
! p(j) = PROFIT OF ITEM  j  (j=1,...,n) .
! w(j) = WEIGHT OF ITEM  j  (j=1,...,n) .
! k(i) = CAPACITY OF KNAPSACK  i  (i=1,...,m) .
! bck  = -1  IF EXACT SOLUTION IS REQUIRED.
!      = MAXIMUM NUMBER OF BACKTRACKINGS TO BE PERFORMED, IF
!        heuristic solution is required.
! wk   = REAL WORK SPACE OF DIMENSION n.
! iwk  = WORK SPACE OF DIMENSION .GE. 5*m + 14*n + 4*m*n + 3
! num  = DIMENSION OF iwk
!
! Meaning of the output parameters ...
!
! xstar(j) = 0  IF ITEM  j  IS NOT IN THE OPTIMAL SOLUTION
!               (I.E. IF  x(i,j) = 0  FOR ALL  i ).
!          = KNAPSACK WHERE ITEM  j  IS INSERTED, OTHERWISE
!            (I.E. IF  x(xstar(j),j) = 1 ).
! vstar    = VALUE OF THE OPTIMAL SOLUTION IF  vstar .GT. 0.
!          = ERROR CONDITION (INFEASIBILITY OR TRIVIALITY)
!            IN THE INPUT DATA IF  vstar .LT. 0 .
!            = -1  IF  n .LT. 2  OR  m .LT. 1 .
!            = -2  IF SOME  p(j) ,  w(j)  OR  k(i) ARE NOT
!                  positive.
!            = -3  IF A KNAPSACK CANNOT CONTAIN ANY ITEM.
!            = -4  IF AN ITEM CANNOT FIT INTO ANY KNAPSACK.
!            = -5  IF KNAPSACK  m  CONTAINS ALL THE ITEMS.
!            = -7  IF ARRAY  k IS NOT CORRECTLY SORTED.
!            = -8  IF num .LT. 5*m + 14*n + 4*m*n + 3.
!
!            (In all the above cases array  xstar is not
!            defined).
!
! All the parameters except wk are of integer type. When mkp
! terminates, all the input parameters are unchanged except
! bck, which gives the number of backtrackings performed.
!
integer, intent(inout) :: p(n), w(n)
integer, intent(in) :: k(m)
integer, intent(inout) :: xstar(n), bck, vstar, iwk(num)
real, intent(inout) :: wk(n)
integer :: bb, bl, x, xl
integer :: b, ubb
integer :: f, pbl, q, v
integer :: bs, ps, ws, xs
!
!                    Check the input data
!
if (m .lt. 1 .or. n .lt. 2) go to 100
mn = m*n
if (num .lt. 5*m + 14*n + 4*mn + 3) go to 160
!
if (p(1) .le. 0 .or. w(1) .le. 0) go to 110
ap = p(1)
aw = w(1)
wk(1) = -ap/aw
maxw = w(1)
minw = w(1)
isumw = w(1)
do j = 2,n
   if (p(j) .le. 0 .or. w(j) .le. 0) go to 110
   ap = p(j)
   aw = w(j)
   wk(j) = -ap/aw
   if (w(j) .gt. maxw) maxw = w(j)
   if (w(j) .lt. minw) minw = w(j)
   isumw = isumw + w(j)
end do
!
if (k(1) .le. 0) go to 110
if (m .eq. 1) go to 30
do i = 2,m
   if (k(i) .le. 0) go to 110
   if (k(i) .lt. k(i-1)) go to 150
end do
!
30 if (minw .gt. k(1)) go to 120
if (maxw .gt. k(m)) go to 130
if (isumw .le. k(m)) go to 140
vstar = 0
!
!             Reorder the arrays p and w so that
!                p(j)/w(j) .GE. p(j+1)/w(j+1)
!
n5 = 5*n
do j = 1,n
   jj = n5 + j
   iwk(jj) = j
end do
call risort (wk, iwk(n5 + 1), n)
!
do j = 1,n
   iwk(j) = p(j)
   jn = j + n
   iwk(jn) = w(j)
end do
!
do j = 1,n
   jj = n5 + j
   l = iwk(jj)
   p(j) = iwk(l)
   npl = n + l
   w(j) = iwk(npl)
end do
!
!                Partition the work space iwk
!
lx =  jj + 1
lxi = lx + n
bs = lxi + n
xs =  bs + n
ubb = xs + n
!
np1 = n + 1
b = ubb + n
ps = b  + np1
ws = ps + np1
!
f = ws + np1
pbl = f + m
q = pbl + m
v = q + m
!
bb = v + m
x = bb + mn
xl = x + mn
!
bl = xl + mn
!
!                     Solve the problem
!
call mkp1 (n, m, p, w, k, bck, xstar, vstar, np1, n5, &
&iwk(bb), iwk(bl), iwk(x), iwk(xl), &
&iwk(b), iwk(ubb), iwk(lx), iwk(lxi), &
&iwk(f), iwk(pbl), iwk(q), iwk(v), &
&iwk(bs), iwk(ps), iwk(ws), iwk(xs), iwk(1))
!
!           Restore the initial ordering to p and w,
!                and reorder xstar accordingly
!
do j = 1,n
   iwk(j) = p(j)
   jn = j + n
   iwk(jn) = w(j)
   jnn = jn + n
   iwk(jnn) = xstar(j)
end do
!
do j = 1,n
   jj = n5 + j
   l = iwk(jj)
   p(l) = iwk(j)
   jn = j + n
   w(l) = iwk(jn)
   jnn = jn + n
   xstar(l) = iwk(jnn)
end do
return
!
!                        Error return
!
100 vstar = -1
return
110 vstar = -2
return
120 vstar = -3
return
130 vstar = -4
return
140 vstar = -5
return
150 vstar = -7
return
160 vstar = -8
return
end subroutine mkp

subroutine mkp1 (n, m, p, w, k, bck, xstar, vstar, np1, n5, &
&bb, bl, x, xl, b, ubb, lx, lxi, &
&f, pbl, q, v, bs, ps, ws, xs, iwk)
implicit none
integer, intent(in) :: m, n, n5, np1
integer :: i, i1, ibv, iflag, ii, ip, ip1, iuv, j, jbck, jj, k1, &
&kub, lb, li, lj, lr, lri, lub, lubi, m1, n1
!
! Meaning of the main internal variables and arrays ...
!
! i       = KNAPSACK CURRENTLY CONSIDERED.
! LB      = LOWER BOUND ON THE OPTIMAL SOLUTION.
! ub      = UPPER BOUND ON THE OPTIMAL SOLUTION.
! vb      = VALUE OF THE CURRENT SOLUTION.
! x(i,j)  = 1  IF ITEM  j  IS INSERTED IN KNAPSACK  i  IN
!              the current solution.
!         = 0  OTHERWISE.
! f(i)    = POINTER TO THE LAST ITEM INSERTED IN KNAPSACK  i
!           ( = -1  IF KNAPSACK  i  IS EMPTY).
! bb(i,j) = POINTER TO THE ITEM INSERTED IN KNAPSACK  i
!           JUST BEFORE ITEM  j ( = -1  IF  j  IS THE FIRST
!           item inserted in knapsack  i ).
! q(i)    = CURRENT AVAILABLE CAPACITY OF KNAPSACK  i .
! b(j)    = 1  IF ITEM  j  IS NOT INSERTED IN ANY KNAPSACK.
!         = 0  IF ITEM  j  IS INSERTED IN A KNAPSACK.
! pbl(i)  = NUMBER OF THE ITEMS WHICH CAN BE INSERTED IN
!           KNAPSACK  i .
! bl(i,s) = POINTER TO THE  s-TH  ITEM WHICH CAN BE INSERTED
!           in knapsack  i .
! xl(i,j) = 1  IF ITEM  j  WAS INSERTED IN KNAPSACK  i  IN
!              the last execution of subroutine pi1.
!         = 0  OTHERWISE.
! iwk       WORK SPACE FOR THE SUBROUTINE sknp.
!
integer, intent(in) :: p(n), w(n), k(m)
integer, intent(inout) :: xstar(n), bck, vstar
integer, intent(inout) :: bb(m,n), bl(m,np1), x(m,n), xl(m,n)
integer, intent(inout) :: b(np1), ubb(n), lx(n), lxi(n)
integer, intent(inout) :: f(m), pbl(m), q(m), v(m)
integer, intent(inout) :: bs(n), ps(np1), ws(np1), xs(n), iwk(n5)
integer :: s, u, ub, vb
!
if (m .eq. 1) go to 250
!
! Step 1 (initialization)
!
jbck = bck
bck = 0
kub = 0
n1 = n + 1
b(n1) = 1
m1 = m - 1
do j=1,n
  b(j) = 1
  do i=1,m
    x(i,j) = 0
    bb(i,j) = 0
  end do
end do
do i=1,m1
  q(i) = k(i)
  f(i) = -1
end do
q(m) = k(m)
vstar = 0
vb = 0
i = 1
call sigma1 (n,m,p,w,k,1,b,kub,ub,np1,n5,lx,lr, &
&bs,ps,ws,xs,iwk)
do j=1,n
  lxi(j) = lx(j)
end do
lri = lr
lubi = ub
iflag = 0
!
! Step 2 (heuristic)
!
70 kub = vstar - vb
call pi1 (n,m,p,w,q,i,b,bb,kub,bl,lb,pbl,v,xl, &
&np1,n5,bs,ps,ws,xs,iwk)
if ( lb + vb .le. vstar ) go to 140
vstar = lb + vb
do 90 j = 1,n
  xstar(j) = 0
  do 80 s = 1,i
    if ( x(s,j) .eq. 0 ) go to 80
    xstar(j) = s
    go to 90
80 continue
90 continue
ip = pbl(i)
if ( ip .eq. 0 ) go to 110
do j=1,ip
  jj = bl(i,j)
  if ( xl(i,j) .eq. 1 ) xstar(jj) = i
end do
110 i1 = i + 1
do 130 ii = i1,m
  ip = pbl(ii)
  if ( ip .eq. 0 ) go to 130
  do j=1,ip
    jj = bl(ii,j)
    if ( xl(ii,j) .eq. 1 ) xstar(jj) = ii
  end do
130 continue
if ( ub .eq. lb ) go to 200
!
! Step 3 (updating)
!
140 if ( v(i) .eq. 0 ) go to 180
iuv = ub + vb
u = pbl(i)
ibv = 0
do 170 s = 1,u
  if ( xl(i,s) .eq. 0 ) go to 170
  j = bl(i,s)
  x(i,j) = 1
  q(i) = q(i) - w(j)
  vb = vb + p(j)
  b(j) = 0
  bb(i,j) = f(i)
  ubb(j) = iuv
  if ( iflag .eq. 1 ) go to 150
  lub = iuv
  lj = j
  li = i
150 f(i) = j
  ibv = ibv + p(j)
  if ( ibv .eq. v(i) ) go to 180
  call parc (i,i,ub,iflag,vb,lub,lj,li,f,bb,q,b,n,m,np1, &
&lx,lxi,lr,lri,lubi)
  if ( iflag .eq. 1 ) go to 160
  kub = vstar - vb
  call sigma1 (n,m,p,w,q,i,b,kub,ub,np1,n5,lx,lr, &
&bs,ps,ws,xs,iwk)
  lj = n1
160 iuv = ub + vb
  if ( iuv .le. vstar ) go to 200
170 continue
180 if ( i .eq. m - 1 ) go to 200
ip1 = i + 1
call parc (ip1,i,ub,iflag,vb,lub,lj,li,f,bb,q,b,n,m,np1, &
&lx,lxi,lr,lri,lubi)
if ( iflag .eq. 1 ) go to 190
kub = vstar - vb
call sigma1 (n,m,p,w,q,ip1,b,kub,ub,np1,n5,lx,lr, &
&bs,ps,ws,xs,iwk)
lj = n1
190 if ( ub + vb .le. vstar ) go to 200
i = i + 1
go to 140
!
! Step 4 (backtracking)
!
200 if ( i .gt. 0 ) go to 210
bck = bck - 1
return
210 if ( bck .eq. jbck ) return
bck = bck + 1
if ( f(i) .ne. (-1) ) go to 230
do j=1,n
  bb(i,j) = 0
end do
i = i - 1
go to 200
230 j = f(i)
x(i,j) = 0
b(j) = 1
vb = vb - p(j)
q(i) = q(i) + w(j)
do s=1,n
  if ( bb(i,s) .eq. j ) bb(i,s) = 0
end do
f(i) = bb(i,j)
if ( ubb(j) .le. vstar ) go to 200
ub = ubb(j) - vb
iflag = 1
go to 70
!
! Particular case (0-1 single knapsack problem)
!
250 k1 = k(1)
do j=1,n
  ps(j) = p(j)
  ws(j) = w(j)
end do
call sknp (n,k1,0,vstar,n,np1,n5,ps,ws,xs,iwk)
do j=1,n
  xstar(j) = xs(j)
end do
bck = 0
return
end subroutine mkp1

subroutine sigma1 (n,m,p,w,q,i,b,kub,ub,np1,n5,lx,lr, &
&bs,ps,ws,xs,iwk)
implicit none
integer, intent(in) :: i, kub
integer, intent(inout) :: lr
integer, intent(in) :: m, n, n5, np1
integer :: j, jj, ns
!
! Subroutine to compute an upper bound  ub  on the best
! final solution which can be obtained from the current
! solution.
!
integer, intent(in) :: p(n), w(n), q(m), b(np1)
integer, intent(inout) :: ub, iwk(n5)
integer, intent(inout) :: lx(n), bs(n), ps(np1), ws(np1), xs(n)
integer :: qs, sb
!
ns = 0
qs = 0
do j=i,m
  qs = qs + q(j)
end do
sb = 0
do 20 j = 1,n
  lx(j) = 0
  if ( b(j) .eq. 0 ) go to 20
  ns = ns + 1
  bs(ns) = j
  ps(ns) = p(j)
  ws(ns) = w(j)
  sb = sb + w(j)
20 continue
if ( sb .gt. qs ) go to 40
lr = qs - sb
ub = 0
if ( ns .eq. 0 ) return
do j=1,ns
  ub = ub + ps(j)
  xs(j) = 1
end do
go to 50
40 call sknp (ns,qs,kub,ub,n,np1,n5,ps,ws,xs,iwk)
lr = qs
50 do j=1,ns
  jj = bs(j)
  lx(jj) = xs(j)
end do
return
end subroutine sigma1

subroutine pi1 (n,m,p,w,q,i,b,bb,kub,bl,lb,pbl,v,xl, &
&np1,n5,bs,ps,ws,xs,iwk)
implicit none
integer, intent(in) :: i
integer, intent(inout) :: kub, lb
integer, intent(in) :: m, n, n5, np1
integer :: ii, ikub, j, jb, jbs, jj, ns
!
! Subroutine to compute a feasible solution to the current
! problem. The solution is stored in array  xl , the
! corresponding value in  lb .
!
integer, intent(in) :: bb(m,n)
integer, intent(inout) :: bl(m,np1), xl(m,n), iwk(n5)
integer, intent(in) :: p(n), w(n), q(m), b(np1)
integer, intent(inout) :: pbl(m), v(m)
integer, intent(inout) :: bs(n), ps(np1), ws(np1), xs(n)
integer :: pb, qs, sb, u
!
! Step 1
!
u = 0
do 10 j = 1,n
  if ( b(j) .eq. 0 ) go to 10
  u = u + 1
  bs(u) = j
10 continue
do j=i,m
  pbl(j) = 0
  v(j) = 0
end do
lb = 0
ikub = kub
if ( u .eq. 0 ) return
ns = 0
sb = 0
do 30 j = 1,u
  jj = bs(j)
  if ( bb(i,jj) .ne. 0 ) go to 30
  if ( w(jj) .gt. q(i) ) go to 30
  ns = ns + 1
  sb = sb + w(jj)
  bl(i,ns) = jj
  ps(ns) = p(jj)
  ws(ns) = w(jj)
30 continue
ii = i
!
! Step 2
!
40 pbl(ii) = ns
if ( sb .gt. q(ii) ) go to 60
pb = 0
if ( ns .eq. 0 ) go to 80
do j=1,ns
  pb = pb + ps(j)
  xl(ii,j) = 1
end do
go to 80
60 qs = q(ii)
kub = 0
if ( ii .eq. m ) kub = ikub
call sknp (ns,qs,kub,pb,n,np1,n5,ps,ws,xs,iwk)
do j=1,ns
  xl(ii,j) = xs(j)
end do
80 lb = lb + pb
ikub = ikub - pb
v(ii) = pb
bl(ii,ns+1) = n + 1
!
! Step 3
!
if ( ii .eq. m ) return
jb = 1
jbs = 0
do 100 j = 1,u
  if ( bs(j) .lt. bl(ii,jb) ) go to 90
  jb = jb + 1
  if ( xl(ii,jb-1) .eq. 1 ) go to 100
90 jbs = jbs + 1
  bs(jbs) = bs(j)
100 continue
u = jbs
if ( u .eq. 0 ) return
ns = 0
sb = 0
ii = ii + 1
do 110 j = 1,u
  jj = bs(j)
  if( w(jj) .gt. q(ii) ) go to 110
  ns = ns + 1
  sb = sb + w(jj)
  bl(ii,ns) = jj
  ps(ns) = p(jj)
  ws(ns) =  w(jj)
110 continue
go to 40
end subroutine pi1

subroutine parc (i,ii,ub,iflag,vb,lub,lj,li,f,bb,q,b,n,m,np1, &
&lx,lxi,lr,lri,lubi)
implicit none
integer, intent(in) :: i
integer, intent(out) :: iflag
integer, intent(in) :: ii, li, lj, lr, lri, lub, lubi, m, n, np1
integer :: i1, iq, j
!
! Subroutine for parametric computation of the upper bounds.
!
integer, intent(in) :: f(m), bb(m,n), q(m), b(np1)
integer, intent(inout) :: ub
integer, intent(in) :: vb
integer :: r, s
integer, intent(in) :: lx(n), lxi(n)
!
iflag = 0
if ( b(lj) .ne. 0 ) go to 60
i1 = i - 1
if ( i1 .lt. li ) go to 20
iq = 0
do r=li,i1
  iq = iq + q(r)
end do
if ( iq .gt. lr ) return
20 r = ii
s = f(r)
30 if ( s .ne. (-1) ) go to 40
r = r - 1
s = f(r)
go to 30
40 if ( lx(s) .eq. 0 ) return
if ( s .eq. lj ) go to 50
s = bb(r,s)
go to 30
50 ub = lub - vb
iflag = 1
return
60 i1 = i - 1
if ( i1 .lt. 1 ) go to 80
iq = 0
do r=1,i1
  iq = iq + q(r)
end do
if ( iq .gt. lri ) return
80 do 90 j = 1,n
  if ( b(j) .eq. 1 ) go to 90
  if ( lxi(j) .eq. 0 ) return
90 continue
ub = lubi - vb
iflag = 1
return
end subroutine parc

subroutine sknp (ns,qs,kub,vs,n,np1,n5,ps,ws,xs,iwk)
implicit none
integer, intent(in) :: kub, n, n5, np1, ns
integer :: i1, i2, i3, i4, i5
!
! Subroutine to solve the 0-1 single knapsack problem
!
! MAXIMIZE    vs = ps(1)*xs(1) + ... + ps(ns)*xs(ns)
! SUBJECT TO       ws(1)*xs(1) + ... + ws(ns)*xs(ns) .LE. qs
!                  xs(J) = 0 OR 1   FOR  J=1,...,ns
!                  vs .GT. kub
!
! This subroutine is a modified version of subroutine kp01
! which appeared in  computing 21, 81-86(1978).
!
integer, intent(inout) :: qs, vs
integer, intent(inout) :: ps(np1), ws(np1), xs(n), iwk(n5)
!
i1 = 1
i2 = i1 + n
i3 = i2 + n
i4 = i3 + n
i5 = i4 + n
call sknp1 (ns,qs,kub,vs,n,np1,ps,ws,xs,iwk(i1),iwk(i2), &
&iwk(i3),iwk(i4),iwk(i5))
return
end subroutine sknp

subroutine sknp1 (ns,qs,kub,vs,n,np1,ps,ws,xs,d,min, &
&pbar,wbar,zbar)
implicit none
integer, intent(in) :: kub, n, np1, ns
integer :: ii, ii1, in, ip, j, j1, jj, kk, l, lim, lim1, ll, lold, &
&mfirst, mink, ms, n1, nn
real :: a, b, c
!
! Subroutine to solve the 0-1 single knapsack problem
!
! MAXIMIZE    vs = ps(1)*xs(1) + ... + ps(ns)*xs(ns)
! SUBJECT TO       ws(1)*xs(1) + ... + ws(ns)*xs(ns) .LE. qs
!                  xs(j) = 0 OR 1   FOR  j=1,...,ns
!                  vs .GT. kub
!
! This subroutine is a modified version of subroutine kp01
! which appeared in  computing 21, 81-86(1978).
!
integer, intent(inout) :: qs
integer, intent(out) :: vs
integer :: diff, pr, r, t
integer, intent(inout) :: ps(np1), ws(np1), xs(n)
integer, intent(inout) :: d(n), min(n), pbar(n), wbar(n), zbar(n)
!
vs = kub
ip = 0
ms = qs
do l=1,ns
  ll = l
  if ( ws(l) .gt. ms ) go to 20
  ip = ip + ps(l)
  ms = ms - ws(l)
end do
20 ll = ll - 1
if ( ms .eq. 0 ) go to 50
ps(ns+1) = 0
ws(ns+1) = qs + 1
lim = ip + (ms*ps(ll+2))/ws(ll+2)
a = ip + ps(ll+1)
b = (ws(ll+1) - ms)*ps(ll)
c = ws(ll)
lim1 = a - b/c
if ( lim1 .gt. lim ) lim = lim1
if ( lim .le. vs ) return
mink = qs + 1
min(ns) = mink
do j=2,ns
  kk = ns + 2 - j
  if ( ws(kk) .lt. mink ) mink = ws(kk)
  min(kk-1) = mink
end do
do j=1,ns
  d(j) = 0
end do
pr = 0
lold = ns
ii = 1
go to 170
50 if ( vs .ge. ip ) return
vs = ip
do j=1,ll
  xs(j) = 1
end do
nn = ll + 1
do j=nn,ns
  xs(j) = 0
end do
qs = 0
return
80 if ( ws(ii) .le. qs ) go to 90
ii1 = ii + 1
if ( vs .ge. (qs*ps(ii1))/ws(ii1) + pr ) go to 280
ii = ii1
go to 80
90 ip = pbar(ii)
ms = qs - wbar(ii)
in = zbar(ii)
ll = ns
if ( in .gt. ns) go to 110
do l=in,ns
  ll = l
  if ( ws(l) .gt. ms ) go to 160
  ip = ip + ps(l)
  ms = ms - ws(l)
end do
110 if ( vs .ge. ip + pr ) go to 280
vs = ip + pr
mfirst = ms
nn = ii - 1
do j=1,nn
  xs(j) = d(j)
end do
do j=ii,ll
  xs(j) = 1
end do
if ( ll .eq. ns ) go to 150
nn = ll + 1
do j=nn,ns
  xs(j) = 0
end do
150 if ( vs .ne. lim ) go to 280
qs = mfirst
return
160 l = ll
ll = ll - 1
if ( ms .eq. 0 ) go to 110
if ( vs .ge. pr + ip + (ms*ps(l))/ws(l) ) go to 280
170 wbar(ii) = qs - ms
pbar(ii) = ip
zbar(ii) = ll + 1
d(ii) = 1
nn = ll - 1
if ( nn .lt. ii ) go to 190
do j=ii,nn
  wbar(j+1) = wbar(j) - ws(j)
  pbar(j+1) = pbar(j) - ps(j)
  zbar(j+1) = ll + 1
  d(j+1) = 1
end do
190 j1 = ll + 1
do j=j1,lold
  wbar(j) = 0
  pbar(j) = 0
  zbar(j) = j
end do
lold = ll
qs = ms
pr = pr + ip
if ( ll - (ns - 2) ) 240, 220, 210
210 ii = ns
go to 250
220 if ( qs .lt. ws(ns) ) go to 230
qs = qs - ws(ns)
pr = pr + ps(ns)
d(ns) = 1
230 ii = ns - 1
go to 250
240 ii = ll + 2
if ( qs .ge. min(ii-1) ) go to 80
250 if ( vs .ge. pr ) go to 270
vs = pr
do j=1,ns
  xs(j) = d(j)
end do
mfirst = qs
if ( vs .eq. lim ) return
270 if ( d(ns) .eq. 0 ) go to 280
d(ns) = 0
qs = qs + ws(ns)
pr = pr - ps(ns)
280 nn = ii - 1
if ( nn .eq. 0 ) go to 300
do j=1,nn
  kk = ii - j
  if ( d(kk) .eq. 1 ) go to 310
end do
300 qs = mfirst
return
310 r = qs
qs = qs + ws(kk)
pr = pr - ps(kk)
d(kk) = 0
if ( r .lt. min(kk) ) go to 320
ii = kk + 1
go to 80
320 nn = kk + 1
ii = kk
330 if ( vs .ge. pr + (qs*ps(nn))/ws(nn) ) go to 280
diff = ws(nn) - ws(kk)
if ( diff ) 390, 340, 350
340 nn = nn + 1
go to 330
350 if ( diff .gt. r ) go to 340
if ( vs .ge. pr + ps(nn) ) go to 340
vs = pr + ps(nn)
do j=1,kk
  xs(j) = d(j)
end do
jj = kk + 1
do j=jj,ns
  xs(j) = 0
end do
xs(nn) = 1
mfirst = qs - ws(nn)
if ( vs .ne. lim ) go to 380
qs = mfirst
return
380 r = r - diff
kk = nn
nn = nn + 1
go to 330
390 t = r - diff
if ( t .lt. min(nn) ) go to 340
n1 = nn + 1
if ( vs .ge. pr + ps(nn) + (t*ps(n1))/ws(n1) ) go to 280
qs = qs - ws(nn)
pr = pr + ps(nn)
d(nn) = 1
ii = nn + 1
wbar(nn) = ws(nn)
pbar(nn) = ps(nn)
zbar(nn) = ii
do j=n1,lold
  wbar(j) = 0
  pbar(j) = 0
  zbar(j) = j
end do
lold = nn
go to 80
end subroutine sknp1

subroutine lainv (mo,fun,t,aerr,rerr,y,c,error,num,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: mo
integer, intent(out) :: num
real, intent(in) :: aerr
real, intent(inout) :: c, error
real, intent(in) :: rerr, t
real, intent(inout) :: y
integer :: ier, ierc, num1
real :: a
real :: exparg
!-----------------------------------------------------------------------
!
!             Computation of the inverse Laplace transform
!              of a function which is not too oscillatory
!
!                          ------------------
!
!     mo is an input integer which specifies the search procedure
!     for determination of c.  a two-pass procedure is used when
!     mo = 0 , AND A ONE-PASS PROCEDURE IS USED WHEN mo IS NOT ZERO.
!     WHEN ALL SINGULARITIES OF F(Z) ARE EXPECTED TO BE REAL, mo = 0
!     is preferable.
!
!     Fun is a real subroutine defined by the user.  The actual name
!     for fun needs to be declared external in the driver program.
!     Fun has the arguments X, y, A, and B.
!
!     t is a positive value of the independent variable for which
!     the inverse Laplace transform is to be calculated.
!
!     c is the abscissa of convergence.  It may be either given
!     or calculated by lainv.
!
!     y is the calculated value of the inverse Laplace transform.
!
!     aerr is the absolute accuracy requested.
!     rerr is the relative accuracy requested.  The subroutine
!     attempts to satisfy the less stringent of the two requirements.
!     IT IS ASSUMED THAT aerr AND rerr ARE .GE. 0.  IF ONE WANTS
!     accuracy to K significant figures, then rerr should be
!     set = 10.0**(-k).
!
!     Error is the estimated absolute error of y.
!
!     num is the number of evaluations of fun in lainv.
!
!     ierr may be either an input integer or an output integer.  When
!     ierr is equal to any negative integer at the beginning of lainv,
!     the abscissa of convergence is calculated and the value obtained
!     is assigned to the argument c.  otherwise, c must be input by
!     the user.  After completion of lainv, ierr has one of the
!     following values...
!
!        ierr = 0   THE CALCULATION WAS SUCCESSFUL.
!
!        ierr = 1   THE CALCULATED VALUE OF y MAY NOT BE ACCURATE
!                   due to possible inaccuracy in the calculation
!                   of c.  this value of ierr may occur only when
!                   ierr is initially negative.
!
!        ierr = 2   THE CALCULATION OF y DID NOT CONVERGE, WHILE
!                   the given or calculated value of c may be
!                   considered accurate.
!
!        ierr = 3   THE CALCULATION OF y DID NOT CONVERGE, AND THE
!                   calculated value of c may be inaccurate.  This
!                   value of ierr may occur only when ierr is
!                   initially negative.
!
!        ierr = 4   THE VALUE OF t IS LESS THAN OR EQUAL TO 0.
!                   THE SPECIAL VALUES y = 0.0 AND error = 1.0
!                   are assigned.
!
!        ierr = 5   c WAS NOT FOUND IN THE INTERVAL (-1.0E4,1.0E4).
!                   THE SPECIAL VALUES c = 0.0, y = 0.0, AND
!                   error = 1.0 ARE ASSIGNED.
!                   This value of ierr may occur only when
!                   ierr is initially negative.
!
!        ierr = 6   t IS TOO LARGE FOR THE INVERSE TRANSFORM TO BE
!                   COMPUTED. THE VALUES y = 0.0 AND error = 1.0
!                   are assigned.
!
!-----------------------------------------------------------------------
external fun
!
num = 0
ierc = -1
if (ierr .ge. 0) go to 10
!
!     Calculation of the abscissa of convergence.
!
if (mo .eq. 0) go to 5
   call abcon1 (fun,c,num,ierc)
   go to 10
5 call abcon (fun,c,num,ierc)
10 if (ierc .eq. 2) go to 100
!
!     Check if t is too large
!
a = c + 2.0/t
if (a*t .gt. exparg(0)) go to 110
!
!     Calculation of the inverse Laplace transform.
!
call lainv1 (fun,t,c,rerr,aerr,y,error,num1,ier)
num = num + num1
!
!     Report the status of the results.
!
if (ierc .ge. 0) go to 20
if (ier  .eq. 0) go to 30
if (ier  .eq. 1) go to 50
20 if (ier  .eq. 2) go to 80
if (ier  .eq. 1) go to 60
if (ierc .eq. 1) go to 40
!
30 ierr = 0
return
40 ierr = 1
return
50 ierr = 2
return
60 if (ierc .eq. 1) go to 70
   ierr = 2
   return
70 ierr = 3
return
80 ierr = 4
return
!
100 y = 0.0
error = 1.0
ierr = 5
return
110 y = 0.0
error = 1.0
ierr = 6
return
end subroutine lainv

subroutine abcon (fun, c, num, ierr)
implicit none
integer, intent(inout) :: ierr, num
real, intent(inout) :: c
integer :: num1
real :: eta, x0, xmin
!-----------------------------------------------------------------------
!
!             Computation of the abscissa of convergence
!             of a function which is not too oscillatory
!
!                         -----------------
!
!     Fun is a real subroutine defined by the user.  The actual name
!     for fun needs to be declared external in the driver program.
!     Fun has the arguments X, Y, A, and B.
!
!     c is the calculated value of the abscissa of convergence.
!
!     num is a variable. On output it has for its value the number
!     of evaluations of fun that were performed.
!
!     ierr is an output integer reporting the status of the
!     calculation of c.  ierr is assigned values as follows...
!
!        ierr = 0   THE CALCULATION WAS SUCCESSFUL.
!
!        ierr = 1   THE REQUESTED ACCURACY MAY NOT HAVE BEEN
!                   obtained.  More subintervals may be required
!                   in the numerical quadratures in subroutines
!                   acond AND xcond.
!
!        ierr = 2   c COULD NOT BE CALCULATED WITH SUFFICIENT
!                   accuracy, or an interval containing c could
!                   NOT BE FOUND. THE SPECIAL VALUE c = 0.0 IS
!                   assigned.
!
!-----------------------------------------------------------------------
logical :: find
external fun, acond, xcond
!
eta = 0.01
xmin = -1.00358e4
!
!     Calculation of the location of the singularity on the real
!     axis which is farthest to the right. Set this value to x0.
!
call srch(fun, xcond, xmin, eta, x0, num, ierr)
c = x0
if (ierr .eq. 2) go to 20
if (ierr .eq. 3) go to 10
!
!     Check if x0 is on the right or left of the abscissa of
!     convergence. If it is on the right then we are done.
!
call acond(fun, x0, find, num1, ierr)
num = num + num1
if (find) go to 20
!
!     Search to the right of x0 to find the abscissa of
!     convergence.
!
10 call srch(fun, acond, x0, eta, c, num1, ierr)
num = num + num1
if (ierr .eq. 3) c = 0.0
!
!     Termination
!
20 ierr = min0(ierr,2)
return
end subroutine abcon

subroutine srch (fun,cond,xl,eta,x,num,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(inout) :: num
real, intent(in) :: eta
real, intent(inout) :: x
real, intent(in) :: xl
integer :: i, ier, num1
real :: dx, tol, x1, x2, xbar, xm
!-----------------------------------------------------------------------
!     srch computes an upper bound for the smallest number x such
!     that a given condition is satisfied. It is assumed that the
!     condition is satisfied for sufficiently large x.
!-----------------------------------------------------------------------
!     Fun is a real subroutine defined by the user.  The actual name
!     for fun needs to be declared external in the driver program.
!     Fun has the arguments x, Y, A, and B.
!
!     Cond is a real subroutine defined by the user.  The actual name
!     for cond needs to be declared external in the driver program.
!     Cond has the arguments fun, x, cnd, and ier, where cnd is
!     a logical variable.
!
!     xl is the smallest value of x for which a search is made.  It
!     SHOULD LIE IN THE RANGE - 1.0E4 .LE. xl .LT. 1.0E4.  IT IS
!     assumed that the logical variable cnd calculated by cond is
!     .FALSE. WHEN x = xl.
!
!     eta is the relative tolerance to which the result is to be
!     determined. It is a positive real number. When this subroutine
!     is used to calculate C for use in the piessens code lainv1
!     (ALGORITHM 619), IT IS USUALLY SUFFICIENT TO TAKE eta = 0.01.
!
!     x is the calculated result.  It is larger than the exact
!     result by an amount less than eta*x.
!
!     num is a variable. On output it has for its value the number
!     of evaluations of fun that were performed.
!
!     ierr is an output integer reporting the status of the
!     calculation of x.  ierr is assigned values as follows...
!
!          ierr = 0     THE CALCULATION WAS FULLY SUCCESSFUL.
!
!          ierr = 1     x MAY BE IN ERROR DUE TO THE CALCULATION
!                       of cond.
!
!          ierr = 2     cnd IS .FALSE. WHEN x = 1.0E4.  x IS SET = 0.0.
!
!          ierr = 3     cnd IS .TRUE. FOR  x .GE. xl.  x IS SET TO xl.
!
logical :: cnd
external fun, cond
ierr = 0
!
!     Search for an interval (x1, x2) containing x where
!     x1 .GE. 0.01269
!
x1 = amax1(.01269, xl)
call cond(fun,x1,cnd,num,ier)
if (cnd) go to 20
!
   x2 = 10.1269
   do 10 i = 1,4
      if (x2 .le. x1) go to 10
      call cond(fun,x2,cnd,num1,ier)
      num = num + num1
      if (cnd) go to 200
      x1 = x2
10 x2 = 10.0*x2
   go to 300
!
20 if (x1 .eq. xl) go to 400
!
!     Search for an interval (x1, x2) containing x where
!     x2 .LE. 0.01269
!
   x2 = x1
   x1 = -.100358
   do 30 i = 1,6
      x1 = amax1(x1, xl)
      call cond(fun,x1,cnd,num1,ier)
      num = num + num1
      if(.not. cnd) go to 200
      x2 = x1
      if (x1 .eq. xl) go to 400
30 x1 = 10.0*x1
!
!     Search for x in the interval (x1, x2) by bisection
!
200 dx = x2 - x1
      xbar = x1 + dx/2.0
      call cond(fun,xbar,cnd,num1,ierr)
      num = num + num1
      xm = amax1(abs(x1), abs(x2))
      tol = eta
      if (xm .gt. 1.0) tol = eta*xm
      if (dx .le. tol) go to 250
         if(cnd) go to 225
            x1 = xbar
            go to 200
225 x2 = xbar
         go to 200
!
!     Final assembly
!
250 if(cnd) go to 275
         x = x2
         return
275 x = xbar
      return
!
!     Error return when x could not be found in the interval
!     (-1.0E4, 1.OE4).
!
300 x = 0.0
ierr = 2
return
400 x = xl
ierr = 3
return
end subroutine srch

subroutine abcon1 (fun, c, num, ierr)
implicit none
integer, intent(inout) :: ierr, num
real, intent(inout) :: c
integer :: i, num1
real :: dx, eta, tol, x1, x2, xbar, xm
!-----------------------------------------------------------------------
!
!             Computation of the abscissa of convergence
!             of a function which is not too oscillatory
!
!                         -----------------
!
!     Fun is a real subroutine defined by the user. The actual name
!     for fun needs to be declared external in the driver program.
!     Fun has the arguments X, Y, A, and B.
!
!     c is the calculated value of the abscissa of convergence.
!
!     num is a variable. On output it has for its value the number
!     of evaluations of fun that were performed.
!
!     ierr is an output integer reporting the status of the
!     calculation of c.  ierr is assigned values as follows...
!
!        ierr = 0   THE CALCULATION WAS SUCCESSFUL.
!
!        ierr = 1   THE REQUESTED ACCURACY MAY NOT HAVE BEEN
!                   obtained.  More subintervals may be required
!                   in the numerical quadratures in subroutines
!                   acond AND xcond.
!
!        ierr = 2   c COULD NOT BE CALCULATED WITH SUFFICIENT
!                   accuracy, or an interval containing c could
!                   NOT BE FOUND. THE SPECIAL VALUE c = 0.0 IS
!                   assigned.
!
!-----------------------------------------------------------------------
logical :: cmplex, iend, right
external fun, acond, xcond
!
eta = 0.01
cmplex = .false.
!
x1 = .01269
call xcond (fun,x1,right,num,ierr)
if (.not. right) go to 10
call acond (fun,x1,right,num1,ierr)
num = num + num1
if (right) go to 30
cmplex = .true.
!
!     Search for an interval (x1, x2) containing X where
!     x1 .GE. 0.01269
!
10 x2 = 10.1269
   do i = 1,4
      if (cmplex) go to 20
         call xcond (fun,x2,right,num1,ierr)
         num = num + num1
         if (.not. right) go to 21
20 call acond (fun,x2,right,num1,ierr)
      num = num + num1
      if (right) go to 50
      cmplex = .true.
21 x1 = x2
      x2 = 10.0*x2
   end do
   go to 100
!
!     Search for an interval (x1, x2) containing X where
!     x2 .LE. 0.01269
!
30 x2 = x1
   x1 = -.100358
   do i = 1,6
      call xcond (fun,x1,right,num1,ierr)
      num = num + num1
      if (.not. right) go to 50
      call acond (fun,x1,right,num1,ierr)
      num = num + num1
      if (.not. right) go to 45
      x2 = x1
      x1 = 10.0*x1
   end do
   go to 100
!
45 cmplex = .true.
!
!     Search for X in the interval (x1, x2) by bisection
!
50 dx = x2 - x1
      xbar = x1 + dx/2.0
      xm = amax1(abs(x1), abs(x2))
      tol = eta
      if (xm .gt. 1.0) tol = eta*xm
      iend =  dx .le. tol
!
      if (cmplex) go to 60
      call xcond (fun,xbar,right,num1,ierr)
      num = num + num1
      if (right) go to 60
         if (iend) go to 80
         x1 = xbar
         go to 50
!
60 call acond (fun,xbar,right,num1,ierr)
      num = num + num1
      if (right) go to 70
         if (iend) go to 80
         x1 = xbar
         cmplex = .true.
         go to 50
70 x2 = xbar
      if (.not. iend) go to 50
!
!     Standard termination
!
80 c = x2
   return
!
!     Error return when X cannot be found in (-1.E4, 1.E4)
!
100 c = 0.0
ierr = 2
return
end subroutine abcon1

subroutine acond (fun, x, cond, num, ierr)
implicit none
integer, intent(inout) :: ierr, num
real, intent(in) :: x
integer :: ier, ier1, ier2, iwk(100), l, m, n, num1, num2
real :: a, aerr, c, error1, error2, rerr, tol, wk(400), y, z1, z2
real :: acondg
real :: acondf
!-----------------------------------------------------------------------
!
!        This subroutine tests whether or not a given value of x
!        lies to the right of the abscissa of convergence of the
!        complex function defined by fun when no singularities lie
!        on the real axis.
!
!                      ----------------
!
!     Fun is a real subroutine defined by the user.  The actual name
!     for fun needs to be declared external in the driver program.
!     Fun has the arguments x, y, A, and B.
!
!     x IS A REAL NUMBER. THE LOGICAL VARIABLE cond = .TRUE. IF
!     x .GT. c, WHERE c IS THE ABSCISSA OF CONVERGENCE, AND .FALSE.
!     IF x .LT. c.
!
!     num is a variable. On output it has for its value the number
!     of evaluations of fun that were performed.
!
!     ierr is an output integer indicating the status of the
!     calculation. It is assigned values as follows...
!
!        ierr = 0   THE CALCULATION WAS SUCCESSFUL.
!
!        ierr = 1   THE CALCULATION OF COND MAY NOT BE
!                   accurate for all values of x.
!
!-----------------------------------------------------------------------
logical, intent(inout) :: cond
external fun, acondf, acondg
!--------------------------
data l /100/, m /400/
data aerr /1.e-30/, rerr /1.e-4/, tol /1.e-4/
!--------------------------
c = x
!
!     Calculation of the integral of acondf from x to infinity.
!
call qagi1 (acondf,fun,y,c,x,1,aerr,rerr,z1,error1,num1,ier1, &
&l,m,n,iwk,wk)
!
!     Calculation of the integral of acondg from 0 to infinity.
!
a = 0.0
call qagi1 (acondg,fun,y,c,a,1,aerr,rerr,z2,error2,num2,ier2, &
&l,m,n,iwk,wk)
num = num1 + num2
ier = max0(ier1, ier2)
!
!     Determination of cond.
!
cond = .false.
if (abs(z1 - z2) .le. tol*amax1(abs(z1),abs(z2))) cond = .true.
!
!     Set ierr and return
!
ierr = 0
if (ier .gt. 4) ierr = 1
return
end subroutine acond

function acondf (x, y, c, fun)
implicit none
real, intent(in) :: c
real :: x
real, intent(in) :: y
real :: a, b, t
real :: acondf
!-----------------------------------------------------------------------
!        acondf is the function integrated along the x-axis in
!        acond. y is a dummy variable.
!-----------------------------------------------------------------------
external fun
!
call fun (x, 0.0, a, b)
t = 1.0/((x - c) + 1.0)
acondf = a*t*t
return
end function acondf

function acondg (x, y, c, fun)
implicit none
real :: c, x
real, intent(in) :: y
real :: a, b, s, t, u, v
real :: acondg
!-----------------------------------------------------------------------
!        acondg IS THE FUNCTION INTEGRATED ALONG THE LINE x = c
!        in acond. y is a dummy variable.
!-----------------------------------------------------------------------
external fun
!
call fun (c, x, a, b)
call crec (1.0, x, s, t)
u = s*s - t*t
v = 2.0*s*t
acondg = -(a*v + b*u)
return
end function acondg

subroutine xcond (fun, x, cond, num, ierr)
implicit none
integer, intent(inout) :: ierr, num
real :: x
integer :: iwk(100), l, m, n
real :: aerr, c, epsr, error, rerr, t, tol, wk(400), y, y1, z
real :: xcondy
real :: xcondx
!-----------------------------------------------------------------------
!
!        This subroutine tests whether or not a given value of x
!        lies to the right of all singularities of the complex
!        function defined by fun which lie on the real axis.
!
!                         ------------
!
!     Fun is a real subroutine defined by the user.  The actual name
!     for fun needs to be declared external in the driver program.
!     Fun has the arguments x, y, A, and B.
!
!     x IS A REAL NUMBER.  THE LOGICAL VARIABLE cond = .TRUE IF
!     x .GT. c, WHERE c IS THE ABSCISSA OF THE SINGULARITY ON THE
!     REAL AXIS WHICH LIES FARTHEST TO THE RIGHT, AND .FALSE. IF
!     x .LT. c.
!
!     num is a variable. On output it has for its value the number
!     of evaluations of fun that were performed.
!
!     ierr is an output integer indicating the status of the
!     calculation.  It is assigned values as follows...
!
!        ierr = 0   THE CALCULATION WAS SUCCESSFUL.
!
!        ierr = 1   THE CALCULATION OF COND MAY NOT BE
!                   accurate for all values of x.
!
!-----------------------------------------------------------------------
logical, intent(out) :: cond
external fun, xcondx, xcondy
!--------------------------
data l /100/, m /400/
data aerr /1.e-30/, rerr /1.e-4/, tol /1.e-4/
data epsr /1.e-2/
!--------------------------
c = 1.0 - x
y = epsr
cond = .false.
!
!     Numerical integration of the imaginary part of the integrand
!     ALONG THE LINE y = epsr.
!
call qagi1 (xcondy,fun,y,c,x,1,aerr,rerr,z,error,num,ierr, &
&l,m,n,iwk,wk)
if (ierr .ne. 0) go to 100
!
!     Determination of cond.
!
y1 = 0.5*y
t = (xcondx(x,y,c,fun) + 4.0*xcondx(x,y1,c,fun) + &
&xcondx(x,0.0,c,fun))*epsr/6.0
num = num + 3
if (t*z .gt. 0.0) return
if (abs(t + z) .gt. tol*amax1(abs(t), abs(z))) return
   cond = .true.
   return
!
!     Error return
!
100 ierr = 1
return
end subroutine xcond

function xcondx (x,y,c,fun)
implicit none
real, intent(in) :: c
real :: x, y
real :: a, b, s, t, u, v
real :: xcondx
!
!     Real part of the integrand in xcond
!
external fun
!
call fun (x, y, a, b)
call crec (x + c, y, s, t)
u = s*s - t*t
v = 2.0*s*t
xcondx = a*u - b*v
return
end function xcondx

function xcondy (x,y,c,fun)
implicit none
real, intent(in) :: c
real :: x, y
real :: a, b, s, t, u, v
real :: xcondy
!
!     Imaginary part of integrand in xcond
!
external fun
!
call fun (x, y, a, b)
call crec (x + c, y, s, t)
u = s*s - t*t
v = 2.0*s*t
xcondy = a*v + b*u
return
end function xcondy

 subroutine lainv1(fun,t,c,epsre,epsab,result,esterr,num, &
&ier)
implicit none
real, intent(in) :: c, epsab, epsre
real, intent(out) :: esterr, result
real, intent(in) :: t
integer :: max
real :: a, aim, ak, are, arg, b, bb, e, eps, epsr1, f, fim, fre, &
&pid16, r, s, si(32), tol
real :: spmpar
!
! ......................................................................
!
!   1. lainv1
!        inversion of Laplace transform using the Durbin formula
!        in combination with the epsilon algorithm
!
!   2. Purpose
!        the routine calculates an approximation result to the
!        inverse Laplace transform f(t) of fun, for the value
!        of the independent variable equal to t, hopefully
!        satisfying the following claim for accuracy ....
!        abs(f(t)-result).LE.max(epsab,epsre*abs(f(t)))
!
!   3. Calling sequence
!        call lainv1(fun,t,c,epsre,epsab,result,esterr,num,ier)
!
!      Input parameters
!        FUN    - REAL
!                 subroutine defining the Laplace transform as
!                 a complex function.  The calling sequence of
!                 fun is call FUN(a,b,c,D) where
!                 a - REAL
!                     real part of the independent variable
!                     of the Laplace transform (input)
!                 b - REAL
!                     imaginary part of the independent
!                     variable of the Laplace transform (input)
!                 c - REAL
!                     real part of the value of the Laplace
!                     transform (OUTPUT)
!                 D - REAL
!                     imaginary part of the value of the
!                     Laplace transform (OUTPUT)
!                 the actual name for fun needs to be declared
!                 external in the driver program.
!
!        t      - REAL
!                 value of the independent variable for which the
!                 inverse Laplace transform has to be computed.
!                 t should be greater than zero.
!
!        c      - REAL
!                 abscissa of convergence of the Laplace transform
!
!        epsre  - REAL
!                 relative accuracy requested.  It is assumed that
!                 epsre .GE. 0.  IF ONE WANTS ACCURACY TO k SIGNIFICANT
!                 FIGURES, THEN RERR SHOULD BE SET = 10.0**(-k).
!
!        epsab  - REAL
!                 absolute accuracy requested.  It is assumed that
!                 epsab .GE. 0.  THE ROUTINE TRIES TO SATISFY THE
!                 least stringent of both accuracy requirements.
!
!      Output parameters
!        result - real
!                 inverse Laplace transform
!
!        esterr - REAL
!                 estimate of the absolute error abs(f(t)-result)
!
!        num    - INTEGER
!                 number of evaluations of fun
!
!        ier    - INTEGER
!                 parameter giving information on the termination
!                 of the algorithm
!                 ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                         routine
!                 ier = 1 THE COMPUTATIONS ARE TERMINATED BECAUSE
!                         the bound on the number of evaluations
!                         of fun has been achieved.  This bound
!                         is equal to 8*max+5 where  max  is A
!                         number initialized in a data
!                         statement.  One can allow more function
!                         evaluations by increasing the value of
!                         max in the data-statement.
!                 ier = 2 THE VALUE OF t IS LESS THAN OR EQUAL
!                         to zero.
!
!   4. Subroutines or functions needed
!                fun - user provided subroutine
!                cqext - epsilon algorithm
!                spmpar - this function is called by
!                          cqext, and provides machine constants
!                atan, exp, AMAX1, sin, abs,
!                DBLE, cmplx, real - Fortran functions
!
! ......................................................................
!
complex :: rex(52), cres, res3la(3)
integer :: i
integer, intent(out) :: ier
integer :: k, kc, kk, ks, m, nex, nres
integer, intent(out) :: num
!
!   The array si contains values of the sine and cosine functions
!   required in the Durbin formula. si(8) and si(16) are given in
!   the following data statement. The other values are computed.
!
data si(8),si(16)/ 1.0e+00,0.0e+00/
!
!   Max is a bound on the number of terms used in the Durbin
!   formula.
!
data max/500/
! ....................................................
!
!   Eps is a machine dependent constant.  Eps is the
!   SMALLEST NUMBER SUCH THAT 1 + eps .GT. 1.
!
eps = spmpar(1)
! ....................................................
!
!   Calculation of the relative tolerance used.
!
tol = 10.0*eps
epsr1 = amax1(tol,epsre)
!
!   Test on validity of the input parameter t
!
ier = 2
result = 0.0e+00
esterr = 1.0e+00
num = 0
if (t.le.0.0e+00) go to 999
!
!   PID16 is equal to pi/16
!
pid16 = atan(1.0e+00)/4.0e+00
!
!   Computation of the elements of the array si
!
ak = 1.0e+00
do 10 k = 1,7
  si(k) = sin(ak*pid16)
  ak = ak+1.0e+00
  kk = 16-k
  si(kk) = si(k)
10 continue
ier = 0
nres = 0
do k=17,32
  si(k) = -si(k-16)
end do
!
!   Initialization of the summation of the Durbin formula.
!
arg = pid16/t
are = c+2.0e+00/t
aim = 0.0e+00
bb = exp(are*t)/(1.6e+01*t)
call fun (are,aim,fre,fim)
num = 5
r = 5.0e-01*fre
s = 0.0
nex = 0
kc = 8
ks = 0
!
!   Main loop for the summation
!
do 40 i = 1,max
  m = 8
  if (i.eq.1) m = 12
  do k=1,m
    aim = aim+arg
    kc = kc+1
    ks = ks+1
    if (kc.gt.32) kc = 1
    if (ks.gt.32) ks = 1
    call fun(are,aim,fre,fim)
a = fre*si(kc)
b = -fim*si(ks)
r = dble(r) + dble(a) + dble(b)
e = fre*si(ks)
f = fim*si(kc)
s = dble(s) + dble(e) + dble(f)
  end do
  num = num+8
  nex = nex+1
  rex(nex) = cmplx(r, s)
!
!   Extrapolation using the epsilon algorithm
!
  if(nex.ge.3) call cqext(nex,rex,cres,esterr,res3la,nres)
  if(nres.lt.4) go to 40
!
!   Computation of intermediate result and estimate of the
!   absolute error
!
  result = real(cres)
  result = result * bb
  esterr = esterr * bb
  if (esterr.lt.amax1(epsab,epsr1*abs(result)).and.abs(r*bb- &
&result).lt.5.0e-01*abs(result)) go to 999
40 continue
!
!   Set error flag in the case that the number of terms in the
!   summation is equal to max
!
ier = 1
999 return
end subroutine lainv1

subroutine cqext(n,epstab,result,abserr,res3la,nres)
implicit none
real, intent(out) :: abserr
real :: a1, a2, b1, b2, c1, c2, d1, d2, e1abs, epmach, epsinf, &
&err1, err2, err3, error, oflow, res1, res2
real :: spmpar
!
! 1.        cqext
!           epsilon algorithm
!              standard Fortran subroutine
!              complex version
!
! 2.        PURPOSE
!              the routine determines the limit of a given sequence of
!              approximations, by means of the epsilon algorithm
!              of P. wynn.
!              An estimate of the absolute error is also given.
!              The condensed epsilon table is computed. Only those
!              elements needed for the computation of the next diagonal
!              are preserved.
!
! 3.        CALLING SEQUENCE
!              call cqext(n,epstab,result,abserr,res3la,nres)
!
!           Parameters
!              n      - INTEGER
!                       epstab(n) contains the new element in the
!                       first column of the epsilon table.
!
!              epstab - COMPLEX
!                       vector of dimension 52 containing the elements
!                       of the two lower diagonals of the
!                       triangular epsilon table
!                       the elements are numbered starting at the
!                       right-hand corner of the triangle.
!
!              result - complex
!                       resulting approximation to the integral
!
!              abserr - REAL
!                       estimate of the absolute error of the real
!                       part of result computed from result and
!                       the 3 previous results
!
!              res3la - COMPLEX
!                       vector of dimension 3 containing the last 3
!                       results
!
!              nres   - INTEGER
!                       number of calls to the routine
!                       (should be zero at first call)
!
! 4.        SUBROUTINES OR FUNCTIONS NEEDED
!                     - spmpar, cdivid
!                     - Fortran abs, AMAX1, cabs, cmplx,
!                       real, aimag, SNGL
!
!     ..................................................................
!
complex :: delta1, delta2, delta3
complex, intent(inout) :: epstab(52)
complex :: e0, e1, e2, e3, res
complex, intent(out) :: result
complex, intent(inout) :: res3la(3)
complex :: ss
double precision :: r, s, u1, u2, u3, v1, v2, v3, ss1, ss2, w1, w2
integer :: i, ib, ib2, ie, indx, k1, k2, k3, limexp
integer, intent(inout) :: n
integer :: newelm
integer, intent(inout) :: nres
integer :: num
!
!           List of major variables
!           -----------------------
!
!           e0     - THE 4 ELEMENTS ON WHICH THE
!           e1       COMPUTATION OF A NEW ELEMENT IN
!           e2       THE EPSILON TABLE IS BASED
!           e3                 e0
!                        e3    e1    NEW
!                              e2
!           newelm - number of elements to be computed in the new
!                    diagonal
!           ERROR  - ERROR = abs(e1-e0)+abs(e2-e1)+abs(NEW-e2)
!           result - the element in the new diagonal with least value
!                    of error
!
!           Machine dependent constants
!           ---------------------------
!
!           epmach is the largest relative spacing.
!           OFLOW is the largest positive magnitude.
!           limexp is the maximum number of elements the epsilon
!           table can contain. If this number is reached, the upper
!           diagonal of the epsilon table is deleted.
!
!***FIRST EXECUTABLE STATEMENT
oflow = spmpar(3)
epmach = spmpar(1)
nres = nres+1
abserr = oflow
result = epstab(n)
if(n.lt.3) go to 100
limexp = 50
epstab(n+2) = epstab(n)
newelm = (n-1)/2
epstab(n) = cmplx(oflow,0.0)
num = n
k1 = n
do 40 i = 1,newelm
  k2 = k1-1
  k3 = k1-2
  res = epstab(k1+2)
  e0 = epstab(k3)
  e1 = epstab(k2)
  e2 = res
  e1abs = cabs(e1)
  a1 = real(e0)
  a2 = aimag(e0)
  b1 = real(e1)
  b2 = aimag(e1)
  c1 = real(e2)
  c2 = aimag(e2)
  err2 = abs(c1 - b1)
  err3 = abs(b1 - a1)
  if(abs(a1-b1) .gt. epmach*amax1(abs(a1),abs(b1)) .or. &
&abs(a2-b2) .gt. epmach*amax1(abs(a2),abs(b2))) go to 10
  if(abs(b1-c1) .gt. epmach*amax1(abs(b1),abs(c1)) .or. &
&abs(b2-c2) .gt. epmach*amax1(abs(b2),abs(c2))) go to 10
!
!           If e0, e1 and e2 are equal to within machine
!           accuracy, convergence is assumed.
!           result = e2
!           abserr = cabs(e1-e0)+cabs(e2-e1)
!
  result = res
  abserr = err2+err3
!***JUMP OUT OF DO-LOOP
  go to 100
10 e3 = epstab(k1)
  epstab(k1) = e1
  d1 = real(e3)
  d2 = aimag(e3)
  err1 = abs(b1 - d1)
!
!           If two elements are very close to each other, omit
!           a part of the table by adjusting the value of n
!
  delta1 = e1 - e3
  delta2 = e2 - e1
  delta3 = e1 - e0
  if(cabs(delta1) .le. epmach*amax1(e1abs,cabs(e3))) go to 20
  if(cabs(delta2) .le. epmach*amax1(e1abs,cabs(e2))) go to 20
  if(cabs(delta3) .le. epmach*amax1(cabs(e0),e1abs)) go to 20
  r = real(delta1)
  s = aimag(delta1)
  call cdivid(1.d0,0.d0,r,s,u1,v1)
  r = real(delta2)
  s = aimag(delta2)
  call cdivid(1.d0,0.d0,r,s,u2,v2)
  r = real(delta3)
  s = aimag(delta3)
  call cdivid(1.d0,0.d0,r,s,u3,v3)
  ss1 = u1 + u2 - u3
  ss2 = v1 + v2 - v3
  ss = cmplx(sngl(ss1), sngl(ss2))
  epsinf = cabs(ss*e1)
!
!           Test to detect irregular behaviour in the table, and
!           eventually omit a part of the table adjusting the value
!           OF n.
!
  if(epsinf.gt.1.0e-04) go to 30
20 n = i+i-1
!***JUMP OUT OF DO-LOOP
  go to 50
!
!           Compute a new element and eventually adjust
!           the value of result.
!
30 call cdivid(1.d0,0.d0,ss1,ss2,w1,w2)
  res1 = real(e1) + sngl(w1)
  res2 = aimag(e1) + sngl(w2)
  res = cmplx(res1,res2)
  epstab(k1) = res
  k1 = k1-2
  error = err2+abs(c1-real(res))+err3
  if(error.gt.abserr) go to 40
  abserr = error
  result = res
40 continue
!
!           Shift the table.
!
50 if(n.eq.limexp) n = 2*(limexp/2)-1
ib = 1
if((num/2)*2.eq.num) ib = 2
ie = newelm+1
do i=1,ie
  ib2 = ib+2
  epstab(ib) = epstab(ib2)
  ib = ib2
end do
if(num.eq.n) go to 80
indx = num-n+1
do i = 1,n
  epstab(i)= epstab(indx)
  indx = indx+1
end do
80 if(nres.ge.4) go to 90
res3la(nres) = result
abserr = oflow
go to 100
!
!           Compute error estimate
!
90 abserr = abs(real(result-res3la(3)))+abs(real(result-res3la(2))) &
&+abs(real(result-res3la(1)))
res3la(1) = res3la(2)
res3la(2) = res3la(3)
res3la(3) = result
100 abserr = amax1(abserr,5.0e+00*epmach*abs(real(result)))
return
end subroutine cqext

subroutine qagi1(f,phi,y,c,bound,inf,epsabs,epsrel,result,abserr, &
&neval,ier,limit,lenw,last,iwork,work)
implicit none
integer, intent(out) :: ier
integer, intent(in) :: inf
integer, intent(out) :: last
integer, intent(in) :: lenw, limit
integer, intent(out) :: neval
real, intent(out) :: abserr
real, intent(in) :: bound
real :: c
real, intent(in) :: epsabs, epsrel
real, intent(out) :: result
real :: y
integer :: l1, l2, l3
real :: f
!-----------------------------------------------------------------------
!
!                   Integration over infinite intervals
!
!-----------------------------------------------------------------------
!
!        Purpose
!           the routine calculates an approximation  result  to a given
!           INTEGRAL    I = INTEGRAL OF  f  OVER (bound,+INFINITY)
!                    OR I = INTEGRAL OF  f  OVER (-INFINITY,bound)
!                    OR I = INTEGRAL OF  f  OVER (-INFINITY,+INFINITY),
!           hopefully satisfying following claim for accuracy
!           abs(I-result).LE.max(epsabs,epsrel*abs(I)). f HAS THE
!           arguments X and phi where phi is a function.
!
!        Parameters
!         on entry
!            f      - REAL
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X T E R N A L in the driver program.
!                     f has the arguments X and phi.
!
!            PHI    - REAL
!                     function subprogram having a single real argument.
!                     The actual name for phi must be declared external
!                     in the driver program.
!
!            bound  - real
!                     finite bound of integration range
!                     (has no meaning if interval is doubly-infinite)
!
!            y      - REAL
!                     parameter for use in xcond.  Ordinate of
!                     horizontal line along which integration
!                     is performed.
!
!            c       - REAL
!                      parameter for use in acond and xcond.
!
!            inf    - INTEGER
!                     indicating the kind of integration range
!                     involved
!                     inf = 1 CORRESPONDS TO  (bound,+INFINITY),
!                     inf = -1            to  (-infinity,bound),
!                     inf = 2             to (-infinity,+infinity).
!
!            epsabs - REAL
!                     absolute accuracy requested
!
!            epsrel - REAL
!                     relative accuracy requested
!
!         On return
!            result - real
!                     approximation to the integral
!
!            abserr - REAL
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            neval  - INTEGER
!                     number of integrand evaluations
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                   - ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE. THE
!                             estimates for result and error are less
!                             reliable. It is assumed that the requested
!                             accuracy has not been achieved.
!
!                     ier = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more
!                             subdivisions by increasing the value
!                             of limit (and taking the according
!                             dimension adjustments into account).
!                             However, if this yields no improvement
!                             it is advised to analyze the integrand
!                             in order to determine the integration
!                             difficulties. If the position of a local
!                             difficulty can be determined (E.G.
!                             Singularity, discontinuity within the
!                             interval) one will probably gain from
!                             splitting up the interval at this point
!                             and calling the integrator on the
!                             subranges. If possible, an appropriate
!                             special-purpose integrator should be used,
!                             which is designed for handling the type
!                             of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS
!                             detected, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR OCCURS
!                             at some points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             Roundoff error is detected in the
!                             extrapolation table.
!                             It is assumed that the requested tolerance
!                             cannot be achieved, and that the returned
!                             result is the best which can be obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted that
!                             divergence can occur with any other value
!                             of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs
!                             OR epsrel IS NEGATIVE, limit .LT. 1,
!                             OR lenw .LT. 4 * limit.
!                             Result, abserr, neval, last are
!                             set to zero.
!
!         Dimensioning parameters
!            limit - integer
!                    dimensioning parameter for iwork
!                    limit determines the maximum number
!                    of subintervals in the partition of the given
!                    INTEGRATION INTERVAL (A,B), limit.GE.1.
!                    IF limit.LT.1, THE ROUTINE WILL END WITH
!                    ier = 6.
!
!            lenw  - INTEGER
!                    dimensioning parameter for work
!                    lenw must be at least limit*4.
!                    IF lenw.LT.limit*4, THE ROUTINE WILL END
!                    WITH ier = 6.
!
!            last  - integer
!                    on return, last equals the number of
!                    subintervals produced in the subdivision
!                    process, which determines the number of significant
!                    elements actually in the work arrays.
!
!         Work arrays
!            iwork - INTEGER
!                    vector of dimension at least limit, the first
!                    K elements of which contain pointers
!                    to the error estimates over the subintervals,
!                    such that work(limit*3+iwork(1)),... ,
!                    work(limit*3+iwork(K)) form a decreasing
!                    SEQUENCE, WITH K = last IF last.LE.(limit/2+2), AND
!                    K = limit+1-last OTHERWISE
!
!            work  - real
!                    vector of dimension at least lenw
!                    on return
!                    work(1), ..., work(last) contain the left
!                     END POINTS OF THE SUBINTERVALS IN THE
!                     partition of (A,B),
!                    work(limit+1), ..., work(limit+last) contain
!                     the right end points,
!                    work(limit*2+1), ..., work(limit*2+last)
!                     contain the integral approximations over
!                     the subintervals,
!                    work(limit*3+1), ..., work(limit*3+last)
!                     contain the error estimates.
!
!        Subroutines or functions needed
!              - qagie1
!              - qk15i1
!              - qpsrt
!              - qelg
!              - f (user provided function)
!              - phi (user provided function)
!              - spmpar
!
!-----------------------------------------------------------------------
real, intent(inout) :: work(lenw)
integer, intent(inout) :: iwork(limit)
external f, phi
!
!         Check validity of limit and lenw.
!
ier = 6
neval = 0
last = 0
result = 0.0
abserr = 0.0
if (limit .lt. 1 .or. lenw .lt. limit*4) return
!
!         Prepare call for qagie1.
!
l1 = limit + 1
l2 = limit + l1
l3 = limit + l2
!
call qagie1(f,phi,y,c,bound,inf,epsabs,epsrel,limit,result,abserr, &
&neval,ier,work(1),work(l1),work(l2),work(l3),iwork,last)
return
end subroutine qagi1

subroutine qagie1(f,phi,y,c,bound,inf,epsabs,epsrel,limit,result, &
&abserr,neval,ier,alist,blist,rlist,elist,iord,last)
implicit none
integer, intent(out) :: ier
integer, intent(in) :: inf
integer, intent(inout) :: iord
integer, intent(out) :: last
integer, intent(in) :: limit
integer, intent(out) :: neval
real, intent(out) :: abserr
real, intent(inout) :: alist(limit), blist(limit)
real, intent(in) :: bound
real :: c
real, intent(inout) :: elist(limit)
real, intent(in) :: epsabs, epsrel
real, intent(out) :: result
real, intent(inout) :: rlist(limit)
real :: y
integer :: id, ierro, iroff1, iroff2, iroff3, jupbnd, k, ksgn, &
&ktmin, maxerr, nres, nrmax, numrl2
real :: a1, a2, abseps, area, area1, area12, area2, b1, b2, boun, &
&correc, defab1, defab2, defabs, dres, epmach, erlarg, erlast, &
&errbnd, errmax, erro12, error1, error2, errsum, ertest, oflow, &
&rerr, res3la(3), resabs, reseps, rlist2(52), small, t, uflow
real :: spmpar
real :: f
!-----------------------------------------------------------------------
!
!                   Integration over infinite intervals
!
!-----------------------------------------------------------------------
!
!        Purpose
!           the routine calculates an approximation  result  to a given
!           INTEGRAL    I = INTEGRAL OF  f  OVER (bound,+INFINITY)
!                    OR I = INTEGRAL OF  f  OVER (-INFINITY,bound)
!                    OR I = INTEGRAL OF  f  OVER (-INFINITY,+INFINITY),
!           hopefully satisfying following claim for accuracy
!           abs(I-result).LE.max(epsabs,epsrel*abs(I)).
!
!        Parameters
!         on entry
!            f      - REAL
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X T E R N A L in the driver program.
!                     f has the arguments X and phi.
!
!            PHI    - REAL
!                     function subprogram having a single real argument.
!                     The actual name for phi must be declared external
!                     in the driver program.
!
!            bound  - real
!                     finite bound of integration range
!                     (has no meaning if interval is doubly-infinite)
!
!            y      - REAL
!                     parameter for use in xcond.  Ordinate of
!                     horizontal line along which integration
!                     is performed.
!
!            c      - REAL
!                     parameter for use in acond and xcond.
!
!            inf    - INTEGER
!                     indicating the kind of integration range
!                     involved
!                     inf = 1 CORRESPONDS TO  (bound,+INFINITY),
!                     inf = -1            to  (-infinity,bound),
!                     inf = 2             to (-infinity,+infinity).
!
!            epsabs - REAL
!                     absolute accuracy requested
!
!            epsrel - REAL
!                     relative accuracy requested
!
!            limit  - integer
!                     gives an upper bound on the number of
!                     subintervals in the partition of (A,B),
!                     limit.GE.1
!
!         On return
!            result - real
!                     approximation to the integral
!
!            abserr - REAL
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            neval  - INTEGER
!                     number of integrand evaluations
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                   - ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE. THE
!                             estimates for result and error are less
!                             reliable. It is assumed that the requested
!                             accuracy has not been achieved.
!
!                     ier = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more
!                             subdivisions by increasing the value
!                             of limit (and taking the according
!                             dimension adjustments into account).
!                             However, if this yields no improvement
!                             it is advised to analyze the integrand
!                             in order to determine the integration
!                             difficulties. If the position of a local
!                             difficulty can be determined (E.G.
!                             Singularity, discontinuity within the
!                             interval) one will probably gain from
!                             splitting up the interval at this point
!                             and calling the integrator on the
!                             subranges. If possible, an appropriate
!                             special-purpose integrator should be used,
!                             which is designed for handling the type
!                             of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS
!                             detected, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR OCCURS
!                             at some points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             Roundoff error is detected in the
!                             extrapolation table.
!                             It is assumed that the requested tolerance
!                             cannot be achieved, and that the returned
!                             result is the best which can be obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted that
!                             divergence can occur with any other value
!                             of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs
!                             or epsrel is negative.
!                             Result, abserr, neval, last, rlist(1),
!                             elist(1) and iord(1) are set to zero.
!                             alist(1) and blist(1) are set to 0
!                             and 1 respectively.
!
!            alist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the left
!                     END POINTS OF THE SUBINTERVALS IN THE PARTITION
!                     of the transformed integration range (0,1).
!
!            blist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the right
!                     END POINTS OF THE SUBINTERVALS IN THE PARTITION
!                     of the transformed integration range (0,1).
!
!            rlist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the integral
!                     approximations on the subintervals
!
!            elist  - REAL
!                     vector of dimension at least limit,  the first
!                      last  elements of which are the moduli
!                     of the absolute error estimates on the
!                     subintervals
!
!            iord   - INTEGER
!                     vector of dimension limit, the first k
!                     elements of which are pointers to the
!                     error estimates over the subintervals,
!                     such that elist(iord(1)), ..., elist(iord(k))
!                     FORM A DECREASING SEQUENCE, WITH k = last
!                     IF last.LE.(limit/2+2), AND k = limit+1-last
!                     otherwise
!
!            last   - INTEGER
!                     number of subintervals actually produced
!                     in the subdivision process
!
!        Subroutines or functions needed
!              - qk15i1
!              - qpsrt
!              - qelg
!              - f (user-provided function)
!              - phi (user-provided function)
!              - spmpar
!
!-----------------------------------------------------------------------
logical :: extrap, noext
!
dimension iord(limit)
!
external f, phi
!
!            The dimension of RLIST2 is determined by the value of
!            LIMEXP in subroutine qelg.
!
!
!            List of major variables
!            -----------------------
!
!           alist     - LIST OF LEFT END POINTS OF ALL SUBINTERVALS
!                       considered up to now
!           blist     - LIST OF RIGHT END POINTS OF ALL SUBINTERVALS
!                       considered up to now
!           rlist(I)  - approximation to the integral over
!                       (alist(I),blist(I))
!           RLIST2    - ARRAY OF DIMENSION AT LEAST (LIMEXP+2),
!                       containing the part of the epsilon table
!                       wich is still needed for further computations
!           elist(I)  - error estimate applying to rlist(I)
!           MAXERR    - POINTER TO THE INTERVAL WITH LARGEST ERROR
!                       estimate
!           ERRMAX    - elist(MAXERR)
!           ERLAST    - ERROR ON THE INTERVAL CURRENTLY SUBDIVIDED
!                       (before that subdivision has taken place)
!           area      - SUM OF THE INTEGRALS OVER THE SUBINTERVALS
!           ERRSUM    - SUM OF THE ERRORS OVER THE SUBINTERVALS
!           ERRBND    - REQUESTED ACCURACY max(epsabs,epsrel*
!                       abs(result))
!           *****1    - VARIABLE FOR THE LEFT SUBINTERVAL
!           *****2    - VARIABLE FOR THE RIGHT SUBINTERVAL
!           last      - INDEX FOR SUBDIVISION
!           NRES      - NUMBER OF CALLS TO THE EXTRAPOLATION ROUTINE
!           NUMRL2    - NUMBER OF ELEMENTS CURRENTLY IN RLIST2. IF AN
!                       appropriate approximation to the compounded
!                       integral has been obtained, it is put in
!                       RLIST2(NUMRL2) after NUMRL2 has been increased
!                       by one.
!           SMALL     - LENGTH OF THE SMALLEST INTERVAL CONSIDERED UP
!                       to now, multiplied by 1.5
!           ERLARG    - SUM OF THE ERRORS OVER THE INTERVALS LARGER
!                       than the smallest interval considered up to now
!           extrap    - LOGICAL VARIABLE DENOTING THAT THE ROUTINE
!                       is attempting to perform extrapolation. I.E.
!                       Before subdividing the smallest interval we
!                       try to decrease the value of ERLARG.
!           noext     - LOGICAL VARIABLE DENOTING THAT EXTRAPOLATION
!                       is no longer allowed (TRUE-VALUE)
!
!            Machine dependent constants
!            ---------------------------
!
!           EPMACH is the largest relative spacing.
!           UFLOW is the smallest positive magnitude.
!           OFLOW is the largest positive magnitude.
!
epmach = spmpar(1)
uflow = spmpar(2)
oflow = spmpar(3)
!
!           Test on validity of parameters
!           -----------------------------
!
neval = 0
last = 0
result = 0.0
abserr = 0.0
alist(1) = 0.0
blist(1) = 1.0
rlist(1) = 0.0
elist(1) = 0.0
iord(1) = 0
ier = 6
if (epsabs .lt. 0.0 .or. epsrel .lt. 0.0) go to 999
ier = 0
rerr = amax1(epsrel, 50.0*epmach, 0.5e-14)
!
!           First approximation to the integral
!           -----------------------------------
!
!           Determine the interval to be mapped onto (0,1).
!           IF inf = 2 THE INTEGRAL IS COMPUTED AS I = I1+I2, WHERE
!           I1 = INTEGRAL OF f OVER (-INFINITY,0),
!           I2 = INTEGRAL OF f OVER (0,+INFINITY).
!
boun = bound
if (inf .eq. 2) boun = 0.0
call qk15i1 (f, phi, y, c, boun, inf, 0.0, 1.0, result, abserr, &
&defabs, resabs, epmach, uflow)
!
!           Test on accuracy
!
last = 1
rlist(1) = result
elist(1) = abserr
iord(1) = 1
dres = abs(result)
errbnd = amax1(epsabs,rerr*dres)
if (abserr .le. 100.0*epmach*defabs .and. abserr .gt. errbnd) &
&ier = 2
if (limit .eq. 1) ier = 1
if (ier .ne. 0 .or. (abserr .le. errbnd .and. abserr .ne. resabs) &
&.or. abserr .eq. 0.0) go to 130
!
!           Initialization
!           --------------
!
rlist2(1) = result
errmax = abserr
maxerr = 1
area = result
errsum = abserr
abserr = oflow
correc = 0.0
nrmax = 1
nres = 0
ktmin = 0
numrl2 = 2
extrap = .false.
noext = .false.
ierro = 0
iroff1 = 0
iroff2 = 0
iroff3 = 0
ksgn = -1
if (dres .ge. (1.0 - 50.0*epmach)*defabs) ksgn = 1
t = 1.0 + 100.0*epmach
!
!           Main do-loop
!           ------------
!
do 90 last = 2,limit
!
!           Bisect the subinterval with NRMAX-TH largest
!           error estimate.
!
  a1 = alist(maxerr)
  b1 = 0.5*(alist(maxerr) + blist(maxerr))
  a2 = b1
  b2 = blist(maxerr)
  erlast = errmax
  call qk15i1 (f, phi, y, c, boun, inf, a1, b1, area1, error1, &
&resabs, defab1, epmach, uflow)
  call qk15i1 (f, phi, y, c, boun, inf, a2, b2, area2, error2, &
&resabs, defab2, epmach, uflow)
!
!           Improve previous approximations to integral
!           and error and test for accuracy.
!
  area12 = area1 + area2
  erro12 = error1 + error2
  errsum = errsum + erro12 - errmax
  area = area + area12 - rlist(maxerr)
  if (defab1 .eq. error1 .or. defab2 .eq. error2) go to 15
  if (abs(rlist(maxerr) - area12) .gt. 0.1e-04*abs(area12) &
&.or. erro12 .lt. 0.99*errmax) go to 10
  if (extrap) iroff2 = iroff2 + 1
  if (.not.extrap) iroff1 = iroff1 + 1
10 if (last .gt. 10 .and. erro12 .gt. errmax) iroff3 = iroff3 + 1
15 rlist(maxerr) = area1
  rlist(last) = area2
  errbnd = amax1(epsabs,rerr*abs(area))
!
!           Test for roundoff error and eventually
!           set error flag.
!
  if (iroff1 + iroff2 .ge. 10 .or. iroff3 .ge. 20) ier = 2
  if (iroff2 .ge. 5) ierro = 3
!
!           Set error flag in the case that the number of
!           subintervals equals limit.
!
  if (last .eq. limit) ier = 1
!
!           Set error flag in the case of bad integrand behaviour
!           at some points of the integration range.
!
  if (amax1(abs(a1),abs(b2)) .le. &
&t*(abs(a2) + 0.1e+04*uflow)) ier = 4
!
!           Append the newly-created intervals to the list.
!
  if (error2 .gt. error1) go to 20
  alist(last) = a2
  blist(maxerr) = b1
  blist(last) = b2
  elist(maxerr) = error1
  elist(last) = error2
  go to 30
20 alist(maxerr) = a2
  alist(last) = a1
  blist(last) = b1
  rlist(maxerr) = area2
  rlist(last) = area1
  elist(maxerr) = error2
  elist(last) = error1
!
!           CALL SUBROUTINE qpsrt TO MAINTAIN THE DESCENDING ORDERING
!           in the list of error estimates and select the
!           subinterval with NRMAX-TH largest error estimate (to be
!           bisected next).
!
30 call qpsrt (limit,last,maxerr,errmax,elist,iord,nrmax)
  if(errsum.le.errbnd) go to 115
  if(ier.ne.0) go to 100
  if(last.eq.2) go to 80
  if(noext) go to 90
  erlarg = erlarg-erlast
  if(abs(b1-a1).gt.small) erlarg = erlarg+erro12
  if(extrap) go to 40
!
!           Test whether the interval to be bisected next is the
!           smallest interval.
!
  if(abs(blist(maxerr)-alist(maxerr)).gt.small) go to 90
  extrap = .true.
  nrmax = 2
40 if(ierro.eq.3.or.erlarg.le.ertest) go to 60
!
!           The smallest interval has the largest error.
!           Before bisecting decrease the sum of the errors
!           over the larger intervals (ERLARG) and perform
!           extrapolation.
!
  id = nrmax
  jupbnd = last
  if(last.gt.(2+limit/2)) jupbnd = limit+3-last
  do 50 k = id,jupbnd
    maxerr = iord(nrmax)
    errmax = elist(maxerr)
    if(abs(blist(maxerr)-alist(maxerr)).gt.small) go to 90
    nrmax = nrmax+1
50 continue
!
!           Perform extrapolation.
!
60 numrl2 = numrl2+1
  rlist2(numrl2) = area
  call qelg (numrl2, rlist2, reseps, abseps, res3la, nres, &
&epmach, oflow)
  ktmin = ktmin+1
  if(ktmin.gt.5.and.abserr.lt.0.1e-02*errsum) ier = 5
  if(abseps.ge.abserr) go to 70
  ktmin = 0
  abserr = abseps
  result = reseps
  correc = erlarg
  ertest = amax1(epsabs,rerr*abs(reseps))
  if(abserr.le.ertest) go to 100
!
!            Prepare bisection of the smallest interval.
!
70 if(numrl2.eq.1) noext = .true.
  if(ier.eq.5) go to 100
  maxerr = iord(1)
  errmax = elist(maxerr)
  nrmax = 1
  extrap = .false.
  small = small*0.5e+00
  erlarg = errsum
  go to 90
80 small = 0.375e+00
  erlarg = errsum
  ertest = errbnd
  rlist2(2) = area
90 continue
!
!           Set final result and error estimate.
!           ------------------------------------
!
100 if (abserr .eq. oflow) go to 115
if (ier + ierro .eq. 0) go to 110
if (ierro .eq. 3) abserr = abserr + correc
if (ier .eq. 0) ier = 3
if (result .ne. 0.0 .and. area .ne. 0.0) go to 105
if (abserr .gt. errsum) go to 115
if (area .eq. 0.0) go to 130
go to 110
105 if (abserr/abs(result) .gt. errsum/abs(area)) go to 115
!
!           Test on divergence
!
110 if (ksgn .eq. -1 .and. amax1(abs(result),abs(area)) .le. &
&defabs*0.1e-01) go to 130
if (0.1e-01 .gt. (result/area) .or. (result/area) .gt. 0.1e+03 &
&.or. errsum .gt. abs(area)) ier = 6
go to 130
!
!           Compute global integral sum.
!
115 result = 0.0
do k = 1,last
  result = result + rlist(k)
end do
abserr = errsum
130 neval = 30*last - 15
if (inf .eq. 2) neval = 2*neval
if (ier .gt. 2) ier = ier - 1
999 return
end subroutine qagie1

subroutine qk15i1 (f, phi, y, c, boun, inf, a, b, result, abserr, &
&resabs, resasc, epmach, uflow)
implicit none
integer, intent(in) :: inf
real, intent(in) :: a
real, intent(inout) :: abserr
real, intent(in) :: b, boun
real :: c
real, intent(in) :: epmach
real, intent(inout) :: resabs, resasc, result
real, intent(in) :: uflow
real :: y
integer :: j
real :: absc, absc1, absc2, centr, dinf, fc, fsum, fval1, fval2, &
&hlgth, resg, resk, reskh, tabsc1, tabsc2, tol
real :: f
!-----------------------------------------------------------------------
!
! 1.        PURPOSE
!              the original (infinite) integration range is mapped
!              onto the interval (0,1) and (a,b) is a part of (0,1).
!              It is the purpose to compute
!              I = INTEGRAL OF TRANSFORMED INTEGRAND OVER (a,b),
!              j = INTEGRAL OF abs(TRANSFORMED INTEGRAND) OVER (a,b).
!
! 2.        PARAMETERS
!            on entry
!              f      - REAL
!                       function subprogram defining the integrand
!                       function f(x). the actual name for f needs
!                       to be declared E X T E R N A L in the
!                       calling program. f has the arguments X and
!                       phi.
!
!              PHI    - REAL
!                       function subprogram having a single real
!                       argument. The actual name for phi must be
!                       dechared external in the driver program.
!
!              boun   - REAL
!                       finite bound of original integration
!                       RANGE (SET TO ZERO IF inf = +2)
!
!              inf    - INTEGER
!                       IF inf = -1, THE ORIGINAL INTERVAL IS
!                                   (-INFINITY,BOUND),
!                       IF inf = +1, THE ORIGINAL INTERVAL IS
!                                   (BOUND,+INFINITY),
!                       IF inf = +2, THE ORIGINAL INTERVAL IS
!                                   (-INFINITY,+INFINITY) and
!                       the integral is computed as the sum of two
!                       integrals, one over (-INFINITY,0)
!                       and one over (0,+INFINITY).
!
!              a      - REAL
!                       lower limit for integration over subrange
!                       of (0,1)
!
!              b      - REAL
!                       upper limit for integration over subrange
!                       of (0,1)
!
!              epmach - REAL
!                       the relative precision of the floating
!                       arithmetic being used.
!
!              uflow  - REAL
!                       the smallest positive magnitude.
!
!            On return
!              result - real
!                       approximation to the integral I
!                       result is computed by applying the 15-point
!                       Kronrod RULE(RESK) obtained by optimal
!                       addition of abscissae to the 7-point Gauss
!                       RULE(RESG).
!
!              abserr - REAL
!                       estimate of the modulus of the absolute error,
!                       which should equal or exceed abs(I-result)
!
!              resabs - REAL
!                       approximation to the integral j
!
!              resasc - REAL
!                       approximation to the integral of
!                       abs((TRANSFORMED INTEGRAND)-I/(b-a))
!                       OVER (a,b)
!
! 3.        SUBROUTINES OR FUNCTIONS NEEDED
!                 - f (user-provided function)
!                 - phi (user-provided function)
!
!-----------------------------------------------------------------------
real :: fv1(7), fv2(7), xgk(8), wgk(8), wg(8)
!
external f, phi
!
!           The abscissae and weights are supplied for the interval
!           (-1,1).  Because of symmetry only the positive abscissae and
!           their corresponding weights are given.
!
!           xgk    - ABSCISSAE OF THE 15-POINT KRONROD RULE
!                    xgk(2), xgk(4), ... abscissae of the 7-point
!                    Gauss rule
!                    xgk(1), xgk(3), ...  abscissae which are optimally
!                    added to the 7-point Gauss rule
!
!           wgk    - WEIGHTS OF THE 15-POINT KRONROD RULE
!
!           wg     - WEIGHTS OF THE 7-POINT GAUSS RULE, CORRESPONDING
!                    to the abscissae xgk(2), xgk(4), ...
!                    wg(1), wg(3), ... are set to zero.
!
data xgk(1),xgk(2),xgk(3),xgk(4),xgk(5),xgk(6),xgk(7), &
&xgk(8)/ &
&0.9914553711208126e+00,     0.9491079123427585e+00, &
&0.8648644233597691e+00,     0.7415311855993944e+00, &
&0.5860872354676911e+00,     0.4058451513773972e+00, &
&0.2077849550078985e+00,     0.0000000000000000e+00/
!
data wgk(1),wgk(2),wgk(3),wgk(4),wgk(5),wgk(6),wgk(7), &
&wgk(8)/ &
&0.2293532201052922e-01,     0.6309209262997855e-01, &
&0.1047900103222502e+00,     0.1406532597155259e+00, &
&0.1690047266392679e+00,     0.1903505780647854e+00, &
&0.2044329400752989e+00,     0.2094821410847278e+00/
!
data wg(1),wg(2),wg(3),wg(4),wg(5),wg(6),wg(7),wg(8)/ &
&0.0000000000000000e+00,     0.1294849661688697e+00, &
&0.0000000000000000e+00,     0.2797053914892767e+00, &
&0.0000000000000000e+00,     0.3818300505051189e+00, &
&0.0000000000000000e+00,     0.4179591836734694e+00/
!
!
!           List of major variables
!           -----------------------
!
!           centr  - mid point of the interval
!           HLGTH  - half-length of the interval
!           absc*  - ABSCISSA
!           TABSC* - transformed abscissa
!           FVAL*  - function VALUE
!           RESG   - result OF THE 7-POINT GAUSS FORMULA
!           RESK   - result OF THE 15-POINT KRONROD FORMULA
!           RESKH  - approximation to the mean value of the transformed
!                    integrand over (a,b), I.E. to I/(b-a)
!
!
dinf = min0(1,inf)
!
centr = 0.5*(a + b)
hlgth = 0.5*(b - a)
tabsc1 = boun + dinf*(1.0 - centr)/centr
fval1 = f(tabsc1,y,c,phi)
if (inf .eq. 2) fval1 = fval1 + f(-tabsc1,y,c,phi)
fc = (fval1/centr)/centr
!
!           Compute the 15-point Kronrod approximation to
!           the integral, and estimate the error.
!
resg = wg(8)*fc
resk = wgk(8)*fc
resabs = abs(resk)
do j = 1,7
  absc = hlgth*xgk(j)
  absc1 = centr - absc
  absc2 = centr + absc
  tabsc1 = boun + dinf*(1.0 - absc1)/absc1
  tabsc2 = boun + dinf*(1.0 - absc2)/absc2
  fval1 = f(tabsc1,y,c,phi)
  fval2 = f(tabsc2,y,c,phi)
  if (inf .eq. 2) fval1 = fval1 + f(-tabsc1,y,c,phi)
  if (inf .eq. 2) fval2 = fval2 + f(-tabsc2,y,c,phi)
  fval1 = (fval1/absc1)/absc1
  fval2 = (fval2/absc2)/absc2
  fv1(j) = fval1
  fv2(j) = fval2
  fsum = fval1 + fval2
  resg = resg + wg(j)*fsum
  resk = resk + wgk(j)*fsum
  resabs = resabs + wgk(j)*(abs(fval1) + abs(fval2))
end do
reskh = resk*0.5
resasc = wgk(8)*abs(fc - reskh)
do j = 1,7
  resasc = resasc + wgk(j)*(abs(fv1(j)-reskh) + &
&abs(fv2(j)-reskh))
end do
result = resk*hlgth
resasc = resasc*hlgth
resabs = resabs*hlgth
abserr = abs((resk - resg)*hlgth)
if (resasc .ne. 0.0 .and. abserr .ne. 0.0) abserr = resasc* &
&amin1(1.0, (0.2e+03*abserr/resasc)**1.5)
tol = 50.0*epmach
if (resabs .gt. uflow/tol) abserr = amax1(abserr, tol*resabs)
return
end subroutine qk15i1

subroutine fft (c,n,isn,ierr)
implicit none
integer, intent(inout) :: ierr
integer :: isn, n
real, intent(inout) :: c(*)
!-----------------------------------------------------------------------
!     The complex array c of dimension n is interpreted by the code
!     as a real array of dimension 2*n. if this association is not
!     permitted by the Fortran being used, then the user may use the
!     SUBROUTINE fft1.
!-----------------------------------------------------------------------
if (iabs(isn) .ne. 1) go to 10
call sfft (c(1),c(2),n,n,n,isn+isn,ierr)
return
10 ierr = 4
return
end subroutine fft

subroutine fft1 (a,b,n,isn,ierr)
implicit none
integer, intent(inout) :: ierr
integer :: isn, n
real, intent(inout) :: a(n), b(n)
!     ------------
if (iabs(isn) .ne. 1) go to 10
call sfft (a,b,n,n,n,isn,ierr)
return
10 ierr = 4
return
end subroutine fft1

subroutine mfft (c,n,ndim,isn,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: isn, ndim
integer :: i, isign, nspan, ntot
real, intent(inout) :: c(*)
integer :: n(ndim)
!-----------------------------------------------------------------------
!     Let ntot denote the product of n(1),...,n(ndim). The complex
!     array c of dimension ntot is interpreted by the routine as
!     a real array of dimension 2*ntot. If this association is not
!     permitted by the Fortran being used, then the user may use
!     the subroutine mfft1.
!-----------------------------------------------------------------------
if (iabs(isn) .ne. 1) go to 40
if (ndim .le. 0) go to 50
ntot = 1
do i = 1,ndim
   ntot = n(i)*ntot
end do
if (ntot .lt. 1) go to 30
!
isign = isn + isn
nspan = 1
do i = 1,ndim
   nspan = n(i)*nspan
   call sfft (c(1),c(2),ntot,n(i),nspan,isign,ierr)
   if (ierr .ne. 0) return
end do
return
!
30 ierr = 1
return
40 ierr = 4
return
50 ierr = 5
return
end subroutine mfft

subroutine mfft1 (a,b,n,ndim,isn,ierr)
implicit none
integer, intent(inout) :: ierr
integer :: isn
integer, intent(in) :: ndim
integer :: i, nspan, ntot
real, intent(inout) :: a(*), b(*)
integer :: n(ndim)
!     ------------
if (iabs(isn) .ne. 1) go to 40
if (ndim .le. 0) go to 50
ntot = 1
do i = 1,ndim
   ntot = n(i)*ntot
end do
if (ntot .lt. 1) go to 30
!
nspan = 1
do i = 1,ndim
   nspan = n(i)*nspan
   call sfft (a,b,ntot,n(i),nspan,isn,ierr)
   if (ierr .ne. 0) return
end do
return
!
30 ierr = 1
return
40 ierr = 4
return
50 ierr = 5
return
end subroutine mfft1

subroutine sfft(a,b,ntot,n,nspan,isn,ierr)
implicit none
integer :: ierr, isn, n, nspan, ntot
real :: a(*), b(*)
integer :: i, ii, inc, j, jc, jf, jj, k, k1, k2, k3, k4, kk, ks, &
&kspan, kspnn, kt, l, m, max, maxf, maxn, maxp, nfac(15), nn, &
&np(209), nt, num
real :: aa, aj, ajm, ajp, ak, akm, akp, at(23), bb, bj, bjm, bjp, &
&bk, bkm, bkp, bt(23), c1, c2, c3, c72, cd, ck(23), rad, radf, s1, &
&s120, s2, s3, s72, sd, sk(23), u, v
!  Multivariate complex Fourier transform, computed in place
!    using mixed-radix fast Fourier transform algorithm.
!  By R. C. Singleton, Stanford Research Institute, oct. 1968
!    modified by A. H. Morris, NSWC/DL, Dahlgren VA
!  arrays A and b originally hold the real and imaginary
!    components of the data, and return the real and
!    imaginary components of the resulting Fourier coefficients.
!  Multivariate data is indexed according to the Fortran
!    array element successor function, without limit
!    on the number of implied multiple subscripts.
!    The subroutine is called once for each variate.
!    The calls for a multivariate transform may be in any order.
!  ntot is the total number of complex data values.
!  n is the dimension of the current variable.
!  nspan/n is the spacing of consecutive data values
!    while indexing the current variable.
!  The sign of isn determines the sign of the complex
!    exponential, and the magnitude of isn is normally one.
!  A TRI-variate transform with a(N1,N2,N3), b(N1,N2,N3)
!    is computed by
!      call sfft(a,b,n1*n2*n3,n1,n1,1,ierr)
!      call sfft(a,b,n1*n2*n3,n2,n1*n2,1,ierr)
!      call sfft(a,b,n1*n2*n3,n3,n1*n2*n3,1,ierr)
!  for a single-variate transform,
!    ntot = n = nspan = (NUMBER OF COMPLEX DATA VALUES), E.G.
!      call sfft(a,b,n,n,n,1,ierr)
!  the data may alternatively be stored in a single complex
!    array a, then the magnitude of isn changed to two to
!    give the correct indexing increment and a(2) used to
!    pass the initial address for the sequence of imaginary
!    values, E.G.
!      call sfft(a,a(2),ntot,n,nspan,2,ierr)
!  arrays NFAC(MAXN),NP(MAXP),at(MAXF),ck(MAXF),BT(MAXF),SK(MAXF)
!    are used for temporary storage.
!    MAXN MUST BE .GE. THE NUMBER OF FACTORS OF n
!    MAXF MUST BE .GE. THE MAXIMUM PRIME FACTOR OF n.
!    MAXP MUST BE .GT. THE NUMBER OF PRIME FACTORS OF n.
!    In addition, MAXN is assumed to be odd.
!    If the square-free portion k of n has two or more prime
!    FACTORS, THEN MAXP MUST BE .GE. k-1.
!  ierr is a variable. ierr is set to 0 if no input errors are
!    detected. Otherwise, ierr is assigned one of the values
!      ierr=1    n IS LESS THAN 1
!      ierr=2    n HAS MORE THAN MAXN FACTORS
!      ierr=3    n HAS A PRIME FACTOR GREATER THAN
!                MAXF or the square-free portion of
!                n is greater than MAXP+1
!  array storage in NFAC for a maximum of 15 factors of n.
!  If n has more than one square-free factor, the product of the
!    SQUARE-FREE FACTORS MUST BE .LE. 210
!  array storage for maximum prime factor of 23
equivalence (i,ii)
!  The following constants should agree with the array dimensions.
maxn=15
maxf=23
maxp=209
!  Set the following constants
!     rad=2.0*pi
!     s72=sin(rad/5.0)
!     c72=cos(rad/5.0)
!     s120=sqrt(0.75)
rad=6.2831853071796
s72=.951056516295154
c72=.309016994374947
s120=.86602540378444
!
ierr=0
if(n-1) 1000,960,5
5 inc=isn
if(isn .ge. 0) go to 10
s72=-s72
s120=-s120
rad=-rad
inc=-inc
10 nt=inc*ntot
ks=inc*nspan
kspan=ks
nn=nt-inc
jc=ks/n
radf=rad*float(jc)*0.5
i=0
jf=0
!  Determine the factors of n
m=0
k=n
max=maxn/2
go to 20
15 if(m .eq. max) go to 1001
m=m+1
nfac(m)=4
k=l
20 l=k/16
if(k .eq. l*16) go to 15
j=3
jj=9
go to 30
25 if(m .eq. max) go to 1001
m=m+1
nfac(m)=j
k=k/jj
30 if(mod(k,jj) .eq. 0) go to 25
j=j+2
jj=j**2
if(j .le. maxf .and. jj .le. k) go to 30
if(k .gt. 4) go to 40
kt=m
nfac(m+1)=k
if(k .ne. 1) m=m+1
go to 80
40 l=k/4
if(k .ne. l*4) go to 50
if(m .eq. max) go to 1001
m=m+1
nfac(m)=2
k=l
kt=m
if(k .eq. 1) go to 85
50 kt=m
if(k-1 .gt. maxp) go to 1002
num=maxn-kt-kt
j=2
60 if(mod(k,j) .ne. 0) go to 70
m=m+1
nfac(m)=j
num=num-1
k=k/j
if(k .eq. 1) go to 80
if(num .le. 0) go to 1001
70 l=(j+1)/2
j=l+l+1
if(j .le. maxf) go to 60
go to 1002
80 if(kt .eq. 0) go to 100
85 j=kt
90 m=m+1
nfac(m)=nfac(j)
j=j-1
if(j .ne. 0) go to 90
!  Compute Fourier transform
100 sd=radf/float(kspan)
cd=2.0*sin(sd)**2
sd=sin(sd+sd)
kk=1
i=i+1
if(nfac(i) .ne. 2) go to 400
!  Transform for factor of 2 (including rotation factor)
kspan=kspan/2
k1=kspan+2
210 k2=kk+kspan
ak=a(k2)
bk=b(k2)
a(k2)=a(kk)-ak
b(k2)=b(kk)-bk
a(kk)=a(kk)+ak
b(kk)=b(kk)+bk
kk=k2+kspan
if(kk .le. nn) go to 210
kk=kk-nn
if(kk .le. jc) go to 210
if(kk .gt. kspan) go to 800
220 c1=1.0-cd
s1=sd
230 k2=kk+kspan
ak=a(kk)-a(k2)
bk=b(kk)-b(k2)
a(kk)=a(kk)+a(k2)
b(kk)=b(kk)+b(k2)
a(k2)=c1*ak-s1*bk
b(k2)=s1*ak+c1*bk
kk=k2+kspan
if(kk .lt. nt) go to 230
k2=kk-nt
c1=-c1
kk=k1-k2
if(kk .gt. k2) go to 230
u=sd*s1+cd*c1
v=sd*c1-cd*s1
ak=c1-u
s1=s1+v
!  The following three statements compensate for truncation error.
!    If rounded arithmetic is used then one may substitute
!     c1=ak
c1=1.5-0.5*(ak*ak+s1*s1)
s1=c1*s1
c1=c1*ak
kk=kk+jc
if(kk .lt. k2) go to 230
k1=k1+inc+inc
kk=(k1-kspan)/2+jc
if(kk .le. jc+jc) go to 220
go to 100
!  Transform for factor of 3 (optional code)
320 k1=kk+kspan
k2=k1+kspan
ak=a(kk)
bk=b(kk)
aj=a(k1)+a(k2)
bj=b(k1)+b(k2)
a(kk)=ak+aj
b(kk)=bk+bj
ak=-0.5*aj+ak
bk=-0.5*bj+bk
aj=(a(k1)-a(k2))*s120
bj=(b(k1)-b(k2))*s120
a(k1)=ak-bj
b(k1)=bk+aj
a(k2)=ak+bj
b(k2)=bk-aj
kk=k2+kspan
if(kk .lt. nn) go to 320
kk=kk-nn
if(kk .le. kspan) go to 320
go to 700
!  Transform for factor of 4
400 if(nfac(i) .ne. 4) go to 600
kspnn=kspan
kspan=kspan/4
410 c1=1.0
s1=0.0
420 k1=kk+kspan
k2=k1+kspan
k3=k2+kspan
akp=a(kk)+a(k2)
akm=a(kk)-a(k2)
ajp=a(k1)+a(k3)
ajm=a(k1)-a(k3)
a(kk)=akp+ajp
ajp=akp-ajp
bkp=b(kk)+b(k2)
bkm=b(kk)-b(k2)
bjp=b(k1)+b(k3)
bjm=b(k1)-b(k3)
b(kk)=bkp+bjp
bjp=bkp-bjp
if(isn .lt. 0) go to 450
akp=akm-bjm
akm=akm+bjm
bkp=bkm+ajm
bkm=bkm-ajm
if(s1 .eq. 0.0) go to 460
430 a(k1)=akp*c1-bkp*s1
b(k1)=akp*s1+bkp*c1
a(k2)=ajp*c2-bjp*s2
b(k2)=ajp*s2+bjp*c2
a(k3)=akm*c3-bkm*s3
b(k3)=akm*s3+bkm*c3
kk=k3+kspan
if(kk .le. nt) go to 420
440 u=sd*s1+cd*c1
v=sd*c1-cd*s1
c2=c1-u
s1=s1+v
!  The following three statements compensate for truncation error.
!    If rounded arithmetic is used then one may substitute
!     c1=c2
c1=1.5-0.5*(c2*c2+s1*s1)
s1=c1*s1
c1=c1*c2
c2=c1*c1-s1*s1
s2=2.0*c1*s1
c3=c2*c1-s2*s1
s3=c2*s1+s2*c1
kk=kk-nt+jc
if(kk .le. kspan) go to 420
kk=kk-kspan+inc
if(kk .le. jc) go to 410
if(kspan .eq. jc) go to 800
go to 100
450 akp=akm+bjm
akm=akm-bjm
bkp=bkm-ajm
bkm=bkm+ajm
if(s1 .ne. 0.0) go to 430
460 a(k1)=akp
b(k1)=bkp
a(k2)=ajp
b(k2)=bjp
a(k3)=akm
b(k3)=bkm
kk=k3+kspan
if(kk .le. nt) go to 420
go to 440
!  Transform for factor of 5 (optional code)
510 c2=c72**2-s72**2
s2=2.0*c72*s72
520 k1=kk+kspan
k2=k1+kspan
k3=k2+kspan
k4=k3+kspan
akp=a(k1)+a(k4)
akm=a(k1)-a(k4)
bkp=b(k1)+b(k4)
bkm=b(k1)-b(k4)
ajp=a(k2)+a(k3)
ajm=a(k2)-a(k3)
bjp=b(k2)+b(k3)
bjm=b(k2)-b(k3)
aa=a(kk)
bb=b(kk)
a(kk)=aa+akp+ajp
b(kk)=bb+bkp+bjp
ak=akp*c72+ajp*c2+aa
bk=bkp*c72+bjp*c2+bb
aj=akm*s72+ajm*s2
bj=bkm*s72+bjm*s2
a(k1)=ak-bj
a(k4)=ak+bj
b(k1)=bk+aj
b(k4)=bk-aj
ak=akp*c2+ajp*c72+aa
bk=bkp*c2+bjp*c72+bb
aj=akm*s2-ajm*s72
bj=bkm*s2-bjm*s72
a(k2)=ak-bj
a(k3)=ak+bj
b(k2)=bk+aj
b(k3)=bk-aj
kk=k4+kspan
if(kk .lt. nn) go to 520
kk=kk-nn
if(kk .le. kspan) go to 520
go to 700
!  Transform for odd factors
600 k=nfac(i)
kspnn=kspan
kspan=kspan/k
if(k .eq. 3) go to 320
if(k .eq. 5) go to 510
if(k .eq. jf) go to 640
jf=k
s1=rad/float(k)
c1=cos(s1)
s1=sin(s1)
ck(jf)=1.0
sk(jf)=0.0
j=1
630 ck(j)=ck(k)*c1+sk(k)*s1
sk(j)=ck(k)*s1-sk(k)*c1
k=k-1
ck(k)=ck(j)
sk(k)=-sk(j)
j=j+1
if(j .lt. k) go to 630
640 k1=kk
k2=kk+kspnn
aa=a(kk)
bb=b(kk)
ak=aa
bk=bb
j=1
k1=k1+kspan
650 k2=k2-kspan
j=j+1
at(j)=a(k1)+a(k2)
ak=at(j)+ak
bt(j)=b(k1)+b(k2)
bk=bt(j)+bk
j=j+1
at(j)=a(k1)-a(k2)
bt(j)=b(k1)-b(k2)
k1=k1+kspan
if(k1 .lt. k2) go to 650
a(kk)=ak
b(kk)=bk
k1=kk
k2=kk+kspnn
j=1
660 k1=k1+kspan
k2=k2-kspan
jj=j
ak=aa
bk=bb
aj=0.0
bj=0.0
k=1
670 k=k+1
ak=at(k)*ck(jj)+ak
bk=bt(k)*ck(jj)+bk
k=k+1
aj=at(k)*sk(jj)+aj
bj=bt(k)*sk(jj)+bj
jj=jj+j
if(jj .gt. jf) jj=jj-jf
if(k .lt. jf) go to 670
k=jf-j
a(k1)=ak-bj
b(k1)=bk+aj
a(k2)=ak+bj
b(k2)=bk-aj
j=j+1
if(j .lt. k) go to 660
kk=kk+kspnn
if(kk .le. nn) go to 640
kk=kk-nn
if(kk .le. kspan) go to 640
!  Multiply by rotation factor (except for factors of 2 and 4)
700 if(i .eq. m) go to 800
kk=jc+1
710 c2=1.0-cd
s1=sd
720 c1=c2
s2=s1
kk=kk+kspan
730 ak=a(kk)
a(kk)=c2*ak-s2*b(kk)
b(kk)=s2*ak+c2*b(kk)
kk=kk+kspnn
if(kk .le. nt) go to 730
ak=s1*s2
s2=s1*c2+c1*s2
c2=c1*c2-ak
kk=kk-nt+kspan
if(kk .le. kspnn) go to 730
u=sd*s1+cd*c1
v=sd*c1-cd*s1
c2=c1-u
s1=s1+v
!  The following three statements compensate for truncation
!    error.  If rounded arithmetic is used then they may
!    be deleted.
c1=1.5-0.5*(c2*c2+s1*s1)
s1=c1*s1
c2=c1*c2
kk=kk-kspnn+jc
if(kk .le. kspan) go to 720
kk=kk-kspan+jc+inc
if(kk .le. jc+jc) go to 710
go to 100
!  Permute the results to normal order---done in two stages
!  permutation for square factors of n
800 np(1)=ks
if(kt .eq. 0) go to 890
k=kt+kt+1
if(m .lt. k) k=k-1
j=1
np(k+1)=jc
810 np(j+1)=np(j)/nfac(j)
np(k)=np(k+1)*nfac(j)
j=j+1
k=k-1
if(j .lt. k) go to 810
k3=np(k+1)
kspan=np(2)
kk=jc+1
k2=kspan+1
j=1
if(n .ne. ntot) go to 850
!  Permutation for single-variate transform (optional code)
820 ak=a(kk)
a(kk)=a(k2)
a(k2)=ak
bk=b(kk)
b(kk)=b(k2)
b(k2)=bk
kk=kk+inc
k2=kspan+k2
if(k2 .lt. ks) go to 820
830 k2=k2-np(j)
j=j+1
k2=np(j+1)+k2
if(k2 .gt. np(j)) go to 830
j=1
840 if(kk .lt. k2) go to 820
kk=kk+inc
k2=kspan+k2
if(k2 .lt. ks) go to 840
if(kk .lt. ks) go to 830
jc=k3
go to 890
!  Permutation for multivariate transform
850 k=kk+jc
860 ak=a(kk)
a(kk)=a(k2)
a(k2)=ak
bk=b(kk)
b(kk)=b(k2)
b(k2)=bk
kk=kk+inc
k2=k2+inc
if(kk .lt. k) go to 860
kk=kk+ks-jc
k2=k2+ks-jc
if(kk .lt. nt) go to 850
k2=k2-nt+kspan
kk=kk-nt+jc
if(k2 .lt. ks) go to 850
870 k2=k2-np(j)
j=j+1
k2=np(j+1)+k2
if(k2 .gt. np(j)) go to 870
j=1
880 if(kk .lt. k2) go to 850
kk=kk+jc
k2=kspan+k2
if(k2 .lt. ks) go to 880
if(kk .lt. ks) go to 870
jc=k3
890 if(2*kt+1 .ge. m) return
kspnn=np(kt+1)
!  Permutation for square-free factors of n
j=m-kt
nfac(j+1)=1
900 nfac(j)=nfac(j)*nfac(j+1)
j=j-1
if(j .ne. kt) go to 900
kt=kt+1
nn=nfac(kt)-1
jj=0
j=0
go to 906
902 jj=jj-k2
k2=kk
k=k+1
kk=nfac(k)
904 jj=kk+jj
if(jj .ge. k2) go to 902
np(j)=jj
906 k2=nfac(kt)
k=kt+1
kk=nfac(k)
j=j+1
if(j .le. nn) go to 904
!  Determine the permutation cycles of length greater than 1
j=0
go to 914
910 k=kk
kk=np(k)
np(k)=-kk
if(kk .ne. j) go to 910
k3=kk
914 j=j+1
kk=np(j)
if(kk .lt. 0) go to 914
if(kk .ne. j) go to 910
np(j)=-j
if(j .ne. nn) go to 914
maxf=inc*maxf
!  Reorder A and b, following the permutation cycles
go to 950
924 j=j-1
if(np(j) .lt. 0) go to 924
jj=jc
926 kspan=jj
if(jj .gt. maxf) kspan=maxf
jj=jj-kspan
k=np(j)
kk=jc*k+ii+jj
k1=kk+kspan
k2=0
928 k2=k2+1
at(k2)=a(k1)
bt(k2)=b(k1)
k1=k1-inc
if(k1 .ne. kk) go to 928
932 k1=kk+kspan
k2=k1-jc*(k+np(k))
k=-np(k)
936 a(k1)=a(k2)
b(k1)=b(k2)
k1=k1-inc
k2=k2-inc
if(k1 .ne. kk) go to 936
kk=k2
if(k .ne. j) go to 932
k1=kk+kspan
k2=0
940 k2=k2+1
a(k1)=at(k2)
b(k1)=bt(k2)
k1=k1-inc
if(k1 .ne. kk) go to 940
if(jj .ne. 0) go to 926
if(j .ne. 1) go to 924
950 j=k3+1
nt=nt-kspnn
ii=nt-inc+1
if(nt .ge. 0) go to 924
960 return
!  Error finish - there is an input error
1000 ierr=1
return
1001 ierr=2
return
1002 ierr=3
return
end subroutine sfft

!     ******************************************************************
!
!     subroutine cosqi(n,wsave)
!
!     ******************************************************************
!
!     Subroutine cosqi initializes the array wsave which is used in
!     both cosqf and cosqb. The prime factorization of n together with
!     a tabulation of the trigonometric functions are computed and
!     stored in WSAVE.
!
!     Input parameter
!
!     n       THE LENGTH OF THE ARRAY TO BE TRANSFORMED.  THE METHOD
!             is most efficient when n is a product of small primes.
!
!     Output parameter
!
!     WSAVE   A WORK ARRAY WHICH MUST BE DIMENSIONED AT LEAST 3*n+15.
!             The same work array can be used for both cosqf and cosqb
!             as long as n remains unchanged. Different WSAVE arrays
!             are required for different values of n. the contents of
!             WSAVE must not be changed between calls of cosqf or cosqb.
!
subroutine cosqi (n,wsave)
implicit none
integer :: n
real, intent(inout) :: wsave(*)
integer :: k
real :: dt, fk, pih
data pih /1.57079632679491/
dt = pih/float(n)
fk = 0.
do k=1,n
   fk = fk+1.
   wsave(k) = cos(fk*dt)
end do
call rffti (n,wsave(n+1))
return
end subroutine cosqi

!     ******************************************************************
!
!     subroutine cosqf(n,x,wsave)
!
!     ******************************************************************
!
!     Subroutine cosqf computes the fast Fourier transform of quarter
!     wave data. That is , cosqf computes the coefficients in a cosine
!     series representation with only odd wave numbers. The transform
!     is defined below at output parameter X
!
!     cosqf is the unnormalized inverse of cosqb since a call of cosqf
!     followed by a call of cosqb will multiply the input sequence X
!     BY 4*n.
!
!     The array wsave which is used by subroutine cosqf must be
!     initialized by calling subroutine cosqi(n,wsave).
!
!
!     Input parameters
!
!     n       THE LENGTH OF THE ARRAY X TO BE TRANSFORMED.  THE METHOD
!             is most efficient when n is a product of small primes.
!
!     X       AN ARRAY WHICH CONTAINS THE SEQUENCE TO BE TRANSFORMED
!
!     wsave   A WORK ARRAY WHICH MUST BE DIMENSIONED AT LEAST 3*n+15
!             in the program that calls cosqf. The wsave array must be
!             initialized by calling subroutine cosqi(n,wsave) and A
!             different wsave array must be used for each different
!             value of n. this initialization does not have to be
!             repeated so long as n remains unchanged thus subsequent
!             transforms can be obtained faster than the first.
!
!     Output parameters
!
!     X       FOR I=1,...,n
!
!                  X(I) = X(1) PLUS THE SUM FROM k=2 TO k=n OF
!
!                     2*X(k)*cos((2*I-1)*(k-1)*pi/(2*n))
!
!                  A call of cosqf followed by a call of
!                  cosqb will multiply the sequence X by 4*n.
!                  Therefore cosqb is the unnormalized inverse
!                  OF cosqf.
!
!     wsave   CONTAINS INITIALIZATION CALCULATIONS WHICH MUST NOT
!             be destroyed between calls of cosqf or cosqb.
!
subroutine cosqf (n,x,wsave)
implicit none
integer :: n
real, intent(inout) :: wsave(*), x(*)
real :: sqrt2, tsqx
data sqrt2 /1.4142135623731/
if (n-2) 102,101,103
101 tsqx = sqrt2*x(2)
x(2) = x(1)-tsqx
x(1) = x(1)+tsqx
102 return
103 call cosqf1 (n,x,wsave,wsave(n+1))
return
end subroutine cosqf

subroutine cosqf1 (n,x,w,xh)
implicit none
integer :: n
real :: w(*)
real, intent(inout) :: x(*), xh(*)
integer :: i, k, kc, modn, np2, ns2
real :: xim1
ns2 = (n+1)/2
np2 = n+2
do k=2,ns2
   kc = np2-k
   xh(k) = x(k)+x(kc)
   xh(kc) = x(k)-x(kc)
end do
modn = mod(n,2)
if (modn .eq. 0) xh(ns2+1) = x(ns2+1)+x(ns2+1)
do k=2,ns2
   kc = np2-k
   x(k) = w(k-1)*xh(kc)+w(kc-1)*xh(k)
   x(kc) = w(k-1)*xh(k)-w(kc-1)*xh(kc)
end do
if (modn .eq. 0) x(ns2+1) = w(ns2)*xh(ns2+1)
call rfftf (n,x,xh)
do i=3,n,2
   xim1 = x(i-1)-x(i)
   x(i) = x(i-1)+x(i)
   x(i-1) = xim1
end do
return
end subroutine cosqf1

!     ******************************************************************
!
!     subroutine cosqb(n,x,wsave)
!
!     ******************************************************************
!
!     Subroutine cosqb computes the fast Fourier transform of quarter
!     wave data. That is , cosqb computes a sequence from its
!     representation in terms of a cosine series with odd wave numbers.
!     The transform is defined below at output parameter x.
!
!     cosqb is the unnormalized inverse of cosqf since a call of cosqb
!     followed by a call of cosqf will multiply the input sequence x
!     BY 4*n.
!
!     The array wsave which is used by subroutine cosqb must be
!     initialized by calling subroutine cosqi(n,WSAVE).
!
!
!     Input parameters
!
!     n       THE LENGTH OF THE ARRAY x TO BE TRANSFORMED.  THE METHOD
!             is most efficient when n is a product of small primes.
!
!     x       AN ARRAY WHICH CONTAINS THE SEQUENCE TO BE TRANSFORMED
!
!     WSAVE   A WORK ARRAY THAT MUST BE DIMENSIONED AT LEAST 3*n+15
!             in the program that calls cosqb. The WSAVE array must be
!             initialized by calling subroutine cosqi(n,WSAVE) and A
!             different WSAVE array must be used for each different
!             value of n. this initialization does not have to be
!             repeated so long as n remains unchanged thus subsequent
!             transforms can be obtained faster than the first.
!
!     Output parameters
!
!     x       FOR i=1,...,n
!
!                  x(i)= THE SUM FROM k=1 TO k=n OF
!
!                    4*x(k)*cos((2*k-1)*(i-1)*pi/(2*n))
!
!                  A call of cosqb followed by a call of
!                  cosqf will multiply the sequence x by 4*n.
!                  Therefore cosqf is the unnormalized inverse
!                  OF cosqb.
!
!     WSAVE   CONTAINS INITIALIZATION CALCULATIONS WHICH MUST NOT
!             be destroyed between calls of cosqb or cosqf.
!
subroutine cosqb (n,x,wsave)
implicit none
integer :: n
real, intent(inout) :: wsave(*), x(*)
real :: tsqrt2, x1
data tsqrt2 /2.82842712474619/
if (n-2) 101,102,103
101 x(1) = 4.*x(1)
return
102 x1 = 4.*(x(1)+x(2))
x(2) = tsqrt2*(x(1)-x(2))
x(1) = x1
return
103 call cosqb1 (n,x,wsave,wsave(n+1))
return
end subroutine cosqb

subroutine cosqb1 (n,x,w,xh)
implicit none
integer :: n
real :: w(*)
real, intent(inout) :: x(*), xh(*)
integer :: i, k, kc, modn, np2, ns2
real :: xim1
ns2 = (n+1)/2
np2 = n+2
do i=3,n,2
   xim1 = x(i-1)+x(i)
   x(i) = x(i)-x(i-1)
   x(i-1) = xim1
end do
x(1) = x(1)+x(1)
modn = mod(n,2)
if (modn .eq. 0) x(n) = x(n)+x(n)
call rfftb (n,x,xh)
do k=2,ns2
   kc = np2-k
   xh(k) = w(k-1)*x(kc)+w(kc-1)*x(k)
   xh(kc) = w(k-1)*x(k)-w(kc-1)*x(kc)
end do
if (modn .eq. 0) x(ns2+1) = w(ns2)*(x(ns2+1)+x(ns2+1))
do k=2,ns2
   kc = np2-k
   x(k) = xh(k)+xh(kc)
   x(kc) = xh(k)-xh(kc)
end do
x(1) = x(1)+x(1)
return
end subroutine cosqb1

!     ******************************************************************
!
!     subroutine sinqf(n,x,wsave)
!
!     ******************************************************************
!
!     Subroutine sinqf computes the fast Fourier transform of quarter
!     wave data. That is , sinqf computes the coefficients in a sine
!     series representation with only odd wave numbers. The transform
!     is defined below at output parameter x.
!
!     sinqb is the unnormalized inverse of sinqf since a call of sinqf
!     followed by a call of sinqb will multiply the input sequence x
!     BY 4*n.
!
!     The array wsave which is used by subroutine sinqf must be
!     initialized by calling subroutine sinqi(n,WSAVE).
!
!
!     Input parameters
!
!     n       THE LENGTH OF THE ARRAY x TO BE TRANSFORMED.  THE METHOD
!             is most efficient when n is a product of small primes.
!
!     x       AN ARRAY WHICH CONTAINS THE SEQUENCE TO BE TRANSFORMED
!
!     WSAVE   A WORK ARRAY WHICH MUST BE DIMENSIONED AT LEAST 3*n+15.
!             In the program that calls sinqf. The WSAVE array must be
!             initialized by calling subroutine sinqi(n,WSAVE) and A
!             different WSAVE array must be used for each different
!             value of n. this initialization does not have to be
!             repeated so long as n remains unchanged thus subsequent
!             transforms can be obtained faster than the first.
!
!     Output parameters
!
!     x       FOR i=1,...,n
!
!                  x(i) = (-1)**(i-1)*x(n)
!
!                     + THE SUM FROM k=1 TO k=n-1 OF
!
!                     2*x(k)*sin((2*i-1)*k*pi/(2*n))
!
!                  A call of sinqf followed by a call of
!                  sinqb will multiply the sequence x by 4*n.
!                  Therefore sinqb is the unnormalized inverse
!                  OF sinqf.
!
!     WSAVE   CONTAINS INITIALIZATION CALCULATIONS WHICH MUST NOT
!             be destroyed between calls of sinqf or sinqb.
!
subroutine sinqf (n,x,wsave)
implicit none
integer :: n
real, intent(inout) :: wsave(*), x(*)
integer :: k, kc, ns2
real :: xhold
if (n .eq. 1) return
ns2 = n/2
do k=1,ns2
   kc = n-k
   xhold = x(k)
   x(k) = x(kc+1)
   x(kc+1) = xhold
end do
call cosqf (n,x,wsave)
do k=2,n,2
   x(k) = -x(k)
end do
return
end subroutine sinqf

!     ******************************************************************
!
!     subroutine sinqb(n,x,wsave)
!
!     ******************************************************************
!
!     Subroutine sinqb computes the fast Fourier transform of quarter
!     wave data. That is , sinqb computes a sequence from its
!     representation in terms of a sine series with odd wave numbers.
!     The transform is defined below at output parameter x.
!
!     sinqf is the unnormalized inverse of sinqb since a call of sinqb
!     followed by a call of sinqf will multiply the input sequence x
!     BY 4*n.
!
!     The array wsave which is used by subroutine sinqb must be
!     initialized by calling subroutine sinqi(n,wsave).
!
!
!     Input parameters
!
!     n       THE LENGTH OF THE ARRAY x TO BE TRANSFORMED.  THE METHOD
!             is most efficient when n is a product of small primes.
!
!     x       AN ARRAY WHICH CONTAINS THE SEQUENCE TO BE TRANSFORMED
!
!     wsave   A WORK ARRAY WHICH MUST BE DIMENSIONED AT LEAST 3*n+15.
!             In the program that calls sinqb. The wsave array must be
!             initialized by calling subroutine sinqi(n,wsave) and A
!             different wsave array must be used for each different
!             value of n. this initialization does not have to be
!             repeated so long as n remains unchanged thus subsequent
!             transforms can be obtained faster than the first.
!
!     Output parameters
!
!     x       FOR I=1,...,n
!
!                  x(I)= THE SUM FROM k=1 TO k=n OF
!
!                    4*x(k)*sin((2k-1)*I*pi/(2*n))
!
!                  A call of sinqb followed by a call of
!                  sinqf will multiply the sequence x by 4*n.
!                  Therefore sinqf is the unnormalized inverse
!                  OF sinqb.
!
!     wsave   CONTAINS INITIALIZATION CALCULATIONS WHICH MUST NOT
!             be destroyed between calls of sinqb or sinqf.
!
subroutine sinqb (n,x,wsave)
implicit none
integer :: n
real, intent(inout) :: wsave(*), x(*)
integer :: k, kc, ns2
real :: xhold
if (n .gt. 1) go to 101
x(1) = 4.*x(1)
return
101 ns2 = n/2
do k=2,n,2
   x(k) = -x(k)
end do
call cosqb (n,x,wsave)
do k=1,ns2
   kc = n-k
   xhold = x(k)
   x(k) = x(kc+1)
   x(kc+1) = xhold
end do
return
end subroutine sinqb

!     ******************************************************************
!
!     subroutine rffti(n,wsave)
!
!       ****************************************************************
!
!     Subroutine rffti initializes the array wsave which is used in
!     both rfftf and rfftb. The prime factorization of n together with
!     a tabulation of the trigonometric functions are computed and
!     stored in wsave.
!
!     Input parameter
!
!     n       THE LENGTH OF THE SEQUENCE TO BE TRANSFORMED.
!
!     Output parameter
!
!     wsave   A WORK ARRAY WHICH MUST BE DIMENSIONED AT LEAST 2*n+15.
!             The same work array can be used for both rfftf and rfftb
!             as long as n remains unchanged. Different wsave arrays
!             are required for different values of n. the contents of
!             wsave must not be changed between calls of rfftf or rfftb.
!
subroutine rffti (n,wsave)
implicit none
integer :: n
real, intent(inout) :: wsave(*)
if (n .eq. 1) return
call rffti1 (n,wsave(n+1),wsave(2*n+1))
return
end subroutine rffti

subroutine rffti1 (n,wa,ifac)
implicit none
integer, intent(in) :: n
integer :: i, ib, ido, ii, ip, ipm, is, j, k1, l1, l2, ld, nf, &
&nfm1, nl, nq, nr, ntry
real :: arg, argh, argld, fi, tpi
real, intent(inout) :: wa(*), ifac(*)
integer :: ntryh(4)
data ntryh(1),ntryh(2),ntryh(3),ntryh(4)/4,2,3,5/
nl = n
nf = 0
j = 0
101 j = j+1
if (j-4) 102,102,103
102 ntry = ntryh(j)
go to 104
103 ntry = ntry+2
104 nq = nl/ntry
nr = nl-ntry*nq
if (nr) 101,105,101
105 nf = nf+1
ifac(nf+2) = ntry
nl = nq
if (ntry .ne. 2) go to 107
if (nf .eq. 1) go to 107
do i=2,nf
   ib = nf-i+2
   ifac(ib+2) = ifac(ib+1)
end do
ifac(3) = 2
107 if (nl .ne. 1) go to 104
ifac(1) = n
ifac(2) = nf
tpi = 6.28318530717959
argh = tpi/float(n)
is = 0
nfm1 = nf-1
l1 = 1
if (nfm1 .eq. 0) return
do k1=1,nfm1
   ip = ifac(k1+2)
   ld = 0
   l2 = l1*ip
   ido = n/l2
   ipm = ip-1
   do j=1,ipm
      ld = ld+l1
      i = is
      argld = float(ld)*argh
      fi = 0.
      do ii=3,ido,2
         i = i+2
         fi = fi+1.
         arg = fi*argld
         wa(i-1) = cos(arg)
         wa(i) = sin(arg)
      end do
      is = is+ido
   end do
   l1 = l2
end do
return
end subroutine rffti1

!     ******************************************************************
!
!     subroutine rfftb(n,r,wsave)
!
!     ******************************************************************
!
!     Subroutine rfftb computes the real perodic sequence from its
!     Fourier coefficients (Fourier synthesis). The transform is defined
!     below at output parameter R.
!
!     Input parameters
!
!     n       THE LENGTH OF THE ARRAY R TO BE TRANSFORMED.  THE METHOD
!             is most efficient when n is a product of small primes.
!             n may change so long as different work arrays are provided
!
!     R       A REAL ARRAY OF LENGTH n WHICH CONTAINS THE SEQUENCE
!             to be transformed
!
!     WSAVE   A WORK ARRAY WHICH MUST BE DIMENSIONED AT LEAST 2*n+15.
!             In the program that calls rfftb. The WSAVE array must be
!             initialized by calling subroutine rffti(n,WSAVE) and A
!             different WSAVE array must be used for each different
!             value of n. this initialization does not have to be
!             repeated so long as n remains unchanged thus subsequent
!             transforms can be obtained faster than the first.
!             The same WSAVE array can be used by rfftf and rfftb.
!
!
!     Output parameters
!
!     R       FOR n EVEN AND FOR i = 1,...,n
!
!                  r(i) = r(1)+(-1)**(i-1)*r(n)
!
!                       PLUS THE SUM FROM K=2 TO K=n/2 OF
!
!                        2.*R(2*K-2)*cos((K-1)*(i-1)*2*pi/n)
!
!                       -2.*R(2*K-1)*sin((K-1)*(i-1)*2*pi/n)
!
!             FOR n ODD AND FOR i = 1,...,n
!
!                  R(i) = R(1) PLUS THE SUM FROM K=2 TO K=(n+1)/2 OF
!
!                       2.*R(2*K-2)*cos((K-1)*(i-1)*2*pi/n)
!
!                      -2.*R(2*K-1)*sin((K-1)*(i-1)*2*pi/n)
!
!      *****  NOTE
!                  this transform is unnormalized since a call of rfftf
!                  followed by a call of rfftb will multiply the input
!                  sequence by n.
!
!     WSAVE   CONTAINS RESULTS WHICH MUST NOT BE DESTROYED BETWEEN
!             calls of rfftb or rfftf.
!
!
subroutine rfftb (n,r,wsave)
implicit none
integer :: n
real, intent(inout) :: r(*), wsave(*)
if (n .eq. 1) return
call rfftb1 (n,r,wsave,wsave(n+1),wsave(2*n+1))
return
end subroutine rfftb

subroutine rfftb1 (n,c,ch,wa,ifac)
implicit none
integer, intent(in) :: n
integer :: i, idl1, ido, ip, iw, ix2, ix3, ix4, k1, l1, l2, na, nf
real, intent(inout) :: c(*), ch(*)
real :: wa(*)
real, intent(in) :: ifac(*)
nf = ifac(2)
na = 0
l1 = 1
iw = 1
do k1=1,nf
   ip = ifac(k1+2)
   l2 = ip*l1
   ido = n/l2
   idl1 = ido*l1
   if (ip .ne. 4) go to 103
   ix2 = iw+ido
   ix3 = ix2+ido
   if (na .ne. 0) go to 101
   call radb4 (ido,l1,c,ch,wa(iw),wa(ix2),wa(ix3))
   go to 102
101 call radb4 (ido,l1,ch,c,wa(iw),wa(ix2),wa(ix3))
102 na = 1-na
   go to 115
103 if (ip .ne. 2) go to 106
   if (na .ne. 0) go to 104
   call radb2 (ido,l1,c,ch,wa(iw))
   go to 105
104 call radb2 (ido,l1,ch,c,wa(iw))
105 na = 1-na
   go to 115
106 if (ip .ne. 3) go to 109
   ix2 = iw+ido
   if (na .ne. 0) go to 107
   call radb3 (ido,l1,c,ch,wa(iw),wa(ix2))
   go to 108
107 call radb3 (ido,l1,ch,c,wa(iw),wa(ix2))
108 na = 1-na
   go to 115
109 if (ip .ne. 5) go to 112
   ix2 = iw+ido
   ix3 = ix2+ido
   ix4 = ix3+ido
   if (na .ne. 0) go to 110
   call radb5 (ido,l1,c,ch,wa(iw),wa(ix2),wa(ix3),wa(ix4))
   go to 111
110 call radb5 (ido,l1,ch,c,wa(iw),wa(ix2),wa(ix3),wa(ix4))
111 na = 1-na
   go to 115
112 if (na .ne. 0) go to 113
   call radbg (ido,ip,l1,idl1,c,c,c,ch,ch,wa(iw))
   go to 114
113 call radbg (ido,ip,l1,idl1,ch,ch,ch,c,c,wa(iw))
114 if (ido .eq. 1) na = 1-na
115 l1 = l2
   iw = iw+(ip-1)*ido
end do
if (na .eq. 0) return
do i=1,n
   c(i) = ch(i)
end do
return
end subroutine rfftb1

subroutine radb2 (ido,l1,cc,ch,wa1)
implicit none
integer, intent(in) :: ido, l1
real :: cc(ido,2,l1)
real, intent(inout) :: ch(ido,l1,*)
real :: wa1(*)
integer :: i, ic, idp2, k
real :: ti2, tr2
do k=1,l1
   ch(1,k,1) = cc(1,1,k)+cc(ido,2,k)
   ch(1,k,2) = cc(1,1,k)-cc(ido,2,k)
end do
if (ido-2) 107,105,102
102 idp2 = ido+2
if((ido-1)/2.lt.l1) go to 108
do k=1,l1
   do i=3,ido,2
      ic = idp2-i
      ch(i-1,k,1) = cc(i-1,1,k)+cc(ic-1,2,k)
      tr2 = cc(i-1,1,k)-cc(ic-1,2,k)
      ch(i,k,1) = cc(i,1,k)-cc(ic,2,k)
      ti2 = cc(i,1,k)+cc(ic,2,k)
      ch(i-1,k,2) = wa1(i-2)*tr2-wa1(i-1)*ti2
      ch(i,k,2) = wa1(i-2)*ti2+wa1(i-1)*tr2
   end do
end do
go to 111
108 do i=3,ido,2
   ic = idp2-i
   do k=1,l1
      ch(i-1,k,1) = cc(i-1,1,k)+cc(ic-1,2,k)
      tr2 = cc(i-1,1,k)-cc(ic-1,2,k)
      ch(i,k,1) = cc(i,1,k)-cc(ic,2,k)
      ti2 = cc(i,1,k)+cc(ic,2,k)
      ch(i-1,k,2) = wa1(i-2)*tr2-wa1(i-1)*ti2
      ch(i,k,2) = wa1(i-2)*ti2+wa1(i-1)*tr2
   end do
end do
111 if (mod(ido,2) .eq. 1) return
105 do k=1,l1
   ch(ido,k,1) = cc(ido,1,k)+cc(ido,1,k)
   ch(ido,k,2) = -(cc(1,2,k)+cc(1,2,k))
end do
107 return
end subroutine radb2

subroutine radb3 (ido,l1,cc,ch,wa1,wa2)
implicit none
integer, intent(in) :: ido, l1
real :: cc(ido,3,l1)
real, intent(inout) :: ch(ido,l1,*)
real :: wa1(*), wa2(*)
integer :: i, ic, idp2, k
real :: ci2, ci3, cr2, cr3, di2, di3, dr2, dr3, taui, taur, ti2, &
&tr2
data taur,taui /-.5,.866025403784439/
do k=1,l1
   tr2 = cc(ido,2,k)+cc(ido,2,k)
   cr2 = cc(1,1,k)+taur*tr2
   ch(1,k,1) = cc(1,1,k)+tr2
   ci3 = taui*(cc(1,3,k)+cc(1,3,k))
   ch(1,k,2) = cr2-ci3
   ch(1,k,3) = cr2+ci3
end do
if (ido .eq. 1) return
idp2 = ido+2
if((ido-1)/2.lt.l1) go to 104
do k=1,l1
   do i=3,ido,2
      ic = idp2-i
      tr2 = cc(i-1,3,k)+cc(ic-1,2,k)
      cr2 = cc(i-1,1,k)+taur*tr2
      ch(i-1,k,1) = cc(i-1,1,k)+tr2
      ti2 = cc(i,3,k)-cc(ic,2,k)
      ci2 = cc(i,1,k)+taur*ti2
      ch(i,k,1) = cc(i,1,k)+ti2
      cr3 = taui*(cc(i-1,3,k)-cc(ic-1,2,k))
      ci3 = taui*(cc(i,3,k)+cc(ic,2,k))
      dr2 = cr2-ci3
      dr3 = cr2+ci3
      di2 = ci2+cr3
      di3 = ci2-cr3
      ch(i-1,k,2) = wa1(i-2)*dr2-wa1(i-1)*di2
      ch(i,k,2) = wa1(i-2)*di2+wa1(i-1)*dr2
      ch(i-1,k,3) = wa2(i-2)*dr3-wa2(i-1)*di3
      ch(i,k,3) = wa2(i-2)*di3+wa2(i-1)*dr3
   end do
end do
return
104 do i=3,ido,2
   ic = idp2-i
   do k=1,l1
      tr2 = cc(i-1,3,k)+cc(ic-1,2,k)
      cr2 = cc(i-1,1,k)+taur*tr2
      ch(i-1,k,1) = cc(i-1,1,k)+tr2
      ti2 = cc(i,3,k)-cc(ic,2,k)
      ci2 = cc(i,1,k)+taur*ti2
      ch(i,k,1) = cc(i,1,k)+ti2
      cr3 = taui*(cc(i-1,3,k)-cc(ic-1,2,k))
      ci3 = taui*(cc(i,3,k)+cc(ic,2,k))
      dr2 = cr2-ci3
      dr3 = cr2+ci3
      di2 = ci2+cr3
      di3 = ci2-cr3
      ch(i-1,k,2) = wa1(i-2)*dr2-wa1(i-1)*di2
      ch(i,k,2) = wa1(i-2)*di2+wa1(i-1)*dr2
      ch(i-1,k,3) = wa2(i-2)*dr3-wa2(i-1)*di3
      ch(i,k,3) = wa2(i-2)*di3+wa2(i-1)*dr3
   end do
end do
return
end subroutine radb3

subroutine radb4 (ido,l1,cc,ch,wa1,wa2,wa3)
implicit none
integer, intent(in) :: ido, l1
real :: cc(ido,4,l1)
real, intent(inout) :: ch(ido,l1,*)
real :: wa1(*), wa2(*), wa3(*)
integer :: i, ic, idp2, k
real :: ci2, ci3, ci4, cr2, cr3, cr4, sqrt2, ti1, ti2, ti3, ti4, &
&tr1, tr2, tr3, tr4
data sqrt2 /1.414213562373095/
do k=1,l1
   tr1 = cc(1,1,k)-cc(ido,4,k)
   tr2 = cc(1,1,k)+cc(ido,4,k)
   tr3 = cc(ido,2,k)+cc(ido,2,k)
   tr4 = cc(1,3,k)+cc(1,3,k)
   ch(1,k,1) = tr2+tr3
   ch(1,k,2) = tr1-tr4
   ch(1,k,3) = tr2-tr3
   ch(1,k,4) = tr1+tr4
end do
if (ido-2) 107,105,102
102 idp2 = ido+2
if((ido-1)/2.lt.l1) go to 108
do k=1,l1
   do i=3,ido,2
      ic = idp2-i
      ti1 = cc(i,1,k)+cc(ic,4,k)
      ti2 = cc(i,1,k)-cc(ic,4,k)
      ti3 = cc(i,3,k)-cc(ic,2,k)
      tr4 = cc(i,3,k)+cc(ic,2,k)
      tr1 = cc(i-1,1,k)-cc(ic-1,4,k)
      tr2 = cc(i-1,1,k)+cc(ic-1,4,k)
      ti4 = cc(i-1,3,k)-cc(ic-1,2,k)
      tr3 = cc(i-1,3,k)+cc(ic-1,2,k)
      ch(i-1,k,1) = tr2+tr3
      cr3 = tr2-tr3
      ch(i,k,1) = ti2+ti3
      ci3 = ti2-ti3
      cr2 = tr1-tr4
      cr4 = tr1+tr4
      ci2 = ti1+ti4
      ci4 = ti1-ti4
      ch(i-1,k,2) = wa1(i-2)*cr2-wa1(i-1)*ci2
      ch(i,k,2) = wa1(i-2)*ci2+wa1(i-1)*cr2
      ch(i-1,k,3) = wa2(i-2)*cr3-wa2(i-1)*ci3
      ch(i,k,3) = wa2(i-2)*ci3+wa2(i-1)*cr3
      ch(i-1,k,4) = wa3(i-2)*cr4-wa3(i-1)*ci4
      ch(i,k,4) = wa3(i-2)*ci4+wa3(i-1)*cr4
   end do
end do
go to 111
108 do i=3,ido,2
   ic = idp2-i
   do k=1,l1
      ti1 = cc(i,1,k)+cc(ic,4,k)
      ti2 = cc(i,1,k)-cc(ic,4,k)
      ti3 = cc(i,3,k)-cc(ic,2,k)
      tr4 = cc(i,3,k)+cc(ic,2,k)
      tr1 = cc(i-1,1,k)-cc(ic-1,4,k)
      tr2 = cc(i-1,1,k)+cc(ic-1,4,k)
      ti4 = cc(i-1,3,k)-cc(ic-1,2,k)
      tr3 = cc(i-1,3,k)+cc(ic-1,2,k)
      ch(i-1,k,1) = tr2+tr3
      cr3 = tr2-tr3
      ch(i,k,1) = ti2+ti3
      ci3 = ti2-ti3
      cr2 = tr1-tr4
      cr4 = tr1+tr4
      ci2 = ti1+ti4
      ci4 = ti1-ti4
      ch(i-1,k,2) = wa1(i-2)*cr2-wa1(i-1)*ci2
      ch(i,k,2) = wa1(i-2)*ci2+wa1(i-1)*cr2
      ch(i-1,k,3) = wa2(i-2)*cr3-wa2(i-1)*ci3
      ch(i,k,3) = wa2(i-2)*ci3+wa2(i-1)*cr3
      ch(i-1,k,4) = wa3(i-2)*cr4-wa3(i-1)*ci4
      ch(i,k,4) = wa3(i-2)*ci4+wa3(i-1)*cr4
   end do
end do
111 if (mod(ido,2) .eq. 1) return
105 do k=1,l1
   ti1 = cc(1,2,k)+cc(1,4,k)
   ti2 = cc(1,4,k)-cc(1,2,k)
   tr1 = cc(ido,1,k)-cc(ido,3,k)
   tr2 = cc(ido,1,k)+cc(ido,3,k)
   ch(ido,k,1) = tr2+tr2
   ch(ido,k,2) = sqrt2*(tr1-ti1)
   ch(ido,k,3) = ti2+ti2
   ch(ido,k,4) = -sqrt2*(tr1+ti1)
end do
107 return
end subroutine radb4

subroutine radb5 (ido,l1,cc,ch,wa1,wa2,wa3,wa4)
implicit none
integer, intent(in) :: ido, l1
real :: cc(ido,5,l1)
real, intent(inout) :: ch(ido,l1,*)
real :: wa1(*), wa2(*), wa3(*), wa4(*)
integer :: i, ic, idp2, k
real :: ci2, ci3, ci4, ci5, cr2, cr3, cr4, cr5, di2, di3, di4, &
&di5, dr2, dr3, dr4, dr5, ti11, ti12, ti2, ti3, ti4, ti5, tr11, &
&tr12, tr2, tr3, tr4, tr5
data tr11,ti11,tr12,ti12 /.309016994374947,.951056516295154, &
&-.809016994374947,.587785252292473/
do k=1,l1
   ti5 = cc(1,3,k)+cc(1,3,k)
   ti4 = cc(1,5,k)+cc(1,5,k)
   tr2 = cc(ido,2,k)+cc(ido,2,k)
   tr3 = cc(ido,4,k)+cc(ido,4,k)
   ch(1,k,1) = cc(1,1,k)+tr2+tr3
   cr2 = cc(1,1,k)+tr11*tr2+tr12*tr3
   cr3 = cc(1,1,k)+tr12*tr2+tr11*tr3
   ci5 = ti11*ti5+ti12*ti4
   ci4 = ti12*ti5-ti11*ti4
   ch(1,k,2) = cr2-ci5
   ch(1,k,3) = cr3-ci4
   ch(1,k,4) = cr3+ci4
   ch(1,k,5) = cr2+ci5
end do
if (ido .eq. 1) return
idp2 = ido+2
if((ido-1)/2.lt.l1) go to 104
do k=1,l1
   do i=3,ido,2
      ic = idp2-i
      ti5 = cc(i,3,k)+cc(ic,2,k)
      ti2 = cc(i,3,k)-cc(ic,2,k)
      ti4 = cc(i,5,k)+cc(ic,4,k)
      ti3 = cc(i,5,k)-cc(ic,4,k)
      tr5 = cc(i-1,3,k)-cc(ic-1,2,k)
      tr2 = cc(i-1,3,k)+cc(ic-1,2,k)
      tr4 = cc(i-1,5,k)-cc(ic-1,4,k)
      tr3 = cc(i-1,5,k)+cc(ic-1,4,k)
      ch(i-1,k,1) = cc(i-1,1,k)+tr2+tr3
      ch(i,k,1) = cc(i,1,k)+ti2+ti3
      cr2 = cc(i-1,1,k)+tr11*tr2+tr12*tr3
      ci2 = cc(i,1,k)+tr11*ti2+tr12*ti3
      cr3 = cc(i-1,1,k)+tr12*tr2+tr11*tr3
      ci3 = cc(i,1,k)+tr12*ti2+tr11*ti3
      cr5 = ti11*tr5+ti12*tr4
      ci5 = ti11*ti5+ti12*ti4
      cr4 = ti12*tr5-ti11*tr4
      ci4 = ti12*ti5-ti11*ti4
      dr3 = cr3-ci4
      dr4 = cr3+ci4
      di3 = ci3+cr4
      di4 = ci3-cr4
      dr5 = cr2+ci5
      dr2 = cr2-ci5
      di5 = ci2-cr5
      di2 = ci2+cr5
      ch(i-1,k,2) = wa1(i-2)*dr2-wa1(i-1)*di2
      ch(i,k,2) = wa1(i-2)*di2+wa1(i-1)*dr2
      ch(i-1,k,3) = wa2(i-2)*dr3-wa2(i-1)*di3
      ch(i,k,3) = wa2(i-2)*di3+wa2(i-1)*dr3
      ch(i-1,k,4) = wa3(i-2)*dr4-wa3(i-1)*di4
      ch(i,k,4) = wa3(i-2)*di4+wa3(i-1)*dr4
      ch(i-1,k,5) = wa4(i-2)*dr5-wa4(i-1)*di5
      ch(i,k,5) = wa4(i-2)*di5+wa4(i-1)*dr5
   end do
end do
return
104 do i=3,ido,2
   ic = idp2-i
   do k=1,l1
      ti5 = cc(i,3,k)+cc(ic,2,k)
      ti2 = cc(i,3,k)-cc(ic,2,k)
      ti4 = cc(i,5,k)+cc(ic,4,k)
      ti3 = cc(i,5,k)-cc(ic,4,k)
      tr5 = cc(i-1,3,k)-cc(ic-1,2,k)
      tr2 = cc(i-1,3,k)+cc(ic-1,2,k)
      tr4 = cc(i-1,5,k)-cc(ic-1,4,k)
      tr3 = cc(i-1,5,k)+cc(ic-1,4,k)
      ch(i-1,k,1) = cc(i-1,1,k)+tr2+tr3
      ch(i,k,1) = cc(i,1,k)+ti2+ti3
      cr2 = cc(i-1,1,k)+tr11*tr2+tr12*tr3
      ci2 = cc(i,1,k)+tr11*ti2+tr12*ti3
      cr3 = cc(i-1,1,k)+tr12*tr2+tr11*tr3
      ci3 = cc(i,1,k)+tr12*ti2+tr11*ti3
      cr5 = ti11*tr5+ti12*tr4
      ci5 = ti11*ti5+ti12*ti4
      cr4 = ti12*tr5-ti11*tr4
      ci4 = ti12*ti5-ti11*ti4
      dr3 = cr3-ci4
      dr4 = cr3+ci4
      di3 = ci3+cr4
      di4 = ci3-cr4
      dr5 = cr2+ci5
      dr2 = cr2-ci5
      di5 = ci2-cr5
      di2 = ci2+cr5
      ch(i-1,k,2) = wa1(i-2)*dr2-wa1(i-1)*di2
      ch(i,k,2) = wa1(i-2)*di2+wa1(i-1)*dr2
      ch(i-1,k,3) = wa2(i-2)*dr3-wa2(i-1)*di3
      ch(i,k,3) = wa2(i-2)*di3+wa2(i-1)*dr3
      ch(i-1,k,4) = wa3(i-2)*dr4-wa3(i-1)*di4
      ch(i,k,4) = wa3(i-2)*di4+wa3(i-1)*dr4
      ch(i-1,k,5) = wa4(i-2)*dr5-wa4(i-1)*di5
      ch(i,k,5) = wa4(i-2)*di5+wa4(i-1)*dr5
   end do
end do
return
end subroutine radb5

subroutine radbg (ido,ip,l1,idl1,cc,c1,c2,ch,ch2,wa)
implicit none
integer, intent(in) :: idl1, ido, ip, l1
real, intent(inout) :: c1(ido,l1,ip), c2(idl1,ip)
real :: cc(ido,ip,l1)
real, intent(inout) :: ch(ido,l1,ip), ch2(idl1,ip)
real :: wa(*)
integer :: i, ic, idij, idp2, ik, ipp2, ipph, is, j, j2, jc, k, l, &
&lc, nbd
real :: ai1, ai2, ar1, ar1h, ar2, ar2h, arg, dc2, dcp, ds2, dsp, &
&tpi
data tpi/6.28318530717959/
arg = tpi/float(ip)
dcp = cos(arg)
dsp = sin(arg)
idp2 = ido+2
nbd = (ido-1)/2
ipp2 = ip+2
ipph = (ip+1)/2
if (ido .lt. l1) go to 103
do k=1,l1
   do i=1,ido
      ch(i,k,1) = cc(i,1,k)
   end do
end do
go to 106
103 do i=1,ido
   do k=1,l1
      ch(i,k,1) = cc(i,1,k)
   end do
end do
106 do j=2,ipph
   jc = ipp2-j
   j2 = j+j
   do k=1,l1
      ch(1,k,j) = cc(ido,j2-2,k)+cc(ido,j2-2,k)
      ch(1,k,jc) = cc(1,j2-1,k)+cc(1,j2-1,k)
   end do
end do
if (ido .eq. 1) go to 116
if (nbd .lt. l1) go to 112
do j=2,ipph
   jc = ipp2-j
   do k=1,l1
      do i=3,ido,2
         ic = idp2-i
         ch(i-1,k,j) = cc(i-1,2*j-1,k)+cc(ic-1,2*j-2,k)
         ch(i-1,k,jc) = cc(i-1,2*j-1,k)-cc(ic-1,2*j-2,k)
         ch(i,k,j) = cc(i,2*j-1,k)-cc(ic,2*j-2,k)
         ch(i,k,jc) = cc(i,2*j-1,k)+cc(ic,2*j-2,k)
      end do
   end do
end do
go to 116
112 do j=2,ipph
   jc = ipp2-j
   do i=3,ido,2
      ic = idp2-i
      do k=1,l1
         ch(i-1,k,j) = cc(i-1,2*j-1,k)+cc(ic-1,2*j-2,k)
         ch(i-1,k,jc) = cc(i-1,2*j-1,k)-cc(ic-1,2*j-2,k)
         ch(i,k,j) = cc(i,2*j-1,k)-cc(ic,2*j-2,k)
         ch(i,k,jc) = cc(i,2*j-1,k)+cc(ic,2*j-2,k)
      end do
   end do
end do
116 ar1 = 1.
ai1 = 0.
do l=2,ipph
   lc = ipp2-l
   ar1h = dcp*ar1-dsp*ai1
   ai1 = dcp*ai1+dsp*ar1
   ar1 = ar1h
   do ik=1,idl1
      c2(ik,l) = ch2(ik,1)+ar1*ch2(ik,2)
      c2(ik,lc) = ai1*ch2(ik,ip)
   end do
   dc2 = ar1
   ds2 = ai1
   ar2 = ar1
   ai2 = ai1
   do j=3,ipph
      jc = ipp2-j
      ar2h = dc2*ar2-ds2*ai2
      ai2 = dc2*ai2+ds2*ar2
      ar2 = ar2h
      do ik=1,idl1
         c2(ik,l) = c2(ik,l)+ar2*ch2(ik,j)
         c2(ik,lc) = c2(ik,lc)+ai2*ch2(ik,jc)
      end do
   end do
end do
do j=2,ipph
   do ik=1,idl1
      ch2(ik,1) = ch2(ik,1)+ch2(ik,j)
   end do
end do
do j=2,ipph
   jc = ipp2-j
   do k=1,l1
      ch(1,k,j) = c1(1,k,j)-c1(1,k,jc)
      ch(1,k,jc) = c1(1,k,j)+c1(1,k,jc)
   end do
end do
if (ido .eq. 1) go to 132
if (nbd .lt. l1) go to 128
do j=2,ipph
   jc = ipp2-j
   do k=1,l1
      do i=3,ido,2
         ch(i-1,k,j) = c1(i-1,k,j)-c1(i,k,jc)
         ch(i-1,k,jc) = c1(i-1,k,j)+c1(i,k,jc)
         ch(i,k,j) = c1(i,k,j)+c1(i-1,k,jc)
         ch(i,k,jc) = c1(i,k,j)-c1(i-1,k,jc)
      end do
   end do
end do
go to 132
128 do j=2,ipph
   jc = ipp2-j
   do i=3,ido,2
      do k=1,l1
         ch(i-1,k,j) = c1(i-1,k,j)-c1(i,k,jc)
         ch(i-1,k,jc) = c1(i-1,k,j)+c1(i,k,jc)
         ch(i,k,j) = c1(i,k,j)+c1(i-1,k,jc)
         ch(i,k,jc) = c1(i,k,j)-c1(i-1,k,jc)
      end do
   end do
end do
132 continue
if (ido .eq. 1) return
do ik=1,idl1
   c2(ik,1) = ch2(ik,1)
end do
do j=2,ip
   do k=1,l1
      c1(1,k,j) = ch(1,k,j)
   end do
end do
if (nbd .gt. l1) go to 139
is = -ido
do j=2,ip
   is = is+ido
   idij = is
   do i=3,ido,2
      idij = idij+2
      do k=1,l1
         c1(i-1,k,j) = wa(idij-1)*ch(i-1,k,j)-wa(idij)*ch(i,k,j)
         c1(i,k,j) = wa(idij-1)*ch(i,k,j)+wa(idij)*ch(i-1,k,j)
      end do
   end do
end do
go to 143
139 is = -ido
do j=2,ip
   is = is+ido
   do k=1,l1
      idij = is
      do i=3,ido,2
         idij = idij+2
         c1(i-1,k,j) = wa(idij-1)*ch(i-1,k,j)-wa(idij)*ch(i,k,j)
         c1(i,k,j) = wa(idij-1)*ch(i,k,j)+wa(idij)*ch(i-1,k,j)
      end do
   end do
end do
143 return
end subroutine radbg

!     ******************************************************************
!
!     subroutine rfftf(n,r,wsave)
!
!     ******************************************************************
!
!     Subroutine rfftf computes the Fourier coefficients of a real
!     perodic sequence (Fourier analysis). The transform is defined
!     below at output parameter R.
!
!     Input parameters
!
!     N       THE LENGTH OF THE ARRAY R TO BE TRANSFORMED.  THE METHOD
!             is most efficient when N is a product of small primes.
!             N may change so long as different work arrays are provided
!
!     R       A REAL ARRAY OF LENGTH N WHICH CONTAINS THE SEQUENCE
!             to be transformed
!
!     WSAVE   A WORK ARRAY WHICH MUST BE DIMENSIONED AT LEAST 2*N+15.
!             In the program that calls rfftf. The WSAVE array must be
!             initialized by calling subroutine rffti(N,WSAVE) and A
!             different WSAVE array must be used for each different
!             value of N. this initialization does not have to be
!             repeated so long as N remains unchanged thus subsequent
!             transforms can be obtained faster than the first.
!             The same WSAVE array can be used by rfftf and rfftb.
!
!
!     Output parameters
!
!     R       R(1) = THE SUM FROM i=1 TO i=N OF R(i)
!
!             IF N IS EVEN SET l =N/2   , IF N IS ODD SET l = (N+1)/2
!
!               THEN FOR k = 2,...,l
!
!                  R(2*k-2) = THE SUM FROM i = 1 TO i = N OF
!
!                       R(i)*cos((k-1)*(i-1)*2*pi/N)
!
!                  R(2*k-1) = THE SUM FROM i = 1 TO i = N OF
!
!                      -R(i)*sin((k-1)*(i-1)*2*pi/N)
!
!             If N is even
!
!                  R(N) = THE SUM FROM i = 1 TO i = N OF
!
!                       (-1)**(i-1)*R(i)
!
!      *****  NOTE
!                  this transform is unnormalized since a call of rfftf
!                  followed by a call of rfftb will multiply the input
!                  sequence by N.
!
!     WSAVE   CONTAINS RESULTS WHICH MUST NOT BE DESTROYED BETWEEN
!             calls of rfftf or rfftb.
!
!
subroutine rfftf (n,r,wsave)
implicit none
integer :: n
real, intent(inout) :: r(*), wsave(*)
if (n .eq. 1) return
call rfftf1 (n,r,wsave,wsave(n+1),wsave(2*n+1))
return
end subroutine rfftf

subroutine rfftf1 (n,c,ch,wa,ifac)
implicit none
integer, intent(in) :: n
integer :: i, idl1, ido, ip, iw, ix2, ix3, ix4, k1, kh, l1, l2, &
&na, nf
real, intent(inout) :: c(*), ch(*)
real :: wa(*)
real, intent(in) :: ifac(*)
nf = ifac(2)
na = 1
l2 = n
iw = n
do k1=1,nf
   kh = nf-k1
   ip = ifac(kh+3)
   l1 = l2/ip
   ido = n/l2
   idl1 = ido*l1
   iw = iw-(ip-1)*ido
   na = 1-na
   if (ip .ne. 4) go to 102
   ix2 = iw+ido
   ix3 = ix2+ido
   if (na .ne. 0) go to 101
   call radf4 (ido,l1,c,ch,wa(iw),wa(ix2),wa(ix3))
   go to 110
101 call radf4 (ido,l1,ch,c,wa(iw),wa(ix2),wa(ix3))
   go to 110
102 if (ip .ne. 2) go to 104
   if (na .ne. 0) go to 103
   call radf2 (ido,l1,c,ch,wa(iw))
   go to 110
103 call radf2 (ido,l1,ch,c,wa(iw))
   go to 110
104 if (ip .ne. 3) go to 106
   ix2 = iw+ido
   if (na .ne. 0) go to 105
   call radf3 (ido,l1,c,ch,wa(iw),wa(ix2))
   go to 110
105 call radf3 (ido,l1,ch,c,wa(iw),wa(ix2))
   go to 110
106 if (ip .ne. 5) go to 108
   ix2 = iw+ido
   ix3 = ix2+ido
   ix4 = ix3+ido
   if (na .ne. 0) go to 107
   call radf5 (ido,l1,c,ch,wa(iw),wa(ix2),wa(ix3),wa(ix4))
   go to 110
107 call radf5 (ido,l1,ch,c,wa(iw),wa(ix2),wa(ix3),wa(ix4))
   go to 110
108 if (ido .eq. 1) na = 1-na
   if (na .ne. 0) go to 109
   call radfg (ido,ip,l1,idl1,c,c,c,ch,ch,wa(iw))
   na = 1
   go to 110
109 call radfg (ido,ip,l1,idl1,ch,ch,ch,c,c,wa(iw))
   na = 0
110 l2 = l1
end do
if (na .eq. 1) return
do i=1,n
   c(i) = ch(i)
end do
return
end subroutine rfftf1

subroutine radf2 (ido,l1,cc,ch,wa1)
implicit none
integer, intent(in) :: ido, l1
real :: cc(ido,l1,*)
real, intent(inout) :: ch(ido,2,l1)
real :: wa1(*)
integer :: i, ic, idp2, k
real :: ti2, tr2
do k=1,l1
   ch(1,1,k) = cc(1,k,1)+cc(1,k,2)
   ch(ido,2,k) = cc(1,k,1)-cc(1,k,2)
end do
if (ido-2) 107,105,102
102 idp2 = ido+2
if((ido-1)/2.lt.l1) go to 108
do k=1,l1
   do i=3,ido,2
      ic = idp2-i
      tr2 = wa1(i-2)*cc(i-1,k,2)+wa1(i-1)*cc(i,k,2)
      ti2 = wa1(i-2)*cc(i,k,2)-wa1(i-1)*cc(i-1,k,2)
      ch(i,1,k) = cc(i,k,1)+ti2
      ch(ic,2,k) = ti2-cc(i,k,1)
      ch(i-1,1,k) = cc(i-1,k,1)+tr2
      ch(ic-1,2,k) = cc(i-1,k,1)-tr2
   end do
end do
go to 111
108 do i=3,ido,2
   ic = idp2-i
   do k=1,l1
      tr2 = wa1(i-2)*cc(i-1,k,2)+wa1(i-1)*cc(i,k,2)
      ti2 = wa1(i-2)*cc(i,k,2)-wa1(i-1)*cc(i-1,k,2)
      ch(i,1,k) = cc(i,k,1)+ti2
      ch(ic,2,k) = ti2-cc(i,k,1)
      ch(i-1,1,k) = cc(i-1,k,1)+tr2
      ch(ic-1,2,k) = cc(i-1,k,1)-tr2
   end do
end do
111 if (mod(ido,2) .eq. 1) return
105 do k=1,l1
   ch(1,2,k) = -cc(ido,k,2)
   ch(ido,1,k) = cc(ido,k,1)
end do
107 return
end subroutine radf2

subroutine radf3 (ido,l1,cc,ch,wa1,wa2)
implicit none
integer, intent(in) :: ido, l1
real :: cc(ido,l1,*)
real, intent(inout) :: ch(ido,3,l1)
real :: wa1(*), wa2(*)
integer :: i, ic, idp2, k
real :: ci2, cr2, di2, di3, dr2, dr3, taui, taur, ti2, ti3, tr2, &
&tr3
data taur,taui /-.5,.866025403784439/
do k=1,l1
   cr2 = cc(1,k,2)+cc(1,k,3)
   ch(1,1,k) = cc(1,k,1)+cr2
   ch(1,3,k) = taui*(cc(1,k,3)-cc(1,k,2))
   ch(ido,2,k) = cc(1,k,1)+taur*cr2
end do
if (ido .eq. 1) return
idp2 = ido+2
if((ido-1)/2.lt.l1) go to 104
do k=1,l1
   do i=3,ido,2
      ic = idp2-i
      dr2 = wa1(i-2)*cc(i-1,k,2)+wa1(i-1)*cc(i,k,2)
      di2 = wa1(i-2)*cc(i,k,2)-wa1(i-1)*cc(i-1,k,2)
      dr3 = wa2(i-2)*cc(i-1,k,3)+wa2(i-1)*cc(i,k,3)
      di3 = wa2(i-2)*cc(i,k,3)-wa2(i-1)*cc(i-1,k,3)
      cr2 = dr2+dr3
      ci2 = di2+di3
      ch(i-1,1,k) = cc(i-1,k,1)+cr2
      ch(i,1,k) = cc(i,k,1)+ci2
      tr2 = cc(i-1,k,1)+taur*cr2
      ti2 = cc(i,k,1)+taur*ci2
      tr3 = taui*(di2-di3)
      ti3 = taui*(dr3-dr2)
      ch(i-1,3,k) = tr2+tr3
      ch(ic-1,2,k) = tr2-tr3
      ch(i,3,k) = ti2+ti3
      ch(ic,2,k) = ti3-ti2
   end do
end do
return
104 do i=3,ido,2
   ic = idp2-i
   do k=1,l1
      dr2 = wa1(i-2)*cc(i-1,k,2)+wa1(i-1)*cc(i,k,2)
      di2 = wa1(i-2)*cc(i,k,2)-wa1(i-1)*cc(i-1,k,2)
      dr3 = wa2(i-2)*cc(i-1,k,3)+wa2(i-1)*cc(i,k,3)
      di3 = wa2(i-2)*cc(i,k,3)-wa2(i-1)*cc(i-1,k,3)
      cr2 = dr2+dr3
      ci2 = di2+di3
      ch(i-1,1,k) = cc(i-1,k,1)+cr2
      ch(i,1,k) = cc(i,k,1)+ci2
      tr2 = cc(i-1,k,1)+taur*cr2
      ti2 = cc(i,k,1)+taur*ci2
      tr3 = taui*(di2-di3)
      ti3 = taui*(dr3-dr2)
      ch(i-1,3,k) = tr2+tr3
      ch(ic-1,2,k) = tr2-tr3
      ch(i,3,k) = ti2+ti3
      ch(ic,2,k) = ti3-ti2
   end do
end do
return
end subroutine radf3

subroutine radf4 (ido,l1,cc,ch,wa1,wa2,wa3)
implicit none
integer, intent(in) :: ido, l1
real :: cc(ido,l1,*)
real, intent(inout) :: ch(ido,4,l1)
real :: wa1(*), wa2(*), wa3(*)
integer :: i, ic, idp2, k
real :: ci2, ci3, ci4, cr2, cr3, cr4, hsqt2, ti1, ti2, ti3, ti4, &
&tr1, tr2, tr3, tr4
data hsqt2 /.7071067811865475/
do k=1,l1
   tr1 = cc(1,k,2)+cc(1,k,4)
   tr2 = cc(1,k,1)+cc(1,k,3)
   ch(1,1,k) = tr1+tr2
   ch(ido,4,k) = tr2-tr1
   ch(ido,2,k) = cc(1,k,1)-cc(1,k,3)
   ch(1,3,k) = cc(1,k,4)-cc(1,k,2)
end do
if (ido-2) 107,105,102
102 idp2 = ido+2
if((ido-1)/2.lt.l1) go to 111
do k=1,l1
   do i=3,ido,2
      ic = idp2-i
      cr2 = wa1(i-2)*cc(i-1,k,2)+wa1(i-1)*cc(i,k,2)
      ci2 = wa1(i-2)*cc(i,k,2)-wa1(i-1)*cc(i-1,k,2)
      cr3 = wa2(i-2)*cc(i-1,k,3)+wa2(i-1)*cc(i,k,3)
      ci3 = wa2(i-2)*cc(i,k,3)-wa2(i-1)*cc(i-1,k,3)
      cr4 = wa3(i-2)*cc(i-1,k,4)+wa3(i-1)*cc(i,k,4)
      ci4 = wa3(i-2)*cc(i,k,4)-wa3(i-1)*cc(i-1,k,4)
      tr1 = cr2+cr4
      tr4 = cr4-cr2
      ti1 = ci2+ci4
      ti4 = ci2-ci4
      ti2 = cc(i,k,1)+ci3
      ti3 = cc(i,k,1)-ci3
      tr2 = cc(i-1,k,1)+cr3
      tr3 = cc(i-1,k,1)-cr3
      ch(i-1,1,k) = tr1+tr2
      ch(ic-1,4,k) = tr2-tr1
      ch(i,1,k) = ti1+ti2
      ch(ic,4,k) = ti1-ti2
      ch(i-1,3,k) = ti4+tr3
      ch(ic-1,2,k) = tr3-ti4
      ch(i,3,k) = tr4+ti3
      ch(ic,2,k) = tr4-ti3
   end do
end do
go to 110
111 do i=3,ido,2
   ic = idp2-i
   do k=1,l1
      cr2 = wa1(i-2)*cc(i-1,k,2)+wa1(i-1)*cc(i,k,2)
      ci2 = wa1(i-2)*cc(i,k,2)-wa1(i-1)*cc(i-1,k,2)
      cr3 = wa2(i-2)*cc(i-1,k,3)+wa2(i-1)*cc(i,k,3)
      ci3 = wa2(i-2)*cc(i,k,3)-wa2(i-1)*cc(i-1,k,3)
      cr4 = wa3(i-2)*cc(i-1,k,4)+wa3(i-1)*cc(i,k,4)
      ci4 = wa3(i-2)*cc(i,k,4)-wa3(i-1)*cc(i-1,k,4)
      tr1 = cr2+cr4
      tr4 = cr4-cr2
      ti1 = ci2+ci4
      ti4 = ci2-ci4
      ti2 = cc(i,k,1)+ci3
      ti3 = cc(i,k,1)-ci3
      tr2 = cc(i-1,k,1)+cr3
      tr3 = cc(i-1,k,1)-cr3
      ch(i-1,1,k) = tr1+tr2
      ch(ic-1,4,k) = tr2-tr1
      ch(i,1,k) = ti1+ti2
      ch(ic,4,k) = ti1-ti2
      ch(i-1,3,k) = ti4+tr3
      ch(ic-1,2,k) = tr3-ti4
      ch(i,3,k) = tr4+ti3
      ch(ic,2,k) = tr4-ti3
   end do
end do
110 if (mod(ido,2) .eq. 1) return
105 do k=1,l1
   ti1 = -hsqt2*(cc(ido,k,2)+cc(ido,k,4))
   tr1 = hsqt2*(cc(ido,k,2)-cc(ido,k,4))
   ch(ido,1,k) = tr1+cc(ido,k,1)
   ch(ido,3,k) = cc(ido,k,1)-tr1
   ch(1,2,k) = ti1-cc(ido,k,3)
   ch(1,4,k) = ti1+cc(ido,k,3)
end do
107 return
end subroutine radf4

subroutine radf5 (ido,l1,cc,ch,wa1,wa2,wa3,wa4)
implicit none
integer, intent(in) :: ido, l1
real :: cc(ido,l1,*)
real, intent(inout) :: ch(ido,5,l1)
real :: wa1(*), wa2(*), wa3(*), wa4(*)
integer :: i, ic, idp2, k
real :: ci2, ci3, ci4, ci5, cr2, cr3, cr4, cr5, di2, di3, di4, &
&di5, dr2, dr3, dr4, dr5, ti11, ti12, ti2, ti3, ti4, ti5, tr11, &
&tr12, tr2, tr3, tr4, tr5
data tr11,ti11,tr12,ti12 /.309016994374947,.951056516295154, &
&-.809016994374947,.587785252292473/
do k=1,l1
   cr2 = cc(1,k,5)+cc(1,k,2)
   ci5 = cc(1,k,5)-cc(1,k,2)
   cr3 = cc(1,k,4)+cc(1,k,3)
   ci4 = cc(1,k,4)-cc(1,k,3)
   ch(1,1,k) = cc(1,k,1)+cr2+cr3
   ch(ido,2,k) = cc(1,k,1)+tr11*cr2+tr12*cr3
   ch(1,3,k) = ti11*ci5+ti12*ci4
   ch(ido,4,k) = cc(1,k,1)+tr12*cr2+tr11*cr3
   ch(1,5,k) = ti12*ci5-ti11*ci4
end do
if (ido .eq. 1) return
idp2 = ido+2
if((ido-1)/2.lt.l1) go to 104
do k=1,l1
   do i=3,ido,2
      ic = idp2-i
      dr2 = wa1(i-2)*cc(i-1,k,2)+wa1(i-1)*cc(i,k,2)
      di2 = wa1(i-2)*cc(i,k,2)-wa1(i-1)*cc(i-1,k,2)
      dr3 = wa2(i-2)*cc(i-1,k,3)+wa2(i-1)*cc(i,k,3)
      di3 = wa2(i-2)*cc(i,k,3)-wa2(i-1)*cc(i-1,k,3)
      dr4 = wa3(i-2)*cc(i-1,k,4)+wa3(i-1)*cc(i,k,4)
      di4 = wa3(i-2)*cc(i,k,4)-wa3(i-1)*cc(i-1,k,4)
      dr5 = wa4(i-2)*cc(i-1,k,5)+wa4(i-1)*cc(i,k,5)
      di5 = wa4(i-2)*cc(i,k,5)-wa4(i-1)*cc(i-1,k,5)
      cr2 = dr2+dr5
      ci5 = dr5-dr2
      cr5 = di2-di5
      ci2 = di2+di5
      cr3 = dr3+dr4
      ci4 = dr4-dr3
      cr4 = di3-di4
      ci3 = di3+di4
      ch(i-1,1,k) = cc(i-1,k,1)+cr2+cr3
      ch(i,1,k) = cc(i,k,1)+ci2+ci3
      tr2 = cc(i-1,k,1)+tr11*cr2+tr12*cr3
      ti2 = cc(i,k,1)+tr11*ci2+tr12*ci3
      tr3 = cc(i-1,k,1)+tr12*cr2+tr11*cr3
      ti3 = cc(i,k,1)+tr12*ci2+tr11*ci3
      tr5 = ti11*cr5+ti12*cr4
      ti5 = ti11*ci5+ti12*ci4
      tr4 = ti12*cr5-ti11*cr4
      ti4 = ti12*ci5-ti11*ci4
      ch(i-1,3,k) = tr2+tr5
      ch(ic-1,2,k) = tr2-tr5
      ch(i,3,k) = ti2+ti5
      ch(ic,2,k) = ti5-ti2
      ch(i-1,5,k) = tr3+tr4
      ch(ic-1,4,k) = tr3-tr4
      ch(i,5,k) = ti3+ti4
      ch(ic,4,k) = ti4-ti3
   end do
end do
return
104 do i=3,ido,2
   ic = idp2-i
   do k=1,l1
      dr2 = wa1(i-2)*cc(i-1,k,2)+wa1(i-1)*cc(i,k,2)
      di2 = wa1(i-2)*cc(i,k,2)-wa1(i-1)*cc(i-1,k,2)
      dr3 = wa2(i-2)*cc(i-1,k,3)+wa2(i-1)*cc(i,k,3)
      di3 = wa2(i-2)*cc(i,k,3)-wa2(i-1)*cc(i-1,k,3)
      dr4 = wa3(i-2)*cc(i-1,k,4)+wa3(i-1)*cc(i,k,4)
      di4 = wa3(i-2)*cc(i,k,4)-wa3(i-1)*cc(i-1,k,4)
      dr5 = wa4(i-2)*cc(i-1,k,5)+wa4(i-1)*cc(i,k,5)
      di5 = wa4(i-2)*cc(i,k,5)-wa4(i-1)*cc(i-1,k,5)
      cr2 = dr2+dr5
      ci5 = dr5-dr2
      cr5 = di2-di5
      ci2 = di2+di5
      cr3 = dr3+dr4
      ci4 = dr4-dr3
      cr4 = di3-di4
      ci3 = di3+di4
      ch(i-1,1,k) = cc(i-1,k,1)+cr2+cr3
      ch(i,1,k) = cc(i,k,1)+ci2+ci3
      tr2 = cc(i-1,k,1)+tr11*cr2+tr12*cr3
      ti2 = cc(i,k,1)+tr11*ci2+tr12*ci3
      tr3 = cc(i-1,k,1)+tr12*cr2+tr11*cr3
      ti3 = cc(i,k,1)+tr12*ci2+tr11*ci3
      tr5 = ti11*cr5+ti12*cr4
      ti5 = ti11*ci5+ti12*ci4
      tr4 = ti12*cr5-ti11*cr4
      ti4 = ti12*ci5-ti11*ci4
      ch(i-1,3,k) = tr2+tr5
      ch(ic-1,2,k) = tr2-tr5
      ch(i,3,k) = ti2+ti5
      ch(ic,2,k) = ti5-ti2
      ch(i-1,5,k) = tr3+tr4
      ch(ic-1,4,k) = tr3-tr4
      ch(i,5,k) = ti3+ti4
      ch(ic,4,k) = ti4-ti3
   end do
end do
return
end subroutine radf5

subroutine radfg (ido,ip,l1,idl1,cc,c1,c2,ch,ch2,wa)
implicit none
integer, intent(in) :: idl1, ido, ip, l1
real, intent(inout) :: c1(ido,l1,ip), c2(idl1,ip), cc(ido,ip,l1), &
&ch(ido,l1,ip), ch2(idl1,ip)
real :: wa(*)
integer :: i, ic, idij, idp2, ik, ipp2, ipph, is, j, j2, jc, k, l, &
&lc, nbd
real :: ai1, ai2, ar1, ar1h, ar2, ar2h, arg, dc2, dcp, ds2, dsp, &
&tpi
data tpi/6.28318530717959/
arg = tpi/float(ip)
dcp = cos(arg)
dsp = sin(arg)
ipph = (ip+1)/2
ipp2 = ip+2
idp2 = ido+2
nbd = (ido-1)/2
if (ido .eq. 1) go to 119
do ik=1,idl1
   ch2(ik,1) = c2(ik,1)
end do
do j=2,ip
   do k=1,l1
      ch(1,k,j) = c1(1,k,j)
   end do
end do
if (nbd .gt. l1) go to 107
is = -ido
do j=2,ip
   is = is+ido
   idij = is
   do i=3,ido,2
      idij = idij+2
      do k=1,l1
         ch(i-1,k,j) = wa(idij-1)*c1(i-1,k,j)+wa(idij)*c1(i,k,j)
         ch(i,k,j) = wa(idij-1)*c1(i,k,j)-wa(idij)*c1(i-1,k,j)
      end do
   end do
end do
go to 111
107 is = -ido
do j=2,ip
   is = is+ido
   do k=1,l1
      idij = is
      do i=3,ido,2
         idij = idij+2
         ch(i-1,k,j) = wa(idij-1)*c1(i-1,k,j)+wa(idij)*c1(i,k,j)
         ch(i,k,j) = wa(idij-1)*c1(i,k,j)-wa(idij)*c1(i-1,k,j)
      end do
   end do
end do
111 if (nbd .lt. l1) go to 115
do j=2,ipph
   jc = ipp2-j
   do k=1,l1
      do i=3,ido,2
         c1(i-1,k,j) = ch(i-1,k,j)+ch(i-1,k,jc)
         c1(i-1,k,jc) = ch(i,k,j)-ch(i,k,jc)
         c1(i,k,j) = ch(i,k,j)+ch(i,k,jc)
         c1(i,k,jc) = ch(i-1,k,jc)-ch(i-1,k,j)
      end do
   end do
end do
go to 121
115 do j=2,ipph
   jc = ipp2-j
   do i=3,ido,2
      do k=1,l1
         c1(i-1,k,j) = ch(i-1,k,j)+ch(i-1,k,jc)
         c1(i-1,k,jc) = ch(i,k,j)-ch(i,k,jc)
         c1(i,k,j) = ch(i,k,j)+ch(i,k,jc)
         c1(i,k,jc) = ch(i-1,k,jc)-ch(i-1,k,j)
      end do
   end do
end do
go to 121
119 do ik=1,idl1
   c2(ik,1) = ch2(ik,1)
end do
121 do j=2,ipph
   jc = ipp2-j
   do k=1,l1
      c1(1,k,j) = ch(1,k,j)+ch(1,k,jc)
      c1(1,k,jc) = ch(1,k,jc)-ch(1,k,j)
   end do
end do
!
ar1 = 1.
ai1 = 0.
do l=2,ipph
   lc = ipp2-l
   ar1h = dcp*ar1-dsp*ai1
   ai1 = dcp*ai1+dsp*ar1
   ar1 = ar1h
   do ik=1,idl1
      ch2(ik,l) = c2(ik,1)+ar1*c2(ik,2)
      ch2(ik,lc) = ai1*c2(ik,ip)
   end do
   dc2 = ar1
   ds2 = ai1
   ar2 = ar1
   ai2 = ai1
   do j=3,ipph
      jc = ipp2-j
      ar2h = dc2*ar2-ds2*ai2
      ai2 = dc2*ai2+ds2*ar2
      ar2 = ar2h
      do ik=1,idl1
         ch2(ik,l) = ch2(ik,l)+ar2*c2(ik,j)
         ch2(ik,lc) = ch2(ik,lc)+ai2*c2(ik,jc)
      end do
   end do
end do
do j=2,ipph
   do ik=1,idl1
      ch2(ik,1) = ch2(ik,1)+c2(ik,j)
   end do
end do
!
if (ido .lt. l1) go to 132
do k=1,l1
   do i=1,ido
      cc(i,1,k) = ch(i,k,1)
   end do
end do
go to 135
132 do i=1,ido
   do k=1,l1
      cc(i,1,k) = ch(i,k,1)
   end do
end do
135 do j=2,ipph
   jc = ipp2-j
   j2 = j+j
   do k=1,l1
      cc(ido,j2-2,k) = ch(1,k,j)
      cc(1,j2-1,k) = ch(1,k,jc)
   end do
end do
if (ido .eq. 1) return
if (nbd .lt. l1) go to 141
do j=2,ipph
   jc = ipp2-j
   j2 = j+j
   do k=1,l1
      do i=3,ido,2
         ic = idp2-i
         cc(i-1,j2-1,k) = ch(i-1,k,j)+ch(i-1,k,jc)
         cc(ic-1,j2-2,k) = ch(i-1,k,j)-ch(i-1,k,jc)
         cc(i,j2-1,k) = ch(i,k,j)+ch(i,k,jc)
         cc(ic,j2-2,k) = ch(i,k,jc)-ch(i,k,j)
      end do
   end do
end do
return
141 do j=2,ipph
   jc = ipp2-j
   j2 = j+j
   do i=3,ido,2
      ic = idp2-i
      do k=1,l1
         cc(i-1,j2-1,k) = ch(i-1,k,j)+ch(i-1,k,jc)
         cc(ic-1,j2-2,k) = ch(i-1,k,j)-ch(i-1,k,jc)
         cc(i,j2-1,k) = ch(i,k,j)+ch(i,k,jc)
         cc(ic,j2-2,k) = ch(i,k,jc)-ch(i,k,j)
      end do
   end do
end do
return
end subroutine radfg

subroutine cheby (a, b, f, g, phi, eps, itno, mxiter, l, m, &
&p, q, error, ierr, w)
implicit none
integer, intent(inout) :: ierr, itno
integer, intent(in) :: l, m, mxiter
integer :: i1, i2, i3, i4, i5, lp1, lpm, mp1, n, np1
!     ******************************************************************
!     Rational Chebychev approximation of continuous functions
!     ******************************************************************
double precision, intent(in) :: a, b
double precision :: f, g, phi
double precision, intent(in) :: eps
double precision, intent(inout) :: error
double precision, intent(inout) :: p(*), q(*), w(*)
external f, g, phi
!     -------------------
if (l .lt. 0 .or. m .lt. 0) go to 10
lp1 = l + 1
mp1 = m + 1
lpm = l + m
n = lpm + 1
np1 = n + 1
!     -------------------
i1 = np1 + 1
i2 = i1 + np1
i3 = i2 + np1*np1
i4 = i3 + np1
i5 = i4 + np1
call cheby1 (a, b, f, g, phi, eps, itno, mxiter, l, m, p, q, &
&error, ierr, lp1, mp1, lpm, n, np1, w(1), &
&w(i1), w(i2), w(i3), w(i4), w(i5))
return
!     ------------------------------------------------------------------
!     Error return
!     ------------------------------------------------------------------
10 ierr = 1
return
end subroutine cheby

subroutine cheby1 (a, b, f, g, phi, eps, itno, mxiter, l, m, &
&p, q, error, ierr, lp1, mp1, lpm, n, np1, &
&x, xval, c, d, err, h)
implicit none
integer, intent(inout) :: ierr, itno
integer, intent(in) :: l, lp1, lpm, m, mp1, mxiter, n, np1
integer :: i, ii, j, k, kount, lpi
!     ------------------------------------------------------------------
double precision, intent(in) :: a, b
double precision :: f, g, phi
double precision, intent(in) :: eps
double precision, intent(out) :: error
double precision, intent(inout) :: p(lp1), q(mp1), x(np1), &
&xval(np1), c(np1,np1), d(np1), err(np1), h(np1)
double precision :: b1, c0, del, dn, dnp1, eps0, half, h1, olderr, &
&one, pi, sign, sum, tau, templ, ten, test, u, xi, xlb, xm1, y, y2, &
&y3, z, zero, zz, z1, z2, z3
external f, g, phi
!     -------------------
data pi/3.14159265358979323846264338328d0/
data zero/0.d0/, half/.5d0/, one/1.d0/, ten/10.d0/
data eps0/1.d-2/, tau/.015d0/, c0/.0625d0/
!     -------------------
error = zero
if (eps .le. zero .or. eps .ge. eps0) go to 200
ierr = 0
!
itno = 1
xlb = zero
dn = n
dnp1 = np1
!
do 10 i = 1,lp1
10 p(i) = zero
do 11 i = 1,mp1
11 q(i) = zero
q(1) = one
!
!     Compute initial approximations of the critical points
!
x(1) = a
x(np1) = b
k = n/2
if (k .le. 0) go to 30
b1 = half*(b - a)
xm1 = half*(a + b)
do 20 i = 1,k
xi = i
z = -b1*dcos(pi*(xi/dn))
x(i+1) = z + xm1
ii = np1 - i
20 x(ii) = xm1 - z
!
!     Evaluate phi at the critical points
!
30 do 31 i = 1,np1
31 xval(i) = phi(x(i))
kount = 1
!
!     Set up the linear equations
!
40 k = l + 2
sign = one
do i = 1,np1
sign = -sign
c(i,1) = one
if (l .le. 0) go to 42
do 41 j = 2,lp1
41 c(i,j) = c(i,j-1)*xval(i)
42 d(i) = f(x(i))
if (m .le. 0) go to 44
templ = sign*xlb*g(x(i)) - d(i)
c(i,k) = xval(i)*templ
if (k .gt. lpm) go to 44
do 43 j = k,lpm
43 c(i,j+1) = c(i,j)*xval(i)
44 c(i,np1) = sign*g(x(i))
end do
!
!     SOLVE THE EQUATIONS CX = D AND STORE THE RESULTS IN D
!
call dpslv (np1, 1, c, np1, d, np1, ierr)
if (ierr .ne. 0) go to 220
if (kount .gt. 1) go to 50
!
!     Redefine the equations and solve
!
xlb = (d(np1) + xlb*dn)/dnp1
if (m .le. 0) go to 61
kount = 2
go to 40
!
50 test = dabs(xlb - d(np1))
xlb = (d(np1) + xlb*dn)/dnp1
kount = kount + 1
if (kount .le. 4 .and. test .gt. eps0*dabs(xlb)) go to 40
!
!     Store the results in p and q
!
do 60 i = 2,mp1
lpi = l + i
60 q(i) = d(lpi)
61 do 62 i = 1,lp1
62 p(i) = d(i)
!
!     Search for new critical points
!
olderr = error
error = zero
z1 = zero
u = one
if (xlb .lt. zero) u = -u
!
if (n .gt. 1) go to 70
h(1) = tau*(x(2) - x(1))
h(2) = -h(1)
go to 72
70 do 71 i = 2,n
71 h(i) = tau*(x(i+1) - x(i-1))
h(1) = half*h(2)
h(np1) = -half*h(n)
72 continue
!
do i = 1,np1
y2 = x(i)
h1 = h(i)
y3 = y2 + h1
call cerr(y2, f(y2), g(y2), phi(y2), del, ierr, l, lp1, m, np1, d)
if (ierr .ne. 0) return
z2 = u*del
call cerr(y3, f(y3), g(y3), phi(y3), del, ierr, l, lp1, m, np1, d)
if (ierr .ne. 0) return
z3 = u*del
if (z2 .lt. z3) go to 80
h1 = -h1
z = z3
z3 = z2
z2 = z
y = y3
y3 = y2
y2 = y
!
80 y = y3 + h1
if (y .ge. a) go to 81
y = a
go to 90
81 if (y .le. b) go to 82
y = b
go to 90
82 call cerr(y, f(y), g(y), phi(y), del, ierr, l, lp1, m, np1, d)
if (ierr .ne. 0) return
z = u*del
if (z .le. z3) go to 83
y2 = y3
y3 = y
z2 = z3
z3 = z
go to 80
83 y = (z - z3) + (z2 - z3)
if (y .ne. zero) go to 84
y = y3
go to 90
84 y = half*(y2 + y3) + h1*(z2 - z3)/y
!
90 x(i) = y
call cerr(y, f(y), g(y), phi(y), del, ierr, l, lp1, m, np1, d)
if (ierr .ne. 0) return
err(i) = del
u = -u
if (i .eq. 1) go to 91
if (x(i) .le. x(i-1)) go to 230
91 z = dabs(err(i))
error = dmax1(error, z)
if (z .ge. ten) go to 240
y = dabs(xlb)
zz = one
if (y .ne. zero) zz = dabs(z - y)/y
if (z1 .lt. zz) z1 = zz
end do
!
!     Search for an extra extremal point between the endpoints
!     of the interval and the critical points
!
if (x(1) .le. a) go to 110
h1 = c0*(x(1) - a)
u = one
if (xlb .ge. zero) u = -u
z3 = zero
y = a
do 100 i = 1,16
call cerr(y, f(y), g(y), phi(y), del, ierr, l, lp1, m, np1, d)
if (ierr .ne. 0) return
z = u*del
if (z .le. z3) go to 100
z3 = z
z2 = y
100 y = y + h1
error = dmax1(error, z3)
z = dabs(xlb)
if (z3 .le. z) go to 110
i = np1
do 101 ii = 2,np1
err(i) = err(i-1)
x(i) = x(i-1)
101 i = i - 1
x(1) = z2
err(1) = u*z3
go to 113
!
110 if (x(np1) .ge. b) go to 120
h1 = c0*(b - x(np1))
u = one
if (err(np1) .ge. zero) u = -u
z3 = zero
y = b
do 111 i = 1,16
call cerr(y, f(y), g(y), phi(y), del, ierr, l, lp1, m, np1, d)
if (ierr .ne. 0) return
z = u*del
if (z .le. z3) go to 111
z3 = z
z2 = y
111 y = y - h1
error = dmax1(error, z3)
z = dabs(xlb)
if (z3 .le. z) go to 120
do 112 i = 1,n
err(i) = err(i+1)
112 x(i) = x(i+1)
x(np1) = z2
err(np1) = u*z3
113 xlb = -xlb
zz = one
if (z .ne. zero) zz = dabs(z3 - z)/z
if (z1 .lt. zz) z1 = zz
!
!     Check for convergence
!
120 if (z1 .le. eps) return
!
!     Set up for the next iteration
!
if (itno .ge. mxiter) go to 210
sum = zero
sign = one
do 130 i = 1,np1
sum = sum + sign*err(i)
130 sign = -sign
xlb = sum/dnp1
itno = itno + 1
go to 30
!     ------------------------------------------------------------------
!     Error return
!     ------------------------------------------------------------------
!     Input error
!
200 ierr = 1
return
!
!     mxiter iterations were performed - more iterations are needed
!
210 ierr = 2
return
!
!     The linear equations cannot be solved
!
220 if (itno .eq. 1) go to 250
ierr = 3
return
!
!     The sequence of critical points is not monotonically increasing
!
230 ierr = 4
if (i .le. n) error = olderr
return
!
!     It appears that the algorithm has failed to converge
!     there may be poles in the rational approximation
!
240 ierr = 5
return
!
!     The routine HAS completely failed - the results should be ignored
!
250 ierr = 6
return
end subroutine cheby1

subroutine cerr (t, ft, gt, phit, del, ierr, l, lp1, m, np1, d)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: l, lp1, m, np1
integer :: i, ii
!     ------------------------------------------------------------------
!     Compute the approximation error at point t
!     ------------------------------------------------------------------
double precision, intent(in) :: t, ft, gt, phit
double precision, intent(inout) :: del
double precision, intent(in) :: d(np1)
double precision :: p, q, r, zero, one
data zero/0.d0/, one/1.d0/
!     -------------------
p = d(lp1)
if (l .le. 0) go to 20
do 10 i = 1,l
ii = lp1 - i
10 p = p*phit + d(ii)
!
20 q = zero
if (m .le. 0) go to 22
do 21 i = 1,m
ii = np1 - i
21 q = (q + d(ii))*phit
22 q = q + one
!
if (q .eq. zero) go to 110
if (gt .eq. zero) go to 100
r = p/q
del = (r - ft)/gt
return
!     ------------------------------------------------------------------
!     Error return
!     ------------------------------------------------------------------
!     The function G is zero at point t
!
100 ierr = 1
return
!
!     The routine HAS completely failed - the results should be ignored
!
110 ierr = 6
return
end subroutine cerr

subroutine adapt (f, xlft, xrgt, epsln, npiece, errest, xknots, &
&coefs, ierr, kmax, ndeg, nsmth, anorm, dx, mo, kbreak, brakpt, &
&kdiff, vallft, valrgt)
implicit none
integer :: ierr, kbreak, kdiff(kbreak), kmax, mo, ndeg, npiece, &
&nsmth
integer :: k, kdimen, ndimen
integer :: leftx, nintrp
integer :: kntdim, level, nbreak, npardm
integer :: ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack
integer :: knots
!
!        ===============================================================
!
!     Tabulation of the internal and external names of the arguments.
!
!
!    INTERNAL   EXTERNAL
!     f          f
!     A          XLFT
!     b          XRGT
!     accur      epsln
!     KNOTS      npiece
!     ERROR      errest
!     xknots     xknots
!     coefs      coefs
!     ierr       ierr
!     kmax       kmax
!     DEGREE     ndeg
!     SMOOTH     NSMTH
!     NORM       anorm
!     charf      dx
!     edist      mo
!     nbreak     kbreak
!     XBREAK     brakpt
!     dbreak     kdiff
!     bleft      VALLFT
!     BRIGHT     VALRGT
!
double precision :: a, accur, b, bleft(20), bright(20), charf, &
&ddtemp(20,20), dsctol, error, errori, factor(20), fintrp(18), &
&fleft(10), fright(10), norm, xbreak(20), xdd(20), xintrp(18), &
&xleft(50), xright(50), buffer
integer :: both, break, dbreak(20), degree, edist, right, rightx, &
&smooth
logical :: discrd
double precision :: xknots(*), coefs(kmax,*)
double precision :: anorm, brakpt(kbreak), dx, epsln, errest, &
&vallft(kbreak), valrgt(kbreak), xlft, xrgt
double precision :: f
external f
!
common /inputz/ a, b, accur, norm, charf, xbreak, bleft, bright, &
&dbreak, degree, smooth, level, edist, nbreak, kntdim, npardm
common /resulz/ error, knots
common /kontrl/ dsctol, errori, xleft, xright, break, both, &
&factor, ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack, right, discrd, buffer
common /comdif/ ddtemp, fintrp, fleft, fright, xdd, xintrp, &
&leftx, nintrp, rightx
!
!
10 a = xlft
b = xrgt
accur = epsln
degree = ndeg
smooth = nsmth
norm = anorm
charf = dx
edist = mo
nbreak = kbreak
if (nbreak.le.0 .or. nbreak.ge.21) go to 30
do 20 k = 1,nbreak
  xbreak(k) = brakpt(k)
  dbreak(k) = kdiff(k)
  bleft(k) = vallft(k)
  bright(k) = valrgt(k)
20 continue
30 continue
!
kdimen = kmax+1
ndimen = ndeg+1
call adapt1(f, xknots, coefs, kdimen, kmax, ndimen, ierr)
npiece = knots
errest = error
return
end subroutine adapt

subroutine adapt1(f, xknots, coefs, kdimen, kmax, ndimen, ierr)
implicit none
integer :: ierr, kdimen, kmax, ndimen
integer :: leftx, nintrp
integer :: kntdim, level, nbreak, npardm
integer :: ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack
integer :: knots
!
!     This algorithm computes a piecewise polynomial approximation
!  of specified smoothness, accuracy and degree.  The input to the
!  computation is
!
!   f      - FUNCTION BEING APPROXIMATED. IT MUST PROVIDE VALUES OF
!            derivatives up to the order of smoothness specified for
!            the approximation.  The calling sequence is f(X,FDERV) and
!            FDERV contains the DERIVATIVES( SEE CONSTRAINT BELOW)
!   A,b    - THE ENDPOINTS OF THE INTERVAL OF APPROXIMATION
!   accur  - the accuracy required for the approximation
!   smooth - the smoothness required for the approximation
!              = 0  MEANS CONTINUOUS
!              = 1  MEANS CONTINUOUS SLOPE
!              = 2  MEANS CONTINUOUS SECOND DERIVATIVE, ETC.
!   degree - the degree of the polynomial pieces.
!            Must have degree GT 2*smooth
!   charf  - characteristic length of the function f(X). Pieces are not
!            longer than this length.
!   NORM   - NORM TO MEASURE THE APPROXIMATION ERROR
!              = 1  L1 APPROXIMATION (LEAST DEVIATIONS)
!              = 2  L2 APPROXIMATION (LEAST SQUARES)
!              = 3  TCHEBYCHEFF (MINIMAX) APPROXIMATION
!              =-P  (NEGATIVE VALUE) GENERAL LP APPROXIMATION
!   nbreak - number of special break points in the approximation.
!            Associated input variables are
!              XBREAK(J)  - location of break points
!              dbreak(J)  - derivative broken at XBREAK
!              bleft (J)  - value from left for dbreak derivative
!              bright(J)  -   -    -   right -    -        -
!   edist  - switch to change from proportional error distribution
!            to fixed distribution. This is primarily of use in
!            approximation of functions with singularities. One should
!            USE NORM = 1. OR SO IN SUCH CASES
!              = 0  PROPORTIONAL DISTRIBUTION
!              = 1  APPROXIMATE FIXED ERROR DISTRIBUTION
!                   attempts to achieve specified accuracy value accur
!              = 2  TRUE FIXED ERROR DISTRIBUTION
!
!  ********** OUTPUT **********
!     the output of the computation consists of 4 parts, each returned
!     to the user in a different way. They are
!
!   xknots,coefs - arrays defining the piecewise polynomial result.
!            xknots(K)  = knots OF THE APPROXIMATION ( K = 1 TO KNOTS)
!                         the last one is right end point of interval
!            coefs(K,N) = COEFFICIENT OF (X - XKNOT(K))**(N-1) IN THE
!                         interval XKNOT(K) to XKNOT(K+1)
!                           K = 1 TO knots-1  AND  N = 1 TO degree+1
!            these arrays are passed as arguments so as to use variable
!            dimensions. The arrays are of dimension xknots(kdimen) and
!            coefs(kmax,ndimen). IT IS ASSUMED THAT kdimen = kmax+1.
!               ***** NOTE ***** SEVERAL SMALL ARRAYS HERE HAVE FIXED
!                        dimensions that limit degree and thus ndimen
!                        SHOULD NOT EXCEED THIS LIMIT (CURRENTLY = 20)
!
!   RESULZ - a labeled common block containing knots and error
!              knots - number of knots of the approximation
!              error - estimated accuracy of the approximation
!
!   ierr - status indicator. ierr takes the values
!      0   THE APPROXIMATION WAS SUCCESSFULLY CONSTRUCTED.
!     -1   INPUT ERROR REPORTED BY adset.
!     -2   A AND b ARE TOO CLOSE.
!     -3   charf IS TOO SMALL.
!     -4   EITHER ALL THE BREAK POINTS ARE NOT BETWEEN A AND b, OR
!          XBREAK(I).GE.XBREAK(I+1) FOR SOME I.
!     -5   dbreak(I).LT.0 .OR. dbreak(I).GT.(degree-1)/2 FOR SOME I.
!      1   THE KNOT LIMIT WAS EXCEEDED.
!      2   BREAK POINT ADJUSTMENT REQUIRES THAT A SUBINTERVAL BE
!          partitioned. However, this cannot be done either because
!          the interval stack is full, or partitioning will produce
!          too small an interval.
!      3   A SUBINTERVAL MUST BE PARTITIONED BECAUSE ITS LENGTH IS
!          greater than charf. However, this cannot be done since the
!          interval stack is full.
!      4   A SUBINTERVAL MUST BE PARTITIONED SO THAT THE ACCURACY
!          criteria can be satisfied. However, this cannot be done
!          either because the interval stack is full, or partitioning
!          will produce too small an interval.
!
!  ********** DIMENSION CONSTRAINTS **********
!     maxknt - max number of knots taken from user via kdimen
!              arrays with this dimension (or related values)
!                   coefs   xknots
!     maxpar - MAX NUMBER OF PARAMETERS PER INTERVAL (CURRENTLY = 20)
!                   user provided ndimen must have ndimen LE maxpar
!                   must have  degree + 1 LE maxpar
!              arrays with this dimension (or related values)
!                D       DDTEMP  FDERVL  FDERVR  FDUMB   FACTOR
!                FINTRP  FLEFT   FRIGHT  POWERS  XTEMP   XINTRP  XDD
!              ***** NOTE ***** maxpar ALSO AFFECTS ARGUMENT fderv
!              of function f.  FDERVL, FDERVR are also involved.
!              Should declare FDERV of size 10 in f to be safe.
!     maxaux - MAXIMUM NUMBER OF AUXILIARY INPUT ( = 20 NOW ). ARRAYS
!                 XBREAK  dbreak  bleft   BRIGHT
!     maxstk - max size of active interval stack
!              MIN INTERVAL LENGTH IS 2**(-maxstk)*(b-a). ARRAYS
!                 XLEFT   XRIGHT
!
!  **********  PORTABILITY CONSIDERATIONS  **********
!
!     All the routines in this package (except adapt) are written in
!     ANSI standard Fortran. In addition, they meet all the requirements
!     of the Bell labs portable Fortran -PFORT-.  Nevertheless, the
!     routines are affected by a change in machine word length and
!     changing to single precision.
!
!     ***** THE GAUSS WEIGHTS AND ABSCISSAE IN adcomp ARE GIVEN TO
!           30 digits. The parameter eps0 in adset specifies the
!           accuracy of these constants. If the accuracy is changed
!           TO K DECIMAL DIGITS THEN SET EPS0 = 10**(-K).
!
!     ***** THE INTERVAL STACK SIZE maxstk IS DEFINED IN adset TO
!           be 50. If maxstk is modified then set the dimensions of
!           XLEFT and XRIGHT to the new value for maxstk. Note that
!           THE MINIMUM INTERVAL LENGTH IS 2**(-maxstk)*(b-a).
!
!  Single precision conversion -- requires four steps
!     1. Declare all double precision variables to be real.
!
!     2. Change all double precision numbers in the data statements.
!        (Floating point numbers appear only in data statements.)
!
!     3. Change dabs,DMAX1,DMIN1 at many places.
!
!     4. Change dpmpar to spmpar in adset.
!
double precision :: a, accur, b, bleft(20), bright(20), charf, &
&ddtemp(20,20), dsctol, error, errori, factor(20), fintrp(18), &
&fleft(10), fright(10), norm, xbreak(20), xdd(20), xintrp(18), &
&xleft(50), xright(50), buffer
integer :: both, break, dbreak(20), degree, edist, right, rightx, &
&smooth
logical :: discrd
double precision :: xknots(kdimen), coefs(kmax,ndimen)
double precision :: f
external f
!
common /inputz/ a, b, accur, norm, charf, xbreak, bleft, bright, &
&dbreak, degree, smooth, level, edist, nbreak, kntdim, npardm
!                      kntdim - kdimen, name changed to put in common
!                      npardm - ndimen, name changed to put in common
common /resulz/ error, knots
!                      knots = FINAL NO. OF KNOTS, INCLUDES b AS ONE.
!                      ERROR = ESTIMATE OF ERROR ACTUALLY ACHIEVED.
common /kontrl/ dsctol, errori, xleft, xright, break, both, &
&factor, ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack, right, discrd, buffer
!             KONTRL contains generally useful variables
!                      maxstk - see comments above
!                      buffer - the machine dependent tolerance used
!                               by the algorithm
!                      NSTACK - counter for interval stack, consists of
!                               (XLEFT(J),XRIGHT(J))  J = 1 TO NSTACK
!                      ERRORI - error estimate for top interval
!                      DSCTOL - tolerance to check discarding intervals
!                      discrd - switch to signal discard of top interval
!                      factor - array of factorials
!                      NPAR   - NUMBER OF PAREMETERS = degree + 1
!                      interp - number of interior interpolation points
!                               in the normal interval
!                      ibreak - counter on break points
!                      break  - switch for break point in top interval
!                               0     = NO BREAK PRESENT
!                               left  = break AT XLEFT(NSTACK)
!                               right = break AT XRIGHT(NSTACK)
!                               both  = break AT BOTH ENDS
common /comdif/ ddtemp, fintrp, fleft, fright, xdd, xintrp, &
&leftx, nintrp, rightx
!             COMDIF contains variables used only by adcomp and friends.
!                      nintrp - number of interior interpolation points
!                               for the current interval
!                      XINTRP - interior interpolation points
!                      FINTRP - f values at XINTRP points
!                      leftx  - multiplicity of interpolation at XLEFT
!                               = NO. OF DERIVATIVES MATCHED AT XLEFT
!                      FLEFT  - values of f and its derivatives at XLEFT
!                      rightx - multiplicity of interpolation at XRIGHT
!                      fright - values of f and derivatives at XRIGHT
!                      DDTEMP - the array of divided differences
!                      XDD    - THE X VALUES FOR DDTEMP WITH PROPER
!                               multiplicities of XLEFT and XRIGHT
!
!------------------------ Main control program -------------------------
!
!            Check the input and initialize all the parameters
!
call adset(xknots, coefs, kdimen, kmax, ndimen, ierr)
if (ierr.ne.0) return
!
!                  Loop over processing of intervals
!
10 call adtake(ierr)
if (ierr.ne.0) return
call adcomp(f)
!
!                   Check for discarding intervals
!
call adchk
!
!            Put new intervals on stack or discard, update status
!
call adput(xknots, coefs, kdimen, kmax, ndimen, ierr)
if (ierr.ne.0) return
!
!                    Test for normal termination
!
if (nstack.eq.0) return
!
!                Check on the number of knots generated
!
if (knots.lt.maxknt) go to 10
ierr = 1
return
end subroutine adapt1

subroutine adset(xknots, coefs, kdimen, kmax, ndimen, ierr)
implicit none
integer :: ierr, kdimen, kmax, ndimen
integer :: j, k, kboth, kleft, kright, limsm
integer :: leftx, nintrp
integer :: kntdim, level, nbreak, npardm
integer :: ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack
integer :: knots
!
!        ===============================================================
!
! **  THIS PROGRAM CHECKS THE INPUT DATA AND INITIALIZES THE COMPUTATION
!
double precision :: a, accur, b, bleft(20), bright(20), charf, &
&ddtemp(20,20), dsctol, error, errori, factor(20), fintrp(18), &
&fleft(10), fright(10), norm, xbreak(20), xdd(20), xintrp(18), &
&xleft(50), xright(50), buffer
integer :: both, break, dbreak(20), degree, edist, right, rightx, &
&smooth
logical :: discrd
double precision :: xknots(kdimen), coefs(kmax,ndimen)
double precision :: akmax, eps, eps0, km1, ratio, zero, one, two, &
&three, c100
double precision :: dpmpar
!
common /inputz/ a, b, accur, norm, charf, xbreak, bleft, bright, &
&dbreak, degree, smooth, level, edist, nbreak, kntdim, npardm
common /resulz/ error, knots
common /kontrl/ dsctol, errori, xleft, xright, break, both, &
&factor, ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack, right, discrd, buffer
common /comdif/ ddtemp, fintrp, fleft, fright, xdd, xintrp, &
&leftx, nintrp, rightx
!
data eps0/1.d-30/
data zero,one,two,three,c100/0.d0,1.d0,2.d0,3.d0,100.d0/
data kleft, kright, kboth /1, 2, 3/
!
eps = dpmpar(1)
buffer = c100*dmax1(eps,eps0)
!
!         Put data statement items into common variables
!
left = kleft
right = kright
both = kboth
!
! -------- Set current values of limits on dimensions ------------------
!
kntdim = kdimen
npardm = ndimen
maxknt = kntdim
maxstk = 50
maxpar = min0(20,npardm)
maxaux = 20
!
! -------- Check input data --------------------------------------------
!
ierr = 0
if (a.ge.b .or. accur.le.zero) go to 200
if (degree.ge.maxpar .or. 2*smooth.ge.degree) go to 200
akmax = kmax
ratio = (b-a)/(dabs(a)+dabs(b))
if (ratio.le.two*buffer*akmax) go to 210
if (charf.lt.(b-a)/akmax) go to 220
if (norm.ge.zero .and. (norm-one)*(norm-two)*(norm-three).ne.zero) &
&go to 200
if (edist*(edist-1)*(edist-2).ne.0) go to 200
if (nbreak.lt.0 .or. nbreak.gt.maxaux) go to 200
if (nbreak.eq.0) go to 150
!
!         Check the break point data, monotonicity and degree
!
j = 1
if (xbreak(1).lt.a .or. xbreak(nbreak).gt.b) go to 230
if (nbreak.eq.1) go to 110
do 100 j = 2,nbreak
  if (xbreak(j-1).ge.xbreak(j)) go to 230
100 continue
110 limsm = (degree-1)/2
do j=1,nbreak
  if (dbreak(j).lt.0 .or. dbreak(j).gt.limsm) go to 240
end do
!
! -------- Initialization of variables ---------------------------------
!
!             Active interval stack
!
150 nstack = 1
xleft(1) = a
xright(1) = b
!
!             Termination and error values
!
error = zero
dsctol = accur**dabs(norm)
if (edist.eq.0) dsctol = dsctol/(b-a)
if (norm.eq.three) dsctol = accur
!
!             Miscellaneous variables and pointers
!
ibreak = 1
knots = 1
interp = degree + 2 - 2*smooth
xknots(1) = a
npar = degree + 1
!
!             Compute array of NPAR factorials
!
factor(1) = one
factor(2) = one
do k=3,npar
  km1 = k-1
  factor(k) = km1*factor(k-1)
end do
return
!
! -------- Error return ------------------------------------------------
!
200 ierr = -1
return
!
!         A and b are too close
!
210 ierr = -2
return
!
!         charf is too small
!
220 ierr = -3
return
!
!         Break points are not monotonic
!
230 ierr = -4
return
!
!         Bad value in derivative breaks
!
240 ierr = -5
return
end subroutine adset

subroutine adtake(ierr)
implicit none
integer :: ierr
integer :: leftx, nintrp
integer :: kntdim, level, nbreak, npardm
integer :: ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack
integer :: knots
!
!        ===============================================================
!
! **  THIS PROGRAM TAKES AN ACTIVE INTERVAL OFF THE TOP OF THE STACK
!     it also does most of the work of locating and handling
!     break points
!
double precision :: a, accur, b, bleft(20), bright(20), charf, &
&ddtemp(20,20), dsctol, error, errori, factor(20), fintrp(18), &
&fleft(10), fright(10), norm, xbreak(20), xdd(20), xintrp(18), &
&xleft(50), xright(50), buffer
integer :: both, break, dbreak(20), degree, edist, right, rightx, &
&smooth
logical :: discrd
double precision :: dx, ratio
!
common /inputz/ a, b, accur, norm, charf, xbreak, bleft, bright, &
&dbreak, degree, smooth, level, edist, nbreak, kntdim, npardm
common /resulz/ error, knots
common /kontrl/ dsctol, errori, xleft, xright, break, both, &
&factor, ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack, right, discrd, buffer
common /comdif/ ddtemp, fintrp, fleft, fright, xdd, xintrp, &
&leftx, nintrp, rightx
!
!         Check for break point
break = 0
if (nbreak.eq.0 .or. ibreak.gt.nbreak) go to 20
if (xbreak(ibreak).gt.xright(nstack)) go to 20
!
!               Set control variable break, check for location
if (xbreak(ibreak).gt.xleft(nstack)) go to 10
break = left
if (ibreak.eq.nbreak) go to 20
!             Check for second break point in this interval
if (xbreak(ibreak+1).ge.xright(nstack)) go to 20
!                 Next break is inside interval, split top interval
break = both
!                  Check exceeding stack limit. If so, stop
if (nstack.eq.maxstk) go to 30
!                     Dont split very small intervals, stop instead
dx = xbreak(ibreak+1) - xleft(nstack)
ratio = dx/(dabs(a)+dabs(b))
if (ratio.le.buffer) go to 30
nstack = nstack + 1
xleft(nstack) = xleft(nstack-1)
xright(nstack) = xbreak(ibreak+1)
xleft(nstack-1) = xright(nstack)
go to 20
!
10 break = right
!                 Check to see if break is already at right end point
if (xbreak(ibreak).ge.xright(nstack)) go to 20
!                 The break is inside interval, split top interval
!                  check exceeding stack limit. If so, stop
if (nstack.eq.maxstk) go to 30
!                     Dont split very small intervals, stop instead
dx = xbreak(ibreak) - xleft(nstack)
ratio = dx/(dabs(a)+dabs(b))
if (ratio.le.buffer) go to 30
nstack = nstack + 1
xleft(nstack) = xleft(nstack-1)
xright(nstack) = xbreak(ibreak)
xleft(nstack-1) = xright(nstack)
20 continue
return
!
!        A break point is in the interior of the top subinterval of
!        the stack.  The subinterval cannot be partitioned either
!        because the stack is full, or because partitioning leads to
!        too small an interval.
!
30 ierr = 2
return
end subroutine adtake

subroutine adcomp(f)
implicit none
integer :: j
integer :: leftx, nintrp
integer :: kntdim, level, nbreak, npardm
integer :: ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack
integer :: knots
!
!        ===============================================================
!
! **  THIS PROGRAM COMPUTES THE PIECEWISE POLYNOMIAL APPROXIMATION ON
!     the current interval. It also estimates the error
!
double precision :: a, accur, b, bleft(20), bright(20), charf, &
&ddtemp(20,20), dsctol, error, errori, factor(20), fintrp(18), &
&fleft(10), fright(10), norm, xbreak(20), xdd(20), xintrp(18), &
&xleft(50), xright(50), buffer
integer :: both, break, dbreak(20), degree, edist, right, rightx, &
&smooth
logical :: discrd
double precision :: absc(4), aj, dx, fdervl(9), fdervr(9), &
&fdumb(9), r, wgts(4)
double precision :: errint, f, polydd
external f, polydd
!
common /inputz/ a, b, accur, norm, charf, xbreak, bleft, bright, &
&dbreak, degree, smooth, level, edist, nbreak, kntdim, npardm
common /resulz/ error, knots
common /kontrl/ dsctol, errori, xleft, xright, break, both, &
&factor, ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack, right, discrd, buffer
common /comdif/ ddtemp, fintrp, fleft, fright, xdd, xintrp, &
&leftx, nintrp, rightx
!
equivalence (fleft(2),fdervl(1)), (fright(2),fdervr(1))
data r/1.5d0/
!
!     Thirty digit values for the Gauss integration constants
!                    .861136311594052575223946488893D0
!                    .339981043584856264802665759103D0
!                    .347854845137453857373063949222D0
!                    .652145154862546142626936050778D0
!
!     ***** THE ABSISSAE AND WEIGHTS ARE GIVEN BELOW TO 30 DIGITS.
!           The parameter eps0 in adset specifies the accuracy of
!           these constants. If the accuracy is changed to K decimal
!           DIGITS THEN SET EPS0 = 10**(-K).
!
data absc(1) /-.861136311594052575223946488893d0 /
data absc(2) /-.339981043584856264802665759103d0 /
data absc(3) / .339981043584856264802665759103d0 /
data absc(4) / .861136311594052575223946488893d0 /
data wgts(1) / .347854845137453857373063949222d0 /
data wgts(2) / .652145154862546142626936050778d0 /
data wgts(3) / .652145154862546142626936050778d0 /
data wgts(4) / .347854845137453857373063949222d0 /
!
!             Compute interpolation information
nintrp = degree - 2*smooth - 1
!
!          Increase number of interpolation points if break points are
!          specified with fewer derivatives than smooth
if (break.eq.left .or. break.eq.right) nintrp = nintrp + smooth - &
&dbreak(ibreak)
if (break.eq.both) nintrp = nintrp + 2*smooth - dbreak(ibreak) - &
&dbreak(ibreak+1)
if (nintrp.eq.0) go to 20
!
!             Generate equal spaced interpolation points
aj = nintrp+1
dx = (xright(nstack)-xleft(nstack))/aj
do 10 j = 1,nintrp
  aj = j
  xintrp(j) = xleft(nstack) + aj*dx
10 continue
!
!             Get left and right f-values, put f-value in first element
!             of arrays FLEFT and fright.  Get derivatives back as
!             other elements via the subarrays fdervl and fdervr.
20 fleft(1) = f(xleft(nstack),fdervl)
fright(1) = f(xright(nstack),fdervr)
leftx = smooth + 1
rightx = leftx
!            Get f-values at other interpolation points, if any
if (nintrp.eq.0) go to 40
do j=1,nintrp
  fintrp(j) = f(xintrp(j),fdumb)
end do
!
!          Check for break points, modify values if necessary
40 continue
if (break.ne.left) go to 50
leftx = dbreak(ibreak) + 1
fleft(leftx) = bright(ibreak)
50 if (break.ne.right) go to 60
rightx = dbreak(ibreak) + 1
fright(rightx) = bleft(ibreak)
60 if (break.ne.both) go to 70
leftx = dbreak(ibreak) + 1
rightx = dbreak(ibreak+1) + 1
fleft(leftx) = bright(ibreak)
fright(rightx) = bleft(ibreak+1)
70 continue
!
!           Compute divided differences, Newton form of polynomial
call newton(leftx, rightx, nintrp)
!
!         Compute norm of error of this appromimation using four pts
!         add 50 percent fudge factor
errori = errint(f,polydd,xleft(nstack),xright(nstack),absc,wgts)
errori = r*errori
return
end subroutine adcomp

double precision function errint(f, fit, aaa, bbb, points, weight)
implicit none
integer :: j
integer :: leftx, nintrp
integer :: kntdim, level, nbreak, npardm
integer :: ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack
integer :: knots
!
!        ===============================================================
!
! **  THIS FUNCTION DOES A FOUR POINT INTEGRATION RULE FOR THE
!     absolute value of the difference of two FUNCTIONS( f AND FIT )
!                   abs( f(X) - fit(X) )**NORM
!     the integration uses the points and weights given and scaled
!     from (-1,1) to (aaa,bbb)
!
double precision :: a, accur, b, bleft(20), bright(20), charf, &
&ddtemp(20,20), dsctol, error, errori, factor(20), fintrp(18), &
&fleft(10), fright(10), norm, xbreak(20), xdd(20), xintrp(18), &
&xleft(50), xright(50), buffer
integer :: both, break, dbreak(20), degree, edist, right, rightx, &
&smooth
logical :: discrd
double precision :: aaa, abmid, ba, bbb, fdumb(9), fit, p, pj, &
&points(*), weight(*), er, f1, f2, two, three
double precision :: f
external f, fit
!
common /inputz/ a, b, accur, norm, charf, xbreak, bleft, bright, &
&dbreak, degree, smooth, level, edist, nbreak, kntdim, npardm
common /resulz/ error, knots
common /kontrl/ dsctol, errori, xleft, xright, break, both, &
&factor, ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack, right, discrd, buffer
common /comdif/ ddtemp, fintrp, fleft, fright, xdd, xintrp, &
&leftx, nintrp, rightx
!
data two,three/2.0d0,3.0d0/
!
!         COMPUTE MIDPOINT = abmid AND HALF LENGTH = ba OF INTERVAL
abmid = (aaa+bbb)/two
ba = (bbb-aaa)/two
pj = abmid + ba*points(1)
!
!         Test for Tchebycheff (minimax) norm which uses special code
if (norm.eq.three) go to 20
!
!         Have general LP norm or least squares or least deviations
p = dabs(norm)
!              Initialize the quadrature rule
errint = dabs(f(pj,fdumb)-fit(pj))**p*weight(1)
!              Loop through remaining points
do 10 j = 2,4
  pj = abmid + ba*points(j)
  f1 = f(pj,fdumb)
  f2 = fit(pj)
  er = dabs(f1-f2)**p
  errint = errint + dabs(f(pj,fdumb)-fit(pj))**p*weight(j)
10 continue
errint = errint*ba
go to 40
!
!         Tchebycheff norm
20 continue
!             Find max error on points
!               initialize
errint = dabs(f(pj,fdumb)-fit(pj))
!              Loop through the remaining points
do j=2,4
  pj = abmid + ba*points(j)
  errint = dmax1(errint,dabs(f(pj,fdumb)-fit(pj)))
end do
40 continue
return
end function errint

subroutine newton(nl, nr, ni)
implicit none
integer :: ni, nl, nr
integer :: idif, ipt, ipt2, j, k, nddx, nl1, nl2, nr1, nr2, nrl, &
&nrlj, nrlj1
integer :: leftx, nintrp
integer :: kntdim, level, nbreak, npardm
integer :: ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack
integer :: knots
!
!        ===============================================================
!
! **  THIS PROGRAM COMPUTES THE DIVIDED DIFFERENCES ARRAY AS FOLLOWS
!         nl COALESCED POINTS ON left   - DERIV VALUES IN FLEFT
!         nr COALESCED POINTS ON right  -   -      -    - FRIGHT
!         ni DISTINCT  POINTS INBETWEEN - FNCTN    -    - FINTRP
!
!     THE POINTS ARE ORDERED XL = XLEFT (NSTACK)
!                            xr = xright(nstack)
!                            XINTRP ARRAY
!
!         Layout of the DDTEMP divided difference array
!
!     nl=6    llllll****ii
!     nr=4    LLLLL****II     L = FIRST TRIANGLE
!     ni=2    llll****ii
!             LLL****II       R = SECOND TRIANGLE
!             LL****II
!             L****II         * = FILL BETWEEN TRIANGLES
!             RRRRII
!             RRRII           I = COMPLETION FOR INTERPOLATION POINTS
!             RRII
!             RII       idif = HORIZONTAL COORD. = DIFFERENCE ORDER
!             II        ipt  = VERTICAL COORD. ASSOCIATED WITH POINTS
!             I
!
!
double precision :: a, accur, b, bleft(20), bright(20), charf, &
&ddtemp(20,20), dsctol, error, errori, factor(20), fintrp(18), &
&fleft(10), fright(10), norm, xbreak(20), xdd(20), xintrp(18), &
&xleft(50), xright(50), buffer
integer :: both, break, dbreak(20), degree, edist, right, rightx, &
&smooth
logical :: discrd
double precision :: difff, diffx
!
common /inputz/ a, b, accur, norm, charf, xbreak, bleft, bright, &
&dbreak, degree, smooth, level, edist, nbreak, kntdim, npardm
common /resulz/ error, knots
common /kontrl/ dsctol, errori, xleft, xright, break, both, &
&factor, ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack, right, discrd, buffer
common /comdif/ ddtemp, fintrp, fleft, fright, xdd, xintrp, &
&leftx, nintrp, rightx
!
!                 Main calculation of divided differences
!         define a few short constants
nl1 = nl - 1
nl2 = nl + 1
nr1 = nr - 1
nr2 = nr + 1
nrl = nr + nl
!
!         PUT X-VALUES IN A SINGLE ARRAY WITH nddx = nl+nr+ni POINTS
do 10 nddx = 1,nl
  xdd(nddx) = xleft(nstack)
10 continue
nddx = nl
do 20 k = 1,nr
  nddx = nddx + 1
  xdd(nddx) = xright(nstack)
20 continue
!            Check if there are any interpolation points to add to XDD
if (ni.eq.0) go to 40
do k=1,ni
  nddx = nddx + 1
  xdd(nddx) = xintrp(k)
end do
!
!           Fill border of first triangle - size nl.
40 continue
!         Top border
do 50 idif = 1,nl
  ddtemp(idif,1) = fleft(idif)/factor(idif)
50 continue
if (nl1.eq.0) go to 70
!                   Bottom border
do idif=1,nl1
  ipt = nl2 - idif
  ddtemp(idif,ipt) = ddtemp(idif,1)
end do
!
!          Fill border of second triangle - size nr
70 continue
!         Top border
do idif=1,nr
  ddtemp(idif,nl2) = fright(idif)/factor(idif)
end do
if (nrl.eq.nl2) go to 100
!                   Bottom border
do idif=1,nr1
  ipt = nrl + 1 - idif
  ddtemp(idif,ipt) = ddtemp(idif,nl2)
end do
!
!           Fill parallogram between the two triangles just filled
!          fill entries parallel to bottom of first triangle
100 continue
!
!         Loop stepping along top side of second triangle
do j=2,nr2
  idif = j
!             Loop stepping parallel to bottom side of first triangle
  do k=2,nl2
    ipt = nl + 2 - k
    difff = ddtemp(idif-1,ipt+1) - ddtemp(idif-1,ipt)
    ipt2 = ipt - 1 + idif
    diffx = xdd(ipt2) - xdd(ipt)
    ddtemp(idif,ipt) = difff/diffx
    idif = idif + 1
  end do
end do
!
!         Fill in bottom diagonals for interpolation points, if any
if (ni.eq.0) go to 150
!         Loop through the interpolatation points
do j=1,ni
  idif = 2
  nrlj = nrl + j
  ddtemp(1,nrlj) = fintrp(j)
!         Loop through the differences (idif index)
  nrlj1 = nrlj - 1
  do k=1,nrlj1
    ipt = nrlj - k
    difff = ddtemp(idif-1,ipt+1) - ddtemp(idif-1,ipt)
    diffx = xdd(nrlj) - xdd(ipt)
    ddtemp(idif,ipt) = difff/diffx
    idif = idif + 1
  end do
end do
150 continue
return
end subroutine newton

double precision function polydd(x)
implicit none
integer :: j, k
integer :: leftx, nintrp
integer :: kntdim, level, nbreak, npardm
integer :: ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack
integer :: knots
!
!        ===============================================================
!
! **  THIS FUNCTION EVALUATES THE CURRENT POLYNOMIAL PIECE REPRESENTED
!     by the divided differences DDTEMP on the point set XDD.
!
double precision :: a, accur, b, bleft(20), bright(20), charf, &
&ddtemp(20,20), dsctol, error, errori, factor(20), fintrp(18), &
&fleft(10), fright(10), norm, xbreak(20), xdd(20), xintrp(18), &
&xleft(50), xright(50), buffer
integer :: both, break, dbreak(20), degree, edist, right, rightx, &
&smooth
logical :: discrd
double precision :: x
!
common /inputz/ a, b, accur, norm, charf, xbreak, bleft, bright, &
&dbreak, degree, smooth, level, edist, nbreak, kntdim, npardm
common /resulz/ error, knots
common /kontrl/ dsctol, errori, xleft, xright, break, both, &
&factor, ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack, right, discrd, buffer
common /comdif/ ddtemp, fintrp, fleft, fright, xdd, xintrp, &
&leftx, nintrp, rightx
!
polydd = ddtemp(degree+1,1)
do 10 k = 1,degree
  j = degree + 1 - k
  polydd = ddtemp(j,1) + (x-xdd(j))*polydd
10 continue
return
end function polydd

subroutine adchk
implicit none
integer :: leftx, nintrp
integer :: kntdim, level, nbreak, npardm
integer :: ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack
integer :: knots
!
!        ===============================================================
!
! **  THIS PROGRAM CHECKS FOR DISCARDING INTERVAL, APPLIES VARIOUS
!     tests about discarding involving edist and charf.
!
double precision :: a, accur, b, bleft(20), bright(20), charf, &
&ddtemp(20,20), dsctol, error, errori, factor(20), fintrp(18), &
&fleft(10), fright(10), norm, xbreak(20), xdd(20), xintrp(18), &
&xleft(50), xright(50), buffer
integer :: both, break, dbreak(20), degree, edist, right, rightx, &
&smooth
logical :: discrd
double precision :: aknots, dtest, dx, three, five
!
common /inputz/ a, b, accur, norm, charf, xbreak, bleft, bright, &
&dbreak, degree, smooth, level, edist, nbreak, kntdim, npardm
common /resulz/ error, knots
common /kontrl/ dsctol, errori, xleft, xright, break, both, &
&factor, ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack, right, discrd, buffer
common /comdif/ ddtemp, fintrp, fleft, fright, xdd, xintrp, &
&leftx, nintrp, rightx
!
data three,five/3.0d0,5.0d0/
!
discrd = .false.
dx = xright(nstack) - xleft(nstack)
if (dx.gt.charf) return
!
!         Compute dtest for the local error criterion
!
if (norm.eq.three) go to 30
if (edist-1) 10,20,30
10 dtest = dx*dsctol
go to 40
!         For the approximate fixed error distribution type we estimate
!         the final number of knots BY( LIMITING IT A LITTLE )
!             (NSTACK+knots+2)((b-a)/(XRIGHT-a))
20 aknots = nstack+knots+2
dtest = dsctol/(aknots*dmin1((b-a)/(xright(nstack)-a),five))
go to 40
30 dtest = dsctol
!
!             Check for discard of interval
!
40 if (errori.le.dtest) discrd = .true.
return
end subroutine adchk

subroutine adput(xknots, coefs, kdimen, kmax, ndimen, ierr)
implicit none
integer :: ierr, kdimen, kmax, ndimen
integer :: k
integer :: leftx, nintrp
integer :: kntdim, level, nbreak, npardm
integer :: ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack
integer :: knots
!
!        ===============================================================
! **  THIS PROGRAM PUTS INTERVALS ON THE STACK OR DISCARDS THEM.
!     When an interval is discarded a new knot is found. Then this
!     program updates the error estimate, the XKNOT array, transforms
!     the polynomial to the power form and put the coefficients into
!     the array coefs.  It also checks for passing break points
!
double precision :: a, accur, b, bleft(20), bright(20), charf, &
&ddtemp(20,20), dsctol, error, errori, factor(20), fintrp(18), &
&fleft(10), fright(10), norm, xbreak(20), xdd(20), xintrp(18), &
&xleft(50), xright(50), buffer
integer :: both, break, dbreak(20), degree, edist, right, rightx, &
&smooth
logical :: discrd
double precision :: xknots(kdimen), coefs(kmax,ndimen)
double precision :: dx, half, one, powers(20), p, ratio, three
!
common /inputz/ a, b, accur, norm, charf, xbreak, bleft, bright, &
&dbreak, degree, smooth, level, edist, nbreak, kntdim, npardm
common /resulz/ error, knots
common /kontrl/ dsctol, errori, xleft, xright, break, both, &
&factor, ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack, right, discrd, buffer
common /comdif/ ddtemp, fintrp, fleft, fright, xdd, xintrp, &
&leftx, nintrp, rightx
!
data half,one,three/.5d0,1.d0,3.d0/
!
!            Check for discarding the interval
if (discrd) go to 30
!
!         Subdivide interval and place on stack
if (nstack.lt.maxstk) go to 10
!             Fatal error, exceeded active stack size
ierr = 4
dx = xright(nstack)-xleft(nstack)
if (dx.gt.charf) ierr = 3
return
!
10 dx = (xright(nstack)-xleft(nstack))*half
!              Check for small intervals
ratio = dx/(dabs(a)+dabs(b))
if (ratio.gt.buffer) go to 20
ierr = 4
return
!
20 nstack = nstack + 1
xleft(nstack) = xleft(nstack-1)
xleft(nstack-1) = xright(nstack-1) - dx
xright(nstack) = xleft(nstack-1)
return
!
!            Discard interval, update global error, xknots and coefs
30 p = dabs(norm)
if (norm.eq.three) error = dmax1(error,errori)
if (norm.ne.three) error = (error**p+errori)**(one/p)
!
!              Check for passing break points
if (break.eq.left .or. break.eq.both) ibreak = ibreak + 1
!
!             Transform representation of polynomial from divided
!             differences to powers of X with origin at xknots (knots)
call adtran(ddtemp, powers)
!
!             Put coefs into the main array
do k=1,npar
  coefs(knots,k) = powers(k)
end do
!            Put the new knots in xknots
knots = knots + 1
xknots(knots) = xright(nstack)
nstack = nstack - 1
return
end subroutine adput

subroutine adtran(d, powers)
implicit none
integer :: i, ii, j, k, khi, koef, l, ltop, ni, ni1, nl, nr, nri, &
&nri1, nrl, nrli, nrlk
integer :: leftx, nintrp
integer :: kntdim, level, nbreak, npardm
integer :: ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack
integer :: knots
!
!        ===============================================================
!
! **  THIS PROGRAM CONVERTS POLYNOMIAL REPRESENTATION FROM DIVIDED
!     difference to power form.  There are coalesced points on each
!     END OF THE INTERVAL (xl,xr) = (XLEFT(NSTACK),XRIGHT(NSTACK)).
!     The number coalesced at each end is leftx and rightx.
!     And there are nintrp other pts XINTRP(k)  inbetween them.
!     See subroutine newton for more details
!
double precision :: a, accur, b, bleft(20), bright(20), charf, &
&ddtemp(20,20), dsctol, error, errori, factor(20), fintrp(18), &
&fleft(10), fright(10), norm, xbreak(20), xdd(20), xintrp(18), &
&xleft(50), xright(50), buffer
integer :: both, break, dbreak(20), degree, edist, right, rightx, &
&smooth
logical :: discrd
double precision :: d(20,*), powers(*), shift, xl, xr, xtemp(20)
!
common /inputz/ a, b, accur, norm, charf, xbreak, bleft, bright, &
&dbreak, degree, smooth, level, edist, nbreak, kntdim, npardm
common /resulz/ error, knots
common /kontrl/ dsctol, errori, xleft, xright, break, both, &
&factor, ibreak, interp, left, maxaux, maxknt, maxpar, maxstk, &
&npar, nstack, right, discrd, buffer
common /comdif/ ddtemp, fintrp, fleft, fright, xdd, xintrp, &
&leftx, nintrp, rightx
!
!         Set some short local variable names
!
xl = xleft(nstack)
xr = xright(nstack)
nl = leftx
nr = rightx
ni = nintrp
nrl = nr + nl
nri = nr + ni
nri1 = nri - 1
nrli = nrl + ni
!
!         STARTING REPRESENTATION IS (ASSUMING xl = 0 )
!
!    d(1) +d(2)X +d(3)X**2 + --- +d(nl)X**(nl-1)
!   +(X**nl)*( d(nl+1)(+d(nl+2)(X-xr)**2 + --- +d(nl+nr)*(X-xr)**(nr-1)
!        *((X-xr)**nr)*(d(nl+nr+1) + d(nl+nr+2)*(X-XINTRP(1))
!                      +d(nl+nr+3)*(X-XINTRP(1))(X-XINTRP(2)) + ---))
!
!         Strategy is to first convert the part from the interp. Pts.
!         To poly in (X-xr).  This poly then has origin shifted to xl.
!
!     The conversion of the interp part is done explicitly for degree
!     two or less and done by synthetic division for higher degrees
!
!   D1 + D2(X-X1) +D3(X**2-(X1+X2)X +X1*X2)
!
!     The resulting coefficients are put in the array powers
!
if (ni.eq.0) go to 100
!
!             Build up the polynomial for the interpolation points
!
!         Use special formulas for ni less than 3
if (ni.eq.1) go to 10
if (ni.eq.2) go to 20
go to 30
10 powers(1) = d(nrl+1,1)
go to 80
20 powers(1) = d(nrl+1,1) + (xr-xintrp(1))*d(nrl+2,1)
powers(2) = d(nrl+2,1)
go to 80
!
!         Conversion by repeated synthetic division
30 ni1 = ni - 1
!         Initialize the powers and xtemp arrays
do k=1,ni
  xtemp(k) = xintrp(k)
  nrlk = nrl + k
  powers(k) = d(nrlk,1)
end do
!
!         Do the repeated synthetic division to replace the xtemp
!         = XINTRP POINTS OF THE NEWTON EXPANSION BY THE xr POINTS
do 70 k = 1,ni1
!              powers(ni) is fixed and set above
  do 50 ii = 1,ni1
    i = ni - ii
    powers(i) = powers(i) + (xr-xtemp(i))*powers(i+1)
50 continue
!              Shift the Newton expansion pts. Up, put in one more xr
  do ii=1,ni1
    i = ni - ii
    xtemp(i+1) = xtemp(i)
  end do
  xtemp(1) = xr
70 continue
80 continue
!             Shift the coefficients to the top of the powers array
do k=1,ni
  l = ni + 1 - k
  ltop = l + nrl
  powers(ltop) = powers(l)
end do
!
!             Have the interpolation PT. COEFS. In the array powers
100 continue
!             Put the remaining divided diffs into the powers array
do j=1,nrl
  powers(j) = d(j,1)
end do
!
!         Transform the origin of the polynomial from xr to xl
!         we use repeated synthetic division
if (nri.eq.1) go to 140
shift = xr - xl
khi = nri1
!             Loop through the coefficients
do j=2,nri
!                   Synthetic division loop
  do k=1,khi
    koef = nrli - k
    powers(koef) = powers(koef) - shift*powers(koef+1)
  end do
  khi = khi - 1
end do
140 continue
!     The coefficients are now of the power form with origin xl
return
end subroutine adtran

subroutine cpsc (f, z, n, ic, tol, r, rs, err)
implicit none
integer, intent(in) :: ic, n
real, intent(inout) :: err(n), r
real, intent(in) :: tol
integer :: i, ia, inr, ip(32), iq, is, it, iw(7), ix, j, jn, kl, &
&km, kn, l, l1, l2, lf, ln, m, np, nr
real :: ang, b, c(4), cm, cp, ct, cx, ep6, eps, eps0, fac, fact, &
&fc(3), pi, r1, ra, re, sc(4), sf, sp, sr
real :: spmpar
!
!  Evaluation of complex power series coefficients or derivatives.
!
!  *** INPUT PARAMETERS ***
!    f   COMPLEX FUNCTION, OF WHICH THE COEFFICIENTS OR DERIVATIVES
!        are sought. This function must be declared external in the
!        calling program.
!    z   COMPLEX POINT AROUND WHICH f IS TO BE EXPANDED OR AT WHICH
!        derivatives are to be evaluated.
!    n   INTEGER, NUMBER OF COEFFICIENTS OR DERIVATIVES WANTED.
!        n must be GE 1 and LE 51.
!    ic  selects between power series coefficients and derivatives.
!        ic .EQ. 0   ROUTINE RETURNS POWER SERIES COEFFICIENTS IN rs.
!        ic .NE. 0   ROUTINE RETURNS DERIVATIVES IN rs.
!    tol estimated relative accuracy of f. it is assumed that tol
!        IS NONNEGATIVE. IF tol = 0 THEN f IS ASSUMED TO BE CORRECT
!        to machine accuracy.
!
!  *** INPUT AND OUTPUT PARAMETER ***
!    r   INITIAL RADIUS USED IN SEARCH FOR OPTIMAL RADIUS. THE RESULTING
!        radius is left in r. the provided guess may be in error with at
!        most a factor of 3.E4 .
!
!  *** OUTPUT PARAMETERS ***
!    rs  complex array rs(n) containing the n first
!        coefficients (corresponding to the powers 0 to n-1) or deriva-
!        tives (orders 0 to n-1).
!    err real array err(n) containing absolute error estimates for the
!        numbers in rs.
!
complex :: f, a(64), v
complex, intent(inout) :: rs(n)
complex :: rt(51,3), fv(6), u, w, t, z, rv(3), rq, s, xk, mult, co
!
!  List of the variables initialized in the data statement below.
!   iw   2**( 0 , 1 , 2 , 3 , 4 , 5 , 6 ) .
!   ip   PERMUTATION CONSTANTS FOR THE FFT.
!   rv   CONSTANTS FOR THE LAURENT SERIES TEST.
!
data iw(1),iw(2),iw(3),iw(4),iw(5),iw(6),iw(7)/1,2,4,8,16,32,64/
data ip( 1),ip( 2),ip( 3),ip( 4),ip( 5),ip( 6),ip( 7),ip( 8), &
&ip( 9),ip(10),ip(11),ip(12),ip(13),ip(14),ip(15),ip(16), &
&ip(17),ip(18),ip(19),ip(20),ip(21),ip(22),ip(23),ip(24), &
&ip(25),ip(26),ip(27),ip(28),ip(29),ip(30),ip(31),ip(32)/ &
&64,32,48,16,56,24,40,8,60,28,44,12,52,20,36,4,62,30,46,14, &
&54,22,38,6,58,26,42,10,50,18,34,2/
data rv(1)/(-.4,.3)/, rv(2)/(.7,.2)/, rv(3)/(.02,-.06)/
!
!  Statement function for multiplication of a complex number
!  by a real number.
!
mult(re,co) = cmplx(re*real(co),re*aimag(co))
!
!  -------------------
!
!  ****** eps0 IS A MACHINE DEPENDENT CONSTANT. eps0 IS THE
!         SMALLEST NUMBER SUCH THAT 1 + eps0 .GT. 1.
!
              eps0 = spmpar(1)
!
!  -------------------
!
!  Initialization.
!
eps = amax1(eps0,tol)
sc(1) = .125
c(1) = eps**(1./28.)
ep6 = c(1)**6
pi = 4.0*atan(1.0)
fv(1) = (-1.,0.)
fv(2) = (0.,-1.)
r1 = sqrt(0.5)
ra = 1.0/r1
fv(3) = cmplx(r1,-r1)
do 10 i = 2,4
  sc(i) = .5*sc(i-1)
  c(i) = sqrt(c(i-1))
  ang = pi*sc(i-1)
10 fv(i+2) = cmplx(cos(ang),-sin(ang))
!
!  Start execution.
!
if (n .gt. 51 .or. n .lt. 1) go to 260
l2 = 1
lf = 0
np = 0
m = 0
nr = -1
!
!  Find if A FFT over 8, 16, 32, or 64 points should be used.
!
kl = 1
if (n .gt. 6) kl = 2
if (n .gt. 12) kl = 3
if (n .gt. 25) kl = 4
km = kl + 2
kn = 7 - km
ix = iw(km + 1)
is = iw(kn)
30 v = cmplx(r,0.0)
!
!  Function values of f are stored ready permutated for the FFT.
!
do 40 i = is,32,is
  iq = ip(i)
  v = v*fv(km)
  a(iq) = f(z + v)
40 a(iq - 1) = f(z - v)
ln = 2
jn = 1
!
!  The loop  do 70 ... constitutes the FFT.
!
do 70 l = 1,km
  u = (1.,0.)
  w = fv(l)
  do 60 j = 1,jn
    do 50 i = j,ix,ln
      it = i + jn
      t = a(it)*u
      a(it) = a(i) - t
50 a(i) = a(i) + t
60 u = u*w
  ln = ln + ln
70 jn = jn + jn
cx = 0.0
b = 1.0
!
!  Test on how fast the coefficients obtained decrease.
!
do 80 i = 1,ix
  ct = cabs(a(i))/b
  if (ct .lt. cx) go to 80
  cx = ct
  inr = i
80 b = b*c(kl)
if (m .le. 1) go to 100
!
!  Estimate of the rounding error level for the last radius.
!
err(1) = cx*eps
do 90 i = 2,n
90 err(i) = err(i-1)/r
100 sf = sc(kl)
do 110 i = 1,ix
  a(i) = mult(sf,a(i))
110 sf = sf/r
l1 = l2
l2 = 1
if (inr .gt. iw(km)) go to 150
if (lf .eq. 1) go to 140
!
!  Test if the series is a Taylor or a Laurent series.
!
sr = 0.0
sp = 0.0
do 130 j = 1,3
  rq = mult(r,rv(j))
  s = a(ix)
  do 120 i = 2,ix
    ia = ix + 1 - i
120 s = s*rq + a(ia)
  cp = cabs(s)
  if (cp .gt. sp) sp = cp
  cm = cabs(s - f(z + rq))
130 if (cm .gt. sr) sr = cm
if (sr .gt. 1.e-3*sp) go to 150
lf = 1
140 l2 = -1
!
!  Determination of the next radius to be used.
!
150 if (nr .ge. 0) go to 160
  fact = 2.0
  if (l2 .eq. 1) fact = 0.5
  l1 = l2
  nr = 0
160 if (l1 .ne. l2) go to 180
  if (nr .gt. 0) go to 170
    np = np + 1
    if (np-15) 190,190,260
170 fact = 1.0/fact
180 fact = 1.0/sqrt(fact)
nr = nr + 1
190 r = r*fact
m = nr - kl - 1
if (m .le. 0) go to 30
!
!  The results for the last three radii are stored.
!
do 200 i = 1,n
200 rt(i,m) = a(i)
if (m .eq. 1) go to 220
!
!  Extrapolation.
!
do 210 i = 1,n
  xk = rt(i,m-1) - rt(i,m)
210 rt(i,m-1) = rt(i,m) - mult(fc(m-1),xk)
if (m .eq. 3) go to 230
!
!  Calculation of the extrapolation constants.
!
220 fc(m) = 1.5 + sign(.5,fact-1.)
if (m .eq. 2) fc(m) = fc(m) + ra
if (fact .gt. 1.0) fc(m) = -fc(m)
go to 30
230 fc(3) = fc(1)*fc(2)/(fc(1) + fc(2) + 1.0)
!
!  Final extrapolation and error estimate.
!
do 240 i = 1,n
  xk = rt(i,1) - rt(i,2)
  err(i) = err(i) + ep6*cabs(xk)
240 rs(i) = rt(i,2) - mult(fc(3),xk)
!
!  Multiply power series coefficients and error estimate by factorials
!  if derivatives wanted.
!
if (ic .eq. 0) return
fac = 0.0
fact = 1.0
do 250 i = 1,n
  rs(i) = mult(fact,rs(i))
  err(i) = fact*err(i)
  fac = fac + 1.0
250 fact = fact*fac
return
!
!  Error return.
!
260 do 270 i = 1,n
  rs(i) = (0.,0.)
270 err(i) = 1.e10
return
end subroutine cpsc

subroutine dcpsc (fun, x, y, n, ic, tol, r, rs1, rs2, err)
implicit none
integer, intent(in) :: ic, n
integer :: i, ia, inr, iq, is, it, ix, j, jn, kl, km, kn, l, l1, &
&l2, lf, ln, m, mm1, np, nr
double precision :: x, y
double precision, intent(in) :: tol
double precision, intent(inout) :: r, rs1(n), rs2(n), err(n)
!
!  Evaluation of complex power series coefficients or derivatives.
!
!  *** INPUT PARAMETERS ***
!    fun subroutine which computes the complex function F for which
!        the coefficients or derivatives are sought. We write
!                   call fun(u1,u2,w1,w2)
!        WHEN W = F(U) IS TO BE COMPUTED FOR THE COMPLEX ARGUMENT U.
!        Here U1 and U2 are the real and imaginary parts of U, and W1
!        and W2 are the real and imaginary parts of W.  U1,U2,W1,W2
!        have double precision values. The subroutine FUN must be
!        declared in the calling program to be of type external.
!    x   REAL PART OF THE COMPLEX POINT AROUND WHICH F IS TO BE
!        expanded or at which its derivatives are to be computed.
!    y   IMAGINARY PART OF THE COMPLEX POINT AROUND WHICH F IS TO BE
!        expanded or at which its derivatives are to be computed.
!    n   INTEGER, NUMBER OF COEFFICIENTS OR DERIVATIVES WANTED.
!        n must be GE 1 and LE 51.
!    ic  selects between power series coefficients and derivatives.
!        ic .EQ. 0   ROUTINE RETURNS POWER SERIES COEFFICIENTS IN
!                    rs1 AND rs2.
!        ic .NE. 0   ROUTINE RETURNS DERIVATIVES IN rs1 AND rs2.
!    tol estimated relative accuracy of fun. It is assumed that tol
!        IS NONNEGATIVE. IF tol = 0 THEN FUN IS ASSUMED TO BE CORRECT
!        to machine accuracy.
!
!  *** INPUT AND OUTPUT PARAMETER ***
!    r   INITIAL RADIUS USED IN SEARCH FOR OPTIMAL RADIUS. THE RESULTING
!        radius is left in r. the provided guess may be in error with at
!        most a factor of 3.E4 .
!
!  *** OUTPUT PARAMETERS ***
!    rs1 array rs1(n) containing the real parts of the first n complex
!        coefficients (corresponding to the powers 0 to n-1) or deriva-
!        tives (orders 0 to n-1).
!    rs2 array rs2(n) containing the imaginary parts of the first n
!        coefficients (corresponding to the powers 0 to n-1) or deriva-
!        tives (orders 0 to n-1).
!    err real array err(n) containing absolute error estimates for the
!        COMPLEX NUMBERS WHOSE REAL AND IMAGINARY PARTS ARE IN rs1,rs2.
!
integer :: ip(32), iw(7)
double precision :: ang, b, cm, cp, ct, cx, eps, eps0, ep6, fac, &
&fact, pi, ra, r1, s, sf, sp, sr, t, u, v, w
double precision :: c(4), fc(3), sc(4)
double precision :: a1(64), a2(64), fv1(6), fv2(6), rt1(51,3), &
&rt2(51,3), rv1(3), rv2(3)
double precision :: dcpabs, dpmpar
!
!  List of the variables initialized in the data statement below.
!   iw   2**( 0 , 1 , 2 , 3 , 4 , 5 , 6 ) .
!   ip   PERMUTATION CONSTANTS FOR THE FFT.
!   RV1  real parts of the constants for the Laurent series test.
!   RV2  imaginary parts of the constants for the Laurent series test.
!
data iw(1),iw(2),iw(3),iw(4),iw(5),iw(6),iw(7)/1,2,4,8,16,32,64/
data ip( 1),ip( 2),ip( 3),ip( 4),ip( 5),ip( 6),ip( 7),ip( 8), &
&ip( 9),ip(10),ip(11),ip(12),ip(13),ip(14),ip(15),ip(16), &
&ip(17),ip(18),ip(19),ip(20),ip(21),ip(22),ip(23),ip(24), &
&ip(25),ip(26),ip(27),ip(28),ip(29),ip(30),ip(31),ip(32)/ &
&64,32,48,16,56,24,40,8,60,28,44,12,52,20,36,4,62,30,46,14, &
&54,22,38,6,58,26,42,10,50,18,34,2/
data rv1(1)/-.4d0/, rv2(1)/.3d0/, &
&rv1(2)/ .7d0/, rv2(2)/.2d0/, &
&rv1(3)/.02d0/, rv2(3)/-.06d0/
!
!  -------------------
!
!  ****** eps0 IS A MACHINE DEPENDENT CONSTANT. eps0 IS THE
!         SMALLEST NUMBER SUCH THAT 1 + eps0 .GT. 1.
!
              eps0 = dpmpar(1)
!
!  -------------------
!
!  Initialization.
!
eps = dmax1(eps0,tol)
sc(1) = .125d0
c(1) = eps**(1.d0/28.d0)
ep6 = c(1)**6
pi = 4.d0*datan(1.d0)
fv1(1) = -1.d0
fv2(1) =  0.d0
fv1(2) =  0.d0
fv2(2) = -1.d0
r1 = dsqrt(0.5d0)
ra = 1.d0/r1
fv1(3) =  r1
fv2(3) = -r1
do 10 i = 2,4
   sc(i) = 0.5d0*sc(i-1)
   c(i) = dsqrt(c(i-1))
   ang = pi*sc(i-1)
   fv1(i + 2) =  dcos(ang)
10 fv2(i + 2) = -dsin(ang)
!
!  Start execution.
!
if (n .gt. 51 .or. n .lt. 1) go to 260
l2 = 1
lf = 0
np = 0
m = 0
nr = -1
!
!  Find if A FFT over 8, 16, 32, or 64 points should be used.
!
kl = 1
if (n .gt. 6) kl = 2
if (n .gt. 12) kl = 3
if (n .gt. 25) kl = 4
km = kl + 2
kn = 7 - km
ix = iw(km + 1)
is = iw(kn)
30 u = r
v = 0.d0
!
!  Function values of F are stored ready permutated for the FFT.
!
do 40 i = is,32,is
   iq = ip(i)
   t = u*fv1(km) - v*fv2(km)
   v = u*fv2(km) + v*fv1(km)
   u = t
   call fun(x + u, y + v, a1(iq), a2(iq))
   call fun(x - u, y - v, a1(iq-1), a2(iq-1))
40 continue
ln = 2
jn = 1
!
!  The loop  do 70 ... constitutes the FFT.
!
do 70 l = 1,km
   u = 1.0
   v = 0.0
   do 60 j = 1,jn
      do 50 i = j,ix,ln
         it = i + jn
         s = u*a1(it) - v*a2(it)
         t = u*a2(it) + v*a1(it)
         a1(it) = a1(i) - s
         a2(it) = a2(i) - t
         a1(i) = a1(i) + s
50 a2(i) = a2(i) + t
      t = u*fv1(l) - v*fv2(l)
      v = u*fv2(l) + v*fv1(l)
60 u = t
   ln = ln + ln
70 jn = jn + jn
cx = 0.d0
b = 1.d0
!
!  Test on how fast the coefficients obtained decrease.
!
do 80 i = 1,ix
   ct = dcpabs(a1(i),a2(i))/b
   if (ct .lt. cx) go to 80
   cx = ct
   inr = i
80 b = b*c(kl)
if (m .le. 1) go to 100
!
!  Estimate of the rounding error level for the last radius.
!
err(1) = cx*eps
do 90 i = 2,n
90 err(i) = err(i-1)/r
!
100 sf = sc(kl)
do 110 i = 1,ix
   a1(i) = sf*a1(i)
   a2(i) = sf*a2(i)
110 sf = sf/r
l1 = l2
l2 = 1
if (inr .gt. iw(km)) go to 150
if (lf .eq. 1) go to 140
!
!  Test if the series is a Taylor or a Laurent series.
!
sr = 0.d0
sp = 0.d0
do 130 j = 1,3
   s = a1(ix)
   t = a2(ix)
   u = r*rv1(j)
   v = r*rv2(j)
   do 120 i = 2,ix
      ia = ix + 1 - i
      w = (s*u - t*v) + a1(ia)
      t = (s*v + t*u) + a2(ia)
120 s = w
   cp = dcpabs(s,t)
   if (cp .gt. sp) sp = cp
   call fun(x + u, y + v, u, v)
   cm = dcpabs(s - u, t - v)
130 if (cm .gt. sr) sr = cm
if (sr .gt. 1.d-3*sp) go to 150
lf = 1
140 l2 = -1
!
!  Determination of the next radius to be used.
!
150 if (nr .ge. 0) go to 160
   fact = 2.d0
   if (l2 .eq. 1) fact = 0.5d0
   l1 = l2
   nr = 0
160 if (l1 .ne. l2) go to 180
   if (nr .gt. 0) go to 170
      np = np + 1
      if (np-15) 190,190,260
170 fact = 1.d0/fact
180 fact = 1.d0/dsqrt(fact)
nr = nr + 1
190 r = r*fact
m = nr - kl - 1
if (m .le. 0) go to 30
!
!  The results for the last three radii are stored.
!
do 200 i = 1,n
   rt1(i,m) = a1(i)
200 rt2(i,m) = a2(i)
if (m .eq. 1) go to 220
!
!  Extrapolation.
!
mm1 = m - 1
do 210 i = 1,n
   u = rt1(i,mm1) - rt1(i,m)
   v = rt2(i,mm1) - rt2(i,m)
   rt1(i,mm1) = rt1(i,m) - fc(mm1)*u
210 rt2(i,mm1) = rt2(i,m) - fc(mm1)*v
if (m .eq. 3) go to 230
!
!  Calculation of the extrapolation constants.
!
220 fc(m) = 1.5d0 + dsign(0.5d0,fact-1.d0)
if (m .eq. 2) fc(m) = fc(m) + ra
if (fact .gt. 1.d0) fc(m) = -fc(m)
go to 30
230 fc(3) = fc(1)*fc(2)/(fc(1) + fc(2) + 1.d0)
!
!  Final extrapolation and error estimate.
!
do 240 i = 1,n
   u = rt1(i,1) - rt1(i,2)
   v = rt2(i,1) - rt2(i,2)
   err(i) = err(i) + ep6*dcpabs(u,v)
   rs1(i) = rt1(i,2) - fc(3)*u
240 rs2(i) = rt2(i,2) - fc(3)*v
!
!  Multiply power series coefficients and error estimate by factorials
!  if derivatives wanted.
!
if (ic .eq. 0) return
fac = 0.d0
fact = 1.d0
do 250 i = 1,n
   rs1(i) = fact*rs1(i)
   rs2(i) = fact*rs2(i)
   err(i) = fact*err(i)
   fac = fac + 1.d0
250 fact = fact*fac
return
!
!  Error return.
!
260 do 270 i = 1,n
   rs1(i) = 0.d0
   rs2(i) = 0.d0
270 err(i) = 1.d10
return
end subroutine dcpsc

function trp(a,n,x,y)
implicit none
integer, intent(in) :: n
real, intent(in) :: a
real :: x(n), y(n)
integer :: i, il, ir, nm1
real :: r
real :: trp
!
nm1 = n-1
if (a.lt.x(2)) go to 50
if (a.ge.x(nm1)) go to 40
il = 2
ir = nm1
!
!     Bisection search
!
10 i = (il+ir)/2
if (i.eq.il) go to 60
if (a-x(i)) 20,60,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     a.LT.x(2) .OR. a.GE.x(n-1)
!
40 i = nm1
go to 60
50 i = 1
!
!     Evaluation
!
60 r = (a-x(i))/(x(i+1)-x(i))
trp = y(i)+r*(y(i+1)-y(i))
return
end function trp

subroutine ltrp (m,x,y,n,xi,yi,ni,t,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: m, n, ni
real, intent(inout) :: t(m)
real :: x(n), xi(ni), y(n)
real, intent(inout) :: yi(ni)
integer :: i, ii, il, ilm1, ilold, ipm, ir, istep, j, jmax, k, l, &
&mm1, num
real :: dl, dr, xx
!     ******************************************************************
!     Lagrange interpolation
!     ******************************************************************
!
!     Check input
!
if (m.lt.2) go to 130
if (m.gt.n) go to 131
if (ni.lt.1) go to 132
ierr = 0
!
!     Initialization
!
mm1 = m-1
k  = 1
xx = xi(1)
ilold = 0
!
!     FIND THE SUBINTERVAL WHICH CONTAINS xx. i = 1 IF xx.LT.x(2)
!     AND i = n IF xx.GE.x(n). OTHERWISE x(i).LE.xx.LT.x(i+1).
!
if (xx-x(1)) 10,11,20
10 i = 1
il = 1
ir = m
go to 80
11 i = 1
yi(k) = y(1)
go to 110
!
20 if (x(n)-xx) 21,22,23
21 i = n
il = n-m+1
ir = n
go to 80
22 i = n
yi(k) = y(n)
go to 110
23 il = 1
ir = n
!
!     Bisection search
!
30 i = (il+ir)/2
if (i.eq.il) go to 50
if (xx-x(i)) 31,32,33
31 ir = i
go to 30
32 yi(k) = y(i)
go to 110
33 il = i
go to 30
!
!     Linear forward search
!
40 if (xx-x(i+1)) 50,41,42
41 i = i+1
yi(k) = y(i)
go to 110
42 i = i+1
go to 40
!
!     Point xx lies in the open subinterval (x(i),x(i+1)).
!     Find the m closest points x(il),...,x(ir) to xx.
!
50 if (i.gt.m) go to 51
il = 1
num = i
go to 60
51 il = i-m+1
num = m
!
60 ipm = i+m
if (ipm.le.n) go to 61
ir = n
num = num+n-i
go to 70
61 ir = ipm
num = num+m
!
70 num = num-m
if (num.eq.0) go to 80
dl = xx-x(il)
dr = x(ir)-xx
do 72 l = 1,num
if (dl.le.dr) go to 71
il = il+1
dl = xx-x(il)
go to 72
71 ir = ir-1
dr = x(ir)-xx
72 continue
!
!     Compute the coefficients t(1),...,t(m) of the backward
!     Newton form of the interpolating polynomial.
!
80 if (il.eq.ilold) go to 100
ilold = il
ilm1 = il-1
do 81 j = 1,m
l = ilm1+j
81 t(j) = y(l)
!
do istep=1,mm1
jmax = m-istep
do 90 j = 1,jmax
ii = ilm1+j
l = ii+istep
90 t(j) = (t(j)-t(j+1))/(x(ii)-x(l))
end do
!
!     Evaluation of the interpolating polynomial
!
100 yi(k) = t(1)
do 101 j = 2,m
l = ilm1+j
101 yi(k) = t(j)+yi(k)*(xx-x(l))
!
!     Next point
!
110 if (k.ge.ni) return
k = k+1
xx = xi(k)
if (xx-x(1)) 10,11,111
111 if (x(n)-xx) 21,22,120
!
120 if (xx-xi(k-1)) 121,122,40
121 il = 1
ir = min0(i+1,n)
go to 30
122 yi(k) = yi(k-1)
go to 110
!
!     Error return
!
130 ierr = 1
return
131 ierr = 2
return
132 ierr = 3
return
end subroutine ltrp

subroutine htrp (n,x,y,a,t,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n
real, intent(inout) :: a(n), t(n)
real :: x(n), y(n)
integer :: i, ibeg, iend, k
real :: diff, f, r
!     ******************************************************************
!     Hermite interpolation
!     ******************************************************************
if (n.le.0) go to 30
ierr = 0
a(1) = y(1)
if (n.eq.1) return
f = 1.0
r = 0.0
iend = 0
ibeg = 1
!
do 22 k = 2,n
if (x(k)-x(k-1)) 10,20,10
!
10 f = 1.0
r = 0.0
iend = k-1
ibeg = k
t(1) = y(k)
do 11 i = 1,iend
diff = x(i)-x(k)
if (diff) 11,31,11
11 t(i+1) = (a(i)-t(i))/diff
go to 22
!
20 r = r+1.0
f = f*r
t(1) = y(k)/f
if (iend.eq.0) go to 22
do 21 i = 1,iend
21 t(i+1) = (t(i+1)-t(i))/(x(i)-x(k))
22 a(k) = t(ibeg)
return
!
30 ierr = 1
return
31 ierr = 2
t(1) = i
t(2) = k
return
end subroutine htrp

subroutine pcoeff(alpha,n,x,a,c,t)
implicit none
integer, intent(in) :: n
real, intent(in) :: alpha
integer :: i, j, k, nm1
real, intent(in) :: x(*), a(n)
real, intent(inout) :: c(n)
double precision :: xx, r
double precision, intent(inout) :: t(n)
if (n.gt.1) go to 10
c(1) = a(1)
return
!
10 xx = alpha
nm1 = n-1
do 11 i = 1,n
11 t(i) = a(i)
!
do i=1,nm1
j = n-i
r = xx-dble(x(j))
do 20 k = j,nm1
20 t(k) = t(k)+r*t(k+1)
end do
!
do 30 i = 1,n
30 c(i) = t(i)
return
end subroutine pcoeff

subroutine pfit(nd,np,x,y,a,rnorm,phi,phix,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: nd, np
real, intent(inout) :: rnorm
integer :: k, la, lb, ls, m, mp1, nd1
real :: alpha, c, temp, xmax, xmin, za, zb
!     ******************************************************************
!     Unweighted least squares polynomial fit
!     ******************************************************************
real, intent(in) :: x(np), y(np)
real, intent(inout) :: a(*), phi(2,*), phix(4,np)
real :: lambda
double precision :: dalpha, dsum
!     ---------------------
ierr=0
if (1.le.nd.and.nd.lt.np) go to 10
ierr=1
return
!
!                      Initialization
!
10 nd1=nd+1
do 11 k = 1,nd1
a(k)=0.0
phi(1,k)=0.0
11 phi(2,k)=0.0
!
!                SET Z=a+B*x WHERE abs(Z).LE.1
!
xmin=x(1)
xmax=x(1)
do 21 k = 2,np
if (x(k).ge.xmin) go to 20
xmin=x(k)
go to 21
20 if (x(k).gt.xmax) xmax=x(k)
21 continue
zb=2.0/(xmax-xmin)
za=-xmin*zb-1.0
do 22 k = 1,np
22 phix(3,k)=za+zb*x(k)
!
!           Compute the closest polynomial of degree 0
!
lambda=np
phi(1,1)=1.0/sqrt(lambda)
dalpha=0.d0
dsum=0.d0
do 30 k = 1,np
phix(1,k)=phi(1,1)
dalpha=dalpha+dble(phix(3,k))
30 dsum=dsum+dble(y(k))
alpha=sngl(dalpha)/lambda
a(1)=sngl(dsum)/lambda
do 31 k = 1,np
31 phix(4,k)=a(1)
!
la=2
lb=1
do 90 m = 1,nd
mp1=m+1
!
!          Generate lambda(m)*phi(m) and evaluate it at Z
!
if (m.ne.1) go to 50
phi(2,1)=-alpha*phi(1,1)
phi(2,2)=phi(1,1)
do 40 k = 1,np
40 phix(2,k)=(phix(3,k)-alpha)*phi(1,1)
go to 60
!
50 c=0.0
do 51 k = 1,m
phi(la,k)=dble(c)-dble(alpha*phi(lb,k))-dble(lambda*phi(la,k))
51 c=phi(lb,k)
phi(la,mp1)=c
do 52 k = 1,np
52 phix(la,k)=(phix(3,k)-alpha)*phix(lb,k)-lambda*phix(la,k)
!
!                Compute alpha(m) and lambda(m)
!
60 dalpha=0.d0
dsum=0.d0
do 61 k = 1,np
c=phix(la,k)*phix(la,k)
dalpha=dalpha+dble(c*phix(3,k))
61 dsum=dsum+dble(c)
lambda=dsum
alpha=sngl(dalpha)/lambda
lambda=sqrt(lambda)
!
!              Generate phi(m) and evaluate it at Z
!
do 70 k = 1,mp1
70 phi(la,k)=phi(la,k)/lambda
do 71 k = 1,np
71 phix(la,k)=phix(la,k)/lambda
!
!        Compute the closest polynomial of degree m or less
!                     and evaluate it at Z
!
dsum=0.d0
do 80 k = 1,np
80 dsum=dsum+dble((y(k)-phix(4,k))*phix(la,k))
c=dsum
do 81 k = 1,mp1
81 a(k)=a(k)+c*phi(la,k)
do 82 k = 1,np
82 phix(4,k)=phix(4,k)+c*phix(la,k)
!
ls=la
la=lb
90 lb=ls
!
!                        Compute rnorm
!
dsum=0.d0
do 95 k = 1,np
95 dsum=dsum+dble((y(k)-phix(4,k))**2)
rnorm=sqrt(sngl(dsum))
!
!        Convert the closest polynomial from a polynomial
!                  in Z to a polynomial in x
!
a(1)=a(1)+za*a(2)
a(2)=zb*a(2)
if (nd.eq.1) return
phi(1,1)=za
phi(1,2)=zb
do 102 m = 2,nd
mp1=m+1
c=0.0
do 100 k = 1,m
temp=phi(1,k)*zb
phi(1,k)=phi(1,k)*za+c
100 c=temp
phi(1,mp1)=c
do 101 k = 1,m
101 a(k)=a(k)+a(mp1)*phi(1,k)
102 a(mp1)=a(mp1)*phi(1,mp1)
return
end subroutine pfit

subroutine wpfit(nd,np,x,y,w,a,rnorm,phi,phix,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: nd, np
real, intent(inout) :: rnorm
integer :: k, la, lb, ls, m, mp1, nd1, nw
real :: alpha, c, temp, xmax, xmin, za, zb
!     ******************************************************************
!     Weighted least squares polynomial fit
!     ******************************************************************
real, intent(in) :: x(np), y(np), w(np)
real, intent(inout) :: a(*), phi(2,*), phix(4,np)
real :: lambda
double precision :: dalpha, dsum
!     ---------------------
!
!                      Error checking
!
if (nd.lt.1.or.np.lt.2) go to 200
nw=0
dsum=0.d0
do 13 k = 1,np
if (w(k)) 202,13,10
10 nw=nw+1
dsum=dsum+dble(w(k))
if (nw.gt.1) go to 11
xmin=x(k)
xmax=x(k)
go to 13
11 if (x(k).ge.xmin) go to 12
xmin=x(k)
go to 13
12 if (x(k).gt.xmax) xmax=x(k)
13 continue
if (nd.ge.nw) go to 200
!
!                      Initialization
!
ierr=0
nd1=nd+1
do 20 k = 1,nd1
a(k)=0.0
phi(1,k)=0.0
20 phi(2,k)=0.0
!
!                SET Z=a+B*x WHERE abs(Z).LE.1
!
zb=2.0/(xmax-xmin)
za=-xmin*zb-1.0
do 25 k = 1,np
25 phix(3,k)=za+zb*x(k)
!
!           Compute the closest polynomial of degree 0
!
lambda=dsum
phi(1,1)=1.0/sqrt(lambda)
dalpha=0.d0
dsum=0.d0
do 30 k = 1,np
phix(1,k)=phi(1,1)
dalpha=dalpha+dble(w(k)*phix(3,k))
30 dsum=dsum+dble(w(k)*y(k))
alpha=sngl(dalpha)/lambda
a(1)=sngl(dsum)/lambda
do 31 k = 1,np
31 phix(4,k)=a(1)
!
la=2
lb=1
do 90 m = 1,nd
mp1=m+1
!
!          Generate lambda(m)*phi(m) and evaluate it at Z
!
if (m.ne.1) go to 50
phi(2,1)=-alpha*phi(1,1)
phi(2,2)=phi(1,1)
do 40 k = 1,np
40 phix(2,k)=(phix(3,k)-alpha)*phi(1,1)
go to 60
!
50 c=0.0
do 51 k = 1,m
phi(la,k)=dble(c)-dble(alpha*phi(lb,k))-dble(lambda*phi(la,k))
51 c=phi(lb,k)
phi(la,mp1)=c
do 52 k = 1,np
52 phix(la,k)=(phix(3,k)-alpha)*phix(lb,k)-lambda*phix(la,k)
!
!                Compute alpha(m) and lambda(m)
!
60 dalpha=0.d0
dsum=0.d0
do 61 k = 1,np
c=w(k)*phix(la,k)*phix(la,k)
dalpha=dalpha+dble(c*phix(3,k))
61 dsum=dsum+dble(c)
lambda=dsum
alpha=sngl(dalpha)/lambda
lambda=sqrt(lambda)
!
!              Generate phi(m) and evaluate it at Z
!
do 70 k = 1,mp1
70 phi(la,k)=phi(la,k)/lambda
do 71 k = 1,np
71 phix(la,k)=phix(la,k)/lambda
!
!        Compute the closest polynomial of degree m or less
!                     and evaluate it at Z
!
dsum=0.d0
do 80 k = 1,np
80 dsum=dsum+dble(w(k)*(y(k)-phix(4,k))*phix(la,k))
c=dsum
do 81 k = 1,mp1
81 a(k)=a(k)+c*phi(la,k)
do 82 k = 1,np
82 phix(4,k)=phix(4,k)+c*phix(la,k)
!
ls=la
la=lb
90 lb=ls
!
!                        Compute rnorm
!
dsum=0.d0
do 95 k = 1,np
95 dsum=dsum+dble(w(k)*(y(k)-phix(4,k))**2)
rnorm=sqrt(sngl(dsum))
!
!        Convert the closest polynomial from a polynomial
!                  in Z to a polynomial in x
!
a(1)=a(1)+za*a(2)
a(2)=zb*a(2)
if (nd.eq.1) return
phi(1,1)=za
phi(1,2)=zb
do 102 m = 2,nd
mp1=m+1
c=0.0
do 100 k = 1,m
temp=phi(1,k)*zb
phi(1,k)=phi(1,k)*za+c
100 c=temp
phi(1,mp1)=c
do 101 k = 1,m
101 a(k)=a(k)+a(mp1)*phi(1,k)
102 a(mp1)=a(mp1)*phi(1,mp1)
return
!
!                        Error return
!
200 ierr=1
return
202 ierr=3
return
end subroutine wpfit

subroutine cbspl (x, y, a, b, c, n, ibeg, iend, alpha, beta, ierr)
implicit none
integer, intent(in) :: ibeg, iend
integer, intent(inout) :: ierr
integer, intent(in) :: n
real, intent(in) :: alpha, beta
integer :: i, j, m, nm1
real :: del, h, r, t
!-----------------------------------------------------------------------
!                   Cubic spline interpolation
!-----------------------------------------------------------------------
real, intent(in) :: x(n), y(n)
real, intent(inout) :: a(n), b(n), c(n)
!
if (n .lt. 3) go to 200

!     A tridiagonal linear system for the unknown slopes S(i) of
!     F AT x(i), i=1,...,n, IS GENERATED AND THEN SOLVED BY GAUSS
!     elimination, with S(i) ending up in a(i) for all i. A, b, c
!     are used initially for work spaces.
!
do m = 2,n
   b(m) = x(m) - x(m-1)
   if (b(m) .le. 0.0) go to 210
   c(m) = (y(m) - y(m-1))/b(m)
end do
ierr = 0
!
!     Construct the first equation from the boundary condition, of
!     the form
!
!             c(1)*S(1) + b(1)*S(2) = a(1)
!
if (ibeg - 1) 20,30,40
!
!     No condition at left end.
!
20 c(1) = b(3)
b(1) = x(3) - x(1)
a(1) = ((b(2) + 2.0*b(1))*b(3)*c(2) + b(2)*b(2)*c(3))/b(1)
go to 50
!
!     Slope prescribed at left end.
!
30 c(1) = 1.0
b(1) = 0.0
a(1) = alpha
go to 50
!
!     Second derivative prescribed at left end.
!
40 c(1) = 2.0
b(1) = 1.0
a(1) = 3.0*c(2) - 0.5*alpha*b(2)
!
!     For the interior knots, generate the corresponding equations and
!     carry out the forward pass of Gauss elimination, after which the
!     m-TH EQUATION READS  c(m)*S(m) + b(m)*S(m+1) = a(m).
!
50 nm1 = n - 1
do m = 2,nm1
   t = -b(m+1)/c(m-1)
   a(m) = t*a(m-1) + 3.0*(b(m)*c(m+1) + b(m+1)*c(m))
   c(m) = t*b(m-1) + 2.0*(b(m) + b(m+1))
end do
!
!     If the slope at the right end is given, then set a(n) to the
!     slope and go to back substitution. Otherwise, construct the
!     last equation from the second boundary condition, of the form
!
!                r*S(n-1) + c(n)*S(n) = a(n)
!
if (iend - 1) 60,80,90
60 if (n .eq. 3 .and. ibeg .eq. 0) go to 70
!
!     NO CONDITION AT THE RIGHT END. EITHER  n .GE. 4  OR
!     there is a condition at the left end.
!
r = x(n) - x(n-2)
del  = (y(nm1) - y(n-2))/b(nm1)
a(n) = ((b(n) + 2.0*r)*b(nm1)*c(n) + b(n)*b(n)*del)/r
c(n) = b(nm1)
go to 100
!
!     NO CONDITIONS AT THE END POINTS AND n = 3. IN THIS CASE,
!     the second boundary condition does not provide us with A
!     new equation. For convenience, we use the following...
!
70 a(n) = 2.0*c(n)
c(n) = 1.0
r = 1.0
go to 100
!
!     Slope prescribed at right end.
!
80 a(n) = beta
go to 110
!
!     Second derivative prescribed at right end.
!
90 a(n) = 3.0*c(n) + 0.5*beta*b(n)
c(n) = 2.0
r = 1.0
!
!     Complete forward pass of Gauss elimination.
!
100 t = -r/c(nm1)
a(n) = (t*a(nm1) + a(n))/(t*b(nm1) + c(n))
!
!     Carry out back substitution.
!
110 do i = 1,nm1
   j = n - i
   a(j) = (a(j) - b(j)*a(j+1))/c(j)
end do
!
!     Generate the cubic coefficients b(i) and c(i).
!
do i = 1,nm1
   h = b(i+1)
   del = (y(i+1) - y(i))/h
   t = a(i) + a(i+1) - 2.0*del
   b(i) = (del - a(i) - t)/h
   c(i) = (t/h)/h
end do
return
!
!     Error return
!
200 ierr = 1
return
210 ierr = 2
return
end subroutine cbspl

subroutine splift (x,y,yp,ypp,n,w,ierr,isx,a1,b1,an,bn)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: isx, n
real, intent(in) :: a1, an, b1, bn
integer :: i, j, nm1, nm2
real :: dnew, dold, h
!
!     Written by Rondall E. Jones
!        Sandia Laboratories
!        albuquerque, new mexico  87115
!        January 1976
!
!     Abstract
!         splift fits an interpolating cubic spline to the n data points
!         given in x and y and returns the first and second derivatives
!         in yp and ypp.
!
!     Description of arguments
!
!       --Input--
!
!         x    - ARRAY OF ABSCISSAS OF DATA (IN INCREASING ORDER)
!         y    - ARRAY OF ORDINATES OF DATA
!         n    - THE NUMBER OF DATA POINTS.  THE ARRAYS x, y, yp, AND
!                ypp MUST BE DIMENSIONED AT LEAST n.  (n .GE. 4)
!         isx  - must be zero on the initial call to splift.
!                If a spline is to be fitted to a second set of data
!                that has the same set of abscissas as a previous set,
!                and if the contents of w have not been changed since
!                that previous fit was computed, then isx may be
!                set to one for faster execution.
!         a1,b1,an,bn - specify the end conditions for the spline which
!                are expressed as constraints on the second derivative
!                of the spline at the end points (see ypp).
!                The end condition constraints are
!                        ypp(1) = a1*ypp(2) + b1
!                and
!                        ypp(n) = an*ypp(n-1) + bn
!                where
!                        abs(a1).LT. 1.0  AND  abs(an).LT. 1.0.
!
!                The smoothest spline (I.E., Least integral of square
!                OF SECOND DERIVATIVE) IS OBTAINED BY a1=b1=an=bn=0.
!                In this case there is an inflection at x(1) and x(n).
!                If the data is to be extrapolated (say, by using splint
!                to evaluate the spline outside the range x(1) to x(n)),
!                THEN TAKING a1=an=0.5 AND b1=bn=0 MAY YIELD BETTER
!                results.  In this case there is an inflection
!                at x(1) - (x(2)-x(1)) and at x(n) + (x(n)-x(n-1)).
!                IN THE MORE GENERAL CASE OF a1=an=A  AND b1=bn=0,
!                there is an inflection at x(1) - (x(2)-x(1))*A/(1.0-A)
!                and at x(n) + (x(n)-x(n-1))*A/(1.0-A).
!
!                A spline that has a given first derivative YP1 at x(1)
!                and YPN at y(n) may be defined by using the
!                following conditions.
!
!                a1=-0.5
!
!                b1= 3.0*((y(2)-y(1))/(x(2)-x(1))-yp1)/(x(2)-x(1))
!
!                an=-0.5
!
!                bn=-3.0*((y(n)-y(n-1))/(x(n)-x(n-1))-ypn)/(x(n)-x(n-1))
!
!       --Output--
!
!         yp   - ARRAY OF FIRST DERIVATIVES OF SPLINE (AT THE x(i))
!         ypp  - array of second derivatives of spline (at the x(i))
!         ierr - a status code
!              --normal code
!                 0 means that the requested spline was computed.
!              --Abnormal codes
!                 1 MEANS THAT abs(a1) OR abs(an) WAS .GE. 1.
!                 2 MEANS THAT n, THE NUMBER OF POINTS, WAS .LT. 4.
!                 3 Means the abscissas were not strictly increasing.
!
!       --Work--
!
!         w    - ARRAY OF WORKING STORAGE DIMENSIONED AT LEAST 3n.
!
real, intent(in) :: x(n), y(n)
real, intent(inout) :: yp(n), ypp(n), w(n,3)
!
if (abs(a1) .ge. 1.0 .or. abs(an) .ge. 1.0) go to 100
if (n .lt. 4) go to 200
nm1 = n - 1
nm2 = n - 2
if (isx .gt. 0) go to 40
do 10 i = 2,n
   if (x(i) .le. x(i-1)) go to 300
10 continue
!
!     Define the tridiagonal matrix
!
w(1,3) = x(2) - x(1)
do 20 i = 2,nm1
   w(i,2) = w(i-1,3)
   w(i,3) = x(i+1) - x(i)
   w(i,1) = 2.0*(w(i,2) + w(i,3))
20 continue
w(1,1) = 4.0
w(1,3) =-4.0*a1
w(n,1) = 4.0
w(n,2) =-4.0*an
!
!     LU decomposition
!
do 30 i = 2,n
   w(i-1,3) = w(i-1,3)/w(i-1,1)
   w(i,1)   = w(i,1) - w(i,2)*w(i-1,3)
30 continue
!
!     Define *constant* vector
!
40 ypp(1) = 4.0*b1
dold = (y(2) - y(1))/w(2,2)
do 50 i = 2,nm2
   dnew   = (y(i+1) - y(i))/w(i+1,2)
   ypp(i) = 6.0*(dnew - dold)
   yp(i)  = dold
   dold   = dnew
50 continue
dnew = (y(n) - y(nm1))/(x(n) - x(nm1))
ypp(nm1) = 6.0*(dnew - dold)
ypp(n) = 4.0*bn
yp(nm1)= dold
yp(n)  = dnew
!
!     Forward substitution
!
ypp(1) = ypp(1)/w(1,1)
do 60 i = 2,n
   ypp(i) = (ypp(i) - w(i,2)*ypp(i-1))/w(i,1)
60 continue
!
!     Backward substitution
!
do 70 j = 1,nm1
   i = n - j
   ypp(i) = ypp(i) - w(i,3)*ypp(i+1)
70 continue
!
!     Compute first derivatives
!
h = x(2) - x(1)
yp(1) = (y(2) - y(1))/h - h*(2.0*ypp(1) + ypp(2))/6.0
do 80 i = 2,nm1
   yp(i) = yp(i) + w(i,2)*(ypp(i-1) + 2.0*ypp(i))/6.0
80 continue
yp(n) = yp(n) + (x(n) - x(nm1))*(ypp(nm1) + 2.0*ypp(n))/6.0
ierr = 0
return
!
100 ierr = 1
return
200 ierr = 2
return
300 ierr = 3
return
end subroutine splift

subroutine spfit (x, y, wgt, m, break, l, z, a, b, c, wk, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: l, m
integer :: j, k, la, lm1, lq, lw, n
!-----------------------------------------------------------------------
!            Weighted least squares cubic spline fitting
!-----------------------------------------------------------------------
real, intent(in) :: x(m), y(m), wgt(m)
real, intent(inout) :: break(l)
real, intent(inout) :: z(*), a(*), b(*), c(*), wk(*)
real :: temp(20)
!---------------------
!     real z(l-1), a(l-1), b(l-1), c(l-1), wk(7*l + 18)
!---------------------
if (l .lt. 2) go to 100
n = l + 2
!
!                Define the knots for the b-splines
!
wk(1) = break(1)
wk(2) = break(1)
wk(3) = break(1)
wk(4) = break(1)
do j = 2,l
   if (break(j - 1) .ge. break(j)) go to 110
   wk(j + 3) = break(j)
end do
wk(l + 4) = break(l)
wk(l + 5) = break(l)
wk(l + 6) = break(l)
!
!     Obtain the b-spline coefficients of the least squares fit
!
la = n + 5
lw = la + n
lq = lw + n
call bslsq (x, y, wgt, m, wk(1), n, 4, wk(la), &
&wk(lw), wk(lq), ierr)
if (ierr .lt. 0) go to 120
ierr = 0
!
!     Obtain the coefficients of the fit in Taylor series form
!
call bspp (wk(1), wk(la), n, 4, break, &
&wk(lq), lm1, temp)
k = lq
do 20 j = 1,lm1
   z(j) = wk(k)
   a(j) = wk(k + 1)
   b(j) = wk(k + 2)
   c(j) = wk(k + 3)
   k = k + 4
20 continue
return
!
!                       Error return
!
100 ierr = 1
return
110 ierr = 2
return
120 ierr = 3
return
end subroutine spfit

subroutine cspfit (x, y, m, break, l, xcon, con, nder, nc, &
&z, a, b, c, wk, iwk, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: l, m, nc
integer :: j, k, la, lm1, lw, n
real :: r
!-----------------------------------------------------------------------
!                Least squares cubic spline fitting with
!                  equality and inequality constraints
!-----------------------------------------------------------------------
real, intent(in) :: x(m), y(m)
real, intent(inout) :: break(l)
real, intent(in) :: xcon(*), con(*)
real, intent(inout) :: z(*), a(*), b(*), c(*), wk(*)
integer, intent(in) :: nder(*)
integer, intent(inout) :: iwk(*)
!
real :: temp(20)
!---------------------
!     xcon, con, nder are arrays of dimension max(1,nc).
!     z, A, b, c are arrays of dimension l - 1.
!     wk and iwk are arrays of dimension iwk(1) and iwk(2)
!        RESPECTIVELY. IT IS REQUIRED THAT iwk(2) .GE. 2
!        AND iwk(1) .GE. 7(l + 7) FOR ALL nc. IF nc .GE. 1
!        then more storage will be needed.
!---------------------
if (l .lt. 2) go to 100
n = l + 2
!
!                Define the knots for the b-splines
!
wk(1) = break(1)
wk(2) = break(1)
wk(3) = break(1)
wk(4) = break(1)
do j = 2,l
   if (break(j - 1) .ge. break(j)) go to 110
   wk(j + 3) = break(j)
end do
wk(l + 4) = break(l)
wk(l + 5) = break(l)
wk(l + 6) = break(l)
!
!     Obtain the b-spline coefficients of the least squares fit
!
k = 7*n + 35
if (iwk(1) .lt. k) go to 120
la = n + 5
lw = la + n
ierr = 0
!
k = lw - 1
iwk(1) = iwk(1) - k
call bfit (wk(1), n, 4, x, y, m, xcon, con, nder, nc, ierr, &
&wk(la), r, wk(lw), iwk)
iwk(1) = iwk(1) + k
if (ierr .lt. 0 .or. ierr .eq. 2) return
!
!     Obtain the coefficients of the fit in Taylor series form
!
call bspp (wk(1), wk(la), n, 4, break, &
&wk(lw), lm1, temp)
k = lw
do 20 j = 1,lm1
   z(j) = wk(k)
   a(j) = wk(k + 1)
   b(j) = wk(k + 2)
   c(j) = wk(k + 3)
   k = k + 4
20 continue
return
!
!                       Error return
!
100 ierr = -1
return
!
110 ierr = -3
return
!
120 ierr = -6
iwk(1) = k
return
end subroutine cspfit

subroutine scomp (x,y,a,b,c,n,xi,yi,ni,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n, ni
integer :: i, il, ir, k
real :: dx, xx
!
!     Abstract
!
!         scomp evaluates a cubic spline at the abscissas in xi.
!         It is assumed that the coefficients of the polynomials
!         which form the spline are provided.
!
!     Description of arguments
!
!       --Input--
!
!         x   - ARRAY OF THE FIRST n ABSCISSAS (IN INCREASING ORDER)
!               that define the spline.
!         y   - ARRAY OF THE FIRST n ORDINATES THAT DEFINE THE SPLINE.
!         A,b,c arrays that contain the coefficients of the polynomials
!               WHICH FORM THE SPLINE. IF i = 1,...,n  THEN THE SPLINE
!               has the value
!                    y(i) + a(i)*dx + b(i)*dx**2 + c(i)*dx**3
!               FOR x(i) .LE. xx .LE. x(i+1).  HERE dx = xx-x(i).
!         n   - THE NUMBER OF POLYNOMIALS THAT DEFINE THE SPLINE.
!               The arrays x, y, A, b, c  must be dimensioned at
!               least n.  n must be greater than or equal to 1.
!         xi  - the abscissa or array of abscissas (in arbitrary order)
!               at which the spline is to be evaluated.
!         ni  - the number of abscissas at which the spline is to be
!               evaluated.  If ni is greater than 1 then xi and yi
!               must be arrays of dimension ni or larger.
!               It is assumed that ni is greater than or equal to 1.
!
!       --Output--
!
!         yi  - array of values of the spline (ordinates) at xi.
!         ierr- status code
!               0  the spline was evaluated at each abscissa in xi.
!               1  Input error - ni is not positive.
!
real, intent(in) :: x(n), y(n), a(n), b(n), c(n), xi(ni)
real, intent(inout) :: yi(ni)
!
!     Check input
!
if (ni .gt. 0) go to 1
   ierr = 1
   return
1 ierr = 0
!
!     k is index on value of xi being worked on.  xx is that value.
!     i is current index into x array.
!
k  = 1
xx = xi(1)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(n)) go to 80
il = 1
ir = n
!
!     Bisection search
!
10 i = (il + ir)/2
if (i .eq. il) go to 100
if (xx - x(i)) 20,100,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     Linear forward search
!
50 if (xx .lt. x(i+1)) go to 100
i = i + 1
go to 50
!
!     xx is greater than x(n) or less than x(1)
!
80 i = n
go to 100
90 i = 1
!
!     Evaluation
!
100 dx = xx - x(i)
yi(k) = y(i) + dx*(a(i) + dx*(b(i) + dx*c(i)))
!
!     Next point
!
if (k .ge. ni) return
k = k + 1
xx = xi(k)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(n)) go to 80
if (xx - xi(k-1)) 110,100,50
110 il = 1
ir = min0(i+1,n)
go to 10
end subroutine scomp

subroutine scomp1 (x,y,yp,n,xi,yi,ni,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n, ni
integer :: i, il, ir, k, nm1
real :: a, b, c, d, dx, h, xx
!
!     Abstract
!
!         scomp1 evaluates a cubic spline at the abscissas in xi.
!         It is assumed that the first derivatives at the nodes
!         have been provided.
!
!     Description of arguments
!
!       --Input--
!
!         x   - ARRAY OF ABSCISSAS (IN INCREASING ORDER) THAT DEFINE THE
!               spline.
!         y   - ARRAY OF ORDINATES THAT DEFINE THE SPLINE.
!         yp  - array of first derivatives that define the spline.
!         n   - THE NUMBER OF DATA POINTS THAT DEFINE THE SPLINE.
!               The arrays x, y, and yp must be dimensioned at least n.
!               n must be greater than or equal to 2.
!         xi  - the abscissa or array of abscissas (in arbitrary order)
!               at which the spline is to be evaluated.
!         ni  - the number of abscissas at which the spline is to be
!               evaluated.  If ni is greater than 1 then xi and yi
!               must be arrays of dimension ni or larger.
!               It is assumed that ni is greater than or equal to 1.
!
!       --Output--
!
!         yi  - array of values of the spline (ordinates) at xi.
!         ierr- status code
!               0  the spline was evaluated at each abscissa in xi.
!               1  Input error - ni is not positive.
!
real, intent(in) :: x(n), y(n), yp(n), xi(ni)
real, intent(inout) :: yi(ni)
!
!     Check input
!
if (ni .gt. 0) go to 1
   ierr = 1
   return
1 ierr = 0
nm1 = n - 1
!
!     k is index on value of xi being worked on.  xx is that value.
!     i is current index into x array.
!
k  = 1
xx = xi(1)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(nm1)) go to 80
il = 1
ir = nm1
!
!     Bisection search
!
10 i = (il + ir)/2
if (i .eq. il) go to 100
if (xx - x(i)) 20,100,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     Linear forward search
!
50 if (xx .lt. x(i+1)) go to 100
i = i + 1
go to 50
!
!     xx is greater than x(n) or less than x(1)
!
80 i = nm1
go to 100
90 i = 1
!
!     Evaluation
!
100 h = x(i+1) - x(i)
d = (y(i+1) - y(i))/h
a = yp(i) + yp(i+1)
b = (-a - yp(i) + 3.0*d)/h
c = (a - d - d)/(h*h)
dx = xx - x(i)
yi(k) = y(i) + dx*(yp(i) + dx*(b + dx*c))
!
!     Next point
!
if (k .ge. ni) return
k = k + 1
xx = xi(k)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(nm1)) go to 80
if (xx - xi(k-1)) 110,100,50
110 il = 1
ir = min0(i+1,nm1)
go to 10
end subroutine scomp1

subroutine scomp2 (x,y,ypp,n,xi,yi,ni,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n, ni
integer :: i, il, ir, k, nm1
real :: h, h2, xl, xl2, xl3, xr, xr2, xr3, xx
!
!     Abstract
!
!         scomp2 evaluates a cubic spline at the abscissas in xi.
!         It is assumed that the second derivatives at the nodes
!         have been provided.
!
!     Description of arguments
!
!       --Input--
!
!         x   - ARRAY OF ABSCISSAS (IN INCREASING ORDER) THAT DEFINE THE
!               spline.
!         y   - ARRAY OF ORDINATES THAT DEFINE THE SPLINE.
!         ypp - array of second derivatives that define the spline.
!         n   - THE NUMBER OF DATA POINTS THAT DEFINE THE SPLINE.
!               The arrays x, y, and ypp must be dimensioned at least n.
!               n must be greater than or equal to 2.
!         xi  - the abscissa or array of abscissas (in arbitrary order)
!               at which the spline is to be evaluated.
!         ni  - the number of abscissas at which the spline is to be
!               evaluated.  If ni is greater than 1 then xi and yi
!               must be arrays of dimension ni or larger.
!               It is assumed that ni is greater than or equal to 1.
!
!       --Output--
!
!         yi  - array of values of the spline (ordinates) at xi.
!         ierr- status code
!               0  the spline was evaluated at each abscissa in xi.
!               1  Input error - ni is not positive.
!
real, intent(in) :: x(n), y(n), ypp(n), xi(ni)
real, intent(inout) :: yi(ni)
!
!     Check input
!
if (ni .gt. 0) go to 1
   ierr = 1
   return
1 ierr = 0
nm1 = n - 1
!
!     k is index on value of xi being worked on.  xx is that value.
!     i is current index into x array.
!
k  = 1
xx = xi(1)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(nm1)) go to 80
il = 1
ir = nm1
!
!     Bisection search
!
10 i = (il + ir)/2
if (i .eq. il) go to 100
if (xx - x(i)) 20,100,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     Linear forward search
!
50 if (xx .lt. x(i+1)) go to 100
i = i + 1
go to 50
!
!     xx is greater than x(n) or less than x(1)
!
80 i = nm1
go to 100
90 i = 1
!
!     Evaluation
!
100 h  = x(i+1) - x(i)
h2 = h*h
xr = (x(i+1) - xx)/h
xr2 = xr*xr
xr3 = xr*xr2
xl = (xx - x(i))/h
xl2 = xl*xl
xl3 = xl*xl2
yi(k) = y(i)*xr + y(i+1)*xl &
&- h2*(ypp(i)*(xr-xr3) + ypp(i+1)*(xl-xl3))/6.0
!
!     Next point
!
if (k .ge. ni) return
k = k + 1
xx = xi(k)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(nm1)) go to 80
if (xx - xi(k-1)) 110,100,50
110 il = 1
ir = min0(i+1,nm1)
go to 10
end subroutine scomp2

subroutine seval (x,y,a,b,c,n,xi,yi,ypi,yppi,ni,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n, ni
integer :: i, il, ir, k
real :: bi, ci, dx, xx
!
!     Abstract
!
!         seval evaluates a cubic spline and its first and second
!         derivatives at the abscissas in xi.  It is assumed that
!         the coefficients of the polynomials which form the spline
!         are provided.
!
!     Description of arguments
!
!       --Input--
!
!         x   - ARRAY OF THE FIRST n ABSCISSAS (IN INCREASING ORDER)
!               that define the spline.
!         y   - ARRAY OF THE FIRST n ORDINATES THAT DEFINE THE SPLINE.
!         A,b,c arrays that contain the coefficients of the polynomials
!               WHICH FORM THE SPLINE. IF i = 1,...,n  THEN THE SPLINE
!               has the value
!                    y(i) + a(i)*dx + b(i)*dx**2 + c(i)*dx**3
!               FOR x(i) .LE. xx .LE. x(i+1).  HERE dx = xx-x(i).
!         n   - THE NUMBER OF POLYNOMIALS THAT DEFINE THE SPLINE.
!               The arrays x, y, A, b, c  must be dimensioned at
!               least n.  n must be greater than or equal to 1.
!         xi  - the abscissa or array of abscissas (in arbitrary order)
!               at which the spline is to be evaluated.
!         ni  - the number of abscissas at which the spline is to be
!               evaluated.  If ni is greater than 1, then xi, yi, ypi,
!               and yppi must be arrays dimensioned at least ni.
!               ni must be greater than or equal to 1.
!
!       --Output--
!
!         yi  - array of values of the spline (ordinates) at xi.
!         ypi - array of values of the first derivative of spline at xi.
!         yppi- array of values of second derivatives of spline at xi.
!         ierr- status code
!               0  the spline was evaluated at each abscissa in xi.
!               1  Input error - ni is not positive.
!
real, intent(in) :: x(n), y(n), a(n), b(n), c(n), xi(ni)
real, intent(inout) :: yi(ni), ypi(ni), yppi(ni)
!
!     Check input
!
if (ni .gt. 0) go to 1
   ierr = 1
   return
1 ierr = 0
!
!     k is index on value of xi being worked on.  xx is that value.
!     i is current index into x array.
!
k  = 1
xx = xi(1)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(n)) go to 80
il = 1
ir = n
!
!     Bisection search
!
10 i = (il + ir)/2
if (i .eq. il) go to 100
if (xx - x(i)) 20,100,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     Linear forward search
!
50 if (xx .lt. x(i+1)) go to 100
i = i + 1
go to 50
!
!     xx is greater than x(n) or less than x(1)
!
80 i = n
go to 100
90 i = 1
!
!     Evaluation
!
100 dx = xx - x(i)
yi(k) = y(i) + dx*(a(i) + dx*(b(i) + dx*c(i)))
bi = b(i) + b(i)
ci = 3.0*c(i)
ypi(k) = a(i) + dx*(bi + dx*ci)
yppi(k) = bi + dx*(ci + ci)
!
!     Next point
!
if (k .ge. ni) return
k = k + 1
xx = xi(k)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(n)) go to 80
if (xx - xi(k-1)) 110,100,50
110 il = 1
ir = min0(i+1,n)
go to 10
end subroutine seval

subroutine seval1 (x,y,yp,n,xi,yi,ypi,yppi,ni,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n, ni
integer :: i, il, ir, k, nm1
real :: a, b, c, d, dx, h, xx
!
!     Abstract
!
!         seval1 evaluates a cubic spline and its first and second
!         derivatives at the abscissas in xi.  It is assumed that
!         the first derivatives at the nodes have been provided.
!
!     Description of arguments
!
!       --Input--
!
!         x   - ARRAY OF ABSCISSAS (IN INCREASING ORDER) THAT DEFINE THE
!               spline.
!         y   - ARRAY OF ORDINATES THAT DEFINE THE SPLINE.
!         yp  - array of first derivatives that define the spline.
!         n   - THE NUMBER OF DATA POINTS THAT DEFINE THE SPLINE.
!               The arrays x, y, and yp must be dimensioned at least n.
!               n must be greater than or equal to 2.
!         xi  - the abscissa or array of abscissas (in arbitrary order)
!               at which the spline is to be evaluated.
!         ni  - the number of abscissas at which the spline is to be
!               evaluated.  If ni is greater than 1, then xi, yi, ypi,
!               and yppi must be arrays dimensioned at least ni.
!               ni must be greater than or equal to 1.
!
!       --Output--
!
!         yi  - array of values of the spline (ordinates) at xi.
!         ypi - array of values of the first derivative of spline at xi.
!         yppi- array of values of second derivatives of spline at xi.
!         ierr- status code
!               0  the spline was evaluated at each abscissa in xi.
!               1  Input error - ni is not positive.
!
real, intent(in) :: x(n), y(n), yp(n), xi(ni)
real, intent(inout) :: yi(ni), ypi(ni), yppi(ni)
!
!     Check input
!
if (ni .gt. 0) go to 1
   ierr = 1
   return
1 ierr = 0
nm1 = n - 1
!
!     k is index on value of xi being worked on.  xx is that value.
!     i is current index into x array.
!
k  = 1
xx = xi(1)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(nm1)) go to 80
il = 1
ir = nm1
!
!     Bisection search
!
10 i = (il + ir)/2
if (i .eq. il) go to 100
if (xx - x(i)) 20,100,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     Linear forward search
!
50 if (xx .lt. x(i+1)) go to 100
i = i + 1
go to 50
!
!     xx is greater than x(n) or less than x(1)
!
80 i = nm1
go to 100
90 i = 1
!
!     Evaluation
!
100 h = x(i+1) - x(i)
d = (y(i+1) - y(i))/h
a = yp(i) + yp(i+1)
b = (-a - yp(i) + 3.0*d)/h
c = (a - d - d)/(h*h)
dx = xx - x(i)
yi(k) = y(i) + dx*(yp(i) + dx*(b + dx*c))
b = b + b
c = 3.0*c
ypi(k) = yp(i) + dx*(b + dx*c)
yppi(k) = b + dx*(c + c)
!
!     Next point
!
if (k .ge. ni) return
k = k + 1
xx = xi(k)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(nm1)) go to 80
if (xx - xi(k-1)) 110,100,50
110 il = 1
ir = min0(i+1,nm1)
go to 10
end subroutine seval1

subroutine seval2 (x,y,ypp,n,xi,yi,ypi,yppi,ni,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n, ni
integer :: i, il, ir, k, nm1
real :: h, h2, xl, xl2, xl3, xr, xr2, xr3, xx
!
!     Abstract
!
!         seval2 evaluates a cubic spline and its first and second
!         derivatives at the abscissas in xi.  It is assumed that
!         the second derivatives at the nodes have been provided.
!
!     Description of arguments
!
!       --Input--
!
!         x   - ARRAY OF ABSCISSAS (IN INCREASING ORDER) THAT DEFINE THE
!               spline.
!         y   - ARRAY OF ORDINATES THAT DEFINE THE SPLINE.
!         ypp - array of second derivatives that define the spline.
!         n   - THE NUMBER OF DATA POINTS THAT DEFINE THE SPLINE.
!               The arrays x, y, and ypp must be dimensioned at least n.
!               n must be greater than or equal to 2.
!         xi  - the abscissa or array of abscissas (in arbitrary order)
!               at which the spline is to be evaluated.
!         ni  - the number of abscissas at which the spline is to be
!               evaluated.  If ni is greater than 1, then xi, yi, ypi,
!               and yppi must be arrays dimensioned at least ni.
!               ni must be greater than or equal to 1.
!
!       --Output--
!
!         yi  - array of values of the spline (ordinates) at xi.
!         ypi - array of values of the first derivative of spline at xi.
!         yppi- array of values of second derivatives of spline at xi.
!         ierr- status code
!               0  the spline was evaluated at each abscissa in xi.
!               1  Input error - ni is not positive.
!
real, intent(in) :: x(n), y(n), ypp(n), xi(ni)
real, intent(inout) :: yi(ni), ypi(ni), yppi(ni)
!
!     Check input
!
if (ni .gt. 0) go to 1
   ierr = 1
   return
1 ierr = 0
nm1 = n - 1
!
!     k is index on value of xi being worked on.  xx is that value.
!     i is current index into x array.
!
k  = 1
xx = xi(1)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(nm1)) go to 80
il = 1
ir = nm1
!
!     Bisection search
!
10 i = (il + ir)/2
if (i .eq. il) go to 100
if (xx - x(i)) 20,100,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     Linear forward search
!
50 if (xx .lt. x(i+1)) go to 100
i = i + 1
go to 50
!
!     xx is greater than x(n) or less than x(1)
!
80 i = nm1
go to 100
90 i = 1
!
!     Evaluation
!
100 h  = x(i+1) - x(i)
h2 = h*h
xr = (x(i+1) - xx)/h
xr2 = xr*xr
xr3 = xr*xr2
xl = (xx - x(i))/h
xl2 = xl*xl
xl3 = xl*xl2
yi(k) = y(i)*xr + y(i+1)*xl &
&- h2*(ypp(i)*(xr-xr3) + ypp(i+1)*(xl-xl3))/6.0
ypi(k) = (y(i+1)-y(i))/h &
&+ h*(ypp(i)*(1.0-3.0*xr2) - ypp(i+1)*(1.0-3.0*xl2))/6.0
yppi(k) = ypp(i)*xr + ypp(i+1)*xl
!
!     Next point
!
if (k .ge. ni) return
k = k + 1
xx = xi(k)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(nm1)) go to 80
if (xx - xi(k-1)) 110,100,50
110 il = 1
ir = min0(i+1,nm1)
go to 10
end subroutine seval2

real function csint (x, y, a, b, c, n, alpha, beta)
implicit none
integer, intent(in) :: n
real, intent(in) :: alpha, beta
integer :: i, k, kp1, l, lm1
real :: a0, b0, d, d2, h, h2, r, s, sum
integer :: intrvl
!-----------------------------------------------------------------------
!
!                    Integrating a cubic spline
!
!                         --------------
!
!     x      ARRAY OF THE FIRST n ABSCISSAS (IN INCREASING ORDER)
!            that define the spline.
!
!     y      ARRAY OF THE FIRST n ORDINATES THAT DEFINE THE SPLINE.
!
!     A,b,c  arrays that contain the coefficients of the polynomials
!            WHICH FORM THE SPLINE. IF i = 1,...,n  THEN THE SPLINE
!            has the value
!                    y(i) + a(i)*DX + b(i)*DX**2 + c(i)*DX**3
!            FOR x(i) .LE. XX .LE. x(i+1). HERE DX = XX - x(i).
!
!     n      THE NUMBER OF POLYNOMIALS THAT DEFINE THE SPLINE.
!            The arrays x, y, A, b, c  must be dimensioned at
!            least n.  n must be greater than or equal to 1.
!
!     alpha  lower limit of the integral.
!
!     beta   UPPER LIMIT OF THE INTEGRAL. beta MAY BE LESS THAN
!            or greater than alpha.
!
!-----------------------------------------------------------------------
real, intent(in) :: x(n), y(n), a(n), b(n), c(n)
!
csint = 0.0
h = beta - alpha
if (h .eq. 0.0) return
if (h .gt. 0.0) go to 10
   a0 = beta
   b0 = alpha
   go to 20
10 a0 = alpha
b0 = beta
!
!     Locate the intervals containing a0 and b0
!
20 if (n .eq. 1) go to 50
if (a0 .ge. x(n)) go to 50
k = intrvl (a0, x, n)
l = intrvl (b0, x, n)
if (b0 .ge. x(n)) l = n
if (k .eq. l) go to 51
!
!     Integrate from a0 to x(k + 1)
!
kp1 = k + 1
h = x(kp1) - x(k)
d = a0 - x(k)
r = h + d
h2 = h*h
d2 = d*d
s = h2 + d2
sum = y(k) + 0.5*a(k)*r + b(k)*(s + h*d)/3.0 &
&+ 0.25*c(k)*r*s
sum = (x(kp1) - a0)*sum
!
!     Integrate over the interior intervals
!
if (kp1 .eq. l) go to 40
lm1 = l - 1
do i = kp1,lm1
   h = x(i + 1) - x(i)
   s = (((0.25*c(i)*h + b(i)/3.0)*h + 0.5*a(i))*h + y(i))*h
   sum = sum + s
end do
!
!     Integrate from x(l) to b0
!
40 h = b0 - x(l)
s = (((0.25*c(l)*h + b(l)/3.0)*h + 0.5*a(l))*h + y(l))*h
csint = sum + s
if (alpha .gt. beta) csint = -csint
return
!
!     Case when a0 and b0 are in the same interval
!
50 k = n
51 h = b0 - x(k)
d = a0 - x(k)
r = h + d
h2 = h*h
d2 = d*d
s = h2 + d2
sum = y(k) + 0.5*a(k)*r + b(k)*(s + h*d)/3.0 &
&+ 0.25*c(k)*r*s
csint = (beta - alpha)*sum
return
end function csint

real function csint1 (x, y, yp, n, a, b)
implicit none
integer, intent(in) :: n
real, intent(in) :: a, b
integer :: i, ip1, k, kp1, l, lm1, lp1
real :: a0, b0, bi, ci, d, d2, h, h2, r, s, sum
integer :: intrvl
!-----------------------------------------------------------------------
!
!                    Integrating a cubic spline
!
!                         --------------
!
!     x    ARRAY OF THE FIRST n ABSCISSAS (IN INCREASING ORDER)
!          that define the spline.
!
!     y    ARRAY OF THE FIRST n ORDINATES THAT DEFINE THE SPLINE.
!
!     yp   ARRAY OF THE FIRST DERIVATIVES THAT DEFINE THE SPLINE.
!
!     n    THE NUMBER OF KNOTS OF THE SPLINE. THE ARRAYS x, y,
!          AND yp MUST HAVE DIMENSION AT LEAST n WHERE n .GE. 2.
!
!     A    LOWER LIMIT OF THE INTEGRAL.
!
!     b    UPPER LIMIT OF THE INTEGRAL. b MAY BE LESS THAN
!          or greater than A.
!
!-----------------------------------------------------------------------
real, intent(in) :: x(n), y(n), yp(n)
!
csint1 = 0.0
h = b - a
if (h .eq. 0.0) return
if (h .gt. 0.0) go to 10
   a0 = b
   b0 = a
   go to 20
10 a0 = a
b0 = b
!
!     Locate the intervals containing a0 and b0
!
20 k = intrvl (a0, x, n)
l = intrvl (b0, x, n)
if (k .eq. l) go to 50
!
!     Integrate from a0 to x(k + 1)
!
kp1 = k + 1
h = x(kp1) - x(k)
d = (y(kp1) - y(k))/h
r = yp(k) + yp(kp1)
bi = (-r - yp(k) + 3.0*d)/h
ci = (r - d - d)/(h*h)
!
d = a0 - x(k)
r = h + d
h2 = h*h
d2 = d*d
s = h2 + d2
sum = y(k) + 0.5*yp(k)*r + bi*(s + h*d)/3.0 &
&+ 0.25*ci*r*s
sum = (x(kp1) - a0)*sum
!
!     Integrate over the interior intervals
!
if (kp1 .eq. l) go to 40
lm1 = l - 1
do i = kp1,lm1
   ip1 = i + 1
   h = x(ip1) - x(i)
   d = (y(ip1) - y(i))/h
   r = yp(i) + yp(ip1)
   bi = (-r - yp(i) + 3.0*d)/h
   ci = (r - d - d)/(h*h)
   s = (((0.25*ci*h + bi/3.0)*h + 0.5*yp(i))*h + y(i))*h
   sum = sum + s
end do
!
!     Integrate from x(l) to b0
!
40 lp1 = l + 1
h = x(lp1) - x(l)
d = (y(lp1) - y(l))/h
r = yp(l) + yp(lp1)
bi = (-r - yp(l) + 3.0*d)/h
ci = (r - d - d)/(h*h)
h = b0 - x(l)
s = (((0.25*ci*h + bi/3.0)*h + 0.5*yp(l))*h + y(l))*h
csint1 = sum + s
if (a .gt. b) csint1 = -csint1
return
!
!     Case when a0 and b0 are in the same interval
!
50 kp1 = k + 1
h = x(kp1) - x(k)
d = (y(kp1) - y(k))/h
r = yp(k) + yp(kp1)
bi = (-r - yp(k) + 3.0*d)/h
ci = (r - d - d)/(h*h)
!
h = b0 - x(k)
d = a0 - x(k)
r = h + d
h2 = h*h
d2 = d*d
s = h2 + d2
sum = y(k) + 0.5*yp(k)*r + bi*(s + h*d)/3.0 &
&+ 0.25*ci*r*s
csint1 = (b - a)*sum
return
end function csint1

real function csint2 (x, y, ypp, n, a, b)
implicit none
integer, intent(in) :: n
real, intent(in) :: a, b
integer :: i, ip1, k, kp1, l, lm1, lp1
real :: a0, b0, d, dma, dmb, dpa, dpb, h, r, s, sum
integer :: intrvl
!-----------------------------------------------------------------------
!
!                    Integrating a cubic spline
!
!                         --------------
!
!     x    ARRAY OF THE FIRST n ABSCISSAS (IN INCREASING ORDER)
!          that define the spline.
!
!     y    ARRAY OF THE FIRST n ORDINATES THAT DEFINE THE SPLINE.
!
!     ypp  array of the second derivatives that define the spline.
!
!     n    THE NUMBER OF KNOTS OF THE SPLINE. THE ARRAYS x, y,
!          AND ypp MUST HAVE DIMENSION AT LEAST n WHERE n .GE. 2.
!
!     A    LOWER LIMIT OF THE INTEGRAL.
!
!     b    UPPER LIMIT OF THE INTEGRAL. b MAY BE LESS THAN
!          or greater than A.
!
!-----------------------------------------------------------------------
real, intent(in) :: x(n), y(n), ypp(n)
!
csint2 = 0.0
h = b - a
if (h .eq. 0.0) return
if (h .gt. 0.0) go to 10
   a0 = b
   b0 = a
   go to 20
10 a0 = a
b0 = b
!
!     Locate the intervals containing a0 and b0
!
20 k = intrvl (a0, x, n)
l = intrvl (b0, x, n)
if (k .eq. l) go to 50
!
!     Integrate from a0 to x(k + 1)
!
kp1 = k + 1
h = x(kp1) - x(k)
d = (x(kp1) - a0)/h
r = y(k)*d + y(kp1)*(2.0 - d)
s = ypp(k)*(2.0 - d*d) + ypp(kp1)*(2.0 - d)**2
sum = h*d*(0.5*r - h*h*d*s/24.0)
!
!
!     Integrate over the interior intervals
!
if (kp1 .eq. l) go to 40
lm1 = l - 1
do i = kp1,lm1
   ip1 = i + 1
   h = x(ip1) - x(i)
   r = y(i) + y(ip1)
   s = ypp(i) + ypp(ip1)
   sum = sum + h*(0.5*r - h*h*s/24.0)
end do
!
!     Integrate from x(l) to b0
!
40 lp1 = l + 1
h = x(lp1) - x(l)
d = (b0 - x(l))/h
r = y(l)*(2.0 - d) + y(lp1)*d
s = ypp(l)*(2.0 - d)**2 + ypp(lp1)*(2.0 - d*d)
csint2 = sum + h*d*(0.5*r - h*h*d*s/24.0)
if (a .gt. b) csint2 = -csint2
return
!
!     Case when a0 and b0 are in the same interval
!
50 kp1 = k + 1
h = x(kp1) - x(k)
dma = (a - x(k))/h
dmb = (b - x(k))/h
dpa = (x(kp1) - a)/h
dpb = (x(kp1) - b)/h
r = (dpa + dpb)*y(k) + (dma + dmb)*y(kp1)
s = ypp(k) * (dpa + dpb)*(dma*(2.0 - dma) + dmb*(2.0 - dmb)) + &
&ypp(kp1)*(dma + dmb)*(dpa*(2.0 - dpa) + dpb*(2.0 - dpb))
csint2 = (b - a)*(0.5*r - h*h*s/24.0)
return
end function csint2

subroutine pdspl (x, y, a, b, c, n, t, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n
integer :: i, j, nm1, nm2, nm3
real :: alpha, del, del0, deli, delta, e, h, hi, r, s, si, w
!-----------------------------------------------------------------------
!                Periodic cubic spline interpolation
!-----------------------------------------------------------------------
real, intent(in) :: x(n), y(*)
real, intent(inout) :: a(*), b(*), c(*), t(*)
!----------------------
!     real x(n), y(n-1), a(n-1), b(n-1), c(n-1), t(n-2)
!----------------------
if (n .lt. 3) go to 100
nm1 = n - 1
nm2 = n - 2
nm3 = n - 3
!
!     A strictly diagonally dominant set of equations for the
!     SLOPES s(i) OF THE SPLINE AT x(i) (i = 1,...,n-1) IS
!     generated and solved by Gauss elimination. The first of
!     these equations is obtained from the requirement that
!     the spline be periodic. This equation has the form ...
!
!        a(1)*s(1) + b(1)*s(2) + c(1)*s(n-1) = t(1)
!
b(1) = x(n) - x(nm1)
h = x(2) - x(1)
if (h .le. 0.0 .or. b(1) .le. 0.0) go to 110
del = (y(1) - y(nm1))/b(1)
deli = (y(2) - y(1))/h
!
c(1) = h
a(1) = 2.0*(h + b(1))
t(1) = 3.0*(h*del + b(1)*deli)
if (n .eq. 3) go to 20
!
!     FOR THE KNOTS x(i) (i = 2,...n-2) GENERATE THE CORRESPOND-
!     ing equations and carry out the pivot reduction of Gauss
!     elimination. Then the i-TH equation has the form ...
!
!        a(i)*s(i) + b(i)*s(i+1) + c(i)*s(n-1) = t(i)
!
do i = 2,nm2
   b(i) = h
   h = x(i+1) - x(i)
   if (h .le. 0.0) go to 110
!
   e = h/a(i-1)
   c(i) = - e*c(i-1)
   a(i) = 2.0*(b(i) + h) - e*b(i-1)
!
   del0 = deli
   deli = (y(i+1) - y(i))/h
   t(i) = 3.0*(h*del0 + b(i)*deli) - e*t(i-1)
end do
!
20 ierr = 0
b(nm1) = h
!
!     Since it is required that the spline be periodic, the
!     equation for the knot x(n-1) has the form ...
!
!        alpha*s(1) + b(1)*s(n-2) + delta*s(n-1) = r
!
!     Applying the pivots to this equation, one obtains after
!     each pivot operation the modified equation ...
!
!        alpha*s(i+1) + b(1)*s(n-2) + delta*s(n-1) = r
!
!     Thus, when this pivot reduction is complete, the (n-1)-ST
!     equation to be solved has the form ...
!
!        (alpha + b(1))*s(n-2) + delta*s(n-1) = r
!
alpha = h
delta = 2.0*(h + b(1))
r = 3.0*(b(1)*deli + h*del)
if (n .eq. 3) go to 40
!
do i = 1,nm3
   e = alpha/a(i)
   alpha = - e*b(i)
   delta = delta - e*c(i)
   r = r - e*t(i)
end do
!
!     Solve the last two equations for s(n-1) and s(n-2), and
!     store these slopes in A.
!
40 e = (alpha + b(1))/a(nm2)
w = b(nm2) + c(nm2)
s = (r - e*t(nm2))/(delta - e*w)
a(nm1) = s
a(nm2) = (t(nm2) - w*s)/a(nm2)
if (n .eq. 3) go to 60
!
!     Back substitution to obtain the remaining slopes s(i).
!     These slopes are stored in A.
!
si = a(nm2)
do j = 3,nm1
   i = n - j
   si = (t(i) - b(i)*si - c(i)*s)/a(i)
   a(i) = si
end do
!
!     Generate the cubic coefficients b(i) and c(i)
!
60 h = b(1)
do i = 1,nm2
   hi = b(i + 1)
   deli = (y(i+1) - y(i))/hi
   w = a(i) + a(i+1) - 2.0*deli
   b(i) = (deli - a(i) - w)/hi
   c(i) = (w/hi)/hi
end do
w = a(1) + a(nm1) - 2.0*del
b(nm1) = (del - a(nm1) - w)/h
c(nm1) = (w/h)/h
return
!
!     Error return
!
100 ierr = 1
return
110 ierr = 2
return
end subroutine pdspl

subroutine pdfit (x, y, m, break, l, z, a, b, c, wk, iwk, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: l, m
integer :: j, k, la, lm1, lw, n
real :: r
!-----------------------------------------------------------------------
!            Least squares periodic cubic spline fitting
!-----------------------------------------------------------------------
real, intent(in) :: x(m), y(m)
real, intent(inout) :: break(l)
real, intent(inout) :: z(*), a(*), b(*), c(*), wk(*)
integer, intent(inout) :: iwk(*)
!--------------------
!     real z(l-1), a(l-1), b(l-1), c(l-1)
!     real wk((l + 6)*(l + 15) + 10)
!     integer iwk(2*l + 6)
!--------------------
real :: temp(20)
real :: con(3), xcon(3)
integer :: nder(3)
!--------------------
data nder(1) /3/, nder(2) /7/, nder(3) /11/
!--------------------
if (m .le. 0 .or. l .lt. 2) go to 100
n = l + 2
!
!                Define the nodes for the b-splines
!
wk(1) = break(1)
wk(2) = break(1)
wk(3) = break(1)
wk(4) = break(1)
do j = 2,l
   if (break(j - 1) .ge. break(j)) go to 110
   wk(j + 3) = break(j)
end do
wk(l + 4) = break(l)
wk(l + 5) = break(l)
wk(l + 6) = break(l)
!
!                Define the periodicity constraints
!
con(1) = break(1)
con(2) = break(1)
con(3) = break(1)
xcon(1) = break(l)
xcon(2) = break(l)
xcon(3) = break(l)
!
!     Obtain the b-spline coefficients of the periodic spline
!
ierr = 0
la = n + 5
lw = la + n
iwk(1) = iwk(1) - (l + l + 8)
call bfit (wk(1), n, 4, x, y, m, xcon, con, nder, 3, ierr, &
&wk(la), r, wk(lw), iwk)
iwk(1) = iwk(1) + (l + l + 8)
if (ierr .ne. 0) go to 30
!
!     Obtain the coefficients of the spline in Taylor series form
!
call bspp (wk(1), wk(la), n, 4, break, wk(lw), lm1, temp)
k = lw
do 20 j = 1,lm1
   z(j) = wk(k)
   a(j) = wk(k + 1)
   b(j) = wk(k + 2)
   c(j) = wk(k + 3)
   k = k + 4
20 continue
return
!
!                The coefficients were not obtained
!
30 if (ierr .eq. -4) go to 120
if (ierr .eq. -6) go to 130
if (ierr .eq. -7) go to 140
ierr = 1
return
!
!                           Error return
!
100 ierr = 2
return
110 ierr = 3
return
120 ierr = 4
return
130 ierr = 5
return
140 ierr = 6
return
end subroutine pdfit

subroutine pscmp (x, y, a, b, c, n, xi, yi, m, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: m, n
integer :: i, il, ir, j, k
real :: dx, h, t, t0, x1, xold, xx
!-----------------------------------------------------------------------
!              Evaluation of a periodic cubic spline
!-----------------------------------------------------------------------
real, intent(in) :: x(n), y(*), a(*), b(*), c(*), xi(m)
real, intent(inout) :: yi(m)
!----------------------
!     real x(n), y(n-1), a(n-1), b(n-1), c(n-1), xi(m), yi(m)
!----------------------
if (n .ge. 3 .and. m .ge. 1) go to 1
   ierr = 1
   return
1 ierr = 0
x1 = x(1)
h = x(n) - x1
!
!     REDUCTION OF xi(k) TO xx WHERE x(1) .LE. xx .LT. x(n)
!
k = 1
t = (xi(1) - x1)/h
j = t
t0 = t - j
if (t0 .lt. 0.0) t0 = 1.0 + t0
xx = x1 + t0*h
if (xx .ge. x(n)) go to 120
il = 1
ir = n
!
!     Bisection search
!
10 i = (il + ir)/2
if (i .eq. il) go to 90
if (xx - x(i)) 20,90,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     Linear forward search
!
40 if (xx .lt. x(i+1)) go to 90
i = i + 1
go to 40
!
!     COMPUTATION WHEN x(i) .LE. xx .LT. x(i+1)
!
90 dx = xx - x(i)
yi(k) = ((c(i)*dx + b(i))*dx + a(i))*dx + y(i)
!
!     Next point
!
100 if (k .ge. m) return
xold = xx
k = k + 1
t = (xi(k) - x1)/h
j = t
t0 = t - j
if (t0 .lt. 0.0) t0 = 1.0 + t0
xx = x1 + t0*h
if (xx .ge. x(n)) go to 120
if (xx - xold) 110,90,40
!
110 il = 1
ir = min0(i+1,n)
go to 10
!
!     Case when roundoff produces a value for xx where
!     xx .GE. x(n). THIS CASE MAY NEVER OCCUR.
!
120 i = 1
xx = x1
yi(k) = y(1)
go to 100
end subroutine pscmp

subroutine psevl (x, y, a, b, c, n, xi, yi, ypi, yppi, m, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: m, n
integer :: i, il, ir, j, k
real :: bi2, ci3, dx, h, t, t0, x1, xold, xx
!-----------------------------------------------------------------------
!     Evaluation and differentiation of a periodic cubic spline
!-----------------------------------------------------------------------
real, intent(in) :: x(n), y(*), a(*), b(*), c(*), xi(m)
real, intent(inout) :: yi(m), ypi(m), yppi(m)
!----------------------
!     real x(n), y(n-1), a(n-1), b(n-1), c(n-1), xi(m), yi(m), ypi(m),
!    *     yppi(m)
!----------------------
if (n .ge. 3 .and. m .ge. 1) go to 1
   ierr = 1
   return
1 ierr = 0
x1 = x(1)
h = x(n) - x1
!
!     REDUCTION OF xi(k) TO xx WHERE x(1) .LE. xx .LT. x(n)
!
k = 1
t = (xi(1) - x1)/h
j = t
t0 = t - j
if (t0 .lt. 0.0) t0 = 1.0 + t0
xx = x1 + t0*h
if (xx .ge. x(n)) go to 120
il = 1
ir = n
!
!     Bisection search
!
10 i = (il + ir)/2
if (i .eq. il) go to 90
if (xx - x(i)) 20,90,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     Linear forward search
!
40 if (xx .lt. x(i+1)) go to 90
i = i + 1
go to 40
!
!     COMPUTATION WHEN x(i) .LE. xx .LT. x(i+1)
!
90 dx = xx - x(i)
yi(k) = ((c(i)*dx + b(i))*dx + a(i))*dx + y(i)
bi2 = b(i) + b(i)
ci3 = 3.0*c(i)
ypi(k) = (ci3*dx + bi2)*dx + a(i)
yppi(k) = bi2 + (ci3 + ci3)*dx
!
!     Next point
!
100 if (k .ge. m) return
xold = xx
k = k + 1
t = (xi(k) - x1)/h
j = t
t0 = t - j
if (t0 .lt. 0.0) t0 = 1.0 + t0
xx = x1 + t0*h
if (xx .ge. x(n)) go to 120
if (xx - xold) 110,90,40
!
110 il = 1
ir = min0(i+1,n)
go to 10
!
!     Case when roundoff produces a value for xx where
!     xx .GE. x(n). THIS CASE MAY NEVER OCCUR.
!
120 i = 1
xx = x1
yi(k) = y(1)
ypi(k) = a(1)
yppi(k) = b(1) + b(1)
go to 100
end subroutine psevl

subroutine csloop (m, n, x, kx, t, dx, kdx, wk, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: kdx, kx, m, n
integer :: ia, ib, ic, ie, mm1
!-----------------------------------------------------------------------
!               Closed curve cubic spline fitting
!                    in n-dimensional space
!-----------------------------------------------------------------------
!     Written by
!        Alfred H. Morris
!        Naval Surface Warfare Center
!        Dahlgren, Virginia
!----------------------
real, intent(in) :: x(kx,n)
real, intent(inout) :: t(m), dx(kdx,n), wk(*)
!----------------------
!     m = THE NUMBER OF n-DIMENSIONAL POINTS GIVEN IN x
!     wk is an array of dimension 4*(m-1)
!----------------------
if (min0(m, n) .lt. 2) go to 10
!
mm1 = m - 1
ie = 1
ia = mm1
ib = ia + mm1
ic = ib + m
call cslop1 (m, n, x, kx, t, dx, kdx, wk(ia), wk(ib), &
&wk(ic), wk(ie), ierr)
return
!
!     Error return
!
10 ierr = 1
return
end subroutine csloop

subroutine cslop1 (m, n, x, kx, t, dx, kdx, a, b, c, e, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: kdx, kx, m, n
integer :: i, im1, j, l, mm1, mm2
real :: alpha, del, del0, del1, deli, delm, eta, h, hm, p, r, si, &
&sm, sum, tau
real :: snrm2
!-----------------------------------------------------------------------
!               Closed curve cubic spline fitting
!                    in n-dimensional space
!-----------------------------------------------------------------------
real, intent(in) :: x(kx,n)
real, intent(inout) :: t(m), dx(kdx,n), a(*), b(m), c(*), e(*)
!----------------------
!     real a(m-1), c(m-1), e(k)  (k = max0(1,m-2))
!     THE e ARRAY IS NOT USED WHEN m = 2.
!----------------------
mm1 = m - 1
mm2 = m - 2
!
!     DEFINITION OF THE KNOTS t(i) (i = 1,...,m). ALSO t(m+1) = 1.
!     This last knot is not stored.
!
t(1) = 0.0
do i = 2,m
   im1 = i - 1
   do j = 1,n
      dx(i,j) = x(i,j) - x(im1,j)
   end do
   t(i) = t(im1) + snrm2(n,dx(i,1),kdx)
   r = t(i) - t(im1)
   if (r .eq. 0.0) go to 200
end do
!
do j = 1,n
   dx(1,j) = x(1,j) - x(m,j)
end do
sum = t(m) + snrm2(n,dx(1,1),kdx)
r = sum - t(m)
if (r .eq. 0.0) go to 210
!
do i = 2,m
   t(i) = t(i)/sum
end do
ierr = 0
!
!     FOR j = 1,...,n, A DIAGONALLY DOMINANT SET OF EQUATIONS
!     for the slopes S(i,j) of the j-TH periodic spline at t(i)
!     (i = 1,...,m) IS GENERATED AND SOLVED BY GAUSS ELIMINATION.
!     The first equation is obtained from the requirement that
!     the spline be periodic. This equation has the form ...
!
!        a(1)*S(1,j) + b(1)*S(2,j) + c(1)*S(m,j) = dx(1,j)
!
h = t(2)
hm = 1.0 - t(m)
c(1) = h
b(1) = hm
a(1) = 2.0*(h + hm)
b(2) = h
!
do j = 1,n
   delm = dx(1,j)/hm
   del1 = dx(2,j)/h
   dx(1,j) = 3.0*(h*delm + hm*del1)
   dx(2,j) = del1
end do
if (m .eq. 2) go to 70
!
!     FOR THE KNOTS t(i) (i = 2,...m-1), GENERATE THE CORRESPOND-
!     ing equations and carry out the pivot reduction of Gauss
!     elimination. Then the i-TH equation has the form ...
!
!        a(i)*S(i,j) + b(i)*S(i+1,j) + c(i)*S(m,j) = dx(i,j)
!
do i = 2,mm1
   im1 = i - 1
   b(i) = h
   h = t(i+1) - t(i)
   e(im1) = h/a(im1)
   c(i) = - e(im1)*c(im1)
   a(i) = 2.0*(b(i) + h) - e(im1)*b(im1)
end do
b(m) = h
!
do j = 1,n
   deli = dx(2,j)
   do i = 2,mm1
      h = b(i+1)
      del0 = deli
      deli = dx(i+1,j)/h
      dx(i,j) = 3.0*(h*del0 + b(i)*deli) - e(i-1)*dx(i-1,j)
   end do
   dx(m,j) = deli
end do
!
!     Since it is required that the spline be periodic, the
!     equation for the knot t(m) has the form ...
!
!        alpha*S(1,j) + hm*S(m-1,j) + eta*S(m,j) = dx(m,j)
!
!     Applying the pivots to this equation, one obtains after
!     each pivot operation the modified equation ...
!
!        alpha*S(i+1,j) + hm*S(m-1,j) + eta*S(m,j) = dx(m,j)
!
!     Thus, when this pivot reduction is complete, the m-TH
!     equation to be solved has the form ...
!
!        (alpha + hm)*S(m-1,j) + eta*S(m,j) = dx(m,j)
!
70 alpha = h
eta = 2.0*(h + hm)
do j = 1,n
   del  = dx(m,j)
   delm = (x(1,j) - x(m,j))/hm
   dx(m,j) = 3.0*(hm*del + h*delm)
end do
if (m .eq. 2) go to 90
!
do i = 1,mm2
   p = alpha/a(i)
   alpha = - p*b(i)
   eta = eta - p*c(i)
   do j = 1,n
      dx(m,j) = dx(m,j) - p*dx(i,j)
   end do
end do
!
!     Solve the last two equations for S(m,j) and S(m-1,j),
!     and store these slopes in dx.
!
90 p = (alpha + hm)/a(mm1)
tau = b(mm1) + c(mm1)
do j = 1,n
   sm = (dx(m,j) - p*dx(mm1,j))/(eta - p*tau)
   dx(m,j) = sm
   dx(mm1,j) = (dx(mm1,j) - tau*sm)/a(mm1)
end do
if (m .eq. 2) return
!
!     Back substitution to obtain the remaining slopes S(i,j).
!     These slopes are stored in dx.
!
do j = 1,n
   sm = dx(m,j)
   si = dx(mm1,j)
   i = mm1
   do l = 3,m
      i = i - 1
      si = (dx(i,j) - b(i)*si - c(i)*sm)/a(i)
      dx(i,j) = si
   end do
end do
return
!
!     Error return
!
200 ierr = 2
return
210 ierr = 3
return
end subroutine cslop1

subroutine lopcmp (m, n, t, x, kx, dx, kdx, l, ti, z, kz)
implicit none
integer, intent(in) :: kdx, kx, kz, l, m, n
integer :: i, il, ir, j, k
real :: a, b, c, d, dt, h, t0, told, w
!-----------------------------------------------------------------------
!            Evaluation of a cubic spline closed curve
!                     in n-dimensional space
!-----------------------------------------------------------------------
real, intent(in) :: t(m), x(kx,n), dx(kdx,n), ti(l)
real, intent(inout) :: z(kz, n)
!
!     REDUCTION OF ti(k) TO t0 WHERE 0 .LE. t0 .LT. 1
!
k = 1
j = ti(1)
t0 = ti(1) - j
if (t0 .lt. 0.0) t0 = 1.0 + t0
if (t0 .ge. t(m)) go to 60
il = 1
ir = m
!
!     Bisection search
!
10 i = (il + ir)/2
if (i .eq. il) go to 50
if (t0 - t(i)) 20,50,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     Linear forward search
!
40 if (t0 .lt. t(i+1)) go to 50
i = i + 1
go to 40
!
!     COMPUTATION WHEN t(i) .LE. t0 .LT. t(i+1)
!
50 h = t(i+1) - t(i)
dt = t0 - t(i)
do j = 1,n
   a = dx(i,j)
   d = (x(i+1,j) - x(i,j))/h
   w = a + dx(i+1,j)
   b = (-w - a + 3.0*d)/h
   c = ((w - d - d)/h)/h
   z(k,j) = x(i,j) + dt*(a + dt*(b + dt*c))
end do
go to 100
!
!     COMPUTATION WHEN t0 .GE. t(m)
!
60 i = m
h = 1.0 - t(m)
dt = t0 - t(m)
do j = 1,n
   a = dx(m,j)
   d = (x(1,j) - x(m,j))/h
   w = a + dx(1,j)
   b = (-w - a + 3.0*d)/h
   c = ((w - d - d)/h)/h
   z(k,j) = x(m,j) + dt*(a + dt*(b + dt*c))
end do
!
!     Next point
!
100 if (k .ge. l) return
told = t0
k = k + 1
j = ti(k)
t0 = ti(k) - j
if (t0 .lt. 0.0) t0 = 1.0 + t0
if (t0 .ge. t(m)) go to 60
if (t0 - told) 110,50,40
!
110 il = 1
ir = min0(i+1,m)
go to 10
end subroutine lopcmp

subroutine lopdf (m, n, t, x, kx, dx, kdx, ti, z, dz, ddz)
implicit none
integer, intent(in) :: kdx, kx, m, n
real, intent(in) :: ti
integer :: i, il, ir, j
real :: a, b, c, d, dt, h, t0, w
!-----------------------------------------------------------------------
!          Evaluation and differentiation of a cubic spline
!                closed curve in n-dimensional space
!-----------------------------------------------------------------------
real, intent(in) :: t(m), x(kx,n), dx(kdx,n)
real, intent(inout) :: z(n), dz(n), ddz(n)
!
!     REDUCTION OF ti TO t0 WHERE 0 .LE. t0 .LT. 1
!
j = ti
t0 = ti - j
if (t0 .lt. 0.0) t0 = 1.0 + t0
if (t0 .ge. t(m)) go to 50
il = 1
ir = m
!
!     Bisection search
!
10 i = (il + ir)/2
if (i .eq. il) go to 40
if (t0 - t(i)) 20,40,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     COMPUTATION WHEN t(i) .LE. t0 .LT. t(i+1)
!
40 h = t(i+1) - t(i)
dt = t0 - t(i)
do j = 1,n
   a = dx(i,j)
   d = (x(i+1,j) - x(i,j))/h
   w = a + dx(i+1,j)
   b = (-w - a + 3.0*d)/h
   c = ((w - d - d)/h)/h
   z(j) = x(i,j) + dt*(a + dt*(b + dt*c))
   b = b + b
   c = 3.0*c
   dz(j) = a + dt*(b + c*dt)
   ddz(j) = b + (c + c)*dt
end do
return
!
!     COMPUTATION WHEN t0 .GE. t(m)
!
50 h = 1.0 - t(m)
dt = t0 - t(m)
do j = 1,n
   a = dx(m,j)
   d = (x(1,j) - x(m,j))/h
   w = a + dx(1,j)
   b = (-w - a + 3.0*d)/h
   c = ((w - d - d)/h)/h
   z(j) = x(m,j) + dt*(a + dt*(b + dt*c))
   b = b + b
   c = 3.0*c
   dz(j) = a + dt*(b + c*dt)
   ddz(j) = b + (c + c)*dt
end do
return
end subroutine lopdf

subroutine curv1 (n,x,y,slp1,slpn,islpsw,yp,temp, &
&sigma,ierr)
implicit none
integer :: i, ibak, nm1, np1
real :: c1, c2, c3, delx1, delx2, delxn, delxnm, diag, diag1, &
&diag2, dx1, dx2, sdiag1, sdiag2, sigmap, slpp1, slppn
!
integer, intent(in) :: n, islpsw
integer, intent(out) :: ierr
real, intent(in) :: x(n), y(n), slp1, slpn
real, intent(inout) :: yp(n), temp(n)
real, intent(in) :: sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This subroutine determines the parameters necessary to
! compute an interpolatory spline under tension through
! a sequence of functional values. The slopes at the two
! ends of the curve may be specified or omitted.  For actual
! computation of points on the curve it is necessary to call
! the function curv2.
!
! On input--
!
!   n IS THE NUMBER OF VALUES TO BE INTERPOLATED (n.GE.2).
!
!   x is an array of the n increasing abscissae of the
!   functional values.
!
!   y is an array of the n ordinates of the values, (I. E.
!   y(K) is the functional value corresponding to x(K) ).
!
!   slp1 and slpn contain the desired values for the first
!   derivative of the curve at x(1) and x(n), respectively.
!   The user may omit values for either or both of these
!   parameters and signal this with islpsw.
!
!   islpsw contains a switch indicating which slope data
!   should be used and which should be estimated by this
!   subroutine,
!          = 0 IF slp1 AND slpn ARE TO BE USED,
!          = 1 IF slp1 IS TO BE USED BUT NOT slpn,
!          = 2 IF slpn IS TO BE USED BUT NOT slp1,
!          = 3 IF BOTH slp1 AND slpn ARE TO BE ESTIMATED
!              internally.
!
!   yp is an array of length at least n.
!
!   Temp is an array of length at least n which is used for
!   scratch storage.
!
! And
!
!   sigma contains the tension factor. This value indicates
!   the curviness desired. If abs(sigma) is nearly zero
!   (E.G. .001) The resulting curve is approximately A
!   cubic spline. If abs(sigma) is large (E.G. 50.) The
!   resulting curve is nearly a polygonal line. If sigma
!   equals zero a cubic spline results.  A standard value
!   for sigma is approximately 1. In absolute value.
!
! On output--
!
!   yp contains the values of the second derivative of the
!   curve at the given nodes.
!
!   ierr contains an error flag,
!        = 0 FOR NORMAL RETURN,
!        = 1 IF n IS LESS THAN 2,
!        = 2 IF x-VALUES ARE NOT STRICTLY INCREASING.
!
! And
!
!   n, x, y, slp1, slpn, islpsw and sigma are unaltered.
!
! This subroutine references package modules ceez, terms,
! and snhcsh.
!
!-----------------------------------------------------------
!
nm1 = n-1
np1 = n+1
ierr = 0
if (n .le. 1) go to 8
if (x(n) .le. x(1)) go to 9
!
! Denormalize tension factor
!
sigmap = abs(sigma)*float(n-1)/(x(n)-x(1))
!
! Approximate end slopes
!
if (islpsw .ge. 2) go to 1
slpp1 = slp1
go to 2
1 delx1 = x(2)-x(1)
delx2 = delx1+delx1
if (n .gt. 2) delx2 = x(3)-x(1)
if (delx1 .le. 0. .or. delx2 .le. delx1) go to 9
call ceez (delx1,delx2,sigmap,c1,c2,c3,n)
slpp1 = c1*y(1)+c2*y(2)
if (n .gt. 2) slpp1 = slpp1+c3*y(3)
2 if (islpsw .eq. 1 .or. islpsw .eq. 3) go to 3
slppn = slpn
go to 4
3 delxn = x(n)-x(nm1)
delxnm = delxn+delxn
if (n .gt. 2) delxnm = x(n)-x(n-2)
if (delxn .le. 0. .or. delxnm .le. delxn) go to 9
call ceez (-delxn,-delxnm,sigmap,c1,c2,c3,n)
slppn = c1*y(n)+c2*y(nm1)
if (n .gt. 2) slppn = slppn+c3*y(n-2)
!
! Set up right hand side and tridiagonal system for yp and
! perform forward elimination
!
4 delx1 = x(2)-x(1)
if (delx1 .le. 0.) go to 9
dx1 = (y(2)-y(1))/delx1
call terms (diag1,sdiag1,sigmap,delx1)
yp(1) = (dx1-slpp1)/diag1
temp(1) = sdiag1/diag1
if (n .eq. 2) go to 6
do 5 i = 2,nm1
  delx2 = x(i+1)-x(i)
  if (delx2 .le. 0.) go to 9
  dx2 = (y(i+1)-y(i))/delx2
  call terms (diag2,sdiag2,sigmap,delx2)
  diag = diag1+diag2-sdiag1*temp(i-1)
  yp(i) = (dx2-dx1-sdiag1*yp(i-1))/diag
  temp(i) = sdiag2/diag
  dx1 = dx2
  diag1 = diag2
5 sdiag1 = sdiag2
6 diag = diag1-sdiag1*temp(nm1)
yp(n) = (slppn-dx1-sdiag1*yp(nm1))/diag
!
! Perform back substitution
!
do 7 i = 2,n
  ibak = np1-i
7 yp(ibak) = yp(ibak)-temp(ibak)*yp(ibak+1)
return
!
! Too few points
!
8 ierr = 1
return
!
! x-values not strictly increasing
!
9 ierr = 2
return
end subroutine curv1

function curv2 (t,n,x,y,yp,sigma)
implicit none
integer :: i, im1
real :: coshp1, coshp2, del1, del2, delp1, delp2, dels, dummy, &
&sigmap, sinhm1, sinhm2, sinhms, sinhp1, sinhp2, sum
integer :: intrvl
real :: curv2
!
integer, intent(in) :: n
real, intent(in) :: t, x(n), y(n), yp(n), sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This function interpolates a curve at a given point
! using a spline under tension. The subroutine curv1 should
! be called earlier to determine certain necessary
! parameters.
!
! On input--
!
!   t contains a real value to be mapped onto the interpo-
!   LATING CURVE.
!
!   n contains the number of points which were specified to
!   determine the curve.
!
!   x and y are arrays containing the abscissae and
!   ordinates, respectively, of the specified points.
!
!   yp is an array of second derivative values of the curve
!   at the nodes.
!
! And
!
!   sigma contains the tension factor (its sign is ignored).
!
! The parameters n, x, y, yp, and sigma should be input
! unaltered from the output of curv1.
!
! On output--
!
!   curv2 contains the interpolated value.
!
! None of the input parameters are altered.
!
! This function references package modules intrvl and
! snhcsh.
!
!-----------------------------------------------------------
!
! Determine interval
!
im1 = intrvl(t,x,n)
i = im1+1
!
! Denormalize tension factor
!
sigmap = abs(sigma)*float(n-1)/(x(n)-x(1))
!
! Set up and perform interpolation
!
del1 = t-x(im1)
del2 = x(i)-t
dels = x(i)-x(im1)
sum = (y(i)*del1+y(im1)*del2)/dels
if (sigmap .ne. 0.) go to 1
curv2 = sum-del1*del2*(yp(i)*(del1+dels)+yp(im1)* &
&(del2+dels))/(6.*dels)
return
1 delp1 = sigmap*(del1+dels)/2.
delp2 = sigmap*(del2+dels)/2.
call snhcsh (sinhm1,dummy,sigmap*del1,-1)
call snhcsh (sinhm2,dummy,sigmap*del2,-1)
call snhcsh (sinhms,dummy,sigmap*dels,-1)
call snhcsh (sinhp1,dummy,sigmap*del1/2.,-1)
call snhcsh (sinhp2,dummy,sigmap*del2/2.,-1)
call snhcsh (dummy,coshp1,delp1,1)
call snhcsh (dummy,coshp2,delp2,1)
curv2 = sum+(yp(i)*(sinhm1*del2-del1*(2.*(coshp1+1.)* &
&sinhp2+sigmap*coshp1*del2))+yp(im1)*(sinhm2* &
&del1-del2*(2.*(coshp2+1.)*sinhp1+sigmap* &
&coshp2*del1)))/(sigmap*sigmap*dels*(sinhms+ &
&sigmap*dels))
return
end function curv2

function curvd (t,n,x,y,yp,sigma)
implicit none
integer :: i, im1
real :: coshm1, coshm2, del1, del2, dels, dummy, sigmap, sinhms, &
&sum
integer :: intrvl
real :: curvd
!
integer, intent(in) :: n
real, intent(in) :: t, x(n), y(n), yp(n), sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This function differentiates a curve at a given point
! using a spline under tension. The subroutine curv1 should
! be called earlier to determine certain necessary
! parameters.
!
! On input--
!
!   t contains a real value at which the derivative is to be
!   determined.
!
!   n contains the number of points which were specified to
!   determine the curve.
!
!   x and y are arrays containing the abscissae and
!   ordinates, respectively, of the specified points.
!
!   yp is an array of second derivative values of the curve
!   at the nodes.
!
! And
!
!   sigma contains the tension factor (its sign is ignored).
!
! The parameters n, x, y, yp, and sigma should be input
! unaltered from the output of curv1.
!
! On output--
!
!   curvd contains the derivative value.
!
! None of the input parameters are altered.
!
! This function references package modules intrvl and
! snhcsh.
!
!-----------------------------------------------------------
!
! Determine interval
!
im1 = intrvl(t,x,n)
i = im1+1
!
! Denormalize tension factor
!
sigmap = abs(sigma)*float(n-1)/(x(n)-x(1))
!
! Set up and perform differentiation
!
del1 = t-x(im1)
del2 = x(i)-t
dels = x(i)-x(im1)
sum = (y(i)-y(im1))/dels
if (sigmap .ne. 0.) go to 1
curvd = sum+(yp(i)*(2.*del1*del1-del2*(del1+dels))- &
&yp(im1)*(2.*del2*del2-del1*(del2+dels))) &
&/(6.*dels)
return
1 call snhcsh (dummy,coshm1,sigmap*del1,1)
call snhcsh (dummy,coshm2,sigmap*del2,1)
call snhcsh (sinhms,dummy,sigmap*dels,-1)
curvd = sum+(yp(i)*(dels*sigmap*coshm1-sinhms)- &
&yp(im1)*(dels*sigmap*coshm2-sinhms))/ &
&(sigmap*sigmap*dels*(sinhms+sigmap*dels))
return
end function curvd

function curvi (xl,xu,n,x,y,yp,sigma)
implicit none
integer :: i, il, ilm1, ilp1, iu, ium1
real :: c1, c2, cl1, cl2, cmm1, cmm2, cs, cu1, cu2, del1, del2, &
&deli, dell1, dell2, dels, delu1, delu2, dummy, sigmap, ss, ssign, &
&sum, t, t1, t2, xxl, xxu
integer :: intrvl
real :: curvi
real :: term
!
integer, intent(in) :: n
real, intent(in) :: xl, xu, x(n), y(n), yp(n), sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This function integrates a curve specified by a spline
! under tension between two given limits. The subroutine
! curv1 should be called earlier to determine necessary
! parameters.
!
! On input--
!
!   xl and xu contain the lower and upper limits of inte-
!   gration, respectively. (xl need not be less than or
!   EQUAL TO xu, curvi (xl,xu,...) .EQ. -curvi (xu,xl,...) ).
!
!   n contains the number of points which were specified to
!   determine the curve.
!
!   x and y are arrays containing the abscissae and
!   ordinates, respectively, of the specified points.
!
!   yp is an array of second derivative values of the curve
!   at the nodes.
!
! And
!
!   sigma contains the tension factor (its sign is ignored).
!
! The parameters n, x, y, yp, and sigma should be input
! unaltered from the output of curv1.
!
! On output--
!
!   curvi contains the integral value.
!
! None of the input parameters are altered.
!
! This function references package modules intrvl and
! snhcsh.
!
!-----------------------------------------------------------
!
! Statement function for coefficient associated with
! derivative terms
!
term (cmm1,cmm2,t) = (cmm1-cmm2-sigmap*t*ss)/(sigmap* &
&sigmap*sigmap*(ss+sigmap*dels))
!
! Denormalize tension factor
!
sigmap = abs(sigma)*float(n-1)/(x(n)-x(1))
!
! Determine actual upper and lower bounds
!
xxl = xl
xxu = xu
ssign = 1.
if (xl .lt. xu) go to 1
xxl = xu
xxu = xl
ssign = -1.
if (xl .gt. xu) go to 1
!
! RETURN ZERO IF xl .EQ. xu
!
curvi = 0.
return
!
! Search for proper intervals
!
1 ilm1 = intrvl (xxl,x,n)
il = ilm1+1
ium1 = intrvl (xxu,x,n)
iu = ium1+1
if (il .eq. iu) go to 8
!
! Integrate from xxl to x(il)
!
sum = 0.
if (xxl .eq. x(il)) go to 3
del1 = xxl-x(ilm1)
del2 = x(il)-xxl
dels = x(il)-x(ilm1)
t1 = (del1+dels)*del2/(2.*dels)
t2 = del2*del2/(2.*dels)
sum = t1*y(il)+t2*y(ilm1)
if (sigma .eq. 0.) go to 2
call snhcsh (dummy,c1,sigmap*del1,2)
call snhcsh (dummy,c2,sigmap*del2,2)
call snhcsh (ss,cs,sigmap*dels,3)
sum = sum+term(cs,c1,t1)*yp(il) &
&+term(c2,0.,t2)*yp(ilm1)
go to 3
2 sum = sum-t1*t1*dels*yp(il)/6. &
&-t2*(del1*(del2+dels)+dels*dels)*yp(ilm1)/12.
!
! Integrate over interior intervals
!
3 if (iu-il .eq. 1) go to 6
ilp1 = il+1
do 5 i = ilp1,ium1
  dels = x(i)-x(i-1)
  sum = sum+(y(i)+y(i-1))*dels/2.
  if (sigma .eq. 0.) go to 4
  call snhcsh (ss,cs,sigmap*dels,3)
  sum = sum+(yp(i)+yp(i-1))*(cs-ss*sigmap*dels/2.)/ &
&(sigmap*sigmap*sigmap*(ss+sigmap*dels))
  go to 5
4 sum = sum-(yp(i)+yp(i-1))*dels*dels*dels/24.
5 continue
!
! Integrate from x(iu-1) to XXU
!
6 if (xxu .eq. x(ium1)) go to 10
del1 = xxu-x(ium1)
del2 = x(iu)-xxu
dels = x(iu)-x(ium1)
t1 = del1*del1/(2.*dels)
t2 = (del2+dels)*del1/(2.*dels)
sum = sum+t1*y(iu)+t2*y(ium1)
if (sigma .eq. 0.) go to 7
call snhcsh (dummy,c1,sigmap*del1,2)
call snhcsh (dummy,c2,sigmap*del2,2)
call snhcsh (ss,cs,sigmap*dels,3)
sum = sum+term(c1,0.,t1)*yp(iu) &
&+term(cs,c2,t2)*yp(ium1)
go to 10
7 sum = sum-t1*(del2*(del1+dels)+dels*dels)*yp(iu)/12. &
&-t2*t2*dels*yp(ium1)/6.
go to 10
!
! Integrate from xxl to XXU
!
8 delu1 = xxu-x(ium1)
delu2 = x(iu)-xxu
dell1 = xxl-x(ium1)
dell2 = x(iu)-xxl
dels = x(iu)-x(ium1)
deli = xxu-xxl
t1 = (delu1+dell1)*deli/(2.*dels)
t2 = (delu2+dell2)*deli/(2.*dels)
sum = t1*y(iu)+t2*y(ium1)
if (sigma .eq. 0.) go to 9
call snhcsh (dummy,cu1,sigmap*delu1,2)
call snhcsh (dummy,cu2,sigmap*delu2,2)
call snhcsh (dummy,cl1,sigmap*dell1,2)
call snhcsh (dummy,cl2,sigmap*dell2,2)
call snhcsh (ss,dummy,sigmap*dels,-1)
sum = sum+term(cu1,cl1,t1)*yp(iu) &
&+term(cl2,cu2,t2)*yp(ium1)
go to 10
9 sum = sum-t1*(delu2*(dels+delu1)+dell2*(dels+dell1))* &
&yp(iu)/12. &
&-t2*(dell1*(dels+dell2)+delu1*(dels+delu2))* &
&yp(ium1)/12.
!
! Correct sign and return
!
10 curvi = ssign*sum
return
end function curvi

subroutine kurv1 (n,x,y,slp1,slpn,islpsw,xp,yp,temp,s, &
&sigma,ierr)
implicit none
integer :: i, ibak, im1, nm1, np1
real :: c1, c2, c3, dels1, dels2, delsn, delsnm, delt, diag, &
&diag1, diag2, diagin, dx1, dx2, dy1, dy2, sdiag1, sdiag2, sigmap, &
&slpp1x, slpp1y, slppnx, slppny, sx, sy
!
integer, intent(in) :: n, islpsw
integer, intent(out) :: ierr
real, intent(in) :: x(n), y(n), slp1, slpn
real, intent(inout) :: xp(n), yp(n), temp(n), s(n)
real, intent(in) :: sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This subroutine determines the parameters necessary to
! compute a spline under tension forming a curve in the
! plane and passing through a sequence of pairs (x(1),y(1)),
! ...,(x(n),y(n)). For actual computation of points on the
! curve it is necessary to call the subroutine kurv2.
!
! On input--
!
!   n IS THE NUMBER OF POINTS TO BE INTERPOLATED (n.GE.2).
!
!   x is an array containing the n x-coordinates of the
!   points.
!
!   y is an array containing the n y-coordinates of the
!   points. (Adjacent x-y pairs must be distinct, I. E.
!   EITHER x(i) .NE. x(i+1) OR y(i) .NE. y(i+1), FOR
!   i = 1,...,n-1.)
!
!   slp1 and slpn contain the desired values for the angles
!   (in radians) of the slope at (x(1),y(1)) and (x(n),y(n))
!   respectively. The angles are measured counter-clock-
!   wise from the x-axis and the positive sense of the curve
!   is assumed to be that moving from point 1 to point n.
!   The user may omit values for either or both of these
!   parameters and signal this with islpsw.
!
!   islpsw contains a switch indicating which slope data
!   should be used and which should be estimated by this
!   subroutine,
!          = 0 IF slp1 AND slpn ARE TO BE USED,
!          = 1 IF slp1 IS TO BE USED BUT NOT slpn,
!          = 2 IF slpn IS TO BE USED BUT NOT slp1,
!          = 3 IF BOTH slp1 AND slpn ARE TO BE ESTIMATED
!              internally.
!
!   xp and yp are arrays of length at least n.
!
!   Temp is an array of length at least n which is used
!   for scratch storage.
!
!   s is an array of length at least n.
!
! And
!
!   sigma contains the tension factor. This value indicates
!   the curviness desired. If abs(sigma) is nearly zero
!   (E.G. .001) The resulting curve is approximately a cubic
!   spline. If abs(sigma) is large (E. G. 50.) The resulting
!   curve is nearly a polygonal line. If sigma equals zero A
!   cubic spline results. A standard value for sigma is
!   approximately 1. In absolute value.
!
! On output--
!
!   xp and yp contain information about the curvature of the
!   curve at the given nodes.
!
!   s contains the polygonal arclengths of the curve.
!
!   ierr contains an error flag,
!        = 0 FOR NORMAL RETURN,
!        = 1 IF n IS LESS THAN 2,
!        = 2 IF ADJACENT COORDINATE PAIRS COINCIDE.
!
! And
!
!   n, x, y, slp1, slpn, islpsw, and sigma are unaltered.
!
! This subroutine references package modules ceez, terms,
! and snhcsh.
!
!-----------------------------------------------------------
!
nm1 = n-1
np1 = n+1
ierr = 0
if (n .le. 1) go to 11
!
! Determine polygonal arclengths
!
s(1) = 0.
do 1 i = 2,n
  im1 = i-1
1 s(i) = s(im1)+sqrt((x(i)-x(im1))**2+ &
&(y(i)-y(im1))**2)
!
! Denormalize tension factor
!
sigmap = abs(sigma)*float(n-1)/s(n)
!
! Approximate end slopes
!
if (islpsw .ge. 2) go to 2
slpp1x = cos(slp1)
slpp1y = sin(slp1)
go to 4
2 dels1 = s(2)-s(1)
dels2 = dels1+dels1
if (n .gt. 2) dels2 = s(3)-s(1)
if (dels1 .eq. 0. .or. dels2 .eq. 0.) go to 12
call ceez (dels1,dels2,sigmap,c1,c2,c3,n)
sx = c1*x(1)+c2*x(2)
sy = c1*y(1)+c2*y(2)
if (n .eq. 2) go to 3
sx = sx+c3*x(3)
sy = sy+c3*y(3)
3 delt = sqrt(sx*sx+sy*sy)
slpp1x = sx/delt
slpp1y = sy/delt
4 if (islpsw .eq. 1 .or. islpsw .eq. 3) go to 5
slppnx = cos(slpn)
slppny = sin(slpn)
go to 7
5 delsn = s(n)-s(nm1)
delsnm = delsn+delsn
if (n .gt. 2) delsnm = s(n)-s(n-2)
if (delsn .eq. 0. .or. delsnm .eq. 0.) go to 12
call ceez (-delsn,-delsnm,sigmap,c1,c2,c3,n)
sx = c1*x(n)+c2*x(nm1)
sy = c1*y(n)+c2*y(nm1)
if (n .eq. 2) go to 6
sx = sx+c3*x(n-2)
sy = sy+c3*y(n-2)
6 delt = sqrt(sx*sx+sy*sy)
slppnx = sx/delt
slppny = sy/delt
!
! Set up right hand sides and tridiagonal system for xp and
! yp and perform forward elimination
!
7 dx1 = (x(2)-x(1))/s(2)
dy1 = (y(2)-y(1))/s(2)
call terms (diag1,sdiag1,sigmap,s(2))
xp(1) = (dx1-slpp1x)/diag1
yp(1) = (dy1-slpp1y)/diag1
temp(1) = sdiag1/diag1
if (n .eq. 2) go to 9
do 8 i = 2,nm1
  dels2 = s(i+1)-s(i)
  if (dels2 .eq. 0.) go to 12
  dx2 = (x(i+1)-x(i))/dels2
  dy2 = (y(i+1)-y(i))/dels2
  call terms (diag2,sdiag2,sigmap,dels2)
  diag = diag1+diag2-sdiag1*temp(i-1)
  diagin = 1./diag
  xp(i) = (dx2-dx1-sdiag1*xp(i-1))*diagin
  yp(i) = (dy2-dy1-sdiag1*yp(i-1))*diagin
  temp(i) = sdiag2*diagin
  dx1 = dx2
  dy1 = dy2
  diag1 = diag2
8 sdiag1 = sdiag2
9 diag = diag1-sdiag1*temp(nm1)
xp(n) = (slppnx-dx1-sdiag1*xp(nm1))/diag
yp(n) = (slppny-dy1-sdiag1*yp(nm1))/diag
!
! Perform back substitution
!
do 10 i = 2,n
  ibak = np1-i
  xp(ibak) = xp(ibak)-temp(ibak)*xp(ibak+1)
10 yp(ibak) = yp(ibak)-temp(ibak)*yp(ibak+1)
return
!
! Too few points
!
11 ierr = 1
return
!
! Coincident adjacent points
!
12 ierr = 2
return
end subroutine kurv1

subroutine kurv2 (t,xs,ys,n,x,y,xp,yp,s,sigma)
implicit none
integer :: i, im1
real :: c1, c2, coshp1, coshp2, d, del1, del2, delp1, delp2, dels, &
&dummy, sigmap, sinhm1, sinhm2, sinhms, sinhp1, sinhp2, sumx, sumy, &
&tn
integer :: intrvl
!
integer, intent(in) :: n
real, intent(in) :: t
real, intent(inout) :: xs, ys
real, intent(in) :: x(n), y(n), xp(n), yp(n), s(n), sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This subroutine performs the mapping of points in the
! interval (0.,1.) Onto a curve in the plane. The subroutine
! kurv1 should be called earlier to determine certain
! necessary parameters. The resulting curve has a parametric
! representation both of whose components are splines under
! tension and functions of the polygonal arclength
! parameter.
!
! On input--
!
!   t contains a real value to be mapped to a point on the
!   curve. The interval (0.,1.) Is mapped onto the entire
!   curve, with 0. Mapping to (x(1),y(1)) and 1. Mapping
!   to (x(n),y(n)). Values outside this interval result in
!   extrapolation.
!
!   n contains the number of points which were specified
!   to determine the curve.
!
!   x and y are arrays containing the x- and y-coordinates
!   of the specified points.
!
!   xp and yp are the arrays output from kurv1 containing
!   curvature information.
!
!   s is an array containing the polygonal arclengths of
!   the curve.
!
! And
!
!   sigma contains the tension factor (its sign is ignored).
!
! The parameters n, x, y, xp, yp, s, and sigma should be
! input unaltered from the output of kurv1.
!
! On output--
!
!   xs and ys contain the x- and y-coordinates of the image
!   point on the curve.
!
! None of the input parameters are altered.
!
! This subroutine references package modules intrvl and
! snhcsh.
!
!-----------------------------------------------------------
!
! Determine interval
!
tn = s(n)*t
im1 = intrvl(tn,s,n)
i = im1+1
!
! Denormalize tension factor
!
sigmap = abs(sigma)*float(n-1)/s(n)
!
! Set up and perform interpolation
!
del1 = tn-s(im1)
del2 = s(i)-tn
dels = s(i)-s(im1)
sumx = (x(i)*del1+x(im1)*del2)/dels
sumy = (y(i)*del1+y(im1)*del2)/dels
if (sigmap .ne. 0.) go to 1
d = del1*del2/(6.*dels)
c1 = (del1+dels)*d
c2 = (del2+dels)*d
xs = sumx-xp(i)*c1-xp(im1)*c2
ys = sumy-yp(i)*c1-yp(im1)*c2
return
1 delp1 = sigmap*(del1+dels)/2.
delp2 = sigmap*(del2+dels)/2.
call snhcsh(sinhm1,dummy,sigmap*del1,-1)
call snhcsh(sinhm2,dummy,sigmap*del2,-1)
call snhcsh(sinhms,dummy,sigmap*dels,-1)
call snhcsh (sinhp1,dummy,sigmap*del1/2.,-1)
call snhcsh (sinhp2,dummy,sigmap*del2/2.,-1)
call snhcsh (dummy,coshp1,delp1,1)
call snhcsh (dummy,coshp2,delp2,1)
d = sigmap*sigmap*dels*(sinhms+sigmap*dels)
c1 = (sinhm1*del2-del1*(2.*(coshp1+1.)*sinhp2+sigmap* &
&coshp1*del2))/d
c2 = (sinhm2*del1-del2*(2.*(coshp2+1.)*sinhp1+sigmap* &
&coshp2*del1))/d
xs = sumx+xp(i)*c1+xp(im1)*c2
ys = sumy+yp(i)*c1+yp(im1)*c2
return
end subroutine kurv2

subroutine kurvp1 (n,x,y,xp,yp,temp,s,sigma,ierr)
implicit none
integer :: i, ibak, im1, nm1, np1, npi, npibak
real :: dels1, dels2, diag, diag1, diag2, diagin, dx1, dx2, dy1, &
&dy2, sdiag1, sdiag2, sigmap, xpn, ypn
!
integer, intent(in) :: n
integer, intent(out) :: ierr
real, intent(in) :: x(n), y(n)
real, intent(inout) :: xp(n), yp(n), temp(*), s(n)
real, intent(in) :: sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This subroutine determines the parameters necessary to
! compute a spline under tension forming a closed curve in
! the plane and passing through a sequence of pairs
! (x(1),y(1)),...,(x(n),y(n)). For actual computation of
! points on the curve it is necessary to call the subroutine
! kurvp2.
!
! On input--
!
!   n IS THE NUMBER OF POINTS TO BE INTERPOLATED (n.GE.2).
!
!   x is an array containing the n x-coordinates of the
!   points.
!
!   y is an array containing the n y-coordinates of the
!   points. (Adjacent x-y pairs must be distinct, I. E.
!   EITHER x(i) .NE. x(i+1) OR y(i) .NE. y(i+1), FOR
!   i = 1,...,n-1.)
!
!   xp and yp are arrays of length at least n.
!
!   Temp is an array of length at least 2*n which is used
!   for scratch storage.
!
!   s is an array of length at least n.
!
! And
!
!   sigma contains the tension factor. This value indicates
!   the curviness desired. If abs(sigma) is nearly zero
!   (E.G. .001) The resulting curve is approximately a cubic
!   spline. If abs(sigma) is large (E. G. 50.) The resulting
!   curve is nearly a polygonal line. If sigma equals zero A
!   cubic spline results. A standard value for sigma is
!   approximately 1. In absolute value.
!
! On output--
!
!   xp and yp contain information about the curvature of the
!   curve at the given nodes.
!
!   s contains the polygonal arclengths of the curve.
!
!   ierr contains an error flag,
!        = 0 FOR NORMAL RETURN,
!        = 1 IF n IS LESS THAN 2,
!        = 2 IF ADJACENT COORDINATE PAIRS COINCIDE.
!
! And
!
!   n, x, y, and sigma are unaltered,
!
! This subroutine references package modules terms and
! snhcsh.
!
!-----------------------------------------------------------
!
nm1 = n-1
np1 = n+1
ierr = 0
if (n .le. 1) go to 7
!
! Determine polygonal arclengths
!
s(1) = sqrt((x(n)-x(1))**2+(y(n)-y(1))**2)
do 1 i = 2,n
  im1 = i-1
1 s(i) = s(im1)+sqrt((x(i)-x(im1))**2+ &
&(y(i)-y(im1))**2)
!
! Denormalize tension factor
!
sigmap = abs(sigma)*float(n)/s(n)
!
! Set up right hand sides of tridiagonal (with corner
! elements) linear system for xp and yp
!
dels1 = s(1)
if (dels1 .eq. 0.) go to 8
dx1 = (x(1)-x(n))/dels1
dy1 = (y(1)-y(n))/dels1
call terms(diag1,sdiag1,sigmap,dels1)
dels2 = s(2)-s(1)
if (dels2 .eq. 0.) go to 8
dx2 = (x(2)-x(1))/dels2
dy2 = (y(2)-y(1))/dels2
call terms(diag2,sdiag2,sigmap,dels2)
diag = diag1+diag2
diagin = 1./diag
xp(1) = (dx2-dx1)*diagin
yp(1) = (dy2-dy1)*diagin
temp(np1) = -sdiag1*diagin
temp(1) = sdiag2*diagin
dx1 = dx2
dy1 = dy2
diag1 = diag2
sdiag1 = sdiag2
if (n .eq. 2) go to 3
do 2 i = 2,nm1
  npi = n+i
  dels2 = s(i+1)-s(i)
  if (dels2 .eq. 0.) go to 8
  dx2 = (x(i+1)-x(i))/dels2
  dy2 = (y(i+1)-y(i))/dels2
  call terms(diag2,sdiag2,sigmap,dels2)
  diag = diag1+diag2-sdiag1*temp(i-1)
  diagin = 1./diag
  xp(i) = (dx2-dx1-sdiag1*xp(i-1))*diagin
  yp(i) = (dy2-dy1-sdiag1*yp(i-1))*diagin
  temp(npi) = -temp(npi-1)*sdiag1*diagin
  temp(i) = sdiag2*diagin
  dx1 = dx2
  dy1 = dy2
  diag1 = diag2
2 sdiag1 = sdiag2
3 dels2 = s(1)
dx2 = (x(1)-x(n))/dels2
dy2 = (y(1)-y(n))/dels2
call terms(diag2,sdiag2,sigmap,dels2)
xp(n) = dx2-dx1
yp(n) = dy2-dy1
temp(nm1) = temp(2*n-1)-temp(nm1)
if (n.eq.2) go to 5
!
! Perform first step of back substitution
!
do 4 i = 3,n
  ibak = np1-i
  npibak = n+ibak
  xp(ibak) = xp(ibak)-temp(ibak)*xp(ibak+1)
  yp(ibak) = yp(ibak)-temp(ibak)*yp(ibak+1)
4 temp(ibak) = temp(npibak)-temp(ibak)*temp(ibak+1)
5 xp(n) = (xp(n)-sdiag2*xp(1)-sdiag1*xp(nm1))/ &
&(diag1+diag2+sdiag2*temp(1)+sdiag1*temp(nm1))
yp(n) = (yp(n)-sdiag2*yp(1)-sdiag1*yp(nm1))/ &
&(diag1+diag2+sdiag2*temp(1)+sdiag1*temp(nm1))
!
! Perform second step of back substitution
!
xpn = xp(n)
ypn = yp(n)
do 6 i = 1,nm1
  xp(i) = xp(i)+temp(i)*xpn
6 yp(i) = yp(i)+temp(i)*ypn
return
!
! Too few points
!
7 ierr = 1
return
!
! Coincident adjacent points
!
8 ierr = 2
return
end subroutine kurvp1

subroutine kurvp2 (t,xs,ys,n,x,y,xp,yp,s,sigma)
implicit none
integer :: i, im1
real :: c1, c2, ci, cim1, coshp1, coshp2, d, del1, del2, delp1, &
&delp2, dels, dummy, si, sigmap, sinhm1, sinhm2, sinhms, sinhp1, &
&sinhp2, sumx, sumy, tn
integer :: intrvl
!
integer, intent(in) :: n
real, intent(in) :: t
real, intent(inout) :: xs, ys
real, intent(in) :: x(n), y(n), xp(n), yp(n), s(n), sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This subroutine performs the mapping of points in the
! interval (0.,1.) Onto a closed curve in the plane. The
! subroutine kurvp1 should be called earlier to determine
! certain necessary parameters. The resulting curve has A
! parametric representation both of whose components are
! periodic splines under tension and functions of the poly-
! gonal arclength parameter.
!
! On input--
!
!   t contains a value to be mapped onto the curve. The
!   interval (0.,1.) Is mapped onto the entire closed curve
!   with both 0. And 1. Mapping to (x(1),y(1)). The mapping
!   is periodic with period one thus any interval of the
!   form (TT,TT+1.) Maps onto the entire curve.
!
!   n contains the number of points which were specified
!   to determine the curve.
!
!   x and y are arrays containing the x- and y-coordinates
!   of the specified points.
!
!   xp and yp are the arrays output from kurvp1 containing
!   curvature information.
!
!   s is an array containing the polygonal arclengths of
!   the curve.
!
! And
!
!   sigma contains the tension factor (its sign is ignored).
!
! The parameters n, x, y, xp, yp, s and sigma should
! be input unaltered from the output of kurvp1.
!
! On output--
!
!   xs and ys contain the x- and y-coordinates of the image
!   point on the curve.
!
! None of the input parameters are altered.
!
! This subroutine references package modules intrvl and
! snhcsh.
!
!-----------------------------------------------------------
!
! Determine interval
!
tn = t-float(ifix(t))
if (tn .lt. 0.) tn = tn+1.
tn = s(n)*tn+s(1)
im1 = n
if (tn .lt. s(n)) im1 = intrvl(tn,s,n)
i = im1+1
if (i .gt. n) i = 1
!
! Denormalize tension factor
!
sigmap = abs(sigma)*float(n)/s(n)
!
! Set up and perform interpolation
!
si = s(i)
if (im1 .eq. n) si = s(n)+s(1)
del1 = tn-s(im1)
del2 = si-tn
dels = si-s(im1)
sumx = (x(i)*del1+x(im1)*del2)/dels
sumy = (y(i)*del1+y(im1)*del2)/dels
if (sigmap .ne. 0.) go to 1
d = del1*del2/(6.*dels)
c1 = (del1+dels)*d
c2 = (del2+dels)*d
xs = sumx-xp(i)*c1-xp(im1)*c2
ys = sumy-yp(i)*c1-yp(im1)*c2
return
1 delp1 = sigmap*(del1+dels)/2.
delp2 = sigmap*(del2+dels)/2.
call snhcsh(sinhm1,dummy,sigmap*del1,-1)
call snhcsh(sinhm2,dummy,sigmap*del2,-1)
call snhcsh(sinhms,dummy,sigmap*dels,-1)
call snhcsh (sinhp1,dummy,sigmap*del1/2.,-1)
call snhcsh (sinhp2,dummy,sigmap*del2/2.,-1)
call snhcsh (dummy,coshp1,delp1,1)
call snhcsh (dummy,coshp2,delp2,1)
d = sigmap*sigmap*dels*(sinhms+sigmap*dels)
ci = (sinhm1*del2-del1*(2.*(coshp1+1.)*sinhp2+sigmap* &
&coshp1*del2))/d
cim1 = (sinhm2*del1-del2*(2.*(coshp2+1.)*sinhp1+ &
&sigmap*coshp2*del1))/d
xs = sumx+ci*xp(i)+cim1*xp(im1)
ys = sumy+ci*yp(i)+cim1*yp(im1)
return
end subroutine kurvp2

subroutine qurv1 (n,x,y,z,slp1x,slp1y,slp1z,slpnx, &
&slpny,slpnz,islpsw,xp,yp,zp,temp, &
&s,sigma,ierr)
implicit none
integer :: i, ibak, im1, nm1, np1
real :: c1, c2, c3, dels1, dels2, delsn, delsnm, delt, diag, &
&diag1, diag2, diagin, dx1, dx2, dy1, dy2, dz1, dz2, sdiag1, &
&sdiag2, sigmap, slpp1x, slpp1y, slpp1z, slppnx, slppny, slppnz, t
!
integer, intent(in) :: n, islpsw
integer, intent(out) :: ierr
real, intent(in) :: x(n), y(n), z(n), slp1x, slp1y, slp1z, slpnx, &
&slpny, slpnz
real, intent(inout) :: xp(n), yp(n), zp(n), temp(n), s(n)
real, intent(in) :: sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This subroutine determines the parameters necessary to
! compute a spline under tension passing through a sequence
! of triples (x(1),y(1),z(1)),...,(x(n),y(n),z(n)). The
! slopes at the two ends of the curve may be specified or
! omitted. For actual computation of points on the curve
! it is necessary to call the subroutine qurv2.
!
! On input--
!
!   n IS THE NUMBER OF POINTS TO BE INTERPOLATED (n.GE.2).
!
!   x is an array containing the n x-coordinates of the
!   points.
!
!   y is an array containing the n y-coordinates of the
!   points.
!
!   z is an array containing the n z-coordinates of the
!   points. (Adjacent x-y-z triples must be distinct, I. E.
!   EITHER x(i) .NE. x(i+1) OR y(i) .NE. y(i+1) OR z(i) .NE.
!   z(i+1), FOR i = 1,...,n-1 ).
!
!   slp1x, slp1y, slp1z and slpnx, SLPNY, SLPNZ contain the
!   desired values of the components of tangent vectors to
!   the curve at (x(1),y(1),z(1)) AND(x(n),y(n),z(n)),
!   respectively. The positive sense of the curve is assumed
!   to be that moving from point 1 to point n. the user may
!   omit values for either or both of these triples and
!   signal this with islpsw.
!
!   islpsw contains a switch indicating which slope data
!   should be used and which should be estimated by this
!   subroutine,
!          = 0 IF slp1x, slp1y, slp1z AND slpnx, SLPNY,
!              SLPNZ are to be used,
!          = 1 IF slp1x, slp1y, slp1z ARE TO BE USED BUT
!              NOT slpnx, SLPNY, SLPNZ,
!          = 2 IF slpnx, SLPNY, SLPNZ ARE TO BE USED BUT
!              NOT slp1x, slp1y, slp1z,
!          = 3 IF BOTH END-TANGENTS ARE TO BE ESTIMATED
!              internally.
!
!   xp, yp, and zp are arrays of length at least n.
!
!   Temp is an array of length at least n which is used
!   for scratch storage.
!
!   s is an array of length at least n.
!
! And
!
!   sigma contains the tension factor. This value indicates
!   the curviness desired. If abs(sigma) is nearly zero
!   (E.G. .001) The resulting curve is approximately a cubic
!   spline. If abs(sigma) is large (E. G. 50.) The resulting
!   curve is nearly a polygonal line. If sigma equals zero A
!   cubic spline results. A standard value for sigma is
!   approximately 1. In absolute value.
!
! On output--
!
!   xp, yp, and zp contain information about the curvature
!   of the curve at the given nodes.
!
!   s contains the polygonal arclengths of the curve.
!
!   ierr contains an error flag,
!        = 0 FOR NORMAL RETURN,
!        = 1 IF n IS LESS THAN 2,
!        = 2 IF ADJACENT TRIPLES COINCIDE.
!
! And
!
!   n, x, y, z, slp1x, slp1y, slp1z, slpnx, SLPNY, SLPNZ,
!   islpsw, and sigma are unaltered,
!
! This subroutine references package modules ceez, terms,
! and snhcsh.
!
!-----------------------------------------------------------
!
nm1 = n-1
np1 = n+1
ierr = 0
if (n .le. 1) go to 9
!
! Determine polygonal arclengths
!
s(1) = 0.
do 1 i = 2,n
  im1 = i-1
1 s(i) = s(im1)+sqrt((x(i)-x(im1))**2+(y(i)-y(im1))**2 &
&+(z(i)-z(im1))**2)
!
! Denormalize tension factor
!
sigmap = abs(sigma)*float(n-1)/s(n)
!
! Approximate end slopes
!
if (islpsw .ge. 2) go to 2
slpp1x = slp1x
slpp1y = slp1y
slpp1z = slp1z
go to 3
2 dels1 = s(2)-s(1)
dels2 = dels1+dels1
if (n .gt. 2) dels2 = s(3)-s(1)
if (dels1 .eq. 0. .or. dels2 .eq. 0.) go to 9
call ceez (dels1,dels2,sigmap,c1,c2,c3,n)
slpp1x = c1*x(1)+c2*x(2)
slpp1y = c1*y(1)+c2*y(2)
slpp1z = c1*z(1)+c2*z(2)
if (n .eq. 2) go to 3
slpp1x = slpp1x+c3*x(3)
slpp1y = slpp1y+c3*y(3)
slpp1z = slpp1z+c3*z(3)
3 delt = sqrt(slpp1x*slpp1x+slpp1y*slpp1y+slpp1z*slpp1z)
slpp1x = slpp1x/delt
slpp1y = slpp1y/delt
slpp1z = slpp1z/delt
if (islpsw .eq. 1 .or. islpsw .eq. 3) go to 4
slppnx = slpnx
slppny = slpny
slppnz = slpnz
go to 5
4 delsn = s(n)-s(nm1)
delsnm = delsn+delsn
if (n .gt. 2) delsnm = s(n)-s(n-2)
if (delsn .eq. 0. .or. delsnm .eq. 0.) go to 10
call ceez (-delsn,-delsnm,sigmap,c1,c2,c3,n)
slppnx = c1*x(n)+c2*x(nm1)
slppny = c1*y(n)+c2*y(nm1)
slppnz = c1*z(n)+c2*z(nm1)
if (n .eq. 2) go to 5
slppnx = slppnx+c3*x(n-2)
slppny = slppny+c3*y(n-2)
slppnz = slppnz+c3*z(n-2)
5 delt = sqrt(slppnx*slppnx+slppny*slppny+slppnz*slppnz)
slppnx = slppnx/delt
slppny = slppny/delt
slppnz = slppnz/delt
!
! Set up right hand sides and tridiagonal system for xp, yp
! and zp and perform forward elimination
!
dx1 = (x(2)-x(1))/s(2)
dy1 = (y(2)-y(1))/s(2)
dz1 = (z(2)-z(1))/s(2)
call terms (diag1,sdiag1,sigmap,s(2))
xp(1) = (dx1-slpp1x)/diag1
yp(1) = (dy1-slpp1y)/diag1
zp(1) = (dz1-slpp1z)/diag1
temp(1) = sdiag1/diag1
if (n .eq. 2) go to 7
do 6 i = 2,nm1
  dels2 = s(i+1)-s(i)
  if (dels2 .eq. 0.) go to 10
  dx2 = (x(i+1)-x(i))/dels2
  dy2 = (y(i+1)-y(i))/dels2
  dz2 = (z(i+1)-z(i))/dels2
  call terms (diag2,sdiag2,sigmap,dels2)
  diag = diag1+diag2-sdiag1*temp(i-1)
  diagin = 1./diag
  xp(i) = (dx2-dx1-sdiag1*xp(i-1))*diagin
  yp(i) = (dy2-dy1-sdiag1*yp(i-1))*diagin
  zp(i) = (dz2-dz1-sdiag1*zp(i-1))*diagin
  temp(i) = sdiag2*diagin
  dx1 = dx2
  dy1 = dy2
  dz1 = dz2
  diag1 = diag2
6 sdiag1 = sdiag2
7 diag = diag1-sdiag1*temp(nm1)
xp(n) = (slppnx-dx1-sdiag1*xp(nm1))/diag
yp(n) = (slppny-dy1-sdiag1*yp(nm1))/diag
zp(n) = (slppnz-dz1-sdiag1*zp(nm1))/diag
!
! Perform back substitution
!
do 8 i = 2,n
  ibak = np1-i
  t = temp(ibak)
  xp(ibak) = xp(ibak)-t*xp(ibak+1)
  yp(ibak) = yp(ibak)-t*yp(ibak+1)
8 zp(ibak) = zp(ibak)-t*zp(ibak+1)
return
!
! Too few points
!
9 ierr = 1
return
!
! Coincident adjacent points
!
10 ierr = 2
return
end subroutine qurv1

subroutine qurv2 (t,xs,ys,zs,n,x,y,z,xp,yp,zp,s,sigma)
implicit none
integer :: i, im1
real :: c1, c2, coshp1, coshp2, d, del1, del2, delp1, delp2, dels, &
&dummy, sigmap, sinhm1, sinhm2, sinhms, sinhp1, sinhp2, sumx, sumy, &
&sumz, tn
integer :: intrvl
!
integer, intent(in) :: n
real, intent(in) :: t
real, intent(inout) :: xs, ys, zs
real, intent(in) :: x(n), y(n), z(n), xp(n), yp(n), zp(n), s(n)
real, intent(in) :: sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This subroutine performs the mapping of points in the
! interval (0.,1.) Onto a curve in space.  The subroutine
! qurv1 should be called earlier to determine certain
! necessary parameters. The resulting curve has a parametric
! representation all of whose components are splines under
! tension and functions of the polygonal arclength
! parameter.
!
! On input--
!
!   t contains a real value to be mapped to a point on the
!   curve. The interval (0.,1.) Is mapped onto the entire
!   curve, with 0. Mapping to (x(1),y(1,z(1)) and 1. Mapping
!   to (x(n),y(n),z(n)). Values outside this interval result
!   in extrapolation.
!
!   n contains the number of points which were specified
!   to determine the curve.
!
!   x, y, and z are arrays containing the x-, y- and z-
!   coordinates of the specified points.
!
!   xp, yp, and zp are the arrays output from qurv1
!   containing curvature information.
!
!   s is an array containing the polygonal arclengths of
!   the curve.
!
! And
!
!   sigma contains the tension factor (its sign is ignored).
!
! The parameters n, x, y, z, xp, yp, zp, s, and sigma
! should be input unaltered from the output of qurv1.
!
! On output--
!
!   xs, ys and zs contain the x-, y- and z-coordinates of
!   the image point on the curve.
!
! None of the input parameters are altered.
!
! This subroutine references package modules intrvl and
! snhcsh.
!
!-----------------------------------------------------------
!
! Determine interval
!
tn = s(n)*t
im1 = intrvl(tn,s,n)
i = im1+1
!
! Denormalize tension factor
!
sigmap = abs(sigma)*float(n-1)/s(n)
!
! Set up and perform interpolation
!
del1 = tn-s(im1)
del2 = s(i)-tn
dels = s(i)-s(im1)
sumx = (x(i)*del1+x(im1)*del2)/dels
sumy = (y(i)*del1+y(im1)*del2)/dels
sumz = (z(i)*del1+z(im1)*del2)/dels
if (sigmap .ne. 0.) go to 1
d = del1*del2/(6.*dels)
c1 = (del1+dels)*d
c2 = (del2+dels)*d
xs = sumx-xp(i)*c1-xp(im1)*c2
ys = sumy-yp(i)*c1-yp(im1)*c2
zs = sumz-zp(i)*c1-zp(im1)*c2
return
1 delp1 = sigmap*(del1+dels)/2.
delp2 = sigmap*(del2+dels)/2.
call snhcsh(sinhm1,dummy,sigmap*del1,-1)
call snhcsh(sinhm2,dummy,sigmap*del2,-1)
call snhcsh(sinhms,dummy,sigmap*dels,-1)
call snhcsh (sinhp1,dummy,sigmap*del1/2.,-1)
call snhcsh (sinhp2,dummy,sigmap*del2/2.,-1)
call snhcsh (dummy,coshp1,delp1,1)
call snhcsh (dummy,coshp2,delp2,1)
d = sigmap*sigmap*dels*(sinhms+sigmap*dels)
c1 = (sinhm1*del2-del1*(2.*(coshp1+1.)*sinhp2+sigmap* &
&coshp1*del2))/d
c2 = (sinhm2*del1-del2*(2.*(coshp2+1.)*sinhp1+sigmap* &
&coshp2*del1))/d
xs = sumx+xp(i)*c1+xp(im1)*c2
ys = sumy+yp(i)*c1+yp(im1)*c2
zs = sumz+zp(i)*c1+zp(im1)*c2
return
end subroutine qurv2

subroutine ceez (del1,del2,sigma,c1,c2,c3,n)
implicit none
integer, intent(in) :: n
real :: coshm1, coshm2, del, delm, delp, denom, dummy, sinhmm, &
&sinhmp
!
real, intent(in) :: del1, del2, sigma
real, intent(inout) :: c1, c2, c3
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This subroutine determines the coefficients c1, c2, and c3
! used to determine endpoint slopes. Specifically, if
! function values Y1, Y2, and Y3 are given at points X1, X2,
! and X3, respectively, the quantity c1*Y1 + c2*Y2 + c3*Y3
! is the value of the derivative at X1 of a spline under
! tension (with tension factor sigma) passing through the
! three points and having third derivative equal to zero at
! X1. Optionally, only two values, c1 and c2 are determined.
!
! On input--
!
!   del1 IS X2-X1 (.GT. 0.).
!
!   del2 IS X3-X1 (.GT. 0.). IF n .EQ. 2, THIS PARAMETER IS
!   ignored.
!
!   sigma is the tension factor.
!
! And
!
!   n is a switch indicating the number of coefficients to
!   BE RETURNED. IF n .EQ. 2 ONLY TWO COEFFICIENTS ARE
!   returned. Otherwise all three are returned.
!
! On output--
!
!   c1, c2, and c3 contain the coefficients.
!
! None of the input parameters are altered.
!
! This subroutine references package module snhcsh.
!
!-----------------------------------------------------------
!
if (n .eq. 2) go to 2
if (sigma .ne. 0.) go to 1
del = del2-del1
!
! TENSION .EQ. 0.
!
c1 = -(del1+del2)/(del1*del2)
c2 = del2/(del1*del)
c3 = -del1/(del2*del)
return
!
! TENSION .NE. 0.
!
1 call snhcsh (dummy,coshm1,sigma*del1,1)
call snhcsh (dummy,coshm2,sigma*del2,1)
delp = sigma*(del2+del1)/2.
delm = sigma*(del2-del1)/2.
call snhcsh (sinhmp,dummy,delp,-1)
call snhcsh (sinhmm,dummy,delm,-1)
denom = coshm1*(del2-del1)-2.*del1*(sinhmp+delp)* &
&(sinhmm+delm)
c1 = 2.*(sinhmp+delp)*(sinhmm+delm)/denom
c2 = -coshm2/denom
c3 = coshm1/denom
return
!
! Two coefficients
!
2 c1 = -1./del1
c2 = -c1
return
end subroutine ceez

subroutine terms (diag,sdiag,sigma,del)
implicit none
real :: coshm, denom, sigdel, sinhm
!
real, intent(inout) :: diag, sdiag
real, intent(in) :: sigma, del
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This subroutine computes the diagonal and superdiagonal
! terms of the tridiagonal linear system associated with
! spline under tension interpolation.
!
! On input--
!
!   sigma contains the tension factor.
!
! And
!
!   Del contains the step size.
!
! On output--
!
!               (sigma*del*COSH(sigma*del) - SINH(sigma*del)
!   diag = del*--------------------------------------------.
!                     (sigma*del)**2 * SINH(sigma*del)
!
!                   SINH(sigma*del) - sigma*del
!   sdiag = del*----------------------------------.
!                (sigma*del)**2 * SINH(sigma*del)
!
! And
!
!   sigma and del are unaltered.
!
! This subroutine references package module snhcsh.
!
!-----------------------------------------------------------
!
if (sigma .ne. 0.) go to 1
diag = del/3.
sdiag = del/6.
return
1 sigdel = sigma*del
call snhcsh (sinhm,coshm,sigdel,0)
denom = del/((sinhm+sigdel)*sigdel*sigdel)
diag = denom*(sigdel*coshm-sinhm)
sdiag = denom*sinhm
return
end subroutine terms

integer function intrvl (x, t, m)
implicit none
integer, intent(in) :: m
integer :: i, il, ir
real :: tm
real, intent(in) :: x, t(m)
!-----------------------------------------------------------------------
!
!             Location of a value x in a sequence t
!
!                       ----------------
!
!     Input--
!
!        x is a real number.
!
!        t is an array of nondecreasing values. It is
!          ASSUMED THAT t(1) .LT. t(m).
!
!        m IS THE LENGTH OF t (m .GE. 2).
!
!     Output--
!
!        intrvl HAS THE VALUE i WHEN  t(i) .LE. x .LT. t(i+1).
!        OTHERWISE, IF L IS THE INTEGER WHERE t(L) .LT. t(L+1)
!        AND t(L+1) = ... = t(m), THEN intrvl HAS THE VALUE i
!        where
!                  i = 1   IF x .LT. t(1)
!                  i = L   IF x .GE. t(L)
!
!-----------------------------------------------------------------------
if (x .lt. t(2)) go to 100
tm = t(m)
i = m - 1
10 if (t(i) .lt. tm) go to 20
   i = i - 1
   go to 10
20 if (x .ge. t(i)) go to 110
il = 2
ir = i
!
!     Bisection search
!
30 i = (il + ir)/2
if (i .eq. il) go to 110
if (x - t(i)) 40,60,50
40 ir = i
go to 30
50 il = i
go to 30
!
!     CASE WHEN x = t(i) FOR SOME i
!
60 if (x .lt. t(i+1)) go to 110
i = i + 1
go to 60
!
!     Left end
!
100 intrvl = 1
return
!
!     Normal exit
!
110 intrvl = i
return
end function intrvl

subroutine bval (t, bcoef, n, k, x, jderiv, w, wk)
implicit none
integer, intent(in) :: jderiv, k, n
real, intent(inout) :: w
real, intent(in) :: x
integer :: i, imk, ipj, j, jc, jcmax, jcmin, jdrvp1, jj, km1, kmj, &
&l, nmi, npk
real :: dl, dr, fkmj
integer :: intrvl
!-----------------------------------------------------------------------
!
!     bval calculates the value at x of the jderiv-TH derivative
!     of a spline F from its B-representation.
!
!******  i n P U t ******
!
!  t     AN ARRAY OF DIMENSION n + k CONTAING THE KNOTS OF THE
!        SPLINE. IT IS ASSUMED THAT t(i) .LE. t(i+1) FOR EACH i.
!  bcoef an array of dimension n containing the B-coefficients
!        of the spline F.
!  n     LENGTH OF bcoef (n .GE. 1).
!  k     ORDER OF THE SPLINE.
!  x     THE POINT AT WHICH TO EVALUATE.
!  jderiv  integer giving the order of the derivative to be
!        EVALUATED. IT IS ASSUMED THAT jderiv .GE. 0.
!
!******  O U t P U t  ******
!
!  w     THE VALUE OF THE (jderiv)-TH DERIVATIVE OF F AT x.
!
!******  w O R k  S P A C E ******
!
!  wk    AN ARRAY OF DIMENSION 3*k OR LARGER.
!
!******  M E t H O D  ******
!
!     The nontrivial knot interval (t(i),t(i+1)) containing x is first
!  obtained. Then the  k  B-coefficients of F relevant for this interval
!  are obtained from bcoef (or taken to be zero if not explicitly avail-
!  able), and DIFFERENCED jderiv times to obtain the B-coefficients of
!  (D**jderiv)F  RELEVANT FOR THE INTERVAL. SPECIFICALLY, IF j = jderiv
!  then from x.(12) Of the reference we have
!
!     (D**j)F  =  sum ( bcoef(.,j)*B(.,k-j,t) )
!
!  Where
!                   / bcoef(.),                     ,  j .EQ. 0
!                   /
!    bcoef(.,j)  =  / bcoef(.,j-1) - bcoef(.-1,j-1)
!                   / ----------------------------- ,  j .GT. 0
!                   /    (t(.+k-j) - t(.))/(k-j)
!
!     Then, we use repeatedly the fact that
!
!    sum ( A(.)*B(.,M,t)(x) )  =  sum ( A(.,x)*B(.,M-1,t)(x) )
!  with
!                 (x - t(.))*A(.) + (t(.+M-1) - x)*A(.-1)
!    a(.,x)  =    ---------------------------------------
!                 (x - t(.))      + (t(.+M-1) - x)
!
!  TO WRITE (D**j)F(x) EVENTUALLY AS A LINEAR COMBINATION OF B-SPLINES
!  of order 1. The coefficient for B(i,1,t)(x) must then be the desired
!  NUMBER  (D**j)F(x). (SEE x.(17)-(19) OF THE REFERENCE).
!
!-----------------------------------------------------------------------
!  Reference. DE boor, carl, A PRATICAL guide to splines, springer-
!  verlag, new york, 1978.
!-----------------------------------------------------------------------
real, intent(in) :: t(*), bcoef(n)
real, intent(inout) :: wk(k,3)
!
w = 0.0
if (jderiv .ge. k) return
!
! *** FIND i WHERE 1 .LE. i .LT. n+k  AND  t(i) .LE. x .LT. t(i+1).
!     If no such i exists, then x lies outside the support of the
!     SPLINE F AND w = 0.
!
npk = n + k
if (x .lt. t(1) .or. x .gt. t(npk)) return
i = intrvl(x, t, npk)
!
!  *** IF k = 1 (AND jderiv = 0), w = bcoef(i).
!
km1 = k - 1
if (km1 .gt. 0) go to 10
   w = bcoef(i)
   return
!
!  *** STORE THE k B-SPLINE COEFFICIENTS RELEVANT FOR THE KNOT INTERVAL
!     (t(i),t(i+1)) IN THE FIRST COLUMN OF wk AND COMPUTE wk(j,2) =
!     x - t(i+1-j), wk(j,3) = t(i+j) - x, j=1,...,k-1 . SET ANY OF THE
!     wk(j,1) not obtainable from input to zero. Set any t.S not obtain-
!     able equal to t(1) or to t(n+k) appropriately.
!
10 jcmin = 1
imk = i - k
if (imk .ge. 0) go to 40
!
   jcmin = 1 - imk
   l = i
   do j = 1,i
      wk(j,2) = x - t(l)
      l = l - 1
   end do
   do j = i,km1
      l = k - j
      wk(l,1) = 0.0
      wk(j,2) = wk(i,2)
   end do
   go to 60
!
40 l = i
do j = 1,km1
   wk(j,2) = x - t(l)
   l = l - 1
end do
!
60 jcmax = k
nmi = n - i
if (nmi .ge. 0) go to 100
!
   jcmax = k + nmi
   do j = 1,jcmax
      ipj = i + j
      wk(j,3) = t(ipj) - x
   end do
   do j = jcmax,km1
      wk(j+1,1) = 0.0
      wk(j,3) = wk(jcmax,3)
   end do
   go to 120
!
100 do j = 1,km1
   ipj = i + j
   wk(j,3) = t(ipj) - x
end do
!
120 do jc = jcmin,jcmax
   l = imk + jc
   wk(jc,1) = bcoef(l)
end do
!
!               *** DIFFERENCE THE COEFFICIENTS  jderiv  TIMES.
!
if (jderiv .eq. 0) go to 170
do j = 1,jderiv
   kmj = k - j
   fkmj = kmj
   l = kmj
   do 150 jj = 1,kmj
      dl = wk(l,2)
      dr = wk(jj,3)
      wk(jj,1) = ((wk(jj+1,1) - wk(jj,1))/(dl + dr))*fkmj
150 l = l - 1
end do
!
!  *** COMPUTE VALUE AT x IN (t(i),t(i+1)) OF jderiv-TH DERIVATIVE,
!     given its relevant B-spline coeffs in wk(1,1),...,wk(k-jderiv,1).
!
170 if (jderiv .eq. km1) go to 200
jdrvp1 = jderiv + 1
do j = jdrvp1,km1
   kmj = k - j
   l = kmj
   do 180 jj = 1,kmj
      dl = wk(l,2)
      dr = wk(jj,3)
      wk(jj,1) = (wk(jj+1,1)*dl + wk(jj,1)*dr)/(dl + dr)
180 l = l - 1
end do
!
200 w = wk(1,1)
return
end subroutine bval

subroutine bvali (t, bcoeff, n, k, x, w, wk)
implicit none
integer, intent(in) :: k, n
real, intent(out) :: w
real, intent(in) :: x
integer :: i, ipk, kp1, np1, npk
real :: sum, tlast, tnew, xval
!-----------------------------------------------------------------------
!           Integral of a piecewise polynomial from t(1) to x
!                   using its B-spline representation
!-----------------------------------------------------------------------
!     real t(n + k), wk(n + 3*(k + 1))
!---------------------------
real, intent(in) :: t(*), bcoeff(n)
real, intent(inout) :: wk(*)
!
w = 0.0
if (x .le. t(1)) return
npk = n + k
tlast = t(npk)
xval = amin1(x, tlast)
!
!     Define the first new knot. The remaining new knots
!         are assumed to be the same as this knot.
!
tnew = 0.1
if (tlast .lt. -0.1) tnew = 0.9*tlast
if (tlast .gt.  0.0) tnew = 1.1*tlast
!
!     Compute the first n coefficients of the antiderivative
!
sum = 0.0
do i = 1,n
   ipk = i + k
   sum = sum + bcoeff(i)*(t(ipk) - t(i))
   wk(i) = sum/k
end do
!
!     Compute the antiderivative
!
kp1 = k + 1
np1 = n + 1
call bvali0 (t, tnew, wk(1), n, kp1, xval, w, wk(np1))
return
end subroutine bvali

subroutine bvali0 (t, tnew, bcoef, n, k, x, w, wk)
implicit none
integer, intent(in) :: k, n
real, intent(in) :: tnew
real, intent(out) :: w
real, intent(in) :: x
integer :: i, imk, ipj, j, jc, jcmin, jj, km1, kmj, l, m
real :: dl, dr, tipj
integer :: intrvl
!-----------------------------------------------------------------------
!
!     bvali0 calculates the value at x of an antiderivative
!     OF A B-SPLINE F FOR t(1) .LE. x .LE. t(n + k - 1).
!
!******  i n P U t ******
!
!  t     AN ARRAY CONTAINING THE FIRST n + k - 1 KNOTS OF THE
!        antiderivative.
!  tnew  the remaing knots are all located at this point.
!  bcoef an array containing the first n coefficients of the
!        antiderivative.
!  n     LENGTH OF bcoef (n .GE. 1).
!  k     ORDER OF THE ANTIDERIVATIVE.
!  x     THE POINT AT WHICH TO EVALUATE.
!
!******  O U t P U t  ******
!
!  w     THE VALUE OF THE ANTIDERIVATIVE AT x.
!
!******  w O R k  S P A C E ******
!
!  wk    AN ARRAY OF DIMENSION 3*k OR LARGER.
!
!-----------------------------------------------------------------------
!     Remark. bvali0 is an adaptation by A.H. Morris (NSWC) of the
!     SUBROUTINE bval.
!-----------------------------------------------------------------------
real, intent(in) :: t(*), bcoef(n)
real, intent(inout) :: wk(k,3)
!
w = 0.0
km1 = k - 1
m = n + km1
i = intrvl(x, t, m)
!
!  *** STORE THE k B-SPLINE COEFFICIENTS RELEVANT FOR THE KNOT INTERVAL
!     (t(i),t(i+1)) IN THE FIRST COLUMN OF wk AND COMPUTE wk(j,2) =
!     x - t(i+1-j), wk(j,3) = t(i+j) - x, j=1,...,k-1 . SET ANY OF THE
!     wk(j,1) not obtainable from input to zero. Set any t.S not obtain-
!     able equal to t(1) or tnew appropriately.
!
jcmin = 1
imk = i - k
if (imk .ge. 0) go to 30
!
   jcmin = 1 - imk
   l = i
   do j = 1,i
      wk(j,2) = x - t(l)
      l = l - 1
   end do
   do j = i,km1
      l = k - j
      wk(l,1) = 0.0
      wk(j,2) = wk(i,2)
   end do
   go to 50
!
30 l = i
do j = 1,km1
   wk(j,2) = x - t(l)
   l = l - 1
end do
!
50 do j = 1,km1
   tipj = tnew
   ipj = i + j
   if (ipj .le. m) tipj = t(ipj)
   wk(j,3) = tipj - x
end do
!
do jc = jcmin,k
   l = min0(imk + jc, n)
   wk(jc,1) = bcoef(l)
end do
!
!  *** COMPUTE VALUE AT x IN (t(i),t(i+1)), GIVEN ITS RELEVANT
!     B-spline coeffs in wk(1,1),...,wk(k,1).
!
do j = 1,km1
   kmj = k - j
   l = kmj
   do 100 jj = 1,kmj
      dl = wk(l,2)
      dr = wk(jj,3)
      wk(jj,1) = (wk(jj+1,1)*dl + wk(jj,1)*dr)/(dl + dr)
100 l = l - 1
end do
!
w = wk(1,1)
return
end subroutine bvali0

subroutine bspp (t, a, n, k, break, c, l, wk)
implicit none
integer, intent(in) :: k
integer, intent(out) :: l
integer, intent(in) :: n
integer :: i, il, ilj, ilkj, j, jj, jp1, km1, kmj, kp1, left
real :: diff, r, s, term, x
!-----------------------------------------------------------------------
!
!              Conversion from B-spline representation
!              to piecewise polynomial representation
!
!
!     Input ...
!
!       t     KNOT SEQUENCE OF LENGTH n+k
!       A     B-SPLINE COEFFICIENT SEQUENCE OF LENGTH n
!       n     LENGTH OF A
!       k     ORDER OF THE B-SPLINES
!
!     Output ...
!
!       Break breakpoint sequence, of length l+1, containing
!             (in increasing order) the distinct points of the
!             SEQUENCE t(k),...,t(n+1).
!       c     KXL MATRIX WHERE c(i,j) = (i-1)ST RIGHT DERIVATIVE
!             of the PP at break(j) divided by FACTORIAL(i-1).
!       l     NUMBER OF POLYNOMIALS WHICH FORM THE PP
!
!     Work area ...
!
!       wk    2-DIMENSIONAL ARRAY OF DIMENSION (k,k+1)
!
!-----------------------------------------------------------------------
real, intent(in) :: t(*), a(n)
real, intent(inout) :: break(*), c(k,*), wk(k,*)
!
l = 0
break(1) = t(k)
if (k .eq. 1) go to 100
km1 = k - 1
kp1 = k + 1
!
!          General k-TH order case
!
do 60 left = k,n
   if (t(left) .eq. t(left + 1)) go to 60
   l = l + 1
   break(l + 1) = t(left + 1)
   do j = 1,k
      jj = left - k + j
      wk(j,1) = a(jj)
   end do
!
   do j = 1,km1
      jp1 = j + 1
      kmj = k - j
      do i = 1,kmj
         il = i + left
         ilkj = il - kmj
         diff = t(il) - t(ilkj)
         wk(i,jp1) = (wk(i+1,j) - wk(i,j))/diff
      end do
   end do
!
   wk(1,kp1) = 1.0
   x = t(left)
   c(k,l) = wk(1,k)
   r = 1.0
   do j = 1,km1
      jp1 = j + 1
      s = 0.0
      do i = 1,j
         il = i + left
         ilj = il - j
         term = wk(i,kp1)/(t(il) - t(ilj))
         wk(i,kp1) = s + (t(il) - x)*term
         s = (x - t(ilj))*term
      end do
      wk(jp1,kp1) = s
!
      s = 0.0
      kmj = k - j
      do i = 1,jp1
         s = s + wk(i,kmj)*wk(i,kp1)
      end do
      r = (r*float(kmj))/float(j)
      c(kmj,l) = r*s
   end do
60 continue
return
!
!          Piecewise constant case
!
100 do 110 left = k,n
   if (t(left) .eq. t(left + 1)) go to 110
   l = l + 1
   break(l + 1) = t(left + 1)
   c(1,l) = a(left)
110 continue
return
end subroutine bspp

subroutine ppval (x, a, l, n, xi, yi, ni)
implicit none
integer, intent(in) :: l, n, ni
real :: a(l,n), x(n), xi(ni)
real, intent(inout) :: yi(ni)
integer :: i, il, ir, j, k, lm1, lmj
real :: dx, s, xx
!-----------------------------------------------------------------------
!
!         This routine evaluates a piecewise polynomial at the
!         abscissas in xi. It is assumed that the coefficients
!         of the polynomials which form the PP are given.
!
!       --Input--
!
!         x   - ARRAY OF THE FIRST n ABSCISSAS (IN INCREASING ORDER)
!               that define the PP.
!         a   - MATRIX THAT CONTAINS THE COEFFICIENTS OF THE POLY-
!               NOMIALS  WHICH FORM THE PP. IF i = 1,...,n THEN THE
!               PP has the value
!                    a(1,i) + a(2,i)*dx + ... + a(l,i)*dx**(l-1)
!               FOR x(i) .LE. xx .LT. x(i+1).  HERE dx = xx - x(i).
!         l   - ORDER OF THE PIECEWISE POLYNOMIAL.
!         n   - THE NUMBER OF POLYNOMIALS THAT DEFINE THE PP.
!               n must be greater than or equal to 1.
!         xi  - the array of abscissas (in arbitrary order) at which
!               at which the PP is to be evaluated.
!         ni  - the dimension of the arrays xi and yi. It is assumed
!               that ni is greater than or equal to 1.
!
!       --Output--
!
!         yi  - array of values of the PP at the points in xi.
!
!-----------------------------------------------------------------------
!
!     k is index on value of xi being worked on.  xx is that value.
!     i is the current index in the x array.
!
k  = 1
xx = xi(1)
lm1 = l - 1
if (xx .lt. x(1)) go to 90
if (xx .ge. x(n)) go to 80
il = 1
ir = n
!
!     Bisection search
!
10 i = (il + ir)/2
if (i .eq. il) go to 100
if (xx - x(i)) 20,100,30
20 ir = i
go to 10
30 il = i
go to 10
!
!     Linear forward search
!
40 if (xx .lt. x(i+1)) go to 100
i = i + 1
go to 40
!
!     xx is greater than x(n) or less than x(1)
!
80 i = n
go to 100
90 i = 1
!
!     Evaluation
!
100 dx = xx - x(i)
s = a(l,i)
if (l .eq. 1) go to 120
do j = 1,lm1
   lmj = l - j
   s = a(lmj,i) + dx*s
end do
120 yi(k) = s
!
!     Next point
!
if (k .ge. ni) return
k = k + 1
xx = xi(k)
if (xx .lt. x(1)) go to 90
if (xx .ge. x(n)) go to 80
if (xx - xi(k-1)) 130,120,40
130 il = 1
ir = min0(i + 1, n)
go to 10
end subroutine ppval

subroutine bspvb (t, k, jhigh, j, x, left, blist)
implicit none
integer, intent(inout) :: j
integer, intent(in) :: jhigh, k, left
real, intent(in) :: x
integer :: i, imj, l
real :: s, term, ti, timj
!-----------------------------------------------------------------------
!
!     bspvb calculates the value of all possibly nonzero B-splines
!     AT x OF ORDER max(jhigh,j + 1) WHERE t(k) .LE. x .LT. t(N+1).
!
!     Description of arguments
!
!         Input
!
!          t       - KNOT VECTOR OF LENGTH N + k.
!          k       - HIGHEST POSSIBLE ORDER OF THE B-SPLINES.
!          jhigh   - ORDER OF B-SPLINES (1 .le. jhigh .le. k).
!          j       - j .LE. 0  GIVES B-SPLINES OF ORDER jhigh.
!                    j .GE. 1  ON A PREVIOUS CALL TO bspvb THE
!                              B-splines of order j were com-
!                              puted and stored in blist. It is
!                              assumed that work has not been
!                              MODIFIED AND THAT j .LT. k.
!          x       - ARGUMENT OF THE B-SPLINES.
!          left    - LARGEST INTEGER SUCH THAT
!                    t(left) .LE. x .LT. t(left+1)
!
!         Output
!
!          blist   - VECTOR OF LENGTH k FOR SPLINE VALUES.
!          j       - B-SPLINES OF ORDER j HAVE BEEN COMPUTED
!                    and stored in blist.
!
!-----------------------------------------------------------------------
!     Written by carl DE boor (University of Wisconsin) and modified
!         by A.H. Morris (NSWC).
!-----------------------------------------------------------------------
real, intent(in) :: t(*)
real, intent(inout) :: blist(k)
!
if (j .gt. 0) go to 10
   j = 1
   blist(1) = 1.0
   if (j .ge. jhigh) return
!
10 s = 0.0
do l = 1,j
   i = left + l
   imj = i - j
   timj = t(imj)
   ti = t(i)
   term = blist(l)/(ti - timj)
   blist(l) = s + (ti - x)*term
   s = (x - timj)*term
end do
j = j + 1
blist(j) = s
if (j .lt. jhigh) go to 10
!
return
end subroutine bspvb

subroutine bspvd (t, k, x, left, dbiatx, idim, nderiv, a)
implicit none
integer, intent(in) :: idim, k, left, nderiv
real, intent(in) :: x
integer :: i, ideriv, il, j, jj, jlow, jp1mid, kp1, kp1mm, l, &
&ldummy, m, mhigh
real :: factor, fkp1mm, sum
!-----------------------------------------------------------------------
!
! Calculates value and deriv.S of all B-splines which do not vanish at x
!
!******  i N P U t  ******
!
!  t     THE KNOT ARRAY, OF LENGTH left+k (AT LEAST)
!  k     THE ORDER OF THE B-SPLINES TO BE EVALUATED
!  x     THE POINT AT WHICH THESE VALUES ARE SOUGHT
!  left  an integer indicating the left endpoint of the interval of
!        interest. The  k  B-splines whose support contains the interval
!               (t(left), t(left+1))
!        are to be considered.
!  A S S U M P t i O N  - - -  it is assumed that
!               t(left) .LT. t(left+1)
!        division by zero will result otherwise (in  B S P V B ).
!        Also, the output is as advertised only if
!               t(left) .LE. x .LE. t(left+1) .
!  idim  the row dimension of the matrix dbiatx. If is assumed that
!        idim .GE. k .
!  nderiv  an integer indicating that values of B-splines and their
!        derivatives up to but not including the  nderiv-TH  are asked
!        for. (nderiv is replaced internally by the integer  M H i G H
!        in (1,k) closest to it.)
!
!******  O U t P U t  ******
!
!  dbiatx  an array of order (idim,nderiv). Its entry (i,M) contains
!        value of  (M-1)ST  derivative of  (left-k+i)-TH  B-spline of
!        ORDER  k  FOR KNOT SEQUENCE  t , i=M,...,k, M=1,...,nderiv.
!
!******  W O R k   A R E a  ******
!
!  A     AN ARRAY OF ORDER (k,k), TO CONTAIN B-COEFF.S OF THE DERIVA-
!        tives of a certain order of the  k  B-splines of interest.
!
!******  M E t H O D  ******
!
!  Values at  x  of all the relevant B-splines of order k,k-1,...,
!  k+1-nderiv  are generated via bspvb and stored temporarily in
!  dbiatx. Then the B-coeffs of the required derivatives of the B-
!  splines of interest are generated by differencing, each from the pre-
!  ceding one of lower order, and combined with the values of B-splines
!  of corresponding order in  dbiatx  to produce the desired values .
!
!-----------------------------------------------------------------------
!  Written by carl DE boor (University of Wisconsin) and modified
!     by A.H. Morris (NSWC).
!-----------------------------------------------------------------------
real, intent(in) :: t(*)
real, intent(inout) :: dbiatx(idim,nderiv), a(k,k)
!
mhigh = max0(min0(nderiv,k),1)
!     MHIGH is usually equal to nderiv.
kp1 = k + 1
jj = 0
call bspvb (t, k, kp1 - mhigh, jj, x, left, dbiatx)
if (mhigh .eq. 1) return
!
!     The first column of dbiatx always contains the B-spline values
!     for the current order. These are stored in column k+1-current
!     order  before  bspvb  is called to put values for the next
!     higher order on top of it.
!
ideriv = mhigh
do m = 2,mhigh
   jp1mid = 1
   do 10 j = ideriv,k
      dbiatx(j,ideriv) = dbiatx(jp1mid,1)
10 jp1mid = jp1mid + 1
   ideriv = ideriv - 1
   call bspvb (t, k, kp1 - ideriv, jj, x, left, dbiatx)
end do
!
!     At this point, B(left-k+i, k+1-j)(x) is in dbiatx(i,j) for
!     i = j,...,k AND j = 1,...,MHIGH. IN PARTICULAR, THE FIRST
!     column of dbiatx is already in final form. To obtain cor-
!     responding derivatives of B-splines in subsequent columns,
!     generate their B-repr. By differencing. Then evaluate at x.
!
jlow = 1
do 20 i = 1,k
   do 19 j = jlow,k
19 a(j,i) = 0.0
   jlow = i
20 a(i,i) = 1.0
!
!     At this point, a(.,j) contains the B-coeffs for the j-TH of the
!     k  B-splines of interest here.
!
do m = 2,mhigh
   kp1mm = kp1 - m
   fkp1mm = float(kp1mm)
   il = left
   i = k
!
!        FOR j = 1,...,k, CONSTRUCT B-COEFFS OF (M-1)ST  DERIVATIVE OF
!        B-splines from those for preceding derivative by differencing
!        AND STORE AGAIN IN  a(.,j) . THE FACT THAT  a(i,j) = 0  FOR
!        i .LT. j  IS USED.
!
   do ldummy = 1,kp1mm
      l = il + kp1mm
      factor = fkp1mm/(t(l) - t(il))
!
!           THE ASSUMPTION THAT t(left).LT.t(left+1) MAKES DENOMINATOR
!           in the factor nonzero.
!
      do 25 j = 1,i
25 a(i,j) = (a(i,j) - a(i-1,j))*factor
      il = il - 1
      i = i - 1
   end do
!
!        FOR i = 1,...,k, COMBINE B-COEFFS a(.,i) WITH B-SPLINE VALUES
!        stored in dbiatx(.,M) to get value of  (M-1)ST  derivative of
!        i-TH B-spline (of interest here) at x, and store in
!        dbiatx(i,M). Storage of this value over the value of A B-spline
!        of order M there is safe since the remaining B-spline derivat-
!        ives of the same order do not use this value due to the fact
!        THAT  a(j,i) = 0  FOR j .LT. i .
!
   do i = 1,k
      sum = 0.0
      jlow = max0(i,m)
      do 35 j = jlow,k
35 sum = a(j,i)*dbiatx(j,m) + sum
      dbiatx(i,m) = sum
   end do
end do
return
end subroutine bspvd

subroutine bstrp (tau, gtau, t, n, k, bcoef, q, iflag)
implicit none
integer, intent(inout) :: iflag
integer, intent(in) :: k, n
integer :: i, ilp1mx, j, jj, km1, kpkm2, left, lenq, np1
real :: taui
!-----------------------------------------------------------------------
!   This routine produces the B-spline COEFF.S bcoef of the piecewise
!   POLYNOMIAL OF ORDER k WITH KNOTS t(i) (i=1,...,n+k) WHICH HAS THE
!   VALUE gtau(i) AT tau(i) FOR i=1,...,n.
!
!******  i n P U t  ******
!
!  tau.....array of length  n , containing data point abscissae.
!    A S S U M P t i O n . . .  tau  is strictly increasing
!  gtau.....corresponding array of length  n , containing data point
!        ordinates.
!  t.....knot sequence, of length  n+k
!  n.....number of data points and dimension of spline space  S(k,t)
!  k.....order of the piecewise polynomial
!  iflag.....on an initial call to the routine, iflag may be assigned
!        any value except 0. The routine may be recalled when only gtau
!        IS MODIFIED. iflag=0 WHEN THIS IS DONE.
!
!******  O U t P U t  ******
!
!  bcoef.....the B-coefficients of the interpolant, of length  n
!  q.....array of size  (2*k-1)*n , containing the triangular factoriz-
!        ation of the coefficient matrix of the linear system for the B-
!        coefficients of the spline interpolant.
!  iflag.....AN INTEGER INDICATING SUCCESS (= 0)  OR FAILURE (= 1)
!        the linear system to be solved is (theoretically) invertible if
!        and only if
!              B(i)(tau(i)) .NE. 0   FOR ALL i.
!        VIOLATION OF THIS CONDITION IS CERTAIN TO LEAD TO iflag = 1.
!
!******  M E t H O D  ******
!
!     THE i-TH EQUATION OF THE LINEAR SYSTEM  A*bcoef = B  FOR THE B-CO-
!  EFFS OF THE INTERPOLANT ENFORCES INTERPOLATION AT  tau(i), i=1,...,n.
!  HENCE,  B(i) = gtau(i), ALL i, AND  A  IS A BAND MATRIX WITH  2k-1
!  bands (if it is invertible).
!     The matrix  A  is generated row by row and stored, diagonal by DI-
!  agonal, in the  R O W S  of the array  q , with the main diagonal go-
!  ing into row  k .  See comments in the program below.
!     The banded system is then solved by a call to banfac (which con-
!  structs the triangular factorization for  A  and stores it in  q),
!  followed by a call to banslv (which then obtains the solution bcoef
!  by substitution).
!     banfac performs no pivoting since the total positivity of the
!  matrix A makes this unnecessary.
!-----------------------------------------------------------------------
real, intent(inout) :: bcoef(n)
real, intent(in) :: gtau(n)
real, intent(inout) :: q(*)
real, intent(in) :: t(*), tau(n)
!
km1 = k - 1
if (iflag .eq. 0) go to 60
np1 = n + 1
kpkm2 = 2*km1
if (n .eq. 1) go to 20
!
!        Check if tau(i) is an increasing sequence
!
do i = 2,n
   if (tau(i) .le. tau(i-1)) go to 100
end do
!
!                Zero out all entries of q
!
20 if (tau(n) .gt. t(np1)) go to 100
lenq = n*(k + km1)
do i = 1,lenq
   q(i) = 0.0
end do
!
!  ***   LOOP OVER i TO CONSTRUCT THE n INTERPOLATION EQUATIONS
!
left = k
do i = 1,n
   taui = tau(i)
   ilp1mx = min0(i + k,np1)
!
!        *** FIND  LEFT  IN THE CLOSED INTERVAL (i,i+k-1) SUCH THAT
!                t(left) .LE. tau(i) .LT. t(left+1)
!        matrix is singular if this is not possible
!
   left = max0(left,i)
   if (taui .lt. t(left)) go to 100
30 if (taui .lt. t(left+1)) go to 40
      left = left + 1
      if (left .lt. ilp1mx) go to 30
   if (left .eq. i + k) go to 100
   left = n
!
!        *** THE i-TH EQUATION ENFORCES INTERPOLATION AT taui, HENCE
!        A(i,j) = B(j,k,t)(taui), ALL j. ONLY THE  k  ENTRIES WITH  j =
!        left-k+1,...,left actually might be nonzero. These  k  numbers
!        are returned, in  bcoef (used for temp.Storage here), by the
!        following
!
40 jj = 0
   call bspvb (t, k, k, jj, taui, left, bcoef)
!
!        Let q denote a two-dimensional array of dimension (2*k-1,n).
!        WE THEREFORE WANT  bcoef(j) = B(left-k+j)(taui) TO GO INTO
!        A(i,left-k+j), I.E., Into  q(i-(left+j)+2*k,(left+j)-k) since
!        A(i+j,j)  is to go into  q(i+k,j), all i,j.  in the current
!        routine we treat q as an equivalent one-dimensional array.
!        Thus we want bcoef(j) to be inserted into entry
!            i - (left+j) + 2*k + ((left+j) - k-1)*(2*k-1)
!                   =  i-left+1 + (left - k)*(2*k-1) + (2*k-2)*j
!        OF  q .
!
   jj = i - left + 1 + (left - k)*(k + km1)
   do j = 1,k
      jj = jj + kpkm2
      q(jj) = bcoef(j)
   end do
end do
!
!     ***OBTAIN FACTORIZATION OF  A  , STORED AGAIN IN  q.
!
call banfac (q, k + km1, n, km1, km1, iflag)
iflag = iflag - 1
if (iflag .ne. 0) return
!
!     *** SOLVE  A*bcoef = gtau  BY BACKSUBSTITUTION
!
60 do i = 1,n
   bcoef(i) = gtau(i)
end do
call banslv (q, k + km1, n, km1, km1, bcoef)
return
!
!     *** ERROR RETURN
!
100 iflag = 1
return
end subroutine bstrp

subroutine banfac ( w, nroww, nrow, nbandl, nbandu, iflag )
implicit none
integer, intent(out) :: iflag
integer, intent(in) :: nbandl, nbandu, nrow, nroww
integer :: i, ipk, j, jbeg, jend, jmax, k, kmax, mdj, middle, &
&midmk, mj, nrowm1
!  From  * a practical guide to splines *  by C. DE boor
!  returns in  w  the LU-factorization (without pivoting) of the banded
!  matrix  A  of order  nrow  with  (nbandl + 1 + nbandu) bands or diag-
!  onals in the work array  w .
!
!******  i N P U T  ******
!  w.....work array of size  (nroww,nrow)  containing the interesting
!        part of A banded matrix  A , with the diagonals or bands of  A
!        stored in the rows of  w , while columns of  a  correspond to
!        columns of  w . This is the storage mode used in  LINPACK  and
!        results in efficient innermost loops.
!           Explicitly,  A  has  nbandl  bands below the diagonal
!                            +     1     (MAIN) DIAGONAL
!                            +   nbandu  BANDS ABOVE THE DIAGONAL
!        AND THUS, WITH    middle = nbandu + 1,
!          A(i+j,j)  IS IN  w(i+middle,j)  FOR i=-nbandu,...,nbandl
!                                              j=1,...,nrow .
!        For example, the interesting entries of A (1,2)-banded matrix
!        OF ORDER  9  WOULD APPEAR IN THE FIRST  1+1+2 = 4  ROWS OF  w
!        as follows.
!                          13 24 35 46 57 68 79
!                       12 23 34 45 56 67 78 89
!                    11 22 33 44 55 66 77 88 99
!                    21 32 43 54 65 76 87 98
!
!        All other entries of  w  not identified in this way with an EN-
!        try of  A  are never referenced .
!  nroww.....row dimension of the work array  w .
!        MUST BE  .GE.  nbandl + 1 + nbandu  .
!  nbandl.....number of bands of  a  below the main diagonal
!  nbandu.....number of bands of  a  above the main diagonal .
!
!******  O U T P U T  ******
!  iflag.....INTEGER INDICATING SUCCESS( = 1) OR FAILURE ( = 2) .
!     IF  iflag = 1, THEN
!  w.....contains the LU-factorization of  a  into a unit lower triangu-
!        lar matrix  L  and an upper triangular matrix  U (both banded)
!        and stored in customary fashion over the corresponding entries
!        of  A . This makes it possible to solve any particular linear
!        SYSTEM  A*X = B  FOR  X  BY A
!              call banslv ( w, nroww, nrow, nbandl, nbandu, b )
!        with the solution X  contained in  B  on return .
!     IF  iflag = 2, THEN
!        one of  nrow-1, nbandl,nbandu failed to be nonnegative, or else
!        one of the potential pivots was found to be zero indicating
!        that  a  does not have an LU-factorization. This implies that
!        A  is singular in case it is totally positive .
!
!******  M E T H O D  ******
!     Gauss elimination  w i T H O U T  pivoting is used. The routine is
!  intended for use with matrices  A  which do not require row inter-
!  changes during factorization, especially for the  T O T A L L Y
!  P O S i T i V E  matrices which occur in spline calculations.
!     The routine should not be used for an arbitrary banded matrix.
!
real, intent(inout) :: w(nroww,nrow)
real :: factor, pivot
!
iflag = 1
middle = nbandu + 1
!                         w(middle,.) Contains the main diagonal of  A .
nrowm1 = nrow - 1
if (nrowm1)                       999,900,1
1 if (nbandl .gt. 0)                go to 10
!                A is upper triangular. Check that diagonal is nonzero .
do i=1,nrowm1
   if (w(middle,i) .eq. 0.)       go to 999
   end do
                                  go to 900
10 if (nbandu .gt. 0)                go to 20
!              A is lower triangular. Check that diagonal is nonzero and
!                 divide each column by its diagonal .
do 15 i = 1,nrowm1
   pivot = w(middle,i)
   if(pivot .eq. 0.)              go to 999
   jmax = min0(nbandl, nrow - i)
   jbeg = middle + 1
   jend = middle + jmax
   do 15 j = jbeg,jend
15 w(j,i) = w(j,i)/pivot
                                  go to 900
!
!        A  is not just a triangular matrix. Construct LU factorization
20 do i=1,nrowm1
!                                  w(middle,i)  is pivot for i-TH step .
   pivot = w(middle,i)
   if (pivot .eq. 0.)             go to 999
!                 jmax  is the number of (nonzero) entries in column  i
!                     below the diagonal .
   jmax = min0(nbandl,nrow - i)
!              Divide each entry in column  i  below diagonal by pivot .
   jbeg = middle + 1
   jend = middle + jmax
   do 32 j = jbeg,jend
32 w(j,i) = w(j,i)/pivot
!                 kmax  is the number of (nonzero) entries in row  i  to
!                     the right of the diagonal .
   kmax = min0(nbandu,nrow - i)
!                  Subtract  A(i,i+k)*(i-TH column) from (i+k)-TH column
!                  (below row  i ) .
   do 40 k = 1,kmax
      ipk = i + k
      midmk = middle - k
      factor = w(midmk,ipk)
      do 40 j = 1,jmax
         mj = middle + j
         mdj = midmk + j
40 w(mdj,ipk) = w(mdj,ipk) - w(mj,i)*factor
   end do
!                                       Check the last diagonal entry .
900 if (w(middle,nrow) .ne. 0.)       return
999 iflag = 2
                                  return
end subroutine banfac

subroutine banslv ( w, nroww, nrow, nbandl, nbandu, b )
implicit none
integer, intent(in) :: nbandl, nbandu, nrow, nroww
integer :: i, imj, ipj, j, jmax, middle, mmj, mpj, nrowm1
!  From  * a practical guide to splines *  by C. DE boor
!  companion routine to  banfac . It returns the solution  X  of the
!  LINEAR SYSTEM  A*X = b  IN PLACE OF  b , GIVEN THE LU-FACTORIZATION
!  for  A  in the workarray  w .
!
!******  i N P U T  ******
!  w, nroww,nrow,nbandl,nbandu.....describe the LU-factorization of A
!        banded matrix  A  of roder  nrow  as constructed in  banfac .
!        For details, see  banfac .
!  b.....right side of the system to be solved .
!
!******  O U T P U T  ******
!  b.....contains the solution  X , of order  nrow .
!
!******  M E T H O D  ******
!     (WITH  A = L*U, AS STORED IN  w,) THE UNIT LOWER TRIANGULAR SYSTEM
!  L(U*X) = b  IS SOLVED FOR  Y = U*X, AND  Y  STORED IN  b . THEN THE
!  UPPER TRIANGULAR SYSTEM  U*X = Y  IS SOLVED FOR  X  . THE CALCUL-
!  ations are so arranged that the innermost loops stay within columns.
!
real, intent(in) :: w(nroww,nrow)
real, intent(inout) :: b(nrow)
middle = nbandu + 1
if (nrow .eq. 1)                  go to 49
nrowm1 = nrow - 1
if (nbandl .eq. 0)                go to 30
!                                 Forward pass
!            FOR i=1,2,...,nrow-1, SUBTRACT  RIGHT SIDE(i)*(i-TH COLUMN
!            of  L )  from right side  (below i-TH row) .
do 21 i = 1,nrowm1
   jmax = min0(nbandl, nrow-i)
   do 21 j = 1,jmax
      ipj = i + j
      mpj = middle + j
21 b(ipj) = b(ipj) - b(i)*w(mpj,i)
!                                 Backward pass
!            FOR i=nrow,nrow-1,...,1, DIVIDE RIGHT SIDE(i) BY i-TH DIAG-
!            onal entry of  U, then subtract  right SIDE(i)*(i-TH column
!            of  U)  from right side  (above i-TH row).
30 if (nbandu .gt. 0)                go to 40
!                                A  is lower triangular .
do 31 i = 1,nrow
31 b(i) = b(i)/w(1,i)
                                  return
40 i = nrow
41 b(i) = b(i)/w(middle,i)
   jmax = min0(nbandu,i-1)
   do 45 j = 1,jmax
      imj = i - j
      mmj = middle - j
45 b(imj) = b(imj) - b(i)*w(mmj,i)
   i = i - 1
   if (i .gt. 1)                  go to 41
49 b(1) = b(1)/w(middle,1)
                                  return
end subroutine banslv

subroutine bslsq (tau, gtau, wgt, ntau, t, n, k, a, wk, q, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: k, n, ntau
integer :: i, j, jj, l, left, leftmk, mm
real :: dw
!-----------------------------------------------------------------------
!
!        bslsq produces the B-spline coefficients of a piecewise
!              polynomial P(X) of order k which minimizes
!
!                sum (wgt(j)*(P(tau(j)) - gtau(j))**2).
!
!
!     Input ...
!
!       tau   ARRAY OF LENGTH ntau CONTAINING DATA POINT ABSCISSAE.
!       gtau  array of length ntau containing data point ordinates.
!       wgt   ARRAY OF LENGTH ntau CONTAINING THE WEIGHTS.
!       ntau  number of data points to be fitted.
!       t     KNOT SEQUENCE OF LENGTH n + k.
!       n     DIMENSION OF THE PIECEWISE POLYNOMIAL SPACE.
!       k     ORDER OF THE B-SPLINES.
!
!     Output ...
!
!       A     ARRAY OF LENGTH n CONTAINING THE B-SPLINE COEFFICIENTS
!             of the L2 approximation.
!
!       ierr  integer reporting the status of the results ...
!
!             0  The coefficient matrix is nonsigular. The
!                unique least squares solution was obtained.
!             1  The coefficient matrix is singular. A
!                least squares solution was obtained.
!            -1  Input errors were detected.
!
!-----------------------------------------------------------------------
real, intent(in) :: tau(ntau), gtau(ntau), wgt(ntau)
real, intent(in) :: t(*)
real, intent(inout) :: a(n), wk(n), q(k,n)
!
if (ntau .lt. max0(2,k)) go to 100
if (tau(1) .lt. t(k) .or. tau(ntau) .gt. t(n + 1)) go to 100
!
do i = 2,ntau
   if (tau(i - 1) .gt. tau(i)) go to 100
end do
!
do j = 1,n
   a(j) = 0.0
   do i = 1,k
      q(i,j) = 0.0
   end do
end do
!
left = k
do l = 1,ntau
!
!        *** FIND THE INDEX LEFT SUCH THAT
!            t(left) .LE. tau(l) .LT. t(left+1)
!
30 if (left .eq. n) go to 40
      if (tau(l) .lt. t(left+1)) go to 40
      left = left + 1
      go to 30
!
40 jj = 0
   call bspvb (t, k, k, jj, tau(l), left, wk)
!
   leftmk = left - k
   do mm = 1,k
      dw = wk(mm)*wgt(l)
      j = leftmk + mm
      a(j) = dw*gtau(l) + a(j)
      i = 1
      do jj = mm,k
         q(i,j) = wk(jj)*dw + q(i,j)
         i = i + 1
      end do
   end do
end do
!
!        Solve the normal equations
!
call bchfac (q, k, n, wk, ierr)
call bchslv (q, k, n, a)
return
!
!             Error return
!
100 ierr = -1
return
end subroutine bslsq

subroutine bchfac (w, nb, n, diag, iflag)
implicit none
integer, intent(inout) :: iflag
integer, intent(in) :: n, nb
integer :: i, imax, ipj, j, jmax, k, kpi
real :: ratio, t
!-----------------------------------------------------------------------
!  From  * a practical guide to splines *  by C. DE boor
!  constructs Cholesky factorization
!                     c  =  l * d * l-transpose
!  with L unit lower triangular and D diagonal, for given matrix C of
!  order  n , in case  C  is (symmetric) positive semidefinite
!  and banded, having nb diagonals at and below the main diagonal.
!
!******  INPUT  ******
!
!     n      THE ORDER OF THE MATRIX C.
!
!     nb     THE BANDWIDTH OF C, I.E.,
!               C(i,j) = 0 FOR abs(i-j) .GT. nb .
!
!     w      WORK ARRAY OF SIZE nb BY n CONTAINING THE nb DIAGONALS
!            in its rows, with the main diagonal in row 1. Precisely,
!            w(i,j)  CONTAINS  C(i+j-1,j), i=1,...,nb, j=1,...,n.
!            For example, the interesting entries of a seven diagonal
!            symmetric matrix C of order 9 would be stored in w as
!
!                       11 22 33 44 55 66 77 88 99
!                       21 32 43 54 65 76 87 98
!                       31 42 53 64 75 86 97
!                       41 52 63 74 85 96
!
!            All other entries of w not identified with an entry of C
!            are never referenced.
!
!     DIAG   WORK ARRAY OF LENGTH n.
!
!******  O U t P U t  ******
!                                                         t
!     w      CONTAINS THE CHOLESKY FACTORIZATION C = L*D*L   WHERE
!            w(1,i) = 1/D(i,i) AND w(i,j) = L(i-1+j,j) (i=2,...,nb).
!
!     iflag  0 if C is nonsingular and 1 if C is singular.
!
!******  M E t H O D  ******
!
!   Gauss elimination, adapted to the symmetry and bandedness of  C , is
!   used .
!     Near zero pivots are handled in a special way. The diagonal ele-
!  MENT C(k,k) = w(1,k) IS SAVED INITIALLY IN  diag(k), ALL k. AT THE k-
!  TH elimination step, the current pivot element, viz.  w(1,k), is com-
!  pared with its original value, diag(k). If, as the result of prior
!  elimination steps, this element has been reduced by about a word
!  LENGTH, (I.E., IF w(1,k)+diag(k) .LE. diag(k)), THEN THE PIVOT IS DE-
!  clared to be zero, and the entire k-TH row is declared to be linearly
!  dependent on the preceding rows. This has the effect of producing
!   X(k) = 0  WHEN SOLVING  C*X = B  FOR  X, REGARDLESS OF  B. JUSTIFIC-
!  ation for this is as follows. In contemplated applications of this
!  program, the given equations are the normal equations for some least-
!  SQUARES APPROXIMATION PROBLEM, diag(k) = C(k,k) GIVES THE NORM-SQUARE
!  of the k-TH basis function, and, at this point,  w(1,k)  contains the
!  norm-square of the error in the least-squares approximation to the k-
!  TH basis function BY linear combinations of the first k-1 . Having
!  w(1,k)+diag(k) .LE. diag(k) SIGNIFIES THAT THE k-TH FUNCTION IS LIN-
!  early dependent to machine accuracy on the first k-1 functions, there
!  fore can safely be left out from the basis of approximating functions
!     the solution of a linear system
!                       C*X = B
!   is effected by the succession of the following  t w O  calls ...
!     call bchfac (w, nb, n, diag, iflag)   , to get factorization
!     call bchslv (w, nb, n, b, x )            , to solve for x.
!-----------------------------------------------------------------------
real, intent(inout) :: w(nb,n), diag(n)
!
if (n .gt. 1) go to 10
   iflag = 1
   if (w(1,1) .eq. 0.0) return
   iflag = 0
   w(1,1) = 1.0/w(1,1)
   return
!
!     Store the diagonal of C in diag
!
10 do k = 1,n
   diag(k) = w(1,k)
end do
!
!     Factorization
!
iflag = 0
do 60 k = 1,n
   t = w(1,k) + diag(k)
   if (t .ne. diag(k)) go to 30
      iflag = 1
      do j = 1,nb
         w(j,k) = 0.0
      end do
      go to 60
!
30 t = 1.0/w(1,k)
   w(1,k) = t
   imax = min0(nb - 1,n - k)
   if (imax .lt. 1) go to 60
   jmax = imax
   do i = 1,imax
      ratio = t*w(i+1,k)
      kpi = k + i
      do j = 1,jmax
         ipj = i + j
         w(j,kpi) = w(j,kpi) - w(ipj,k)*ratio
      end do
      jmax = jmax - 1
      w(i+1,k) = ratio
   end do
60 continue
return
end subroutine bchfac

subroutine bchslv (w, nb, n, b)
implicit none
integer, intent(in) :: n, nb
integer :: j, jmax, jpk, k, nbm1
!-----------------------------------------------------------------------
!
!     bchslv SOLVES THE LINEAR SYSTEM C*X = b FOR X WHEN w CONTAINS
!     the Cholesky factorization obtained by the subroutine bchfac
!     for the banded symmetric positive definite matrix C.
!
!     Input ...
!
!        n   THE ORDER OF THE MATRIX C
!        nb  the bandwidth of C
!        w   THE CHOLESKY FACTORIZATION OF C
!        b   VECTOR OF LENGTH n CONTAINING THE RIGHT SIDE
!
!     Output ...
!
!        b   SOLUTION X OF THE LINEAR SYSTEM C*X = b
!
!                                       T
!     NOTE.  THE FACTORIZATION C = L*D*L  IS USED, WHERE L IS A
!     unit lower triangular matrix and D a diagonal matrix.
!
!-----------------------------------------------------------------------
real, intent(in) :: w(nb,n)
real, intent(inout) :: b(n)
!
if (n .gt. 1) go to 10
b(1) = b(1)*w(1,1)
return
!
!     FORWARD SUBSTITUTION. SOLVE L*Y = b FOR Y AND STORE Y IN b.
!
10 nbm1 = nb - 1
do 30 k = 1,n
   jmax = min0(nbm1,n - k)
   if (jmax .lt. 1) go to 30
   do j = 1,jmax
      jpk = j + k
      b(jpk) = b(jpk) - w(j + 1,k)*b(k)
   end do
30 continue
!                              T     -1
!     BACKSUBSTITUTION. SOLVE L X = D  Y  FOR X AND STORE X IN b.
!
k = n
40 b(k) = b(k)*w(1,k)
   jmax = min0(nbm1,n - k)
   if (jmax .lt. 1) go to 60
   do j = 1,jmax
      jpk = j + k
      b(k) = b(k) - w(j + 1,k)*b(jpk)
   end do
60 k = k - 1
   if (k .gt. 0) go to 40
return
end subroutine bchslv

subroutine bfit (bkpt, n, nord, xdata, ydata, ndata, &
&xconst, yconst, nderiv, nconst, &
&mode, coeff, rnorm, w, iw)
implicit none
integer, intent(inout) :: mode
integer, intent(in) :: n, nconst, ndata, nord
real, intent(inout) :: rnorm
integer :: i1, i2, i3, i7, mdg, mdw, nbkpt
!-----------------------------------------------------------------------
!
!      This subprogram fits a piece-wise polynomial curve
!      to discrete data.  The piece-wise polynomials are
!      represented as B-splines.
!      The fitting is done in a least squares sense.
!      Equality and inequality constraints can be imposed
!      on the fitted curve.
!
!  Input..
!
!      n,nord,bkpt(*)     n IS THE NUMBER OF COEFFICIENTS TO BE COM-
!                         puted and nord is the order of the B-spline.
!                         IT IS ASSUMED THAT n .GE. nord. THE n + nord
!                         knots of the spline are in the array bkpt(*).
!                         It is assumed that the knots form a nonde-
!                         creasing sequence. The problem data interval
!                         lies between the points bkpt(nord) and
!                         bkpt(n+1). The additional end knots bkpt(I),
!                         I = 1,...,nord-1 AND I = n+2,...,n+nord, ARE
!                         required to compute the functions used to
!                         fit the data.
!
!                         (The order of the B-spline is one more than
!                         the degree of the piecewise polynomial. For
!                         EXAMPLE, nord=4 WHEN WE ARE USING PIECEWISE
!                         cubics.)
!
!      ndata,xdata(*),
!      ydata(*)           THE ndata DISCRETE (X,Y) PAIRS ARE IN
!                         the arrays xdata(*) and ydata(*). It is
!                         assumed that xdata(*) is an increasing
!                         SEQUENCE, xdata(1) .GE. bkpt(nord), AND
!                         xdata(ndata) .LE. bkpt(n+1).
!
!      nconst,xconst(*),
!      yconst(*),nderiv(*)
!                         the number of conditions that constrain
!                         the B-spline is nconst. A constraint is
!                         specified by an (X,Y) pair in the arrays
!                         xconst(*) and yconst(*), and by the type
!                         of constraint and derivative value encoded
!                         in the array nderiv(*). It is assumed that
!                         the values in xconst(*) are in the closed
!                         interval (bkpt(nord),bkpt(n+1)). The con-
!                         straints may be given in any order. The
!                         value of nderiv(*) is determined as follows.
!                         Suppose the I-TH constraint applies to the
!                         J-TH derivative of the B-spline.  (Any
!                         NONNEGATIVE VALUE OF J .LT. nord IS PERMITTED.
!                         IN PARTICULAR, THE VALUE J = 0 REFERS TO THE
!                         B-spline itself.)
!                         for this I-TH constraint, set
!                          xconst(i) = x,
!                          yconst(i) = y, and
!                          nderiv(I) = ITYPE + 4*J  WHERE
!
!                          ITYPE = 0,      IF (J-TH DERIV. AT X) .LE. Y.
!                                = 1,      IF (J-TH DERIV. AT X) .GE. Y.
!                                = 2,      IF (J-TH DERIV. AT X) .EQ. Y.
!                                = 3,      IF (J-TH DERIV. AT X) .EQ.
!                                             (J-TH deriv. At Y).
!                          (A negative value for nderiv(I) will cause
!                          this constraint to be ignored.  This
!                          feature is often useful when temporarily
!                          suppressing a constraint while still
!                          retaining the source code of the calling
!                          program.)
!
!      MODE               AN INPUT FLAG THAT DIRECTS THE LEAST
!                         squares solution method used by bfit( ).
!
!                         mode = 0      A NEW PROBLEM.
!
!                         mode .NE. 0   AN OLD PROBLEM.
!
!                         By an old problem it is meant that bfit( )
!                         was last called with the same set of knots
!                         and data points. (The constraints may be
!                         different than before.)
!
!
!      iw(1),iw(2)        THE AMOUNTS OF WORKING STORAGE ACTUALLY
!                         allocated for the working arrays w(*) and
!                         iw(*).  These quantities are compared with the
!                         actual amounts of storage needed in bfit( ).
!                         Insufficient storage allocated for
!                         either w(*) or iw(*) is an error.
!
!                         Length of w(*) must be at least
!
!                           nb = (n + 3)*(nord + 1) + nord**2
!
!                         And the length of iw(*) must be at least 2.
!                         Whenever possible the code uses banded matrix
!                         processors bndacc( ) and bndsl( ).  These
!                         are utilized if there are no constraints and
!                         there is sufficient data to uniquely determine
!                         the B-spline coefficents.
!
!                         If the band processors cannot be used to
!                         determine the solution, then the constrained
!                         least squares code lsei( ) is used.
!                         In this case the subprogram requires an
!                         additional block of storage in w(*).  For the
!                         discussion here define the integers
!                         NEQCON and NINCON respectively as the
!                         NUMBER OF EQUALITY (ITYPE=2,3) AND
!                         INEQUALITY (ITYPE=0,1) CONSTRAINTS
!                         imposed on the fitted curve.  Define
!
!                           l = n + 1
!
!                         And note that
!
!                           nconst = neqcon + nincon.
!
!                         When the subprogram bfit( ) uses lsei( ) the
!                         length of the working array w(*) must be at
!                         least
!
!                           lw = nb + (l+nconst)*l + 2*(neqcon+l)
!                                   + (NINCON + L) + (NINCON+2)*(L+6)
!
!                         And the length of the array iw(*) must be at
!                         least
!
!                           iw1 = nincon + 2*l .
!
!  Output..
!
!      MODE               AN OUTPUT FLAG THAT INDICATES THE STATUS
!                         of the constrained curve fit.
!
!                         =-1  EITHER nord .LT. 1 OR nord .GT. n.
!
!                         =-2  EITHER ndata .LT. 1 OR nconst .LT. 0.
!
!                         =-3  bkpt(I) .GT. bkpt(I+1) FOR SOME I.
!
!                         =-4  xdata(*) IS NOT AN INCREASING
!                              sequence in the closed interval
!                              (bkpt(nord), bkpt(n+1)).
!
!                         =-5  THE I-TH CONSTRAINT IS INCORRECT
!                              for the value of I stored in iw(2).
!
!                         =-6  INSUFF. STORAGE FOR w(*). iw(1) HAS
!                              been reset to the amount of storage
!                              needed by w(*).
!
!                         =-7  INSUFF. STORAGE FOR iw(*). iw(2) HAS
!                              been reset to the amount of storage
!                              needed by iw(*).
!
!                         = 0  SUCCESSFUL CONSTRAINED CURVE FIT.
!
!                         = 1  THE REQUESTED EQUALITY CONSTRAINTS
!                              are contradictory.
!
!                         = 2  THE PROBLEM CANNOT BE SOLVED. THE
!                              constraints are contradictory.
!
!      coeff(*)
!                         IF THE OUTPUT VALUE OF mode=0 OR 1, coeff(*)
!                         contains the n unknowns obtained from the
!                         least squares fitting process.  These n
!                         parameters are the B-spline coefficients.
!                         FOR mode=1, THE EQUALITY CONSTRAINTS ARE
!                         contradictory.  To make the fitting process
!                         more robust, the equality constraints are
!                         satisfied in a least squares sense.  In
!                         this case the array coeff(*) contains
!                         B-spline coefficients for this extended
!                         concept of a solution.
!                         IF mode .LT. 0 OR mode = 2 ON OUTPUT, THE
!                         array coeff(*) is undefined.
!
!      rnorm              IF THE OUTPUT VALUE OF mode = 0 OR 1 THEN
!                         rnorm is the L2 norm of the vector
!                         (ydata(I) - F(xdata(I)), I = 1,ndata).
!
!  Working arrays..
!
!      w(*),iw(*)         THESE ARRAYS ARE RESPECTIVELY TYPED
!                         real and integer.  Their required
!                         lengths are specified as input parameters
!                         in iw(1), iw(2) noted above. It is assumed
!                         that w(1),...,w(NB) have not been modified
!                         if bfit( ) is being recalled for the same
!                         knots and data as before (I.E., If we have
!                         an old problem).
!
!
!   Reference.  Hanson R.J., Constrained least squares curve fitting
!               to discrete data using B-splines, a users guide.
!               Sandia labs. Tech. Rept. Sand-78-1291, DEC, 1978.
!
!-----------------------------------------------------------------------
!   Written by
!     richard J. Hanson
!     Sandia Laboratories
!   modified by A.H. Morris (NSWC)
!-----------------------------------------------------------------------
real, intent(in) :: bkpt(*), xdata(ndata), ydata(ndata)
real, intent(in) :: xconst(*), yconst(*)
real, intent(inout) :: coeff(n), w(*)
integer, intent(in) :: nderiv(*)
integer, intent(inout) :: iw(*)
!
nbkpt = n + nord
mdg = n + 3
mdw = n + 1 + nconst
!
!                         Usage in bfit0( ) of w(*)..
!
!      i1,...,i2-1      G(*,*)
!
!      i2,...,i3-1      BF(*,*)
!
!      i3,...,i7-1      w(*,*)
!
!      i7,...           WORK(*) FOR bspvd( ) AND lsei( )
!
i1 = 1
i2 = i1 + mdg*(nord + 1)
i3 = i2 + nord*nord
i7 = i3 + mdw*(n + 1)
!
call bfit0 (ndata, xdata, ydata, nord, nbkpt, bkpt, nconst, &
&xconst, yconst, nderiv, mode, coeff, rnorm, w(i2), &
&w(i1), mdg, w(i3), mdw, w(i7), iw)
return
end subroutine bfit

subroutine bfit0 (ndata, xdata, ydata, nord, nbkpt, bkpt, &
&nconst, xconst, yconst, nderiv, mode, coeff, rnorm, &
&bf, g, mdg, w, mdw, work, iwork)
implicit none
integer, intent(in) :: mdg, mdw
integer, intent(inout) :: mode
integer, intent(in) :: nbkpt, nconst, ndata, nord
real, intent(inout) :: rnorm
integer :: i, idata, ideriv, ierr, ileft, intrvl, intw1, ip, ip1, &
&ir, irow, itype, iw1, iw2, j, l, lw, m, mt, n, nb, neqcon, nincon, &
&nordm1, nordp1, np1
real :: rnorme, xmax, xmin, xval, yval
!---------------------
real, intent(in) :: bkpt(nbkpt), xdata(ndata), ydata(ndata)
real, intent(in) :: xconst(*), yconst(*)
real, intent(inout) :: coeff(*)
real, intent(inout) :: bf(nord,nord), g(mdg,*), w(mdw,*), work(*)
integer, intent(in) :: nderiv(*)
integer, intent(inout) :: iwork(*)
!
real :: prgopt(7)
logical :: band, new
!
go to 100
!
10 if (.not. band) go to 20
call bndsl (1, g, mdg, nord, ip, ir, coeff, n, rnorm, ierr)
if (ierr .eq. 0) return
!
!     Check further for sufficient storage in working arrays.
!
20 if (iw1 .lt. lw) go to 850
if (iw2 .lt. intw1) go to 860
go to 300
!
!     Solve the equations
!
30 call lsei(w, mdw, neqcon, np1, nincon, n, prgopt, coeff, rnorme, &
&rnorm, mode, work, iwork)
iwork(1) = iw1
iwork(2) = iw2
return
!-----------------------------------------------------------------------
!               Initialize-variables-and-analyze-input
!-----------------------------------------------------------------------
100 n = nbkpt - nord
if (nord .lt. 1 .or. nord .gt. n) go to 800
if (ndata .lt. 1 .or. nconst .lt. 0) go to 810
!
!     Check the break points
!
if (mode .ne. 0) go to 120
m = nbkpt - 1
do i = 1,m
   if (bkpt(i) .gt. bkpt(i+1)) go to 820
end do
!
!     Amount of storage allocated for w(*),IW(*)
!
120 iw1 = iwork(1)
iw2 = iwork(2)
nb = (n + 3)*(nord + 1) + nord*nord
lw = nb
if (iw1 .lt. nb) go to 850
!
!     Compute the amount of storage needed for lsei
!
neqcon = 0
nincon = 0
if (nconst .eq. 0) go to 150
do 140 i = 1,nconst
   l = nderiv(i)
   if (l .lt. 0) go to 140
   itype = l - 4*(l/4)
   if (itype .gt. 1) go to 130
      nincon = nincon + 1
      go to 140
130 neqcon = neqcon + 1
140 continue
!
150 np1 = n + 1
l = np1
lw = nb + (l+nconst)*l + 2*(neqcon+l) + (nincon+l) + &
&(nincon+2)*(l+6)
intw1 = nincon + 2*l
!
!     Check the xconst(*) array
!
xmin = bkpt(nord)
xmax = bkpt(np1)
if (nconst .eq. 0) go to 170
do i = 1,nconst
   if (xconst(i) .lt. xmin .or. xconst(i) .gt. xmax) &
&go to 840
end do
!
!     Initialize parameters
!
170 new = mode .eq. 0
band = nconst .eq. 0
mode = 0
nordm1 = nord - 1
nordp1 = nord + 1
!
!     Define the option vector for use in lsei( )
!
!     Increase the rank determination tolerances
!     for both equality constraint equations and
!     least squares equations.
!
prgopt(1) = 4
prgopt(2) = 4
prgopt(3) = 1.e-3
!
prgopt(4) = 7
prgopt(5) = 5
prgopt(6) = 1.e-3
!
prgopt(7) = 1
!
if (.not. new) go to 260
!
!     Check the xdata(*) array
!
if (xdata(1) .lt. xmin .or. xdata(ndata) .gt. xmax) &
&go to 830
if (ndata .eq. 1) go to 200
!
m = ndata - 1
do i = 1,m
   if (xdata(i) .ge. xdata(i+1)) go to 830
end do
!
!     Initialize parameters of banded matrix processor, bndacc( )
!
200 mt = 0
ip = 1
ir = 1
idata = 1
ileft = nord
!
210 if (idata .gt. ndata) go to 250
xval = xdata(idata)
if (ileft .eq. n) go to 230
!
!     When interval changes, process equations in the last block.
!
ip1 = ileft + 1
if (xval .lt. bkpt(ip1)) go to 230
intrvl = ileft - nordm1
call bndacc (g, mdg, nord, ip, ir, mt, intrvl)
mt = 0
!
!     MOVE POINTER UP SO THAT xval .GE. bkpt(ileft).
!
do 220 i = ip1,n
   if (xval .lt. bkpt(i)) go to 230
220 ileft = i
!
!     Obtain B-spline function VALUE
!
230 j = 0
call bspvb (bkpt, nord, nord, j, xval, ileft, bf)
!
!     Move row into place
!
irow = ir + mt
mt = mt + 1
call scopy (nord, bf, 1, g(irow,1), mdg)
g(irow,nordp1) = ydata(idata)
!
!     When staging work area is exhausted, process rows
!
if (irow .ne. mdg - 1) go to 240
   intrvl = ileft - nordm1
   call bndacc (g, mdg, nord, ip, ir, mt, intrvl)
   mt = 0
240 idata = idata + 1
go to 210
!
!     Process  block of equations
!
250 intrvl = ileft - nordm1
call bndacc (g, mdg, nord, ip, ir, mt, intrvl)
!
!     Last call to adjust block positioning
!
g(ir,1) = 0.0
call scopy (nordp1, g(ir,1), 0, g(ir,1), mdg)
call bndacc (g, mdg, nord, ip, ir, 1, np1)
!
260 do i = 1,n
  band = band .and. g(i,1) .ne. 0.0
end do
go to 10
!-----------------------------------------------------------------------
!       Analyze constraint indicators for equality constraints
!-----------------------------------------------------------------------
300 idata = 0
neqcon = 0
!
310 idata = idata + 1
if (idata .gt. nconst) go to 400
l = nderiv(idata)
if (l .lt. 0) go to 310
ideriv = l/4
itype = l - 4*ideriv
!
if (itype .lt. 2) go to 310
neqcon = neqcon + 1
xval = xconst(idata)
ileft = nord
if (nord .eq. n) go to 330
do 320 i = nordp1,n
   if (xval .lt. bkpt(i)) go to 330
320 ileft = i
330 call bspvd (bkpt, nord, xval, ileft, bf, nord, ideriv + 1, work)
w(neqcon,1) = 0.0
call scopy (n, w(neqcon,1), 0, w(neqcon,1), mdw)
intrvl = ileft - nordm1
call scopy (nord, bf(1,ideriv+1), 1, w(neqcon,intrvl), mdw)
if (itype .ne. 2) go to 340
w(neqcon,np1) = yconst(idata)
go to 310
!
340 w(neqcon,np1) = 0.0
yval = yconst(idata)
i = idata
if (yval .lt. xmin .or. yval .gt. xmax) go to 840
ileft = nord
if (nord .eq. n) go to 360
do 350 i = nordp1,n
   if (yval .lt. bkpt(i)) go to 360
350 ileft = i
360 call bspvd (bkpt, nord, yval, ileft, bf, nord, ideriv + 1, work)
intrvl = ileft - nordm1
call saxpy (nord, -1.0, bf(1,ideriv+1), 1, w(neqcon,intrvl), mdw)
go to 310
!-----------------------------------------------------------------------
!                    Transfer-least-squares data
!-----------------------------------------------------------------------
400 do i = 1,np1
  irow = i + neqcon
  w(irow,1) = 0.0
  call scopy (n, w(irow,1), 0, w(irow,1), mdw)
  call scopy (min0(np1-i,nord), g(i,1), mdg, w(irow,i), mdw)
  w(irow,np1) = g(i,nordp1)
end do
!-----------------------------------------------------------------------
!      Analyze constraint indicators for inequality constraints
!-----------------------------------------------------------------------
idata = 0
nincon = 0
!
500 idata = idata + 1
if (idata .gt. nconst) go to 30
l = nderiv(idata)
if (l .lt. 0) go to 500
ideriv = l/4
itype = l - 4*ideriv
!
if (itype .gt. 1) go to 500
nincon = nincon + 1
xval = xconst(idata)
ileft = nord
if (nord .eq. n) go to 520
do 510 i = nordp1,n
   if (xval .lt. bkpt(i)) go to 520
510 ileft = i
520 call bspvd (bkpt, nord, xval, ileft, bf, nord, ideriv + 1, work)
irow = neqcon + np1 + nincon
w(irow,1) = 0.0
call scopy (n, w(irow,1), 0, w(irow,1), mdw)
intrvl = ileft - nordm1
call scopy (nord, bf(1,ideriv+1), 1, w(irow,intrvl), mdw)
w(irow,np1) = yconst(idata)
if (itype .ne. 0) go to 500
w(irow,np1) = -w(irow,np1)
call sscal(nord, -1.0, w(irow,intrvl), mdw)
go to 500
!-----------------------------------------------------------------------
!                         Error return
!-----------------------------------------------------------------------
!                       EITHER nord .LT. 1 OR nord .GT. N.
800 mode = -1
return
!                       EITHER ndata .LT. 1 OR nconst .LT. 0.
810 mode = -2
return
!                       The sequence of knots is not nondecreasing.
820 mode = -3
return
!                       xdata(*) is not an increasing sequence in the
!                       closed interval (bkpt(1),bkpt(N+1)).
830 mode = -4
return
!                       The i-TH constraint is incorrect for the
!                       value of i stored in iwork(2).
840 iwork(2) = i
mode = -5
return
!                       Insuff. Storage for w(*). iwork(1) has been set
!                       to the amount of storage needed by w(*).
850 iwork(1) = lw
mode = -6
return
!                       Insuff. Storage for IW(*). iwork(2) has been set
!                       to the amount of storage needed by IW(*).
860 iwork(2) = intw1
mode = -7
return
end subroutine bfit0

subroutine bndacc (g,mdg,nb,ip,ir,mt,jt)
implicit none
integer, intent(inout) :: ip, ir
integer, intent(in) :: jt, mdg, mt, nb
real, intent(inout) :: g(mdg,*)
integer :: i, ie, ig, ig1, ig2, j, jg, k, kh, l, lp1, mh, mu, nbp1
real :: rho
!
!***AUTHOR  LAWSON, C. L., (JPL)
!           Hanson, R. J., (SNLA)
!
!***PURPOSE  SOLVE THE LEAST SQUARES PROBLEM AX = B FOR BANDED
!            matrices a using sequential accumulation of rows of
!            the data matrix.  Exactly one right-handed side vector
!            is permitted.
!***DESCRIPTION
!
!     THESE SUBROUTINES SOLVE THE LEAST SQUARES PROBLEM AX = B FOR
!     banded matrices a using sequential accumulation of rows of the
!     data matrix.  Exactly one right-hand side vector is permitted.
!
!     These subroutines are intended for the type of least squares
!     systems that arise in applications such as curve or surface
!     fitting of data.  The least squares equations are accumulated and
!     processed using only part of the data.  This requires a certain
!     USER INTERACTION DURING THE SOLUTION OF AX = B.
!
!     Specifically, suppose the data matrix (A B) is row partitioned
!     into Q submatrices.  Let (E F) be the T-TH one of these
!     SUBMATRICES WHERE E = (0 C 0).  HERE THE DIMENSION OF E IS mt BY N
!     and the dimension of C is mt by nb.  The value of nb is the
!     bandwidth of A.  the dimensions of the leading block of zeros in E
!     are mt by jt-1.
!
!     The user of the subroutine bndacc provides mt,jt,C and F for
!     T=1,...,Q.  NOT ALL OF THIS DATA MUST BE SUPPLIED AT ONCE.
!
!     Following the processing of the various blocks (E F), the matrix
!     (A B) has been transformed to the form (R D) where R is upper
!     triangular and banded with bandwidth nb.  The least squares
!     SYSTEM RX = D IS THEN EASILY SOLVED USING BACK SUBSTITUTION BY
!     executing the statement call bndsl(1,...). The sequence of
!     values for jt must be nondecreasing.  This may require some
!     preliminary interchanges of rows and columns of the matrix A.
!
!     The primary reason for these subroutines is that the total
!     processing can take place in a working array of dimension mu by
!     nb+1.  An acceptable value for mu is
!
!                       mu = max(mt + n + 1),
!
!     Where N is the number of unknowns.
!
!     HERE THE MAXIMUM IS TAKEN OVER ALL VALUES OF mt FOR T=1,...,Q.
!     Notice that mt can be taken to be a small as one, showing that
!     mu can be as small as N+2.  The subprogram bndacc processes the
!     rows more efficiently if mu is large enough so that each new
!     block (C F) has a distinct value of jt.
!
!     The four principle parts of these algorithms are obtained by the
!     following call statements
!
!     call bndacc(...)  introduce new blocks of data.
!
!     call bndsl(1,...)compute solution vector and length of
!                       residual vector.
!
!     call bndsl(2,...)given any row vector h solve yr = h for the
!                       row vector Y.
!
!     call bndsl(3,...)given any column vector w solve rz = w for
!                       the column vector Z.
!
!     The dots in the above call statements indicate additional
!     arguments that will be specified in the following paragraphs.
!
!     The user must dimension the array appearing in the call list..
!     g(mdg,nb+1)
!
!     Description of calling sequence for bndacc..
!
!     The entire set of parameters for bndacc are
!
!     Input..
!
!     g(*,*)            THE WORKING ARRAY INTO WHICH THE USER WILL
!                       place the mt by nb+1 block (C F) in rows ir
!                       through ir+mt-1, columns 1 through nb+1.
!                       See descriptions of ir and mt below.
!
!     mdg               THE NUMBER OF ROWS IN THE WORKING ARRAY
!                       g(*,*).  THE VALUE OF mdg SHOULD BE .GE. mu.
!                       The value of mu is defined in the abstract
!                       of these subprograms.
!
!     nb                THE BANDWIDTH OF THE DATA MATRIX A.
!
!     ip                SET BY THE USER TO THE VALUE 1 BEFORE THE
!                       first call to bndacc.  Its subsequent value
!                       is controlled by bndacc to set up for the
!                       next call to bndacc.
!
!     ir                INDEX OF THE ROW OF g(*,*) WHERE THE USER IS
!                       to place the new block of data (C F).  Set by
!                       the user to the value 1 before the first call
!                       to bndacc.  Its subsequent value is controlled
!                       BY bndacc. A VALUE OF ir .GT. mdg IS CONSIDERED
!                       an error.
!
!     mt,jt             SET BY THE USER TO INDICATE RESPECTIVELY THE
!                       number of new rows of data in the block and
!                       the index of the first nonzero column in that
!                       SET OF ROWS (E F) = (0 C 0 F) BEING PROCESSED.
!
!     Output..
!
!     g(*,*)            THE WORKING ARRAY WHICH WILL CONTAIN THE
!                       processed rows of that part of the data
!                       matrix which has been passed to bndacc.
!
!     ip,ir             THE VALUES OF THESE ARGUMENTS ARE ADVANCED BY
!                       bndacc to be ready for storing and processing
!                       a new block of data in g(*,*).
!
!
!     Remarks..
!
!     To obtain the upper triangular matrix and transformed right-hand
!     side vector D so that the super diagonals of R form the columns
!     of g(*,*), execute the following Fortran statements.
!
!     nbp1=nb+1
!
!     do 10 j=1, nbp1
!
!  10 g(ir,j) = 0.e0
!
!     mt=1
!
!     jt=n+1
!
!     call bndacc(g,mdg,nb,ip,ir,mt,jt)
!
!***REFERENCES  C. L. LAWSON AND R. J. HANSON,
!                 solving least square problems,PRENCTICE-Hall, inc
!                 (1974), chapter 27
!
!
!
!              Alg. Steps 1-4 are performed external to this subroutine.
!
nbp1 = nb + 1
if (mt .le. 0 .or. nb .le. 0) return
!                                             Alg. Step 5
if (jt .eq. ip) go to 70
!                                             Alg. Steps 6-7
if (jt .le. ir) go to 30
!                                             Alg. Steps 8-9
do i = 1,mt
   ig1 = jt + mt - i
   ig2 = ir + mt - i
   do j = 1,nbp1
      g(ig1,j) = g(ig2,j)
   end do
end do
!                                             Alg. Step 10
ie = jt - ir
do i = 1,ie
   ig = ir + i - 1
   do j = 1,nbp1
     g(ig,j) = 0.0
   end do
end do
!                                             Alg. Step 11
ir = jt
!                                             Alg. Step 12
30 mu = min0(nb - 1, ir - ip - 1)
if (mu .eq. 0) go to 60
!                                             Alg. Step 13
do l = 1,mu
!                                             Alg. Step 14
   k = min0(l, jt - ip)
!                                             Alg. Step 15
   lp1 = l + 1
   ig = ip + l
   do i = lp1,nb
      jg = i - k
      g(ig,jg) = g(ig,i)
   end do
!                                             Alg. Step 16
   do i = 1,k
      jg = nbp1 - i
      g(ig,jg) = 0.0
   end do
end do
!                                             Alg. Step 17
60 ip = jt
!                                             Alg. Steps 18-19
70 mh = ir + mt - ip
kh = min0(nbp1, mh)
!                                             Alg. Step 20
do i = 1,kh
   call h12 (1,i,max0(i+1,ir-ip+1),mh,g(ip,i),1,rho, &
&g(ip,i+1),1,mdg,nbp1-i)
end do
!                                             Alg. Step 21
ir = ip + kh
!                                             Alg. Step 22
if (kh .lt. nbp1) go to 100
!                                             Alg. Step 23
do i = 1,nb
   g(ir-1,i) = 0.0
end do
!                                             Alg. Step 24
100 continue
!                                             Alg. Step 25
return
end subroutine bndacc

subroutine bndsl (mode,g,mdg,nb,ip,ir,x,n,rnorm,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ip, ir, mdg, mode, n, nb
real :: g(mdg,*)
real, intent(out) :: rnorm
real, intent(inout) :: x(n)
integer :: i, i1, i2, ie, ii, irm1, ix, j, jg, l, np1
real :: rsq, s
!
!***AUTHOR  LAWSON, C. L., (JPL)
!           Hanson, R. J., (SNLA)
!
!***PURPOSE  SOLVE THE LEAST SQUARES PROBLEM AX = B FOR BANDED
!            matrices a using sequential accumulation of rows of
!            the data matrix.  Exactly one right-handed side vector
!            is permitted.
!
!     THESE SUBROUTINES SOLVE THE LEAST SQUARES PROBLEM AX = B FOR
!     banded matrices a using sequential accumulation of rows of the
!     data matrix.  Exactly one right-hand side vector is permitted.
!
!     These subroutines are intended for the type of least squares
!     systems that arise in applications such as curve or surface
!     fitting of data.  The least squares equations are accumulated and
!     processed using only part of the data.  This requires a certain
!     USER INTERACTION DURING THE SOLUTION OF AX = B.
!
!     Specifically, suppose the data matrix (A B) is row partitioned
!     into Q submatrices.  Let (E F) be the T-TH one of these
!     SUBMATRICES WHERE E = (0 C 0).  HERE THE DIMENSION OF E IS MT BY n
!     and the dimension of C is MT by nb.  The value of nb is the
!     bandwidth of A.  the dimensions of the leading block of zeros in E
!     are MT by JT-1.
!
!     The user of the subroutine bndacc provides MT,JT,C and F for
!     T=1,...,Q.  NOT ALL OF THIS DATA MUST BE SUPPLIED AT ONCE.
!
!     Following the processing of the various blocks (E F), the matrix
!     (A B) has been transformed to the form (R D) where R is upper
!     triangular and banded with bandwidth nb.  The least squares
!     SYSTEM RX = D IS THEN EASILY SOLVED USING BACK SUBSTITUTION BY
!     executing the statement call bndsl(1,...). The sequence of
!     values for JT must be nondecreasing.  This may require some
!     preliminary interchanges of rows and columns of the matrix A.
!
!     The primary reason for these subroutines is that the total
!     processing can take place in a working array of dimension mu by
!     nb+1.  An acceptable value for mu is
!
!                       mu = max(mt + n + 1),
!
!     Where n is the number of unknowns.
!
!     HERE THE MAXIMUM IS TAKEN OVER ALL VALUES OF MT FOR T=1,...,Q.
!     Notice that MT can be taken to be a small as one, showing that
!     mu can be as small as n+2.  The subprogram bndacc processes the
!     rows more efficiently if mu is large enough so that each new
!     block (C F) has a distinct value of JT.
!
!     The four principle parts of these algorithms are obtained by the
!     following call statements
!
!     call bndacc(...)  introduce new blocks of data.
!
!     call bndsl(1,...)compute solution vector and length of
!                       residual vector.
!
!     call bndsl(2,...)given any row vector h solve yr = h for the
!                       row vector Y.
!
!     call bndsl(3,...)given any column vector w solve rz = w for
!                       the column vector Z.
!
!     The dots in the above call statements indicate additional
!     arguments that will be specified in the following paragraphs.
!
!     The user must dimension the array appearing in the call list..
!     g(mdg,nb+1)
!
!     Description of calling sequence for bndsl..
!
!     The user must dimension the arrays appearing in the call list..
!
!     g(mdg,nb+1), x(n)
!
!     The entire set of parameters for bndsl are
!
!     Input..
!
!     MODE              SET BY THE USER TO ONE OF THE VALUES 1, 2, OR
!                       3.  These values respectively indicate that
!                       THE SOLUTION OF AX = B, YR = H OR RZ = W IS
!                       required.
!
!     g(*,*),mdg,       THESE ARGUMENTS ALL HAVE THE SAME MEANING AND
!      nb,ip,ir         CONTENTS AS FOLLOWING THE LAST CALL TO bndacc.
!
!     x(*)              WITH mode=2 OR 3 THIS ARRAY CONTAINS,
!                       respectively, the right-side vectors H or W of
!                       THE SYSTEMS YR = H OR RZ = W.
!
!     n                 THE NUMBER OF VARIABLES IN THE SOLUTION
!                       vector.  If any of the n diagonal terms are
!                       zero the subroutine bndsl prints an
!                       appropriate message.  This condition is
!                       considered an error.
!
!     Output..
!
!     x(*)              THIS ARRAY CONTAINS THE SOLUTION VECTORS x,
!                       Y OR Z OF THE SYSTEMS AX = B, YR = H OR
!                       RZ = W DEPENDING ON THE VALUE OF mode=1,
!                       2 or 3.
!
!     rnorm             IF mode=1 rnorm IS THE EUCLIDEAN LENGTH OF THE
!                       RESIDUAL VECTOR ax-B.  WHEN mode=2 OR 3 rnorm
!                       is set to zero.
!
!     ierr              ierr = 0 IF THE SOLUTION WAS OBTAINED.
!                       ierr = 1 IF THE PROBLEM CANNOT BE SOLVED.
!
!
!***REFERENCES  C. L. LAWSON AND R. J. HANSON,
!                 solving least square problems,PRENCTICE-Hall, inc
!                 (1974), chapter 27
!
!
ierr = 0
rnorm = 0.0
go to (10,90,50), mode
!                                   ********************* mode = 1
!                                   alg. Step 26
10 do j = 1,n
   x(j) = g(j, nb+1)
end do
rsq = 0.0
np1 = n + 1
irm1 = ir - 1
if (np1 .gt. irm1) go to 40
   do j = np1,irm1
      rsq = rsq + g(j, nb+1)**2
   end do
   rnorm = sqrt(rsq)
40 continue
!                                   ********************* mode = 3
!                                   alg. Step 27
50 do ii = 1,n
   i = n + 1 - ii
!                                   Alg. Step 28
   s = 0.0
   l = max0(0, i - ip)
!                                   Alg. Step 29
   if (i .eq. n) go to 70
!                                   Alg. Step 30
      ie = min0(n + 1 - i, nb)
      do j = 2,ie
         jg = j + l
         ix = i - 1 + j
         s = s + g(i,jg)*x(ix)
      end do
!                                   Alg. Step 31
70 if (g(i,l+1) .eq. 0.0) go to 130
   x(i) = (x(i) - s)/g(i,l+1)
end do
!                                   Alg. Step 32
return
!                                   ********************* mode = 2
90 do j = 1,n
   s = 0.0
   if (j .eq. 1) go to 110
      i1 = max0(1, j - nb + 1)
      i2 = j - 1
      do i = i1,i2
         l = j - i + 1 + max0(0, i - ip)
         s = s + x(i)*g(i,l)
      end do
110 l = max0(0, j - ip)
   if (g(j,l+1) .eq. 0.0) go to 130
   x(j) = (x(j) - s)/g(j,l+1)
end do
return
!
!            A zero diagonal term occurs
!
130 ierr = 1
return
end subroutine bndsl

subroutine spfit2 (x, wx, mx, y, wy, my, z, kz, xbreak, nx, &
&ybreak, ny, f, s, t, wk, num, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: kz, mx, my, num, nx, ny
integer :: i, imax, j, l, ld, m, n, nu
!-----------------------------------------------------------------------
!
!            Weighted least squares bicubic spline fitting
!
!                          -----------------
!
!     The piecewise polynomials considered are tensor products of
!     B-splines, having the form
!
!                          m    n
!              f(x,y)  =  SUM  SUM  A   U (x) V (y)
!                         i=1  j=1   IJ  i     j
!
!     WHERE m = nx + 2 AND n = ny + 2, AND U  AND V  ARE B-SPLINE
!     BASIS FUNCTIONS OF DEGREE 3. LET      i      j
!
!                       m
!              G (x) = SUM A   U (x)
!               j      i=1  IJ  i
!
!     FOR j = 1,...,n. THEN G (x),...,G (x) ARE CUBIC SPLINES AND
!                            1         n
!                        n
!              f(x,y) = SUM G (x) V (y) .
!                       j=1  j     j
!
!     The arrays s and t defined in the code are the knot sequences
!     for the B-splines U (x) and V (y).
!                        i         j
!-----------------------------------------------------------------------
!     Written by
!        Alfred H. Morris, Jr.
!        Naval Surface Warfare Center
!        Dahlgren, Virginia
!-----------------------------------------------------------------------
real, intent(in) :: x(mx), wx(mx), y(my), wy(my), z(kz, my)
real, intent(in) :: xbreak(nx), ybreak(ny)
real, intent(inout) :: f(*)
real, intent(inout) :: s(*), t(*), wk(num)
!---------------------
!     real f(4*nx*ny), s(nx + 6), t(ny + 6)
!---------------------
if (nx .lt. 2) go to 100
if (ny .lt. 2) go to 120
m = nx + 2
n = ny + 2
l = max0(m*n, m*my + 5*max0(m,n))
if (num .lt. l) go to 130
!
!     Define the knot squences
!
s(1) = xbreak(1)
s(2) = xbreak(1)
s(3) = xbreak(1)
s(4) = xbreak(1)
do i = 2,nx
   if (xbreak(i - 1) .ge. xbreak(i)) go to 100
   s(i + 3) = xbreak(i)
end do
s(nx + 4) = xbreak(nx)
s(nx + 5) = xbreak(nx)
s(nx + 6) = xbreak(nx)
!
t(1) = ybreak(1)
t(2) = ybreak(1)
t(3) = ybreak(1)
t(4) = ybreak(1)
do j = 2,ny
   if (ybreak(j - 1) .ge. ybreak(j)) go to 120
   t(j + 3) = ybreak(j)
end do
t(ny + 4) = ybreak(ny)
t(ny + 5) = ybreak(ny)
t(ny + 6) = ybreak(ny)
!
!     Obtain the B-spline coefficients of the bivariate
!     least squares fit and store them in wk.
!
call bslsq2 (x, wx, mx, y, wy, my, z, kz, s, m, 4, &
&t, n, 4, f, m, wk, num, ierr)
if (ierr .lt. 0) go to 110
ierr = 0
!
l = m*n
do i = 1,l
   wk(i) = f(i)
end do
!
!     Compute the n cubic splines G (x) and their first
!                                  j
!     derivatives at the points in xbreak. Then store the
!     derivatives in wk. (The values of the splines will
!     be in the latter half of f.)
!
nu = nx*ny
l = 2*nu + 1
call cspp (s, wk, m, m, n, f(l), n, f(1), n)
!
imax = n*nx
do i = 1,imax
   wk(i) = f(i)
end do
!
!     Compute the values of the bispline and their partial
!     derivatives with respect to y. the results are stored
!     in the first half of f.
!
ld = nu + 1
call cspp (t, f(l), n, n, nx, f(1), nx, f(ld), nx)
!
!     Compute the remaining partial derivatives and store
!     the results in the latter half of f.
!
ld = l + nu
call cspp (t, wk, n, n, nx, f(l), nx, f(ld), nx)
return
!
!     Error return
!
100 ierr = 1
return
110 ierr = 2
if (ierr .eq. -2) ierr = 4
return
120 ierr = 3
return
130 ierr = 5
wk(1) = l
return
end subroutine spfit2

subroutine cspp (t, a, ka, m, n, z, kz, dz, kdz)
implicit none
integer, intent(in) :: ka, kdz, kz, m, n
integer :: i, il, ilj, ilkj, j, jj, jp1, k, kmj, l, left, mp1, mu
real :: del, diff, r, s, term, x
!-----------------------------------------------------------------------
!
!            Computation of n cubic splines and their first
!            derivatives at the knots t(4),...,t(m+1). The
!            cubic splines are represented in B-spline form.
!
!                          ---------------
!
!     Input ...
!
!       t     KNOT SEQUENCE OF LENGTH m+4.
!       A     m x n MATRIX. EACH COLUMN OF A IS A SEQUENCE
!             of m B-spline coefficients for a cubic spline.
!       ka    THE NUMBER OF ROWS SPECIFIED IN THE CALLING
!             PROGRAM FOR A. IT IS ASSUMED THAT ka .GE. m.
!       m     DIMENSION OF THE B-SPLINE SPACE.
!       n     NUMBER OF CUBIC SPLINES CONSIDERED.
!       kz    THE NUMBER OF ROWS SPECIFIED IN THE CALLING
!             PROGRAM FOR z. IT IS ASSUMED THAT kz .GE. n.
!       kdz   THE NUMBER OF ROWS SPECIFIED IN THE CALLING
!             PROGRAM FOR dz. IT IS ASSUMED THAT kz .GE. n.
!
!     Output ...
!
!       z     n x (m-2) MATRIX WHERE z(j,i) = VALUE OF j-TH CUBIC
!             SPLINE AT THE POINT t(i+3) FOR i = 1,...,m-2.
!
!       dz    n x (m-2) MATRIX WHERE dz(j,i) = FIRST DERIVATIVE OF
!             the j-TH cubic spline evaluated at the point t(i+3).
!
!-----------------------------------------------------------------------
real, intent(in) :: t(*), a(ka,n)
real, intent(inout) :: z(kz,*), dz(kdz,*)
real :: c(4), wk(4,5)
!
k = 4
mp1 = m + 1
do mu = 1,n
!
!        Obtaing the values for the mu-TH cubic spline
!
   l = 0
   do left = k,m
      l = l + 1
!
!           Compute the coefficients for the l-TH
!           polynomial forming the cubic spline. The
!           coefficients are stored in c. this code
!           is from the subroutine bspp.
!
      do j = 1,k
         jj = left - k + j
         wk(j,1) = a(jj,mu)
      end do
!
      do j = 1,3
         jp1 = j + 1
         kmj = k - j
         do i = 1,kmj
            il = i + left
            ilkj = il - kmj
            diff = t(il) - t(ilkj)
            wk(i,jp1) = (wk(i+1,j) - wk(i,j))/diff
         end do
      end do
!
      wk(1,5) = 1.0
      x = t(left)
      c(4) = wk(1,4)
      r = 1.0
      do j = 1,3
         jp1 = j + 1
         s = 0.0
         do i = 1,j
            il = i + left
            ilj = il - j
            term = wk(i,5)/(t(il) - t(ilj))
            wk(i,5) = s + (t(il) - x)*term
            s = (x - t(ilj))*term
         end do
         wk(jp1,5) = s
!
         s = 0.0
         kmj = k - j
         do i = 1,jp1
            s = s + wk(i,kmj)*wk(i,5)
         end do
         r = (r*float(kmj))/float(j)
         c(kmj) = r*s
      end do
!
!           Store the value of the spline and its
!           first derivative at the knot t(left)
!
      z(mu,l) = c(1)
      dz(mu,l) = c(2)
   end do
!
!        Compute the spline and its first derivative
!                    at the knot t(m+1)
!
   l = l + 1
   del = t(mp1) - t(m)
   z(mu,l) = ((c(4)*del + c(3))*del + c(2))*del + c(1)
   dz(mu,l) = (3.0*c(4)*del + 2.0*c(3))*del + c(2)
end do
return
end subroutine cspp

subroutine csurf (ider, jder, x, mx, y, my, z, kz, s, m, t, n, &
&f, kf, f1, kf1, f2, kf2, f12, kf12)
implicit none
integer, intent(in) :: ider, jder, kf, kf1, kf12, kf2, kz, m, mx, &
&my, n
integer :: i, iold, ip1, j, jold, jp1, k, l, mm1, nm1
real :: a, b, b1, b2, b3, bx, c, c1, c2, c3, cx, d, dfi, dfip1, &
&ds, dt, dx, dy, fi, fip1, xx, yy
integer :: intrvl
!-----------------------------------------------------------------------
!
!             Evaluation or differentiation of a bicubic
!                        spline over a grid
!
!-----------------------------------------------------------------------
real, intent(in) :: x(mx), y(my)
real, intent(inout) :: z(kz,my)
real, intent(in) :: s(m), t(n), f(kf,n), f1(kf1,n), f2(kf2,n), &
&f12(kf12,n)
!
if (ider .gt. 3 .or. jder .gt. 3) go to 400
mm1 = m - 1
nm1 = n - 1
!
iold = 0
jold = 0
do l = 1,my
   yy = y(l)
   if (yy .lt. t(2)) go to 10
   if (yy .ge. t(nm1)) go to 20
   if (l .eq. 1) go to 30
   if (yy - y(l-1)) 30,50,40
!
10 j = 1
   go to 50
20 j = nm1
   go to 50
30 j = intrvl (yy, t, n)
   go to 50
!
!        Linear forward search
!
40 if (yy .lt. t(j + 1)) go to 50
   j = j + 1
   go to 40
!
50 jp1 = j + 1
   dt = t(jp1) - t(j)
!
   do 350 k = 1,mx
      xx = x(k)
      if (xx .lt. s(2)) go to 100
      if (xx .ge. s(mm1)) go to 110
      if (k .eq. 1) go to 120
      if (xx - x(k-1)) 120,130,140
!
100 i = 1
      if (i .eq. iold .and. j .eq. jold) go to 210
      go to 200
110 i = mm1
      if (i .eq. iold .and. j .eq. jold) go to 210
      go to 200
120 i = intrvl (xx, s, m)
      if (i .eq. iold .and. j .eq. jold) go to 210
      go to 200
130 z(k,l) = z(k-1,l)
      go to 350
!
!           Linear forward search
!
140 if (xx .lt. s(i + 1)) go to 210
150 i = i + 1
         if (xx .ge. s(i + 1)) go to 150
!
!           Computation of the jder-TH derivative of
!           f(s(i),y), D1F(s(i),y), f(s(i+1),y), AND
!           D1F(s(i+1),y) at the point YY.
!
200 iold = i
         ip1 = i + 1
         ds = s(ip1) - s(i)
!
         d = (f(i,jp1) - f(i,j))/dt
         a = f2(i,j) + f2(i,jp1)
         b = (-a - f2(i,j) + 3.0*d)/dt
         c = (a - d - d)/(dt*dt)
!
         d = (f(ip1,jp1) - f(ip1,j))/dt
         a = f2(ip1,j) + f2(ip1,jp1)
         b1 = (-a - f2(ip1,j) + 3.0*d)/dt
         c1 = (a - d - d)/(dt*dt)
!
         d = (f1(i,jp1) - f1(i,j))/dt
         a = f12(i,j) + f12(i,jp1)
         b2 = (-a - f12(i,j) + 3.0*d)/dt
         c2 = (a - d - d)/(dt*dt)
!
         d = (f1(ip1,jp1) - f1(ip1,j))/dt
         a = f12(ip1,j) + f12(ip1,jp1)
         b3 = (-a - f12(ip1,j) + 3.0*d)/dt
         c3 = (a - d - d)/(dt*dt)
!
210 dy = yy - t(j)
      if (jder .eq. 0) go to 220
      if (jder - 2) 230,240,250
!
220 fi = ((c*dy + b)*dy + f2(i,j))*dy + f(i,j)
      fip1 = ((c1*dy + b1)*dy + f2(ip1,j))*dy + f(ip1,j)
      dfi = ((c2*dy + b2)*dy + f12(i,j))*dy + f1(i,j)
      dfip1 = ((c3*dy + b3)*dy + f12(ip1,j))*dy + f1(ip1,j)
      go to 300
!
230 fi = (3.0*c*dy + 2.0*b)*dy + f2(i,j)
      fip1 = (3.0*c1*dy + 2.0*b1)*dy + f2(ip1,j)
      dfi = (3.0*c2*dy + 2.0*b2)*dy + f12(i,j)
      dfip1 = (3.0*c3*dy + 2.0*b3)*dy + f12(ip1,j)
      go to 300
!
240 fi = 6.0*c*dy + 2.0*b
      fip1 = 6.0*c1*dy + 2.0*b1
      dfi = 6.0*c2*dy + 2.0*b2
      dfip1 = 6.0*c3*dy + 2.0*b3
      go to 300
!
250 fi = 6.0*c
      fip1 = 6.0*c1
      dfi = 6.0*c2
      dfip1 = 6.0*c3
!
!           Computation of the ider-TH derivative
!           at the point XX.
!
300 d = (fip1 - fi)/ds
      a = dfi + dfip1
      bx = (-a - dfi + 3.0*d)/ds
      cx = (a - d - d)/(ds*ds)
!
      dx = xx - s(i)
      if (ider .eq. 0) go to 310
      if (ider - 2) 320,330,340
!
310 z(k,l) = ((cx*dx + bx)*dx + dfi)*dx + fi
      go to 350
320 z(k,l) = (3.0*cx*dx + 2.0*bx)*dx + dfi
      go to 350
330 z(k,l) = 6.0*cx*dx + 2.0*bx
      go to 350
340 z(k,l) = 6.0*cx
!
350 continue
   jold = j
end do
return
!
!     Case when the results are zero.
!
400 do l = 1,my
   do k = 1,mx
      z(k,l) = 0.0
   end do
end do
return
end subroutine csurf

subroutine csurf1 (ider, jder, x, mx, y, my, z, kz, s, m, t, n, f)
implicit none
integer, intent(in) :: ider, jder, kz, m, mx, my, n
!-----------------------------------------------------------------------
!
!             Evaluation or differentiation of a bicubic
!                        spline over a grid
!
!-----------------------------------------------------------------------
real, intent(in) :: x(mx), y(my)
real, intent(inout) :: z(kz,my)
real, intent(in) :: s(m), t(n), f(m,n,4)
!
call csurf (ider, jder, x, mx, y, my, z, kz, s, m, t, n, f, m, &
&f(1,1,3), m, f(1,1,2), m, f(1,1,4), m)
return
end subroutine csurf1

subroutine csrf (ider, jder, x, mx, y, my, z, kz, s, m, t, n, &
&f, kf, f1, kf1, f2, kf2, f12, kf12)
implicit none
integer, intent(in) :: ider, jder, kf, kf1, kf12, kf2, kz, m, mx, &
&my, n
integer :: i, iold, ip1, j, jold, jp1, k, l, mm1, nm1
real :: a, a1, a2, a3, ax, c, c1, c2, c3, cx, d, dfi, dfip1, ds, &
&dt, dx, dy, fi, fip1, xx, yy
integer :: intrvl
!-----------------------------------------------------------------------
!
!             Evaluation or differentiation of a bicubic
!                        spline over a grid
!
!-----------------------------------------------------------------------
real, intent(in) :: x(mx), y(my)
real, intent(inout) :: z(kz,my)
real, intent(in) :: s(m), t(n), f(kf,n), f1(kf1,n), f2(kf2,n), &
&f12(kf12,n)
!
if (ider .gt. 3 .or. jder .gt. 3) go to 400
mm1 = m - 1
nm1 = n - 1
!
iold = 0
jold = 0
do l = 1,my
   yy = y(l)
   if (yy .lt. t(2)) go to 10
   if (yy .ge. t(nm1)) go to 20
   if (l .eq. 1) go to 30
   if (yy - y(l-1)) 30,50,40
!
10 j = 1
   go to 50
20 j = nm1
   go to 50
30 j = intrvl (yy, t, n)
   go to 50
!
!        Linear forward search
!
40 if (yy .lt. t(j + 1)) go to 50
   j = j + 1
   go to 40
!
50 jp1 = j + 1
   dt = t(jp1) - t(j)
!
   do 350 k = 1,mx
      xx = x(k)
      if (xx .lt. s(2)) go to 100
      if (xx .ge. s(mm1)) go to 110
      if (k .eq. 1) go to 120
      if (xx - x(k-1)) 120,130,140
!
100 i = 1
      if (i .eq. iold .and. j .eq. jold) go to 210
      go to 200
110 i = mm1
      if (i .eq. iold .and. j .eq. jold) go to 210
      go to 200
120 i = intrvl (xx, s, m)
      if (i .eq. iold .and. j .eq. jold) go to 210
      go to 200
130 z(k,l) = z(k-1,l)
      go to 350
!
!           Linear forward search
!
140 if (xx .lt. s(i + 1)) go to 210
150 i = i + 1
         if (xx .ge. s(i + 1)) go to 150
!
!           Computation of the jder-TH derivative of
!           f(s(i),y), D1F(s(i),y), f(s(i+1),y), AND
!           D1F(s(i+1),y) at the point YY.
!
200 iold = i
         ip1 = i + 1
         ds = s(ip1) - s(i)
!
         d = (f(i,jp1) - f(i,j))/dt
         a = d - dt*(2.0*f2(i,j) + f2(i,jp1))/6.0
         c = (f2(i,jp1) - f2(i,j))/(6.0*dt)
!
         d = (f(ip1,jp1) - f(ip1,j))/dt
         a1 = d - dt*(2.0*f2(ip1,j) + f2(ip1,jp1))/6.0
         c1 = (f2(ip1,jp1) - f2(ip1,j))/(6.0*dt)
!
         d = (f1(i,jp1) - f1(i,j))/dt
         a2 = d - dt*(2.0*f12(i,j) + f12(i,jp1))/6.0
         c2 = (f12(i,jp1) - f12(i,j))/(6.0*dt)
!
         d = (f1(ip1,jp1) - f1(ip1,j))/dt
         a3 = d - dt*(2.0*f12(ip1,j) + f12(ip1,jp1))/6.0
         c3 = (f12(ip1,jp1) - f12(ip1,j))/(6.0*dt)
!
210 dy = yy - t(j)
      if (jder .eq. 0) go to 220
      if (jder - 2) 230,240,250
!
220 fi = ((c*dy + 0.5*f2(i,j))*dy + a)*dy + f(i,j)
      fip1 = ((c1*dy + 0.5*f2(ip1,j))*dy + a1)*dy + f(ip1,j)
      dfi = ((c2*dy + 0.5*f12(i,j))*dy + a2)*dy + f1(i,j)
      dfip1 = ((c3*dy + 0.5*f12(ip1,j))*dy + a3)*dy + f1(ip1,j)
      go to 300
!
230 fi = (3.0*c*dy + f2(i,j))*dy + a
      fip1 = (3.0*c1*dy + f2(ip1,j))*dy + a1
      dfi = (3.0*c2*dy + f12(i,j))*dy + a2
      dfip1 = (3.0*c3*dy + f12(ip1,j))*dy + a3
      go to 300
!
240 fi = 6.0*c*dy + f2(i,j)
      fip1 = 6.0*c1*dy + f2(ip1,j)
      dfi = 6.0*c2*dy + f12(i,j)
      dfip1 = 6.0*c3*dy + f12(ip1,j)
      go to 300
!
250 fi = 6.0*c
      fip1 = 6.0*c1
      dfi = 6.0*c2
      dfip1 = 6.0*c3
!
!           Computation of the ider-TH derivative
!           at the point XX.
!
300 d = (fip1 - fi)/ds
      ax = d - ds*(2.0*dfi + dfip1)/6.0
      cx = (dfip1 - dfi)/(6.0*ds)
!
      dx = xx - s(i)
      if (ider .eq. 0) go to 310
      if (ider - 2) 320,330,340
!
310 z(k,l) = ((cx*dx + 0.5*dfi)*dx + ax)*dx + fi
      go to 350
320 z(k,l) = (3.0*cx*dx + dfi)*dx + ax
      go to 350
330 z(k,l) = 6.0*cx*dx + dfi
      go to 350
340 z(k,l) = 6.0*cx
!
350 continue
   jold = j
end do
return
!
!     Case when the results are zero.
!
400 do l = 1,my
   do k = 1,mx
      z(k,l) = 0.0
   end do
end do
return
end subroutine csrf

subroutine csrf2 (ider, jder, x, mx, y, my, z, kz, s, m, t, n, &
&f, kf, ddf)
implicit none
integer, intent(in) :: ider, jder, kf, kz, m, mx, my, n
!-----------------------------------------------------------------------
!
!             Evaluation or differentiation of a bicubic
!                        spline over a grid
!
!-----------------------------------------------------------------------
real, intent(in) :: x(mx), y(my)
real, intent(inout) :: z(kz,my)
real, intent(in) :: s(m), t(n), f(kf,n), ddf(m,n,3)
!
call csrf (ider, jder, x, mx, y, my, z, kz, s, m, t, n, f, kf, &
&ddf(1,1,2), m, ddf, m, ddf(1,1,3), m)
return
end subroutine csrf2

subroutine surf (m,n,x,y,z,iz,opt,zp,temp,sigma,ierr)
implicit none
integer :: i, ibak, ibakp1, im1, ip1, j, jbak, jbakp1, jm1, jp1, &
&key, l, mm1, mp1, nm1, np1, npi, npibak, npm, npmpj
real :: c1, c2, c3, del1, del2, deli, delx1, delx2, delxm, delxmm, &
&dely1, dely2, delyn, delynm, diag1, diag2, diagi, diagin, sdiag1, &
&sdiag2, sigmax, sigmay, t, zxy1ns, zxymns
!
integer, intent(in) :: m, n, iz
integer, intent(out) :: ierr
real, intent(in) :: x(m), y(n), z(iz,n), opt(*)
real, intent(inout) :: zp(m,n,*), temp(*)
real, intent(in) :: sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
!                               Modified by Alfred H. Morris
!                               naval surface weapons center
!                                          Dahlgren Virginia
!
! This subroutine determines the parameters necessary to
! compute an interpolatory surface passing through a rect-
! angular grid of functional values. The surface determined
! can be represented as the tensor product of splines under
! tension. The x- and y-partial derivatives around the
! boundary and the x-y-partial derivatives at the four
! corners may be specified or omitted. For actual mapping
! of points onto the surface it is necessary to call the
! FUNCTION surf2.
!
! On input--
!
!   m is the number of grid lines in the x-direction, I. E.
!   LINES PARALLEL TO THE y-AXIS (m .GE. 2).
!
!   n is the number of grid lines in the y-direction, I. E.
!   LINES PARALLEL TO THE x-AXIS (n .GE. 2).
!
!   x is an array of the m x-coordinates of the grid lines
!   in the x-direction. These should be strictly increasing.
!
!   y is an array of the n y-coordinates of the grid lines
!   in the y-direction. These should be strictly increasing.
!
!   z is an array of the m * n functional values at the grid
!   points, I. E. z(i,j) contains the functional value at
!   (x(i),y(j)) FOR i = 1,...,m AND j = 1,...,n.
!
!   iz is the row dimension of the matrix z used in the
!   CALLING PROGRAM (iz .GE. m).
!
!   Opt is an option vector. If no boundary conditions are
!   to be imposed on the surface then let opt be of length 1
!   AND SET opt(1)=0. OTHERWISE, SEE THE DESCRIPTION OF SURF
!   in the NSWC library manual.
!
!   zp is an array of at least 3*m*n locations.
!
!   Temp is an array of at least n+n+m locations which is
!   used for scratch storage.
!
!   sigma contains the tension factor. This value indicates
!   the curviness desired. If abs(sigma) is nearly zero
!   (E. G. .001) The resulting surface is approximately the
!   tensor product of cubic splines. If abs(sigma) is large
!   (E. G. 50.) The resulting surface is approximately
!   BI-linear. If sigma equals zero tensor products of
!   cubic splines result. A standard value for sigma is
!   approximately 1. In absolute value.
!
! On output--
!
!   zp contains the values of the XX-, YY-, and XXYY-partial
!   derivatives of the surface at the given nodes.
!
!   ierr contains an error flag,
!        = 0 FOR NORMAL RETURN,
!        = 1 IF n IS LESS THAN 2 OR m IS LESS THAN 2,
!        = 2 IF THE x-VALUES OR y-VALUES ARE NOT STRICTLY
!            increasing,
!        = 3 THE OPTION VECTOR HAS AN ERROR.
!
! This subroutine references package modules ceez, terms,
! and snhcsh.
!
!-----------------------------------------------------------
!
integer :: ind(8), loc(8), num(8)
data num(5)/1/, num(6)/1/, num(7)/1/, num(8)/1/
!
mm1 = m-1
mp1 = m+1
nm1 = n-1
np1 = n+1
npm = n+m
ierr = 0
if (n .le. 1 .or. m .le. 1) go to 46
if (y(n) .le. y(1)) go to 47
!
! Process the option vector
!
num(1) = n
num(2) = n
num(3) = m
num(4) = m
ind(1) = 0
ind(2) = 0
ind(3) = 0
ind(4) = 0
ind(5) = 0
ind(6) = 0
ind(7) = 0
ind(8) = 0
!
l = 1
100 key = opt(l)
if (key) 48,110,101
101 if (key .gt. 8) go to 48
ind(key) = 1
l = l+1
loc(key) = l
l = l + num(key)
go to 100
!
! Denormalize tension factor in y-direction
!
110 sigmay = abs(sigma)*float(n-1)/(y(n)-y(1))
!
! OBTAIN y-PARTIAL DERIVATIVES ALONG y = y(1)
!
if (ind(3) .eq. 0) go to 2
l = loc(3)
do 1 i = 1,m
  zp(i,1,1) = opt(l)
1 l = l+1
go to 5
2 dely1 = y(2)-y(1)
dely2 = dely1+dely1
if (n .gt. 2) dely2 = y(3)-y(1)
if (dely1 .le. 0. .or. dely2 .le. dely1) go to 47
call ceez (dely1,dely2,sigmay,c1,c2,c3,n)
do 3 i = 1,m
3 zp(i,1,1) = c1*z(i,1)+c2*z(i,2)
if (n .eq. 2) go to 5
do 4 i = 1,m
4 zp(i,1,1) = zp(i,1,1)+c3*z(i,3)
!
! OBTAIN y-PARTIAL DERIVATIVES ALONG y = y(n)
!
5 if (ind(4) .eq. 0) go to 7
l = loc(4)
do 6 i = 1,m
  npi = n+i
  temp(npi) = opt(l)
6 l = l+1
go to 10
7 delyn = y(n)-y(nm1)
delynm = delyn+delyn
if (n .gt. 2) delynm = y(n)-y(n-2)
if (delyn .le. 0. .or. delynm .le. delyn) go to 47
call ceez (-delyn,-delynm,sigmay,c1,c2,c3,n)
do 8 i = 1,m
  npi = n+i
8 temp(npi) = c1*z(i,n)+c2*z(i,nm1)
if (n .eq. 2) go to 10
do 9 i = 1,m
  npi = n+i
9 temp(npi) = temp(npi)+c3*z(i,n-2)
10 if (x(m) .le. x(1)) go to 47
!
! Denormalize tension factor in x-direction
!
sigmax = abs(sigma)*float(m-1)/(x(m)-x(1))
!
! OBTAIN x-PARTIAL DERIVATIVES ALONG x = x(1)
!
if (ind(1) .eq. 0) go to 12
l = loc(1)
do 11 j = 1,n
  zp(1,j,2) = opt(l)
11 l = l+1
if (ind(5)+ind(7) .eq. 2) go to 15
12 delx1 = x(2)-x(1)
delx2 = delx1+delx1
if (m .gt. 2) delx2 = x(3)-x(1)
if (delx1 .le. 0. .or. delx2 .le. delx1) go to 47
call ceez (delx1,delx2,sigmax,c1,c2,c3,m)
if (ind(1) .eq. 1) go to 15
do 13 j = 1,n
13 zp(1,j,2) = c1*z(1,j)+c2*z(2,j)
if (m .eq. 2) go to 15
do 14 j = 1,n
14 zp(1,j,2) = zp(1,j,2)+c3*z(3,j)
!
! Obtain x-y-partial derivative at (x(1),y(1))
!
15 if (ind(5) .eq. 0) go to 16
l = loc(5)
zp(1,1,3) = opt(l)
go to 17
16 zp(1,1,3) = c1*zp(1,1,1)+c2*zp(2,1,1)
if (m .gt. 2) zp(1,1,3) = zp(1,1,3)+c3*zp(3,1,1)
!
! Obtain x-y-partial derivative at (x(1),y(n))
!
17 if (ind(7) .eq. 0) go to 18
l = loc(7)
zxy1ns = opt(l)
go to 19
18 zxy1ns = c1*temp(n+1)+c2*temp(n+2)
if (m .gt. 2) zxy1ns = zxy1ns+c3*temp(n+3)
!
! OBTAIN x-PARTIAL DERIVATIVE ALONG x = x(m)
!
19 if (ind(2) .eq. 0) go to 21
l = loc(2)
do 20 j = 1,n
  npmpj = npm+j
  temp(npmpj) = opt(l)
20 l = l+1
21 if (ind(6)+ind(8) .eq. 2) go to 24
delxm = x(m)-x(mm1)
delxmm = delxm+delxm
if (m .gt. 2) delxmm = x(m)-x(m-2)
if (delxm .le. 0. .or. delxmm .le. delxm) go to 47
call ceez (-delxm,-delxmm,sigmax,c1,c2,c3,m)
if (ind(2) .eq. 1) go to 24
do 22 j = 1,n
  npmpj = npm+j
22 temp(npmpj) = c1*z(m,j)+c2*z(mm1,j)
if (m .eq. 2) go to 24
do 23 j = 1,n
  npmpj = npm+j
23 temp(npmpj) = temp(npmpj)+c3*z(m-2,j)
!
! Obtain x-y-partial derivative at (x(m),y(1))
!
24 if (ind(6) .eq. 0) go to 25
l = loc(6)
zp(m,1,3) = opt(l)
go to 26
25 zp(m,1,3) = c1*zp(m,1,1)+c2*zp(mm1,1,1)
if (m .gt. 2) zp(m,1,3) = zp(m,1,3)+c3*zp(m-2,1,1)
!
! Obtain x-y-partial derivative at (x(m),y(n))
!
26 if (ind(8) .eq. 0) go to 27
l = loc(8)
zxymns = opt(l)
go to 28
27 zxymns = c1*temp(npm)+c2*temp(npm-1)
if (m .gt. 2) zxymns = zxymns+c3*temp(npm-2)
!
! Set up right hand sides and tridiagonal system for y-grid
! perform forward elimination
!
28 del1 = y(2)-y(1)
if (del1 .le. 0.) go to 47
deli = 1./del1
do 29 i = 1,m
29 zp(i,2,1) = deli*(z(i,2)-z(i,1))
zp(1,2,3) = deli*(zp(1,2,2)-zp(1,1,2))
zp(m,2,3) = deli*(temp(npm+2)-temp(npm+1))
call terms (diag1,sdiag1,sigmay,del1)
diagi = 1./diag1
do 30 i = 1,m
30 zp(i,1,1) = diagi*(zp(i,2,1)-zp(i,1,1))
zp(1,1,3) = diagi*(zp(1,2,3)-zp(1,1,3))
zp(m,1,3) = diagi*(zp(m,2,3)-zp(m,1,3))
temp(1) = diagi*sdiag1
if (n .eq. 2) go to 34
do 33 j = 2,nm1
  jm1 = j-1
  jp1 = j+1
  npmpj = npm+j
  del2 = y(jp1)-y(j)
  if (del2 .le. 0.) go to 47
  deli = 1./del2
  do 31 i = 1,m
31 zp(i,jp1,1) = deli*(z(i,jp1)-z(i,j))
  zp(1,jp1,3) = deli*(zp(1,jp1,2)-zp(1,j,2))
  zp(m,jp1,3) = deli*(temp(npmpj+1)-temp(npmpj))
  call terms (diag2,sdiag2,sigmay,del2)
  diagin = 1./(diag1+diag2-sdiag1*temp(jm1))
  do 32 i = 1,m
32 zp(i,j,1) = diagin*(zp(i,jp1,1)-zp(i,j,1)- &
&sdiag1*zp(i,jm1,1))
  zp(1,j,3) = diagin*(zp(1,jp1,3)-zp(1,j,3)- &
&sdiag1*zp(1,jm1,3))
  zp(m,j,3) = diagin*(zp(m,jp1,3)-zp(m,j,3)- &
&sdiag1*zp(m,jm1,3))
  temp(j) = diagin*sdiag2
  diag1 = diag2
33 sdiag1 = sdiag2
34 diagin = 1./(diag1-sdiag1*temp(nm1))
do 35 i = 1,m
  npi = n+i
35 zp(i,n,1) = diagin*(temp(npi)-zp(i,n,1)- &
&sdiag1*zp(i,nm1,1))
zp(1,n,3) = diagin*(zxy1ns-zp(1,n,3)- &
&sdiag1*zp(1,nm1,3))
temp(n) = diagin*(zxymns-zp(m,n,3)- &
&sdiag1*zp(m,nm1,3))
!
! Perform back substitution
!
do 37 j = 2,n
  jbak = np1-j
  jbakp1 = jbak+1
  t = temp(jbak)
  do 36 i = 1,m
36 zp(i,jbak,1) = zp(i,jbak,1)-t*zp(i,jbakp1,1)
  zp(1,jbak,3) = zp(1,jbak,3)-t*zp(1,jbakp1,3)
37 temp(jbak) = zp(m,jbak,3)-t*temp(jbakp1)
!
! Set up right hand sides and tridiagonal system for x-grid
! perform forward elimination
!
del1 = x(2)-x(1)
if (del1 .le. 0.) go to 47
deli = 1./del1
do 38 j = 1,n
  zp(2,j,2) = deli*(z(2,j)-z(1,j))
38 zp(2,j,3) = deli*(zp(2,j,1)-zp(1,j,1))
call terms (diag1,sdiag1,sigmax,del1)
diagi = 1./diag1
do 39 j = 1,n
  zp(1,j,2) = diagi*(zp(2,j,2)-zp(1,j,2))
39 zp(1,j,3) = diagi*(zp(2,j,3)-zp(1,j,3))
temp(n+1) = diagi*sdiag1
if (m  .eq. 2) go to 43
do 42 i = 2,mm1
  im1 = i-1
  ip1 = i+1
  npi = n+i
  del2 = x(ip1)-x(i)
  if (del2 .le. 0.) go to 47
  deli = 1./del2
  do 40 j = 1,n
    zp(ip1,j,2) = deli*(z(ip1,j)-z(i,j))
40 zp(ip1,j,3) = deli*(zp(ip1,j,1)-zp(i,j,1))
  call terms (diag2,sdiag2,sigmax,del2)
  diagin = 1./(diag1+diag2-sdiag1*temp(npi-1))
  do 41 j = 1,n
    zp(i,j,2) = diagin*(zp(ip1,j,2)-zp(i,j,2)- &
&sdiag1*zp(im1,j,2))
41 zp(i,j,3) = diagin*(zp(ip1,j,3)-zp(i,j,3)- &
&sdiag1*zp(im1,j,3))
  temp(npi) = diagin*sdiag2
  diag1 = diag2
42 sdiag1 = sdiag2
43 diagin = 1./(diag1-sdiag1*temp(npm-1))
do 44 j = 1,n
  npmpj = npm+j
  zp(m,j,2) = diagin*(temp(npmpj)-zp(m,j,2)- &
&sdiag1*zp(mm1,j,2))
44 zp(m,j,3) = diagin*(temp(j)-zp(m,j,3)- &
&sdiag1*zp(mm1,j,3))
!
! Perform back substitution
!
do 45 i = 2,m
  ibak = mp1-i
  ibakp1 = ibak+1
  npibak = n+ibak
  t = temp(npibak)
  do 45 j = 1,n
    zp(ibak,j,2) = zp(ibak,j,2)-t*zp(ibakp1,j,2)
45 zp(ibak,j,3) = zp(ibak,j,3)-t*zp(ibakp1,j,3)
return
!
! Too few points
!
46 ierr = 1
return
!
! Points not strictly increasing
!
47 ierr = 2
return
!
! The option vector HAS an error
!
48 ierr = 3
return
end subroutine surf

function surf2 (xx,yy,m,n,x,y,z,iz,zp,sigma)
implicit none
integer :: i, im1, j, jm1
real :: coshp1, coshp2, del1, del2, delp1, delp2, dels, dummy, f1, &
&f2, fp1, fp2, sigmap, sigmax, sigmay, sinhm1, sinhm2, sinhms, &
&sinhp1, sinhp2, zi, zim1, zxxi, zxxim1
real :: hermnz
real :: surf2
real :: hermz
integer :: intrvl
!
integer, intent(in) :: m, n, iz
real, intent(in) :: xx, yy, x(m), y(n)
real :: z(iz,n), zp(m,n,*)
real, intent(in) :: sigma
!
!                      From the spline under tension package
!                       coded by A. K. Cline and R. J. Renka
!                            department of computer sciences
!                              University of Texas at Austin
!
! This function interpolates a surface at a given coordinate
! pair using A BI-spline under tension. The subroutine surf1
! should be called earlier to determine certain necessary
! parameters.
!
! On input--
!
!   xx and yy contain the x- and y-coordinates of the point
!   to be mapped onto the interpolating surface.
!
!   m and n contain the number of grid lines in the x- and
!   y-directions, respectively, of the rectangular grid
!   which specified the surface.
!
!   x and y are arrays containing the x- and y-grid values,
!   respectively, each in increasing order.
!
!   z is a matrix containing the m * n functional values
!   corresponding to the grid values (I. E. z(i,j) is the
!   SURFACE VALUE AT THE POINT (x(i),y(j)) FOR i = 1,...,m
!   AND j = 1,...,n).
!
!   iz contains the row dimension of the array z as declared
!   in the calling program.
!
!   zp is an array of 3*m*n locations stored with the
!   various surface derivative information determined by
!   SURF1.
!
! And
!
!   sigma contains the tension factor (its sign is ignored).
!
! The parameters m, n, x, y, z, iz, zp, and sigma should be
! input unaltered from the output of SURF1.
!
! On output--
!
!   surf2 contains the interpolated surface value.
!
! None of the input parameters are altered.
!
! This function references package modules intrvl and
! snhcsh.
!
!-----------------------------------------------------------
!
! Inline one dimensional cubic spline interpolation
!
hermz (f1,f2,fp1,fp2) = (f2*del1+f1*del2)/dels-del1* &
&del2*(fp2*(del1+dels)+ &
&fp1*(del2+dels))/ &
&(6.*dels)
!
! Inline one dimensional spline under tension interpolation
!
hermnz (f1,f2,fp1,fp2,sigmap) = (f2*del1+f1*del2)/dels &
&+(fp2*(sinhm1*del2-del1*(2.*(coshp1+1.)* &
&sinhp2+sigmap*coshp1*del2)) &
&+fp1*(sinhm2*del1-del2*(2.*(coshp2+1.)* &
&sinhp1+sigmap*coshp2*del1)) &
&)/(sigmap*sigmap*dels*(sinhms+sigmap*dels))
!
! Denormalize tension factor in x and y direction
!
sigmax = abs(sigma)*float(m-1)/(x(m)-x(1))
sigmay = abs(sigma)*float(n-1)/(y(n)-y(1))
!
! Determine y interval
!
jm1 = intrvl (yy,y,n)
j = jm1+1
!
! Determine x interval
!
im1 = intrvl (xx,x,m)
i = im1+1
del1 = yy-y(jm1)
del2 = y(j)-yy
dels = y(j)-y(jm1)
if (sigmay .ne. 0.) go to 1
!
! Perform four interpolations in y-direction
!
zim1 = hermz(z(i-1,j-1),z(i-1,j),zp(i-1,j-1,1), &
&zp(i-1,j,1))
zi = hermz(z(i,j-1),z(i,j),zp(i,j-1,1),zp(i,j,1))
zxxim1 = hermz(zp(i-1,j-1,2),zp(i-1,j,2), &
&zp(i-1,j-1,3),zp(i-1,j,3))
zxxi = hermz(zp(i,j-1,2),zp(i,j,2), &
&zp(i,j-1,3),zp(i,j,3))
go to 2
1 delp1 = (del1+dels)/2.
delp2 = (del2+dels)/2.
call snhcsh (sinhm1,dummy,sigmay*del1,-1)
call snhcsh (sinhm2,dummy,sigmay*del2,-1)
call snhcsh (sinhms,dummy,sigmay*dels,-1)
call snhcsh (sinhp1,dummy,sigmay*del1/2.,-1)
call snhcsh (sinhp2,dummy,sigmay*del2/2.,-1)
call snhcsh (dummy,coshp1,sigmay*delp1,1)
call snhcsh (dummy,coshp2,sigmay*delp2,1)
zim1 = hermnz(z(i-1,j-1),z(i-1,j),zp(i-1,j-1,1), &
&zp(i-1,j,1),sigmay)
zi = hermnz(z(i,j-1),z(i,j),zp(i,j-1,1),zp(i,j,1), &
&sigmay)
zxxim1 = hermnz(zp(i-1,j-1,2),zp(i-1,j,2), &
&zp(i-1,j-1,3),zp(i-1,j,3),sigmay)
zxxi = hermnz(zp(i,j-1,2),zp(i,j,2), &
&zp(i,j-1,3),zp(i,j,3),sigmay)
!
! Perform final interpolation in x-direction
!
2 del1 = xx-x(im1)
del2 = x(i)-xx
dels = x(i)-x(im1)
if (sigmax .ne. 0.) go to 3
surf2 = hermz(zim1,zi,zxxim1,zxxi)
return
3 delp1 = (del1+dels)/2.
delp2 = (del2+dels)/2.
call snhcsh (sinhm1,dummy,sigmax*del1,-1)
call snhcsh (sinhm2,dummy,sigmax*del2,-1)
call snhcsh (sinhms,dummy,sigmax*dels,-1)
call snhcsh (sinhp1,dummy,sigmax*del1/2.,-1)
call snhcsh (sinhp2,dummy,sigmax*del2/2.,-1)
call snhcsh (dummy,coshp1,sigmax*delp1,1)
call snhcsh (dummy,coshp2,sigmax*delp2,1)
surf2 = hermnz(zim1,zi,zxxim1,zxxi,sigmax)
return
end function surf2

subroutine nsurf2 (dxmin,dxmax,md,dymin,dymax,nd,dz, &
&idz,m,n,x,y,z,iz,zp,work,sigma)
implicit none
integer :: i, ii, im1, j, jj, jm1, lasti, lastj
real :: c1, c2, c3, c4, coshp1, coshp2, del1, del2, delp1, delp2, &
&dels, deltdx, deltdy, dummy, sigmax, sigmay, sinhm1, sinhm2, &
&sinhms, sinhp1, sinhp2, temp, xii, yjj, zi, zim1, zxxi, zxxim1
!
integer, intent(in) :: md, nd, idz, m, n, iz
real, intent(in) :: dxmin, dxmax, dymin, dymax
real, intent(inout) :: dz(idz,nd)
real, intent(in) :: x(m), y(n), z(iz,n), zp(m,n,*)
real, intent(inout) :: work(4,md)
real, intent(in) :: sigma
!
!                      From the spline under tension package
!                                 coded by alan Kaylor Cline
!                            department of computer sciences
!                              University of Texas at Austin
!
! This subroutine maps values onto a surface at every point
! of a grid equally spaced in both x and y coordinates. The
! surface interpolation is performed using A BI-spline
! under tension. The subroutine surf1 or NSURF1 should be
! called earlier to determine certain necessary parameters.
!
! On input--
!
!   dxmin and dxmax contain the lower and upper limits,
!   respectively, of the x-coordinates of the second grid.
!
!   md contains the number of grid lines in the x direction
!   OF THE SECOND GRID (md .GE. 1).
!
!   dymin and dymax contain the lower and upper limits,
!   respectively, of the y-coordinates of the second grid.
!
!   nd contains the number of grid lines in the y direction
!   OF THE SECOND GRID (nd .GE. 1).
!
!   idz contains the row dimension of the array dz as
!   declared in the calling program.
!
!   m and n contain the number of grid lines in the x- and
!   y-directions, respectively, of the rectangular grid
!   which specified the surface.
!
!   x and y are arrays containing the x- and y-grid values,
!   respectively, each in increasing order.
!
!   z is a matrix containing the m * n functional values
!   corresponding to the grid values (I. E. z(i,j) is the
!   SURFACE VALUE AT THE POINT (x(i),y(j)) FOR i = 1,...,m
!   AND j = 1,...,n).
!
!   iz contains the row dimension of the array z as declared
!   in the calling program.
!
!   zp is an array of 3*m*n locations stored with the
!   various surface derivative information determined by
!   SURF1.
!
!   Work is an array of 4*md locations to be used internally
!   for workspace.
!
! And
!
!   sigma contains the tension factor (its sign is ignored).
!
! The parameters m, n, x, y, z, iz, zp, and sigma should be
! input unaltered from the output of SURF1 or NSURF1.
!
! On output--
!
!   dz contains the md by nd array of surface values
!   interpolated at the points of the second grid.
!
! None of the input parameters are altered.
!
! This function references package module snhcsh.
!
!-----------------------------------------------------------
!
! Denormalize tension factor in x and y direction
!
sigmax = abs(sigma)*float(m-1)/(x(m)-x(1))
sigmay = abs(sigma)*float(n-1)/(y(n)-y(1))
!
! Find intervals of second x grid with respect to original x
! grid
!
deltdx = 0.
if (md .ge. 2) deltdx = (dxmax-dxmin)/float(md-1)
lasti = 1
do 3 ii = 1,md
  xii = dxmin+float(ii-1)*deltdx
  i = lasti
1 i = i+1
  if (xii .gt. x(i) .and. i .lt. m) go to 1
  im1 = i-1
  lasti = im1
  del1 = xii-x(im1)
  del2 = x(i)-xii
  dels = x(i)-x(im1)
  work(1,ii) = del2/dels
  work(2,ii) = del1/dels
  if (sigmax .ne. 0.) go to 2
  temp = -del1*del2/(6.*dels)
  work(3,ii) = temp*(del2+dels)
  work(4,ii) = temp*(del1+dels)
  go to 3
2 delp1 = (del1+dels)/2.
  delp2 = (del2+dels)/2.
  call snhcsh (sinhm1,dummy,sigmax*del1,-1)
  call snhcsh (sinhm2,dummy,sigmax*del2,-1)
  call snhcsh (sinhms,dummy,sigmax*dels,-1)
  call snhcsh (sinhp1,dummy,sigmax*del1/2.,-1)
  call snhcsh (sinhp2,dummy,sigmax*del2/2.,-1)
  call snhcsh (dummy,coshp1,sigmax*delp1,1)
  call snhcsh (dummy,coshp2,sigmax*delp2,1)
  temp = sigmax*sigmax*dels*(sinhms+sigmax*dels)
  work(3,ii) = (sinhm2*del1-del2*(2.*(coshp2+1.)* &
&sinhp1+sigmax*coshp2*del1))/temp
  work(4,ii) = (sinhm1*del2-del1*(2.*(coshp1+1.)* &
&sinhp2+sigmax*coshp1*del2))/temp
3 continue
!
! Find intervals of second y grid with respect to original y
! grid and perform intrpolation
!
deltdy = 0.
if (nd .ge. 2) deltdy = (dymax-dymin)/float(nd-1)
lastj = 1
do 8 jj = 1,nd
  yjj = dymin+float(jj-1)*deltdy
  j = lastj
4 j = j+1
  if (yjj .gt. y(j) .and. j .lt. n) go to 4
  jm1 = j-1
  lastj = jm1
  del1 = yjj-y(jm1)
  del2 = y(j)-yjj
  dels = y(j)-y(jm1)
  c1 = del2/dels
  c2 = del1/dels
  if (sigmay .ne. 0.) go to 5
  temp = -del1*del2/(6.*dels)
  c3 = temp*(del2+dels)
  c4 = temp*(del1+dels)
  go to 6
5 delp1 = (del1+dels)/2.
  delp2 = (del2+dels)/2.
  call snhcsh (sinhm1,dummy,sigmay*del1,-1)
  call snhcsh (sinhm2,dummy,sigmay*del2,-1)
  call snhcsh (sinhms,dummy,sigmay*dels,-1)
  call snhcsh (sinhp1,dummy,sigmay*del1/2.,-1)
  call snhcsh (sinhp2,dummy,sigmay*del2/2.,-1)
  call snhcsh (dummy,coshp1,sigmay*delp1,1)
  call snhcsh (dummy,coshp2,sigmay*delp2,1)
  temp = sigmay*sigmay*dels*(sinhms+sigmay*dels)
  c3 = (sinhm2*del1-del2*(2.*(coshp2+1.)* &
&sinhp1+sigmay*coshp2*del1))/temp
  c4 = (sinhm1*del2-del1*(2.*(coshp1+1.)* &
&sinhp2+sigmay*coshp1*del2))/temp
6 lasti = 0
  do 8 ii = 1,md
    xii = dxmin+float(ii-1)*deltdx
    i = max0 (1, lasti)
7 i = i+1
    if (xii .gt. x(i) .and. i .lt. m) go to 7
    im1 = i-1
    if (im1 .eq. lasti) go to 8
    lasti = im1
    zim1 = c1*z(im1,jm1)+c2*z(im1,j) &
&+c3*zp(im1,jm1,1)+c4*zp(im1,j,1)
    zi = c1*z(i,jm1)+c2*z(i,j) &
&+c3*zp(i,jm1,1)+c4*zp(i,j,1)
    zxxim1 = c1*zp(im1,jm1,2)+c2*zp(im1,j,2) &
&+c3*zp(im1,jm1,3)+c4*zp(im1,j,3)
    zxxi = c1*zp(i,jm1,2)+c2*zp(i,j,2) &
&+c3*zp(i,jm1,3)+c4*zp(i,j,3)
8 dz(ii,jj) = work(1,ii)*zim1+work(2,ii)*zi &
&+work(3,ii)*zxxim1+work(4,ii)*zxxi
return
end subroutine nsurf2

subroutine bstrp2 (x, y, z, kz, tx, nx, kx, ty, ny, ky, &
&a, ka, wk, l, iflag)
implicit none
integer, intent(inout) :: iflag
integer, intent(in) :: ka, kx, ky, kz, l, nx, ny
integer :: iw, m
!-----------------------------------------------------------------------
!
!         Piecewise polynomial interpolation in two variables
!
!                          -----------------
!
!     The piecewise polynomials considered are tensor products of
!     B-splines, having the form
!
!                          nx   ny
!              F(x,y)  =  SUM  SUM  A   U (x) V (y)
!                         I=1  J=1   IJ  I     J
!
!     Where U  and V  are one-dimensional B-spline basis functions.
!            I      J
!
!-----------------------------------------------------------------------
!     real tx(nx + kx), ty(ny + ky)
!     real wk(l)  where l = nx*ny + max(2*kx*nx, 2*ky*ny)
!-------------------------
real, intent(in) :: x(nx), y(ny), z(kz,ny)
real, intent(in) :: tx(*), ty(*)
real, intent(inout) :: a(ka,ny), wk(l)
!
m = nx*ny + 2*max0(kx*nx, ky*ny)
if (l .lt. m) go to 120
!
!     Compute the coefficients
!
iw = nx*ny + 1
call bstrp1 (x, z, kz, nx, ny, tx, kx, wk, ny, wk(iw), iflag)
if (iflag .ne. 0) go to 100
call bstrp1 (y, wk, ny, ny, nx, ty, ky, a, ka, wk(iw), iflag)
if (iflag .ne. 0) go to 110
return
!
!     Error return
!
100 iflag = 1
return
110 iflag = 2
return
120 iflag = 3
return
end subroutine bstrp2

subroutine bstrp1 (x, z, kz, m, n, t, k, a, ka, work, iflag)
implicit none
integer, intent(out) :: iflag
integer, intent(in) :: k, ka, kz, m, n
integer :: i, j, mp1
!-------------------------------------------------------------------
!     bstrp1 computes B-spline interpolation coefficients for
!     n sets of data stored in the columns of the array z. the
!     coefficients are stored in the rows of A.
!
!     IT IS ASSUMED THAT kz .GE. m AND ka .GE. n.
!-------------------------------------------------------------------
!     real t(m + k), work(2*k*m)
!-----------------------
real, intent(in) :: x(m), z(kz,n), t(*)
real, intent(inout) :: a(ka,m), work(*)
!
!     First data set
!
iflag = 1
mp1 = m + 1
call bstrp (x, z, t, m, k, work(1), work(mp1), iflag)
if (iflag .ne. 0) return
!
do i = 1,m
   a(1,i) = work(i)
end do
if (n .eq. 1) return
!
!     Remaining data sets
!
do j = 2,n
   call bstrp (x, z(1,j), t, m, k, work(1), work(mp1), iflag)
   do i = 1,m
      a(j,i) = work(i)
   end do
end do
return
end subroutine bstrp1

subroutine bslsq2 (x, wx, mx, y, wy, my, z, kz, tx, nx, kx, &
&ty, ny, ky, a, ka, wk, l, iflag)
implicit none
integer, intent(inout) :: iflag
integer, intent(in) :: ka, kx, ky, kz, l, mx, my, nx, ny
integer :: ierr, iq, iw, m
!-----------------------------------------------------------------------
!
!             Weighted least squares fitting of piecewise
!                    polynomials in two variables
!
!                          ----------------
!
!     The piecewise polynomials considered are tensor products of
!     B-splines, having the form
!
!                          nx   ny
!              F(x,y)  =  SUM  SUM  A   U (x) V (y)
!                         I=1  J=1   IJ  I     J
!
!     Where U  and V  are one-dimensional B-spline basis functions.
!            I      J
!
!-----------------------------------------------------------------------
!     real tx(nx + kx), ty(ny + ky)
!     real wk(l)  where l = nx*my + max((kx+1)*nx,(ky+1)*ny)
!-------------------------
real, intent(in) :: x(mx), wx(mx), y(my), wy(my), z(kz,my)
real, intent(in) :: tx(*), ty(*)
real, intent(inout) :: a(ka,ny), wk(l)
!
m = nx*my + max0((kx + 1)*nx,(ky + 1)*ny)
if (l .lt. m) go to 120
!
!     Compute the coefficients
!
iw = nx*my + 1
iq = iw + nx
call bslsq1 (x, wx, mx, z, kz, my, tx, nx, kx, &
&wk, my, wk(iw), wk(iq), ierr)
if (ierr .lt. 0) go to 100
!
iq = iw + ny
call bslsq1 (y, wy, my, wk, my, nx, ty, ny, ky, &
&a, ka, wk(iw), wk(iq), iflag)
if (iflag .lt. 0) go to 110
iflag = max0(ierr,iflag)
return
!
!     Error return
!
100 iflag = -1
return
110 iflag = -2
return
120 iflag = -3
wk(1) = m
return
end subroutine bslsq2

subroutine bslsq1 (tau, wgt, ntau, z, kz, m, t, n, k, &
&a, ka, wk, q, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: k, ka, kz, m, n, ntau
integer :: i, j, jj, l, left, leftmk, mm
real :: dw
!-----------------------------------------------------------------------
!
!     bslsq1 produces the B-spline coefficients a(j,1),...,a(j,n)
!     of the piecewise polynomial P(X) of order k with knots t(i)
!     (i = 1,...,n+k) WHICH MINIMIZES
!
!              sum (wgt(l)*(P(tau(l)) - z(l,j))**2)
!                 l
!
!     FOR j = 1,...,m.
!
!     Input ...
!
!       tau   ARRAY OF LENGTH ntau CONTAINING DATA POINT ABSCISSAE.
!       wgt   ARRAY OF LENGTH ntau CONTAINING THE WEIGHTS.
!       ntau  NUMBER OF DATA POINTS TO BE FITTED (ntau .GE. n).
!       z     MATRIX CONTAINING m SETS OF ORDINATES TO BE FITTED.
!             Each set of ntau ordinates is a column of z.
!       kz    NUMBER OF ROWS OF z IN THE CALLING PROGRAM.
!             IT IS ASSUMED THAT kz .GE. ntau.
!       m     NUMBER OF SETS OF ORDINATES TO BE FITTED.
!       t     KNOT SEQUENCE OF LENGTH n+k.
!       n     DIMENSION OF THE PIECEWISE POLYNOMIAL SPACE.
!       k     ORDER OF THE B-SPLINES.
!       ka    NUMBER OF ROWS OF A IN THE CALLING PROGRAM.
!             IT IS ASSUMED THAT ka .GE. m.
!
!     Output ...
!
!       A     MATRIX CONTAINING THE m SETS OF B-SPLINE COEFFICIENTS
!             of the L2 approximations. Each set of n coefficients
!             is a row of A.
!
!       ierr  integer reporting the status of the results ...
!
!             0  The coefficient matrix is nonsigular. The
!                unique least squares solution was obtained.
!             1  The coefficient matrix is singular. A
!                least squares solution was obtained.
!            -1  Input errors were detected.
!
!-----------------------------------------------------------------------
real, intent(in) :: tau(ntau), wgt(ntau), z(kz,m)
real, intent(in) :: t(*)
real, intent(inout) :: a(ka,n), wk(n), q(k,n)
!
if (ntau .lt. max0(2,k)) go to 100
if (tau(1) .lt. t(k) .or. tau(ntau) .gt. t(n + 1)) go to 100
!
do i = 2,ntau
   if (tau(i - 1) .gt. tau(i)) go to 100
end do
!
do j = 1,n
   do i = 1,m
      a(i,j) = 0.0
   end do
end do
!
do j = 1,n
   do i = 1,k
      q(i,j) = 0.0
   end do
end do
!
left = k
do l = 1,ntau
!
!        *** FIND THE INDEX LEFT SUCH THAT
!            t(left) .LE. tau(l) .LT. t(left+1)
!
40 if (left .eq. n) go to 50
      if (tau(l) .lt. t(left+1)) go to 50
      left = left + 1
      go to 40
!
50 jj = 0
   call bspvb (t, k, k, jj, tau(l), left, wk)
!
   leftmk = left - k
   do mm = 1,k
      dw = wk(mm)*wgt(l)
      j = leftmk + mm
      do i = 1,m
         a(i,j) = dw*z(l,i) + a(i,j)
      end do
      i = 1
      do jj = mm,k
         q(i,j) = wk(jj)*dw + q(i,j)
         i = i + 1
      end do
   end do
end do
!
!        Solve the normal equations
!
call bchfac (q, k, n, wk, ierr)
call bchsv1 (q, k, n, a, ka, m)
return
!
!             Error return
!
100 ierr = -1
return
end subroutine bslsq1

subroutine bchsv1 (w, nb, n, b, kb, m)
implicit none
integer, intent(in) :: kb, m, n, nb
integer :: i, j, jmax, jpk, k, nbm1
real :: t
!-----------------------------------------------------------------------
!
!     bchsv1 SOLVES m LINEAR SYSTEMS C*X = b  (i = 1,...,m), WHERE
!                                       i   i
!     each b  is a vector stored in the i-TH row of a matrix b.
!           i
!                       ------------------
!
!     Input ...
!
!        n   THE ORDER OF THE MATRIX C
!        nb  the bandwidth of C
!        w   THE CHOLESKY FACTORIZATION OF THE BANDED SYMMETRIC
!            positive definite matrix C obtained by the routine
!            bchfac.
!        b   MATRIX WHOSE ROWS ARE THE VECTORS TO BE SOLVED FOR
!            in the m linear systems of equations.
!        kb  the number of rows of b specified in the calling
!            PROGRAM. IT IS ASSUMED THAT kb .GE. m.
!        m   NUMBER OF LINEAR SYSTEMS TO BE SOLVED.
!
!     Output ...
!
!        b   MATRIX WHOSE ROWS ARE THE SOLUTIONS X  OF THE m
!            LINEAR SYSTEMS OF EQUATIONS.         i
!
!                                       t
!     NOTE.  THE FACTORIZATION C = L*D*L  IS USED, WHERE L IS A
!     unit lower triangular matrix and D a diagonal matrix.
!
!-----------------------------------------------------------------------
real, intent(in) :: w(nb,n)
real, intent(inout) :: b(kb,n)
!
if (n .gt. 1) go to 20
do i = 1,m
   b(i,1) = b(i,1)*w(1,1)
end do
return
!
!     FORWARD SUBSTITUTION. SOLVE L*Y = b FOR Y AND STORE Y IN b.
!
20 nbm1 = nb - 1
do 40 k = 1,n
   jmax = min0(nbm1,n - k)
   if (jmax .lt. 1) go to 40
   do j = 1,jmax
      jpk = j + k
      t = w(j + 1,k)
      do i = 1,m
         b(i,jpk) = b(i,jpk) - t*b(i,k)
      end do
   end do
40 continue
!                              t     -1
!     BACKSUBSTITUTION. SOLVE L X = D  Y  FOR X AND STORE X IN b.
!
k = n
50 t = w(1,k)
   do i = 1,m
      b(i,k) = t*b(i,k)
   end do
   jmax = min0(nbm1,n - k)
   if (jmax .lt. 1) go to 80
   do j = 1,jmax
      jpk = j + k
      t = w(j + 1,k)
      do i = 1,m
         b(i,k) = b(i,k) - t*b(i,jpk)
      end do
   end do
80 k = k - 1
   if (k .gt. 0) go to 50
return
end subroutine bchsv1

subroutine bval2 (a, ka, tx, nx, kx, ty, ny, ky, x0, y0, &
&idx, idy, f, wk)
implicit none
integer, intent(in) :: idx, idy, ka, kx, ky, nx, ny
real, intent(out) :: f
real, intent(in) :: x0, y0
integer :: i, iw, j, l, m
integer :: intrvl
!-----------------------------------------------------------------------
!
!                Evaluation and partial differentiation
!                      of a piecewise polynomial
!
!                            nx   ny
!                f(X,Y)  =  SUM  SUM  A   U (X) V (Y)
!                           i=1  j=1   IJ  i     j
!
!     Where U  and V  are one-dimensional B-spline basis functions.
!            i      j
!-----------------------------------------------------------------------
!     real tx(nx + kx), ty(ny + ky), wk(ky + 3*max(kx,ky))
!-----------------------------
real, intent(in) :: a(ka,ny), tx(*), ty(*)
real, intent(inout) :: wk(*)
!
f = 0.0
m = nx + kx
if (x0 .lt. tx(1) .or. x0 .gt. tx(m)) return
m = ny + ky
if (y0 .lt. ty(1) .or. y0 .gt. ty(m)) return
!
iw = ky + 1
j = intrvl(y0, ty, m)
if (j .gt. ky) go to 20
!
!     CASE WHEN  j .LE. ky
!
do l = 1,j
   call bval (tx, a(1,l), nx, kx, x0, idx, wk(l), wk(iw))
end do
call bval (ty, wk(1), j, ky, y0, idy, f, wk(iw))
return
!
!     CASE WHEN  j .GT. ky
!
20 l = j - ky
do i = 1,ky
   l = l + 1
   call bval (tx, a(1,l), nx, kx, x0, idx, wk(i), wk(iw))
end do
l = j - ky + 1
call bval (ty(l), wk(1), ky, ky, y0, idy, f, wk(iw))
return
end subroutine bval2

subroutine trmesh (n,x,y, iadj,iend,ier)
implicit none
integer, intent(in) :: n
integer, intent(inout) :: iadj(*), iend(n)
integer, intent(out) :: ier
real :: x(n), y(n)
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   This routine creates a thiessen triangulation of n
! arbitrarily spaced points in the plane referred to as
! nodes.  The triangulation is optimal in the sense that it
! is as nearly equiangular as possible.  trmesh is part of
! an interpolation package which also provides subroutines
! to reorder the nodes, add a new node, delete an arc, plot
! the mesh, and print the data structure.
!   Unless the nodes are already ordered in some reasonable
! fashion, they should be reordered by subroutine reordr for
! increased efficiency before calling trmesh.
!
! INPUT PARAMETERS -     n - NUMBER OF NODES IN THE MESH.
!                            n .GE. 3.
!
!                      x,y - n-vectors of coordinates.
!                            (x(I),y(I)) defines node I.
!
!                     iadj - VECTOR OF LENGTH .GE. 6*n-9.
!
!                     iend - VECTOR OF LENGTH .GE. n.
!
! n, x, and y are not altered by this routine.
!
! Output parameters - iadj - adjacency lists of neighbors in
!                            counterclockwise order.  The
!                            list for node I+1 follows that
!                            for node I where x and y define
!                            the order.  The value 0 denotes
!                            the boundary (or a pseudo-node
!                            at infinity) and is always the
!                            last neighbor of a boundary
!                            node.  iadj is unchanged if ier
!                            .NE. 0.
!
!                     iend - pointers to the ends of
!                            adjacency lists (sets of
!                            neighbors) in iadj.  The
!                            neighbors of node 1 begin in
!                            iadj(1).  FOR k .GT. 1, THE
!                            neighbors of node k begin in
!                            iadj(iend(k-1)+1) and k has
!                            iend(k) - iend(k-1) NEIGHBORS
!                            including (possibly) the
!                            BOUNDARY.  iadj(iend(k)) .EQ. 0
!                            IFF node k is on the boundary.
!                            iend IS UNCHANGED IF ier = 1.
!                            IF ier = 2 iend CONTAINS THE
!                            indices of a sequence of n
!                            nodes ordered from left to
!                            right where left and right are
!                            defined by assuming node 1 is
!                            to the left of node 2.
!
!                      ier - error indicator
!                            ier = 0 IF NO ERRORS WERE
!                                    encountered.
!                            ier = 1 IF n .LT. 3.
!                            ier = 2 IF n .GE. 3 AND ALL
!                                    nodes are collinear.
!
! Modules referenced by trmesh - shiftd, adnode, trfind,
!                                intadd, bdyadd, swptst,
!                                swapd, tindx
!
!***********************************************************
!
integer :: nn, k, km1, nl, nr, ind, indx, n0, itemp, ierr, km1d2, &
&kmi, i, kmin
real :: xl, yl, xr, yr, dxr, dyr, xk, yk, dxk, dyk, cprod, sprod
!
! Local parameters -
!
! nn =          LOCAL COPY OF n
! k =           NODE (INDEX) TO BE INSERTED INTO iend
! km1 =         k-1 - (VARIABLE) LENGTH OF iend
! nl,nr =       iend(1), iend(km1) -- LEFTMOST AND RIGHTMOST
!                 nodes in iend as viewed from the right of
!                 1-2 when iend contains the initial ordered
!                 set of nodal indices
! xl,yl,xr,yr = x AND y COORDINATES OF nl AND nr
! dxr,dyr =     xr-xl, yr-yl
! xk,yk =       x AND y COORDINATES OF NODE k
! dxk,dyk =     xk-xl, yk-yl
! cprod =       VECTOR CROSS PRODUCT OF nl-nr AND nl-k --
!                 used to determine the position of node k
!                 with respect to the line defined by the
!                 nodes in iend
! sprod =       SCALAR PRODUCT USED TO DETERMINE THE
!                 interval containing node k when k is on
!                 the line defined by the nodes in iend
! IND,indx =    INDICES FOR iend AND iadj, RESPECTIVELY
! n0,itemp =    TEMPORARY NODES (INDICES)
! ierr =        DUMMY PARAMETER FOR CALL TO adnode
! km1d2,KMI,I = km1/2, k-I, DO-LOOP INDEX -- USED IN iend
!                 reordering loop
! KMIN =        FIRST NODE INDEX SENT TO adnode
!
nn = n
ier = 1
if (nn .lt. 3) return
ier = 0
!
! Initialize iend, nl, nr, and k
!
iend(1) = 1
iend(2) = 2
xl = x(1)
yl = y(1)
xr = x(2)
yr = y(2)
k = 2
!
! Begin loop on nodes 3,4,...
!
1 dxr = xr-xl
dyr = yr-yl
!
! Next loop begins here if nl and nr are unchanged
!
2 if (k .eq. nn) go to 13
km1 = k
k = km1 + 1
xk = x(k)
yk = y(k)
dxk = xk-xl
dyk = yk-yl
cprod = dxr*dyk - dxk*dyr
if (cprod .gt. 0.) go to 6
if (cprod .lt. 0.) go to 8
!
! Node k lies on the line containing nodes 1,2,...,k-1.
!   Set sprod to (nl-nr,nl-k).
!
sprod = dxr*dxk + dyr*dyk
if (sprod .gt. 0.) go to 3
!
! Node k is to the left of nl.  Insert k as the first
!   (leftmost) node in iend and set nl to k.
!
call shiftd(1,km1,1, iend )
iend(1) = k
xl = xk
yl = yk
go to 1
!
! Node k is to the right of nl.  Find the leftmost node
!   n0 which lies to the right of k.
!   Set sprod to (n0-nl,n0-k).
!
3 do 4 ind = 2,km1
  n0 = iend(ind)
  sprod = (xl-x(n0))*(xk-x(n0)) + &
&(yl-y(n0))*(yk-y(n0))
  if (sprod .ge. 0.) go to 5
4 continue
!
! Node k is to the right of nr.  Insert k as the last
!   (rightmost) node in iend and set nr to k.
!
iend(k) = k
xr = xk
yr = yk
go to 1
!
! Node k lies between iend(ind-1) and iend(ind).  Insert k
!   IN iend.
!
5 call shiftd(ind,km1,1, iend )
iend(ind) = k
go to 2
!
! Node k is to the left of nl-nr.  Reorder iend so that nl
!   is the leftmost node as viewed from k.
!
6 km1d2 = km1/2
do i = 1,km1d2
  kmi = k-i
  itemp = iend(i)
  iend(i) = iend(kmi)
  iend(kmi) = itemp
  end do
!
! Node k is to the right of nl-nr.  Create a triangulation
!   consisting of nodes 1,2,...,k.
!
8 nl = iend(1)
nr = iend(km1)
!
! Create the adjacency lists for the first k-1 nodes.
!   Insert neighbors in reverse order.  Each node has four
!   neighbors except nl and nr which have three.
!
do 9 ind = 1,km1
  n0 = iend(ind)
  indx = 4*n0
  if (n0 .ge. nl) indx = indx-1
  if (n0 .ge. nr) indx = indx-1
  iadj(indx) = 0
  indx = indx-1
  if (ind .lt. km1) iadj(indx) = iend(ind+1)
  if (ind .lt. km1) indx = indx-1
  iadj(indx) = k
  if (ind .eq. 1) go to 9
  iadj(indx-1) = iend(ind-1)
9 continue
!
! Create the adjacency list for node k
!
indx = 5*km1 - 1
iadj(indx) = 0
do ind = 1,km1
  indx = indx-1
  iadj(indx) = iend(ind)
  end do
!
! Replace iend elements with pointers to iadj
!
indx = 0
do ind = 1,km1
  indx = indx + 4
  if (ind .eq. nl  .or.  ind .eq. nr) indx = indx-1
  iend(ind) = indx
  end do
indx = indx + k
iend(k) = indx
!
! Add the remaining nodes to the triangulation
!
if (k .eq. nn) return
kmin = k+1
do k = kmin,nn
  call adnode(k,x,y, iadj,iend, ierr)
  end do
return
!
! All nodes are collinear
!
13 ier = 2
return
end subroutine trmesh

subroutine adnode (kk,x,y, iadj,iend, ier)
implicit none
integer, intent(in) :: kk
integer, intent(inout) :: iadj(*), iend(kk)
integer, intent(out) :: ier
real :: x(kk), y(kk)
logical :: swptst
integer :: tindx
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   This routine adds node kk to a triangulation of a set
! of points in the plane producing a new triangulation.  A
! sequence of edge swaps is then applied to the mesh,
! resulting in an optimal triangulation.  adnode is part
! of an interpolation package which also provides routines
! to initialize the data structure, plot the mesh, and
! delete arcs.
!
! INPUT PARAMETERS -   kk - INDEX OF THE NODE TO BE ADDED
!                           TO THE MESH.  kk .GE. 4.
!
!                     x,y - vectors of coordinates of the
!                           nodes in the mesh.  (x(I),y(I))
!                           DEFINES NODE I FOR I = 1,..,kk.
!
!                    iadj - set of adjacency lists of nodes
!                           1,..,kk-1.
!
!                    iend - pointers to the ends of
!                           adjacency lists in iadj for
!                           each node in the mesh.
!
! iadj and iend may be created by trmesh.
!
! kk, x, and y are not altered by this routine.
!
! Output parameters - iadj,iend - updated with the addition
!                                 of node kk as the last
!                                 entry.
!
!                           ier - error indicator
!                                 ier = 0 IF NO ERRORS
!                                         were encountered.
!                                 ier = 1 IF ALL NODES
!                                         (including kk) are
!                                         collinear.
!
! Modules referenced by adnode - trfind, intadd, bdyadd,
!                                shiftd, tindx, swptst,
!                                swapd
!
!***********************************************************
!
integer :: k, km1, i1, i2, i3, indkf, indkl, nabor1, io1, io2, &
&in1, indk1, ind2f, ind21
real :: xk, yk
!
! Local parameters -
!
! k =        LOCAL COPY OF kk
! km1 =      k - 1
! i1,i2,i3 = VERTICES OF A TRIANGLE CONTAINING k
! indkf =    iadj INDEX OF THE FIRST NEIGHBOR OF k
! indkl =    iadj INDEX OF THE LAST NEIGHBOR OF k
! nabor1 =   FIRST NEIGHBOR OF k BEFORE ANY SWAPS OCCUR
! io1,io2 =  ADJACENT NEIGHBORS OF k DEFINING AN ARC TO
!              be tested for a swap
! IN1 =      VERTEX OPPOSITE k -- FIRST NEIGHBOR OF io2
!              which precedes io1.  IN1,io1,io2 are in
!              counterclockwise order.
! INDK1 =    INDEX OF io1 IN THE ADJACENCY LIST FOR k
! IND2F =    INDEX OF THE FIRST NEIGHBOR OF io2
! IND21 =    INDEX OF io1 IN THE ADJACENCY LIST FOR io2
! xk,yk =    x(k), y(k)
!
ier = 0
k = kk
!
! Initialization
!
km1 = k - 1
xk = x(k)
yk = y(k)
!
! Add node k to the mesh
!
call trfind(km1,xk,yk,x,y,iadj,iend, i1,i2,i3)
if (i1 .eq. 0) go to 5
if (i3 .eq. 0) call bdyadd(k,i1,i2, iadj,iend )
if (i3 .ne. 0) call intadd(k,i1,i2,i3, iadj,iend )
!
! Initialize variables for optimization of the mesh
!
indkf = iend(km1) + 1
indkl = iend(k)
nabor1 = iadj(indkf)
io2 = nabor1
indk1 = indkf + 1
io1 = iadj(indk1)
!
! Begin loop -- find the vertex opposite k
!
1 ind2f = 1
if (io2 .ne. 1) ind2f = iend(io2-1) + 1
ind21 = tindx(io2,io1,iadj,iend)
if (ind2f .eq. ind21) go to 2
in1 = iadj(ind21-1)
go to 3
!
! IN1 is the last neighbor of io2
!
2 ind21 = iend(io2)
in1 = iadj(ind21)
if (in1 .eq. 0) go to 4
!
! Swap test -- if a swap occurs, two new arcs are opposite k
!              and must be tested.  INDK1 and indkf must be
!              decremented.
!
3 if ( .not. swptst(in1,k,io1,io2,x,y) ) go to 4
call swapd (in1,k,io1,io2, iadj,iend)
io1 = in1
indk1 = indk1 - 1
indkf = indkf - 1
go to 1
!
! No swap occurred.  Reset io2 and io1, and test for
!   termination.
!
4 if (io1 .eq. nabor1) return
io2 = io1
indk1 = indk1 + 1
if (indk1 .gt. indkl) indk1 = indkf
io1 = iadj(indk1)
if (io1 .ne. 0) go to 1
return
!
! All nodes are collinear
!
5 ier = 1
return
end subroutine adnode

subroutine bdyadd (kk,i1,i2, iadj,iend )
implicit none
integer, intent(in) :: kk, i1, i2
integer, intent(inout) :: iadj(*), iend(kk)
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   This routine adds a boundary node to a triangulation
! of a set of kk-1 points in the plane.  iadj and iend are
! updated with the insertion of node kk.
!
! INPUT PARAMETERS -   kk - INDEX OF AN EXTERIOR NODE TO BE
!                           ADDED.  kk .GE. 4.
!
!                      i1 - first (rightmost as viewed from
!                           kk) boundary node in the mesh
!                           which is visible from kk - the
!                           line segment kk-i1 intersects
!                           no arcs.
!
!                      i2 - last (leftmost) boundary node
!                           which is visible from kk.
!
!                    iadj - set of adjacency lists of nodes
!                           in the mesh.
!
!                    iend - pointers to the ends of
!                           adjacency lists in iadj for
!                           each node in the mesh.
!
!   iadj and iend may be created by trmesh and must contain
! the vertices i1 and i2.  i1 and i2 may be determined by
! trfind.
!
! kk, i1, and i2 are not altered by this routine.
!
! Output parameters - iadj,iend - updated with the addition
!                                 of node kk as the last
!                                 entry.  Node kk will be
!                                 connected to i1, i2, and
!                                 all boundary nodes between
!                                 them.  No optimization of
!                                 the mesh is performed.
!
! Module referenced by bdyadd - shiftd
!
! Intrinsic functions called by bdyadd - MIN0, MAX0
!
!***********************************************************
!
integer :: k, km1, nright, nleft, nf, nl, n1, n2, i, imin, imax, &
&kend, next, indx
!
! Local parameters -
!
! k =            LOCAL COPY OF kk
! km1 =          k - 1
! nright,nleft = LOCAL COPIES OF i1, i2
! nf,nl =        INDICES OF iadj BOUNDING THE PORTION OF THE
!                  array to be shifted
! n1 =           iadj INDEX OF THE FIRST NEIGHBOR OF nleft
! n2 =           iadj INDEX OF THE LAST NEIGHBOR OF nright
! i =            DO-LOOP INDEX
! imin,imax =    BOUNDS ON DO-LOOP INDEX -- FIRST AND LAST
!                  elements of iend to be incremented
! KEND =         POINTER TO THE LAST NEIGHBOR OF k IN iadj
! NEXT =         NEXT BOUNDARY NODE TO BE CONNECTED TO kk
! INDX =         INDEX FOR iadj
!
k = kk
km1 = k - 1
nright = i1
nleft = i2
!
! Initialize variables
!
nl = iend(km1)
n1 = 1
if (nleft .ne. 1) n1 = iend(nleft-1) + 1
n2 = iend(nright)
nf = max0(n1,n2)
!
! Insert k as a neighbor of max(nright,nleft)
!
call shiftd(nf,nl,2, iadj )
iadj(nf+1) = k
imin = max0(nright,nleft)
do 1 i = imin,km1
  iend(i) = iend(i) + 2
1 continue
!
! Initialize KEND and insert k as a neighbor of
!   min(nright,nleft)
!
kend = nl + 3
nl = nf - 1
nf = min0(n1,n2)
call shiftd(nf,nl,1, iadj )
iadj(nf) = k
imax = imin - 1
imin = min0(nright,nleft)
do 2 i = imin,imax
  iend(i) = iend(i) + 1
2 continue
!
! Insert nright as the first neighbor of k
!
iadj(kend) = nright
!
! Initialize INDX for loop on boundary nodes between nright
!   AND nleft
!
indx = iend(nright) - 2
3 next = iadj(indx)
if (next .eq. nleft) go to 4
!
! Connect next and k
!
kend = kend + 1
iadj(kend) = next
indx = iend(next)
iadj(indx) = k
indx = indx - 1
go to 3
!
! Insert nleft and 0 as the last neighbors of k
!
4 iadj(kend+1) = nleft
kend = kend + 2
iadj(kend) = 0
iend(k) = kend
return
end subroutine bdyadd

subroutine intadd (kk,i1,i2,i3, iadj,iend )
implicit none
integer, intent(in) :: kk, i1, i2, i3
integer, intent(inout) :: iadj(*), iend(kk)
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   This routine adds an interior node to a triangulation
! of a set of kk-1 points in the plane.  iadj and iend are
! updated with the insertion of node kk in the triangle
! whose vertices are i1, i2, and i3.
!
! INPUT PARAMETERS -        kk - INDEX OF NODE TO BE
!                                INSERTED.  kk .GE. 4.
!
!                     i1,i2,i3 - indices of the vertices of
!                                a triangle containing node
!                                kk -- in counterclockwise
!                                order.
!
!                         iadj - set of adjacency lists
!                                of nodes in the mesh.
!
!                         iend - pointers to the ends of
!                                adjacency lists in iadj for
!                                each node in the mesh.
!
!   iadj and iend may be created by trmesh and must contain
! the vertices i1, i2, and i3.  i1,i2,i3 may be determined
! BY trfind.
!
! kk, i1, i2, and i3 are not altered by this routine.
!
! Output parameters - iadj,iend - updated with the addition
!                                 of node kk as the last
!                                 entry.  Node kk will be
!                                 connected to nodes i1, i2,
!                                 and i3.  No optimization
!                                 of the mesh is performed.
!
! Module referenced by intadd - shiftd
!
! Intrinsic function called by intadd - mod
!
!***********************************************************
!
integer :: k, km1, n(3), nft(3), ip1, ip2, ip3, indx, nf, nl, n1, &
&n2, imin, imax, i, itemp
!
! Local parameters -
!
! k =           LOCAL COPY OF kk
! km1 =         k - 1
! n =           VECTOR CONTAINING i1, i2, i3
! nft =         POINTERS TO THE TOPS OF THE 3 SETS OF iadj
!                 elements to be shifted downward
! ip1,ip2,ip3 = PERMUTATION INDICES FOR n AND NFT
! indx =        INDEX FOR iadj AND n
! nf,nl =       INDICES OF FIRST AND LAST ENTRIES IN iadj
!                 to be shifted down
! n1,N2 =       FIRST 2 VERTICES OF A NEW TRIANGLE --
!                 (n1,N2,kk)
! IMIN,IMAX =   BOUNDS ON DO-LOOP INDEX -- FIRST AND LAST
!                 elements of iend to be incremented
! I =           DO-LOOP INDEX
! ITEMP =       TEMPORARY STORAGE LOCATION
!
k = kk
!
! Initialization
!
n(1) = i1
n(2) = i2
n(3) = i3
!
! Set up nft
!
do 2 i = 1,3
  n1 = n(i)
  indx = mod(i,3) + 1
  n2 = n(indx)
  indx = iend(n1) + 1
!
! Find the index of N2 as a neighbor of n1
!
1 indx = indx - 1
  if (iadj(indx) .ne. n2) go to 1
  nft(i) = indx + 1
2 continue
!
! Order the vertices by decreasing magnitude.
!   n(IP(I+1)) precedes n(IP(I)) in iend for
!   i = 1,2.
!
ip1 = 1
ip2 = 2
ip3 = 3
if ( n(2) .le. n(1) ) go to 3
ip1 = 2
ip2 = 1
3 if ( n(3) .le. n(ip1) ) go to 4
ip3 = ip1
ip1 = 3
4 if ( n(ip3) .le. n(ip2) )  go to 5
itemp = ip2
ip2 = ip3
ip3 = itemp
!
! Add node k to the adjacency lists of each vertex and
!   update iend.  For each vertex, a set of iadj elements
!   is shifted downward and k is inserted.  Shifting starts
!   at the end of the array.
!
5 km1 = k - 1
nl = iend(km1)
nf = nft(ip1)
if (nf .le. nl) call shiftd(nf,nl,3, iadj )
iadj(nf+2) = k
imin = n(ip1)
imax = km1
do i = imin,imax
  iend(i) = iend(i) + 3
  end do
!
nl = nf - 1
nf = nft(ip2)
call shiftd(nf,nl,2, iadj )
iadj(nf+1) = k
imax = imin - 1
imin = n(ip2)
do i = imin,imax
  iend(i) = iend(i) + 2
  end do
!
nl = nf - 1
nf = nft(ip3)
call shiftd(nf,nl,1, iadj )
iadj(nf) = k
imax = imin - 1
imin = n(ip3)
do i = imin,imax
  iend(i) = iend(i) + 1
  end do
!
! Add node k to iend and its neighbors to iadj
!
indx = iend(km1)
iend(k) = indx + 3
do i = 1,3
  indx = indx + 1
  iadj(indx) = n(i)
  end do
return
end subroutine intadd

subroutine shiftd (nfrst,nlast,kk, iarr )
implicit none
integer, intent(in) :: nfrst, nlast, kk
integer, intent(inout) :: iarr(*)
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   This routine shifts a set of contiguous elements of an
! INTEGER ARRAY kk POSITIONS DOWNWARD (UPWARD IF kk .LT. 0).
! The loops are unrolled in order to increase efficiency.
!
! Input parameters - nfrst,nlast - bounds on the portion of
!                                  iarr to be shifted.  All
!                                  elements between and
!                                  including the bounds are
!                                  SHIFTED UNLESS nfrst .GT.
!                                  nlast, in which case no
!                                  shift occurs.
!
!                             kk - number of positions each
!                                  element is to be shifted.
!                                  IF kk .LT. 0 SHIFT UP.
!                                  IF kk .GT. 0 SHIFT DOWN.
!
!                           iarr - integer array of length
!                                  .GE. nlast + max(kk,0).
!
! nfrst, nlast, and kk are not altered by this routine.
!
! OUTPUT PARAMETER -        iarr - SHIFTED ARRAY.
!
! Modules referenced by shiftd - none
!
!***********************************************************
!
integer :: inc, k, nf, nl, nlp1, ns, nsl, i, ibak, indx, imax
data    inc/5/
!
! Local parameters -
!
! inc =  DO-LOOP INCREMENT (UNROLLING FACTOR) -- IF INC IS
!          changed, statements must be added to or deleted
!          from the do-loops
! k =    LOCAL COPY OF kk
! nf =   LOCAL COPY OF nfrst
! nl =   LOCAL COPY OF nlast
! nlp1 = nl + 1
! ns =   NUMBER OF SHIFTS
! nsl =  NUMBER OF SHIFTS DONE IN UNROLLED DO-LOOP (MULTIPLE
!          of inc)
! i =    DO-LOOP INDEX AND INDEX FOR iarr
! ibak = INDEX FOR DOWNWARD SHIFT OF iarr
! indx = INDEX FOR iarr
! imax = BOUND ON DO-LOOP INDEX
!
k = kk
nf = nfrst
nl = nlast
if (nf .gt. nl  .or.  k .eq. 0) return
nlp1 = nl + 1
ns = nlp1 - nf
nsl = inc*(ns/inc)
if ( k .lt. 0) go to 4
!
! Shift downward starting from the bottom
!
if (nsl .le. 0) go to 2
do 1 i = 1,nsl,inc
  ibak = nlp1 - i
  indx = ibak + k
  iarr(indx) = iarr(ibak)
  iarr(indx-1) = iarr(ibak-1)
  iarr(indx-2) = iarr(ibak-2)
  iarr(indx-3) = iarr(ibak-3)
  iarr(indx-4) = iarr(ibak-4)
1 continue
!
! Perform the remaining ns-nsl shifts one at a time
!
2 ibak = nlp1 - nsl
3 if (ibak .le. nf) return
ibak = ibak - 1
indx = ibak + k
iarr(indx) = iarr(ibak)
go to 3
!
! Shift upward starting from the top
!
4 if (nsl .le. 0) go to 6
imax = nlp1 - inc
do 5 i = nf,imax,inc
  indx = i + k
  iarr(indx) = iarr(i)
  iarr(indx+1) = iarr(i+1)
  iarr(indx+2) = iarr(i+2)
  iarr(indx+3) = iarr(i+3)
  iarr(indx+4) = iarr(i+4)
5 continue
!
! Perform the remaining ns-nsl shifts one at a time
!
6 i = nsl + nf
7 if (i .gt. nl) return
indx = i + k
iarr(indx) = iarr(i)
i = i + 1
go to 7
end subroutine shiftd

subroutine swapd (nin1,nin2,nout1,nout2, iadj,iend)
implicit none
integer, intent(in) :: nin1, nin2, nout1, nout2
integer, intent(inout) :: iadj(*), iend(*)
integer :: tindx
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   This subroutine swaps the diagonals in a convex quadri-
! lateral.
!
! Input parameters -  nin1,nin2,nout1,nout2 - nodal indices
!                            of a pair of adjacent triangles
!                            which form a convex quadrilat-
!                            eral.  nout1 and nout2 are con-
!                            nected by an arc which is to be
!                            replaced by the arc nin1-nin2.
!                            (nin1,nout1,nout2) must be TRI-
!                            angle vertices in counterclock-
!                            wise order.
!
! The above parameters are not altered by this routine.
!
!                iadj,iend - triangulation data structure
!                            (see subroutine trmesh).
!
! Output parameters - iadj,iend - updated with the arc
!                                 replacement.
!
! Modules referenced by swapd - tindx, shiftd
!
!***********************************************************
!
integer :: in(2), io(2), ip1, ip2, j, k, nf, nl, i, imin, imax
!
! Local parameters -
!
! in =        nin1 AND nin2 ORDERED BY INCREASING MAGNITUDE
!               (the neighbors of in(1) precede those of
!               in(2) in iadj)
! io =        nout1 AND nout2 IN INCREASING ORDER
! ip1,ip2 =   PERMUTATION OF (1,2) SUCH THAT io(ip1)
!               precedes io(ip2) as a neighbor of in(1)
! j,k =       PERMUTATION OF (1,2) USED AS INDICES OF IN
!               AND io
! nf,nl =     iadj INDICES BOUNDARY A PORTION OF THE ARRAY
!               to be shifted
! i =         iend INDEX
! imin,imax = BOUNDS ON THE PORTION OF iend TO BE INCRE-
!               mented or decremented
!
in(1) = nin1
in(2) = nin2
io(1) = nout1
io(2) = nout2
ip1 = 1
!
! ORDER THE INDICES SO THAT in(1) .LT. in(2) AND io(1) .LT.
!   io(2), and choose ip1 and ip2 such that (in(1),io(ip1),
!   io(ip2)) forms a triangle.
!
if (in(1) .lt. in(2)) go to 1
in(1) = in(2)
in(2) = nin1
ip1 = 2
1 if (io(1) .lt. io(2)) go to 2
io(1) = io(2)
io(2) = nout1
ip1 = 3 - ip1
2 ip2 = 3 - ip1
if (io(2) .lt. in(1)) go to 8
if (in(2) .lt. io(1)) go to 12
!
! in(1) AND io(1) PRECEDE in(2) AND io(2).  FOR (j,k) =
!   (1,2) and (2,1), delete io(k) as a neighbor of io(j)
!   by shifting a portion of iadj either up or down and
!   and insert in(k) as a neighbor of in(j).
!
do 7 j = 1,2
  k = 3 - j
  if (in(j) .gt. io(j)) go to 4
!
!   The neighbors of in(j) precede those of io(j) -- shift
!     down by 1
!
  nf = 1 + tindx(in(j),io(ip1),iadj,iend)
  nl = -1 + tindx(io(j),io(k),iadj,iend)
  if (nf .le. nl) call shiftd(nf,nl,1, iadj )
  iadj(nf) = in(k)
  imin = in(j)
  imax = io(j)-1
  do 3 i = imin,imax
3 iend(i) = iend(i) + 1
  go to 6
!
!   The neighbors of io(j) precede those of in(j) -- shift
!     up by 1
!
4 nf = 1 + tindx(io(j),io(k),iadj,iend)
  nl = -1 + tindx(in(j),io(ip2),iadj,iend)
  if (nf .le. nl) call shiftd(nf,nl,-1, iadj )
  iadj(nl) = in(k)
  imin = io(j)
  imax = in(j) - 1
  do 5 i = imin,imax
5 iend(i) = iend(i) - 1
!
!   REVERSE (ip1,ip2) FOR (j,k) = (2,1)
!
6 ip1 = ip2
  ip2 = 3 - ip1
7 continue
return
!
! The vertices are ordered (io(1),io(2),in(1),in(2)).
!   Delete io(2) by shifting up by 1
!
8 nf = 1 + tindx(io(1),io(2),iadj,iend)
nl = -1 + tindx(io(2),io(1),iadj,iend)
if (nf .le. nl) call shiftd(nf,nl,-1, iadj )
imin = io(1)
imax = io(2)-1
do 9 i = imin,imax
9 iend(i) = iend(i) - 1
!
!   Delete io(1) by shifting up by 2 and insert in(2)
!
nf = nl + 2
nl = -1 + tindx(in(1),io(ip2),iadj,iend)
if (nf .le. nl) call shiftd(nf,nl,-2, iadj )
iadj(nl-1) = in(2)
imin = io(2)
imax = in(1)-1
do 10 i = imin,imax
10 iend(i) = iend(i) - 2
!
!   Shift up by 1 and insert in(1)
!
nf = nl + 1
nl = -1 + tindx(in(2),io(ip1),iadj,iend)
call shiftd(nf,nl,-1, iadj )
iadj(nl) = in(1)
imin = in(1)
imax = in(2)-1
do 11 i = imin,imax
11 iend(i) = iend(i) - 1
return
!
! The vertices are ordered (in(1),in(2),io(1),io(2)).
!   Delete io(1) by shifting down by 1
!
12 nf = 1 + tindx(io(1),io(2),iadj,iend)
nl = -1 + tindx(io(2),io(1),iadj,iend)
if (nf .le. nl) call shiftd(nf,nl,1, iadj )
imin = io(1)
imax = io(2) - 1
do 13 i = imin,imax
13 iend(i) = iend(i) + 1
!
!   Delete io(2) by shifting down by 2 and insert in(1)
!
nl = nf - 2
nf = 1 + tindx(in(2),io(ip2),iadj,iend)
if (nf .le. nl) call shiftd(nf,nl,2, iadj )
iadj(nf+1) = in(1)
imin = in(2)
imax = io(1) - 1
do 14 i = imin,imax
14 iend(i) = iend(i) + 2
!
!   Shift down by 1 and insert in(2)
!
nl = nf - 1
nf = 1 + tindx(in(1),io(ip1),iadj,iend)
call shiftd(nf,nl,1, iadj )
iadj(nf) = in(2)
imin = in(1)
imax = in(2) - 1
do 15 i = imin,imax
15 iend(i) = iend(i) + 1
return
end subroutine swapd

logical function swptst (in1,in2,io1,io2,x,y)
implicit none
integer, intent(in) :: in1, in2, io1, io2
real, intent(in) :: x(*), y(*)
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   This function decides whether or not to replace A
! diagonal arc in a quadrilateral with the other diagonal.
! The determination is based on the sizes of the angles
! contained in the 2 triangles defined by the diagonal.
! The diagonal is chosen to maximize the smallest of the
! six angles over the two pairs of triangles.
!
! Input parameters -  in1,in2,io1,io2 - node indices of the
!                              four points defining the
!                              quadrilateral.  io1 and io2
!                              are currently connected by A
!                              diagonal arc.  This arc
!                              should be replaced by an arc
!                              connecting in1, in2 if the
!                              decision is made to swap.
!                              in1,io1,io2 must be in
!                              counterclockwise order.
!
!                        x,y - vectors of nodal coordinates.
!                              (x(I),y(I)) are the coord-
!                              INATES OF NODE I FOR I = in1,
!                              in2, io1, OR io2.
!
! None of the input parameters are altered by this routine.
!
! Output parameter -  swptst - .True. IFF the arc connecting
!                              io1 and io2 is to be replaced
!
! Modules referenced by swptst - none
!
!***********************************************************
!
real :: dx11, dx12, dx22, dx21, dy11, dy12, dy22, dy21, sin1, &
&sin2, cos1, cos2, sin12
!
! Local parameters -
!
! dx11,dy11 = x,y COORDINATES OF THE VECTOR in1-io1
! dx12,dy12 = x,y COORDINATES OF THE VECTOR in1-io2
! dx22,dy22 = x,y COORDINATES OF THE VECTOR in2-io2
! dx21,dy21 = x,y COORDINATES OF THE VECTOR in2-io1
! sin1 =      CROSS PRODUCT OF THE VECTORS in1-io1 AND
!               in1-io2 -- proportional to sin(T1) where T1
!               is the angle at in1 formed by the vectors
! cos1 =      INNER PRODUCT OF THE VECTORS in1-io1 AND
!               in1-io2 -- proportional to cos(T1)
! SIN2 =      CROSS PRODUCT OF THE VECTORS in2-io2 AND
!               in2-io1 -- proportional to sin(T2) where T2
!               is the angle at in2 formed by the vectors
! COS2 =      INNER PRODUCT OF THE VECTORS in2-io2 AND
!               in2-io1 -- proportional to cos(T2)
! SIN12 =     sin1*COS2 + cos1*SIN2 -- PROPORTIONAL TO
!               sin(T1+T2)
!
swptst = .false.
!
! Compute the vectors containing the angles T1, T2
!
dx11 = x(io1) - x(in1)
dx12 = x(io2) - x(in1)
dx22 = x(io2) - x(in2)
dx21 = x(io1) - x(in2)
!
dy11 = y(io1) - y(in1)
dy12 = y(io2) - y(in1)
dy22 = y(io2) - y(in2)
dy21 = y(io1) - y(in2)
!
! Compute inner products
!
cos1 = dx11*dx12 + dy11*dy12
cos2 = dx22*dx21 + dy22*dy21
!
! THE DIAGONALS SHOULD BE SWAPPED IFF (T1+T2) .GT. 180
!   degrees.  The following two tests insure numerical
!   stability.
!
if (cos1 .ge. 0.  .and.  cos2 .ge. 0.) return
if (cos1 .lt. 0.  .and.  cos2 .lt. 0.) go to 1
!
! Compute vector cross products
!
sin1 = dx11*dy12 - dx12*dy11
sin2 = dx22*dy21 - dx21*dy22
sin12 = sin1*cos2 + cos1*sin2
if (sin12 .ge. 0.) return
1 swptst = .true.
return
end function swptst

integer function tindx (nvertx,nabor,iadj,iend)
implicit none
integer, intent(in) :: nvertx, nabor, iadj(*), iend(*)
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   This function returns the index of nabor in the
! adjacency list for nvertx.
!
! Input parameters - nvertx - node whose adjacency list is
!                             to be searched.
!
!                     nabor - node whose index is to be
!                             returned.  nabor must be
!                             connected to nvertx.
!
!                      iadj - set of adjacency lists.
!
!                      iend - pointers to the ends of
!                             adjacency lists in iadj.
!
! Input parameters are not altered by this function.
!
! OUTPUT PARAMETER -  tindx - iadj(tindx) = nabor.
!
! Modules referenced by tindx - none
!
!***********************************************************
!
integer :: nb, indx
!
! Local parameters -
!
! nb =   LOCAL COPY OF nabor
! indx = INDEX FOR iadj
!
nb = nabor
!
! Initialization
!
indx = iend(nvertx) + 1
!
! Search the list of nvertx neighbors for nb
!
1 indx = indx - 1
if (iadj(indx) .ne. nb) go to 1
!
tindx = indx
return
end function tindx

subroutine trfind (nst,px,py,x,y,iadj,iend, i1,i2,i3)
implicit none
real :: x0, x1, x2, y0, y1, y2
integer, intent(in) :: nst, iadj(*), iend(*)
integer, intent(inout) :: i1, i2, i3
real, intent(in) :: px, py
real :: x(*), y(*)
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   This routine locates a point P in a thiessen triangu-
! lation, returning the vertex indices of a triangle which
! contains P.  trfind is part of an interpolation package
! which provides subroutines for creating the mesh.
!
! INPUT PARAMETERS -    nst - INDEX OF NODE AT WHICH trfind
!                             begins search.  Search time
!                             depends on the proximity of
!                             nst TO P.
!
!                     px,py - x and y-coordinates of the
!                             point to be located.
!
!                       x,y - vectors of coordinates of
!                             nodes in the mesh.  (x(I),y(I))
!                             DEFINES NODE I FOR I = 1,...,N
!                             WHERE N .GE. 3.
!
!                      iadj - set of adjacency lists of
!                             nodes in the mesh.
!
!                      iend - pointers to the ends of
!                             adjacency lists in iadj for
!                             each node in the mesh.
!
! iadj and iend may be created by trmesh.
!
! Input parameters are not altered by this routine.
!
! Output parameters - i1,i2,i3 - vertex indices in counter-
!                                clockwise order - vertices
!                                of a triangle containing P
!                                if P is an interior node.
!                                If P is outside of the
!                                boundary of the mesh, i1
!                                and i2 are the first (right
!                                -most) and last (leftmost)
!                                nodes which are visible
!                                FROM P, AND i3 = 0.  IF P
!                                and all of the nodes lie on
!                                A SINGLE LINE THEN i1 = i2
!                                = i3 = 0.
!
! Modules referenced by trfind - none
!
! Intrinsic function called by trfind - MAX0
!
!***********************************************************
!
integer :: n0, n1, n2, n3, n4, indx, ind, nf, nl, next
real :: xp, yp
logical :: left
!
! Local parameters -
!
! xp,yp =     LOCAL VARIABLES CONTAINING px AND py
! n0,n1,n2 =  NODES IN COUNTERCLOCKWISE ORDER DEFINING A
!               cone (with vertex n0) containing P
! n3,n4 =     NODES OPPOSITE n1-n2 AND n2-n1, RESPECTIVELY
! indx,ind =  INDICES FOR iadj
! nf,nl =     FIRST AND LAST NEIGHBORS OF n0 IN iadj, OR
!               first (rightmost) and last (leftmost) nodes
!               visible from P when P is outside the
!               boundary
! next =      CANDIDATE FOR i1 OR i2 WHEN P IS OUTSIDE OF
!               the boundary
! left =      STATEMENT FUNCTION WHICH COMPUTES THE SIGN OF
!               a cross product (Z-COMPONENT).  Left(x1,...,
!               y0) = .TRUE. IFF (x0,y0) IS ON OR TO THE
!               left of the vector from (x1,y1) to (x2,y2).
!
left(x1,y1,x2,y2,x0,y0) = (x2-x1)*(y0-y1) .ge. &
&(x0-x1)*(y2-y1)
xp = px
yp = py
!
! Initialize variables and find a cone containing P
!
n0 = max0(nst,1)
1 indx = iend(n0)
nl = iadj(indx)
indx = 1
if (n0 .ne. 1) indx = iend(n0-1) + 1
nf = iadj(indx)
n1 = nf
if (nl .ne. 0) go to 3
!
! n0 is a boundary node.  Set nl to the last nonzero
!   neighbor of n0.
!
ind = iend(n0) - 1
nl = iadj(ind)
if ( left(x(n0),y(n0),x(nf),y(nf),xp,yp) ) go to 2
!
! P is outside the boundary
!
nl = n0
go to 16
2 if ( left(x(nl),y(nl),x(n0),y(n0),xp,yp) ) go to 4
!
! P is outside the boundary and n0 is the rightmost
!   visible boundary node
!
i1 = n0
go to 18
!
! n0 is an interior node.  Find n1.
!
3 if ( left(x(n0),y(n0),x(n1),y(n1),xp,yp) ) go to 4
indx = indx + 1
n1 = iadj(indx)
if (n1 .eq. nl) go to 7
go to 3
!
! P is to the left of arc n0-n1.  Initialize n2 to the next
!   neighbor of n0.
!
4 indx = indx + 1
n2 = iadj(indx)
if ( .not. left(x(n0),y(n0),x(n2),y(n2),xp,yp) ) &
&go to 8
n1 = n2
if (n1 .ne. nl) go to 4
if ( .not. left(x(n0),y(n0),x(nf),y(nf),xp,yp) ) &
&go to 7
if (xp .eq. x(n0) .and. yp .eq. y(n0)) go to 6
!
! P is left of or on arcs n0-NB for all neighbors NB
!   OF n0.
! All points are collinear IFF P is left of NB-n0 for
!   all neighbors NB of n0.  Search the neighbors of n0
!   IN REVERSE ORDER.  NOTE -- n1 = nl AND indx POINTS TO
!   nl.
!
5 if ( .not. left(x(n1),y(n1),x(n0),y(n0),xp,yp) ) &
&go to 6
if (n1 .eq. nf) go to 20
indx = indx - 1
n1 = iadj(indx)
go to 5
!
! P IS TO THE RIGHT OF n1-n0, OR P=n0.  SET n0 TO n1 AND
!   start over.
!
6 n0 = n1
go to 1
!
! P is between arcs n0-n1 and n0-nf
!
7 n2 = nf
!
! P is contained in a cone defined by line segments n0-n1
!   and n0-n2 where n1 is adjacent to n2
!
8 n3 = n0
9 if ( left(x(n1),y(n1),x(n2),y(n2),xp,yp) ) go to 13
!
! Set n4 to the first neighbor of n2 following n1
!
indx = iend(n2)
if (iadj(indx) .ne. n1) go to 10
!
! n1 is the last neighbor of n2.
! Set n4 to the first neighbor.
!
indx = 1
if (n2 .ne. 1) indx = iend(n2-1) + 1
n4 = iadj(indx)
go to 11
!
! n1 is not the last neighbor of n2
!
10 indx = indx-1
if (iadj(indx) .ne. n1) go to 10
n4 = iadj(indx+1)
if (n4 .ne. 0) go to 11
!
! P is outside the boundary
!
nf = n2
nl = n1
go to 16
!
! Define a new arc n1-n2 which intersects the line
!   SEGMENT n0-P
!
11 if ( left(x(n0),y(n0),x(n4),y(n4),xp,yp) ) go to 12
n3 = n2
n2 = n4
go to 9
12 n3 = n1
n1 = n4
go to 9
!
! P is in the triangle (n1,n2,n3) and not on n2-n3.  If
!   n3-n1 or n1-n2 is a boundary arc containing P, treat P
!   as exterior.
!
13 indx = iend(n1)
if (iadj(indx) .ne. 0) go to 15
!
! n1 is a boundary node.  n3-n1 is a boundary arc IFF n3
!   is the last nonzero neighbor of n1.
!
if (n3 .ne. iadj(indx-1)) go to 14
!
! n3-n1 is a boundary arc
!
if ( .not. left(x(n1),y(n1),x(n3),y(n3),xp,yp) ) &
&go to 14
!
! P lies on n1-n3
!
i1 = n1
i2 = n3
i3 = 0
return
!
! n3-n1 is not a boundary arc containing P.  n1-n2 is A
!   boundary arc IFF n2 is the first neighbor of n1.
!
14 indx = 1
if (n1 .ne. 1) indx = iend(n1-1) + 1
if (n2 .ne. iadj(indx)) go to 15
!
! n1-n2 is a boundary arc
!
if ( .not. left(x(n2),y(n2),x(n1),y(n1),xp,yp) ) &
&go to 15
!
! P lies on n1-n2
!
i1 = n2
i2 = n1
i3 = 0
return
!
! P does not lie on a boundary arc.
!
15 i1 = n1
i2 = n2
i3 = n3
return
!
! nf and nl are adjacent boundary nodes which are visible
!   from P.  find the first visible boundary node.
! Set next to the first neighbor of nf.
!
16 indx = 1
if (nf .ne. 1) indx = iend(nf-1) + 1
next = iadj(indx)
if ( left(x(nf),y(nf),x(next),y(next),xp,yp) ) &
&go to 17
nf = next
go to 16
!
! nf is the first (rightmost) visible boundary node
!
17 i1 = nf
!
! Find the last visible boundary node.  nl is the first
!   candidate for i2.
! Set next to the last neighbor of nl.
!
18 indx = iend(nl) - 1
next = iadj(indx)
if ( left(x(next),y(next),x(nl),y(nl),xp,yp) ) &
&go to 19
nl = next
go to 18
!
! nl is the last (leftmost) visible boundary node
!
19 i2 = nl
i3 = 0
return
!
! All points are collinear
!
20 i1 = 0
i2 = 0
i3 = 0
return
end subroutine trfind

subroutine gradg (n, x, y, z, iadj, iend, zxzy, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n
integer :: j, miter
real :: eps
!-----------------------------------------------------------------------
!                      Derivative estimation
!-----------------------------------------------------------------------
real, intent(in) :: x(n), y(n), z(n)
real, intent(inout) :: zxzy(2,n)
integer, intent(in) :: iadj(*), iend(n)
!
if (n .lt. 3) go to 20
!
eps = 0.0
miter = 5
do j = 1,n
   zxzy(1,j) = 0.0
   zxzy(2,j) = 0.0
end do
call gradg1 (n, x, y, z, iadj, iend, eps, miter, zxzy, ierr)
ierr = 0
return
!
!     Error return
!
20 ierr = 1
return
end subroutine gradg

subroutine gradg1 (n,x,y,z,iadj,iend,eps, nit, &
&zxzy, ier)
implicit none
integer, intent(in) :: n, iadj(*), iend(n)
integer, intent(inout) :: nit, ier
real, intent(in) :: x(n), y(n), z(n), eps
real, intent(inout) :: zxzy(2,n)
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   Given a triangulation of n nodes in the plane with
! associated data values, this routine uses a global method
! to compute estimated gradients at the nodes.  The method
! consists of minimizing a quadratic functional Q(G) over
! the n-vector G of gradients where Q approximates the lin-
! earized curvature of an interpolant F over the triangula-
! tion.  The restriction of F to an arc of the triangulation
! is taken to be the Hermite cubic interpolant of the data
! values and tangential gradient components at the end-
! points of the arc, and Q is the sum of the linearized
! curvatures of F along the arcs -- the integrals over the
! ARCS OF D2F(T)**2 WHERE D2F(T) IS THE SECOND DERIVATIVE
! of F with respect to distance T along the arc.  This min-
! imization problem corresponds to an order 2n symmetric
! positive-definite sparse linear system which is solved for
! the x and y partial derivatives by the block Gauss-Seidel
! method with 2 by 2 blocks.
!   An alternative method, subroutine gradl, computes A
! local approximation to the partials at a single node and
! may be more accurate, depending on the data values and
! distribution of nodes (neither method emerged as superior
! in tests for accuracy).  However, in tests run on an IBM
! 370, gradg1 was found to be about 3.6 times as fast for
! nit = 4.
!
! INPUT PARAMETERS - n - NUMBER OF NODES.  n .GE. 3.
!
!                  x,y - cartesian coordinates of the nodes.
!
!                    z - data values at the nodes.  z(I) is
!                        associated with (x(I),y(I)).
!
!            iadj,iend - data structure defining the trian-
!                        gulation.  See subroutine trmesh.
!
!                  eps - nonnegative convergence criterion.
!                        The method is terminated when the
!                        maximum change in a gradient compo-
!                        nent between iterations is at most
!                        EPS.  eps = 1.E-2 IS SUFFICIENT FOR
!                        effective convergence.
!
! The above parameters are not altered by this routine.
!
!                  nit - maximum number of Gauss-Seidel
!                        iterations to be applied.  This
!                        maximum will likely be achieved if
!                        eps is smaller than the machine
!                        precision.  Optimal efficiency was
!                        ACHIEVED IN TESTING WITH eps = 0
!                        AND nit = 3 OR 4.
!
!                 zxzy - 2 by n array whose columns contain
!                        initial estimates of the partial
!                        derivatives (zero vectors are
!                        sufficient).
!
! Output parameters - nit - number of Gauss-Seidel itera-
!                           TIONS EMPLOYED.
!
!                    zxzy - estimated x and y partial deriv-
!                           atives at the nodes with x par-
!                           tials in the first row.  zxzy is
!                           NOT CHANGED IF ier = 2.
!
!                     ier - error indicator
!                           ier = 0 IF THE CONVERGENCE CRI-
!                                   terion was achieved.
!                           ier = 1 IF CONVERGENCE WAS NOT
!                                   achieved within nit
!                                   iterations.
!                           ier = 2 IF n OR EPS IS OUT OF
!                                   RANGE OR nit .LT. 0 ON
!                                   input.
!
! Modules referenced by gradg1 - none
!
! Intrinsic functions called by gradg1 - sqrt, AMAX1, abs
!
!***********************************************************
!
integer :: nn, maxit, iter, k, indf, indl, indx, nb
real :: tol, dgmax, xk, yk, zk, zxk, zyk, a11, a12, a22, r1, r2, &
&delx, dely, delxs, delys, dsq, dcub, t, dzx, dzy
!
! Local parameters -
!
! nn =          LOCAL COPY OF n
! maxit =       INPUT VALUE OF NIT
! iter =        NUMBER OF ITERATIONS USED
! k =           DO-LOOP AND NODE INDEX
! indf,indl =   iadj INDICES OF THE FIRST AND LAST NEIGHBORS
!                 OF k
! indx =        iadj INDEX IN THE RANGE indf,...,indl
! nb =          NEIGHBOR OF k
! tol =         LOCAL COPY OF EPS
! dgmax =       MAXIMUM CHANGE IN A GRADIENT COMPONENT BE-
!                 tween iterations
! xk,yk,zk =    x(k), y(k), z(k)
! zxk,zyk =     INITIAL VALUES OF zxzy(1,k) AND zxzy(2,k)
! a11,a12,a22 = MATRIX COMPONENTS OF THE 2 BY 2 BLOCK A*DG
!                 = R WHERE A IS SYMMETRIC, DG = (DZX,DZY)
!                 is the change in the gradient at k, and R
!                 is the residual
! r1,r2 =       COMPONENTS OF THE RESIDUAL -- DERIVATIVES OF
!                 Q with respect to the components of the
!                 gradient at node k
! DELX,DELY =   COMPONENTS OF THE ARC nb-k
! DELXS,DELYS = DELX**2, DELY**2
! DSQ =         SQUARE OF THE DISTANCE D BETWEEN k AND nb
! dcub =        d**3
! T =           FACTOR OF r1 AND r2
! DZX,DZY =     SOLUTION OF THE 2 BY 2 SYSTEM -- CHANGE IN
!                 derivatives at k from the previous iterate
!
nn = n
tol = eps
maxit = nit
!
! Error checks and initialization
!
if (nn .lt. 3  .or.  tol .lt. 0.  .or.  maxit .lt. 0) &
&go to 5
iter = 0
!
! Top of iteration loop
!
1 if (iter .eq. maxit) go to 4
dgmax = 0.
indl = 0
do 3 k = 1,nn
  xk = x(k)
  yk = y(k)
  zk = z(k)
  zxk = zxzy(1,k)
  zyk = zxzy(2,k)
!
!   Initialize components of the 2 by 2 system
!
  a11 = 0.
  a12 = 0.
  a22 = 0.
  r1 = 0.
  r2 = 0.
!
!   Loop on neighbors nb of k
!
  indf = indl + 1
  indl = iend(k)
  do 2 indx = indf,indl
    nb = iadj(indx)
    if (nb .eq. 0) go to 2
!
!   Compute the components of arc nb-k
!
    delx = x(nb) - xk
    dely = y(nb) - yk
    delxs = delx*delx
    delys = dely*dely
    dsq = delxs + delys
    dcub = dsq*sqrt(dsq)
!
!   Update the system components for node nb
!
    a11 = a11 + delxs/dcub
    a12 = a12 + delx*dely/dcub
    a22 = a22 + delys/dcub
    t = ( 1.5*(z(nb)-zk) - ((zxzy(1,nb)/2.+zxk)*delx + &
&(zxzy(2,nb)/2.+zyk)*dely) )/dcub
    r1 = r1 + t*delx
    r2 = r2 + t*dely
2 continue
!
!   Solve the 2 by 2 system and update dgmax
!
  dzy = (a11*r2 - a12*r1)/(a11*a22 - a12*a12)
  dzx = (r1 - a12*dzy)/a11
  dgmax = amax1(dgmax,abs(dzx),abs(dzy))
!
!   Update the partials at node k
!
  zxzy(1,k) = zxk + dzx
3 zxzy(2,k) = zyk + dzy
!
!   Increment iter and test for convergence
!
iter = iter + 1
if (dgmax .gt. tol) go to 1
!
! Method converged
!
nit = iter
ier = 0
return
!
! Method failed to converge within nit iterations
!
4 ier = 1
return
!
! Parameter OUT of range
!
5 nit = 0
ier = 2
return
end subroutine gradg1

subroutine gradl (n, x, y, z, iadj, iend, zxzy, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n
integer :: j
!-----------------------------------------------------------------------
!                      Derivative estimation
!-----------------------------------------------------------------------
real, intent(in) :: x(n), y(n), z(n)
real, intent(inout) :: zxzy(2,n)
integer, intent(in) :: iadj(*)
integer, intent(inout) :: iend(n)
!
if (n .lt. 3) go to 20
!
do j = 1,n
   call gradl1 (n, j, x, y, z, iadj, iend, zxzy(1,j), &
&zxzy(2,j), ierr)
   if (ierr .lt. 0) go to 30
end do
ierr = 0
return
!
!     Error return
!
20 ierr = 1
return
!
30 ierr = 2
return
end subroutine gradl

subroutine gradl1 (n,k,x,y,z,iadj,iend, dx,dy,ier)
implicit none
integer, intent(in) :: n, k, iadj(*)
integer, intent(inout) :: iend(n), ier
real, intent(in) :: x(n), y(n), z(n)
real, intent(inout) :: dx, dy
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   Given a thiessen triangulation of n points in the plane
! with associated data values z, this subroutine estimates
! x and y partial derivatives at node k.  the derivatives
! are taken to be the partials at k of a quadratic function
! which interpolates z(k) and fits the data values at a set
! of nearby nodes in a weighted least squares sense. A mar-
! quardt stabilization factor is used if necessary to ensure
! a well-conditioned system and a linear fitting function is
! USED IF n .LT. 6.  THUS, A UNIQUE SOLUTION EXISTS UNLESS
! the nodes are collinear.
!   An alternative routine, gradg, employs a global method
! to compute the partial derivatives at all of the nodes at
! once.  That method is more efficient (when all partials
! are needed) and may be more accurate, depending on the
! data.
!
! Input parameters - n - number of nodes in the triangula-
!                        TION.  n .GE. 3.
!
!                    k - node at which derivatives are
!                        SOUGHT.  1 .LE. k .LE. n.
!
!                  x,y - n-vectors containing the cartesian
!                        coordinates of the nodes.
!
!                    z - n-vector containing the data values
!                        associated with the nodes.
!
!                 iadj - set of adjacency lists.
!
!                 iend - pointers to the ends of adjacency
!                        lists for each node.
!
! iadj and iend may be created by subroutine trmesh.
!
! Input parameters are not altered by this routine.
!
! Output parameters - dx,dy - estimated partial derivatives
!                             AT NODE k UNLESS ier .LT. 0.
!
!                       ier - error indicator
!                             ier .GT. 0 IF NO ERRORS WERE
!                                      encountered.  Ier
!                                      contains the number
!                                      of nodes (including
!                                      k) used in the fit.
!                                      ier = 3, 4, or 5 im-
!                                      plies a linear fit.
!                             ier = -1 IF n OR k IS OUT OF
!                                      range.
!                             ier = -2 IF ALL NODES ARE
!                                      collinear.
!
! Modules referenced by gradl1 - getnp, setrm, srotg, srot
!
! Intrinsic functions called by gradl1 - MIN0, float, sqrt,
!                                       AMIN1, ABS
!
!***********************************************************
!
integer :: nn, kk, lmn, lmx, lmin, lmax, lm1, lnp, npts(30), ierr, &
&np, i, j, im1, jp1, ip1, l
real :: sum, ds, r, rs, rtol, avsq, av, xk, yk, zk, a(6,6), c, s, &
&dmin, dtol, sf
data    lmn/10/
data    lmx/30/, rtol/1.e-5/, dtol/.01/, sf/1./
!
! Local parameters -
!
! nn,kk =     LOCAL COPIES OF n AND k
! lmn,lmx =   MINIMUM AND MAXIMUM VALUES OF lnp FOR n
!               sufficiently large.  In most cases lmn-1
!               NODES ARE USED IN THE FIT.  4 .LE. lmn .LE.
!               lmx.
! lmin,lmax = min(lmn,n), min(lmx,n)
! lm1 =       lmin-1 OR lnp-1
! lnp =       LENGTH OF npts
! npts =      ARRAY CONTAINING THE INDICES OF A SEQUENCE OF
!               NODES ORDERED BY DISTANCE FROM k.  npts(1)=k
!               and the first lnp-1 elements of npts are
!               used in the least squares fit.  Unless lnp
!               exceeds lmax, npts(lnp) determines r.
! ierr =      ERROR FLAG FOR CALLS TO getnp (NOT CHECKED)
! NP =        ELEMENT OF npts TO BE ADDED TO THE SYSTEM
! I,J =       DO-LOOP INDICES
! IM1,JP1 =   I-1, J+1
! ip1 =       i+1
! L =         NUMBER OF COLUMNS OF a**T TO WHICH A ROTATION
!               is applied
! sum =       sum OF SQUARED EUCLIDEAN DISTANCES BETWEEN
!               node k and the nodes used in the least
!               squares fit
! ds =        SQUARED DISTANCE BETWEEN NODE k AND AN ELE-
!               MENT OF npts
! r =         DISTANCE BETWEEN NODE k AND npts(lnp) OR SOME
!               point further from k than npts(lmax) if
!               npts(lmax) is used in the fit.  r is A
!               radius of influence which enters into the
!               weights (see subroutine setrm).
! rs =        r*r
! rtol =      TOLERANCE FOR DETERMINING r.  IF THE RELATIVE
!               change in ds between two elements of npts is
!               not greater than rtol they are treated as
!               being the same distance from node k
! avsq =      av*av
! av =        ROOT-MEAN-SQUARE DISTANCE BETWEEN k AND THE
!               nodes (other than k) in the least squares
!               fit.  The first 3 columns of the system are
!               scaled by 1/avsq, the next 2 by 1/av.
! xk,yk,zk =  COORDINATES AND DATA VALUE ASSOCIATED WITH k
! a =         TRANSPOSE OF THE AUGMENTED REGRESSION MATRIX
! c,s =       COMPONENTS OF THE PLANE ROTATION DETERMINED
!               by subroutine srotg
! DMIN =      MINIMUM OF THE MAGNITUDES OF THE DIAGONAL
!               elements of the regression matrix after
!               zeros are introduced below the diagonal
! DTOL =      TOLERANCE FOR DETECTING AN ILL-CONDITIONED
!               system.  The system is accepted when DMIN
!               .GE. DTOL
! SF =        MARQUARDT STABILIZATION FACTOR USED TO DAMP
!               out the first 3 solution components (second
!               partials of the quadratic) when the system
!               is ill-conditioned.  As SF increases, the
!               fitting function approaches a linear
!
nn = n
kk = k
!
! Check for errors and initialize lmin, lmax
!
if (nn .lt. 3  .or.  kk .lt. 1  .or.  kk .gt. nn) &
&go to 16
lmin = min0(lmn,nn)
lmax = min0(lmx,nn)
!
! Compute npts, lnp, avsq, av, and r.
!   Set npts to the closest lmin-1 nodes to k.
!
sum = 0.
npts(1) = kk
lm1 = lmin - 1
do 1 lnp = 2,lm1
  call getnp (x,y,iadj,iend,lnp, npts, ds,ierr)
1 sum = sum + ds
!
! Add additional nodes to npts until the relative increase
!   in ds is at least rtol.
!
do 2 lnp = lmin,lmax
  call getnp (x,y,iadj,iend,lnp, npts, rs,ierr)
  if ((rs-ds)/ds .le. rtol) go to 2
  if (lnp .gt. 6) go to 3
2 sum = sum + rs
!
! Use all lmax nodes in the least squares fit.  rs is
!   arbitrarily increased by 10 per cent.
!
rs = 1.1*rs
lnp = lmax + 1
!
! There are lnp-2 equations corresponding to nodes npts(2),
!   ...,npts(lnp-1).
!
3 avsq = sum/float(lnp-2)
av = sqrt(avsq)
r = sqrt(rs)
xk = x(kk)
yk = y(kk)
zk = z(kk)
if (lnp .lt. 7) go to 12
!
! Set up the first 5 equations of the augmented regression
!   matrix (transposed) as the columns of A, and zero out
!   the lower triangle (upper triangle of A) with Givens
!   rotations
!
do 5 i = 1,5
  np = npts(i+1)
  call setrm (xk,yk,zk,x(np),y(np),z(np),av,avsq, &
&r, a(1,i))
  if (i .eq. 1) go to 5
  im1 = i - 1
  do 4 j = 1,im1
    jp1 = j + 1
    l = 6 - j
    call srotg (a(j,j),a(j,i),c,s)
4 call srot (l,a(jp1,j),1,a(jp1,i),1,c,s)
5 continue
!
! Add the additional equations to the system using
!   THE LAST COLUMN OF a -- I .LE. lnp.
!
i = 7
6 if (i .eq. lnp) go to 8
  np = npts(i)
  call setrm (xk,yk,zk,x(np),y(np),z(np),av,avsq, &
&r, a(1,6))
  do 7 j = 1,5
    jp1 = j + 1
    l = 6 - j
    call srotg (a(j,j),a(j,6),c,s)
7 call srot (l,a(jp1,j),1,a(jp1,6),1,c,s)
  i = i + 1
  go to 6
!
! Test the system for ill-conditioning
!
8 dmin = amin1( abs(a(1,1)),abs(a(2,2)),abs(a(3,3)), &
&abs(a(4,4)),abs(a(5,5)) )
if (dmin .ge. dtol) go to 15
if (lnp .gt. lmax) go to 9
!
! Add another node to the system and increase r --
!   I .EQ. lnp
!
lnp = lnp + 1
if (lnp .le. lmax) call getnp (x,y,iadj,iend,lnp, &
&npts, rs,ierr)
r = sqrt(1.1*rs)
go to 6
!
! Stabilize the system by damping second partials --add
!   multiples of the first three unit vectors to the first
!   three equations.
!
9 do 11 i = 1,3
  a(i,6) = sf
  ip1 = i + 1
  do 10 j = ip1,6
10 a(j,6) = 0.
  do 11 j = i,5
    jp1 = j + 1
    l = 6 - j
    call srotg (a(j,j),a(j,6),c,s)
11 call srot (l,a(jp1,j),1,a(jp1,6),1,c,s)
go to 14
!
! 4 .LE. lnp .LE. 6 (2, 3, OR 4 EQUATIONS) -- FIT A PLANE TO
!   the data using the last 3 columns of A.
!
12 np = npts(2)
call setrm (xk,yk,zk,x(np),y(np),z(np),av,avsq, &
&r, a(1,4))
np = npts(3)
call setrm (xk,yk,zk,x(np),y(np),z(np),av,avsq, &
&r, a(1,5))
call srotg (a(4,4),a(4,5),c,s)
call srot (2,a(5,4),1,a(5,5),1,c,s)
if (lnp .eq. 4) go to 14
!
lm1 = lnp - 1
do 13 i = 4,lm1
  np = npts(i)
  call setrm (xk,yk,zk,x(np),y(np),z(np),av,avsq, &
&r, a(1,6))
  call srotg (a(4,4),a(4,6),c,s)
  call srot (2,a(5,4),1,a(5,6),1,c,s)
  call srotg (a(5,5),a(5,6),c,s)
13 call srot (1,a(6,5),1,a(6,6),1,c,s)
!
! Test the linear fit for ill-conditioning
!
14 dmin = amin1( abs(a(4,4)),abs(a(5,5)) )
if (dmin .lt. dtol) go to 17
!
! Solve the 2 by 2 triangular system for the derivatives
!
15 dy = a(6,5)/a(5,5)
dx = (a(6,4) - a(5,4)*dy)/a(4,4)/av
dy = dy/av
ier = lnp - 1
return
!
! n or k is out of range
!
16 ier = -1
return
!
! No unique solution due to collinear nodes
!
17 ier = -2
return
end subroutine gradl1

subroutine setrm (xk,yk,zk,xi,yi,zi,s1,s2,r, row)
implicit none
real, intent(in) :: xk, yk, zk, xi, yi, zi, s1, s2, r
real, intent(inout) :: row(6)
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   This routine sets up the i-TH row of an augmented RE-
! gression matrix for a weighted least-squares fit of A
! quadratic function Q(X,Y) to a set of data values Z where
! Q(xk,yk) = zk.  THE FIRST 3 COLUMNS (QUADRATIC TERMS) ARE
! scaled by 1/s2 and the fourth and fifth columns (linear
! terms) are scaled by 1/s1.  The weight is (r-d)/(r*d) if
! r .GT. d AND 0 IF r .LE. d, WHERE d IS THE DISTANCE
! between nodes i and K.
!
! Input parameters - xk,yk,zk - coordinates and data value
!                               at node K -- interpolated
!                               BY Q.
!
!                    xi,yi,zi - coordinates and data value
!                               at node i.
!
!                       s1,s2 - inverse scale factors.
!
!                           r - radius of influence about
!                               node K defining the weight.
!
!                         row - vector of length 6.
!
! Input parameters are not altered by this routine.
!
! Output parameter - row - vector containing a row of the
!                          augmented regression matrix.
!
! Modules referenced by setrm - none
!
! Intrinsic function called by setrm - sqrt
!
!***********************************************************
!
integer :: i
real :: dx, dy, dxsq, dysq, d, w, w1, w2
!
! Local parameters -
!
! i =    DO-LOOP INDEX
! dx =   xi - xk
! dy =   yi - yk
! dxsq = dx*dx
! dysq = dy*dy
! d =    DISTANCE BETWEEN NODES K AND i
! w =    WEIGHT ASSOCIATED WITH THE ROW
! w1 =   w/s1
! w2 =   w/s2
!
dx = xi - xk
dy = yi - yk
dxsq = dx*dx
dysq = dy*dy
d = sqrt(dxsq + dysq)
if (d .le. 0.  .or.  d .ge. r) go to 1
w = (r-d)/r/d
w1 = w/s1
w2 = w/s2
row(1) = dxsq*w2
row(2) = dx*dy*w2
row(3) = dysq*w2
row(4) = dx*w1
row(5) = dy*w1
row(6) = (zi - zk)*w
return
!
! Nodes K and i coincide or node i is outside of the radius
!   of influence.  Set row to the zero vector.
!
1 do 2 i = 1,6
2 row(i) = 0.
return
end subroutine setrm

subroutine getnp (x,y,iadj,iend,l, npts, ds,ier)
implicit none
integer, intent(in) :: iadj(*)
integer, intent(inout) :: iend(*)
integer, intent(in) :: l
integer, intent(inout) :: npts(l), ier
real, intent(in) :: x(*), y(*)
real, intent(inout) :: ds
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   Given a thiessen triangulation of N nodes and an array
! npts containing the indices of l-1 nodes ordered by
! Euclidean distance from npts(1), this subroutine sets
! npts(l) to the index of the next node in the sequence --
! the node, other than npts(1),...,npts(l-1), which is
! closest to npts(1).  Thus, the ordered sequence of K
! closest nodes to n1 (including n1) may be determined by
! K-1 CALLS TO getnp WITH npts(1) = n1 AND l = 2,3,...,K
! FOR K .GE. 2.
!   The algorithm uses the fact that, in a thiessen trian-
! gulation, the K-TH closest node to a given node n1 is A
! neighbor of one of the K-1 closest nodes to n1.
!
! Input parameters - x,y - vectors of length N containing
!                          the cartesian coordinates of the
!                          nodes.
!
!                   iadj - set of adjacency lists of nodes
!                          in the triangulation.
!
!                   iend - pointers to the ends of adjacency
!                          lists for each node in the TRI-
!                          angulation.
!
!                      l - number of nodes in the sequence
!                          ON OUTPUT.  2 .LE. l .LE. N.
!
!                   npts - ARRAY OF LENGTH .GE. l CONTAIN-
!                          ing the indices of the l-1 clos-
!                          est nodes to npts(1) in the first
!                          l-1 LOCATIONS.
!
! iadj and iend may be created by subroutine trmesh.
!
! Input parameters other than npts are not altered by this
!   routine.
!
! Output parameters - npts - updated with the index of the
!                            l-TH closest node to npts(1) in
!                            POSITION l UNLESS ier = 1.
!
!                       ds - squared Euclidean distance be-
!                            tween npts(1) and npts(l)
!                            UNLESS ier = 1.
!
!                      ier - error indicator
!                            ier = 0 IF NO ERRORS WERE EN-
!                                    countered.
!                            ier = 1 IF l IS OUT OF RANGE.
!
! Modules referenced by getnp - none
!
! Intrinsic function called by getnp - IABS
!
!***********************************************************
!
integer :: lm1, n1, i, ni, np, indf, indl, indx, nb
real :: x1, y1, dnp, dnb
!
! Local parameters -
!
! lm1 =     l - 1
! n1 =      npts(1)
! i =       npts INDEX AND DO-LOOP INDEX
! ni =      npts(i)
! np =      CANDIDATE FOR npts(l)
! indf =    iadj INDEX OF THE FIRST NEIGHBOR OF ni
! indl =    iadj INDEX OF THE LAST NEIGHBOR OF ni
! indx =    iadj INDEX IN THE RANGE indf,...,indl
! nb =      NEIGHBOR OF ni AND CANDIDATE FOR np
! x1,y1 =   COORDINATES OF n1
! dnp,dnb = SQUARED DISTANCES FROM n1 TO np AND nb,
!             respectively
!
lm1 = l - 1
if (lm1 .lt. 1) go to 4
ier = 0
n1 = npts(1)
x1 = x(n1)
y1 = y(n1)
!
! Mark the elements of npts
!
do 1 i = 1,lm1
  ni = npts(i)
  iend(ni) = -iend(ni)
1 continue
!
! CANDIDATES FOR np = npts(l) ARE THE UNMARKED NEIGHBORS
!   OF NODES IN npts.  np=0 IS A FLAG TO SET np TO THE
!   first candidate encountered.
!
np = 0
dnp = 0.
!
! Loop on nodes ni in npts
!
do 2 i = 1,lm1
  ni = npts(i)
  indf = 1
  if (ni .gt. 1) indf = iabs(iend(ni-1)) + 1
  indl = -iend(ni)
!
! Loop on neighbors nb of ni
!
  do 2 indx = indf,indl
    nb = iadj(indx)
    if (nb .eq. 0  .or.  iend(nb) .lt. 0) go to 2
!
! nb is an unmarked neighbor of ni.  Replace np if nb is
!   closer to n1 or is the first candidate encountered.
!
    dnb = (x(nb)-x1)**2 + (y(nb)-y1)**2
    if (np .ne. 0  .and.  dnb .ge. dnp) go to 2
    np = nb
    dnp = dnb
2 continue
npts(l) = np
ds = dnp
!
! Unmark the elements of npts
!
do i = 1,lm1
  ni = npts(i)
  iend(ni) = -iend(ni)
  end do
return
!
! l is out of range
!
4 ier = 1
return
end subroutine getnp

subroutine sfval (n, x, y, z, m, xi, yi, zi, iadj, iend, &
&zxzy, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: m, n
integer :: ist, j
!-----------------------------------------------------------------------
!                    Evaluation of the surface
!-----------------------------------------------------------------------
real :: x(n), y(n)
real, intent(in) :: z(n), xi(m), yi(m)
real, intent(inout) :: zi(m)
real, intent(in) :: zxzy(2,n)
integer, intent(in) :: iadj(*)
integer, intent(inout) :: iend(n)
!
if (n .lt. 3 .or. m .lt. 1) go to 20
!
ist = 1
do j = 1,m
   call intrc1 (n, xi(j), yi(j), x, y, z, iadj, iend, &
&1, zxzy, ist, zi(j), ierr)
   if (ierr .lt. 0) go to 30
end do
ierr = 0
return
!
!     Error return
!
20 ierr = 1
return
30 ierr = 2
return
end subroutine sfval

subroutine sfval2 (n, x, y, z, l, m, nrows, xi, yi, zi, &
&iadj, iend, zxzy, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: l, m, n, nrows
integer :: i, ist, j
!-----------------------------------------------------------------------
!                Evaluation of the surface over a grid
!-----------------------------------------------------------------------
real :: x(n), y(n)
real, intent(in) :: z(n), zxzy(2,n)
real, intent(in) :: xi(l), yi(m)
real, intent(inout) :: zi(nrows,m)
integer, intent(in) :: iadj(*)
integer, intent(inout) :: iend(n)
!
if (n .lt. 3 .or. l .lt. 1 .or. m .lt. 1 .or. nrows .lt. l) &
&go to 30
!
ist = 1
do j = 1,m
   do i = 1,l
      call intrc1 (n, xi(i), yi(j), x, y, z, iadj, iend, &
&1, zxzy, ist, zi(i,j), ierr)
      if (ierr .lt. 0) go to 40
   end do
end do
ierr = 0
return
!
!     Error return
!
30 ierr = 1
return
40 ierr = 2
return
end subroutine sfval2

subroutine intrc1 (n,px,py,x,y,z,iadj,iend,iflag, &
&zxzy, ist, pz,ier)
implicit none
integer, intent(in) :: n, iadj(*)
integer, intent(inout) :: iend(n)
integer, intent(in) :: iflag
integer, intent(inout) :: ist, ier
real, intent(in) :: px, py
real :: x(n), y(n)
real, intent(in) :: z(n), zxzy(2,n)
real, intent(out) :: pz
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   Given a triangulation of a set of points in the plane,
! this routine determines a piecewise cubic function F(x,y)
! which interpolates a set of data values and partial
! derivatives at the vertices.  F has continuous first
! derivatives over the mesh and extends beyond the mesh
! boundary allowing extrapolation.  Interpolation is exact
! for quadratic data.  The value of F at (px,py) is
! returned.  intrc1 is part of an interpolation package
! which provides routines to generate, update and plot the
! mesh.
!
! INPUT PARAMETERS -     n - NUMBER OF NODES IN THE MESH.
!                            n .GE. 3.
!
!                    px,py - coordinates of a point at which
!                            F is to be evaluated.
!
!                      x,y - vectors of coordinates of the
!                            nodes in the mesh.
!
!                        z - vector of data values at the
!                            nodes.
!
!                     iadj - set of adjacency lists of nodes
!                            in the mesh.
!
!                     iend - pointers to the ends of
!                            adjacency lists in iadj for
!                            each node in the mesh.
!
!                    iflag - option indicator
!                            iflag = 0 IF intrc1 IS TO
!                                      provide derivative
!                                      estimates (from
!                                      gradl1).
!                            iflag = 1 IF DERIVATIVES ARE
!                                      user provided.
!
!                     zxzy - 2 by n array whose columns
!                            contain estimated partial der-
!                            ivatives at the nodes (x par-
!                            tials in the first row) if
!                            iflag = 1, NOT USED IF iflag
!                            = 0.
!
!                      ist - index of the starting node in
!                            the search for a triangle con-
!                            TAINING (px,py).  1 .LE. ist
!                            .LE. n.  THE OUTPUT VALUE OF
!                            ist from a previous call may
!                            be a good choice.
!
! iadj and iend may be created by trmesh and derivative
!   estimates may be computed by gradl1 or gradg.
!
! Input parameters other than ist are not altered by this
!   routine.
!
! Output parameters - ist - index of one of the vertices of
!                           the triangle containing (px,py)
!                           UNLESS ier .LT. 0.
!
!                      pz - value of F at (px,py), or 0 if
!                           ier .LT. 0.
!
!                     ier - error indicator
!                           ier = 0 IF NO ERRORS WERE
!                                   encountered.
!                           ier = 1 IF NO ERRORS WERE EN-
!                                   countered and extrapola-
!                                   tion was performed.
!                           ier = -1 IF n, iflag, OR ist IS
!                                    out of range.
!                           ier = -2 IF THE NODES ARE COL-
!                                    linear.
!
! Modules referenced by intrc1 - trfind, tval,
!             (AND OPTIONALLY)   gradl1, getnp, setrm,
!                                srotg, srot
!
!***********************************************************
!
integer :: nn, i1, i2, i3, ierr, n1, n2, indx
real :: xp, yp, zx1, zy1, zx2, zy2, zx3, zy3, x1, y1, x2, y2, x3, &
&y3, z1, z2, z3, dum, dp, u, v, xq, yq, r1, r2, a1, a2, b1, b2, c1, &
&c2, f1, f2
!
! Local parameters -
!
! nn =                      LOCAL COPY OF n
! i1,i2,i3 =                VERTICES DETERMINED BY trfind
! ierr =                    ERROR FLAG FOR CALLS TO gradl1
!                             AND tval
! n1,n2 =                   ENDPOINTS OF THE CLOSEST BOUND-
!                             ary edge to P when P is out-
!                             side of the mesh boundary
! indx =                    iadj INDEX OF n1 AS A NEIGHBOR
!                             OF n2
! xp,yp =                   LOCAL COPIES OF THE COORDINATES
!                             OF P=(px,py)
! zx1,zy1,zx2,zy2,zx3,zy3 = x AND y DERIVATIVES AT THE
!                             vertices of a triangle T which
!                             contains P or at n1 and n2
! x1,y1,x2,y2,x3,Y3 =       x,y COORDINATES OF THE VERTICES
!                             of T or of n1 and n2
! Z1,Z2,Z3 =                DATA VALUES AT THE VERTICES OF T
! DUM =                     DUMMY VARIABLE FOR CALL TO tval
! DP =                      INNER PRODUCT OF n1-n2 AND P-n2
! U,V =                     x,y COORDINATES OF THE VECTOR
!                             n2-n1
! XQ,YQ =                   x,y COORDINATES OF THE CLOSEST
!                             boundary point to P when P is
!                             outside of the mesh boundary
! R1,R2 =                   BARYCENTRIC COORDINATES OF Q
!                             with respect to the line SEG-
!                             MENT n2-n1 CONTAINING Q
! A1,A2,B1,B2,C1,C2 =       CARDINAL FUNCTIONS FOR EVALUAT-
!                             ing the interpolatory surface
!                             AT Q
! F1,F2 =                   CUBIC FACTORS USED TO COMPUTE
!                             the cardinal functions
!
nn = n
pz = 0.
if (nn .lt. 3  .or.  iflag .lt. 0  .or.  iflag .gt. 1 &
&.or.  ist .lt. 1  .or.  ist .gt. nn) go to 11
xp = px
yp = py
!
! Find a triangle containing P if P is within the mesh
!   boundary
!
call trfind(ist,xp,yp,x,y,iadj,iend, i1,i2,i3)
if (i1 .eq. 0) go to 12
ist = i1
if (i3 .eq. 0) go to 3
if (iflag .ne. 1) go to 1
!
! Derivatives are user provided
!
zx1 = zxzy(1,i1)
zx2 = zxzy(1,i2)
zx3 = zxzy(1,i3)
zy1 = zxzy(2,i1)
zy2 = zxzy(2,i2)
zy3 = zxzy(2,i3)
go to 2
!
! Compute derivative estimates at the vertices
!
1 call gradl1(nn,i1,x,y,z,iadj,iend, zx1,zy1,ierr)
call gradl1(nn,i2,x,y,z,iadj,iend, zx2,zy2,ierr)
call gradl1(nn,i3,x,y,z,iadj,iend, zx3,zy3,ierr)
!
! Set local parameters for call to tval
!
2 x1 = x(i1)
y1 = y(i1)
x2 = x(i2)
y2 = y(i2)
x3 = x(i3)
y3 = y(i3)
z1 = z(i1)
z2 = z(i2)
z3 = z(i3)
call tval(xp,yp,x1,x2,x3,y1,y2,y3,z1,z2,z3,zx1,zx2, &
&zx3,zy1,zy2,zy3,0, pz,dum,dum,ierr)
if (ierr .ne. 0) go to 12
ier = 0
return
!
! P is outside of the mesh boundary.  Extrapolate to P by
!   passing a linear function of one variable THROUGH the
!   value and directional derivative (in the direction
!   P-Q) of the interpolatory surface (tval) at Q where
!   Q is the closest boundary point to P.
!
! Determine Q by traversing the boundary starting from
!   the rightmost visible node i1.
!
3 n2 = i1
!
! Set n1 to the last nonzero neighbor of n2 and compute DP
!
4 indx = iend(n2) - 1
n1 = iadj(indx)
x1 = x(n1)
y1 = y(n1)
x2 = x(n2)
y2 = y(n2)
dp = (x1-x2)*(xp-x2) + (y1-y2)*(yp-y2)
if (dp .le. 0.) go to 5
if ((xp-x1)*(x2-x1) + (yp-y1)*(y2-y1) .gt. 0.) go to 8
n2 = n1
go to 4
!
! n2 is the closest boundary point to P.  compute partial
!   derivatives at n2.
!
5 if (iflag .ne. 1) go to 6
zx2 = zxzy(1,n2)
zy2 = zxzy(2,n2)
go to 7
6 call gradl1(nn,n2,x,y,z,iadj,iend, zx2,zy2,ierr)
!
! Compute extrapolated value at P
!
7 pz = z(n2) + zx2*(xp-x2) + zy2*(yp-y2)
ier = 1
return
!
! The closest boundary point Q lies on n2-n1.  Compute
!   partials at n1 and n2.
!
8 if (iflag .ne. 1) go to 9
zx1 = zxzy(1,n1)
zy1 = zxzy(2,n1)
zx2 = zxzy(1,n2)
zy2 = zxzy(2,n2)
go to 10
9 call gradl1(nn,n1,x,y,z,iadj,iend, zx1,zy1,ierr)
call gradl1(nn,n2,x,y,z,iadj,iend, zx2,zy2,ierr)
!
! Compute Q, its barycentric coordinates, and the cardinal
!   functions for extrapolation
!
10 u = x2-x1
v = y2-y1
r1 = dp/(u**2 + v**2)
r2 = 1. - r1
xq = r1*x1 + r2*x2
yq = r1*y1 + r2*y2
f1 = r1*r1*r2
f2 = r1*r2*r2
a1 = r1 + (f1-f2)
a2 = r2 - (f1-f2)
b1 = u*f1
b2 = -u*f2
c1 = v*f1
c2 = -v*f2
!
! Compute the value of the interpolatory surface (tval)
!   AT Q
!
pz = a1*z(n1) + a2*z(n2) + b1*zx1 + b2*zx2 + &
&c1*zy1 + c2*zy2
!
! Compute the extrapolated value at P
!
pz = pz + (r1*zx1 + r2*zx2)*(xp-xq) + &
&(r1*zy1 + r2*zy2)*(yp-yq)
ier = 1
return
!
! n, iflag, or ist out of range
!
11 ier = -1
return
!
! Nodes are collinear
!
12 ier = -2
return
end subroutine intrc1

subroutine tval (x,y,x1,x2,x3,y1,y2,y3,z1,z2,z3,zx1, &
&zx2,zx3,zy1,zy2,zy3,iflag, w,wx,wy, &
&ier)
implicit none
integer, intent(in) :: iflag
integer, intent(inout) :: ier
real, intent(in) :: x, y, x1, x2, x3, y1, y2, y3, z1, z2, z3, zx1, &
&zx2, zx3, zy1, zy2, zy3
real, intent(inout) :: w, wx, wy
!
!***********************************************************
!
!                                               Robert Renka
!                                       Oak Ridge Natl. Lab.
!                                             (615) 576-5139
!
!   Given function values and first partial derivatives at
! the three vertices of a triangle, this routine determines
! a function w which agrees with the given data, returning
! the value and (optionally) first partial derivatives of w
! at a point (x,y) in the triangle.  The interpolation
! method is exact for quadratic polynomial data.  The
! triangle is partitioned into three subtriangles with
! equal areas.  w is cubic in each subtriangle and along
! the edges, but has only one continuous derivative across
! edges.  The normal derivative of w varies linearly along
! each outer edge.  The values and partial derivatives of w
! along a triangle edge depend only on the data values at
! the endpoints of the edge.  Thus the method yields C-1
! continuity when used to interpolate over a triangular
! grid.  This algorithm is due to C. L. Lawson.
!
! INPUT PARAMETERS -   x,y - COORDINATES OF A POINT AT WHICH
!                            w is to be evaluated.
!
!        x1,x2,x3,y1,y2,y3 - coordinates of the vertices of
!                            a triangle containing (x,y).
!
!                 z1,z2,z3 - function values at the vertices
!                            to be interpolated.
!
!              zx1,ZX2,ZX3 - x-derivative values at the
!                            vertices.
!
!              ZY1,ZY2,ZY3 - y-derivative values at the
!                            vertices.
!
!                    iflag - option indicator
!                            iflag = 0 IF ONLY w IS TO BE
!                                      computed.
!                            iflag = 1 IF w, wx, AND wy ARE
!                                      to be returned.
!
! Input parameters are not altered by this routine.
!
! OUTPUT PARAMETERS -   w - ESTIMATED VALUE OF THE INTERP-
!                           olatory function at (x,y) if
!                           ier = 0.  OTHERWISE w = 0.
!
!                   wx,wy - partial derivatives of w at
!                           (x,y) IF ier = 0 AND iflag = 1,
!                           UNCHANGED IF iflag .NE. 1, ZERO
!                           IF ier .NE. 0 AND iflag = 1.
!
!                     ier - error indicator
!                           ier = 0 IF NO ERRORS WERE
!                                   encountered.
!                           ier = 1 IF THE VERTICES OF THE
!                                   triangle are collinear.
!
! Modules referenced by tval - none
!
! Intrinsic function called by tval - AMIN1
!
!***********************************************************
!
integer :: i, ip1, ip2, ip3
real :: u(3), v(3), sl(3), area, xp, yp, r(3), rx(3), ry(3), &
&phi(3), phix(3), phiy(3), rmin, c1, c2, ro(3), rox(3), roy(3), &
&f(3), g(3), gx(3), gy(3), p(3), px(3), py(3), q(3), qx(3), qy(3), &
&a(3), ax(3), ay(3), b(3), bx(3), by(3), c(3), cx(3), cy(3)
!
! Local parameters -
!
! i =               DO-LOOP INDEX
! ip1,ip2,ip3 =     PERMUTED INDICES FOR COMPUTING RO, ROX,
!                     and roy
! u(K) =            x-COMPONENT OF THE VECTOR REPRESENTING
!                     the side opposite vertex K
! v(K) =            y-COMPONENT OF THE VECTOR REPRESENTING
!                     the side opposite vertex K
! sl(K) =           SQUARE OF THE LENGTH OF THE SIDE
!                     opposite vertex K
! area =            TWICE THE AREA OF THE TRIANGLE
! xp,yp =           x-x1, y-y1
! r(K) =            K-TH BARYCENTRIC COORDINATE
! rx(K),ry(K) =     x,y PARTIAL DERIVATIVES OF r(K)
! PHI(K)            r(K-1)*r(K+1) -- QUADRATIC
! PHIX(K),PHIY(K) = x,y PARTIALS OF PHI(K)
! rmin =            min(r1,r2,r3)
! C1,C2 =           FACTORS FOR COMPUTING RO
! RO(K) =           FACTORS FOR COMPUTING G -- CUBIC
!                     correction terms
! ROX(K),ROY(K) =   x,y PARTIALS OF RO(K)
! F(K) =            FACTORS FOR COMPUTING G, GX, AND GY --
!                     constant
! G(K) =            FACTORS FOR COMPUTING THE CARDINAL
!                     functions -- cubic
! GX(K),GY(K) =     x,y PARTIALS OF G(K)
! p(k) =            g(k) + phi(k)
! PX(K),PY(K) =     x,y PARTIALS OF P(K)
! q(k) =            g(k) - phi(k)
! QX(K),QY(K) =     x,y PARTIALS OF Q(K)
! A(K) =            CARDINAL FUNCTION WHOSE COEFFICIENT IS
!                     Z(K)
! AX(K),AY(K) =     x,y PARTIALS OF A(K) -- CARDINAL
!                     functions for wx and wy
! B(K) =            TWICE THE CARDINAL FUNCTION WHOSE
!                     coefficient is ZX(K)
! BX(K),BY(K) =     x,y PARTIALS OF B(K)
! C(K) =            TWICE THE CARDINAL FUNCTION WHOSE
!                     coefficient is ZY(K)
! CX(K),CY(K) =     x,y PARTIALS OF C(K)
!
u(1) = x3 - x2
u(2) = x1 - x3
u(3) = x2 - x1
!
v(1) = y3 - y2
v(2) = y1 - y3
v(3) = y2 - y1
!
do 1 i = 1,3
  sl(i) = u(i)*u(i) + v(i)*v(i)
1 continue
!
! area = 3-1 x 3-2
!
area = u(1)*v(2) - u(2)*v(1)
if (area .eq. 0.) go to 9
!
! r(1) = (2-3 x 2-(x,y))/area, r(2) = (1-(x,y) x 1-3)/area,
!   r(3) = (1-2 x 1-(x,y))/area
!
r(1) = (u(1)*(y-y2) - v(1)*(x-x2))/area
xp = x - x1
yp = y - y1
r(2) = (u(2)*yp - v(2)*xp)/area
r(3) = (u(3)*yp - v(3)*xp)/area
ier = 0
!
phi(1) = r(2)*r(3)
phi(2) = r(3)*r(1)
phi(3) = r(1)*r(2)
!
rmin = amin1(r(1),r(2),r(3))
if (rmin .ne. r(1)) go to 3
ip1 = 1
ip2 = 2
ip3 = 3
go to 5
3 if (rmin .ne. r(2)) go to 4
ip1 = 2
ip2 = 3
ip3 = 1
go to 5
4 ip1 = 3
ip2 = 1
ip3 = 2
!
5 c1 = rmin*rmin/2.
c2 = rmin/3.
ro(ip1) = (phi(ip1) + 5.*c1/3.)*r(ip1) - c1
ro(ip2) = c1*(r(ip3) - c2)
ro(ip3) = c1*(r(ip2) - c2)
!
f(1) = 3.*(sl(2)-sl(3))/sl(1)
f(2) = 3.*(sl(3)-sl(1))/sl(2)
f(3) = 3.*(sl(1)-sl(2))/sl(3)
!
g(1) = (r(2)-r(3))*phi(1) + f(1)*ro(1) - ro(2) + ro(3)
g(2) = (r(3)-r(1))*phi(2) + f(2)*ro(2) - ro(3) + ro(1)
g(3) = (r(1)-r(2))*phi(3) + f(3)*ro(3) - ro(1) + ro(2)
!
do i = 1,3
  p(i) = g(i) + phi(i)
  q(i) = g(i) - phi(i)
  end do
!
a(1) = r(1) + g(3) - g(2)
a(2) = r(2) + g(1) - g(3)
a(3) = r(3) + g(2) - g(1)
!
b(1) = u(3)*p(3) + u(2)*q(2)
b(2) = u(1)*p(1) + u(3)*q(3)
b(3) = u(2)*p(2) + u(1)*q(1)
!
c(1) = v(3)*p(3) + v(2)*q(2)
c(2) = v(1)*p(1) + v(3)*q(3)
c(3) = v(2)*p(2) + v(1)*q(1)
!
! w is a linear combination of the cardinal functions
!
w = a(1)*z1 + a(2)*z2 + a(3)*z3 + (b(1)*zx1 + b(2)*zx2 &
&+ b(3)*zx3 + c(1)*zy1 + c(2)*zy2 + c(3)*zy3)/2.
if (iflag .ne. 1) return
!
! Compute wx and wy
!
do i = 1,3
  rx(i) = -v(i)/area
  ry(i) = u(i)/area
  end do
phix(1) = r(2)*rx(3) + rx(2)*r(3)
phiy(1) = r(2)*ry(3) + ry(2)*r(3)
phix(2) = r(3)*rx(1) + rx(3)*r(1)
phiy(2) = r(3)*ry(1) + ry(3)*r(1)
phix(3) = r(1)*rx(2) + rx(1)*r(2)
phiy(3) = r(1)*ry(2) + ry(1)*r(2)
!
rox(ip1) = rx(ip1)*(phi(ip1) + 5.*c1) + &
&r(ip1)*(phix(ip1) - rx(ip1))
roy(ip1) = ry(ip1)*(phi(ip1) + 5.*c1) + &
&r(ip1)*(phiy(ip1) - ry(ip1))
rox(ip2) = rx(ip1)*(phi(ip2) - c1) + c1*rx(ip3)
roy(ip2) = ry(ip1)*(phi(ip2) - c1) + c1*ry(ip3)
rox(ip3) = rx(ip1)*(phi(ip3) - c1) + c1*rx(ip2)
roy(ip3) = ry(ip1)*(phi(ip3) - c1) + c1*ry(ip2)
!
gx(1) = (rx(2) - rx(3))*phi(1) + (r(2) - r(3))*phix(1) &
&+ f(1)*rox(1) - rox(2) + rox(3)
gy(1) = (ry(2) - ry(3))*phi(1) + (r(2) - r(3))*phiy(1) &
&+ f(1)*roy(1) - roy(2) + roy(3)
gx(2) = (rx(3) - rx(1))*phi(2) + (r(3) - r(1))*phix(2) &
&+ f(2)*rox(2) - rox(3) + rox(1)
gy(2) = (ry(3) - ry(1))*phi(2) + (r(3) - r(1))*phiy(2) &
&+ f(2)*roy(2) - roy(3) + roy(1)
gx(3) = (rx(1) - rx(2))*phi(3) + (r(1) - r(2))*phix(3) &
&+ f(3)*rox(3) - rox(1) + rox(2)
gy(3) = (ry(1) - ry(2))*phi(3) + (r(1) - r(2))*phiy(3) &
&+ f(3)*roy(3) - roy(1) + roy(2)
!
do i = 1,3
  px(i) = gx(i) + phix(i)
  py(i) = gy(i) + phiy(i)
  qx(i) = gx(i) - phix(i)
  qy(i) = gy(i) - phiy(i)
  end do
!
ax(1) = rx(1) + gx(3) - gx(2)
ay(1) = ry(1) + gy(3) - gy(2)
ax(2) = rx(2) + gx(1) - gx(3)
ay(2) = ry(2) + gy(1) - gy(3)
ax(3) = rx(3) + gx(2) - gx(1)
ay(3) = ry(3) + gy(2) - gy(1)
!
bx(1) = u(3)*px(3) + u(2)*qx(2)
by(1) = u(3)*py(3) + u(2)*qy(2)
bx(2) = u(1)*px(1) + u(3)*qx(3)
by(2) = u(1)*py(1) + u(3)*qy(3)
bx(3) = u(2)*px(2) + u(1)*qx(1)
by(3) = u(2)*py(2) + u(1)*qy(1)
!
cx(1) = v(3)*px(3) + v(2)*qx(2)
cy(1) = v(3)*py(3) + v(2)*qy(2)
cx(2) = v(1)*px(1) + v(3)*qx(3)
cy(2) = v(1)*py(1) + v(3)*qy(3)
cx(3) = v(2)*px(2) + v(1)*qx(1)
cy(3) = v(2)*py(2) + v(1)*qy(1)
!
! wx and wy are linear combinations of the cardinal
!   functions
!
wx = ax(1)*z1 + ax(2)*z2 + ax(3)*z3 + (bx(1)*zx1 + &
&bx(2)*zx2 + bx(3)*zx3 + cx(1)*zy1 + cx(2)*zy2 + &
&cx(3)*zy3)/2.
wy = ay(1)*z1 + ay(2)*z2 + ay(3)*z3 + (by(1)*zx1 + &
&by(2)*zx2 + by(3)*zx3 + cy(1)*zy1 + cy(2)*zy2 + &
&cy(3)*zy3)/2.
return
!
! Vertices are collinear
!
9 ier = 1
w = 0.
if (iflag .ne. 1) return
wx = 0.
wy = 0.
return
end subroutine tval

subroutine mfit(dimen,fitdeg,nfpols,nfpts, &
&fitcds,ncrows,fitvls,wts, &
&resids,error,fitiwk,fitdwk, &
&fiwkln,fdwkln,ireqd,dreqd)
implicit none
!
integer, intent(inout) :: nfpols, fitdeg
integer, intent(in) :: nfpts, dimen, fiwkln, fdwkln
integer, intent(inout) :: error, ireqd, dreqd
integer :: indstt, p, dimp1
integer, intent(in) :: ncrows
integer :: newstt, maxstt, alfstt, psistt, cstt, ssqstt, psiwid, &
&alfl
integer, intent(inout) :: fitiwk(fiwkln)
real, intent(inout) :: fitdwk(fdwkln), fitcds(ncrows,dimen)
real, intent(inout) :: fitvls(nfpts), resids(nfpts)
real, intent(in) :: wts(nfpts)
real :: scale
!
!     ***************
!     Purpose
!     -------
!
!     This subroutine constructs a least-squares  multinomial  fit  to
!     given data using a basis of orthogonal multinomials.
!
!     The data for the fit is given in the arrays fitcds, fitvls, and
!     wts. fitcds is a matrix, each row of which contains an observa-
!     tion point. fitvls is a singly-indexed array, each element of
!     which contains a function VALUE corresponding to an observation
!     point. wts is a singly-indexed array, each element of which is
!     a nonnegative weight for the corresponding observation.
!
!     The fit which is produced is a multinomial expressed in the form
!
!      C  psi  (X ,...,X     ) +...+ C       psi       (X ,...,X     )
!       1    1   1      dimen         nfpols    nfpols   1      dimen
!
!     WHERE THE VALUE OF  nfpols  WILL BE AS GIVEN (IF  fitdeg .LT. 0)
!     or  as  computed  by  mfit  to give a full-degree fit (in case
!     fitdeg  IS SPECIFIED .GE. 0).  THE ELEMENTS
!
!         psi  (X ,...,X     )
!            K   1      dimen
!
!     Form a basis for the multinomials which is orthogonal with
!     respect to the weights and observation points.
!
!     The extent of the fit can be specified in one of two ways.
!         IF THE PARAMETER fitdeg IS SET .GE. 0, THEN A COMPLETE BASIS
!         FOR THE MULTINOMIALS OF DEGREE =  fitdeg  WILL BE USED.  (AN
!         error will be  flagged  if  this  will  require  more  basis
!         multinomials  than  the  number  of  data  points which were
!         given.)
!         IF THE PARAMETER  fitdeg  IS .LT.  0, THEN  nfpols  WILL  BE
!         taken as the count of the number of basis multinomials to be
!         used for a partial-degree fit.  (An error will be flagged if
!         nfpols  .LT. 0.)
!
!     Variables
!     ---------
!
!      dimen  -- (INTEGER) -- (passed)
!         the number of variables.
!      fitdeg  - (INTEGER) -- (PASSED/RETURNED)
!         IGNORED IF .LT. 0.
!         IF fitdeg .GE. 0 THEN  fitdeg  IS  CHECKED  AGAINST  nfpts .
!         The value of  fitdeg  will be reduced if there is a basis of
!         MULTINOMIALS, ALL OF  DEGREE  .LE. fitdeg ,  OF  CARDINALITY
!         nfpts .  See  error  below.
!      nfpols  - (INTEGER) -- (PASSED/RETURNED)
!         IGNORED IF  fitdeg  .GE. 0.
!         IF  fitdeg .LT. 0 THEN THE VALUE OF nfpols WILL BE TAKEN  AS
!         the size of the basis of multinomials to be used in the fit.
!         nfpols  MUST SATISFY  nfpols  .LT. nfpts  AND nfpols .GE. 1
!         see  error  below.
!      nfpts  --- (INTEGER) -- (passed)
!         the number of data points to be used in the fit.
!         nfpts  MUST BE .GE. 1.  SEE  ERROR  BELOW.
!      fitcds  -- (real 2-subscript array) -- (passed)
!         fitcds (p,K) is the value of the K-TH variable at the  p-TH
!         data point.
!      ncrows  -- (INTEGER) -- (passed)
!         THE ROW DIMENSION  DECLARED  FOR   fitcds   IN  THE  CALLING
!         program.
!      fitvls  -- (real 1-subscript array) -- (passed)
!         fitvls (p) is the observed function VALUE of the p-TH  data
!         point.
!      wts  ----- (real 1-subscript array) -- (passed)
!         wts (p) is the weight attached to the p-TH data point.
!      resids  -- (real 1-subscript array) -- (returned)
!         resids (p) is the difference between the fitted function at
!         point p and  fitvls (p).
!      error  -- (INTEGER) -- (returned)
!       0 the desired least square multinomial fit was obtained.
!      -1 Only the first nfpols basis polynomials were obtained.
!         fitdeg is the degree of the fit.
!       1 IF  fitdeg  .GE. 0 BUT THERE IS AN INTERPOLATING MULTINOMIAL
!         OF SMALLER DEGREE OR IF fitdeg .LT. 0 AND nfpols .GT. nfpts.
!       2 IF  fitdeg  .LT. 0 AND  nfpols  .LE. 0.
!       3 IF  nfpts  .LT. 1 AND/OR  dimen  .LT. 1.
!       4 IF  IWKLEN  AND/OR  DWKLEN  IS TOO SMALL.  (SET  IWKLEN   TO
!         the value returned in  ireqd , and set  DWKLEN  to the value
!         returned in  dreqd  to resolve this problem.)
!      fitiwk  -- (integer, 1-subscript array) -- (returned)
!         an integer work array of length  fiwkln .  Upon return  from
!         mfit, fitiwk contains dimension and array LENGTH information.
!      fitdwk  -- (real 1-subscript array) -- (returned)
!         a real array of length  fdwkln  containing the coefficients
!         needed for computing the multinomial fit at a point.
!      fiwkln  -- (INTEGER) -- (passed)
!         the length of the array  fitiwk .
!      fdwkln  -- (INTEGER) -- (passed)
!         the length of the array  fitdwk .
!      ireqd  -- (INTEGER) -- (returned)
!         the length which the array  fitiwk  really needs to be.
!      dreqd  -- (INTEGER) -- (returned)
!         the length which the array  fitdwk  really needs to be.
!
!
!     Note. The 20 loop depends on the scaling scheme being used. The
!     residual scaling must be consistent with that defined by scalpm
!     AND scaldn.
!
!     mfit  calls  allot  and  gnrtp.
!     ****************
!
dimp1 = dimen + 1
!
!     ***************
!
call allot(fitdeg,nfpols,nfpts,dimen,fitiwk,fiwkln,ireqd,dreqd, &
&error)
if ( error .ge. 2 ) return
!
if ( fdwkln .ge. dreqd ) go to 10
   error = 4
   return
10 continue
!
psiwid = fitiwk(3)
alfl = fitiwk(4)
indstt = 1
newstt = 4 * nfpols + indstt
maxstt = 1
alfstt = maxstt + dimp1
cstt = alfstt + alfl
ssqstt = cstt + nfpols
psistt = ssqstt + nfpols
!
!     ***************
!
   call gnrtp(fitdeg,fitdwk(alfstt), &
&fitdwk(psistt),fitiwk(indstt), &
&fitiwk(newstt),fitdwk(ssqstt),fitcds, &
&ncrows,nfpols,dimen,nfpts,fitvls,resids, &
&fitdwk(cstt),psiwid,wts,alfl,dimp1, &
&fitdwk(maxstt),error)
!
!     ***************
!     Store the number of basis polynomials actually computed
!     by the modified routine incdg called by gnrtp.
!     ***************
!
fitiwk(1) = nfpols
!
!     ***************
!     Unscale the residuals for the benefit of the user.
!     ***************
!
scale = fitdwk(dimen + 1)
do p = 1,nfpts
  resids(p) = resids(p) * scale
end do
return
end subroutine mfit

subroutine allot(degree,npolys,npts,dimen,iwork,iwklen, &
&ireqd,dreqd,error)
implicit none
!
integer, intent(inout) :: ireqd, dreqd
integer :: alfl
integer, intent(inout) :: error, npolys, degree
integer, intent(in) :: dimen, npts
integer :: newstt, psiwid, kmxbas, startj, kjp1d2, index
integer, intent(in) :: iwklen
integer :: nplyt4
integer, intent(inout) :: iwork(iwklen)
!
!     ***************
!     Purpose
!     -------
!
!      Allot  checks for sufficiency the declared  dimensions  of  the
!     work  arrays  used by the subroutine  mfit .  Various sizes of
!     sub-arrays are computed and reported.
!
!     This routine is called by  mfit .  It is not  called  directly
!     by the user.
!
!     THIS ROUTINE CALLS   basiz   AND   mtable   FOR  THE  SUBSTANTIVE
!     computations.
!
!     Variables
!     ---------
!
!      degree  - (PASSED/RETURNED)
!         IGNORED IF .LT. 0.
!         IF  degree  .GE. 0 THEN  DEGREE IS CHECKED  AGAINST   npts .
!         The value of  degree  will be reduced if there is a basis of
!         MULTINOMIALS, ALL OF  degree .LE.  DEGREE ,  OF  CARDINALITY
!          npts
!      npolys  - (PASSED/RETURNED)
!         IGNORED IF  degree  .GE. 0.
!         IF degree .LT. 0 THEN THE VALUE OF npolys WILL BE TAKEN  AS
!         the size of the basis of multinomials to be used in the fit.
!         npolys  MUST SATISFY npolys .LT.  npts  AND  npolys  .GE. 1
!      npts  --- (PASSED)
!         the number of data points to be used in the fit.
!          npts  MUST BE .GE. 1.
!      dimen  -- (PASSED)
!         the number of variables.
!      iwork  -- (RETURNED)
!         an integer work array of length at least
!            IF  degree  .GE. 0 THEN
!               4*BINOMIAL( dimen + degree , dimen )
!                  +( dimen )*( DEGREE )
!            ELSE
!               4*BINOMIAL( dimen +D,D)+( dimen )*D
!         where D is the minimum cardinality  of  a  basis  of  degree
!          degree  such that
!            BINOMIAL( dimen +abs( degree ), dimen ) .GE.  npolys
!      iwklen  - (PASSED)
!         the length of  iwork
!      ireqd  -- (RETURNED)
!         THE SIZE OF THE INTEGER WORK ARRAY REQUIRED BY  mfit   FOR
!         the fit specified by the 4 input parameters.
!      dreqd  -- (RETURNED)
!         the size of the double  precision  work  array  required  by
!          mfit  for the fit specified by the 4 input parameters.
!      error  -- (returned)
!       0 IF  npolys ,  dimen ,   DEGREE ,   npts   AND   iwklen   ARE
!         valid and consistent with each other.
!       1 IF  degree  .GE. 0 BUT THERE IS AN INTERPOLATING MULTINOMIAL
!         OF SMALLER DEGREE OR IF  degree .LT. 0 AND  npolys .GT. npts
!       2 IF  degree  .LT. 0 AND  npolys  .LE. 0
!       3 IF  npts  .LT. 1 AND/OR  dimen  .LT. 1
!       4 if  iwklen  is too small (set  iwklen  to the value returned
!         in  ireqd  to resolve this problem)
!
!     NOTE THAT  DEGREE ,  npolys ,  psiwid  AND  alfl   ARE  RETURNED
!     in  iwork (1-4), respectively.
!
!     Date last modified
!     ---- ---- --------
!     December 10, 1984
!     ****************
!
!     ***************
!     basiz  computes the size of the basis (and auxiliary sizes)
!     based primarily upon the degree, number of  fitting points,
!     and the dimension.
!     ***************
!
call basiz(degree,npts,dimen,npolys,error)
if ( error .ge. 2 ) return
ireqd = 4 * npolys + degree * dimen
if ( iwklen .ge. ireqd ) go to 5
   error = 4
   return
5 newstt = 4 * npolys + 1
!
!     ***************
!     Set up useful indexing arrays
!          iwork(1) ,..., iwork(newstt-1)
!     and
!          iwork(newstt ,..., iwork(newstt+dimen*degree)
!     ***************
!
call mtable(degree,dimen,npolys,iwork,iwork(newstt),alfl)
iwork(1) = degree
iwork(2) = npolys
!
!     ***************
!     Force  alfl  to be at least 1 so that dimension statements
!     using  alfl  do not bomb.
!     ***************
!
if ( alfl .gt. 1 ) alfl = alfl - 1
iwork(4) = alfl
!
!     ***************
!     The following is a section of code for setting up the
!     storage  management of the  psi  array.  There  is  A
!     complicated dovetailing formula used to pack information
!     into  psi  without leaving gaps.
!
!     ARRAY          LENGTH
!     -----          ------
!      MAXABS         dimen  + 1
!      ALPHA          alfl
!      C              npolys
!      SUMSQS         npolys
!
!     The number of columns in  psi ,  psiwid , is determined by
!     psiwid  =  npolys  + 1 - (THE SMALLEST M SUCH THAT ALPHA(J,M)
!                                   IS NONZERO AND J .GE. npolys)
!     this insures that if the user extends the basis, all the  psi
!     required will certainly be stored
!
!     IF degree( npolys ) .LE. 2 THEN                      (CASE 1)
!       psiwid  =  npolys
!     ELSE
!       IF K =  dimen  THEN                                (CASE 2)
!         psiwid  =  npolys
!                    -  NEWKJ( 1 , degree(npolys)-1 )  + 1
!       ELSE
!            psiwid  =  npolys
!                      + 1
!                      - (
!                         The smaller of
!                           NEWKJ(K+1,degree(npolys)-2)    (CASE 3)
!                         and
!                           INDEXS(3,npolys)               (CASE 4)
!                        )
!
if ( degree .gt. 2 ) go to 10
!
!     ***************
!     Case 1
!     ***************
!
   psiwid = npolys
go to 40
10 nplyt4 = 4 * npolys
!
!     ***************
!     kmxbas  IS K
!                 npolys
!     ***************
!
   kmxbas = iwork(nplyt4 - 2)
!
   if ( kmxbas .ne. dimen ) go to 20
!
!     ***************
!     Case 2
!     ***************
!
      psiwid = npolys - iwork(4 * npolys - 1)
   go to 40
!
!     ***************
!     index =  newkj( k      + 1 , degree(npolys-2) )
!                      npolys
!     ***************
!
20 index = nplyt4 + (degree - 3) * dimen + kmxbas + 1
      kjp1d2 = iwork(index)
!
!     ***************
!     startj  =  indexs(3,npolys)
!     ***************
!
      startj = iwork(nplyt4 - 1)
      if ( startj .gt. kjp1d2 ) go to 30
!
!     ***************
!     Case 4
!     ***************
!
         psiwid = npolys - startj + 1
      go to 40
!
!     ***************
!     Case 3
!     ***************
!
30 psiwid = npolys - kjp1d2 + 1
40 iwork(3) = psiwid
dreqd = 2 * npolys + dimen + 1 + npts * psiwid + alfl
return
end subroutine allot

subroutine basiz(degree,npts,dimen,npolys,error)
implicit none
!
integer :: top, bot
integer, intent(inout) :: degree
integer, intent(in) :: npts, dimen
integer, intent(inout) :: npolys
integer, intent(out) :: error
integer :: i, rowlen
!
!     ***************
!     Purpose
!     -------
!
!     IF  degree  .GE. 0 THEN
!       find the size of a basis required either to
!       1) approximate the data with a polynomial of degree
!          given by the parameter  degree
!       or to
!       2) SPAN THE SPACE OF POLYNOMIALS OF degree .LE. THE
!          smallest degree of polynomial which interpolates the
!          data.
!       IN CASE 1  error  = 0.
!       IN CASE 2  error  = 1.
!     ELSE
!       IF  npolys  .GE. 1 THEN
!          IF npolys .GT. npts THEN
!             SET  npolys  =  npts , FIND THE SMALLEST DEGREE OF A
!             polynomial  which  interpolates  the  data,  and set
!              error  = 1.
!          ELSE
!             find the largest degree  degree  of a polynomial  in
!             a  basis of  npolys  polynomials generated according
!             TO OUR ORDERING AND SET  error  = 0.
!       ELSE
!           error  = 2
!
!     This subroutine is called by  allot .  It is not  called  by
!     the user directly.
!
!     Date last modified
!     ---- ---- --------
!     October 16, 1984
!     ****************
!
error = 0
if ( npts .ge. 1 .and. dimen .ge. 1 ) go to 10
   error = 3
   return
!
10 continue
if ( degree .lt. 0 ) go to 30
!
  rowlen = 1
  npolys = 1
  top = dimen - 1
  bot = 0
  if ( degree .lt. 1 )  go to 30
    do i=1,degree
      top = top + 1
      bot = bot + 1
      rowlen = (rowlen*top)/bot
      npolys = npolys + rowlen
    end do
!
30 continue
if ( npolys .ge. 1 ) go to 40
      error = 2
      return
40 continue
if ( npolys .lt. npts ) go to 50
      npolys = npts
      error = 1
50 continue
rowlen = 1
i = 1
degree = 0
top = dimen - 1
bot = 0
60 continue
if ( i .ge. npolys )  go to 70
    top = top + 1
    bot = bot + 1
    rowlen = (rowlen*top)/bot
    i = i + rowlen
    degree = degree + 1
    if ( i .lt. npolys )  go to 60
70 continue
return
end subroutine basiz

subroutine mtable(degree,dimen,npolys,indexs,newkj,alflp1)
implicit none
!
integer :: j, kj, curdeg, jprime, nwithk, i, curm1, ralen, dimm1, &
&dimm2
integer, intent(in) :: npolys, dimen, degree
integer, intent(out) :: alflp1
integer :: dimp1
integer, intent(inout) :: indexs(4,npolys), newkj(dimen,degree)
!
!     ***************
!     Purpose
!     -------
!
!     Tabulate  JP  and  kj  for each  j
!
!     Variables
!     ---------
!
!      alflp1  -- (INTEGER) -- (passed)
!         the length required for array  ALPHA , plus one
!      degree  -- (INTEGER) -- (passed)
!         the degree of the polynomial to be fitted
!      dimen  -- (INTEGER) -- (passed)
!         number of independent variables
!      indexs  -- (integer, 2-subscript array) -- (returned)
!          indexs (1, j )   IS    JP ,    indexs (2, j )   IS     kj ,
!          indexs (3, j )  is the first nonzero recurrence coefficient
!         in  alpha  and  indexs (4, j ) is its location in  alpha .
!      newkj  -- (integer, 2-subscript array) -- (returned)
!          newkj ( K , D ) IS THE FIRST MONOMIAL OF DEGREE  D   HAVING
!          kj = k .
!      npolys  -- (INTEGER) -- (passed)
!         NUMBER  OF  MONOMIALS  OF  degree  .LE.  ORDER  IN   dimen
!         independent variables.
!
!     This subprogram can be coded (excluding the part for calculating
!      indexs (3, j )  AND   indexs (4, j )) MENTALLY MORE EFFICIENTLY
!     but computationally less efficiently as
!
!         j = 2
!         do 5 kj = 1,dimen
!           newkj(kj,1) = kj + 1
!           indexs(1,j) = 1
!           indexs(2,j) = kj
!           j = j + 1
!      5  continue
!         do 10 curdeg = 2,degree
!           do 10 kj = 1,dimen
!             jprime = newkj(kj,curdeg - 1)
!             newkj(kj,curdeg) = j
!             nwithk = comb(dimen + curdeg - kj - 1,curdeg - 1)
!             do 10 i = 1,nwithk
!               indexs(1,j) = jprime
!               indexs(2,j) = kj
!               jprime = jprime + 1
!               j = j + 1
!     10  continue
!
!     Where COMB(N,kj) is N-factorial / ((N-kj)-factorial * kj-factorial
!     here we make use of the recurrence relations
!
!       COMB(dimen+curdeg-2,curdeg-1)
!
!            (dimen+curdeg-2)*COMB(dimen+curdeg-3,curdeg-2)
!          = ----------------------------------------------
!                              (curdeg-1)
!
!     And
!
!       COMB(dimen+curdeg-kj-1,curdeg-1)
!
!            (dimen-kj+1)*COMB(dimen+curdeg-kj,curdeg-1)
!          = -------------------------------------------
!                         (dimen+curdeg-kj)
!
!
!     Date last modified
!     ---- ---- --------
!     October 16, 1984
!     ****************
!
alflp1 = 1
!
!     ***************
!     Set  indexs (4,1) to 1 so that  ALFL - indexs (4,1)+1 is the
!     NUMBER OF COLUMNS REQUIRED FOR  PSI  FOR  npolys =1  ( ALFL
!     IS DEFINED IN THE MAINLINE TO BE  alflp1 -1 IF alflp1 .GT. 1
!     and  alflp1  otherwise.
!     ***************
!
indexs(4,1) = 1
!
if ( npolys .eq. 1 ) return
j = 2
do 10 kj = 1,dimen
   newkj(kj,1) = kj + 1
   indexs(1,j) = 1
   indexs(2,j) = kj
   indexs(3,j) = 1
   indexs(4,j) = alflp1
   alflp1 = alflp1 + j - 1
   if ( j .eq. npolys ) return
10 j = j + 1
if ( degree .eq. 1 ) return
ralen = 1
dimm1 = dimen - 1
dimm2 = dimen - 2
dimp1 = dimen + 1
do 70 curdeg = 2,degree
   curm1 = curdeg - 1
   ralen = (ralen * (dimm2 + curdeg)) / curm1
   nwithk = ralen
   kj = 1
20 jprime = newkj(kj,curm1)
   newkj(kj,curdeg) = j
   if ( kj .eq. dimen ) go to 60
      do 50 i = 1,nwithk
         indexs(1,j) = jprime
         indexs(2,j) = kj
!
!     ***************
!     CALCULATE  indexs (3, j ),  indexs (4, j )
!     ***************
!
         if ( kj .lt. indexs(2,jprime) ) go to 30
            indexs(3,j) = indexs(1,jprime)
            go to 40
30 indexs(3,j) = newkj(1,curdeg - 1)
40 indexs(4,j) = alflp1
         alflp1 = alflp1 + j - indexs(3,j)
         if ( j .eq. npolys ) return
!
         jprime = jprime + 1
50 j = j + 1
      kj = kj + 1
      nwithk = (nwithk * (dimp1 - kj)) / (dimen + curdeg - kj)
      go to 20
60 indexs(1,j) = jprime
   indexs(2,j) = dimen
   indexs(3,j) = indexs(1,jprime)
   indexs(4,j) = alflp1
   alflp1 = alflp1 + j - indexs(3,j)
   if ( j .eq. npolys ) return
70 j = j + 1
return
end subroutine mtable

subroutine gnrtp(degree,alpha,psi,indexs, &
&newkj,sumsqs,coord,ncrows,npolys, &
&dimen,npts,f,z,c,psiwid,weight, &
&alfl,dimp1,maxabs,error)
implicit none
integer, intent(in) :: ncrows
!
integer, intent(inout) :: degree
integer, intent(in) :: dimen
integer, intent(inout) :: npolys
integer, intent(in) :: npts
integer :: k
integer, intent(in) :: psiwid, alfl
integer :: p, sttdeg, onplys
integer, intent(inout) :: error
integer :: dimp1
integer, intent(in) :: indexs(4,npolys), newkj(dimen,degree)
real, intent(inout) :: psi(npts,psiwid), alpha(alfl), f(npts)
real, intent(inout) :: coord(ncrows,dimen), maxabs(dimp1)
real, intent(in) :: weight(npts)
real, intent(inout) :: z(npts), sumsqs(npolys), c(npolys)
real :: runtot, rntot1
!
!     ***************
!     Purpose
!     -------
!
!     The multinomial fit is generated incrementally, a basis  element
!     at a time.  This subroutine starts the process off by setting up
!     the first basis element, scaling the  data,  finding  the  first
!     coefficient,  and  initializing  the  work array z.  gnrtp  then
!     calls  incdg  if more than one basis element is required.
!
!     This subroutine is called by  mfit .  It is not called by  the
!     user.
!
!     This subroutine calls  scalpm ,  scaldn , and  incdg .
!
!
!     Modified by A.H. Morris (NSWC)
!     ****************
!
!     ***************
!     Set up the scaling.
!     ***************
!
do 10 k = 1,dimen
   call scalpm(coord(1,k),npts,maxabs(k))
10 call scaldn(coord(1,k),npts,maxabs(k))
call scalpm(f,npts,maxabs(dimp1))
call scaldn(f,npts,maxabs(dimp1))
!
!     ***************
!      sumsqs (1) = (1,1)
!     c  = (f,1) / (1,1)
!      1
!     ***************
!
runtot = 0.0
rntot1 = 0.0
do 20 p = 1,npts
   psi(p,1) = 1.0
   rntot1 = rntot1 + weight(p)
20 runtot = runtot + f(p) * weight(p)
sumsqs(1) = rntot1
c(1) = runtot / rntot1
!
!     ***************
!     z = f - c
!              1
!     ***************
!
do 30 p = 1,npts
30 z(p) = f(p) - c(1)
!
if ( npolys .eq. 1 ) return
sttdeg = 1
onplys = 1
!
call incdg(degree,alpha,psi,indexs,newkj,sumsqs, &
&coord,ncrows,npolys,dimen,npts,f,z,c,psiwid, &
&weight,alfl,onplys,sttdeg,error)
return
end subroutine gnrtp

subroutine incdg(degree,alpha,psi,indexs,newkj, &
&sumsqs,coord,ncrows,npolys, &
&dimen,npts,f,z,c,psiwid,weight, &
&alfl,onplys,sttdeg,error)
implicit none
integer, intent(in) :: ncrows
!
integer :: jprime, p, j, curdeg, kj, kjp, l, jpm1, jm1
integer :: m, start, jindex, jpindx, q, j3, j1, j1mj2
integer, intent(inout) :: error
integer :: j0mj1, j1m1, starta
integer, intent(in) :: onplys
integer :: onpp1
integer, intent(inout) :: sttdeg
integer :: index1, index2
integer, intent(inout) :: degree, npolys
integer, intent(in) :: npts, dimen, psiwid, alfl
integer, intent(in) :: indexs(4,npolys), newkj(dimen,degree)
real, intent(inout) :: alpha(alfl)
real, intent(in) :: coord(ncrows,dimen)
real, intent(inout) :: psi(npts,psiwid)
real, intent(inout) :: sumsqs(npolys), c(npolys)
real, intent(in) :: f(npts), weight(npts)
real, intent(inout) :: z(npts)
real :: arc, runtot, rntot1, rntot2
!
!     ***************
!     Purpose
!     -------
!
!     The multinomial fit is generated incrementally, a basis  element
!     at a time.  This subroutine continues the process started off by
!      gnrtp .
!
!     This subroutine is called by  gnrtp  and not by the user.
!
!
!     Modified by A.H. Morris (NSWC)
!
!     ****************
!
if ( onplys .ge. 1 .and. sttdeg .ge. 1 ) go to 10
   error = 6
return
10 if ( indexs(2,onplys) .eq. dimen ) go to 20
      curdeg = sttdeg
   go to 30
20 curdeg = sttdeg + 1
30 onpp1 = onplys + 1
do 170 j = onpp1,npolys
   jprime = indexs(1,j)
   jindex = j - ((j - 1) / psiwid) * psiwid
   jpindx = jprime - ((jprime - 1) / psiwid) * psiwid
   kj = indexs(2,j)
   start = indexs(3,j)
   m = start
   starta = indexs(4,j) - start
   if ( curdeg .eq. 1 ) go to 100
   kjp = indexs(2,jprime)
   j1 = newkj(kj,curdeg - 1)
!
!     ***************
!     Calculate those  alpha ( j , m ) that can be calculated from
!     previously calculated alphas.
!     ***************
!
   if ( kj .lt. kjp ) go to 50
!
!     ***************
!     First calculate those between  JPP  and the end of 2 rows back.
!     Calculate  alpha ( j , JPP )
!     ***************
!
   index1 = indexs(4,j)
   alpha(index1) = sumsqs(jprime) / sumsqs(start)
!
   m = start + 1
   j3 = newkj(1,curdeg - 1) - 1
   if ( m .gt. j3 ) go to 50
!
!     ***************
!     curdeg .GT. 2 IF CONTROL HAS PASSED THE BRANCHES IN THE 3-RD
!     previous and 8-TH previous statements.
!     ***************
!
      j1mj2 = j1 - newkj(kj,curdeg - 2)
!
      do 40 l = m,j3
         q = j1mj2 + l
         index1 = starta + l
         index2 = indexs(4,q) - indexs(3,q) + jprime
40 alpha(index1) = alpha(index2) * sumsqs(jprime) / &
&sumsqs(l)
!
!     ***************
!     Calculate  alpha ( j , m ) for  m  between the 2
!     ranges calculated before using
!
!        alpha ( j , l ) = (X  *  psi  ,psi )  / (psi ,psi )
!                             K      JP    l         l    l
!                              j
!     ***************
!
   m = j3 + 1
50 if ( jprime .eq. j1 ) go to 100
      if ( kj .eq. 1 ) go to 80
      j1m1 = j1 - 1
      do 70 l = m,j1m1
         runtot = 0.0
         do 60 p = 1,npts
            index1 = l - ((l - 1) / psiwid) * psiwid
60 runtot = runtot + coord(p,kj) * psi(p,jpindx) * &
&psi(p,index1) * weight(p)
         index1 = starta + l
70 alpha(index1) = runtot / sumsqs(l)
!
!     ***************
!     Calculate  alpha ( j , m ) for  m  between
!      newkj ( kj , curdeg  - 1)  AND
!      JP  - 1.
!     ***************
!
80 j0mj1 = newkj(kj,curdeg) - j1
      jpm1 = jprime - 1
      do 90 l = j1,jpm1
         q = j0mj1 + l
         index1 = starta + l
         index2 = indexs(4,q) - indexs(3,q) + jprime
90 alpha(index1) = alpha(index2) * sumsqs(jprime) / &
&sumsqs(l)
      m = jprime
!
!     ***************
!     Calculate the remaining  alpha ( j , m ) from
!
!      alpha ( j , l ) = (X   * psi  ,psi ) / (psi ,psi )
!                          K       JP    l        l    l
!                           j
!     ***************
!
100 jm1 = j - 1
   do 120 l = m,jm1
      runtot = 0.0
      do 110 p = 1,npts
         index1 = l - ((l - 1) / psiwid) * psiwid
110 runtot = runtot + coord(p,kj) * psi(p,jpindx) * &
&psi(p,index1) * weight(p)
      index1 = starta + l
120 alpha(index1) = runtot / sumsqs(l)
!
!     ***************
!     Now calculate the  psi (p,j),  sumsqs (j) and  c (j) using
!
!                          j-1
!     psi  = X  * psi   -  SUM   alpha(j,l) * psi
!        j    K      JP    l=JPP                 l
!
!     sumsqs  = (psi ,psi )
!           j       j    j
!
!     c  = (z,psi )
!      j         j
!     ***************
!
130 jm1 = j - 1
    arc = 0.0
    rntot1 = 0.0
    rntot2 = 0.0
    do 150 p = 1,npts
        runtot = coord(p,kj) * psi(p,jpindx)
        do 140 l = start,jm1
           index1 = starta + l
           index2 = l - ((l - 1) / psiwid) * psiwid
140 runtot = runtot - alpha(index1) * psi(p,index2)
        psi(p,jindex) = runtot
        arc = arc + psi(p,index2) * psi(p,jindex) * &
&weight(p)
        rntot1 = rntot1 + psi(p,jindex) * psi(p,jindex) * &
&weight(p)
150 rntot2 = rntot2 + z(p) * psi(p,jindex) * weight(p)
    if (arc * arc .ge. sumsqs(jm1) * rntot1 * 1.e-03) &
&go to 200
    sumsqs(j) = rntot1
    c(j) = rntot2 / rntot1
!
!     ***************
!     Calculate the new  z ( p ) and the new  SSRES  using
!
!     z = z - c  * psi
!              j      j
!     ***************
!
    do 160 p = 1,npts
160 z(p) = z(p) - c(j) * psi(p,jindex)
    sttdeg = curdeg
170 if ( kj .eq. dimen ) curdeg = curdeg + 1
return
!
!     ***************
!     The j-TH basis multinomial cannot be computed accurately.
!     Only j - 1 basis multinomials are generated.
!     ***************
!
200 error = -1
degree = sttdeg
npolys = jm1
return
end subroutine incdg

subroutine scalpm(coord,npts,maxabs)
implicit none
!
integer, intent(in) :: npts
integer :: p
real, intent(out) :: maxabs
real :: a
real, intent(in) :: coord(npts)
!
!     ***************
!     Purpose
!     -------
!
!     Find scaling PARAMETER(S) for the problem. If the scaling scheme
!     is changed, all four of the following would have to be changed
!
!     1)  scalpm  - find the scaling parameters
!     2)  scaldn  - scale the problem data
!     3)  the scaling of the residuals in  mfit
!     4)  the scaling performed in  meval1
!
!     This subroutine is called by  gnrtp .  It is not called  by  the
!     user.
!
!     The scaling which  it  defines  must  be  coordinated  with  the
!     scaling  of residuals which is carried out toward the end of the
!     subroutine  mfit.  The scaling must also be coordinated with the
!     scaling performed in the 10 loop  and  at statements 40 and 50
!     (with the scale factor maxabs(DIMP1)) in  meval1.
!
!     ****************
!
maxabs = 0.0
do 10 p = 1,npts
   a = abs(coord(p))
10 if ( a .gt. maxabs ) maxabs = a
return
end subroutine scalpm

subroutine scaldn(coord,npts,maxabs)
implicit none
!
integer, intent(in) :: npts
integer :: p
real, intent(in) :: maxabs
real, intent(inout) :: coord(npts)
!
!     ***************
!     Purpose
!     -------
!
!     Carry out the data-scaling which is defined  by  the  subroutine
!     scalpm .
!
!     This subroutine is called by  gnrtp .  It is not called  by  the
!     user.
!
!     The scaling which this routine carries out  must  be  consistent
!     with the scaling in the subroutines mfit and meval1.
!
!     ****************
!
if ( maxabs .eq. 0.0e+00 ) return
   do 10 p = 1,npts
10 coord(p) = coord(p) / maxabs
   return
end subroutine scaldn

subroutine meval(dimen,evldeg,nepols,nepts,evlcds,nerows,evlvls, &
&error,fitiwk,fitdwk,fiwkln,fdwkln,temp)
implicit none
integer, intent(in) :: nerows
!
integer, intent(in) :: fiwkln, fdwkln
integer, intent(inout) :: nepols
integer, intent(in) :: nepts, dimen
integer, intent(inout) :: error
integer :: maxstt, alfstt, cstt
integer :: gbasiz, alfl, dimp1
integer, intent(in) :: evldeg
integer :: top, bot, curdeg, psistt
integer, intent(in) :: fitiwk(fiwkln)
real, intent(inout) :: fitdwk(fdwkln)
real, intent(in) :: evlcds(nerows,dimen)
real, intent(inout) :: evlvls(nepts), temp(dimen)
!
!     ***************
!     Purpose
!     -------
!
!     This subroutine  evaluates  the  least-squares  multinomial  fit
!     which has been previously produced by  mfit .  Either the full
!     multinomial as produced may be evaluated,  or  only  an  initial
!     segment thereof.  As in the case with  mfit , it is possible
!     (1) to specify multinomials of a full given degree, or
!     (2) to specify  the  number  of  orthogonal  basis  elements  to
!         achieve a partial-degree fit.
!
!     In case (1), the  desired  degree  is  given  as  the  value  of
!     evldeg   (WHICH  MUST  BE  NONNEGATIVE AND NOT GREATER THAN THE
!     value used for  FITDEG  in  mfit ), and the parameter  nepols
!     will  be  set  by  meval  to specify the number of basis elements
!     REQUIRED. IF  evldeg  .LT.  FITDEG   IS  GIVEN,  THEN  ONLY  THE
!     initial  portion of the fitting multinomial (of degree  evldeg )
!     will be evaluated.
!
!     In case (2),  evldeg  is to be set negative, in which  case  the
!     VALUE  OF   nepols  (WHICH MUST BE POSITIVE AND NOT GREATER THAN
!     THE VALUE USED FOR   NFPOLS   IN   mfit )  WILL  BE  TAKEN  AS
!     defining  the  initial  portion of the fitting multinomial to be
!     evaluated.
!
!     IF  nepols  =  NFPOLS  (WITH  evldeg  .LT.  0),  OR   evldeg   =
!     FITDEG  (WITH   evldeg   .GT.  0),  THEN  THE  FULL  MULTINOMIAL
!     generated by  mfit  will be evaluated.
!
!     THE  EVALUATION  WILL  TAKE  PLACE  FOR  EACH  OF   THE   POINTS
!     (collection  of  variable  values)  given as a row of the matrix
!      evlcds .  The  values  produced  from  the  full,  or  partial,
!     multinomial will be placed in the array  evlvls .
!
!     Variables
!     ---------
!
!      dimen  -- (INTEGER) -- (passed)
!         the number of variables.
!      evldeg  -- (INTEGER) -- (passed)
!         IF  evldeg  .LT. 0, THEN THIS PARAMETER WILL BE IGNORED.
!         IF  evldeg  .GE. 0, THEN THE VALUE OF  evldeg  MUST  SATISFY
!         evldeg  .LE. (THE  DEGREE  OF THE APPROXIMATING MULTINOMIAL
!         generated in  mfit ).  In this case  evldeg  will  specify
!         the degree of the initial portion of the fitting multinomial
!         to be evaluated.
!      nepols  -- (INTEGER) -- (PASSED/RETURNED)
!         IF  evldeg  .GE. 0, THEN THIS PARAMETER WILL BE IGNORED.
!         IF evldeg .LT. 0, THEN THE PARTIAL MULTINOMIAL INVOLVING THE
!         FIRST   nepols  ORTHOGONAL BASIS FUNCTIONS WILL BE EVALUATED
!         at the points given by  evlcds .  The resulting values  will
!         be stored in  evlvls .
!         THE VALUE OF nepols MUST BE .GE. 1 AND .LE. (THE SIZE OF THE
!         BASIS  GENERATED  IN   mfit ),  WHICH  WAS RETURNED AS THE
!         value of  NFPOLS .
!         nepols  WILL BE CHANGED IF evldeg .GT. 0 TO GIVE THE SIZE OF
!         basis required for the multinomial of degree  evldeg .
!      nepts  -- (INTEGER) -- (passed)
!         the number of evaluation points.
!      evlcds  -- (real 2-subscript array) -- (passed)
!         evlcds (P,K) is the value of the K-TH variable at the  P-TH
!         evaluation point.
!      nerows  -- (INTEGER) -- (passed)
!         the row dimension declared for evlcds in the calling program.
!      evlvls  -- (INTEGER) -- (returned)
!         evlvls (P) is the value of the evaluated multinomial at the
!         P-TH evaluation point.
!      error  -- (INTEGER) -- (returned)
!          0 .........  if no errors
!         -1 .........  IF  nepols  .GT.  NFPOLS  OR  nepols  .LT. 1
!         -2 .........  IF  nepts  .LT. 1 OR  dimen  .LT. 1
!      fitiwk  -- (integer, 1-subscript array) -- (passed)
!         the integer work array of length  fiwkln  that was  used  in
!          mfit .
!      fitdwk  -- (real 2-subscript array) -- (passed)
!         the real work array of length  fdwkln  that was
!         used in  mfit .
!      fiwkln  -- (INTEGER) -- (passed)
!         the length of  fitiwk .
!      fdwkln  -- (INTEGER) -- (passed)
!         the length of  fitdwk .
!      temp    -- (REAL 1-SUBSCRIPT ARRAY)
!         a work array of length  dimen  (or longer).
!
!     The subroutine  meval1  is called to do the actual evaluation.
!
!     Modified by A.H. Morris (NSWC)
!
!     ****************
!
!
!     ***************
!     Set up index pointers to the beginning of each row of
!     the mtable -- this sets the beginning point for each
!     full multinomial degree.
!     ***************
!
if (nepts .lt. 1 .or. dimen .lt. 1) go to 110
if (evldeg) 40,10,20
!
10 nepols = 1
go to 50
!
20 top = 1
bot = 1
do 30 curdeg = 1,evldeg
   top = top * (dimen + curdeg)
30 bot = bot * curdeg
nepols = top / bot
!
40 gbasiz = fitiwk(1)
if (nepols .gt. gbasiz .or. nepols .lt. 1) go to 100
!
50 error = 0
dimp1 = dimen + 1
alfl = fitiwk(4)
maxstt = 1
alfstt = dimp1 + maxstt
cstt = alfstt + alfl
psistt = cstt + fitiwk(2)
!
!     ***************
!     The actual evaluation is done inside  meval1.
!     ***************
!
call meval1 (evlcds,nerows,fitdwk(cstt),nepts,dimen,nepols, &
&fitdwk(alfstt),fitiwk,fitdwk(psistt), &
&evlvls,alfl,fitdwk(maxstt),temp,dimp1)
return
!
!     ***************
!     Error return
!     ***************
!
100 error = -1
return
110 error = -2
return
end subroutine meval

subroutine meval1 (coord,ncrows,c,nepts,dimen,npolys,alpha, &
&indexs,psi,f,alfl,maxabs,x,dimp1)
implicit none
integer, intent(in) :: ncrows
!
integer, intent(in) :: dimen, nepts, npolys, alfl, dimp1
integer :: jm1, jprime, m, p, k, i, j, index
integer, intent(in) :: indexs(4,npolys)
real, intent(in) :: alpha(alfl), coord(ncrows,dimen)
real, intent(inout) :: psi(npolys)
real, intent(in) :: c(npolys)
real, intent(inout) :: f(nepts)
real, intent(in) :: maxabs(dimp1)
real, intent(inout) :: x(dimen)
real :: runtot, rntot1
!
!     ***************
!     Purpose
!     -------
!
!     This subroutine performs the main work of evaluating the
!     fitting multinomial (or the initial portion of it  which
!     is requested by the setting of  NEPOLS ,  EVLDEG  in the
!     CALL TO SUBROUTINE  meval .
!
!     This subroutine is called by  meval .  It is  not  called
!     directly by the user.
!
!     The body of this subroutine FOLLOWS the explanation
!     given in
!          least squares fitting using
!          orthogonal multinomials
!     by
!          Bartels and Jezioranski
!     in
!          ACM transactions on mathematical software
!
!
!     Modified by A.H. Morris (NSWC)
!
!     ****************
!
if (npolys .eq. 1) go to 50
!
psi(1) = 1.0
do 40 p = 1,nepts
!
!     ***************
!     Scale the coordinates of the p-TH point
!     ***************
!
   do k = 1,dimen
        x(k) = coord(p,k)
        if (maxabs(k) .ne. 0.0) x(k) = x(k) / maxabs(k)
   end do
!
!     ***************
!     Use the  basis function coefficients  c  and recurrence
!     coefficients  alpha  to evaluate the fitted multinomial
!     at the p-TH point.
!     ***************
!
   rntot1 = c(1)
   do 30 j = 2,npolys
        k = indexs(2,j)
        jprime = indexs(1,j)
        runtot = x(k) * psi(jprime)
        i = indexs(3,j)
        jm1 = j - 1
        do 20 m = i,jm1
           index = indexs(4,j) + m - i
20 runtot = runtot - psi(m) * alpha(index)
        psi(j) = runtot
30 rntot1 = rntot1 + c(j) * psi(j)
40 f(p) = rntot1 * maxabs(dimp1)
return
!
!     ***************
!     Compute the degree 0 polynomial
!     ***************
!
50 runtot = c(1) * maxabs(dimp1)
do 60 p = 1,nepts
60 f(p) = runtot
return
end subroutine meval1

subroutine dmfit(dimen,fitdeg,nfpols,nfpts, &
&fitcds,ncrows,fitvls,wts, &
&resids,error,fitiwk,fitdwk, &
&fiwkln,fdwkln,ireqd,dreqd)
implicit none
!
integer, intent(inout) :: nfpols, fitdeg
integer, intent(in) :: nfpts, dimen, fiwkln, fdwkln
integer, intent(inout) :: error, ireqd, dreqd
integer :: indstt, p, dimp1
integer, intent(in) :: ncrows
integer :: newstt, maxstt, alfstt, psistt, cstt, ssqstt, psiwid, &
&alfl
integer, intent(inout) :: fitiwk(fiwkln)
double precision, intent(inout) :: fitdwk(fdwkln), &
&fitcds(ncrows,dimen)
double precision, intent(inout) :: fitvls(nfpts), resids(nfpts)
double precision, intent(in) :: wts(nfpts)
double precision :: scale
!
!     ***************
!     Purpose
!     -------
!
!     This subroutine constructs a least-squares  multinomial  fit  to
!     given data using a basis of orthogonal multinomials. The computa-
!     tion is performed in double precision.
!
!     The data for the fit is given in the arrays FITCDS, fitvls, and
!     wts. FITCDS is a matrix, each row of which contains an observa-
!     tion point. fitvls is a singly-indexed array, each element of
!     which contains a function VALUE corresponding to an observation
!     point. wts is a singly-indexed array, each element of which is
!     a nonnegative weight for the corresponding observation.
!
!     The fit which is produced is a multinomial expressed in the form
!
!      C  psi  (X ,...,X     ) +...+ C       psi       (X ,...,X     )
!       1    1   1      dimen         nfpols    nfpols   1      dimen
!
!     WHERE THE VALUE OF  nfpols  WILL BE AS GIVEN (IF  fitdeg .LT. 0)
!     or  as  computed  by  dmfit  to give a full-degree fit (in case
!     fitdeg  IS SPECIFIED .GE. 0).  THE ELEMENTS
!
!         psi  (X ,...,X     )
!            K   1      dimen
!
!     Form a basis for the multinomials which is orthogonal with
!     respect to the weights and observation points.
!
!     The extent of the fit can be specified in one of two ways.
!         IF THE PARAMETER fitdeg IS SET .GE. 0, THEN A COMPLETE BASIS
!         FOR THE MULTINOMIALS OF DEGREE =  fitdeg  WILL BE USED.  (AN
!         error will be  flagged  if  this  will  require  more  basis
!         multinomials  than  the  number  of  data  points which were
!         given.)
!         IF THE PARAMETER  fitdeg  IS .LT.  0, THEN  nfpols  WILL  BE
!         taken as the count of the number of basis multinomials to be
!         used for a partial-degree fit.  (An error will be flagged if
!         nfpols  .LT. 0.)
!
!     Variables
!     ---------
!
!      dimen  -- (INTEGER) -- (passed)
!         the number of variables.
!      fitdeg  - (INTEGER) -- (PASSED/RETURNED)
!         IGNORED IF .LT. 0.
!         IF fitdeg .GE. 0 THEN  fitdeg  IS  CHECKED  AGAINST  nfpts .
!         The value of  fitdeg  will be reduced if there is a basis of
!         MULTINOMIALS, ALL OF  DEGREE  .LE. fitdeg ,  OF  CARDINALITY
!         nfpts .  See  error  below.
!      nfpols  - (INTEGER) -- (PASSED/RETURNED)
!         IGNORED IF  fitdeg  .GE. 0.
!         IF  fitdeg .LT. 0 THEN THE VALUE OF nfpols WILL BE TAKEN  AS
!         the size of the basis of multinomials to be used in the fit.
!         nfpols  MUST SATISFY  nfpols  .LT. nfpts  AND nfpols .GE. 1
!         see  error  below.
!      nfpts  --- (INTEGER) -- (passed)
!         the number of data points to be used in the fit.
!         nfpts  MUST BE .GE. 1.  SEE  ERROR  BELOW.
!      FITCDS  -- (double precision 2-subscript array) -- (passed)
!         FITCDS (p,K) is the value of the K-TH variable at the  p-TH
!         data point.
!      ncrows  -- (INTEGER) -- (passed)
!         THE ROW DIMENSION  DECLARED  FOR   FITCDS   IN  THE  CALLING
!         program.
!      fitvls  -- (double precision 1-subscript array) -- (passed)
!         fitvls (p) is the observed function VALUE of the p-TH  data
!         point.
!      wts  ----- (double precision 1-subscript array) -- (passed)
!         wts (p) is the weight attached to the p-TH data point.
!      resids  -- (double precision 1-subscript array) -- (returned)
!         resids (p) is the difference between the fitted function at
!         point p and  fitvls (p).
!      error  -- (INTEGER) -- (returned)
!       0 the desired least square multinomial fit was obtained.
!      -1 Only the first nfpols basis polynomials were obtained.
!         fitdeg is the degree of the fit.
!       1 IF  fitdeg  .GE. 0 BUT THERE IS AN INTERPOLATING MULTINOMIAL
!         OF SMALLER DEGREE OR IF fitdeg .LT. 0 AND nfpols .GT. nfpts.
!       2 IF  fitdeg  .LT. 0 AND  nfpols  .LE. 0.
!       3 IF  nfpts  .LT. 1 AND/OR  dimen  .LT. 1.
!       4 IF  IWKLEN  AND/OR  DWKLEN  IS TOO SMALL.  (SET  IWKLEN   TO
!         the value returned in  ireqd , and set  DWKLEN  to the value
!         returned in  dreqd  to resolve this problem.)
!      fitiwk  -- (integer, 1-subscript array) -- (returned)
!         an integer work array of length  fiwkln .  Upon return  from
!         dmfit, fitiwk contains dimension and array LENGTH information.
!      fitdwk  -- (double precision 1-subscript array) -- (returned)
!         an array of length  fdwkln  containing the coefficients
!         needed for computing the multinomial fit at a point.
!      fiwkln  -- (INTEGER) -- (passed)
!         the length of the array  fitiwk .
!      fdwkln  -- (INTEGER) -- (passed)
!         the length of the array  fitdwk .
!      ireqd  -- (INTEGER) -- (returned)
!         the length which the array  fitiwk  really needs to be.
!      dreqd  -- (INTEGER) -- (returned)
!         the length which the array  fitdwk  really needs to be.
!
!
!     Note. The 20 loop depends on the scaling scheme being used. The
!     residual scaling must be consistent with that defined by dscalp
!     AND dscald.
!
!     dmfit  calls  allot  and  dgnrtp.
!     ****************
!
dimp1 = dimen + 1
!
!     ***************
!
call allot(fitdeg,nfpols,nfpts,dimen,fitiwk,fiwkln,ireqd,dreqd, &
&error)
if ( error .ge. 2 ) return
!
if ( fdwkln .ge. dreqd ) go to 10
   error = 4
   return
10 continue
!
psiwid = fitiwk(3)
alfl = fitiwk(4)
indstt = 1
newstt = 4 * nfpols + indstt
maxstt = 1
alfstt = maxstt + dimp1
cstt = alfstt + alfl
ssqstt = cstt + nfpols
psistt = ssqstt + nfpols
!
!     ***************
!
   call dgnrtp(fitdeg,fitdwk(alfstt), &
&fitdwk(psistt),fitiwk(indstt), &
&fitiwk(newstt),fitdwk(ssqstt),fitcds, &
&ncrows,nfpols,dimen,nfpts,fitvls,resids, &
&fitdwk(cstt),psiwid,wts,alfl,dimp1, &
&fitdwk(maxstt),error)
!
!     ***************
!     Store the number of basis polynomials actually computed
!     by the modified routine dincdg called by dgnrtp.
!     ***************
!
fitiwk(1) = nfpols
!
!     ***************
!     Unscale the residuals for the benefit of the user.
!     ***************
!
scale = fitdwk(dimen + 1)
do p = 1,nfpts
  resids(p) = resids(p) * scale
end do
return
end subroutine dmfit

subroutine dgnrtp(degree,alpha,psi,indexs, &
&newkj,sumsqs,coord,ncrows,npolys, &
&dimen,npts,f,z,c,psiwid,weight, &
&alfl,dimp1,maxabs,error)
implicit none
integer, intent(in) :: ncrows
!
integer, intent(inout) :: degree
integer, intent(in) :: dimen
integer, intent(inout) :: npolys
integer, intent(in) :: npts
integer :: k
integer, intent(in) :: psiwid, alfl
integer :: p, sttdeg, onplys
integer, intent(inout) :: error
integer :: dimp1
integer, intent(in) :: indexs(4,npolys), newkj(dimen,degree)
double precision, intent(inout) :: psi(npts,psiwid), alpha(alfl), &
&f(npts)
double precision, intent(inout) :: coord(ncrows,dimen), &
&maxabs(dimp1)
double precision, intent(in) :: weight(npts)
double precision, intent(inout) :: z(npts), sumsqs(npolys), &
&c(npolys)
double precision :: runtot, rntot1
!
!     ***************
!     Purpose
!     -------
!
!     The multinomial fit is generated incrementally, a basis  element
!     at a time.  This subroutine starts the process off by setting up
!     the first basis element, scaling the  data,  finding  the  first
!     coefficient,  and  initializing  the  work array z.  dgnrtp then
!     calls  dincdg  if more than one basis element is required.
!
!     This subroutine is called by  dmfit .  It is not called by  the
!     user.
!
!     This subroutine calls  dscalp ,  dscald , and  dincdg .
!
!
!     Modified by A.H. Morris (NSWC)
!     ****************
!
!     ***************
!     Set up the scaling.
!     ***************
!
do 10 k = 1,dimen
   call dscalp(coord(1,k),npts,maxabs(k))
10 call dscald(coord(1,k),npts,maxabs(k))
call dscalp(f,npts,maxabs(dimp1))
call dscald(f,npts,maxabs(dimp1))
!
!     ***************
!      sumsqs (1) = (1,1)
!     c  = (f,1) / (1,1)
!      1
!     ***************
!
runtot = 0.d0
rntot1 = 0.d0
do 20 p = 1,npts
   psi(p,1) = 1.d0
   rntot1 = rntot1 + weight(p)
20 runtot = runtot + f(p) * weight(p)
sumsqs(1) = rntot1
c(1) = runtot / rntot1
!
!     ***************
!     z = f - c
!              1
!     ***************
!
do 30 p = 1,npts
30 z(p) = f(p) - c(1)
!
if ( npolys .eq. 1 ) return
sttdeg = 1
onplys = 1
!
call dincdg(degree,alpha,psi,indexs,newkj,sumsqs, &
&coord,ncrows,npolys,dimen,npts,f,z,c,psiwid, &
&weight,alfl,onplys,sttdeg,error)
return
end subroutine dgnrtp

subroutine dincdg(degree,alpha,psi,indexs,newkj, &
&sumsqs,coord,ncrows,npolys, &
&dimen,npts,f,z,c,psiwid,weight, &
&alfl,onplys,sttdeg,error)
implicit none
integer, intent(in) :: ncrows
!
integer :: jprime, p, j, curdeg, kj, kjp, l, jpm1, jm1
integer :: m, start, jindex, jpindx, q, j3, j1, j1mj2
integer, intent(inout) :: error
integer :: j0mj1, j1m1, starta
integer, intent(in) :: onplys
integer :: onpp1
integer, intent(inout) :: sttdeg
integer :: index1, index2
integer, intent(inout) :: degree, npolys
integer, intent(in) :: npts, dimen, psiwid, alfl
integer, intent(in) :: indexs(4,npolys), newkj(dimen,degree)
double precision, intent(inout) :: alpha(alfl)
double precision, intent(in) :: coord(ncrows,dimen)
double precision, intent(inout) :: psi(npts,psiwid)
double precision, intent(inout) :: sumsqs(npolys), c(npolys)
double precision, intent(in) :: f(npts), weight(npts)
double precision, intent(inout) :: z(npts)
double precision :: arc, runtot, rntot1, rntot2
!
!     ***************
!     Purpose
!     -------
!
!     The multinomial fit is generated incrementally, a basis  element
!     at a time.  This subroutine continues the process started off by
!      dgnrtp .
!
!     This subroutine is called by  dgnrtp  and not by the user.
!
!
!     Modified by A.H. Morris (NSWC)
!
!     ****************
!
if ( onplys .ge. 1 .and. sttdeg .ge. 1 ) go to 10
   error = 6
return
10 if ( indexs(2,onplys) .eq. dimen ) go to 20
      curdeg = sttdeg
   go to 30
20 curdeg = sttdeg + 1
30 onpp1 = onplys + 1
do 170 j = onpp1,npolys
   jprime = indexs(1,j)
   jindex = j - ((j - 1) / psiwid) * psiwid
   jpindx = jprime - ((jprime - 1) / psiwid) * psiwid
   kj = indexs(2,j)
   start = indexs(3,j)
   m = start
   starta = indexs(4,j) - start
   if ( curdeg .eq. 1 ) go to 100
   kjp = indexs(2,jprime)
   j1 = newkj(kj,curdeg - 1)
!
!     ***************
!     Calculate those  alpha ( j , m ) that can be calculated from
!     previously calculated alphas.
!     ***************
!
   if ( kj .lt. kjp ) go to 50
!
!     ***************
!     First calculate those between  JPP  and the end of 2 rows back.
!     Calculate  alpha ( j , JPP )
!     ***************
!
   index1 = indexs(4,j)
   alpha(index1) = sumsqs(jprime) / sumsqs(start)
!
   m = start + 1
   j3 = newkj(1,curdeg - 1) - 1
   if ( m .gt. j3 ) go to 50
!
!     ***************
!     curdeg .GT. 2 IF CONTROL HAS PASSED THE BRANCHES IN THE 3-RD
!     previous and 8-TH previous statements.
!     ***************
!
      j1mj2 = j1 - newkj(kj,curdeg - 2)
!
      do 40 l = m,j3
         q = j1mj2 + l
         index1 = starta + l
         index2 = indexs(4,q) - indexs(3,q) + jprime
40 alpha(index1) = alpha(index2) * sumsqs(jprime) / &
&sumsqs(l)
!
!     ***************
!     Calculate  alpha ( j , m ) for  m  between the 2
!     ranges calculated before using
!
!        alpha ( j , l ) = (X  *  psi  ,psi )  / (psi ,psi )
!                             K      JP    l         l    l
!                              j
!     ***************
!
   m = j3 + 1
50 if ( jprime .eq. j1 ) go to 100
      if ( kj .eq. 1 ) go to 80
      j1m1 = j1 - 1
      do 70 l = m,j1m1
         runtot = 0.d0
         do 60 p = 1,npts
            index1 = l - ((l - 1) / psiwid) * psiwid
60 runtot = runtot + coord(p,kj) * psi(p,jpindx) * &
&psi(p,index1) * weight(p)
         index1 = starta + l
70 alpha(index1) = runtot / sumsqs(l)
!
!     ***************
!     Calculate  alpha ( j , m ) for  m  between
!      newkj ( kj , curdeg  - 1)  AND
!      JP  - 1.
!     ***************
!
80 j0mj1 = newkj(kj,curdeg) - j1
      jpm1 = jprime - 1
      do 90 l = j1,jpm1
         q = j0mj1 + l
         index1 = starta + l
         index2 = indexs(4,q) - indexs(3,q) + jprime
90 alpha(index1) = alpha(index2) * sumsqs(jprime) / &
&sumsqs(l)
      m = jprime
!
!     ***************
!     Calculate the remaining  alpha ( j , m ) from
!
!      alpha ( j , l ) = (X   * psi  ,psi ) / (psi ,psi )
!                          K       JP    l        l    l
!                           j
!     ***************
!
100 jm1 = j - 1
   do 120 l = m,jm1
      runtot = 0.d0
      do 110 p = 1,npts
         index1 = l - ((l - 1) / psiwid) * psiwid
110 runtot = runtot + coord(p,kj) * psi(p,jpindx) * &
&psi(p,index1) * weight(p)
      index1 = starta + l
120 alpha(index1) = runtot / sumsqs(l)
!
!     ***************
!     Now calculate the  psi (p,j),  sumsqs (j) and  c (j) using
!
!                          j-1
!     psi  = X  * psi   -  SUM   alpha(j,l) * psi
!        j    K      JP    l=JPP                 l
!
!     sumsqs  = (psi ,psi )
!           j       j    j
!
!     c  = (z,psi )
!      j         j
!     ***************
!
130 jm1 = j - 1
    arc = 0.d0
    rntot1 = 0.d0
    rntot2 = 0.d0
    do 150 p = 1,npts
        runtot = coord(p,kj) * psi(p,jpindx)
        do 140 l = start,jm1
           index1 = starta + l
           index2 = l - ((l - 1) / psiwid) * psiwid
140 runtot = runtot - alpha(index1) * psi(p,index2)
        psi(p,jindex) = runtot
        arc = arc + psi(p,index2) * psi(p,jindex) * &
&weight(p)
        rntot1 = rntot1 + psi(p,jindex) * psi(p,jindex) * &
&weight(p)
150 rntot2 = rntot2 + z(p) * psi(p,jindex) * weight(p)
    if (arc * arc .ge. sumsqs(jm1) * rntot1 * 1.d-06) &
&go to 200
    sumsqs(j) = rntot1
    c(j) = rntot2 / rntot1
!
!     ***************
!     Calculate the new  z ( p ) and the new  SSRES  using
!
!     z = z - c  * psi
!              j      j
!     ***************
!
    do 160 p = 1,npts
160 z(p) = z(p) - c(j) * psi(p,jindex)
    sttdeg = curdeg
170 if ( kj .eq. dimen ) curdeg = curdeg + 1
return
!
!     ***************
!     The j-TH basis multinomial cannot be computed accurately.
!     Only j - 1 basis multinomials are generated.
!     ***************
!
200 error = -1
degree = sttdeg
npolys = jm1
return
end subroutine dincdg

subroutine dscalp(coord,npts,maxabs)
implicit none
!
integer, intent(in) :: npts
integer :: p
double precision, intent(out) :: maxabs
double precision :: a
double precision, intent(in) :: coord(npts)
!
!     ***************
!     Purpose
!     -------
!
!     Find scaling PARAMETER(S) for the problem. If the scaling scheme
!     is changed, all four of the following would have to be changed
!
!     1)  dscalp  - find the scaling parameters
!     2)  dscald  - scale the problem data
!     3)  the scaling of the residuals in  dmfit
!     4)  the scaling performed in  dmevl1
!
!     This subroutine is called by  dgnrtp .  It is not called  by  the
!     user.
!
!     The scaling which  it  defines  must  be  coordinated  with  the
!     scaling  of residuals which is carried out toward the end of the
!     subroutine  dmfit.  The scaling must also be coordinated with the
!     scaling performed in the 10 loop  and  at statements 40 and 50
!     (with the scale factor maxabs(DIMP1)) in  dmevl1.
!
!     ****************
!
maxabs = 0.d0
do 10 p = 1,npts
   a = dabs(coord(p))
10 if ( a .gt. maxabs ) maxabs = a
return
end subroutine dscalp

subroutine dscald(coord,npts,maxabs)
implicit none
!
integer, intent(in) :: npts
integer :: p
double precision, intent(in) :: maxabs
double precision, intent(inout) :: coord(npts)
!
!     ***************
!     Purpose
!     -------
!
!     Carry out the data-scaling which is defined  by  the subroutine
!     dscalp .
!
!     This subroutine is called by  dgnrtp .  It is not called by the
!     user.
!
!     The scaling which this routine carries out must  be  consistent
!     with the scaling in the subroutines dmfit and dmevl1.
!
!     ****************
!
if ( maxabs .eq. 0.0d+00 ) return
   do 10 p = 1,npts
10 coord(p) = coord(p) / maxabs
   return
end subroutine dscald

subroutine dmeval(dimen,evldeg,nepols,nepts,evlcds,nerows,evlvls, &
&error,fitiwk,fitdwk,fiwkln,fdwkln,temp)
implicit none
integer, intent(in) :: nerows
!
integer, intent(in) :: fiwkln, fdwkln
integer, intent(inout) :: nepols
integer, intent(in) :: nepts, dimen
integer, intent(inout) :: error
integer :: maxstt, alfstt, cstt
integer :: gbasiz, alfl, dimp1
integer, intent(in) :: evldeg
integer :: top, bot, curdeg, psistt
integer, intent(in) :: fitiwk(fiwkln)
double precision, intent(inout) :: fitdwk(fdwkln)
double precision, intent(in) :: evlcds(nerows,dimen)
double precision, intent(inout) :: evlvls(nepts), temp(dimen)
!
!     ***************
!     Purpose
!     -------
!
!     This subroutine  evaluates  the  least-squares  multinomial  fit
!     which has been previously produced by  dmfit .  The computation
!     is performed in double precision. Either the full
!     multinomial as produced may be evaluated,  or  only  an  initial
!     segment thereof.  As in the case with  dmfit , it is possible
!     (1) to specify multinomials of a full given degree, or
!     (2) to specify  the  number  of  orthogonal  basis  elements  to
!         achieve a partial-degree fit.
!
!     In case (1), the  desired  degree  is  given  as  the  value  of
!     evldeg   (WHICH  MUST  BE  NONNEGATIVE AND NOT GREATER THAN THE
!     value used for  FITDEG  in  dmfit ), and the parameter  nepols
!     will be set  by  dmeval  to specify the number of basis elements
!     REQUIRED. IF  evldeg  .LT.  FITDEG   IS  GIVEN,  THEN  ONLY  THE
!     initial  portion of the fitting multinomial (of degree  evldeg )
!     will be evaluated.
!
!     In case (2),  evldeg  is to be set negative, in which  case  the
!     VALUE  OF   nepols  (WHICH MUST BE POSITIVE AND NOT GREATER THAN
!     THE VALUE USED FOR   NFPOLS   IN   dmfit )  WILL  BE  TAKEN  AS
!     defining  the  initial  portion of the fitting multinomial to be
!     evaluated.
!
!     IF  nepols  =  NFPOLS  (WITH  evldeg  .LT.  0),  OR   evldeg   =
!     FITDEG  (WITH   evldeg   .GT.  0),  THEN  THE  FULL  MULTINOMIAL
!     generated by  dmfit  will be evaluated.
!
!     THE  EVALUATION  WILL  TAKE  PLACE  FOR  EACH  OF   THE   POINTS
!     (collection  of  variable  values)  given as a row of the matrix
!      evlcds .  The  values  produced  from  the  full,  or  partial,
!     multinomial will be placed in the array  evlvls .
!
!     Variables
!     ---------
!
!      dimen  -- (INTEGER) -- (passed)
!         the number of variables.
!      evldeg  -- (INTEGER) -- (passed)
!         IF  evldeg  .LT. 0, THEN THIS PARAMETER WILL BE IGNORED.
!         IF  evldeg  .GE. 0, THEN THE VALUE OF  evldeg  MUST  SATISFY
!         evldeg  .LE. (THE  DEGREE  OF THE APPROXIMATING MULTINOMIAL
!         generated in  dmfit ).  In this case  evldeg  will  specify
!         the degree of the initial portion of the fitting multinomial
!         to be evaluated.
!      nepols  -- (INTEGER) -- (PASSED/RETURNED)
!         IF  evldeg  .GE. 0, THEN THIS PARAMETER WILL BE IGNORED.
!         IF evldeg .LT. 0, THEN THE PARTIAL MULTINOMIAL INVOLVING THE
!         FIRST   nepols  ORTHOGONAL BASIS FUNCTIONS WILL BE EVALUATED
!         at the points given by  evlcds .  The resulting values  will
!         be stored in  evlvls .
!         THE VALUE OF nepols MUST BE .GE. 1 AND .LE. (THE SIZE OF THE
!         BASIS  GENERATED  IN   dmfit ),  WHICH  WAS RETURNED AS THE
!         value of  NFPOLS .
!         nepols  WILL BE CHANGED IF evldeg .GT. 0 TO GIVE THE SIZE OF
!         basis required for the multinomial of degree  evldeg .
!      nepts  -- (INTEGER) -- (passed)
!         the number of evaluation points.
!      evlcds  -- (double precision 2-subscript array) -- (passed)
!         evlcds (P,K) is the value of the K-TH variable at the  P-TH
!         evaluation point.
!      nerows  -- (INTEGER) -- (passed)
!         the row dimension declared for evlcds in the calling program.
!      evlvls  -- (INTEGER) -- (returned)
!         evlvls (P) is the value of the evaluated multinomial at the
!         P-TH evaluation point.
!      error  -- (INTEGER) -- (returned)
!          0 .........  if no errors
!         -1 .........  IF  nepols  .GT.  NFPOLS  OR  nepols  .LT. 1
!         -2 .........  IF  nepts  .LT. 1 OR  dimen  .LT. 1
!      fitiwk  -- (integer, 1-subscript array) -- (passed)
!         the integer work array of length  fiwkln  that was  used  in
!          dmfit .
!      fitdwk  -- (double precision 2-subscript array) -- (passed)
!         the real work array of length  fdwkln  that was
!         used in  dmfit .
!      fiwkln  -- (INTEGER) -- (passed)
!         the length of  fitiwk .
!      fdwkln  -- (INTEGER) -- (passed)
!         the length of  fitdwk .
!      temp    -- (DOUBLE PRECISION 1-SUBSCRIPT ARRAY)
!         a work array of length  dimen  (or longer).
!
!     The subroutine  dmevl1  is called to do the actual evaluation.
!
!     Modified by A.H. Morris (NSWC)
!
!     ****************
!
!
!     ***************
!     Set up index pointers to the beginning of each row of
!     the mtable -- this sets the beginning point for each
!     full multinomial degree.
!     ***************
!
if (nepts .lt. 1 .or. dimen .lt. 1) go to 110
if (evldeg) 40,10,20
!
10 nepols = 1
go to 50
!
20 top = 1
bot = 1
do 30 curdeg = 1,evldeg
   top = top * (dimen + curdeg)
30 bot = bot * curdeg
nepols = top / bot
!
40 gbasiz = fitiwk(1)
if (nepols .gt. gbasiz .or. nepols .lt. 1) go to 100
!
50 error = 0
dimp1 = dimen + 1
alfl = fitiwk(4)
maxstt = 1
alfstt = dimp1 + maxstt
cstt = alfstt + alfl
psistt = cstt + fitiwk(2)
!
!     ***************
!     The actual evaluation is done inside  dmevl1.
!     ***************
!
call dmevl1 (evlcds,nerows,fitdwk(cstt),nepts,dimen,nepols, &
&fitdwk(alfstt),fitiwk,fitdwk(psistt), &
&evlvls,alfl,fitdwk(maxstt),temp,dimp1)
return
!
!     ***************
!     Error return
!     ***************
!
100 error = -1
return
110 error = -2
return
end subroutine dmeval

subroutine dmevl1 (coord,ncrows,c,nepts,dimen,npolys,alpha, &
&indexs,psi,f,alfl,maxabs,x,dimp1)
implicit none
integer, intent(in) :: ncrows
!
integer, intent(in) :: dimen, nepts, npolys, alfl, dimp1
integer :: jm1, jprime, m, p, k, i, j, index
integer, intent(in) :: indexs(4,npolys)
double precision, intent(in) :: alpha(alfl), coord(ncrows,dimen)
double precision, intent(inout) :: psi(npolys)
double precision, intent(in) :: c(npolys)
double precision, intent(inout) :: f(nepts)
double precision, intent(in) :: maxabs(dimp1)
double precision, intent(inout) :: x(dimen)
double precision :: runtot, rntot1
!
!     ***************
!     Purpose
!     -------
!
!     This subroutine performs the main work of evaluating the
!     fitting multinomial (or the initial portion of it  which
!     is requested by the setting of  NEPOLS ,  EVLDEG  in the
!     CALL TO SUBROUTINE  dmeval .
!
!     This subroutine is called by  dmeval .  It is  not  called
!     directly by the user.
!
!     The body of this subroutine FOLLOWS the explanation
!     given in
!          least squares fitting using
!          orthogonal multinomials
!     by
!          Bartels and Jezioranski
!     in
!          ACM transactions on mathematical software
!
!
!     Modified by A.H. Morris (NSWC)
!
!     ****************
!
if (npolys .eq. 1) go to 50
!
psi(1) = 1.d0
do 40 p = 1,nepts
!
!     ***************
!     Scale the coordinates of the p-TH point
!     ***************
!
   do k = 1,dimen
        x(k) = coord(p,k)
        if (maxabs(k) .ne. 0.d0) x(k) = x(k) / maxabs(k)
   end do
!
!     ***************
!     Use the  basis function coefficients  c  and recurrence
!     coefficients  alpha  to evaluate the fitted multinomial
!     at the p-TH point.
!     ***************
!
   rntot1 = c(1)
   do 30 j = 2,npolys
        k = indexs(2,j)
        jprime = indexs(1,j)
        runtot = x(k) * psi(jprime)
        i = indexs(3,j)
        jm1 = j - 1
        do 20 m = i,jm1
           index = indexs(4,j) + m - i
20 runtot = runtot - psi(m) * alpha(index)
        psi(j) = runtot
30 rntot1 = rntot1 + c(j) * psi(j)
40 f(p) = rntot1 * maxabs(dimp1)
return
!
!     ***************
!     Compute the degree 0 polynomial
!     ***************
!
50 runtot = c(1) * maxabs(dimp1)
do 60 p = 1,nepts
60 f(p) = runtot
return
end subroutine dmevl1

real function qsuba (f, a, b, epsil, mcount, relerr, ind)
implicit none
integer, intent(inout) :: ind
integer, intent(in) :: mcount
real, intent(in) :: a, b, epsil
real, intent(inout) :: relerr
integer :: icheck, is, ismax, k, nf, npts
real :: eps, err, result(8), stack(100), sub1, sub2, sub3, sum, &
&tol, x
real :: f, spmpar
!-----------------------------------------------------------------------
!
!                Integration over a finite interval
!
!                          ----------
!
!     qsuba computes the integral of f(X) from A to b where the
!     relative error does not exceed epsil.
!
!     mcount is the maximum number of points at which f(X) may be
!     evaluated.
!
!     relerr is a variable. When qsuba terminates, if the value
!     of the integral is nonzero then relerr is a crude estimate
!     OF THE RELATIVE ERROR OF THE VALUE. OTHERWISE, IF qsuba = 0
!     then relerr is an estimate of the absolute error.
!
!     Ind is a variable. When qsuba terminates, ind has one of the
!     following values ...
!
!     ind=0   qsuba IS SATISFIED THAT THE INTEGRAL HAS BEEN
!             computed to the desired accuracy.
!     ind=1   THE INTEGRAL HAS BEEN COMPUTED, BUT qsuba IS
!             not certain of the accuracy of the result.
!     ind=2   THE INTEGRAND HAS BEEN EVALUATED AT mcount
!             points. If more evaluations are needed then
!             qsuba TERMINATES.
!     ind=3   qsuba CANNOT COMPUTE THE INTEGRAL TO THE DESIRED
!             accuracy. Ind is set to 3 whenever the stack of
!             intervals becomes full (it currently can hold 50
!             intervals). A result is obtained by continuing
!             the integration ignoring convergence failures
!             which cannot be accommodated on the stack.
!
!     The reliability of the algorithm decreases for large values
!     of epsil. It is recommended that epsil be less than 0.001.
!
!-----------------------------------------------------------------------
external f
data ismax/100/
!-----------------------------------------------------------------------
!
!     ****** eps IS A MACHINE DEPENDENT CONSTANT. EPS IS THE
!            SMALLEST NUMBER SUCH THAT 1.0 + eps .GT. 1.0.
!
                eps = spmpar(1)
!
!-----------------------------------------------------------------------
qsuba = 0.0
relerr = 0.0
ind = 0
if (a .eq. b) return
!
!     Apply quad to the entire interval
!
sub1 = amin1(a,b)
sub3 = amax1(a,b)
tol = amax1(epsil, 10.0*eps)
call quad (sub1, sub3, result, k, tol, npts, icheck, f)
if (icheck .eq. 0) go to 100
is = 1
!
!     Subdivide the interval (sub1,sub3) into the subintervals
!     (sub1,sub2) and (sub2,sub3). Call quad for (sub1,sub2).
!
10 if (npts .ge. mcount) go to 110
sub2 = 0.5*(sub1 + sub3)
call quad (sub1, sub2, result, k, tol, nf, icheck, f)
npts = npts + nf
err = abs(result(k) - result(k-1))
sum = qsuba + result(k)
if (icheck .eq. 0 .or. err .le. abs(tol*sum)) go to 30
!
!        Stack the subinterval (sub1,sub2) for further
!        examination if there is sufficient storage.
!
   if (is .ge. ismax) go to 20
      stack(is) = sub1
      is = is + 1
      stack(is) = sub2
      is = is + 1
      go to 40
20 ind = 3
!
!     Update qsuba and check if any significant digits are lost
!
30 x = qsuba
qsuba = sum
relerr = relerr + err
if (ind .ne. 0 .or. x*result(k) .ge. 0.0) go to 40
x = 0.1*amin1(abs(x),abs(result(k)))
if (abs(qsuba) .le. x) ind = 1
!
!     CALL QUAD FOR THE INTERVAL (sub2,sub3)
!
40 if (npts .ge. mcount) go to 110
call quad (sub2, sub3, result, k, tol, nf, icheck, f)
npts = npts + nf
err = abs(result(k) - result(k-1))
sum = qsuba + result(k)
if (icheck .eq. 0 .or. err .le. abs(tol*sum)) go to 50
!
!        Subdivide the interval (sub2,sub3)
!
   sub1 = sub2
   go to 10
!
!     Update qsuba and check if any significant digits are lost
!
50 x = qsuba
qsuba = sum
relerr = relerr + err
if (ind .ne. 0 .or. x*result(k) .ge. 0.0) go to 60
x = 0.1*amin1(abs(x),abs(result(k)))
if (abs(qsuba) .le. x) ind = 1
!
!     Subdivide the interval last stacked
!
60 if (is .eq. 1) go to 120
is = is - 1
sub3 = stack(is)
is = is - 1
sub1 = stack(is)
go to 10
!
!     Termination when subdivision is not needed
!
100 qsuba = result(k)
if (a .gt. b) qsuba = -qsuba
relerr = abs(result(k) - result(k-1))
if (qsuba .ne. 0.0) relerr = relerr/abs(qsuba)
return
!
!     Subdivision result
!
110 ind = 2
120 if (a .gt. b) qsuba = -qsuba
if (qsuba .ne. 0.0) relerr = relerr/abs(qsuba)
return
end function qsuba

subroutine quad(a, b, result, k, epsil, npts, icheck, f)
implicit none
integer, intent(out) :: icheck
integer, intent(inout) :: k, npts
real, intent(in) :: a, b, epsil
