&0.71203315536225203459e00,0.94636899938300652943e-02, &
&0.69281376977911470289e00,0.97546565363174114611e-02, &
&0.67301883023041847920e00,0.10039172044056840798e-01, &
&0.65266166541001749610e00,0.10316812330947621682e-01, &
&0.63175643771119423041e00,0.10587167904885197931e-01, &
&0.61031811371518640016e00,0.10849844089337314099e-01, &
&0.58836243444766254143e00,0.11104461134006926537e-01/
data p(337),p(338),p(339),p(340),p(341),p(342),p(343), &
&p(344),p(345),p(346),p(347),p(348),p(349),p(350), &
&p(351),p(352),p(353),p(354),p(355),p(356),p(357), &
&p(358),p(359),p(360),p(361),p(362),p(363),p(364)/ &
&0.56590588542365442262e00,0.11350654315980596602e-01, &
&0.54296566649831149049e00,0.11588074033043952568e-01, &
&0.51955966153745702199e00,0.11816385890830235763e-01, &
&0.49570640791876146017e00,0.12035270785279562630e-01, &
&0.47142506587165887693e00,0.12244424981611985899e-01, &
&0.44673538766202847374e00,0.12443560190714035263e-01, &
&0.42165768662616330006e00,0.12632403643542078765e-01, &
&0.39621280605761593918e00,0.12810698163877361967e-01, &
&0.37042208795007823014e00,0.12978202239537399286e-01, &
&0.34430734159943802278e00,0.13134690091960152836e-01, &
&0.31789081206847668318e00,0.13279951743930530650e-01, &
&0.29119514851824668196e00,0.13413793085110098513e-01, &
&0.26424337241092676194e00,0.13536035934956213614e-01, &
&0.23705884558982972721e00,0.13646518102571291428e-01/
data p(365),p(366),p(367),p(368),p(369),p(370),p(371), &
&p(372),p(373),p(374),p(375),p(376),p(377),p(378), &
&p(379),p(380),p(381)/ &
&0.20966523824318119477e00,0.13745093443001896632e-01, &
&0.18208649675925219825e00,0.13831631909506428676e-01, &
&0.15434681148137810869e00,0.13906019601325461264e-01, &
&0.12647058437230196685e00,0.13968158806516938516e-01, &
&0.98482396598119202090e-01,0.14017968039456608810e-01, &
&0.70406976042855179063e-01,0.14055382072649964277e-01, &
&0.42269164765363603212e-01,0.14080351962553661325e-01, &
&0.14093886410782462614e-01,0.14092845069160408355e-01, &
&0.14094407090096179347e-01/
icheck = 0
! Check for trivial case.
if (a.eq.b) go to 70
! Scale factors.
sum = (b+a)/2.0
diff = (b-a)/2.0
! 1-Point Gauss
fzero = f(sum)
result(1) = 2.0*fzero*diff
i = 0
iold = 0
inew = 1
k = 2
acum = 0.0
go to 30
10 if (k.eq.8) go to 50
k = k + 1
acum = 0.0
! Contribution from function values already computed.
do 20 j = 1,iold
  i = i + 1
  acum = acum + p(i)*funct(j)
20 continue
! Contribution from new function values.
30 iold = iold + inew
do 40 j = inew,iold
  i = i + 1
  x = p(i)*diff
  funct(j) = f(sum+x) + f(sum-x)
  i = i + 1
  acum = acum + p(i)*funct(j)
40 continue
inew = iold + 1
i = i + 1
result(k) = (acum+p(i)*fzero)*diff
! Check for convergence.
if (abs(result(k)-result(k-1))-epsil*abs(result(k))) 60, &
&60, 10
! Convergence not achieved.
50 icheck = 1
! Normal termination.
60 npts = inew + iold
return
! Trivial case
70 k = 2
result(1) = 0.0
result(2) = 0.0
npts = 0
return
end subroutine quad

subroutine qags (f, a, b, epsabs, epsrel, result, abserr, &
&neval, ier, limit, lenw, last, iwork, work)
implicit none
real :: f
integer, intent(out) :: ier, last
integer, intent(in) :: lenw, limit
integer, intent(out) :: neval
real, intent(in) :: a
real, intent(out) :: abserr
real, intent(in) :: b, epsabs, epsrel
real, intent(out) :: result
integer :: l1, l2, l3
!-----------------------------------------------------------------------
!
!                 Computation of a definite integral
!
!-----------------------------------------------------------------------
!
!        Purpose
!           the routine calculates an approximation  result  to a given
!           DEFINITE INTEGRAL   I = INTEGRAL OF  f  OVER (a,b),
!           hopefully satisfying following claim for accuracy
!           abs(I-result).LE.max(epsabs,epsrel*abs(I)).
!
!        Parameters
!         on entry
!            f      - REAL
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X T E R N A L in the driver program.
!
!            a      - REAL
!                     lower limit of integration
!
!            b      - REAL
!                     upper limit of integration
!
!            epsabs - REAL
!                     absolute accuracy requested
!
!            epsrel - REAL
!                     relative accuracy requested
!
!         On return
!            result - real
!                     approximation to the integral
!
!            abserr - REAL
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            neval  - INTEGER
!                     number of integrand evaluations
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                     ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE
!                             the estimates for integral and error are
!                             less reliable. It is assumed that the
!                             requested accuracy has not been achieved.
!
!                     ier = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more sub-
!                             divisions by increasing the value of
!                             limit (and taking the according
!                             dimension adjustments into account).
!                             However, if this yields no improvement
!                             it is advised to analyze the integrand
!                             in order to determine the integration
!                             difficulties. If the position of A
!                             local difficulty can be determined (E.G.
!                             Singularity, discontinuity within the
!                             interval) one will probably gain from
!                             splitting up the interval at this point
!                             and calling the integrator on the sub-
!                             ranges. If possible, an appropriate
!                             special-purpose integrator should be used,
!                             which is designed for handling the type
!                             of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS DETEC-
!                             ted, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR
!                             occurs at some  points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             It is presumed that the requested
!                             tolerance cannot be achieved, and that the
!                             returned result is the best which can be
!                             obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted
!                             that divergence can occur with any other
!                             value of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs
!                             OR epsrel IS NEGATIVE, limit .LT. 1,
!                             OR lenw .LT. 4 * limit.
!                             Result, abserr, neval, last are
!                             set to zero.
!
!         Dimensioning parameters
!            limit - integer
!                    dimensioning parameter for iwork
!                    limit determines the maximum number
!                    of subintervals in the partition of the given
!                    INTEGRATION INTERVAL (a,b), limit.GE.1.
!                    IF limit.LT.1, THE ROUTINE WILL END WITH
!                    ier = 6.
!
!            lenw  - INTEGER
!                    dimensioning parameter for work
!                    lenw must be at least limit*4.
!                    IF lenw.LT.limit*4, THE ROUTINE WILL END
!                    WITH ier = 6.
!
!            last  - integer
!                    on return, last equals the number of
!                    subintervals produced in the subdivision
!                    process, which determines the number of
!                    significant elements actually in the work
!                    arrays.
!
!         Work arrays
!            iwork - INTEGER
!                    vector of dimension at least limit, the first K
!                    elements of which contain pointers
!                    to the error estimates over the subintervals
!                    such that work(limit*3+iwork(1)),... ,
!                    work(limit*3+iwork(K)) form a decreasing
!                    SEQUENCE, WITH K = last IF last.LE.(limit/2+2), AND
!                    K = limit+1-last OTHERWISE
!
!            work  - real
!                    vector of dimension at least lenw
!                    on return
!                    work(1), ..., work(last) contain the left
!                     END POINTS OF THE SUBINTERVALS IN THE
!                     partition of (a,b),
!                    work(limit+1), ..., work(limit+last) contain
!                     the right end points,
!                    work(limit*2+1), ..., work(limit*2+last)
!                     contain the integral approximations over
!                     the subintervals,
!                    work(limit*3+1), ..., work(limit*3+last)
!                     contain the error estimates.
!
!         Subroutines or functions needed
!              - qagse
!              - qk21f
!              - qpsrt
!              - qelg
!              - f (user-provided function)
!              - spmpar
!
!-----------------------------------------------------------------------
real, intent(inout) :: work(lenw)
integer, intent(inout) :: iwork(limit)
external f
!
!         Check validity of limit and lenw.
!
ier = 6
neval = 0
last = 0
result = 0.0
abserr = 0.0
if (limit .lt. 1 .or. lenw .lt. limit*4) return
!
!         Prepare call for qagse.
!
l1 = limit + 1
l2 = limit + l1
l3 = limit + l2
!
call qagse (f,a,b,epsabs,epsrel,limit,result,abserr,neval, &
&ier,work(1),work(l1),work(l2),work(l3),iwork,last)
return
end subroutine qags

subroutine qagse (f,a,b,epsabs,epsrel,limit,result,abserr, &
&neval,ier,alist,blist,rlist,elist,iord,last)
implicit none
!-----------------------------------------------------------------------
!
!                 Computation of a definite integral
!
!-----------------------------------------------------------------------
!
!        Purpose
!           the routine calculates an approximation  result  to a given
!           DEFINITE INTEGRAL   I = INTEGRAL OF  F  OVER (a,b),
!           hopefully satisfying following claim for accuracy
!           abs(I-result).LE.max(epsabs,epsrel*abs(I)).
!
!        Parameters
!         on entry
!            F      - REAL
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X t E R N A L in the driver program.
!
!            a      - REAL
!                     lower limit of integration
!
!            b      - REAL
!                     upper limit of integration
!
!            epsabs - REAL
!                     absolute accuracy requested
!
!            epsrel - REAL
!                     relative accuracy requested
!
!            limit  - integer
!                     gives an upperbound on the number of
!                     subintervals in the partition of (a,b)
!
!         On return
!            result - real
!                     approximation to the integral
!
!            abserr - REAL
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            neval  - INTEGER
!                     number of integrand evaluations
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                     ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE
!                             the estimates for integral and error are
!                             less reliable. It is assumed that the
!                             requested accuracy has not been achieved.
!
!                         = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more sub-
!                             divisions by increasing the value of
!                             limit (and taking the according
!                             dimension adjustments into account).
!                             However, if this yields no improvement
!                             it is advised to analyze the integrand
!                             in order to determine the integration
!                             difficulties. If the position of A
!                             local difficulty can be determined (E.G.
!                             Singularity, discontinuity within the
!                             interval) one will probably gain from
!                             splitting up the interval at this point
!                             and calling the integrator on the sub-
!                             ranges. If possible, an appropriate
!                             special-purpose integrator should be used,
!                             which is designed for handling the type
!                             of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS DETEC-
!                             ted, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR
!                             occurs at some  points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             It is presumed that the requested
!                             tolerance cannot be achieved, and that the
!                             returned result is the best which can be
!                             obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted
!                             that divergence can occur with any other
!                             value of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs
!                             or epsrel is negative.
!                             Result, abserr, neval, last, rlist(1),
!                             iord(1) and elist(1) are set to zero.
!                             alist(1) and blist(1) are set to A and b
!                             respectively.
!
!            alist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the left
!                     END POINTS OF THE SUBINTERVALS IN THE PARTITION
!                     of the given integration range (a,b)
!
!            blist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the right
!                     END POINTS OF THE SUBINTERVALS IN THE PARTITION
!                     of the given integration range (a,b)
!
!            rlist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the integral
!                     approximations on the subintervals
!
!            elist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the moduli
!                     of the absolute error estimates on the
!                     SUBINERVALS
!
!            iord   - INTEGER
!                     vector of dimension at least limit, the first k
!                     elements of which are pointers to the error
!                     estimates over the subintervals, such
!                     THAT elist(iord(1)), ..., elist(iord(k))
!                     FORM A DECREASING SEQUENCE, WITH k = last
!                     IF last.LE.(limit/2+2), AND k = limit+1-last
!                     otherwise
!
!            last   - INTEGER
!                     number of subintervals actually produced in the
!                     subdivision process
!
!         Subroutines or functions needed
!              - qk21f
!              - qpsrt
!              - qelg
!              - F (user-provided function)
!              - spmpar
!
!-----------------------------------------------------------------------
real, intent(in) :: a
real :: abseps
real, intent(out) :: abserr
real, intent(inout) :: alist
real :: area, area1, area12, area2, a1, a2
real, intent(in) :: b
real, intent(inout) :: blist
real :: b1, b2, correc, defabs, defab1, defab2, dres
real, intent(inout) :: elist
real :: epmach
real, intent(in) :: epsabs, epsrel
real :: erlarg, erlast, errbnd, errmax, error1, error2, erro12, &
&errsum, ertest, f, oflow, rerr, resabs, reseps
real, intent(out) :: result
real :: res3la(3)
real, intent(inout) :: rlist
real :: rlist2(52), small, spmpar, t, uflow
integer :: id
integer, intent(out) :: ier
integer :: ierro
integer, intent(inout) :: iord
integer :: iroff1, iroff2, iroff3, jupbnd, k, ksgn, ktmin
integer, intent(out) :: last
integer, intent(in) :: limit
integer :: maxerr
integer, intent(out) :: neval
integer :: nres, nrmax, numrl2
logical :: extrap, noext
!
dimension alist(limit), blist(limit), elist(limit), iord(limit), &
&rlist(limit)
!
external f
!
!            The dimension of rlist2 is determined by the value of
!            LIMEXP in subroutine qelg (rlist2 should be of dimension
!            (LIMEXP+2) at least).
!
!            List of major variables
!            -----------------------
!
!           alist     - LIST OF LEFT END POINTS OF ALL SUBINTERVALS
!                       considered up to now
!           blist     - LIST OF RIGHT END POINTS OF ALL SUBINTERVALS
!                       considered up to now
!           rlist(I)  - approximation to the integral over
!                       (alist(I),blist(I))
!           rlist2    - ARRAY OF DIMENSION AT LEAST LIMEXP+2
!                       containing the part of the epsilon table
!                       which is still needed for further computations
!           elist(I)  - error estimate applying to rlist(I)
!           maxerr    - POINTER TO THE INTERVAL WITH LARGEST ERROR
!                       estimate
!           errmax    - elist(maxerr)
!           erlast    - ERROR ON THE INTERVAL CURRENTLY SUBDIVIDED
!                       (before that subdivision has taken place)
!           area      - SUM OF THE INTEGRALS OVER THE SUBINTERVALS
!           ERRSUM    - SUM OF THE ERRORS OVER THE SUBINTERVALS
!           errbnd    - REQUESTED ACCURACY max(epsabs,epsrel*
!                       abs(result))
!           *****1    - VARIABLE FOR THE LEFT INTERVAL
!           *****2    - VARIABLE FOR THE RIGHT INTERVAL
!           last      - INDEX FOR SUBDIVISION
!           nres      - NUMBER OF CALLS TO THE EXTRAPOLATION ROUTINE
!           numrl2    - NUMBER OF ELEMENTS CURRENTLY IN rlist2. IF AN
!                       appropriate approximation to the compounded
!                       integral has been obtained it is put in
!                       rlist2(numrl2) after numrl2 has been increased
!                       by one.
!           small     - LENGTH OF THE SMALLEST INTERVAL CONSIDERED
!                       up to now, multiplied by 1.5
!           erlarg    - SUM OF THE ERRORS OVER THE INTERVALS LARGER
!                       than the smallest interval considered up to now
!           extrap    - LOGICAL VARIABLE DENOTING THAT THE ROUTINE
!                       is attempting to perform extrapolation
!                       I.E. before subdividing the smallest interval
!                       we try to decrease the value of erlarg.
!           noext     - LOGICAL VARIABLE DENOTING THAT EXTRAPOLATION
!                       is no longer allowed (true value)
!
!            Machine dependent constants
!            ---------------------------
!
!           epmach is the largest relative spacing.
!           uflow is the smallest positive magnitude.
!           OFLOW is the largest positive magnitude.
!
epmach = spmpar(1)
uflow = spmpar(2)
oflow = spmpar(3)
!
!            Check epsabs and epsrel
!            -----------------------
!
neval = 0
last = 0
result = 0.0
abserr = 0.0
alist(1) = a
blist(1) = b
rlist(1) = 0.0
elist(1) = 0.0
ier = 6
if (epsabs .lt. 0.0 .or. epsrel .lt. 0.0) go to 999
ier = 0
rerr = amax1(epsrel, 50.0*epmach, 0.5e-14)
!
!           First approximation to the integral
!           -----------------------------------
!
ierro = 0
call qk21f (f, a, b, result, abserr, defabs, resabs, &
&epmach, uflow, id)
if (id .ne. 0) go to 999
neval = 21
!
!           Test on accuracy.
!
dres = abs(result)
errbnd = amax1(epsabs,rerr*dres)
last = 1
rlist(1) = result
elist(1) = abserr
iord(1) = 1
if (abserr .le. 100.0*epmach*defabs .and. abserr .gt. &
&errbnd) ier = 2
if (limit .eq. 1) ier = 1
if (ier .ne. 0) go to 999
!
!           Initialization
!           --------------
!
rlist2(1) = result
errmax = abserr
maxerr = 1
area = result
errsum = abserr
abserr = oflow
correc = 0.0
nrmax = 1
nres = 0
numrl2 = 2
ktmin = 0
extrap = .false.
noext = .false.
iroff1 = 0
iroff2 = 0
iroff3 = 0
ksgn = -1
if (dres .ge. (1.0 - 50.0*epmach)*defabs) ksgn = 1
t = 1.0 + 100.0*epmach
!
!           Main do-loop
!           ------------
!
do 90 last = 2,limit
!
!           Bisect the subinterval with the nrmax-TH largest
!           error estimate.
!
  a1 = alist(maxerr)
  b1 = 0.5*(alist(maxerr) + blist(maxerr))
  a2 = b1
  b2 = blist(maxerr)
  erlast = errmax
  call qk21f (f, a1, b1, area1, error1, resabs, defab1, &
&epmach, uflow, ier)
  if (ier .ne. 0) go to 100
  call qk21f (f, a2, b2, area2, error2, resabs, defab2, &
&epmach, uflow, ier)
  neval = neval + 42
!
!           Improve previous approximations to integral
!           and error and test for accuracy.
!
  area12 = area1 + area2
  erro12 = error1 + error2
  errsum = errsum + erro12 - errmax
  area = area + area12 - rlist(maxerr)
  if (defab1 .eq. error1 .or. defab2 .eq. error2) go to 15
  if (abs(rlist(maxerr) - area12) .gt. 0.1e-04*abs(area12) &
&.or. erro12 .lt. 0.99*errmax) go to 10
  if (extrap) iroff2 = iroff2 + 1
  if (.not.extrap) iroff1 = iroff1 + 1
10 if (last .gt. 10 .and. erro12 .gt. errmax) iroff3 = iroff3 + 1
15 rlist(maxerr) = area1
  rlist(last) = area2
  errbnd = amax1(epsabs,rerr*abs(area))
!
!           Test for roundoff error and eventually
!           set error flag.
!
  if (iroff1 + iroff2 .ge. 10 .or. iroff3 .ge. 20) ier = 2
  if (iroff2 .ge. 5) ierro = 3
!
!           Set error flag in the case that the number of
!           subintervals equals limit.
!
  if (last .eq. limit) ier = 1
!
!           Set error flag in the case of bad integrand behaviour
!           at a point of the integration range.
!
  if (amax1(abs(a1),abs(b2)) .le. &
&t*(abs(a2) + 0.1e+04*uflow)) ier = 4
!
!           Append the newly-created intervals to the list.
!
  if (error2 .gt. error1) go to 20
  alist(last) = a2
  blist(maxerr) = b1
  blist(last) = b2
  elist(maxerr) = error1
  elist(last) = error2
  go to 30
20 alist(maxerr) = a2
  alist(last) = a1
  blist(last) = b1
  rlist(maxerr) = area2
  rlist(last) = area1
  elist(maxerr) = error2
  elist(last) = error1
!
!           CALL SUBROUTINE qpsrt TO MAINTAIN THE DESCENDING ORDERING
!           in the list of error estimates and select the
!           subinterval with nrmax-TH largest error estimate (to be
!           bisected next).
!
30 call qpsrt (limit,last,maxerr,errmax,elist,iord,nrmax)
! ***JUMP OUT OF DO-LOOP
  if (errsum .le. errbnd) go to 115
! ***JUMP OUT OF DO-LOOP
  if (ier .ne. 0) go to 100
  if (last .eq. 2) go to 80
  if (noext) go to 90
  erlarg = erlarg - erlast
  if (abs(b1 - a1) .gt. small) erlarg = erlarg + erro12
  if (extrap) go to 40
!
!           Test whether the interval to be bisected next is the
!           smallest interval.
!
  if (abs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
  extrap = .true.
  nrmax = 2
40 if (ierro .eq. 3 .or. erlarg .le. ertest) go to 60
!
!           The smallest interval has the largest error.
!           Before bisecting decrease the sum of the errors
!           over the larger intervals (erlarg) and perform
!           extrapolation.
!
  id = nrmax
  jupbnd = last
  if (last .gt. (2 + limit/2)) jupbnd = limit + 3 - last
  do 50 k = id,jupbnd
    maxerr = iord(nrmax)
    errmax = elist(maxerr)
! ***JUMP OUT OF DO-LOOP
    if (abs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
    nrmax = nrmax + 1
50 continue
!
!           Perform extrapolation.
!
60 numrl2 = numrl2 + 1
  rlist2(numrl2) = area
  call qelg (numrl2, rlist2, reseps, abseps, res3la, nres, &
&epmach, oflow)
  ktmin = ktmin + 1
  if (ktmin .gt. 5 .and. abserr .lt. 0.1e-02*errsum) ier = 5
  if (abseps .ge. abserr) go to 70
  ktmin = 0
  abserr = abseps
  result = reseps
  correc = erlarg
  ertest = amax1(epsabs,rerr*abs(reseps))
! ***JUMP OUT OF DO-LOOP
  if (abserr .le. ertest) go to 100
!
!           Prepare bisection of the smallest interval.
!
70 if (numrl2 .eq. 1) noext = .true.
  if (ier .eq. 5) go to 100
  maxerr = iord(1)
  errmax = elist(maxerr)
  nrmax = 1
  extrap = .false.
  small = small*0.5
  erlarg = errsum
  go to 90
80 small = abs(b - a)*0.375
  erlarg = errsum
  ertest = errbnd
  rlist2(2) = area
90 continue
!
!           Set final result and error estimate.
!           ------------------------------------
!
100 if (abserr .eq. oflow) go to 115
if (ier + ierro .eq. 0) go to 110
if (ierro .eq. 3) abserr = abserr + correc
if (ier .eq. 0) ier = 3
if (result .ne. 0.0 .and. area .ne. 0.0) go to 105
if (abserr .gt. errsum) go to 115
if (area .eq. 0.0) go to 130
go to 110
105 if (abserr/abs(result) .gt. errsum/abs(area)) go to 115
!
!           Test on divergence.
!
110 if (ksgn .eq. -1 .and. amax1(abs(result),abs(area)) .le. &
&defabs*0.1e-01) go to 130
if (0.1e-01 .gt. (result/area) .or. (result/area) .gt. 0.1e+03 &
&.or. errsum .gt. abs(area)) ier = 6
go to 130
!
!           Compute global integral sum.
!
115 result = 0.0
do k = 1,last
   result = result + rlist(k)
end do
abserr = errsum
130 if (ier .gt. 2) ier = ier - 1
999 return
end subroutine qagse

subroutine qk21f (f, a, b, result, abserr, resabs, resasc, &
&epmach, uflow, isig)
implicit none
integer, intent(out) :: isig
real, intent(in) :: a
real, intent(inout) :: abserr
real, intent(in) :: b, epmach
real, intent(inout) :: resabs, resasc, result
real, intent(in) :: uflow
integer :: j, jtw, jtwm1
real :: absc, centr, dhlgth, fc, fsum, fval1, fval2, hlgth, resg, &
&resk, reskh, tol
real :: f
!-----------------------------------------------------------------------
!
! 1.        PURPOSE
!              TO COMPUTE I = INTEGRAL OF f OVER (a,b), WITH ERROR
!                             estimate
!                         j = INTEGRAL OF abs(f) OVER (a,b)
!
! 2.        PARAMETERS
!            on entry
!              f      - REAL
!                       function subprogram defining the integrand
!                       function f(x). the actual name for f needs
!                       to be declared E X T E R N A L in the
!                       calling program.
!
!              a      - REAL
!                       lower limit of integration
!
!              b      - REAL
!                       upper limit of integration
!
!              epmach - REAL
!                       the relative precision of the floating
!                       arithmetic being used.
!
!              uflow  - REAL
!                       the smallest positive magnitude.
!
!            On return
!              result - real
!                       approximation to the integral I
!                       result is computed by applying the 21-point
!                       Kronrod rule (RESK) obtained by optimal
!                       addition of abscissae to the 10-point Gauss
!                       RULE (resg).
!
!              abserr - REAL
!                       estimate of the modulus of the absolute error,
!                       which should not exceed abs(I-result)
!
!              resabs - REAL
!                       approximation to the integral j
!
!              resasc - REAL
!                       approximation to the integral of abs(f-I/(b-a))
!                       OVER (a,b)
!
!              isig   - INTEGER
!                       isig=0  THE INTEGRAL WAS APPROXIMATED.
!                       isig=5  THE INTERVAL (a,b) IS TOO SHORT.
!                               The integral cannot be computed.
!
! 3.        SUBROUTINES OR FUNCTIONS NEEDED
!                 - f (user-provided function)
!
!-----------------------------------------------------------------------
real :: fv1(10), fv2(10), wg(5), wgk(11), xgk(11)
external f
!
!           The abscissae and weights are given for the interval (-1,1).
!           Because of symmetry only the positive abscissae and their
!           corresponding weights are given.
!
!           xgk    - ABSCISSAE OF THE 21-POINT KRONROD RULE
!                    xgk(2), xgk(4), ...  abscissae of the 10-point
!                    Gauss rule
!                    xgk(1), xgk(3), ...  abscissae which are optimally
!                    added to the 10-point Gauss rule
!
!           wgk    - WEIGHTS OF THE 21-POINT KRONROD RULE
!
!           wg     - WEIGHTS OF THE 10-POINT GAUSS RULE
!
data xgk(1),xgk(2),xgk(3),xgk(4),xgk(5),xgk(6),xgk(7), &
&xgk(8),xgk(9),xgk(10),xgk(11)/ &
&0.9956571630258081e+00,     0.9739065285171717e+00, &
&0.9301574913557082e+00,     0.8650633666889845e+00, &
&0.7808177265864169e+00,     0.6794095682990244e+00, &
&0.5627571346686047e+00,     0.4333953941292472e+00, &
&0.2943928627014602e+00,     0.1488743389816312e+00, &
&0.0000000000000000e+00/
!
data wgk(1),wgk(2),wgk(3),wgk(4),wgk(5),wgk(6),wgk(7), &
&wgk(8),wgk(9),wgk(10),wgk(11)/ &
&0.1169463886737187e-01,     0.3255816230796473e-01, &
&0.5475589657435200e-01,     0.7503967481091995e-01, &
&0.9312545458369761e-01,     0.1093871588022976e+00, &
&0.1234919762620659e+00,     0.1347092173114733e+00, &
&0.1427759385770601e+00,     0.1477391049013385e+00, &
&0.1494455540029169e+00/
!
data wg(1),wg(2),wg(3),wg(4),wg(5)/ &
&0.6667134430868814e-01,     0.1494513491505806e+00, &
&0.2190863625159820e+00,     0.2692667193099964e+00, &
&0.2955242247147529e+00/
!
!
!           List of major variables
!           -----------------------
!
!           centr  - mid point of the interval
!           hlgth  - half-length of the interval
!           absc   - ABSCISSA
!           FVAL*  - function VALUE
!           resg   - result OF THE 10-POINT GAUSS FORMULA
!           RESK   - result OF THE 21-POINT KRONROD FORMULA
!           RESKH  - approximation to the mean value of f over (a,b),
!                    I.E. TO I/(b-a)
!
!
centr = 0.5*(a + b)
hlgth = 0.5*(b - a)
dhlgth = abs(hlgth)
!
!             Check if the interval (a,b) is too short
!
isig = 5
absc = abs(centr) + dhlgth*0.14
if (absc .eq. abs(centr)) return
!
!           Compute the 21-point Kronrod approximation to
!           the integral, and estimate the absolute error.
!
isig = 0
resg = 0.0
fc = f(centr)
resk = wgk(11)*fc
resabs = abs(resk)
do 10 j = 1,5
  jtw = 2*j
  absc = hlgth*xgk(jtw)
  fval1 = f(centr - absc)
  fval2 = f(centr + absc)
  fv1(jtw) = fval1
  fv2(jtw) = fval2
  fsum = fval1 + fval2
  resg = resg + wg(j)*fsum
  resk = resk + wgk(jtw)*fsum
  resabs = resabs + wgk(jtw)*(abs(fval1) + abs(fval2))
10 continue
do j = 1,5
  jtwm1 = 2*j - 1
  absc = hlgth*xgk(jtwm1)
  fval1 = f(centr - absc)
  fval2 = f(centr + absc)
  fv1(jtwm1) = fval1
  fv2(jtwm1) = fval2
  fsum = fval1 + fval2
  resk = resk + wgk(jtwm1)*fsum
  resabs = resabs + wgk(jtwm1)*(abs(fval1) + abs(fval2))
end do
reskh = resk*0.5
resasc = wgk(11)*abs(fc - reskh)
do j = 1,10
  resasc = resasc + wgk(j)*(abs(fv1(j)-reskh) + abs(fv2(j)-reskh))
end do
result = resk*hlgth
resabs = resabs*dhlgth
resasc = resasc*dhlgth
abserr = abs((resk - resg)*hlgth)
if (resasc .ne. 0.0 .and. abserr .ne. 0.0) &
&abserr = resasc*amin1(1.0, &
&(0.2e+03*abserr/resasc)**1.5)
tol = epmach*0.5e+02
if (resabs .gt. uflow/tol) abserr = amax1(abserr,tol*resabs)
return
end subroutine qk21f

subroutine qagi (f, bound, inf, epsabs, epsrel, result, abserr, &
&neval, ier, limit, lenw, last, iwork, work)
implicit none
integer, intent(out) :: ier
integer, intent(in) :: inf
integer, intent(out) :: last
integer, intent(in) :: lenw, limit
integer, intent(out) :: neval
real, intent(out) :: abserr
real, intent(in) :: bound, epsabs, epsrel
real, intent(out) :: result
integer :: l1, l2, l3
real :: f
!-----------------------------------------------------------------------
!
!                   Integration over infinite intervals
!
!-----------------------------------------------------------------------
!
!        Purpose
!           the routine calculates an approximation  result  to a given
!           INTEGRAL    I = INTEGRAL OF  f  OVER (bound,+INFINITY)
!                    OR I = INTEGRAL OF  f  OVER (-INFINITY,bound)
!                    OR I = INTEGRAL OF  f  OVER (-INFINITY,+INFINITY),
!           hopefully satisfying following claim for accuracy
!           abs(I-result).LE.max(epsabs,epsrel*abs(I)).
!
!        Parameters
!         on entry
!            f      - REAL
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X T E R N A L in the driver program.
!
!            bound  - real
!                     finite bound of integration range
!                     (has no meaning if interval is doubly-infinite)
!
!            inf    - INTEGER
!                     indicating the kind of integration range
!                     involved
!                     inf = 1 CORRESPONDS TO  (bound,+INFINITY),
!                     inf = -1            to  (-infinity,bound),
!                     inf = 2             to (-infinity,+infinity).
!
!            epsabs - REAL
!                     absolute accuracy requested
!
!            epsrel - REAL
!                     relative accuracy requested
!
!         On return
!            result - real
!                     approximation to the integral
!
!            abserr - REAL
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            neval  - INTEGER
!                     number of integrand evaluations
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                   - ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE. THE
!                             estimates for result and error are less
!                             reliable. It is assumed that the requested
!                             accuracy has not been achieved.
!
!                     ier = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more
!                             subdivisions by increasing the value
!                             of limit (and taking the according
!                             dimension adjustments into account).
!                             However, if this yields no improvement
!                             it is advised to analyze the integrand
!                             in order to determine the integration
!                             difficulties. If the position of a local
!                             difficulty can be determined (E.G.
!                             Singularity, discontinuity within the
!                             interval) one will probably gain from
!                             splitting up the interval at this point
!                             and calling the integrator on the
!                             subranges. If possible, an appropriate
!                             special-purpose integrator should be used,
!                             which is designed for handling the type
!                             of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS
!                             detected, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR OCCURS
!                             at some points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             Roundoff error is detected in the
!                             extrapolation table.
!                             It is assumed that the requested tolerance
!                             cannot be achieved, and that the returned
!                             result is the best which can be obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted that
!                             divergence can occur with any other value
!                             of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs
!                             OR epsrel IS NEGATIVE, limit .LT. 1,
!                             OR lenw .LT. 4 * limit.
!                             Result, abserr, neval, last are
!                             set to zero.
!
!         Dimensioning parameters
!            limit - integer
!                    dimensioning parameter for iwork
!                    limit determines the maximum number
!                    of subintervals in the partition of the given
!                    INTEGRATION INTERVAL (A,B), limit.GE.1.
!                    IF limit.LT.1, THE ROUTINE WILL END WITH
!                    ier = 6.
!
!            lenw  - INTEGER
!                    dimensioning parameter for work
!                    lenw must be at least limit*4.
!                    IF lenw.LT.limit*4, THE ROUTINE WILL END
!                    WITH ier = 6.
!
!            last  - integer
!                    on return, last equals the number of
!                    subintervals produced in the subdivision
!                    process, which determines the number of significant
!                    elements actually in the work arrays.
!
!         Work arrays
!            iwork - INTEGER
!                    vector of dimension at least limit, the first
!                    K elements of which contain pointers
!                    to the error estimates over the subintervals,
!                    such that work(limit*3+iwork(1)),... ,
!                    work(limit*3+iwork(K)) form a decreasing
!                    SEQUENCE, WITH K = last IF last.LE.(limit/2+2), AND
!                    K = limit+1-last OTHERWISE
!
!            work  - real
!                    vector of dimension at least lenw
!                    on return
!                    work(1), ..., work(last) contain the left
!                     END POINTS OF THE SUBINTERVALS IN THE
!                     partition of (A,B),
!                    work(limit+1), ..., work(limit+last) contain
!                     the right end points,
!                    work(limit*2+1), ..., work(limit*2+last)
!                     contain the integral approximations over
!                     the subintervals,
!                    work(limit*3+1), ..., work(limit*3+last)
!                     contain the error estimates.
!
!        Subroutines or functions needed
!              - qagie
!              - qk15i
!              - qpsrt
!              - qelg
!              - f (user provided function)
!              - spmpar
!
!-----------------------------------------------------------------------
real, intent(inout) :: work(lenw)
integer, intent(inout) :: iwork(limit)
external f
!
!         Check validity of limit and lenw.
!
ier = 6
neval = 0
last = 0
result = 0.0
abserr = 0.0
if (limit .lt. 1 .or. lenw .lt. limit*4) return
!
!         Prepare call for qagie.
!
l1 = limit + 1
l2 = limit + l1
l3 = limit + l2
!
call qagie (f,bound,inf,epsabs,epsrel,limit,result,abserr, &
&neval,ier,work(1),work(l1),work(l2),work(l3),iwork,last)
return
end subroutine qagi

subroutine qagie (f,bound,inf,epsabs,epsrel,limit,result,abserr, &
&neval,ier,alist,blist,rlist,elist,iord,last)
implicit none
!-----------------------------------------------------------------------
!
!                   Integration over infinite intervals
!
!-----------------------------------------------------------------------
!
!        Purpose
!           the routine calculates an approximation  result  to a given
!           INTEGRAL    I = INTEGRAL OF  F  OVER (bound,+INFINITY)
!                    OR I = INTEGRAL OF  F  OVER (-INFINITY,bound)
!                    OR I = INTEGRAL OF  F  OVER (-INFINITY,+INFINITY),
!           hopefully satisfying following claim for accuracy
!           abs(I-result).LE.max(epsabs,epsrel*abs(I)).
!
!        Parameters
!         on entry
!            F      - REAL
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X t E R N A L in the driver program.
!
!            bound  - real
!                     finite bound of integration range
!                     (has no meaning if interval is doubly-infinite)
!
!            inf    - INTEGER
!                     indicating the kind of integration range
!                     involved
!                     inf = 1 CORRESPONDS TO  (bound,+INFINITY),
!                     inf = -1            to  (-infinity,bound),
!                     inf = 2             to (-infinity,+infinity).
!
!            epsabs - REAL
!                     absolute accuracy requested
!
!            epsrel - REAL
!                     relative accuracy requested
!
!            limit  - integer
!                     gives an upper bound on the number of
!                     subintervals in the partition of (A,B),
!                     limit.GE.1
!
!         On return
!            result - real
!                     approximation to the integral
!
!            abserr - REAL
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            neval  - INTEGER
!                     number of integrand evaluations
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                   - ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE. THE
!                             estimates for result and error are less
!                             reliable. It is assumed that the requested
!                             accuracy has not been achieved.
!
!                     ier = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more
!                             subdivisions by increasing the value
!                             of limit (and taking the according
!                             dimension adjustments into account).
!                             However, if this yields no improvement
!                             it is advised to analyze the integrand
!                             in order to determine the integration
!                             difficulties. If the position of a local
!                             difficulty can be determined (E.G.
!                             Singularity, discontinuity within the
!                             interval) one will probably gain from
!                             splitting up the interval at this point
!                             and calling the integrator on the
!                             subranges. If possible, an appropriate
!                             special-purpose integrator should be used,
!                             which is designed for handling the type
!                             of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS
!                             detected, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR OCCURS
!                             at some points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             Roundoff error is detected in the
!                             extrapolation table.
!                             It is assumed that the requested tolerance
!                             cannot be achieved, and that the returned
!                             result is the best which can be obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted that
!                             divergence can occur with any other value
!                             of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs
!                             or epsrel is negative.
!                             Result, abserr, neval, last, rlist(1),
!                             elist(1) and iord(1) are set to zero.
!                             alist(1) and blist(1) are set to 0
!                             and 1 respectively.
!
!            alist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the left
!                     END POINTS OF THE SUBINTERVALS IN THE PARTITION
!                     of the transformed integration range (0,1).
!
!            blist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the right
!                     END POINTS OF THE SUBINTERVALS IN THE PARTITION
!                     of the transformed integration range (0,1).
!
!            rlist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the integral
!                     approximations on the subintervals
!
!            elist  - REAL
!                     vector of dimension at least limit,  the first
!                      last  elements of which are the moduli
!                     of the absolute error estimates on the
!                     subintervals
!
!            iord   - INTEGER
!                     vector of dimension limit, the first k
!                     elements of which are pointers to the
!                     error estimates over the subintervals,
!                     such that elist(iord(1)), ..., elist(iord(k))
!                     FORM A DECREASING SEQUENCE, WITH k = last
!                     IF last.LE.(limit/2+2), AND k = limit+1-last
!                     otherwise
!
!            last   - INTEGER
!                     number of subintervals actually produced
!                     in the subdivision process
!
!        Subroutines or functions needed
!              - qk15i
!              - qpsrt
!              - qelg
!              - F (user-provided function)
!              - spmpar
!
!-----------------------------------------------------------------------
real :: abseps
real, intent(out) :: abserr
real, intent(inout) :: alist
real :: area, area1, area12, area2, a1, a2
real, intent(inout) :: blist
real :: boun
real, intent(in) :: bound
real :: b1, b2, correc, defabs, defab1, defab2, dres
real, intent(inout) :: elist
real :: epmach
real, intent(in) :: epsabs, epsrel
real :: erlarg, erlast, errbnd, errmax, error1, error2, erro12, &
&errsum, ertest, f, oflow, rerr, resabs, reseps
real, intent(out) :: result
real :: res3la(3)
real, intent(inout) :: rlist
real :: rlist2(52), small, spmpar, t, uflow
integer :: id
integer, intent(out) :: ier
integer :: ierro
integer, intent(in) :: inf
integer, intent(inout) :: iord
integer :: iroff1, iroff2, iroff3, jupbnd, k, ksgn, ktmin
integer, intent(out) :: last
integer, intent(in) :: limit
integer :: maxerr
integer, intent(out) :: neval
integer :: nres, nrmax, numrl2
logical :: extrap, noext
!
dimension alist(limit), blist(limit), elist(limit), iord(limit), &
&rlist(limit)
!
external f
!
!            The dimension of rlist2 is determined by the value of
!            LIMEXP in subroutine qelg.
!
!
!            List of major variables
!            -----------------------
!
!           alist     - LIST OF LEFT END POINTS OF ALL SUBINTERVALS
!                       considered up to now
!           blist     - LIST OF RIGHT END POINTS OF ALL SUBINTERVALS
!                       considered up to now
!           rlist(I)  - approximation to the integral over
!                       (alist(I),blist(I))
!           rlist2    - ARRAY OF DIMENSION AT LEAST (LIMEXP+2),
!                       containing the part of the epsilon table
!                       wich is still needed for further computations
!           elist(I)  - error estimate applying to rlist(I)
!           maxerr    - POINTER TO THE INTERVAL WITH LARGEST ERROR
!                       estimate
!           errmax    - elist(maxerr)
!           erlast    - ERROR ON THE INTERVAL CURRENTLY SUBDIVIDED
!                       (before that subdivision has taken place)
!           area      - SUM OF THE INTEGRALS OVER THE SUBINTERVALS
!           ERRSUM    - SUM OF THE ERRORS OVER THE SUBINTERVALS
!           errbnd    - REQUESTED ACCURACY max(epsabs,epsrel*
!                       abs(result))
!           *****1    - VARIABLE FOR THE LEFT SUBINTERVAL
!           *****2    - VARIABLE FOR THE RIGHT SUBINTERVAL
!           last      - INDEX FOR SUBDIVISION
!           nres      - NUMBER OF CALLS TO THE EXTRAPOLATION ROUTINE
!           numrl2    - NUMBER OF ELEMENTS CURRENTLY IN rlist2. IF AN
!                       appropriate approximation to the compounded
!                       integral has been obtained, it is put in
!                       rlist2(numrl2) after numrl2 has been increased
!                       by one.
!           small     - LENGTH OF THE SMALLEST INTERVAL CONSIDERED UP
!                       to now, multiplied by 1.5
!           erlarg    - SUM OF THE ERRORS OVER THE INTERVALS LARGER
!                       than the smallest interval considered up to now
!           extrap    - LOGICAL VARIABLE DENOTING THAT THE ROUTINE
!                       is attempting to perform extrapolation. I.E.
!                       Before subdividing the smallest interval we
!                       try to decrease the value of erlarg.
!           noext     - LOGICAL VARIABLE DENOTING THAT EXTRAPOLATION
!                       is no longer allowed (TRUE-VALUE)
!
!            Machine dependent constants
!            ---------------------------
!
!           epmach is the largest relative spacing.
!           uflow is the smallest positive magnitude.
!           OFLOW is the largest positive magnitude.
!
epmach = spmpar(1)
uflow = spmpar(2)
oflow = spmpar(3)
!
!           Check epsabs and epsrel
!           -----------------------
!
neval = 0
last = 0
result = 0.0
abserr = 0.0
alist(1) = 0.0
blist(1) = 1.0
rlist(1) = 0.0
elist(1) = 0.0
iord(1) = 0
ier = 6
if (epsabs .lt. 0.0 .or. epsrel .lt. 0.0) go to 999
ier = 0
rerr = amax1(epsrel, 50.0*epmach, 0.5e-14)
!
!           First approximation to the integral
!           -----------------------------------
!
!           Determine the interval to be mapped onto (0,1).
!           IF inf = 2 THE INTEGRAL IS COMPUTED AS I = I1+I2, WHERE
!           I1 = INTEGRAL OF F OVER (-INFINITY,0),
!           I2 = INTEGRAL OF F OVER (0,+INFINITY).
!
boun = bound
if (inf .eq. 2) boun = 0.0
call qk15i (f, boun, inf, 0.0, 1.0, result, abserr, &
&defabs, resabs, epmach, uflow)
!
!           Test on accuracy
!
last = 1
rlist(1) = result
elist(1) = abserr
iord(1) = 1
dres = abs(result)
errbnd = amax1(epsabs,rerr*dres)
if (abserr .le. 100.0*epmach*defabs .and. abserr .gt. errbnd) &
&ier = 2
if (limit .eq. 1) ier = 1
if (ier .ne. 0 .or. (abserr .le. errbnd .and. abserr .ne. resabs) &
&.or. abserr .eq. 0.0) go to 130
!
!           Initialization
!           --------------
!
rlist2(1) = result
errmax = abserr
maxerr = 1
area = result
errsum = abserr
abserr = oflow
correc = 0.0
nrmax = 1
nres = 0
ktmin = 0
numrl2 = 2
extrap = .false.
noext = .false.
ierro = 0
iroff1 = 0
iroff2 = 0
iroff3 = 0
ksgn = -1
if (dres .ge. (1.0 - 50.0*epmach)*defabs) ksgn = 1
t = 1.0 + 100.0*epmach
!
!           Main do-loop
!           ------------
!
do 90 last = 2,limit
!
!           Bisect the subinterval with nrmax-TH largest
!           error estimate.
!
  a1 = alist(maxerr)
  b1 = 0.5*(alist(maxerr) + blist(maxerr))
  a2 = b1
  b2 = blist(maxerr)
  erlast = errmax
  call qk15i (f, boun, inf, a1, b1, area1, error1, &
&resabs, defab1, epmach, uflow)
  call qk15i (f, boun, inf, a2, b2, area2, error2, &
&resabs, defab2, epmach, uflow)
!
!           Improve previous approximations to integral
!           and error and test for accuracy.
!
  area12 = area1 + area2
  erro12 = error1 + error2
  errsum = errsum + erro12 - errmax
  area = area + area12 - rlist(maxerr)
  if (defab1 .eq. error1 .or. defab2 .eq. error2) go to 15
  if (abs(rlist(maxerr) - area12) .gt. 0.1e-04*abs(area12) &
&.or. erro12 .lt. 0.99*errmax) go to 10
  if (extrap) iroff2 = iroff2 + 1
  if (.not.extrap) iroff1 = iroff1 + 1
10 if (last .gt. 10 .and. erro12 .gt. errmax) iroff3 = iroff3 + 1
15 rlist(maxerr) = area1
  rlist(last) = area2
  errbnd = amax1(epsabs,rerr*abs(area))
!
!           Test for roundoff error and eventually
!           set error flag.
!
  if (iroff1 + iroff2 .ge. 10 .or. iroff3 .ge. 20) ier = 2
  if (iroff2 .ge. 5) ierro = 3
!
!           Set error flag in the case that the number of
!           subintervals equals limit.
!
  if (last .eq. limit) ier = 1
!
!           Set error flag in the case of bad integrand behaviour
!           at some points of the integration range.
!

  if (amax1(abs(a1),abs(b2)) .le. &
&t*(abs(a2) + 0.1e+04*uflow)) ier = 4
!
!           Append the newly-created intervals to the list.
!
  if (error2 .gt. error1) go to 20
  alist(last) = a2
  blist(maxerr) = b1
  blist(last) = b2
  elist(maxerr) = error1
  elist(last) = error2
  go to 30
20 alist(maxerr) = a2
  alist(last) = a1
  blist(last) = b1
  rlist(maxerr) = area2
  rlist(last) = area1
  elist(maxerr) = error2
  elist(last) = error1
!
!           CALL SUBROUTINE qpsrt TO MAINTAIN THE DESCENDING ORDERING
!           in the list of error estimates and select the
!           subinterval with nrmax-TH largest error estimate (to be
!           bisected next).
!
30 call qpsrt (limit,last,maxerr,errmax,elist,iord,nrmax)
  if (errsum .le. errbnd) go to 115
  if (ier .ne. 0) go to 100
  if (last .eq. 2) go to 80
  if (noext) go to 90
  erlarg = erlarg - erlast
  if (abs(b1 - a1) .gt. small) erlarg = erlarg + erro12
  if (extrap) go to 40
!
!           Test whether the interval to be bisected next is the
!           smallest interval.
!
  if (abs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
  extrap = .true.
  nrmax = 2
40 if (ierro .eq. 3 .or. erlarg .le. ertest) go to 60
!
!           The smallest interval has the largest error.
!           Before bisecting decrease the sum of the errors
!           over the larger intervals (erlarg) and perform
!           extrapolation.
!
  id = nrmax
  jupbnd = last
  if (last .gt. (2 + limit/2)) jupbnd = limit + 3 - last
  do 50 k = id,jupbnd
    maxerr = iord(nrmax)
    errmax = elist(maxerr)
    if (abs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
    nrmax = nrmax + 1
50 continue
!
!           Perform extrapolation.
!
60 numrl2 = numrl2 + 1
  rlist2(numrl2) = area
  call qelg (numrl2, rlist2, reseps, abseps, res3la, nres, &
&epmach, oflow)
  ktmin = ktmin + 1
  if (ktmin .gt. 5 .and. abserr .lt. 0.1e-02*errsum) ier = 5
  if (abseps .ge. abserr) go to 70
  ktmin = 0
  abserr = abseps
  result = reseps
  correc = erlarg
  ertest = amax1(epsabs,rerr*abs(reseps))
  if (abserr .le. ertest) go to 100
!
!            Prepare bisection of the smallest interval.
!
70 if (numrl2 .eq. 1) noext = .true.
  if (ier .eq. 5) go to 100
  maxerr = iord(1)
  errmax = elist(maxerr)
  nrmax = 1
  extrap = .false.
  small = small*0.5
  erlarg = errsum
  go to 90
80 small = 0.375
  erlarg = errsum
  ertest = errbnd
  rlist2(2) = area
90 continue
!
!           Set final result and error estimate.
!           ------------------------------------
!
100 if (abserr .eq. oflow) go to 115
if (ier + ierro .eq. 0) go to 110
if (ierro .eq. 3) abserr = abserr + correc
if (ier .eq. 0) ier = 3
if (result .ne. 0.0 .and. area .ne. 0.0) go to 105
if (abserr .gt. errsum) go to 115
if (area .eq. 0.0) go to 130
go to 110
105 if (abserr/abs(result) .gt. errsum/abs(area)) go to 115
!
!           Test on divergence
!
110 if (ksgn .eq. -1 .and. amax1(abs(result),abs(area)) .le. &
&defabs*0.1e-01) go to 130
if (0.1e-01 .gt. (result/area) .or. (result/area) .gt. 0.1e+03 &
&.or. errsum .gt. abs(area)) ier = 6
go to 130
!
!           Compute global integral sum.
!
115 result = 0.0
do k = 1,last
  result = result + rlist(k)
end do
abserr = errsum
130 neval = 30*last - 15
if (inf .eq. 2) neval = 2*neval
if (ier .gt. 2) ier = ier - 1
999 return
end subroutine qagie

subroutine qk15i (f, boun, inf, a, b, result, abserr, resabs, &
&resasc, epmach, uflow)
implicit none
integer, intent(in) :: inf
real, intent(in) :: a
real, intent(inout) :: abserr
real, intent(in) :: b, boun, epmach
real, intent(inout) :: resabs, resasc, result
real, intent(in) :: uflow
integer :: j
real :: absc, absc1, absc2, centr, dinf, fc, fsum, fval1, fval2, &
&hlgth, resg, resk, reskh, tabsc1, tabsc2, tol
real :: f
!-----------------------------------------------------------------------
!
! 1.        PURPOSE
!              the original (infinite) integration range is mapped
!              onto the interval (0,1) and (a,b) is a part of (0,1).
!              It is the purpose to compute
!              I = INTEGRAL OF TRANSFORMED INTEGRAND OVER (a,b),
!              j = INTEGRAL OF abs(TRANSFORMED INTEGRAND) OVER (a,b).
!
! 2.        PARAMETERS
!            on entry
!              f      - REAL
!                       function subprogram defining the integrand
!                       function f(x). the actual name for f needs
!                       to be declared E X T E R N A L in the
!                       calling program.
!
!              boun   - REAL
!                       finite bound of original integration
!                       RANGE (SET TO ZERO IF inf = +2)
!
!              inf    - INTEGER
!                       IF inf = -1, THE ORIGINAL INTERVAL IS
!                                   (-INFINITY,BOUND),
!                       IF inf = +1, THE ORIGINAL INTERVAL IS
!                                   (BOUND,+INFINITY),
!                       IF inf = +2, THE ORIGINAL INTERVAL IS
!                                   (-INFINITY,+INFINITY) and
!                       the integral is computed as the sum of two
!                       integrals, one over (-INFINITY,0)
!                       and one over (0,+INFINITY).
!
!              a      - REAL
!                       lower limit for integration over subrange
!                       of (0,1)
!
!              b      - REAL
!                       upper limit for integration over subrange
!                       of (0,1)
!
!              epmach - REAL
!                       the relative precision of the floating
!                       arithmetic being used.
!
!              uflow  - REAL
!                       the smallest positive magnitude.
!
!            On return
!              result - real
!                       approximation to the integral I
!                       result is computed by applying the 15-point
!                       Kronrod RULE(RESK) obtained by optimal
!                       addition of abscissae to the 7-point Gauss
!                       RULE(RESG).
!
!              abserr - REAL
!                       estimate of the modulus of the absolute error,
!                       which should equal or exceed abs(I-result)
!
!              resabs - REAL
!                       approximation to the integral j
!
!              resasc - REAL
!                       approximation to the integral of
!                       abs((TRANSFORMED INTEGRAND)-I/(b-a))
!                       OVER (a,b)
!
! 3.        SUBROUTINES OR FUNCTIONS NEEDED
!                 - f (user-provided function)
!
!-----------------------------------------------------------------------
real :: fv1(7), fv2(7), xgk(8), wgk(8), wg(8)
external f
!
!           The abscissae and weights are supplied for the interval
!           (-1,1).  Because of symmetry only the positive abscissae and
!           their corresponding weights are given.
!
!           xgk    - ABSCISSAE OF THE 15-POINT KRONROD RULE
!                    xgk(2), xgk(4), ... abscissae of the 7-point
!                    Gauss rule
!                    xgk(1), xgk(3), ...  abscissae which are optimally
!                    added to the 7-point Gauss rule
!
!           wgk    - WEIGHTS OF THE 15-POINT KRONROD RULE
!
!           wg     - WEIGHTS OF THE 7-POINT GAUSS RULE, CORRESPONDING
!                    to the abscissae xgk(2), xgk(4), ...
!                    wg(1), wg(3), ... are set to zero.
!
data xgk(1),xgk(2),xgk(3),xgk(4),xgk(5),xgk(6),xgk(7), &
&xgk(8)/ &
&0.9914553711208126e+00,     0.9491079123427585e+00, &
&0.8648644233597691e+00,     0.7415311855993944e+00, &
&0.5860872354676911e+00,     0.4058451513773972e+00, &
&0.2077849550078985e+00,     0.0000000000000000e+00/
!
data wgk(1),wgk(2),wgk(3),wgk(4),wgk(5),wgk(6),wgk(7), &
&wgk(8)/ &
&0.2293532201052922e-01,     0.6309209262997855e-01, &
&0.1047900103222502e+00,     0.1406532597155259e+00, &
&0.1690047266392679e+00,     0.1903505780647854e+00, &
&0.2044329400752989e+00,     0.2094821410847278e+00/
!
data wg(1),wg(2),wg(3),wg(4),wg(5),wg(6),wg(7),wg(8)/ &
&0.0000000000000000e+00,     0.1294849661688697e+00, &
&0.0000000000000000e+00,     0.2797053914892767e+00, &
&0.0000000000000000e+00,     0.3818300505051189e+00, &
&0.0000000000000000e+00,     0.4179591836734694e+00/
!
!
!           List of major variables
!           -----------------------
!
!           centr  - mid point of the interval
!           HLGTH  - half-length of the interval
!           absc*  - ABSCISSA
!           TABSC* - transformed abscissa
!           FVAL*  - function VALUE
!           RESG   - result OF THE 7-POINT GAUSS FORMULA
!           RESK   - result OF THE 15-POINT KRONROD FORMULA
!           RESKH  - approximation to the mean value of the transformed
!                    integrand over (a,b), I.E. to I/(b-a)
!
!
dinf = min0(1,inf)
!
centr = 0.5*(a + b)
hlgth = 0.5*(b - a)
tabsc1 = boun + dinf*(1.0 - centr)/centr
fval1 = f(tabsc1)
if (inf .eq. 2) fval1 = fval1 + f(-tabsc1)
fc = (fval1/centr)/centr
!
!           Compute the 15-point Kronrod approximation to
!           the integral, and estimate the error.
!
resg = wg(8)*fc
resk = wgk(8)*fc
resabs = abs(resk)
do j = 1,7
  absc = hlgth*xgk(j)
  absc1 = centr - absc
  absc2 = centr + absc
  tabsc1 = boun + dinf*(1.0 - absc1)/absc1
  tabsc2 = boun + dinf*(1.0 - absc2)/absc2
  fval1 = f(tabsc1)
  fval2 = f(tabsc2)
  if (inf .eq. 2) fval1 = fval1 + f(-tabsc1)
  if (inf .eq. 2) fval2 = fval2 + f(-tabsc2)
  fval1 = (fval1/absc1)/absc1
  fval2 = (fval2/absc2)/absc2
  fv1(j) = fval1
  fv2(j) = fval2
  fsum = fval1 + fval2
  resg = resg + wg(j)*fsum
  resk = resk + wgk(j)*fsum
  resabs = resabs + wgk(j)*(abs(fval1) + abs(fval2))
end do
reskh = resk*0.5
resasc = wgk(8)*abs(fc - reskh)
do j = 1,7
  resasc = resasc + wgk(j)*(abs(fv1(j)-reskh) + &
&abs(fv2(j)-reskh))
end do
result = resk*hlgth
resasc = resasc*hlgth
resabs = resabs*hlgth
abserr = abs((resk - resg)*hlgth)
if (resasc .ne. 0.0 .and. abserr .ne. 0.0) abserr = resasc* &
&amin1(1.0, (0.2e+03*abserr/resasc)**1.5)
tol = 50.0*epmach
if (resabs .gt. uflow/tol) abserr = amax1(abserr, tol*resabs)
return
end subroutine qk15i

subroutine qpsrt(limit,last,maxerr,ermax,elist,iord,nrmax)
implicit none
!     ..................................................................
!
! 1.        qpsrt
!           ordering routine
!              standard Fortran subroutine
!              real version
!
! 2.        PURPOSE
!              this routine maintains the descending ordering
!              in the list of the local error estimates resulting from
!              the interval subdivision process. At each call two error
!              estimates are inserted using the sequential search
!              method, top-down for the largest error estimate
!              and bottom-up for the smallest error estimate.
!
! 3.        CALLING SEQUENCE
!              call qpsrt(limit,last,maxerr,ermax,elist,iord,nrmax)
!
!           Parameters (meaning at output)
!              limit  - integer
!                       maximum number of error estimates the list
!                       can contain
!
!              last   - INTEGER
!                       number of error estimates currently
!                       in the list
!
!              maxerr - INTEGER
!                       maxerr points to the nrmax-TH largest error
!                       estimate currently in the list
!
!              ermax  - REAL
!                       nrmax-TH largest error estimate
!                       ermax = elist(maxerr)
!
!              elist  - REAL
!                       vector of dimension last containing
!                       the error estimates
!
!              iord   - INTEGER
!                       vector of dimension last, the first k
!                       elements of which contain pointers
!                       to the error estimates, such that
!                       elist(iord(1)),... , elist(iord(k))
!                       form a decreasing sequence, with
!                       k = last IF last.LE.(limit/2+2), AND
!                       k = limit+1-last OTHERWISE
!
!              nrmax  - INTEGER
!                       maxerr = iord(nrmax)
!
! 4.        NO SUBROUTINES OR FUNCTIONS NEEDED
!
!     ..................................................................
!
real :: elist
real, intent(inout) :: ermax
real :: errmax, errmin
integer :: i, ibeg, ido
integer, intent(inout) :: iord
integer :: isucc, j, jbnd, jupbn, k
integer, intent(in) :: last, limit
integer, intent(inout) :: maxerr, nrmax
dimension elist(last),iord(last)
!
!           Check whether the list contains more than
!           two error estimates.
!
!***FIRST EXECUTABLE STATEMENT  qpsrt
if(last.gt.2) go to 10
iord(1) = 1
iord(2) = 2
go to 90
!
!           This part of the routine is only executed
!           if, due to a difficult integrand, subdivision
!           increased the error estimate. In the normal case
!           the insert procedure should start after the
!           nrmax-TH largest error estimate.
!
10 errmax = elist(maxerr)
if(nrmax.eq.1) go to 30
ido = nrmax-1
do i = 1,ido
  isucc = iord(nrmax-1)
! ***JUMP OUT OF DO-LOOP
  if(errmax.le.elist(isucc)) go to 30
  iord(nrmax) = isucc
  nrmax = nrmax-1
   end do
!
!           Compute the number of elements in the list to
!           be maintained in descending order. This number
!           depends on the number of subdivisions still
!           allowed.
!
30 jupbn = last
if(last.gt.(limit/2+2)) jupbn = limit+3-last
errmin = elist(last)
!
!           Insert errmax by traversing the list top-down,
!           starting comparison from the element elist(iord(nrmax+1)).
!
jbnd = jupbn-1
ibeg = nrmax+1
if(ibeg.gt.jbnd) go to 50
do i=ibeg,jbnd
  isucc = iord(i)
! ***JUMP OUT OF DO-LOOP
  if(errmax.ge.elist(isucc)) go to 60
  iord(i-1) = isucc
end do
50 iord(jbnd) = maxerr
iord(jupbn) = last
go to 90
!
!           Insert errmin by traversing the list bottom-up.
!
60 iord(i-1) = maxerr
k = jbnd
do j=i,jbnd
  isucc = iord(k)
! ***JUMP OUT OF DO-LOOP
  if(errmin.lt.elist(isucc)) go to 80
  iord(k+1) = isucc
  k = k-1
end do
iord(i) = last
go to 90
80 iord(k+1) = last
!
!           Set maxerr and ermax.
!
90 maxerr = iord(nrmax)
ermax = elist(maxerr)
return
end subroutine qpsrt

subroutine qelg (n, epstab, result, abserr, res3la, nres, &
&epmach, oflow)
implicit none
integer, intent(inout) :: n, nres
real, intent(out) :: abserr
real, intent(in) :: epmach, oflow
real, intent(out) :: result
integer :: i, ib, ib2, ie, indx, k1, k2, k3, limexp, newelm, num
real :: delta1, delta2, delta3, e0, e1, e1abs, e2, e3, epsinf, &
&err1, err2, err3, error, res, ss, tol1, tol2, tol3
!-----------------------------------------------------------------------
!
! 1.        PURPOSE
!              the routine determines the limit of a given sequence of
!              approximations, by means of the epsilon algorithm
!              of P. wynn.
!              An estimate of the absolute error is also given.
!              The condensed epsilon table is computed. Only those
!              elements needed for the computation of the next diagonal
!              are preserved.
!
! 2.        PARAMETERS
!              n      - INTEGER
!                       epstab(n) contains the new element in the
!                       first column of the epsilon table.
!
!              epstab - REAL
!                       vector of dimension 52 containing the
!                       elements of the two lower diagonals of
!                       the triangular epsilon table
!                       the elements are numbered starting at the
!                       right-hand corner of the triangle.
!
!              result - real
!                       resulting approximation to the integral
!
!              abserr - REAL
!                       estimate of the absolute error computed from
!                       result and the 3 previous results
!
!              res3la - REAL
!                       vector of dimension 3 containing the last 3
!                       results
!
!              nres   - INTEGER
!                       number of calls to the routine
!                       (should be zero at first call)
!
!              epmach - REAL
!                       the relative precision of the floating
!                       arithmetic being used.
!
!              oflow  - REAL
!                       the largest positive magnitude.
!
! 3.        NO SUBROUTINES OR FUNCTIONS USED
!
!-----------------------------------------------------------------------
real, intent(inout) :: epstab(52), res3la(3)
!---------------------
!
!           List of major variables
!           -----------------------
!
!           e0     - THE 4 ELEMENTS ON WHICH THE
!           e1       COMPUTATION OF A NEW ELEMENT IN
!           e2       THE EPSILON TABLE IS BASED
!           e3                 e0
!                        e3    e1    NEW
!                              e2
!           newelm - number of elements to be computed in the new
!                    diagonal
!           ERROR  - ERROR = abs(e1-e0)+abs(e2-e1)+abs(NEW-e2)
!           result - the element in the new diagonal with least value
!                    of error
!
!           limexp is the maximum number of elements the epsilon
!           table can contain. If this number is reached, the upper
!           diagonal of the epsilon table is deleted.
!
nres = nres + 1
abserr = oflow
result = epstab(n)
if (n .lt. 3) go to 100
limexp = 50
epstab(n + 2) = epstab(n)
newelm = (n - 1)/2
epstab(n) = oflow
num = n
k1 = n
do 40 i = 1,newelm
  k2 = k1 - 1
  k3 = k1 - 2
  res = epstab(k1 + 2)
  e0 = epstab(k3)
  e1 = epstab(k2)
  e2 = res
  e1abs = abs(e1)
  delta2 = e2 - e1
  err2 = abs(delta2)
  tol2 = amax1(abs(e2),e1abs)*epmach
  delta3 = e1 - e0
  err3 = abs(delta3)
  tol3 = amax1(e1abs,abs(e0))*epmach
  if (err2 .gt. tol2 .or. err3 .gt. tol3) go to 10
!
!           If e0, e1 and e2 are equal to within machine
!           accuracy, convergence is assumed.
!           result = e2
!           abserr = abs(e1-e0) + abs(e2-e1)
!
  result = res
  abserr = err2 + err3
! ***JUMP OUT OF DO-LOOP
  go to 100
10 e3 = epstab(k1)
  epstab(k1) = e1
  delta1 = e1 - e3
  err1 = abs(delta1)
  tol1 = amax1(e1abs,abs(e3))*epmach
!
!           If two elements are very close to each other, omit
!           a part of the table by adjusting the value of n
!
  if (err1.le.tol1 .or. err2.le.tol2 .or. err3.le.tol3) go to 20
  ss = 1.0/delta1 + 1.0/delta2 - 1.0/delta3
  epsinf = abs(ss*e1)
!
!           Test to detect irregular behaviour in the table, and
!           eventually omit a part of the table adjusting the value
!           OF n.
!
  if (epsinf .gt. 0.1e-03) go to 30
20 n = i + i - 1
! ***JUMP OUT OF DO-LOOP
  go to 50
!
!           Compute a new element and eventually adjust
!           the value of result.
!
30 res = e1 + 1.0/ss
  epstab(k1) = res
  k1 = k1 - 2
  error = err2 + abs(res - e2) + err3
  if (error .gt. abserr) go to 40
  abserr = error
  result = res
40 continue
!
!           Shift the table.
!
50 if (n .eq. limexp) n = 2*(limexp/2) - 1
ib = 1
if ((num/2)*2 .eq. num) ib = 2
ie = newelm + 1
do i = 1,ie
  ib2 = ib + 2
  epstab(ib) = epstab(ib2)
  ib = ib2
end do
if (num .eq. n) go to 80
indx = num - n + 1
do i = 1,n
  epstab(i) = epstab(indx)
  indx = indx + 1
end do
80 if (nres .ge. 4) go to 90
res3la(nres) = result
abserr = oflow
go to 100
!
!           Compute error estimate
!
90 abserr = abs(result - res3la(3)) + abs(result - res3la(2)) + &
&abs(result - res3la(1))
res3la(1) = res3la(2)
res3la(2) = res3la(3)
res3la(3) = result
100 abserr = amax1(abserr,5.0*epmach*abs(result))
return
end subroutine qelg

subroutine qxgs (f,a,b,epsabs,epsrel,result,abserr,ier, &
&limit,leniw,lenw,last,iwork,work)
implicit none
!
!            The routine calculates an approximation result to a given
!            DEFINITE INTEGRAL  I = INTEGRAL OF f OVER (a,b),
!            hopefully satisfying following claim for accuracy
!            abs(I-result).LE.max(epsabs,epsrel*abs(I)).
!
!        Parameters
!         on entry
!            f      - REAL
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X T E R N A L in the driver program.
!
!            a      - REAL
!                     lower limit of integration
!
!            b      - REAL
!                     upper limit of integration
!
!            epsabs - REAL
!                     absolute accuracy requested
!
!            epsrel - REAL
!                     relative accuracy requested
!
!         On return
!            result - real
!                     approximation to the integral
!
!            abserr - REAL
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                     ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE
!                             the estimates for integral and error are
!                             less reliable. It is assumed that the
!                             requested accuracy has not been achieved.
!            Error messages
!                     ier = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more sub-
!                             divisions by increasing the value of limit
!                             (and taking the according dimension
!                             adjustments into account. However, if
!                             this yields no improvement it is advised
!                             to analyze the integrand in order to
!                             determine the integration difficulties. If
!                             the position of a local difficulty can be
!                             determined (E.G. singularity,
!                             discontinuity within the interval) one
!                             will probably gain from splitting up the
!                             interval at this point and calling the
!                             integrator on the subranges. If possible,
!                             an appropriate special-purpose integrator
!                             should be used, which is designed for
!                             handling the type of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS DETEC-
!                             ted, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR
!                             occurs at some points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             Roundoff error is detected in the
!                             extrapolation table. It is presumed that
!                             the requested tolerance cannot be
!                             achieved, and that the returned result is
!                             the best which can be obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted that
!                             divergence can occur with any other value
!                             of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs OR
!                             epsrel IS NEGATIVE, limit .LT. 1,
!                             lenw .LT. 46*limit, OR
!                             leniw .LT. 3*limit.
!                             Result, abserr, last are set to
!                             zero. Except when limit or lenw or leniw
!                             is invalid, iwork(1), work(limit*2+1) and
!                             work(limit*3+1) are set to zero, work(1)
!                             is set to A, and work(limit+1) to b.
!
!         Dimensioning parameters
!            limit - integer
!                    limit determines the maximum number of subintervals
!                    in the partition of the given integration interval
!                    (A,b), limit.GE.1.
!                    IF limit.LT.1, THE ROUTINE WILL END WITH ier = 6.
!
!            lenw  - INTEGER
!                    dimensioning parameter for work
!                    lenw must be at least limit*46.
!                    IF lenw.LT.limit*46, THE ROUTINE WILL END
!                    WITH ier = 6.
!
!            leniw - INTEGER
!                    dimensioning parameter for iwork
!                    leniw must be at least limit*3.
!                    IF lenw.LT.limit*3, THE ROUTINE WILL END
!                    WITH ier = 6.
!
!            last  - integer
!                    on return, last equals the number of subintervals
!                    produced in the subdivision process, which deter-
!                    mines the number of significant elements actually
!                    in the work arrays.
!
!         Work arrays
!            iwork - INTEGER
!                    vector of dimension at least 3*limit, the first K
!                    elements of which contain pointers
!                    to the error estimates over the subintervals
!                    such that work(limit*3+iwork(1)),... ,
!                    work(limit*3+iwork(K)) form a decreasing
!                    SEQUENCE, WITH K = last IF last.LE.(limit/2+2),
!                    AND K = limit+1-last OTHERWISE.
!
!            work  - real
!                    vector of dimension at least lenw
!                    on return
!                    work(1), ..., work(last) contain the left
!                     END-POINTS OF THE SUBINTERVALS IN THE
!                     partition of (a,b),
!                    work(limit+1), ..., work(limit+last) contain
!                     the right end-points,
!                    work(limit*2+1), ..., work(limit*2+last) contain
!                     the integral approximations over the subintervals,
!                    work(limit*3+1), ..., work(limit*3+last)
!                     contain the error estimates.
!                    work(limit*4+1), ... is the area reserved to store
!                     functional values.
!
real :: a
real, intent(out) :: abserr
real :: b
real, intent(in) :: epsabs, epsrel
real :: f
real, intent(out) :: result
real, intent(inout) :: work
integer, intent(out) :: ier
integer, intent(inout) :: iwork
integer, intent(out) :: last
integer, intent(in) :: leniw, lenw, limit
integer :: l1, l2, l3, l4, l5
!
dimension iwork(leniw),work(lenw)
!
external f
!
!         Check validity of limit,leniw and lenw.
!
ier = 6
last = 0
result = 0.0
abserr = 0.0
if (limit.lt.1 .or. leniw.lt.limit*3 .or. lenw.lt.limit*46) &
&return
!
!         Prepare call for qxgse.
!
l1 = limit + 1
l2 = limit + l1
l3 = limit + l2
l4 = limit + l3
l5 = 21*limit + l4
!
call qxgse(f,a,b,epsabs,epsrel,limit,result,abserr, &
&ier,work(1),work(l1),work(l2),work(l3),iwork,last, &
&work(l4),work(l5),iwork(l1),iwork(l2))
!
return
end subroutine qxgs

subroutine qxgse(f,a,b,epsabs,epsrel,limit,result,abserr, &
&ier,alist,blist,rlist,elist,iord,last,valp,valn,lp,ln)
implicit none
!
!            The routine calculates an approximation result to A
!            DEFINITE INTEGRAL I = INTEGRAL OF F OVER (a,b),
!            hopefully satisfying following claim for accuracy
!            abs(I-result).LE.max(epsabs,epsrel*abs(I)).
!
!        Parameters
!         on entry
!            F      - REAL
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X t E R N A L in the driver program.
!
!            a      - REAL
!                     lower limit of integration
!
!            b      - REAL
!                     upper limit of integration
!
!            epsabs - REAL
!                     absolute accuracy requested
!
!            epsrel - REAL
!                     relative accuracy requested
!
!            limit  - integer
!                     gives an upperbound on the number of subintervals
!                     in the partition of (a,b)
!
!         On return
!            result - real
!                     approximation to the integral
!
!            abserr - REAL
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                     ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE
!                             the estimates for integral and error are
!                             less reliable. It is assumed that the
!                             requested accuracy has not been achieved.
!            Error messages
!                         = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more sub-
!                             divisions by increasing the value of limit
!                             (and taking the according dimension
!                             adjustments into account). However, if
!                             this yields no improvement it is advised
!                             to analyze the integrand in order to
!                             determine the integration difficulties. If
!                             the position of a local difficulty can be
!                             determined (E.G. singularity,
!                             discontinuity within the interval) one
!                             will probably gain from splitting up the
!                             interval at this point and calling the
!                             integrator on the subranges. If possible,
!                             an appropriate special-purpose integrator
!                             should be used, which is designed for
!                             handling the type of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS DETEC-
!                             ted, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR
!                             occurs at some points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             Roundoff error is detected in the
!                             extrapolation table.
!                             It is presumed that the requested
!                             tolerance cannot be achieved, and that the
!                             returned result is the best which can be
!                             obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted that
!                             divergence can occur with any other value
!                             of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs OR
!                             epsrel is negative. Result, abserr,
!                             last, rlist(1), iord(1), and elist(1)
!                             are set to zero. alist(1) and blist(1)
!                             are set to A and b respectively.
!
!            alist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the left end points
!                     of the subintervals in the partition of the
!                     given integration range (a,b)
!
!            blist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the right end points
!                     of the subintervals in the partition of the given
!                     integration range (a,b)
!
!            rlist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the integral
!                     approximations on the subintervals
!
!            elist  - REAL
!                     vector of dimension at least limit, the first
!                      last  elements of which are the moduli of the
!                     absolute error estimates on the subintervals
!
!            iord   - INTEGER
!                     vector of dimension at least limit, the first k
!                     elements of which are pointers to the
!                     error estimates over the subintervals,
!                     such that elist(iord(1)), ..., elist(iord(k))
!                     FORM A DECREASING SEQUENCE, WITH k = last
!                     IF last.LE.(limit/2+2), AND k = limit+1-last
!                     otherwise
!
!            last   - INTEGER
!                     number of subintervals actually produced in the
!                     subdivision process
!
!            valp   - REAL
!            valn     ARRAYS OF DIMENSION AT LEAST (21,limit) USED TO
!                     save the functional values
!
!            lp     - INTEGER
!            ln       VECTORS OF DIMENSION AT LEAST LIMIT, USED TO
!                     store the actual number of functional values
!                     saved in the corresponding column
!                     OF valp,valn
!
!***ROUTINES CALLED  F,spmpar,qelg,qxlqm,qpsrt,qxrrd,qxcpy
!
real :: a, abseps
real, intent(out) :: abserr
real, intent(inout) :: alist
real :: area, area1, area12, area2, a1, a2, b
real, intent(inout) :: blist
real :: b1, b2, correc, defabs, defab1, defab2, dres
real, intent(inout) :: elist
real :: epmach
real, intent(in) :: epsabs, epsrel
real :: erlarg, erlast, errbnd, errmax, error1, error2, erro12, &
&errsum, ertest, f, oflow, rerr, resabs, reseps
real, intent(out) :: result
real :: res3la(3)
real, intent(inout) :: rlist
real :: rlist2(52), small, t, uflow
real, intent(inout) :: valp, valn
real :: vp1(21), vp2(21), vn1(21), vn2(21), spmpar
integer :: id
integer, intent(out) :: ier
integer :: ierro
integer, intent(inout) :: iord
integer :: iroff1, iroff2, iroff3, jupbnd, k, ksgn, ktmin
integer, intent(out) :: last
integer, intent(in) :: limit
integer :: maxerr, nres, nrmax, numrl2
integer, intent(inout) :: lp(limit), ln(limit)
integer :: lp1, lp2, ln1, ln2
logical :: extrap, noext
!
dimension alist(limit), blist(limit), elist(limit), iord(limit), &
&rlist(limit), valp(21,limit), valn(21,limit)
!
external f
!
!            Machine dependent constants
!            ---------------------------
!
!          epmach is the largest relative spacing.
!          uflow is the smallest positive magnitude.
!          OFLOW is the largest positive magnitude.
!
epmach = spmpar(1)
uflow = spmpar(2)
oflow = spmpar(3)
!
!            Test on validity of parameters
!            ------------------------------
last = 0
result = 0.0
abserr = 0.0
alist(1) = a
blist(1) = b
rlist(1) = 0.0
elist(1) = 0.0
ier = 6
if (epsabs .lt. 0.0 .or. epsrel.lt. 0.0) go to 999
ier = 0
rerr = amax1(epsrel, 50.0*epmach)
!
!           First approximation to the integral
!           -----------------------------------
!
ierro = 0
lp(1) = 1
ln(1) = 1
valp(1,1) = f((a + b)*0.5)
valn(1,1) = valp(1,1)
call qxlqm (f,a,b,result,abserr,defabs,resabs, &
&valp(1,1),valn(1,1),lp(1),ln(1),2, &
&epmach,uflow,oflow)
!
!           Test on accuracy.
!
dres = abs(result)
errbnd = amax1(epsabs,rerr*dres)
last = 1
rlist(1) = result
elist(1) = abserr
iord(1) = 1
if (abserr .le. 100.0*epmach*defabs .and. abserr .gt. &
&errbnd) ier = 2
if (limit .eq. 1) ier = 1
if (ier .ne. 0 .or. (abserr.le.errbnd.and.abserr.ne.resabs) .or. &
&abserr .eq. 0.0) go to 999
!
!           Initialization
!           --------------
!
rlist2(1) = result
errmax = abserr
maxerr = 1
area = result
errsum = abserr
abserr = oflow
nrmax = 1
nres = 0
numrl2 = 2
ktmin = 0
extrap = .false.
noext = .false.
iroff1 = 0
iroff2 = 0
iroff3 = 0
ksgn = -1
if (dres .ge. (1.0 - 50.0*epmach)*defabs) ksgn = 1
t = 1.0 + 100.0*epmach
!
!           Main do-loop
!           ------------
!
do 90 last = 2,limit
!
!           Bisect the subinterval with the nrmax-TH largest error
!           estimate.
!
  a1 = alist(maxerr)
  b1 = 0.5*(alist(maxerr) + blist(maxerr))
  a2 = b1
  b2 = blist(maxerr)
  erlast = errmax
  call qxrrd(f,valn(1,maxerr),ln(maxerr),b1,a1,vn1,vp1,ln1,lp1)
  call qxlqm(f,a1,b1,area1,error1,resabs,defab1,vp1,vn1,lp1,ln1, &
&2,epmach,uflow,oflow)
  call qxrrd(f,valp(1,maxerr),lp(maxerr),a2,b2,vp2,vn2,lp2,ln2)
  call qxlqm(f,a2,b2,area2,error2,resabs,defab2,vp2,vn2,lp2,ln2, &
&2,epmach,uflow,oflow)
!
!           Improve previous approximations to integral
!           and error and test for accuracy.
!
  area12 = area1 + area2
  erro12 = error1 + error2
  errsum = errsum + erro12 - errmax
  area = area + area12 - rlist(maxerr)
  if (defab1 .eq. error1 .or. defab2 .eq. error2) go to 15
  if (abs(rlist(maxerr) - area12) .gt. 0.1e-04*abs(area12) &
&.or. erro12 .lt. 0.99*errmax) go to 10
  if (extrap) iroff2 = iroff2 + 1
  if (.not.extrap) iroff1 = iroff1 + 1
10 if (last.gt.10 .and. erro12.gt.errmax) iroff3 = iroff3 + 1
15 rlist(maxerr) = area1
  rlist(last) = area2
  errbnd = amax1(epsabs,rerr*abs(area))
!
!           Test for roundoff error and eventually set error flag.
!
  if (iroff1 + iroff2 .ge. 10 .or. iroff3 .ge. 20) ier = 2
  if (iroff2 .ge. 5) ierro = 3
!
!           Set error flag in the case that the number of subintervals
!           equals limit.
!
  if (last .eq. limit) ier = 1
!
!           Set error flag in the case of bad integrand behaviour
!           at a point of the integration range.
!
  if (amax1(abs(a1),abs(b2)) .le. &
&t*(abs(a2) + 1.e+03*uflow)) ier = 4
!
!           Append the newly-created intervals to the list.
!
  if (error2 .gt. error1) go to 20
  alist(last) = a2
  blist(maxerr) = b1
  blist(last) = b2
  elist(maxerr) = error1
  elist(last) = error2
  call qxcpy(valp(1,maxerr),vp1,lp1)
  lp(maxerr) = lp1
  call qxcpy(valn(1,maxerr),vn1,ln1)
  ln(maxerr) = ln1
  call qxcpy(valp(1,last),vp2,lp2)
  lp(last) = lp2
  call qxcpy(valn(1,last),vn2,ln2)
  ln(last) = ln2
  go to 30
!
20 alist(maxerr) = a2
  alist(last) = a1
  blist(last) = b1
  rlist(maxerr) = area2
  rlist(last) = area1
  elist(maxerr) = error2
  elist(last) = error1
  call qxcpy(valp(1,maxerr),vp2,lp2)
  lp(maxerr) = lp2
  call qxcpy(valn(1,maxerr),vn2,ln2)
  ln(maxerr) = ln2
  call qxcpy(valp(1,last),vp1,lp1)
  lp(last) = lp1
  call qxcpy(valn(1,last),vn1,ln1)
  ln(last) = ln1
!
!           CALL SUBROUTINE qpsrt TO MAINTAIN THE DESCENDING ORDERING
!           in the list of error estimates and select the subinterval
!           with nrmax-TH largest error estimate (to be bisected next).
!
30 call qpsrt(limit,last,maxerr,errmax,elist,iord,nrmax)
! ***JUMP OUT OF DO-LOOP
  if(errsum .le. errbnd) go to 115
! ***JUMP OUT OF DO-LOOP
  if (ier .ne. 0) go to 100
  if (last .eq. 2) go to 80
  if (noext) go to 90
  erlarg = erlarg - erlast
  if (abs(b1 - a1) .gt. small) erlarg = erlarg + erro12
  if (extrap) go to 40
!
!           Test whether the interval to be bisected next is the
!           smallest interval.
!
  if (abs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
  extrap = .true.
  nrmax = 2
!
!           The bound 0.3*ERTEST has been introduced to perform A
!           more cautious extrapolation than in the original dqagse
!           routine
!
40 if (ierro .eq. 3 .or. erlarg .le. 0.3*ertest) go to 60
!
!           The smallest interval has the largest error.
!           Before bisecting decrease the sum of the errors over the
!           larger intervals (erlarg) and perform extrapolation.
!
  id = nrmax
  jupbnd = last
  if (last .gt. (2 + limit/2)) jupbnd = limit + 3 - last
  do 50 k = id,jupbnd
    maxerr = iord(nrmax)
    errmax = elist(maxerr)
! ***JUMP OUT OF DO-LOOP
    if(abs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
    nrmax = nrmax + 1
50 continue
!
!           Perform extrapolation.
!
60 numrl2 = numrl2 + 1
  rlist2(numrl2) = area
  call qelg (numrl2,rlist2,reseps,abseps,res3la,nres, &
&epmach,oflow)
  ktmin = ktmin + 1
  if (ktmin .gt. 5 .and. abserr .lt. 0.1e-02*errsum) ier = 5
  if (abseps .ge. abserr) go to 70
  ktmin = 0
  abserr = abseps
  result = reseps
  correc = erlarg
  ertest = amax1(epsabs,rerr*abs(reseps))
! ***JUMP OUT OF DO-LOOP
  if (abserr .le. ertest) go to 100
!
!           Prepare bisection of the smallest interval.
!
70 if (numrl2 .eq. 1) noext = .true.
  if (ier .eq. 5) go to 100
  maxerr = iord(1)
  errmax = elist(maxerr)
  nrmax = 1
  extrap = .false.
  small = small*0.5
  erlarg = errsum
  go to 90
80 small = abs(b - a)*0.375
  erlarg = errsum
  ertest = errbnd
  rlist2(2) = area
90 continue
!
!           Set final result and error estimate.
!           ------------------------------------
!
100 if (abserr .eq. oflow) go to 115
if (ier + ierro .eq. 0) go to 110
if (ierro .eq. 3) abserr = abserr + correc
if (ier .eq. 0) ier = 3
if (result .ne. 0.0 .and. area .ne. 0.0) go to 105
if (abserr .gt. errsum) go to 115
if (area .eq. 0.0) go to 130
go to 110
105 if (abserr/abs(result) .gt. errsum/abs(area)) go to 115
!
!           Test on divergence.
!
110 if(ksgn.eq.(-1).and.amax1(abs(result),abs(area)).le. &
&defabs*0.1e-01) go to 130
if(0.1e-01.gt.(result/area).or.(result/area).gt.0.1e+03 &
&.or.errsum.gt.abs(area)) ier = 6
go to 130
!
!           Compute global integral sum.
!
115 result = 0.0
do k = 1,last
   result = result + rlist(k)
end do
abserr = errsum
130 if (ier .gt. 2) ier = ier - 1
999 return
end subroutine qxgse

subroutine qxcpy (a, b, l)
implicit none
integer :: i
!
!  TO COPY THE REAL VECTOR b OF LENGTH l   i N T O
!          the real vector a of length l
!
integer, intent(in) :: l
real, intent(inout) :: a(l)
real, intent(in) :: b(l)
!
do 10 i = 1,l
10 a(i) = b(i)
return
end subroutine qxcpy

subroutine qxlqm (f,a,b,result,abserr,resabs,resasc,vr,vs,lr,ls, &
&key,epmach,uflow,oflow)
implicit none
!
!            TO COMPUTE I = INTEGRAL OF f OVER (a,b), WITH ERROR
!                           estimate
!                       J = INTEGRAL OF abs(f) OVER (a,b)
!
!           Parameters
!            on entry
!              f      - REAL
!                       function subprogram defining the integrand
!                       function f(x). the actual name for f needs to be
!                       declared E X t E R N A L in the driver program.
!
!              a      - REAL
!                       lower limit of integration
!
!              b      - REAL
!                       upper limit of integration
!
!              vr     - REAL
!                       vector of length lr containing the
!                       saved  functional values of positive abscissas
!
!              vs     - REAL
!                       vector of length ls containing the
!                       saved  functional values of negative abscissas
!
!              lr     - INTEGER
!              ls       NUMBER OF ELEMENTS IN
!                       vr,vs respectively
!
!            key    - INTEGER
!                     key for choice of local integration rule
!                     rms formulas are used with
!                      13 - 19               POINTS IF key.LT.1,
!                      13 - 19 - (27)        POINTS IF key = 1,
!                      13 - 19 - (27) - (41) POINTS IF key = 2,
!                           19 -  27  - (41) POINTS IF key = 3,
!                                 27  -  41  POINTS IF key.GT.3.
!
!                         (Rules) used if the function APPEARS
!                         enough regular
!
!              epmach - REAL
!                       the relative precision of the floating
!                       arithmetic being used.
!
!              uflow  - REAL
!                       the smallest positive magnitude.
!
!              oflow  - REAL
!                       the largest positive magnitude.
!
!            On return
!              result - real
!                       approximation to the integral I
!
!              abserr - REAL
!                       estimate of the modulus of the absolute error,
!                       which should not exceed abs(I-result)
!
!              resabs - REAL
!                       approximation to the integral J
!
!              resasc - REAL
!                       approximation to the integral of abs(f-I/(b-a))
!                       OVER (a,b)
!
!              vr     - REAL
!                       vector of length lr containing the
!                       saved  functional values of positive abscissas
!
!              vs     - REAL
!                       vector of length ls containing the
!                       saved  functional values of negative abscissas
!
!              lr     - INTEGER
!              ls       NUMBER OF ELEMENTS IN
!                       vr,vs respectively
!
!***ROUTINES CALLED  qxrul
!
real :: f
real, intent(in) :: a, b
real, intent(inout) :: result, abserr, resabs, resasc
real :: t
real, intent(in) :: epmach, oflow, uflow
real :: resg, resk, errold
real, intent(inout) :: vr(21), vs(21)
integer :: k, k0, k1, k2
integer, intent(in) :: key
integer :: key1
integer, intent(inout) :: lr, ls
external f
!
key1 = max0(key ,  0)
key1 = min0(key1,  4)
k0   = max0(key1-2,0)
k1   = k0 + 1
k2   = min0(key1+1,3)
!
call qxrul (f,a,b,resg,resabs,resasc,k0,k1,vr,vs,lr,ls)
errold = oflow
t = 10.0*epmach
do 10 k = k1,k2
  call qxrul (f,a,b,resk,resabs,resasc,k,k1,vr,vs,lr,ls)
  result = resk
  abserr = abs(resk - resg)
  if (resasc .ne. 0.0 .and. abserr .ne. 0.0) &
&abserr = resasc*amin1(1.0,(200.0*abserr/resasc)**1.5)
  if (resabs .gt. uflow/t) abserr = amax1(t*resabs,abserr)
  resg = resk
  if (abserr .gt. errold*0.16) go to 3000
  if (abserr .lt. 1000.0*epmach*resabs) go to 3000
  errold = abserr
10 continue
3000 continue
return
end subroutine qxlqm

subroutine qxrul (f,xl,xu,y,ya,ym,ke,k1,fv1,fv2,l1,l2)
implicit none
integer :: i, is, k, ks
!
!            TO COMPUTE i = INTEGRAL OF f OVER (A,B), WITH ERROR
!                           estimate
!            and conditionally compute
!                       j = INTEGRAL OF abs(f) OVER (A,B)
!                       by using an  rms rule
!           parameters
!            on entry
!              f      - REAL
!                       function subprogram defining the integrand
!                       function f(x). the actual name for f needs to be
!                       declared E X T E R N A L in the driver program.
!
!              xl     - REAL
!                       lower limit of integration
!
!              xu     - REAL
!                       upper limit of integration
!
!              ke     - INTEGER
!                     key for choice of local integration rule
!                     an rms rule is used with
!                         13      POINTS IF ke  = 2,
!                         19      POINTS IF ke  = 3,
!                         27      POINTS IF ke  = 4,
!                         42      POINTS IF ke  = 5
!
!              k1     INTEGER
!                     value of key for which the additional estimates
!                     ya, ym are to be computed
!
!              fv1    - REAL
!                       vector containing l1
!                       saved  functional values of positive abscissas
!
!              fv2    - REAL
!                       vector containing l2
!                       saved  functional values of negative abscissas
!
!              l1     - INTEGER
!              l2       NUMBER OF ELEMENTS IN fv1,fv2  RESPECTIVELY
!
!            On return
!              y      - REAL
!                       approximation to the integral i
!                       result is computed by applying the
!                       requested rms rule
!
!              ya     - REAL
!                       IF KEY = k1  APPROXIMATION TO THE INTEGRAL j
!                       ELSE UNCHANGED
!
!              ym     - REAL
!                       IF KEY = k1  APPROXIMATION TO THE INTEGRAL OF
!                                      abs(f-i/(xu-xl)   OVER (xl,xu)
!                       ELSE UNCHANGED
!
!              fv1    - REAL
!                       vector containing l1
!                       saved  functional values of positive abscissas
!
!              fv2    - REAL
!                       vector containing l2
!                       saved  functional values of negative abscissas
!
!              l1     - INTEGER
!              l2       NUMBER OF ELEMENTS IN fv1,fv2  RESPECTIVELY
!
!------------------------
real :: f
real, intent(in) :: xl, xu
real :: ldl
real, intent(out) :: y
real, intent(inout) :: ya, ym
real :: y2, xx(41), ww(52)
real, intent(inout) :: fv1(21), fv2(21)
real :: aa, bb, c
integer :: istart(4), len(4), j
integer, intent(in) :: ke, k1
integer, intent(inout) :: l1, l2
external f
!------------------------
data istart(1)/0/, istart(2)/7/, istart(3)/17/, istart(4)/31/
data len(1)/7/, len(2)/10/, len(3)/14/, len(4)/21/
!------------------------
data xx( 1)/.0                       /
data xx( 2)/.25000000000000000000e+00/
data xx( 3)/.50000000000000000000e+00/
data xx( 4)/.75000000000000000000e+00/
data xx( 5)/.87500000000000000000e+00/
data xx( 6)/.93750000000000000000e+00/
data xx( 7)/.10000000000000000000e+01/
data xx( 8)/.37500000000000000000e+00/
data xx( 9)/.62500000000000000000e+00/
data xx(10)/.96875000000000000000e+00/
data xx(11)/.12500000000000000000e+00/
data xx(12)/.68750000000000000000e+00/
data xx(13)/.81250000000000000000e+00/
data xx(14)/.98437500000000000000e+00/
data xx(15)/.18750000000000000000e+00/
data xx(16)/.31250000000000000000e+00/
data xx(17)/.43750000000000000000e+00/
data xx(18)/.56250000000000000000e+00/
data xx(19)/.84375000000000000000e+00/
data xx(20)/.90625000000000000000e+00/
data xx(21)/.99218750000000000000e+00/
!   Number of nodes 13
data ww(1)/1.303262173284849021810473057638590518409112513421e-1/
data ww(2)/2.390632866847646220320329836544615917290026806242e-1/
data ww(3)/2.630626354774670227333506083741355715758124943143e-1/
data ww(4)/2.186819313830574175167853094864355208948886875898e-1/
data ww(5)/2.757897646642836865859601197607471574336674206700e-2/
data ww(6)/1.055750100538458443365034879086669791305550493830e-1/
data ww(7)/1.571194260595182254168429283636656908546309467968e-2/
!   Number of nodes 19
data ww(8)/1.298751627936015783241173611320651866834051160074e-1/
data ww(9)/2.249996826462523640447834514709508786970828213187e-1/
data ww(15)/5.542699233295875168406783695143646338274805359780e-2/
data ww(10)/1.680415725925575286319046726692683040162290325505e-1/
data ww(16)/9.986735247403367525720377847755415293097913496236e-2/
data ww(11)/1.415567675701225879892811622832845252125600939627e-1/
data ww(12)/1.006482260551160175038684459742336605269707889822e-1/
data ww(13)/2.510604860724282479058338820428989444699235030871e-2/
data ww(17)/4.507523056810492466415880450799432587809828791196e-2/
data ww(14)/9.402964360009747110031098328922608224934320397592e-3/
!   Number of nodes 27
data ww(18)/6.300942249647773931746170540321811473310938661469e-2/
data ww(28)/1.239572396231834242194189674243818619042280816640e-1/
data ww(19)/1.261383225537664703012999637242003647020326905948e-1/
data ww(25)/1.235837891364555000245004813294817451524633100256e-1/
data ww(20)/1.273864433581028272878709981850307363453523117880e-1/
data ww(26)/1.148933497158144016800199601785309838604146040215e-1/
data ww(29)/2.501306413750310579525950767549691151739047969345e-2/
data ww(21)/8.576500414311820514214087864326799153427368592787e-2/
data ww(30)/4.915957918146130094258849161350510503556792927578e-2/
data ww(22)/7.102884842310253397447305465997026228407227220665e-2/
data ww(23)/5.026383572857942403759829860675892897279675661654e-2/
data ww(27)/1.252575774226122633391477702593585307254527198070e-2/
data ww(31)/2.259167374956474713302030584548274729936249753832e-2/
data ww(24)/4.683670010609093810432609684738393586390722052124e-3/
!   Number of nodes 41
data ww(32)/6.362762978782724559269342300509058175967124446839e-2/
data ww(42)/1.187141856692283347609436153545356484256869129472e-1/
data ww(46)/1.533126874056586959338368742803997744815413565014e-2/
data ww(33)/9.950065827346794643193261975720606296171462239514e-2/
data ww(47)/3.527159369750123100455704702965541866345781113903e-2/
data ww(39)/8.140326425945938045967829319725797511040878579808e-2/
data ww(48)/5.000556431653955124212795201196389006184693561679e-2/
data ww(34)/7.048220002718565366098742295389607994441704889441e-2/
data ww(49)/5.744164831179720106340717579281831675999717767532e-2/
data ww(40)/6.583213447600552906273539578430361199084485578379e-2/
data ww(43)/5.999947605385971985589674757013565610751028128731e-2/
data ww(35)/6.512297339398335645872697307762912795346716454337e-2/
data ww(44)/5.500937980198041736910257988346101839062581489820e-2/
data ww(50)/1.598823797283813438301248206397233634639162043386e-2/
data ww(36)/3.998229150313659724790527138690215186863915308702e-2/
data ww(51)/2.635660410220884993472478832884065450876913559421e-2/
data ww(37)/3.456512257080287509832054272964315588028252136044e-2/
data ww(41)/2.592913726450792546064232192976262988065252032902e-2/
data ww(45)/5.264422421764655969760271538981443718440340270116e-3/
data ww(52)/1.196003937945541091670106760660561117114584656319e-2/
data ww(38)/2.212167975884114432760321569298651047876071264944e-3/
!------------------------
k = ke + 1
is = istart(k)
ks = len(k)
ldl = xu - xl
bb = ldl*0.5
aa = xl + bb
!
y = 0.0
do 10 i = 1,ks
   c = bb*xx(i)
   if (i .gt. l1) fv1(i) = f(aa + c)
   if (i .gt. l2) fv2(i) = f(aa - c)
   j = is + i
   y = y + (fv1(i) + fv2(i))*ww(j)
10 continue
!
y2 = y
y = y*bb
if (l1 .lt. ks) l1 = ks
if (l2 .lt. ks) l2 = ks
if (ke .ne. k1) return
!
ya = 0.0
do 20 i = 1,ks
   j = is + i
   ya = ya + (abs(fv1(i)) + abs(fv2(i)))*ww(j)
20 continue
ya = ya*abs(bb)
!
y2 = y2*0.5
ym = 0.0
do 30 i = 1,ks
   j = is + i
   ym = ym + (abs(fv1(i) - y2) + abs(fv2(i) - y2))*ww(j)
30 continue
ym = ym*abs(bb)
return
end subroutine qxrul

subroutine qxrrd (f,z,lz,xl,xu,r,s,lr,ls)
implicit none
!
!            To reorder the computed functional values before
!            the bisection of an interval
!
!           Parameters
!            on entry
!              f      - REAL
!                       function subprogram defining the integrand
!                       function f(x). the actual name for f needs to be
!                       declared E X T E r N A L in the driver program.
!
!              xl     - REAL
!                       lower limit of interval
!
!              xu     - REAL
!                       upper limit of interval
!
!              z      - REAL
!                       vector containing lz
!                       saved  functional values
!
!              lz     - INTEGER
!                       number of elements in lz
!
!            On return
!              r      - REAL
!              s        VECTORS CONTAINING lr, ls
!                       saved  functional values for the new intervals
!
!              lr     - INTEGER
!              ls       NUMBER OF ELEMENTES IN r,s RESPECTIVELY
!
!***ROUTINES CALLED  f
!
real :: f
real, intent(inout) :: r(21), s(21)
real :: z(21)
real, intent(in) :: xu, xl
real :: dlen, centr
integer, intent(inout) :: lr, ls
integer, intent(in) :: lz
!
dlen = (xu - xl)*0.5
centr = xl + dlen
r(1) =  z(3)
r(2) =  z(9)
r(3) =  z(4)
r(4) =  z(5)
r(5) =  z(6)
r(6) =  z(10)
r(7) =  z(7)
s(1) =  z(3)
s(2) =  z(8)
s(3) =  z(2)
s(7) =  z(1)
if (lz .gt. 11) go to 10
!
r(8) =  f(centr + dlen*0.375)
r(9) =  f(centr + dlen*0.625)
r(10) = f(centr + dlen*0.96875)
lr = 10
if (lz .ne. 11) s(4) = f(centr - dlen*0.75)
if (lz .eq. 11) s(4) = z(11)
s(5) =  f(centr - dlen*0.875)
s(6) =  f(centr - dlen*0.9375)
s(8) =  f(centr - dlen*0.375)
s(9) =  f(centr - dlen*0.625)
s(10) = f(centr - dlen*0.96875)
ls = 10
return
!
10 r(8) = z(12)
r(9) = z(13)
r(10) = z(14)
lr = 10
s(4) = z(11)
s(5) = f(centr - dlen*0.875)
s(6) = f(centr - dlen*0.9375)
if (lz .gt. 14) go to 20
s(8)  = f(centr - dlen*0.375)
s(9)  = f(centr - dlen*0.625)
s(10) = f(centr - dlen*0.96875)
ls = 10
return
!
20 r(11) = z(18)
r(12) = z(19)
r(13) = z(20)
r(14) = z(21)
lr = 14
s(8) = z(16)
s(9) = z(15)
s(10) = f(centr - dlen*0.96875)
s(11) = z(17)
ls = 11
return
end subroutine qxrrd

subroutine dqags (f, a, b, epsabs, epsrel, result, abserr, &
&neval, ier, limit, lenw, last, iwork, work)
implicit none
integer, intent(out) :: last
!-----------------------------------------------------------------------
!
!           Double precision computation of a definite integral
!
!-----------------------------------------------------------------------
!
!        Purpose
!           the routine calculates an approximation  result  to a given
!           DEFINITE INTEGRAL   I = INTEGRAL OF  f  OVER (a,b),
!           hopefully satisfying following claim for accuracy
!           abs(I-result).LE.max(epsabs,epsrel*abs(I)).
!
!        Parameters
!         on entry
!            f      - DOUBLE PRECISION
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X T E R N A L in the driver program.
!
!            a      - DOUBLE PRECISION
!                     lower limit of integration
!
!            b      - DOUBLE PRECISION
!                     upper limit of integration
!
!            epsabs - double precision
!                     absolute accuracy requested
!
!            epsrel - double precision
!                     relative accuracy requested
!
!         On return
!            result - double precision
!                     approximation to the integral
!
!            abserr - double precision
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            neval  - INTEGER
!                     number of integrand evaluations
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                     ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE
!                             the estimates for integral and error are
!                             less reliable. It is assumed that the
!                             requested accuracy has not been achieved.
!
!                     ier = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more sub-
!                             divisions by increasing the value of
!                             limit (and taking the according
!                             dimension adjustments into account).
!                             However, if this yields no improvement
!                             it is advised to analyze the integrand
!                             in order to determine the integration
!                             difficulties. If the position of A
!                             local difficulty can be determined (E.G.
!                             Singularity, discontinuity within the
!                             interval) one will probably gain from
!                             splitting up the interval at this point
!                             and calling the integrator on the sub-
!                             ranges. If possible, an appropriate
!                             special-purpose integrator should be used,
!                             which is designed for handling the type
!                             of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS DETEC-
!                             ted, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR
!                             occurs at some  points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             It is presumed that the requested
!                             tolerance cannot be achieved, and that the
!                             returned result is the best which can be
!                             obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted
!                             that divergence can occur with any other
!                             value of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs
!                             OR epsrel IS NEGATIVE, limit .LT. 1,
!                             OR lenw .LT. 4 * limit.
!                             Result, abserr, neval, last are
!                             set to zero.
!
!         Dimensioning parameters
!            limit - integer
!                    dimensioning parameter for iwork
!                    limit determines the maximum number
!                    of subintervals in the partition of the given
!                    INTEGRATION INTERVAL (a,b), limit.GE.1.
!                    IF limit.LT.1, THE ROUTINE WILL END WITH
!                    ier = 6.
!
!            lenw  - INTEGER
!                    dimensioning parameter for work
!                    lenw must be at least limit*4.
!                    IF lenw.LT.limit*4, THE ROUTINE WILL END
!                    WITH ier = 6.
!
!            last  - integer
!                    on return, last equals the number of
!                    subintervals produced in the subdivision
!                    process, which determines the number of
!                    significant elements actually in the work
!                    arrays.
!
!         Work arrays
!            iwork - INTEGER
!                    vector of dimension at least limit, the first K
!                    elements of which contain pointers
!                    to the error estimates over the subintervals
!                    such that work(limit*3+iwork(1)),... ,
!                    work(limit*3+iwork(K)) form a decreasing
!                    SEQUENCE, WITH K = last IF last.LE.(limit/2+2), AND
!                    K = limit+1-last OTHERWISE
!
!            work  - double precision
!                    vector of dimension at least lenw
!                    on return
!                    work(1), ..., work(last) contain the left
!                     END POINTS OF THE SUBINTERVALS IN THE
!                     partition of (a,b),
!                    work(limit+1), ..., work(limit+last) contain
!                     the right end points,
!                    work(limit*2+1), ..., work(limit*2+last)
!                     contain the integral approximations over
!                     the subintervals,
!                    work(limit*3+1), ..., work(limit*3+last)
!                     contain the error estimates.
!
!         Subroutines or functions needed
!              - dqagse
!              - dqk21
!              - dqpsrt
!              - dqelg
!              - f (user-provided function)
!              - dpmpar
!
!-----------------------------------------------------------------------
double precision, intent(in) :: a
double precision, intent(out) :: abserr
double precision, intent(in) :: b, epsabs, epsrel
double precision :: f
double precision, intent(out) :: result
double precision, intent(inout) :: work
integer, intent(out) :: ier
integer, intent(inout) :: iwork
integer, intent(in) :: lenw, limit
integer :: l1, l2, l3
integer, intent(out) :: neval
!
dimension iwork(limit), work(lenw)
external f
!
!         Check validity of limit and lenw.
!
ier = 6
neval = 0
last = 0
result = 0.d0
abserr = 0.d0
if (limit .lt. 1 .or. lenw .lt. limit*4) return
!
!         Prepare call for dqagse.
!
l1 = limit + 1
l2 = limit + l1
l3 = limit + l2
!
call dqagse (f,a,b,epsabs,epsrel,limit,result,abserr,neval, &
&ier,work(1),work(l1),work(l2),work(l3),iwork,last)
return
end subroutine dqags

subroutine dqagse (f,a,b,epsabs,epsrel,limit,result,abserr, &
&neval,ier,alist,blist,rlist,elist,iord,last)
implicit none
!-----------------------------------------------------------------------
!
!           Double precision computation of a definite integral
!
!-----------------------------------------------------------------------
!
!        Purpose
!           the routine calculates an approximation  result  to a given
!           DEFINITE INTEGRAL   I = INTEGRAL OF  F  OVER (a,b),
!           hopefully satisfying following claim for accuracy
!           abs(I-result).LE.max(epsabs,epsrel*abs(I)).
!
!        Parameters
!         on entry
!            F      - DOUBLE PRECISION
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X t E R N A L in the driver program.
!
!            a      - DOUBLE PRECISION
!                     lower limit of integration
!
!            b      - DOUBLE PRECISION
!                     upper limit of integration
!
!            epsabs - double precision
!                     absolute accuracy requested
!
!            epsrel - double precision
!                     relative accuracy requested
!
!            limit  - integer
!                     gives an upperbound on the number of
!                     subintervals in the partition of (a,b)
!
!         On return
!            result - double precision
!                     approximation to the integral
!
!            abserr - double precision
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            neval  - INTEGER
!                     number of integrand evaluations
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                     ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE
!                             the estimates for integral and error are
!                             less reliable. It is assumed that the
!                             requested accuracy has not been achieved.
!
!                         = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more sub-
!                             divisions by increasing the value of
!                             limit (and taking the according
!                             dimension adjustments into account).
!                             However, if this yields no improvement
!                             it is advised to analyze the integrand
!                             in order to determine the integration
!                             difficulties. If the position of A
!                             local difficulty can be determined (E.G.
!                             Singularity, discontinuity within the
!                             interval) one will probably gain from
!                             splitting up the interval at this point
!                             and calling the integrator on the sub-
!                             ranges. If possible, an appropriate
!                             special-purpose integrator should be used,
!                             which is designed for handling the type
!                             of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS DETEC-
!                             ted, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR
!                             occurs at some  points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             It is presumed that the requested
!                             tolerance cannot be achieved, and that the
!                             returned result is the best which can be
!                             obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted
!                             that divergence can occur with any other
!                             value of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs
!                             or epsrel is negative.
!                             Result, abserr, neval, last, rlist(1),
!                             iord(1) and elist(1) are set to zero.
!                             alist(1) and blist(1) are set to A and b
!                             respectively.
!
!            alist  - double precision
!                     vector of dimension at least limit, the first
!                      last  elements of which are the left
!                     END POINTS OF THE SUBINTERVALS IN THE PARTITION
!                     of the given integration range (a,b)
!
!            blist  - double precision
!                     vector of dimension at least limit, the first
!                      last  elements of which are the right
!                     END POINTS OF THE SUBINTERVALS IN THE PARTITION
!                     of the given integration range (a,b)
!
!            rlist  - double precision
!                     vector of dimension at least limit, the first
!                      last  elements of which are the integral
!                     approximations on the subintervals
!
!            elist  - double precision
!                     vector of dimension at least limit, the first
!                      last  elements of which are the moduli
!                     of the absolute error estimates on the
!                     SUBINERVALS
!
!            iord   - INTEGER
!                     vector of dimension at least limit, the first k
!                     elements of which are pointers to the error
!                     estimates over the subintervals, such
!                     THAT elist(iord(1)), ..., elist(iord(k))
!                     FORM A DECREASING SEQUENCE, WITH k = last
!                     IF last.LE.(limit/2+2), AND k = limit+1-last
!                     otherwise
!
!            last   - INTEGER
!                     number of subintervals actually produced in the
!                     subdivision process
!
!         Subroutines or functions needed
!              - dqk21
!              - dqpsrt
!              - dqelg
!              - F (user-provided function)
!              - dpmpar
!
!-----------------------------------------------------------------------
double precision, intent(in) :: a
double precision :: abseps
double precision, intent(out) :: abserr
double precision, intent(inout) :: alist
double precision :: area, area1, area12, area2, a1, a2
double precision, intent(in) :: b
double precision, intent(inout) :: blist
double precision :: b1, b2, correc, defabs, defab1, defab2, &
&dpmpar, dres
double precision, intent(inout) :: elist
double precision :: epmach
double precision, intent(in) :: epsabs, epsrel
double precision :: erlarg, erlast, errbnd, errmax, error1, &
&error2, erro12, errsum, ertest, f, oflow, rerr, resabs, reseps
double precision, intent(out) :: result
double precision :: res3la(3)
double precision, intent(inout) :: rlist
double precision :: rlist2(52), small, t, uflow
integer :: id
integer, intent(out) :: ier
integer :: ierro
integer, intent(inout) :: iord
integer :: iroff1, iroff2, iroff3, jupbnd, k, ksgn, ktmin
integer, intent(out) :: last
integer, intent(in) :: limit
integer :: maxerr
integer, intent(out) :: neval
integer :: nres, nrmax, numrl2
logical :: extrap, noext
!
dimension alist(limit), blist(limit), elist(limit), iord(limit), &
&rlist(limit)
!
external f
!
!            The dimension of rlist2 is determined by the value of
!            LIMEXP in subroutine dqelg (rlist2 should be of dimension
!            (LIMEXP+2) at least).
!
!            List of major variables
!            -----------------------
!
!           alist     - LIST OF LEFT END POINTS OF ALL SUBINTERVALS
!                       considered up to now
!           blist     - LIST OF RIGHT END POINTS OF ALL SUBINTERVALS
!                       considered up to now
!           rlist(I)  - approximation to the integral over
!                       (alist(I),blist(I))
!           rlist2    - ARRAY OF DIMENSION AT LEAST LIMEXP+2
!                       containing the part of the epsilon table
!                       which is still needed for further computations
!           elist(I)  - error estimate applying to rlist(I)
!           maxerr    - POINTER TO THE INTERVAL WITH LARGEST ERROR
!                       estimate
!           errmax    - elist(maxerr)
!           erlast    - ERROR ON THE INTERVAL CURRENTLY SUBDIVIDED
!                       (before that subdivision has taken place)
!           area      - SUM OF THE INTEGRALS OVER THE SUBINTERVALS
!           ERRSUM    - SUM OF THE ERRORS OVER THE SUBINTERVALS
!           errbnd    - REQUESTED ACCURACY max(epsabs,epsrel*
!                       abs(result))
!           *****1    - VARIABLE FOR THE LEFT INTERVAL
!           *****2    - VARIABLE FOR THE RIGHT INTERVAL
!           last      - INDEX FOR SUBDIVISION
!           nres      - NUMBER OF CALLS TO THE EXTRAPOLATION ROUTINE
!           numrl2    - NUMBER OF ELEMENTS CURRENTLY IN rlist2. IF AN
!                       appropriate approximation to the compounded
!                       integral has been obtained it is put in
!                       rlist2(numrl2) after numrl2 has been increased
!                       by one.
!           small     - LENGTH OF THE SMALLEST INTERVAL CONSIDERED
!                       up to now, multiplied by 1.5
!           erlarg    - SUM OF THE ERRORS OVER THE INTERVALS LARGER
!                       than the smallest interval considered up to now
!           extrap    - LOGICAL VARIABLE DENOTING THAT THE ROUTINE
!                       is attempting to perform extrapolation
!                       I.E. before subdividing the smallest interval
!                       we try to decrease the value of erlarg.
!           noext     - LOGICAL VARIABLE DENOTING THAT EXTRAPOLATION
!                       is no longer allowed (true value)
!
!            Machine dependent constants
!            ---------------------------
!
!           epmach is the largest relative spacing.
!           uflow is the smallest positive magnitude.
!           OFLOW is the largest positive magnitude.
!
epmach = dpmpar(1)
uflow = dpmpar(2)
oflow = dpmpar(3)
!
!            Check epsabs and epsrel
!            -----------------------
!
neval = 0
last = 0
result = 0.d0
abserr = 0.d0
alist(1) = a
blist(1) = b
rlist(1) = 0.d0
elist(1) = 0.d0
ier = 6
if (epsabs .lt. 0.d0 .or. epsrel .lt. 0.d0) go to 999
ier = 0
rerr = dmax1(epsrel, 50.d0*epmach, 0.5d-28)
!
!           First approximation to the integral
!           -----------------------------------
!
ierro = 0
call dqk21 (f, a, b, result, abserr, defabs, resabs, &
&epmach, uflow, id)
if (id .ne. 0) go to 999
neval = 21
!
!           Test on accuracy.
!
dres = dabs(result)
errbnd = dmax1(epsabs,rerr*dres)
last = 1
rlist(1) = result
elist(1) = abserr
iord(1) = 1
if (abserr .le. 100.d0*epmach*defabs .and. abserr .gt. &
&errbnd) ier = 2
if (limit .eq. 1) ier = 1
if (ier .ne. 0) go to 999
!
!           Initialization
!           --------------
!
rlist2(1) = result
errmax = abserr
maxerr = 1
area = result
errsum = abserr
abserr = oflow
correc = 0.d0
nrmax = 1
nres = 0
numrl2 = 2
ktmin = 0
extrap = .false.
noext = .false.
iroff1 = 0
iroff2 = 0
iroff3 = 0
ksgn = -1
if (dres .ge. (1.d0 - 50.d0*epmach)*defabs) ksgn = 1
t = 1.d0 + 100.d0*epmach
!
!           Main do-loop
!           ------------
!
do 90 last = 2,limit
!
!           Bisect the subinterval with the nrmax-TH largest
!           error estimate.
!
  a1 = alist(maxerr)
  b1 = 0.5d0*(alist(maxerr) + blist(maxerr))
  a2 = b1
  b2 = blist(maxerr)
  erlast = errmax
  call dqk21 (f, a1, b1, area1, error1, resabs, defab1, &
&epmach, uflow, ier)
  if (ier .ne. 0) go to 100
  call dqk21 (f, a2, b2, area2, error2, resabs, defab2, &
&epmach, uflow, ier)
  neval = neval + 42
!
!           Improve previous approximations to integral
!           and error and test for accuracy.
!
  area12 = area1 + area2
  erro12 = error1 + error2
  errsum = errsum + erro12 - errmax
  area = area + area12 - rlist(maxerr)
  if (defab1 .eq. error1 .or. defab2 .eq. error2) go to 15
  if (dabs(rlist(maxerr) - area12) .gt. 0.1d-04*dabs(area12) &
&.or. erro12 .lt. 0.99d0*errmax) go to 10
  if (extrap) iroff2 = iroff2 + 1
  if (.not.extrap) iroff1 = iroff1 + 1
10 if (last .gt. 10 .and. erro12 .gt. errmax) iroff3 = iroff3 + 1
15 rlist(maxerr) = area1
  rlist(last) = area2
  errbnd = dmax1(epsabs,rerr*dabs(area))
!
!           Test for roundoff error and eventually
!           set error flag.
!
  if (iroff1 + iroff2 .ge. 10 .or. iroff3 .ge. 20) ier = 2
  if (iroff2 .ge. 5) ierro = 3
!
!           Set error flag in the case that the number of
!           subintervals equals limit.
!
  if (last .eq. limit) ier = 1
!
!           Set error flag in the case of bad integrand behaviour
!           at a point of the integration range.
!
  if (dmax1(dabs(a1),dabs(b2)) .le. &
&t*(dabs(a2) + 0.1d+04*uflow)) ier = 4
!
!           Append the newly-created intervals to the list.
!
  if (error2 .gt. error1) go to 20
  alist(last) = a2
  blist(maxerr) = b1
  blist(last) = b2
  elist(maxerr) = error1
  elist(last) = error2
  go to 30
20 alist(maxerr) = a2
  alist(last) = a1
  blist(last) = b1
  rlist(maxerr) = area2
  rlist(last) = area1
  elist(maxerr) = error2
  elist(last) = error1
!
!           CALL SUBROUTINE dqpsrt TO MAINTAIN THE DESCENDING ORDERING
!           in the list of error estimates and select the
!           subinterval with nrmax-TH largest error estimate (to be
!           bisected next).
!
30 call dqpsrt (limit,last,maxerr,errmax,elist,iord,nrmax)
! ***JUMP OUT OF DO-LOOP
  if (errsum .le. errbnd) go to 115
! ***JUMP OUT OF DO-LOOP
  if (ier .ne. 0) go to 100
  if (last .eq. 2) go to 80
  if (noext) go to 90
  erlarg = erlarg - erlast
  if (dabs(b1 - a1) .gt. small) erlarg = erlarg + erro12
  if (extrap) go to 40
!
!           Test whether the interval to be bisected next is the
!           smallest interval.
!
  if (dabs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
  extrap = .true.
  nrmax = 2
40 if (ierro .eq. 3 .or. erlarg .le. ertest) go to 60
!
!           The smallest interval has the largest error.
!           Before bisecting decrease the sum of the errors
!           over the larger intervals (erlarg) and perform
!           extrapolation.
!
  id = nrmax
  jupbnd = last
  if (last .gt. (2 + limit/2)) jupbnd = limit + 3 - last
  do 50 k = id,jupbnd
    maxerr = iord(nrmax)
    errmax = elist(maxerr)
! ***JUMP OUT OF DO-LOOP
    if (dabs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
    nrmax = nrmax + 1
50 continue
!
!           Perform extrapolation.
!
60 numrl2 = numrl2 + 1
  rlist2(numrl2) = area
  call dqelg (numrl2, rlist2, reseps, abseps, res3la, nres, &
&epmach, oflow)
  ktmin = ktmin + 1
  if (ktmin .gt. 5 .and. abserr .lt. 0.1d-02*errsum) ier = 5
  if (abseps .ge. abserr) go to 70
  ktmin = 0
  abserr = abseps
  result = reseps
  correc = erlarg
  ertest = dmax1(epsabs,rerr*dabs(reseps))
! ***JUMP OUT OF DO-LOOP
  if (abserr .le. ertest) go to 100
!
!           Prepare bisection of the smallest interval.
!
70 if (numrl2 .eq. 1) noext = .true.
  if (ier .eq. 5) go to 100
  maxerr = iord(1)
  errmax = elist(maxerr)
  nrmax = 1
  extrap = .false.
  small = small*0.5d0
  erlarg = errsum
  go to 90
80 small = dabs(b - a)*0.375d0
  erlarg = errsum
  ertest = errbnd
  rlist2(2) = area
90 continue
!
!           Set final result and error estimate.
!           ------------------------------------
!
100 if (abserr .eq. oflow) go to 115
if (ier + ierro .eq. 0) go to 110
if (ierro .eq. 3) abserr = abserr + correc
if (ier .eq. 0) ier = 3
if (result .ne. 0.d0 .and. area .ne. 0.d0) go to 105
if (abserr .gt. errsum) go to 115
if (area .eq. 0.d0) go to 130
go to 110
105 if (abserr/dabs(result) .gt. errsum/dabs(area)) go to 115
!
!           Test on divergence.
!
110 if (ksgn .eq. -1 .and. dmax1(dabs(result),dabs(area)) .le. &
&defabs*0.1d-01) go to 130
if (0.1d-01 .gt. (result/area) .or. (result/area) .gt. 0.1d+03 &
&.or. errsum .gt. dabs(area)) ier = 6
go to 130
!
!           Compute global integral sum.
!
115 result = 0.0
do k = 1,last
   result = result + rlist(k)
end do
abserr = errsum
130 if (ier .gt. 2) ier = ier - 1
999 return
end subroutine dqagse

subroutine dqk21 (f, a, b, result, abserr, resabs, resasc, &
&epmach, uflow, isig)
implicit none
!-----------------------------------------------------------------------
!
! 1.        PURPOSE
!              TO COMPUTE I = INTEGRAL OF f OVER (a,b), WITH ERROR
!                             estimate
!                         j = INTEGRAL OF dabs(f) OVER (a,b)
!
! 2.        PARAMETERS
!            on entry
!              f      - DOUBLE PRECISION
!                       function subprogram defining the integrand
!                       function f(x). the actual name for f needs
!                       to be declared E X T E R N A L in the
!                       calling program.
!
!              a      - DOUBLE PRECISION
!                       lower limit of integration
!
!              b      - DOUBLE PRECISION
!                       upper limit of integration
!
!              epmach - double precision
!                       the relative precision of the floating
!                       arithmetic being used.
!
!              uflow  - double precision
!                       the smallest positive magnitude.
!
!            On return
!              result - double precision
!                       approximation to the integral I
!                       result is computed by applying the 21-point
!                       Kronrod rule (resk) obtained by optimal
!                       addition of abscissae to the 10-point Gauss
!                       RULE (resg).
!
!              abserr - double precision
!                       estimate of the modulus of the absolute error,
!                       which should not exceed abs(I-result)
!
!              resabs - double precision
!                       approximation to the integral j
!
!              resasc - double precision
!                       approximation to the integral of abs(f-I/(b-a))
!                       OVER (a,b)
!
!              isig   - INTEGER
!                       isig=0  THE INTEGRAL WAS APPROXIMATED.
!                       isig=5  THE INTERVAL (a,b) IS TOO SHORT.
!                               The integral cannot be computed.
!
! 3.        SUBROUTINES OR FUNCTIONS NEEDED
!                 - f (user-provided function)
!
!-----------------------------------------------------------------------
double precision, intent(in) :: a
double precision :: absc
double precision, intent(inout) :: abserr
double precision, intent(in) :: b
double precision :: centr, dhlgth
double precision, intent(in) :: epmach
double precision :: f, fc, fsum, fval1, fval2, fv1(10), fv2(10), &
&hlgth
double precision, intent(inout) :: resabs
double precision :: resg, resk, reskh
double precision, intent(inout) :: result
double precision :: tol
double precision, intent(in) :: uflow
double precision :: wg(5), wgk(11), xgk(11)
double precision, intent(inout) :: resasc
integer, intent(out) :: isig
integer :: j, jtw, jtwm1
!
external f
!
!           The abscissae and weights are given for the interval (-1,1).
!           Because of symmetry only the positive abscissae and their
!           corresponding weights are given.
!
!           xgk    - ABSCISSAE OF THE 21-POINT KRONROD RULE
!                    xgk(2), xgk(4), ...  abscissae of the 10-point
!                    Gauss rule
!                    xgk(1), xgk(3), ...  abscissae which are optimally
!                    added to the 10-point Gauss rule
!
!           wgk    - WEIGHTS OF THE 21-POINT KRONROD RULE
!
!           wg     - WEIGHTS OF THE 10-POINT GAUSS RULE
!
data xgk(1),xgk(2),xgk(3),xgk(4),xgk(5),xgk(6),xgk(7), &
&xgk(8),xgk(9),xgk(10),xgk(11)/ &
&0.995657163025808080735527280689d+00, &
&0.973906528517171720077964012084d+00, &
&0.930157491355708226001207180060d+00, &
&0.865063366688984510732096688423d+00, &
&0.780817726586416897063717578345d+00, &
&0.679409568299024406234327365115d+00, &
&0.562757134668604683339000099273d+00, &
&0.433395394129247190799265943166d+00, &
&0.294392862701460198131126603104d+00, &
&0.148874338981631210884826001130d+00, &
&0.000000000000000000000000000000d+00/
!
data wgk(1),wgk(2),wgk(3),wgk(4),wgk(5),wgk(6),wgk(7), &
&wgk(8),wgk(9),wgk(10),wgk(11)/ &
&0.116946388673718742780643960622d-01, &
&0.325581623079647274788189724594d-01, &
&0.547558965743519960313813002446d-01, &
&0.750396748109199527670431409162d-01, &
&0.931254545836976055350654650834d-01, &
&0.109387158802297641899210590326d+00, &
&0.123491976262065851077958109831d+00, &
&0.134709217311473325928054001772d+00, &
&0.142775938577060080797094273139d+00, &
&0.147739104901338491374841515972d+00, &
&0.149445554002916905664936468390d+00/
!
data wg(1),wg(2),wg(3),wg(4),wg(5)/ &
&0.666713443086881375935688098933d-01, &
&0.149451349150580593145776339658d+00, &
&0.219086362515982043995534934228d+00, &
&0.269266719309996355091226921569d+00, &
&0.295524224714752870173892994651d+00/
!
!
!           List of major variables
!           -----------------------
!
!           centr  - mid point of the interval
!           HLGTH  - half-length of the interval
!           absc   - ABSCISSA
!           FVAL*  - function VALUE
!           resg   - result OF THE 10-POINT GAUSS FORMULA
!           resk   - result OF THE 21-POINT KRONROD FORMULA
!           reskh  - approximation to the mean value of f over (a,b),
!                    I.E. TO I/(b-a)
!
!
centr = 0.5d0*(a + b)
hlgth = 0.5d0*(b - a)
dhlgth = dabs(hlgth)
!
!             Check if the interval (a,b) is too short
!
isig = 5
absc = dabs(centr) + dhlgth*0.14d0
if (absc .eq. dabs(centr)) return
!
!           Compute the 21-point Kronrod approximation to
!           the integral, and estimate the absolute error.
!
isig = 0
resg = 0.d0
fc = f(centr)
resk = wgk(11)*fc
resabs = dabs(resk)
do 10 j = 1,5
  jtw = 2*j
  absc = hlgth*xgk(jtw)
  fval1 = f(centr - absc)
  fval2 = f(centr + absc)
  fv1(jtw) = fval1
  fv2(jtw) = fval2
  fsum = fval1 + fval2
  resg = resg + wg(j)*fsum
  resk = resk + wgk(jtw)*fsum
  resabs = resabs + wgk(jtw)*(dabs(fval1) + dabs(fval2))
10 continue
do j = 1,5
  jtwm1 = 2*j - 1
  absc = hlgth*xgk(jtwm1)
  fval1 = f(centr - absc)
  fval2 = f(centr + absc)
  fv1(jtwm1) = fval1
  fv2(jtwm1) = fval2
  fsum = fval1 + fval2
  resk = resk + wgk(jtwm1)*fsum
  resabs = resabs + wgk(jtwm1)*(dabs(fval1) + dabs(fval2))
end do
reskh = resk*0.5d0
resasc = wgk(11)*dabs(fc - reskh)
do j = 1,10
  resasc = resasc + wgk(j)*(dabs(fv1(j)-reskh) &
&+ dabs(fv2(j)-reskh))
end do
result = resk*hlgth
resabs = resabs*dhlgth
resasc = resasc*dhlgth
abserr = dabs((resk - resg)*hlgth)
if (resasc .ne. 0.d0 .and. abserr .ne. 0.d0) &
&abserr = resasc*dmin1(1.d0, &
&(0.2d+03*abserr/resasc)**1.5d0)
tol = epmach*0.5d+02
if (resabs .gt. uflow/tol) abserr = dmax1(abserr,tol*resabs)
return
end subroutine dqk21

subroutine dqagi (f, bound, inf, epsabs, epsrel, result, abserr, &
&neval, ier, limit, lenw, last, iwork, work)
implicit none
integer, intent(in) :: inf
integer, intent(out) :: last
!-----------------------------------------------------------------------
!
!         Double precision integration over infinite intervals
!
!-----------------------------------------------------------------------
!
!        Purpose
!           the routine calculates an approximation  result  to a given
!           INTEGRAL    I = INTEGRAL OF  f  OVER (bound,+INFINITY)
!                    OR I = INTEGRAL OF  f  OVER (-INFINITY,bound)
!                    OR I = INTEGRAL OF  f  OVER (-INFINITY,+INFINITY),
!           hopefully satisfying following claim for accuracy
!           abs(I-result).LE.max(epsabs,epsrel*abs(I)).
!
!        Parameters
!         on entry
!            f      - DOUBLE PRECISION
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X T E R N A L in the driver program.
!
!            bound  - double precision
!                     finite bound of integration range
!                     (has no meaning if interval is doubly-infinite)
!
!            inf    - INTEGER
!                     indicating the kind of integration range
!                     involved
!                     inf = 1 CORRESPONDS TO  (bound,+INFINITY),
!                     inf = -1            to  (-infinity,bound),
!                     inf = 2             to (-infinity,+infinity).
!
!            epsabs - double precision
!                     absolute accuracy requested
!
!            epsrel - double precision
!                     relative accuracy requested
!
!         On return
!            result - double precision
!                     approximation to the integral
!
!            abserr - double precision
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            neval  - INTEGER
!                     number of integrand evaluations
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                   - ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE. THE
!                             estimates for result and error are less
!                             reliable. It is assumed that the requested
!                             accuracy has not been achieved.
!
!                     ier = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more
!                             subdivisions by increasing the value
!                             of limit (and taking the according
!                             dimension adjustments into account).
!                             However, if this yields no improvement
!                             it is advised to analyze the integrand
!                             in order to determine the integration
!                             difficulties. If the position of a local
!                             difficulty can be determined (E.G.
!                             Singularity, discontinuity within the
!                             interval) one will probably gain from
!                             splitting up the interval at this point
!                             and calling the integrator on the
!                             subranges. If possible, an appropriate
!                             special-purpose integrator should be used,
!                             which is designed for handling the type
!                             of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS
!                             detected, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR OCCURS
!                             at some points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             Roundoff error is detected in the
!                             extrapolation table.
!                             It is assumed that the requested tolerance
!                             cannot be achieved, and that the returned
!                             result is the best which can be obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted that
!                             divergence can occur with any other value
!                             of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs
!                             OR epsrel IS NEGATIVE, limit .LT. 1,
!                             OR lenw .LT. 4 * limit.
!                             Result, abserr, neval, last are
!                             set to zero.
!
!         Dimensioning parameters
!            limit - integer
!                    dimensioning parameter for iwork
!                    limit determines the maximum number
!                    of subintervals in the partition of the given
!                    INTEGRATION INTERVAL (A,B), limit.GE.1.
!                    IF limit.LT.1, THE ROUTINE WILL END WITH
!                    ier = 6.
!
!            lenw  - INTEGER
!                    dimensioning parameter for work
!                    lenw must be at least limit*4.
!                    IF lenw.LT.limit*4, THE ROUTINE WILL END
!                    WITH ier = 6.
!
!            last  - integer
!                    on return, last equals the number of
!                    subintervals produced in the subdivision
!                    process, which determines the number of significant
!                    elements actually in the work arrays.
!
!         Work arrays
!            iwork - INTEGER
!                    vector of dimension at least limit, the first
!                    K elements of which contain pointers
!                    to the error estimates over the subintervals,
!                    such that work(limit*3+iwork(1)),... ,
!                    work(limit*3+iwork(K)) form a decreasing
!                    SEQUENCE, WITH K = last IF last.LE.(limit/2+2), AND
!                    K = limit+1-last OTHERWISE
!
!            work  - double precision
!                    vector of dimension at least lenw
!                    on return
!                    work(1), ..., work(last) contain the left
!                     END POINTS OF THE SUBINTERVALS IN THE
!                     partition of (A,B),
!                    work(limit+1), ..., work(limit+last) contain
!                     the right end points,
!                    work(limit*2+1), ..., work(limit*2+last)
!                     contain the integral approximations over
!                     the subintervals,
!                    work(limit*3+1), ..., work(limit*3+last)
!                     contain the error estimates.
!
!        Subroutines or functions needed
!              - dqagie
!              - dqk15i
!              - dqpsrt
!              - dqelg
!              - f (user provided function)
!              - dpmpar
!
!-----------------------------------------------------------------------
double precision, intent(out) :: abserr
double precision, intent(in) :: bound, epsabs, epsrel
double precision :: f
double precision, intent(out) :: result
double precision, intent(inout) :: work
integer, intent(out) :: ier
integer, intent(inout) :: iwork
integer, intent(in) :: lenw, limit
integer :: l1, l2, l3
integer, intent(out) :: neval
!
dimension iwork(limit),work(lenw)
!
external f
!
!         Check validity of limit and lenw.
!
ier = 6
neval = 0
last = 0
result = 0.d0
abserr = 0.d0
if (limit .lt. 1 .or. lenw .lt. limit*4) return
!
!         Prepare call for dqagie
!
l1 = limit + 1
l2 = limit + l1
l3 = limit + l2
!
call dqagie (f,bound,inf,epsabs,epsrel,limit,result,abserr, &
&neval,ier,work(1),work(l1),work(l2),work(l3),iwork,last)
return
end subroutine dqagi

subroutine dqagie (f,bound,inf,epsabs,epsrel,limit,result,abserr, &
&neval,ier,alist,blist,rlist,elist,iord,last)
implicit none
!-----------------------------------------------------------------------
!
!                   Integration over infinite intervals
!
!-----------------------------------------------------------------------
!
!        Purpose
!           the routine calculates an approximation  result  to a given
!           INTEGRAL    I = INTEGRAL OF  F  OVER (bound,+INFINITY)
!                    OR I = INTEGRAL OF  F  OVER (-INFINITY,bound)
!                    OR I = INTEGRAL OF  F  OVER (-INFINITY,+INFINITY),
!           hopefully satisfying following claim for accuracy
!           abs(I-result).LE.max(epsabs,epsrel*abs(I)).
!
!        Parameters
!         on entry
!            F      - DOUBLE PRECISION
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X t E R N A L in the driver program.
!
!            bound  - double precision
!                     finite bound of integration range
!                     (has no meaning if interval is doubly-infinite)
!
!            inf    - INTEGER
!                     indicating the kind of integration range
!                     involved
!                     inf = 1 CORRESPONDS TO  (bound,+INFINITY),
!                     inf = -1            to  (-infinity,bound),
!                     inf = 2             to (-infinity,+infinity).
!
!            epsabs - double precision
!                     absolute accuracy requested
!
!            epsrel - double precision
!                     relative accuracy requested
!
!            limit  - integer
!                     gives an upper bound on the number of
!                     subintervals in the partition of (A,B),
!                     limit.GE.1
!
!         On return
!            result - double precision
!                     approximation to the integral
!
!            abserr - double precision
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed abs(I-result)
!
!            neval  - INTEGER
!                     number of integrand evaluations
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                   - ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE. THE
!                             estimates for result and error are less
!                             reliable. It is assumed that the requested
!                             accuracy has not been achieved.
!
!                     ier = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more
!                             subdivisions by increasing the value
!                             of limit (and taking the according
!                             dimension adjustments into account).
!                             However, if this yields no improvement
!                             it is advised to analyze the integrand
!                             in order to determine the integration
!                             difficulties. If the position of a local
!                             difficulty can be determined (E.G.
!                             Singularity, discontinuity within the
!                             interval) one will probably gain from
!                             splitting up the interval at this point
!                             and calling the integrator on the
!                             subranges. If possible, an appropriate
!                             special-purpose integrator should be used,
!                             which is designed for handling the type
!                             of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS
!                             detected, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR OCCURS
!                             at some points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             Roundoff error is detected in the
!                             extrapolation table.
!                             It is assumed that the requested tolerance
!                             cannot be achieved, and that the returned
!                             result is the best which can be obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted that
!                             divergence can occur with any other value
!                             of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs
!                             or epsrel is negative.
!                             Result, abserr, neval, last, rlist(1),
!                             elist(1) and iord(1) are set to zero.
!                             alist(1) and blist(1) are set to 0
!                             and 1 respectively.
!
!            alist  - double precision
!                     vector of dimension at least limit, the first
!                      last  elements of which are the left
!                     END POINTS OF THE SUBINTERVALS IN THE PARTITION
!                     of the transformed integration range (0,1).
!
!            blist  - double precision
!                     vector of dimension at least limit, the first
!                      last  elements of which are the right
!                     END POINTS OF THE SUBINTERVALS IN THE PARTITION
!                     of the transformed integration range (0,1).
!
!            rlist  - double precision
!                     vector of dimension at least limit, the first
!                      last  elements of which are the integral
!                     approximations on the subintervals
!
!            elist  - double precision
!                     vector of dimension at least limit,  the first
!                      last  elements of which are the moduli
!                     of the absolute error estimates on the
!                     subintervals
!
!            iord   - INTEGER
!                     vector of dimension limit, the first k
!                     elements of which are pointers to the
!                     error estimates over the subintervals,
!                     such that elist(iord(1)), ..., elist(iord(k))
!                     FORM A DECREASING SEQUENCE, WITH k = last
!                     IF last.LE.(limit/2+2), AND k = limit+1-last
!                     otherwise
!
!            last   - INTEGER
!                     number of subintervals actually produced
!                     in the subdivision process
!
!        Subroutines or functions needed
!              - dqk15i
!              - dqpsrt
!              - dqelg
!              - F (user-provided function)
!              - dpmpar
!
!-----------------------------------------------------------------------
double precision :: abseps
double precision, intent(out) :: abserr
double precision, intent(inout) :: alist
double precision :: area, area1, area12, area2, a1, a2
double precision, intent(inout) :: blist
double precision :: boun
double precision, intent(in) :: bound
double precision :: b1, b2, correc, defabs, defab1, defab2, dres, &
&dpmpar
double precision, intent(inout) :: elist
double precision :: epmach
double precision, intent(in) :: epsabs, epsrel
double precision :: erlarg, erlast, errbnd, errmax, error1, &
&error2, erro12, errsum, ertest, f, oflow, rerr, resabs, reseps
double precision, intent(out) :: result
double precision :: res3la(3)
double precision, intent(inout) :: rlist
double precision :: rlist2(52), small, t, uflow
integer :: id
integer, intent(out) :: ier
integer :: ierro
integer, intent(in) :: inf
integer, intent(inout) :: iord
integer :: iroff1, iroff2, iroff3, jupbnd, k, ksgn, ktmin
integer, intent(out) :: last
integer, intent(in) :: limit
integer :: maxerr
integer, intent(out) :: neval
integer :: nres, nrmax, numrl2
logical :: extrap, noext
!
dimension alist(limit), blist(limit), elist(limit), iord(limit), &
&rlist(limit)
!
external f
!
!            The dimension of rlist2 is determined by the value of
!            LIMEXP in subroutine dqelg.
!
!
!            List of major variables
!            -----------------------
!
!           alist     - LIST OF LEFT END POINTS OF ALL SUBINTERVALS
!                       considered up to now
!           blist     - LIST OF RIGHT END POINTS OF ALL SUBINTERVALS
!                       considered up to now
!           rlist(I)  - approximation to the integral over
!                       (alist(I),blist(I))
!           rlist2    - ARRAY OF DIMENSION AT LEAST (LIMEXP+2),
!                       containing the part of the epsilon table
!                       wich is still needed for further computations
!           elist(I)  - error estimate applying to rlist(I)
!           maxerr    - POINTER TO THE INTERVAL WITH LARGEST ERROR
!                       estimate
!           errmax    - elist(maxerr)
!           erlast    - ERROR ON THE INTERVAL CURRENTLY SUBDIVIDED
!                       (before that subdivision has taken place)
!           area      - SUM OF THE INTEGRALS OVER THE SUBINTERVALS
!           ERRSUM    - SUM OF THE ERRORS OVER THE SUBINTERVALS
!           errbnd    - REQUESTED ACCURACY max(epsabs,epsrel*
!                       abs(result))
!           *****1    - VARIABLE FOR THE LEFT SUBINTERVAL
!           *****2    - VARIABLE FOR THE RIGHT SUBINTERVAL
!           last      - INDEX FOR SUBDIVISION
!           nres      - NUMBER OF CALLS TO THE EXTRAPOLATION ROUTINE
!           numrl2    - NUMBER OF ELEMENTS CURRENTLY IN rlist2. IF AN
!                       appropriate approximation to the compounded
!                       integral has been obtained, it is put in
!                       rlist2(numrl2) after numrl2 has been increased
!                       by one.
!           small     - LENGTH OF THE SMALLEST INTERVAL CONSIDERED UP
!                       to now, multiplied by 1.5
!           erlarg    - SUM OF THE ERRORS OVER THE INTERVALS LARGER
!                       than the smallest interval considered up to now
!           extrap    - LOGICAL VARIABLE DENOTING THAT THE ROUTINE
!                       is attempting to perform extrapolation. I.E.
!                       Before subdividing the smallest interval we
!                       try to decrease the value of erlarg.
!           noext     - LOGICAL VARIABLE DENOTING THAT EXTRAPOLATION
!                       is no longer allowed (TRUE-VALUE)
!
!            Machine dependent constants
!            ---------------------------
!
!           epmach is the largest relative spacing.
!           uflow is the smallest positive magnitude.
!           OFLOW is the largest positive magnitude.
!
epmach = dpmpar(1)
uflow = dpmpar(2)
oflow = dpmpar(3)
!
!           Check epsabs and epsrel
!           -----------------------
!
neval = 0
last = 0
result = 0.d0
abserr = 0.d0
alist(1) = 0.d0
blist(1) = 1.d0
rlist(1) = 0.d0
elist(1) = 0.d0
iord(1) = 0
ier = 6
if (epsabs .lt. 0.d0 .or. epsrel .lt. 0.d0) go to 999
ier = 0
rerr = dmax1(epsrel, 50.d0*epmach, 0.5d-28)
!
!           First approximation to the integral
!           -----------------------------------
!
!           Determine the interval to be mapped onto (0,1).
!           IF inf = 2 THE INTEGRAL IS COMPUTED AS I = I1+I2, WHERE
!           I1 = INTEGRAL OF F OVER (-INFINITY,0),
!           I2 = INTEGRAL OF F OVER (0,+INFINITY).
!
boun = bound
if (inf .eq. 2) boun = 0.d0
call dqk15i (f, boun, inf, 0.d0, 1.d0, result, abserr, &
&defabs, resabs, epmach, uflow)
!
!           Test on accuracy
!
last = 1
rlist(1) = result
elist(1) = abserr
iord(1) = 1
dres = dabs(result)
errbnd = dmax1(epsabs,rerr*dres)
if (abserr .le. 100.d0*epmach*defabs .and. abserr .gt. errbnd) &
&ier = 2
if (limit .eq. 1) ier = 1
if (ier .ne. 0 .or. (abserr .le. errbnd .and. abserr .ne. resabs) &
&.or. abserr .eq. 0.d0) go to 130
!
!           Initialization
!           --------------
!
rlist2(1) = result
errmax = abserr
maxerr = 1
area = result
errsum = abserr
abserr = oflow
correc = 0.d0
nrmax = 1
nres = 0
ktmin = 0
numrl2 = 2
extrap = .false.
noext = .false.
ierro = 0
iroff1 = 0
iroff2 = 0
iroff3 = 0
ksgn = -1
if (dres .ge. (1.d0 - 50.d0*epmach)*defabs) ksgn = 1
t = 1.d0 + 100.d0*epmach
!
!           Main do-loop
!           ------------
!
do 90 last = 2,limit
!
!           Bisect the subinterval with nrmax-TH largest
!           error estimate.
!
  a1 = alist(maxerr)
  b1 = 0.5d0*(alist(maxerr) + blist(maxerr))
  a2 = b1
  b2 = blist(maxerr)
  erlast = errmax
  call dqk15i (f, boun, inf, a1, b1, area1, error1, &
&resabs, defab1, epmach, uflow)
  call dqk15i (f, boun, inf, a2, b2, area2, error2, &
&resabs, defab2, epmach, uflow)
!
!           Improve previous approximations to integral
!           and error and test for accuracy.
!
  area12 = area1 + area2
  erro12 = error1 + error2
  errsum = errsum + erro12 - errmax
  area = area + area12 - rlist(maxerr)
  if (defab1 .eq. error1 .or. defab2 .eq. error2) go to 15
  if (dabs(rlist(maxerr) - area12) .gt. 0.1d-04*dabs(area12) &
&.or. erro12 .lt. 0.99d0*errmax) go to 10
  if (extrap) iroff2 = iroff2 + 1
  if (.not.extrap) iroff1 = iroff1 + 1
10 if (last .gt. 10 .and. erro12 .gt. errmax) iroff3 = iroff3 + 1
15 rlist(maxerr) = area1
  rlist(last) = area2
  errbnd = dmax1(epsabs,rerr*dabs(area))
!
!           Test for roundoff error and eventually
!           set error flag.
!
  if (iroff1 + iroff2 .ge. 10 .or. iroff3 .ge. 20) ier = 2
  if (iroff2 .ge. 5) ierro = 3
!
!           Set error flag in the case that the number of
!           subintervals equals limit.
!
  if (last .eq. limit) ier = 1
!
!           Set error flag in the case of bad integrand behaviour
!           at some points of the integration range.
!

  if (dmax1(dabs(a1),dabs(b2)) .le. &
&t*(dabs(a2) + 0.1d+04*uflow)) ier = 4
!
!           Append the newly-created intervals to the list.
!
  if (error2 .gt. error1) go to 20
  alist(last) = a2
  blist(maxerr) = b1
  blist(last) = b2
  elist(maxerr) = error1
  elist(last) = error2
  go to 30
20 alist(maxerr) = a2
  alist(last) = a1
  blist(last) = b1
  rlist(maxerr) = area2
  rlist(last) = area1
  elist(maxerr) = error2
  elist(last) = error1
!
!           CALL SUBROUTINE dqpsrt TO MAINTAIN THE DESCENDING ORDERING
!           in the list of error estimates and select the
!           subinterval with nrmax-TH largest error estimate (to be
!           bisected next).
!
30 call dqpsrt (limit,last,maxerr,errmax,elist,iord,nrmax)
  if (errsum .le. errbnd) go to 115
  if (ier .ne. 0) go to 100
  if (last .eq. 2) go to 80
  if (noext) go to 90
  erlarg = erlarg - erlast
  if (dabs(b1 - a1) .gt. small) erlarg = erlarg + erro12
  if (extrap) go to 40
!
!           Test whether the interval to be bisected next is the
!           smallest interval.
!
  if (dabs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
  extrap = .true.
  nrmax = 2
40 if (ierro .eq. 3 .or. erlarg .le. ertest) go to 60
!
!           The smallest interval has the largest error.
!           Before bisecting decrease the sum of the errors
!           over the larger intervals (erlarg) and perform
!           extrapolation.
!
  id = nrmax
  jupbnd = last
  if (last .gt. (2 + limit/2)) jupbnd = limit + 3 - last
  do 50 k = id,jupbnd
    maxerr = iord(nrmax)
    errmax = elist(maxerr)
    if (dabs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
    nrmax = nrmax + 1
50 continue
!
!           Perform extrapolation.
!
60 numrl2 = numrl2 + 1
  rlist2(numrl2) = area
  call dqelg (numrl2, rlist2, reseps, abseps, res3la, nres, &
&epmach, oflow)
  ktmin = ktmin + 1
  if (ktmin .gt. 5 .and. abserr .lt. 0.1d-02*errsum) ier = 5
  if (abseps .ge. abserr) go to 70
  ktmin = 0
  abserr = abseps
  result = reseps
  correc = erlarg
  ertest = dmax1(epsabs,rerr*dabs(reseps))
  if (abserr .le. ertest) go to 100
!
!            Prepare bisection of the smallest interval.
!
70 if (numrl2 .eq. 1) noext = .true.
  if (ier .eq. 5) go to 100
  maxerr = iord(1)
  errmax = elist(maxerr)
  nrmax = 1
  extrap = .false.
  small = small*0.5d0
  erlarg = errsum
  go to 90
80 small = 0.375d0
  erlarg = errsum
  ertest = errbnd
  rlist2(2) = area
90 continue
!
!           Set final result and error estimate.
!           ------------------------------------
!
100 if (abserr .eq. oflow) go to 115
if (ier + ierro .eq. 0) go to 110
if (ierro .eq. 3) abserr = abserr + correc
if (ier .eq. 0) ier = 3
if (result .ne. 0.d0 .and. area .ne. 0.d0) go to 105
if (abserr .gt. errsum) go to 115
if (area .eq. 0.d0) go to 130
go to 110
105 if (abserr/dabs(result) .gt. errsum/dabs(area)) go to 115
!
!           Test on divergence
!
110 if (ksgn .eq. -1 .and. dmax1(dabs(result),dabs(area)) .le. &
&defabs*0.1d-01) go to 130
if (0.1d-01 .gt. (result/area) .or. (result/area) .gt. 0.1d+03 &
&.or. errsum .gt. dabs(area)) ier = 6
go to 130
!
!           Compute global integral sum.
!
115 result = 0.d0
do k = 1,last
  result = result + rlist(k)
end do
abserr = errsum
130 neval = 30*last - 15
if (inf .eq. 2) neval = 2*neval
if (ier .gt. 2) ier = ier - 1
999 return
end subroutine dqagie

subroutine dqk15i (f, boun, inf, a, b, result, abserr, resabs, &
&resasc, epmach, uflow)
implicit none
integer, intent(in) :: inf
integer :: j
!-----------------------------------------------------------------------
!
! 1.        PURPOSE
!              the original (infinite) integration range is mapped
!              onto the interval (0,1) and (a,b) is a part of (0,1).
!              It is the purpose to compute
!              I = INTEGRAL OF TRANSFORMED INTEGRAND OVER (a,b),
!              j = INTEGRAL OF abs(TRANSFORMED INTEGRAND) OVER (a,b).
!
! 2.        PARAMETERS
!            on entry
!              f      - DOUBLE PRECISION
!                       function subprogram defining the integrand
!                       function f(x). the actual name for f needs
!                       to be declared E X T E R N A L in the
!                       calling program.
!
!              boun   - DOUBLE PRECISION
!                       finite bound of original integration
!                       RANGE (SET TO ZERO IF inf = +2)
!
!              inf    - INTEGER
!                       IF inf = -1, THE ORIGINAL INTERVAL IS
!                                   (-INFINITY,BOUND),
!                       IF inf = +1, THE ORIGINAL INTERVAL IS
!                                   (BOUND,+INFINITY),
!                       IF inf = +2, THE ORIGINAL INTERVAL IS
!                                   (-INFINITY,+INFINITY) and
!                       the integral is computed as the sum of two
!                       integrals, one over (-INFINITY,0)
!                       and one over (0,+INFINITY).
!
!              a      - DOUBLE PRECISION
!                       lower limit for integration over subrange
!                       of (0,1)
!
!              b      - DOUBLE PRECISION
!                       upper limit for integration over subrange
!                       of (0,1)
!
!              epmach - double precision
!                       the relative precision of the floating
!                       arithmetic being used.
!
!              uflow  - double precision
!                       the smallest positive magnitude.
!
!            On return
!              result - double precision
!                       approximation to the integral I
!                       result is computed by applying the 15-point
!                       Kronrod RULE(resk) obtained by optimal
!                       addition of abscissae to the 7-point Gauss
!                       RULE(resg).
!
!              abserr - double precision
!                       estimate of the modulus of the absolute error,
!                       which should equal or exceed abs(I-result)
!
!              resabs - double precision
!                       approximation to the integral j
!
!              resasc - double precision
!                       approximation to the integral of
!                       abs((TRANSFORMED INTEGRAND)-I/(b-a))
!                       OVER (a,b)
!
! 3.        SUBROUTINES OR FUNCTIONS NEEDED
!                 - f (user-provided function)
!
!-----------------------------------------------------------------------
double precision, intent(in) :: a
double precision :: absc, absc1, absc2
double precision, intent(inout) :: abserr
double precision, intent(in) :: b, boun
double precision :: centr, dinf
double precision, intent(in) :: epmach
double precision :: f, fc, fsum, fval1, fval2, hlgth
double precision, intent(inout) :: resabs, resasc
double precision :: resg, resk, reskh
double precision, intent(inout) :: result
double precision :: tabsc1, tabsc2, tol
double precision, intent(in) :: uflow
double precision :: fv1(7), fv2(7), xgk(8), wgk(8), wg(8)
external f
!
!           The abscissae and weights are supplied for the interval
!           (-1,1).  Because of symmetry only the positive abscissae and
!           their corresponding weights are given.
!
!           xgk    - ABSCISSAE OF THE 15-POINT KRONROD RULE
!                    xgk(2), xgk(4), ... abscissae of the 7-point
!                    Gauss rule
!                    xgk(1), xgk(3), ...  abscissae which are optimally
!                    added to the 7-point Gauss rule
!
!           wgk    - WEIGHTS OF THE 15-POINT KRONROD RULE
!
!           wg     - WEIGHTS OF THE 7-POINT GAUSS RULE, CORRESPONDING
!                    to the abscissae xgk(2), xgk(4), ...
!                    wg(1), wg(3), ... are set to zero.
!
data xgk(1),xgk(2),xgk(3),xgk(4),xgk(5),xgk(6),xgk(7), &
&xgk(8)/ &
&0.991455371120812639206854697526d+00, &
&0.949107912342758524526189684048d+00, &
&0.864864423359769072789712788641d+00, &
&0.741531185599394439863864773281d+00, &
&0.586087235467691130294144838259d+00, &
&0.405845151377397166906606412077d+00, &
&0.207784955007898467600689403773d+00, &
&0.000000000000000000000000000000d+00/
!
data wgk(1),wgk(2),wgk(3),wgk(4),wgk(5),wgk(6),wgk(7), &
&wgk(8)/ &
&0.229353220105292249637320080590d-01, &
&0.630920926299785532907006631892d-01, &
&0.104790010322250183839876322542d+00, &
&0.140653259715525918745189590510d+00, &
&0.169004726639267902826583426599d+00, &
&0.190350578064785409913256402421d+00, &
&0.204432940075298892414161999235d+00, &
&0.209482141084727828012999174892d+00/
!
data wg(1),wg(2),wg(3),wg(4),wg(5),wg(6),wg(7),wg(8)/ &
&0.0d+00,    0.129484966168869693270611432679d+00, &
&0.0d+00,    0.279705391489276667901467771424d+00, &
&0.0d+00,    0.381830050505118944950369775489d+00, &
&0.0d+00,    0.417959183673469387755102040816d+00/
!
!
!           List of major variables
!           -----------------------
!
!           centr  - mid point of the interval
!           hlgth  - half-length of the interval
!           absc*  - ABSCISSA
!           TABSC* - transformed abscissa
!           FVAL*  - function VALUE
!           resg   - result OF THE 7-POINT GAUSS FORMULA
!           resk   - result OF THE 15-POINT KRONROD FORMULA
!           reskh  - approximation to the mean value of the transformed
!                    integrand over (a,b), I.E. to I/(b-a)
!
!
dinf = min0(1,inf)
!
centr = 0.5d0*(a + b)
hlgth = 0.5d0*(b - a)
tabsc1 = boun + dinf*(1.d0 - centr)/centr
fval1 = f(tabsc1)
if (inf .eq. 2) fval1 = fval1 + f(-tabsc1)
fc = (fval1/centr)/centr
!
!           Compute the 15-point Kronrod approximation to
!           the integral, and estimate the error.
!
resg = wg(8)*fc
resk = wgk(8)*fc
resabs = dabs(resk)
do j = 1,7
  absc = hlgth*xgk(j)
  absc1 = centr - absc
  absc2 = centr + absc
  tabsc1 = boun + dinf*(1.d0 - absc1)/absc1
  tabsc2 = boun + dinf*(1.d0 - absc2)/absc2
  fval1 = f(tabsc1)
  fval2 = f(tabsc2)
  if (inf .eq. 2) fval1 = fval1 + f(-tabsc1)
  if (inf .eq. 2) fval2 = fval2 + f(-tabsc2)
  fval1 = (fval1/absc1)/absc1
  fval2 = (fval2/absc2)/absc2
  fv1(j) = fval1
  fv2(j) = fval2
  fsum = fval1 + fval2
  resg = resg + wg(j)*fsum
  resk = resk + wgk(j)*fsum
  resabs = resabs + wgk(j)*(dabs(fval1) + dabs(fval2))
end do
reskh = resk*0.5d0
resasc = wgk(8)*dabs(fc - reskh)
do j = 1,7
  resasc = resasc + wgk(j)*(dabs(fv1(j)-reskh) + &
&dabs(fv2(j)-reskh))
end do
result = resk*hlgth
resasc = resasc*hlgth
resabs = resabs*hlgth
abserr = dabs((resk - resg)*hlgth)
if (resasc .ne. 0.d0 .and. abserr .ne. 0.d0) abserr = resasc* &
&dmin1(1.d0, (0.2d+03*abserr/resasc)**1.5d0)
tol = 50.d0*epmach
if (resabs .gt. uflow/tol) abserr = dmax1(abserr, tol*resabs)
return
end subroutine dqk15i

subroutine dqpsrt(limit,last,maxerr,ermax,elist,iord,nrmax)
implicit none
!     ..................................................................
!
! 1.        dqpsrt
!           ordering routine
!              standard Fortran subroutine
!              double precision version
!
! 2.        PURPOSE
!              this routine maintains the descending ordering
!              in the list of the local error estimates resulting from
!              the interval subdivision process. At each call two error
!              estimates are inserted using the sequential search
!              method, top-down for the largest error estimate
!              and bottom-up for the smallest error estimate.
!
! 3.        CALLING SEQUENCE
!              call dqpsrt(limit,last,maxerr,ermax,elist,iord,nrmax)
!
!           Parameters (meaning at output)
!              limit  - integer
!                       maximum number of error estimates the list
!                       can contain
!
!              last   - INTEGER
!                       number of error estimates currently
!                       in the list
!
!              maxerr - INTEGER
!                       maxerr points to the nrmax-TH largest error
!                       estimate currently in the list
!
!              ermax  - double precision
!                       nrmax-TH largest error estimate
!                       ermax = elist(maxerr)
!
!              elist  - double precision
!                       vector of dimension last containing
!                       the error estimates
!
!              iord   - INTEGER
!                       vector of dimension last, the first k
!                       elements of which contain pointers
!                       to the error estimates, such that
!                       elist(iord(1)),... , elist(iord(k))
!                       form a decreasing sequence, with
!                       k = last IF last.LE.(limit/2+2), AND
!                       k = limit+1-last OTHERWISE
!
!              nrmax  - INTEGER
!                       maxerr = iord(nrmax)
!
! 4.        NO SUBROUTINES OR FUNCTIONS NEEDED
!
!     ..................................................................
!
double precision :: elist
double precision, intent(inout) :: ermax
double precision :: errmax, errmin
integer :: i, ibeg, ido
integer, intent(inout) :: iord
integer :: isucc, j, jbnd, jupbn, k
integer, intent(in) :: last, limit
integer, intent(inout) :: maxerr, nrmax
dimension elist(last),iord(last)
!
!           Check whether the list contains more than
!           two error estimates.
!
!***FIRST EXECUTABLE STATEMENT dqpsrt
if(last.gt.2) go to 10
iord(1) = 1
iord(2) = 2
go to 90
!
!           This part of the routine is only executed
!           if, due to a difficult integrand, subdivision
!           increased the error estimate. In the normal case
!           the insert procedure should start after the
!           nrmax-TH largest error estimate.
!
10 errmax = elist(maxerr)
if(nrmax.eq.1) go to 30
ido = nrmax-1
do i = 1,ido
  isucc = iord(nrmax-1)
! ***JUMP OUT OF DO-LOOP
  if(errmax.le.elist(isucc)) go to 30
  iord(nrmax) = isucc
  nrmax = nrmax-1
   end do
!
!           Compute the number of elements in the list to
!           be maintained in descending order. This number
!           depends on the number of subdivisions still
!           allowed.
!
30 jupbn = last
if(last.gt.(limit/2+2)) jupbn = limit+3-last
errmin = elist(last)
!
!           Insert errmax by traversing the list top-down,
!           starting comparison from the element elist(iord(nrmax+1)).
!
jbnd = jupbn-1
ibeg = nrmax+1
if(ibeg.gt.jbnd) go to 50
do i=ibeg,jbnd
  isucc = iord(i)
! ***JUMP OUT OF DO-LOOP
  if(errmax.ge.elist(isucc)) go to 60
  iord(i-1) = isucc
end do
50 iord(jbnd) = maxerr
iord(jupbn) = last
go to 90
!
!           Insert errmin by traversing the list bottom-up.
!
60 iord(i-1) = maxerr
k = jbnd
do j=i,jbnd
  isucc = iord(k)
! ***JUMP OUT OF DO-LOOP
  if(errmin.lt.elist(isucc)) go to 80
  iord(k+1) = isucc
  k = k-1
end do
iord(i) = last
go to 90
80 iord(k+1) = last
!
!           Set maxerr and ermax.
!
90 maxerr = iord(nrmax)
ermax = elist(maxerr)
return
end subroutine dqpsrt

subroutine dqelg (n, epstab, result, abserr, res3la, nres, &
&epmach, oflow)
implicit none
!-----------------------------------------------------------------------
!
! 1.        PURPOSE
!              the routine determines the limit of a given sequence of
!              approximations, by means of the epsilon algorithm
!              of P. wynn.
!              An estimate of the absolute error is also given.
!              The condensed epsilon table is computed. Only those
!              elements needed for the computation of the next diagonal
!              are preserved.
!
! 2.        PARAMETERS
!              n      - INTEGER
!                       epstab(n) contains the new element in the
!                       first column of the epsilon table.
!
!              epstab - double precision
!                       vector of dimension 52 containing the
!                       elements of the two lower diagonals of
!                       the triangular epsilon table
!                       the elements are numbered starting at the
!                       right-hand corner of the triangle.
!
!              result - double precision
!                       resulting approximation to the integral
!
!              abserr - double precision
!                       estimate of the absolute error computed from
!                       result and the 3 previous results
!
!              res3la - double precision
!                       vector of dimension 3 containing the last 3
!                       results
!
!              nres   - INTEGER
!                       number of calls to the routine
!                       (should be zero at first call)
!
!              epmach - double precision
!                       the relative precision of the floating
!                       arithmetic being used.
!
!              oflow  - double precision
!                       the largest positive magnitude.
!
! 3.        NO SUBROUTINES OR FUNCTIONS USED
!
!-----------------------------------------------------------------------
double precision, intent(out) :: abserr
double precision :: delta1, delta2, delta3
double precision, intent(in) :: epmach
double precision :: epsinf
double precision, intent(inout) :: epstab(52)
double precision :: error, err1, err2, err3, e0, e1, e1abs, e2, e3
double precision, intent(in) :: oflow
double precision :: res
double precision, intent(out) :: result
double precision, intent(inout) :: res3la(3)
double precision :: ss, tol1, tol2, tol3
integer :: i, ib, ib2, ie, indx, k1, k2, k3, limexp
integer, intent(inout) :: n
integer :: newelm
integer, intent(inout) :: nres
integer :: num
!---------------------
!
!           List of major variables
!           -----------------------
!
!           e0     - THE 4 ELEMENTS ON WHICH THE
!           e1       COMPUTATION OF A NEW ELEMENT IN
!           e2       THE EPSILON TABLE IS BASED
!           e3                 e0
!                        e3    e1    NEW
!                              e2
!           newelm - number of elements to be computed in the new
!                    diagonal
!           error  - error = abs(e1-e0) + abs(e2-e1) + abs(NEW-e2)
!           result - the element in the new diagonal with least value
!                    of error
!
!           limexp is the maximum number of elements the epsilon
!           table can contain. If this number is reached, the upper
!           diagonal of the epsilon table is deleted.
!
nres = nres + 1
abserr = oflow
result = epstab(n)
if (n .lt. 3) go to 100
limexp = 50
epstab(n + 2) = epstab(n)
newelm = (n - 1)/2
epstab(n) = oflow
num = n
k1 = n
do 40 i = 1,newelm
  k2 = k1 - 1
  k3 = k1 - 2
  res = epstab(k1 + 2)
  e0 = epstab(k3)
  e1 = epstab(k2)
  e2 = res
  e1abs = dabs(e1)
  delta2 = e2 - e1
  err2 = dabs(delta2)
  tol2 = dmax1(dabs(e2),e1abs)*epmach
  delta3 = e1 - e0
  err3 = dabs(delta3)
  tol3 = dmax1(e1abs,dabs(e0))*epmach
  if (err2 .gt. tol2 .or. err3 .gt. tol3) go to 10
!
!           If e0, e1 and e2 are equal to within machine
!           accuracy, convergence is assumed.
!           result = e2
!           abserr = abs(e1-e0) + abs(e2-e1)
!
  result = res
  abserr = err2 + err3
! ***JUMP OUT OF DO-LOOP
  go to 100
10 e3 = epstab(k1)
  epstab(k1) = e1
  delta1 = e1 - e3
  err1 = dabs(delta1)
  tol1 = dmax1(e1abs,dabs(e3))*epmach
!
!           If two elements are very close to each other, omit
!           a part of the table by adjusting the value of n
!
  if (err1.le.tol1 .or. err2.le.tol2 .or. err3.le.tol3) go to 20
  ss = 1.d0/delta1 + 1.d0/delta2 - 1.d0/delta3
  epsinf = dabs(ss*e1)
!
!           Test to detect irregular behaviour in the table, and
!           eventually omit a part of the table adjusting the value
!           OF n.
!
  if (epsinf .gt. 0.1d-03) go to 30
20 n = i + i - 1
! ***JUMP OUT OF DO-LOOP
  go to 50
!
!           Compute a new element and eventually adjust
!           the value of result.
!
30 res = e1 + 1.d0/ss
  epstab(k1) = res
  k1 = k1 - 2
  error = err2 + dabs(res - e2) + err3
  if (error .gt. abserr) go to 40
  abserr = error
  result = res
40 continue
!
!           Shift the table.
!
50 if (n .eq. limexp) n = 2*(limexp/2) - 1
ib = 1
if ((num/2)*2 .eq. num) ib = 2
ie = newelm + 1
do i = 1,ie
  ib2 = ib + 2
  epstab(ib) = epstab(ib2)
  ib = ib2
end do
if (num .eq. n) go to 80
indx = num - n + 1
do i = 1,n
  epstab(i) = epstab(indx)
  indx = indx + 1
end do
80 if (nres .ge. 4) go to 90
res3la(nres) = result
abserr = oflow
go to 100
!
!           Compute error estimate
!
90 abserr = dabs(result - res3la(3)) + dabs(result - res3la(2)) + &
&dabs(result - res3la(1))
res3la(1) = res3la(2)
res3la(2) = res3la(3)
res3la(3) = result
100 abserr = dmax1(abserr,5.d0*epmach*dabs(result))
return
end subroutine dqelg

subroutine dqxgs (f,a,b,epsabs,epsrel,result,abserr,ier, &
&limit,leniw,lenw,last,iwork,work)
implicit none
!
!            The routine calculates an approximation result to a given
!            DEFINITE INTEGRAL  I = INTEGRAL OF f OVER (a,b),
!            hopefully satisfying following claim for accuracy
!            dabs(I-result).LE.max(epsabs,epsrel*dabs(I)).
!
!        Parameters
!         on entry
!            f      - DOUBLE PRECISION
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X T E R N A L in the driver program.
!
!            a      - DOUBLE PRECISION
!                     lower limit of integration
!
!            b      - DOUBLE PRECISION
!                     upper limit of integration
!
!            epsabs - double precision
!                     absolute accuracy requested
!
!            epsrel - double precision
!                     relative accuracy requested
!
!         On return
!            result - double precision
!                     approximation to the integral
!
!            abserr - double precision
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed dabs(I-result)
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                     ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE
!                             the estimates for integral and error are
!                             less reliable. It is assumed that the
!                             requested accuracy has not been achieved.
!            Error messages
!                     ier = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more sub-
!                             divisions by increasing the value of limit
!                             (and taking the according dimension
!                             adjustments into account. However, if
!                             this yields no improvement it is advised
!                             to analyze the integrand in order to
!                             determine the integration difficulties. If
!                             the position of a local difficulty can be
!                             determined (E.G. singularity,
!                             discontinuity within the interval) one
!                             will probably gain from splitting up the
!                             interval at this point and calling the
!                             integrator on the subranges. If possible,
!                             an appropriate special-purpose integrator
!                             should be used, which is designed for
!                             handling the type of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS DETEC-
!                             ted, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR
!                             occurs at some points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             Roundoff error is detected in the
!                             extrapolation table. It is presumed that
!                             the requested tolerance cannot be
!                             achieved, and that the returned result is
!                             the best which can be obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted that
!                             divergence can occur with any other value
!                             of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs OR
!                             epsrel IS NEGATIVE, limit .LT. 1,
!                             lenw .LT. 46*limit, OR
!                             leniw .LT. 3*limit.
!                             Result, abserr, last are set to
!                             zero. Except when limit or lenw or leniw
!                             is invalid, iwork(1), work(limit*2+1) and
!                             work(limit*3+1) are set to zero, work(1)
!                             is set to A, and work(limit+1) to b.
!
!         Dimensioning parameters
!            limit - integer
!                    limit determines the maximum number of subintervals
!                    in the partition of the given integration interval
!                    (A,b), limit.GE.1.
!                    IF limit.LT.1, THE ROUTINE WILL END WITH ier = 6.
!
!            lenw  - INTEGER
!                    dimensioning parameter for work
!                    lenw must be at least limit*46.
!                    IF lenw.LT.limit*46, THE ROUTINE WILL END
!                    WITH ier = 6.
!
!            leniw - INTEGER
!                    dimensioning parameter for iwork
!                    leniw must be at least limit*3.
!                    IF lenw.LT.limit*3, THE ROUTINE WILL END
!                    WITH ier = 6.
!
!            last  - integer
!                    on return, last equals the number of subintervals
!                    produced in the subdivision process, which deter-
!                    mines the number of significant elements actually
!                    in the work arrays.
!
!         Work arrays
!            iwork - INTEGER
!                    vector of dimension at least 3*limit, the first K
!                    elements of which contain pointers
!                    to the error estimates over the subintervals
!                    such that work(limit*3+iwork(1)),... ,
!                    work(limit*3+iwork(K)) form a decreasing
!                    SEQUENCE, WITH K = last IF last.LE.(limit/2+2),
!                    AND K = limit+1-last OTHERWISE.
!
!            work  - double precision
!                    vector of dimension at least lenw
!                    on return
!                    work(1), ..., work(last) contain the left
!                     END-POINTS OF THE SUBINTERVALS IN THE
!                     partition of (a,b),
!                    work(limit+1), ..., work(limit+last) contain
!                     the right end-points,
!                    work(limit*2+1), ..., work(limit*2+last) contain
!                     the integral approximations over the subintervals,
!                    work(limit*3+1), ..., work(limit*3+last)
!                     contain the error estimates.
!                    work(limit*4+1), ... is the area reserved to store
!                     functional values.
!
double precision :: a
double precision, intent(out) :: abserr
double precision :: b
double precision, intent(in) :: epsabs, epsrel
double precision :: f
double precision, intent(out) :: result
double precision, intent(inout) :: work
integer, intent(out) :: ier
integer, intent(inout) :: iwork
integer, intent(out) :: last
integer, intent(in) :: leniw, lenw, limit
integer :: l1, l2, l3, l4, l5
!
dimension iwork(leniw),work(lenw)
!
external f
!
!         Check validity of limit,leniw and lenw.
!
ier = 6
last = 0
result = 0.d0
abserr = 0.d0
if (limit.lt.1 .or. leniw.lt.limit*3 .or. lenw.lt.limit*46) &
&return
!
!         Prepare call for dqxgse.
!
l1 = limit + 1
l2 = limit + l1
l3 = limit + l2
l4 = limit + l3
l5 = 21*limit + l4
!
call dqxgse(f,a,b,epsabs,epsrel,limit,result,abserr, &
&ier,work(1),work(l1),work(l2),work(l3),iwork,last, &
&work(l4),work(l5),iwork(l1),iwork(l2))
!
return
end subroutine dqxgs

subroutine dqxgse(f,a,b,epsabs,epsrel,limit,result,abserr, &
&ier,alist,blist,rlist,elist,iord,last,valp,valn,lp,ln)
implicit none
!
!            The routine calculates an approximation result to A
!            DEFINITE INTEGRAL I = INTEGRAL OF F OVER (a,b),
!            hopefully satisfying following claim for accuracy
!            dabs(I-result).LE.max(epsabs,epsrel*dabs(I)).
!
!        Parameters
!         on entry
!            F      - DOUBLE PRECISION
!                     function subprogram defining the integrand
!                     function f(x). the actual name for f needs to be
!                     declared E X t E R N A L in the driver program.
!
!            a      - DOUBLE PRECISION
!                     lower limit of integration
!
!            b      - DOUBLE PRECISION
!                     upper limit of integration
!
!            epsabs - double precision
!                     absolute accuracy requested
!
!            epsrel - double precision
!                     relative accuracy requested
!
!            limit  - integer
!                     gives an upperbound on the number of subintervals
!                     in the partition of (a,b)
!
!         On return
!            result - double precision
!                     approximation to the integral
!
!            abserr - double precision
!                     estimate of the modulus of the absolute error,
!                     which should equal or exceed dabs(I-result)
!
!            ier    - INTEGER
!                     ier = 0 NORMAL AND RELIABLE TERMINATION OF THE
!                             routine. It is assumed that the requested
!                             accuracy has been achieved.
!                     ier.GT.0 ABNORMAL TERMINATION OF THE ROUTINE
!                             the estimates for integral and error are
!                             less reliable. It is assumed that the
!                             requested accuracy has not been achieved.
!            Error messages
!                         = 1 MAXIMUM NUMBER OF SUBDIVISIONS ALLOWED
!                             has been achieved. One can allow more sub-
!                             divisions by increasing the value of limit
!                             (and taking the according dimension
!                             adjustments into account). However, if
!                             this yields no improvement it is advised
!                             to analyze the integrand in order to
!                             determine the integration difficulties. If
!                             the position of a local difficulty can be
!                             determined (E.G. singularity,
!                             discontinuity within the interval) one
!                             will probably gain from splitting up the
!                             interval at this point and calling the
!                             integrator on the subranges. If possible,
!                             an appropriate special-purpose integrator
!                             should be used, which is designed for
!                             handling the type of difficulty involved.
!                         = 2 THE OCCURRENCE OF ROUNDOFF ERROR IS DETEC-
!                             ted, which prevents the requested
!                             tolerance from being achieved.
!                             The error may be under-estimated.
!                         = 3 EXTREMELY BAD INTEGRAND BEHAVIOUR
!                             occurs at some points of the integration
!                             interval.
!                         = 4 THE ALGORITHM DOES NOT CONVERGE.
!                             Roundoff error is detected in the
!                             extrapolation table.
!                             It is presumed that the requested
!                             tolerance cannot be achieved, and that the
!                             returned result is the best which can be
!                             obtained.
!                         = 5 THE INTEGRAL IS PROBABLY DIVERGENT, OR
!                             slowly convergent. It must be noted that
!                             divergence can occur with any other value
!                             of ier.
!                         = 6 THE INPUT IS INVALID BECAUSE epsabs OR
!                             epsrel is negative. Result, abserr,
!                             last, rlist(1), iord(1), and elist(1)
!                             are set to zero. alist(1) and blist(1)
!                             are set to A and b respectively.
!
!            alist  - double precision
!                     vector of dimension at least limit, the first
!                      last  elements of which are the left end points
!                     of the subintervals in the partition of the
!                     given integration range (a,b)
!
!            blist  - double precision
!                     vector of dimension at least limit, the first
!                      last  elements of which are the right end points
!                     of the subintervals in the partition of the given
!                     integration range (a,b)
!
!            rlist  - double precision
!                     vector of dimension at least limit, the first
!                      last  elements of which are the integral
!                     approximations on the subintervals
!
!            elist  - double precision
!                     vector of dimension at least limit, the first
!                      last  elements of which are the moduli of the
!                     absolute error estimates on the subintervals
!
!            iord   - INTEGER
!                     vector of dimension at least limit, the first k
!                     elements of which are pointers to the
!                     error estimates over the subintervals,
!                     such that elist(iord(1)), ..., elist(iord(k))
!                     FORM A DECREASING SEQUENCE, WITH k = last
!                     IF last.LE.(limit/2+2), AND k = limit+1-last
!                     otherwise
!
!            last   - INTEGER
!                     number of subintervals actually produced in the
!                     subdivision process
!
!            valp   - DOUBLE PRECISION
!            valn     ARRAYS OF DIMENSION AT LEAST (21,limit) USED TO
!                     save the functional values
!
!            lp     - INTEGER
!            ln       VECTORS OF DIMENSION AT LEAST LIMIT, USED TO
!                     store the actual number of functional values
!                     saved in the corresponding column
!                     OF valp,valn
!
!***ROUTINES CALLED  F,dpmpar,dqelg,dqxlqm,dqpsrt,dqxrrd,dqxcpy
!
double precision :: a, abseps
double precision, intent(out) :: abserr
double precision, intent(inout) :: alist
double precision :: area, area1, area12, area2, a1, a2, b
double precision, intent(inout) :: blist
double precision :: b1, b2, correc, defabs, defab1, defab2, dres
double precision, intent(inout) :: elist
double precision :: epmach
double precision, intent(in) :: epsabs, epsrel
double precision :: erlarg, erlast, errbnd, errmax, error1, &
&error2, erro12, errsum, ertest, f, oflow, rerr, resabs, reseps
double precision, intent(out) :: result
double precision :: res3la(3)
double precision, intent(inout) :: rlist
double precision :: rlist2(52), small, t, uflow
double precision, intent(inout) :: valp, valn
double precision :: vp1(21), vp2(21), vn1(21), vn2(21), dpmpar
integer :: id
integer, intent(out) :: ier
integer :: ierro
integer, intent(inout) :: iord
integer :: iroff1, iroff2, iroff3, jupbnd, k, ksgn, ktmin
integer, intent(out) :: last
integer, intent(in) :: limit
integer :: maxerr, nres, nrmax, numrl2
integer, intent(inout) :: lp(limit), ln(limit)
integer :: lp1, lp2, ln1, ln2
logical :: extrap, noext
!
dimension alist(limit), blist(limit), elist(limit), iord(limit), &
&rlist(limit), valp(21,limit), valn(21,limit)
!
external f
!
!            Machine dependent constants
!            ---------------------------
!
!          epmach is the largest relative spacing.
!          uflow is the smallest positive magnitude.
!          OFLOW is the largest positive magnitude.
!
epmach = dpmpar(1)
uflow = dpmpar(2)
oflow = dpmpar(3)
!
!            Test on validity of parameters
!            ------------------------------
last = 0
result = 0.d0
abserr = 0.d0
alist(1) = a
blist(1) = b
rlist(1) = 0.d0
elist(1) = 0.d0
ier = 6
if (epsabs .lt. 0.d0 .or. epsrel.lt. 0.d0) go to 999
ier = 0
rerr = dmax1(epsrel, 50.d0*epmach)
!
!           First approximation to the integral
!           -----------------------------------
!
ierro = 0
lp(1) = 1
ln(1) = 1
valp(1,1) = f((a + b)*0.5d0)
valn(1,1) = valp(1,1)
call dqxlqm (f,a,b,result,abserr,defabs,resabs, &
&valp(1,1),valn(1,1),lp(1),ln(1),2, &
&epmach,uflow,oflow)
!
!           Test on accuracy.
!
dres = dabs(result)
errbnd = dmax1(epsabs,rerr*dres)
last = 1
rlist(1) = result
elist(1) = abserr
iord(1) = 1
if (abserr .le. 100.d0*epmach*defabs .and. abserr .gt. &
&errbnd) ier = 2
if (limit .eq. 1) ier = 1
if (ier .ne. 0 .or. (abserr.le.errbnd.and.abserr.ne.resabs) .or. &
&abserr .eq. 0.d0) go to 999
!
!           Initialization
!           --------------
!
rlist2(1) = result
errmax = abserr
maxerr = 1
area = result
errsum = abserr
abserr = oflow
nrmax = 1
nres = 0
numrl2 = 2
ktmin = 0
extrap = .false.
noext = .false.
iroff1 = 0
iroff2 = 0
iroff3 = 0
ksgn = -1
if (dres .ge. (1.d0 - 50.d0*epmach)*defabs) ksgn = 1
t = 1.d0 + 100.d0*epmach
!
!           Main do-loop
!           ------------
!
do 90 last = 2,limit
!
!           Bisect the subinterval with the nrmax-TH largest error
!           estimate.
!
  a1 = alist(maxerr)
  b1 = 0.5d0*(alist(maxerr) + blist(maxerr))
  a2 = b1
  b2 = blist(maxerr)
  erlast = errmax
  call dqxrrd(f,valn(1,maxerr),ln(maxerr),b1,a1,vn1,vp1,ln1,lp1)
  call dqxlqm(f,a1,b1,area1,error1,resabs,defab1,vp1,vn1,lp1,ln1, &
&2,epmach,uflow,oflow)
  call dqxrrd(f,valp(1,maxerr),lp(maxerr),a2,b2,vp2,vn2,lp2,ln2)
  call dqxlqm(f,a2,b2,area2,error2,resabs,defab2,vp2,vn2,lp2,ln2, &
&2,epmach,uflow,oflow)
!
!           Improve previous approximations to integral
!           and error and test for accuracy.
!
  area12 = area1 + area2
  erro12 = error1 + error2
  errsum = errsum + erro12 - errmax
  area = area + area12 - rlist(maxerr)
  if (defab1 .eq. error1 .or. defab2 .eq. error2) go to 15
  if (dabs(rlist(maxerr) - area12) .gt. 0.1d-04*dabs(area12) &
&.or. erro12 .lt. 0.99d0*errmax) go to 10
  if (extrap) iroff2 = iroff2 + 1
  if (.not.extrap) iroff1 = iroff1 + 1
10 if (last.gt.10 .and. erro12.gt.errmax) iroff3 = iroff3 + 1
15 rlist(maxerr) = area1
  rlist(last) = area2
  errbnd = dmax1(epsabs,rerr*dabs(area))
!
!           Test for roundoff error and eventually set error flag.
!
  if (iroff1 + iroff2 .ge. 10 .or. iroff3 .ge. 20) ier = 2
  if (iroff2 .ge. 5) ierro = 3
!
!           Set error flag in the case that the number of subintervals
!           equals limit.
!
  if (last .eq. limit) ier = 1
!
!           Set error flag in the case of bad integrand behaviour
!           at a point of the integration range.
!
  if (dmax1(dabs(a1),dabs(b2)) .le. &
&t*(dabs(a2) + 1.d+03*uflow)) ier = 4
!
!           Append the newly-created intervals to the list.
!
  if (error2 .gt. error1) go to 20
  alist(last) = a2
  blist(maxerr) = b1
  blist(last) = b2
  elist(maxerr) = error1
  elist(last) = error2
  call dqxcpy(valp(1,maxerr),vp1,lp1)
  lp(maxerr) = lp1
  call dqxcpy(valn(1,maxerr),vn1,ln1)
  ln(maxerr) = ln1
  call dqxcpy(valp(1,last),vp2,lp2)
  lp(last) = lp2
  call dqxcpy(valn(1,last),vn2,ln2)
  ln(last) = ln2
  go to 30
!
20 alist(maxerr) = a2
  alist(last) = a1
  blist(last) = b1
  rlist(maxerr) = area2
  rlist(last) = area1
  elist(maxerr) = error2
  elist(last) = error1
  call dqxcpy(valp(1,maxerr),vp2,lp2)
  lp(maxerr) = lp2
  call dqxcpy(valn(1,maxerr),vn2,ln2)
  ln(maxerr) = ln2
  call dqxcpy(valp(1,last),vp1,lp1)
  lp(last) = lp1
  call dqxcpy(valn(1,last),vn1,ln1)
  ln(last) = ln1
!
!           CALL SUBROUTINE dqpsrt TO MAINTAIN THE DESCENDING ORDERING
!           in the list of error estimates and select the subinterval
!           with nrmax-TH largest error estimate (to be bisected next).
!
30 call dqpsrt(limit,last,maxerr,errmax,elist,iord,nrmax)
! ***JUMP OUT OF DO-LOOP
  if(errsum .le. errbnd) go to 115
! ***JUMP OUT OF DO-LOOP
  if (ier .ne. 0) go to 100
  if (last .eq. 2) go to 80
  if (noext) go to 90
  erlarg = erlarg - erlast
  if (dabs(b1 - a1) .gt. small) erlarg = erlarg + erro12
  if (extrap) go to 40
!
!           Test whether the interval to be bisected next is the
!           smallest interval.
!
  if (dabs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
  extrap = .true.
  nrmax = 2
!
!           The bound 0.3*ERTEST has been introduced to perform A
!           more cautious extrapolation than in the original dqagse
!           routine
!
40 if (ierro .eq. 3 .or. erlarg .le. 0.3d0*ertest) go to 60
!
!           The smallest interval has the largest error.
!           Before bisecting decrease the sum of the errors over the
!           larger intervals (erlarg) and perform extrapolation.
!
  id = nrmax
  jupbnd = last
  if (last .gt. (2 + limit/2)) jupbnd = limit + 3 - last
  do 50 k = id,jupbnd
    maxerr = iord(nrmax)
    errmax = elist(maxerr)
! ***JUMP OUT OF DO-LOOP
    if(dabs(blist(maxerr) - alist(maxerr)) .gt. small) go to 90
    nrmax = nrmax + 1
50 continue
!
!           Perform extrapolation.
!
60 numrl2 = numrl2 + 1
  rlist2(numrl2) = area
  call dqelg (numrl2,rlist2,reseps,abseps,res3la,nres, &
&epmach,oflow)
  ktmin = ktmin + 1
  if (ktmin .gt. 5 .and. abserr .lt. 0.1d-02*errsum) ier = 5
  if (abseps .ge. abserr) go to 70
  ktmin = 0
  abserr = abseps
  result = reseps
  correc = erlarg
  ertest = dmax1(epsabs,rerr*dabs(reseps))
! ***JUMP OUT OF DO-LOOP
  if (abserr .le. ertest) go to 100
!
!           Prepare bisection of the smallest interval.
!
70 if (numrl2 .eq. 1) noext = .true.
  if (ier .eq. 5) go to 100
  maxerr = iord(1)
  errmax = elist(maxerr)
  nrmax = 1
  extrap = .false.
  small = small*0.5d0
  erlarg = errsum
  go to 90
80 small = dabs(b - a)*0.375d0
  erlarg = errsum
  ertest = errbnd
  rlist2(2) = area
90 continue
!
!           Set final result and error estimate.
!           ------------------------------------
!
100 if (abserr .eq. oflow) go to 115
if (ier + ierro .eq. 0) go to 110
if (ierro .eq. 3) abserr = abserr + correc
if (ier .eq. 0) ier = 3
if (result .ne. 0.d0 .and. area .ne. 0.d0) go to 105
if (abserr .gt. errsum) go to 115
if (area .eq. 0.d0) go to 130
go to 110
105 if (abserr/dabs(result) .gt. errsum/dabs(area)) go to 115
!
!           Test on divergence.
!
110 if(ksgn.eq.(-1).and.dmax1(dabs(result),dabs(area)).le. &
&defabs*0.1d-01) go to 130
if(0.1d-01.gt.(result/area).or.(result/area).gt.0.1d+03 &
&.or.errsum.gt.dabs(area)) ier = 6
go to 130
!
!           Compute global integral sum.
!
115 result = 0.d0
do k = 1,last
   result = result + rlist(k)
end do
abserr = errsum
130 if (ier .gt. 2) ier = ier - 1
999 return
end subroutine dqxgse

subroutine dqxcpy (a, b, l)
implicit none
integer :: i
!
!  TO COPY THE DOUBLE PRECISION VECTOR b OF LENGTH l   i N T O
!          the double precision vector a of length l
!
integer, intent(in) :: l
double precision, intent(inout) :: a(l)
double precision, intent(in) :: b(l)
!
do 10 i = 1,l
10 a(i) = b(i)
return
end subroutine dqxcpy

subroutine dqxlqm (f,a,b,result,abserr,resabs,resasc,vr,vs,lr,ls, &
&key,epmach,uflow,oflow)
implicit none
!
!            TO COMPUTE I = INTEGRAL OF f OVER (a,b), WITH ERROR
!                           estimate
!                       J = INTEGRAL OF dabs(f) OVER (a,b)
!
!           Parameters
!            on entry
!              f      - DOUBLE PRECISION
!                       function subprogram defining the integrand
!                       function f(x). the actual name for f needs to be
!                       declared E X t E R N A L in the driver program.
!
!              a      - DOUBLE PRECISION
!                       lower limit of integration
!
!              b      - DOUBLE PRECISION
!                       upper limit of integration
!
!              vr     - DOUBLE PRECISION
!                       vector of length lr containing the
!                       saved  functional values of positive abscissas
!
!              vs     - DOUBLE PRECISION
!                       vector of length ls containing the
!                       saved  functional values of negative abscissas
!
!              lr     - INTEGER
!              ls       NUMBER OF ELEMENTS IN
!                       vr,vs respectively
!
!            key    - INTEGER
!                     key for choice of local integration rule
!                     rms formulas are used with
!                      13 - 19               POINTS IF key.LT.1,
!                      13 - 19 - (27)        POINTS IF key = 1,
!                      13 - 19 - (27) - (41) POINTS IF key = 2,
!                           19 -  27  - (41) POINTS IF key = 3,
!                                 27  -  41  POINTS IF key.GT.3.
!
!                         (Rules) used if the function APPEARS
!                         enough regular
!
!              epmach - double precision
!                       the relative precision of the floating
!                       arithmetic being used.
!
!              uflow  - double precision
!                       the smallest positive magnitude.
!
!              oflow  - double precision
!                       the largest positive magnitude.
!
!            On return
!              result - double precision
!                       approximation to the integral I
!
!              abserr - double precision
!                       estimate of the modulus of the absolute error,
!                       which should not exceed dabs(I-result)
!
!              resabs - double precision
!                       approximation to the integral J
!
!              resasc - double precision
!                       approximation to the integral of dabs(f-I/(b-a))
!                       OVER (a,b)
!
!              vr     - DOUBLE PRECISION
!                       vector of length lr containing the
!                       saved  functional values of positive abscissas
!
!              vs     - DOUBLE PRECISION
!                       vector of length ls containing the
!                       saved  functional values of negative abscissas
!
!              lr     - INTEGER
!              ls       NUMBER OF ELEMENTS IN
!                       vr,vs respectively
!
!***ROUTINES CALLED  dqxrul
!
double precision :: f
double precision, intent(in) :: a, b
double precision, intent(inout) :: result, abserr, resabs, resasc
double precision :: t
double precision, intent(in) :: epmach, oflow, uflow
double precision :: resg, resk, errold
double precision, intent(inout) :: vr(21), vs(21)
integer :: k, k0, k1, k2
integer, intent(in) :: key
integer :: key1
integer, intent(inout) :: lr, ls
external f
!
key1 = max0(key ,  0)
key1 = min0(key1,  4)
k0   = max0(key1-2,0)
k1   = k0 + 1
k2   = min0(key1+1,3)
!
call dqxrul (f,a,b,resg,resabs,resasc,k0,k1,vr,vs,lr,ls)
errold = oflow
t = 10.d0*epmach
do 10 k = k1,k2
  call dqxrul (f,a,b,resk,resabs,resasc,k,k1,vr,vs,lr,ls)
  result = resk
  abserr = dabs(resk - resg)
  if (resasc .ne. 0.d0 .and. abserr .ne. 0.d0) &
&abserr = resasc*dmin1(1.d0,(200.d0*abserr/resasc)**1.5d0)
  if (resabs .gt. uflow/t) abserr = dmax1(t*resabs,abserr)
  resg = resk
  if (abserr .gt. errold*0.16d0) go to 3000
  if (abserr .lt. 1000.d0*epmach*resabs) go to 3000
  errold = abserr
10 continue
3000 continue
return
end subroutine dqxlqm

subroutine dqxrul (f,xl,xu,y,ya,ym,ke,k1,fv1,fv2,l1,l2)
implicit none
integer :: i, is, k, ks
!
!            TO COMPUTE i = INTEGRAL OF f OVER (A,B), WITH ERROR
!                           estimate
!            and conditionally compute
!                       j = INTEGRAL OF dabs(f) OVER (A,B)
!                       by using an  rms rule
!           parameters
!            on entry
!              f      - DOUBLE PRECISION
!                       function subprogram defining the integrand
!                       function f(x). the actual name for f needs to be
!                       declared E X T E R N A L in the driver program.
!
!              xl     - DOUBLE PRECISION
!                       lower limit of integration
!
!              xu     - DOUBLE PRECISION
!                       upper limit of integration
!
!              ke     - INTEGER
!                     key for choice of local integration rule
!                     an rms rule is used with
!                         13      POINTS IF ke  = 2,
!                         19      POINTS IF ke  = 3,
!                         27      POINTS IF ke  = 4,
!                         42      POINTS IF ke  = 5
!
!              k1     INTEGER
!                     value of key for which the additional estimates
!                     ya, ym are to be computed
!
!              fv1    - DOUBLE PRECISION
!                       vector containing l1
!                       saved  functional values of positive abscissas
!
!              fv2    - DOUBLE PRECISION
!                       vector containing l2
!                       saved  functional values of negative abscissas
!
!              l1     - INTEGER
!              l2       NUMBER OF ELEMENTS IN fv1,fv2  RESPECTIVELY
!
!            On return
!              y      - DOUBLE PRECISION
!                       approximation to the integral i
!                       result is computed by applying the
!                       requested rms rule
!
!              ya     - DOUBLE PRECISION
!                       IF KEY = k1  APPROXIMATION TO THE INTEGRAL j
!                       ELSE UNCHANGED
!
!              ym     - DOUBLE PRECISION
!                       IF KEY = k1  APPROXIMATION TO THE INTEGRAL OF
!                                      dabs(f-i/(xu-xl)   OVER (xl,xu)
!                       ELSE UNCHANGED
!
!              fv1    - DOUBLE PRECISION
!                       vector containing l1
!                       saved  functional values of positive abscissas
!
!              fv2    - DOUBLE PRECISION
!                       vector containing l2
!                       saved  functional values of negative abscissas
!
!              l1     - INTEGER
!              l2       NUMBER OF ELEMENTS IN fv1,fv2  RESPECTIVELY
!
!------------------------
double precision :: f
double precision, intent(in) :: xl, xu
double precision :: ldl
double precision, intent(out) :: y
double precision, intent(inout) :: ya, ym
double precision :: y2, xx(41), ww(52)
double precision, intent(inout) :: fv1(21), fv2(21)
double precision :: aa, bb, c
integer :: istart(4), len(4), j
integer, intent(in) :: ke, k1
integer, intent(inout) :: l1, l2
external f
!------------------------
data istart(1)/0/, istart(2)/7/, istart(3)/17/, istart(4)/31/
data len(1)/7/, len(2)/10/, len(3)/14/, len(4)/21/
!------------------------
data xx( 1)/0.d0                     /
data xx( 2)/.25000000000000000000d+00/
data xx( 3)/.50000000000000000000d+00/
data xx( 4)/.75000000000000000000d+00/
data xx( 5)/.87500000000000000000d+00/
data xx( 6)/.93750000000000000000d+00/
data xx( 7)/.10000000000000000000d+01/
data xx( 8)/.37500000000000000000d+00/
data xx( 9)/.62500000000000000000d+00/
data xx(10)/.96875000000000000000d+00/
data xx(11)/.12500000000000000000d+00/
data xx(12)/.68750000000000000000d+00/
data xx(13)/.81250000000000000000d+00/
