subroutine urng2 (ix, x, y, n, ierr)
implicit none
integer, intent(inout) :: ierr, ix
integer, intent(in) :: n
integer :: k, l, leftlo
real :: s, t
!-----------------------------------------------------------------------
!
!         Generation of uniform random points (x(I),y(I))
!                     FOR I = 1,...,n WHERE
!
!                      0 .LT. x(I) .LT. 1
!                      0 .LT. y(I) .LT. 1
!
!     IT IS ASSUMED THAT 0 .LT. ix .LT. p
!-----------------------------------------------------------------------
!     Written by
!        linus schrage
!        University of Chicago
!     adapted by A.H. Morris (NSWC)
!-------------------
real, intent(inout) :: x(n), y(n)
integer :: a, b15, b16, fhi, p, xalo, xhi
!-------------------
!     data a/7**5/,  b15/2**15/, b16/2**16/, p/2**31 - 1/
!-------------------
data a/16807/, b15/32768/, b16/65536/, p/2147483647/
data s/.465661e-09/
!-------------------
if (n .le. 0) go to 100
if (ix .le. 0 .or. ix .ge. p) go to 110
ierr = 0
!
!         See the comments in the subroutine urng for the
!                statements in the following loop
!
do l = 1,n
   xhi = ix/b16
   xalo = (ix - xhi*b16)*a
   leftlo = xalo/b16
   fhi = xhi*a + leftlo
   k = fhi/b15
   ix = (((xalo - leftlo*b16) - p) + (fhi - k*b15)*b16) + k
   if (ix .lt. 0) ix = ix + p
   t = ix
   x(l) = s*t
!
   xhi = ix/b16
   xalo = (ix - xhi*b16)*a
   leftlo = xalo/b16
   fhi = xhi*a + leftlo
   k = fhi/b15
   ix = (((xalo - leftlo*b16) - p) + (fhi - k*b15)*b16) + k
   if (ix .lt. 0) ix = ix + p
   t = ix
   y(l) = s*t
end do
return
!
!                         Error return
!
100 ierr = 1
return
110 ierr = 2
return
end subroutine urng2

