   if (ind .eq. -3 .or. ind .eq. -7) x1 = 0.d0
!
   call durng0 (ix, u, v)
   call dginv (b, x2, u, v, ind)
   if (ind .eq. -3 .or. ind .eq. -7) x2 = 0.d0
!
!        It is required that A and b not be less
!        than 0.25 so that x1 + x2 is nonzero.
!
   x(i) = x1/(x1 + x2)
